window.POLICIES = [{"id":"small-business-income-tax","title":"关于进一步支持小微企业和个体工商户发展有关税费政策的公告","level":"national","region":"全国","issuer":"财政部 税务总局","documentNo":"财政部 税务总局公告2023年第12号","publishedAt":"2023-08-02","effectiveAt":"2023-01-01","expiresAt":"2027-12-31","status":"active","tags":["税收优惠"],"audience":["小型微利企业","个体工商户"],"hot":98,"summary":"小型微利企业年应纳税所得额不超过300万元的部分，实际税负降到5%；个体工商户年应纳税所得额不超过200万元的部分，减半征收个人所得税。执行到2027年底。","sections":[{"no":"一","title":"小型微利企业所得税","text":"对小型微利企业年应纳税所得额不超过300万元的部分，减按25%计入应纳税所得额，按20%的税率缴纳企业所得税。"},{"no":"二","title":"个体工商户个人所得税","text":"对个体工商户年应纳税所得额不超过200万元的部分，减半征收个人所得税。个体工商户在享受现行其他个人所得税优惠政策的基础上，可叠加享受本条优惠政策。"},{"no":"三","title":"执行期限","text":"上述政策执行至2027年12月31日。"}],"interpretations":[{"sectionNo":"一","headline":"应纳税所得额300万元以内，实际税负5%","who":"小型微利企业：年应纳税所得额不超过300万元的部分。","materials":[],"window":"执行至2027年12月31日。","where":"按企业所得税申报渠道享受。","tip":"是「减按25%计入应纳税所得额，再按20%税率缴纳」，算下来实际税负5%；只对不超过300万元的部分适用。"},{"sectionNo":"二","headline":"个体户200万元以内所得，个税减半且可叠加","who":"个体工商户，年应纳税所得额不超过200万元的部分。","materials":[],"window":"执行至2027年12月31日。","where":"按经营所得申报渠道享受。","tip":"可以和现行其他个人所得税优惠政策叠加享受。"}],"sourceUrl":"https://www.gov.cn/zhengce/zhengceku/202308/content_6896379.htm","sourceNote":"请在税务总局官网「政策文件」栏按文号检索原文核对；2026-11-08 链接替换为官方原文页（标题与文号已核对）","verified":true,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":false},{"id":"vat-small-scale","title":"关于增值税小规模纳税人减免增值税政策的公告","level":"national","region":"全国","issuer":"财政部 税务总局","documentNo":"财政部 税务总局公告2023年第19号","publishedAt":"2023-08-02","effectiveAt":"2023-01-01","expiresAt":"2027-12-31","status":"active","tags":["税收优惠"],"audience":["小规模纳税人","个体工商户","小微企业"],"hot":96,"summary":"小规模纳税人月销售额10万元（季度30万元）以下免征增值税；适用3%征收率的收入减按1%征收。执行到2027年底。","sections":[{"no":"一","title":"起征点免税","text":"对月销售额10万元以下（含本数）的增值税小规模纳税人，免征增值税。"},{"no":"二","title":"征收率下调","text":"增值税小规模纳税人适用3%征收率的应税销售收入，减按1%征收率征收增值税；适用3%预征率的预缴增值税项目，减按1%预征率预缴增值税。"},{"no":"三","title":"执行期限","text":"上述政策执行至2027年12月31日。"}],"interpretations":[{"sectionNo":"一","headline":"月销售额10万元以下，免征增值税","who":"月销售额10万元以下（含本数）的增值税小规模纳税人。","materials":[],"window":"执行至2027年12月31日。","where":"按增值税申报渠道享受。","tip":"口径是「月销售额10万元以下（含本数）」，超了就不再适用免征。"},{"sectionNo":"二","headline":"3%征收率减按1%征收","who":"适用3%征收率的增值税小规模纳税人；适用3%预征率的预缴增值税项目。","materials":[],"window":"执行至2027年12月31日。","where":"按增值税申报渠道享受。","tip":"预缴项目同样减按1%预征率预缴，不要按3%预缴后再申请退。"}],"sourceUrl":"https://www.gov.cn/zhengce/zhengceku/202308/content_6896287.htm","sourceNote":"请在税务总局官网按文号检索原文核对；2026-11-08 链接替换为官方原文页（标题与文号已核对）","verified":true,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":false},{"id":"rd-super-deduction","title":"关于进一步完善研发费用税前加计扣除政策的公告","level":"national","region":"全国","issuer":"财政部 税务总局","documentNo":"财政部 税务总局公告2023年第7号","publishedAt":"2023-03-26","effectiveAt":"2023-01-01","status":"active","tags":["税收优惠","研发创新"],"audience":["科技型企业","制造业企业","有研发投入的企业"],"hot":88,"summary":"企业实际发生的研发费用，未形成无形资产的按100%加计扣除；形成无形资产的按成本的200%在税前摊销。所有符合条件行业均可享受。","sections":[{"no":"一","title":"第一条","text":"企业开展研发活动中实际发生的研发费用，未形成无形资产计入当期损益的，在按规定据实扣除的基础上，自2023年1月1日起，再按照实际发生额的100%在税前加计扣除；形成无形资产的，自2023年1月1日起，按照无形资产成本的200%在税前摊销。"},{"no":"二","title":"第二条","text":"企业享受研发费用加计扣除政策的其他政策口径和管理要求，按照《财政部国家税务总局科技部关于完善研究开发费用税前加计扣除政策的通知》（财税〔2015〕119号）、《财政部税务总局科技部关于企业委托境外研究开发费用税前加计扣除有关政策问题的通知》（财税〔2018〕64号）等文件相关规定执行。"},{"no":"三","title":"第三条","text":"本公告自2023年1月1日起执行，《财政部税务总局关于进一步完善研发费用税前加计扣除政策的公告》（财政部税务总局公告2021年第13号）、《财政部税务总局科技部关于进一步提高科技型中小企业研发费用税前加计扣除比例的公告》（财政部税务总局科技部公告2022年第16号）、《财政部税务总局科技部关于加大支持科技创新税前扣除力度的公告》（财政部税务总局科技部公告2022年第28号）同时废止。\n特此公告。\n财政部税务总局2023年3月26日\n\n政策解读"}],"interpretations":[{"sectionNo":"一","headline":"研发费用据实扣除后，再按100%加计扣除","who":"开展研发活动、实际发生研发费用的企业；费用化与资本化两种情形分别处理。","materials":[],"window":"自2023年1月1日起执行。","where":"按现行企业所得税申报渠道享受（具体口径按财税〔2015〕119号等文件执行）。","tip":"未形成无形资产的按实际发生额100%加计扣除；形成无形资产的按成本200%在税前摊销，两者不能混用。"},{"sectionNo":"三","headline":"2021年第13号等三份旧公告同时废止","who":"此前按旧公告享受研发费用加计扣除的企业。","materials":[],"window":"自2023年1月1日起执行，旧公告同时废止。","where":"主管税务机关。","tip":"2023年起按本公告口径执行，别再引用2021年第13号、2022年第16号和第28号。"},{"sectionNo":"二","headline":"研发费用加计扣除其他口径按财税〔2015〕119号等文件执行","who":"享受研发费用加计扣除政策的企业；其他政策口径和管理要求（含委托境外研究开发）分别按财税〔2015〕119号、财税〔2018〕64号文件执行。","materials":[],"window":"本条未另定执行期限，随研发费用加计扣除政策及上述文件执行。","where":"财政部、国家税务总局、科技部（财税〔2015〕119号）及财税〔2018〕64号文件规定的口径。","tip":"本条不另设加计扣除比例，只做口径衔接；其他政策口径和管理要求以财税〔2015〕119号、财税〔2018〕64号为准。"}],"sourceUrl":"https://zc.gjzwfw.gov.cn/art/2023/3/29/art_14_63825.html","sourceNote":"请在税务总局官网按文号检索原文核对；2026-11-08 链接替换为官方原文页（标题与文号已核对）；2026-11-09 条文按官方原文重切（3 条，自查召回 100%）","verified":true,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":false},{"id":"startup-guarantee-loan","title":"关于进一步做好创业担保贷款财政贴息工作的通知","level":"national","region":"全国","issuer":"财政部 人力资源社会保障部 中国人民银行","documentNo":"财金〔2018〕22号","publishedAt":"2018-03-27","effectiveAt":"2018-03-27","status":"active","tags":["融资支持","贷款贴息"],"audience":["创业者","小微企业","返乡创业人员","高校毕业生"],"hot":84,"summary":"个人创业担保贷款由财政贴息；小微企业当年新招用符合条件人员达到在职职工25%（超100人企业15%）即可申请，同一借款人贴息累计不超过3次，非贫困地区个人贷款按2年全额贴息。","sections":[{"no":"一","title":"加大政策支持力度","text":"（一）扩大贷款对象范围。除原规定的创业担保贷款对象（城镇登记失业人员、就业困难人员、复员转业退役军人、刑满释放人员、高校毕业生、化解过剩产能企业职工和失业人员、返乡创业农民工、网络商户、建档立卡贫困人口）外，将农村自主创业农民纳入支持范围。将小微企业贷款对象范围调整为：当年新招用符合创业担保贷款申请条件的人员数量达到企业现有在职职工人数25%（超过100人的企业达到15%）、并与其签订1年以上劳动合同的小微企业。\n\n（二）降低贷款申请条件。个人创业担保贷款申请人贷款记录的要求调整为:除助学贷款、扶贫贷款、住房贷款、购车贷款、5万元以下小额消费贷款（含信用卡消费）以外，申请人提交创业担保贷款申请时，本人及其配偶应没有其他贷款。\n\n（三）放宽担保和贴息要求。对已享受财政部门贴息支持的小微企业创业担保贷款，可通过创业担保贷款担保基金提供担保形式支持。对还款积极、带动就业能力强、创业项目好的借款个人和小微企业，可继续提供创业担保贷款贴息，但累计次数不得超过3次。"},{"no":"二","title":"优化申请办理程序","text":"（四）健全服务机制。各地、各部门要简化流程、提高效率，为符合条件的创业者办理创业担保贷款提供便利化服务，探索将申请受理、材料审核、征信查询等贷款手续和担保手续一次性办结。有条件的地方，应积极探索电子化审批流转模式，优化贷款申请、审核、发放各环节，保障服务的快捷优质。\n\n（五）完善担保机制。鼓励各地聚焦第一还款来源，探索通过信用方式发放创业贷款，在不断提高风险评估能力的基础上，逐步取消反担保。对获得市（设区的市）级以上荣誉称号的创业人员、创业项目、创业企业，经金融机构评估认定的信用小微企业、商户、农户，经营稳定守信的二次创业者等特定群体原则上取消反担保。"},{"no":"三","title":"因地制宜推进工作","text":"（六）落实地方自主管理权限。符合中央规定标准的贷款产生的贴息资金支出，由中央和地方财政按规定比例共担，中央财政负担部分按照普惠金融发展专项资金管理办法有关规定在年度预算规模内核定。比照实施西部大开发政策的地区，执行西部地区分担比例。除贫困地区外的其他地区，对个人贷款按2年（第1年、第2年）全额贴息执行。各地应把握节奏，分清轻重缓急，财政贴息资金要按规定及时足额拨付到位，对超出中央规定的贷款贴息部分，由地方财政自行承担，具体贴息标准和条件由地方结合实际予以确定。对地方财政部门自行安排贴息的创业担保贷款，要与中央财政贴息支持的创业担保贷款分离管理，分账核算。\n\n（七）加强基础管理。各地应优化管理方式，提高管理效率，加强信息数据收集和统计工作，掌握贷款发放和财政贴息资金使用动态，防止重复申报、不当使用，防范道德风险、保障财政资金安全，及时将创业担保贷款信息纳入金融信用信息基础数据库。财政部将与人民银行建立合作机制，开展创业担保贷款贴息资金使用情况总结分析和后评估等工作，推动提升政策精准度，优化政策执行效果。"},{"no":"四","title":"加强监督管理","text":"（八）完善配套制度。各地、各部门要制定所辖地区创业担保贷款贴息资金管理办法、业务操作规程、工作人员管理办法等配套制度。鼓励各地结合实际，积极探索优化创业担保贷款风险分担机制和呆账核销机制，巩固提升创业担保贷款政策实施效果。各经办银行要按照人民银行等部门政策规定，严格贷前审核，强化贷中服务，加强贷后管理，不断提高贷款服务质量和效率。\n\n（九）强化部门协作。各地要进一步明确各部门职责，各司其职、各担其责。人力资源和社会保障部门主要负责审核贷款贴息对象申报资格；人民银行主要负责督促经办银行规范创业担保贷款发放；财政部门主要负责按规定拨付贴息及奖补资金。各级财政、人民银行、人力资源和社会保障部门及其工作人员在专项资金办理、审批、分配工作中，若存在以虚报、冒领等方式骗取或滞留、截留、挤占、挪用专项资金的情况，以及其他滥用职权、玩忽职守、徇私舞弊等违法违纪行为的，按照《预算法》《公务员法》《行政监察法》《财政违法行为处罚处分条例》等法律法规追究相应责任；涉嫌犯罪的，移送司法机关处理。\n\n（十）加强绩效评价。地方财政部门要设定创业担保贷款财政贴息资金绩效目标和相应绩效指标，对资金实际产出和效益进行评估，加强对绩效目标的审核和下达，强化绩效目标执行监控，确保目标如期落实。可委托第三方开展绩效评价，不断优化资金分配和使用。\n\n（十一）组织专项检查。财政部驻各地专员办要加强资金使用监督，督促有关部门和金融机构不断提升管理和服务水平。除对省级财政部门报送的材料进行合规性、完整性、真实性审核外，应对创业担保贷款财政贴息政策执行情况组织专项检查，原则上每两年至少组织一次，及时发现问题，分析提出相关建议。对检查过程中发现的重大问题，要及时向财政部报告。\n\n（十二）推进信息公开。各地要强化信息公开意识，不断扩宽创业担保贷款信息公开范围，细化公开事项、内容、时限、方式、责任主体，增加公开手段和渠道，提升公众信息获取的便利度。在杜绝个人敏感信息泄露的前提下，对贷款拟发放对象要提前进行公示，对创业担保贷款管理规定、贷款审核发放、资金拨付情况等信息做到及时、全面、准确发布。"},{"no":"五","title":"做好组织实施","text":"（十三）切实真抓实干。各地、各部门要高度重视，将落实好创业担保贷款政策作为工作重要目标和重点内容。要结合实际制定当地工作计划，抓紧制定出台配套政策措施，明确年度目标任务和具体工作措施。扎实推进相关工作，确保取得实效。\n\n（十四）健全工作机制。各部门要加强配合、协同推进，既要防止管理错位，又要防止管理真空。各部门要定期不定期召开联席会议，加强沟通与信息共享，及时协商解决政策实施过程中存在的问题，构建平稳有序、高效顺畅的工作机制。\n\n（十五）强化服务意识。各地、各部门要加强组织领导，不断深入推进简政放权、优化服务改革，健全服务体系，整合服务资源，提升信息化水平，推进基层便民服务，提升人民群众的满意度。\n\n（十六）加大宣传力度。各地要着力探索积累经验，每年要总结并报告落实情况，综合运用各种媒介、方式，加强政策解释宣传。对优秀创业企业和个人，要树立典型，形成示范案例，以点带面、梯次推进。\n\n本通知自发布之日起施行，此前发布的有关创业担保贷款政策与本通知不一致的，以本通知为准。本通知印发前已生效的创业担保贷款合同，仍按原合同约定执行。\n\n财政部\n\n人力资源社会保障部\n\n中国人民银行\n\n2018年3月27日"}],"interpretations":[{"sectionNo":"一","headline":"小微招用符合条件人员达在职职工25%，才够创业担保贷款门槛","who":"个人：城镇登记失业人员、就业困难人员、复员转业退役军人、刑满释放人员、高校毕业生、化解过剩产能企业职工和失业人员、返乡创业农民工、网络商户、建档立卡贫困人口，以及新纳入的农村自主创业农民。小微企业：当年新招用符合条件人员达到在职职工25%（超100人的企业达15%），并与其签订1年以上劳动合同。","materials":[],"window":"按经办银行与当地人社部门的贷款流程办理。","where":"经办银行；资格审核由人力资源和社会保障部门负责。","tip":"个人申请时，本人及配偶除助学贷款、扶贫贷款、住房贷款、购车贷款、5万元以下小额消费贷款外应没有其他贷款；贴息累计不超过3次。"},{"sectionNo":"二","headline":"这几类人可逐步取消反担保","who":"获得市（设区的市）级以上荣誉称号的创业人员、创业项目、创业企业；经金融机构评估认定的信用小微企业、商户、农户；经营稳定守信的二次创业者等特定群体。","materials":[],"window":"按经办银行与当地人社部门流程办理。","where":"经办银行；各地可探索通过信用方式发放创业贷款。","tip":"取消反担保是「原则上」，具体由地方和经办银行把握；文件鼓励聚焦第一还款来源、逐步取消反担保。"},{"sectionNo":"三","headline":"个人贷款按2年全额贴息，中央地方按比例分担","who":"符合中央规定标准的创业担保贷款；比照实施西部大开发政策的地区执行西部地区分担比例。","materials":[],"window":"个人贷款按2年（第1年、第2年）全额贴息；超出中央规定的贴息部分由地方财政自行承担。","where":"财政部门按规定拨付贴息及奖补资金。","tip":"地方自行安排贴息的创业担保贷款，要与中央财政贴息支持的分账核算、分离管理。"}],"sourceUrl":"https://www.gov.cn/zhengce/zhengceku/2018-12/31/content_5439367.htm","sourceNote":"财政部官网按文号检索；地方实施口径请查当地人社局文件；2026-11-08 核对：现有链接指向部委首页，原文链接待补；2026-11-09 条文按官方原文重切（5 条，自查召回 100%）","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":false},{"id":"sample-one-time-startup-subsidy","title":"〔示例〕一次性创业补贴实施办法","level":"city","region":"示例地区","issuer":"示例市人力资源和社会保障局","documentNo":"示例人社〔2025〕1号","publishedAt":"2025-03-01","effectiveAt":"2025-03-01","expiresAt":"2026-12-31","status":"expiring","tags":["创业补贴","财政奖补"],"audience":["首次创业者","高校毕业生","返乡创业人员"],"hot":70,"summary":"这是用于演示地区级政策的示例数据：对首次创办小微企业或个体户、正常经营满一定期限的创业者，给予一次性创业补贴。真实标准请以当地文件为准。","sections":[{"no":"一","title":"补贴对象","text":"（示例条款）首次在本市创办小微企业或个体工商户，正常经营并依法缴纳社会保险费满6个月的创业者，可申请一次性创业补贴。"},{"no":"二","title":"补贴标准与申领","text":"（示例条款）补贴标准为每人一次性5000元至10000元，同一创业者只能享受一次；申请人应在经营满6个月后的12个月内提出申请。"}],"interpretations":[{"sectionNo":"一","headline":"首创办企业，经营满半年就能领","who":"本市户籍或在本市创业的首次创业者；创办主体需为小微企业或个体工商户，且本人依法缴纳社保满6个月。已享受过同类补贴的不能重复申请。","materials":["补贴申请表","营业执照副本","社保缴费记录","本人身份证与银行账户","经营场所证明"],"window":"经营满6个月后12个月内申请，逾期视为放弃。","where":"创业地街道（乡镇）便民服务中心或人社局线上申报入口。","tip":"示例数据，仅用于演示申请流程；各地金额与条件差异很大，务必核对本地当年文件。"},{"sectionNo":"二","headline":"5000到10000元，一生只能领一次","who":"符合对象条件且未重复享受的创业者。","materials":["同上一节材料","补贴发放确认单"],"window":"按季度集中审核发放。","where":"人社部门审核后拨付至本人账户。","tip":"部分地区要求「正常经营」需有实际流水，空壳注册通常无法通过审核。"}],"sourceUrl":"https://www.mohrss.gov.cn/","sourceNote":"本条为演示用示例数据，非真实政策，请勿据此申领","verified":false,"isSample":true,"numberStyle":"item","hunan":false},{"id":"cd-digital-2023","title":"常德市人民政府办公室关于印发《常德市“智赋万企”行动方案（2023—2025年）》的通知","level":"city","region":"常德市","issuer":"常德市人民政府办公室","documentNo":"CDCR—2023—01003","publishedAt":"2023-05-05","effectiveAt":null,"expiresAt":"2025-12-31","status":"expired","tags":["数字化转型","认定资质","财政奖补"],"audience":["常德市规模以上制造业企业","中小企业"],"summary":"到2025年推动全市12000家企业上云、1200家企业上平台，打造40家智能制造企业、400个智能工位。","sections":[{"no":"二","title":"数字化转型目标","text":"推动全市12000家企业上云，1200家企业上平台。全市75%的规模以上制造业企业基本实现数字化网络化，工业互联网平台在规模工业企业中的普及率达50%。"},{"no":"二续","title":"智能制造能力目标","text":"打造40家智能制造企业、80条（个）智能制造生产线（车间）、400个智能工位。"},{"no":"二续二","title":"企业培育目标","text":"国家级、省级专精特新“小巨人”企业分别达到35家、230家，国家级、省级制造业单项冠军分别达到5家、15家，推动30家以上企业通过国家两化融合管理体系贯标。"},{"no":"三(一)1","title":"基础设施提速","text":"全面部署千兆光纤网络，争创“千兆城市”，加快5G等新型基础设施建设，到2025年，建成5G基站12000个，实现市县城区和乡镇核心区域5G全面覆盖、重点场景5G深度覆盖。推动5G与工业互联网的融合创新，支持重点行业龙头企业进行内网改造。"}],"interpretations":[{"sectionNo":"三(一)1","headline":"到2025年建成5G基站12000个，支持龙头企业内网改造","who":"常德市重点行业龙头企业：可获5G内网改造支持；市县城区、乡镇核心区域及重点场景内企业可享5G网络覆盖。原文未设规模、营收等附加门槛。","materials":[],"window":"到2025年：建成5G基站12000个，实现市县城区和乡镇核心区域5G全面覆盖、重点场景5G深度覆盖。","where":"原文未指定受理部门或线上系统，仅表述为“支持重点行业龙头企业进行内网改造”。","tip":"5G基站与覆盖目标是全市建设口径，企业不单独申报；内网改造支持只指向重点行业龙头企业，其他企业的5G融合应用不在本条范围。"}],"sourceUrl":"https://www.changde.gov.cn/zwgk/public/6616759/2117570121.html","sourceNote":"2026-11-21 取自常德市政府门户「政务公开—规范性文件」原文页；页面给出登记号 CDCR—2023—01003 但未显示文号，已如实记录。行动期已止，判失效。 2026-11-21 收录：与官方页面逐句比对，命中 6/6 句（100%），关卡判定「verbatim」。 有效期依据：文件名载明实施期限止于2025年；基准日已过，判失效","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"cd-forest-2026","title":"常德市林业局等10家单位关于印发《常德市促进林下经济高质量发展的八条措施》的通知","level":"city","region":"常德市","issuer":"常德市林业局、常德市发展和改革委员会、常德市财政局、常德市自然资源和规划局、常德市交通运输局、常德市水利局、常德市农业农村局、常德市卫生健康委员会、常德市市场监督管理局、中国人民银行常德市分行","documentNo":"","publishedAt":"2026-07-06","effectiveAt":"2026-07-06","expiresAt":"2031-07-06","status":"active","tags":["财政奖补","融资支持","认定资质"],"audience":["林下经济经营主体","林业龙头企业","农民专业合作社","农产品加工企业"],"summary":"常德市促进林下经济高质量发展八条措施，从释放林地空间、适度规模经营、创新经营模式、培育经营主体、基础设施建设、产业提档增效、财政金融支持、组织领导八方面提出支持举措；市级财政整合涉林资金继续支持林下经济发展，林下种养主体购置农机、有机肥、绿色防控产品及病虫害防治补贴纳入惠农扶持政策，符合条件可申报中央预算内投资、地方政府专项债券、农业保险奖补和政府融资担保；文件未列具体补助金额或比例标准；自印发之日起施行，有效期5年。","sections":[{"no":"一","title":"","text":"有效释放发展空间。支持合理利用国家二级公益林、地方公益林、自然保护地一般控制区内的林地、除划定为天然林重点保护区域外的其他天然林适度发展林下经济。支持涉林项目实施主体合理利用林下空间发展林下经济。鼓励通过租赁、特许经营等方式，有偿使用国有森林资源资产发展林下经济。"},{"no":"二","title":"","text":"促进适度规模经营。进一步深化集体林权制度改革，加快推动林权确权登记和集体林地收益权量化到户，取消人工商品林主伐年龄限制，推广林耕置换，加快林权类不动产登记，探索林下空间经营权确认、登记、流转、融资机制，为流转林地经营权、促进适度规模经营创造基础条件。鼓励农户通过出租（转包）、入股或其他方式依法流转林地经营权，推动“小山变大山”；支持村级集体经济组织统一收储分散林地，通过“反租倒包”发展林下经济。"},{"no":"三","title":"","text":"创新生产经营模式。坚持市场主导、利益联结，推广“企业+村集体+基地+农户”“合作社（大户）+基地+农户”等多种经营模式，林畜、林禽、林蜂、林菌、林果等立体生产模式，发展林下经济。探索“国有林场+生态旅游+森林康养+特色研学”复合经营模式，支持“场村合作”，发挥国有林场资源、人才、技术优势，建设高标准林下产业基地，带动周边林农就业增收。"},{"no":"四","title":"","text":"培育壮大经营主体。鼓励合作社、专业大户、乡（村）办林场、国有企业、民营企业等各类经营主体投资发展林下经济。加大项目策划和招商引资力度，支持有实力的经营主体建设林产品种养基地、加工基地和线上线下相结合的销售平台，打造多功能、高效益的林下经济综合体。支持创建国（省）林下经济发展重点县、林下经济示范基地，支持符合条件的经营主体申报市级以上农业、林业产业化龙头企业和优势特色产业集群等项目。支持返乡农民工、高校毕业生、退役军人等投身发展林下经济。"},{"no":"五","title":"","text":"助力基础设施建设。支持发展林下经济必需的供电供水、通讯网络、培育贮存等基础设施建设，相关用地按直服用地规定程序办理。整合农业农村、林业、水利、交通等部门项目资金，支持林下经济示范基地基础设施建设。支持建设“林业标准地”。"},{"no":"六","title":"","text":"推动产业提档增效。突出发展重点，集中发展油茶、无患子、中药材、楠竹等产业，支持县市区因地制宜发展1-2个特色优势产业，建设高标准示范基地，形成鲜明区域特色。突出科技赋能，支持引进推广良种选育、良法种养、病虫害防治、采收加工、储藏保鲜等先进实用技术。突出产品开发，支持企业开发一批药食同源品、休闲即食品、美容护肤品、餐桌副食品，延长产业链，提高附加值。突出品牌建设，支持经营主体推行食用林产品“一品一码”质量追溯管理，开展绿色食品、有机农产品和农产品地理标志认证，打造一批区域公共品牌、特色品牌。突出销售服务，推广实施“互联网+林业经济”营销模式，推进传统营销模式与电商集群、直播带货、社区营销等新兴营销模式共同发展。"},{"no":"七","title":"","text":"加强财政金融支持。市级财政整合涉林资金继续支持林下经济发展，积极争取中央、省级财政林业专项资金支持。支持符合条件的林下经济项目申报中央预算内投资、地方政府专项债券等资金需求。将林下种养经营主体购置农机、有机肥、绿色防控产品以及病虫害防治补贴等纳入惠农扶持政策范畴。鼓励金融机构针对林下经济发展特点，开发期限适配、利率优惠的林业信贷产品。鼓励开发多样化的林下经济保险产品，逐步扩大保险覆盖面，符合条件的纳入省以下品种农业保险奖补范围，鼓励为符合条件的林下经济经营主体提供政府融资担保服务。"},{"no":"八","title":"","text":"强化组织领导保障。压实各级林长发展林下经济责任，将林下经济发展纳入林长制督查考核评价指标体系。建立由市政府牵头抓总，市林业局具体负责，发改、财政、自然资源、农业农村、市场监管、科技、金融等部门积极参与的协同联动机制，协调解决具体问题。各县市区政府结合实际细化举措，厘清部门职责，推动各项措施落实。加强对林下经济发展成功模式、典型经验、特色品牌的宣传推广，营造林下经济发展的浓厚氛围，带动全市林下经济高质量发展。"},{"no":"九","title":"","text":"本措施自印发之日起施行，有效期5年。国家及省另有规定的，从其规定。"}],"interpretations":[{"sectionNo":"一","headline":"二级公益林、一般控制区林地可适度发展林下经济","who":"利用国家二级公益林、地方公益林、自然保护地一般控制区内林地，以及除天然林重点保护区域外其他天然林发展林下经济的涉林项目实施主体；可租赁、特许经营有偿使用国有森林资源资产。","materials":[],"window":"原文未设申报期限，措施施行期内适用","where":"林地权属方（国有森林资源资产通过租赁、特许经营有偿使用）","tip":"天然林重点保护区域不在支持范围；支持方式为租赁、特许经营等有偿使用。"},{"sectionNo":"二","headline":"取消人工商品林主伐年龄限制，林地经营权可流转","who":"流转林地经营权发展林下经济的农户、村级集体经济组织；农户可出租（转包）、入股流转，村集体可统一收储分散林地后反租倒包。","materials":[],"window":"原文未设申报期限","where":"未列受理窗口；林权类不动产登记按不动产登记渠道办理","tip":"探索林下空间经营权确认、登记、流转、融资机制；推动小山变大山。"},{"sectionNo":"三","headline":"推广企业+村集体+基地+农户等林下经营模式","who":"参与林下经济的企业、村集体、合作社（大户）、农户；国有林场可通过场村合作建设高标准林下产业基地。","materials":[],"window":"原文未设申报期限","where":"国有林场（场村合作）","tip":"支持国有林场+生态旅游+森林康养+特色研学复合经营，带动周边林农就业增收。"},{"sectionNo":"四","headline":"支持创建国省林下经济示范基地、申报市级以上龙头企业","who":"合作社、专业大户、乡（村）办林场、国有企业、民营企业等经营主体；返乡农民工、高校毕业生、退役军人等投身林下经济者。","materials":[],"window":"原文未设申报期限，按市级以上农业、林业产业化龙头企业申报安排","where":"市级以上农业、林业产业化龙头企业认定渠道（原文未列受理部门）","tip":"支持建设林产品种养基地、加工基地和线上线下销售平台；可创建国（省）林下经济发展重点县、示范基地。"},{"sectionNo":"五","headline":"林下经济供电供水、通讯、培育贮存设施可获项目资金","who":"发展林下经济需建设供电供水、通讯网络、培育贮存等基础设施的经营主体；相关用地按直服用地规定程序办理。","materials":[],"window":"原文未设申报期限","where":"农业农村、林业、水利、交通等部门项目资金（原文未列申报窗口）","tip":"用地须按直服用地规定程序办理；支持建设林业标准地。"},{"sectionNo":"六","headline":"重点发展油茶、中药材、楠竹，县市区可育1-2个特色产业","who":"发展油茶、无患子、中药材、楠竹等产业的经营主体；推行食用林产品一品一码追溯、开展绿色食品、有机农产品和农产品地理标志认证的企业。","materials":[],"window":"原文未设申报期限","where":"绿色食品、有机农产品和农产品地理标志认证渠道","tip":"支持引进良种选育、良法种养、病虫害防治、采收加工、储藏保鲜技术；推广互联网+林业经济营销。"},{"sectionNo":"七","headline":"林下经济项目可申报中央预算内投资、地方政府专项债券","who":"符合条件的林下经济项目主体；购置农机、有机肥、绿色防控产品及病虫害防治补贴的林下种养经营主体。","materials":[],"window":"原文未设申报期限，按中央预算内投资、专项债券申报节奏","where":"市级财政、金融机构（原文未列具体申报窗口）","tip":"林下种养购置农机、有机肥、绿色防控产品纳入惠农扶持政策；保险符合条件纳入省以下品种农业保险奖补范围。"}],"sourceUrl":"https://www.changde.gov.cn/zwgk/zwgk/zfgb/2026n/2026nd7-8qzd209q8y31rcb/szfbmwj/4237874281.html","derivedFrom":"official","sourceNote":"2026-11-22 取自常德市人民政府门户「政务公开—政府公报—2026年第7-8期—市直部门文件」原文页，发文日期2026年7月6日，联合发文单位共10家（红头与落款一致）。页面为政府公报版式，仅载统一登记号 CDCR—2026—30001，全页无“××发〔2026〕×号”形式的发文字号，故 documentNo 留空。 2026-11-22 收录：与官方页面逐句比对，命中 12/12 句（100%），关卡判定「verbatim」。 有效期依据：正文末条明示“有效期5年”，自2026年7月6日印发起算至2031年7月6日 2026-11-24 收录：与官方页面逐句比对，命中 30/30 句（100%），关卡判定「verbatim」。 有效期依据：原文未明示","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"cd-msme-2022-5","title":"常德市人民政府关于印发《常德市促进市场主体高质量发展实施方案》的通知","level":"city","region":"常德市","issuer":"常德市人民政府","documentNo":"常政发〔2022〕5号","publishedAt":"2022-03-23","effectiveAt":null,"expiresAt":null,"status":"active","tags":["认定资质","财政奖补","营商环境"],"audience":["常德市各类市场主体","规模工业企业","专精特新“小巨人”企业","高新技术企业"],"summary":"每年净增规模以上工业企业150家，到2025年末全市规上工业企业总数达2200家、国家级专精特新“小巨人”企业55家。","sections":[{"no":"一","title":"目标任务","text":"2022年，净增市场主体5万户，总数达到43.5万户，其中净增企业1.5万户、“个转企”1500户。到2025年末，全市市场主体突破58.5万户，其中企业突破12.6万户，净增“四上”企业1000家以上。"},{"no":"一(一)","title":"培育发展先进制造业企业","text":"大力培育四大千亿产业，积极发展四大新兴产业，形成产业集群，强力推进工业项目建设，加快推进新建投产项目“入规”。每年净增规模以上工业企业150家，到2025年末，全市规模以上工业企业总数达到2200家、国家级专精特新“小巨人”企业55家、省级专精特新“小巨人”企业180家、制造业单项冠军企业12家。"},{"no":"一(四)","title":"培育发展建筑业企业","text":"支持建筑业企业资质升级、增项，鼓励建筑业企业创建行业品牌，提升企业竞争力。每年净增具有总承包和专业承包资质的独立核算建筑业企业22家。"},{"no":"一(六)","title":"培育发展高新技术企业","text":"设立优质企业名录库和光荣榜（龙虎榜），实施市级工程技术中心培育行动。"}],"interpretations":[],"sourceUrl":"https://www.hunan.gov.cn/zqt/zcsd/202204/t20220415_22737277.html","sourceNote":"2026-11-21 取自省门户「政策速递」转载页；文号与成文日期（2022年3月23日）已核对。常德市政府门户原始页未检出，标为转载页。 2026-11-21 收录：与官方页面逐句比对，命中 7/7 句（100%），关卡判定「verbatim」。 有效期依据：原文未设期限；按行政规范性文件一般不超5年推算至2027-03","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"cd-startup-2025","title":"常德市2025年度一次性创业补贴申报","level":"city","region":"常德市","issuer":"常德市人力资源和社会保障局","documentNo":"","publishedAt":"","effectiveAt":null,"expiresAt":"2025-11-20","status":"expired","tags":["创业补贴","就业补贴"],"audience":["近5年内在常德首次创办小微企业或从事个体经济的大学生、就业困难人员、返乡入乡农民工","创业孵化基地在孵实体"],"summary":"2025年度一次性创业补贴，最高15000元：按吸纳就业人数分3档，吸纳2人补5000元、3—9人补10000元、10人以上补15000元；大学生创业者首次创办小微企业或个体经济并注册补10000元，吸纳3人及以上就业提高至15000元。对象为近5年内首次创业的大学生、就业困难人员、返乡入乡农民工及孵化基地在孵实体；须正常运营1年以上、吸纳2人及以上并稳定就业6个月以上；11月20日前向注册地人社部门申报。","sections":[{"no":"一","title":"申报安排","text":"10月27日，记者从常德市人社部门获悉，全市2025年度一次性创业补贴申报已启动，符合条件者可于11月20日前向营业执照注册地人社部门申报；市、县人社部门管理的创业孵化基地在孵企业和个体工商户，向直属的就业服务机构申报。"},{"no":"二","title":"补贴对象","text":"本次补贴对象包括近5年内（2020年1月1日以后）在常德市范围内首次创办小微企业或从事个体经济的大学生（在校及毕业2年内，含普通高校、职业学校、技工院校和留学归国人员）、就业困难人员、返乡入乡农民工；人社部门认定的创业孵化基地内的在孵实体初创企业和初次注册的个体工商户。"},{"no":"三","title":"申报条件","text":"申报一次性创业补贴需符合以下条件：创业或经营项目符合国家产业政策方向；市场主体自登记注册之日起正常运营1年以上；吸纳2名及以上劳动者并稳定就业6个月以上（申报大学生一次性创业补贴的，吸纳就业人数可适当放宽）；近两年在“信用中国”平台无行政处罚等违法记录。创业孵化基地内的在孵实体，还需入孵并正常经营1年以上，且在孵时间不超过3年。已享受过人社部门创业补贴的主体，不再重复享受。"},{"no":"四","title":"补贴标准","text":"根据吸纳城乡劳动者就业人数情况，一次性创业补贴标准分为3档：吸纳2人就业的，可享5000元补贴；吸纳3—9人就业的，可享10000元补贴；吸纳10人以上就业的，可享15000元补贴。针对大学生创业者，补贴标准进一步提高：首次创办小微企业或从事个体经济并注册的，可获10000元补贴；若吸纳3人及以上就业，补贴金额提高至15000元。"}],"interpretations":[{"sectionNo":"一","headline":"常德一次性创业补贴：11月20日前向注册地人社部门申报","who":"符合2025年度一次性创业补贴条件的申报主体；市、县人社部门管理的创业孵化基地在孵企业和个体工商户，向直属的就业服务机构申报，其余主体向营业执照注册地人社部门申报。","materials":[],"window":"2025年度申报已启动，11月20日前申报。","where":"营业执照注册地人社部门；创业孵化基地在孵企业和个体工商户向直属的就业服务机构申报。","tip":"两类申报口不同：一般主体向营业执照注册地人社部门，孵化基地在孵企业和个体工商户向直属的就业服务机构。"},{"sectionNo":"二","headline":"近5年首次在常德创业的大学生、就业困难人员、返乡农民工","who":"近5年内（2020年1月1日以后）在常德市范围内首次创办小微企业或从事个体经济的大学生（在校及毕业2年内，含普通高校、职业学校、技工院校和留学归国人员）、就业困难人员、返乡入乡农民工；人社部门认定的创业孵化基地内的在孵实体初创企业和初次注册的个体工商户。","materials":[],"window":"近5年内（2020年1月1日以后）首次创办；按2025年度申报。","where":"常德市、县人社部门；人社部门认定的创业孵化基地。","tip":"须为首次创办；大学生含在校及毕业2年内，含职业学校、技工院校和留学归国人员。"},{"sectionNo":"三","headline":"正常运营1年以上、吸纳2人稳定就业6个月以上可申报","who":"创业或经营项目符合国家产业政策方向；市场主体自登记注册之日起正常运营1年以上；吸纳2名及以上劳动者并稳定就业6个月以上（申报大学生一次性创业补贴的，吸纳就业人数可适当放宽）；近两年在“信用中国”平台无行政处罚等违法记录；创业孵化基地在孵实体还需入孵并正常经营1年以上、在孵时间不超过3年；已享受过人社部门创业补贴的主体不再重复享受。","materials":[],"window":"正常运营1年以上、稳定就业6个月以上；近两年无违法记录；在孵时间不超过3年。","where":"“信用中国”平台（核查违法记录）；常德市、县人社部门。","tip":"已享受过人社部门创业补贴的主体不再重复享受；大学生吸纳就业人数可适当放宽。"},{"sectionNo":"四","headline":"大学生创业补10000元，吸纳3人以上提高至15000元","who":"按吸纳城乡劳动者就业人数分档：吸纳2人就业补5000元；吸纳3—9人就业补10000元；吸纳10人以上就业补15000元。大学生创业者首次创办小微企业或从事个体经济并注册的补10000元，吸纳3人及以上提高至15000元。","materials":[],"window":"一次性发放，按吸纳城乡劳动者就业人数分档核定。","where":"常德市、县人社部门（申报口见第一条申报安排）。","tip":"大学生注册即补10000元，吸纳3人及以上提高至15000元；一般主体按吸纳2人、3—9人、10人以上分别补5000元、10000元、15000元。"}],"sourceUrl":"https://www.changde.gov.cn/cdzx/bmdt/content_78177859","derivedFrom":"official","sourceNote":"2026-11-24 修订：原条目仅 4 款且缺补贴标准，按常德市人民政府门户「常德资讯—部门动态」原文（常德日报 2025-10-28）逐段补录，补入5000/10000/15000元三档及大学生10000/15000元标准。原文为新闻报道，无条款编号，按段落列款。 2026-11-24 收录：与官方页面逐句比对，命中 15/15 句（100%），关卡判定「verbatim」。 有效期依据：原文未明示","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"cd-synbio-2026","title":"常德市支持合成生物制造产业发展的若干措施","level":"city","region":"常德市","issuer":"常德市人民政府","documentNo":"","publishedAt":"2026-06-08","effectiveAt":"2026-06-08","expiresAt":"2028-12-31","status":"active","tags":["财政奖补","研发创新","认定资质","专项资金"],"audience":["合成生物制造企业","高新技术企业","专精特新中小企业","制造业单项冠军企业"],"summary":"对合成生物制造企业研发投入较上年新增加计扣除部分按20%补助、单家每年最高100万元；对新认定国家高企奖10万元、国家级专精特新“小巨人”奖50万元、20万元；市级奖补资金在市合成生物制造产业专项资金中列支，有效期至2028年12月31日。","sections":[{"no":"一（一）","title":"支持企业加大研发投入","text":"市财政按合成生物制造企业（以下简称企业）用于合成生物领域较上年度新增享受研发费用加计扣除部分的20%给予补助，每年每家企业最高不超过100万元。“常德市十大技术攻关与成果转化项目”向合成生物制造产业倾斜。"},{"no":"一（二）","title":"鼓励承接科技专项","text":"对新获得合成生物领域国家级重点专项或课题的承担单位，市财政按实际获得资助经费的30%给予配套支持，单个国家级项目配套总额最高不超过300万元。配套资金只能用于项目承担单位的后续研发。"},{"no":"二（五）","title":"完善企业培育体系","text":"支持企业专注细分领域，培育一批高新技术企业、专精特新企业和单项冠军企业，对新认定、再次认定的国家高新技术企业，市财政分别给予10万元、5万元奖励；对新认定的国家级专精特新重点“小巨人”企业、国家级专精特新“小巨人”企业，市财政分别给予50万元、20万元奖励；对新认定的国家级制造业“单项冠军”企业，市财政给予20万元奖励。"},{"no":"三（九）","title":"发挥政府专项资金作用","text":"安排中小企业发展专项资金并逐步扩大资金规模，统筹科技创新重大项目资金向小微型企业倾斜，通过资助、购买服务、奖励等方式，重点支持合成生物领域公共服务体系建设、中小企业专精特新发展和融资担保体系建设。"},{"no":"三（十）","title":"拓宽融资担保渠道","text":"发挥政府性融资担保作用，推广“信补贷”“潇湘财银贷”“知识价值信用贷”等政策性金融产品，拓宽企业融资渠道。鼓励金融机构为企业提供以应收账款、知识产权、机器设备等为担保品的担保融资。"}],"interpretations":[{"sectionNo":"一（一）","headline":"研发费用加计扣除新增部分补20%，每家每年最高100万","who":"常德市合成生物制造企业；补助基数是用于合成生物领域、较上年度新增享受研发费用加计扣除的部分。","materials":[],"window":"按年度计算，每年每家企业最高不超过100万元；原文未设申报截止日。","where":"市财政（原文未列具体受理部门或申报系统）","tip":"只补“较上年度新增”的加计扣除部分，不是全部研发费用；比例20%，每年每家封顶100万元。"},{"sectionNo":"一（二）","headline":"国家级重点专项配套30%，单个项目最高300万","who":"新获得合成生物领域国家级重点专项或课题的承担单位。","materials":[],"window":"按项目立项配套，单个国家级项目配套总额最高不超过300万元。","where":"市财政（原文未列具体受理部门或申报系统）","tip":"配套按实际获得资助经费的30%计算、单个项目封顶300万元；资金只能用于后续研发。"},{"sectionNo":"二（五）","headline":"国家高企新认定奖10万、再次认定奖5万，小巨人最高50万","who":"常德市合成生物制造等细分领域企业：新认定或再次认定的国家高新技术企业；新认定的国家级专精特新重点“小巨人”企业、国家级专精特新“小巨人”企业；新认定的国家级制造业“单项冠军”企业。","materials":[],"window":"一次性奖励，按认定年度兑现；原文未设申报截止日。","where":"市财政（认定由科技部、工业和信息化部作出，原文未列申报窗口）","tip":"国家高企“新认定10万元、再次认定5万元”；专精特新仅“新认定”给奖，重点“小巨人”50万元高于“小巨人”20万元；单项冠军20万元。"},{"sectionNo":"三（九）","headline":"中小企业专项资金向小微倾斜，支持公共服务与专精特新","who":"合成生物领域的中小企业、小微型企业，以及公共服务体系、融资担保体系建设相关主体。","materials":[],"window":"按年度专项资金安排执行，原文未设申报期。","where":"市财政（中小企业发展专项资金，原文未列受理窗口）","tip":"资金投向三个方向：公共服务体系、专精特新、融资担保体系；支持方式是资助、购买服务、奖励。"},{"sectionNo":"三（十）","headline":"推广信补贷、潇湘财银贷、知识价值信用贷等融资产品","who":"有融资需求的合成生物制造等企业；可用应收账款、知识产权、机器设备等作为担保品申请担保融资。","materials":[],"window":"按各政策性金融产品规则办理，原文未设申报期。","where":"政府性融资担保机构、金融机构（“信补贷”“潇湘财银贷”“知识价值信用贷”）","tip":"本条是融资渠道而非财政奖补；担保品可为应收账款、知识产权、机器设备，不必局限不动产。"}],"sourceUrl":"https://cdjkq.changde.gov.cn/yqgk/zsyz/hqzc/content_78206023","sourceNote":"2026-11-22 取自常德经济技术开发区管委会门户「园区概况—招商引资—惠企政策」栏目转载的市级政策原文，页面标注来源为中共常德市人民政府。该转载页未载版头文号，故 documentNo 留空。原文为“自印发之日起施行”，转载页发布时间为2026-06-08，effectiveAt 据此填写。 2026-11-22 收录：与官方页面逐句比对，命中 10/10 句（100%），关卡判定「verbatim」。 有效期依据：正文末条明示“有效期至2028年12月31日”","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"chaling-listing-award-2022","title":"茶陵县企业挂牌上市扶持奖励办法","level":"district","region":"株洲市·茶陵县","issuer":"茶陵县人民政府","documentNo":"茶政发〔2022〕38号","publishedAt":"2022-12-20","effectiveAt":"2022-12-20","expiresAt":null,"status":"active","tags":["上市培育","财政奖补","融资支持"],"audience":["茶陵县内拟上市（挂牌）企业","新三板及湖南股权交易所挂牌企业"],"summary":"对在沪深证券交易所主板或中小板上市的企业按向湖南证监局辅导备案、申报受理、发行上市三个阶段以“二三五”比例给予总额600万元补助；借壳上市或境外主流资本市场上市一次性补助600万元，总部迁入并本地纳税的上市公司同样一次性补助600万元；北交所上市总额400万元，转板沪深再补200万元；新三板基础层、创新层挂牌一次性100万元；湖南股交所股改板、科技创新专板挂牌一次性25万元。","sections":[{"no":"二","title":"","text":"二、 对在沪、深证券交易所主板或中小板上市企业， 按照 “ 二三五 ” 比例分阶段（即向 湖南证监局辅导备案、申报上市材料并获受理、上市发行三个阶段）给予总额奖励 600 万元补 助， 待企业成功上市后可按不超过 30% 用于奖励企业管理团队及技术骨干。"},{"no":"三","title":"","text":"三、对在沪、深证券交易所借壳上市或在香港、美国等境外主流资本市场上市的企业，给予一次性 6 00 万元补 助。对总部注册地迁入茶陵县并完成工商、纳税登记关系变更且在茶陵本地纳税的上市公司，承诺不搬离本县，给予一次性 6 00 万元补助。同时享受茶陵县招商引资相关政策。"},{"no":"四","title":"","text":"四、对在北京证券交易所上市的企业， 按照 “ 二三五 ” 比例分阶段（即向 湖南证监局辅导备案、申报上市材料并获受理、发行上市 三个阶段）给予总额奖励 4 00  万元 ，之前享受的新三板挂牌补助相应扣除。对成功转板至沪、深证券交易所上市的北交所企业，再给予 200 万元补 助。"},{"no":"五","title":"","text":"五、 对在全国中小企业股份转让系统（ “ 新三板 ” ） 基础层和创新层挂牌的企业，给予一次性 100 万元补 助。"},{"no":"六","title":"","text":"六、对在湖南股权交易所股改板、科技创新专板挂牌的企业， 给予一次性 2 5 万元补 助。"},{"no":"十（二）","title":"","text":"（二）本办法自公布之日起施行，以前政策与本文件不一致的，以本文件为准。"}],"interpretations":[{"sectionNo":"二","headline":"沪深主板或中小板上市，总额奖励600万元，分三阶段拨付","who":"在沪、深证券交易所主板或中小板上市的企业；须按“二三五”比例分阶段推进，即向湖南证监局辅导备案、申报上市材料并获受理、上市发行三个阶段。","materials":[],"window":"分阶段奖励：向湖南证监局辅导备案、申报上市材料并获受理、上市发行三个阶段，按“二三五”比例拨付。","where":"湖南证监局（辅导备案）；沪、深证券交易所（上市发行）。","tip":"奖励按阶段分次拨付，不是一次性到账；企业成功上市后，可按不超过30%用于奖励企业管理团队及技术骨干。"},{"sectionNo":"三","headline":"借壳或境外主流市场上市，一次性补600万元","who":"在沪、深证券交易所借壳上市，或在香港、美国等境外主流资本市场上市的企业；总部注册地迁入茶陵县并完成工商、纳税登记关系变更、在茶陵本地纳税且承诺不搬离本县的上市公司。","materials":[],"window":"一次性补助；总部迁入的须完成工商、纳税登记关系变更并在茶陵本地纳税、承诺不搬离本县。","where":"上市地：沪、深证券交易所，或香港、美国等境外主流资本市场；总部迁入在茶陵县办理工商、纳税登记变更。","tip":"迁入型补助以承诺不搬离本县为前提，且须在茶陵本地纳税；同时可享受茶陵县招商引资相关政策。"},{"sectionNo":"四","headline":"北交所上市分阶段奖励，转板沪深再补200万元","who":"在北京证券交易所上市的企业，按“二三五”比例分阶段（向湖南证监局辅导备案、申报上市材料并获受理、发行上市）申请；成功转板至沪、深证券交易所上市的北交所企业可再申请。","materials":[],"window":"分三阶段拨付：辅导备案、申报受理、发行上市；转板沪深后另行申请200万元补助。","where":"湖南证监局（辅导备案）；北京证券交易所（上市）；转板后在沪、深证券交易所上市。","tip":"之前享受的新三板挂牌补助要相应扣除；转板至沪深交易所后再补200万元。"},{"sectionNo":"五","headline":"新三板基础层、创新层挂牌，一次性补100万元","who":"在全国中小企业股份转让系统（“新三板”）基础层和创新层挂牌的企业。","materials":[],"window":"挂牌后一次性发放。","where":"全国中小企业股份转让系统（“新三板”）。","tip":"补助为一次性；基础层、创新层挂牌均在覆盖范围内。"},{"sectionNo":"六","headline":"湖南股交所股改板、科技创新专板挂牌，一次性补助","who":"在湖南股权交易所股改板、科技创新专板挂牌的企业。","materials":[],"window":"挂牌后一次性发放。","where":"湖南股权交易所。","tip":"只覆盖股改板、科技创新专板两个板块；补助一次性发放。"}],"sourceUrl":"http://www.chaling.gov.cn/c11039/20230112/i1991144.html","sourceNote":"2026-11-22 取自茶陵县政府门户「政府文件」原文页，页面标注来源为茶陵县人民政府；版头文号茶政发〔2022〕38号，统一登记号 ZZCLDR—2022—00005（公报登记号，非发文字号）。成文日期2022年12月16日，页面发布时间2022年12月20日，原文为“自公布之日起施行”，生效日取页面发布日期。 2026-11-22 收录：与官方页面逐句比对，命中 9/9 句（100%），关卡判定「verbatim」。 有效期依据：第十条第（二）项","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"chaling-msme-loan-interest-2022","title":"茶陵县中小微工业企业贷款贴息办法","level":"district","region":"株洲市·茶陵县","issuer":"茶陵县人民政府办公室","documentNo":"茶政办发〔2022〕29号","publishedAt":"2022-05-20","effectiveAt":"2022-05-20","expiresAt":null,"status":"active","tags":["贷款贴息","融资支持","财政奖补"],"audience":["茶陵县内注册的规模以上中小微工业企业","技改与科技创新型工业企业"],"summary":"对茶陵县内依法登记、经营满1年以上的非国有中小微工业企业新增贷款给予贴息，按年缴增值税分四档贴息比例分别为利息的40%、30%、20%、10%；单户企业当年贴息最高30万元，且县本级留存财力不低于贴息额2倍；县财政年度预算贴息资金200万元，申报截止次年1月31日。","sections":[{"no":"二","title":"","text":"本办法适用于在茶陵县市场监督管理部门注册登记并具有独立法人资格的，合法正常经营满 1 年以上，资信程度良好，符合《关于印发中小企业划型标准规定的通知》（工信部联企业〔 2011 〕 300 号）规定（新的中小企业划型标准出台后，按新标准执行）的非国有或非国有控股的中小微工业企业。重点扶持和发展工业制造业企业、高新技术企业、进行技术改造和技术创新的科技型企业，以及吸纳失业人员等劳动密集型工业企业要优先扶持；申请贷款贴息的企业必须是按规定依法足额缴纳税款、不拖欠职工工资、无重大安全事故、无重大环境污染、信誉度良好的合法经营的规模工业企业。下列企业不在贴息范围内：以消耗非可再生性资源为主的企业，主要指石材、矿贸、有色、陶瓷、煤炭矿产开采、水泥生产以及水、电生产等企业。"},{"no":"四","title":"","text":"符合条件的工业企业，具体贴息标准： \n （一）贷款数额 100 万元（含 100 万元）以上且当年缴纳增值税 50 万元以上（含 50 万元）的工业企业，可获得当年贷款所产生利息 40% 的贴息。 \n （二）贷款数额 100 万元（含 100 万元）以上且当年缴纳增值税（ 20 ）万元以上（含 20 万元）的工业企业，可获得当年贷款所产生利息 30% 的贴息。 \n （三）贷款数额 100 万元（含 100 万元）以上且当年缴纳增值税 10 万元以上（含 10 万元）的工业企业，可获得当年贷款所产生利息 20% 的贴息。 \n （四）贷款数额 100 万元（含 100 万元）以上且当年缴纳增值税 1 万元以上（含 1 万元）的工业企业，可获得当年贷款所产生利息 10% 的贴息。 \n （五）补贴利率标准：按实补贴，且申请补贴企业贷款利率不高于贷款借据日期中国人民银行公布的同期贷款基准利率。"},{"no":"五","title":"","text":"每户企业当年贷款贴息金额最高为 30 万元，且每户企业当年纳税总额中县本级留存财力应不低于贴息金额的 2 倍，否则按比例递减贴息金额。"},{"no":"八","title":"","text":"县财政年度预算贴息资金为 200 万元，当企业申报补贴总额超过财政年度贴息预算时，则按比例份额分配企业申报贴息额。"},{"no":"十四","title":"","text":"本办法自 公布之日 起 开始 施行。"}],"interpretations":[{"sectionNo":"二","headline":"茶陵非国有中小微工业企业经营满1年可申请贷款贴息","who":"在茶陵县市场监督管理部门注册登记、具独立法人资格、合法正常经营满1年以上的非国有或非国有控股中小微工业企业；须资信良好、依法足额纳税、不拖欠职工工资、无重大安全事故、无重大环境污染；石材、矿贸、有色、陶瓷、煤炭矿产开采、水泥生产及水、电生产企业不在贴息范围。","materials":[],"window":"按年度贷款计息期申报，具体申报时间原文未列。","where":"茶陵县市场监督管理部门登记注册；贴息资金由县财政年度预算安排（原文未列受理窗口）。","tip":"石材、矿贸、有色、陶瓷、煤炭矿产开采、水泥生产及水、电生产企业不纳入；须经营满1年、依法足额纳税且无重大安全事故、无重大环境污染。"},{"sectionNo":"四","headline":"贷款100万元以上，按增值税额贴息40%至10%","who":"贷款数额100万元（含）以上、当年缴纳增值税1万元以上的茶陵县非国有中小微工业企业；按增值税额分四档：50万元以上贴40%、20万元以上贴30%、10万元以上贴20%、1万元以上贴10%；贷款利率不得高于贷款借据日期中国人民银行公布的同期贷款基准利率。","materials":[],"window":"按当年贷款所产生利息计算，一年一贴。","where":"原文未写明受理窗口；贴息按当年贷款利息由县财政资金安排。","tip":"四档按当年增值税额对应，就高档不叠加；贷款利率高于借据日期同期贷款基准利率的不予补贴；每户当年最高30万元。"},{"sectionNo":"五","headline":"每户当年贴息最高30万元，留存财力须达贴息额2倍","who":"已获贴息的茶陵县中小微工业企业；每户当年贴息金额最高30万元；当年纳税总额中县本级留存财力不低于贴息金额的2倍。","materials":[],"window":"按年度计算，一年一贴；当年贴息额同时受30万元上限与留存财力2倍约束。","where":"原文未写明受理窗口；由县财政在年度贴息预算内核定。","tip":"县本级留存财力不足贴息金额2倍的，按比例递减贴息；30万元是每户当年上限，不是必达额度。"},{"sectionNo":"八","headline":"县财政年度贴息预算200万元，超额按比例分配","who":"申报茶陵县中小微工业企业贷款贴息的企业；当申报补贴总额超过年度预算200万元时，按比例份额分配。","materials":[],"window":"按财政年度预算执行，年度贴息资金总额200万元。","where":"茶陵县财政（年度预算安排）。","tip":"申报总额超过200万元预算时按比例份额分配，不能按申报额全额贴息。"}],"sourceUrl":"http://www.chaling.gov.cn/c11039/20220520/i1861938.html","sourceNote":"2026-11-22 取自茶陵县政府门户「政府文件」原文页，页面标注来源为茶陵县人民政府办公室；版头文号茶政办发〔2022〕29号，统一登记号 ZZCLDR—2022—01002。成文日期2022年5月7日，页面发布时间2022年5月20日；原文为“自公布之日起施行”，生效日取页面发布日期。 2026-11-22 收录：与官方页面逐句比对，命中 13/13 句（100%），关卡判定「verbatim」。 有效期依据：第十四条","verified":false,"isSample":false,"numberStyle":"clause","bodyVerified":"verbatim","hunan":true},{"id":"changsha-one-time-startup-subsidy-2026","title":"关于开展长沙市一次性创业补贴（含大学生一次性创业补贴）申报工作的通知","level":"city","region":"长沙市","issuer":"长沙市人力资源和社会保障局","documentNo":"","publishedAt":"2026-05-25","effectiveAt":"","expiresAt":"","status":"active","tags":["创业补贴"],"audience":["初创企业","高校毕业生"],"summary":"长沙初创企业正常经营1年以上并吸纳就业，按吸纳人数补5000至30000元，大学生同项补1万至3万元。","sections":[{"no":"一","title":"一次性创业补贴申报","text":"（一）申报条件\n\n申报长沙市一次性创业补贴，须同时具备以下条件：\n\n1.在湖南湘江新区、芙蓉区、天心区、开福区、雨花区、望城区范围内登记注册的初创企业；登记注册时间在5年以内（自注册之日至申报之日不超过5年）；\n\n2.正常经营1年以上，吸纳1名及以上劳动者就业，缴纳城镇职工社会保险费6个月以上且处于正常缴纳状态；\n\n3.符合长沙市产业发展方向；\n\n4.在信用中国无行政处罚、严重失信等记录；\n\n5.申报人为企业法定代表人，属于就业困难人员或返乡入乡农民工，持股比例不低于企业总股份的30%；\n\n申报人非企业第一任法定代表人的，不纳入补贴范围。\n\n（二）所需资料\n\n1.《长沙市一次性创业补贴申请表》（申报系统填写资料后自动生成）；\n\n2.营业执照、申报人身份证；企业股权分配证明资料；\n\n3.申报人属于返乡入乡农民工的需提供长沙市行政区域范围内户籍地乡镇（街道）人力资源社会保障服务站或村（社区）出具的返乡创业佐证资料；属于就业困难人员的无需提供佐证资料，由湖南湘江新区民政和社会保障局、各区人力资源和社会保障局在信息系统中核实。\n\n（三）补贴标准\n\n根据吸纳城乡劳动者就业人数申请5000至30000元不等的一次性创业补贴。吸纳城乡劳动者就业人数取申报前3个月缴纳城镇职工社会保险人数的平均值。吸纳1人的按5000元标准给予一次性创业补贴；吸纳1人以上的每增加1人给予1000元补贴，最高不超过30000元。已经享受过市财政同一项目补贴的，不能重复享受。"},{"no":"二","title":"大学生一次性创业补贴","text":"（一）申报条件\n\n申报大学生一次性创业补贴，须同时具备以下条件：\n\n1.在湖南湘江新区、芙蓉区、天心区、开福区、雨花区、望城区范围内登记注册的初创企业；登记注册时间在5年以内（自注册之日至申报之日不超过5年）；\n\n2.正常经营1年以上，吸纳1名及以上劳动者就业，缴纳城镇职工社会保险费3个月以上且处于正常缴纳状态；\n\n3.符合长沙市产业发展方向；\n\n4.在信用中国无行政处罚、严重失信等记录；\n\n5.申报人为企业法定代表人，属于离校2年内高校毕业生，且持股比例不低于企业总股份的30%；\n\n申报人非企业第一任法定代表人的，不纳入补贴范围。\n\n（二）所需资料\n\n1.《长沙市大学生一次性创业补贴申请表》（申报系统填写资料后自动生成）；\n\n2.营业执照、申报人身份证、企业股权分配证明资料；\n\n3.申报人属于离校2年内高校毕业生的相关证明材料（毕业证或学信网学籍证明）。\n\n（三）补贴标准\n\n根据吸纳城乡劳动者就业人数申请10000至30000元不等的一次性创业补贴。吸纳城乡劳动者就业人数取申报前3个月缴纳城镇职工社会保险人数的平均值。吸纳1人的按10000元标准给予一次性创业补贴；吸纳1人以上的每增加1人给予1000元补贴，最高不超过30000元。已经享受过市财政同一项目补贴的，不能重复享受。"},{"no":"三","title":"申报流程","text":"（一）线上申报。长沙市一次性创业补贴、大学生一次性创业补贴进行线上申报。申报人登录湖南省政务服务网点击“高效办成一件事”，选择“大学生就业创业落户‘一件事’——创业补贴申领”（离校2年内高校毕业生）或“个人创业‘一件事’——创业补贴申领”（返乡入乡农民工、就业困难人员），按要求填写相关信息，并上传相关资料。\n\n（二）审核报送。湖南湘江新区民政和社会保障局、各区人力资源和社会保障局负责辖区内申报资料的审核，并做好实地考察工作，将符合条件的申报人名单报送至市人力资源社会保障局。\n\n（三）市级复审。市人力资源社会保障局对申报人资料进行复审，核定申报人是否符合申报条件，对符合条件的，核定其吸纳就业人数和应补贴金额，形成拟补贴名单。\n\n（四）网上公示。每个季度对该季度拟补贴的申报人名单在市人力资源社会保障局官网上进行公示，公示期为5个工作日。\n\n（五）资金拨付。受补贴名单公示完毕后，由湘江新区民政和社会保障局、各区县（市）人力资源和社会保障局按照相关规定将扶持资金拨付至申报人账户。"},{"no":"四","title":"补贴终止","text":"出现以下情形之一的，终止享受补贴：\n\n（一）申报审核期间，初创企业实体处于停业状态，或已注销、吊销营业执照的。\n\n（二）经核实有其他不符合补贴发放政策相关条件的。"},{"no":"五","title":"工作要求","text":"（一）加强宣传推荐。湖南湘江新区民政和社会保障局、各区人力资源和社会保障局要通过网络、报纸、电视、微信等媒体广泛开展政策宣传。各相关单位要积极推荐符合当地产业发展方向，代表先进生产力、生产方式的创新创业带动就业的先进典型。\n\n（二）严肃工作纪律。任何服务于补贴申报的公职人员不得假公济私、以权谋私、索拿卡要、刁难企业和个人，收受企业和个人财物。申报人应对申报资料的真实性负责。对在申报过程中弄虚作假的申报人，一经核实，取消申报资格，情节严重的纳入诚信黑名单，不再享受长沙市政府各类财政支持。"},{"no":"六","title":"相关解释","text":"（一）“初创企业”类型包括企业、个体工商户和农民专业合作社等。\n\n（二）普通高校是指国家教育行政部门批准或备案的实施高等学历教育为主的高等学校，包括全日制大学、独立学院、职业技术学院、高等专科学校。非全日制研究生享受与全日制研究生同等对待。\n\n（三）各县（市）根据本通知精神，可参照制定相关办法。\n\n（四）其他未尽事宜，由市人力资源社会保障局负责解释。"}],"interpretations":[{"sectionNo":"一","headline":"长沙首次创业满1年，补5000至30000元，按带动就业人数算","who":"在湘江新区及芙蓉、天心、开福、雨花、望城登记注册、注册未满5年的初创企业；正常经营1年以上、吸纳1人及以上就业、缴城镇职工社保6个月以上；申报人为法定代表人且属就业困难人员或返乡入乡农民工，持股不低于30%。","materials":["《长沙市一次性创业补贴申请表》（系统填报后自动生成）","营业执照、申报人身份证","企业股权分配证明资料","返乡创业佐证资料（返乡入乡农民工，由乡镇/街道人社服务站或村社区出具）"],"window":"登记注册5年以内、正常经营1年以上、社保缴满6个月；每季度公示一次拟补贴名单。","where":"湖南省政务服务网「高效办成一件事」→「个人创业『一件事』——创业补贴申领」线上申报。","tip":"申报人不是企业第一任法定代表人的，不纳入补贴范围；已经享受过市财政同一项目补贴的不能重复享受；就业困难人员不用自己提供佐证资料。"},{"sectionNo":"二","headline":"离校2年内高校毕业生创业，补贴提到1万元起、最高3万元","who":"同区域内注册未满5年的初创企业；正常经营1年以上、吸纳1人及以上就业、缴社保3个月以上；申报人为法定代表人且属离校2年内高校毕业生，持股不低于30%。","materials":["《长沙市大学生一次性创业补贴申请表》（系统填报后自动生成）","营业执照、申报人身份证","企业股权分配证明资料","毕业证或学信网学籍证明"],"window":"登记注册5年以内、正常经营1年以上、社保缴满3个月。","where":"湖南省政务服务网「高效办成一件事」→「大学生就业创业落户『一件事』——创业补贴申领」。","tip":"大学生标准比普通标准高：吸纳1人按1万元起，每多1人加1000元，最高3万元；同样要求是第一任法定代表人。"},{"sectionNo":"三","headline":"线上申报创业补贴，每季度公示5个工作日，公示后拨付","who":"离校2年内高校毕业生，或返乡入乡农民工、就业困难人员；须登录湖南省政务服务网，按身份选择对应“一件事”入口填报并上传资料。","materials":[],"window":"每个季度公示一次该季度拟补贴名单，公示期为5个工作日。","where":"湖南省政务服务网“高效办成一件事”，选择“大学生就业创业落户‘一件事’——创业补贴申领”或“个人创业‘一件事’——创业补贴申领”。","tip":"申报资料先由湘江新区民政和社会保障局、各区人力资源和社会保障局审核并实地考察，市级复审后核定吸纳就业人数和补贴金额；公示完毕由区县（市）人社部门拨付至申报人账户。"},{"sectionNo":"四","headline":"企业停业、注销或吊销执照的，终止享受补贴","who":"已申报或正在审核的初创企业；申报审核期间实体处于停业状态，或已注销、吊销营业执照，以及经核实有其他不符合补贴发放条件的。","materials":[],"window":"在申报审核期间核查，出现所列情形即终止享受补贴。","where":"申报审核环节（原文未列具体部门）","tip":"除停业、注销、吊销营业执照外，经核实有其他不符合补贴发放政策相关条件的，同样终止享受补贴。"},{"sectionNo":"五","headline":"申报造假取消资格，情节严重纳入诚信黑名单","who":"申报长沙市一次性创业补贴、大学生一次性创业补贴的申报人；须对申报资料的真实性负责。","materials":[],"window":"申报过程中核查，一经核实即取消申报资格。","where":"湖南湘江新区民政和社会保障局、各区人力资源和社会保障局（负责宣传推荐与工作纪律监督）。","tip":"弄虚作假的取消申报资格，情节严重的纳入诚信黑名单，不再享受长沙市政府各类财政支持；公职人员不得假公济私、索拿卡要。"},{"sectionNo":"六","headline":"初创企业含企业、个体工商户、农民专业合作社","who":"初创企业类型包括企业、个体工商户和农民专业合作社；普通高校指国家教育行政部门批准或备案、实施高等学历教育为主的高等学校，含全日制大学、独立学院、职业技术学院、高等专科学校；非全日制研究生与全日制研究生同等对待。","materials":[],"window":"本通知执行期内适用。","where":"市人力资源社会保障局（负责解释）；各县（市）可参照制定相关办法。","tip":"非全日制研究生享受与全日制研究生同等对待；其他未尽事宜由市人力资源社会保障局负责解释。"}],"sourceUrl":"http://rsj.changsha.gov.cn/xxgk/fdzdgk/zfcg_131322/cggg_131324/202605/t20260525_12390713.html","sourceNote":"2026-10-31 取自长沙市人力资源和社会保障局官网采购公告栏原文页；原文未标注文号，documentNo 留空；适用范围为湘江新区及芙蓉、天心、开福、雨花、望城区。；2026-11-08 核对：页面发布日期 2026-05-25","verified":true,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"cn-business-env-2019-722","title":"优化营商环境条例","level":"national","region":"全国","issuer":"国务院","documentNo":"国务院令第722号","publishedAt":"2019-10-22","effectiveAt":"2020-01-01","expiresAt":null,"status":"active","tags":["营商环境","场地支持"],"audience":["各类市场主体","中小企业"],"summary":"持续深化简政放权、放管结合、优化服务改革，保护市场主体经营自主权，落实减税降费政策，规范涉企收费与执法检查。","sections":[{"no":"第一条","title":"立法目的","text":"为了持续优化营商环境，不断解放和发展社会生产力，加快建设现代化经济体系，推动高质量发展，制定本条例。"},{"no":"第十四条","title":"减税降费","text":"国家持续推进减税降费，及时公布涉企收费目录清单，清理规范涉企收费，减轻市场主体负担。"},{"no":"第五十三条","title":"规范涉企执法","text":"行政执法机关应当依法履行监管职责，规范行政执法行为，避免多头执法、重复检查，减少对市场主体正常生产经营活动的影响。"}],"interpretations":[],"sourceUrl":"https://www.gov.cn/gongbao/content/2019/content_5449647.htm","sourceNote":"2026-11-21 依据中国政府网公布的国务院令第722号文本核对文号、公布日期与施行日期；条款按原文分条摘录。 原文链接由核对脚本定位：标题已在页面命中。 2026-11-21 收录：与官方页面逐句比对，命中 2/3 句（67%），关卡判定「partial」。 有效期依据：原文明示（自2020年1月1日起施行，未设失效期限）","verified":false,"isSample":false,"numberStyle":"clause","bodyVerified":"partial","hunan":false},{"id":"cn-employment-2023-15","title":"财政部 税务总局 人力资源社会保障部 农业农村部关于进一步支持重点群体创业就业有关税收政策的公告","level":"national","region":"全国","issuer":"财政部、税务总局、人力资源社会保障部、农业农村部","documentNo":"财政部 税务总局 人力资源社会保障部 农业农村部公告2023年第15号","publishedAt":"2023-08-02","effectiveAt":"2023-01-01","expiresAt":"2027-12-31","status":"active","tags":["就业补贴","创业补贴","税收优惠"],"audience":["脱贫人口及防止返贫监测对象","登记失业半年以上人员","零就业家庭、享受城市居民最低生活保障家庭劳动年龄内的登记失业人员","毕业年度内高校毕业生"],"summary":"重点群体从事个体经营，3年内按每户每年20000元为限额依次扣减税费，限额标准最高可上浮20%。","sections":[{"no":"一","title":"个体经营扣减限额","text":"自2023年1月1日至2027年12月31日，脱贫人口（含防止返贫监测对象）、持《就业创业证》（注明“自主创业税收政策”或“毕业年度内自主创业税收政策”）或《就业失业登记证》（注明“自主创业税收政策”）的人员，从事个体经营的，自办理个体工商户登记当月起，在3年（36个月）内按每户每年20000元为限额依次扣减其当年实际应缴纳的增值税、城市维护建设税、教育费附加、地方教育附加和个人所得税。限额标准最高可上浮20%，各省、自治区、直辖市人民政府可根据本地区实际情况在此幅度内确定具体限额标准。"},{"no":"二","title":"企业吸纳就业扣减","text":"企业招用脱贫人口、登记失业半年以上且持《就业创业证》或《就业失业登记证》的人员，与其签订1年以上期限劳动合同并依法缴纳社会保险费的，自签订劳动合同并缴纳社会保险当月起，在3年（36个月）内按实际招用人数予以定额依次扣减增值税、城市维护建设税、教育费附加、地方教育附加和企业所得税优惠。定额标准为每人每年6000元，最高可上浮30%。"},{"no":"三","title":"扣减顺序","text":"纳税人按上述标准计算的税收扣减额应在企业当年实际应缴纳的增值税、城市维护建设税、教育费附加、地方教育附加和企业所得税税额中扣减，当年扣减不完的，不得结转下年使用。"}],"interpretations":[{"sectionNo":"一","headline":"重点群体从事个体经营，每户每年20000元限额扣减税费","who":"脱贫人口（含防止返贫监测对象），以及持《就业创业证》（注明“自主创业税收政策”或“毕业年度内自主创业税收政策”）或《就业失业登记证》（注明“自主创业税收政策”）的人员；须从事个体经营并办理个体工商户登记。","materials":["《就业创业证》（注明“自主创业税收政策”或“毕业年度内自主创业税收政策”）","《就业失业登记证》（注明“自主创业税收政策”）"],"window":"2023年1月1日至2027年12月31日；自办理个体工商户登记当月起3年（36个月）内扣减。","where":"在缴纳增值税、城市维护建设税、教育费附加、地方教育附加和个人所得税时依次扣减。","tip":"限额为每户每年20000元，最高可上浮20%，具体限额由各省、自治区、直辖市人民政府在幅度内确定；扣减期限为3年（36个月）。"},{"sectionNo":"二","headline":"企业招用脱贫人口等重点群体，每人每年6000元定额扣减","who":"招用脱贫人口、登记失业半年以上且持《就业创业证》或《就业失业登记证》人员的企业；须与其签订1年以上期限劳动合同并依法缴纳社会保险费。","materials":["《就业创业证》","《就业失业登记证》","1年以上期限劳动合同"],"window":"自签订劳动合同并缴纳社会保险当月起3年（36个月）内，按实际招用人数计算。","where":"在缴纳增值税、城市维护建设税、教育费附加、地方教育附加和企业所得税时依次扣减。","tip":"定额标准为每人每年6000元、最高可上浮30%；须签订1年以上期限劳动合同并依法缴纳社会保险费，按实际招用人数计算。"},{"sectionNo":"三","headline":"税收扣减额当年用完，扣减不完不得结转下年","who":"按上述标准计算税收扣减额的纳税人，包括从事个体经营的重点群体人员和招用重点群体的企业。","materials":[],"window":"按当年度计算，仅限当年实际应缴纳的税额，不得结转下年。","where":"在企业当年实际应缴纳的增值税、城市维护建设税、教育费附加、地方教育附加和企业所得税税额中扣减。","tip":"当年扣减不完的部分不得结转下年使用，未扣完即失效；扣减顺序为增值税、城市维护建设税、教育费附加、地方教育附加、企业所得税。"}],"sourceUrl":"https://www.gov.cn/zhengce/zhengceku/202308/content_6896453.htm","sourceNote":"2026-11-21 依据国家税务总局政策法规库与人力资源社会保障部公开口径核对文号与条款；本轮未附直链。 原文链接由核对脚本定位：标题已在页面命中。 2026-11-21 收录：与官方页面逐句比对，命中 5/5 句（100%），关卡判定「verbatim」。 有效期依据：原文明示（执行至2027年12月31日）","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":false},{"id":"cn-equip-2024-7","title":"国务院关于印发《推动大规模设备更新和消费品以旧换新行动方案》的通知","level":"national","region":"全国","issuer":"国务院","documentNo":"国发〔2024〕7号","publishedAt":"2024-03-07","effectiveAt":null,"expiresAt":null,"status":"active","tags":["数字化转型","财政奖补","场地支持"],"audience":["工业领域重点行业企业","制造业企业","建筑市政交通农业等领域设备使用单位"],"summary":"到2027年工业领域设备投资规模较2023年增长25%以上，推进重点行业设备更新改造，中央预算内投资等资金予以支持。","sections":[{"no":"一","title":"总体目标","text":"到2027年，工业、农业、建筑、交通、教育、文旅、医疗等领域设备投资规模较2023年增长25%以上。"},{"no":"二","title":"推进重点行业设备更新改造","text":"围绕推进新型工业化，以节能降碳、超低排放、安全生产、数字化转型、智能化升级为重要方向，聚焦钢铁、有色、石化、化工、建材、电力、机械、航空、船舶、轻纺、电子等重点行业，大力推动生产设备、用能设备、发输配电设备等更新和技术改造。"},{"no":"三","title":"资金支持","text":"加大财政政策支持力度，加强企业设备更新和技术改造的资金支持，引导金融机构加大对设备更新和技术改造的信贷支持。"}],"interpretations":[{"sectionNo":"二","headline":"钢铁、有色、石化等重点行业设备更新和技术改造获支持","who":"钢铁、有色、石化、化工、建材、电力、机械、航空、船舶、轻纺、电子等重点行业的工业企业；方向为节能降碳、超低排放、安全生产、数字化转型、智能化升级，对象为生产设备、用能设备、发输配电设备等。","materials":[],"window":"本条未列申报期，随重点行业设备更新改造同步推进。","where":"本条未列受理窗口，按行业设备更新改造渠道组织实施。","tip":"本条只列行业与更新方向，未给补贴标准，实际支持需对接后续资金细则。"}],"sourceUrl":"https://www.gov.cn/gongbao/2024/issue_11246/202403/content_6941843.html","sourceNote":"2026-11-21 依据中国政府网政策文件库核对文号与成文日期（2024年3月7日）；条款按原文分条归纳。 原文链接由核对脚本定位：标题已在页面命中。 2026-11-21 收录：与官方页面逐句比对，命中 2/3 句（67%），关卡判定「partial」。 有效期依据：原文未设期限","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"partial","hunan":false},{"id":"cn-guarantee-2019-6","title":"国务院办公厅关于有效发挥政府性融资担保基金作用切实支持小微企业和“三农”发展的指导意见","level":"national","region":"全国","issuer":"国务院办公厅","documentNo":"国办发〔2019〕6号","publishedAt":"2019-02-14","effectiveAt":null,"expiresAt":null,"status":"active","tags":["融资支持","贷款贴息"],"audience":["小微企业","“三农”主体","政府性融资担保机构"],"summary":"政府性融资担保机构聚焦支小支农主业，逐步将平均担保费率降至1%以下，落实风险分担补偿机制。","sections":[{"no":"一","title":"聚焦支小支农主业","text":"政府性融资担保机构要聚焦支小支农主业，重点支持单户担保金额500万元及以下的小微企业和“三农”主体。"},{"no":"二","title":"保本微利运行","text":"政府性融资担保机构要坚持保本微利运行，逐步将平均担保费率降至1%以下。"},{"no":"三","title":"风险分担补偿","text":"落实风险分担补偿机制，国家融资担保基金、省级再担保机构、政府性融资担保机构、银行业金融机构按比例分担风险。"}],"interpretations":[{"sectionNo":"一","headline":"政府性融资担保重点支持单户500万元及以下小微企业和“三农”","who":"单户担保金额500万元及以下的小微企业；“三农”主体。","materials":[],"window":"按担保业务办理，原文未设申报期限","where":"政府性融资担保机构","tip":"聚焦支小支农主业，单户担保金额超过500万元的不在重点支持范围"},{"sectionNo":"二","headline":"政府性融资担保平均费率逐步降至1%以下","who":"通过政府性融资担保机构办理担保业务的小微企业和“三农”主体。","materials":[],"window":"逐步降至1%以下，原文未设完成时限","where":"政府性融资担保机构","tip":"1%是平均担保费率，不是每笔业务的固定费率；机构须保本微利运行"}],"sourceUrl":"https://www.gov.cn/zhengce/zhengceku/2019-02/14/content_5365711.htm","sourceNote":"2026-11-21 依据中国政府网政策文件库核对文号与成文日期（2019年2月14日）；条款按原文分条归纳。 原文链接由核对脚本定位：标题已在页面命中。 2026-11-21 收录：与官方页面逐句比对，命中 2/3 句（67%），关卡判定「partial」。 有效期依据：原文未设期限","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"partial","hunan":false},{"id":"cn-payment-2025-802","title":"保障中小企业款项支付条例","level":"national","region":"全国","issuer":"国务院","documentNo":"国务院令第802号","publishedAt":"2025-03-17","effectiveAt":"2025-06-01","expiresAt":null,"status":"active","tags":["营商环境","融资支持"],"audience":["中小企业","机关、事业单位和大型企业（付款方）"],"summary":"机关、事业单位从中小企业采购货物工程服务应自交付之日起30日内支付，合同约定最长不超过60日；大型企业约定最长不超过60日，逾期应支付逾期利息。","sections":[{"no":"第九条","title":"付款期限","text":"机关、事业单位从中小企业采购货物、工程、服务，应当自货物、工程、服务交付之日起30日内支付款项；合同另有约定的，付款期限最长不得超过60日。大型企业从中小企业采购货物、工程、服务，应当按照行业规范、交易习惯合理约定付款期限并及时支付款项，双方约定的付款期限一般不得超过60日。"},{"no":"第十五条","title":"逾期利息","text":"机关、事业单位和大型企业迟延支付中小企业款项的，应当支付逾期利息。双方对逾期利息的利率有约定的，约定利率不得低于合同订立时1年期贷款市场报价利率；未作约定的，按照每日利率万分之五支付逾期利息。"},{"no":"第十条","title":"不得强制接受商业汇票等","text":"机关、事业单位和大型企业不得强制中小企业接受商业汇票、应收账款电子凭证等非现金支付方式，不得利用非现金支付方式变相延长付款期限。"}],"interpretations":[{"sectionNo":"第九条","headline":"机关事业单位采购，交付后30日内付款，最长60日","who":"与机关、事业单位、大型企业签订货物、工程、服务采购合同的中小企业；机关、事业单位应自交付之日起30日内付款，合同另有约定最长不超过60日；大型企业按行业规范、交易习惯合理约定，一般不超过60日。","materials":[],"window":"自货物、工程、服务交付之日起30日内；合同另有约定的最长60日；大型企业约定一般不超过60日。","where":"机关、事业单位（按财政支付流程付款）；大型企业（按合同约定付款）。","tip":"起算点是交付之日，不是验收或开票日；合同另约可延长，但机关事业单位最长60日。"},{"sectionNo":"第十五条","headline":"逾期付款按日万分之五付息，约定利率不得低于1年期LPR","who":"被机关、事业单位和大型企业迟延支付款项的中小企业；双方对逾期利息利率有约定的，约定利率不得低于合同订立时1年期贷款市场报价利率；未约定的按每日利率万分之五计。","materials":[],"window":"迟延支付期间计息；约定利率以合同订立时的1年期LPR为下限。","where":"向迟延付款的机关、事业单位和大型企业主张；原文未列投诉受理窗口。","tip":"无约定时直接适用每日万分之五；有约定时不得低于合同订立时1年期LPR，约定过低不达下限。"},{"sectionNo":"第十条","headline":"不得强制中小企业接受商业汇票、应收账款电子凭证","who":"向机关、事业单位和大型企业提供货物、工程、服务的中小企业；对方不得强制其接受商业汇票、应收账款电子凭证等非现金支付方式。","materials":[],"window":"合同履行与付款环节全程适用，原文未设期限。","where":"机关、事业单位和大型企业（付款方）；原文未列投诉受理窗口。","tip":"非现金支付不得用于变相延长付款期限；被强制接受时该要求不符合本条规定。"}],"sourceUrl":"https://www.gov.cn/zhengce/zhengceku/202503/content_7015405.htm","sourceNote":"2026-11-21 依据中国政府网公布的国务院令第802号修订文本核对文号、公布日期（2025年3月17日）与施行日期；条款按原文分条摘录。 原文链接由核对脚本定位：标题已在页面命中。 2026-11-21 收录：与官方页面逐句比对，命中 6/7 句（86%），关卡判定「partial」。 有效期依据：原文明示（自2025年6月1日起施行，未设失效期限）","verified":false,"isSample":false,"numberStyle":"clause","bodyVerified":"partial","hunan":false},{"id":"cn-private-2023-31","title":"中共中央 国务院关于促进民营经济发展壮大的意见","level":"national","region":"全国","issuer":"中共中央、国务院","documentNo":"","publishedAt":"2023-07-19","effectiveAt":null,"expiresAt":null,"status":"active","tags":["营商环境","融资支持","场地支持"],"audience":["民营企业","中小微企业","个体工商户"],"summary":"从持续优化民营经济发展环境、加大政策支持力度、强化法治保障等方面提出31条举措，明确破除市场准入壁垒、完善融资支持政策制度。","sections":[{"no":"一","title":"破除市场准入壁垒","text":"持续破除市场准入壁垒，各地区各部门不得以备案、注册、年检、认定、认证、指定等形式设定或者变相设定准入障碍。"},{"no":"二","title":"完善融资支持政策制度","text":"完善民营企业融资支持政策制度，加大对民营企业的信贷投放，支持民营企业通过债券市场融资，发挥政府性融资担保机构作用。"},{"no":"三","title":"完善拖欠账款常态化预防和清理机制","text":"完善拖欠账款常态化预防和清理机制，机关、事业单位和大型企业不得以内部人员变更、履行内部付款流程等为由拒绝或者延迟支付账款。"}],"interpretations":[],"sourceUrl":"https://myjj.ndrc.gov.cn/31file/202412/t20241231_1395387.html","sourceNote":"2026-11-21 依据新华社受权发布的意见全文核对发布日期（2023年7月19日）与主要内容；条款按原文分条归纳。 原文链接由核对脚本定位：标题已在页面命中。 2026-11-21 收录：与官方页面逐句比对，命中 2/3 句（67%），关卡判定「partial」。 有效期依据：原文未设期限","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"partial","hunan":false},{"id":"cn-procurement-2020-46","title":"财政部 工业和信息化部关于印发《政府采购促进中小企业发展管理办法》的通知","level":"national","region":"全国","issuer":"财政部、工业和信息化部","documentNo":"财库〔2020〕46号","publishedAt":"2020-12-18","effectiveAt":"2021-01-01","expiresAt":null,"status":"active","tags":["营商环境","认定资质"],"audience":["符合《中小企业划型标准规定》的中小微企业","小微企业（含联合体、分包供应商）"],"summary":"200万元以下货物服务、400万元以下工程项目原则上面向中小企业；超过部分预留预算总额30%以上，其中小微企业不低于60%；未预留项目给予小微企业6%—10%价格扣除。","sections":[{"no":"第七条","title":"小额项目专门面向中小企业","text":"采购限额标准以上，200万元以下的货物和服务采购项目、400万元以下的工程采购项目，适宜由中小企业提供的，采购人应当专门面向中小企业采购。"},{"no":"第八条","title":"预留份额","text":"超过200万元的货物和服务采购项目、超过400万元的工程采购项目中适宜由中小企业提供的，预留该部分采购项目预算总额的30%以上专门面向中小企业采购，其中预留给小微企业的比例不低于60%。"},{"no":"第九条","title":"价格评审优惠","text":"对于经主管预算单位统筹后未预留份额专门面向中小企业采购的采购项目，以及预留份额项目中的非预留部分采购包，采购人、采购代理机构应当对符合本办法规定的小微企业报价给予6%—10%（工程项目为3%—5%）的扣除，用扣除后的价格参加评审。"},{"no":"第十一条","title":"中小企业声明函","text":"中小企业参加政府采购活动，应当出具本办法规定的《中小企业声明函》，否则不得享受相关中小企业扶持政策。任何单位和个人不得要求供应商提供《中小企业声明函》之外的中小企业身份证明文件。"}],"interpretations":[{"sectionNo":"第七条","headline":"200万元以下货物服务、400万元以下工程专门面向中小企业","who":"中小企业；适用于采购限额标准以上、200万元以下的货物和服务采购项目，以及400万元以下的工程采购项目，且适宜由中小企业提供。","materials":[],"window":"按采购项目执行，原文未列申报期。","where":"由采购人按政府采购程序执行（原文未列受理窗口）","tip":"前提是项目适宜由中小企业提供，且属于采购限额标准以上的小额项目；超过200万元的货物服务和超过400万元的工程不适用本条。"},{"sectionNo":"第八条","headline":"超200万元货物服务、400万元工程，预留30%给中小企业","who":"中小企业，其中小微企业优先；适用于超过200万元的货物和服务采购项目、超过400万元的工程采购项目中适宜由中小企业提供的部分。","materials":[],"window":"按采购项目预算执行，原文未列申报期。","where":"由采购人按政府采购程序执行（原文未列受理窗口）","tip":"预留比例是采购项目预算总额的30%以上，其中预留给小微企业的比例不低于60%；仅限适宜由中小企业提供的部分。"},{"sectionNo":"第九条","headline":"小微企业报价扣除6%—10%（工程3%—5%）后参加评审","who":"符合本办法规定的小微企业；适用于主管预算单位统筹后未预留份额专门面向中小企业采购的项目，以及预留份额项目中的非预留部分采购包。","materials":[],"window":"按采购项目评审环节执行，原文未列申报期。","where":"由采购人、采购代理机构在评审中执行（原文未列受理窗口）","tip":"货物服务按6%—10%、工程按3%—5%扣除后价格参加评审；已预留份额专门面向中小企业的部分不再重复适用。"},{"sectionNo":"第十一条","headline":"参加政府采购须出具《中小企业声明函》，否则不享扶持","who":"参加政府采购活动的中小企业；须出具本办法规定的《中小企业声明函》，才能享受相关中小企业扶持政策。","materials":["《中小企业声明函》"],"window":"随政府采购活动提交，原文未列具体时限。","where":"参加政府采购活动时提交（原文未列受理窗口）","tip":"声明函是享受扶持的唯一身份证明；任何单位和个人不得再要求提供声明函之外的中小企业身份证明文件，不出具则不得享受扶持政策。"}],"sourceUrl":"https://www.gov.cn/gongbao/content/2021/content_5591418.htm","sourceNote":"2026-11-21 取自国务院公报所载原文；文号与条款逐字核对，第七条至第十一条与财政部条法司公布文本一致。 2026-11-21 收录：与官方页面逐句比对，命中 5/5 句（100%），关卡判定「verbatim」。 有效期依据：原文明示（自2021年1月1日起施行，原文未设失效期限）","verified":false,"isSample":false,"numberStyle":"clause","bodyVerified":"verbatim","hunan":false},{"id":"cn-quality-sme-2022-63","title":"工业和信息化部关于印发《优质中小企业梯度培育管理暂行办法》的通知","level":"national","region":"全国","issuer":"工业和信息化部","documentNo":"工信部企业〔2022〕63号","publishedAt":"2022-06-01","effectiveAt":"2022-08-01","expiresAt":"2026-03-31","status":"expired","tags":["认定资质","研发创新"],"audience":["创新型中小企业","专精特新中小企业","专精特新“小巨人”企业"],"summary":"建立创新型中小企业、专精特新中小企业、专精特新“小巨人”企业三层次培育体系；其专精特新相关条款与认定标准已被工信部企业〔2026〕2号替代。","sections":[{"no":"第二条","title":"三层次构成","text":"优质中小企业是指在产品、技术、管理、模式等方面创新能力强、专注细分市场、成长性好的中小企业，由创新型中小企业、专精特新中小企业和专精特新“小巨人”企业三个层次组成。"},{"no":"第三条","title":"参评条件","text":"参评优质中小企业应在中华人民共和国境内工商注册登记、具有独立法人资格，符合《中小企业划型标准规定》，企业未被列入经营异常名录或严重失信主体名单，提供的产品（服务）不属于国家禁止、限制或淘汰类，同时近三年未发生重大安全（含网络安全、数据安全）、质量、环境污染等事故以及偷漏税等违法违规行为。"},{"no":"第五条","title":"管理职责","text":"工业和信息化部负责优质中小企业梯度培育工作的宏观指导、统筹协调和监督检查，推动出台相关支持政策，发布相关评价和认定标准，负责专精特新“小巨人”企业认定工作。"}],"interpretations":[{"sectionNo":"第三条","headline":"参评优质中小企业须境内注册、独立法人、近三年无事故","who":"在中华人民共和国境内工商注册登记、具有独立法人资格的中小企业；须符合《中小企业划型标准规定》；未被列入经营异常名录或严重失信主体名单；提供的产品（服务）不属于国家禁止、限制或淘汰类；近三年未发生重大安全（含网络安全、数据安全）、质量、环境污染等事故以及偷漏税等违法违规行为。","materials":[],"window":"近三年为安全、质量、环境污染事故及偷漏税等违法违规行为的考察期；原文未规定申报起止时间。","where":"原文未指定受理部门或线上申报系统，仅列参评条件。","tip":"被列入经营异常名录或严重失信主体名单即不符合条件；近三年发生重大安全、质量、环境污染事故或偷漏税等违法违规行为的，同样不符合。"}],"sourceUrl":"https://www.miit.gov.cn/threestrategy/dtzx/zhzx/art/2022/art_eff8aa2758204e96a3e08b57e791bb7d.html","sourceNote":"2026-11-21 取自工业和信息化部网站原文；成文日期2022年6月1日。列入本库用于记录被替代关系，状态判失效，不计入现行有效统计口径说明见覆盖矩阵。 2026-11-21 收录：与官方页面逐句比对，命中 3/3 句（100%），关卡判定「verbatim」。 有效期依据：按替代文件推算（工信部企业〔2026〕2号自2026-04-01实施，相关条款同时废止）","verified":false,"isSample":false,"numberStyle":"clause","bodyVerified":"verbatim","hunan":false},{"id":"cn-sme-standard-2011-300","title":"中小企业划型标准规定","level":"national","region":"全国","issuer":"工业和信息化部、国家统计局、国家发展改革委、财政部","documentNo":"工信部联企业〔2011〕300号","publishedAt":"2011-06-18","effectiveAt":"2011-06-18","expiresAt":null,"status":"active","tags":["认定资质","营商环境"],"audience":["工业、建筑业、批发业、零售业、软件和信息技术服务业等16个行业的企业"],"summary":"按行业以从业人员、营业收入、资产总额划分中型、小型、微型企业，是享受中小企业各项扶持政策的基础判定依据。","sections":[{"no":"第四条","title":"工业划型标准","text":"工业。从业人员1000人以下或营业收入40000万元以下的为中小微型企业。其中，从业人员300人及以上，且营业收入2000万元及以上的为中型企业；从业人员20人及以上，且营业收入300万元及以上的为小型企业；从业人员20人以下或营业收入300万元以下的为微型企业。"},{"no":"第五条","title":"建筑业划型标准","text":"建筑业。营业收入80000万元以下或资产总额80000万元以下的为中小微型企业。其中，营业收入6000万元及以上，且资产总额5000万元及以上的为中型企业；营业收入300万元及以上，且资产总额300万元及以上的为小型企业；营业收入300万元以下或资产总额300万元以下的为微型企业。"},{"no":"第七条","title":"划型依据","text":"企业类型的划分以统计部门的统计数据为依据。"}],"interpretations":[{"sectionNo":"第四条","headline":"工业中小微划型：从业1000人以下或营收40000万元以下","who":"工业行业企业；从业人员1000人以下或营业收入40000万元以下为中小微型企业；中型须从业人员300人及以上且营业收入2000万元及以上；小型须20人及以上且营业收入300万元及以上；微型为20人以下或营业收入300万元以下。","materials":[],"window":"无申报期限，按统计部门统计数据认定企业类型。","where":"原文未列明受理部门；划型结果用于各部门执行中小企业政策。","tip":"中型、小型须同时满足人数与营业收入两项下限，任一不满足即按下一档认定。"},{"sectionNo":"第五条","headline":"建筑业划型：营收或资产总额80000万元以下为中小微","who":"建筑业企业；营业收入80000万元以下或资产总额80000万元以下为中小微型企业；中型须营业收入6000万元及以上且资产总额5000万元及以上；小型须营业收入300万元及以上且资产总额300万元及以上；微型为营业收入300万元以下或资产总额300万元以下。","materials":[],"window":"无申报期限，以营业收入与资产总额两项指标认定。","where":"原文未列明受理部门；划型结果用于各部门执行中小企业政策。","tip":"中型、小型须同时满足营业收入与资产总额两项下限；任一低于下限即降一档。"}],"sourceUrl":"https://www.miit.gov.cn/jgsj/qyj/wjfb/art/2011/art_235af1ade45c4865957adeed23f9d949.html","sourceNote":"2026-11-21 依据工业和信息化部网站公布的《中小企业划型标准规定》核对文号与发布日期；条款逐字摘录。 原文链接由核对脚本定位：标题已在页面命中。 2026-11-21 收录：与官方页面逐句比对，命中 9/9 句（100%），关卡判定「verbatim」。 有效期依据：原文明示（自发布之日起执行，未设失效期限）","verified":false,"isSample":false,"numberStyle":"clause","bodyVerified":"verbatim","hunan":false},{"id":"cs-ai-action-2025-13","title":"长沙市人民政府关于印发《长沙市“人工智能+”行动方案》的通知","level":"city","region":"长沙市","issuer":"长沙市人民政府","documentNo":"长政发〔2025〕13号","publishedAt":"2025-12-24","effectiveAt":"2025-12-24","expiresAt":"2030-12-23","status":"active","tags":["数字化转型","研发创新","营商环境"],"audience":["人工智能相关企业","制造业企业","产业园区","高校院所"],"summary":"部署基础底座强基、产业集群赋智、科技创新攻坚、政策保障提质、高端人才引育、应用场景推广六大工程，推动人工智能与长沙“4433”现代化产业体系融合。","sections":[{"no":"（一）","title":"基础底座强基工程","text":"支持建设市级算力调度平台，围绕“东数西算”国家战略布局，融入全国一体化算力网。鼓励智算中心应用液冷、分布式储能、余热回收等技术进行绿色低碳改造，探索利用差别化电价措施，引导算力设施向绿色化、高效化发展。加强长沙国家数据标注基地建设，打造智能标注公共服务平台。发展基于数字对象架构的数据确权解析和安全流通、区块链追溯防篡改等数据互联网技术。支持建设城市可信数据空间，促进数据要素安全合规、有序高效流动与融合应用。深耕垂类大模型布局，推进服务大模型训练的行业特色高质量数据集建设。深化数据要素市场化配置改革，探索开展行政事业单位公共数据资产全过程管理，积极开展公共数据授权运营，鼓励市场经营主体参与公共数据资源开发利用。完善数据交易撮合机制和管理规范，鼓励数据进场交易，规范数据场外交易。（市数据局牵头，市委网信办、市发展改革委、市工业和信息化局、市文旅广电局、市卫生健康委按职责分工负责）"},{"no":"（二）","title":"产业集群赋智工程","text":"支持工程机械、自主安全计算等集群企业联合开发基于人工智能的三维建模、参数化设计等物理世界仿真建模工具，提升工业软件底层技术研发效率，加快研发高精度智能传感技术与多模态融合算法。持续建设领航级智能工厂，推动数字孪生、AI仿真技术、智能数控机床等人工智能技术在制造业研发设计、中试验证、生产制造、营销服务、运营管理等关键环节的深度融合应用。深入实施“智赋万企”行动，推广一批人工智能赋能新型工业化典型应用场景。推动人工智能与工业互联网深度融合、双向赋能，促进产业链上下游企业数据融通，重塑生产流程和方式。积极推进人工智能领域头部企业在长布局研发中心或子公司。（市工业和信息化局牵头，市发展改革委、市科技局按职责分工负责）"},{"no":"（三）","title":"科技创新攻坚工程","text":"持续推动长沙国家新一代人工智能创新发展试验区建设，聚焦AI领域引育一批具备“四个全球”功能的研发机构、三类500强企业研发总部。支持建设“人工智能+”领域重点实验室、技术创新中心、制造业创新中心等科研创新平台，开展具身智能、跨媒体智能等前沿研究。持续推进“大院、大所、大企业”战略合作，联合开展一批新技术攻关。鼓励支持在人工智能领域实施“揭榜挂帅”重大科技项目和科技重大专项。布局一批人工智能领域的中试平台、概念验证中心等，推进科技成果转化。（市科技局牵头，市发展改革委、市工业和信息化局按职责分工负责）"},{"no":"（四）","title":"政策保障提质工程","text":"出台长沙市推动“人工智能+”行动相关政策，支持人工智能领域尤其是纳入国家、省级扶持范围的项目、企业、场景、平台等发展。建立重点企业、示范场景、重点平台等清单制度，实施动态更新管理。整合现有基金资源，设立百亿规模的市级人工智能产业政府投资基金群，带动社会资本着力投早、投小、投长期、投硬科技。鼓励银行、保险等金融机构研发面向中小企业场景创新的金融产品，为中小企业推动场景项目建设提供资金支持。鼓励市场化投资机构关注场景创新企业，为开展场景创新的科技企业提供融资支持。（市工业和信息化局牵头，市金融管理局、市发展改革委、市科技局、市财政局按职责分工负责）"},{"no":"（六）","title":"应用场景推广工程","text":"深入推动长沙国家人工智能创新应用先导区建设，布局建设人工智能应用场景服务平台，通过整合行业资源、高质量数据和行业场景需求，吸引汇聚优秀创新团队来长创业。鼓励政府部门、龙头企业、行业协会等加大人工智能场景开放。组织开展人工智能领域场景招商活动、供需对接会等，定期发布应用场景供需清单，为企业、高校、科研院所等搭建合作交流平台。（市工业和信息化局牵头，市教育局、市发展改革委、市科技局、市住房城乡建设局、市交通运输局、市商务局、市卫生健康委、市数据局按职责分工负责）"}],"interpretations":[{"sectionNo":"（一）","headline":"支持建市级算力调度平台，智算中心可探索差别化电价","who":"在长沙建设运营智算中心、从事数据标注与数据服务、垂类大模型及数据交易的市场主体；鼓励市场经营主体参与公共数据资源开发利用。","materials":[],"window":"方案实施期内持续推进，原文未设申报截止时间。","where":"市数据局牵头，市委网信办、市发展改革委、市工业和信息化局、市文旅广电局、市卫生健康委按职责分工负责。","tip":"差别化电价仅为探索方向，不是已确定的电价优惠；数据交易须进场或按规范场外交易。"},{"sectionNo":"（二）","headline":"支持集群企业联合开发AI仿真建模工具，建领航级智能工厂","who":"工程机械、自主安全计算等集群企业，以及开展智能化改造的制造业企业；鼓励人工智能领域头部企业在长布局研发中心或子公司。","materials":[],"window":"方案实施期内持续推进，原文未设申报截止时间。","where":"市工业和信息化局牵头，市发展改革委、市科技局按职责分工负责。","tip":"本条为方向性支持，具体支持方式与金额原文未明确。"},{"sectionNo":"（三）","headline":"支持建AI重点实验室、技术创新中心，实施揭榜挂帅项目","who":"在长高校、科研院所、企业；可申报人工智能+领域重点实验室、技术创新中心、制造业创新中心等平台，参与揭榜挂帅重大科技项目和科技重大专项。","materials":[],"window":"方案实施期内持续推进，原文未设申报截止时间。","where":"市科技局牵头，市发展改革委、市工业和信息化局按职责分工负责。","tip":"聚焦具身智能、跨媒体智能等前沿方向，平台与项目均须经相应评审程序。"},{"sectionNo":"（四）","headline":"设立百亿规模市级AI产业政府投资基金群，投早投小","who":"纳入国家、省级扶持范围的人工智能项目、企业、场景、平台；开展场景创新的中小企业与科技企业；市场化投资机构。","materials":[],"window":"方案实施期内持续推进；基金与金融产品按市场化方式运作，原文未设申报期限。","where":"市工业和信息化局牵头，市金融管理局、市发展改革委、市科技局、市财政局按职责分工负责。","tip":"基金群规模为百亿级，投向为投早、投小、投长期、投硬科技；清单实行动态更新管理。"},{"sectionNo":"（六）","headline":"布局AI应用场景服务平台，定期发布场景供需清单","who":"来长创业的创新团队、企业、高校、科研院所；可对接政府部门、龙头企业、行业协会开放的人工智能场景。","materials":[],"window":"方案实施期内定期发布应用场景供需清单，原文未设申报截止时间。","where":"市工业和信息化局牵头，市教育局、市发展改革委、市科技局、市住房城乡建设局、市交通运输局、市商务局、市卫生健康委、市数据局按职责分工负责。","tip":"场景获取靠供需对接会与清单发布，不是先到先得。"}],"sourceUrl":"https://www.changsha.gov.cn/zfxxgk/zfwjk/srmzf/202512/t20251224_12134151.html","sourceNote":"2026-11-21 取自长沙市人民政府门户「政策文件—市人民政府文件」原文页；页面标注文号长政发〔2025〕13号、公布日期2025-12-24、信息时效期2030-12-23。条文为页面正文逐字摘录。 2026-11-21 收录：与官方页面逐句比对，命中 31/31 句（100%），关卡判定「verbatim」。 有效期依据：原文明示“自公布之日起施行，有效期5年”；页面登记信息时效期2030-12-23，推算一致。","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"cs-ai-industry-2025-16","title":"长沙市人民政府办公室关于印发《长沙市加快人工智能产业高质量发展若干政策》的通知","level":"city","region":"长沙市","issuer":"长沙市人民政府办公室","documentNo":"长政办发〔2025〕16号","publishedAt":"2025-12-26","effectiveAt":"2025-12-26","expiresAt":"2028-12-25","status":"active","tags":["研发创新","财政奖补","数字化转型"],"audience":["人工智能企业","智能硬件制造企业","垂类大模型开发企业","创新平台运营方"],"summary":"智能硬件新产品按销售增量的10%给予最高200万元奖励；垂类大模型按不超过年度模型购买费用的30%给予最高100万元奖励；创新支撑平台按年度运营费用30%每年最高100万元。","sections":[{"no":"一","title":"支持创新产品供给","text":"打造智能产品生态，支持智能电脑、智能可穿戴设备、智能机器人等领域智能硬件产品研发、制造和推广，对符合条件的新产品，按照销售增量的10%，给予最高200万元奖励。对拥有自主知识产权、技术先进且已实现首次商业化应用的人工智能软件，按其销售情况给予最高200万元奖励。（责任单位：市工业和信息化局）"},{"no":"二","title":"支持垂类大模型研发","text":"支持在先进制造、文化科技、交通出行、医疗健康、安全生产、应急管理等领域开展行业垂类大模型研发应用。鼓励企业依托经国家网信办备案的生成式人工智能模型进行二次开发应用，对开发形成且通过国家网信办登记、具备自主知识产权、实施效果显著的垂类大模型或工业智能体，按不超过年度模型购买费用的30%，给予最高100万元奖励。（责任单位：市工业和信息化局）"},{"no":"三","title":"支持创新平台建设","text":"鼓励企业、高校、科研机构、园区等面向人工智能领域建设数据归集、算法汇聚、算力开放、场景训练、适配测评、智能标注公共服务等创新支撑平台，对符合条件的国家级、省级创新支撑平台，按不超过平台年度运营费用的30%，每年给予最高100万元运营奖励，每个平台累计奖励不超过200万元。支持建设人工智能开源平台和开发预训练模型、模型智能体等，对符合条件的共享开源项目给予最高100万元奖励。（责任单位：市工业和信息化局）"},{"no":"六","title":"发展数据标注产业","text":"落实国家数据标注基地建设任务，支持打造视频文创、工业制造、交通运输、医疗健康、地理信息、教育教学等特色数据标注产业集聚区，对培育数据标注产业成效突出的区县（市）人民政府或园区管委会，给予最高100万元奖励。支持建设智能标注公共服务平台，面向数据标注企业提供共性技术支持、算力资源、人才培训、业务推广等服务，依据相关规定对数据标注行业赋能作用显著的平台建设运营方，给予最高100万元奖励。支持数据标注企业做大做强，根据数据标注供给价值等情况给予其奖励。（责任单位：市数据局）"},{"no":"九","title":"强化金融政策保障","text":"充分发挥市级政府投资基金撬动作用，聚焦人工智能基础及应用软件、智能芯片等关键软硬件，计算机视觉、机器学习、具身智能、人机交互等关键技术，以及人工智能重点应用场景解决方案等领域。鼓励银行机构为人工智能关键软硬件、关键技术和重点企业等，配置专项信贷额度，加大人工智能金融支持力度。支持符合条件的人工智能相关项目申报超长期特别国债、地方政府专项债券资金。（责任单位：市发展改革委、市财政局、市金融管理局）"}],"interpretations":[{"sectionNo":"一","headline":"智能硬件按销售增量10%奖励，最高200万元","who":"在长沙市开展智能电脑、智能可穿戴设备、智能机器人等智能硬件产品研发、制造和推广，且符合条件的新产品企业；拥有自主知识产权、技术先进且已实现首次商业化应用的人工智能软件企业。","materials":[],"window":"按销售增量核算奖励；软件按销售情况奖励，原文未列申报起止时间。","where":"市工业和信息化局（责任单位）。","tip":"硬件按销售增量的10%计奖、封顶200万元；软件按销售情况奖励，同样封顶200万元。"},{"sectionNo":"二","headline":"垂类大模型按模型购买费30%奖励，最高100万元","who":"在先进制造、文化科技、交通出行、医疗健康、安全生产、应急管理等领域开展行业垂类大模型研发应用，依托经国家网信办备案的生成式人工智能模型二次开发，形成的垂类大模型或工业智能体通过国家网信办登记、具备自主知识产权、实施效果显著的企业。","materials":[],"window":"按不超过年度模型购买费用的30%计算；原文未明确申报时间。","where":"市工业和信息化局（责任单位）。","tip":"须通过国家网信办登记并具备自主知识产权；奖励按年度模型购买费用30%计、封顶100万元。"},{"sectionNo":"三","headline":"创新支撑平台按年运营费30%奖励，每年最高100万元","who":"面向人工智能领域建设数据归集、算法汇聚、算力开放、场景训练、适配测评、智能标注公共服务等创新支撑平台的企业、高校、科研机构、园区，且须为符合条件的国家级、省级创新支撑平台；建设人工智能开源平台和开发预训练模型、模型智能体的主体。","materials":[],"window":"按年度运营费用计算，每年给予一次运营奖励，每个平台累计不超过200万元。","where":"市工业和信息化局（责任单位）。","tip":"每年最高100万元、每平台累计封顶200万元；共享开源项目另有最高100万元奖励。"},{"sectionNo":"六","headline":"数据标注集聚区成效突出的区县或园区，最高奖100万元","who":"培育数据标注产业成效突出的区县（市）人民政府或园区管委会；建设智能标注公共服务平台并对数据标注行业赋能作用显著的平台建设运营方；做大做强的数据标注企业。","materials":[],"window":"按年度成效认定；原文未明确申报时间。","where":"市数据局（责任单位）。","tip":"平台奖励最高100万元；企业奖励按数据标注供给价值等情况确定，未设固定比例。"},{"sectionNo":"九","headline":"AI项目可申报超长期特别国债、地方政府专项债","who":"长沙市人工智能基础及应用软件、智能芯片等关键软硬件，计算机视觉、机器学习、具身智能、人机交互等关键技术以及重点应用场景解决方案领域的企业；符合条件的人工智能相关项目。","materials":[],"window":"按超长期特别国债、地方政府专项债券年度申报安排执行；原文未列具体时间。","where":"市发展改革委、市财政局、市金融管理局（责任单位）。","tip":"银行专项信贷额度属鼓励性安排、不是直接补贴；债券资金须项目符合条件才可申报。"}],"sourceUrl":"https://www.changsha.gov.cn/zfxxgk/zfwjk/szfbgt/202512/t20251226_12135846.html","sourceNote":"2026-11-21 取自长沙市人民政府门户「政务公开—政策文件—市政府办公室文件」原文页；页面标注文号长政办发〔2025〕16号、公布日期2025-12-26、信息时效期2028-12-25，与本条一致。条文为页面正文逐字摘录，未作改写。 2026-11-21 收录：与官方页面逐句比对，命中 16/16 句（100%），关卡判定「verbatim」。 有效期依据：原文明示“自公布之日起施行，有效期3年”；页面登记信息时效期2028-12-25，推算一致。","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"cs-consumption-new-2026-14","title":"长沙市商务局 长沙市财政局关于印发《长沙市消费新业态新模式新场景试点项目专项资金管理办法（试行）》的通知","level":"city","region":"长沙市","issuer":"长沙市商务局、长沙市财政局","documentNo":"长商务发〔2026〕14号","publishedAt":"2026-03-23","effectiveAt":"2026-03-23","expiresAt":"2027-12-31","status":"active","tags":["专项资金","财政奖补"],"audience":["消费新业态项目实施企业","首发经济运营主体","IP联名企业","商圈运营方"],"summary":"中央财政安排资金支持首发经济服务体系、多元化服务消费场景、优质消费资源与知名IP联名三个方向，投资类项目按有效投资额和项目规模给予补助或奖励，实行进度拨付加验收结算。","sections":[{"no":"第六条（一）","title":"支持健全首发经济服务体系","text":"支持打造一批首发中心、首发经济集聚区，在重点商圈商街、创意园区、文化场所等打造多层次的新品发布平台载体，集聚一批传播、传媒、广告、策划等专业服务机构。支持具有引领性的国内外品牌开设高能级首店、旗舰店、概念店，并推动首店向总店、总部提升发展。支持时尚服饰、消费电子、美妆、潮玩、家居、汽车、智能终端、运动潮品以及服务消费等领域具有创新性、引领性的产品和服务举办首发首秀首展活动。支持有关展会开设首发专区、专场，集中展示新产品新服务新技术。"},{"no":"第六条（二）","title":"支持创新多元化服务消费场景","text":"支持业态创新、模式创新，推动人工智能、元宇宙等数字技术在文娱、旅游、健康、体育等领域的深化应用，打造商旅文体健融合的消费新场景；推动服务消费集聚区建设，支持重点商圈、特色商业街区、文旅集聚区、会展场馆、传统购物型商超、废旧工业厂区向多元消费场景升级，拓展增加文化时尚、健康体育、艺术展览、主题社交、休闲娱乐等服务消费功能，推动重点赛事活动及演出“进商圈、进街区、进景区”；发展夜间经济，打造夜间文化和旅游消费集聚区；服务“一老一小”，打造银发金街、童趣乐园等；支持培育汽车后市场服务、旅居服务、演出服务、冰雪经济、体育赛事、旅游列车等服务消费新增长点领域，发展艺术展览、沉浸体验、数字艺术、房车露营等消费场景；促进家政等领域新业态新模式发展；建设外贸优品展销中心、购物集聚区等。"},{"no":"第六条（三）","title":"支持优质消费资源与知名IP跨界联名","text":"推动全球知名IP、国潮IP、历史文化IP、本地特色IP联动开发系列周边产品。支持围绕本地特色文化，联动国潮动漫影视知识产权（IP）及文博场馆、非遗机构、历史文化名城等传统资源，推出一批影响范围广、社交属性强、创意新颖的综合性消费场景。支持老字号企业、新消费品牌企业依托本地优质消费资源，开设新店、旗舰店，开发推出“老牌新品”、“国货潮品”。"},{"no":"第十七条","title":"","text":"专项资金结合项目投资建设进度对投资类项目实行“进度拨付+验收结算”的模式进行资金拨付，由市商务局会同市财政局提出项目资金分配方案，并报市政府批示同意后，分批次由市商务局将资金预拨至项目实施单位，项目验收合格前拨付补助资金比例不得高于90%。一次性奖励类项目待项目评审通过，项目公示等程序完成后，一次性拨付奖励资金。"}],"interpretations":[{"sectionNo":"第六条（一）","headline":"首店首秀首展可获支持，涵盖首发中心与首发专区","who":"在重点商圈商街、创意园区、文化场所打造首发中心、首发经济集聚区的运营主体；开设高能级首店、旗舰店、概念店的国内外品牌；举办首发首秀首展的时尚服饰、消费电子、美妆、潮玩、家居、汽车、智能终端、运动潮品及服务消费领域企业；开设首发专区、专场的展会主办方。","materials":[],"window":"原文未设申报期或执行期限，属专项资金支持方向。","where":"市商务局、市财政局（专项资金管理，具体申报窗口原文未列明）","tip":"支持对象须具创新性、引领性，并落在重点商圈商街、创意园区、文化场所等载体；原文未列具体奖补金额。"},{"sectionNo":"第六条（二）","headline":"商圈街区景区可建多元消费场景，夜间经济与一老一小在列","who":"推动人工智能、元宇宙等数字技术在文娱、旅游、健康、体育领域应用的企业；重点商圈、特色商业街区、文旅集聚区、会展场馆、传统购物型商超、废旧工业厂区的运营主体；开展夜间经济、银发金街、童趣乐园、汽车后市场、旅居、演出、冰雪、体育赛事、旅游列车、家政新业态及外贸优品展销中心建设的市场主体。","materials":[],"window":"原文未设申报期或执行期限，属专项资金支持方向。","where":"市商务局、市财政局（专项资金管理，具体申报窗口原文未列明）","tip":"支持以业态创新、模式创新为前提，须落到具体场景载体；原文未列具体奖补金额。"},{"sectionNo":"第六条（三）","headline":"知名IP与本地文化联名开发周边，老字号可开新店","who":"推动全球知名IP、国潮IP、历史文化IP、本地特色IP联动开发周边产品的市场主体；围绕本地特色文化、联动国潮动漫影视知识产权（IP）及文博场馆、非遗机构、历史文化名城推出综合性消费场景的主体；开设新店、旗舰店并开发“老牌新品”“国货潮品”的老字号企业、新消费品牌企业。","materials":[],"window":"原文未设申报期或执行期限，属专项资金支持方向。","where":"市商务局、市财政局（专项资金管理，具体申报窗口原文未列明）","tip":"支持重点为影响范围广、社交属性强、创意新颖的综合性消费场景；原文未列具体奖补金额。"},{"sectionNo":"第十七条","headline":"投资类项目验收前最多拨90%，奖励类评审后一次性拨付","who":"获得长沙市消费新业态新模式新场景试点专项资金支持的项目实施单位：投资类项目按进度拨付、验收结算；一次性奖励类项目经评审、公示后拨付。","materials":[],"window":"投资类项目按投资建设进度分批次预拨，验收合格前累计拨付不得高于90%；奖励类项目评审通过并公示后一次性拨付。","where":"市商务局会同市财政局提出项目资金分配方案，报市政府批示同意后拨付","tip":"投资类项目验收合格前拨付比例不得高于90%，余款验收结算；奖励类项目须先通过评审和公示程序。"}],"sourceUrl":"https://www.changsha.gov.cn/zfxxgk/zfwjk/gdwxtwj/202603/t20260323_12342294.html","sourceNote":"2026-11-21 取自长沙市人民政府门户「政策文件—各单位系统文件」原文页；页面标注文号长商务发〔2026〕14号、公布日期2026-03-23、信息时效期2027-12-31。条文为页面正文逐字摘录。 2026-11-21 收录：与官方页面逐句比对，命中 16/16 句（100%），关卡判定「verbatim」。 有效期依据：原文明示“自公布之日起施行，有效期至2027年12月31日”；页面登记信息时效期一致。","verified":false,"isSample":false,"numberStyle":"clause","bodyVerified":"verbatim","hunan":true},{"id":"cs-crossborder-fund-2026-11","title":"关于印发《长沙市开放型经济发展专项资金（跨境电商部分）管理办法》的通知","level":"city","region":"长沙市","issuer":"长沙市商务局、长沙市财政局","documentNo":"长商务发〔2026〕11号","publishedAt":"2026-03-04","effectiveAt":"2026-03-04","expiresAt":"2029-03-03","status":"active","tags":["外贸外资","专项资金"],"audience":["跨境电商企业","跨境电商行业协会","综试区园区","支持机构"],"summary":"设市级跨境电商专项资金，三项硬标准：卖家企业按综合评分奖励、单个企业年度不超过700万元；行业协会、专业机构报备举办行业峰会、对接交流活动，按实际支出不超过50%支持、单个主体年度不超过30万元；获批湖南省跨境电商专项职业能力考核站的机构，年组织考试（评）不少于500人、通过率不低于80%，按500元/人给予单站每年不超过50万元支持。年度资金不足时按比例折算。自2026年3月4日起施行，有效期三年。","sections":[{"no":"一","title":"第一章 总则","text":"为加强长沙开放型经济跨境电商发展专项资金规范管理，加快推进长沙跨境电商高质量发展，深入推进中国（长沙）跨境电子商务综合试验区建设，根据国务院《关于同意在北京等22个城市设立跨境电子商务综合实验区的批复》（国函〔2018〕93号）、《湖南省开放型经济促进条例》、《湖南省人民政府办公厅关于印发<湖南省关于促进外贸稳定增长的若干政策措施>的通知》（湘政办发〔2025〕20号）和长沙市财政专项资金管理相关规定，制定本办法。"},{"no":"二","title":"","text":"本办法所称开放型经济发展专项资金（跨境电商部分），是指由市级财政预算安排，用于支持跨境电子商务发展和长沙综试区建设的专项资金。在资金安排上，可与中央、省级相关专项资金统筹使用。鼓励湖南湘江新区、各区县（市）、园区设立跨境电商扶持资金，推动全市跨境电商高质量发展。"},{"no":"三","title":"","text":"本办法支持对象是对长沙跨境电商高质量发展作出贡献的跨境电商企业、行业协会、其他经济组织以及经政府批准的支持机构。"},{"no":"四","title":"","text":"本办法各项奖励政策的实施遵循依法依规、公平公正公开的原则，坚持突出重点、示范引导、注重效益。"},{"no":"五","title":"","text":"市商务局，湖南湘江新区商务和市场监管局，各区县（市）、园区商务部门按职责分工共同做好开放型经济发展专项资金（跨境电商部分）管理使用和监督工作。（一）市商务局主要负责编制专项资金年度预算和年度使用计划，负责业务指导和项目管理，组织项目申报、审核、评审，拟定资金分配方案，公示相关信息，监督管理专项资金的使用，组织项目绩效评价。（二）湖南湘江新区商务和市场监管局，各区县（市）、园区商务部门负责组织本辖区所属企业、单位的项目申报、审核、监督检查等，按要求开展绩效评价工作，确保专项资金的使用安全高效。"},{"no":"六","title":"第二章 适用范围及标准","text":"支持跨境电商经营主体做大做强对开展跨境电商进出口业务的卖家企业，结合其业务成长质量、合规与信用水平、推动就业等体现发展质量与社会贡献的指标，开展综合评估，根据评分结果给予奖励，单个企业年度支持不超过700万元。"},{"no":"七","title":"","text":"支持跨境电商行业交流氛围营造对行业协会、专业机构等主体，向长沙市商务局报备举办具有重要行业影响力的行业峰会、对接交流等相关活动的，按活动实际支出费用给予不超过50%的支持，单个申报主体年度该项总支持不超过30万元。"},{"no":"八","title":"","text":"支持跨境电商人才培育体系建设对获批湖南省跨境电商专项职业能力考核站的机构，年度组织参加职业技能鉴定考试（评）人员不少于500人，通过率不低于80%的，根据组织参加职业技能鉴定考试（评）的实际人数，按500元/人的标准给予单个考核站点每年不超过50万元的支持。"},{"no":"九","title":"第三章 申请条件和申报材料","text":"专项资金的申报主体应当符合以下条件:（一）对长沙跨境电商高质量发展作出贡献；（二）遵守国家法律法规；依法登记注册纳税、守法诚信经营；未被列入全国信用信息共享平台（湖南长沙）失信“黑名单”；（三）其他按规定应满足的条件；（四）单个企业同一项目不得重复申请其他中央、省级、市级专项资金支持。（五）其他申报条件和申报材料以年度申报通知为准。"},{"no":"十","title":"第四章 专项资金申报和审批程序","text":"对于落实到具体项目的政策性支持事项，主要采取项目法分配。项目法申报和审批程序为：（一）项目申报。市商务局每年根据市政府跨境电商相关重点工作安排制定申报通知，明确支持范围、申报程序以及申报材料等内容，申报单位根据申报通知要求及时上交申报材料。（二）项目初审。湖南湘江新区、各国家级园区、区县（市）商务部门对申报项目进行初审，形成初审意见，并报送市商务局。（三）部门复审。市商务局对湖南湘江新区、各国家级园区、区县（市）提交的项目进行复审。（四）政府审定。市商务局拟定资金分配方案，报请市政府批准。（五）结果公示。市商务局将经市政府批准的资金分配方案在资金申报平台、长沙市商务局门户网上公示。公示期满后，由市商务局出具公示情况说明。（六）集中拨付。结果公示无异议后，根据市政府最终审定后的资金分配方案和公示结果，将资金拨付至项目所在地，由湖南湘江新区、各国家级园区、各区县（市）按程序拨付至项目单位。（七）绩效评价。市商务局，湖南湘江新区、各国家级园区、各区县（市）商务部门定期对专项资金进行绩效评价，加强绩效评价结果运用。"},{"no":"十一","title":"","text":"如计算出的全部支持金额超过财政资金安排的年度专项资金总额，则按相应比例予以折算。"},{"no":"十二","title":"第五章 专项资金监督与管理","text":"市商务局以及湖南湘江新区商务和市场监管局，各区县（市）、园区商务部门应加强对专项资金的管理，定期对资金使用情况进行监督检查、绩效评价，确保专项资金发挥效益。"},{"no":"十三","title":"","text":"获得专项资金的单位应加强内部管理，专项资金应专款专用，妥善保管申请和审核材料，建立完整的档案。"},{"no":"十四","title":"","text":"各部门、项目单位和个人应主动接受有关部门的监督检查。对拒不接受监督检查的单位，检查部门应当责令其改正。拒不改正的，应暂停或停止拨付资金；已经拨付资金的，责令其停止使用，并收回资金；同时取消其今后三年的申报资格。"},{"no":"十五","title":"","text":"项目实施单位企业对项目申报材料的真实性负责。对于截留、挪用、骗取专项资金等违法行为，按《财政违法行为处罚处分条例》（国务院令第427号）的相关规定进行处理。涉嫌犯罪的，移送有权机关处理。"},{"no":"十六","title":"第六章 附则","text":"本办法由市商务局负责解释。"},{"no":"十七","title":"","text":"本办法自2026年3月4日起施行，有效期三年。原《长沙市开放型经济发展专项资金（跨境电商部分）管理办法》（长商务发〔2024〕21号）同时废止。"}],"interpretations":[{"sectionNo":"三","headline":"跨境电商企业、行业协会、支持机构可申报专项资金","who":"对长沙跨境电商高质量发展作出贡献的跨境电商企业、行业协会、其他经济组织，以及经政府批准的支持机构。","materials":[],"window":"本办法自2026年3月4日起施行、有效期三年，期内按年度申报通知申报","where":"市商务局；湖南湘江新区商务和市场监管局及各区县（市）、园区商务部门","tip":"支持对象须对长沙跨境电商高质量发展有实际贡献，与跨境电商无关的经营主体不在范围内"},{"sectionNo":"六","headline":"跨境电商卖家企业综合评估奖励，单家年度最高700万元","who":"开展跨境电商进出口业务的卖家企业；按业务成长质量、合规与信用水平、推动就业等指标综合评估，依评分结果给予奖励。","materials":[],"window":"按年度评估兑现，单个企业年度支持不超过700万元","where":"市商务局（组织项目申报、审核、评审并拟定资金分配方案）","tip":"奖励按综合评分结果确定，不是按出口额同比例补贴；同一项目不得重复申请其他中央、省级、市级专项资金"},{"sectionNo":"七","headline":"报备办行业峰会、对接活动，按实际支出补50%，年最高30万元","who":"行业协会、专业机构等主体；活动须向长沙市商务局报备，且具有重要行业影响力（行业峰会、对接交流等）。","materials":[],"window":"活动前向长沙市商务局报备；单个申报主体年度该项总支持不超过30万元","where":"长沙市商务局（活动报备）","tip":"只补活动实际支出费用的50%以内，同一主体年度该项累计不超过30万元；未报备的活动不在支持范围"},{"sectionNo":"八","headline":"考核站年鉴定500人、通过率80%，按500元/人补","who":"获批湖南省跨境电商专项职业能力考核站的机构；年度组织参加职业技能鉴定考试（评）人员不少于500人，且通过率不低于80%。","materials":[],"window":"按年度组织参加鉴定考试（评）的实际人数计算，单个考核站点每年不超过50万元","where":"湖南省跨境电商专项职业能力考核站（认定机构）","tip":"年组织鉴定不足500人或通过率低于80%即不符合支持条件；补贴按实际参考人数×500元计，年度封顶50万元"},{"sectionNo":"九","headline":"申报须守法诚信、未入失信黑名单，同一项目不得重复申请","who":"对长沙跨境电商高质量发展有贡献、依法登记注册纳税、守法诚信经营，且未被列入全国信用信息共享平台（湖南长沙）失信“黑名单”的申报主体；单个企业同一项目不得重复申请其他中央、省级、市级专项资金。","materials":[],"window":"其他申报条件和申报材料以年度申报通知为准","where":"湖南湘江新区、各国家级园区、区县（市）商务部门初审，市商务局复审","tip":"失信“黑名单”是一票否决项；同一项目已获其他中央、省级、市级专项资金的不得再申请"},{"sectionNo":"十","headline":"项目法分配：区县初审、市局复审、市政府审定后公示拨付","who":"按市商务局年度申报通知提交材料的申报单位；项目经湖南湘江新区、各国家级园区、区县（市）商务部门初审后报市商务局复审。","materials":[],"window":"市商务局每年制定申报通知明确支持范围、程序和材料；公示期满无异议后集中拨付","where":"市商务局；湖南湘江新区、各国家级园区、区县（市）商务部门（初审）","tip":"公示在资金申报平台和市商务局门户网进行，公示无异议才拨付；资金拨至项目所在地后由区县按程序转拨项目单位"},{"sectionNo":"十一","headline":"支持总额超年度资金总额时，按比例折算","who":"获得跨境电商专项资金支持的项目单位；适用于计算出的全部支持金额超过财政资金安排的年度专项资金总额的情形。","materials":[],"window":"年度专项资金总额确定后统一折算","where":"原文未单列受理部门（折算方案由市商务局拟定）","tip":"折算后实际到手可能低于按标准算出的金额，申报时不要按满额做资金预算"},{"sectionNo":"十三","headline":"获资金单位须专款专用、妥善保管材料并建立完整档案","who":"获得跨境电商专项资金的单位。","materials":[],"window":"资金拨付后至项目申请、审核材料归档保管期满","where":"本单位（接受市商务局及区县商务部门监督检查）","tip":"申请和审核材料要建档留存，检查时须能提供；专款专用，不得挪作他用"},{"sectionNo":"十四","headline":"拒不接受检查且不改正的，收回资金并取消三年申报资格","who":"各部门、项目单位和个人（专项资金申报与使用主体），应主动接受有关部门监督检查。","materials":[],"window":"检查发现问题后责令改正；拒不改正即暂停或停止拨付","where":"检查部门（市商务局及区县、园区商务部门）","tip":"已拨付资金会被收回，并取消今后三年的申报资格"},{"sectionNo":"十五","headline":"申报材料真实性由企业负责，骗取资金依法追责","who":"项目实施单位企业（项目申报材料真实性责任主体）。","materials":[],"window":"项目申报及资金使用全过程","where":"市商务局；涉嫌犯罪的移送有权机关","tip":"截留、挪用、骗取专项资金按《财政违法行为处罚处分条例》处理，涉嫌犯罪移送有权机关"}],"sourceUrl":"https://www.changsha.gov.cn/zfxxgk/zfwjk/gdwxtwj/202603/t20260306_12329963.html","derivedFrom":"official","sourceNote":"2026-11-21 取自长沙市人民政府门户「政策文件—各单位系统文件」原文页；页面标注文号长商务发〔2026〕11号、公布日期2026-03-04、信息时效期2029-03-03。条文为页面正文逐字摘录；具体奖补标准以年度申报通知为准。 2026-11-21 收录：与官方页面逐句比对，命中 5/5 句（100%），关卡判定「verbatim」。 有效期依据：原文明示“自2026年3月4日起施行，有效期三年”；页面登记信息时效期2029-03-03，一致。 2026-11-24 收录：与官方页面逐句比对，命中 42/42 句（100%），关卡判定「verbatim」。 有效期依据：原文未明示","verified":false,"isSample":false,"numberStyle":"clause","bodyVerified":"verbatim","hunan":true},{"id":"cs-csx-bus-ic-2025","title":"长沙县交通运输局 长沙县财政局关于印发《长沙县公交 IC 卡票价优惠补贴实施细则》的通知","level":"district","region":"长沙市·长沙县","issuer":"长沙县交通运输局、长沙县财政局","documentNo":"长县交发〔2025〕30号","publishedAt":"2025-12-16","effectiveAt":"2025-12-16","expiresAt":"2030-12-15","status":"active","tags":["财政奖补","专项资金"],"audience":["长沙县人民政府许可的公交企业","承担 IC 卡刷卡的公交运营单位"],"summary":"长沙县公交 IC 卡票价优惠补贴的完整标准：县属公交实行 IC 卡（含虚拟卡）打折优惠，与学生五折、成人七折同步，由县财政对票价优惠部分补贴——成人刷卡一次补贴票价的 30%，学生刷卡一次补贴票价的 50%，65 周岁以上老年人（刷老年爱心卡）、14 周岁以下儿童（刷儿童卡）免费乘车部分按票价的 100% 补贴。补贴按季度依据公交大数据刷卡数据审核、公示后发放，细则自 2025 年 12 月 16 日施行，有效期 5 年。","sections":[{"no":"一","title":"总则","text":"本细则适用于长沙县人民政府许可的公交企业及长沙县交通运输局批复的公交线路和运营车辆，公交车辆应当实行“一车一机（车载POS机）”"},{"no":"二","title":"补贴范围及标准","text":"公交卡包含普通卡、学生卡、老年卡、爱心卡四项实体卡种；虚拟卡包含湘行一卡通二维码、支付宝、和包支付三项刷卡方式。如有新增其他刷卡方式，以上级文件为准将其纳入补贴范围。"},{"no":"三","title":"补贴范围及标准","text":"县属公交实行IC卡（含虚拟卡）打折优惠（与长沙市内同步，学生五折，成人七折），由县财政对票价优惠部分予以补贴，成人刷卡一次补贴票价的30%，学生刷卡一次补贴票价的50%，县属公交为老年人群（65周岁以上含65周岁，刷老年爱心卡）、14周岁以下儿童（刷儿童卡）提供免费公交服务，由县财政予以补贴，补贴额度为票价的100%。"},{"no":"四","title":"审核与拨付","text":"对于长沙县公交线路及车辆的异常刷卡数据由长沙公交大数据单位初步判断认定并提供至县交通运输局，由县交通运输局核实刷卡人员信息、刷卡行为及目的，核实属于正常出行刷卡行为的刷卡数据纳入补贴范围，核实为恶意刷卡套取补贴行为将由当事人及所属单位承担相应的法律责任。"},{"no":"五","title":"审核与拨付","text":"县交通运输局负责补贴审核发放工作，长沙公交大数据单位每月向县交通运输局提供IC卡（普通卡、学生卡、老年卡、爱心卡、虚拟卡等）刷卡数据，县交通运输局按季度根据长沙公交大数据单位提供刷卡数据依本办法规定进行审核，并将审核结果在县人民政府门户网站或县级媒体上进行公示，公示无异议后按流程发放补贴。"},{"no":"六","title":"审核与拨付","text":"县交通运输局负责组织长沙县公交卡票价优惠补贴项目的申报、审核、公示验收、监督，编制年度卡票价优惠补贴预算，按照程序发放补贴资金，并对项目实施情况，目标实现程度、资金使用效益进行绩效评价。"},{"no":"七","title":"监督与管理","text":"长沙公交大数据单位需严格按照相关程序和规定对车载POS机进行发放和安装，负责车载POS机的维护和换装，并实时监督车载机刷卡情况。负责升级平台系统，定期维护数据库，避免出现数据丢失和数据重复的现象，不允许向公交企业发放备用POS机。"},{"no":"八","title":"监督与管理","text":"公交企业应当安排专人管理车载POS机，不得擅自调整车载机绑定关系、对POS机进行物理移动和修改相关设置及参数信息，不允许留存备用POS机。"},{"no":"九","title":"监督与管理","text":"相关部门应自觉接受审计、监察等部门的依法监督。"},{"no":"十","title":"监督与管理","text":"严肃责任追究，依据相关法律、法规对违反规定的行为做出处理，涉嫌犯罪的，依法移交司法机关处理。"},{"no":"十一","title":"附则","text":"自2025年1月1日至本细则施行之日内的公交1c卡票价优惠补贴可参照本细则执行。"},{"no":"十二","title":"附则","text":"本细则由县交通运输局负责解释。"},{"no":"十三","title":"附则","text":"本细则自2025年12月16日之日起施行，有效期5年。"}],"interpretations":[{"sectionNo":"一","headline":"长沙县许可公交企业及批复线路车辆适用，须一车一机","who":"长沙县人民政府许可的公交企业，以及长沙县交通运输局批复的公交线路和运营车辆；公交车辆须实行“一车一机（车载POS机）”。","materials":[],"window":"本细则施行期内适用","where":"长沙县人民政府（许可）、长沙县交通运输局（线路批复）","tip":"未实行一车一机的车辆不在补贴范围；线路须经县交通运输局批复"},{"sectionNo":"二","headline":"补贴覆盖四类实体卡及湘行一卡通等三项虚拟卡","who":"持普通卡、学生卡、老年卡、爱心卡的乘客，以及使用湘行一卡通二维码、支付宝、和包支付刷卡乘车的乘客；新增其他刷卡方式以上级文件为准纳入补贴范围。","materials":[],"window":"原文未设申报期，随卡种和刷卡方式确定","where":"原文未列明受理部门（按卡种和支付渠道确定）","tip":"新增刷卡方式要等上级文件明确才纳入补贴，不在清单内的方式暂不补贴"},{"sectionNo":"三","headline":"县属公交学生刷卡补票价50%、成人30%，老幼免费全补","who":"长沙县县属公交企业（补贴申领方）；乘客侧：学生卡五折、成人七折（与长沙市内同步），65周岁以上（含65周岁）老年人刷老年爱心卡、14周岁以下儿童刷儿童卡免费乘车。","materials":[],"window":"按刷卡次数逐笔计算，随季度审核发放","where":"县财政（对票价优惠部分补贴）","tip":"成人补票价的30%、学生补50%，补贴给公交企业而非乘客折扣；老年卡、儿童卡补贴额度为票价的100%"},{"sectionNo":"四","headline":"异常刷卡由大数据单位初判、县交通运输局核实，恶意套取追责","who":"长沙县公交线路及车辆的运营企业；异常刷卡数据的当事人及所属单位承担相应法律责任。","materials":[],"window":"原文未单列申报期；异常刷卡数据经初判后由县交通运输局核实","where":"长沙县交通运输局（核实刷卡人员信息、刷卡行为及目的）；长沙公交大数据单位（初判认定）","tip":"只有核实为正常出行刷卡的数据才纳入补贴；恶意刷卡套取补贴由当事人及所属单位担责"},{"sectionNo":"八","headline":"公交企业须专人管POS机，不得留存备用机、不得改参数","who":"长沙县公交企业（补贴申领主体）；须安排专人管理车载POS机。","materials":[],"window":"补贴期内持续适用","where":"公交企业（车载POS机日常管理）","tip":"擅自调整绑定关系、物理移动POS机、修改设置参数或留存备用机都属违规，异常刷卡数据不予补贴并追责"}],"sourceUrl":"http://www.csx.gov.cn/zwgk/zfxxgkml/fdzdgknr/fgwj/gfxwj/gdwxtwj/202512/P020251216514063759684.pdf","derivedFrom":"ocr","sourceNote":"正文取自附件：长沙县政府门户「政策文件—各单位系统文件」原文页 /zwgk/zfxxgkml/fdzdgknr/fgwj/gfxwj/gdwxtwj/202512/t20251216_12126978.html 所挂 PDF（扫描版，无文字层）。2026-11-24 用 Windows.Media.Ocr 逐页识别原件后按条重切全文 13 条，补贴比例（30%、50%、100%）、卡种、有效期已对照原件页面图像逐字复核。 2026-11-24 收录：原件为扫描件（无文字层），条文系 OCR 转录后按条重切，机器无法独立比对；金额与比例已对原件页面图像逐字复核。 有效期依据：第十三条：本细则自2025年12月16日起施行，有效期5年","verified":false,"isSample":false,"numberStyle":"clause","bodyVerified":"unverifiable","hunan":true},{"id":"cs-csx-bus-subsidy-2025","title":"长沙县交通运输局 长沙县财政局关于印发《长沙县城乡公交运营补贴实施细则》的通知","level":"district","region":"长沙市·长沙县","issuer":"长沙县交通运输局、长沙县财政局","documentNo":"长县交发〔2025〕29号","publishedAt":"2025-12-16","effectiveAt":"2025-12-16","expiresAt":"2030-12-15","status":"active","tags":["财政奖补","专项资金"],"audience":["经长沙县交通运输局许可的城乡公交企业","承担通镇通村公交线路的运营单位"],"summary":"长沙县城乡公交运营补贴按「成本规制」核算，补偿低票价造成的政策性亏损：成本端允许计提管理费用不超过 1 至 8 项运营成本之和的 5%，车辆管理费按营运车辆折旧费的 14% 计取，安全生产投入按不低于上年度实际营业收入 1.5% 提取；拨付端按各运营主体上年度经第三方审定的亏损金额 25% 季度预拨，第三方审定结果未出具时暂按上年度核定亏损额的 80% 预拨，次年清算「多退少补」。补贴总额实行年度管控并逐年下降，细则自 2025 年 12 月 16 日施行，有效期 5 年。","sections":[{"no":"一","title":"总则","text":"为贯彻落实公交优先发展战略，促进城乡公交一体化发展，规范我县城乡公交补贴资金的使用和管理，确保我县农村客运体系稳定、健康、可持续发展，根据《国务院关于城市优先发展公共交通的指导意见》（国发〔2012〕64号），交通运输部、公安部、财政部、自然资源部、农业农村部、文化和旅游部、国家乡村振兴局、国家邮政局、中华全国供销合作总社发布《关于推动农村客运高质量发展的指导意见》（交运发〔2021〕73号），《关于落实优先发展战略进一步推动全省城市公共交通高质量发展的指导意见》（湘政办发〔2022〕63号）等文件精神，结合我县实际，制定本细则。"},{"no":"二","title":"总则","text":"坚持公交公益属性，按照“政府主导、市场运作、行业监管\"原则，结合国家节能减排、保护环境、安全生产相关要求，逐步建立以成本规制为核心的城乡公交运营模式，构建社会可承受、财政可承担、企业可承载、发展可持续的政府补贴城乡公交服务新机制，努力为广大群众提供优质高效的公交服务。"},{"no":"三","title":"总则","text":"本细则适用补贴对象为：经县交通运输局许可，获得我县城乡公共交通客运运营权，运营线路为县域内的通镇、通村公交线路的公交企业。"},{"no":"四","title":"总则","text":"城乡公交补贴资金是指用于弥补城乡公交低票价运营等带来的政策性亏损，在实施年度公交企业成本和收入核算以及运营服务考核的基础上，由县财政按年度对公交企业予以补贴的专项资金。"},{"no":"五","title":"企业成本","text":"公交企业成本由营运成本、管理费用、税费和其他成本等项目构成，具体如下：（一）营运成本包括人力成本、能耗成本、车辆折旧费、车辆维修费、车辆轮胎费、车辆保险费、车载设备购置及服务费、站场费用、安全生产投入等，按年度据实核算。1.人力成本指与公交运营业务直接相关人员的薪酬，包含驾驶员、车队长、调度员、充电工、夜保员的工资、福利、绩效、社保、公和金等，上述人员配比情况须报县交通运输局核准后执行，薪酬水平标准不高于同一年度县内城市公交同类从业人员薪酬水平。2.能耗成本指用于公交营运车辆的燃油、燃气、电等动力消耗的费用。3.车辆折旧费指公交营运车辆的购置价格（含税、含上牌费用）分8年用平均年限法折旧的费用。4.车辆修理费指用于公交营运车辆保养维修的费用，包含材料费、工时费等（生产安全事故造成的维修费除外）。5.车辆轮胎费指公交营运车辆投入营运后用于轮胎更换所支出的费用（公交营运车辆每十万公里强制更换新轮胎）。6.车辆保险费指用于公交营运车辆的投保费用，包含交强险、承运人险和商业险（公交企业向县交通运输局备案并获得批准后，按车型统一标准投保）。7.车载设备购置及服务费指公交营运车辆使用车载卡终端、定位及监控设备等产生的购置费（或租赁使用费）、服务费及通讯费。8.站场费用是指公交企业经县交通运输局批准将公交营运车辆停放在自有或租用的停保场内，需要向第三方支付的场地租赁费、房屋租赁费、物业费、洗车费等。9·安全生产投入是指公交企业依据《安全生产法》和《企业安全生产费用提取和使用管理办法》等规定按不低于上年度实际营业收入1.5%提取、设立的安全生产专项资金，用于安全宣教、安全设备购置、职业病防治等方面的安全生产投入。（二）管理费用包含委托运营单位发生的城乡公交企业管理、后勤人员的薪酬，日常管理的办公、通讯、交通、会务、伙食、收钞、点钞等各项开支和公交企业发生的车辆管理费。1.管理费用年度据实核算，上述1至8项运营成本（不包含安全生产投入）之和的5%为委托运营单位发生的管理费用上限2.车辆管理费每年度按公司城乡公交营运车辆折旧费的14%计取。三）税费根据国家、地方税法及相关规定需缴纳的各项税费按实计算（不包含车辆购置税）。（四）其他成本一线从业人员工装采购费用和体检费用作为企业成本，纳入城乡公交营运补贴核算。2.公交企业在实际运营过程中发生的与公交营运直接相关的其他成本和费用，报县人民政府同意后计入。"},{"no":"六","title":"企业成本","text":"下列支出不计入成本，由公交企业自行承担：1.与城乡公交营运无关的费用。2.公交企业经营管理不善所造成的损失。3.公交企业因发生安全生产责任事故所发生的支出。4.对外捐赠（赞助）、滞纳金、违约金、罚款以及计提的准备金等。5.其他不予认可的支出。"},{"no":"七","title":"企业成本","text":"成本核算须遵循《企业会计准则》及交通运输行业成本核算规范，并接受第三方审计。"},{"no":"八","title":"企业成本","text":"经县交通运输局委托的第三方专业机构对成本异常项有现场核查权，公交企业和委托运营单位拒不配合则核减该项成本。"},{"no":"九","title":"企业收入","text":"公交企业收入包含营运收入（包括现金投币收入和电子支付收入）、其他业务净收入和各级补助资金等。在补贴核算时，按公交企业当年度实际收入发生额进行核定。（一）公交企业营运收入指公交企业的公交票款收入，包括现金投币收入和电子支付收入。（二）其他业务净收入指公交企业除公交票款收入以外，利用公共交通资源（如车辆、站场、车身广告收入等）经营所产生的利润，利润为负时，由企业自行负担。（三）各级补助资金包含公交行业成品油价格补助、新能源公交车运营补助资金及其他补助资金等。"},{"no":"十","title":"企业收入","text":"县交通运输局每两年组织开展城乡公交客流量调查工作。通过统计各城乡公交线路现金支付人数及IC卡支付人数，测算IC卡支付人数比值作为核定企业收入的比对依据。调查结论两年有效。企业年度收入核算以公交企业年度申报收入与客流量调查测算收入两者的高值为准。"},{"no":"十一","title":"补贴核算","text":"建立年度管控机制，通过管控年度补贴总额、制定运营成本上限标准、管控运营里程等方式保障财政资源的可持续性。（一）实行年度补贴总额管控，县交通运输局结合上年度补贴规模、经济发展、行业政策等因素，发布下年度补贴管控目标，确保城乡公交补贴总额逐年下降。（二）实行公交企业运营成本管控，通过科学测算制定分项成本上限标准，实行“两年动态调整\"机制。年度财务审计时，严格遵循“就低不就高\"原则：当实际运营成本高于上限标准时，按上限标准核定成本；低于上限标准时，按实际发生额核定成本。（三）实行公交线路运营里程管控。1.按照“计划管控、据实核算\"原则，对超出计划的运营里程不纳入补贴核算范围，若未完成计划运营里程则按照实际里程核算补贴，按完成比例调控补贴总额。2.城乡公交年度营运总里程核算以第三方年度审计里程为依据，以县交通运输局结合实际校验核定为准。在运营过程中，县交通运输局暂以各委托运营单位平台系统数据作为参考，对运营里程数据进行过程管控。"},{"no":"十二","title":"补贴核算","text":"补贴分配实施报备审核机制。当实际亏损总额大于或等于亏损补贴计划上限时，补贴总额取计划上限值；当实际亏损总额小于亏损补贴计划上限时，补贴总额取实际值。"},{"no":"十三","title":"运营服务考核","text":"县交通运输局按照《长沙县公共客运服务质量考评办法》及《长沙县公共汽车服务质量考评计分细则》（以下分别简称“《办法》及《细则》”）对公交企业开展运营服务考核，计算年度服务质量扣款额。"},{"no":"十四","title":"运营服务考核","text":"服务质量扣款用于激励公交运营降本增效，由公交企业制定激励方案，报县交通运输局审核同意后实施。"},{"no":"十五","title":"职能分工","text":"县交通运输局、县财政局、公交企业等部门和单位按照职能分工，相互配合，共同做好补贴资金的管理工作。（一）公交企业和委托运营单位义务1·公交企业和委托运营单位应对城乡公交运营成本进行严格管理，建立健全本单位内控制度，对人力成本、能耗成本、车辆维修费、车辆保险费等营运成本应制定统一采购标准，以及科学的支付管理程序；公交企业应加强对委托营运单位城乡公交运营线路的管理以及成本的控制。2.公交企业应每月对委托营运单位管理的城乡公交线路运营的成本、收入情况进行检查，对人力成本、能耗成本、车辆修理费、车辆轮胎费、车辆运营数据以及营运收入进行核实，对所有基础数据实行存档备查制，并将核实情况形成验收表格按月向县交通运输局报送，对报送情况的真实性、完整性、合法性负责。3.公交企业应根据上年度城乡公交实际补贴金额，结合审批线路调整、车辆购置和设施建设等情况，向县交通运输局申请下年度财政预算。4.公交企业和委托运营单位应主动接受纪检监察、财政、审计、交通等监督部门及经委托的第三方专业机构的监督检查，配合做好成本、收入的复核工作。5.委托营运单位应在完善好财务核算的基础上，进一步建立清晰的管理台账、报表，根据《中华人民共和国会计法》及本办法，设立城乡公交营运成本、收入科目，并按城乡公交营运线路进行财务核算。委托营运单位因同时承担城市公交和城乡公交业务而发生的成本项目无法直接分开核算时，则按该成本项目对应的城市公交与城乡公交营运里程数比例核算。（二）县交通运输局负责编制年度公交补贴预算，负责初审公交企业年度成本、收入；实施公交运营服务考核；委托第三方专业机构对公交企业运营补贴初审结果进行复审，相关情况报县人民政府审批；负责审核公交企业各级财政补贴申报与绩效管理；规范补贴资金的申请和拨付程序。（三）县财政局负责将城乡公交补贴纳入预算管理并落实。对城乡公交补贴的使用实施监督；年度内资金实行总量控制，不足部分跨年度滚动安排。（四）其他部门根据县城乡公交一体化项目的需要，按各自法定职责进行监督与管理。"},{"no":"十六","title":"工作程序","text":"编制城乡公交运营计划与补贴预算（一）公交企业于每年7月底前编制下一年度城乡公交补贴预算，报县交通运输局审核。（二）县交通运输局于每年9月底前审核并编制下一年度城乡公交补贴预算，报县财政局审定。（三）公交企业在每年12月份编制下一年度城乡公交运营计划，报县交通运输局备案审核；县交通运输局结合公交企业上年度亏损补贴额度、企业申报下一年度运营计划，发布确定下一年度城乡公交运营里程计划上限和亏损补贴计划上限，亏损补贴总额力争实现逐年下降。"},{"no":"十七","title":"工作程序","text":"申报与审核补贴资金（一）公交企业于当年3月31日前提交上年度的城乡公交补贴申报资料，申报材料包括申请报告、年度运营里程报告、财务结算报告、收入情况说明、支出情况说明、营运报表等。（二）县交通运输局收到企业提交的申报材料后，完成申报材料的初审工作。（三）县交通运输局委托第三方专业机构完成对初审结果的复审工作，并出具复审结果。（四）县交通运输局将复审结果按程序报县人民政府审定批准后，在县人民政府门户网站或县级媒体上进行公示，公示无异议后，按程序拨付清算资金。"},{"no":"十八","title":"工作程序","text":"为保证城乡公交企业正常运营，采取季度预拨和年度清算拨付方式进行。每年第一、第二、第三季度末分别按各运营主体上年度经第三方审定的亏损金额25%为依据进行季度预拨。若当年度第三方审定结果尚未出具，暂按上年度核定亏损额的80%作为预拨基准。在次年审计完成结果认定后，以县交通运输局报政府审定的年度补贴金额为基准，先行扣减当年已预拨的财政补贴资金，严格执行“多退少补\"清算流程。"},{"no":"十九","title":"保障措施","text":"加强资金管理。城乡公交运营补贴资金由县财政局、县交通运输局负责监督使用。县交通运输局应当组织对补贴资金的管理使用情况、目标实现程度、资金使用效益等进行绩效评价。县财政局和县交通运输局要加强对绩效评价结果的应用，将绩效评价结果作为今后专项资金预算安排的重要依据，并视情况提请县人民政府对该专项资金予以暂停、调整、减少或撤销。"},{"no":"二十","title":"保障措施","text":"加强监督考核。县交通运输局要加强对公交企业和各委托运营单位的运营状况进行监督，对不按照规定进行运营或无法核实运营情况的，不予发放补贴；经营者通过弄虚作假骗取补贴资金的，一经查实，追回当年度已拨付的违规补贴资金，并取消下年度补助资格。同时，严格按照《办法》及《细则》要求，及时完成运营服务考核工作，将考核结果与财政补助资金分配挂钩，应扣必扣，规范发放。"},{"no":"二十一","title":"保障措施","text":"加强督查检查。县交通运输局要加强对补贴资金拨付和使用情况的督查、检查，并配合纪检监察、巡察、审计等部门的监督和管理。在各级监督检查和审计中，如发现公交企业有违法违规行为应缓拨或停拨补贴资金。相关工作人员应主动接受社会和公民的监督，不得违反本细则的规定。"},{"no":"二十二","title":"附则","text":"自2025年1月1日至本细则施行之日内的城乡公交运营补贴可参照本细则执行。"},{"no":"二十三","title":"附则","text":"本细则由县交通运输局负责解释。"},{"no":"二十四","title":"附则","text":"本细则自2025年12月16日起施行，有效期5年。"}],"interpretations":[{"sectionNo":"三","headline":"经许可运营县域通镇通村线路的公交企业可获补贴","who":"经县交通运输局许可、获得我县城乡公共交通客运运营权，且运营线路为县域内通镇、通村公交线路的公交企业。","materials":[],"window":"无固定申报期，补贴按年度核算","where":"县交通运输局","tip":"未取得县交通运输局许可，或线路不在县域通镇、通村范围的，不属补贴对象。"},{"sectionNo":"五","headline":"成本按营运、管理、税费、其他四类据实核算","who":"经许可运营县域通镇、通村公交线路的公交企业及其委托运营单位；人力成本涉及人员配比须报县交通运输局核准。","materials":[],"window":"按年度据实核算；车辆折旧按8年平均年限法；管理费用上限为1至8项运营成本之和的5%；车辆管理费按折旧费14%计取。","where":"县交通运输局","tip":"安全生产投入按不低于上年度实际营业收入1.5%提取；人员薪酬不高于同一年度县内城市公交同类从业人员水平。"},{"sectionNo":"六","headline":"五类支出不计入成本，由公交企业自行承担","who":"申报城乡公交运营补贴的公交企业","materials":[],"window":"年度成本核算时","where":"县交通运输局","tip":"安全生产责任事故支出、罚款、违约金、捐赠赞助等均由企业自行承担。"},{"sectionNo":"七","headline":"成本核算须遵循企业会计准则并接受第三方审计","who":"申报补贴的公交企业及委托运营单位","materials":[],"window":"年度成本核算及审计期间","where":"县交通运输局委托的第三方审计机构","tip":"核算不符合准则或拒绝审计的，相关成本存在被核减风险。"},{"sectionNo":"八","headline":"拒不配合第三方成本现场核查的，核减该项成本","who":"公交企业和委托运营单位","materials":[],"window":"成本核查期间","where":"县交通运输局委托的第三方专业机构","tip":"第三方机构对成本异常项有现场核查权，拒不配合即核减该项成本。"},{"sectionNo":"九","headline":"补贴核算按营运收入、其他业务净收入和补助资金核定","who":"申报城乡公交运营补贴的公交企业","materials":[],"window":"按当年度实际收入发生额核定","where":"县交通运输局","tip":"其他业务利润为负时由企业自行负担，不冲减核定收入。"},{"sectionNo":"十","headline":"收入按企业申报与客流量测算两者高值核定","who":"县内运营通镇、通村公交线路的公交企业","materials":[],"window":"每两年开展一次客流量调查，调查结论两年有效","where":"县交通运输局","tip":"年度收入以申报收入与客流量调查测算收入的高值为准。"},{"sectionNo":"十一","headline":"成本按上限标准就低核定，超计划里程不纳入补贴","who":"县域内通镇、通村公交线路的公交企业","materials":[],"window":"年度管控；分项成本上限标准实行两年动态调整","where":"县交通运输局","tip":"实际成本高于上限按上限核定，低于上限按实际发生额核定；超计划运营里程不纳入补贴核算。"},{"sectionNo":"十二","headline":"实际亏损达补贴计划上限的，按上限值补贴","who":"纳入年度亏损补贴计划的公交企业","materials":[],"window":"年度补贴清算时","where":"县交通运输局、县财政局","tip":"实际亏损小于计划上限的按实际值补贴，不补足到上限。"},{"sectionNo":"十三","headline":"按服务质量考评办法考核并计算年度扣款额","who":"本县城乡公交企业","materials":[],"window":"年度运营服务考核","where":"县交通运输局","tip":"考核依据《长沙县公共客运服务质量考评办法》及计分细则。"},{"sectionNo":"十四","headline":"服务质量扣款由企业制定激励方案报审后使用","who":"公交企业","materials":["激励方案"],"window":"年度考核扣款后","where":"县交通运输局","tip":"激励方案须报县交通运输局审核同意后实施。"},{"sectionNo":"十五","headline":"企业须按月报送成本收入核实表并申请下年度预算","who":"公交企业及委托运营单位；同时承担城市公交和城乡公交业务的，成本按营运里程数比例核算。","materials":["验收表格","下年度财政预算申请"],"window":"每月报送核实情况；按上年度实际补贴金额申请下年度财政预算","where":"县交通运输局；县财政局","tip":"对报送情况的真实性、完整性、合法性负责；成本无法分开核算的按两类公交营运里程数比例核算。"},{"sectionNo":"十六","headline":"企业7月底前报下年度补贴预算，12月报运营计划","who":"公交企业","materials":["下一年度城乡公交补贴预算","下一年度城乡公交运营计划"],"window":"每年7月底前报预算；县交通运输局9月底前审核报财政局审定；每年12月报运营计划","where":"县交通运输局、县财政局","tip":"运营里程计划上限和亏损补贴计划上限由县交通运输局发布确定。"},{"sectionNo":"十七","headline":"企业3月31日前提交上年度补贴申报资料","who":"公交企业","materials":["申请报告","年度运营里程报告","财务结算报告","收入情况说明","支出情况说明","营运报表"],"window":"当年3月31日前提交上年度资料；复审结果报县政府审定后公示","where":"县交通运输局；县人民政府门户网站或县级媒体","tip":"公示无异议后按程序拨付清算资金。"},{"sectionNo":"十八","headline":"按上年度审定亏损额25%季度预拨，次年清算","who":"公交企业","materials":[],"window":"第一、二、三季度末各按25%预拨；次年审计完成后清算","where":"县交通运输局、县财政局","tip":"审定结果未出具时暂按上年度核定亏损额80%预拨；清算多退少补，先行扣减已预拨资金。"},{"sectionNo":"二十","headline":"弄虚作假骗取补贴的追回资金并取消下年度资格","who":"公交企业和委托运营单位","materials":[],"window":"年度考核及补贴发放期间","where":"县交通运输局","tip":"不按规定运营或无法核实运营情况的不予发放补贴；考核结果与资金分配挂钩、应扣必扣。"}],"sourceUrl":"http://www.csx.gov.cn/zwgk/zfxxgkml/fdzdgknr/fgwj/gfxwj/gdwxtwj/202512/P020251216493631037492.pdf","derivedFrom":"ocr","sourceNote":"正文取自长沙县政府门户「政策文件—各单位系统文件」原文页所挂 PDF（/202512/P020251216493631037492.pdf，扫描版，无文字层）。2026-11-24 用 Windows.Media.Ocr 逐页识别原件后按条重切全文 24 条，比例（5%、14%、1.5%、25%、80%）已对照原件页面图像逐字复核。 2026-11-24 收录：原件为扫描件（无文字层），条文系 OCR 转录后按条重切，机器无法独立比对；金额与比例已对原件页面图像逐字复核。 有效期依据：第二十四条：本细则自2025年12月16日起施行，有效期5年","verified":false,"isSample":false,"numberStyle":"clause","bodyVerified":"unverifiable","hunan":true},{"id":"cs-csx-film-drama-2026","title":"关于印发《长沙县推动影视（微短剧）产业高质量发展若干措施（试行）》的通知","level":"district","region":"长沙市·长沙县","issuer":"长沙县文化旅游广电体育局、长沙县新闻出版局（县版权局）、长沙县财政局","documentNo":"长县文旅发〔2026〕4号","publishedAt":"2026-03-12","effectiveAt":"2026-03-20","expiresAt":"2028-03-19","status":"active","tags":["财政奖补","场地支持"],"audience":["县内影视（微短剧）企业","影视基地、园区运营主体","文化类直播企业"],"summary":"县内企业拍摄制作的精品微短剧在央视、一线卫视或头部网络视听平台播出且效果达标的，每部最高奖励10万元，入选国家级、省级创作计划的再奖最高10万元；剧组在县内完成全剧集拍摄的每部给3000元取景补贴，成效显著再追加最高15万元；新建或改造影视基地、园区最高奖励200万元，打造数字影棚最高奖励100万元。","sections":[{"no":"一1","title":"支持精品内容创作，赋能标杆作品打造","text":"1. 支持精品内容创作，赋能标杆作品打造。鼓励县内企业拍摄制作精品微短剧，对登陆央视、一线卫视播出，或在头部网络视听平台播出且播出效果达到一定标准的，经审核认定，给予每部最高10万元奖励。对成功入选国家级、省级微短剧创作计划的，经审核认定，给予每部最高10万元奖励。若以上作品重点聚焦长沙县历史文化底蕴、主导产业发展、文旅融合成果和典型人物事迹等核心主题，对提升县域知名度和美誉度有显著促进作用，在对应奖励基础上追加50%奖励额度。"},{"no":"一2","title":"鼓励县域取景拍摄，助推品牌形象传播","text":"2. 鼓励县域取景拍摄，助推品牌形象传播。鼓励微短剧剧组在县内完成全剧集拍摄，作品在相关网络视听平台播出后，经审核符合申报条件的，给予每部3000元基础取景补贴。经认定对长沙县文旅宣传、主导产业品牌塑造、县域形象提升等方面有显著成效的，结合传播效果综合评定，每部追加最高15万元奖励。"},{"no":"一3","title":"基地园区协拍补助，夯实产业服务基础","text":"3. 基地园区协拍补助，夯实产业服务基础。对县内承接优质影视拍摄项目达到一定规模、协拍服务规范且综合成效突出的影视基地、园区，经综合评定，择优给予符合申报条件的主体最高30万元奖励。"},{"no":"一4","title":"支持影视载体发展，打造特色产业集群","text":"4. 支持影视载体发展，打造特色产业集群。鼓励影视产业基地、园区等载体集聚发展，培育形成主题鲜明、业态完善、要素集聚、辐射力强的影视文化特色产业集群。支持在县内投资新建或改造升级影视基地、园区，经综合评定，对符合申报条件的主体给予最高200万元奖励。支持企业在县内打造数字影棚，经综合评定，对符合申报条件的主体给予最高100万元奖励。"}],"interpretations":[{"sectionNo":"一1","headline":"微短剧登央视或头部平台，每部最高奖10万，县主题再加50%","who":"长沙县内企业拍摄制作的精品微短剧；作品须登陆央视、一线卫视播出，或在头部网络视听平台播出且播出效果达到一定标准，或成功入选国家级、省级微短剧创作计划。","materials":[],"window":"无固定申报期，以作品播出、入选创作计划并经审核认定为条件。","where":"原文未写明受理部门，经审核认定办理。","tip":"作品重点聚焦长沙县历史文化底蕴、主导产业发展、文旅融合成果和典型人物事迹等主题、对提升县域知名度有显著促进作用的，在对应奖励基础上追加50%。"},{"sectionNo":"一2","headline":"县内拍完全剧集，每部补3000元，成效突出再奖最高15万","who":"在长沙县内完成全剧集拍摄的微短剧剧组；作品须在相关网络视听平台播出，并经审核符合申报条件；追加奖励还须经认定对长沙县文旅宣传、主导产业品牌塑造、县域形象提升有显著成效。","materials":[],"window":"作品在网络视听平台播出后申报；追加奖励结合传播效果综合评定。","where":"原文未写明受理部门，经审核、综合评定办理。","tip":"基础取景补贴每部3000元；追加奖励每部最高15万元，须结合传播效果综合评定。"},{"sectionNo":"一3","headline":"影视基地园区协拍成效突出，择优最高奖30万","who":"长沙县内承接优质影视拍摄项目达到一定规模、协拍服务规范且综合成效突出的影视基地、园区；须经综合评定择优。","materials":[],"window":"无固定申报期，按综合评定结果择优确定。","where":"原文未写明受理部门，经综合评定办理。","tip":"奖励为择优给予，并非普惠；最高30万元。"},{"sectionNo":"一4","headline":"新建改造影视基地最高奖200万，数字影棚最高100万","who":"在长沙县内投资新建或改造升级影视基地、园区的主体，以及在县内打造数字影棚的企业；均须经综合评定且符合申报条件。","materials":[],"window":"无固定申报期，按综合评定结果确定。","where":"原文未写明受理部门，经综合评定办理。","tip":"影视基地、园区最高200万元，数字影棚最高100万元，两项分设。"}],"sourceUrl":"http://www.csx.gov.cn/zwgk/zfxxgkml/fdzdgknr/fgwj/gfxwj/gdwxtwj/202603/P020260312496538342362.pdf","sourceNote":"正文取自附件：长沙县政府门户「政策文件—规范性文件库—各单位系统文件」原文页 /zwgk/zfxxgkml/fdzdgknr/fgwj/gfxwj/gdwxtwj/202603/t20260312_12334901.html 所挂 PDF（扫描版，无文字层）。2026-11-22 按附件原件逐页转录，金额、比例、年限均对照原件核对；因是扫描件，脚本无法逐句自动比对。 2026-11-22 收录：官方页面未能打开或不是正文（pages/pdf），条文未与原文比对。 有效期依据：原文明示「自2026年3月20日起试行，有效期两年」，页面信息时效期为2028-03-19","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"unverifiable","hunan":true},{"id":"cs-datalabel-2025-4","title":"长沙市人民政府办公室关于印发《长沙市关于推进国家数据标注基地建设若干政策（试行）》的通知","level":"city","region":"长沙市","issuer":"长沙市人民政府办公室","documentNo":"长政办发〔2025〕4号","publishedAt":"2025-03-13","effectiveAt":"2025-04-01","expiresAt":"2027-03-31","status":"active","tags":["融资支持","财政奖补","贷款贴息"],"audience":["小微数据标注企业","数据标注与人工智能企业","产教融合实训基地","银行机构"],"summary":"小微数据标注企业可获每家每次最高400万元创业担保贷款并按规定贴息；参与制定国际标准、国家标准的企业每项分别最高奖励300万元、100万元；招用就业困难人员可享社保补贴。","sections":[{"no":"一2","title":"","text":"对符合条件的小微数据标注企业提供每家每次最高400万元创业担保贷款支持，并按规定给予财政贴息。"},{"no":"二5","title":"鼓励企事业单位参与制定数据标注技术标准","text":"对参与制定并获得批准发布国际标准、国家标准的企业（排名第1位），每项标准分别给予不高于300万元、100万元的一次性奖励；对参与制定的企业（排名第2、3位），每项标准分别给予不高于200万元、50万元的一次性奖励。对参与制定并获得批准发布行业标准、地方标准的企业，按规定给予相应奖励。"},{"no":"三7","title":"","text":"鼓励高校与企业合作建设数据标注产教融合实训基地。对参加数据标注职业技能培训、经培训取得规定证书（包括职业资格证书、职业技能等级证书、职业培训合格证书）的人员，按照《湖南省人力资源和社会保障厅 湖南省财政厅关于印发〈湖南省职业技能培训补贴实施办法〉的通知》（湘人社规〔2024〕16号）给予培训、就业有关补贴。"},{"no":"四11","title":"","text":"发挥长沙市政府投资产业引导类、科技创新类基金作用，支持合作银行用好支小再贷款、普惠小微贷款支持工具、科技创新和技术改造再贷款等货币政策工具额度，增加中小数据标注企业信用贷、专精特新贷、无还本续贷和中长期贷款投放。"}],"interpretations":[{"sectionNo":"一2","headline":"小微数据标注企业可获每家每次最高400万元创业担保贷款","who":"符合条件的小微数据标注企业；每家每次最高400万元创业担保贷款，并按规定给予财政贴息。","materials":[],"window":"按每家每次申请，最高400万元，原文未列申报期。","where":"创业担保贷款经办机构（原文未列具体名称）。","tip":"最高400万元指每家每次的贷款额度；贷款须属创业担保贷款并按规贴息，仅限符合条件的小微数据标注企业。"},{"sectionNo":"二5","headline":"国际标准排名第1位奖300万元，国家标准奖100万元","who":"参与制定并获批准发布国际标准、国家标准且排名第1位的企业，每项分别不高于300万元、100万元；排名第2、3位的企业，每项分别不高于200万元、50万元；参与制定行业标准、地方标准的企业按规定给予相应奖励。","materials":[],"window":"标准获批发布后给予一次性奖励，原文未列申报期。","where":"原文未列具体受理部门，按标准奖励政策兑现。","tip":"奖励按企业排名分档，第1位与第2、3位金额不同；同一标准每项一次性奖励，行业标准、地方标准按规定给予相应奖励。"},{"sectionNo":"三7","headline":"数据标注培训取得规定证书，可获培训、就业补贴","who":"参加数据标注职业技能培训、经培训取得规定证书的人员，证书包括职业资格证书、职业技能等级证书、职业培训合格证书；鼓励高校与企业合作建设数据标注产教融合实训基地。","materials":["职业资格证书","职业技能等级证书","职业培训合格证书"],"window":"取得规定证书后按《湖南省职业技能培训补贴实施办法》执行，原文未列申报期。","where":"湖南省人力资源和社会保障厅 湖南省财政厅《湖南省职业技能培训补贴实施办法》（湘人社规〔2024〕16号）。","tip":"须参加数据标注职业技能培训并取得规定证书，三类证书均在范围内；补贴含培训和就业两方面，标准按湘人社规〔2024〕16号执行。"},{"sectionNo":"四11","headline":"中小数据标注企业可获信用贷、专精特新贷、无还本续贷","who":"中小数据标注企业；由长沙市政府投资产业引导类、科技创新类基金及合作银行提供支持，信贷产品包括信用贷、专精特新贷、无还本续贷和中长期贷款。","materials":[],"window":"按合作银行信贷投放安排执行，原文未列申报期。","where":"长沙市政府投资产业引导类、科技创新类基金；合作银行（支小再贷款、普惠小微贷款支持工具、科技创新和技术改造再贷款）。","tip":"支持方式是增加信贷投放而非直接补贴；再贷款额度由合作银行使用，企业可对接信用贷、专精特新贷、无还本续贷和中长期贷款。"}],"sourceUrl":"https://www.changsha.gov.cn/zfxxgk/zfwjk/szfbgt/202503/t20250313_11778619.html","sourceNote":"2026-11-21 取自长沙市人民政府门户「政策文件—市政府办公室文件」原文页；页面标注文号长政办发〔2025〕4号、公布日期2025-03-13、信息时效期2027-03-31。条文为页面正文逐字摘录。 2026-11-21 收录：与官方页面逐句比对，命中 7/7 句（100%），关卡判定「verbatim」。 有效期依据：原文明示“自2025年4月1日起施行，有效期2年”；页面登记信息时效期2027-03-31，一致。","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"cs-expo-2025-14","title":"长沙市人民政府办公室关于印发《长沙市推进会展业高质量发展的若干措施》的通知","level":"city","region":"长沙市","issuer":"长沙市人民政府办公室","documentNo":"长政办发〔2025〕14号","publishedAt":"2025-11-06","effectiveAt":"2025-12-15","expiresAt":"2030-12-14","status":"active","tags":["财政奖补","外贸外资"],"audience":["会展主办方","会展企业","组展企业","行业商协会"],"summary":"5000平方米以上、展期3天以上的展览项目按场租50%给予补助，单届最高100万元；商务性会议单次最高50万元；引进品牌会展项目单个最高1000万元；境外自办展最高50万元。","sections":[{"no":"一（一）","title":"","text":"对在我市举办的展览面积在5000平方米以上（含本数，下同）、展期3天以上的展览项目，根据举办届数给予不超过场租50%的资金补助。在此基础上，展览面积较上届增加10%以上的，补助金额按对应比例上浮，最高上浮比例为30%；国际展览项目补助金额上浮30%。单个展览项目单届补助金额最高不超过100万元。"},{"no":"一（二）","title":"","text":"对在我市举办的会期2天以上、会期住宿酒店房间达到500间夜数的商务性、学术性会议项目，根据举办届数给予不超过场租50%的资金补助。在此基础上，会期住宿酒店房间每增加200间夜数，场租补助上浮5%，最高上浮比例为30%；国际性会议项目补助金额上浮30%。单个会议项目单次补助金额最高不超过50万元。"},{"no":"三（一）","title":"","text":"大力引进推动经济发展、提升城市知名度的品牌会展项目。重点引进“世界商展百强”“全国展览百强”、全国同行业规模排名前三、国际展览业协会（UFI）认证的展览项目和纳入国际大会及会议协会（ICCA）统计范围等的全国性、国际性大型会议项目，根据会展规模、绩效目标及评价结果，对主办方给予补助，单个项目补助金额最高不超过1000万元。"},{"no":"五（一）","title":"鼓励我市会展企业到境外自办展览，开拓海外市场","text":"对我市会展企业经相关部门批准，在境外举办的展览项目，给予办展企业最高不超过50万元的补助。"}],"interpretations":[{"sectionNo":"一（一）","headline":"5000平方米以上、展期3天以上展览，场租补助最高100万元","who":"在长沙市举办、展览面积5000平方米以上（含本数）、展期3天以上的展览项目主办方；国际展览项目、展览面积较上届增加10%以上的可上浮补助。","materials":[],"window":"按举办届数计算；单个展览项目单届补助最高100万元。","where":"长沙市（市级财政资金补助）。","tip":"面积较上届增加10%以上按对应比例上浮、最高上浮30%；国际展览项目上浮30%；单届封顶100万元。"},{"sectionNo":"一（二）","headline":"会期2天以上、住宿500间夜的会议，场租补助最高50万元","who":"在长沙市举办、会期2天以上、会期住宿酒店房间达到500间夜数的商务性、学术性会议项目主办方；国际性会议项目、住宿间夜数每增加200间夜数的可上浮。","materials":[],"window":"按举办届数计算；单个会议项目单次补助最高50万元。","where":"长沙市（市级财政资金补助）。","tip":"住宿每增200间夜数场租补助上浮5%、最高上浮30%；国际性会议项目上浮30%；单次封顶50万元。"},{"sectionNo":"三（一）","headline":"引进世界商展百强、UFI认证会展，单项目最高1000万元","who":"引进并主办“世界商展百强”“全国展览百强”、全国同行业规模排名前三、国际展览业协会（UFI）认证的展览项目，或纳入国际大会及会议协会（ICCA）统计范围的全国性、国际性大型会议项目的主办方。","materials":[],"window":"按会展规模、绩效目标及评价结果确定；单个项目最高1000万元。","where":"长沙市（市级财政资金补助）。","tip":"补助依规模、绩效目标及评价结果确定，非按场租比例；单个项目封顶1000万元。"},{"sectionNo":"五（一）","headline":"长沙会展企业经批准在境外办展，最高补助50万元","who":"长沙市会展企业；须经相关部门批准、在境外举办展览项目。","materials":[],"window":"本条未列申报期；单个项目补助最高50万元。","where":"长沙市（市级财政资金补助）。","tip":"以经相关部门批准为前提；补助对象为办展企业，单个项目封顶50万元。"}],"sourceUrl":"https://www.changsha.gov.cn/zfxxgk/zfwjk/szfbgt/202511/t20251106_12046887.html","sourceNote":"2026-11-21 取自长沙市人民政府门户「政策文件—市政府办公室文件」原文页；页面标注文号长政办发〔2025〕14号、公布日期2025-11-06、信息时效期2030-12-14。条文为页面正文逐字摘录。 2026-11-21 收录：与官方页面逐句比对，命中 11/11 句（100%），关卡判定「verbatim」。 有效期依据：原文明示“自2025年12月15日起施行，有效期5年”；页面登记信息时效期2030-12-14，一致。","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"cs-foreign-capital-fund-2026-13","title":"长沙市商务局 长沙市财政局关于印发《长沙市扩大利用外资专项资金管理办法》的通知","level":"city","region":"长沙市","issuer":"长沙市商务局、长沙市财政局","documentNo":"长商务发〔2026〕13号","publishedAt":"2026-03-06","effectiveAt":"2026-03-06","expiresAt":"2031-03-05","status":"active","tags":["外贸外资","专项资金","财政奖补"],"audience":["外商投资企业","外资研发中心","园区商务部门","QFLP试点主体"],"summary":"市级财政预算安排专项资金，对年度内实际使用外资额超过年度目标的高技术产业及非高技术产业外商投资企业给予支持，可与省级资金统筹使用，具体标准以年度申报通知为准。","sections":[{"no":"第一条","title":"","text":"为进一步加大吸引外资力度，加强长沙市扩大利用外资专项资金规范化管理，根据《长沙市人民政府办公室关于印发<长沙市进一步扩大利用外资促进经济高质量发展的若干措施>的通知》（长政办发〔2024〕8号），以及长沙市市级财政专项资金管理相关文件，制定本办法。"},{"no":"第二条","title":"","text":"本办法所称长沙市扩大利用外资专项资金，是指由市级财政预算安排，专项用于支持长沙市扩大利用外资的专项资金。在资金安排上，可与省级相关专项资金统筹使用。鼓励湖南湘江新区、各区县（市）、园区设立扩大利用外资相关资金。"},{"no":"第五条（一）1","title":"","text":"对年度内实际使用外资额超过年度目标的高技术产业外商投资企业，按实际使用外资额不超过1.5%给予支持。每家企业每年支持不超过300万元，累计不超过1000万元。"},{"no":"第六条（二）","title":"","text":"对长沙市扩大利用外资发挥促进作用，依法登记注册的外商投资企业；"}],"interpretations":[{"sectionNo":"第五条（一）1","headline":"高技术外资企业按实际使用外资额不超1.5%给予支持","who":"年度内实际使用外资额超过年度目标的高技术产业外商投资企业。","materials":[],"window":"按年度核定实际使用外资额，须超过年度目标。","where":"长沙市扩大利用外资专项资金（市级财政预算安排）","tip":"每家企业每年支持不超过300万元，累计不超过1000万元；支持比例不超过实际使用外资额的1.5%。"},{"sectionNo":"第六条（二）","headline":"依法登记注册的外商投资企业可申请利用外资专项资金","who":"在长沙市依法登记注册、对长沙市扩大利用外资发挥促进作用的外商投资企业。","materials":[],"window":"按年度组织申报，与省级相关专项资金统筹安排。","where":"长沙市商务局、长沙市财政局","tip":"须依法登记注册且对扩大利用外资有促进作用；具体支持比例与上限按所属支持方向确定。"}],"sourceUrl":"https://www.changsha.gov.cn/zfxxgk/zfwjk/gdwxtwj/202603/t20260306_12329940.html","sourceNote":"2026-11-21 取自长沙市人民政府门户「政策文件—各单位系统文件」原文页；页面标注文号长商务发〔2026〕13号、公布日期2026-03-06、信息时效期2031-03-05。条文为页面正文逐字摘录。 2026-11-21 收录：与官方页面逐句比对，命中 7/7 句（100%），关卡判定「verbatim」。 有效期依据：原文明示“自公布之日起施行，有效期5年”；页面登记信息时效期2031-03-05，一致。","verified":false,"isSample":false,"numberStyle":"clause","bodyVerified":"verbatim","hunan":true},{"id":"cs-foreign-invest-2024-8","title":"长沙市人民政府办公室关于印发《长沙市进一步扩大利用外资促进经济高质量发展的若干措施》的通知","level":"city","region":"长沙市","issuer":"长沙市人民政府办公室","documentNo":"长政办发〔2024〕8号","publishedAt":"2024-04-16","effectiveAt":"2024-04-20","expiresAt":"2029-04-19","status":"active","tags":["外贸外资","财政奖补","税收优惠"],"audience":["外商投资企业","外资研发中心","外资先进制造业项目","境外投资者"],"summary":"对年度内实际使用外资贡献突出的外商投资企业，每家每年支持不超过300万元、累计不超过1000万元；落实外国投资者利润再投资暂不征收预提所得税；世界500强研发中心负责人可直接认定高层次人才。","sections":[{"no":"二（一）","title":"优化外商投资结构","text":"鼓励外资投向制造业和高新技术、现代服务业、节能环保等领域，引导外资积极参与碳达峰碳中和战略。落实鼓励外商投资产业目录配套政策，符合条件的外商投资企业在投资总额内进口自用设备，可向海关办理减免税审核确认手续。依据相关规定，对集约用地的鼓励类外商投资工业项目提供用地保障。（责任单位：市商务局、市工业和信息化局、市科技局、市生态环境局、市发展改革委、市自然资源规划局、星沙海关）"},{"no":"二（二）","title":"鼓励外商投资制造业","text":"充分发挥外商投资企业的资本和技术优势，引导外资投向工程机械、汽车及零部件、生物医药、电子信息等支柱产业，以及新一代半导体、移动互联网、智能网联汽车等特色新兴产业，提升产业链供应链水平，推动制造业高质量发展。对新引进的外资先进制造业项目，按照我市招商引资相关政策给予支持。（责任单位：市工业和信息化局、市科技局、市商务局、市财政局、湖南湘江新区管委会、自贸区长沙片区管委会、各区县市人民政府和园区管委会）"},{"no":"三（四）","title":"加大财税支持力度","text":"对年度内实际使用外资贡献突出的外商投资企业给予支持，每家企业每年不超过300万元，累计不超过1000万元。落实外国投资者境内取得利润再投资暂不征收预提所得税政策。对全市产业发展有重大推动作用的外资项目，根据有关政策按“一事一议”方式给予支持。（责任单位：市商务局、市财政局、市税务局）"},{"no":"四（四）","title":"支持外商投资企业引进人才","text":"鼓励外商投资企业引进高端人才，按照我市人才政策及相关配套细则、中国（湖南）自由贸易试验区长沙片区人才集聚发展相关政策予以支持。对世界500强企业研发中心、外资研发中心主要负责人，符合条件的可直接认定为长沙市高层次人才（C类以上）。持续推进外国人来华“一站式”服务中心建设。实施外国人来华工作许可制度，符合A类标准的可以依据相关规定采取告知承诺、容缺受理等方式，为外国人才来长办理工作许可提供便利。对经认定的外国高层次人才、国家紧缺专门人才，可换发入境有效期不超过5年，停留期不超过180天的多次签证或居留有效期不超过5年的居留证件。对重大和重点外资项目，按工作需要为项目相关外方人员签发多次往返商务签证。（责任单位：市商务局、自贸区长沙片区管委会、市人力资源社会保障局、市科技局、市公安局）"}],"interpretations":[{"sectionNo":"二（一）","headline":"鼓励类外资项目进口自用设备可办减免税，用地优先保障","who":"投向制造业和高新技术、现代服务业、节能环保等领域的外商投资企业；符合鼓励外商投资产业目录、在投资总额内进口自用设备的，可办理减免税审核确认；集约用地的鼓励类外商投资工业项目可获用地保障。","materials":[],"window":"原文未设申报期，按海关减免税审核确认程序办理。","where":"星沙海关（减免税审核确认）；市商务局、市工业和信息化局、市科技局、市生态环境局、市发展改革委、市自然资源规划局按职责分工","tip":"仅限符合鼓励外商投资产业目录、在投资总额内进口的自用设备；用地保障针对集约用地的鼓励类外商投资工业项目。"},{"sectionNo":"二（二）","headline":"新引进外资先进制造业项目，按招商引资政策给予支持","who":"投向工程机械、汽车及零部件、生物医药、电子信息等支柱产业，以及新一代半导体、移动互联网、智能网联汽车等特色新兴产业的新引进外资先进制造业项目。","materials":[],"window":"原文未设申报期，按我市招商引资相关政策执行。","where":"市工业和信息化局、市科技局、市商务局、市财政局、湖南湘江新区管委会、自贸区长沙片区管委会、各区县市人民政府和园区管委会按职责分工","tip":"支持对象限“新引进”的外资先进制造业项目，投向须属支柱产业或特色新兴产业；具体支持标准依招商引资政策。"},{"sectionNo":"三（四）","headline":"外资企业年度支持最高300万元，累计不超1000万元","who":"年度内实际使用外资贡献突出的外商投资企业；以境内取得利润再投资的外国投资者暂不征收预提所得税；对全市产业发展有重大推动作用的外资项目可按“一事一议”支持。","materials":[],"window":"按年度计算，每家企业每年不超过300万元，累计不超过1000万元。","where":"市商务局、市财政局、市税务局按职责分工","tip":"年度上限300万元、累计上限1000万元；再投资暂不征预提所得税须为境内取得的利润；重大项目另按“一事一议”方式支持。"},{"sectionNo":"四（四）","headline":"外资研发中心主要负责人可认定C类以上高层次人才","who":"外商投资企业引进的高端人才；世界500强企业研发中心、外资研发中心主要负责人，符合条件的可直接认定为长沙市高层次人才（C类以上）；符合外国人来华工作许可A类标准的外国人才；经认定的外国高层次人才、国家紧缺专门人才；重大和重点外资项目相关外方人员。","materials":[],"window":"经认定的外国高层次人才、国家紧缺专门人才可换发入境有效期不超过5年、停留期不超过180天的多次签证，或居留有效期不超过5年的居留证件。","where":"市商务局、自贸区长沙片区管委会、市人力资源社会保障局、市科技局、市公安局；外国人来华“一站式”服务中心","tip":"C类以上认定仅限世界500强企业研发中心、外资研发中心主要负责人；签证与居留证件有效期上限5年、停留期上限180天。"}],"sourceUrl":"https://www.changsha.gov.cn/zfxxgk/zfwjk/szfbgt/202404/t20240416_11419635.html","sourceNote":"2026-11-21 取自长沙市人民政府门户「政策文件—市政府办公室文件」原文页；页面标注文号长政办发〔2024〕8号、公布日期2024-04-16、信息时效期2029-04-19。条文为页面正文逐字摘录。 2026-11-21 收录：与官方页面逐句比对，命中 18/18 句（100%），关卡判定「verbatim」。 有效期依据：原文明示“自2024年4月20日起施行，有效期5年”；页面登记信息时效期2029-04-19，一致。","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"cs-foreign-trade-fund-2026-9","title":"关于印发《长沙市开放型经济发展专项资金（外贸部分）管理办法》的通知","level":"city","region":"长沙市","issuer":"长沙市商务局、长沙市财政局","documentNo":"长商务发〔2026〕9号","publishedAt":"2026-03-04","effectiveAt":"2026-03-04","expiresAt":"2029-03-03","status":"active","tags":["外贸外资","专项资金","财政奖补"],"audience":["外贸企业","园区外贸综合服务中心","组展机构","海关AEO认证企业"],"summary":"外贸企业按业务规模及海关、税务、外汇信用等级分类分档奖励，单个企业最高300万元；参加进博会等展会的场地费、特装费、运输费按不超过50%支持，单家最高10万元。","sections":[{"no":"第六条（一）","title":"","text":"鼓励外贸企业做大做强，综合考虑外贸企业业务规模及海关、税务、外汇信用管理等级等因素，分类分档给予奖励，单个企业最高支持上限为300万元。综合考评条件和补贴标准以当年申报通知为准。"},{"no":"第六条（二）","title":"","text":"支持企业参加中国国际进口博览会等国内具有国际影响力的会展平台。对企业在进博会等重大展会期间开展的采购对接、投资促进、人文交流等活动产生的场地费、特装费、运输费等相关费用给予不超过50%的比例予以资金支持，单个企业支持上限为10万元。"},{"no":"第六条（三）","title":"","text":"支持企业开展管理体系认证、境外产品认证、境外专利申请和境外商标注册。对外贸企业开展管理体系认证、产品境外认证、境外专利申请和境外商标注册产生的费用给予不超过50%的比例予以资金支持，单个企业支持上限为15万元。"},{"no":"第六条（五）","title":"支持企业开展海关AEO高级认证","text":"对外贸企业本年度通过海关AEO高级认证的企业，在认定过程中，为完善自身信用体系建设所产生的咨询辅导费、体系建设费、委托业务费等服务费用给予不超过50%的支持，单个企业支持上限为15万元。"}],"interpretations":[{"sectionNo":"第六条（一）","headline":"外贸企业分类分档奖励，单个企业最高300万元","who":"外贸企业；综合考评外贸业务规模及海关、税务、外汇信用管理等级等因素分类分档；具体考评条件和补贴标准以当年申报通知为准。","materials":[],"window":"按当年申报通知执行，原文未列具体申报期。","where":"长沙市商务局、长沙市财政局（以当年申报通知为准）","tip":"300万元是单个企业最高支持上限，实际按业务规模与海关、税务、外汇信用等级分档；考评条件和标准每年随申报通知调整。"},{"sectionNo":"第六条（二）","headline":"参加进博会等展会，场地特装运输费补50%，最高10万元","who":"参加中国国际进口博览会等国内具有国际影响力的会展平台，并在展会期间开展采购对接、投资促进、人文交流等活动的外贸企业。","materials":[],"window":"按展会活动发生年度申报，原文未列具体申报期。","where":"长沙市商务局、长沙市财政局（原文未列具体受理窗口）","tip":"只补场地费、特装费、运输费等展会相关费用，比例不超过50%，单个企业支持上限10万元。"},{"sectionNo":"第六条（三）","headline":"管理体系与境外认证、专利商标费用补50%，最高15万元","who":"开展管理体系认证、境外产品认证、境外专利申请和境外商标注册的外贸企业。","materials":[],"window":"按年度申报，原文未列具体申报期。","where":"长沙市商务局、长沙市财政局（原文未列具体受理窗口）","tip":"管理体系认证、产品境外认证、境外专利申请、境外商标注册四类费用均按不超过50%支持，单个企业支持上限15万元。"},{"sectionNo":"第六条（五）","headline":"本年度通过海关AEO高级认证，服务费补50%，最高15万元","who":"本年度通过海关AEO高级认证的外贸企业；支持其在认定过程中为完善自身信用体系建设所产生的咨询辅导费、体系建设费、委托业务费等服务费用。","materials":[],"window":"本年度通过认证后申报，原文未列具体申报期。","where":"长沙市商务局、长沙市财政局（原文未列具体受理窗口）","tip":"只补AEO认定过程中的咨询辅导费、体系建设费、委托业务费，比例不超过50%，单个企业上限15万元；支持对象限定为本年度通过认证的企业。"}],"sourceUrl":"https://www.changsha.gov.cn/zfxxgk/zfwjk/gdwxtwj/202603/t20260306_12329902.html","sourceNote":"2026-11-21 取自长沙市人民政府门户「政策文件—各单位系统文件」原文页；页面标注文号长商务发〔2026〕9号、公布日期2026-03-04、信息时效期2029-03-03。条文为页面正文逐字摘录。 2026-11-21 收录：与官方页面逐句比对，命中 7/7 句（100%），关卡判定「verbatim」。 有效期依据：原文明示“自2026年3月4日起施行，有效期三年”；页面登记信息时效期2029-03-03，一致。","verified":false,"isSample":false,"numberStyle":"clause","bodyVerified":"verbatim","hunan":true},{"id":"cs-ftz-2026-2","title":"长沙市人民政府办公室印发《关于推动中国（湖南）自由贸易试验区长沙片区高水平开放高质量发展的若干政策》的通知","level":"city","region":"长沙市","issuer":"长沙市人民政府办公室","documentNo":"长政办发〔2026〕2号","publishedAt":"2026-03-11","effectiveAt":null,"expiresAt":null,"status":"active","tags":["外贸外资","财政奖补"],"audience":["自贸区长沙片区内的“四新”经济项目主体","工程机械再制造企业","生物医药企业及专业服务机构"],"summary":"对“四新”经济项目按当年实际投入给予最高30%奖励、单个项目最高1000万元；工程机械再制造按设备数量最高2万元/台奖励、单个企业最高200万元。","sections":[{"no":"一","title":"加快实施创新发展","text":"支持打造高能级创新生态，促进创新链产业链融合发展，对“四新”（新技术、新产业、新业态、新模式）经济项目，市及区县按其当年实际投入（新增固定资产投资及无形资产投资，不含购买土地费用，下同）给予最高30%的奖励，单个项目最高奖励1000万元。"},{"no":"一续","title":"课题与模式创新奖励","text":"鼓励部门（单位）、企业、高校、行业协会等机构围绕制度创新和产业发展提供创新支持，开展专题研讨、项目研究、标准制定和创新等方面探索，对形成创新成果的课题（案例）给予奖励，单个课题（案例）最高奖励20万元。支持探索“以服易货”等业务新模式，根据模式类别对探索企业奖励50万元，单个企业最高奖励100万元。"},{"no":"一续二","title":"生物医药产业","text":"支持生物医药产业创新发展，鼓励企业或机构在依法依规并遵守伦理及生物安全相关要求的前提下，建设自贸区长沙片区应用研究和服务等设施，市及区县按其当年实际投入的30%给予奖励，单个企业或机构最高奖励1000万元。"},{"no":"二","title":"工程机械再制造体系","text":"对业务创新发展的工程机械再制造企业，按其完成维修（再制造）及检测销售的设备数量，给予最高2万元/台奖励，单个企业最高奖励200万元。对参与工程机械再制造（二手）设备出口标准制定的机构，按标准层级给予最高200万元奖励。"},{"no":"二续","title":"检测认证与溯源平台","text":"对开展工程机械再制造（二手）设备检测认证的第三方检验机构，按其检验检测的设备品类及规格给予最高补助3000元/台，单个机构最高补助30万元。支持工程机械再制造线上溯源管理信息平台建设，依法依规对建设并运营平台的企业，按其当年实际建设及运营投入的30%给予奖励。"}],"interpretations":[{"sectionNo":"一","headline":"「四新」项目按当年实际投入30%奖励，单项目最高1000万","who":"在中国（湖南）自由贸易试验区长沙片区的“四新”（新技术、新产业、新业态、新模式）经济项目；按当年实际投入（新增固定资产投资及无形资产投资，不含购买土地费用）给予奖励。","materials":[],"window":"按当年实际投入计算，年度兑现；原文未列申报起止时间。","where":"市及区县（原文未写明具体受理部门）。","tip":"投入不含购买土地费用；奖励比例最高30%、单个项目封顶1000万元。"},{"sectionNo":"一续","headline":"创新成果课题（案例）最高奖20万，「以服易货」企业奖50万","who":"围绕制度创新和产业发展开展专题研讨、项目研究、标准制定等探索并形成创新成果的部门（单位）、企业、高校、行业协会等机构；探索“以服易货”等业务新模式的企业。","materials":[],"window":"按创新成果认定兑现；单个企业“以服易货”类奖励最高100万元。","where":"原文未写明受理窗口，按创新成果申报认定。","tip":"单个课题（案例）封顶20万元；模式创新按类别奖励50万元、单企业累计封顶100万元。"},{"sectionNo":"一续二","headline":"生物医药设施按当年投入30%奖励，单家最高1000万元","who":"在依法依规并遵守伦理及生物安全相关要求的前提下，在自贸区长沙片区建设应用研究和服务等设施的企业或机构。","materials":[],"window":"按当年实际投入计算，年度兑现；原文未列申报起止时间。","where":"市及区县（原文未写明具体受理部门）。","tip":"须符合伦理及生物安全要求；奖励比例30%、单个企业或机构封顶1000万元。"},{"sectionNo":"二","headline":"再制造设备最高奖2万元/台，单企业封顶200万元","who":"业务创新发展的工程机械再制造企业（按完成维修（再制造）及检测销售的设备数量计奖）；参与工程机械再制造（二手）设备出口标准制定的机构。","materials":[],"window":"按完成维修（再制造）及检测销售的设备数量核算；标准奖励按标准层级确定。","where":"原文未写明受理部门，按设备数量与标准层级申报。","tip":"单个企业奖励封顶200万元；参与出口标准制定的机构最高奖励200万元。"},{"sectionNo":"二续","headline":"再制造检测认证最高补3000元/台，单机构封顶30万","who":"开展工程机械再制造（二手）设备检测认证的第三方检验机构；建设并运营工程机械再制造线上溯源管理信息平台的企业。","materials":[],"window":"检测补助按检验检测的设备品类及规格核算；平台按当年实际建设及运营投入的30%奖励。","where":"原文未写明受理部门，按检测品类与平台投入申报。","tip":"检测补助单个机构封顶30万元；溯源平台奖励比例为投入的30%。"}],"sourceUrl":"http://ftz.changsha.gov.cn/zwgk/fdzdgknr/zcwj/202603/P020260318425154096326.wps","sourceNote":"2026-11-21 取自自贸区长沙片区管委会「政务公开—政策文件」原文（.wps 直链）；标题与文号经长沙市政府门户“政策文件”栏目同名条目核对。附件直链，属链接降级形态。 2026-11-21 收录：与官方页面逐句比对，命中 8/8 句（100%），关卡判定「verbatim」。 有效期依据：原文未设期限；按行政规范性文件一般不超5年推算至2031-03","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"cs-incubator-2026-20","title":"关于印发《长沙市科技型企业孵化器管理办法》的通知","level":"city","region":"长沙市","issuer":"长沙市科学技术局","documentNo":"长科发〔2026〕20号","publishedAt":"2026-09-28","effectiveAt":"2026-09-28","expiresAt":"2031-09-27","status":"active","tags":["认定资质","场地支持","财政奖补"],"audience":["孵化器运营主体","科技型初创企业","创业团队","投资机构"],"summary":"垂直孵化器建设期三年、分阶段支持，经费最高200万元；在孵企业入库科技型中小企业每家支持0.5万元，通过高新技术企业认定每家支持3万元。","sections":[{"no":"第十五条","title":"孵化器建设支持","text":"聚焦优势产业、新兴产业和未来产业细分赛道，布局建设产业集聚强、孵化服务强、专业人才强、投资赋能强、孵化成效好的垂直孵化器，建设期三年，采取分阶段支持的方式，支持经费最高200万元。垂直孵化器的遴选方式、评审程序、评价管理等以后续出台的文件为准。"},{"no":"第十六条","title":"孵化器的运营支持","text":"对绩效评价结果合格以上的孵化器给予运营支持。支持方式为：在孵企业入库科技型中小企业的，按每家0.5万元的标准予以支持，从第3次入科技型中小企业库起不再对孵化器予以支持；在孵企业通过高新技术企业认定的，按照每家3万元的标准予以支持。"},{"no":"第七条","title":"","text":"本办法认定的孵化器运营主体应实际注册并运行满1年，具有独立法人资格、完善的运营管理体系；具有产权清晰且可自主支配（自有、租赁或协议使用）的孵化场地；具有全职的运营管理团队；聚焦重点产业、新兴产业及未来产业，提供专业技术服务，开展多模式孵化。"},{"no":"第八条","title":"","text":"孵化器在孵企业是指注册且实际运营在孵化器内，从事新技术新产品研发、生产和服务的被孵化企业，且符合《中小企业划型标准规定》中的小型、微型企业标准。"}],"interpretations":[{"sectionNo":"第十五条","headline":"垂直孵化器建设期3年，分阶段支持最高200万元","who":"聚焦优势产业、新兴产业和未来产业细分赛道建设的垂直孵化器；须产业集聚强、孵化服务强、专业人才强、投资赋能强、孵化成效好。","materials":[],"window":"建设期三年，采取分阶段支持的方式。","where":"原文未明确受理部门，遴选方式、评审程序以后续出台文件为准","tip":"200万元为最高支持额；遴选方式、评审程序、评价管理以后续出台文件为准。"},{"sectionNo":"第十六条","headline":"在孵企业入库科技型中小每家补0.5万元、高企每家3万元","who":"绩效评价结果合格以上的孵化器；其在孵企业入库科技型中小企业的按每家0.5万元支持，在孵企业通过高新技术企业认定的按每家3万元支持。","materials":[],"window":"从在孵企业第3次入科技型中小企业库起不再对孵化器予以支持。","where":"原文未明确受理部门","tip":"同一在孵企业第3次入库起不再支持；高企认定按每家3万元另行支持。"},{"sectionNo":"第七条","headline":"孵化器运营主体须注册运行满1年、有独立法人资格和场地","who":"本办法认定的孵化器运营主体：实际注册并运行满1年；具有独立法人资格、完善的运营管理体系；具有产权清晰且可自主支配（自有、租赁或协议使用）的孵化场地；具有全职的运营管理团队；聚焦重点产业、新兴产业及未来产业并提供专业技术服务。","materials":[],"window":"应实际注册并运行满1年。","where":"原文未明确受理部门","tip":"场地须产权清晰且可自主支配，自有、租赁或协议使用均可；团队须为全职。"},{"sectionNo":"第八条","headline":"在孵企业须注册运营在孵化器内、符合小型微型企业标准","who":"注册且实际运营在孵化器内，从事新技术新产品研发、生产和服务的被孵化企业，且符合《中小企业划型标准规定》中的小型、微型企业标准。","materials":[],"window":"原文未明确在孵期限，以实际注册运营在孵化器内为准。","where":"原文未明确受理部门","tip":"须同时满足在孵化器内注册运营与小型、微型企业标准；中型及以上企业不属在孵企业。"}],"sourceUrl":"https://www.changsha.gov.cn/zfxxgk/zfwjk/gdwxtwj/202609/t20260928_12578045.html","sourceNote":"2026-11-21 取自长沙市人民政府门户「政策文件—各单位系统文件」原文页；页面标注文号长科发〔2026〕20号、公布日期2026-09-28、信息时效期2031-09-27。条文为页面正文逐字摘录。 2026-11-21 收录：与官方页面逐句比对，命中 9/9 句（100%），关卡判定「verbatim」。 有效期依据：原文明示“自公布之日起施行，有效期5年”；页面登记信息时效期2031-09-27，一致。","verified":false,"isSample":false,"numberStyle":"clause","bodyVerified":"verbatim","hunan":true},{"id":"cs-industry-research-inst-2026-24","title":"关于印发《长沙市工业技术研究院建设与管理办法》的通知","level":"city","region":"长沙市","issuer":"长沙市科学技术局","documentNo":"长科发〔2026〕24号","publishedAt":"2026-11-09","effectiveAt":"2026-12-15","expiresAt":"2029-12-14","status":"active","tags":["认定资质","研发创新","专项资金"],"audience":["行业科技领军企业","新型研发机构","产业链链主企业"],"summary":"工业技术研究院依托行业科技领军企业组建、注册为企业法人，需科研办公场所达标、研发人员不少于50人；经专家评审和会议审定后组建，市政府按建设任务书给予资金支持，建设期三年。","sections":[{"no":"第二条","title":"","text":"本办法所称工业技术研究院是依托行业科技领军企业组建，围绕长沙产业发展重点，聚焦重大科技创新需求，集行业技术研发、技术服务、成果转化、企业孵化、人才聚集和资源开放于一体的协同创新平台，是投资主体多元化、管理制度现代化、运行机制市场化、用人机制灵活化的新型研发机构，应依法注册为企业法人。"},{"no":"第十条（一）","title":"","text":"具备进行研究、开发和试验所需要的仪器、设备和固定场地等基础设施，科研和办公场所不少于2000平方米，用于研究开发试验的仪器设备原值不少于2000万元。"},{"no":"第十条（三）","title":"","text":"具有实力较强的研发队伍，研发人员不少于50人，其中中级以上技术职称或具有相应技术能力的人员比例不低于30%。"},{"no":"第十五条","title":"","text":"对同意组建的工业技术研究院，长沙市人民政府予以资金支持，根据任务书约定的阶段目标完成情况及建设进展进行拨付。探索采用“拨改投”、“拨投结合”方式对工业技术研究院进行支持。"}],"interpretations":[{"sectionNo":"第二条","headline":"工业技术研究院须注册为企业法人，依托行业领军企业组建","who":"依托行业科技领军企业组建、围绕长沙产业发展重点、聚焦重大科技创新需求的协同创新平台；须依法注册为企业法人，投资主体多元化、管理制度现代化、运行机制市场化、用人机制灵活化。","materials":[],"window":"按办法组建认定，原文未设申报截止期。","where":"长沙市；由行业科技领军企业依托组建，原文未单列受理部门。","tip":"必须是企业法人，不能以事业单位或内设机构身份申报；功能定位为新型研发机构。"},{"sectionNo":"第十条（一）","headline":"场地不少于2000平方米，仪器设备原值不低于2000万元","who":"申报组建工业技术研究院的单位；须具备进行研究、开发和试验所需的仪器、设备和固定场地等基础设施，科研和办公场所不少于2000平方米，用于研究开发试验的仪器设备原值不少于2000万元。","materials":[],"window":"组建申报时核定，原文未设期限。","where":"原文未列受理窗口；属地长沙市。","tip":"场所面积与仪器设备原值两项门槛须同时满足，均以2000为下限。"},{"sectionNo":"第十条（三）","headline":"研发人员不少于50人，中级以上职称占比不低于30%","who":"申报组建工业技术研究院的单位；须具有实力较强的研发队伍，研发人员不少于50人，其中中级以上技术职称或具有相应技术能力的人员比例不低于30%。","materials":[],"window":"组建申报时核定，原文未设期限。","where":"原文未列受理窗口；属地长沙市。","tip":"30%的口径包含“具有相应技术能力”的人员，不限于职称；研发人员总数须达到50人。"},{"sectionNo":"第十五条","headline":"同意组建的工研院获市政府资金支持，按阶段目标拨付","who":"经同意组建的工业技术研究院；资金按任务书约定的阶段目标完成情况及建设进展拨付。","materials":[],"window":"按任务书约定的阶段目标完成情况及建设进展分阶段拨付。","where":"长沙市人民政府（资金支持）；具体拨付按任务书执行。","tip":"资金与阶段目标完成情况挂钩，不是一次性到位；探索“拨改投”“拨投结合”方式支持。"}],"sourceUrl":"https://www.changsha.gov.cn/zfxxgk/zfwjk/gdwxtwj/202611/t20261109_12611507.html","sourceNote":"2026-11-21 取自长沙市人民政府门户「政策文件—各单位系统文件」原文页；页面标注文号长科发〔2026〕24号、公布日期2026-11-09、信息时效期2029-12-14。条文为页面正文逐字摘录。 2026-11-21 收录：与官方页面逐句比对，命中 5/5 句（100%），关卡判定「verbatim」。 有效期依据：原文明示“自2026年12月15日起施行，有效期三年”；页面登记信息时效期2029-12-14，一致。","verified":false,"isSample":false,"numberStyle":"clause","bodyVerified":"verbatim","hunan":true},{"id":"cs-intl-consumption-2026-68","title":"长沙市商务局 长沙市财政局关于印发《长沙市国际化消费环境建设试点项目与专项资金管理办法》的通知","level":"city","region":"长沙市","issuer":"长沙市商务局、长沙市财政局","documentNo":"长商务发〔2026〕68号","publishedAt":"2026-11-20","effectiveAt":"2026-11-20","expiresAt":"2027-12-31","status":"active","tags":["专项资金","财政奖补"],"audience":["商贸流通企业","商圈运营管理方","景区与场馆运营方","行业协会"],"summary":"多语种标识、行李寄存等便利化设施项目（有效投资额不低于50万元）按不超过80%支持、最高200万元；商圈商户统一申报的多语种服务设施项目最高100万元；同一主体补助最高2000万元。","sections":[{"no":"第十三条（三）1","title":"","text":"对完善重点商圈、旅游景区、机场、火车站、地铁站、体育场馆、文博机构等重点场所多语种标识，增设行李寄存、境外旅客引导服务台、服务指引等便利化服务设施，投放多语种翻译工具的项目（有效投资额不低于50万元），按照不超过有效投资额80%的比例给予支持，补助金额最高不超过200万元。"},{"no":"第十三条（三）2","title":"","text":"对国际消费集聚区、入境友好型商圈、4A级及以上景区等区域内的餐饮、住宿、零售商户，在经营场所布设多语种价签、菜单、标牌、行李寄存等服务设施的，由商户所在区域的运营管理方统一组织申报（总申报项目有效投资额不低于10万元），按不超过有效投资额的80%给予补助，补助金额最高不超过100万元。"},{"no":"第十三条（三）3","title":"","text":"对有关单位和机构聚焦重点商圈、交通枢纽选派志愿者参与外语接待、支付指导、旅游咨询、购物指引等志愿服务的项目，以及联合高校、培训机构针对重点消费场所服务人员开展同类业务培训的项目，补助标准均不超过200元/人/天，其中志愿服务类项目补助金额最高不超过100万元（补助资金限用于与项目直接相关的志愿者培训、服务补助、社会宣传、物资及后勤保障等支出，申报时须提供费用明细清单及志愿者服务证明材料等）；业务培训类项目补助金额最高不超过50万元（申报时须提供培训服务协议、参训人员签到记录及反映培训现场情况的影像资料等证明材料）。"},{"no":"第九条（二）","title":"项目审核","text":"区县（市）商务部门对申报主体及项目的真实性、完整性、合规性进行审核，开展实地核查，审核通过的报送至市商务局。"}],"interpretations":[{"sectionNo":"第十三条（三）1","headline":"重点场所多语种标识项目按投资额80%补助，最高200万元","who":"完善重点商圈、旅游景区、机场、火车站、地铁站、体育场馆、文博机构等重点场所多语种标识，增设行李寄存、境外旅客引导服务台、服务指引等便利化服务设施，投放多语种翻译工具的项目单位；项目有效投资额不低于50万元。","materials":[],"window":"按项目有效投资额核定，补助比例不超过有效投资额80%。","where":"重点商圈、旅游景区、机场、火车站、地铁站、体育场馆、文博机构等重点场所。","tip":"有效投资额低于50万元的不予支持；补助金额最高不超过200万元。"},{"sectionNo":"第十三条（三）2","headline":"商圈景区内餐饮住宿零售商户布设多语种设施，补投资额80%","who":"国际消费集聚区、入境友好型商圈、4A级及以上景区等区域内的餐饮、住宿、零售商户；须由商户所在区域的运营管理方统一组织申报，总申报项目有效投资额不低于10万元。","materials":[],"window":"由运营管理方统一组织申报，总申报项目有效投资额不低于10万元。","where":"国际消费集聚区、入境友好型商圈、4A级及以上景区等区域（由运营管理方统一申报）。","tip":"商户不单独申报，须由所在区域运营管理方统一组织；补助金额最高不超过100万元。"},{"sectionNo":"第十三条（三）3","headline":"志愿与培训项目按200元/人/天补，志愿类最高100万元","who":"聚焦重点商圈、交通枢纽选派志愿者参与外语接待、支付指导、旅游咨询、购物指引等志愿服务的单位和机构；联合高校、培训机构针对重点消费场所服务人员开展同类业务培训的单位和机构。","materials":["费用明细清单","志愿者服务证明材料","培训服务协议","参训人员签到记录","反映培训现场情况的影像资料"],"window":"补助标准不超过200元/人/天；志愿服务类项目最高100万元，业务培训类项目最高50万元。","where":"重点商圈、交通枢纽及重点消费场所（志愿服务与业务培训项目）。","tip":"补助资金限用于与项目直接相关的志愿者培训、服务补助、社会宣传、物资及后勤保障等支出。"}],"sourceUrl":"https://www.changsha.gov.cn/zfxxgk/zfwjk/gdwxtwj/202611/t20261120_12624303.html","sourceNote":"2026-11-21 取自长沙市人民政府门户「政策文件—各单位系统文件」原文页；页面标注文号长商务发〔2026〕68号、公布日期2026-11-20、信息时效期2027-12-31。条文为页面正文逐字摘录。 2026-11-21 收录：与官方页面逐句比对，命中 5/5 句（100%），关卡判定「verbatim」。 有效期依据：原文明示“自公布之日起施行，有效期至2027年12月31日”；页面登记信息时效期一致。","verified":false,"isSample":false,"numberStyle":"clause","bodyVerified":"verbatim","hunan":true},{"id":"cs-liuyang-brand-plan-2023","title":"浏阳市人民政府办公室关于印发《浏阳市品牌建设工程行动计划》的通知","level":"district","region":"长沙市·浏阳市","issuer":"浏阳市人民政府办公室","documentNo":"浏政办发〔2023〕9号","publishedAt":"2023-07-03","effectiveAt":"2023-07-03","expiresAt":"2028-07-02","status":"active","tags":["营商环境","认定资质"],"audience":["浏阳市制造业、农业、服务业企业","品牌培育企业"],"summary":"以湖南名品引领、行业品牌提升、品牌强基固本、品牌宣传推广、品牌成长护航五项行动推进浏阳品牌建设，设立浏阳市市长质量奖并组织推荐企业参加省长质量奖、长沙市市长质量奖评选，支持企业申报品牌类专项资金、开展境外商标注册和品牌推广。","sections":[{"no":"二（一）","title":"湖南名品引领行动","text":"工作内容：开展品牌标准宣传贯彻，引导企业强化品牌意识，加强品牌建设。聚焦优势特色农业、先进制造业和服务业，由行业主管部门结合实际，加大对湖南名品、高新技术企业、专精特新企业、等级景区、老字号、芙蓉奖、省优质工程奖等品牌培育工作的指导和支持，全力助推符合条件的企业向上申报专项资金，引导各类社会资金支持品牌建设。（市场监管局、发改局、财政局、科技局、工信局、商务局、文旅广体局、农业农村局、住建局、水利局、林业局、花炮中心等单位分工负责，排名第一的为牵头单位，下同）"},{"no":"二（二）1","title":"打造政府质量奖标杆","text":"1．打造政府质量奖标杆。设立浏阳市市长质量奖，做好首届奖项评选工作。根据《中国质量奖管理办法》《湖南省省长质量奖管理办法》要求，聚焦浏阳优势特色产业，积极指导和推荐企业参加省长质量奖、长沙市市长质量奖的评选工作。（市场监管局、教育局、科技局、工信局、财政局、人社局、商务局、文旅广体局、卫健局、花炮中心按职责分工负责）"},{"no":"二（二）2","title":"建设农产品品牌体系","text":"2．建设农产品品牌体系。建立、实施农产品品牌目录制度，持续开展农产品区域公用品牌和产业集群品牌建设，深入实施农业生产“三品一标”（品种培优、品质提升、品牌打造和标准化生产）提升行动，加强绿色、有机和地理标志农产品培育发展，深入推进地理标志农产品保护工程，示范保护一批地理标志农产品。加强科技创新、质量管理和市场营销，打造一批产品优、信誉好、产业带动性强、具有核心竞争力的合作社品牌、家庭农场品牌和农业领军企业品牌。发展乡村新产业新业态，围绕休闲农业、乡村服务业，打造新型农业服务品牌。（农业农村局、林业局、市场监管局、发改局按职责分工负责）"},{"no":"三（二）","title":"强化政策支持","text":"（二）强化政策支持。各有关部门要加强促进品牌建设的政策引导，强化浏阳品牌发展扶持力度，加大产业、环境、土地、金融、税收、人才等方面的支持，在政府采购、招投标、银行信贷等项目中，依法支持浏阳品牌推广应用，提升本地品牌发展水平。鼓励通过市场化运作，引导社会资金支持品牌建设。"}],"interpretations":[{"sectionNo":"二（二）1","headline":"浏阳设市长质量奖，企业可参评省长、长沙市市长质量奖","who":"浏阳优势特色产业企业：可参加首届浏阳市市长质量奖评选，并由市场监管等部门指导推荐参加省长质量奖、长沙市市长质量奖评选。","materials":[],"window":"首届浏阳市市长质量奖评选；省长质量奖、长沙市市长质量奖按上级评选安排推荐。","where":"浏阳市市场监管局牵头，教育局、科技局、工信局、财政局、人社局、商务局、文旅广体局、卫健局、花炮中心按职责分工","tip":"奖项依据《中国质量奖管理办法》《湖南省省长质量奖管理办法》要求组织；推荐参评上级奖项需经部门指导推荐。"},{"sectionNo":"二（二）2","headline":"农产品可进品牌目录，绿色有机地标农产品重点培育","who":"浏阳市农产品生产经营主体：合作社、家庭农场、农业领军企业可打造自有品牌；绿色、有机和地理标志农产品可获培育支持和保护。","materials":[],"window":"持续开展，原文未设申报截止时间。","where":"浏阳市农业农村局、林业局、市场监管局、发改局按职责分工","tip":"品牌建设与“三品一标”（品种培优、品质提升、品牌打造和标准化生产）挂钩；地理标志农产品另有保护工程示范保护。"}],"sourceUrl":"http://www.liuyang.gov.cn/zwgk/zfxxgk/fdzdgknr/zcwj/xzgfxwj/szfyzfbwj/202602/t20260228_12321653.html","sourceNote":"2026-11-22 取自浏阳市政府门户「政策文件—市政府与政府办文件」原文页；页面信息时效期2028-07-02。 2026-11-22 收录：与官方页面逐句比对，命中 12/12 句（100%），关卡判定「verbatim」。 有效期依据：页面「信息时效期」标注为2028-07-02，据此确定到期日","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"cs-liuyang-ip-award-2023","title":"浏阳市人民政府办公室关于印发《浏阳市知识产权奖励补助办法》的通知","level":"district","region":"长沙市·浏阳市","issuer":"浏阳市人民政府办公室","documentNo":"浏政办发〔2023〕3号","publishedAt":"2023-03-23","effectiveAt":"2023-03-23","expiresAt":"2028-03-23","status":"active","tags":["财政奖补","研发创新","认定资质"],"audience":["浏阳市域内注册的企业","知识产权服务机构","专利密集型企业"],"summary":"职务发明专利新获中国专利金奖、银奖、优秀奖的企业分别奖励50万元、30万元、10万元；承载高校知识产权转化项目并实际运用的按转化金额10%奖补、最高20万元；新认定国家知识产权示范企业、优势企业分别奖励20万元、10万元；通过知识产权贯标认证的补助初次认证费用不超过2.5万元。","sections":[{"no":"三","title":"奖补对象","text":"本办法奖补对象为我市域内注册的自然人、法人或其他组织，或者为向我市知识产权提供保护和服务的自然人、法人或其他组织。"},{"no":"四","title":"促进知识产权高质量创造","text":"促进知识产权高质量创造。对职务发明专利当年新获中国专利金奖、银奖、优秀奖的企业，分别奖励50万元、30万元、10万元。对职务发明专利当年新获中国外观设计金奖、银奖、优秀奖的企业，分别奖励20万元、10万元、5万元；对知识产权管理制度完善，知识产权运用情况良好，有效发明专利或实用新型专利达10件以上且当年新增有效发明专利达1件以上的专利密集型企业，给予3万元至5万元补助。"},{"no":"五","title":"促进知识产权高效益运用","text":"促进知识产权高效益运用。鼓励企业与高校精准对接，对当年承载高校知识产权转化项目（含知识产权转让、许可、作价入股）并实际运用的企业，按照知识产权当年实际转化金额的10%给予奖补，每家企业最高奖补金额不超过20万元；支持企业通过知识产权质押获得融资，对当年融资额达到500万元的企业给予2万元补助；对团体、协会或其他组织成功注册国家地理标志（含以集体商标或证明商标注册的区域品牌）并运用情况良好的，给予10万元补助（每个地标仅补助一次）。"},{"no":"七","title":"促进知识产权高水平管理","text":"促进知识产权高水平管理。对新认定为国家知识产权示范企业、国家知识产权优势企业的企业，分别奖励20万元、10万元；支持企业通过知识产权贯标认证提高知识产权管理水平，对贯彻实施《企业知识产权管理规范》（GB/T29490—2013），并获得第三方认证的企业，补助初次实际认证费用（不超过2.5万元）；鼓励“湘品出湘”“湘品出境”，对参加商标、地理标志等知识产权展会展览的地理标志或商标区域品牌，每次补助1万元，每年不超过2万元。"}],"interpretations":[{"sectionNo":"三","headline":"浏阳市域内注册的自然人、法人或其他组织均可申报知识产权奖补","who":"我市域内注册的自然人、法人或其他组织；或为我市知识产权提供保护和服务的自然人、法人或其他组织。","materials":[],"window":"按各奖补项目组织申报（原文未列具体申报期）。","where":"浏阳市域内（以注册地或服务对象在浏阳市为界）。","tip":"奖补对象以在浏阳市域内注册，或为我市知识产权提供保护和服务的自然人、法人或其他组织为界。"},{"sectionNo":"四","headline":"中国专利金奖奖励50万元，银奖30万元，优秀奖10万元","who":"职务发明专利当年新获中国专利金奖、银奖、优秀奖的企业；新获中国外观设计金奖、银奖、优秀奖的企业；知识产权管理制度完善、运用情况良好、有效发明专利或实用新型专利达10件以上且当年新增有效发明专利达1件以上的专利密集型企业。","materials":[],"window":"以当年新获奖项、当年新增有效发明专利为认定口径。","where":"浏阳市（按奖项类别申报知识产权奖补）。","tip":"外观设计金奖20万元、银奖10万元、优秀奖5万元；专利密集型企业补助3万元至5万元。"},{"sectionNo":"五","headline":"高校知识产权转化按转化额10%奖补，每家企业最高20万元","who":"当年承载高校知识产权转化项目（含知识产权转让、许可、作价入股）并实际运用的企业；当年知识产权质押融资额达到500万元的企业；成功注册国家地理标志（含以集体商标或证明商标注册的区域品牌）并运用情况良好的团体、协会或其他组织。","materials":[],"window":"按当年实际转化金额、当年融资额计算。","where":"浏阳市（知识产权转化、质押融资、地理标志奖补）。","tip":"地理标志补助10万元、每个地标仅补助一次；质押融资须当年融资额达到500万元才补2万元。"},{"sectionNo":"七","headline":"国家知识产权示范企业奖20万元，优势企业奖10万元","who":"新认定为国家知识产权示范企业、国家知识产权优势企业的企业；贯彻实施《企业知识产权管理规范》（GB/T29490—2013）并获得第三方认证的企业；参加商标、地理标志等知识产权展会展览的地理标志或商标区域品牌。","materials":[],"window":"贯标补助初次实际认证费用；展会补助每年不超过2万元。","where":"浏阳市（知识产权示范、优势企业及贯标认证奖补）。","tip":"贯标补助仅限初次实际认证费用且不超过2.5万元；展会每次补1万元、每年不超过2万元。"}],"sourceUrl":"http://www.liuyang.gov.cn/zwgk/zfxxgk/fdzdgknr/zcwj/xzgfxwj/szfyzfbwj/202602/t20260228_12321652.html","sourceNote":"2026-11-22 取自浏阳市政府门户「政策文件—市政府与政府办文件」原文页；页面信息时效期2028-03-23。 2026-11-22 收录：与官方页面逐句比对，命中 10/10 句（100%），关卡判定「verbatim」。 有效期依据：页面「信息时效期」标注为2028-03-23，据此确定到期日","verified":false,"isSample":false,"numberStyle":"clause","bodyVerified":"verbatim","hunan":true},{"id":"cs-liuyang-scitech-center-2023","title":"浏阳市人民政府关于印发《浏阳市关于全力打造区域科创中心的若干政策措施》的通知","level":"district","region":"长沙市·浏阳市","issuer":"浏阳市人民政府","documentNo":"浏政发〔2023〕9号","publishedAt":"2023-12-20","effectiveAt":"2023-12-20","expiresAt":"2026-12-19","status":"expiring","tags":["研发创新","财政奖补","认定资质"],"audience":["浏阳市域内企业","高新技术企业","科技企业孵化器等创新平台"],"summary":"对上年度研发经费加计扣除总量、增量或占比排名靠前且建立研发准备金制度的企业给予2万元补助；2023年新认定高新技术企业补助4万元/家、重新认定2万元/家；新获中国专利金奖等科技创新平台按级别给10万元、5万元、3万元配套补助；技术合同成交额2000万元以上按1‰补助，最高10万元。","sections":[{"no":"一","title":"引导企业加大研发投入","text":"引导企业加大研发投入。①上年度研发经费投入加计扣除总量在全市排名前40位；②上年度研发经费投入加计扣除增量排名前20位的经开区外企业；③上年度享受研发费用加计扣除政策的研发投入占主营业务收入比例排名前20位且研发投入总量保持正增长并不低于300万元的经开区企业。符合以上条件之一且设立了准备金制度并依法填报研发投入经费年报的企业，给予2万元补助。（企业不重复享受该奖项，如有重复剔除后顺延）"},{"no":"二","title":"壮大高新技术企业队伍","text":"壮大高新技术企业队伍。对2023年新认定的高新技术企业，给予4万元/家的补助；对2023年重新认定的高新技术企业，给予2万元/家的补助（仅限2023年度，以后年度本级不再对高新技术企业认定进行补助）。"},{"no":"三","title":"加强科技平台建设","text":"加强科技平台建设。对通过科技部、省科技厅、长沙市科技局认定、备案（平台备案后须通过上级科技部门验收且验收结果为优秀）或授牌的科技企业孵化器、星创天地、国际科技创新合作基地、引才引智示范基地、技术创新中心、技术转移示范机构、新型研发机构、野外科学观测研究站、重点实验室、工程技术研究中心、科技资源共享服务平台、产业技术创新战略联盟、研发企业（中心）等科技创新平台，分别给予10万元、5万元、3万元配套资金补助[单个科技创新平台（基地）累计最高不超过10万元]。"},{"no":"四","title":"鼓励技术交易","text":"鼓励技术交易。对工商注册、纳税关系在浏阳市的企事业单位，经长沙市技术合同登记点认定的技术合同，年度累计合同成交额2000万元（含）以上的，按其年度累计合同成交额1‰的标准给予卖方补助，最高不超过10万元。年度累计合同项数达到100项（含）以上的，每100项补助1万元，最高不超过3万元。"},{"no":"七","title":"实施“揭榜挂帅”重大科技项目管理制度","text":"实施“揭榜挂帅”重大科技项目管理制度。每年确定5个以内“揭榜挂帅”项目，每个项目支持额度为20万元。"}],"interpretations":[{"sectionNo":"一","headline":"研发投入排名靠前且符合条件的企业，补2万元","who":"①上年度研发经费投入加计扣除总量在全市排名前40位；②上年度研发经费投入加计扣除增量排名前20位的经开区外企业；③上年度享受研发费用加计扣除政策的研发投入占主营业务收入比例排名前20位，且研发投入总量保持正增长并不低于300万元的经开区企业。符合以上条件之一，且设立了准备金制度并依法填报研发投入经费年报的企业。","materials":[],"window":"以上年度研发经费投入加计扣除总量、增量及占主营业务收入比例的排名为评定依据。","where":"浏阳市（经开区外企业按全市排名，经开区企业按区内排名分别评定）。","tip":"同一企业不重复享受该奖项，如有重复剔除后顺延；未设立准备金制度或未依法填报研发投入经费年报的不予补助。"},{"sectionNo":"二","headline":"2023年新认定高企补4万元，重新认定补2万元","who":"2023年新认定的高新技术企业，以及2023年重新认定的高新技术企业；补助仅限2023年度，以后年度本级不再对高新技术企业认定进行补助。","materials":[],"window":"仅限2023年度，以后年度本级不再对高新技术企业认定进行补助。","where":"浏阳市本级（高新技术企业认定补助，仅限2023年度）。","tip":"只补2023年当年新认定和重新认定的企业，以后年度本级不再对高企认定补助。"},{"sectionNo":"三","headline":"科创平台按国家、省、市级分别补助10万、5万、3万元","who":"通过科技部、省科技厅、长沙市科技局认定、备案（平台备案后须通过上级科技部门验收且验收结果为优秀）或授牌的科技企业孵化器、星创天地、技术创新中心、重点实验室、工程技术研究中心、新型研发机构等科技创新平台；单个平台（基地）累计最高不超过10万元。","materials":[],"window":"平台备案后须通过上级科技部门验收且验收结果为优秀，方可获得配套资金补助。","where":"科技部、省科技厅、长沙市科技局（认定、备案或授牌）。","tip":"单个科技创新平台（基地）累计最高不超过10万元，按国家、省、市三级分别为10万元、5万元、3万元。"},{"sectionNo":"四","headline":"技术合同年成交额2000万元以上，按1‰补助卖方最高10万元","who":"工商注册、纳税关系在浏阳市的企事业单位；技术合同须经长沙市技术合同登记点认定；年度累计合同成交额2000万元（含）以上，或年度累计合同项数达到100项（含）以上。","materials":[],"window":"按年度累计合同成交额、年度累计合同项数计算。","where":"长沙市技术合同登记点（技术合同认定）。","tip":"成交额按1‰补助、最高10万元；合同项数每100项补1万元、最高3万元。"},{"sectionNo":"七","headline":"每年5个以内揭榜挂帅项目，每个支持20万元","who":"承担浏阳市“揭榜挂帅”重大科技项目的揭榜单位（原文未列具体申报门槛）。","materials":[],"window":"每年确定5个以内“揭榜挂帅”项目，按年度组织。","where":"浏阳市（“揭榜挂帅”重大科技项目管理制度）。","tip":"项目数量每年控制在5个以内，单个项目支持额度20万元。"}],"sourceUrl":"http://www.liuyang.gov.cn/zwgk/zfxxgk/fdzdgknr/zcwj/xzgfxwj/szfyzfbwj/202602/t20260228_12321657.html","sourceNote":"2026-11-22 取自浏阳市政府门户「政策文件—市政府与政府办文件」原文页；页面信息时效期2026-12-19，落在有效期内。 2026-11-22 收录：与官方页面逐句比对，命中 12/12 句（100%），关卡判定「verbatim」。 有效期依据：原文明示「自2023年12月20日起实施，有效期3年」，推算至2026-12-19，与页面信息时效期一致","verified":false,"isSample":false,"numberStyle":"clause","bodyVerified":"verbatim","hunan":true},{"id":"cs-liuyang-startup-20-2025","title":"浏阳市人民政府办公室关于印发《浏阳市支持大学生创业二十条》的通知","level":"district","region":"长沙市·浏阳市","issuer":"浏阳市人民政府办公室","documentNo":"浏政办发〔2025〕1号","publishedAt":"2025-03-20","effectiveAt":"2025-03-20","expiresAt":"2029-11-30","status":"active","tags":["创业补贴","场地支持","贷款贴息"],"audience":["来浏创业的大学生","大学生初创企业","创业孵化基地入驻项目"],"summary":"大学生创业项目入驻指定孵化基地可获首年场地租金和管理费全额补贴、次年补贴50%，基地外注册的两年内每月最高800元租金补贴；初创企业按实际有效投入不超过50%最高补贴10万元，另可获最高2万元一次性创业补贴；个人创业担保贷款最高30万元、小微企业最高400万元，财政按实际利率50%贴息。","sections":[{"no":"一（二）","title":"实施场地补贴政策","text":"（二）实施场地补贴政策。对入驻指定创业孵化基地的大学生创业项目，给予首年办公场地租金和管理费用全额补贴，次年补贴50％；对在创业孵化基地以外注册且符合相关条件的大学生创业项目，给予两年内每月最高800元的办公场地租金补贴。［责任单位：市人力资源社会保障局、经开区、市农业科技园发展中心、市鞭炮烟花产业发展中心（市文化创意产业发展中心）］"},{"no":"一（三）","title":"实施创业补贴政策","text":"（三）实施创业补贴政策。对符合相关条件的大学生初创企业，按照不超过申报企业实际有效投入的50％，最高给予10万元的项目补贴；对大学生初创企业，根据实际投入、带动就业人数，最高给予2万元的一次性创业补贴。具体实施细则由市人力资源社会保障部门另行制定。（责任单位：市人力资源社会保障局、市财政局）"},{"no":"二（六）","title":"提供贴息贷款","text":"（六）提供贴息贷款。大学生个人创业的，最高可申请30万元的创业担保贷款；合伙创业、创办小微企业的，根据合伙创业人数、小微企业新增吸纳就业人数，最高可申请400万元的创业担保贷款。创业担保贷款利息由财政部门按贷款实际利率的50％给予贴息。（责任单位：市人力资源社会保障局、市财政局）"},{"no":"六（十八）","title":"组织创业竞赛","text":"（十八）组织创业竞赛。举办大学生创业创新大赛，选送优质项目参加上级赛事，对获得国家级赛事一、二、三等奖的，分别给予10万元、8万元、5万元奖励；对获得省级赛事一、二、三等奖的，分别给予5万元、4万元、3万元奖励；对获得浏阳赛事一、二、三等奖的，分别给予4万元、3万元、2万元奖励。（责任单位：市人力资源社会保障局、市融媒中心、市科技局、市工业和信息化局、市财政局、市农业农村局、市商务局、市总工会、团市委）"}],"interpretations":[{"sectionNo":"一（二）","headline":"基地外创业每月最高补800元租金，基地内首年全免","who":"入驻指定创业孵化基地的大学生创业项目：首年办公场地租金和管理费用全额补贴，次年补贴50％；在创业孵化基地以外注册且符合相关条件的大学生创业项目：两年内每月最高800元办公场地租金补贴。","materials":[],"window":"基地内首年全额、次年50％；基地外补贴期限为两年内。","where":"指定创业孵化基地；责任单位：市人力资源社会保障局、经开区、市农业科技园发展中心、市鞭炮烟花产业发展中心（市文化创意产业发展中心）。","tip":"基地外按每月最高800元补贴，不是按实际租金全额；两类主体分别向孵化基地和属地责任单位申报。"},{"sectionNo":"一（三）","headline":"大学生初创企业按投入50％补，最高10万元","who":"符合相关条件的大学生初创企业：按不超过申报企业实际有效投入的50％、最高10万元项目补贴；根据实际投入、带动就业人数，最高2万元一次性创业补贴。","materials":[],"window":"一次性补贴；具体实施细则由市人力资源社会保障部门另行制定。","where":"浏阳市人力资源社会保障局、市财政局。","tip":"项目补贴不超过实际有效投入的50％、最高10万元；一次性创业补贴最高2万元。"},{"sectionNo":"二（六）","headline":"个人创业担保贷款最高30万元，小微企业最高400万元","who":"大学生个人创业：最高30万元创业担保贷款；合伙创业、创办小微企业：根据合伙创业人数、小微企业新增吸纳就业人数，最高400万元；利息由财政部门按贷款实际利率的50％给予贴息。","materials":[],"window":"贴息按贷款实际利率的50％执行；本条未写贷款期限。","where":"浏阳市人力资源社会保障局、市财政局。","tip":"合伙创业与小微企业额度按合伙人数、新增吸纳就业人数确定，最高400万元。"},{"sectionNo":"六（十八）","headline":"创业大赛国家级一等奖奖10万元，浏阳赛区一等奖4万元","who":"参加大学生创业创新大赛的项目：国家级一、二、三等奖分别10万元、8万元、5万元；省级5万元、4万元、3万元；浏阳赛事4万元、3万元、2万元。","materials":[],"window":"按赛事获奖等次一次性奖励。","where":"浏阳市人力资源社会保障局、市融媒中心、市科技局等责任单位。","tip":"奖励按赛事级别和获奖等次分档，国家级、省级、浏阳赛事标准不同。"}],"sourceUrl":"http://www.liuyang.gov.cn/zwgk/zfxxgk/fdzdgknr/zcwj/xzgfxwj/szfyzfbwj/202602/t20260228_12321669.html","sourceNote":"2026-11-22 取自浏阳市政府门户「政策文件—行政规范性文件—市政府与政府办文件」原文页，文号、公布日期、信息时效期均按页面标注核对。 2026-11-22 收录：与官方页面逐句比对，命中 15/15 句（100%），关卡判定「verbatim」。 有效期依据：原文明示「自2025年3月20日起施行，有效期至2029年11月30日」，页面信息时效期同为2029-11-30","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"cs-liuyang-tech-fund-2023","title":"浏阳市人民政府办公室关于印发《浏阳市科技计划项目及专项资金管理办法》的通知","level":"district","region":"长沙市·浏阳市","issuer":"浏阳市人民政府办公室","documentNo":"浏政办发〔2023〕13号","publishedAt":"2023-12-20","effectiveAt":"2023-12-20","expiresAt":"2026-12-19","status":"expiring","tags":["专项资金","研发创新"],"audience":["浏阳市注册的企事业单位","高新技术企业","科技型中小企业"],"summary":"科技计划项目按重大专项、重点项目、一般项目、指令性项目分类支持：重大专项10万—20万元，重点项目6万—10万元，一般项目3万—5万元，一般项目和重点项目申报单位须为具独立法人资格的医疗机构、事业单位、科研机构或有效高新技术企业、备案在库科技型中小企业。","sections":[{"no":"五","title":"","text":"市科技计划项目采取事前立项事后补助和前资助两类资金支持方式，并根据支持方式的不同进行分类管理。"},{"no":"六","title":"","text":"市科技计划项目按照重大专项、重点项目、一般项目、指令性项目分类支持。"},{"no":"六（一）","title":"重大专项","text":"（一）重大专项项目支持金额10万元—20万元，聚焦浏阳市经济社会发展重点领域，主要支持重大关键共性技术攻关、重大科技成果转化和重大科技合作项目，该计划根据科技发展需求单独发布申报指南。原则上采取前资助方式。"},{"no":"六（二）","title":"重点项目、一般项目","text":"（二）重点项目支持金额6万元—10万元、一般项目支持金额3万元—5万元，采取事前立项事后补助方式支持，申报单位为具有独立法人资格医疗机构、事业单位、科研机构，及有效的国家高新技术企业或备案在库的科技型中小企业。"},{"no":"六（三）","title":"指令性项目","text":"（三）指令性项目主要支持上级文件或市委市政府确定的重点工作和应急性任务，由市科技局以自上而下的方式组织实施。原则上采取前资助方式。"}],"interpretations":[{"sectionNo":"五","headline":"科技项目资金分事前立项事后补助、前资助两种","who":"申报浏阳市科技计划项目的单位；资金按事前立项事后补助与前资助两类方式分类管理。","materials":[],"window":"按支持方式分类管理，具体方式随项目类别在立项环节确定。","where":"浏阳市科技计划项目资金（市科技局管理）","tip":"前资助在立项阶段投入，事后补助在立项后拨付，资金到位时点不同，申报时需对应项目类别的支持方式。"},{"sectionNo":"六（一）","headline":"重大专项支持10万至20万元，原则上采取前资助","who":"聚焦浏阳市经济社会发展重点领域，承担重大关键共性技术攻关、重大科技成果转化或重大科技合作项目的单位；按该计划单独发布的申报指南申报。","materials":[],"window":"根据科技发展需求单独发布申报指南，按指南组织申报。","where":"重大专项申报指南（单独发布）","tip":"原则上采取前资助方式，须按单独发布的申报指南申报，与重点项目、一般项目的事后补助方式不同。"},{"sectionNo":"六（二）","headline":"重点项目补6万至10万、一般项目补3万至5万，事后补助","who":"具有独立法人资格的医疗机构、事业单位、科研机构，以及有效的国家高新技术企业或备案在库的科技型中小企业。","materials":[],"window":"采取事前立项事后补助方式，立项在前、补助在后。","where":"市科技局（市科技计划项目立项与补助管理）","tip":"重点项目与一般项目均为事后补助，申报单位须属于规定的五类主体之一。"},{"sectionNo":"六（三）","headline":"指令性项目由市科技局自上而下组织，原则上前资助","who":"承担上级文件或市委市政府确定的重点工作和应急性任务的单位；由市科技局以自上而下的方式组织实施。","materials":[],"window":"按上级文件或市委市政府确定的重点工作和应急性任务安排组织实施。","where":"市科技局","tip":"原则上采取前资助方式；项目由市科技局自上而下确定，不经过公开申报竞争。"}],"sourceUrl":"http://www.liuyang.gov.cn/zwgk/zfxxgk/fdzdgknr/zcwj/xzgfxwj/szfyzfbwj/202602/t20260228_12321656.html","sourceNote":"2026-11-22 取自浏阳市政府门户「政策文件—市政府与政府办文件」原文页；页面信息时效期2026-12-19。 2026-11-22 收录：与官方页面逐句比对，命中 5/5 句（100%），关卡判定「verbatim」。 有效期依据：页面「信息时效期」标注为2026-12-19，据此确定到期日","verified":false,"isSample":false,"numberStyle":"clause","bodyVerified":"verbatim","hunan":true},{"id":"cs-liuyang-wusiburao-2025","title":"浏阳市人民政府办公室印发《浏阳市关于推行涉企行政执法“无事不扰”监管服务工作措施》的通知","level":"district","region":"长沙市·浏阳市","issuer":"浏阳市人民政府办公室","documentNo":"浏政办发〔2025〕6号","publishedAt":"2025-09-12","effectiveAt":"2025-09-12","expiresAt":"2027-09-11","status":"active","tags":["营商环境"],"audience":["浏阳市域内企业","个体工商户"],"summary":"将每月1日至15日设为企业“宁静日”，除国家安全、公共安全、专项检查等6类情形外不得入企现场检查；按上年度检查处罚、信用、风险等情况将企业分为红黄绿牌分类监管，绿牌原则上减少或避免现场检查，并推行涉企非现场监管事项清单。","sections":[{"no":"一（一）","title":"设置企业“宁静日”","text":"（一）设置企业“宁静日”。将每月1日至15日设定为企业“宁静日”，在此期间，除下列法定或特定情形外，任何行政执法单位不得对企业开展现场行政检查："},{"no":"一（二）","title":"规范例外审批程序","text":"（二）规范例外审批程序。符合上述6类情形，确需在企业“宁静日”期间开展现场检查的，各行政执法单位应填写《“无事不扰”入企执法检查审批表》（详见附件），其中第1—3项的检查须经市政府分管负责人审批同意；第4—6项的检查须经各行政执法单位主要负责人审签同意。启动例外审批程序的行政执法单位应及时向市司法局备案（每月20日前将审批资料报市司法局）。执法人员入企检查时，应当主动出示本单位审批文件及有效执法证件。"},{"no":"二（一）","title":"评定机制","text":"（一）评定机制。各行政执法单位应当根据企业上一年度接受检查、行政处罚、信用状况、安全生产、风险等级、投诉举报处理、配合整改等情况，对企业实施分类分级监管。分类分级结果由各行政执法单位在每年年初进行动态调整并报市司法局备案，且须在市政府门户网站进行公示。"},{"no":"三（一）","title":"梳理“无扰清单”","text":"（一）梳理“无扰清单”。各行政执法单位应当依据本部门涉企行政检查事项清单，全面梳理可通过书面核查、在线监测、信息共享、智慧监管平台、大数据筛查等非现场方式实现有效监管目标的事项，形成本单位《涉企非现场监管事项清单》，报市司法局备案后，在市政府门户网站进行公示。"}],"interpretations":[{"sectionNo":"一（一）","headline":"每月1日至15日为企业宁静日，除特定情形不得现场检查","who":"浏阳市域内企业；在每月1日至15日“宁静日”期间，除法定或特定情形外，任何行政执法单位不得对其开展现场行政检查。","materials":[],"window":"每月1日至15日，按月循环。","where":"浏阳市各行政执法单位（市司法局监督）。","tip":"“宁静日”不等于免检：法定或特定情形仍可检查，但须按例外程序审批。"},{"sectionNo":"一（二）","headline":"宁静日入企检查须先审批，并出示审批文件和执法证件","who":"在“宁静日”期间被现场检查的浏阳市企业；检查须符合6类法定或特定情形，第1—3项经市政府分管负责人审批同意，第4—6项经各行政执法单位主要负责人审签同意。","materials":["《“无事不扰”入企执法检查审批表》（详见附件）"],"window":"每月20日前将审批资料报市司法局备案；检查前须完成审批。","where":"市司法局（备案）；市政府分管负责人、各行政执法单位主要负责人（审批）。","tip":"第1—3项与第4—6项审批层级不同；执法人员入企应主动出示本单位审批文件及有效执法证件。"}],"sourceUrl":"http://www.liuyang.gov.cn/zwgk/zfxxgk/fdzdgknr/zcwj/xzgfxwj/szfyzfbwj/202602/t20260228_12321673.html","sourceNote":"2026-11-22 取自浏阳市政府门户「政策文件—市政府与政府办文件」原文页；页面信息时效期2027-09-11。 2026-11-22 收录：与官方页面逐句比对，命中 8/8 句（100%），关卡判定「verbatim」。 有效期依据：原文明示「自2025年9月12日起实施，有效期2年」，推算至2027-09-11，与页面信息时效期一致","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"cs-logistics-fund-2026-4","title":"长沙市人民政府物流与口岸办公室 长沙市财政局关于印发《长沙市现代物流发展专项资金管理办法（修订版）》的通知","level":"city","region":"长沙市","issuer":"长沙市人民政府物流与口岸办公室、长沙市财政局","documentNo":"长物口办发〔2026〕4号","publishedAt":"2026-05-22","effectiveAt":"2026-06-25","expiresAt":"2031-06-24","status":"active","tags":["专项资金","财政奖补"],"audience":["物流企业","多式联运经营人","快递企业","仓储设施建设主体"],"summary":"五星、四星、三星通用仓库分别奖励最高20万元、10万元、5万元；信息化与智能化设备投入按年度投资额10%奖励、每家最高100万元；开行铁路内贸班列按100元/大柜奖励、每家最高100万元。","sections":[{"no":"第六条（一）","title":"提质物流基础设施","text":"科学集约布局建设大型仓储物流设施，对符合竣工验收规定的项目，一次性给予建设主体不超过30元/平方米的奖励。对首次评为国家五星、四星、三星通用仓库的物流企业，分别一次性给予每家企业不超过20万元、10万元、5万元奖励。支持物流设施设备标准化、智能化、数智化建设，提高流通组织能力和效率，对物流企业信息化投入，实施标准化设施设备改造，购置物流机器人、快递无人机、自动分拣设备、安防设备等新型智能化物流设施设备，按年度实际完成投资额的10%给予奖励，每家企业不超过100万元。"},{"no":"第六条（二）","title":"培育壮大现代物流企业","text":"实施现代化物流龙头企业培育行动，对新增入规且营收相比上年度实现稳定增长的多式联运和运输代理业企业、装卸搬运和仓储业企业，一次性给予每家企业5万元奖励。对首次评为国家5A、4A、3A的物流企业，分别一次性给予每家企业不超过30万元、20万元、10万元奖励。制定市示范物流企业认定办法，每年认定10家示范物流企业，一次性给予每家示范企业20万元奖励。"},{"no":"第六条（三）","title":"支持多式联运发展","text":"加快健全多式联运体系，开展优化运输结构行动，大力推进“公转铁”、“公转水”。支持开行常态化铁路内贸班列，按年度发运量给予100元/大柜的奖励，每家企业不超过100万元。鼓励航运企业常态化开行长沙港往返内支线港口航线，对开行航次较上年度增量部分，给予航运企业5000元/航次的奖励，每家企业不超过100万元。鼓励航运企业为长沙整车生产厂提供稳定的商品汽车滚装运输服务，对年度发运滚装车辆给予20元/台的奖励，每家企业不超过100万元。大力推进铁水联运业务发展，对以进港铁路为节点开展铁水联运业务的主体，给予20元/大柜的奖励，每家企业不超过100万元。"},{"no":"第六条（六）","title":"促进快递行业高质量发展","text":"建立农村物流基础设施共享共用新机制，对快递企业在行政村建设共建共享快递服务网点且正常运营1年以上的，一次性给予每个网点2万元奖励。对在乡（镇）、行政村投放具有无人机接驳功能智能快递柜的快递企业，一次性给予每个快递柜2万元奖励。"}],"interpretations":[{"sectionNo":"第六条（一）","headline":"仓储设施竣工奖30元/平方米，智能设备投入奖10%","who":"符合竣工验收规定的大型仓储物流设施建设主体；首次评为国家五星、四星、三星通用仓库的物流企业；实施标准化设施设备改造，购置物流机器人、快递无人机、自动分拣设备、安防设备等新型智能化物流设施设备的物流企业。","materials":[],"window":"原文未设申报期；信息化投入按年度实际完成投资额计算，每家企业不超过100万元。","where":"市物流与口岸办公室、市财政局（专项资金管理）","tip":"设施奖励按竣工验收一次性给予，每平方米不超过30元；星级仓库为一次性奖励，五星20万元、四星10万元、三星5万元；信息化投入按10%奖励且每家企业上限100万元。"},{"sectionNo":"第六条（二）","headline":"首次评5A奖30万，入规企业奖5万，示范企业奖20万","who":"新增入规且营收相比上年度实现稳定增长的多式联运和运输代理业企业、装卸搬运和仓储业企业；首次评为国家5A、4A、3A的物流企业；经市示范物流企业认定办法认定的示范物流企业。","materials":[],"window":"每年认定10家示范物流企业；入规奖励、星级奖励均为一次性。","where":"市物流与口岸办公室、市财政局（专项资金管理）","tip":"入规奖励要求“新增入规”且营收较上年度稳定增长；星级奖励仅限首次获评，5A为30万元、4A为20万元、3A为10万元；示范企业每年10家、每家20万元。"},{"sectionNo":"第六条（三）","headline":"铁路内贸班列奖100元/大柜，航线增量奖5000元/航次","who":"开行常态化铁路内贸班列的运营主体；常态化开行长沙港往返内支线港口航线、开行航次较上年度有增量的航运企业；为长沙整车生产厂提供商品汽车滚装运输的航运企业；以进港铁路为节点开展铁水联运业务的主体。","materials":[],"window":"按年度发运量、开行航次、年度发运滚装车辆结算，每家企业每项不超过100万元。","where":"市物流与口岸办公室、市财政局（专项资金管理）","tip":"航线奖励只算较上年度的增量航次；铁路班列100元/大柜、滚装20元/台、铁水联运20元/大柜，每家企业每项均以100万元封顶。"},{"sectionNo":"第六条（六）","headline":"行政村共建快递网点运营满1年奖2万，智能柜每个奖2万","who":"在行政村建设共建共享快递服务网点且正常运营1年以上的快递企业；在乡（镇）、行政村投放具有无人机接驳功能智能快递柜的快递企业。","materials":[],"window":"网点须正常运营1年以上；网点与快递柜奖励均为一次性。","where":"市物流与口岸办公室、市财政局（专项资金管理）","tip":"网点奖励要求“共建共享”且运营满1年，未满1年不符合；智能快递柜须具有无人机接驳功能，普通柜不在奖励范围。"}],"sourceUrl":"https://www.changsha.gov.cn/zfxxgk/zfwjk/gdwxtwj/202605/t20260522_12389829.html","sourceNote":"2026-11-21 取自长沙市人民政府门户「政策文件—各单位系统文件」原文页；页面标注文号长物口办发〔2026〕4号、公布日期2026-05-22、信息时效期2031-06-24。条文为页面正文逐字摘录。 2026-11-21 收录：与官方页面逐句比对，命中 13/13 句（100%），关卡判定「verbatim」。 有效期依据：原文明示施行日期；原文未单独表述有效期，以页面登记的信息时效期2031-06-24为准。","verified":false,"isSample":false,"numberStyle":"clause","bodyVerified":"verbatim","hunan":true},{"id":"cs-msme-2023","title":"长沙市进一步促进中小企业稳增长调结构强能力若干措施","level":"city","region":"长沙市","issuer":"长沙市人民政府办公室","documentNo":"长工信中小发〔2023〕53号","publishedAt":"2023-11-14","effectiveAt":null,"expiresAt":null,"status":"active","tags":["认定资质","财政奖补","融资支持"],"audience":["长沙市中小企业","专精特新“小巨人”企业","制造业单项冠军企业"],"summary":"中小企业新认定为国家级专精特新“小巨人”奖励50万元；新认定国家级制造业单项冠军企业奖励200万元、单项冠军产品奖励100万元。","sections":[{"no":"8","title":"加大优质中小企业梯度培育力度","text":"到2025年，新培育创新型中小企业2000家、专精特新中小企业500家，新增专精特新“小巨人”企业150家、制造业单项冠军企业10家。中小企业被新认定为国家级专精特新“小巨人”企业的，奖励50万元。"},{"no":"8续","title":"单项冠军奖励","text":"中小企业被新认定为国家级制造业单项冠军企业的，奖励200万元；中小企业有产品被新认定为国家级制造业单项冠军产品的，奖励100万元，同一企业不同产品的奖励可以累计。"},{"no":"8续二","title":"信贷风险补偿额度","text":"将专精特新“小巨人”企业和专精特新北交所上市培育库企业在市小微企业信贷风险补偿基金项下的信用类贷款额度提升至1000万元。"},{"no":"9","title":"专精特新企业上市专项行动","text":"2023年到2025年，从专精特新“小巨人”企业和专精特新中小企业中优中选优，集中政策资源重点培育一批上市后备企业。综合运用政府性基金、项目贷款贴息，引导股权投资机构和商业银行提供低成本资金支持，帮助企业发展上台阶，稳步达到上市条件。"},{"no":"7","title":"加强校企人才合作","text":"上下联动大力实施中小企业经营管理人才培训，优化中小企业职称评审工作，帮助符合条件的专精特新“小巨人”企业备案设立博士后科研工作站。"}],"interpretations":[{"sectionNo":"8","headline":"新认定国家级专精特新“小巨人”，奖励50万元","who":"长沙市中小企业；须被新认定为国家级专精特新“小巨人”企业。","materials":[],"window":"到2025年培育目标为创新型中小企业2000家、专精特新中小企业500家、小巨人150家、制造业单项冠军10家；奖励对应新认定。","where":"原文未列明受理窗口或系统。","tip":"奖励条件是“新认定”，存量已认定企业不在此列。"},{"sectionNo":"8续","headline":"国家级制造业单项冠军企业奖200万元，产品奖100万元","who":"长沙市中小企业；新认定为国家级制造业单项冠军企业，或产品新认定为国家级制造业单项冠军产品。","materials":[],"window":"按新认定兑现；同一企业不同产品的奖励可以累计。","where":"原文未列明受理窗口或系统。","tip":"企业奖200万元与产品奖100万元分设；同一企业不同产品的奖励可以累计。"},{"sectionNo":"8续二","headline":"小巨人及北交所培育库企业，信用贷额度提至1000万元","who":"长沙市专精特新“小巨人”企业和专精特新北交所上市培育库企业；须在市小微企业信贷风险补偿基金项下申请信用类贷款。","materials":[],"window":"按基金项下信用类贷款办理，原文未设申报期限。","where":"市小微企业信贷风险补偿基金。","tip":"提升的是信用类贷款额度，至1000万元；适用对象仅限小巨人和专精特新北交所上市培育库企业。"},{"sectionNo":"9","headline":"2023至2025年，从小巨人、专精特新企业中培育上市后备","who":"长沙市专精特新“小巨人”企业和专精特新中小企业；经优中选优纳入上市后备培育。","materials":[],"window":"2023年到2025年集中培育。","where":"原文未列明具体申报窗口或系统。","tip":"培育对象从两类企业中优中选优；支持方式为政府性基金、项目贷款贴息，并引导股权投资机构和商业银行提供低成本资金。"},{"sectionNo":"7","headline":"中小企业人才培训、职称评审优化，小巨人可设博士后站","who":"长沙市中小企业经营管理人才，可参加人才培训、职称评审；符合条件的专精特新“小巨人”企业，可备案设立博士后科研工作站。","materials":[],"window":"常态化实施，原文未设申报期限。","where":"原文未列明受理部门或系统。","tip":"博士后科研工作站只面向符合条件的专精特新“小巨人”企业，且须备案设立。"}],"sourceUrl":"https://www.hunan.gov.cn/zqt/zcsd/202311/t20231114_32404547.html","sourceNote":"2026-11-21 取自省门户「政策速递」转载页（长沙市政府文件由省门户转载）；页面未标注文号，已在 documentNo 如实记录。原始发文页未检出，标为转载页。 2026-11-21 收录：与官方页面逐句比对，命中 8/8 句（100%），关卡判定「verbatim」。 有效期依据：原文未设期限；按行政规范性文件一般不超5年推算至2028-11 2026-11-21 补录：documentNo 据官方页面版头/落款核对后填入。","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"cs-relief-2022","title":"长沙市人民政府办公厅关于纾解长沙市中小企业困难的若干意见","level":"city","region":"长沙市","issuer":"长沙市人民政府办公厅","documentNo":"","publishedAt":"2022-03-15","effectiveAt":"2022-03-15","expiresAt":"2022-09-14","status":"expired","tags":["融资支持","贷款贴息","就业补贴"],"audience":["长沙市规上制造业小微企业","缺少担保抵押的轻资产中小企业"],"summary":"对贷款200万元以上且2021年实缴税收30万元以上的规上制造业小微企业，按2021年实际贷款利息支出的15%给予贴息，单个企业最高不超过10万元。","sections":[{"no":"二(2)","title":"扩大股权投资规模","text":"对拟上市“专精特新”中小企业开展分类指导、精准培育、投融资对接，提高企业在资本市场融资的能力；运用产业投资基金、中小微企业发展基金引导社会资本扩大对“专精特新”中小企业的股权投资规模；支持更多符合条件的“专精特新”中小企业在科创板、创业板、北交所上市融资。"},{"no":"二(3)","title":"规上企业贷款贴息","text":"对贷款200万元以上且2021年实缴税收30万元以上的规上制造业小微企业，按2021年期间实际贷款利息支出的15%计算给予贴息，单个企业贴息额最高不超过10万元。贷款贴息资金，由市本级财政、企业所在区县（市）财政各承担50%。享受“专精特新”小巨人贷款贴息政策的企业不适用本条政策。"},{"no":"二(1)","title":"助力中小企业开拓市场","text":"组织中小企业参加中国国际中小企业博览会、APEC中小企业技术交流暨展览会等境内外展会，积极开拓国内外市场；鼓励中小企业申报长沙市两型产品目录，推出拥有自主知识产权、市场前景好的产品。"},{"no":"三","title":"政策叠加规则","text":"本文件政策与其他政策重复、类同的，同一企业、同一项目按就高不就低、不重复享受的原则执行。"}],"interpretations":[{"sectionNo":"二(2)","headline":"拟上市“专精特新”中小企业可获上市培育和产业基金股权投资","who":"长沙市拟上市的“专精特新”中小企业，以及符合科创板、创业板、北交所上市融资条件的“专精特新”中小企业。","materials":[],"window":"按分类指导、精准培育、投融资对接常态化推进，原文未设申报截止时间。","where":"产业投资基金、中小微企业发展基金及上市培育对接渠道","tip":"本条为支持方向，未明确补贴金额和申报材料；股权投资由基金按市场化方式决策。"},{"sectionNo":"二(3)","headline":"规上制造业小微企业贷款贴息：按利息15%补，最高10万元","who":"长沙市规上制造业小微企业，2021年贷款200万元以上且2021年实缴税收30万元以上。","materials":[],"window":"按2021年期间实际贷款利息支出的15%计算贴息，申报截止时间原文未明确。","where":"市本级财政、企业所在区县（市）财政","tip":"单个企业贴息最高不超过10万元；市本级财政与企业所在区县（市）财政各承担50%；已享受“专精特新”小巨人贷款贴息的企业不适用。"},{"sectionNo":"二(1)","headline":"中小企业可参展境内外展会，并申报长沙市两型产品目录","who":"长沙市中小企业；申报两型产品目录的产品须拥有自主知识产权、市场前景好。","materials":[],"window":"按展会组织和两型产品目录申报安排推进，原文未列具体时间。","where":"中国国际中小企业博览会、APEC中小企业技术交流暨展览会；长沙市两型产品目录","tip":"参展由部门统一组织；目录申报看重自主知识产权和市场前景，原文未列补贴标准。"}],"sourceUrl":"https://www.changsha.gov.cn/zfxxgk/zfwjk/szfbgt/202203/P020220315580059075218.pdf","sourceNote":"2026-11-21 取自长沙市政府门户「政府文件库—市政府办公厅」原文（PDF 直链）；有效期6个月原句已逐字核对，基准日已过，判失效。保留作历史口径对照。 2026-11-21 收录：与官方页面逐句比对，命中 9/9 句（100%），关卡判定「verbatim」。 有效期依据：原文明示（自公布之日起施行、有效期6个月），自2022-03-15起算已于2022-09-14到期","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"cs-service-trade-fund-2026-8","title":"长沙市商务局 长沙市财政局关于印发《长沙市服务贸易及服务外包产业发展专项资金管理办法》的通知","level":"city","region":"长沙市","issuer":"长沙市商务局、长沙市财政局","documentNo":"长商务发〔2026〕8号","publishedAt":"2026-03-03","effectiveAt":"2026-03-03","expiresAt":"2028-03-02","status":"active","tags":["外贸外资","专项资金","财政奖补"],"audience":["服务外包企业","服务贸易经营主体","行业协会","公共服务平台"],"summary":"离岸服务外包按业务规模和离岸执行额贡献每家支持不超过100万元；在岸服务外包每家不超过50万元；首次突破50万美元的企业支持不超过10万元；公共平台每年不超过20万元/家。","sections":[{"no":"第六条","title":"推动离岸服务外包转型升级","text":"根据企业离岸服务外包业务收入规模、完成服务外包离岸执行额贡献度等综合评定，每家给予不超过100万元的支持。对新纳入商务部业务统一平台，当年度离岸服务外包执行额首次突破50万美元的企业，根据其执行额每家给予不超过10万元的支持，对其下一年度实现业务持续增长，离岸服务外包执行额达到更高规模的企业，根据综合评定每家给予不超过20万元的支持"},{"no":"第七条","title":"扶持在岸服务外包业务发展","text":"根据其上年度在岸服务外包业务收入规模、完成服务外包在岸执行额贡献度等综合评定，每家给予不超过50万元的支持。对新纳入商务部业务统一平台，且当年度在岸服务外包执行额达到一定规模的企业，根据综合评定每家给予不超过10万元的支持，对其下一年度实现业务持续增长，在岸服务外包执行额达到更高规模的企业，根据综合评定每家给予不超过20万元的支持。"},{"no":"第八条","title":"支持公共平台发挥作用","text":"对行业协会、公共平台开展的业务培训、组织会展、行业调查、统计分析等活动的投入给予每年不超过20万元/家的支持。"},{"no":"第三条","title":"","text":"本办法支持对象是指依法注册、纳税，且纳入“商务部业务系统统一平台服务贸易统计监测管理应用”（以下简称“商务部业务统一平台”）的从事服务贸易或服务外包的经营主体或为该经营主体提供相关公共服务的平台机构等。"}],"interpretations":[{"sectionNo":"第三条","headline":"服务贸易、服务外包主体须入商务部统一平台方可申报","who":"依法注册、纳税，且已纳入“商务部业务系统统一平台服务贸易统计监测管理应用”的从事服务贸易或服务外包的经营主体，以及为该经营主体提供相关公共服务的平台机构。","materials":[],"window":"按年度专项资金申报组织，原文未设申报期。","where":"商务部业务系统统一平台服务贸易统计监测管理应用（“商务部业务统一平台”）","tip":"未纳入商务部业务统一平台的经营主体不符合支持对象条件；依法注册、纳税与平台入库是三项并列前提。"},{"sectionNo":"第六条","headline":"离岸服务外包最高支持100万，首破50万美元另补10万","who":"从事离岸服务外包的企业：按业务收入规模、离岸执行额贡献度综合评定；新纳入商务部业务统一平台且当年度离岸执行额首次突破50万美元的，另按执行额支持。","materials":[],"window":"按年度评定；首次突破按当年度执行额，业务增长支持看下一年度执行额是否达到更高规模。","where":"商务部业务统一平台（业务数据口径）；专项资金按年度申报受理","tip":"100万元档看收入规模与贡献度综合评定；首次突破50万美元只给10万元以内，次年达到更高规模再按20万元以内评定。"},{"sectionNo":"第七条","headline":"在岸服务外包最高支持50万，新入库企业最高10万","who":"从事在岸服务外包的企业：按上年度业务收入规模、在岸执行额贡献度综合评定；新纳入商务部业务统一平台且当年度在岸执行额达到一定规模的，另按10万元以内支持。","materials":[],"window":"按年度评定；主档看上年度数据，新增档看当年度，增长档看下一年度。","where":"商务部业务统一平台（业务数据口径）；专项资金按年度申报受理","tip":"在岸档低于离岸档：综合评定最高50万元；新入库按10万元以内，次年达到更高规模按20万元以内。"},{"sectionNo":"第八条","headline":"行业协会、公共平台办培训会展等，每年最高20万元/家","who":"开展业务培训、组织会展、行业调查、统计分析等活动的行业协会、公共平台。","materials":[],"window":"每年不超过20万元/家；按年度申报。","where":"按年度专项资金申报受理（原文未列具体部门或系统）","tip":"支持按“家”计，每年每家封顶20万元；活动范围限于业务培训、会展、行业调查、统计分析四类投入。"}],"sourceUrl":"https://www.changsha.gov.cn/zfxxgk/zfwjk/gdwxtwj/202603/t20260304_12327529.html","sourceNote":"2026-11-21 取自长沙市人民政府门户「政策文件—各单位系统文件」原文页；页面标注文号长商务发〔2026〕8号、公布日期2026-03-03、信息时效期2028-03-02。条文为页面正文逐字摘录。 2026-11-21 收录：与官方页面逐句比对，命中 6/6 句（100%），关卡判定「verbatim」。 有效期依据：原文明示“自2026年3月3日起施行，有效期2年”；页面登记信息时效期2028-03-02，一致。","verified":false,"isSample":false,"numberStyle":"clause","bodyVerified":"verbatim","hunan":true},{"id":"cs-short-drama-2026-5","title":"关于印发《长沙市关于支持微短剧产业高质量发展的若干措施（试行）》的通知","level":"city","region":"长沙市","issuer":"长沙市文化旅游广电局等部门","documentNo":"长文旅广电联〔2026〕5号","publishedAt":"2026-03-03","effectiveAt":"2026-03-03","expiresAt":"2027-03-02","status":"active","tags":["财政奖补","外贸外资","场地支持"],"audience":["微短剧制作企业","拍摄基地运营方","视频平台","行业协会"],"summary":"园区（基地）年拍摄微短剧500部、1000部及以上的分别给予最高50万元等支持；文化出海翻译制作费用给予50%译制补贴、单个企业最高不超过20万元；智慧化服务平台单个项目最高50万元。","sections":[{"no":"一","title":"支持微短剧拍摄标杆基地建设","text":"加强布局引导，重点依托马栏山视频文创产业园打造集“剧本创作、技术创新、审核服务、分发出海、版权服务”等功能的微短剧产业核心引爆地；支持有条件的区县（市）盘活工业退出闲置资源、文旅景点资源、打造一站式微短剧拍摄制作标杆基地。对以服务微短剧拍摄制作为主要业态的园区（基地），每年拍摄制作微短剧500部、1000部及以上的，结合播出情况等综合评审，分别给予最高不超过50万元、100万元补助。"},{"no":"二","title":"支持精品微短剧创作","text":"鼓励企业讲好长沙创新创业的时代传奇、十步芳草的红色芳华、楚汉名城的潇湘人物、网红长沙的青春故事、山水洲城的幸福佳话，实施“微短剧+”行动计划，鼓励“跟着微短剧品湘味”“跟着微短剧游长沙”等主题创作，鼓励微短剧与创新创业、都市文旅、商业消费、体育竞技等深度融合。企业作为第一出品方出品的网络微短剧，通过规划备案和成片审查并在红果、抖音、爱奇艺、优酷、腾讯、芒果TV等头部网络视听平台播出，根据播出情况、价值导向等综合评审，给予每部作品最高不超过30万元的补助。鼓励和支持企业积极参与国家级、省级微短剧创作计划和各类评选评奖申报。"},{"no":"五","title":"支持微短剧出海","text":"鼓励和支持企业与海外传播渠道加强合作，拓展多语种海外市场，开展内容创作、制作技术、发行播映等方面国际合作。鼓励申报国家文化出口重点企业和重点项目。发挥“长沙国际传播中心”平台作用，加强对长沙优秀微短剧的宣传和海外推广营销，增强湖湘文化产品国际知名度，提升中华文化传播力影响力。对优秀网络微短剧的第一出品方，因文化出海产生的翻译制作费用，给予50%的译制补贴，单个企业最高不超过20万元。"},{"no":"六","title":"支持智慧化服务平台建设","text":"支持微短剧智慧化综合服务平台建设和智能化升级，支持审核服务平台建设；支持版权服务平台建设，覆盖微短剧版权生产、交易、监管、审核、确权、维权全链条；支持有条件的企业建设微短剧拍摄资源整合平台、微短剧出海平台；根据上下游资源链接情况、服务拍摄企业和作品情况、资源交易数量等综合评价情况，单个项目予以最高不超过50万元的支持。"}],"interpretations":[{"sectionNo":"一","headline":"园区年拍微短剧500部补50万，1000部及以上补100万","who":"以服务微短剧拍摄制作为主要业态的园区（基地）；年拍摄制作微短剧500部、1000部及以上，结合播出情况综合评审。","materials":[],"window":"按年度拍摄制作数量计算（每年500部、1000部档），结合播出情况综合评审。","where":"长沙市文化旅游广电局等部门；马栏山视频文创产业园及有条件的区县（市）基地。","tip":"补助分档最高不超过50万元、100万元，须经综合评审，非达标即得。"},{"sectionNo":"二","headline":"第一出品方微短剧在头部平台播出，每部最高补30万元","who":"作为第一出品方出品网络微短剧的企业；须通过规划备案和成片审查，并在红果、抖音、爱奇艺、优酷、腾讯、芒果TV等头部网络视听平台播出。","materials":[],"window":"按作品申报，每部作品评审一次；原文未设申报截止时间。","where":"长沙市文化旅游广电局等部门（作品在头部网络视听平台播出）。","tip":"每部最高不超过30万元；须为企业第一出品方，并按播出情况和价值导向综合评审。"},{"sectionNo":"五","headline":"微短剧出海译制费补50%，单个企业最高20万元","who":"优秀网络微短剧的第一出品方企业；因文化出海产生翻译制作费用。","materials":[],"window":"按译制项目申报，原文未设申报截止时间。","where":"长沙市文化旅游广电局等部门；长沙国际传播中心提供海外推广。","tip":"补贴比例为翻译制作费用的50%，单个企业累计最高不超过20万元。"},{"sectionNo":"六","headline":"微短剧智慧化服务平台单个项目最高补50万元","who":"建设微短剧智慧化综合服务平台、审核服务平台、版权服务平台，或拍摄资源整合平台、出海平台的企业。","materials":[],"window":"按项目申报，依据综合评价确定支持金额；原文未设截止时间。","where":"长沙市文化旅游广电局等部门。","tip":"单个项目最高不超过50万元，须按资源链接、服务企业作品、资源交易数量等综合评价。"}],"sourceUrl":"https://www.changsha.gov.cn/zfxxgk/zfwjk/gdwxtwj/202603/t20260303_12326782.html","sourceNote":"2026-11-21 取自长沙市人民政府门户「政策文件—各单位系统文件」原文页；页面标注文号长文旅广电联〔2026〕5号、公布日期2026-03-03、信息时效期2027-03-02。条文为页面正文逐字摘录。 2026-11-21 收录：与官方页面逐句比对，命中 14/14 句（100%），关卡判定「verbatim」。 有效期依据：原文明示“自公布之日起生效，有效期一年”；页面登记信息时效期2027-03-02，推算一致。","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"cs-sme-digital-pilot-2024-4","title":"长沙市人民政府办公厅关于印发《长沙市支持国家中小企业数字化转型城市试点的若干政策》的通知","level":"city","region":"长沙市","issuer":"长沙市人民政府办公厅","documentNo":"长政办发〔2024〕4号","publishedAt":"2024-03-06","effectiveAt":"2024-03-15","expiresAt":"2027-03-14","status":"active","tags":["数字化转型","财政奖补","专项资金"],"audience":["试点中小企业","数字化转型服务商","智能制造示范工厂","推进机构"],"summary":"先行试点企业数字化改造按采购总额40%补助、单家最高40万元，其他试点企业按30%、最高30万元，市级财政再同额配套；新认定市级智能制造示范工厂奖励最高50万元，国家级最高100万元。","sections":[{"no":"（一）2","title":"推进细分行业中小企业数字化改造","text":"按照“企业出一点、服务商让一点、政府补一点”的原则，支持细分行业中小企业开展生产制造等相关环节的数字化改造。对试点企业采购数字化软件业务系统、云平台服务（含租赁、算力）、数字化改造设计施工服务以及数据采集传输设备（数据存储、网络、通信、智能终端）等给予补助。遴选一批有代表性的先行试点企业开展数字化改造试点，每家企业按照不高于数字化改造采购总额40%的比例给予补助，单家企业补助金额最高不超过40万元。其他试点企业按照每家企业不高于数字化改造采购总额30%的比例给予补助，单家企业补助金额最高不超过30万元。在使用中央财政资金按上述标准给予补助后，市级财政再根据实际改造情况给予配套支持，先行试点企业每家补助最高不超过40万元，其他试点企业每家补助最高不超过30万元。"},{"no":"（一）3","title":"支持数字化转型标杆建设","text":"支持企业结合自身实际和行业特点，打造数字化转型标杆。对新认定的市级智能制造示范工厂，一次性给予最高不超过50万元的奖励，并支持申报国家级智能制造示范工厂揭榜单位、省级智能制造标杆企业（车间）。对通过验收的国家级智能制造示范工厂，一次性给予最高不超过100万元的奖励。国家级、市级智能制造示范工厂按照就高不重复、晋级补差的原则给予奖励。打造一批智能工位，对经认定、建设3个及以上数量智能工位的企业，一次性给予最高不超过15万元的奖励。鼓励智能制造系统解决方案提供商积极为企业提供具有较高应用价值的系统解决方案，对经认定符合要求的系统解决方案一次性给予提供商最高不超过20万元的奖励。鼓励企业采购设备、软件开展智能化技术改造，对经认定符合要求的企业按不超过设备、软件采购额10%的比例给予补助，补助总额最高不超过200万元。"},{"no":"（一）4","title":"支持数字化转型优秀场景建设","text":"鼓励企业推动5G、工业互联网、数字孪生、大数据、人工智能、区块链等新技术与先进制造技术深度融合，在设计、研发、生产、仓储、质量管理、安全管理等环节，打造一批智能制造典型应用场景。对新认定的市级典型应用场景，一次性给予最高不超过25万元的奖励，并支持申报国家级智能制造优秀场景。对认定的国家级智能制造优秀场景，一次性给予最高不超过50万元的奖励。国家级、市级应用场景按照就高不重复、晋级补差的原则给予奖励。支持企业基于大数据、大模型、云计算等新一代人工智能技术开展融合创新产品研发及应用服务。每年遴选一批具有示范带动意义的应用场景和解决方案，视企业年度经营情况、地方贡献情况等，分类分级给予最高不超过50万元/项的奖励。"},{"no":"（二）2","title":"支持工业互联网平台建设","text":"对工业互联网平台纳入工业和信息化部试点示范的，按照不超过项目总投资20%的比例给予配套补助，单个项目补助最高不超过200万元。对纳入省级工业互联网平台建设计划且通过项目验收的，按照不超过项目总投资20%的比例给予配套补助，单个项目补助最高不超过100万元。国家级、省级工业互联网平台试点示范按照就高不重复、晋级补差的原则给予奖励。支持重点细分行业建设工业互联网平台，公开遴选若干细分行业平台建设计划，对按照计划建设且行业转型支撑明显、服务覆盖广的平台给予平台建设单位最高不超过300万元的奖励。"}],"interpretations":[{"sectionNo":"（一）2","headline":"先行试点改造补40%最高40万，其他企业30%最高30万","who":"长沙市细分行业中小企业中的试点企业；采购范围含数字化软件业务系统、云平台服务（含租赁、算力）、数字化改造设计施工服务及数据采集传输设备（数据存储、网络、通信、智能终端）。先行试点企业（遴选的有代表性企业）按不高于采购总额40%补助、单家最高40万元；其他试点企业按不高于采购总额30%补助、单家最高30万元。","materials":[],"window":"改造完成、按采购额比例核定；中央财政按标准补助后，市级财政再按实际改造情况配套","where":"原文未列明受理部门（按试点遴选程序确定）","tip":"中央财政补助后市级财政再配套；先行试点与其他试点的补助比例、封顶额均不同，先确认自己属哪类试点"},{"sectionNo":"（一）3","headline":"市级智能工厂奖50万、国家级100万，3个智能工位奖15万","who":"长沙市内新认定的市级智能制造示范工厂（一次性最高50万元）；通过验收的国家级智能制造示范工厂（一次性最高100万元）；经认定建设3个及以上智能工位的企业（一次性最高15万元）；经认定符合要求的智能制造系统解决方案提供商（一次性最高20万元）；采购设备、软件开展智能化技术改造的企业（按不超过采购额10%补助、总额最高200万元）。","materials":[],"window":"认定或验收通过后一次性奖励；智能化技术改造按设备、软件采购额比例补助","where":"原文未列明受理部门（按认定、验收程序确定）","tip":"国家级与市级示范工厂就高不重复、晋级补差；智能工位须经认定且达3个及以上才奖"},{"sectionNo":"（一）4","headline":"市级典型场景奖25万、国家级50万，年度遴选最高50万/项","who":"在长沙市内打造智能制造典型应用场景的企业（5G、工业互联网、数字孪生、大数据、人工智能、区块链等新技术与先进制造融合，覆盖设计、研发、生产、仓储、质量管理、安全管理环节）：新认定市级典型应用场景一次性最高25万元，国家级智能制造优秀场景一次性最高50万元；基于大数据、大模型、云计算开展融合创新产品研发及应用的企业，每年遴选分类分级最高50万元/项。","materials":[],"window":"认定后一次性奖励；每年遴选一批应用场景和解决方案","where":"原文未列明受理部门（按认定、遴选程序确定）","tip":"国家级与市级应用场景就高不重复、晋级补差；年度遴选还看企业年度经营情况和地方贡献"},{"sectionNo":"（二）2","headline":"国家级工业互联网平台补总投资20%、最高200万","who":"工业互联网平台纳入工业和信息化部试点示范的项目单位（按不超过项目总投资20%配套、单个最高200万元）；纳入省级工业互联网平台建设计划且通过验收的（按不超过项目总投资20%、单个最高100万元）；按公开遴选的细分行业平台建设计划建设、行业转型支撑明显、服务覆盖广的平台建设单位（最高300万元）。","materials":[],"window":"纳入试点示范或省级建设计划并通过项目验收后补助","where":"工业和信息化部（国家级试点示范）；省级工业互联网平台建设计划（省级）","tip":"国家级与省级平台就高不重复、晋级补差；细分行业平台须按公开遴选的建设计划建设才可获最高300万元奖励"}],"sourceUrl":"https://www.changsha.gov.cn/zfxxgk/zfwjk/szfbgt/202403/t20240306_11386629.html","sourceNote":"2026-11-21 取自长沙市人民政府门户「政策文件—市政府办公室文件」原文页；页面标注文号长政办发〔2024〕4号、公布日期2024-03-06、信息时效期2027-03-14。条文为页面正文逐字摘录。 2026-11-21 收录：与官方页面逐句比对，命中 22/22 句（100%），关卡判定「verbatim」。 有效期依据：原文明示“自2024年3月15日起施行，有效期3年”；页面登记信息时效期2027-03-14，一致。","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"cs-startup-loan-2026","title":"长沙市创业担保贷款申请指南","level":"city","region":"长沙市","issuer":"长沙市人力资源和社会保障局","documentNo":"","publishedAt":"2026-11-05","effectiveAt":null,"expiresAt":null,"status":"active","tags":["融资支持","创业补贴","贷款贴息"],"audience":["在长沙创业的重点就业群体","合伙创业主体","符合条件的小微企业"],"summary":"个人创业担保贷款最高50万元（大学生）、其他群体30万元，小微企业最高400万元；财政部门给予贷款实际利率50%的贴息。","sections":[{"no":"一","title":"个人创业申请条件","text":"属于重点就业群体。包括城镇登记失业人员或登记自主创业人员、就业困难人员（含残疾人）、退役军人、刑满释放人员、大学生（含大学生村官和留学回国学生）、化解过剩产能企业职工和失业人员、返乡创业农民工、网络商户、脱贫人口、农村自主创业农民、新市民；其中大学生包括国内外高校在校学生或毕业5年以内的大专、本科、硕士、博士毕业生。"},{"no":"一续","title":"小微企业申请条件","text":"属于现行中小企业划型标准规定的小型、微型企业；申请创业担保贷款前12个月内新招用重点就业群体的在职人数达到企业现有在职职工人数10%（超过100人的企业达到5%），并与其签订1年以上劳动合同；无拖欠职工工资、欠缴社会保险费等违法信用记录。"},{"no":"二","title":"额度及期限","text":"个人创业：大学生个人创业担保贷款额度不超过50万元，其他群体不超过30万元。贷款期限不超过3年。合伙创业：最高不超过重点就业群体人数的个人创业担保贷款额度上限之和的110%且不超过小微企业创业担保贷款额度上限。小微企业：创业担保贷款额度不超过400万元，但新招用人数不足3人的，贷款额度不得超过300万元；贷款期限不超过2年。"},{"no":"三","title":"贷款利率","text":"贷款利率上限为LPR+150BP，其中LPR为1年期贷款市场报价利率。"},{"no":"四","title":"财政贴息","text":"对符合条件的创业担保贷款，财政部门给予贷款实际利率50%的财政贴息。"}],"interpretations":[{"sectionNo":"一","headline":"重点就业群体个人创业可申请创业担保贷款","who":"城镇登记失业人员或登记自主创业人员、就业困难人员（含残疾人）、退役军人、刑满释放人员、大学生（含大学生村官和留学回国学生）、化解过剩产能企业职工和失业人员、返乡创业农民工、网络商户、脱贫人口、农村自主创业农民、新市民；大学生含国内外高校在校学生或毕业5年以内的大专、本科、硕士、博士毕业生。","materials":[],"window":"无明确申报截止期；大学生身份按在校或毕业5年以内认定","where":"原文未列受理窗口或线上系统","tip":"须先属于重点就业群体；大学生含在校生和毕业5年以内毕业生"},{"sectionNo":"一续","headline":"小微企业新招重点群体达10%可申请创业担保贷款","who":"现行中小企业划型标准规定的小型、微型企业；申请创业担保贷款前12个月内新招用重点就业群体的在职人数达到企业现有在职职工人数10%（超过100人的企业达到5%），并与其签订1年以上劳动合同；无拖欠职工工资、欠缴社会保险费等违法信用记录。","materials":[],"window":"申请前12个月为招用考察期；劳动合同须1年以上","where":"原文未列受理窗口或线上系统","tip":"超过100人的企业比例降至5%；新招人数、合同期限、信用记录须同时满足"},{"sectionNo":"二","headline":"个人创业担保贷款最高50万元，小微企业最高400万元","who":"个人创业：大学生最高50万元、其他群体最高30万元；合伙创业最高为重点群体人数个人额度上限之和的110%，且不超小微企业上限；小微企业最高400万元，新招用不足3人不得超300万元。","materials":[],"window":"个人及合伙贷款期限不超过3年；小微企业不超过2年","where":"原文未列受理窗口或线上系统","tip":"新招用人数不足3人的小微企业贷款额度不得超过300万元；合伙创业额度上限为110%"},{"sectionNo":"三","headline":"创业担保贷款利率上限为LPR+150BP","who":"申请创业担保贷款的个人、合伙创业者及小微企业","materials":[],"window":"贷款期内按合同约定执行，原文未另设申报期","where":"原文未列受理窗口或线上系统","tip":"LPR为1年期贷款市场报价利率，利率不得超过上限"},{"sectionNo":"四","headline":"符合条件创业担保贷款，财政贴息实际利率的50%","who":"符合条件的创业担保贷款借款人（个人、合伙及小微企业）","materials":[],"window":"贴息随贷款期限执行，原文未单列申报期","where":"财政部门（原文未列受理窗口）","tip":"贴息为贷款实际利率的50%，不是全额免息"}],"sourceUrl":"http://rsj.changsha.gov.cn/zxzx_0/tzgg_131288/202611/t20261105_12609526.html","sourceNote":"2026-11-21 取自长沙市人社局「通知公告」原文页；页面标题已核对，为办事指南类文件，无文号。同栏目2026-09-10另发个人版指南，数据一致。 2026-11-21 收录：与官方页面逐句比对，命中 10/10 句（100%），关卡判定「verbatim」。 有效期依据：原文未设期限；属现行办事指南","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"cs-tech-fund-2026-11","title":"长沙市科学技术局 长沙市财政局关于印发《长沙市科技专项资金管理办法》的通知","level":"city","region":"长沙市","issuer":"长沙市科学技术局、长沙市财政局","documentNo":"长科发〔2026〕11号","publishedAt":"2026-03-31","effectiveAt":"2026-05-01","expiresAt":"2031-04-30","status":"active","tags":["专项资金","研发创新"],"audience":["高等院校","科研院所","科技型企业","新型研发机构"],"summary":"市级科技专项资金，支持基础研究、技术研发、科技成果转化、科技产业高质量发展、高水平机构建设运行、科技人才引育、创新生态建设、指令性计划等方向，采取前资助、后补助、滚动资助等方式，具体额度由年度项目申报指南确定；科研单位可从项目资金中提取项目管理费，10万元及以下部分最高不超过10%、10—100万元部分不超过5%、100万元以上部分不超过3%，单项项目最高不超过10万元。自2026年5月1日起施行，有效期5年。","sections":[{"no":"一","title":"","text":"按照《中华人民共和国科学技术进步法》、《湖南省科学技术进步条例》要求，设立长沙市科技专项资金（以下简称专项资金）。为规范和加强专项资金的管理，提高财政资金使用绩效，发挥专项资金的引导带动作用，根据《国务院办公厅关于改革完善中央财政科研经费管理的若干意见》（国办发〔2021〕32号）等国家、省科技经费管理和本市财政资金管理有关规定，制定本办法。"},{"no":"二","title":"","text":"专项资金由市级财政预算安排，由长沙市科学技术局和长沙市财政局共同管理（以下分别简称市科技局和市财政局）。市科技局、市财政局及有关市直职能部门分别履行以下职责：（一）市科技局负责编制专项资金预算，确定专项资金年度使用方向和支持重点，开展专项资金日常管理；对专项资金项目进行全过程管理并开展监督检查；实施专项资金绩效管理。（二）市财政局负责专项资金预算管理和资金拨付，监督检查专项资金使用情况，指导推进专项资金绩效管理工作。（三）专项资金使用涉及的各市直职能部门应当根据职责分工，按照本办法要求，协同做好专项资金的使用、管理和监督。"},{"no":"三","title":"","text":"项目承担单位是专项资金使用管理的责任主体。项目承担单位负责专项资金项目申报，对申报项目及相关材料的真实性、合法性等承担法律责任，并落实项目承诺的自筹资金。建立健全财务管理和内部控制制度，合理制定项目实施方案，严格按照经批准的绩效目标组织项目实施，合理合规使用专项资金。按照规定开展专项资金绩效管理，自觉接受纪检监察、审计和财政等部门监督。"},{"no":"四","title":"","text":"专项资金的使用应当符合国家、省和本市科技发展的政策导向，符合财政预算管理的有关规定，通过支持创新生态链各个环节构建资助体系。具体使用原则如下：（一）聚焦重点，科学配置。围绕科技创新高地建设需求，聚焦前沿优势领域及重大技术创新、科技成果转化等，建立高水平科技战略决策咨询机制，突出使命需求导向，强化前瞻性、战略性、系统性、带动性布局，加强对科技创新全链条关键环节支持和全过程管理，优化资源配置。（二）统筹投入，加强联动。加强专项资金与其他财政科技投入资金错位支持、统筹管理、形成合力，加强与创业投资基金联动，鼓励和引导社会资本投入科技创新，推进“项目、平台、人才、政策”一体化布局。（三）强化管理，注重绩效。按照预算管理和财政资金使用规定规范使用专项资金，探索专项资金管理更加有效服务科技创新新模式。强化预算绩效管理，加强执行监督，切实提高专项资金使用效益。（四）优化路径，动态管理。对照新形势、新要求，借鉴国际先进研发组织模式，优化重大科技创新组织机制，建立更加适应技术领域特点与创新需求的组织实施方式，不断探索科研资助新路径，强化专项资金高效组织使用与动态调整管理。（五）鼓励创新，尽职免责。鼓励科研人员在项目实施过程中，探索使用新路线、新技术、新方法、新模式。对于基础研究项目，在履行勤勉尽责义务前提下，非因主观故意导致项目实施不成功的，对科研人员免责。"},{"no":"五","title":"","text":"专项资金的支持对象是具有独立法人资格的高等院校、科研院所、企业、医疗卫生机构和其他具备科研开发、科技服务和决策咨询研究能力的单位，以及市委、市人民政府确定的重大科技事项承担或合作的市内外具备独立法人资格的单位。"},{"no":"六","title":"第二章 支持范围与方式","text":"专项资金主要支持以下方向：（一）基础研究。支持各类创新主体开展战略导向的体系化基础研究、前沿导向的探索性基础研究、市场导向的应用性基础研究，提出原创基础理论，掌握底层技术原理，筑牢科技创新根基和底座。（二）技术研发。围绕产业链部署创新链，坚持企业创新主体，以全链条布局强化全过程创新，加强前沿引领技术、颠覆性技术、关键共性技术等创新攻关，夯实科技基础条件自主保障，加强新领域、新赛道科技供给，支撑产业链、供应链自主安全可控，培育壮大新兴产业和未来产业，发展新质生产力。（三）科技成果转化。围绕科技成果转化全链条、全要素，完善科技成果转化政策，强化服务体系专业化能效，持续提升科技成果转化和产业化水平，以新技术、新产品、新场景促进传统产业转型升级和产业结构优化。（四）科技产业高质量发展。进一步壮大高新技术企业、科技型中小企业群体，支持培育科技创新领军企业和创新联合体，整体提升全市科技产业竞争力。（五）高水平机构建设运行。支持重大科创平台、新型研发机构、技术研发平台、高水平科技智库等各类主体建设和创新能级提升，促进优质创新资源高效整合与共享，进一步提升科技实力和国际竞争力。（六）科技人才引育。围绕国家吸引集聚人才平台建设，依托重大平台和任务，搭建科技人才事业发展平台，凝聚科技人才竞争优势，构筑汇聚全球智慧资源的创新高地。（七）创新生态建设。面向科技合作、科学普及、科技金融和科研资源开放共享，完善创新体系建设，推动科技开放合作，主动对接国际大科学计划和大科学工程，吸引全球科技创新要素，形成良好的创新生态和科研环境。（八）指令性计划。用于市委、市人民政府明确支持的科技创新工作。"},{"no":"七","title":"","text":"专项资金主要采取前资助、后补助、滚动资助等支持形式，包括但不限于无偿资助、奖补、政府购买服务、先研后股、科技金融资助等。发挥财政资金带动作用，引导建立科技创新多元化投入机制。具体支持方式由市科技局在制定具体政策和发布科技项目申报指南（通知）时确定。"},{"no":"八","title":"","text":"科技项目管理费在部门预算中安排，主要用于长沙市科技创新综合信息平台建设与维护、项目管理人员培训、形式审查、项目评审、公示、验收、监督检查及绩效评价等科技项目组织和管理工作。"},{"no":"九","title":"第三章 资金使用","text":"前资助项目资金开支包括项目实施过程中发生的直接费用和间接费用。（一）直接费用是指在科技项目研究开发过程中发生的与之直接相关的费用，主要包括设备费、材料费、测试化验加工费、燃料动力费、差旅费、会议费、国际合作与交流费、出版/文献/信息传播/知识产权事务费、劳务费、专家咨询费和其他直接支出。其中，劳务费是指在项目研究开发过程中支付给项目组成员及项目组临时聘用人员的人力资源成本费，可包括项目临时聘用人员的社会保险补助。设备购置费预算调整，需报市科技局同意。设备购置费预算以外的调整，由项目承担单位根据项目实际情况调整。项目组成员所在单位有事业费拨款、工资性收入的部分，不得在财政资助的项目资金中重复列支。（二）间接费用是指项目承担单位在组织实施项目过程中发生的无法在直接费用中列支的相关费用。主要包括项目承担单位为项目实施提供的现有仪器设备及房屋、水、电、气、暖消耗，有关管理费用支出，以及绩效支出等。其中绩效支出是指项目承担单位为提高科研工作绩效安排的相关支出。（三）关于直接费用和间接费用的比例，项目承担单位应按照国家、省相关规定科学合理、实事求是地做出安排。（四）青年人才项目和基础研究项目经费的使用实行“负面清单+包干制”。"},{"no":"十","title":"","text":"后补助项目资金，除政策指定专门用途的外，由项目承担单位统筹安排，不再组织资金过程管理和财务验收。"},{"no":"十一","title":"","text":"滚动资助项目资金，项目启动前和中期拨付的，用于支持下一阶段项目实施的参照前资助项目资金管理使用；用于补助评估阶段的和项目通过验收后拨付的参照后补助项目资金管理使用。"},{"no":"十二","title":"","text":"专项资金拨付严格按照财政国库集中支付有关规定执行；属于政府采购、招投标、国有资产管理等事项，应当严格按照相关法律、规章、制度规定执行。"},{"no":"十三","title":"","text":"高等院校、科研院所、新型研发机构、医疗卫生机构等科研单位可根据本单位规定在市科技项目资金中提取一定比例项目管理费，10万元及以下的部分最高不超过10%，10—100万元的部分不超过5%，100万元以上的部分不超过3%，单项项目最高不超过10万元。"},{"no":"十四","title":"","text":"前资助项目实施期内的年度结余资金结转下一年度继续使用。项目完成目标任务并通过验收后，结余资金留归项目承担单位使用。项目承担单位要将结余资金统筹安排用于科研活动直接支出，优先考虑原项目团队科研需求，并加强结余资金管理，健全结余资金盘活机制，加快资金使用进度。项目终止实施、撤销、未通过验收或项目承担单位信用评价差的，按原渠道收回未使用和使用不合理的专项资金。"},{"no":"十五","title":"第四章 监督管理","text":"健全信息公开制度。市科技局按照有关规定，向社会公开专项资金安排情况等信息，接受社会监督。"},{"no":"十六","title":"","text":"市科技局、市财政局根据专项资金使用要求和全面实施预算绩效管理的要求，建立健全预算绩效管理机制，提高资金使用效益。完善差异化绩效评价指标体系，督促项目承担单位按规定科学合理设定绩效目标，做好绩效监控和绩效评价，强化评价结果运用。"},{"no":"十七","title":"","text":"市科技局、市财政局可自行或委托专业机构对专项资金使用和项目实施情况进行全过程监督检查，确保专项资金规范、安全、高效使用。"},{"no":"十八","title":"","text":"专项资金的安排、拨付、使用和管理，依法接受审计机关的审计监督，主动接受人大和社会监督。"},{"no":"十九","title":"","text":"专项资金应当严格按照国家会计法律法规制度管理使用，对专项资金使用过程中出现弄虚作假、截留、挪用、挤占资金等违法违规行为的单位和个人，按照相关规定进行处理，并按规定收回已拨付的专项资金，涉嫌犯罪的，依法移送有权机关处理。"},{"no":"二十","title":"第五章 附则","text":"各区、县（市）可根据各自区域特点和科技创新工作实际，设立区、县（市）科技专项资金并制定相应管理办法，促进区域科技创新高质量发展。"},{"no":"二十一","title":"","text":"本办法自2026年5月1日起施行，有效期5年，由市科技局负责解释。"}],"interpretations":[{"sectionNo":"五","headline":"支持独立法人高校、院所、企业、医疗机构等申报","who":"具有独立法人资格的高等院校、科研院所、企业、医疗卫生机构和其他具备科研开发、科技服务和决策咨询研究能力的单位；以及市委、市人民政府确定的重大科技事项承担或合作的市内外独立法人单位。","materials":[],"window":"按市科技局发布的科技项目申报指南（通知）确定申报期。","where":"长沙市科学技术局","tip":"须为独立法人；市外单位仅限市委、市人民政府确定的重大科技事项承担或合作方。"},{"sectionNo":"六","headline":"支持基础研究、技术研发、成果转化等八个方向","who":"符合八类支持方向的创新主体：基础研究、技术研发、科技成果转化、科技产业高质量发展、高水平机构建设运行、科技人才引育、创新生态建设、指令性计划。","materials":[],"window":"按年度科技项目申报指南（通知）组织申报。","where":"长沙市科学技术局","tip":"第八类指令性计划仅用于市委、市人民政府明确支持的科技创新工作。"},{"sectionNo":"七","headline":"支持方式含前资助、后补助、滚动资助，以指南为准","who":"符合支持方向的项目承担单位。","materials":[],"window":"具体支持方式由市科技局在申报指南（通知）中确定。","where":"长沙市科学技术局","tip":"还包括无偿资助、奖补、政府购买服务、先研后股、科技金融资助等形式。"},{"sectionNo":"九","headline":"前资助可列设备、材料、劳务等直接费用及间接费用","who":"前资助项目承担单位（含项目组成员及临时聘用人员）。","materials":["设备购置费预算调整报批材料"],"window":"设备购置费预算调整须报市科技局同意；其他费用由承担单位按实际情况调整。","where":"长沙市科学技术局","tip":"有事业费拨款、工资性收入的部分不得在财政资助资金中重复列支；青年人才和基础研究项目实行负面清单加包干制。"},{"sectionNo":"十","headline":"后补助资金由承担单位统筹，不再财务验收","who":"后补助项目承担单位。","materials":[],"window":"拨付后由承担单位统筹安排，不组织资金过程管理和财务验收。","where":"长沙市科学技术局、长沙市财政局","tip":"除政策指定专门用途外，后补助资金可统筹安排使用。"},{"sectionNo":"十一","headline":"滚动资助分段管理：前期按前资助、验收后按后补助","who":"滚动资助项目承担单位。","materials":[],"window":"项目启动前和中期拨付的参照前资助；评估阶段和验收后拨付的参照后补助。","where":"长沙市科学技术局","tip":"同一项目不同阶段资金适用不同管理规则。"},{"sectionNo":"十三","headline":"科研单位可提项目管理费，10万元以下部分最高10%","who":"高等院校、科研院所、新型研发机构、医疗卫生机构等科研单位。","materials":[],"window":"按本单位规定提取，单项项目最高不超过10万元。","where":"项目承担单位（按本单位规定）","tip":"分段计提：10万元及以下部分不超过10%、10—100万元部分不超过5%、100万元以上部分不超过3%。"},{"sectionNo":"十四","headline":"结余资金可结转，验收通过后留归单位用于科研","who":"前资助项目承担单位。","materials":[],"window":"实施期内年度结余结转下一年度；通过验收后结余留归单位统筹用于科研活动直接支出。","where":"项目承担单位（市科技局监管）","tip":"项目终止、撤销、未通过验收或信用评价差的，未使用和使用不合理资金按原渠道收回。"},{"sectionNo":"十九","headline":"弄虚作假、截留挪用资金将被收回并追责","who":"专项资金使用过程中出现违规行为的单位和个人。","materials":[],"window":"发现即按规定处理并收回已拨付专项资金；涉嫌犯罪移送有权机关。","where":"长沙市科学技术局、长沙市财政局（依法接受审计监督）","tip":"截留、挪用、挤占与弄虚作假同等处理。"}],"sourceUrl":"https://www.changsha.gov.cn/zfxxgk/zfwjk/gdwxtwj/202604/t20260402_12351442.html","derivedFrom":"official","sourceNote":"2026-11-21 取自长沙市人民政府门户「政策文件—各单位系统文件」原文页；页面标注文号长科发〔2026〕11号、公布日期2026-03-31、信息时效期2031-04-30。条文为页面正文逐字摘录。 2026-11-21 收录：与官方页面逐句比对，命中 5/5 句（100%），关卡判定「verbatim」。 有效期依据：原文明示“自2026年5月1日起施行，有效期5年”；页面登记信息时效期2031-04-30，一致。 2026-11-24 收录：与官方页面逐句比对，命中 63/63 句（100%），关卡判定「verbatim」。 有效期依据：原文未明示","verified":false,"isSample":false,"numberStyle":"clause","bodyVerified":"verbatim","hunan":true},{"id":"cs-yuelu-huiqi-cash-2026","title":"关于申报2022—2026年湖南湘江新区企业普惠政策兑现的通知","level":"district","region":"长沙市·岳麓区","issuer":"湖南湘江新区管理委员会科技创新和产业促进局、湖南湘江新区管理委员会财政金融局","documentNo":"","publishedAt":"2026-11-12","effectiveAt":null,"expiresAt":null,"status":"active","tags":["财政奖补","专项资金"],"audience":["湘江新区内企业","专精特新中小企业","大学生创业企业"],"summary":"湘江新区 2022—2026 年企业普惠政策兑现申报：本次兑现共涉及 30 个政策文件，覆盖科技创新和产业促进局（7 项市级配套政策及湘新管发〔2023〕5 号、6 号、11 号，湘新管发〔2025〕6 号、7 号等 8 项政策部分条款）、财政金融局（湘新管发〔2023〕8 号等 9 项）、湘江科学城（湘新管发〔2023〕10 号）、麓谷产业片区（湘新管发〔2023〕13 号）、岳麓高新区（岳高新管发〔2023〕24 号、25 号等 3 项）。线上提交期为 2026 年 11 月 12 日至 20 日，同一文件同一年度同一类型支持事项就高不就低、只能申报一项。","sections":[{"no":"一","title":"兑现政策","text":"（一）科技创新和产业促进局（大学科技园办公室）：1.北斗产业发展、网络安全产业发展、先进计算产业发展、新一代半导体和集成电路产业发展、智能汽车产业生态火炬计划、“院士、专家工作站”资助等7项市级配套支持政策。2.《关于湖南湘江新区（长沙高新区）推进前沿科技创新高地建设的若干政策》（湘新管发〔2023〕5号）、《关于湖南湘江新区（长沙高新区）推进先进制造业高质量发展的若干政策》（湘新管发〔2023〕6号）、《湖南湘江新区（长沙高新区）促进经济高质量发展的若干政策（试行）》（湘新管发〔2025〕6号）、《湖南湘江新区（长沙高新区）支持大学生创业若干政策（试行）》（湘新管发〔2025〕7号）共8项政策部分条款；3.《关于湖南湘江新区（长沙高新区）促进JMRH产业发展的若干政策》（湘新管发〔2023〕11号）。（二）财政金融局：《关于湖南湘江新区（长沙高新区）促进金融业发展的若干政策》（湘新管发〔2023〕8号）、《关于支持湘江基金小镇发展的若干政策》（湘新综发〔2023〕41号）等9项政策部分条款。（三）湘江科学城（长沙）管理委员会：《关于湖南湘江新区（长沙高新区）支持高质量科技成果就地转化的若干政策》（湘新管发〔2023〕10号）部分条款。（四）湖南湘江新区（长沙高新区）麓谷产业片区管理办公室：《关于湖南湘江新区（长沙高新区）促进数字经济发展的若干政策（试行）》（湘新管发〔2023〕13号）部分条款。（五）岳麓高新技术产业开发区管理委员会：《关于岳麓高新区促进检验检测产业链发展的若干政策》（岳高新管发〔2023〕24号）、《关于岳麓高新区促进人工智能产业发展的若干政策》（岳高新管发〔2023〕25号）等3项政策部分条款。"},{"no":"二","title":"申报基本条件","text":"（一）申报单位一般应具有独立法人资格，具有健全的财务管理机构和制度，能够严格落实资金管理要求，积极配合做好调查、调度等工作，具有良好信用。（二）项目符合国家产业政策和有关法律法规，具有较强的示范带动作用。（三）不符合申报条件的主要情况：1.项目不符合安全生产、环境保护等规定。2.被列入“信用湖南”网失信名单或近3年以来发生重大安全生产事故、重大生态环境违法事件、重大产品质量安全事故、数据安全事件等其他严重问题的单位。"},{"no":"三","title":"申报程序","text":"（一）申报单位请详细阅读《湖南湘江新区2022—2026年普惠政策申报指南》（附件1），简称《申报指南》，查询兑现年度、申报形式，在申报过程中遇到业务问题，请联系《申报指南》对应条款所涉部门（园区）工作人员。（二）采取线上申报方式，项目申报单位对照《申报指南》编制申报材料，由申报单位注册并登录（长沙市统一认证登录）湘江新区企业服务平台（https://www.kccyj.cn/platform），在线填报并上传材料（湘江新区企业服务平台企业端操作指引见附件2）。部分条款要求线下同步提交资料。促进JMRH产业发展的相关政策，不参与线上申报，请线下查阅政策内容，线下提交纸质申请资料。（三）《关于湖南湘江新区（长沙高新区）推进前沿科技创新高地建设的若干政策》（湘新管发〔2023〕5号）、《关于湖南湘江新区（长沙高新区）推进先进制造业高质量发展的若干政策》（湘新管发〔2023〕6号）、《湖南湘江新区（长沙高新区）促进经济高质量发展的若干政策（试行）》（湘新管发〔2025〕6号）按注册地街道所在园区、部门进行线上受理、组织初审。注意事项：注册在洋湖街道、梅溪湖街道、观沙岭街道、莲花镇、含浦街道、天顶街道、银盆岭街道、望城坡街道、桔子洲街道、咸嘉湖街道、望岳街道、西湖街道、望月湖街道、雨敞坪镇的企业，初审联系湖南湘江新区科技创新和产业促进局（大学科技园办公室）；注册在麓谷街道、白马街道、金山桥街道、黄金园街道、东方红街道、雷锋街道、白箬铺镇的企业，初审联系湖南湘江新区（长沙高新区）麓谷产业片区管理办公室产业发展部；注册在学士街道的企业初审联系岳麓高新区产业发展局；注册在岳麓街道、坪塘街道的企业初审联系湘江科学城（长沙）管理委员会科技创新和成果转化局。"},{"no":"四","title":"申报注意事项","text":"（一）本次申报的线上提交日期为2026年11月12日至20日。申报主体须在截止时间之前完成线上提交，逾期不予受理。（二）本次申报项目资金拨付将结合可用财力分年度制定资金计划逐年安排落实。具体拨付时间以责任部门通知为准。（三）此次申报涉及的所有支持事项中，同一年度同一文件如属于同一类型的，就高不就低，只能申报一项。此次申报的政策支持事项较多，请申报主体逐一对照附件支持事项清单，不要遗漏，及时在线提交材料。（四）对本次项目的申报、评审和资金拨付，湘江新区各部门不收取任何费用，请广大企业提高警惕，如发现任何不当要求，及时举报，谨防上当受骗（湘江新区科产局，纪检电话：88999259，监督评价处电话88999219）。（五）申报主体应如实提供申报材料，对材料真实性负责；对以虚假材料骗取奖补资金的，取消其申报资格，并依法依规追究责任。系统联系人：湘江新区企业服务平台：0731-88999913；长沙市统一认证（市认证）：18773100452；湖南省统一身份认证（省认证）：0731-82214464。"}],"interpretations":[{"sectionNo":"一","headline":"湘江新区兑现前沿科技、先进制造、金融等政策，含7项市级配套","who":"在湘江新区（长沙高新区）注册、符合湘新管发〔2023〕5号、6号、8号、10号、11号、13号及〔2025〕6号、7号等文件条款的企业、机构；其中第2项所列文件仅部分条款纳入本次兑现。","materials":[],"window":"2023年、2025年出台的上述政策条款均在本次兑现范围内","where":"湖南湘江新区科技创新和产业促进局（大学科技园办公室）、财政金融局、湘江科学城（长沙）管理委员会、麓谷产业片区管理办公室、岳麓高新技术产业开发区管理委员会按政策归口受理","tip":"第2项所列政策只兑现部分条款，申报前须确认自己的条款是否在兑现清单内；不同文件归口不同部门，受理口不一致"},{"sectionNo":"二","headline":"申报须独立法人、财务健全、信用良好，项目符合产业政策","who":"在湘江新区注册、一般应具有独立法人资格、具有健全的财务管理机构和制度、能配合调查调度、信用良好的企业；项目须符合国家产业政策和有关法律法规并有较强示范带动作用；被列入“信用湖南”网失信名单或近3年以来发生重大安全生产事故、重大生态环境违法事件、重大产品质量安全事故、数据安全事件的单位不得申报。","materials":[],"window":"本次申报的线上提交日期为2026年11月12日至20日","where":"湘江新区企业服务平台（https://www.kccyj.cn/platform）线上申报","tip":"失信名单和近3年重大安全、环保、质量、数据安全事件是硬性排除项；申报单位须能配合后续调查、调度"},{"sectionNo":"三","headline":"线上申报，按注册街道分园区初审","who":"在湘江新区注册的企业，按注册地街道（镇）确定初审园区：注册在洋湖、梅溪湖、观沙岭、莲花镇、含浦、天顶、银盆岭、望城坡、桔子洲、咸嘉湖、望岳、西湖、望月湖、雨敞坪的企业报科技创新和产业促进局（大学科技园办公室）；注册在麓谷、白马、金山桥、黄金园、东方红、雷锋、白箬铺的企业报麓谷产业片区管理办公室产业发展部；注册在学士街道的报岳麓高新区产业发展局；注册在岳麓街道、坪塘街道的报湘江科学城（长沙）管理委员会科技创新和成果转化局。","materials":[],"window":"按《申报指南》查询兑现年度、申报形式","where":"湘江新区企业服务平台（https://www.kccyj.cn/platform），长沙市统一认证登录；促进JMRH产业发展的相关政策线下提交纸质资料","tip":"注册地决定初审园区，报错园区会被退回；JMRH产业相关政策不参与线上申报，须线下交纸质材料"},{"sectionNo":"四","headline":"11月12日至20日线上提交，逾期不予受理","who":"本次申报的所有申报主体；同一年度同一文件如属同一类型事项，只能申报一项，就高不就低；申报主体须对材料真实性负责。","materials":[],"window":"2026年11月12日至20日线上提交；资金结合可用财力分年度制定计划逐年拨付，具体拨付时间以责任部门通知为准","where":"湘江新区企业服务平台（咨询电话0731-88999913）；长沙市统一认证、湖南省统一身份认证","tip":"各部门不收取任何费用；以虚假材料骗取奖补的取消申报资格并追责；同一年度同一文件同一类型只能报一项"}],"sourceUrl":"http://www.yuelu.gov.cn/yl_xxgk/tzgg/202611/t20261112_12615675.html","derivedFrom":"official","sourceNote":"取自岳麓区政府门户（湖南湘江新区）「通知公告」原文页，页面标注来源为湘江新区科技创新和产业促进局；该件为申报通知，无文号。发文主体为湖南湘江新区管理委员会（适用范围含岳麓区、望城区、高新区），收录时按管委会驻地归入岳麓区。2026-11-24 按原文一至四部分重切全文；本通知只列兑现范围与申报程序，各事项奖补金额标准写在其附件《湖南湘江新区2022—2026年普惠政策申报指南》及所列 30 个政策文件正文中，通知本身不含金额。 2026-11-24 收录：与官方页面逐句比对，命中 32/32 句（100%），关卡判定「verbatim」。 有效期依据：原文未设有效期条款","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"cs-yuelu-wengang-return-2026","title":"关于进一步明确2026年度劳务派遣单位申请失业保险稳岗返还的通知","level":"district","region":"长沙市·岳麓区","issuer":"湖南湘江新区管理委员会民政和社会保障局（退役军人事务局）","documentNo":"","publishedAt":"2026-11-20","effectiveAt":null,"expiresAt":null,"status":"active","tags":["就业补贴","社保补贴"],"audience":["劳务派遣单位","实际用工单位"],"summary":"湘江新区（岳麓区）劳务派遣单位 2026 年度失业保险稳岗返还的线下申请安排：单位可在 2026 年 12 月 31 日前为符合条件的实际用工单位线下申请稳岗返还，材料要求按长人社办函〔2024〕7 号执行；未按规定拨付稳岗返还资金、逾期未提交拨付凭证的，经办机构应要求退回未拨付部分并取消下一年度申领资格。受理窗口为岳麓区政府 7 栋一楼政务服务中心 52、53 号窗口。","sections":[{"no":"一","title":"政策依据","text":"为贯彻落实《湖南省人力资源和社会保障厅 湖南省教育厅 湖南省财政厅 国家税务总局湖南省税务局关于失业保险支持企业稳岗扩岗的通知》（湘人社规〔2026〕13号）精神，精准快速落实稳岗返还政策，现就劳务派遣单位申请享受稳岗返明确如下："},{"no":"二","title":"申请时限与执行要求","text":"湘江新区（岳麓区）劳务派遣单位可在2026年12月31日前为符合稳岗返还条件的实际用工单位线下申请稳岗返还，相关要求按《长沙市人力资源和社会保障局办公室 关于进一步明确2024年度线下申请失业保险稳岗返还相关资料的通知》（长人社办函〔2024〕7号）执行。对于未按规定拨付稳岗返还资金、逾期未提交拨付凭证的劳务派遣单位，经办机构应要求其退回未拨付部分，并取消下一年度申领资格。"},{"no":"三","title":"受理窗口与附件","text":"联系地址：长沙市岳麓区金星北路517号岳麓区政府7栋一楼政务服务中心52、53号窗口；联系电话：0731-88999648；电子邮箱：msjggfw@163.com。附件：湘江新区（岳麓区）初步符合2026年度稳岗返还劳务派遣单位名单。"}],"interpretations":[{"sectionNo":"二","headline":"劳务派遣单位12月31日前可为用工单位线下申请稳岗返还","who":"湘江新区（岳麓区）的劳务派遣单位；须为符合稳岗返还条件的实际用工单位申请，并按规定拨付资金、按期提交拨付凭证。","materials":["拨付凭证"],"window":"2026年12月31日前线下申请；拨付情况影响下一年度申领资格。","where":"线下申请，由湘江新区（岳麓区）经办机构受理（原文未列具体窗口）。","tip":"未按规定拨付稳岗返还资金或逾期未提交拨付凭证的，须退回未拨付部分，并取消下一年度申领资格。"},{"sectionNo":"三","headline":"受理窗口：岳麓区政府7栋一楼政务服务中心52、53号窗口","who":"湘江新区（岳麓区）办理2026年度稳岗返还的劳务派遣单位；附件所列单位为初步符合2026年度稳岗返还条件的劳务派遣单位。","materials":["湘江新区（岳麓区）初步符合2026年度稳岗返还劳务派遣单位名单"],"window":"在2026年度稳岗返还申请期内到窗口现场办理。","where":"长沙市岳麓区金星北路517号岳麓区政府7栋一楼政务服务中心52、53号窗口；电话0731-88999648；邮箱msjggfw@163.com。","tip":"附件名单只是初步符合名单，办理前先核对本单位是否在列，再到窗口提交。"}],"sourceUrl":"http://www.yuelu.gov.cn/yl_xxgk/tzgg/202611/t20261120_12624033.html","derivedFrom":"official","sourceNote":"取自岳麓区政府门户「通知公告」原文页，发文机关与日期已核对；该件为通知，无文号。发文主体为湖南湘江新区管理委员会（适用范围含岳麓区、望城区、高新区），收录时按管委会驻地归入岳麓区。2026-11-24 按原文三段重切全文；本通知只明确申请时限与执行口径，返还比例（大型企业、中小微企业分档）写在其依据文件湘人社规〔2026〕13 号中，通知本身不含比例。 2026-11-24 收录：与官方页面逐句比对，命中 7/7 句（100%），关卡判定「verbatim」。 有效期依据：原文未设有效期条款","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"cs-yuelu-xj6-manufacturing-2023","title":"湖南湘江新区管理委员会印发《关于湖南湘江新区（长沙高新区）推进先进制造业高质量发展的若干政策》的通知","level":"district","region":"长沙市·岳麓区","issuer":"湖南湘江新区管理委员会","documentNo":"湘新管发〔2023〕6号","publishedAt":"2023-01-30","effectiveAt":"2023-01-30","expiresAt":"2026-01-29","status":"expired","tags":["财政奖补","研发创新"],"audience":["新区直管区、托管区制造业企业","专精特新中小企业","智能制造服务商"],"summary":"湘江新区先进制造业高质量发展的金额标准：新获批国家级、省级智能制造示范企业分别一次性支持 100 万元、50 万元；智能化改造按设备投资额 500 万—3000 万元部分 3%、3000 万元以上部分 1% 支持，单个企业每年最高 100 万元；新获批国家级、省级制造业创新中心分别支持 2000 万元、200 万元；国家级专精特新「小巨人」50 万元（复核 10 万元）、省级专精特新中小企业 10 万元；瞪羚企业按一至四星级分别支持 30 万、40 万、60 万、100 万元；采购新区内企业产品 500 万元以上一次性支持 10 万元、每增 500 万元加 5 万元，单个企业当年不超过 200 万元。政策自公布之日起施行，有效期 3 年。","sections":[{"no":"一","title":"适用范围","text":"本政策适用于新区直管区、托管区的高校、科研院所、企业、创新创业平台及其他相关单位和个人。"},{"no":"二","title":"重点打造智能制造装备和工程机械、移动互联","text":"重点打造智能制造装备和工程机械、移动互联网及软件、先进计算及信息安全等具有世界影响力的先进制造业集群，扩大航空航天（含北斗）、新材料（先进储能材料）、生物医药及大健康、检验检测等集群优势，培育功率半导体及集成电路、人工智能、智能网联汽车等新兴产业集群，出台专项政策给予支持。"},{"no":"三","title":"支持企业开展工业智能化技术改造","text":"支持企业开展工业智能化技术改造1.对当年新获批的国家级、省级智能制造示范企业（项目）、智能制造标杆企业（车间）、服务型制造示范企业，分别一次性支持100万元、50万元，晋级补差。对获评国家、省、市智能制造试点示范企业（项目、车间）、智能制造标杆企业（车间）、服务型制造示范企业并经验收合格的，优先推荐该企业生产的符合条件的产品纳入新区两型产品目录。2.对市级及以上智能制造试点示范企业采购工业软件和智能装备进行智能化技术改造且有明显质效提升的，按采购价格的15%给予支持，单个企业支持金额最高不超过500万元。支持智能制造服务商向新区企业提供服务，对通过市工信局组织的专家评审的，根据当年市级给予服务商支持的50%配套支持，最高支持金额不超过10万元。3.对企业新增技术改造项目，当年设备投资额（含网络改造工程，软件和信息技术服务投入）在500万元（含）以上的，经新区认定并纳入统计数据库后给予支持：设备投资额500万元（含）-3000万元的部分，按该部分设备投资额的3%支持;设备投资额3000万元（含）以上的部分，按该部分设备投资额的1%支持。单个企业每年最高支持金额，不超过100万元。"},{"no":"四","title":"支持制造业数字化、网络化融合发展","text":"支持制造业数字化、网络化融合发展1.对当年新获批的国家级、省级两化融合管理体系贯标标杆（试点）企业，分别一次性支持25万元、10万元。2.对当年新获批工信部“技术创新示范企业”“制造业与互联网融合发展试点示范项目”“工业互联网试点示范项目”等试点示范的企业（项目），一次性支持50万元。"},{"no":"五","title":"实施“五首”产品支持","text":"实施“五首”产品支持。对获评湖南省先进制造业首台套技术设备、首批次新材料、首版次高端软件、首轮次工程流片芯片、首套件基础电子元器件产品的，按获批省级资金的50%给予支持，每家支持金额不超过100万元。"},{"no":"六","title":"支持建设工业绿色制造体系","text":"支持建设工业绿色制造体系。对当年首次认定为绿色工厂或绿色供应链管理示范的企业，按国家级、省级分别一次性支持50万元、30万元。对当年首次通过自愿性清洁生产审核验收的企业，一次性支持10万元。"},{"no":"七","title":"培育示范应用场景","text":"培育示范应用场景1.支持科技创新场景应用。为科技创新企业的新产品、新技术、新服务、新应用创造可落地的应用场景，加速科技型创新企业发展，推动前沿科技与新区城市建设、民生服务、优势产业发展深度融合。支持新区财政性资金和新区企业开展首购活动。2.对获评基于PK体系、华为鲲鹏体系的终端设备及应用服务示范项目或场景，对承担单位给予研发投入15%、最高不超过250万元的补助。"},{"no":"八","title":"支持企业扩大发展规模","text":"支持企业扩大发展规模1.对当年新进规模以上工业企业，一次性给予主要经营者（主要经营者指董事长、总经理和副总经理级别财务负责人，下同）15万元支持，当年新进规模以上其他类企业的，给予主要经营者一次性5万元支持，以统计职能部门提供的企业名单为准。2.对当年产值或应税收入在2000万元（含）-1亿元的企业，当年产值或应税收入增幅超过30%、且实际入库税收（不含个人所得税及其他代扣代缴的等非企业自身缴纳税收以及费金等非税收入，下同）增幅超过20%，一次性支持主要经营者2万元。对当年产值或应税收入在1亿元（含）-10亿元的企业，当年产值或应税收入首次突破1亿元、且当年实际入库税收不低于200万元，一次性支持主要经营者5万元;当年产值或应税收入增幅超过20%、且实际入库税收增幅超过15%，一次性支持主要经营者5万元。对当年产值或应税收入在10亿元（含）-100亿元的企业，当年产值或应税收入首次突破10亿元、且当年实际入库税收不低于2000万元，一次性支持主要经营者20万元;当年产值或应税收入增幅超过15%、且实际入库税收增幅超过10%，一次性支持主要经营者20万元。对当年产值或应税收入在100亿元（含）以上的企业，当年产值或应税收入首次突破100亿元、且当年实际入库税收不低于2亿元，一次性支持主要经营者200万元;当年产值或应税收入增幅超过10%、且实际入库税收增幅超过5%，一次性支持主要经营者100万元。本条所述支持晋级补差，不重复支持。"},{"no":"九","title":"支持创建制造业创新中心","text":"支持创建制造业创新中心。对当年新获批的国家级、省级制造业创新中心，分别给予2000万元、200万元支持，晋级补差。"},{"no":"十","title":"鼓励公共技术平台发展","text":"鼓励公共技术平台发展1.对企业组建的公共技术服务平台，按照平台对新区内企业服务能力、平台收入等进行年度综合评价，排名前五名的给予支持，单个平台支持金额最高不超过30万元。2.对当年新认定的国家级产业技术创新战略联盟，一次性支持20万元。对当年经新区评定为优秀等级的技术、产业联盟，一次性支持20万元。"},{"no":"十一","title":"实施企业梯度培育计划","text":"实施企业梯度培育计划1.对经新区认定的雏鹰企业，一次性支持20万元。2.对经新区认定的瞪羚企业，按一、二、三、四星级分别一次性支持30万元、40万元、60万元、100万元，晋级补差。3.对当年新获批国家级专精特新“小巨人”企业、省级专精特新中小企业，分别给予50万元（复核10万元）、10万元支持，并优先纳入新区两型产品目录。4.对当年新获批国家制造业单项冠军企业、单项冠军产品的，分别一次性支持100万元、50万元，并优先纳入新区两型产品目录。"},{"no":"十二","title":"支持企业开展标准化建设","text":"支持企业开展标准化建设1.对企业承担国际标准化组织相关专业秘书处的，一次性支持30万元;对承担国家专业标准化技术委员会秘书处的，一次性支持20万元;对承担国家专业标准化分技术委员会秘书处的，一次性支持10万元。2.对企业主导制订、修订国际标准的，一次性支持10万元;对主导制订、修订国家标准、行业标准、地方标准、团体标准的，一次性支持5万元。"},{"no":"十三","title":"引导企业强化质量管理","text":"引导企业强化质量管理1.对首次获中国质量奖、省长质量奖、市长质量奖的企业，分别给予50万元、20万元、15万元支持;获新区质量奖的企业或组织给予20万元支持，个人给予5万元支持;2.对企业当年新获CMMI3、CMMI4、CMMI5等级认证的，分别支持10万元、20万元、30万元，晋级补差。"},{"no":"十四","title":"鼓励新区企业配套采购产品","text":"鼓励新区企业配套采购产品。对企业采购新区内其他企业（非关联）产品，当年度实际（非关联）采购额达500万元（含）的（依据税务机关开具的发票统计），一次性支持采购企业10万元;实际采购额每增加500万元，增加5万元支持。单个企业当年支持总额不超过200万元。"},{"no":"十五","title":"加大企业帮扶力度","text":"加大企业帮扶力度。对制造业企业开展专项帮扶，建立长效帮扶机制、组织专班，针对行业共性问题和企业个性问题深入研究、分类施策，做好资金、用工、供应链、土地等要素保障，着力破解成本上涨、市场需求、生产要素、经营管理等方面的“急难愁盼”问题。"},{"no":"十六","title":"其他事项（就高不就低）","text":"本政策与新区财政承担的同类政策按“就高不就低”原则不重复支持;享受“一事一议”政策的，不再享受普惠政策。"},{"no":"十七","title":"区域范围","text":"新区直管区包括岳麓区全境，托管区包括望城区白箬铺镇、白马街道、雷锋街道、金山桥街道和黄金园街道。"},{"no":"十八","title":"施行与解释","text":"本政策自公布之日起施行，有效期3年，由湖南湘江新区管理委员会负责解释，原有相关政策与本文件不一致的，以本文件为准。"}],"interpretations":[{"sectionNo":"一","headline":"新区直管区、托管区的高校、科研院所、企业、平台均可申报","who":"湖南湘江新区直管区、托管区范围内的高校、科研院所、企业、创新创业平台及其他相关单位和个人。","materials":[],"window":"政策施行期内持续适用；原文未另设申报期限。","where":"湖南湘江新区管理委员会","tip":"高校、科研院所、平台等非企业主体同样在适用范围内，不限企业。"},{"sectionNo":"三","headline":"国家级智能制造示范企业一次性支持100万元，省级50万元","who":"新区内的工业企业与智能制造服务商：当年新获批国家级、省级智能制造示范企业（项目）、智能制造标杆企业（车间）、服务型制造示范企业；市级及以上智能制造试点示范企业采购工业软件和智能装备实施技改；新增技改项目当年设备投资额500万元（含）以上并纳入统计数据库的企业。","materials":[],"window":"按年度认定，当年新获批或当年设备投资额达标；技改部分单个企业每年最高不超过100万元。","where":"湖南湘江新区管理委员会（经新区认定并纳入统计数据库）","tip":"智能制造示范晋级补差；技改按设备投资额500万元（含）至3000万元部分3%、3000万元（含）以上部分1%分段计算。"},{"sectionNo":"四","headline":"两化融合贯标标杆国家级支持25万元、省级10万元","who":"新区内当年新获批国家级、省级两化融合管理体系贯标标杆（试点）的企业；当年新获批工信部技术创新示范企业、制造业与互联网融合发展试点示范项目、工业互联网试点示范项目等试点示范的企业（项目）。","materials":[],"window":"当年新获批，按年度一次性支持。","where":"湖南湘江新区管理委员会","tip":"两化融合贯标与工信部试点示范是两类不同支持，前者为25万元与10万元，后者一次性50万元。"},{"sectionNo":"五","headline":"五首产品按省级资金50%配套，每家最高100万元","who":"获评湖南省先进制造业首台套技术设备、首批次新材料、首版次高端软件、首轮次工程流片芯片、首套件基础电子元器件产品的企业。","materials":[],"window":"获评省级五首产品后按省级资金配套，原文未设申报期限。","where":"湖南湘江新区管理委员会","tip":"按获批省级资金的50%给予支持，每家支持金额不超过100万元。"},{"sectionNo":"六","headline":"绿色工厂国家级支持50万元、省级30万元，清洁生产10万元","who":"当年首次认定为绿色工厂或绿色供应链管理示范的企业（国家级、省级）；当年首次通过自愿性清洁生产审核验收的企业。","materials":[],"window":"当年首次认定或首次通过验收，一次性支持。","where":"湖南湘江新区管理委员会","tip":"只支持首次认定或首次通过验收，复核与再次认定不在本条款范围。"},{"sectionNo":"七","headline":"鲲鹏、PK体系示范场景按研发投入15%补，最高250万元","who":"承担基于PK体系、华为鲲鹏体系的终端设备及应用服务示范项目或场景的单位；科技创新企业可参与新区财政性资金和新区企业的首购活动。","materials":[],"window":"获评示范项目或场景后给予补助，原文未设申报期限。","where":"湖南湘江新区管理委员会","tip":"补助按研发投入的15%计算，最高不超过250万元。"},{"sectionNo":"八","headline":"新进规模以上工业企业，主要经营者一次性支持15万元","who":"新区内当年新进规模以上工业企业（主要经营者指董事长、总经理和副总经理级别财务负责人）、当年新进规模以上其他类企业；以及当年产值或应税收入达2000万元（含）以上并满足增幅与税收门槛的企业主要经营者。","materials":[],"window":"按年度认定，以统计职能部门提供的企业名单为准；一次性支持，晋级补差不重复支持。","where":"湖南湘江新区管理委员会（以统计职能部门提供的企业名单为准）","tip":"本条支持晋级补差、不重复支持；产值或应税收入分2000万元至1亿元、1亿元至10亿元、10亿元至100亿元、100亿元以上四档。"},{"sectionNo":"九","headline":"国家级制造业创新中心支持2000万元、省级200万元","who":"新区内当年新获批国家级、省级制造业创新中心的单位。","materials":[],"window":"当年新获批，一次性支持，晋级补差。","where":"湖南湘江新区管理委员会","tip":"晋级补差：先获省级200万元、后获国家级2000万元的，按差额补齐。"},{"sectionNo":"十","headline":"公共技术服务平台年度评价前五名，单个最高支持30万元","who":"新区内企业组建的公共技术服务平台（按服务能力、平台收入年度综合评价排名前五名）；当年新认定的国家级产业技术创新战略联盟；经新区评定为优秀等级的技术、产业联盟。","materials":[],"window":"平台按年度综合评价；联盟为当年新认定或当年评定。","where":"湖南湘江新区管理委员会","tip":"平台支持按年度评价排名取前五名，单个平台最高30万元；联盟支持为一次性20万元。"},{"sectionNo":"十一","headline":"瞪羚企业按星级支持30万至100万元，小巨人50万元","who":"经新区认定的雏鹰企业、瞪羚企业（一至四星级）；当年新获批国家级专精特新小巨人企业、省级专精特新中小企业；当年新获批国家制造业单项冠军企业、单项冠军产品。","materials":[],"window":"按年度认定；专精特新小巨人复核支持10万元。","where":"湖南湘江新区管理委员会","tip":"瞪羚企业星级晋级补差；国家级小巨人50万元、复核10万元，省级专精特新中小企业10万元。"},{"sectionNo":"十二","headline":"承担国际标准化组织秘书处支持30万元，主导国际标准10万元","who":"新区内承担国际标准化组织相关专业秘书处、国家专业标准化技术委员会秘书处、国家专业标准化分技术委员会秘书处的企业；主导制订、修订国际标准或国家、行业、地方、团体标准的企业。","materials":[],"window":"承担秘书处或主导标准制订、修订后一次性支持。","where":"湖南湘江新区管理委员会","tip":"秘书处分三档30万元、20万元、10万元；标准中国际标准10万元，国家、行业、地方、团体标准均为5万元。"},{"sectionNo":"十三","headline":"中国质量奖50万元、省长质量奖20万元、市长质量奖15万元","who":"首次获中国质量奖、省长质量奖、市长质量奖的企业；获新区质量奖的企业或组织、个人；当年新获CMMI3、CMMI4、CMMI5等级认证的企业。","materials":[],"window":"首次获奖或当年新获认证，一次性支持；CMMI晋级补差。","where":"湖南湘江新区管理委员会","tip":"新区质量奖企业或组织20万元、个人5万元；CMMI3、CMMI4、CMMI5分别10万元、20万元、30万元。"},{"sectionNo":"十四","headline":"采购新区内非关联企业产品满500万元，一次性支持10万元","who":"采购新区内其他企业（非关联）产品、当年度实际非关联采购额达500万元（含）以上的企业，采购额依据税务机关开具的发票统计。","materials":["税务机关开具的发票（用于统计实际采购额）"],"window":"按当年度实际采购额统计，一次性支持。","where":"湖南湘江新区管理委员会（依据税务机关开具的发票统计）","tip":"采购额每增加500万元增加5万元支持，单个企业当年支持总额不超过200万元。"},{"sectionNo":"十六","headline":"同类政策就高不就低不重复支持，一事一议者不享普惠","who":"同时符合新区财政承担的同类政策的企业；已享受一事一议政策的企业不再享受普惠政策。","materials":[],"window":"政策有效期内适用。","where":"湖南湘江新区管理委员会（新区财政承担的政策）","tip":"同类政策只能选一头：按就高不就低原则不重复支持。"},{"sectionNo":"十七","headline":"新区直管区含岳麓区全境，托管区含望城白箬铺镇等五街镇","who":"注册或坐落于新区直管区（岳麓区全境）、托管区（望城区白箬铺镇、白马街道、雷锋街道、金山桥街道和黄金园街道）的单位。","materials":[],"window":"政策有效期内适用。","where":"新区直管区、托管区属地范围","tip":"托管区仅含望城区白箬铺镇、白马街道、雷锋街道、金山桥街道、黄金园街道，其他街镇不在政策范围。"}],"sourceUrl":"https://www.changsha.gov.cn/zfxxgk/zfwjk/gdwxtwj/202303/P020230302532508668311.pdf","derivedFrom":"official","sourceNote":"取自长沙市政府门户「政府文件—各单位系统文件」所挂 PDF 原件（湘新管发〔2023〕6号，8 页，带文字层）。2026-11-24 按原文八部分、（一）至（十七）项全文转录为 18 条；原文以半角逗号、括号排版，转录时统一为全角，文字与数字未改。该政策是《关于申报2022—2026年湖南湘江新区企业普惠政策兑现的通知》所列 30 个兑现政策文件之一。 2026-11-24 收录：与官方页面逐句比对，命中 42/42 句（100%），关卡判定「verbatim」。 有效期依据：（十七）本政策自公布之日起施行，有效期3年","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"cs-yuhua-hightech-apply-2025","title":"关于组织开展雨花区2025年度高新技术企业申报工作的通知","level":"district","region":"长沙市·雨花区","issuer":"长沙市雨花区科学技术局","documentNo":"","publishedAt":"2025-05-30","effectiveAt":null,"expiresAt":null,"status":"active","tags":["认定资质","研发创新"],"audience":["雨花区注册成立一年以上的居民企业","2022 年认定到期需重新认定的企业"],"summary":"雨花区 2025 年度高新技术企业申报组织安排：评审分两批，第一批受理截止 2025 年 6 月 15 日、第二批截止 9 月 23 日；申报对象为在雨花区注册成立一年以上、符合《认定办法》第十一条的居民企业，2022 年认定到期企业须重新认定。出具专项审计报告的中介机构须近三年无不良记录，注册会计师或税务师人数占职工全年月平均人数比例不低于 30%，全年月平均在职职工 20 人以上。","sections":[{"no":"一","title":"申报时间安排","text":"2025年度雨花区高企认定评审工作分二批进行，第一批申报受理截止时间为2025年6月15日（星期天）；第二批申报受理截止时间为2025年9月23日（星期二）。"},{"no":"二","title":"申报对象","text":"（一）在雨花区行政区域内注册成立一年以上的居民企业，且符合《认定办法》第十一条有关规定。（二）2022年通过高企认定的企业，2025年高企资格期满，须重新提请认定。2022年认定为高企的企业，名称或注册地发生变化的，应先完成高企相关事项变更，同时完成高企年报填报，再进行高企认定申报。"},{"no":"三","title":"申报程序","text":"（一）自我评价。企业应对照《认定办法》《工作指引》进行自我评价。符合条件的，选择符合《工作指引》第一条第三项有关规定的会计师事务所或税务师事务所，对研究开发费用以及高新技术产品（服务）收入进行专项审计（鉴证），并按照《认定办法》《工作指引》和本通知要求自主编写完成高新技术企业认定申请材料。（二）注册登记。为进一步做好雨花区高新技术企业培育管理工作，企业可登录高新技术企业认定管理工作网（www.innocom.gov.cn）按操作流程完成注册登记。已注册过的企业，无需重新注册，忘记用户名、密码的企业，可按照系统提示找回信息。（三）提交材料。1.网上申报材料提交。企业登录高新技术企业认定管理工作网（www.innocom.gov.cn），按要求填写《高新技术企业认定申请书》，并上传相关附件，检查无误后通过网络系统提交。2.现场申报材料受理。企业提交网上申报材料的同时须在申报截止日前将加盖公章的高企申报纸质材料正本（为节约资源，企业不需提供副本）交区科技局科技计划科办公室（长沙市雨花区香樟路雨花区政府2号楼B336办公室），具体申报材料要求详见《湖南省高新技术企业认定申报材料清单和要求》（附件1）。3.加强申报工作规范管理。请申报企业如实填写《高新技术企业认定申报推荐汇总表》（附件2）、《高新技术企业认定申报综合信息表》（附件5）以及《高新技术企业认定申报基本情况表》（附件6），并将附件2、5、6的盖章纸质件交至所属辖区街道（镇），雨花经开区企业交至雨花经开区产业发展局，同时提交附件2、5、6的word版电子档（电子版可不加盖公章，扫描件或者PDF文件）（必须在邮件主题处备注工商营业执照上的企业全称），由雨花经开区产业发展局、跳马镇人民政府、各街道办事处汇总推荐企业情况后（附件2、5、6）交至区科技局科技计划科。（四）核实初审。申报企业对提交的高企申报材料真实性、完整性负责。雨花经开区产业局、跳马镇人民政府、各街道办事处配合区科技局做好辖区申报企业（企业提前携带相关资料到注册所在地的雨花经开区产业发展局、跳马镇人民政府、各街道办事处备案及盖章）的现场核实和推荐工作，区科技局负责全区高企申报企业申报材料的初审工作，并统一将企业申报纸质材料报送长沙市科技局创新与产业发展处。"},{"no":"四","title":"工作要求","text":"（一）雨花经开区产业发展局、跳马镇人民政府、各街道办事处要高度重视，按照本通知要求，积极开展宣传发动、政策培训、专业技术宣讲，扎实做好相关政策解读、咨询答疑等工作。切实做好高企申报的现场核实，严格按照时间节点和要求认真组织好辖区内高企认定申报工作，进一步提高申报质量。（二）企业聘用中介机构应认真查询其相关资质和信用等，确保所聘用的中介机构符合条件，出具专项审计报告或鉴证报告的中介机构须近三年内无不良记录（不良记录指刑事、行政处罚、行业惩戒等记录），承担认定工作当年的注册会计师或税务师人数占职工全年月平均人数的比例不低于30%，全年月平均在职职工人数在20人以上。查询会计师事务所信息，可在“中国注册会计师协会”网站（https://www.cicpa.org.cn/），点击左下方“行业管理信息查询”—在左下方“公共查询”中，再点击“会计师事务所信息查询（立即查询）”—输入要查询中介机构名称；查询税务师事务所信息，可在“中国注册税务师协会”网站点击首页右下方的“信息服务平台”，进入中税协信息服务平台，点击“行业管理”—再点击“税务师事务所查询/（注册）税务师查询。同时，提供服务的中介机构应出具符合条件的书面承诺。（三）省认定办、市区科技局未授权、委托或认定任何单位、社会组织或中介机构作为高企申报代理代办机构。各申报企业应提高警惕，不要轻信任何单位或个人给出的各种承诺，避免合法权益受损。（四）参与企业研发费用、高新技术产品（服务）收入专项审计或鉴证的中介机构须符合《工作指引》中规定的中介机构条件，严格按照《认定办法》规定的相关财务指标，据实出具专项审计或鉴证报告，对企业的研发费用、高新技术产品（服务）收入情况及相关编制说明发表明确的意见。对工作中出现严重失误或弄虚作假的中介机构，实行追溯倒查，按照《工作指引》相关规定，在“高新技术企业认定管理工作网”上公告，自公告之日起三年内不得参与高企认定相关工作。有关部门将加大对中介机构配合财务造假行为的打击力度，按规定将业务报告数量明显超出服务能力的中介机构列为年度重点检查对象。对检查发现的未按执业准则、规则出具的审计报告、鉴证报告不予采用，对相关中介机构按规定进行处理处罚，造成损失的，由企业和中介机构自行承担。（五）雨花经开区产业发展局、跳马镇人民政府、各街道办事处要积极引导企业充分享受研发费用税前加计扣除政策，引导符合条件企业在提出高企认定申请的同时参与科技型中小企业评价入库工作，以便享受有关支持科技型企业的扶持政策。（六）企业应诚信申报，对申报材料的真实性、完整性负责，并作出书面承诺。报送的纸质材料只须包含湖南省高新技术企业认定申报材料要求的内容，须标注页码，书脊处须注明申报年度、企业名称、所属技术领域、册数。涉密企业须将申报材料进行脱密处理，确保涉密信息安全。在认定管理过程中若发现企业提供虚假信息行为的，一经查实，将按规定严肃处理并通报相关部门。"},{"no":"五","title":"联系方式","text":"（一）政策咨询。湖南省认定办：湖南省科技厅成果转化处周玉林0731－88988819；湖南省财政厅税政法规处肖淳丹0731－85165043；湖南省税务局企业所得税处饶逸0731－85579162。（二）系统申报及材料报送。湖南省火炬创业中心刘军0731－88988749；湖南省火炬创业中心傅为0731－88988755；长沙市科技局创新与产业发展处0731－88666993；长沙生产力促进中心0731－82843339；雨花区区科技局科技计划科潘邹璇0731－85880249。（二）雨花经开区产业发展局、跳马镇人民政府、各街道办事处高企申报工作咨询电话详见附件3。"}],"interpretations":[{"sectionNo":"一","headline":"高企申报分两批，6月15日、9月23日截止","who":"雨花区行政区域内拟申报2025年度高新技术企业认定的企业。","materials":[],"window":"第一批受理截止2025年6月15日；第二批截止2025年9月23日。","where":"雨花区科学技术局","tip":"2025年度仅设两批受理，按截止时间提交。"},{"sectionNo":"二","headline":"注册满一年以上居民企业可申报，2022年认定企业须重认","who":"在雨花区行政区域内注册成立一年以上的居民企业，且符合《认定办法》第十一条；2022年通过高企认定、2025年资格期满的企业须重新提请认定；名称或注册地变化的须先完成高企事项变更并完成年报。","materials":["高企相关事项变更材料","高企年报"],"window":"注册成立一年以上；2022年认定企业2025年资格期满须重新认定。","where":"雨花区科学技术局","tip":"名称或注册地变化未先完成变更和年报的，不能直接申报认定。"},{"sectionNo":"三","headline":"网上填报并交纸质正本至区科技局，街道备案盖章","who":"雨花区申报高新技术企业认定的企业（含雨花经开区企业）。","materials":["《高新技术企业认定申请书》（网上填报）","加盖公章的高企申报纸质材料正本","《高新技术企业认定申报推荐汇总表》（附件2）","《高新技术企业认定申报综合信息表》（附件5）","《高新技术企业认定申报基本情况表》（附件6）","专项审计（鉴证）报告"],"window":"申报截止日前提交网上材料与纸质正本；附件2、5、6交所属街道（镇）或雨花经开区产业发展局。","where":"高新技术企业认定管理工作网（www.innocom.gov.cn）；区科技局科技计划科办公室（长沙市雨花区香樟路雨花区政府2号楼B336办公室）","tip":"纸质材料只交正本、不需副本；附件2、5、6另交word版电子档；区科技局统一报送长沙市科技局。"},{"sectionNo":"四","headline":"中介须近三年无不良记录，注会税务师占比不低于30%","who":"申报高企的企业及其聘用的中介机构；中介须近三年无刑事、行政处罚、行业惩戒记录，承担当年注册会计师或税务师人数占职工全年月平均人数比例不低于30%，全年月平均在职职工20人以上。","materials":["中介机构出具的符合条件的书面承诺","标注页码、书脊注明申报年度和企业名称等信息的纸质材料","涉密企业脱密处理后的申报材料"],"window":"申报及认定管理全过程；中介违规自公告之日起三年内不得参与高企认定。","where":"省认定办、长沙市科技局、雨花区科技局（未授权任何代理代办机构）","tip":"省认定办、市区科技局未授权任何单位或个人代理代办；提供虚假信息一经查实严肃处理。"},{"sectionNo":"五","headline":"申报咨询与材料报送渠道见省、市、区三级联系方式","who":"2025年度雨花区高企申报企业。","materials":[],"window":"申报期内接受政策咨询与系统申报咨询。","where":"湖南省认定办（省科技厅成果转化处、省财政厅税政法规处、省税务局企业所得税处）；湖南省火炬创业中心；长沙市科技局创新与产业发展处；长沙生产力促进中心；雨花区科技局科技计划科；雨花经开区产业发展局、跳马镇人民政府、各街道办事处","tip":"系统申报及材料报送找省火炬创业中心、长沙生产力促进中心、区科技局科技计划科。"}],"sourceUrl":"http://www.yuhua.gov.cn/zwgk97/jcxxgk/zcwj/zcwj8293/202506/t20250603_11874430.html","derivedFrom":"official","sourceNote":"取自雨花区政府门户「政策文件—政务文件」原文页，页面标注来源区科技局；该件为年度申报通知，无文号。2026-11-24 按原文五部分重切全文；本通知只讲申报时间、对象、程序与要求，认定奖励金额不在本通知内（雨花区高企认定补贴见《雨花区促进经济高质量发展扶持奖励办法》），通知本身不含金额。 2026-11-24 收录：与官方页面逐句比对，命中 40/40 句（100%），关卡判定「verbatim」。 有效期依据：原文未设有效期条款","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"cs-yuhua-lowaltitude-plan-2024","title":"长沙雨花经开区低空经济高质量发展三年行动计划（2024—2026年）","level":"district","region":"长沙市·雨花区","issuer":"长沙雨花经济开发区管理委员会","documentNo":"雨开工发〔2024〕26号","publishedAt":"2024-10-28","effectiveAt":"2024-10-28","expiresAt":"2026-12-31","status":"expiring","tags":["研发创新","营商环境"],"audience":["无人机制造与研发企业","无人机应用服务企业","初创企业及项目团队"],"summary":"以同升湖人工智能科创谷为核心建设无人机人工智能试飞区和“人工智能+低空经济”产业示范区，三年内吸引至少10家国内外知名无人机制造企业和研发机构入驻、培育30家以上无人机应用服务企业、建成至少3个无人机产业平台和10个以上垂直起降点，为初创企业和项目提供资金支持、技术咨询、市场拓展等服务。","sections":[{"no":"二（一）","title":"建设全国民用无人驾驶航空试验区","text":"(一)建设全国民用无人驾驶航空试验区。抢抓全省低空空域全域开放的政策机遇,争取打造国家级低空飞行测试试验区。计划在未来三年内,吸引至少10家国内外知名的无人机制造企业和研发机构入驻,培育30家以上的无人机应用服务企业,无人机驾驶员培训规模扩大至每年培养500名合格操控员。建立完善的无人机监管体系,确保飞行安全,为无人机产业的发展提供良好的政策环境和社会氛围。"},{"no":"二（二）","title":"打造低空经济无人机产业中部加速器","text":"(二)打造低空经济无人机产业中部加速器。发挥雨花经开区产业基础和科研优势,围绕“一域、一谷、一镇、一园、一街区、一大厦”产业规划,打造低空经济无人机产业的中部加速器。在未来三年内,建立起至少3个无人机产业平台,10个以上垂直起降点,无人机飞行取得突破性进展。孵化出一批具有核心竞争力的无人机企业,新增就业岗位超过1000个。为初创企业和项目提供资金支持、技术咨询、市场拓展等全方位服务。"},{"no":"二（三）","title":"建设低空制造为主体的产业示范区和应用区","text":"(三)建设低空制造为主体的产业示范区和应用区。推动产业集群化发展,集中力量打造工业级无人机主机制造、中小发动机制造、无人机关键零配件制造、MRO服务(维护、维修与检修)四个产业集群。通过政策引导和项目扶持,推动无人机技术的研发和应用创新,到2026年,在低空制造、智能物流、智慧文旅、环境监测、应急救援等领域取得突破,新增10个以上应用场景,力争三年内园区低空经济总产值达到30亿元,成为推动区域经济发展的重要力量。"},{"no":"三（一）1","title":"建设优质试飞空域","text":"1.建设优质试飞空域。打造长沙真高120米以下,面积260平方公里辐射长株潭的优质低空试飞空域,在空域内提供低空通航“飞得起”“落得下”的基础和支撑,探索建设38号地、25号地、同升湖等飞行试验区和航线,积极向上争取长期空域和简便飞行。"}],"interpretations":[],"sourceUrl":"http://yhjkq.changsha.gov.cn/xxgk50/xxgkml65/lzyj/zcwj/202502/t20250219_11752385.html","sourceNote":"2026-11-22 取自雨花经开区门户「政府信息公开—法定主动公开内容—履职依据—规范性文件」原文页；页面标注文号雨开工发〔2024〕26号、信息时效期2026-12-31。 2026-11-22 收录：与官方页面逐句比对，命中 13/13 句（100%），关卡判定「verbatim」。 有效期依据：页面「信息时效期」标注为2026-12-31，据此确定到期日","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"cs-yuhua-newenergy-project-2026","title":"长沙市雨花区发展和改革局关于印发《长沙市雨花区新能源项目建设管理办法》的通知","level":"district","region":"长沙市·雨花区","issuer":"长沙市雨花区发展和改革局","documentNo":"雨发改发〔2026〕4号","publishedAt":"2026-08-11","effectiveAt":"2026-08-11","expiresAt":null,"status":"active","tags":["营商环境"],"audience":["分布式光伏项目投资企业","电化学储能项目建设单位","充换电基础设施建设运营企业"],"summary":"雨花区新能源项目（分布式光伏、电化学储能、电动汽车充换电基础设施）建设管理办法：项目经省投资项目在线审批监管平台备案，备案后 2 年内未开工应撤回备案信息；属地街镇与区自然资源、住建部门各 3 个工作日内完成现场核查与联合审查，通过后方可开工；分布式光伏坡屋面组件垂直高度不超过 30 厘米、平屋面光伏板顶端距屋顶不高于 1.5 米；公用专用充换电设施竣工须委托具备 CMA 资质的第三方检测机构验收，并在 15 个工作日内向区发改局递交验收报告。","sections":[{"no":"一","title":"总则","text":"为规范雨花区新能源项目建设管理，根据湖南省发展和改革委员会关于印发《湖南省电动汽车充换电基础设施建设与运营管理办法》的通知（湘发改能源规〔2025〕289号）、湖南省发展和改革委员会关于印发《湖南省分布式光伏发电开发建设管理实施细则》的通知（湘发改能源规〔2025〕843号）、湖南省发展和改革委员会《关于规范新型储能项目管理有关事项的通知》（湘发改能源〔2024〕760号）等相关规定，结合工作实际，制定本办法。"},{"no":"二","title":"总则","text":"本办法所称的新能源项目包括：分布式光伏、电化学储能、电动汽车充换电基础设施项目（以下简称新能源项目）（一）电动汽车充换电基础设施项目是指为电动汽车提供电能补给的各类充换电设施。自用充电设施：指在私人固定停车位上安装的，专为个人自用电动汽车提供充电的设施；专用充电设施：指专为公交、客运、环卫以及单位、企业内部等特定的电动汽车提供充电服务的设施；公用充电设施：指为非特定的电动汽车提供充电服务的设施；换电设施：指电池更换区、电池充电区和电池存储区置于露天场地或构筑物内，为电动汽车提供电池更换服务的设施（非建筑物）。（二）分布式光伏发电项目分为自然人户用、非自然人户用、一般工商业和大型工商业四种类型。自然人户用分布式光伏：是指自然人利用自有住宅、庭院投资建设，与公共电网连接点电压等级不超过380伏的分布式光伏；非自然人户用分布式光伏：是指非自然人利用居民住宅、庭院投资建设，与公共电网连接点电压等级不超过10千伏、总装机容量不超过6兆瓦的分布式光伏；一般工商业分布式光伏：是指利用党政机关、学校、医院、市政、文化、体育设施、交通场站等公共机构以及工商业厂房等建筑物及其附属场所建设，与公共电网连接点电压等级不超过10千伏、总装机容量原则上不超过6兆瓦的分布式光伏；大型工商业分布式光伏：是指利用建筑物及其附属场所建设，接入用户侧电网或者与用户开展专线供电（不直接接入公共电网且用户与发电项目投资方为同一法人主体），与公共电网连接点电压等级为35千伏、总装机容量原则上不超过20兆瓦或者与公共电网连接点电压等级为110千伏、总装机容量原则上不超过50兆瓦的分布式光伏。除上述四类分布式光伏项目外，其他光伏项目统一按集中式光伏项目管理。（三）电化学储能项目是指以输出电力为主要形式，并对外提供服务的储能，按其接入系统位置分为电源侧储能、电网侧储能和用户侧储能三类。电源侧储能指装设并接入在常规电厂、风电场、光伏电站等电源厂站内部的新型储能设施；电网侧储能指在专用站址建设，直接接入公用电网的储能设施；用户侧储能指在用户内部场地建设，直接接入用户内部配电设施的新型储能设施，所充电能原则上在用户内部消纳。"},{"no":"三","title":"项目备案","text":"雨花区范围内的新能源项目单位通过湖南省投资项目在线审批监管平台向雨花区发展和改革局申请办理备案手续，备案内容及要求按照湖南省发改委相关文件执行。"},{"no":"四","title":"项目备案","text":"项目自备案后2年内未开工建设或者未办理任何其他手续的，项目单位应当撤回已备案信息。已备案的项目，其投资主体及股权比例等主要内容不得擅自变更，在项目竣工前不得转让。对确需变更项目业主、建设地址、建设规模、建筑物权属人等，应向原备案部门办理相关变更手续，项目所涉及的相关权益和责任须一并移交。"},{"no":"五","title":"项目备案","text":"发现本行政区域内的已开工项目应备案但未依法备案的，应当责令项目单位限期改正，要求项目单位根据备案权限及时办理备案；逾期不改正的，将相关主体纳入失信名单，依法开展联合监管。第三章项目建设、验收及运维"},{"no":"六","title":"项目建设验收及运维","text":"项目备案后，项目建设单位向属地街镇提交项目初步建设方案，方案应包含项目选址、建设规模、用地性质等基本信息。属地街镇在3个工作日内完成现场核查，填写《长沙市雨花区新能源项目建设意见表》（详见附件），重点核实项目选址是否在拆迁范围、群诉群访等情况，出具现场核查意见并反馈至项目建设单位。项目建设单位持属地街镇核查意见及项目相关材料，向区自然资源局、区住房城乡建设局提交联合审查资料，重点核查项目选址是否符合国土空间规划、用地手续是否合规，项目设计是否符合相关规范，结构安全是否符合要求、涉及配套基础设施建设是否符合要求。各单位在3个工作日内完成审查并出具审查意见。通过联合审查的项目方可开工建设。《长沙市雨花区新能源项目建设意见表》报区发展改革局报备。"},{"no":"七","title":"项目建设验收及运维","text":"新能源项目设计须符合《分布式光伏工程施工标准》《电动汽车充电站设计标准》（GB/T50966）（DBJ43/T105）、《电化学储能电站设计标准》（GB/T51048-2025）《湖南省电动汽车充电设施设计标准》（DBJ43/T016）的相关要求，按照《分布式光伏工程验收标准》（DBJ43/T207）、《建筑防火通用规范》（GB55037）、《火力发电厂与变电站设计防火标准》（GB50229-2019）等要求，落实项目设计、施工、验收全过程管理。"},{"no":"八","title":"项目建设验收及运维","text":"分布式光伏发电项目开工建设前，投资主体应确保建设场所合法合规，手续齐全，产权清晰。应对建构筑物可使用年限、载荷能力、周边环境等进行评估，确保建设可行性和安全性。不得在未取得相关利益人同意的小区共有区域、违章建筑、列入征拆计划的建筑、存在安全风险的建筑中建设分布式光伏发电项目。"},{"no":"九","title":"项目建设验收及运维","text":"建筑为坡屋面结构时，光伏组件应顺坡安装，组件不应超过该安装屋面的最高点，组件方阵表面与安装屋面的垂直高度不应超过30厘米；建筑为平屋面结构时，光伏板顶端距离屋顶平面的高度不得高于1.5米。光伏板下方四周不得进行任何形式的围合，不得利用光伏项目增加额外建筑面积。光伏项目安装不得降低相邻建筑的日照标准，光伏组件覆盖范围不得超越建筑物主体结构轮廓线。"},{"no":"十","title":"项目建设验收及运维","text":"充换电基础设施项目建设选址、设计、施工应符合国家标准规范，并满足规划、环保、消防、电力、防雷和噪声等方面的相关规定。建设附属配套设施需完善相关手续。"},{"no":"十一","title":"项目建设验收及运维","text":"储能电站的施工、监理等单位应具备相应专业资质，并严格按照国家有关法律法规、工程建设强制性标准和设计文件进行施工和监理。功率在5MW以上的储能电站需按照国家有关规定办理工程质量监督手续。"},{"no":"十二","title":"项目建设验收及运维","text":"分布式光伏发电项目的投资、总承包、设计、安装、监理和运维等服务企业应在工商管理部门登记，具有独立法人资格和相关的资质，总承包企业应取得《电力工程施工凸承包资质证书》或《机电工程施工总承包资质证书》或《承装（修、试）电力设施许可证》等相关资质证书。"},{"no":"十三","title":"项目建设验收及运维","text":"充换电基础设施项目的施工单位应具备建筑机电安装工程或输变电工程专业承包资质，禁止转包和违法分包建设工程。"},{"no":"十四","title":"项目建设验收及运维","text":"分布式光伏建设施工和安装调试全部完成后，原则上由项目投资建设单位自行组织验收，项目总承包单位或安装企业配合。项目验收包括工程验收和并网验收两个部分，其中工程验收包括工商业项目验收、户用项目验收。勘察、设计、施工、安装、调试、运维等单位要将完整的技术资料移交给投资建设单位。项目投资建设单位应参照《分布式光伏工程验收标准》（DBJ43/T207一2022）组织验收。"},{"no":"十五","title":"项目建设验收及运维","text":"公用、专用充换电基础设施建设项目竣工后，须委托第三方检测机构进行验收，验收合格并出具验收报告后方可投入运营，并在15个工作日内向区发展改革局递交验收报告。第三方检测机构须具备省级及以上CMA检测资质，检测范围包含非车载充电机、交流充电桩等内容。"},{"no":"十六","title":"项目建设验收及运维","text":"储能电站投产前，项目业主（建设单位）应组织开展竣工验收，审核到货抽检、型式试验、设备调试、涉网试验等资料，检查储能电站是否符合规划设计要求及储能设备整体试运行情况，核验各项缺陷和隐患的整改情况。"},{"no":"十七","title":"项目建设验收及运维","text":"储能电站竣工验收后，项目业主（建设单位）应按照《建设工程消防设计审查验收管理暂行规定》要求，及时向住房城乡建设部门申请消防备案或验收。"},{"no":"十八","title":"项目建设验收及运维","text":"公用、专用充换电基础设施投资主体应具备充换电设施运营企业承诺的条件或委托满足承诺条件的充换电设施运营企业建设运营。充换电设施不再运营的，产权所有者应当向区发展改革局提交书面报告，获得同意后30个工作日内向供电企业办理销户手续，及时拆除相关设备。充电桩存在安全风险或充电相关执行功能失效，且限期整改后不能恢复正常功能和安全状态的，判定为失效桩。经3个月整改后不能恢复正常功能和安全状态的失效桩，以及6个月内未使用或无法提供最近6个月内运维记录的充电桩判定为长期失效桩。对于长期失效桩，充换电设施运营企业须在3个月内完成维修、换新或拆除。"},{"no":"十九","title":"项目建设验收及运维","text":"功率5MW以下的储能电站，应实现状态运行监测，实时监控系统运行工况。功率5MW及以上的储能电站，应设置现场值班人员，值班人员应熟练掌握火警处置流程和设备操作技能。设置有消防控制室的储能电站，应实行每日24小时专人值班制度，每班不应少于2人，值班人员应持有消防控制室操作职业资格证书。极端天气时，所有储能电站均应安排现场值班值守。"},{"no":"二十","title":"安全管理","text":"严格落实“管行业必须管安全、管业务必须管安全、管生产经营必须管安全\"的工作要求，建立健全安全管理和检查监督机制，督促指导运营企业定期开展安全隐患排查和治理，强化安全监管。"},{"no":"二十一","title":"安全管理","text":"项目投资主体是新能源项目运行安全的责任主体，项目单位要将新能源项目安全管理纳入企业安全管理体系，健全全员安全生产责任制，完善安全生产保证体系和监督体系，健全安全风险分级管控和隐患排查治理双重预防机制。"},{"no":"二十二","title":"安全管理","text":"项目单位必须贯彻执行国家及行业安全生产管理规定，加强项目建设运营全过程的安全生产管理。项目正式投运前，需将24小时运维服务电话、紧急联系人姓名及联系方式等书面告知区发展改革局。"},{"no":"二十三","title":"安全管理","text":"项目单位和运营企业应加强从业人员安全业务培训，具备应对突发事件的能力。自行或委托第三方专业运维机构定期开展安全隐患排查，建立隐患台账、分级分类施策，及时消除安全隐患。"},{"no":"二十四","title":"安全管理","text":"区发展改革局牵头会同有关部门定期组织对新能源项目安全运行情况开展检查，重点检查安全生产规章制度建立及执行情况、值班人员及应急装备配备情况、隐患自查整改情况等。有关部门检查发现安全隐患整改不到位，维单位立即或限期整改，拒不整改的依法进行处罚。"},{"no":"二十五","title":"部门职责","text":"区发展改革局为新能源项目的行业监管部门。督促产权（运营）单位切实履行安全管理（安全生产）主体责任。牵头负责项目单位提交项目备案申请资料审查，督促企业采购符合质量安全规定设施设备，完成项目备案、参照有关标准自行组织竣工验收，督促公共充电设施全面接入省充电设施智能服务管理平台，提升安全监测预警能力。"},{"no":"二十六","title":"部门职责","text":"区住房城乡建设局负责审查项目设计是否符合建筑施工相关规范，结构安全是否符合要求，对涉及的配套基础设施建设提出意见，对项目进行消防验收备案情况进行抽查"},{"no":"二十七","title":"部门职责","text":"区市场监管局负责规范产品销售，维护市场秩序，负责生产、销售环节产品质量安全监督管理。依据法定职责对标准的实施进行监督检查。对充换电设施企业计量工作实施监督管理。"},{"no":"二十八","title":"部门职责","text":"城管执法局负责对项目市容风貌、违章违建、公共区域占用等督查处理。"},{"no":"二十九","title":"部门职责","text":"区自然资源与规划分局负责审查项目用地手续是否合规，建设是否符合豁免办理建设工程规划许可证出具意见。"},{"no":"三十","title":"部门职责","text":"区生态环境分局负责对项目否占用生态红线、基本农田等出具意见，并对边界噪声、电磁辐射是否达标进行督查处理。"},{"no":"三十一","title":"部门职责","text":"各街道（镇）负责对辖区内新能源项目的建设、运行和安全进行监管，参与审查光伏发电项目依托建筑物产权合法性、项目是否在用地冲突、拆迁范围、群诉群访等情况出具意见。履行属地安全管理责任。本办法自公布之日起实施，未尽事宜按照省、市相关文件执行。附件长沙市雨花区新能源项目建设意见表项目名称（备案名称）法人代表及联系方式项目种类（分布式光伏、电化学储能、电动汽车充电基础设施）建设内容建设单位（统一社会信用代码）建设地址施工单位名称及联系方式1、我公司所填报的企业基本信息和项目基本信息均真实、合法、有效。2、建设项目符合国家产业发展政策，不属于企业投资核准项目。3、我公司将严格遵守项目的用地、规划、建设及运营等法律、法规、规章、规范性文件的规定，并依法依规办理相关手续。4、我公司将认真履行有关节能利用、环境保护、安全生产等行业监管要求，并主动接受相关部门事中事后监管。5我公司将按照《企业投资事中事后监管办法》的要求，项目开工前每季度，开工后每月，竣工验收后30天内分别报送项目进度，并通过在线平台及时报送变更信息：企业承诺如有填报信息不实，违反或耒履行声明与承诺事项的情形，由我公司承担相应的法律责任及由此产生的一切后果。签名（盖章）·年月对项目依托建筑物产权合法性、项目是否在拆迁范围、群诉群访等情况提出意见。镇人民政府（街道办事处）意见签名（盖章）·具意见区资规分局意见签名（盖章）·年月项目用地手续是否合规，建设是否符合豁免办理建设工程规划许可证出年月对项目设计是否符合相关规范、结构安全是否符合要求、涉及配套基础设施建设提出意见，区住房城乡建设局意见签名（盖章）．年月长沙市雨花区发展和改革局办公室2026年8月11日印发"}],"interpretations":[{"sectionNo":"二","headline":"新能源项目分三类：分布式光伏、电化学储能、电动汽车充换电设施","who":"雨花区范围内建设分布式光伏、电化学储能、电动汽车充换电基础设施的单位或个人；分布式光伏分自然人户用（接入电压不超过380伏）、非自然人户用（不超过10千伏且总装机不超过6兆瓦）、一般工商业、大型工商业四类；电化学储能分电源侧、电网侧、用户侧三类。","materials":[],"window":"项目备案及建设全过程按此分类管理，原文未另设申报期限。","where":"雨花区发展和改革局（项目备案机关）","tip":"除上述四类分布式光伏外，其他光伏项目统一按集中式光伏项目管理，不再走分布式备案口径。"},{"sectionNo":"三","headline":"雨花区新能源项目须经省投资项目在线审批监管平台向区发改局备案","who":"在雨花区范围内建设分布式光伏、电化学储能、电动汽车充换电基础设施的项目单位。","materials":[],"window":"项目开工前办理备案；备案内容及要求按湖南省发改委相关文件执行。","where":"湖南省投资项目在线审批监管平台；受理机关为雨花区发展和改革局。","tip":"备案内容及要求按湖南省发改委相关文件执行，项目单位不能自行选择备案层级。"},{"sectionNo":"四","headline":"备案后2年未开工须撤回备案，竣工前不得转让项目","who":"已取得备案的新能源项目单位；需变更项目业主、建设地址、建设规模、建筑物权属人的，应向原备案部门办理变更。","materials":[],"window":"自备案之日起2年内未开工建设或未办理任何其他手续的，应撤回备案信息。","where":"原备案部门（雨花区发展和改革局）","tip":"投资主体及股权比例等主要内容不得擅自变更，项目竣工前不得转让；变更时相关权益和责任须一并移交。"},{"sectionNo":"五","headline":"应备案未备案即开工，逾期不改正将纳入失信名单","who":"雨花区内已开工但未依法办理备案的新能源项目单位。","materials":[],"window":"责令限期改正；逾期不改正即纳入失信名单。","where":"雨花区发展和改革局（按备案权限）","tip":"在限期内补办备案可避免失信；逾期不改正的将依法开展联合监管。"},{"sectionNo":"六","headline":"备案后须向街镇报建设方案，街镇与区级部门各3个工作日核查","who":"已备案的新能源项目建设单位；项目选址须不在拆迁范围、无群诉群访，用地手续合规、设计符合规范、结构安全达标，通过联合审查后方可开工。","materials":["《长沙市雨花区新能源项目建设意见表》","项目初步建设方案（含项目选址、建设规模、用地性质等基本信息）","属地街镇现场核查意见","报区自然资源局、区住房城乡建设局联合审查的项目相关材料"],"window":"属地街镇3个工作日内完成现场核查；区自然资源局、区住房城乡建设局3个工作日内完成审查。","where":"属地街镇；区自然资源局、区住房城乡建设局；《建设意见表》报区发展改革局报备。","tip":"未通过联合审查的项目不得开工建设。"},{"sectionNo":"七","headline":"设计施工验收须执行分布式光伏、充电站、储能电站国家与省级标准","who":"雨花区内新建、改扩建的分布式光伏、电动汽车充换电设施、电化学储能电站的建设单位及设计、施工、验收单位。","materials":[],"window":"贯穿项目设计、施工、验收全过程。","where":"项目设计、施工、验收各环节按对应国家标准与湖南省地方标准执行。","tip":"防火方面须同时满足《建筑防火通用规范》（GB55037）与《火力发电厂与变电站设计防火标准》（GB50229-2019）。"},{"sectionNo":"八","headline":"分布式光伏开工前须核查场所产权与荷载，四类建筑禁建","who":"分布式光伏发电项目投资主体；建设场所须合法合规、手续齐全、产权清晰，并完成建构筑物可使用年限、载荷能力、周边环境评估。","materials":[],"window":"项目开工建设前完成场所与建构筑物评估。","where":"项目所在地（建设场所）","tip":"未取得相关利益人同意的小区共有区域、违章建筑、列入征拆计划的建筑、存在安全风险的建筑，均不得建设。"},{"sectionNo":"九","headline":"屋顶光伏限高：坡屋面不超30厘米、平屋面不超1.5米","who":"在建筑物屋顶安装分布式光伏的业主与安装企业；坡屋面须顺坡安装且不超过屋面最高点，平屋面光伏板顶端距屋顶不得高于1.5米。","materials":[],"window":"项目设计、安装阶段执行。","where":"项目所在地（建筑屋顶）","tip":"光伏板下方四周不得围合、不得借光伏增加建筑面积，且不得降低相邻建筑日照标准、不得超越建筑主体轮廓线。"},{"sectionNo":"十","headline":"充换电设施选址设计施工须过规划、环保、消防、电力等关","who":"雨花区内建设充换电基础设施的项目单位；选址、设计、施工须符合国家标准规范及规划、环保、消防、电力、防雷、噪声规定。","materials":[],"window":"项目选址、设计、施工阶段。","where":"项目所在地；附属配套设施须另行完善相关手续。","tip":"建设附属配套设施需另行完善手续，不能随主体一并省略。"},{"sectionNo":"十一","headline":"5MW以上储能电站须办工程质量监督手续，施工监理须有资质","who":"储能电站建设单位；施工、监理单位须具备相应专业资质，并按法律法规、工程建设强制性标准和设计文件施工监理。","materials":[],"window":"施工与监理阶段；功率5MW以上的储能电站需办理工程质量监督手续。","where":"按国家有关规定办理工程质量监督手续","tip":"5MW是分界线：达到5MW以上才需办理工程质量监督手续。"},{"sectionNo":"十二","headline":"分布式光伏总承包须有电力工程或机电工程总承包等资质","who":"为分布式光伏项目提供投资、总承包、设计、安装、监理、运维服务的企业；须在工商管理部门登记、具有独立法人资格和相关资质。","materials":["《电力工程施工总承包资质证书》或《机电工程施工总承包资质证书》或《承装（修、试）电力设施许可证》"],"window":"承接项目前具备；原文未设备案或申报期限。","where":"工商管理部门登记；资质由相应主管部门核发。","tip":"总承包企业三选一即可：电力工程施工总承包、机电工程施工总承包、承装（修、试）电力设施许可证。"},{"sectionNo":"十三","headline":"充换电设施施工单位须有建筑机电安装或输变电专业承包资质","who":"承接充换电基础设施项目的施工单位；须具备建筑机电安装工程或输变电工程专业承包资质。","materials":[],"window":"施工前具备；原文未设期限。","where":"项目所在地（施工现场）","tip":"禁止转包和违法分包，资质不符或转包分包的不得承接。"},{"sectionNo":"十四","headline":"分布式光伏由投资建设单位自行组织验收，含工程与并网两部分","who":"分布式光伏项目投资建设单位；总承包单位或安装企业配合，勘察、设计、施工、安装、调试、运维单位移交完整技术资料。","materials":["完整的技术资料（勘察、设计、施工、安装、调试、运维等单位移交）"],"window":"建设施工和安装调试全部完成后组织验收。","where":"由项目投资建设单位自行组织，参照《分布式光伏工程验收标准》（DBJ43/T207一2022）。","tip":"验收分工程验收与并网验收，工程验收又分工商业项目、户用项目两类，缺一不可。"},{"sectionNo":"十五","headline":"公用专用充换电设施须第三方验收，15个工作日内报区发改局","who":"公用、专用充换电基础设施项目建设单位；须委托具备省级及以上CMA检测资质的第三方机构验收，检测范围含非车载充电机、交流充电桩。","materials":["第三方检测机构出具的验收报告"],"window":"竣工验收后15个工作日内向区发展改革局递交验收报告。","where":"区发展改革局（递交验收报告）","tip":"验收合格并出具报告后方可投入运营；检测机构无CMA资质或检测范围不含充电设备的报告无效。"},{"sectionNo":"十六","headline":"储能电站投产前须自行组织竣工验收，核验缺陷整改","who":"储能电站项目业主（建设单位）；投产前组织竣工验收，审核到货抽检、型式试验、设备调试、涉网试验资料。","materials":["到货抽检、型式试验、设备调试、涉网试验等资料"],"window":"储能电站投产前完成竣工验收。","where":"由项目业主（建设单位）自行组织。","tip":"须同时核验各项缺陷和隐患的整改情况，未整改到位不宜投产。"},{"sectionNo":"十七","headline":"储能电站竣工验收后须向住建部门办消防备案或验收","who":"储能电站项目业主（建设单位）；竣工验收后按《建设工程消防设计审查验收管理暂行规定》办理。","materials":[],"window":"竣工验收后及时办理。","where":"住房城乡建设部门","tip":"消防手续分备案与验收两种，按项目对应的规定类别办理。"},{"sectionNo":"十八","headline":"充换电设施停运须报区发改局，同意后30个工作日内销户","who":"公用、专用充换电基础设施投资主体与运营企业；投资主体须具备运营企业承诺条件，或委托满足条件的运营企业建设运营。","materials":["书面报告（充换电设施不再运营时向区发展改革局提交）"],"window":"获得同意后30个工作日内向供电企业办理销户；失效桩整改3个月、长期失效桩3个月内维修换新或拆除。","where":"区发展改革局（提交书面报告）；供电企业（办理销户）。","tip":"6个月内未使用或无法提供最近6个月运维记录的充电桩判为长期失效桩。"},{"sectionNo":"十九","headline":"5MW及以上储能站须设现场值班，消防控制室每班不少于2人","who":"储能电站运营单位；功率5MW以下须实现状态运行监测，5MW及以上须设现场值班人员并熟练掌握火警处置流程。","materials":[],"window":"常态运行期间；极端天气时所有储能电站均安排现场值班值守。","where":"储能电站现场（消防控制室）","tip":"消防控制室须每日24小时专人值班、每班不少于2人，值班人员须持消防控制室操作职业资格证书。"},{"sectionNo":"二十一","headline":"项目投资主体是运行安全责任主体，须建双重预防机制","who":"新能源项目投资主体与项目单位；须将项目安全管理纳入企业安全管理体系，健全全员安全生产责任制。","materials":[],"window":"项目运行全过程。","where":"项目单位内部安全管理体系","tip":"安全责任在投资主体，不因委托运维而转移。"},{"sectionNo":"二十二","headline":"项目投运前须将24小时运维电话、紧急联系人书面报区发改局","who":"新能源项目单位；须贯彻执行国家及行业安全生产管理规定，加强建设运营全过程安全生产管理。","materials":["24小时运维服务电话、紧急联系人姓名及联系方式（书面）"],"window":"项目正式投运前书面告知。","where":"区发展改革局","tip":"告知义务须在正式投运前完成，留的应是24小时可通的运维服务电话。"},{"sectionNo":"二十三","headline":"项目单位须培训从业人员并建隐患台账，可委托第三方运维","who":"新能源项目单位与运营企业；须加强从业人员安全业务培训，自行或委托第三方专业运维机构排查隐患。","materials":["隐患台账"],"window":"定期开展，原文未定具体频次。","where":"项目单位内部；可委托第三方专业运维机构。","tip":"隐患排查须建立台账并分级分类施策，只排查不建台账不符合要求。"}],"sourceUrl":"http://www.yuhua.gov.cn/zwgk97/jcxxgk/zcwj/zcwj8293/202609/W020260914379185915286.pdf","derivedFrom":"ocr","sourceNote":"正文取自雨花区政府门户「政策文件」原文页所挂 PDF（雨发改发〔2026〕4 号，/202609/W020260914379185915286.pdf，扫描版，无文字层）。2026-11-24 用 Windows.Media.Ocr 逐页识别原件后按条重切全文 31 条（含文末未编号的施行句）。该办法为项目建设与安全管理规范，全文不含资金奖补条款。 2026-11-24 收录：原件为扫描件（无文字层），条文系 OCR 转录后按条重切，机器无法独立比对；金额与比例已对原件页面图像逐字复核。 有效期依据：原文未设有效期条款（文末为「本办法自公布之日起实施」）","verified":false,"isSample":false,"numberStyle":"clause","bodyVerified":"unverifiable","hunan":true},{"id":"csx-agri-park-fund-2026","title":"关于印发《长沙县国家现代农业产业园中央财政奖补资金使用管理办法》的通知","level":"district","region":"长沙市·长沙县","issuer":"长沙县农业农村局、长沙县财政局","documentNo":"","publishedAt":"2025-10-27","effectiveAt":"2025-10-27","expiresAt":"2030-10-26","status":"active","tags":["专项资金","财政奖补"],"audience":["长沙县国家现代农业产业园项目实施主体","涉农企业","农民合作社"],"summary":"长沙县国家现代农业产业园中央财政奖补资金使用管理办法共 9 章 46 条：资金采取以奖代补、先建后补、贷款贴息、直接补助、政府购买服务等方式；实行项目库管理，由县农业农村局发布项目申报指南，项目资金安排计划在县政府门户网站公示 7 天；明确负面清单（不得用于楼堂馆所、市政道路、农村公路、管理费和咨询论证评审费、「三保」及政府债务还本付息）；省级以上检查发现挤占挪用即收回资金并列入黑名单。办法自 2025 年 10 月 27 日施行，有效期 5 年。","sections":[{"no":"一","title":"总则","text":"为加强现代农业产业园中央财政奖补资金(以下简称“奖补资金”)管理,提高资金使用效益,推动现代农业产业园建设,依据《农业产业发展资金管理办法》、《农业农村部发展规划司关于印发〈国家现代农业产业园项目管理工作规程〉(试行)的通知》(农规〈示范〉〔2025〕2号)等文件精神,结合长沙县实际,制定本办法。"},{"no":"二","title":"总则","text":"本办法所称奖补资金,是指由中央财政拨付的用于国家现代农业产业园建设的专项资金。办法适用于本县行政区域内使用奖补资金的项目实施主体,以及对资金进行管理监督的部门和乡镇。"},{"no":"三","title":"总则","text":"奖补资金遵循“科学规划、突出重点、集中使用、规范管理、注重绩效”的原则,确保资金使用安全、高效,发挥最大效益。"},{"no":"四","title":"总则","text":"长沙县国家现代农业产业园工作由长沙县国家现代农业产业园建设工作专班(产业园管委会)统一领导和部署,专班办公室设在县农业农村局,县农业农村局会同县财政局承担国家现代农业产业园项目实施与管理工作,相关工作报请县人民政府同意后实施。"},{"no":"五","title":"组织机构分工及职责","text":"长沙县人民政府为项目责任主体,负责长沙县国家现代农业产业园建设统筹推进和组织管理工作,按照有关规定开展督导检查,负责落实监管责任。"},{"no":"六","title":"组织机构分工及职责","text":"工作专班代表长沙县人民政府对产业园进行日常管理,加强产业园项目建设的领导和协调服务,及时处理项目建设过程中的相关问题。"},{"no":"七","title":"组织机构分工及职责","text":"县农业农村局负责组织编制产业园中央财政奖补资金使用方案和项目实施方案,按程序报县人民政府审批;负责组织实施和管理中央财政奖补资金项目库,拟定项目实施计划报工作专班审核;负责制定项目管理流程,按规定范围使用奖补资金,组织落实监督检查和绩效评价。"},{"no":"八","title":"组织机构分工及职责","text":"县财政局负责专项资金的预算安排、资金拨付等财政财务管理,组织开展绩效管理,对资金支出进行监督。"},{"no":"九","title":"组织机构分工及职责","text":"相关镇人民政府负责拨付到本镇专项资金的具体实施,按规定范围使用专项资金,并做好专账核算;配合开展监督检查、绩效评价,对项目申报资料的真实性、完整性负责。"},{"no":"十","title":"资金支持范围","text":"奖补资金按照“突出重点、集中使用、创新方式”的原则,采用“以奖代补、先建后补、贷款贴息、直接补助、政府购买服务”等方式投入使用。"},{"no":"十一","title":"资金支持范围","text":"奖补资金重点支持具有较强公益性、对产业发展具有引领作用,对农民增收带动能力强的环节和领域。对中央财政奖补资金支持企业形成的资产,原则上通过折股量化、租贷合作、收益分红等方式,让园区内农民或农村集体经济组织分享资产收益。"},{"no":"十二","title":"资金支持范围","text":"奖补资金不得用于建设楼堂馆所、市政道路、农村公路,不得用于一般性支出、列支管理费和项目咨询、论证评审费,原则上不得用于大量购买一次性生产资料、建设旅游项目设施;不得用于“三保”和政府债务还本付息;不得重复安排中央财政已有普惠专项支持的内容。"},{"no":"十三","title":"项目申报管理","text":"奖补资金实行项目库管理。项目库由工作专班统筹,县农业农村局具体组织实施和管理。建设项目一般情况下应从项目库中筛选。由县农业农村局组织发布项目申报指南,明确资金支持方向,避免资金使用负面清单。"},{"no":"十四","title":"项目申报管理","text":"项目申报单位按照产业园申报文件相关规定,组织编写项目申报书。经过项目所在地镇人民政府和镇农业农村部门审核后,向县农业农村局提交书面申报资料。项目申报单位承诺对本单位基本情况、项目基本情况及申报资料的真实性负完全责任。"},{"no":"十五","title":"项目申报管理","text":"相关镇人民政府负责审核项目申报条件、项目真实性和申报材料完整性,在项目申报表上签署意见并签字盖章,择优向县农业农村局推荐审核合格项目。"},{"no":"十六","title":"项目申报管理","text":"县农业农村局负责组织专家团队对申报项目是否符合奖补资金支持方向和范围进行材料和现场审查核实,并组织相关部门(或人员)按照公平、公正、公开的原则,对申报的项目进行择优审定,签署意见后上报工作专班。"},{"no":"十七","title":"项目申报管理","text":"经工作专班审核的项目资金安排计划,在县政府门户网站进行公示,公示时间7天。公示内容包括:项目实施主体责任人;各实施主体的建设内容、资金额度。"},{"no":"十八","title":"项目申报管理","text":"公示完成后,由工作专班批复下达县农业农村局、财政局等相关部门与各实施主体。"},{"no":"十九","title":"项目申报管理","text":"县农业农村局负责按照工作专班批复文件的要求及时通知项目实施单位。"},{"no":"二十","title":"项目实施管理","text":"项目实施主体负责按照项目批复文件制定项目实施方案,包含项目名称、实施主体及项目概况、项目建设方案、资金使用计划和保障措施等,并确保自筹资金按规定比例投入。"},{"no":"二十一","title":"项目实施管理","text":"项目实施主体严格按照项目实施方案、资金使用计划和相应的项目管理办法以及有关规定组织实施项目,确保项目建设质量和进度,按时完成项目建设任务。县农业农村局组织相关镇加强项目建设指导和日常监管,建立监管台账,对项目建设的真实性负责。"},{"no":"二十二","title":"项目实施管理","text":"项目实施主体要严格按照项目批复文件组织实施,不得擅自变更;如因特殊情况确需变更或撤销的,按规定程序向县农业农村局提出变更或撤销请示,由县农业农村局统一汇总后上报工作专班,经工作专班批复后予以变更或撤销。"},{"no":"二十三","title":"项目实施管理","text":"产业园中期评估后,结合项目变更情况,由县农业农村局组织修改产业园中央财政奖补资金使用方案,按程序报县人民政府、省农业农村厅和农业农村部备案。"},{"no":"二十四","title":"项目实施管理","text":"子项目的结余资金可用于该项目相关联内容的建设或允许在同一实施主体同一上级子项目内调整使用,但不得用于其他一级项目。确实需要调整至其他一级项目的,则按第二十二条规定程序,进行项目变更。对因客观原因需变更的,按程序报县人民政府、省农业农村厅和农业农村部备案,农业农村部开展备案审查,不符合要求的不予变更备案。"},{"no":"二十五","title":"项目验收管理","text":"项目实施完成后,先由实施主体进行初验。初验合格并具备项目验收条件后,由实施主体向县农业农村局提出书面验收申请。县农业农村局在收到项目验收申请后,组织专家进行项目验收。"},{"no":"二十六","title":"项目验收管理","text":"专家组由5或7人组成,包括不限于县农业农村局、项目所属镇相关人员。专家组通过对项目的全面检查和考核,对项目建设的科学性、合理性、合法性作出评价,验收合格的出具项目验收报告,填写项目验收表。对验收不合格的项目由专家组提出整改意见,限期整改。逾期未提出书面验收申请或未通过验收的,按申报指南的相关规定执行。项目验收报告由以下主要内容组成:项目概况,资金到位、使用及财务管理情况,基础设施类项目建设情况,政府采购类项目建设情况,制度建设、操作规程及档案情况,项目实施与运行情况,项目效益与建设效果评价,存在的主要问题,验收结论与建议。"},{"no":"二十七","title":"项目验收管理","text":"县农业农村局汇总验收情况,编制项目资金安排方案,报工作专班审批。"},{"no":"二十八","title":"项目验收管理","text":"经审批的项目资金安排方案中,计划资金与安排资金有调整的部分,在县政府门户网站进行公示,公示时间7天。公示期满无异议,县农业农村局、县财政局联合下达项目资金安排文件。"},{"no":"二十九","title":"资金支付管理","text":"由县农业农村局统筹,组织各实施主体提交项目资金拨付申请及相关材料;由县财政局按照工作专班批复文件、项目验收结果及资金拨付申请,按照国库集中支付制度有关规定执行。属于政府采购管理范围的按照政府采购有关规定执行。"},{"no":"三十","title":"资金支付管理","text":"各实施主体要按照产业园中央财政奖补资金使用管理办法和项目批复文件的相关要求管理使用财政专项资金,要专款专用,任何单位和个人不得滞留、截留、挤占、挪用。"},{"no":"三十一","title":"资金支付管理","text":"国家现代农业产业园项目分为奖补类项目、基础设施类项目和政府采购类项目三大类项目。"},{"no":"三十二","title":"资金支付管理","text":"奖补类项目资金拨付:凭县农业农村局、县财政局联合下达项目资金安排文件进行拨付。"},{"no":"三十三","title":"资金支付管理","text":"基础设施类项目资金拨付:根据合同约定,按项目实施进度,提交支付申请表、进度表等材料,可申请支付部分中央财政奖补资金;项目验收且通过审核后,可申请支付中央财政奖补资金尾款。"},{"no":"三十四","title":"资金支付管理","text":"政府采购类项目资金拨付:根据合同约定,提交支付审核表和合同,可申请支付采购预付款;实施期间,按项目实施进度,提交支付审核表、采购付款文件等材料,可申请支付部分中央财政奖补资金;项目验收且通过审核后,可申请支付中央财政奖补资金尾款。"},{"no":"三十五","title":"资金支付管理","text":"项目实施单位要按照会计制度规定,凭合法发票及申请拨付资金时提交的全部资料进行规范的账务处理。"},{"no":"三十六","title":"档案管理","text":"项目实施主体要留存完整的中央财政奖补资金项目资料档案,对建设内容前、中、后全过程留存影像资料,健全项目支出财务账。"},{"no":"三十七","title":"档案管理","text":"县农业农村局要留存完整的中央财政奖补资金项目资料档案,建立奖补资金专账,建立奖补资金形成的资产台账。及时在农业农村部转移支付管理平台和国家现代农业产业园项目监测信息系统,填报项目建设进展和中央财政奖补资金使用进度。"},{"no":"三十八","title":"档案管理","text":"各单位档案资料应留存原件,确实没有原件的可留存复印件。"},{"no":"三十九","title":"监督管理","text":"为确保产业园财政性资金的安全和高效运行,牵头实施主体及相关实施主体要严格按照本办法的规定规范操作和有序运行。"},{"no":"四十","title":"监督管理","text":"工作专班应加强日常监督管理,发现问题应及时向县人民政府报告。"},{"no":"四十一","title":"监督管理","text":"县人民政府将对各实施主体项目建设情况和资金使用情况进行综合绩效评估,作为下一年度项目立项和资金安排的重要依据。"},{"no":"四十二","title":"监督管理","text":"对挤占、截留、挪用项目中央财政奖补资金、省级财政补助资金、地方统筹资金等违法违纪行为的实施主体,按程序取消其国家现代农业产业园建设实施主体的资格,收回该项目的中央财政奖补资金,并通报批评,列入黑名单;涉嫌违法犯罪的,依法移交司法机关追究法律责任;对采用虚构事实和材料依据,骗取、侵占国家级财政补助资金、省级财政补助资金、地方统筹资金等违法违纪行为的实施主体责任人,视其具体情节和数额,追究其相应的法律责任。"},{"no":"四十三","title":"监督管理","text":"被取消国家现代农业产业园建设资格的实施主体,将收回中央财政奖补资金且不得再次申报该项目。"},{"no":"四十四","title":"监督管理","text":"相关业务主管部门、相关镇和实施主体,必须各司其职、各尽其责,因未认真履行职责造成影响现代农业产业园建设财政资金及出现重大管理问题的,依照有关规定予以责任追究;对涉嫌犯罪的,依法移交司法机关追究法律责任。"},{"no":"四十五","title":"附则","text":"本办法由县农业农村局会同财政局负责解释。"},{"no":"四十六","title":"附则","text":"本办法自2025年10月27日起施行,有效期5年。"}],"interpretations":[{"sectionNo":"二","headline":"奖补资金用于国家现代农业产业园建设","who":"本县行政区域内使用中央财政奖补资金的项目实施主体，以及资金管理监督部门和乡镇。","materials":[],"window":"产业园项目实施期内","where":"县农业农村局、县财政局","tip":"奖补资金为中央财政拨付的产业园建设专项资金，须按规定范围使用。"},{"sectionNo":"十","headline":"奖补资金采取以奖代补、先建后补、贷款贴息等方式","who":"产业园项目实施主体","materials":[],"window":"项目实施期内","where":"县农业农村局、县财政局","tip":"支持方式还包括直接补助和政府购买服务。"},{"sectionNo":"十一","headline":"重点支持公益性强、带动农民增收的产业环节","who":"园区内项目实施主体；中央财政奖补资金支持企业形成的资产，原则上折股量化给农民或农村集体经济组织。","materials":[],"window":"项目实施期内","where":"县农业农村局","tip":"通过折股量化、租贷合作、收益分红等方式让农民或村集体经济组织分享资产收益。"},{"sectionNo":"十二","headline":"奖补资金不得用于楼堂馆所、市政道路、农村公路","who":"使用奖补资金的项目实施主体","materials":[],"window":"资金使用全过程","where":"县农业农村局、县财政局","tip":"不得用于一般性支出、管理费和项目咨询论证评审费，不得用于三保和政府债务还本付息，不得重复安排中央财政已有普惠专项支持内容。"},{"sectionNo":"十四","headline":"项目申报书经镇审核后报县农业农村局","who":"项目申报单位","materials":["项目申报书","书面申报资料"],"window":"按产业园申报文件规定的申报时间","where":"项目所在地镇人民政府、镇农业农村部门、县农业农村局","tip":"申报单位对单位基本情况、项目基本情况及申报资料真实性负完全责任。"},{"sectionNo":"二十","headline":"实施主体须编制实施方案并按规定比例投入自筹资金","who":"项目实施主体","materials":["项目实施方案"],"window":"项目批复后、项目实施前","where":"县农业农村局","tip":"实施方案须包含项目名称、实施主体及项目概况、项目建设方案、资金使用计划和保障措施。"},{"sectionNo":"二十一","headline":"实施主体须按方案组织实施，按时完成建设任务","who":"项目实施主体","materials":[],"window":"项目建设期内","where":"县农业农村局、相关镇人民政府","tip":"县农业农村局组织相关镇加强项目建设指导和日常监管，建立监管台账。"},{"sectionNo":"二十二","headline":"项目不得擅自变更，确需变更须报工作专班批复","who":"项目实施主体","materials":["变更或撤销请示"],"window":"项目实施期内","where":"县农业农村局、工作专班","tip":"变更请示由县农业农村局汇总后上报工作专班，经批复后方可变更或撤销。"},{"sectionNo":"二十四","headline":"子项目结余资金限同一实施主体同一上级子项目内调整","who":"项目实施主体","materials":[],"window":"项目结余资金安排时","where":"县农业农村局、县人民政府","tip":"不得用于其他一级项目；确需调整的按项目变更程序报批并备案。"},{"sectionNo":"二十五","headline":"项目完成后由实施主体初验并书面申请验收","who":"项目实施主体","materials":["书面验收申请"],"window":"项目实施完成后","where":"县农业农村局","tip":"初验合格并具备验收条件后，方可向县农业农村局提出书面验收申请。"},{"sectionNo":"二十六","headline":"验收专家组由5或7人组成，不合格限期整改","who":"项目实施主体","materials":[],"window":"收到项目验收申请后组织专家验收；不合格限期整改","where":"县农业农村局","tip":"逾期未提出书面验收申请或未通过验收的，按申报指南相关规定执行。"},{"sectionNo":"二十九","headline":"实施主体提交拨付申请，财政按国库集中支付","who":"项目实施主体","materials":["项目资金拨付申请及相关材料"],"window":"项目资金安排文件下达后","where":"县农业农村局、县财政局","tip":"属于政府采购管理范围的，按政府采购有关规定执行。"},{"sectionNo":"三十","headline":"奖补资金须专款专用，不得滞留截留挤占挪用","who":"各实施主体","materials":[],"window":"资金使用全过程","where":"县农业农村局、县财政局","tip":"任何单位和个人不得滞留、截留、挤占、挪用财政专项资金。"},{"sectionNo":"三十三","headline":"基础设施类项目可按进度申请资金，验收后付尾款","who":"基础设施类项目实施主体","materials":["支付申请表","进度表"],"window":"按合同约定和项目实施进度","where":"县农业农村局、县财政局","tip":"项目验收且通过审核后，可申请支付中央财政奖补资金尾款。"},{"sectionNo":"三十四","headline":"政府采购类项目可申请预付款，验收后付尾款","who":"政府采购类项目实施主体","materials":["支付审核表","合同","采购付款文件"],"window":"按合同约定和项目实施进度","where":"县农业农村局、县财政局","tip":"实施期间按进度提交支付审核表、采购付款文件等材料，可申请部分资金。"},{"sectionNo":"三十五","headline":"凭合法发票及拨付资料规范账务处理","who":"项目实施单位","materials":["合法发票","申请拨付资金时提交的全部资料"],"window":"资金拨付后","where":"项目实施单位（按会计制度）","tip":"按会计制度规定进行规范账务处理。"},{"sectionNo":"三十六","headline":"实施主体须留存项目全过程资料和影像","who":"项目实施主体","materials":["中央财政奖补资金项目资料档案","建设内容前、中、后全过程影像资料","项目支出财务账"],"window":"项目建设全过程及建成后","where":"项目实施主体","tip":"档案资料应完整留存，健全项目支出财务账。"},{"sectionNo":"三十八","headline":"档案资料应留存原件，无原件可留存复印件","who":"各单位（项目实施主体）","materials":["档案资料原件"],"window":"档案归集时","where":"各单位","tip":"确实没有原件的，可留存复印件。"},{"sectionNo":"四十一","headline":"绩效评估结果作为下年度立项和资金安排依据","who":"各实施主体","materials":[],"window":"年度综合绩效评估","where":"县人民政府","tip":"评估针对项目建设情况和资金使用情况，直接影响下一年度项目立项和资金安排。"},{"sectionNo":"四十二","headline":"挤占挪用或骗取奖补资金的取消资格并收回资金","who":"项目实施主体及责任人","materials":[],"window":"发现违法违纪行为后","where":"县人民政府、县农业农村局","tip":"列入黑名单；涉嫌犯罪的依法移交司法机关追究法律责任。"},{"sectionNo":"四十三","headline":"被取消产业园建设资格的主体不得再次申报","who":"被取消国家现代农业产业园建设资格的实施主体","materials":[],"window":"取消资格后","where":"县农业农村局","tip":"同时收回中央财政奖补资金。"}],"sourceUrl":"http://www.csx.gov.cn/zwgk/zjdxxgkml/bsz/zcwj21/202603/t20260326_12345562.html","derivedFrom":"official","sourceNote":"取自长沙县人民政府门户「镇（街道）信息公开目录—北山镇—政策文件」转载页（页面日期 2026-03-26）；正文落款为长沙县农业农村局、长沙县财政局，2025 年 10 月 27 日；转载页未载文号。2026-11-24 按原文 9 章 46 条全文重切（原文以「,」「( )」半角标点排版，照录未改）。该办法只规定资金使用方式与流程，不含具体奖补金额与比例，标准在其配套的年度项目申报指南中。 2026-11-24 收录：与官方页面逐句比对，命中 65/65 句（100%），关卡判定「verbatim」。 有效期依据：第四十六条：本办法自2025年10月27日起施行，有效期5年","verified":false,"isSample":false,"numberStyle":"clause","bodyVerified":"verbatim","hunan":true},{"id":"csx-agri-park-quality-guide-2025","title":"长沙县国家现代农业产业园 农产品质量安全体系建设项目申报指南","level":"district","region":"长沙市·长沙县","issuer":"长沙县农业农村局","documentNo":"","publishedAt":"2025-12-10","effectiveAt":null,"expiresAt":null,"status":"active","tags":["财政奖补","专项资金"],"audience":["园区 6 镇农业经营主体","春华镇等 6 镇人民政府"],"summary":"长沙县国家现代农业产业园中央财政奖补资金的配套申报指南，把奖补标准写到了具体数额：每年新认证绿色产品奖励 1 万元、单个主体最高不超过 5 万元，续证绿色产品奖励 0.5 万元；新认证有机农产品一次性每个产品奖励 5 万元、单个主体最高不超过 20 万元；新建改建农残重金属速测室按不超过总投资额的 30% 奖补；项目总投资 200 万元，全部为中央财政奖补资金。申报主体为园区范围内镇人民政府或 2024 年 12 月 31 日前在长沙县依法注册登记的农业经营主体。","sections":[{"no":"一","title":"指导思想","text":"认真贯彻落实“四个最严”要求，以“预防为主，控制源头，多措并举，确保安全”为工作原则，坚持产管结合，强化源头监管，落实监管责任，提升园区农产品质量安全监管能力和种养基地农产品质量安全管理水平，确保从源头上保障农产品质量安全。确保农产品监测总体合格率稳定在98%以上，不发生重大农产品质量安全事故。"},{"no":"二","title":"项目目标","text":"通过3年（2025—2027年）建设，“二品一标”认证数量每年新增5个以上，至2027年达到135个以上；农产品质量安全监管体系不断完善，农产品监测总体合格率稳定在98%以上，确保不发生重大农产品质量安全事故；农产品承诺达标合格证覆盖率达到80%以上。"},{"no":"三","title":"实施范围","text":"春华镇、路口镇、高桥镇、金井镇、青山铺镇、开慧镇6个镇。"},{"no":"四","title":"实施时间","text":"2025年3月15日—2027年6月30日。"},{"no":"五","title":"支持建设的内容","text":"（一）开展“二品一标”认证奖励。对6个镇辖区内蔬菜、水稻种植主体每年获得农业农村部新认证的绿色产品奖励1万元，单个主体最高不超过5万元，对续证的绿色产品给予0.5万元奖励。每年新认证有机农产品（农业农村部认证机构：北京中绿华夏有机产品认证中心有限公司）一次性每个产品奖励5万元，单个主体最高不超过20万元。（二）落实农产品承诺达标合格证制度。2025—2026年由县农业农村局统一采购100台农产品承诺达标合格证便携式蓝牙电子打印机下发到园区各农产品生产主体，不再另行申报。（三）开展农残速测。由县农业农村局统一采购2台便携式农残速测仪用于开展日常监管和检查。（四）建设农残自检室。3年内对6个镇辖区蔬菜、水稻种植主体新建、改建和更新农产品农残、重金属速测室给予奖补；每年新增3-5（个）。仪器类别为蔬菜胶体金免疫法检测设备和试剂、酶标法检测设备和试剂、稻谷重金属检测设备等监测设施设备及配套设施设备。奖补标准按照不超过总投资额的30%进行奖补。（五）完善镇街监管体系。对6个镇农产品质量安全监管站的农产品农残速测室进行改造，完善水电（网络）、通风、工作台等基础设施，补充快速检测设备仪器。胶体金免疫法检测设备和试剂、酶标法检测设备和试剂、稻谷重金属检测设备。"},{"no":"六","title":"资金来源及奖补标准","text":"（一）资金来源项目总投资200万元，其中长沙县国家农业产业园建设项目中央财政奖补资金200万元。所有奖补项目均不能与其他奖补项目重复奖补。（二）奖补标准1.奖补方式：中央财政奖补资金采取政府采购服务、以奖代补方式等方式支持。2.奖补内容：主要用于支持绿色认证奖补、购置100台农产品承诺达标合格证设施、2台便携式农残速测仪、胶体金免疫法检测设备、酶标法检测设备、稻谷重金属检测设备等监测设施设备及配套设施设备，改建农产品农残、重金属速测室。（三）使用原则中央财政奖补资金不得用于建设楼堂馆所、市政道路、农村公路，不得用于列支管理费、项目咨询、论证评审费，原则上不得用于大量购买一次性生产资料、建设旅游项目设施，所有奖补项目均不能与其他奖补项目重复奖补。"},{"no":"七","title":"申报程序","text":"（一）宣传发动长沙县国家现代农业产业园相关镇街要广泛开展农产品质量安全体系建设项目宣传发动工作，认真组织符合条件的主体积极申报。（二）自主申报1.申报条件：申报单位为园区范围内的镇人民政府或2024年12月31日前在长沙县依法注册登记的农业经营主体。2.申报时间（1）“二品一标”认证奖补项目：每年3月20日—3月31日，逾期不再受理项目申报。（2）农残自检室建设项目：每年12月10日—12月23日，逾期不再受理项目申报。3.申报要求：（1）申报单位须在申报截止日期前完成项目申报，同时向项目所在地镇人民政府和农业农村部门提交项目申报纸质材料（申报材料模板见附件）。申报材料用A4纸打印一式两份，并装订成册。2.负面清单。以下情形不得申报项目：（1）项目单位以各种手段对项目评审和验收人员进行各种形式的贿赂，利用或冒用领导干部名义打招呼、批条子，影响项目审批的公正性。（2）项目单位虚假申报，重复申报，或提供虚假材料、现场和实物，骗取项目和资金。（3）项目单位不按申报的项目建设内容进行建设。（4）在各级农产品例行监督抽查中，检出含有国家禁止使用的农药或其他化学物质，或农药等化学物质残留不符合农产品质量安全标准；或者出现农产品质量安全事故、安全生产和环境污染事件。（5）违反国家和政府禁止性规定；企业法人或法人代表因违纪违规申报项目受到党纪政纪处分尚在影响期内的；或在项目申报至资金下拨期间内，被追究刑事责任或纳入失信黑名单等不良记录的。（三）镇级初审项目所在地镇人民政府负责对项目申报资料的真实性、合规性、完整性进行审查，对项目是否符合申报条件负责。经审查合格，各镇负责人在项目审核表上签署意见并签字盖章，推荐上报县农业农村局申请中央财政奖补资金。（四）县级复审县农业农村局负责组织专家组对申报项目是否符合中央财政奖补资金支持方向和范围进行材料和现场审查核实，专家组由5或7人组成，包括不限于县农业农村局、项目所属镇相关人员。组织相关部门（或人员）按照公平、公正、公开的原则，对申报的项目进行择优审定后推荐纳入产业园项目库，签署意见后上报工作专班。（五）审核批复县农业农村局根据专家评审和现场核查结果提出资金分配方案，报工作专班审批后，在县政府门户网站进行公示，公示时间7天。公示内容包括：项目实施主体责任人；各实施主体的建设内容、资金额度。公示完成后，由工作专班批复下达县农业农村局、县财政局等相关部门与各实施主体。（六）项目实施1.项目评审程序：公开申报→镇级审核→县级评审→实地考察→公示→项目实施→项目验收。2.物资采购程序：县级采购→主体实施→项目验收→项目公示→拨付资金。（七）绩效评价项目完成后，项目单位对项目实施情况、资金使用及绩效目标完成情况进行绩效自评，将绩效自评报告纸质档送至县农业农村局，并积极配合所在地镇人民政府、县农业农村局等单位开展绩效评价工作。"},{"no":"八","title":"日常管理","text":"相关镇人民政府负责拨付到本镇中央财政奖补资金的具体实施，按规定范围使用中央财政奖补资金，并做好专账核算；配合开展监督检查、绩效评价，对项目申报资料的真实性、完整性负责；配合相关部门对监测指标进行报送。县农业农村局负责组织实施和管理中央财政奖补资金项目库，拟定项目实施计划报工作专班审核。负责制定项目管理流程，按规定范围使用奖补资金，组织落实监督检查和绩效评价。"},{"no":"九","title":"项目验收与资金拨付","text":"（一）项目验收项目所在地镇人民政府对完成建设任务、具备验收条件的实施主体进行初验，经初验合格后，向县农业农村局提出书面验收申请。县农业农村局在收到项目验收申请后，组织专家进行项目验收，专家组由5或7人组成，包括不限于县农业农村局、项目所属镇相关人员。专家组通过对项目的全面检查和考核，对项目建设的科学性、合理性、合法性作出评价，验收合格的出具项目验收报告，填写项目验收表。对验收不合格的项目由专家组提出整改意见，限期整改。逾期未提出书面验收申请或未通过验收的，取消项目资格。县农业农村局汇总验收情况，编制中央财政奖补资金安排方案，报工作专班审批。（二）资金拨付项目验收合格，由县农业农村局统筹，组织各实施主体提交中央财政奖补资金拨付申请及相关材料。经公示无异议后，按照相关文件规定将中央财政奖补资金拨付至实施主体账户。项目实施主体应配合县农业农村局、县财政局对资金使用情况进行绩效评价，确保资金使用合规、有效。"},{"no":"十","title":"咨询方式及监督方式","text":"（一）咨询电话：长沙县农业农村局农业发展管理科（三）：0731-84011734（二）监督电话：长沙县农业农村局计划财务科：0731-84011725长沙县纪委监委驻县农业农村局纪检监察组：0731-86882198附件：1.“二品一标”认证奖补项目申报材料2.农残自检室建设项目申报材料3.农产品质量安全监管站快检室建设项目申报材料"}],"interpretations":[{"sectionNo":"三","headline":"项目覆盖春华、路口、高桥等6个镇","who":"春华镇、路口镇、高桥镇、金井镇、青山铺镇、开慧镇6个镇辖区内的申报主体。","materials":[],"window":"按项目实施范围在6个镇辖区内申报。","where":"长沙县农业农村局、项目所在地镇人民政府","tip":"6个镇以外的主体不在本项目实施范围。"},{"sectionNo":"四","headline":"项目实施期为2025年3月15日至2027年6月30日","who":"6个镇辖区内符合条件、在实施期内完成建设内容的申报主体。","materials":[],"window":"2025年3月15日—2027年6月30日。","where":"长沙县农业农村局","tip":"建设内容须落在实施期内，超出实施期不予奖补。"},{"sectionNo":"五","headline":"绿色认证奖1万元，有机认证每产品奖5万元","who":"6个镇辖区内蔬菜、水稻种植主体：每年获农业农村部新认证绿色产品奖1万元、单个主体最高5万元，续证奖0.5万元；新认证有机农产品（北京中绿华夏有机产品认证中心有限公司认证）每个产品一次性奖5万元、单个主体最高20万元；新建、改建农残重金属速测室的种植主体按不超过总投资额30%奖补。","materials":[],"window":"认证类按每年新认证、续证分别奖励；自检室3年内每年新增3-5个；合格证打印机由县农业农村局统一采购下发，不再另行申报。","where":"长沙县农业农村局（统一采购打印机、速测仪下发园区生产主体）","tip":"打印机和2台便携式农残速测仪由县局统一采购，不需申报；自检室奖补不超过总投资额30%。"},{"sectionNo":"六","headline":"项目总投资200万元，全部为中央财政奖补资金","who":"纳入长沙县国家现代农业产业园农产品质量安全体系建设项目的实施主体；所有奖补项目不得与其他奖补项目重复。","materials":[],"window":"资金用于绿色认证奖补、合格证设施、便携式农残速测仪、检测设备及速测室改建。","where":"中央财政奖补资金（长沙县农业农村局组织实施）","tip":"不得用于楼堂馆所、市政道路、农村公路，不得列支管理费、咨询论证评审费；不得重复奖补。"},{"sectionNo":"七","headline":"认证奖补3月20日至31日申报，自检室12月10日至23日","who":"园区范围内的镇人民政府，或2024年12月31日前在长沙县依法注册登记的农业经营主体；有贿赂、虚假或重复申报、检出禁用农药、质量安全事故、失信黑名单等情形不得申报。","materials":["项目申报纸质材料（申报材料模板见附件，A4纸打印一式两份并装订成册）"],"window":"「二品一标」认证奖补每年3月20日—3月31日；农残自检室建设每年12月10日—12月23日；逾期不再受理。","where":"项目所在地镇人民政府初审，长沙县农业农村局复审；县政府门户网站公示7天","tip":"负面清单含虚假申报、重复申报、检出国家禁用农药、质量安全事故、被纳入失信黑名单等。"},{"sectionNo":"九","headline":"验收合格并公示无异议后拨付中央财政奖补资金","who":"完成建设任务、具备验收条件的项目实施主体。","materials":["书面验收申请","项目验收表","中央财政奖补资金拨付申请及相关材料"],"window":"初验合格后提出书面验收申请；验收合格、公示无异议后拨付。","where":"项目所在地镇人民政府初验，长沙县农业农村局组织验收","tip":"逾期未提出书面验收申请或未通过验收的，取消项目资格。"},{"sectionNo":"十","headline":"申报咨询与监督电话见县农业农村局三个科室","who":"申报本项目的镇人民政府及园区内农业经营主体。","materials":["附件1「二品一标」认证奖补项目申报材料","附件2 农残自检室建设项目申报材料","附件3 农产品质量安全监管站快检室建设项目申报材料"],"window":"申报期内接受咨询；监督电话长期公布。","where":"长沙县农业农村局农业发展管理科（三）0731-84011734；计划财务科0731-84011725；县纪委监委驻县农业农村局纪检监察组0731-86882198","tip":"三类项目分别对应附件1至附件3的申报材料模板。"}],"sourceUrl":"http://csx.gov.cn/zwgk/zfxxgkml/rdzt/6w6b_zwgk/6b/202512/P020251210558217714345.pdf","derivedFrom":"official","sourceNote":"取自长沙县政府门户所挂《长沙县国家现代农业产业园农产品质量安全体系建设项目申报指南》PDF 原件（附件 7，页面 15 页，带文字层）。2026-11-24 按原文一至十部分全文转录，金额与比例（1 万元、5 万元、0.5 万元、20 万元、200 万元、30%、98%、80%）与原件逐字核对。文末附件 1—3 为申报表与承诺书样表，未单列条款。 2026-11-24 收录：与官方页面逐句比对，命中 62/62 句（100%），关卡判定「verbatim」。 有效期依据：原文未设有效期条款；实施时间为2025年3月15日—2027年6月30日","verified":false,"isSample":false,"numberStyle":"clause","bodyVerified":"verbatim","hunan":true},{"id":"csx-industry-modern-2026","title":"长沙县人民政府办公室关于印发《长沙县加快建设现代化产业体系 推动经济高质量发展若干措施（试行）》的通知","level":"district","region":"长沙市·长沙县","issuer":"长沙县人民政府办公室","documentNo":"","publishedAt":"2025-06-07","effectiveAt":"2025-06-07","expiresAt":"2027-06-06","status":"active","tags":["财政奖补","认定资质","研发创新","数字化转型","外贸外资"],"audience":["长沙县规模以上工业企业","专精特新中小企业","外贸企业","科技型企业"],"summary":"围绕“358”现代化产业体系给出奖补标准：首次入规工业企业奖10万元，年产值每上一个10亿元台阶再奖20万元、单个企业最高200万元；新认定国家级、省级制造业单项冠军分别奖50万元、10万元，国家重点“小巨人”、国家级专精特新“小巨人”、省级专精特新中小企业分别奖50万元、10万元、5万元；技改投入50万元以上按不超过投入金额20%奖励、单个企业最高100万元；高新技术企业按市县1:1奖励，研发经费增量按10%奖励、单个企业最高200万元；外贸企业单个最高奖励50万元。措施自2025年6月7日施行，有效期两年。","sections":[{"no":"一","title":"","text":"一、支持产业提质升级\n(一)支持企业发展上规模上台阶。对首次入规的工业企业给予10万元奖励。对年产值首次达到1亿元、2亿元、5亿元、10亿元,且同比增速达到15%的工业企业,分别给予5万元、10万元、15万元、20万元奖励;对年产值10亿元以上的工业 企业,每上一个台阶(10亿元),给予20万元 奖励,单个企业 最高奖励200万元。(责任单位:县工业和信息化局、自贸临空区产业促进局)\n(二)支持企业提升发展和创新能级。对新认定为国家级、 省级制造业单项冠军企业(产品)的企业,分别给予50万元、 10万元奖励。对新认定为国家重点“小巨人”、国家级专精特新“小巨人”、省级专精特新中小企业的企业,分别给予50万 元、10万元、5万元奖励(责任单位:县工业和信息化局、自贸临空区产业促进局)。对新获评为“独角兽”企业、“瞪羚”企 业的企业分别给予最高100万元、20万元奖励(责任单位:县 发展改革局)。开展县长质量奖评选活动,对通过了县长质量奖 评审委员会评审的企业或组织给予20万元奖励。(责任单位:县市场监管局)\n(三)支持企业开展技改投资和设备更新。鼓励工业和信息化企业开展技术改造,对技术改造投入50万元以上的工业和信息化企业,按不超过经评审认定技术改造投入金额的20%给予奖励,单个企业最高奖励100万元。(责任单位:县 工业和信息化 局)\n(四)支持企业两化融合(信息化和工业化融合)和绿色发 展。支持企业两化融合发展,对首次通过工信部两化融合管理体 系贯标评定达到AAA级、AA级、A级的企业,分别给予10万元、 8万元、5万元奖励;对首次通过工信部数字化转型贯标星级评 估获得3星级、2星级、1星级认证的企业, 分别给予10万元、8万元、5万元奖励;对首次通过工业互联网企业网络安全分类 分级管理考核或工业和信息化领域数据安全管理考核的企业,给 予10万元奖励。支持企业绿色发展,对首次获评国家级、省级 的绿色工厂、绿色设计产品、工业产品绿色设计示范企业、绿色 供应链、工业固体废物资源综合利用示范企业(项目)、碳减排标杆企业、节水型企业的企业,分别给予15万元、8万元奖励; 对首次通过清洁生产审核的企业,给予5万元奖励。(责任单位: 县工业和信息化局)\n(五)支持产业集群集聚发展。对组织申报且首次进入国家 级、省级先进制造业集群和中小企业特色产业集群决赛优胜者名单的集群促进组织或服务机构,分别给予50万元、20万元奖励。对当年具有产业带动示范效应且促进产业集群发展,在产业链延链、补链中发挥良好作用的集群促进组织或服务机构、行业协会,经评审认定为一类的,给予30万元奖励,经评审认定为二类的,   给予15万元奖励。(责任单位:县工业和信息化局)"},{"no":"二","title":"","text":"二、支持科技创新\n(六)支持企业能级提升。对首次认定和重新认定为国家高新技术企业的,按照市县1:1的比例给予奖励。对年度研发经费达到100万元且占主营业务收入比重达到5%的规模以上企业,按其较上年度核心研发经费增量的10%给予奖励,单个企业最高奖励200万元,其中,经核定奖励额不足1万元的,不予以奖 励,上述政策可与上级政策叠加享受。对年度研发经费首次破零 并达到50万元的规模以上企业,给予2万元奖励。对获评世界500强企业研发中心、领军企业总部研发中心、扩能升级企业研 发中心、保税研发中心、外资企业研发中心的企业,按《中共长 沙市委办公厅长沙市人民政府办公厅关于印发<长沙市全力建设全球研发中心城市的若干政策〉的通知》(长办发〔2023〕14   号)规定给予配套支持。(责任单位:县科技局)\n(七)支持科技成果转化落地。支持县内企业聚焦关键技术 需求、战略性新兴产业及未来产业技术攻关;支持县内企业与国内高校或科研院所开展重点产学研合作。鼓励高校院所科研成果落地,促进科技成果转化为现实生产力,对单个项目给予奖励。 支持技术合同交易,对年技术合同交易金额累计达到500万元的企业,按不超过技术合同交易金额的1‰给予奖励,单个企业每年最高奖励50万元。上述政策可与上级政策叠加享受。(责任 单位:县科技局)\n(八)支持松雅湖未来科技城建设。围绕构建“358”现代 化产业体系,支持国内外知名高校、科研院所、知名企业在松雅湖未来科技城设立分支机构、创新研究院、产业特色研究院、企业研发中心等研究机构,并在研发投入、成果转化、重大项目建 设等方面给予综合支持。(责任单位:县科技局)\n(九)支持企业科创平台建设。对新认定的国家级、省级重 点实验室、工程(技术)研究中心、制造业创新中心、技术创新 中心、工业设计中心,分别给予100万元、30万元奖励;由省级晋级为国家级的,补充奖励70万元。对新认定的省级企业技术中心、新备案的省级新型研发机构,给予10万元奖励。上述政策可与上级政策叠加享受。(责任单位:县科技局)\n(十)优化科技创新生态。鼓励围绕研发试验、检验检测、 概念验证、中试服务等创新关键环节设立公共服务平台,鼓励国内外高校院所、国家技术转移示范机构设立技术转移转化机构, 鼓励在国内外科技发达地区设立离岸科创平台发展“科创飞 地”,上述平台或机构经认定后根据工作成效给予单个企业每年最高奖励200万元。对获得国家级创新创业大赛一、二、三等奖   的企业,分别给予30万元、20万元、10万元奖励;对获得省级创新创业大赛一、二、三等奖的企业,分别给予15万元、10万元、5万元奖励。上述政策可与上级政策叠加享 受。(责任单位:   县科技局)\n(十一)支持“文化+科技”融合发展。对首次认定的国家级、省级文化和科技融合示范基地,分别给予30万元、20万元奖励,由省级晋级为国家级的,补充奖励10万元。支持高校院所、企业、行业协会等建设“文化+科技”产业孵化平台,积极 培育网络视听、音视频装备、数字文化场景应用、工业设计等上 下游产业链企业,首次获得国家级、省级认定的,分别给予30 万元和15万元奖励,由省级晋级为国家级的,补充奖励15万元。 上述政策可与上级政策叠加享受。(责任单位:县委宣传部)\n(十二)支持未来生物新技术研发。对企业商业化的生物制 品,以获得临床试验批件或临床默示许可为标准,按不超过研发 投入金额的30%给予奖励,单个企业最高奖励100万元;进入 临床试验后,按不超过各阶段研发投入金额的40%给予奖励,单个企业最高奖励1000万元。(责任单位:自贸临空区招商合 作局)"},{"no":"三","title":"","text":"三、支持高水平开放\n(十三)支持自贸临空区开放型经济发展。支持自贸临空区 稳规模、扩增量、培育外贸新业态,更大力度引进外资,奋力打造内陆地区改革开放高地。根据自贸临空区当年外贸进出口总额和增长贡献度、对外投资和实际利用外资等情况,给予自贸临空 区最高3000万元奖励。(责任单位:自贸临空区综保事务局、自贸临空区招商合作局)\n(十四)支持镇(街道)和自贸会展区外贸稳步增长。对镇   (街道)和自贸会展区近两年平均外贸进出口额1亿元(含)以 上的企业进行综合评价,分档给予奖励。重点支持镇(街道)和 自贸会展区生产型企业积极开拓国际市场,对当年实现外贸进出 口额1000万元(含)以上的企业进行综合评价,分档给予奖励; 对当年成功实现外贸转型,首次开展外贸业务并实现外贸进出口 额50万元(含)以上的企业进行综合评价,分档给予奖励。鼓 励镇(街道)和自贸会展区企业开展对非贸易,对当年实现对非贸易额500万元(含)以上的企业进行综合评价,分档给予奖励。 以上三项政策不叠加享受,单个企业最高奖励50万元。(责任单位:县商务局)\n(十五)鼓励镇(街道)和自贸会展区培育外贸新业态。鼓 励镇(街道)和自贸会展区企业开展二手车出口业务,对当年二手车出口200台(含)以上的企业进行综合评价,分档给予奖励,   单个企业最高奖励100万元。鼓励企业培育跨境电商孵化中心、 跨境电商产业园,综合考虑当年服务企业数量、贸易规模、场地 面积等情况进行评估,单个企业最高奖励100万元;支持跨境电 商企业借助社交媒体、搜索引擎等数字化平台和跨境电子商务平台,开展自主品牌全球推广,按不超过年跨境电商网络营销推广 费用的30%给予奖励,单个企业最高奖励50万元。(责任单位:县商务局)"},{"no":"四","title":"","text":"四、支持未来产业\n(十六)支持培育未来产业新增长点。大力发展未来制造、 未来能源、未来信息、未来健康、未来材料等未来产业,对涉及新一代信息技术、人工智能、人形机器人、量子技术、低空经济、   生物医药、精密制造等经评审认定的未来产业规模以上企业相关 产品,按产品年度销售收入同比增量的2.5%给予奖励,单个企业最高奖励100万元。对年度营业收入首次突破3000万元的互联网软件信息企业,给予10万元奖励;每上一个台阶(1亿元),   给予10万元奖励。(责任单位:县工业和信息化局)"},{"no":"附则三十六","title":"","text":"(三十六)本措施自2025年6月7日起施行,有效期两年。 措施实施期间如遇国家或者上级政策调整,以上级政策为准。"},{"no":"附则三十七","title":"","text":"(三十七)《长沙县人民政府办公室关于印发长沙县县长质 量奖评审考核办法的通知》(长县政办发〔2021〕12号)、《长 沙县人民政府办公室关于印发长沙县鼓励金融业创新支持产业 发展奖励办法的通知》(长县政办发〔2022〕14号)、《长沙 县人民政府办公室关于印发长沙县“个转企”若干措施的通知》   (长县政办发〔2023〕1号)、《长沙县人民政府关于印发长沙 县全力支持预制菜产业高质量发展二十条政策的通知》(长县政 发〔2023〕4号)、《长沙县人民政府办公室关于做好“规上” 企业申报入库工作的通知》(长县政办发〔2023〕9号)、《长 沙县人民政府办公室关于印发<长沙县鼓励和扶持企业上市(挂 牌)实施办法〉的通知》(长县政办发〔2024〕5号)、《长沙  县人民政府办公室关于印发<长沙县支持企业股份制改造“一事  一议”议事规则(试行)〉的通知》(长县政办发〔2024〕8号)   同时废止。"}],"interpretations":[{"sectionNo":"一","headline":"首次入规工业企业奖10万元，产值上台阶最高奖200万元","who":"长沙县工业企业：首次入规；年产值首达1亿元、2亿元、5亿元、10亿元且同比增速15%；国家级、省级制造业单项冠军；国家重点小巨人、国家级专精特新小巨人、省级专精特新中小企业；独角兽、瞪羚企业；通过县长质量奖评审；技改投入50万元以上；首次通过两化融合贯标AAA级、AA级、A级或数字化转型3星级、2星级、1星级；首次获评国家级、省级绿色工厂等；首次通过清洁生产审核；进入国家级、省级产业集群决赛优胜者名单的集群促进组织或服务机构。","materials":[],"window":"按年度组织申报，首次达标或当年达标即奖","where":"县工业和信息化局、自贸临空区产业促进局、县发展改革局、县市场监管局","tip":"单个企业最高奖励200万元；年产值10亿元以上每上一个10亿元台阶奖20万元；技术改造按投入不超过20%奖励、最高100万元。"},{"sectionNo":"二","headline":"研发经费增量奖10%，单个企业最高200万元","who":"长沙县规模以上企业：年度研发经费达100万元且占主营业务收入5%；研发经费首次破零达50万元；首次或重新认定国家高新技术企业；世界500强等研发中心；技术合同交易额累计500万元；新认定国家级、省级重点实验室等科创平台；获国家级、省级创新创业大赛奖项；生物制品企业获临床试验批件或默示许可。","materials":[],"window":"按年度申报；研发经费按较上年度增量计算","where":"县科技局、县委宣传部、自贸临空区招商合作局","tip":"研发增量奖励不足1万元不予奖励；上述政策可与上级政策叠加享受；生物制品按研发投入30%、临床阶段40%奖励，最高1000万元。"},{"sectionNo":"三","headline":"外贸企业分档奖励，单个企业最高50万元","who":"自贸临空区、镇（街道）和自贸会展区企业：近两年平均外贸进出口额1亿元以上；当年外贸进出口额1000万元以上；首次开展外贸业务且进出口额50万元以上；当年对非贸易额500万元以上；二手车出口200台以上；跨境电商孵化中心、产业园；开展自主品牌全球推广的跨境电商企业。","materials":[],"window":"按年度申报，以上三项政策不叠加享受","where":"县商务局、自贸临空区综保事务局、自贸临空区招商合作局","tip":"外贸三项政策不叠加，单个企业最高50万元；二手车出口、跨境电商孵化中心最高100万元；海外推广费按不超过30%奖励、最高50万元。"},{"sectionNo":"四","headline":"未来产业企业按销售收入增量2.5%奖励，最高100万元","who":"经评审认定的未来产业规模以上企业（涉及新一代信息技术、人工智能、人形机器人、量子技术、低空经济、生物医药、精密制造等）；年度营业收入首次突破3000万元的互联网软件信息企业。","materials":[],"window":"按年度申报，按产品年度销售收入同比增量计算","where":"县工业和信息化局","tip":"互联网软件信息企业营收首破3000万元奖10万元，每上一个1亿元台阶再奖10万元。"}],"sourceUrl":"http://www.csx.gov.cn/zwgk/zjdxxgkml/asz/zcwj16/202606/t20260625_12422055.html","sourceNote":"2026-11-22 取自长沙县人民政府门户「镇（街道）信息公开目录—安沙镇—政策文件」转载页（页面日期2026-02-13）；转载页未载版头文号与成文日期，文号空缺。附则第三十六条载明自2025年6月7日施行，publishedAt 取施行日。 2026-11-22 收录：与官方页面逐句比对，命中 61/61 句（100%），关卡判定「verbatim」。 有效期依据：附则第（三十六）条","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"csx-startup-measures-2025","title":"长沙县关于支持大学生创新创业的若干措施","level":"district","region":"长沙市·长沙县","issuer":"长沙县人民政府","documentNo":"","publishedAt":"2025-05-29","effectiveAt":"2025-01-01","expiresAt":"2027-12-31","status":"active","tags":["创业补贴","贷款贴息","场地支持","人才政策"],"audience":["在校大学生及毕业5年内高校毕业生创办的长沙县初创企业","大学生创业项目团队"],"summary":"对入驻长沙县大学生创新创业中心的项目提供面积不超过500平方米、最长24个月的免费场地；优秀创业项目经评审给5万元至20万元创业补贴，国家级创新创业大赛一、二、三等奖分别支持30万元、20万元、10万元，省级分别支持15万元、10万元、5万元；设首期1000万元大学生创业投资基金，单次投资最高50万元；个人创业担保贷款最高30万元、合伙创业最高400万元，并按贷款实际利率50%贴息；新引进博士、硕士、本科生分别给3万元、2万元、1.2万元租房和生活补贴。文件自2025年1月1日起执行，有效期三年。","sections":[{"no":"一","title":"","text":"一、创业经营场地扶持\n1.创新创业项目入驻长沙县大学生创新创业中心的可提供面积不超过500平方米、最长24个月的免费场地。\n2.对已入驻长沙县创新创业中心的项目或企业，因孵化转化成效好，需在县内租赁场地的，统筹县属国有企业自有物业，免费提供最长12个月的过渡性场地支持。"},{"no":"二","title":"","text":"二、创业项目扶持资金\n3.每年定期开展大学生优秀创业项目评选活动，面向符合条件的创新创业项目及企业遴选优秀项目，经评审通过后，可获得5万元-20万元的创业补贴。\n4.对新入选国家级创新训练项目和创业训练项目给予最高5万元/项的支持，对新入选国家级创业实践项目给予最高20万元/项的支持。\n5.对参加国家级创新创业大赛获得一、二、三等奖的企业，分别给予30万元、20万元、10万元支持；对参加省级创新创业大赛获得一、二、三等奖的企业，分别给予15万元、10万元、5万元支持。"},{"no":"三","title":"","text":"三、大学生创业投资基金支持\n6.设立运营长沙县大学生创业投资基金。首期基金规模1000万元，重点支持投早、投小、投硬科技，为大学生主导的创业初期项目提供创业启动资金。基金对于大学生个人或团队创业项目（企业）的单次投资额最高可达50万元，对市场前景好、示范引领带动能力强、影响力大的项目还可追加投资。"},{"no":"四","title":"","text":"四、大学生创业金融扶持\n7.符合条件的大学生创业者，个人创业的，可申请最高30万元的个人创业担保贷款；合伙创业的，可根据合伙创业人数适当提高创业担保贷款额度，最高不超过400万元。创业担保贷款利息由财政部门按贷款实际利率的50%给予贴息，贷款风险可由政府性融资担保机构或担保基金与银行按8:2比例分担。\n8.对接金融机构开发推广支持长沙县大学生创业的专属金融产品，创新风险评估方式，优化申贷材料和审批流程，提高贷款审批效率。"},{"no":"五","title":"","text":"五、落实支持大学生创业税收优惠政策\n9.对毕业年度内持《就业创业证》的高校毕业生从事个体经营的，自办理个体工商户登记当月起，在3年内按每户每年24000元的限额依次扣减其当年实际应缴纳的增值税、城市维护建设税、教育费附加、地方教育附加和个人所得税。\n10.对创业投资企业、天使投资人投资于未上市的中小高新技术企业以及种子期、初创期科技型企业的投资额，按国务院有关文件规定抵扣所得税应纳税所得额。"},{"no":"六","title":"","text":"六、加快集聚优秀大学生\n11.对企业新引进毕业两年内落户并在长工作的博士、硕士、全日制本科毕业生，分别给予3万元、2万元、1.2万元租房和生活补贴。境外高校博士毕业生，租房和生活补贴提高至10万元。"},{"no":"八","title":"","text":"八、选树一批大学生创新创业典型\n15.加大大学生创新创业典型发现培养力度，每两年选树一批大学生创新创业先进典型，根据企业规模、科研投入、成果转化、经营状况等，给予5000元、1万元、2万元综合性资助，加强跟踪培养扶持，加大宣传推介，优先推荐参加上级评选表彰、项目申报、人才研修等活动，营造支持大学生创新创业的良好氛围。"},{"no":"有效期","title":"","text":"本文件自2025年1月1日起执行，有效期三年。《长沙县关于支持大学生创新创业的若干措施（试行）》（长县区人才发〔2023〕4号）同时废止。本措施与省、市、县、区相关政策有交叉重复的按照“时间从新、标准从高、奖励补贴不重复”的原则执行。本措施有效期内，如遇法律法规或有关政策调整变化的，从其规定 。"}],"interpretations":[{"sectionNo":"一","headline":"入驻县大学生创新创业中心，最高500平方米免租24个月","who":"创新创业项目入驻长沙县大学生创新创业中心：面积不超过500平方米、最长24个月免费场地；已入驻长沙县创新创业中心、因孵化转化成效好需在县内租赁场地的项目或企业：统筹县属国有企业自有物业，免费提供最长12个月过渡性场地。","materials":[],"window":"最长24个月；过渡性场地最长12个月。","where":"长沙县大学生创新创业中心、长沙县创新创业中心；县属国有企业自有物业。","tip":"免费面积不超过500平方米；过渡性场地仅限孵化转化成效好的已入驻项目或企业。"},{"sectionNo":"二","headline":"县优秀创业项目评选最高20万元，国家级大赛一等奖30万元","who":"符合条件的创新创业项目及企业：每年评选优秀项目，经评审通过可获5万元-20万元创业补贴；新入选国家级创新训练项目和创业训练项目最高5万元/项、国家级创业实践项目最高20万元/项；参加国家级创新创业大赛获一、二、三等奖的企业分别30万元、20万元、10万元，省级分别15万元、10万元、5万元。","materials":[],"window":"每年定期开展优秀创业项目评选；赛事与立项支持按次给予。","where":"长沙县（县内创新创业项目及企业）。","tip":"优秀项目为评审制，需先通过遴选；国家级与省级赛事、训练项目与创业实践项目分别按对应档补。"},{"sectionNo":"三","headline":"县大学生创业投资基金首期1000万元，单次最高投50万元","who":"大学生主导的创业初期项目（企业），重点投早、投小、投硬科技；基金对大学生个人或团队创业项目（企业）的单次投资额最高可达50万元；市场前景好、示范引领带动能力强、影响力大的项目还可追加投资。","materials":[],"window":"首期基金规模1000万元；单次投资，符合条件可追加。","where":"长沙县大学生创业投资基金。","tip":"单次投资最高50万元；仅面向大学生个人或团队创业项目（企业），优质项目可追加投资。"},{"sectionNo":"四","headline":"大学生个人创业担保贷款最高30万元，合伙最高400万元","who":"符合条件的大学生创业者：个人创业最高30万元个人创业担保贷款；合伙创业按合伙人数适当提高额度，最高不超过400万元；利息由财政部门按贷款实际利率的50%给予贴息，贷款风险可由政府性融资担保机构或担保基金与银行按8:2比例分担。","materials":[],"window":"贴息按贷款实际利率的50%执行；本条未写贷款期限。","where":"政府性融资担保机构或担保基金与银行（风险分担）。","tip":"合伙创业按人数提高额度，最高400万元；贷款风险按8:2比例分担。"},{"sectionNo":"五","headline":"毕业年度高校毕业生个体经营，3年内每年最高扣减24000元","who":"毕业年度内持《就业创业证》的高校毕业生，从事个体经营并办理个体工商户登记；自登记当月起3年内按每户每年24000元限额依次扣减其当年实际应缴纳的税费。","materials":["《就业创业证》"],"window":"自办理个体工商户登记当月起3年内，每户每年24000元限额。","where":"个体工商户登记地（自办理登记当月起计算）。","tip":"依次扣减增值税、城市维护建设税、教育费附加、地方教育附加和个人所得税，限额每户每年24000元。"},{"sectionNo":"六","headline":"企业新引进博士补3万元、硕士2万元、本科1.2万元","who":"企业新引进、毕业两年内落户并在长工作的博士、硕士、全日制本科毕业生；境外高校博士毕业生租房和生活补贴提高至10万元。","materials":[],"window":"毕业两年内落户并在长工作；一次性租房和生活补贴。","where":"长沙市（落户并在长工作）。","tip":"境外高校博士提高至10万元；须为企业新引进且毕业两年内落户并在长工作。"},{"sectionNo":"八","headline":"每两年选树大学生创业典型，给予5000元至2万元资助","who":"大学生创新创业先进典型：根据企业规模、科研投入、成果转化、经营状况等评定，给予5000元、1万元、2万元综合性资助。","materials":[],"window":"每两年选树一批。","where":"长沙县（选树，优先推荐参加上级评选表彰）。","tip":"资助按评定结果分5000元、1万元、2万元三档；优先推荐参加上级评选表彰、项目申报、人才研修。"}],"sourceUrl":"http://www.csx.gov.cn/zwgk/qtxxgkml/txw/zcwj_120357/202505/t20250529_11870286.html","sourceNote":"2026-11-22 取自长沙县人民政府门户「群团信息公开目录—长沙县共青团—政策文件」；页面未载发文机关署名与文号，按标题归为长沙县人民政府发文。原文明确自2025年1月1日起执行（早于页面发布日期2025-05-29），属追溯施行。 2026-11-22 收录：与官方页面逐句比对，命中 25/25 句（100%），关卡判定「verbatim」。 有效期依据：正文末段（有效期条款）","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"cz-ai-2026","title":"郴州市人民政府办公室关于印发《郴州市“人工智能+”行动实施方案（2026—2030年）》的通知","level":"city","region":"郴州市","issuer":"郴州市人民政府办公室","documentNo":"郴政办发〔2026〕6号","publishedAt":"2026-06-25","effectiveAt":"2026-06-25","expiresAt":null,"status":"active","tags":["数字化转型","研发创新","专项资金"],"audience":["制造业企业","专精特新中小企业","数据标注企业","人工智能相关企业"],"summary":"到2027年全市智能算力规模达500PFlops、培育350家左右专精特新中小企业、建设60家智能工厂；每年培育15家基础级智能工厂、8家先进级智能工厂；鼓励企业申报发改、科技、工信、数据、财政等部门专项资金，方案期2026—2030年。","sections":[{"no":"一","title":"近期目标（到2027年）","text":"到2027年，全市智能算力规模达500PFlops，建设3个行业高质量数据集，培育一支200人左右的数据标注队伍，打造具有本地特色的行业垂类大模型，推广35个左右典型应用场景，新增省级及以上科技创新平台2个，培育350家左右专精特新中小企业，建设60家智能工厂。"},{"no":"二（一）1","title":"“人工智能+”先进制造","text":"加快推动我市“1221”现代化产业体系智能化升级，聚焦锂电新能源、有色金属新材料等重点产业链，在研发设计、中试验证、生产制造等关键环节，推广一批人工智能赋能新型工业化的典型应用场景。深入实施中小企业数字化赋能专项行动，支持中小企业开展数字化、智能化改造，加快中小企业人工智能应用复制推广。"},{"no":"二（三）1","title":"梯次培育工业企业","text":"加快人工智能赋能原材料、装备制造、电子信息、特色轻工、绿色食品加工等重点行业，实施一批数字化改造重点项目，持续建设智能制造工厂、智能制造产线（车间）和智能工位。纵深推进“智赋万企”行动，按照“基础级－先进级－卓越级－领航级”四个层级，建立智能工厂培育库。每年培育15家基础级智能工厂、8家先进级智能工厂，力争实现卓越级智能工厂“零的突破”。"},{"no":"三（二）","title":"争取政策支持","text":"推动国有投资基金、社会资本以市场化方式支持行业语料库建设、智能体与大模型开发等。鼓励企业申报发改、科技、工信、数据、财政等部门专项资金，加大对公共平台建设、核心技术攻关、产业链构建、重点场景应用示范等支持力度。"}],"interpretations":[{"sectionNo":"二（一）1","headline":"锂电、有色金属等重点产业链中小企业数字化改造可获支持","who":"聚焦锂电新能源、有色金属新材料等重点产业链，在研发设计、中试验证、生产制造等关键环节开展人工智能应用的企业；重点支持中小企业开展数字化、智能化改造。","materials":[],"window":"按“中小企业数字化赋能专项行动”推进，原文未设申报期。","where":"中小企业数字化赋能专项行动（原文未列受理部门与系统）","tip":"本条只明确支持方向（场景推广、数字化改造、AI应用复制推广），未列补助金额与申报条件。"},{"sectionNo":"二（三）1","headline":"每年培育15家基础级、8家先进级智能工厂","who":"原材料、装备制造、电子信息、特色轻工、绿色食品加工等重点行业的工业企业；按“基础级－先进级－卓越级－领航级”四个层级纳入智能工厂培育库。","materials":[],"window":"每年培育15家基础级智能工厂、8家先进级智能工厂；卓越级为“零的突破”目标。","where":"“智赋万企”行动、智能工厂培育库（原文未列受理部门与系统）","tip":"培育分四级递进，基础级与先进级有年度数量（15家、8家）；卓越级目前为零，属突破目标而非既有额度。"},{"sectionNo":"三（二）","headline":"企业可申报发改、科技、工信、数据、财政等部门专项资金","who":"开展行业语料库建设、智能体与大模型开发的企业，以及公共平台建设、核心技术攻关、产业链构建、重点场景应用示范等项目的实施单位。","materials":[],"window":"按各专项资金年度申报通知执行，原文未设统一申报期。","where":"发改、科技、工信、数据、财政等部门专项资金（按各部门申报渠道）","tip":"资金来自既有部门专项资金而非新设基金，需按各部门渠道分别申报；社会资本与国有投资基金以市场化方式参与。"}],"sourceUrl":"https://czs.gov.cn/html/zwgk/hgjj/fzgh/content_4020184.html","sourceNote":"2026-11-22 取自郴州市人民政府门户「政务公开—规划计划」原文页，文头载郴政办发〔2026〕6号，成文日期2026年6月25日，标注“此件主动公开”。本机直连 czs.gov.cn 被站点防护拦截（HTTP 412），改用工具端读取原文页全文，条文未与本地抓取文件比对。 2026-11-22 收录：官方页面未能打开或不是正文（fetch/html），条文未与原文比对。 有效期依据：原文未明示有效期；方案名称与目标年度为2026—2030年，故 expiresAt 留空","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"unverifiable","hunan":true},{"id":"cz-digital-2025-8","title":"郴州市人民政府办公室关于印发《郴州市2025年“智赋万企”行动方案》的通知","level":"city","region":"郴州市","issuer":"郴州市人民政府办公室","documentNo":"郴政办发〔2025〕8号","publishedAt":"2025-04-23","effectiveAt":null,"expiresAt":"2025-12-31","status":"expired","tags":["数字化转型","认定资质","财政奖补"],"audience":["郴州市规模以上制造业企业","中小企业","数字化转型服务商"],"summary":"2025年新增4000家企业上云、360家企业上平台，打造15家智能制造企业、45条智能生产线、225个智能工位。","sections":[{"no":"一","title":"工作目标","text":"全年新增4000家企业上云、360家企业上平台；打造15家智能制造企业、45条（个）智能制造生产线（车间）、225个智能工位，力争创建领航级、卓越级智能工厂1家；新增80家创新型中小企业、40家省级及以上专精特新中小企业；新增5家左右省级制造业单项冠军企业，力争新增1家国家制造业单项冠军企业。"},{"no":"二(三)7","title":"推动生产智能化改造","text":"持续推动“智赋万企”行动，系统培育智能制造企业，标准化建设智能产线和车间，推广智能工位，全年力争新增智能标杆企业15家、智能车间45家、智能工位225个。鼓励企业引入先进的自动化设备和智能控制系统，实现生产过程的自动化和智能化。"},{"no":"二(三)8","title":"推动管理数字化升级","text":"推动企业建立全面的数字化管理体系，包括PLM（产品生命周期管理系统）、ERP（资源计划系统）、MES（制造执行系统）等。加快中小企业从关键环节入手实施数字化改造，推进线上营销、远程协作、智能生产等应用，实现生产、销售、采购、库存等环节集成管理。"},{"no":"二(二)2","title":"强化算力支撑","text":"根据《湖南省绿色智能计算产业高质量发展规划（2025—2030年）》要求，全力推进湖南省大数据灾备中心和智能计算基地建设，力争智能算力超500P。"}],"interpretations":[{"sectionNo":"一","headline":"全年新增4000家企业上云、360家上平台","who":"郴州市拟上云上平台、建设智能制造企业/生产线（车间）/智能工位、申报创新型中小企业、省级及以上专精特新中小企业、制造业单项冠军的企业（全市目标口径）。","materials":[],"window":"全年推进，按年度目标口径落实；原文未设企业申报截止时间。","where":"郴州市“智赋万企”行动（原文未点名具体受理部门）","tip":"这些是全市年度目标数，不是企业可直接申领的额度；企业按单项政策另行申报认定。"},{"sectionNo":"二(三)7","headline":"全年力争新增智能标杆企业15家、智能车间45家","who":"郴州市制造业企业，重点为拟建设智能产线、智能车间、推广智能工位、引入自动化设备和智能控制系统的企业。","materials":[],"window":"全年推进，按“智赋万企”行动年度安排；原文未设申报截止时间。","where":"郴州市“智赋万企”行动（原文未点名具体受理部门）","tip":"15家、45家、225个为全市力争目标；企业需按智能制造企业、车间、工位标准建设后认定。"},{"sectionNo":"二(三)8","headline":"中小企业可先从关键环节实施数字化改造，建PLM/ERP/MES","who":"郴州市中小企业，尤其是需建立PLM、ERP、MES等数字化管理体系、推进线上营销和远程协作、智能生产的企业。","materials":[],"window":"按“智赋万企”行动年度推进；原文未设申报截止时间。","where":"郴州市“智赋万企”行动数字化改造推进渠道（原文未点名具体部门）","tip":"原文只给改造方向，未列补助金额；落点是生产、销售、采购、库存等环节集成管理。"}],"sourceUrl":"https://www.czs.gov.cn/html/zwgk/fggw/gfxwj/content_3899344.html","sourceNote":"2026-11-21 取自郴州市政府门户「规范性文件」栏目原文页；文号、成文日期（2025年4月23日）与条款逐字核对。该方案为2025年度方案，基准日已过执行年度，判失效。 2026-11-21 收录：官方页面未能打开或不是正文（fetch/html），条文未与原文比对。 有效期依据：按年度性文件判定（方案名称与目标均限定2025年度，跨年度自动作废）","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"unverifiable","hunan":true},{"id":"cz-scene-2026","title":"郴州市人民政府办公室关于印发《郴州市加快场景创新和大规模应用三年行动方案（2026—2028年）》的通知","level":"city","region":"郴州市","issuer":"郴州市人民政府办公室","documentNo":"郴政办发〔2026〕8号","publishedAt":"2026-07-30","effectiveAt":"2026-07-30","expiresAt":"2028-12-31","status":"active","tags":["专项资金","研发创新","数字化转型","融资支持"],"audience":["专精特新“小巨人”企业","科技型企业","大学生初创企业","国有企业"],"summary":"提出每年落地重大场景不少于2项、发布高价值小切口场景不少于8项，到2028年为不少于80家企业开展场景对接；探索财政资金“补改投”改革、试点发放“场景创新券”，引导金融机构创新供应链融资、知识产权质押融资产品，方案期2026—2028年。","sections":[{"no":"一","title":"行动目标","text":"以场景创新为牵引，促进科技创新和产业创新深度融合，打造全省重要的场景资源开放应用高地，推动技术创新、产业升级、治理效能、民生保障等取得明显成效。每年落地重大场景不少于2项、建设行业领域集成式场景1项以上、发布高价值小切口场景不少于8项，推动新技术、新产品、新业态在我市验证和推广。"},{"no":"二（一）1","title":"制造业领域","text":"深入实施“人工智能+制造”行动，围绕有色金属新材料、锂电新能源、电子信息、装备制造等优势产业，加快推动5G、传感器、AI大模型智能分析等新技术综合运用，打造智能辅助设计、虚拟仿真中试、机器视觉质检、废料资源化利用等全环节应用场景，带动形成智慧冶炼、智慧矿山、智慧仓储、智能工厂、智慧供应链协同管理、零碳园区等行业领域集成式场景，推动制造业向高端化、智能化、绿色化转型。"},{"no":"三（三）","title":"鼓励“三新”场景培育","text":"面向高校、科研院所、领军企业、专精特新“小巨人”企业、大学生初创企业等，分领域、分批次挖掘技术引领性强、产业带动效益突出的新技术、新产品。依托郴州科技服务超市等平台，开展科技成果供需对接，加强郴江实验室、各类研发中心、高能级创新平台建设，鼓励郴州“3+N”中试基地面向社会开放中试资源，加速科技成果中试验证，助力成熟技术转化落地。"},{"no":"四（一）","title":"加大支持保障","text":"坚持“政府引导、社会资本参与”模式，推动优质场景项目落地。编制全市场景建设支持政策清单（详见附件4）。引导金融机构创新供应链融资、知识产权质押融资等产品，探索设立概念验证基金或场景驱动型基金。积极争取国家和省级试点及专项资金支持，营造场景创新良好生态。"},{"no":"四（二）","title":"加快机制创新","text":"探索财政资金“补改投”改革，以股权直投方式支持创新场景建设；试点发放“场景创新券”，支持场景对接落地。鼓励银行、保险等机构面向中小企业创新金融产品。构建场景与概念验证中心、中试基地、专业化孵化机构、技术经理人、产业基金协同联动机制。"}],"interpretations":[{"sectionNo":"一","headline":"郴州每年发布高价值小切口场景不少于8项","who":"在郴州开展新技术、新产品、新业态验证和推广的企业及各类创新主体；重大场景、行业集成式场景同步推进。","materials":[],"window":"每年（年度目标：重大场景不少于2项、集成式场景1项以上、小切口场景不少于8项）","where":"原文未列申报窗口；场景资源开放应用由市级统筹","tip":"目标为每年落地，非一次性；新技术、新产品、新业态在我市验证和推广。"},{"sectionNo":"二（一）1","headline":"有色金属、锂电、电子信息、装备制造优先开放AI+制造场景","who":"有色金属新材料、锂电新能源、电子信息、装备制造等优势产业中，应用5G、传感器、AI大模型智能分析等技术的制造企业。","materials":[],"window":"原文未设申报期限","where":"原文未列申报窗口；由市级统筹打造行业集成式场景","tip":"重点场景含智能辅助设计、虚拟仿真中试、机器视觉质检、废料资源化利用及智慧冶炼、智慧矿山、智能工厂等。"},{"sectionNo":"三（三）","headline":"高校、小巨人、大学生初创企业可报三新场景，中试资源开放","who":"高校、科研院所、领军企业、专精特新小巨人企业、大学生初创企业；分领域、分批次挖掘新技术、新产品。","materials":[],"window":"分领域、分批次挖掘（原文未列具体申报期）","where":"郴州科技服务超市等平台；郴江实验室、3+N中试基地","tip":"中试基地面向社会开放中试资源；成熟技术转化落地可加速验证。"},{"sectionNo":"四（一）","headline":"编制场景建设支持政策清单，探索概念验证基金","who":"优质场景项目主体；需要供应链融资、知识产权质押融资的中小企业。","materials":[],"window":"原文未设申报期限","where":"金融机构；国家和省级试点及专项资金（原文未列申报窗口）","tip":"支持模式为政府引导、社会资本参与；场景建设支持政策清单详见附件4。"},{"sectionNo":"四（二）","headline":"试点场景创新券，财政资金可股权直投创新场景","who":"创新场景建设主体；可获银行、保险创新金融产品的中小企业。","materials":[],"window":"试点（原文未列具体申报期）","where":"原文未列申报窗口；由市级探索补改投与场景创新券","tip":"补改投以股权直投方式支持，非无偿补助；场景创新券为试点发放。"}],"sourceUrl":"https://czs.gov.cn/html/zwgk/czzb/szfzb/68911/69181/content_4034794.html","sourceNote":"2026-11-22 取自郴州市人民政府门户「政务公开—郴州政报—市政府办文件」原文页，版头载郴政办发〔2026〕8号，成文日期2026年7月30日。本机直连 czs.gov.cn 被站点防护拦截（HTTP 412），改用工具端读取原文页全文，条文未与本地抓取文件比对。 2026-11-22 收录：官方页面未能打开或不是正文（fetch/html），条文未与原文比对。 有效期依据：标题及行动目标明示方案期为2026—2028年，按方案末年度计至2028年12月31日","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"unverifiable","hunan":true},{"id":"cz-seven-battle-2025-5","title":"郴州市人民政府办公室关于印发《郴州市实施“七大攻坚”总体方案》的通知","level":"city","region":"郴州市","issuer":"郴州市人民政府办公室","documentNo":"郴政办发〔2025〕5号","publishedAt":"","effectiveAt":null,"expiresAt":"2025-12-31","status":"expired","tags":["融资支持","营商环境","场地支持"],"audience":["郴州市工业企业","制造业企业","园区企业","产业人才"],"summary":"强化财政金融支持，推荐企业享受省级贷款贴息，落实“潇湘财银贷”增量扩面；推进工业用地弹性出让降低企业初始用地成本。","sections":[{"no":"四(一)1","title":"强化财政金融支持力度","text":"鼓励工业企业开展设备更新和技术改造项目融资，积极推荐企业享受省级及以上贷款贴息政策。落实园区企业“潇湘财银贷”增量扩面要求，进一步发挥好政府性融资担保增信分险作用。进一步完善市场化运营和激励机制，发挥现有政府投资基金在引进重大项目、培育企业等方面的作用，紧扣有色金属新材料、新能源、智能制造、大消费等产业加快设立子基金，助力重点产业转型升级。"},{"no":"四(一)2","title":"增强产业人才保障能力","text":"实施更加积极、更加开放、更加有效的“聚才”新政，制定出台更加有利于推动产业发展、科技创新的人才政策，用好落地“人才新政52条”等各项政策措施，促进创新链、产业链、资金链、人才链的深度融合。"},{"no":"四(一)3","title":"常态化开展“送解优”服务","text":"统筹推进“两员”行动和“纾困增效”专项帮扶工作。持续开展“林邑茶话”“政企早餐会”“企业家日”等系列活动，倾听企业家诉求。深化“多规合一”改革，优化对口服务机制，组建专班实行全流程、全周期跟踪指导服务，全力保障重大产业项目合理用地需求。推进工业用地弹性出让、用地清单制，大力降低企业初始用地成本。"},{"no":"二(四)","title":"推广绿色生产模式","text":"推广绿色生产模式，加快园区企业实施系统性清洁生产改造，鼓励园区发展高效节能、先进环保和资源循环利用产业，推进绿色运输，建设一批国家级绿色园区、绿色工厂。"}],"interpretations":[{"sectionNo":"四(一)1","headline":"工业企业设备更新融资，可推荐享受省级及以上贷款贴息","who":"开展设备更新和技术改造项目融资的工业企业；园区企业可对接“潇湘财银贷”；有色金属新材料、新能源、智能制造、大消费等重点产业企业可对接政府投资基金及新设子基金。","materials":[],"window":"按省级及以上贷款贴息政策和“潇湘财银贷”增量扩面要求执行，原文未列申报期。","where":"园区“潇湘财银贷”；政府性融资担保机构；政府投资基金及新设子基金。","tip":"贷款贴息是省级及以上政策，需由当地推荐企业享受；担保增信通过政府性融资担保机构分险，基金支持聚焦有色金属新材料、新能源、智能制造、大消费等产业。"},{"sectionNo":"四(一)3","headline":"重大产业项目用地有专班保障，工业用地可弹性出让","who":"有诉求需反映的企业，可参加“林邑茶话”“政企早餐会”“企业家日”等活动；重大产业项目业主，由专班全流程、全周期跟踪服务并保障合理用地需求；需工业用地的企业，适用弹性出让、用地清单制。","materials":[],"window":"常态化推进：“两员”行动、“纾困增效”专项帮扶及“林邑茶话”“政企早餐会”“企业家日”系列活动持续开展。","where":"“林邑茶话”“政企早餐会”“企业家日”等活动；重大产业项目由组建的专班跟踪服务。","tip":"诉求反映走“林邑茶话”“政企早餐会”“企业家日”等渠道；用地保障和专班服务面向重大产业项目，工业用地弹性出让、用地清单制用于降低企业初始用地成本。"}],"sourceUrl":"https://www.czs.gov.cn/html/zwgk/czzb/szfzb/67077/67084/content_3874332.html","sourceNote":"2026-11-21 取自《郴州市政府公报》所载原文；文号与条款逐字核对。页面未显示成文日期，按年度方案判失效。 2026-11-21 收录：官方页面未能打开或不是正文（fetch/html），条文未与原文比对。 有效期依据：按年度性文件判定（方案目标限定年度，跨年度自动作废）","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"unverifiable","hunan":true},{"id":"hh-growth-2023","title":"怀化市人民政府办公室关于印发《怀化市贯彻落实〈关于打好经济增长主动仗实现经济运行整体好转的若干政策措施〉实施方案》的通知","level":"city","region":"怀化市","issuer":"怀化市人民政府办公室","documentNo":"怀政办发〔2023〕9号","publishedAt":"2023-04-01","effectiveAt":null,"expiresAt":null,"status":"active","tags":["财政奖补","研发创新","数字化转型"],"audience":["怀化市中小企业","专精特新“小巨人”企业","上云上平台企业","外贸综合服务中心"],"summary":"对年投资额5万元以上的“上云上平台”市级标杆企业按年度费用30%补贴、最高5万元；发明专利每项奖励2万元。","sections":[{"no":"四1","title":"加强市场主体培育","text":"对国家、省、市级专精特新“小巨人”企业、“上云上平台”省级标杆企业、在“专精特新”专板挂牌企业进行奖补，对年投资额5万元以上的“上云上平台”市级标杆企业按其“上云上平台”年度费用的30%进行补贴，最高不超过5万元。支持中小企业实现发明专利“破零倍增”行动，对取得发明专利的企业每项专利奖励2万元。"},{"no":"四2","title":"支持企业技术创新","text":"落实企业研发奖补政策，支持企业建立研发准备金制度，对企业研发（R&D）经费投入进行补助，按上一年度研发（R&D）经费投入总量和总量占主营业务收入比例（以税务部门税前加计扣除认定为准）进行综合认定，对全市排名前10位的企业，分别给予前5位各10万元、第6—10位各5万元的补助。"},{"no":"四2续","title":"创新平台与高企奖励","text":"对新认定和重新认定的高新技术企业分别给予20万元、10万元申报奖励；对在有效期内整体搬迁入怀的高新技术企业给予10万元奖励。在此基础上，以符合企业所得税税前加计扣除的研发费用为基数，新增部分的10%进行补贴，合计最高30万元。"},{"no":"外贸","title":"外贸综合服务中心支持","text":"全面提升现有外贸综合服务中心的报关办理、指导退税、市场开拓等能力，推动成立1家以上园区外贸综合服务中心，对考核合格的外贸综合服务中心按25万元/个的标准予以支持。"}],"interpretations":[{"sectionNo":"四1","headline":"专精特新与上云标杆企业获奖补，上云费用补30%最高5万","who":"国家、省、市级专精特新“小巨人”企业、“上云上平台”省级标杆企业、在“专精特新”专板挂牌企业；年投资额5万元以上的“上云上平台”市级标杆企业；取得发明专利的中小企业。","materials":[],"window":"按年度组织奖补，原文未列明申报起止时间。","where":"原文未列明受理部门或申报系统。","tip":"上云上平台按年度费用的30%补贴、最高不超过5万元；发明专利每项奖励2万元。"},{"sectionNo":"四2","headline":"研发投入全市前10名获补助，前5位10万、第6至10位5万","who":"建立研发准备金制度、有研发（R&D）经费投入的企业；按上一年度研发经费投入总量及占主营业务收入比例综合认定，以税务部门税前加计扣除认定为准；全市排名前10位。","materials":[],"window":"按上一年度研发经费投入总量认定，年度评定。","where":"以税务部门税前加计扣除认定为准。","tip":"仅全市排名前10位可获补助：前5位各10万元，第6—10位各5万元。"},{"sectionNo":"四2续","headline":"高企新认定奖20万、重新认定10万，搬迁入怀再奖10万","who":"新认定和重新认定的高新技术企业；在有效期内整体搬迁入怀的高新技术企业。","materials":[],"window":"按认定年度给予申报奖励；研发费用补贴以符合企业所得税税前加计扣除的研发费用为基数计算。","where":"原文未列明受理部门或申报系统。","tip":"新认定20万元、重新认定10万元、有效期内整体搬迁入怀10万元；研发费用新增部分按10%补贴，合计最高30万元。"},{"sectionNo":"外贸","headline":"考核合格的外贸综合服务中心每个支持25万元","who":"现有外贸综合服务中心及新成立的园区外贸综合服务中心；须考核合格。","materials":[],"window":"原文未列明申报时间，按考核结果予以支持。","where":"原文未列明受理部门。","tip":"按25万元/个标准支持，前提是考核合格；全市推动成立1家以上园区外贸综合服务中心。"}],"sourceUrl":"https://www.huaihua.gov.cn/huaihua/c133461/202304/e2610237152548d1a17d78a4f72d9cbb.shtml","sourceNote":"2026-11-21 取自怀化市政府门户原文页；页面未标注文号，措施条目与金额已逐字核对，另经中方县政府转载页比对一致。 2026-11-21 收录：与官方页面逐句比对，命中 7/7 句（100%），关卡判定「verbatim」。 有效期依据：原文未设期限；按行政规范性文件一般不超5年推算至2028-03 2026-11-21 补录：documentNo 据官方页面版头/落款核对后填入。","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"hh-tech-2025-5","title":"怀化市人民政府办公室关于印发《怀化市加快科技创新与成果转化赋能高质量发展若干措施》的通知","level":"city","region":"怀化市","issuer":"怀化市人民政府办公室","documentNo":"怀政办发〔2025〕5号","publishedAt":"2025-03-27","effectiveAt":null,"expiresAt":null,"status":"active","tags":["研发创新","认定资质","财政奖补"],"audience":["怀化市中医药、新材料、新型显示等产业链企业","高新技术企业","科技创新平台建设单位"],"summary":"对牵头实施“5+10”现代化产业体系科技创新与成果转化专项的单位，每个给予最高200万元支持；高新技术企业首次认定奖20万元。","sections":[{"no":"一(一)","title":"强化重点产业技术攻关","text":"针对中医药、新材料、新型显示等产业链的核心技术需求，支持产业链上下游企业联合高校、科研院所共同攻克关键核心技术难题。精准编制科技创新与成果转化项目清单，组织实施怀化市“5+10”现代化产业体系科技创新与成果转化专项。对牵头实施专项项目的单位，按市级科技计划项目立项程序评估，每个给予最高200万元支持。"},{"no":"一(二)","title":"联合基金","text":"进一步完善湖南省自然科学基金区域（怀化市）联合基金资助机制，鼓励企事业单位出资参与联合基金项目资助，开展高质量的基础研究和应用基础研究，培养青年科技人才，增强自主创新能力，对立项项目最高资助10万元。"},{"no":"一(三)","title":"科技计划引导","text":"完善以基础研究、重点研发、成果转化等科技创新全链条为基本框架的项目体系，每年组织实施“十大科技创新项目”、重点研发计划等一批市级科技计划项目，择优给予立项扶持。对符合我市发展战略的重点产业、重点领域、重点企业在项目推荐申报方面予以倾斜。"},{"no":"高新技术企业","title":"梯次培育奖励","text":"对首次认定、重新认定的高新技术企业，一次性分别给予20万元、10万元奖励。对新获批的国家高新区、国家农业高新技术产业示范区和省级高新区、省级农业科技园区，一次性分别给予100万元、50万元奖励。"}],"interpretations":[{"sectionNo":"一(一)","headline":"牵头实施市级科技专项，每个项目最高支持200万元","who":"中医药、新材料、新型显示等产业链上下游企业，需联合高校、科研院所共同攻克关键核心技术；牵头实施怀化市“5+10”现代化产业体系科技创新与成果转化专项项目的单位。","materials":[],"window":"按市级科技计划项目立项程序评估立项后支持；原文未明确申报截止时间。","where":"怀化市“5+10”现代化产业体系科技创新与成果转化专项，按市级科技计划项目立项程序评估","tip":"仅对牵头实施专项项目的单位给予支持，联合参与的高校、科研院所不单列；须先通过市级科技计划项目立项程序评估。"},{"sectionNo":"一(二)","headline":"联合基金立项项目最高资助10万元","who":"湖南省自然科学基金区域（怀化市）联合基金出资参与的企事业单位，以及开展基础研究和应用基础研究的青年科技人才；立项项目方可获资助。","materials":[],"window":"按湖南省自然科学基金区域（怀化市）联合基金资助机制立项；原文未明确申报截止时间。","where":"湖南省自然科学基金区域（怀化市）联合基金（原文未点名具体受理部门）","tip":"须先出资参与联合基金项目资助，且项目经立项；单个立项项目资助不超过10万元。"},{"sectionNo":"一(三)","headline":"重点产业企业申报市级科技计划，推荐申报予以倾斜","who":"符合怀化市发展战略的重点产业、重点领域、重点企业；申报“十大科技创新项目”、重点研发计划等市级科技计划项目的单位。","materials":[],"window":"每年组织实施“十大科技创新项目”、重点研发计划等市级科技计划项目，按年度申报。","where":"市级科技计划项目申报渠道（原文未点名具体部门和系统）","tip":"项目需择优立项，非申报即得；重点产业、重点领域、重点企业在推荐申报环节倾斜。"},{"sectionNo":"高新技术企业","headline":"首次认定高企奖20万元，重新认定奖10万元","who":"首次认定或重新认定的高新技术企业；新获批的国家高新区、国家农业高新技术产业示范区、省级高新区、省级农业科技园区。","materials":[],"window":"认定或获批后一次性奖励；原文未明确申报截止时间。","where":"高新技术企业认定及园区批复渠道（原文未点名具体受理部门）","tip":"首次认定与重新认定奖励不同（20万元与10万元），按认定类型对应；园区按国家级、省级分别100万元、50万元。"}],"sourceUrl":"http://www.huaihua.gov.cn/huaihua/c138296/202507/a2404de9d20b45ff961f2fad388edcc6/files/a60177c973c248d5ad8eaae33751aff5.pdf","sourceNote":"2026-11-21 取自《怀化市人民政府公报》2025年第3期（总第42期）原文；文号与成文日期（2025年3月27日）已核对。 2026-11-21 收录：与官方页面逐句比对，命中 8/8 句（100%），关卡判定「verbatim」。 有效期依据：原文未设期限；规范性文件登记号 HHCR-2025-01001，按一般不超5年推算至2030-03","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"hh-trade-2026","title":"怀化市人民政府办公室关于印发《怀化市服务和促进外贸高质量发展的若干措施》的通知","level":"city","region":"怀化市","issuer":"怀化市人民政府办公室","documentNo":"怀政办发〔2026〕8号","publishedAt":"2026-07-17","effectiveAt":"2026-07-17","expiresAt":"2029-07-17","status":"active","tags":["外贸外资","财政奖补","融资支持"],"audience":["外贸企业","跨境电商企业","生产型出口企业","国际物流企业"],"summary":"18条措施支持外贸主体发展、开拓多元国际市场、提升通关便利化、强化全链条服务；境外展会市级配套10%展位费，非省重点展会给予不超过70%展位费与50%交通费支持，单家企业年度重点展会市级财政支持不超过10万元，有效期3年。","sections":[{"no":"一2","title":"鼓励外贸企业实施技术改造","text":"鼓励外贸企业夯实发展根基，支持企业在技改升级、设备更新、重大项目、智能化改造、专精特新培育、装备首台套、新材料首批次生产应用等领域申报国家、省、市专项资金。"},{"no":"二5","title":"加强参会参展服务保障","text":"全面落实省重点境外展会补贴政策，市级配套10%展位费支持。对参加省重点境外展会以外的境内外重点国际性展会的企业，给予不超过70%的展位费支持和不超过50%的交通费支持，单个企业单次参展参会交通费支持金额最高不超过1万元，同一企业年度重点展会市级财政支持金额总计不超过10万元。"},{"no":"三9","title":"建立外贸企业白名单机制","text":"联合商务、发展改革、海关、税务、人民银行、工业和信息化、农业农村、林业、贸促、教育、卫生健康等部门，动态评审和发布外贸企业白名单，强化“越合规越便利越优先”导向。对纳入白名单的外贸企业提供快速通关、优先办理出口退税、加急办理外汇业务、优先调配物流班列仓位等便利。"},{"no":"四14","title":"深化金融产品与信保服务","text":"结合箱包、水果、竹木等特色产业，推广仓单贷、订单贷、箱包贷、水果贷、竹木贷、退税贷等专属金融产品，满足外贸企业合理融资需求，提高授信规模，做到应贷尽贷。扩大出口信用保险覆盖面，优化承保、理赔流程，发展供应链金融。"}],"interpretations":[{"sectionNo":"一2","headline":"外贸企业技改、设备更新等可申报国家省市专项资金","who":"怀化市外贸企业；项目须落在技改升级、设备更新、重大项目、智能化改造、专精特新培育、装备首台套、新材料首批次生产应用等领域。","materials":[],"window":"按国家、省、市专项资金申报要求执行，原文未明确具体期限。","where":"国家、省、市专项资金。","tip":"申报领域限定为技改升级、设备更新、智能化改造、装备首台套、新材料首批次生产应用等，领域外项目不在支持范围。"},{"sectionNo":"二5","headline":"参展省重点境外展会，市级再配套10%展位费","who":"参加省重点境外展会的怀化市外贸企业，市级配套10%展位费；参加省重点境外展会以外的境内外重点国际性展会的企业，展位费支持不超过70%、交通费不超过50%。","materials":[],"window":"单次参展参会交通费支持最高1万元；同一企业年度重点展会市级财政支持累计不超过10万元。","where":"市级财政；省重点境外展会补贴按省政策执行。","tip":"交通费按单次最高1万元封顶，年度市级支持累计不超过10万元；省重点展会以外的展会按展位费70%、交通费50%的比例支持。"},{"sectionNo":"三9","headline":"纳入外贸白名单，可快速通关、优先退税、加急办外汇","who":"怀化市外贸企业；由商务、发展改革、海关、税务、人民银行等部门动态评审纳入白名单，合规经营是前提。","materials":[],"window":"白名单动态评审、发布，原文未设固定申报期。","where":"商务、海关、税务、人民银行等部门联合评审。","tip":"便利包括快速通关、优先办理出口退税、加急办理外汇业务、优先调配物流班列仓位；导向是“越合规越便利越优先”。"},{"sectionNo":"四14","headline":"箱包、水果、竹木外贸企业可申请仓单贷、订单贷等","who":"怀化市箱包、水果、竹木等特色产业外贸企业；有合理融资需求，可申请仓单贷、订单贷、箱包贷、水果贷、竹木贷、退税贷。","materials":[],"window":"常态化推广，做到应贷尽贷，原文未设申报期限。","where":"原文未列明具体经办银行或系统。","tip":"融资与出口信用保险同步推进：扩大信保覆盖面、优化承保理赔流程，并发展供应链金融。"}],"sourceUrl":"https://www.huaihua.gov.cn/huaihua/c122169/202607/680ab2c7395344dcbd22bd591c3598b9.shtml","sourceNote":"2026-11-22 取自怀化市人民政府门户「信息公开—文件库—市政府办公室文件」原文页，版头载文号怀政办发〔2026〕8号、统一登记号 HHCR-2026-01002，页面信息时效期栏载2029-07-17。 2026-11-22 收录：与官方页面逐句比对，命中 7/7 句（100%），关卡判定「verbatim」。 有效期依据：正文末段明示“有效期3年”；页面信息时效期栏载2029-07-17","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"hn-advmfg-fund-2023-31","title":"湖南省财政厅 湖南省工业和信息化厅关于印发《湖南省先进制造业高地建设专项资金管理办法》的通知","level":"provincial","region":"湖南省","issuer":"湖南省财政厅、湖南省工业和信息化厅","documentNo":"湘财企〔2023〕31号","publishedAt":"2023-12-28","effectiveAt":"2024-01-01","expiresAt":"2026-12-31","status":"expiring","tags":["财政奖补"],"audience":["符合条件的工业企业","为工业发展提供服务的机构"],"summary":"专项资金采取无偿补助、贷款贴息、奖励等方式支持先进制造业重大项目；重点产业项目和重大平台项目的实施主体给予不超过500万元的资金补助。","sections":[{"no":"第三条","title":"申报与审核责任","text":"市州、财政省直管县（市）工信部门围绕政策目标，对照项目申报条件，根据本地区产业基础和优势审核推荐项目，市州、财政省直管县（市）财政部门配合同级工信部门开展相关工作。直接受理资金申报材料的工信部门承担直接审核把关责任。原则上，项目按属地申报管理。"},{"no":"第五条","title":"支持方向","text":"专项资金实施归口管理，聚焦产业基础再造和重大技术装备攻关、数字经济创新发展、“智赋万企”重点项目实施、重点产业链（群）培育壮大、制造业高端化、智能化、绿色低碳发展等领域，重点支持先进制造业重大新建项目、重大技术改造项目、重大扩能提质升级项目等有效投资项目，以及省委、省政府决策部署的重大事项。"},{"no":"第六条","title":"年度申报与限额","text":"省工信厅会同省财政厅根据年度支持方向和重点，发布专项资金申报通知和申报指南，明确专项资金支持领域、支持方式、申报条件和要求。原则上同一项目单位同一年度最多获得两项奖励类资金和一项补助类资金支持。原则上同一项目只能获得一次资金支持。"},{"no":"第七条","title":"支持方式","text":"专项资金主要采取项目法和因素法等方式进行分配。采用项目法分配的，实行项目库管理，应当有明确的项目建设任务。由省工信厅组织实施项目遴选，主要采取认定、事前绩效评估、评审、招标等方式确定拟支持项目，按照无偿补助、贷款贴息、奖励等方式给予支持。"},{"no":"执行标准","title":"单项目补助上限","text":"（依省门户惠企政策公开口径）对重点产业项目和重大平台项目的实施主体给予不超过500万的资金补助。"}],"interpretations":[{"sectionNo":"第三条","headline":"项目按属地申报，由市县工信部门审核推荐","who":"按属地申报的项目单位；由市州、财政省直管县（市）工信部门对照项目申报条件审核推荐，同级财政部门配合开展相关工作，直接受理资金申报材料的工信部门承担直接审核把关责任。","materials":[],"window":"按年度组织申报，由市县工信部门审核推荐；本条未规定具体申报起止时间。","where":"项目所在地市州、财政省直管县（市）工信部门（按属地申报管理）。","tip":"项目按属地申报管理；直接受理资金申报材料的工信部门承担直接审核把关责任，申报条件由受理部门对照审核。"},{"sectionNo":"第五条","headline":"专项资金支持先进制造业重大新建、技改、扩能提质项目","who":"聚焦产业基础再造和重大技术装备攻关、数字经济创新发展、“智赋万企”重点项目实施、重点产业链（群）培育壮大、制造业高端化、智能化、绿色低碳发展等领域的项目单位；重点支持先进制造业重大新建项目、重大技术改造项目、重大扩能提质升级项目等有效投资项目，以及省委、省政府决策部署的重大事项。","materials":[],"window":"实行归口管理，按年度支持方向和重点组织申报；本条未规定申报起止时间。","where":"省工信厅、省财政厅（省级归口管理，按年度申报通知受理）。","tip":"支持对象限先进制造业重大新建、重大技术改造、重大扩能提质升级等有效投资项目，以及省委、省政府决策部署的重大事项。"},{"sectionNo":"第六条","headline":"同一单位每年最多两项奖励、一项补助，同一项目仅一次","who":"申报省级先进制造业高地建设专项资金的项目单位；同一项目单位同一年度最多获得两项奖励类资金和一项补助类资金支持。","materials":[],"window":"按年度申报通知和申报指南组织；同一年度内计算奖励类、补助类支持次数。","where":"省工信厅、省财政厅（发布专项资金申报通知和申报指南）。","tip":"同一项目只能获得一次资金支持；同一年度超过两项奖励类、一项补助类限额的不再支持。"},{"sectionNo":"第七条","headline":"专项资金按项目法分配，以补助、贴息、奖励方式支持","who":"纳入项目库管理、有明确项目建设任务的项目单位；由省工信厅组织项目遴选，经认定、事前绩效评估、评审、招标等方式确定。","materials":[],"window":"实行项目库管理，按年度组织遴选；本条未规定具体申报期限。","where":"省工信厅（组织实施项目遴选）。","tip":"采用项目法分配须先纳入项目库并有明确项目建设任务；支持方式为无偿补助、贷款贴息或奖励。"},{"sectionNo":"执行标准","headline":"重点产业和重大平台项目，补助最高不超过500万元","who":"重点产业项目和重大平台项目的实施主体。","materials":[],"window":"按项目申报；本条未列申报期与频次。","where":"省工信厅、省财政厅（专项资金归口管理）。","tip":"补助对象限重点产业项目和重大平台项目的实施主体，单个主体补助不超过500万元。"}],"sourceUrl":"https://www.hunan.gov.cn/hnszf/xxgk/wjk/szbm/szfzcbm_19689/sczt/gfxwj_19835/202406/33326162/files/146e935f31e64aff9601a6b0a9eebadf.doc","sourceNote":"2026-11-21 取自省门户「文件库—省财政厅—规范性文件」条目所附原文（.doc 直链）；文号、施行日、截止日与省门户惠企政策页一致。注意：本条 main_url 为附件直链，按链接规则属降级形态，已在覆盖矩阵中标注。 2026-11-21 收录：与官方页面逐句比对，命中 10/11 句（91%），关卡判定「verbatim」。 有效期依据：原文明示（施行日与截止日均载明）","verified":false,"isSample":false,"numberStyle":"clause","bodyVerified":"verbatim","hunan":true},{"id":"hn-bid-2025","title":"湖南省人民政府办公厅关于创新完善体制机制推动招标投标市场规范健康发展的实施意见","level":"provincial","region":"湖南省","issuer":"湖南省人民政府办公厅","documentNo":"","publishedAt":"2025-04-29","effectiveAt":"2025-04-29","expiresAt":"2030-04-28","status":"active","tags":["营商环境"],"audience":["参与招标投标的中小企业","首台（套）重大技术装备制造企业","招标人及代理机构"],"summary":"适用招标投标法的政府采购工程项目，2026年底前为中小企业预留40%份额；落实首台（套）重大技术装备招标投标机制。","sections":[{"no":"(十九)","title":"提升招标投标政策效能","text":"落实首台（套）重大技术装备招标投标机制，支持首台（套）重大技术装备平等参与企业招标投标活动。优化绿色招标采购推广应用机制。落实工程建设招标投标领域支持中小企业发展政策举措，2026年底前，适用招标投标法的政府采购工程项目适宜由中小企业提供的，为中小企业预留40%份额。"},{"no":"(十九)续","title":"国企社会责任考核","text":"探索将支持中小企业参与招标投标情况列为国有企业履行社会责任考核内容。"},{"no":"(二十一)","title":"清理交易壁垒","text":"定期对招标投标法规、规章、规范性文件、其他政策文件和范本以及有关做法进行全面排查，持续开展招标投标交易壁垒征集，健全招标投标交易壁垒投诉、处理、回应机制，及时清理所有制歧视、行业壁垒、地方保护等不合理限制。"}],"interpretations":[{"sectionNo":"(十九)","headline":"2026年底前，政府采购工程项目为中小企业预留40%份额","who":"适用招标投标法的政府采购工程项目中的中小企业；须项目适宜由中小企业提供。首台（套）重大技术装备可平等参与企业招标投标活动。","materials":[],"window":"2026年底前落实为中小企业预留40%份额；首台（套）装备招标投标机制、绿色招标采购机制为常态化执行。","where":"适用招标投标法的政府采购工程项目（招标环节预留份额）。","tip":"预留40%份额以项目「适宜由中小企业提供」为前提，并非所有政府采购工程项目都适用。"}],"sourceUrl":"https://www.hunan.gov.cn/hnszf/xxgk/wjk/szfbgt//202505/33662166/files/c01b54e1884d4c8babd1eb04af337097.doc","sourceNote":"2026-11-21 取自省门户「文件库—省政府办公厅文件」条目原文（.doc 直链）；页末落款与有效期条款均已核对。文号未在正文出现。 2026-11-21 收录：与官方页面逐句比对，命中 5/5 句（100%），关卡判定「verbatim」。 有效期依据：原文明示（自发布之日起施行、有效期5年）","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"hn-digtrade-2026-46","title":"湖南省人民政府办公厅关于印发《湖南省促进数字贸易创新发展的若干措施》的通知","level":"provincial","region":"湖南省","issuer":"湖南省人民政府办公厅","documentNo":"湘政办发〔2026〕46号","publishedAt":"2026-09-16","effectiveAt":null,"expiresAt":null,"status":"active","tags":["外贸外资","数字化转型","财政奖补"],"audience":["数字贸易企业","跨境电商企业","服务外包企业","文化科技类经营主体"],"summary":"从培育经营主体、拓展境外业务、推进数字化转型、发展数字技术贸易等方面提出措施，支持跨境电商综试区提质升级与“跨境电商+海外仓”发展。","sections":[{"no":"一(一)","title":"多层次招引经营主体","text":"做强数智制造贸易融合企业、做优知识密集型服务贸易企业、做大服务外包企业，构建梯度层次递进、大中小企业协同发展的数字贸易生态。利用“港洽周”“沪洽周”、全球湘商大会、中国国际供应链促进博览会等重大招商平台，聚焦信息技术服务、人工智能等重点领域，靶向引进一批拥有海外市场的“链主”企业和核心配套商。"},{"no":"一(二)","title":"多渠道拓展境外业务","text":"持续完善《湖南省重点境外展会目录》，支持企业参加国际国内优质数字贸易展会，指导市州利用中国国际服务贸易交易会、全球数字贸易博览会等平台举办路演、磋商等活动。支持数字企业采取融资并购、建立国际营销网络等方式布局海外市场。"},{"no":"一(三)","title":"推进数字化转型和数据赋能","text":"支持会计、法律、管理咨询、广告等专业服务机构线上运营，提升国际化、数智化服务水平。"},{"no":"三(九)","title":"提质数字订购贸易","text":"推动跨境电商综合试验区建设提质升级，梯度建设跨境电商产业集聚园区，赋能湖湘特色产业带跨境出海。支持跨境电商孵化中心、综合服务平台等建设，鼓励企业利用跨境电商平台、独立站等拓展出海新渠道。支持企业品牌建设及国际营销推广，培育跨境电商自主品牌。支持“跨境电商+海外仓”发展，推动海外仓功能升级。"},{"no":"四(十)","title":"着力发展数字技术贸易","text":"推动人工智能、绿电装备、生命健康、空天产品等高技术、高附加值、高成长性产品出口，大力培育数字技术贸易龙头企业。支持科研机构、企业设立境外研发中心、联合实验室，认定并支持一批数字经济领域外资研发中心，对符合条件的科研用品进口按规定免除相关税费。"}],"interpretations":[{"sectionNo":"四(十)","headline":"数字经济外资研发中心认定，科研用品进口免税费","who":"在境外设立研发中心、联合实验室的科研机构、企业；被认定为数字经济领域外资研发中心的机构，其符合条件的科研用品进口可按规定免除相关税费。","materials":[],"window":"按外资研发中心认定批次执行；原文未列申报时间。","where":"原文未写明具体受理部门，按数字经济领域外资研发中心认定程序办理。","tip":"免税只限符合条件的科研用品进口；须先取得数字经济领域外资研发中心认定。"}],"sourceUrl":"https://hunan.gov.cn/zqt/zcsd/202609/t20260929_34074001.html","sourceNote":"2026-11-21 取自省门户「政策速递」原文页；页面标题与文号已核对。第五条与政府公报2026年第19期所载文本一致。 2026-11-21 收录：与官方页面逐句比对，命中 11/11 句（100%），关卡判定「verbatim」。 有效期依据：原文未设期限；按行政规范性文件一般不超过5年的通行要求推算至2031-09","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"hn-guarantee-2026-22","title":"湖南省人民政府办公厅关于印发《推动融资担保行业高质量发展的实施方案》的通知","level":"provincial","region":"湖南省","issuer":"湖南省人民政府办公厅","documentNo":"湘政办发〔2026〕22号","publishedAt":"2026-03-23","effectiveAt":"2026-04-01","expiresAt":"2031-03-31","status":"active","tags":["融资支持","贷款贴息","财政奖补"],"audience":["政府性融资担保机构","小微企业","“三农”主体","出海民营中小企业"],"summary":"政策性常规融资担保业务按0.75%给予保费补贴，每家机构每年最高不超过500万元；科技创新类中小企业单户在保余额上限提高至3000万元。","sections":[{"no":"二(一)1","title":"进一步规范机构运行","text":"省财政厅会同省委金融办建立政府性融资担保机构名单制管理动态调整制度。各级财政部门要指导政府性融资担保机构优化公司治理结构，完善议事规则和决策程序，增强公司治理的规范性和有效性。政府性融资担保机构应自主经营、独立决策、自担风险，地方各级人民政府及有关部门不得干预其日常经营活动。"},{"no":"二(一)2","title":"完善资本金补充机制","text":"统筹研究对政府性融资担保机构的支持规模，完善资本金补充机制，支持政府性融资担保机构可持续发展。对融资担保责任余额放大倍数达到6倍以上且最近一个会计年度分类监管评级结果为“A”级的融资担保机构，鼓励出资人启动增资程序。"},{"no":"二(一)3","title":"优化风险补偿机制","text":"对省再担保公司开展的国家融资担保基金备案业务、省级备案业务、因国家融资担保基金政策调整或授信额度不足导致不能备案的业务，代偿率在5%以内部分，原则上按照国家融资担保基金、省级财政、省再担保公司40%，担保机构30%，合作银行20%，市县财政10%的比例进行风险分担。市县人民政府要严格落实风险代偿补偿专项资金提取制度并纳入本级财政预算，落实10%风险分担。"},{"no":"二(一)4","title":"加大保费补贴力度","text":"省级财政对单笔融资担保金额1000万元及以下且年化担保费率（含税）不高于1%的政策性常规融资担保业务，按照0.75%给予保费补贴；对线上标准化政策性批量担保业务，按照0.8%与实际担保费率之差给予保费补贴，且最高不超过0.3%。每家融资担保机构每年最高补贴金额不超过500万元。实施减免政策的再担保业务，省级财政对减免部分给予补贴。"},{"no":"二(二)7","title":"加快推动科技担保业务","text":"落实国家科技创新专项担保计划。科技创新类中小企业单户在保余额上限提高至3000万元。鼓励政府性融资担保机构创新开展科技型中小企业融资担保合作，进一步降低担保费率和反担保要求，拓展科技型企业首次担保覆盖面。支持融资担保机构开展“投担联动”，为企业发行科创债券提供增信支持。"},{"no":"二(二)9","title":"优化普惠重点群体担保服务","text":"融资担保机构要围绕省委、省人民政府重大战略部署，优化重点领域产品服务供给，增强对民营企业的融资担保支持。各级政府性融资担保机构应在可持续经营的前提下降费让利，促进常规业务与批量业务协调发展。"},{"no":"二(三)12","title":"深化银担合作","text":"在风险可控的前提下，全面取消保证金或变相保证金。对政策性担保业务，风险分担比例不低于20%。全面落实无还本续贷，给予融资担保机构不低于60天的代偿宽限期。支持银行业监管部门将银担合作情况纳入银行业金融机构业绩考评体系。"},{"no":"二(三)13","title":"落实财税支持政策","text":"融资担保机构为农户、小型企业、微型企业及个体工商户借款、发行债券提供融资担保取得的保费收入，以及为上述融资担保提供再担保取得的再担保收入，免征增值税。对符合条件的中小企业融资担保机构实施担保赔偿准备金、未到期责任准备金企业所得税税前扣除。"},{"no":"三","title":"施行日期与有效期","text":"本方案自2026年4月1日起施行，有效期5年。国家和我省对政策性融资担保业务单户在保余额，农业信贷担保风险分担、保费补贴另有规定的，从其规定。"}],"interpretations":[{"sectionNo":"二(一)2","headline":"放大倍数6倍以上且监管评级A级，鼓励出资人增资","who":"融资担保责任余额放大倍数达到6倍以上、且最近一个会计年度分类监管评级结果为“A”级的融资担保机构。","materials":[],"window":"按最近一个会计年度分类监管评级结果核定，原文未设申报截止时间。","where":"出资人（启动增资程序）","tip":"两个条件须同时满足；政策用词为鼓励出资人启动增资，不是自动补充资本金。"},{"sectionNo":"二(一)3","headline":"代偿率5%以内，按40%、30%、20%、10%比例分险","who":"省再担保公司开展的国家融资担保基金备案业务、省级备案业务、因国家融资担保基金政策调整或授信额度不足导致不能备案的业务；代偿率在5%以内部分。","materials":[],"window":"按代偿率5%以内部分计算，市县财政须将风险代偿补偿专项资金纳入本级预算。","where":"国家融资担保基金、省级财政、省再担保公司、担保机构、合作银行、市县财政","tip":"分担比例为40%、30%、20%、10%；市县财政须严格落实10%风险分担并纳入本级财政预算。"},{"sectionNo":"二(一)4","headline":"政策性担保保费补贴0.75%，单机构每年最高500万元","who":"单笔融资担保金额1000万元及以下、年化担保费率（含税）不高于1%的政策性常规融资担保业务；线上标准化政策性批量担保业务及实施减免政策的再担保业务。","materials":[],"window":"按年度补贴，每家融资担保机构每年最高补贴金额不超过500万元。","where":"省级财政","tip":"批量业务按0.8%与实际担保费率之差补贴，最高不超过0.3%；单家机构年度补贴上限500万元。"},{"sectionNo":"二(二)7","headline":"科技创新类中小企业单户在保余额上限提至3000万元","who":"科技创新类中小企业；由政府性融资担保机构提供融资担保，单户在保余额上限提高至3000万元。","materials":[],"window":"按担保业务办理，原文未设申报期限。","where":"政府性融资担保机构","tip":"3000万元是单户在保余额上限，不是补贴金额；首次担保覆盖面与反担保要求可进一步放宽。"},{"sectionNo":"二(三)12","headline":"银担合作取消保证金，政策性担保风险分担不低于20%","who":"办理政策性融资担保业务的企业和融资担保机构；银担合作业务全面取消保证金或变相保证金。","materials":[],"window":"代偿宽限期不低于60天，无还本续贷全面落实，原文未设截止时间。","where":"银行与融资担保机构（银担合作）","tip":"风险分担比例不低于20%、代偿宽限期不低于60天，均为底线要求；无还本续贷全面实施。"},{"sectionNo":"二(三)13","headline":"为小微、农户等担保取得的保费收入免征增值税","who":"融资担保机构：为农户、小型企业、微型企业及个体工商户借款、发行债券提供融资担保取得的保费收入，以及为上述融资担保提供再担保取得的再担保收入。","materials":[],"window":"按现行税收政策执行，原文未设期限。","where":"增值税免征与企业所得税税前扣除环节","tip":"免税和税前扣除都要求担保对象为农户、小型企业、微型企业及个体工商户；原文未列备案材料。"}],"sourceUrl":"https://hunan.gov.cn/hnszf/xxgk/wjk/szfbgt/202603/t20260326_33942249.html","sourceNote":"2026-11-21 取自湖南省政府门户「文件库—省政府办公厅文件」原文页；页面标题与文号已核对。第三条数据引自省地方金融管理局、省财政厅公开答复（湘金办函〔2026〕23号）中对本文件的口径复述。 2026-11-21 收录：与官方页面逐句比对，命中 25/25 句（100%），关卡判定「verbatim」。 有效期依据：原文明示（自2026年4月1日起施行，有效期5年，推算至2031-03-31）","verified":false,"isSample":false,"numberStyle":"clause","bodyVerified":"verbatim","hunan":true},{"id":"hn-ipo-2022-02","title":"湖南省人民政府办公厅关于印发《湖南省企业上市“金芙蓉”跃升行动计划（2022—2025年）》的通知","level":"provincial","region":"湖南省","issuer":"湖南省人民政府办公厅","documentNo":"湘政办发〔2022〕2号","publishedAt":"","effectiveAt":null,"expiresAt":"2025-12-31","status":"expired","tags":["上市培育","财政奖补","融资支持"],"audience":["已完成股份制改造、拟在沪深北交易所上市的湖南企业","境外上市及迁址入湘的上市公司"],"summary":"省财政对已在湖南证监局辅导验收的企业给予200万元补助，对科创板上市企业再奖励100万元；收购省外上市公司控制权并迁址湖南的给予200万元一次性补助。","sections":[{"no":"三(一)","title":"实施财政补助","text":"省财政对已在湖南证监局辅导验收的企业，给予200万元补助资金，对科创板上市企业再奖励100万元。对在香港、美国等资本市场上市的公司，参照企业A股上市补助政策给予资金补助。对收购省外上市控制权并将注册地迁至我省的企业，省财政给予200万元的一次性补助资金。"},{"no":"三(一)续","title":"市州配套","text":"各市州人民政府要根据实际，健全覆盖企业股份制改造、上市、并购重组等方面的政策措施，对企业股份制改造、重组过程中的新增成本给予奖补、缓交等优惠政策，降低上市成本。"},{"no":"三(二)","title":"加大人才支持","text":"对上市公司、拟上市企业为引进高层次急需紧缺人才支付的一次性住房补贴、安家费、科研启动经费等支出，落实国家企业所得税税前扣除政策。"},{"no":"三(三)","title":"健全工作机制","text":"充分发挥省企业上市工作联席会议作用，定期召开会议，研究部署企业上市工作，协调解决重大问题，加快推进上市进程。各市州、市县区人民政府要把推进企业上市“金芙蓉”跃升行动计划摆在突出重要位置，制定政策规划，纳入绩效评估，组建工作专班。"},{"no":"十一","title":"引导上市公司做强做优","text":"支持上市公司采取增发、配股、发行可转债等多种方式再融资。鼓励上市公司开展并购重组，优化产业结构，带动产业链发展。各市州、国家级产业园区支持辖区内上市公司设立并购重组引导基金，积极开展产业链横向、纵向整合，壮大产业集群。"}],"interpretations":[{"sectionNo":"三(一)","headline":"证监局辅导验收即补200万元，科创板上市再奖100万元","who":"已在湖南证监局辅导验收的企业；科创板上市企业；在香港、美国等资本市场上市的公司；收购省外上市控制权并将注册地迁至我省的企业。","materials":[],"window":"辅导验收后给予补助；科创板上市再奖励100万元；收购省外上市控制权并迁址的为一次性补助。","where":"省财政。","tip":"境外上市参照企业A股上市补助政策；收购省外上市公司控制权须将注册地迁至我省，才能拿到一次性补助。"},{"sectionNo":"三(一)续","headline":"企业股改、重组新增成本可获奖补或缓交","who":"在各市州进行股份制改造、上市、并购重组的企业；股改、重组过程中的新增成本可获奖补、缓交等优惠。","materials":[],"window":"由各市州根据实际制定政策措施，原文未明确具体期限。","where":"各市州人民政府。","tip":"政策覆盖股改、上市、并购重组三个环节；奖补与缓交的具体标准由各市州按实际确定。"},{"sectionNo":"三(二)","headline":"上市及拟上市企业引才的住房补贴、安家费可税前扣除","who":"上市公司、拟上市企业；支出须是为引进高层次急需紧缺人才支付的一次性住房补贴、安家费、科研启动经费等。","materials":[],"window":"按国家企业所得税税前扣除政策执行，原文未另设期限。","where":"原文未列明受理部门或系统。","tip":"只限引进高层次急需紧缺人才的相关支出，且须符合国家企业所得税税前扣除政策口径。"},{"sectionNo":"十一","headline":"上市公司可增发、配股、发可转债再融资","who":"省内上市公司；可由各市州、国家级产业园区支持辖区内上市公司设立并购重组引导基金。","materials":[],"window":"原文未明确申报期；再融资、并购重组按常态化推进。","where":"各市州、国家级产业园区。","tip":"再融资方式包括增发、配股、发行可转债；并购重组引导基金面向辖区内上市公司，用于产业链横向、纵向整合。"}],"sourceUrl":"https://www.hunan.gov.cn/xxgk/wjk/szfbgt/202201/22459805/files/47b9f5ff21fe453eb285d704052b41d8.doc","sourceNote":"2026-11-21 取自省门户「文件库—省政府办公厅文件」条目原文（.doc 直链）；文号与补助标准另经省门户惠企政策页「企业上市补助」交叉核对一致。计划期已过，主数据保留但标注失效，供对照历史口径。 2026-11-21 收录：与官方页面逐句比对，命中 10/10 句（100%），关卡判定「verbatim」。 有效期依据：原文明示施行方式，计划期止于2025年；基准日已过，判失效","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"hn-robot-2026","title":"湖南省人民政府办公厅关于加快智能机器人产业发展的实施意见","level":"provincial","region":"湖南省","issuer":"湖南省人民政府办公厅","documentNo":"","publishedAt":"2026-08-15","effectiveAt":"2026-08-15","expiresAt":"2031-08-14","status":"active","tags":["财政奖补","融资支持"],"audience":["智能机器人整机及零部件企业","产业链上下游配套企业","未来产业子基金管理机构"],"summary":"加强国省财政资金统筹支持技术攻关、企业培育、平台建设，依法加快设立目标规模100亿元的未来产业子基金，并落实中小微企业贷款贴息等金融工具。","sections":[{"no":"二(十)","title":"财政金融保障工程","text":"加强国省财政资金统筹，持续加大对智能机器人技术攻关、企业培育、平台建设、场景打造、人才引育、产业大赛举办及市州成效激励等重点领域的投入。发挥金芙蓉投资基金作用，依法加快设立目标规模100亿元的未来产业子基金，引导社会资本加大对智能机器人领域的投资。"},{"no":"二(十)续","title":"信贷与担保工具","text":"创新信贷产品，推广产业链供应链贷、研发和场景专项信贷等特色金融产品，落实中小微企业贷款贴息、“潇湘财银贷”风险补偿、中小企业商业价值信用贷款风险补偿、科技型企业知识价值贷款风险补偿等国省支持政策，拓宽企业融资渠道，降低智能机器人领域相关企业融资成本。"},{"no":"二(十)续二","title":"科技保险","text":"完善担保与租赁机制，发挥融资租赁对机器人产品推广助力作用，鼓励政府性融资担保机构为机器人项目提供融资增信支持。健全科技保险保障体系，支持企业投保科技保险，构建多元化、多层次的财政金融保障体系。"},{"no":"三","title":"保障措施","text":"在制造强省建设领导小组下，设立智能机器人产业发展专项小组，统筹制定省级支持政策，协调解决产业发展重大问题。聚焦产业链上中下游全链条，加快建立智能机器人产业发展统计监测体系，一体推进产业数据动态监测。"}],"interpretations":[{"sectionNo":"二(十)","headline":"设100亿元未来产业子基金，投智能机器人","who":"智能机器人领域企业及项目，覆盖技术攻关、企业培育、平台建设、场景打造、人才引育、产业大赛举办及市州成效激励等重点领域。","materials":[],"window":"国省财政资金持续投入，基金依法加快设立，原文未设申报截止期。","where":"国省财政资金（统筹安排）；金芙蓉投资基金（未来产业子基金）。","tip":"基金目标规模100亿元，用于引导社会资本投入；财政资金投向技术攻关、企业培育、平台建设、场景打造、人才引育、产业大赛及市州成效激励。"},{"sectionNo":"二(十)续","headline":"产业链供应链贷、研发场景专项信贷，落实贷款贴息","who":"智能机器人领域相关企业；可申请产业链供应链贷、研发和场景专项信贷，并适用中小微企业贷款贴息、“潇湘财银贷”风险补偿、中小企业商业价值信用贷款风险补偿、科技型企业知识价值贷款风险补偿等政策。","materials":[],"window":"按国省支持政策执行，原文未设申报期限。","where":"“潇湘财银贷”风险补偿、中小企业商业价值信用贷款风险补偿、科技型企业知识价值贷款风险补偿等政策渠道。","tip":"贴息与风险补偿共同降低融资成本；原文未列具体银行和产品名单。"},{"sectionNo":"二(十)续二","headline":"政府性融资担保增信，支持机器人企业投保科技保险","who":"智能机器人领域企业及机器人项目；可由政府性融资担保机构提供融资增信，并通过融资租赁推广机器人产品。","materials":[],"window":"长期机制安排，原文未设申报期。","where":"政府性融资担保机构；融资租赁机构；科技保险承保机构（原文未列名称）。","tip":"担保与租赁机制并用；科技保险的保费补贴比例原文未写。"}],"sourceUrl":"https://www.hunan.gov.cn/szf/hnzb_18/2026/2026016/szfbgtwj_98720_88_1qqcuhkgvehermhkrrgnckumddvqssemgdhcscguemrbsvtvegftmrskmsnbgghgvhubedmdurhqfduvdrnusqsdnhrsmutefssdqpnuqtfbdkeqtd/202608/t20260831_34053628.html","sourceNote":"2026-11-21 取自《湖南省人民政府公报》2026年第16期原文页；页面为公报版式，未标注文号，已如实记录。 2026-11-21 收录：与官方页面逐句比对，命中 7/7 句（100%），关卡判定「verbatim」。 有效期依据：原文明示（自印发之日起施行、有效期5年）","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"hn-techfin-2022-53","title":"湖南省人民政府办公厅关于印发《湖南省财政支持企业科技创新若干政策措施》的通知","level":"provincial","region":"湖南省","issuer":"湖南省人民政府办公厅","documentNo":"湘政办发〔2022〕53号","publishedAt":"2022-10-11","effectiveAt":null,"expiresAt":"2027-10-10","status":"active","tags":["研发创新","营商环境","财政奖补"],"audience":["科技型中小企业","专精特新中小微企业","首台套等“五首”产品生产企业","高校院所"],"summary":"对“五首”产品给予售后或研发奖励，单个产品不超过100万元、成套产品不超过500万元；政府采购面向中小企业预留份额由30%以上提高至40%以上。","sections":[{"no":"(七)","title":"科研仪器向企业开放共享","text":"省属高校、科研院所、企业使用财政资金全额或主要出资购置单台套价值50万元以上的科学仪器设备、专用软件和实验装置，纳入省大型科学仪器设备共享服务平台，全部对社会开放共享。省财政按向企业用户开放共享服务收入的10%，对科学仪器设备管理单位予以奖补，单家单位补助额不超过200万元。"},{"no":"(八)","title":"“五首”产品奖励与保费补助","text":"每年发布《湖南省先进制造业首台套技术设备、首批次新材料、首版次高端软件、首轮次工程流片芯片、首套件基础电子元器件产品方向指南》，对指南范围内经评定达到国内先进或首创，且市场应用前景良好的首台套、首批次、首版次、首轮次、首套件产品给予售后或研发奖励，单个产品奖励不超过100万元，成套产品奖励不超过500万元。"},{"no":"(八)续","title":"创新保险保费补助","text":"对相关产品投保综合创新保险，按3%的投保费率上限，给予不超过保费50%的补助，单个产品补助不超过100万元，成套产品补助不超过500万元，售后或研发奖励与保费补助择一支持，不重复享受。"},{"no":"(九)","title":"政府采购支持创新产品","text":"将创新产品（服务）按规定纳入《湖南省首购产品（创新类）目录》，对入选的创新产品（服务）给予政府采购首购订购政策支持。降低供应商创新产品（服务）参与政府采购准入门槛，对符合条件的创新产品（服务）给予最高10%的价格扣除评审优惠。"},{"no":"(九)续","title":"中小企业预留份额","text":"加大政府采购支持科技型中小企业力度，将预留面向中小企业采购的份额由30%以上提高至40%以上，非预留项目给予小微企业10%—20%的价格扣除优惠（工程项目6%—10%）。对科技型中小微企业、“专精特新”中小微企业参加政府采购活动，免收保证金，或以保函、电子增信替代保证金。"},{"no":"(九)续二","title":"“政采贷”与预付款","text":"实施科技型中小微企业政府采购合同线上信用融资“政采贷”，科技型中小微企业凭政府采购中标通知书及政府采购合同，可直接向合作银行申请贷款，单笔贷款原则上不低于政府采购合同金额的70%。融资期限原则上与政府采购合同履约付款期限相匹配，贷款利率原则上不超过同期贷款市场报价利率（LPR）。"}],"interpretations":[{"sectionNo":"(七)","headline":"50万元以上科研仪器入省共享平台，全部对社会开放","who":"使用财政资金全额或主要出资购置单台套价值50万元以上科学仪器设备、专用软件和实验装置的省属高校、科研院所、企业（作为管理单位，可获开放共享奖补）；向其购买共享服务的企业用户。","materials":[],"window":"按向企业用户开放共享服务收入的10%计算奖补；原文未设申报期限。","where":"省大型科学仪器设备共享服务平台。","tip":"奖补给仪器管理单位而非使用企业；单家单位补助不超过200万元。"},{"sectionNo":"(八)","headline":"「五首」产品奖励：单个最高100万元，成套最高500万元","who":"产品列入当年《湖南省先进制造业首台套技术设备、首批次新材料、首版次高端软件、首轮次工程流片芯片、首套件基础电子元器件产品方向指南》，经评定达到国内先进或首创、市场应用前景良好的企业。","materials":[],"window":"每年发布产品方向指南后按年度组织评定；原文未列申报截止时间。","where":"按每年发布的《湖南省先进制造业首台套技术设备、首批次新材料、首版次高端软件、首轮次工程流片芯片、首套件基础电子元器件产品方向指南》申报（原文未写明具体受理部门）。","tip":"单个产品奖励不超过100万元；成套产品奖励不超过500万元。"},{"sectionNo":"(八)续","headline":"创新保险保费补助50%，单个产品最高100万元","who":"对相关产品投保综合创新保险的企业；投保费率上限3%，补助不超过保费的50%，单个产品补助不超过100万元、成套产品不超过500万元。","materials":[],"window":"按投保年度计算；售后或研发奖励与保费补助择一支持、不重复享受。","where":"向承保综合创新保险的机构投保后申请保费补助（原文未写明受理部门）。","tip":"保费补助与售后或研发奖励择一，不重复享受；投保费率上限3%。"},{"sectionNo":"(九)","headline":"创新产品入首购目录，政府采购评审最高10%价格扣除","who":"产品（服务）按规定纳入《湖南省首购产品（创新类）目录》的供应商；入选产品（服务）享受政府采购首购订购支持，符合条件的给予最高10%的价格扣除评审优惠。","materials":[],"window":"在政府采购项目评审环节执行；原文未列申报时间。","where":"按《湖南省首购产品（创新类）目录》参与政府采购（原文未写明具体系统名称）。","tip":"价格扣除是评审优惠、最高10%；前提是先入选首购产品（创新类）目录。"},{"sectionNo":"(九)续","headline":"中小企业政采预留份额提至40%以上，小微再享价格扣除","who":"科技型中小微企业、“专精特新”中小微企业；参加政府采购时预留份额由30%以上提高至40%以上，非预留项目小微企业享10%—20%价格扣除（工程项目6%—10%），并免收保证金。","materials":[],"window":"按政府采购项目执行，预留份额适用于面向中小企业采购的项目。","where":"政府采购项目（原文未写明具体平台）。","tip":"工程类价格扣除为6%—10%，低于货物服务类的10%—20%；保证金可免收或用保函、电子增信替代。"},{"sectionNo":"(九)续二","headline":"政采贷：凭中标通知书和合同贷款，单笔不低于合同额70%","who":"科技型中小微企业；凭政府采购中标通知书及政府采购合同向合作银行申请“政采贷”，单笔贷款原则上不低于合同金额的70%。","materials":["政府采购中标通知书","政府采购合同"],"window":"融资期限原则上与政府采购合同履约付款期限相匹配。","where":"合作银行（凭中标通知书及政府采购合同直接申请）。","tip":"单笔贷款不低于合同金额的70%；利率原则上不超过同期LPR。"}],"sourceUrl":"https://www.hunan.gov.cn/hnszf/xxgk/wjk/szfbgt/202210/t20221011_29050337.html","sourceNote":"2026-11-21 取自省门户「文件库—省政府办公厅文件」原文页；页面标题与文号已核对。有效期条款确实缺失，故按5年通则推算并标注来源局限。 2026-11-21 收录：与官方页面逐句比对，命中 10/10 句（100%），关卡判定「verbatim」。 有效期依据：原文未设期限；按行政规范性文件一般不超5年推算至2027-10-10（以网页发布日期起算），需以省司法厅清理结果复核","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"hn-wengang-kuogang-2026","title":"湖南省人力资源和社会保障厅 湖南省教育厅 湖南省财政厅 国家税务总局湖南省税务局关于失业保险支持企业稳岗扩岗的通知","level":"provincial","region":"湖南省","issuer":"湖南省人力资源和社会保障厅、湖南省教育厅、湖南省财政厅、国家税务总局湖南省税务局","documentNo":"湘人社规〔2026〕13号","publishedAt":"2026-07-24","effectiveAt":"2026-01-01","expiresAt":"2026-12-31","status":"expiring","tags":["就业补贴","社保补贴"],"audience":["参保企业","中小微企业","劳务派遣单位","社会组织"],"summary":"湖南省级失业保险稳岗扩岗政策，是各区县稳岗返还通知的依据文件：参保企业上年度足额缴纳失业保险费 12 个月且无历史欠费、裁员率符合规定的，可享受稳岗返还，大型企业按 30%、中小微企业按 60% 返还，社会组织、律师事务所、会计师事务所及以单位形式参保的个体工商户按 30% 返还；2026 年度招用三类人员并缴满 3 个月社保的，按每招用 1 人 1500 元发放一次性扩岗补助；技能提升补贴按初级 1000 元、中级 1500 元、高级 2000 元领取。政策执行期限为 2026 年 1 月 1 日至 12 月 31 日。","sections":[{"no":"一","title":"","text":"延续实施稳岗返还政策。参保企业上年度足额缴纳失业保险费12个月且无历史欠费,裁员率符合国家规定的,可以享受失业保险稳岗返还。严重失信单位不予享受稳岗返还。大型企业、中小微企业分别按30%、60%返还。社会组织(包括社会团体、基金会和民办非企业单位)、律师事务所、会计师事务所、以单位形式参保的个体工商户按30%返还。资金用途按国家规定执行。"},{"no":"二","title":"","text":"延续实施一次性扩岗补助政策。对2026年度按国家规定招用三类人员,并签订劳动合同、为其足额缴纳失业、工伤、职工养老保险费满3个月的企业和社会组织,按每招用1人1500元的标准发放一次性扩岗补助。其中,毕业年度未就业高校毕业生毕业时间不早于2026年1月1日,离校两年内未就业高校毕业生毕业时间不早于2024年1月1日,16-24岁登记失业青年是指企业招用时年龄为16-24岁且在我省办理失业登记人员。同一人员身份信息只能享受1次一次性扩岗补助,不得跨企业、跨年度、跨地区、跨资金渠道重复享受。"},{"no":"三","title":"","text":"优化技能提升补贴政策。符合国家规定的人员,取得列入我省急需紧缺职业(工种)目录、职业中类与所在企业行业类别一致、数字和绿色职业等级证书之一的,可在证书核发之日起12个月内申请技能提升补贴,逾期不予受理。初级(五级)、中级(四级)、高级(三级)职业资格证书或职业技能等级证书分别按1000元、1500元、2000元的标准领取。同一职业(工种)同一等级只能申请并享受1次,不得和职业培训补贴重复享受。已持有同一职业(工种)高等级证书或享受相应补贴的,不再享受低等级证书补贴。每人每年可享受1次补贴,对取得多项急需紧缺职业(工种)证书的,在此基础上增加2次补贴次数,共计不超过3次。自2026年1月1日起至本通知印发之日前,符合技能提升补贴申领条件且提出申领的人员,可以在通知印发后申领技能提升补贴。"},{"no":"四","title":"","text":"提升经办服务质效。优化稳岗返还“免申即享”经办模式,通过单位网厅向符合条件的企业主动推送政策信息和资金用途,通过媒体宣传、电话联系、短信通知等方式,提醒企业及时确认资金领取相关信息。对未注册单位网厅账号的单位,可采用线下提交确认函的方式办理。对没有对公账户的小微企业,经企业申请、确认及授权后,可将资金返还至当地税务部门协助提供的其缴纳社会保险费的账户。在2026年12月31日前仍未确认稳岗返还、一次性扩岗补助领取信息的单位,视为放弃享受。"},{"no":"五","title":"","text":"切实防范基金风险。各地要指导劳务派遣单位规范申请享受稳岗扩岗政策。对于未按规定拨付稳岗扩岗资金、逾期未提交拨付凭证的劳务派遣单位,经办机构应要求其退回未拨付部分,并取消下一年度申领资格。要加强技能提升补贴业务核查,重点核查批量持外省份同一评价机构所发证书申领技能提升补贴等情形,将问题线索及时移交有关部门。各地要提高政治站位,加强部门协作,迅速行动起来,加快推动政策落地见效。相关政策执行期限为2026年1月1日至12月31日。已有规定与本通知不一致的,按本通知执行。国家出台新规定的,从其规定。湖南省人力资源和社会保障厅湖南省教育厅湖南省财政厅国家税务总局湖南省税务局2026年7月24日"},{"no":"六","title":"落实要求","text":"各地要提高政治站位,加强部门协作,迅速行动起来,加快推动政策落地见效。相关政策执行期限为2026年1月1日至12月31日。已有规定与本通知不一致的,按本通知执行。国家出台新规定的,从其规定。"}],"interpretations":[{"sectionNo":"一","headline":"稳岗返还：大型企业返30%、中小微企业返60%","who":"上年度足额缴纳失业保险费12个月且无历史欠费、裁员率符合国家规定的参保企业；社会组织（社会团体、基金会、民办非企业单位）、律师事务所、会计师事务所、以单位形式参保的个体工商户按30%返还；严重失信单位不予享受。","materials":[],"window":"按上年度12个月缴费情况核定，资金用途按国家规定执行。","where":"失业保险参保地经办机构","tip":"大型企业、中小微企业分别按30%、60%返还；社会组织、律师事务所、会计师事务所及以单位形式参保的个体工商户按30%返还；严重失信单位不享受。"},{"sectionNo":"二","headline":"招用三类人员并缴社保满3个月，每招1人补1500元","who":"2026年度招用毕业年度未就业高校毕业生（毕业时间不早于2026年1月1日）、离校两年内未就业高校毕业生（毕业时间不早于2024年1月1日）、16-24岁登记失业青年（招用时年龄16-24岁且在我省办理失业登记），签订劳动合同并足额缴纳失业、工伤、职工养老保险费满3个月的企业和社会组织。","materials":[],"window":"2026年度招用，社保缴费满3个月后可申领；政策执行期限为2026年1月1日至12月31日。","where":"失业保险参保地经办机构","tip":"同一人员身份信息只能享受1次，不得跨企业、跨年度、跨地区、跨资金渠道重复享受。"},{"sectionNo":"三","headline":"技能提升补贴：初级1000、中级1500、高级2000元","who":"取得列入我省急需紧缺职业(工种)目录、职业中类与所在企业行业类别一致、数字和绿色职业等级证书之一的人员；须在证书核发之日起12个月内申请；每人每年可享受1次，取得多项急需紧缺职业(工种)证书的增加2次、共计不超过3次。","materials":[],"window":"证书核发之日起12个月内申请，逾期不予受理；2026年1月1日至通知印发前符合条件并提出申领的，可在通知印发后申领。","where":"技能提升补贴经办机构","tip":"同一职业(工种)同一等级只能申请并享受1次，不得和职业培训补贴重复享受；已持有同一职业(工种)高等级证书或享受相应补贴的，不再享受低等级证书补贴。"},{"sectionNo":"四","headline":"稳岗返还免申即享，2026年12月31日前未确认视为放弃","who":"符合稳岗返还、一次性扩岗补助条件的单位；未注册单位网厅账号的可线下提交确认函；没有对公账户的小微企业，经申请、确认及授权后可将资金返还至其缴纳社会保险费的账户。","materials":["确认函"],"window":"2026年12月31日前未确认稳岗返还、一次性扩岗补助领取信息的，视为放弃享受。","where":"单位网厅；未注册账号的单位可线下提交确认函；资金可返还至当地税务部门协助提供的缴纳社会保险费账户。","tip":"逾期未确认视为放弃享受；无对公账户的小微企业须经申请、确认及授权后才能变更收款账户。"},{"sectionNo":"五","headline":"劳务派遣单位未拨付稳岗资金，须退回并取消下一年度申领资格","who":"申请享受稳岗扩岗政策的劳务派遣单位；未按规定拨付稳岗扩岗资金、逾期未提交拨付凭证的，须退回未拨付部分并取消下一年度申领资格。","materials":["拨付凭证"],"window":"政策执行期限为2026年1月1日至12月31日；资格取消适用于下一年度。","where":"失业保险经办机构","tip":"批量持外省份同一评价机构所发证书申领技能提升补贴是重点核查情形，问题线索将移交有关部门。"}],"sourceUrl":"https://hunan.gov.cn/zqt/zcsd/202610/t20261016_34082523.html","derivedFrom":"official","sourceNote":"取自湖南省人民政府门户网站「政策速递」原文页（信息来源：湖南省人力资源和社会保障厅网站，发布时间 2026-10-16，发文日期 2026-07-24）。2026-11-24 按原文五条并文末落实要求段全文转录；比例与金额（30%、60%、1500 元、1000/1500/2000 元）与原文逐字核对。原文以半角逗号、括号排版，照录未改。 2026-11-24 收录：与官方页面逐句比对，命中 30/30 句（100%），关卡判定「verbatim」。 有效期依据：相关政策执行期限为2026年1月1日至12月31日","verified":false,"isSample":false,"numberStyle":"clause","bodyVerified":"verbatim","hunan":true},{"id":"hunan-2026-business-environment-measures","title":"湖南省人民政府办公厅关于印发《湖南省以问题为靶心优化营商环境若干举措》的通知","level":"provincial","region":"湖南省","issuer":"湖南省人民政府办公厅","documentNo":"湘政办发〔2026〕30号","publishedAt":"2026-06-04","effectiveAt":"","expiresAt":"2031-06-04","status":"active","tags":["营商环境","融资支持"],"audience":["民营企业","中小企业","个体工商户"],"summary":"湖南出台23条优化营商环境举措：政策找企与免申即享、限时清零拖欠民企账款、工商业电价降3—5分/度、入企检查一律扫码、涉企诉求统一归口受理。自印发之日起施行，有效期5年。","sections":[{"no":"一","title":"着力解决惠企政策获得感不强的问题","text":"一、着力解决惠企政策获得感不强的问题\n\n（一）推行“政策找企”主动服务。完善“政企通”涉企政策集中发布系统，分类归集、及时更新国家、省、市惠企政策，同步公开申报条件、审核标准、流程时限等要素，实时推送“湘易办”。加强政策拆解，完善政策标签体系，统一经营主体与惠企政策标注规则，开发“政策计算器”，集中归集涉企数据，为经营主体“精准画像”，点对点推送适配政策。通过“政企通”开展全链条产业政策梳理，依托“湘易办”上线“产业链政策地图”，实现产业政策查询“一站检索”。（责任单位：省工业和信息化厅、省数据局等省直相关单位，各市州人民政府。原则上第一位为牵头单位，以下均需各市州人民政府落实，不再列出）\n\n（二）打造惠企政策兑现“快车道”。出台惠企政策兑现平台管理办法，在省政务服务网建设“惠企政策直达快享专区”，实现申报入口“一键直达”。拓展“免申即享”“直达快享”政策覆盖面，提高兑现实效，可通过数据比对确认条件的兑现事项、普惠性奖补等，实现“无需申报、资金直达”。强化全流程穿透式监管，建立政策兑现超时预警督办机制。推行政策兑现“容缺受理+后置补正”模式，对非核心材料缺失的申报事项“先受理、后补正、快兑付”。（责任单位：省数据局、省财政厅、惠企政策制定单位）\n\n（三）健全惠企政策效能评估。建立惠企政策制定、宣讲、实施、反馈、优化闭环机制，每年开展一次惠企政策效能评估，持续清理、落实、新增一批涉企发展政策。探索运用人工智能大模型辅助开展政策效能分析。（责任单位：省发展改革委、省工商联、省司法厅、惠企政策制定单位）"},{"no":"二","title":"着力解决拖欠民企账款的问题","text":"二、着力解决拖欠民企账款的问题\n\n（四）限时清零存量拖欠。紧盯交通运输、农业、水利、住房城乡建设、教育、卫生健康等重点行业及国有平台公司拖欠民营企业账款问题，建立清偿台账。省级挂牌督办大额拖欠，市县分级包干，限期完成存量拖欠清零。用好地方政府专项债券、盘活存量资产等手段，鼓励通过债务置换、资产证券化等方式筹措清偿资金。将清欠成效纳入地方政府领导班子和领导干部综合考评、国有企业负责人经营业绩考核。（责任单位：省工业和信息化厅、省财政厅、省交通运输厅、省农业农村厅、省水利厅、省住房城乡建设厅、省教育厅、省卫生健康委、省委金融办、省委组织部、省国资委、各行业主管部门）\n\n（五）源头严防新增拖欠。严格执行“无预算不支出、无资金来源不开工”规定，按照工程进度及时足额拨付政府投资项目建设资金。建立账款支付临期、逾期、政务失信三级预警督办机制。推动行业协会等定期披露企业账期信息。对发现的存量台账以外的拖欠，甄别后按漏报瞒报或者新增拖欠处理，如属新增地方政府隐性债务，按有关规定严肃追责问责，由各地自行统筹资金资源限时化解。（责任单位：省财政厅、省工业和信息化厅、各行业主管部门）\n\n（六）加强诚信履约监管。依托现有系统建设“政府合同库”，规范合同线上备案，开放经营主体上传渠道，全量归集政府投资、招商引资、政府采购、工程建设、产业扶持等各类政府合同。聚焦政府负有给付义务的合同，建立全生命周期智慧监管制度。完善政府合同履约投诉管理运行机制。将经核实的机关、事业单位、国有企业违约失信情况纳入政务失信记录，结合审计项目加强监督。对失信主体，依规限制财政资金和扶持政策申请、项目申报、评先评优。（责任单位：省发展改革委、省财政厅、省商务厅、省住房城乡建设厅、省工业和信息化厅、省审计厅、省委组织部、省国资委、各行业主管部门）"},{"no":"三","title":"着力解决资源要素使用成本较高的问题","text":"三、着力解决资源要素使用成本较高的问题\n\n（七）降低企业用能成本。进一步优化电力资源配置，完善水电调度，争取省外优质低价电源，通过改革的手段降低工商业用户电价3—5分钱每千瓦时，每年降低全省企业用能成本30—50亿元。推动省内高速公路充电服务费下降0.1元每千瓦时，每年减少用户支出2000万元。从严核定天然气管道运输价格和配气价格，挖掘空间为用户降价减负。加快推行园区“转改直”，清理转供电环节不合理加价。实行园区通信配套设施与园区建设同步规划、施工、交付。（责任单位：省发展改革委、省能源局、国网湖南省电力公司、省交通运输厅、省高速集团、省市场监管局、省住房城乡建设厅、省通信管理局）\n\n（八）优化土地资源供给。全面实施工业项目“标准地”供应，分地区、分类采取差异化地价支持政策，切实降低企业用地成本。工业用地提高土地利用率和增加容积率的，不再增收土地价款。支持产业链关联企业联合拿地、联合建楼，简化办理工业物业产权分割及转让登记流程。按建筑面积超50%的建筑功能确定土地主导用途，制定土地混合开发和空间复合利用正面清单和管控要求，符合正面清单即视为符合详细规划。因政府原因或自然灾害等不可抗力导致开竣工违约的，可由市县政府集体研究后免除企业违约责任，本文件实施前已实际竣工验收的项目，可不再追究企业开竣工违约责任。（责任单位：省自然资源厅等省直相关部门）\n\n（九）提升金融服务质效。引导金融机构完善奖励政策和尽职免责、容错纠错制度，增加民营经济相关业务绩效考核权重，逐步提升民营经济贷款占比。加强“湘信贷”平台推广应用，订单平均受理时间压减至3个工作日以内，2026年、2027年撮合授信分别达1200亿元、1500亿元以上。完善小微企业融资协调工作机制，推广随借随还、无还本续贷等便利化产品，引导金融机构不盲目停贷、压贷、抽贷、断贷。建立省市县三级政府投资基金统筹管理机制，优化投资决策与投放，形成资金合力。健全政府性融资担保体系，加大保费补贴力度，引导降低担保费率和反担保要求。推行重点企业“金融特派员”制度，银行安排专员“一对一”提供融资辅导和服务。（责任单位：省委金融办、人民银行湖南省分行、湖南金融监管局、省发展改革委、省工业和信息化厅、省科技厅、省财政厅、省融资担保集团、各行业主管部门）\n\n（十）推进物流降本增效。加快推进“公转铁”“公转水”，培育铁水联运精品线路，扩大“一单制”“一箱制”试点。优化跨境多式联运顺势监管，支持内外贸同船运输。大力发展智慧物流，搭建全省物流信息平台，推行物流运价公开透明机制，推广共享物流、统仓统配等模式，推出物流类数据增信金融产品。稳妥推进全省高速公路限速优化调整，试点绿通车辆智能核验。推动航空口岸机场货站智慧化改造，优化场地分区及物流路线，符合条件进口货物实现24小时提离，出口货物实现“抵港直装”。（责任单位：省交通运输厅、省发展改革委、省财政厅、省商务厅、省高速集团、广铁集团长沙铁路物流中心、省港航水利集团、省机场管理集团、长沙海关）"},{"no":"四","title":"着力解决中介服务不规范的问题","text":"四、着力解决中介服务不规范的问题\n\n（十一）深化中介服务源头治理。各行业主管部门分领域编制中介服务事项清单，逐项明确中介服务内容、设定依据、服务时限、收费标准等要素，依托省网上中介服务超市集中发布并动态更新，清单之外一律不得强制或者变相要求申请人委托中介机构开展服务。进一步简化中介服务报告编制，突出必要信息和核心数据，按照简约、高效、便利原则，分级分类明确结果要件要求。规范各部门下属事业单位及主管的行业协会发展，结合事业单位改革，对依托行政权力、垄断中介服务的单位，予以撤并整合。（责任单位：省委社会工作部、省数据局、省委编办、省民政厅、各行业主管部门）\n\n（十二）加强中介服务跟踪管理。全面推广省网上中介服务超市，实现供需对接全程透明。开展中介服务质量跟踪评价，推行“好差评”制度，评价结果与入驻资格、业务承接挂钩。加强中介服务机构监管，建立中介机构不良行为记录库，将失信中介机构名单推送至“信用湖南”一体化平台，依法依规实施联合惩戒。严格规范中介服务收费，严查超标准收费、捆绑收费、变相牟利行为。（责任单位：省数据局、省发展改革委、省市场监管局、各行业主管部门）\n\n（十三）开展中介服务专项整治。聚焦投资项目审批、专项评估评价、检验检测、法律服务、信贷服务、招工服务等重点领域，分类开展中介服务专项整治，纳入群众身边不正之风和腐败问题集中整治重点。严格落实禁止在职、退休公职人员在中介机构兼职取酬的纪律规定，针对性开展审计监督。建立中介违规行为举报绿色通道，对查实的违规中介，清出中介超市，依法依规追责问责。（责任单位：省纪委监委、省委组织部、省委社会工作部、省民政厅、省审计厅、省数据局、各行业主管部门）"},{"no":"五","title":"着力解决涉企执法检查突出问题","text":"五、着力解决涉企执法检查突出问题\n\n（十四）全面深化“扫码入企”。深化“扫码入企、联码督查”，实现亮码入企、全程留痕、闭环监督。公安、税务等部门全面接入扫码入企系统。除法律法规另有规定外，所有入企行政检查、调研、服务等行为一律扫码登记，被检查对象可扫码核验执法资质、检查权限，有异议可一键反馈。建立企业“拒绝未扫码检查”保护机制，严肃查处未按规定扫码、以规避扫码为由要求企业前往相关单位现场办理业务等行为。（责任单位：省司法厅、省公安厅、省税务局、各行政执法部门）\n\n（十五）规范行政执法自由裁量权。依托全省行政执法和行政执法监督一体化平台，建立全省统一的行政处罚裁量权基准数据库、涉企执法案例库，通过案例公开、大数据比较、社会监督，压缩自由裁量空间。（责任单位：省司法厅、各行政执法部门）\n\n（十六）实施分级分类精准监管。健全“信用+风险”监管体系，建立“无感监测”对象清单和“无事不扰”事项清单，对风险低、信用好的企业优先采用非现场检查。动态更新轻微违法行为依法免罚、轻罚事项清单，扩大柔性执法适用范围。对违法行为轻微并及时改正、没有造成危害后果的，推广行政执法“观察期”制度。（责任单位：省司法厅、省市场监管局、省发展改革委、各行政执法部门）"},{"no":"六","title":"着力解决妨碍民营企业公平参与市场竞争的问题","text":"六、着力解决妨碍民营企业公平参与市场竞争的问题\n\n（十七）维护公平竞争秩序。全面开展市场准入效能评估，保障各类经营主体平等进入。定期发布基础设施、公共服务等领域适合民间资本参与的项目，不得设置隐性门槛。持续优化“机器管招投标”，重点规范复评管理、投诉处理等行政监督环节，建立全链条、穿透式数智化监管体系。深化招标投标领域突出问题整治，重点打击、公开曝光围标串标、买标卖标、转包、违法分包等损害市场秩序的违法违规行为。鼓励招标人对信用较好的企业免除投标担保。深化政府采购领域违法违规行为专项整治。（责任单位：省发展改革委、省市场监管局、省财政厅、省公共资源交易中心、各行业主管部门）\n\n（十八）推动市场高效畅通。完善企业跨区域迁移机制，实现只向迁入地申请一次。优化企业注销流程，推动长期未经营或停止经营企业和个体工商户市场退出。严肃查处对企业跨区域经营、迁移或者注销设置障碍等行为。推动行业部门、国有企业主动开放应用场景，建立面向民营企业常态化开放机制。拓展开放平台，支持有条件的市州、园区按照规定程序在重点国别地区设立联络代表处。（责任单位：省市场监管局、省发展改革委、省数据局、省税务局、省人力资源社会保障厅、省医保局、省直住房资金管理中心、省商务厅、省国资委、各行业主管部门）\n\n（十九）深化重点领域整治。建立恶意举报异常名录库，依法打击恶意索赔、敲诈勒索、缠诉闹访等违法行为。重拳整治平台经济乱象，重点规制利用数据和算法、技术、资本优势、平台规则实施的算法共谋、大数据杀熟、“二选一”限定交易、利用规则封禁屏蔽、附加不合理交易条件等垄断行为。严厉打击平台经营者利用市场支配地位向平台内经营者收取不公平高额费用、低于成本销售排挤竞争对手等行为。（责任单位：省市场监管局、省委社会工作部、省高级人民法院、省人民检察院、省发展改革委、省公安厅、各行业主管部门）"},{"no":"七","title":"着力解决民营企业“投诉无门”的问题","text":"七、着力解决民营企业“投诉无门”的问题\n\n（二十）完善诉求办理机制。发挥省民营经济发展局（省营商环境建设局）统一归口受理涉企诉求职能，迭代升级省营商环境诉求办理平台，优化诉求办理全链条闭环管理和服务体系。对深层次营商环境疑难问题，建立“法治会诊”机制，组织政法、公安、检察院、法院、司法行政、纪检、审计部门及行业专家等联合会诊解难。（责任单位：省发展改革委、省委政法委、省公安厅、省人民检察院、省高级人民法院、省司法厅、省纪委监委、省审计厅、各行业主管部门）\n\n（二十一）优化涉企法律服务。完善法律服务对接机制，提供送法进企、法治体检、纠纷调解等服务。加强涉外法律服务机构培育，建强涉外法律服务人才专家库，为出海企业提供公益法律服务。加强一流公证机构和公证领军人才培育，优化公证便企利企服务。依托综治中心加强诉讼、调解、仲裁等对接，提供一站式商事纠纷多元化解服务。（责任单位：省司法厅等省直相关部门）"},{"no":"八","title":"着力解决政商关系“亲清”不分的问题","text":"八、着力解决政商关系“亲清”不分的问题\n\n（二十二）规范政商交往行为。落实省纪委监委《关于规范政商交往推动构建亲清新型政商关系的意见》，紧扣政商交往突出问题，聚焦企业需求和干部顾虑，推动构建亲而有度、清而有为的亲清新型政商关系。（责任单位：省纪委监委、省委统战部、省工商联）\n\n（二十三）激发干事创业活力。选取不同类型民营企业设立营商环境亲清监测点，动态收集企业意见建议。（责任单位：省委统战部、省工商联）落实“三个区分开来”，区别对待在推动企业发展中出现的失误错误，激励党政机关及公职人员主动担当作为。（责任单位：省纪委监委）对服务企业成效突出的公职人员，在评优评先、选拔任用中予以倾斜。（责任单位：省委组织部）\n\n各级各部门要压实责任，强化协同，细化举措，力戒形式主义，确保落地见效。省发展改革委要加强统筹协调、跟踪督导，提炼推广经验，通报问题不足，重要情况及时向省委、省人民政府请示报告，推动全省营商环境持续优化提升。\n\n本措施自印发之日起施行，有效期5年。"}],"interpretations":[{"sectionNo":"一","headline":"政策主动找企业，符合条件可「免申即享」","who":"在湖南经营的各类经营主体，重点是需要申报惠企政策的企业；通过「政企通」「湘易办」获取政策与申报入口。","materials":[],"window":"持续推进；惠企政策效能评估每年开展一次。","where":"「政企通」涉企政策集中发布系统与「湘易办」平台；省政务服务网「惠企政策直达快享专区」。","tip":"可通过数据比对确认条件的兑现事项、普惠性奖补，目标是「无需申报、资金直达」；非核心材料缺失时可先受理后补正。"},{"sectionNo":"二","headline":"拖欠民企账款要限期清零，新增拖欠严查","who":"被机关、事业单位、国有企业拖欠账款的民营企业，重点行业包括交通运输、农业、水利、住建、教育、卫生健康及国有平台公司。","materials":["账款凭证与合同（用于主张清偿）"],"window":"限期完成存量拖欠清零；建立台账后按督办节点推进。","where":"省级挂牌督办大额拖欠、市县分级包干；可通过政府合同履约投诉机制反映。","tip":"「无预算不支出、无资金来源不开工」是源头约束；被核实的违约失信会进政务失信记录，并影响其财政资金与项目申报。"},{"sectionNo":"三","headline":"工商业电价降3—5分/度，工业用地不再因提容增收地价","who":"省内工商业用电企业、工业用地企业，以及有融资需求的民营企业。","materials":[],"window":"2026—2027年（金融部分明确两个年度的撮合授信目标）。","where":"电价由省发改委、省能源局、国网湖南电力落实；用地找自然资源部门；融资通过「湘信贷」平台。","tip":"工业用地提高利用率、增加容积率不再增收土地价款；因政府原因或不可抗力导致的开竣工违约，可申请免除违约责任。"},{"sectionNo":"四","headline":"中介清单之外不得强制委托，收费要透明","who":"需要办理审批、评估、检测、法律、信贷、招工等中介服务的经营主体。","materials":[],"window":"持续推进；专项整治按部署分批开展。","where":"省网上中介服务超市（清单发布、供需对接、「好差评」）。","tip":"清单之外一律不得强制或变相要求委托中介；超标准收费、捆绑收费、变相牟利可举报，失信中介会被联合惩戒。"},{"sectionNo":"五","headline":"入企检查一律扫码，轻微违法多用免罚与观察期","who":"省内接受行政检查、调研、服务的各类企业。","materials":[],"window":"持续执行。","where":"扫码入企系统（公安、税务等部门已接入）；对未扫码检查可一键反馈。","tip":"企业有权拒绝未扫码检查；风险低、信用好的企业优先非现场检查；违法行为轻微并及时改正、没有造成危害后果的，可适用「观察期」。"},{"sectionNo":"六","headline":"招投标不得设隐性门槛，信用好可免投标担保","who":"参与招投标、政府采购、跨区域迁移或注销的各类经营主体，重点是民营企业。","materials":[],"window":"持续执行。","where":"省公共资源交易中心（机器管招投标）、市场监管部门（迁移与注销）。","tip":"企业跨区域迁移只需向迁入地申请一次；招标人可对信用较好的企业免除投标担保；对设置迁移、注销障碍的行为会被查处。"},{"sectionNo":"七","headline":"涉企诉求统一归口，疑难问题「法治会诊」","who":"在湖南经营、遇到政策兑现或执法争议的民营企业。","materials":[],"window":"持续执行。","where":"省民营经济发展局（省营商环境建设局）统一归口受理；省营商环境诉求办理平台。","tip":"深层次疑难问题可走「法治会诊」，由政法、公安、检察、法院、司法行政、纪检、审计及专家联合会诊。"},{"sectionNo":"八","headline":"政商交往划边界，干事创业有容错","who":"与政府部门打交道的民营企业；以及服务企业的公职人员（激励与容错条款）。","materials":[],"window":"持续执行。","where":"省纪委监委《关于规范政商交往推动构建亲清新型政商关系的意见》框架下；营商环境亲清监测点。","tip":"落实「三个区分开来」，对推动企业发展中的失误错误区别对待；服务企业成效突出的公职人员在评优评先、选拔任用中倾斜。"}],"sourceUrl":"https://kjt.hunan.gov.cn/kjt/xxgk/zcfg/sbgfxwj/202606/t20260623_34009868.html","sourceNote":"2026-11-02 取自湖南省科技厅政策法规栏目转载原文页（省政府办公厅文件，网页发布 2026-06-04）；原文「本措施自印发之日起施行，有效期5年」，按网页发布日期推算有效期至 2031-06-04；省科技厅为转载栏目，正式文本以省政府门户发布为准。；2026-11-08 核对：页面发布日期 2026-06-04","verified":true,"isSample":false,"hunan":true,"numberStyle":"item","bodyVerified":"verbatim"},{"id":"hunan-2026-wage-guideline","title":"湖南省人力资源和社会保障厅关于发布湖南省2026年企业工资指导线的通知","level":"provincial","region":"湖南省","issuer":"湖南省人力资源和社会保障厅","documentNo":"湘人社规〔2026〕18号","publishedAt":"2026-01-01","effectiveAt":"2026-01-01","expiresAt":"2026-12-31","status":"expiring","tags":["就业补贴"],"audience":["各类企业","国有企业","非国有企业"],"summary":"2026年湖南企业工资指导线：上线8%、基准线6%、下线2%，适用于城镇各类企业；效益好的可往上线谈，效益差的可零增长甚至负增长，但不得低于当地最低工资。","sections":[{"no":"一","title":"2026年我省工资指导线","text":"一、2026年我省工资指导线\n\n(一)2026年我省企业工资指导线上线为8%。\n\n(二)2026年我省企业工资指导线基准线为6%。\n\n(三)2026年我省企业工资指导线下线为2%。"},{"no":"二","title":"工资指导线执行范围","text":"二、工资指导线执行范围\n\n2026年工资指导线适用于我省城镇各类企业和按照企业经营方式进行经营性活动的各类机构、团体。\n\n(一)对经济效益比上年有较大增长幅度或扭亏成效显著的企业,可在工资指导线的基准线和上线区间内协商确定工资增长幅度。\n\n(二)现有工资水平已超过所在地在岗职工平均工资2倍的企业和经济效益比上年增长幅度较小的企业,可在工资指导线的下线与基准线的区间内协商确定工资增长幅度。\n\n(三)当年效益情况与往年持平或略有下降的企业,可结合自身实际参照下线确定工资增长幅度。\n\n(四)对于经营亏损、职工工资发放出现困难的企业,经与工会或职工代表协商,工资可以零增长或负增长,但支付给劳动者的工资不得低于当地最低工资标准。"},{"no":"三","title":"工作要求","text":"三、工作要求\n\n(一)全省各类企业应建立健全工资决定机制和正常增长机制,根据本企业经济效益和劳动生产率的具体情况,协商确定2026年度工资增长比例,合理安排工资增长。着力提高工资水平偏低、工资增长缓慢的普通职工,特别是生产一线及技术工人岗位人员工资水平,使生产一线职工工资增长幅度不低于职工平均工资增长幅度。\n\n1.国有企业(含国有独资、控股和实际控制的企业,下同)应按照国有企业工资决定机制改革的有关规定编制工资总额预算方案,在工资监管部门核准或备案的工资总额预算内,通过与工会开展工资集体协商,合理确定本企业2026年度的职工工资增长幅度和工资水平。\n\n2.非国有企业应依据工资指导线和劳动报酬增长与劳动生产率提高同步的要求,积极主动地与工会或职工协商代表开展工资集体协商,合理确定本企业2026年度的职工工资增长幅度和工资水平。\n\n(二)各级工会组织要加强对企业工会工作的指导,与企业共同协商工资分配制度、分配形式及工资调整幅度,促进企业发展与维护职工权益有机结合,合理提高职工工资水平。\n\n(三)各级人力资源社会保障行政部门要按规定做好国有企业工资总额执行结果的备案工作,加大对工资指导线和《湖南省企业工资集体协商条例》的宣传力度,加强对企业执行情况的监督检查,进一步发挥工资指导线的宏观调控作用,切实提升工资指导线的实施效果和社会影响力。\n\n本通知自2026年1月1日起施行,有效期一年。\n\n政策解读:湖南省2026年企业工资指导线政策解读\n\n湖南省人力资源和社会保障厅\n\n2026年9月28日"}],"interpretations":[{"sectionNo":"一","headline":"2026年工资增长：上限8%、基准6%、下限2%","who":"湖南省内城镇各类企业在与工会协商年度工资增长幅度时参照（原文先给出三条线，再在第二条明确适用范围）。","materials":[],"window":"2026年度工资增长协商时使用。","where":"由企业与工会或职工代表协商确定，报人社部门备案（国企工资总额另有核准/备案程序）。","tip":"三条线是协商区间不是强制标准；效益下滑时按下限甚至零增长谈，别越过当地最低工资。"},{"sectionNo":"二","headline":"四类企业分别对应不同协商区间","who":"2026年工资指导线适用于我省城镇各类企业和按照企业经营方式进行经营性活动的各类机构、团体。效益大幅增长或扭亏显著的企业，在基准线与上线之间谈；工资已超过当地在岗职工平均工资2倍、或增幅较小的企业，在下线与基准线之间谈；效益持平或略降的按下线；经营亏损、发薪困难的经协商可零增长或负增长。","materials":[],"window":"2026年度工资集体协商期间。","where":"企业内部工资集体协商；国企另需在工资总额预算内核准备案。","tip":"即使零增长或负增长，支付给劳动者的工资也不得低于当地最低工资标准；超额发放的「超2倍」企业不能往上限方向谈。"},{"sectionNo":"三","headline":"企业要建工资协商机制，一线职工增幅不低于平均","who":"全省各类企业；国有企业需编制工资总额预算方案并在核准或备案的预算内协商，非国有企业依据工资指导线开展集体协商。","materials":["工资总额预算方案（国有企业）","工资集体协商相关材料"],"window":"2026年度；本通知自2026年1月1日起施行，有效期一年。","where":"企业工会/职工代表协商；国有企业报工资监管部门核准或备案；人社部门负责备案与监督检查。","tip":"文件特别要求提高一线及技术工人工资，使生产一线职工工资增长幅度不低于职工平均工资增长幅度。"}],"sourceUrl":"https://rst.hunan.gov.cn/rst/xxgk/zcfg/zxzc/202610/t20261015_34081933.html","sourceNote":"2026-11-02 取自湖南省人社厅「厅发规范性文件」原文页（湘人社规〔2026〕18号，网页发布 2026-10-15，落款 2026-09-28）；原文「自2026年1月1日起施行，有效期一年」，据此推算有效期至 2026-12-31。；2026-11-08 核对：页面发布日期 2026-10-15","verified":true,"isSample":false,"hunan":true,"numberStyle":"item","bodyVerified":"verbatim"},{"id":"hunan-ai-zhifuwanqi-fund-2026","title":"关于组织开展2026年湖南省“人工智能+”“智赋万企”行动相关项目支持资金申报工作的通知","documentNo":"湘工信财务〔2026〕160号","level":"provincial","region":"湖南省","issuer":"湖南省工业和信息化厅、湖南省财政厅","publishedAt":"2026-05-06","effectiveAt":"","expiresAt":"","status":"active","tags":["数字化转型"],"audience":["制造业企业","中小企业"],"summary":"2026年湖南省“人工智能+”“智赋万企”行动相关项目支持资金申报通知，对2025年9月3日实施方案发布以来获评的人工智能创新应用、工业互联网平台、数字化转型促进中心、高标准数字园区、国家级数字化转型标杆等事项给予奖励，网上申报截止2026年6月5日。","sections":[{"no":"一","title":"支持方向","text":"对2025年9月3日《实施方案》发布以来，符合条件的以下事项进行奖励：\n\n（一）支持人工智能创新应用。优秀算法产品、数据产品；通过国家网信办备案的生成式人工智能大模型、国家人工智能“揭榜挂帅”优胜单位；湖南省级人工智能终端产品、人工智能大模型、人工智能赋能新型工业化典型应用场景以及“人工智能+      ”十大示范场景（企业主体）。\n\n（二）支持工业互联网创新发展。国家级“双跨”工业互联网平台、湖南省工业互联网平台、湖南省“    5G+工业互联网”标杆工厂、工业互联网标识解析二级节点。\n\n（三）支持建设制造业数字化转型促进中心。国家级、湖南省制造业数字化转型促进中心。\n\n（四）支持建设高标准数字园区。国家级、湖南省高标准数字园区。\n\n（五）支持争创国家数字化智能化转型标杆。实体经济和数字经济深度融合、制造业数字化转型、人工智能赋能新型工业化（人工智能）、物联网赋能行业发展等国家级数字化典型案例；“数据要素×工业制造”等国家级赛事奖项；卓越级智能工厂；通过国家智能制造系统解决方案“揭榜挂帅”验收项目。"},{"no":"二","title":"申报条件","text":"（一）申报单位。申报单位应具有独立法人资格，或为独立核算并纳入最小法人统计的分公司或子公司，具有健全的财务管理机构和制度，依法纳税，能够严格落实资金管理要求，积极配合做好调查、调度、绩效评价等工作，信用状况良好。\n\n（二）申报项目。申报项目符合国家产业政策和有关法律法规，属于前述支持方向，经济社会效益显著，示范带动作用强。同一申报主体同一年度原则上申报不超过两个项目。\n\n（三）申报要求。详见《项目申报指南》（附件1）。\n\n（四）不符合申报条件的主要情况：\n\n1.违反安全生产、环境保护等规定，使用国家明令禁止设备进行建设的项目；\n\n2.项目单位在绩效评价中未获得通过，或在项目调度、经济运行调度等工作中不配合，造成不良影响的；\n\n3.存在被列入信用湖南网失信名单或近两年发生重大数据安全事件等其他严重问题的单位；\n\n4.存在税务、环保、安全等领域重大违法违规记录的单位；\n\n5.国家和省级文件明确不得重复申报财政资金的各类项目。"},{"no":"三","title":"申报程序","text":"（一）项目申报\n\n项目申报资料采取网上报送方式，不受理纸质申报资料。申报单位对照《项目申报指南》和申报材料模板（附件3）编制项目申请报告，通过湖南省工业和信息化厅项目管理系统（https://222.244.103.250:8181/pmp/a/login#）提交，各市州、县（市、区）工信部门及时在系统中审核上报。相关附件应全部插入到项目申请报告中一并上传，不接受多个文件上传。盖章页及相关证明材料须为原件扫描件，勿使用拍照方式。提交的所有项目资料应是可公开的，不得涉及国家秘密。\n\n（二）文件报送\n\n1.市州项目。由市州工业和信息化局负责组织项目的申报、初审等工作，市州财政局配合开展相关工作，市州工业和信息化局、财政局联合行文推荐、上报至省工业和信息化厅。财政省直管县（市）项目。由县（市）工业和信息化部门、财政部门参照市州项目的组织方式，联合行文推荐、上报至省工业和信息化厅，同时抄报所在市州工业和信息化局、财政局。中央在湘单位和省属单位项目。按照属地管理原则，通过所在地进行申报。\n\n2.各市州、财政省直管县（市）工业和信息化部门将推荐文件和《项目申报汇总表》（附件2）扫描上传至省工业和信息化厅项目管理系统，并报送纸质文件一式2份（只需红头文件和项目汇总表，不需要项目资料）至省工业和信息化厅人工智能与数字产业处。项目汇总表可编辑电子版发送到电子邮箱（hngxtrgznc@163.com）。\n\n3.网上申报及文件报送截止时间为2026年6月5日（星期五）24:00（项目管理系统将在申报截止时间自动关闭）。"},{"no":"四","title":"其他事项","text":"1.项目申报业务问题请向当地工业和信息化部门咨询（申报单位请注意所在地申报截止时间要求），或联系《项目申报指南》中各方向对应工作人员。项目管理系统操作问题咨询请联系：0731-88955465。\n\n2.各市州、财政省直管县（市）工业和信息化部门、财政部门须对申报项目资料及要件齐全性等认真把关，坚决杜绝虚假申报，不得推荐不符合条件的申报项目。对审核把关不严的地区，将予以通报批评。\n\n3.项目资料是资金安排、监督管理、绩效评价等工作的重要依据，申报单位对提交材料及附件的真实性、合法性、完整性负责，因申报材料不完善、不清晰、不正确、不符合要求等问题导致不能获得支持资金的，相关责任自负。对材料造假、使用同一凭证多头重复申报中央和省级财政补助资金的，一经查实即取消申报资格，三年内不得申报省工业和信息化厅项目资金。对获得资金支持却不配合全程监管等工作的，视情况收回已安排的资金。\n\n4.项目申报不收取任何费用。省工业和信息化厅、省财政厅未委托任何单位或个人为项目单位代理申报事宜，请相关单位自主申报，并按程序报送。如有任何中介机构或个人假借机关单位或工作人员名义进行推销或收取费用的，请向当地相关部门举报，谨防上当受骗。省工业和信息化厅举报受理电话：0731-88955596。\n\n附件：\n\n1.项目申报指南\n\n2.项目申报汇总表\n\n3.各支持方向申报材料模板（见挂网附件）\n\n湖南省工业和信息化厅\n\n湖南省财政厅\n\n2026年4月28日\n\n收藏\n\n国家部委网站\n\n发展改革委\n\n外交部\n\n卫生健康委\n\n国防部\n\n教育部\n\n科技部\n\n工业和信息化部\n\n公安部\n\n中央纪委国家监委\n\n民政部\n\n司法部\n\n财政部\n\n人力资源和社会保障部\n\n自然资源部\n\n生态环境部\n\n住房和城乡建设部\n\n交通运输部\n\n水利部\n\n农业农村部\n\n商务部\n\n应急管理部\n\n退役军人事务部\n\n文化和旅游部\n\n人民银行\n\n审计署\n\n海关总署\n\n税务总局\n\n市场监督管理总局\n\n广电总局\n\n民航局\n\n体育总局\n\n各省工信厅网站\n\n北京市经信局\n\n天津市工信局\n\n河北省工信厅\n\n辽宁省工信厅\n\n内蒙古工信厅\n\n黑龙江省工信厅\n\n浙江省经信厅\n\n安徽省经信厅\n\n河南省工信厅\n\n广东省工信厅\n\n湖北省经信厅\n\n重庆市经信委\n\n四川省经信厅\n\n贵州省工信厅\n\n云南省工信厅\n\n甘肃省工信厅\n\n陕西省工信厅\n\n宁夏工信厅\n\n青海省工信厅\n\n山西省工信厅\n\n吉林省工信厅\n\n上海市经信委\n\n江苏省工信厅\n\n福建省工信厅\n\n江西省工信厅\n\n山东省工信厅\n\n海南省工信厅\n\n广西工信厅\n\n新疆工信厅\n\n西藏经信厅\n\n各市州工信局网站\n\n长沙市工信局\n\n衡阳市工信局\n\n株洲市工信局\n\n湘潭市工信局\n\n邵阳市工信局\n\n岳阳市工信局\n\n常德市工信局\n\n张家界市工信局\n\n益阳市工信局\n\n郴州市工信局\n\n永州市工信局\n\n怀化市工信局\n\n娄底市工信局\n\n湘西州工信局\n\n直属机构\n\n湖南兵器工业高级技工学校\n\n中南工业学校\n\n湖南省汽车技师学院\n\n湖南省散装水泥和墙体材料改革办公室\n\n湖南无线电管理\n\n湖南省工业通信业节能监察中心\n\n湖南省电子信息产业研究院\n\n湖南省计算机软件资格考试办公室\n\n湖南省国防科技工业局技术开发中心\n\n网站地图"}],"interpretations":[{"sectionNo":"一","headline":"人工智能、工业互联网、数字园区等五类事项可获奖励","who":"符合支持方向的湖南企业：人工智能创新应用（优秀算法/数据产品、通过国家网信办备案的生成式大模型、省级人工智能终端与大模型、典型应用场景、「人工智能+」十大示范场景）；工业互联网（国家级双跨平台、省级平台、5G+工业互联网标杆工厂、标识解析二级节点）；制造业数字化转型促进中心；高标准数字园区；国家级数字化智能化转型标杆。","materials":[],"window":"事项须发生在 2025年9月3日《实施方案》发布之后。","where":"省工信厅项目管理系统申报，逐级由市州/县市区工信部门审核上报。","tip":"同一申报主体同一年度原则上最多申报两个项目；奖励只覆盖《实施方案》发布后符合条件的事项。"},{"sectionNo":"二","headline":"申报单位要有独立法人资格，信用良好","who":"具有独立法人资格，或为独立核算并纳入最小法人统计的分公司、子公司；财务制度健全、依法纳税、信用状况良好。","materials":[],"window":"网上申报及文件报送截止 2026年6月5日（星期五）24:00，系统自动关闭。","where":"市州工信局组织申报初审；财政省直管县（市）由县市工信、财政部门联合行文上报。","tip":"被列入信用湖南网失信名单、近两年有重大数据安全事件、或存在税务环保安全重大违法违规记录的，不予支持。"},{"sectionNo":"三","headline":"全程网上报送，附件要插进申请报告一起上传","who":"申报单位；中央在湘单位和省属单位按属地原则通过所在地申报。","materials":["项目申请报告（按《项目申报指南》和附件3模板编制）","盖章页及证明材料须为原件扫描件","《项目申报汇总表》（附件2，由市州/县市工信部门报）"],"window":"2026年6月5日24:00 前完成网上申报与文件报送。","where":"湖南省工业和信息化厅项目管理系统。","tip":"不受理纸质申报资料；不接受多个文件上传，所有附件要插进申请报告；证明材料不能用手机拍照，必须是原件扫描。"},{"sectionNo":"四","headline":"项目申报不收费，材料造假三年内不得申报省工信厅资金","who":"申报本通知所列项目的申报单位；须对提交材料及附件的真实性、合法性、完整性负责，并按程序自主申报，不得委托中介机构或个人代理。","materials":["项目申报汇总表","各支持方向申报材料模板（见挂网附件）"],"window":"按所在地申报截止时间要求报送；原文未列具体申报日期。","where":"当地工业和信息化部门；项目管理系统；省工业和信息化厅、省财政厅。","tip":"材料造假或使用同一凭证多头重复申报中央和省级财政补助资金的，一经查实即取消申报资格，三年内不得申报省工业和信息化厅项目资金；获得资金后不配合全程监管的，视情况收回已安排的资金。"}],"sourceUrl":"https://gxt.hunan.gov.cn/gxt/xxgk_71033/tzgg/202605/t20260506_33970529.html","sourceNote":"湖南省工信厅官网公开正文，2026年度一次性奖励项目申报通知。；2026-11-08 核对：页面发布日期 2026-05-06；2026-11-09 条文按官方原文重切（4 条，自查召回 100%）","verified":true,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"hunan-equipment-upgrade-financing-2026","title":"关于组织开展第三批湖南省工业企业设备更新和技术改造项目融资补贴申报工作的通知","documentNo":"","level":"provincial","region":"湖南省","issuer":"湖南省工业和信息化厅、湖南省财政厅、湖南省地方金融管理局、中国人民银行湖南省分行","publishedAt":"2026-09-30","effectiveAt":"","expiresAt":"","status":"active","tags":["融资支持"],"audience":["工业企业","制造业企业"],"summary":"第三批湖南省工业企业设备更新和技术改造项目融资补贴申报通知，对符合条件的工业企业设备更新技改项目给予贷款贴息或融资租赁补贴，项目须在湖南制造强省项目库入库，入库及系统申报截止2026年10月30日。","sections":[{"no":"一","title":"支持方向","text":"工业企业聚焦制造业智能化、绿色化、融合化发展和本质安全提升，以提升质量、增加品种、塑造品牌、节约成本、降低消耗、增强安全为目的，采取先进适用的新设备，对现有生产设施、生产工艺条件和辅助设施进行改造。"},{"no":"二","title":"申报基本条件","text":"1.申报单位一般应为具有独立法人资格，具有健全的财务管理机构和制度，能够严格落实资金管理要求，积极配合做好调查、调度、绩效评价等工作，诚信经营，依法纳税，无不良信用记录的工业企业。\n\n2.项目应为在建项目或在2026年3月13日之后完工的项目，符合国家产业政策和有关法律法规，符合先进设备更新、数字化智能化改造、节能降碳改造、本质安全改造等设备更新和技术改造方向，预期经济社会效益较好，具有较强的示范带动作用。\n\n3.项目应在湖南制造强省项目库系统入库管理，接受常态化调度。由金融机构向项目提供了贷款或融资租赁，并于2024年3月7日（含）后完成贷款合同或融资租赁合同签订。\n\n4.申请贷款贴息的项目应满足以下条件：\n\n（1）项目总投资应在200万元及以上，贷款期限一年期（含）以上，贷款资金应于项目申报日前完成发放；项目贷款总额不得高于项目总投资；（2）项目设备计划总投资（包括设备采购，配套厂房及实验室等建设工程，以及软件和数据服务、安装费用等）占项目贷款总额的比例应不低于50%；（3）设备购置时间应在2024年3月7日（含）之后，购置时间早于此日期的设备不得计入设备投资之内；（4）项目已完成结算的设备投资额占设备计划总投资额的比重不低于30%；（5）贷款需全部用于项目建设，不得用于购买原材料、日常经营周转、发放员工工资等；（6）贷款合同签订时间不得晚于项目完工时间；（7）已获得中央或省级贷款贴息融资补贴的贷款（2024年3月7日（含）以来）不得再次用于申报此次融资补贴。\n\n5.申请融资租赁补贴的项目，已结算的设备投资和单笔设备融资租赁合同均应在2024年3月7日（含）之后，且设备金额均不低于100万元。\n\n6.同一项目只能享受设备更新贷款中央财政贴息、省级贷款贴息、融资租赁补贴其中一项。\n\n7.存在下列情形的项目不予支持：\n\n（1）已经获得设备更新贷款中央财政贴息、省级贷款贴息或融资租赁补贴、2026年省先进制造业高地建设和中小企业发展专项重点产业项目、中小企业创新发展项目资金支持的项目。\n\n（2）纯新建项目，无设备更新和技术改造内容。\n\n（3）贷款期限低于一年（含提前还款后贷款期限低于一年）。\n\n（4）采用有关法律法规和产业政策明令禁止的设备或技术建设的项目。\n\n（5）项目实施单位在绩效评价中未获得通过，以及在项目调度、经济运行调度等工作中不配合、造成不良影响的。\n\n（6）申报单位在申报期间被发现存在信用、环保、安全等方面的严重问题。\n\n（7）企业或项目存在相关法律法规和政策规定不应予以支持的其他严重问题。"},{"no":"三","title":"基本程序","text":"1.项目实施企业通过湖南制造强省项目库系统填报完整的项目入库信息（http://222.240.80.54:18080/hnibdp-daq/login），由所在市州、县市区工信部门审核后入库管理。入库信息填报截止时间为2026年10月30日24:00。\n\n2.项目实施企业向当地县市区工信部门提出补贴申请，申请贷款贴息的项目应按照附件1、附件1-1提交申报资料，申请融资租赁补贴的项目应按照附件2、附件2-1提交申报资料。中央在湘单位和省属单位等项目按照属地管理原则，通过项目所在地进行申报。\n\n3.申报材料通过省工业和信息化厅项目管理系统（http://222.240.80.54:8086/pmp/a/login）上传提交。相关申请材料应盖章扫描后形成一个PDF文档上传（项目管理系统不接受多个文件上传）。所有申报资料须进行脱密处理。市州、县市区工信部门及时在系统中审核上报（项目管理系统关闭时间为2026年10月30日）。\n\n4  .县市区（以行政区划为准）工信部门履行项目审查主体责任，通过现场核查、资料审核等方式进行审核，商县市区财政部门后再报市州工信部门。\n\n5  .市州工信部门负责项目汇总、复核，商同级财政部门后向省工业和信息化厅推荐申报。\n\n6  .省工业和信息化厅会同省财政厅、省地方金融监管局、人民银行湖南省分行开展审核和资金测算工作。"},{"no":"四","title":"申报方式与要求","text":"（一）文件上报要求\n\n市州工信部门需于2026年10月30日前将正式推荐文件扫描上传至省工业和信息化厅项目管理系统，同时报送纸质推荐文件一式4份（仅红头文件和项目汇总表）至省工业和信息化厅投资规划处，并将项目汇总表电子版（必须是可编辑表格文件，不能是PDF或图片文件）发送到省工业和信息化厅投资规划处邮箱abc2212144@126.com。\n\n（二）文件上报收件人\n\n省工业和信息化厅投资规划处：李嘉璇电话：0731-88955499\n\n地址：长沙市天心区新韶东路467号，邮编：410004"},{"no":"五","title":"特别提醒","text":"（一）各项目实施企业要对项目资料的申报事项真实性、数据准确性负责，由企业法人代表或法人代表委托授权人在申报资料上签名并加盖单位公章。由委托授权人签名的，应提供企业法人代表相关授权文书。对材料造假的，一经查实，立即取消申报资格、收回补助资金并依法依规处理。对获得补助资金支持却不配合后续监管的，视情况收回已安排的资金。\n\n（二）各市州、县市区工信部门要认真履行审查责任，对项目申报资料要件的齐全性、真实性等认真把关。坚决杜绝虚假申报，不得推荐不符合条件的项目，对审核把关不严的地方，将给予通报批评并追究责任。\n\n（三）金融机构应配合做好项目申报的资料准备。对金融机构参与项目信息造假、套取骗取补贴资金等情况，一经查实，将向金融监管部门通报。\n\n（四）本次申报不收取任何费用，从未委托任何单位或个人为申报单位代理申报事宜。任何机构或个人假借机关单位或工作人员名义进行推销，违背企业意愿收取费用，可向当地有关部门或省工业和信息化厅举报。省工业和信息化厅举报受理电话：0731-88955596。\n\n附件：\n\n1.第三批湖南省工业企业设备更新和技术改造项目贷款贴息申报汇总表\n\n1-1.第三批湖南省工业企业设备更新和技术改造项目贷款贴息申请报告（模板）\n\n2.第三批湖南省工业企业设备更新和技术改造项目融资租赁补贴申报汇总表\n\n2-1.第三批湖南省工业企业设备更新和技术改造项目融资租赁补贴申请报告（模板）\n\n附件下载：附件1-2\n\n湖南省工业和信息化厅\n\n湖南省财政厅\n\n湖南省地方金融管理局\n\n中国人民银行湖南省分行\n\n2026年9月30日\n\n收藏\n\n国家部委网站\n\n发展改革委\n\n外交部\n\n卫生健康委\n\n国防部\n\n教育部\n\n科技部\n\n工业和信息化部\n\n公安部\n\n中央纪委国家监委\n\n民政部\n\n司法部\n\n财政部\n\n人力资源和社会保障部\n\n自然资源部\n\n生态环境部\n\n住房和城乡建设部\n\n交通运输部\n\n水利部\n\n农业农村部\n\n商务部\n\n应急管理部\n\n退役军人事务部\n\n文化和旅游部\n\n人民银行\n\n审计署\n\n海关总署\n\n税务总局\n\n市场监督管理总局\n\n广电总局\n\n民航局\n\n体育总局\n\n各省工信厅网站\n\n北京市经信局\n\n天津市工信局\n\n河北省工信厅\n\n辽宁省工信厅\n\n内蒙古工信厅\n\n黑龙江省工信厅\n\n浙江省经信厅\n\n安徽省经信厅\n\n河南省工信厅\n\n广东省工信厅\n\n湖北省经信厅\n\n重庆市经信委\n\n四川省经信厅\n\n贵州省工信厅\n\n云南省工信厅\n\n甘肃省工信厅\n\n陕西省工信厅\n\n宁夏工信厅\n\n青海省工信厅\n\n山西省工信厅\n\n吉林省工信厅\n\n上海市经信委\n\n江苏省工信厅\n\n福建省工信厅\n\n江西省工信厅\n\n山东省工信厅\n\n海南省工信厅\n\n广西工信厅\n\n新疆工信厅\n\n西藏经信厅\n\n各市州工信局网站\n\n长沙市工信局\n\n衡阳市工信局\n\n株洲市工信局\n\n湘潭市工信局\n\n邵阳市工信局\n\n岳阳市工信局\n\n常德市工信局\n\n张家界市工信局\n\n益阳市工信局\n\n郴州市工信局\n\n永州市工信局\n\n怀化市工信局\n\n娄底市工信局\n\n湘西州工信局\n\n直属机构\n\n湖南兵器工业高级技工学校\n\n中南工业学校\n\n湖南省汽车技师学院\n\n湖南省散装水泥和墙体材料改革办公室\n\n湖南无线电管理\n\n湖南省工业通信业节能监察中心\n\n湖南省电子信息产业研究院\n\n湖南省计算机软件资格考试办公室\n\n湖南省国防科技工业局技术开发中心\n\n网站地图"}],"interpretations":[{"sectionNo":"二","headline":"项目总投资200万元以上、贷款满1年，才能申设备更新贷款贴息","who":"具有独立法人资格、财务制度健全、依法纳税、无不良信用记录的工业企业；项目须为在建项目或2026年3月13日之后完工的项目，且已在湖南制造强省项目库入库。","materials":[],"window":"入库信息填报与项目管理系统提交均截止 2026年10月30日（24:00 系统关闭）。","where":"当地县市区工信部门受理，逐级上报市州工信部门、省工信厅。","tip":"贷款须在申报日前已发放、期限一年期（含）以上；同一项目只能享受中央贴息、省级贴息、融资租赁补贴中的一项；已拿过其他贴息的贷款不能重复申报。"},{"sectionNo":"二","headline":"设备投资要占贷款总额一半以上，且已结算三成以上","who":"申请贷款贴息的项目；融资租赁方式申报的，单笔设备合同金额不低于100万元。","materials":[],"window":"设备购置时间须在 2024年3月7日（含）之后。","where":"同上，通过省工信厅项目管理系统提交。","tip":"贷款只能用于项目建设，不能买原材料、发工资或日常周转；设备购置早于2024年3月7日的不能算进设备投资。"},{"sectionNo":"三","headline":"先入库、再申报，材料要合成一个 PDF 上传","who":"项目实施企业；中央在湘单位和省属单位按属地原则通过项目所在地申报。","materials":["贷款贴息：按附件1、附件1-1准备","融资租赁补贴：按附件2、附件2-1准备","盖章扫描后合成一个 PDF（系统不接受多个文件）"],"window":"2026年10月30日截止，市州推荐文件也要在当天前上传。","where":"湖南制造强省项目库系统入库；省工信厅项目管理系统上传申报材料。","tip":"所有申报资料要做脱密处理；项目汇总表电子版必须是可编辑表格，不能交 PDF 或图片。"},{"sectionNo":"四","headline":"市州工信部门10月30日前上报推荐文件，纸质一式4份","who":"工业企业项目由属地市州工信部门汇总推荐上报；市州工信部门须报送正式推荐文件，并报送纸质推荐文件一式4份（仅红头文件和项目汇总表），项目汇总表电子版须为可编辑表格文件。","materials":["正式推荐文件（红头文件）","项目汇总表（纸质一式4份，电子版须为可编辑表格文件）"],"window":"2026年10月30日前完成推荐文件上报（本批次截止时间）","where":"省工业和信息化厅项目管理系统（线上上传）；省工业和信息化厅投资规划处（纸质件报送、邮箱abc2212144@126.com）","tip":"纸质件只需红头文件和项目汇总表，一式4份；汇总表电子版必须是可编辑表格文件，PDF或图片文件不符合要求；收件人为投资规划处李嘉璇，电话0731-88955499。"},{"sectionNo":"五","headline":"材料造假一经查实立即取消申报资格、收回补助资金","who":"各项目实施企业（申报企业）对项目资料申报事项真实性、数据准确性负责；申报资料须由企业法人代表或法人代表委托授权人签名并加盖单位公章，由委托授权人签名的应提供企业法人代表相关授权文书；获得补助资金后须配合后续监管。","materials":["企业法人代表相关授权文书（由委托授权人签名时提供）","第三批湖南省工业企业设备更新和技术改造项目贷款贴息申报汇总表","第三批湖南省工业企业设备更新和技术改造项目贷款贴息申请报告（模板）","第三批湖南省工业企业设备更新和技术改造项目融资租赁补贴申报汇总表","第三批湖南省工业企业设备更新和技术改造项目融资租赁补贴申请报告（模板）"],"window":"本批次申报按通知时限执行；获得补助资金后须配合后续监管，不配合的视情况收回已安排资金","where":"省工业和信息化厅（举报受理电话0731-88955596）；当地有关部门","tip":"本次申报不收取任何费用，省工业和信息化厅从未委托任何单位或个人代理申报；假借机关单位或工作人员名义推销、违背企业意愿收费的，可向当地有关部门或省工业和信息化厅举报；材料造假一经查实立即取消申报资格、收回补助资金。"}],"sourceUrl":"https://gxt.hunan.gov.cn/xxgk_71033/tzgg/202609/t20260930_34075438.html","sourceNote":"湖南省工信厅官网公开正文。该通知未标注独立文号，依据《关于修改〈湖南省工业企业设备更新和技术改造项目融资补贴实施办法〉的通知》（湘财产业〔2025〕5号）组织第三批申报。；2026-11-08 核对：页面发布日期 2026-09-30；2026-11-09 条文按官方原文重切（5 条，自查召回 100%）","verified":true,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"hunan-guaranteed-loan-grads-2026","title":"湖南省人力资源和社会保障厅等三部门关于进一步优化创业担保贷款政策全力支持大学生等重点群体创业的通知","level":"provincial","region":"湖南省","issuer":"湖南省人力资源和社会保障厅、湖南省财政厅、中国人民银行湖南省分行","documentNo":"湘人社规〔2026〕9号","publishedAt":"2026-08-14","effectiveAt":"2026-08-14","expiresAt":"2029-08-13","status":"active","tags":["贷款贴息"],"audience":["大学生","小微企业"],"summary":"大学生个人创业担保贷款最高额度提至50万元，按实际利率50%财政贴息，担保费率不高于0.1%并给予补贴。","sections":[{"no":"一","title":"加大政策扶持力度","text":"（一）扩大支持范围。将借款对象中的高校毕业生类别扩大为大学生，包括国内外高校在校学生或毕业5年内的大专、本科、硕士、博士毕业生，以及技师学院在校或毕业5年以内的毕业生。残疾人大学生可放宽至毕业8年内的毕业生。\n\n（二）提高贷款额度。参照湖南省财政厅等四部门《关于实施大学生创业贷款财政补助政策的通知》（湘财金〔2025〕43号），将符合条件的大学生个人申请创业担保贷款，最高额度提高至50万元。\n\n（三）提高担保费补贴。参照湖南省财政厅等四部门《关于实施大学生创业贷款财政补助政策的通知》（湘财金〔2025〕43号），政府性融资担保机构为大学生个人创业担保贷款提供担保的，收取担保费率不得高于0.1%，省财政按不高于担保金额的1.4%给予补贴。担保费补贴按实际承保期限计算，按年度补贴。"},{"no":"二","title":"完善资金保障与机制","text":"（一）优化财政贴息分担。对于大学生个人创业担保贷款所需贴息资金，由中央和省级财政承担，免除市县配套资金。对创业担保贷款贴息资金分担机制进行优化，分担比例为：脱贫县所需贴息资金由省财政统筹中央奖补资金和省级配套资金承担95%、脱贫县承担5%，其他市县所需贴息资金由省财政统筹中央奖补资金和省级配套资金承担75%、其他市县承担25%。各市州、县市区须严格落实本级应承担的贴息配套资金。\n\n（二）预拨贴息资金。参照湖南省财政厅等四部门《关于实施大学生创业贷款财政补助政策的通知》（湘财金〔2025〕43号），建立贴息预拨机制，鼓励各市县财政按照当地创业担保贷款余额，年初预拨当年贴息资金，年底据实结算。贴息资金暂时不足的，由担保基金垫付，待财政贴息资金到位后直接拨付至担保基金。\n\n（三）完善基金风险分担和补充机制。将创业担保贷款纳入现有国家中小微企业贷款风险分担政策范围，各级可根据实际引入政府性担保公司担保。建立健全担保基金持续补充机制，担保基金不足的地区要及时补充。建立呆坏账代偿核销机制，每年开展一次呆坏账清理。\n\n（四）落实创业担保贷款奖补政策。落实我省创业担保贷款有关规定，省财政加大创业担保贷款奖补资金保障力度。省人力资源社会保障厅每年4月底前完成奖补资金分配方案。省财政厅每年5月底前完成奖补资金拨付。各级财政部门每年6月底前将奖补资金拨付至各单位。"},{"no":"三","title":"强化协同与宣传引导","text":"（一）健全协同与激励机制。省人力资源社会保障厅、省财政厅、人民银行湖南省分行要积极推动创业担保贷款政策落实，将发放创业担保贷款纳入年度省重点民生实事项目，将创业担保贷款担保情况纳入政府性融资担保公司绩效评价体系，并将创业担保贷款开展情况作为就业专项资金分配因素及纳入其他评价激励体系，鼓励各类银行积极参与，对服务优质、贡献突出的合作银行，在业务对接、省级财政资金存放等方面予以重点倾斜。各级人力资源社会保障、财政、人民银行等部门要提高政治站位，将落实创业担保贷款政策作为稳就业、促创业的重要举措，明确专人负责，压实工作责任。\n\n（二）优化经办服务。由省财政牵头、省融资担保集团旗下的省中小担保公司建设全线上经办的创业担保贷款数字化管理系统，接入人力资源社会保障、教育、金融监管等部门数据，推动资格审核、担保审批、银行授信、资金结算等流程并联审批。各级人力资源社会保障部门应加快人员资格审核速度，简化纸质资料，优化经办流程，及时推送担保机构。\n\n（三）加大宣传力度。各地要统筹宣传资源，创新宣传方式，充分利用政府网站、新闻发布、政策宣讲等多种渠道，广泛宣传政策内容、申请流程和典型案例，有效提高政策知晓度、覆盖面和获得感。"}],"interpretations":[{"sectionNo":"一","headline":"大学生个人创业担保贷款最高提到50万元","who":"国内外高校在校学生或毕业5年内的大专、本科、硕士、博士毕业生，以及技师学院在校或毕业5年以内的毕业生；残疾人大学生可放宽至毕业8年内。","materials":[],"window":"按创业担保贷款经办流程办理。","where":"经办银行、政府性融资担保机构与当地人力资源社会保障部门。","tip":"担保费率不得高于0.1%，省财政按不高于担保金额的1.4%给予补贴，按实际承保期限年度补贴。"},{"sectionNo":"二","headline":"大学生贷款贴息由中央和省级承担，市县不用配套","who":"大学生个人创业担保贷款；脱贫县与其他市县分担比例不同。","materials":[],"window":"年初预拨当年贴息资金，年底据实结算；省人社厅每年4月底前完成奖补分配，省财政厅5月底前拨付。","where":"省级财政统筹，市县财政按规定落实本级应承担的配套资金。","tip":"脱贫县贴息资金由省财政统筹承担95%、县里承担5%；其他市县由省里承担75%、市县承担25%。"}],"sourceUrl":"https://www.hunan.gov.cn/hnszf/szf/hnzb_18/2026/202615/szfbmwj_98721_88_1urmmqrurrdbvpccutqhrmsteguugvmdqkupkguegktvspfmfnnccnmvnkhnueqhqrmcrunhkbqgcqshkecsrgbnercksgkvunnqqdpsgvgpukgdtd/202608/t20260814_34045077.html","sourceNote":"2026-10-31 取自湖南省人民政府门户网站政府公报2026年第15期原文页；原文“自公布之日起施行，有效期3年”，公布日为公报发布日2026-08-14，据此推算有效期至2029-08-13。；2026-11-08 核对：页面发布日期 2026-08-14","verified":true,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"hunan-one-time-startup-subsidy-2026","title":"湖南省人力资源和社会保障厅 湖南省财政厅关于进一步做好一次性创业补贴工作的通知（试行）","level":"provincial","region":"湖南省","issuer":"湖南省人力资源和社会保障厅、湖南省财政厅","documentNo":"湘人社规〔2026〕11号","publishedAt":"2026-08-05","effectiveAt":"2026-08-01","expiresAt":"2027-07-31","status":"active","tags":["创业补贴"],"audience":["小微企业","个体工商户"],"summary":"首次创办市场主体并正常经营1年以上，高校毕业生/在校学生补不低于1万元，其他重点群体不低于5000元。","sections":[{"no":"一","title":"补贴对象","text":"省内首次创办小微企业或从事个体经济,且所创办企业或个体工商户(以下称市场主体)自工商登记注册之日起正常运营1年以上的离校2年内高校毕业生、院校在校学生、就业困难人员、返乡入乡农民工。已在我省享受过一次性创业补贴的单位或个人,原则上不重复享受,各市州和县市区另有明确规定的除外。"},{"no":"二","title":"补贴标准","text":"就业困难人员、返乡入乡农民工创办的市场主体按最低不少于5000元/家的标准给予补贴。对离校2年内高校毕业生、院校在校学生创办的市场主体按最低不少于10000元/家的标准给予补贴。\n\n补贴所需资金从各地就业专项资金中列支。安排其他非就业专项资金用于发放一次性创业补贴的,可按照相应文件执行。"},{"no":"三","title":"补贴拨付流程","text":"(一)申请。符合条件的市场主体可采用线上或线下的方式申请一次性创业补贴。\n\n1.线上申请。符合条件的市场主体可通过“湘易办”高效办成个人创业“一件事”专区或“湘就业”小程序等线上平台填写并提交人员身份、项目等信息。\n\n2.线下申请。符合条件的市场主体可前往当地人力资源社会保障部门或相关窗口现场办理,并提供《一次性创业补贴申请表》、营业执照、国家企业信用信息公示系统下载的《企业年度报告》、法定代表人身份证明材料(具体要求见《人员身份证明材料》)。\n\n通过省人社一体化业务管理系统业务协同获得的信息,可不再提供相关证明材料。\n\n(二)审核。各级人力资源社会保障部门收到申请后,对申报资料进行审核。申请对象提供材料不实、不准导致审核错误的,后果由申请对象承担。\n\n(三)发放。审核通过后,各级人力资源社会保障、财政部门及时将补贴资金发放至补贴对象。"},{"no":"四","title":"相关要求","text":"(一)各级人力资源社会保障、财政部门要提高政治站位,将落实一次性创业补贴工作作为稳就业、促创业的重要举措。要依托省人社一体化业务管理系统,简化纸质材料、优化经办流程,切实提升经办效率。要加强政策宣传,不断提升政策知晓度。\n\n(二)各级财政、人力资源社会保障部门要严格按照相关规定,做好资金申报、审核和拨付工作,切实保障财政资金安全规范、高效精准使用。要统筹安排好资金,持续加大保障投入力度,确保政策落地见效。\n\n(三)本通知自2026年8月1日起施行,有效期一年。各地已有政策的,可按补贴对象从宽、补贴标准从高原则执行。各市州可结合实际制定细则,具备条件的,可适度放宽补贴对象、提高补贴标准。"}],"interpretations":[{"sectionNo":"一","headline":"省内首次创业、正常运营满1年，这四类人可领一次性补贴","who":"离校2年内高校毕业生、院校在校学生、就业困难人员、返乡入乡农民工；须在省内首次创办小微企业或从事个体经济，且自工商登记注册之日起正常运营1年以上。已在我省享受过一次性创业补贴的，原则上不重复享受。","materials":[],"window":"自工商登记注册之日起正常运营1年以上方可申请；本通知自2026年8月1日起施行，有效期一年。","where":"线上「湘易办」个人创业一件事专区或「湘就业」小程序；线下当地人力资源社会保障部门或相关窗口。","tip":"各市州和县市区另有明确规定的，可不按「不重复享受」处理；各地可按补贴对象从宽、补贴标准从高执行。"},{"sectionNo":"二","headline":"就业困难人员等补5000元起，大学生创业补1万元起","who":"就业困难人员、返乡入乡农民工创办的市场主体最低不少于5000元/家；离校2年内高校毕业生、院校在校学生创办的，最低不少于10000元/家。","materials":[],"window":"资金从各地就业专项资金中列支。","where":"各级人力资源社会保障、财政部门审核发放。","tip":"这是省级最低标准，各市州可结合实际提高；用其他非就业专项资金发放的，按相应文件执行。"},{"sectionNo":"三","headline":"线上用「湘易办」办，线下要交申请表、营业执照和年报","who":"符合条件的市场主体，线上或线下均可申请。","materials":["《一次性创业补贴申请表》","营业执照","国家企业信用信息公示系统下载的《企业年度报告》","法定代表人身份证明材料（按《人员身份证明材料》要求）"],"window":"收到申请后由人社部门审核，通过后由人社、财政部门发放。","where":"线上「湘易办」个人创业一件事专区、「湘就业」小程序；线下当地人社部门或窗口。","tip":"通过省人社一体化业务管理系统能协同到的信息，可以不再提供证明材料。"}],"sourceUrl":"https://rst.hunan.gov.cn/rst/xxgk/zcfg/zxzc/202608/t20260805_34040428.html","sourceNote":"2026-10-31 取自湖南省人社厅官网厅发规范性文件栏目原文页；有效期一年据原文“自2026年8月1日起施行，有效期一年”推算为2027-07-31。；2026-11-08 核对：页面发布日期 2026-08-05","verified":true,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"hunan-sme-development-fund-2025","title":"关于做好2025年湖南省中小企业发展专项资金项目申报工作的通知","documentNo":"湘工信中小发展〔2025〕226号","level":"provincial","region":"湖南省","issuer":"湖南省工业和信息化厅、湖南省财政厅","publishedAt":"2025-07-09","effectiveAt":"","expiresAt":"","status":"active","tags":["专项资金"],"audience":["中小企业","专精特新中小企业"],"summary":"2025年湖南省中小企业发展专项资金项目申报通知，以无偿补助方式重点支持专精特新发展类和完善服务体系类两类项目，明确申报基本条件、项目类别、名额分配、申报程序与资料要求，网上申报截止2025年8月7日。","sections":[{"no":"一","title":"申报基本条件","text":"1、在湖南省境内依法登记注册，一般应具有独立法人资格，或在湖南设立独立核算并纳入最小法人统计的分公司或子公司，截至2024年12月31日成立1年以上，申报单位应具有健全的财务管理机构和制度，能够严格落实资金管理要求，积极配合做好调查、调度、绩效评价等工作，具有良好信用。\n\n2、项目符合国家有关法律法规和产业政策，主要用于支持中小企业提升创新能力及专业化水平，优化创新创业环境，不断完善中小企业公共服务体系，开展中小企业开展合作交流等促进中小企业发展的相关工作。\n\n3、存在以下情形之一的，不得申报本专项资金项目：\n\n（1）已经申报2025年度其他省级财政专项资金补助类项目；\n\n（2）2024年已获得省先进制造业高地建设专项、省中小企业发展专项等省工业和信息化厅管理专项支持的补助类项目单位，不得申报本专项专精特新发展补助类项目；\n\n（3）2023-2024年连续两年获得省先进制造业高地建设专项、省中小企业发展专项等省工业和信息化厅管理专项支持的补助类项目单位，不得申报本专项完善服务体系补助类项目；\n\n（4）被列入“信用湖南”黑名单或者近两年在安全生产（含网络安全）、产品质量、生态环保等方面有严重不良信用记录；\n\n（5）在项目申报中存在弄虚作假行为的单位；\n\n（6）在绩效评价中未获得通过，以及在项目调度、企业服务等工作中极不配合，造成不良影响的，不得申报。"},{"no":"二","title":"申报项目类别","text":"2025年省中小企业发展专项资金以无偿补助方式重点支持以下两类项目：\n\n（一）专精特新发展类项目\n\n重点支持方向：支持中小企业进行数字化、网络化、智能化建设，购置仪器设备，改造场地设施，引进技术及服务，增强研发创新能力，改进产品质量，提高生产技术水平和生产效率，加快专精特新发展。\n\n重点支持范围：制造业中小企业，原则上是2024年认定的湖南省专精特新中小企业。项目符合专精特新发展方向，主要建设内容在2024年期间实施，主要投入发生在2024年，经济社会生态效益良好。\n\n市县区推荐名额分配：\n\n市州本级：长沙市7个，衡阳市5个，株洲市4个，湘潭市、常德市、张家界市、益阳市、郴州市、永州市各2个，邵阳市、岳阳市各3个，怀化市、娄底市各1个，湘西州8个。\n\n财政省直管县市：浏阳市、宁乡市、城步县、新宁县、资兴市各2个，其他财政省直管县市各1个。\n\n（二）完善服务体系类项目\n\n1、服务能力建设项目\n\n重点支持方向：为完善服务功能，进行的场地设施改造、软件升级、设备更新等软硬件投入（不含基建及厂房建设）。\n\n2、服务业务补助项目\n\n重点支持方向：为解决中小企业发展“急难愁盼”问题，开展“一起益企”中小企业服务、大学生创新创业服务、中小企业出海、“一月一链”中小企业融资促进等活动，推进中小企业商业价值信用贷款改革试点工作。\n\n重点支持范围：（1）有效期内的国家小型微型企业创业创新基地和国家中小企业公共服务示范平台；（2）全省中小企业公共服务平台网络窗口服务平台运营单位，有效期内的全省中小微企业核心服务机构；（3）省专精特新中小企业股权融资服务平台。\n\n1-2类项目市县区推荐名额分配：\n\n市州本级：长沙市7个，衡阳市、株洲市各4个，湘潭市、邵阳市、岳阳市、常德市、郴州市各3个，益阳市、永州市、娄底市、怀化市、张家界市各2个，湘西州5个。\n\n每个县（市区）各1个。"},{"no":"三","title":"项目申报程序","text":"（一）市州项目，由市州工业和信息化局牵头组织申报、审核等工作，市州财政局配合开展相关工作。市州工业和信息化局、财政局联合行文（含附件《2025年湖南省中小企业发展专项资金项目汇总表》，以下简称《项目汇总表》）上报省工业和信息化厅。\n\n（二）财政省直管县市项目，由县市工信部门、财政局参照市州项目的组织方式，联合行文（含《项目汇总表》）上报省工业和信息化厅，同时抄报所在市州工业和信息化局、财政局。\n\n（三）省直单位申报服务体系项目，由省直主管部门审核并行文报省工业和信息化厅。\n\n（四）审核部门对项目申报单位信用情况在“信用湖南”网站进行查询。各级工信部门要对项目是否符合国家法律法规和产业政策、是否符合专项资金支持范围和方向严格审查，对项目资料真实性、完整性、准确性、规范性严格审查。"},{"no":"四","title":"申报资料要求","text":"（一）项目申报资料提交方式：实行网上申报方式，不受理纸质申报资料。项目单位必须通过《湖南省工业和信息化厅项目管理系统》（https://222.244.103.250:8181/pmp/a/login）填报，严格按照项目类别申报模板（从《湖南省工业和信息化厅项目管理系统》中下载）编制申报资料、进行在线提交。各级工信部门及时对网上申报资料进行审核上报。\n\n（二）上报文件要求：市州和财政省直管县市工信部门将申报文件（PDF格式）和《项目汇总表》（Excel格式）上传到《湖南省工业和信息化厅项目管理系统》。\n\n（三）截止日期：2025年8月7日前完成项目申报系统审核上报及推荐文件上传流程，逾期不予受理。\n\n（四）其他事项\n\n1、项目资料是项目评审、资金安排、监督管理、绩效评价等工作的重要依据，各申报单位对项目资料真实性负责。\n\n2、所有申报内容需按照要求如实填写，准确完整，不得缺项漏项；申报材料真实性承诺及所提供的相关附件要求字迹及公章清晰；其他相关扫描件均要求资料字迹、印章清晰。主体材料不齐全的项目不予受理。\n\n3、项目申报系统填报的申报资料，包括企业申报材料真实性承诺、申请报告正文及相关附件，必须以一个完整的文档形式上传。\n\n4、专项资金的监管、绩效评价、审计等工作按照有关规定实施。各项目单位应当积极配合，如实申报有关事项。对报大建小、材料造假、使用同一凭证多头重复申报省级财政专项资金的，一经查实即取消申报资格，并登记为不良信用记录，三年内不得申报本专项资金。对获得专项资金支持却不配合全程监管，或不按约定完成项目建设的视情况收回已安排的资金。\n\n5、特别提醒：省工业和信息化厅、省财政厅未委托任何单位或个人为项目单位代理专项资金申报事宜。请相关单位按程序自主申报。凡发现代理申报，经查实将淘汰该项目。各级工信部门受理项目申报申请，不收取任何费用。如有任何中介机构或个人假借单位或工作人员名义向企业进行推销或收取费用的，请谨防欺诈，避免上当受骗，并向当地相关部门举报。"},{"no":"五","title":"联系人及地址","text":"（一）省工业和信息化厅\n\n地址：长沙市天心区新韶东路467号，邮编：410004。\n\n1、专精特新发展类项目联系人：孙丹，0731-88955539；\n\n2、完善服务体系类项目联系人：黄轶凡，0731-88955535。\n\n（二）省工业和信息化厅项目管理系统技术咨询\n\n联系人：张凯迪，0731-88955465。\n\n附件：2025年湖南省中小企业发展专项资金项目汇总表\n\n湖南省工业和信息化厅湖南省财政厅\n\n2025年7月8日\n\n收藏\n\n国家部委网站\n\n发展改革委\n\n外交部\n\n卫生健康委\n\n国防部\n\n教育部\n\n科技部\n\n工业和信息化部\n\n公安部\n\n中央纪委国家监委\n\n民政部\n\n司法部\n\n财政部\n\n人力资源和社会保障部\n\n自然资源部\n\n生态环境部\n\n住房和城乡建设部\n\n交通运输部\n\n水利部\n\n农业农村部\n\n商务部\n\n应急管理部\n\n退役军人事务部\n\n文化和旅游部\n\n人民银行\n\n审计署\n\n海关总署\n\n税务总局\n\n市场监督管理总局\n\n广电总局\n\n民航局\n\n体育总局\n\n各省工信厅网站\n\n北京市经信局\n\n天津市工信局\n\n河北省工信厅\n\n辽宁省工信厅\n\n内蒙古工信厅\n\n黑龙江省工信厅\n\n浙江省经信厅\n\n安徽省经信厅\n\n河南省工信厅\n\n广东省工信厅\n\n湖北省经信厅\n\n重庆市经信委\n\n四川省经信厅\n\n贵州省工信厅\n\n云南省工信厅\n\n甘肃省工信厅\n\n陕西省工信厅\n\n宁夏工信厅\n\n青海省工信厅\n\n山西省工信厅\n\n吉林省工信厅\n\n上海市经信委\n\n江苏省工信厅\n\n福建省工信厅\n\n江西省工信厅\n\n山东省工信厅\n\n海南省工信厅\n\n广西工信厅\n\n新疆工信厅\n\n西藏经信厅\n\n各市州工信局网站\n\n长沙市工信局\n\n衡阳市工信局\n\n株洲市工信局\n\n湘潭市工信局\n\n邵阳市工信局\n\n岳阳市工信局\n\n常德市工信局\n\n张家界市工信局\n\n益阳市工信局\n\n郴州市工信局\n\n永州市工信局\n\n怀化市工信局\n\n娄底市工信局\n\n湘西州工信局\n\n直属机构\n\n湖南兵器工业高级技工学校\n\n中南工业学校\n\n湖南省汽车技师学院\n\n湖南省散装水泥和墙体材料改革办公室\n\n湖南无线电管理\n\n湖南省工业通信业节能监察中心\n\n湖南省电子信息产业研究院\n\n湖南省计算机软件资格考试办公室\n\n湖南省国防科技工业局技术开发中心\n\n网站地图"}],"interpretations":[{"sectionNo":"一","headline":"成立满1年、财务健全才能申报，两类补助互斥","who":"在湖南省依法登记注册、一般应具独立法人资格（或独立核算的分公司/子公司），截至 2024年12月31日 成立1年以上、财务制度健全、信用良好，项目符合国家产业政策。","materials":[],"window":"按 2025 年度申报通知的时间安排（网上申报截止 2025年8月7日）。","where":"省工信厅项目管理系统申报，市县工信部门审核推荐。","tip":"2024 年已获省先进制造业高地建设专项、省中小企业发展专项补助类项目的，不得申报专精特新发展补助类；2023-2024 连续两年获得的，不得申报完善服务体系补助类；已申报 2025 年度其他省级财政专项补助类项目的也不能申报。"},{"sectionNo":"二","headline":"只支持两类：专精特新发展类、完善服务体系类","who":"专精特新发展类：制造业中小企业，原则上是 2024 年认定的湖南省专精特新中小企业，主要建设内容和投入发生在 2024 年；完善服务体系类：有效期内的国家小微企业创业创新基地、国家中小企业公共服务示范平台、全省窗口服务平台运营单位、核心服务机构、专精特新中小企业股权融资服务平台。","materials":[],"window":"2025 年度，按名额分配到市县推荐。","where":"省工信厅（项目管理系统）；市县工信部门组织推荐。","tip":"两类都有推荐名额限制，市州本级与财政省直管县市各不相同（如长沙专精特新类7个、湘西州8个），不是报了就能上。"},{"sectionNo":"三","headline":"市州项目由市州工信局牵头组织申报，联合行文报省厅","who":"市州项目：由市州工业和信息化局牵头组织申报、审核，市州财政局配合；财政省直管县市项目：由县市工信部门、财政局参照市州项目的组织方式；省直单位申报服务体系项目：由省直主管部门审核并行文。申报单位信用情况由审核部门在“信用湖南”网站查询。","materials":["《2025年湖南省中小企业发展专项资金项目汇总表》（随联合行文上报的附件）"],"window":"按年度申报通知组织申报、审核，本条未列截止日期。","where":"市州工业和信息化局、市州财政局；县市工信部门、财政局；省工业和信息化厅；“信用湖南”网站。","tip":"财政省直管县市项目除联合行文上报省工信厅外，还须同时抄报所在市州工信局、财政局；审核部门会在“信用湖南”网站查询申报单位信用情况。"},{"sectionNo":"四","headline":"网上填报，2025年8月7日前完成审核上报，逾期不受理","who":"通过《湖南省工业和信息化厅项目管理系统》网上申报的项目单位（不受理纸质申报资料）；申报单位须对项目资料真实性负责，申报内容如实填写、准确完整、不得缺项漏项，申报材料真实性承诺及所提供相关附件字迹及公章清晰；主体材料不齐全的项目不予受理。","materials":["企业申报材料真实性承诺","申请报告正文","相关附件","申报文件（PDF格式）","《项目汇总表》（Excel格式）"],"window":"2025年8月7日前完成项目申报系统审核上报及推荐文件上传流程，逾期不予受理。","where":"《湖南省工业和信息化厅项目管理系统》（https://222.244.103.250:8181/pmp/a/login）；各级工信部门。","tip":"报大建小、材料造假、使用同一凭证多头重复申报省级财政专项资金的，一经查实即取消申报资格并登记为不良信用记录，三年内不得申报本专项资金；省工信厅、省财政厅未委托任何单位或个人代理申报，受理申报不收取任何费用。"},{"sectionNo":"五","headline":"项目咨询：专精特新类0731-88955539","who":"申报2025年湖南省中小企业发展专项资金项目的单位；专精特新发展类项目联系省工信厅孙丹（0731-88955539），完善服务体系类项目联系黄轶凡（0731-88955535），项目管理系统技术咨询联系张凯迪（0731-88955465）。","materials":["2025年湖南省中小企业发展专项资金项目汇总表（附件）"],"window":"按申报期电话咨询，原文未列具体咨询时间。","where":"省工业和信息化厅：长沙市天心区新韶东路467号（邮编410004）；省工业和信息化厅项目管理系统技术咨询。","tip":"两个项目类别联系人不同：专精特新发展类为孙丹，完善服务体系类为黄轶凡；系统填报故障找技术咨询张凯迪。"}],"sourceUrl":"https://gxt.hunan.gov.cn/gxt/xxgk_71033/tzgg/202507/t20250709_33734493.html","sourceNote":"湖南省工信厅官网公开正文，2025年度一次性申报通知。；2026-11-08 核对：页面发布日期 2025-07-09；2026-11-09 条文按官方原文重切（5 条，自查召回 100%）","verified":true,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"hunan-specialized-sme-2026-batch2","title":"关于组织开展2026年第二批湖南省专精特新中小企业申报工作的通知","level":"provincial","region":"湖南省","issuer":"湖南省工业和信息化厅","documentNo":"","publishedAt":"2026-05-21","effectiveAt":"","expiresAt":"","status":"active","tags":["认定资质"],"audience":["中小企业","创新型中小企业"],"summary":"组织2026年第二批湖南省专精特新中小企业申报，须为有效期内创新型中小企业，经属地工信部门审核推荐、专家评审认定。","sections":[{"no":"一","title":"条件标准","text":"1.申报企业应在湖南省内依法设立，符合《中小企业划型标准规定》，遵守国家法律法规和行业规范。\n\n2.申报期间未被列入经营异常名录或严重失信主体名单，提供的产品（服务）不属于国家禁止、限制或淘汰类，同时近三年未发生较大生产安全事故、重大网络和数据安全事件、重大环境违法行为、严重质量问题、严重违反相关行业管理规定。\n\n3.坚持企业自愿原则，符合《专精特新中小企业认定标准》（工信部企业〔2026〕2号，附件1）。\n\n4.重点聚焦制造强国重点产业（新一代信息技术产业、高档数控机床和机器人、航空航天装备、海洋工程装备及高技术船舶、先进轨道交通装备、节能与新能源汽车、电力装备、农机装备、新材料、生物医药及高性能医疗器械）、工业“六基”（核心基础零部件、核心基础元器件、关键软件、先进基础工艺、关键基础材料、产业技术基础）、“4×4”现代化产业体系（现代石化、绿色矿业、食品加工、轻工纺织4大传统产业，工程机械、轨道交通装备、现代农业、文化旅游4大优势产业，数字、新能源、大健康、空天海洋4大新兴产业，以及人工智能、生命工程、量子科技、前沿材料4大未来产业）等领域。"},{"no":"二","title":"申报时间","text":"2026年5月20日-2026年6月1日"},{"no":"三","title":"申报方式","text":"1.申报企业须是有效期内的创新型中小企业，有效期内的专精特新中小企业、专精特新“小巨人”企业不再申报。\n\n2.按属地原则，申报企业须首先在优质中小企业梯度培育平台（https://zjtx.miit.gov.cn/，以下称“培育平台”）完成数字化水平评测，然后在培育平台进行线上申报，完整填写《专精特新中小企业申请书》，并打包上传佐证材料（附件2）。"},{"no":"四","title":"有关要求","text":"1.各市州工信部门要高度重视专精特新中小企业培育工作，认真履行职责，坚持条件标准，严格审核把关，确保申报质量。\n\n2.请各市州工信部门于6月1日前在培育平台提交审核意见，并将专精特新中小企业推荐函和汇总表（附件3，纸质件2份）报省工业和信息化厅，逾期不候。\n\n3.严禁弄虚作假。申报企业对申报材料的完整性、真实性、合法性负责，相关后果由申报企业自行承担。凡在申报过程中存在弄虚作假行为的，一经发现，取消本年度申报资格，并且三年内不得再次申报。\n\n4.严禁代理申报。省工业和信息化厅从未委托任何单位或个人为企业代理申报事宜，请相关企业按程序自主申报。凡委托代理申报的，一经发现，取消参评资格，且三年内不得再次申报。各级工信部门受理申报申请，不收取任何费用。如有任何中介机构或个人假借单位或工作人员名义向企业进行推销或收取费用的，请谨防欺诈，避免上当受骗，并请向当地相关部门举报。任何单位不得以参加收费培训班或解读班作为企业申报前提条件。\n\n联系电话：0731-88955419\n\n邮寄地址：长沙市天心区新韶东路467号\n\n培育平台相关问题咨询电话：85559832"}],"interpretations":[{"sectionNo":"一","headline":"省级专精特新申报：先得是有效期内的创新型中小企业","who":"在湖南省内依法设立、符合中小企业划型标准的企业；申报期间未被列入经营异常名录或严重失信名单，近三年无较大生产安全事故、重大网络数据安全事件、重大环境违法等。","materials":[],"window":"2026年5月20日至6月1日。","where":"优质中小企业梯度培育平台（zjtx.miit.gov.cn）线上申报。","tip":"已经是有效期内的专精特新中小企业或「小巨人」企业的，不再申报；申报前要先在培育平台完成数字化水平评测。"},{"sectionNo":"一","headline":"重点看制造强国产业、工业「六基」和「4×4」产业体系","who":"符合《专精特新中小企业认定标准》（工信部企业〔2026〕2号）的企业；重点聚焦制造强国十大产业、工业「六基」以及湖南「4×4」现代化产业体系领域。","materials":[],"window":"同上，2026年5月20日至6月1日申报。","where":"优质中小企业梯度培育平台。","tip":"认定标准是工信部企业〔2026〕2号，不是省里另定，材料要按该标准逐项对应。"},{"sectionNo":"三","headline":"线上填申请书，佐证材料要打包上传","who":"申报企业（须为有效期内的创新型中小企业）。","materials":["《专精特新中小企业申请书》","佐证材料（按附件2准备，打包上传）"],"window":"2026年6月1日截止。","where":"优质中小企业梯度培育平台，按属地原则申报。","tip":"先把数字化水平评测做完再申报，否则系统里走不下去。"},{"sectionNo":"二","headline":"2026年5月20日至6月1日申报第二批湖南省专精特新中小企业","who":"2026年第二批申报湖南省专精特新中小企业的企业；须在申报期内完成申报。","materials":[],"window":"2026年5月20日-2026年6月1日","where":"培育平台线上提交；本条款未列具体窗口","tip":"申报仅限上述区间，截止日期为2026年6月1日。"},{"sectionNo":"四","headline":"申报造假取消本年度资格，三年内不得再次申报","who":"2026年第二批申报湖南省专精特新中小企业的企业；须对申报材料完整性、真实性、合法性负责，并按程序自主申报，不得委托代理。","materials":["专精特新中小企业推荐函","汇总表（附件3，纸质件2份）"],"window":"市州工信部门于6月1日前在培育平台提交审核意见，逾期不候。","where":"培育平台；省工业和信息化厅（邮寄地址：长沙市天心区新韶东路467号）","tip":"委托代理申报一经发现取消参评资格且三年内不得再次申报；各级工信部门受理申报不收取任何费用，收费培训班或解读班不得作为申报前提。"}],"sourceUrl":"https://gxt.hunan.gov.cn/gxt/xxgk_71033/tzgg/202605/t20260521_33982323.html","sourceNote":"2026-10-31 取自湖南省工业和信息化厅文件通知栏目原文页；原文未标注文号，documentNo 留空；申报窗口为2026-05-20至2026-06-01，认定标准依据工信部企业〔2026〕2号。；2026-11-08 核对：页面发布日期 2026-05-21","verified":true,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"hunan-zhifuwanqi-digital-transformation-2025","title":"关于印发《深化“智赋万企”行动 加快制造业数字化转型实施方案》的通知","documentNo":"湘工信人工智能〔2025〕325号","level":"provincial","region":"湖南省","issuer":"湖南省工业和信息化厅、湖南省财政厅","publishedAt":"2025-09-12","effectiveAt":"2025-09-03","expiresAt":"2028-09-02","status":"active","tags":["数字化转型"],"audience":["制造业企业","专精特新中小企业"],"summary":"湖南省深化“智赋万企”行动、加快制造业数字化转型的实施方案。提出到2027年规上工业企业数字化研发设计工具普及率超90%、关键工序数控化率超75%，并从评估诊断、人工智能应用、工业互联网、数字化转型促进中心、数字园区、争创国家级标杆等方面明确财政支持比例与上限。","sections":[{"no":"一","title":"目标要求","text":"坚持以习近平新时代中国特色社会主义思想为指导，深入贯彻党的二十大和二十届二中、三中全会精神和习近平总书记关于湖南工作的重要讲话和重要指示批示精神，以深化“智赋万企”行动为抓手，以夯实数字基础设施为支撑，以推进企业数字化智能化改造为方向，深化数字技术在制造业大规模普及应用，加快数据和安全双向赋能，为推进新型工业化注入强劲动力。到2027年，全省规上工业企业数字化研发设计工具普及率、关键工序数控化率分别超过90%、75%，全省工业大市和重点园区规上工业企业实现数字化改造全覆盖，数字赋能、管理创新步伐明显加快。"},{"no":"二","title":"重点任务","text":"（一）推动数字基础设施建设\n\n1、提升智能算力供给。支持工业企业建设智算中心，鼓励重点地区和工业园区建设智算中心为企业提供算力服务，推动传统数据中心改造升级为智能计算中心。在严格落实国家关于算力基础设施布局要求的基础上，支持工业企业部署工业算力设备及面向特定场景的边缘计算设施。鼓励产学研合作开展工业算力创新应用部署，研发满足企业数字化转型需求的算法应用产品。支持全省算力调度和综合管理平台建设和运营，鼓励企业利用算力平台对接资源方购买算力。\n\n2、完善新型网络设施。鼓励工业企业内外网改造，支持工业企业建设5G独立专网，综合运用5G/5G-A、边缘计算、IPv6、时间敏感网络（TSN）等技术，部署新型工业路由器、交换机、网关、网管、标识中间件和算网一体化设备与系统。持续壮大工业互联网平台体系，推动国家级“双跨”工业互联网平台和省级工业互联网平台建设。支持建设国家工业互联网大数据中心湖南分中心。开展工业互联网标识解析体系“贯通”行动，支持链主企业建设运营工业互联网标识解析二级节点。加强关键信息基础设施的安全防护能力建设，提升安全防护水平。\n\n（二）推动产业“智改数转网联”\n\n3、健全数字服务体系。省市协同对省级及以上专精特新企业和规模以上工业企业数字化转型基础和需求“建档立卡”，并进行动态评估和监测。推动服务商为数字化转型意向企业开展咨询诊断，提供“一企一策”数字化解决方案。持续更新省级制造业数字化转型生态供给资源池，培育一批数字化、智能化等领域解决方案供应商，鼓励供应商为制造业企业提供优秀解决方案。支持有条件的单位建设深耕行业的制造业数字化转型促进中心，促进先进生产方式推广普及。\n\n4、“点线面”协同推进。“点”上培育数字化转型标杆。加快新一代信息技术在制造业企业的深度融合应用，持续推动企业上云上平台，每年培育一批省级制造业数字化转型标杆项目、“5G+工业互联网”标杆工厂，分级建设一批数字化转型标杆企业。深入开展两化融合管理体系贯标、数字化转型贯标、数据管理能力成熟度贯标（DCMM）。“线”上打造数字化供应链产业链。推动供应链龙头企业以商业订单为牵引构建数字化供应链体系，打造优势行业领域产业大脑和产业互联网平台，建设一批供应链产业链数字化转型典型案例，形成一批高质量制造业数据集，赋能供应链上下游中小企业数字化转型。“面”上推进重点集群和园区数字化转型。在国家级和省级先进制造业集群核心承载园区等区域，加快5G、工业互联网等新型基础设施的规模化建设应用，推动万兆园区建设，加快重点集群数字化转型，促进资源在线化、产能柔性化。推动建设高标准数字园区，探索园区数字化整体提升路径。\n\n（三）推动人工智能技术和智能装备推广\n\n5、推广人工智能创新应用。加快发展高性能智能芯片和传感器、智能机器人（含人形机器人）、智能移动终端、数字人等，培育一批人工智能终端产品；实施人工智能大模型建设计划，加强行业大模型的研发布局。开展“人工智能+制造”行动，加快人工智能技术在工业研发设计、中试验证、生产制造、营销服务、运营管理等环节的深度融合应用，打造一批人工智能赋能新型工业化典型应用场景。鼓励省内龙头企业建设具身智能训练场。\n\n6、加快智能装备部署应用。推广智能制造装备，重点推动装备制造业更新面向特定场景的智能成套生产线和柔性生产单元；电子信息制造业推进电子产品专用智能制造装备与自动化装配线集成应用；原材料制造业加快无人运输车辆等新型智能装备部署应用，推进催化裂化、冶炼等重大工艺装备智能化改造升级；消费品制造业推广面向柔性生产、个性化定制等新模式智能装备。梯度培育建设一批智能工厂，引导数字化水平较高的企业加快推进单机设备、制造单元、生产线、制造车间等智能化升级，持续建设一批智能工位、智能制造生产线（车间）和智能制造企业。\n\n（四）推动软硬件更新和安全防护\n\n7、推动基础软硬件一体化更新。推动重点产业链（集群）企业全面更新信息系统，重点推进计算整机、中央处理器（CPU）、图形处理器（GPU）、智能传感器、操作系统、数据库、办公软件等基础软硬件一体化迭代升级。鼓励省重点软件企业参与工业企业基础软硬件更新换代系统集成项目。加快省“首台套”重大技术装备、“首版次”软件产品、“首轮次”工程流片芯片、“首套件”基础电子元器件推广应用。加强软硬件耦合适配，重点推进上位机、工作站、实时数据库等基础软硬件一体化更新换代，全面更新智能操作系统、嵌入式操作系统、时序数据库、消息中间件等产品。\n\n8、加快工业软件应用迭代。推动重点产业链（集群）企业全面更新换代研发设计（CAD、CAE、PLM）、资源管理（ERP）、生产运营（MES、QMS、WMS）等各类工业软件。鼓励企业应用部署可编程逻辑控制器（PLC）、分布式控制系统（DCS）等工业操作系统。鼓励产业链龙头企业和工业软件企业、大专院校、科研院所合作开展供需结对攻关、产学研联合攻关。遴选推广省级优秀工业软件、工业操作系统产品和应用解决方案，建成动态更新的优秀工业软件资源池。推动组建省工业软件产业创新联盟，加快建设工业软件专业园区和工业技术软件化创新中心。鼓励本省工业软件企业布局和参与开源项目建设，基于开源项目开发定制化产品。鼓励重点产业链（集群）龙头企业牵头建设工业软件中试验证平台。\n\n9、提升工业信息安全防护能力。组织开展工业互联网“安全深度行”、“工业信息安全服务月”、“铸网”攻防演练等活动，依托网络安全和数据安全协调机制平台，深入开展工业互联网安全分类分级管理和数据安全分类分级管理工作。建设省工业互联网安全态势感知监测平台，加强企业网络安全设备更新改造，推动部署企业级工业互联网安全监测平台。加快建设国家网络安全产业园区（长沙），培育工业领域网络和数据安全服务机构资源池，打造网络和数据安全产业新高地。"},{"no":"三","title":"支持措施","text":"（一）支持开展评估诊断。支持各市州以政府购买服务的方式，组织服务商对具有数字化转型意向的工业企业开展诊断服务，省级财政对各市州购买诊断服务费用给予补贴，每家企业不超过2万元，已获得中小企业数字化转型城市试点资金支持的企业不重复纳入评估诊断。\n\n（二）支持人工智能创新应用。推动新型研发机构、软件企业研发算法产品和数据产品，对具有自主知识产权、满足企业数字化转型需求并推广应用的优秀算法产品、数据产品和人工智能高质量数据集，按项目投资额的20%给予支持，最高不超过100万元。支持通用大模型、行业大模型以及通用人工智能其他路径探索的应用研究，对通过国家网信办备案的生成式人工智能大模型、国家人工智能揭榜挂帅优胜单位，按项目投资额的30%给予支持，最高不超过300万元；对获评省级人工智能终端产品、省级人工智能大模型的单位，按项目投资额的20%给予支持，最高不超过100万元。推进人工智能赋能新型工业化，对获评省级人工智能赋能新型工业化典型应用场景的企业，按项目投资额的20%给予支持，最高不超过100万元。\n\n（三）支持工业互联网创新发展。加快推动工业互联网平台建设，对获评国家级“双跨”工业互联网平台、省级工业互联网平台的企业，分别按项目投资额的30%、20%给予支持，最高不超过300万元、100万元。深化5G+工业互联网融合应用，对获评省级“5G+工业互联网”标杆工厂的企业，按项目投资额的20%给予支持，最高不超过100万元。支持工业互联网标识解析二级节点建设，对取得“互联网域名服务”许可证并投入解析服务运营的企业，按项目投资额的20%给予支持，最高不超过100万元。\n\n（四）支持建设制造业数字化转型促进中心。培育专业化服务机构，对获评国家级、省级制造业数字化转型促进中心的单位，分别按项目投资额的30%、20%给予支持，最高不超过300万元、100万元。\n\n（五）支持建设高标准数字园区。推动重点园区数字化转型，对获评国家级、省级数字园区的园区，分别按项目投资额的30%、20%给予支持，最高不超过300万元、100万元。\n\n（六）支持争创国家数字化智能化转型标杆。对获评实体经济和数字经济深度融合、制造业数字化转型、人工智能赋能新型工业化、物联网赋能行业等国家级数字化典型案例的企业，以及入选“数据要素×工业制造”等国家级赛事奖项的企业，按项目投资额的30%给予支持，最高不超过300万元。对获评卓越级智能工厂的企业，按项目投资额的30%给予支持，最高不超过300万元；对通过国家智能制造系统解决方案“揭榜挂帅”项目验收的企业，按项目投资额的30%给予支持，最高不超过300万元。\n\n省开展“智赋万企”行动工作专班办公室负责日常工作协调、调度，各地同步建立工作推进机制，研究制定具体措施，抓好重点任务落实。积极向金融机构推荐有融资需求的制造业数字化转型重点项目。组织开展供需对接会、工业互联网一体化进园区、智能制造进园区等活动。各级工业和信息化主管部门、财政部门加强对“智赋万企”行动的政策支持，及时总结工作进展和成效，培育一批标杆企业及项目，推广典型经验和模式。"},{"no":"四","title":"本方案自公布之日起实施，有效期3年","text":"本方案自公布之日起实施，有效期3年。\n相关链接：《深化“智赋万企”行动加快制造业数字化转型实施方案》政策解读\n\n一图读懂《深化“智赋万企”行动加快制造业数字化转型实施方案》\n\n收藏\n\n国家部委网站\n\n发展改革委\n\n外交部\n\n卫生健康委\n\n国防部\n\n教育部\n\n科技部\n\n工业和信息化部\n\n公安部\n\n中央纪委国家监委\n\n民政部\n\n司法部\n\n财政部\n\n人力资源和社会保障部\n\n自然资源部\n\n生态环境部\n\n住房和城乡建设部\n\n交通运输部\n\n水利部\n\n农业农村部\n\n商务部\n\n应急管理部\n\n退役军人事务部\n\n文化和旅游部\n\n人民银行\n\n审计署\n\n海关总署\n\n税务总局\n\n市场监督管理总局\n\n广电总局\n\n民航局\n\n体育总局\n\n各省工信厅网站\n\n北京市经信局\n\n天津市工信局\n\n河北省工信厅\n\n辽宁省工信厅\n\n内蒙古工信厅\n\n黑龙江省工信厅\n\n浙江省经信厅\n\n安徽省经信厅\n\n河南省工信厅\n\n广东省工信厅\n\n湖北省经信厅\n\n重庆市经信委\n\n四川省经信厅\n\n贵州省工信厅\n\n云南省工信厅\n\n甘肃省工信厅\n\n陕西省工信厅\n\n宁夏工信厅\n\n青海省工信厅\n\n山西省工信厅\n\n吉林省工信厅\n\n上海市经信委\n\n江苏省工信厅\n\n福建省工信厅\n\n江西省工信厅\n\n山东省工信厅\n\n海南省工信厅\n\n广西工信厅\n\n新疆工信厅\n\n西藏经信厅\n\n各市州工信局网站\n\n长沙市工信局\n\n衡阳市工信局\n\n株洲市工信局\n\n湘潭市工信局\n\n邵阳市工信局\n\n岳阳市工信局\n\n常德市工信局\n\n张家界市工信局\n\n益阳市工信局\n\n郴州市工信局\n\n永州市工信局\n\n怀化市工信局\n\n娄底市工信局\n\n湘西州工信局\n\n直属机构\n\n湖南兵器工业高级技工学校\n\n中南工业学校\n\n湖南省汽车技师学院\n\n湖南省散装水泥和墙体材料改革办公室\n\n湖南无线电管理\n\n湖南省工业通信业节能监察中心\n\n湖南省电子信息产业研究院\n\n湖南省计算机软件资格考试办公室\n\n湖南省国防科技工业局技术开发中心\n\n网站地图"}],"interpretations":[{"sectionNo":"三","headline":"数字化转型诊断服务，每家企业最高补2万元","who":"各市州以政府购买服务方式组织服务商，为有转型意向的工业企业开展诊断；已获中小企业数字化转型城市试点资金支持的企业不重复纳入。","materials":[],"window":"按年度组织，省级财政对各市州购买诊断服务费用给予补贴。","where":"市州工信部门（组织购买服务），省级财政补贴。","tip":"补的是市州买服务的钱，不是直接发给企业；每家企业补贴上限2万元。"},{"sectionNo":"三","headline":"大模型按投资额30%补、最高300万元，其他应用补20%","who":"研发优秀算法产品、数据产品、高质量数据集的企业；通过国家网信办备案的生成式人工智能大模型、国家人工智能揭榜挂帅优胜单位；获评省级人工智能终端产品、省级人工智能大模型、省级人工智能赋能新型工业化典型应用场景的企业。","materials":[],"window":"按年度项目申报安排，由省工信厅另行发文组织。","where":"省工信厅项目管理系统申报。","tip":"支持比例分档：备案大模型/揭榜挂帅按30%、最高300万元；算法产品、数据产品、省级终端与大模型、典型应用场景按20%、最高100万元。"},{"sectionNo":"三","headline":"工业互联网平台：国家级补30%最高300万，省级补20%最高100万","who":"获评国家级「双跨」工业互联网平台、省级工业互联网平台的企业；获评省级「5G+工业互联网」标杆工厂的企业；取得「互联网域名服务」许可证并投入解析服务运营的标识解析二级节点企业。","materials":[],"window":"按年度项目申报安排。","where":"省工信厅项目管理系统。","tip":"标杆工厂和标识解析节点都是按投资额20%、最高100万元；制造业数字化转型促进中心、高标准数字园区执行同样的国家级30%/省级20%分档。"},{"sectionNo":"二","headline":"工业企业可参与算力、5G专网、标杆工厂、智能工厂建设","who":"工业企业，包括重点产业链（集群）企业、链主企业、供应链龙头企业、工业园区内企业；省级及以上专精特新企业、规模以上工业企业纳入数字化转型基础和需求“建档立卡”；建设智算中心、5G独立专网、智能工厂、智能制造生产线（车间）的制造业企业均可参与。","materials":[],"window":"每年培育一批省级制造业数字化转型标杆项目、“5G+工业互联网”标杆工厂；建档立卡后实行动态评估和监测；原文未列具体申报截止日期。","where":"全省算力调度和综合管理平台；省级制造业数字化转型生态供给资源池。","tip":"“点线面”分类推进，标杆项目、标杆工厂按年度培育；本条款只列任务方向，未明确申报门槛与补助标准，资金支持见“支持措施”。"}],"sourceUrl":"https://gxt.hunan.gov.cn/gxt/xxgk_71033/tzgg/202509/t20250912_33802671.html","sourceNote":"湖南省工信厅官网公开正文。有效期3年自2025-09-03公布日起算，到期日2028-09-02为推算。；2026-11-08 核对：页面发布日期 2025-09-12；2026-11-09 条文按官方原文重切（4 条，自查召回 100%）","verified":true,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"hy-culture-tourism-2026","title":"衡阳市人民政府办公室关于印发《衡阳市促进文化创意旅游产业高质量发展六条措施》的通知","level":"city","region":"衡阳市","issuer":"衡阳市人民政府办公室","documentNo":"衡政办发〔2026〕8号","publishedAt":"2026-03-27","effectiveAt":"2026-01-01","expiresAt":"2028-12-31","status":"active","tags":["财政奖补","认定资质"],"audience":["演艺与赛事主办企业","旅行社","景区与度假区运营企业","旅游饭店","旅游商品经营企业"],"summary":"对大型演唱会每场最高奖励100万元、音乐节艺术节最高30万元、体育赛事最高20万元；旅行社“引客入衡”每家每年最高300万元；新评5A级景区、五星级饭店各奖励600万元；新评文旅消费新场景奖励5万至20万元，有效期3年。","sections":[{"no":"一（一）","title":"大型演唱会","text":"单场售票观众达2.5万人（含）以上的，根据演出层级、规模、带动旅游和促进消费等效果，每场给予不超过100万元的奖励。同一市场主体在同一年度内，举办2个（含）以上演唱会且达到奖励条件的，自第2个起按10%比例递增奖励金额。"},{"no":"二","title":"支持“引客入衡”","text":"对于单个旅行社从衡阳市外招徕游客，游览两个以上文旅消费项目（含景区门票、演出票、赛事票、游船票、摩天轮票、团队讲解服务费等）的，可申报人数奖、交通补助奖和新客源市场开拓奖。每家旅行社每年奖励总金额不超过300万元。"},{"no":"三（一）","title":"景区（度假区）品牌创建","text":"新评为国家5A级、4A级景区分别奖励600万元、100万元；新评为国家级、省级旅游度假区分别奖励300万元、50万元。"},{"no":"三（二）","title":"住宿品牌创建","text":"新评为五星级、四星级旅游饭店的，分别奖励600万元、60万元。"},{"no":"六","title":"支持发展旅游商品（购物）","text":"对于在城区文旅消费集聚区、休闲街区、游客集散中心、A级景区、旅游度假区、乡村旅游区等旅游场所辐射范围内，投资新建综合性旅游购物场所的企业，店内以销售衡阳特产、文创产品等旅游商品为主，商场店招及店内风格装饰体现衡阳文化旅游元素的，可给予不超过30万元的奖励。"}],"interpretations":[{"sectionNo":"一（一）","headline":"单场售票观众2.5万人以上，每场最高奖100万元","who":"在衡阳市举办大型演唱会的市场主体；单场售票观众达2.5万人（含）以上；奖励按演出层级、规模、带动旅游和促进消费等效果评定。","materials":[],"window":"按年度申报；同一市场主体同一年度内举办2个（含）以上且达到奖励条件的，自第2个起按10%比例递增奖励金额。","where":"衡阳市（属地申报，原文未列具体受理窗口）","tip":"100万元是每场奖励上限，实际额度按演出层级、规模、带动旅游和促进消费效果评定；同一年度第2场起才按10%递增。"},{"sectionNo":"二","headline":"旅行社从市外招徕游客游览两个以上文旅项目，可申报三项奖","who":"单个旅行社；从衡阳市外招徕游客；行程游览两个以上文旅消费项目（含景区门票、演出票、赛事票、游船票、摩天轮票、团队讲解服务费等）。","materials":[],"window":"按年度申报；每家旅行社每年奖励总金额不超过300万元。","where":"衡阳市（属地申报，原文未列具体受理窗口）","tip":"人数奖、交通补助奖、新客源市场开拓奖可一并申报，但每家旅行社每年合计不超过300万元；游览项目须在两个以上。"},{"sectionNo":"三（一）","headline":"新评5A级景区奖600万元，国家级度假区奖300万元","who":"新评为国家5A级、4A级景区，或新评为国家级、省级旅游度假区的创建主体。","materials":[],"window":"按年度奖励，原文未列申报起止时间。","where":"衡阳市（属地申报，原文未列具体受理窗口）","tip":"按最终评定档次对应奖励：5A级600万元、4A级100万元、国家级度假区300万元、省级度假区50万元，不同品牌不重复套档。"},{"sectionNo":"三（二）","headline":"新评五星级旅游饭店奖600万元，四星级奖60万元","who":"新评为五星级、四星级旅游饭店的住宿经营主体。","materials":[],"window":"按年度奖励，原文未列申报起止时间。","where":"衡阳市（属地申报，原文未列具体受理窗口）","tip":"按最终评定星级对应奖励，五星级600万元、四星级60万元，须为“新评”而非复核保留星级。"},{"sectionNo":"六","headline":"新建综合性旅游购物场所，最高奖30万元","who":"在城区文旅消费集聚区、休闲街区、游客集散中心、A级景区、旅游度假区、乡村旅游区等旅游场所辐射范围内投资新建综合性旅游购物场所的企业；店内以销售衡阳特产、文创产品等旅游商品为主；商场店招及店内风格装饰体现衡阳文化旅游元素。","materials":[],"window":"按年度申报，原文未列申报起止时间。","where":"衡阳市（属地申报，原文未列具体受理窗口）","tip":"30万元是上限；须同时满足选址在旅游场所辐射范围内、以销售衡阳特产和文创产品为主、店招与店内风格体现衡阳文化旅游元素三项条件。"}],"sourceUrl":"https://www.hyyfq.gov.cn/zwgk/bmxxgkml/qzfzcbm/zfb/zcwj/20260527/i3908372.html","sourceNote":"2026-11-22 取自衡阳市雁峰区人民政府门户「政务公开—部门信息公开目录—区政府组成部门—政府办—政策文件」转载的市政府办文件原文，版头载文号衡政办发〔2026〕8号，成文日期2026年3月27日。本机直连 hyyfq.gov.cn 与 hengyang.gov.cn 均被站点防护拦截（HTTP 412），改用工具端读取原文页全文，条文未与本地抓取文件比对。日期口径：publishedAt 取版头成文日期2026-03-27；原文末条明示“自2026年1月1日起施行”，属追溯施行，故 effectiveAt 为2026-01-01，早于成文日期。 2026-11-22 收录：官方页面未能打开或不是正文（fetch/html），条文未与原文比对。 有效期依据：正文末条明示“自2026年1月1日起施行，有效期3年”，计至2028年12月31日","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"unverifiable","hunan":true},{"id":"hy-mfg-2024-21","title":"衡阳市人民政府办公室印发《关于全面落实“三高四新”美好蓝图推动制造业高质量发展的若干支持政策（试行）》的通知","level":"city","region":"衡阳市","issuer":"衡阳市人民政府办公室","documentNo":"衡政办发〔2024〕21号","publishedAt":"2024-11-05","effectiveAt":null,"expiresAt":"2026-02-12","status":"expired","tags":["财政奖补","数字化转型","认定资质"],"audience":["衡阳市制造业企业","倍增培育企业"],"summary":"试行版制造业支持政策：设备投资500万元以上按年基准利率50%贴息、单个企业最高100万元；数字化改造按60%贴息、最高60万元。","sections":[{"no":"1","title":"支持设备更新和技术改造","text":"倍增培育企业实施技术改造项目，当年设备投资达到500万元以上的，其设备购置贷款按照年基准利率的50%予以一年贴息，单个企业贴息最高限额100万元（企业已争取国省或其他贴息的，补助金额不超过实际负担利息）。"},{"no":"1续","title":"智能制造奖励","text":"对国家智能制造示范工厂揭榜单位、优秀场景、系统解决方案“揭榜挂帅”企业给予20万元奖励。对新认定的省级智能制造标杆企业、省级智能制造标杆车间分别给予10万元、5万元奖励。"},{"no":"2","title":"加快“智转数改”步伐","text":"对符合条件的数字化转型升级项目，年度投资在200万元以上的，单个企业按照年基准利率的60%予以一年贴息补助，最高可补助60万元（补助金额不超过实际负担利息，技改设备贷款贴息、数字化转型升级项目贴息原则上不重复享受）。"}],"interpretations":[{"sectionNo":"1","headline":"倍增培育企业设备贷款贴息50%，最高100万元","who":"衡阳市倍增培育企业；须实施技术改造项目，且当年设备投资达到500万元以上；已争取国省或其他贴息的企业仍在范围内，但补助金额不超过实际负担利息。","materials":[],"window":"贴息期限一年，按当年设备投资额核算；原文未写申报起止时间。","where":"原文未指定受理部门或线上申报系统。","tip":"企业已争取国省或其他贴息的，补助金额不超过实际负担利息；单个企业贴息最高限额100万元。"},{"sectionNo":"1续","headline":"智能制造国家级揭榜单位奖20万元，省级标杆企业10万元","who":"国家智能制造示范工厂揭榜单位、智能制造优秀场景、系统解决方案“揭榜挂帅”企业；新认定的省级智能制造标杆企业、省级智能制造标杆车间。","materials":[],"window":"以获评、新认定为条件；原文未写申报起止时间与兑现频次。","where":"原文未指定受理部门或线上申报系统。","tip":"国家级奖励20万元；省级标杆企业10万元、省级标杆车间5万元；省级奖励只给“新认定”的标杆，已认定过的不在本条范围。"},{"sectionNo":"2","headline":"数字化改造项目年投资超200万元，贴息60%最高60万元","who":"衡阳市符合条件的数字化转型升级项目承担企业；年度投资在200万元以上；补助金额不超过实际负担利息。","materials":[],"window":"贴息期限一年，按年度投资额核算；原文未写申报起止时间。","where":"原文未指定受理部门或线上申报系统。","tip":"技改设备贷款贴息与数字化转型升级项目贴息原则上不重复享受；补助金额不超过实际负担利息，最高60万元。"}],"sourceUrl":"https://www.hengyang.gov.cn/xxgk/fgwj/gfxwj/20241129/i3526270.html","sourceNote":"2026-11-21 取自衡阳市政府门户「规范性文件」原文页；文号、成文日期已核对。该试行文件已由衡政发〔2026〕1号同类事项新政策接续，旧文件判失效并保留对照。 2026-11-21 收录：官方页面未能打开或不是正文（fetch/html），条文未与原文比对。 有效期依据：被衡政发〔2026〕1号同类事项新政策替代，替代生效日（2026-02-13）为旧政策效力终点","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"unverifiable","hunan":true},{"id":"ld-bizenv-2022-3","title":"娄底市人民政府关于印发《娄底市进一步优化营商环境促进市场主体高质量发展实施方案（2022—2025）》的通知","level":"city","region":"娄底市","issuer":"娄底市人民政府","documentNo":"娄政发〔2022〕3号","publishedAt":"2022-03-29","effectiveAt":null,"expiresAt":"2025-12-31","status":"expired","tags":["营商环境","上市培育","认定资质"],"audience":["娄底市市场主体","拟上市企业","先进制造业企业","科技型企业"],"summary":"建立“科企—高企—小巨人—上市领军型”企业梯度培育体系，开辟企业上市“绿色通道”，围绕“材料谷”推进10条工业新兴优势产业链建设。","sections":[{"no":"18","title":"支持企业上市融资","text":"抓住资本市场改革机遇，积极引进私募股权投资基金等成立产业转型发展股权投资引导基金，通过股权、债权或股债结合的方式投资（或参股）拟上市企业。进一步优化企业上市服务，开辟“绿色通道”，着力构建服务企业发展的资本市场生态系统。"},{"no":"19","title":"提升先进制造业核心竞争力","text":"围绕建设娄底“材料谷”，谋划推进一批重大产业项目，以项目大建设推动先进制造业大发展。充分发挥钢铁新材和工程机械两大产业的引擎作用，统筹推进10条工业新兴优势产业链建设，不断推动形成产业集聚、产业集群、产业生态。"},{"no":"20","title":"推动创新主体增量提质","text":"强化企业创新主体地位，建立“科企—高企—小巨人—上市领军型”企业梯度培育体系，完善市级工程技术研究中心建设体系，支持各类企业申报科技计划项目。开展关键核心技术攻关，继续推行“揭榜挂帅”，引导创新要素向企业聚集。"}],"interpretations":[{"sectionNo":"18","headline":"拟上市企业可引入私募股权基金，上市走绿色通道","who":"娄底市拟上市企业；通过股权、债权或股债结合方式引入私募股权投资基金等投资，并可走企业上市服务“绿色通道”。","materials":[],"window":"实施方案执行期内持续推进，未设集中申报期。","where":"产业转型发展股权投资引导基金；企业上市服务“绿色通道”","tip":"引导基金以股权、债权或股债结合方式投资（或参股）拟上市企业，属股权投资而非财政补贴。"},{"sectionNo":"20","headline":"企业可申报科技计划项目，关键技术攻关推行揭榜挂帅","who":"娄底市各类企业；纳入“科企—高企—小巨人—上市领军型”企业梯度培育体系，可申报科技计划项目、参与关键核心技术攻关与“揭榜挂帅”。","materials":[],"window":"按科技计划项目申报与“揭榜挂帅”榜单发布安排推进。","where":"市级工程技术研究中心；科技计划项目；“揭榜挂帅”","tip":"梯度培育按“科企—高企—小巨人—上市领军型”逐级推进，关键核心技术攻关以“揭榜挂帅”方式组织。"}],"sourceUrl":"https://www.hnloudi.gov.cn/loudi/xybBusinessMap/c103669/202311/d37a65b155774b348cf466b20e842376.shtml","sourceNote":"2026-11-21 取自娄底市政府门户原文页；文号娄政发〔2022〕3号与条款逐字核对。页面未显示成文日期，按标题适用期判失效。 2026-11-21 收录：与官方页面逐句比对，命中 6/6 句（100%），关卡判定「verbatim」。 有效期依据：按文件标题载明的适用期限判定（2022—2025年），基准日已过 2026-11-21 补录：publishedAt 据官方页面版头/落款核对后填入。","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"ld-gxj-fund-2026","title":"娄底市工业和信息化局 娄底市财政局关于印发《娄底市先进制造业高地建设专项资金管理办法》的通知","level":"city","region":"娄底市","issuer":"娄底市工业和信息化局、娄底市财政局","documentNo":"娄工信投资〔2026〕116号","publishedAt":"2026-11-04","effectiveAt":"2026-11-04","expiresAt":"2031-11-04","status":"active","tags":["专项资金","财政奖补"],"audience":["先进制造业企业","软件和信息技术服务企业","中小企业公共服务平台","技术改造项目单位"],"summary":"设立市级先进制造业高地建设专项资金，采取直接补助、以奖代补方式，支持工业转型升级技改项目、软件开发及互联网服务、数字赋能项目、公共服务平台等；项目公示5个工作日，补助超50万元须验收，有效期5年。","sections":[{"no":"五（二）","title":"工信领域项目发展","text":"（二）工信领域项目发展。主要支持先进制造业发展、重点产业链延链补链强链等工信领域重点项目，推动工业转型升级的企业技术改造项目、软件开发及互联网服务项目、数字赋能项目等。"},{"no":"五（三）","title":"工信领域公共服务平台","text":"（三）工信领域公共服务平台。服务于我市工信领域的中小企业公共服务平台、中小企业核心服务机构等公共服务平台（机构）。"},{"no":"五（四）","title":"推动工业产业发展壮大","text":"（四）推动工业产业发展壮大。支持县市区培育壮大工业企业，推动产业集群发展，根据企业培育及集群发展相关工作完成情况进行综合评价给予支持。"},{"no":"六","title":"支持方式","text":"专项资金支持主要采取直接补助、以奖代补等方式。"},{"no":"七1","title":"支持条件（一）","text":"1.项目单位具有独立法人资格，具有良好的信用，积极配合财政、工信等部门工作，属于先进制造业、互联网及相关服务、软件和信息技术服务领域合法经营的企业；"},{"no":"七2","title":"支持条件（二）","text":"2.项目符合国家法律法规、产业政策和有关规划，技术较先进，具有较好的市场前景和良好的经济社会效益；"},{"no":"七3","title":"支持条件（三）","text":"3.项目实施单位近3年未发生重大安全生产事故、重大生态环境违法事件、重大产品质量安全事故、数据安全事件等其他严重问题；企业、法定代表人无正在生效的重大刑事犯罪记录，未被列入信用湖南网失信名单；"},{"no":"七4","title":"支持条件（四）","text":"4.申报通知明确的其他条件。"},{"no":"十八","title":"验收管理","text":"获得补助资金超过50万元（含50万元）的项目实行验收管理，由市工信局和市财政局共同组织验收。未完成项目验收的单位，不得再次申报专项资金补助类项目。市委、市政府有明确要求的从其规定。"}],"interpretations":[{"sectionNo":"五（二）","headline":"专项资金投向技改、软件开发、数字赋能等工信项目","who":"在我市实施先进制造业、重点产业链延链补链强链等工信领域重点项目的企业，含工业转型升级技术改造项目、软件开发及互联网服务项目、数字赋能项目的实施单位。","materials":[],"window":"按专项资金年度申报通知组织，原文未设固定申报期。","where":"市工信局、市财政局；本条为工信领域重点项目资金投向（原文未列申报窗口）","tip":"支持范围限于工信领域重点项目，技改、软件开发及互联网服务、数字赋能三类在列；本条未明确具体补助额度。"},{"sectionNo":"五（三）","headline":"服务工信领域的中小企业公共服务平台、核心服务机构可获支持","who":"服务于我市工信领域的中小企业公共服务平台、中小企业核心服务机构等公共服务平台（机构）。","materials":[],"window":"按专项资金年度申报通知组织，原文未设固定申报期。","where":"市工信局、市财政局；本条为公共服务平台支持方向（原文未列申报窗口）","tip":"支持对象是平台（机构）而非单个企业；须“服务于我市工信领域”，跨区域平台不在本条范围。"},{"sectionNo":"五（四）","headline":"县市区培育工业企业、发展产业集群可获综合评价支持","who":"承担工业企业培育壮大、产业集群发展工作的县市区；支持依据是企业培育及集群发展相关工作完成情况的综合评价结果。","materials":[],"window":"按年度综合评价组织，原文未设固定申报期。","where":"市工信局、市财政局；本条为县市区培育与集群发展支持方向（原文未列申报窗口）","tip":"本条不支持单个企业直接申报，支持对象是县市区的培育与集群工作，额度取决于综合评价结果。"},{"sectionNo":"七1","headline":"申报须独立法人、信用良好，且属先进制造等三领域","who":"具有独立法人资格、信用良好、积极配合财政和工信等部门工作，且属于先进制造业、互联网及相关服务、软件和信息技术服务领域合法经营的企业。","materials":[],"window":"按专项资金年度申报通知组织，原文未设固定申报期。","where":"市工信局、市财政局（申报须配合财政、工信等部门工作）","tip":"主体资格是硬门槛：独立法人、良好信用、三大领域合法经营三项同时具备；非独立法人的分支机构不在范围。"},{"sectionNo":"七2","headline":"项目须合规、技术较先进、市场前景好方可申报","who":"申报专项资金的项目单位；项目须符合国家法律法规、产业政策和有关规划，技术较先进，并具有较好的市场前景和良好的经济社会效益。","materials":[],"window":"按专项资金年度申报通知组织，原文未设固定申报期。","where":"市工信局、市财政局；本条为项目质量门槛（原文未列申报窗口）","tip":"本条是项目质量门槛，四项同时满足：合法合规、符合产业政策与规划、技术较先进、市场前景与效益较好；原文未设量化分数线。"},{"sectionNo":"七3","headline":"近3年无重大事故、法人无犯罪记录且不在失信名单","who":"项目实施单位须近3年未发生重大安全生产事故、重大生态环境违法事件、重大产品质量安全事故、数据安全事件等其他严重问题；企业及其法定代表人无正在生效的重大刑事犯罪记录，且未被列入信用湖南网失信名单。","materials":[],"window":"以近3年为考察期；按专项资金年度申报通知组织。","where":"市工信局、市财政局；失信情况核查“信用湖南网”","tip":"考察期是近3年，且同时查企业与法定代表人；有一项重大事故、生效犯罪记录或失信名单记录即不符合条件。"},{"sectionNo":"十八","headline":"补助超50万元须验收，未验收不得再申报","who":"获得专项资金补助资金超过50万元（含50万元）的项目实施单位；未完成项目验收的单位不得再次申报补助类项目。","materials":[],"window":"获补助50万元以上（含）即纳入验收管理；项目完成后由两局共同组织验收。","where":"市工信局、市财政局共同组织验收","tip":"50万元是验收管理分界线（含50万元）；未完成验收将被限制再次申报补助类项目，市委、市政府有明确要求的从其规定。"}],"sourceUrl":"http://www.hnloudi.gov.cn/loudi/040404/202611/a77cf7552d8745d995dcac966c641e1d.shtml","sourceNote":"2026-11-22 取自娄底市人民政府门户「政务公开—市政府信息公开—文件库—市直部门规范性文件」原文页，版头载文号娄工信投资〔2026〕116号、统一登记号 LDCR-2026-03001，生效日期与失效日期栏目齐全。 2026-11-22 收录：与官方页面逐句比对，命中 12/12 句（100%），关卡判定「verbatim」。 有效期依据：第二十二条明示“有效期五年”；页面栏目载生效日期2026-11-04、失效日期2031-11-04","verified":false,"isSample":false,"numberStyle":"clause","bodyVerified":"verbatim","hunan":true},{"id":"ld-industry-2016-19","title":"娄底市人民政府关于印发《娄底市帮扶工业企业十五条》的通知","level":"city","region":"娄底市","issuer":"娄底市人民政府","documentNo":"娄政发〔2016〕19号","publishedAt":"2016-11-29","effectiveAt":null,"expiresAt":"2021-11-28","status":"expired","tags":["财政奖补","融资支持"],"audience":["税收解缴关系在娄底市的园区内工业企业","中小工业企业","龙头企业"],"summary":"市财政设50亿元工业产业基金、每年安排1亿元工业转型发展引导资金；新增流动资金贷款按0.5%—1%贴息，单户贴息总额不超过40万元。","sections":[{"no":"一","title":"加大财政扶持力度","text":"市财政设立50亿元的工业产业基金。在整合现有涉工专项资金的基础上，每年安排1亿元工业转型发展引导资金，对产业发展、企业融资、创新创优等进行奖励和补助。"},{"no":"二","title":"加大金融支持力度","text":"对战略性新兴产业工业企业当年内新增流动资金银行贷款的，由受益财政按照新增流动资金贷款额的0.5%—1%给予财政贴息，单户企业贴息总额不超过40万元。"},{"no":"三","title":"推动全产业链发展","text":"对年销售收入超5亿元的龙头企业，每增加1户与其发生开票销售收入500万元以上的市内配套企业，由受益财政奖励龙头企业10万元，奖励总额最高不超过50万元。"},{"no":"二(续)","title":"支持企业股改上市","text":"支持工业企业股改，鼓励企业上市融资、股权融资，在省人民政府给予奖励的基础上，受益财政给予等额奖励。"}],"interpretations":[{"sectionNo":"一","headline":"市财政设50亿元工业产业基金，每年再拿1亿元引导资金","who":"娄底市范围内涉及产业发展、企业融资、创新创优的工业企业；资金由市财政涉工专项资金与每年1亿元工业转型发展引导资金安排。","materials":[],"window":"每年安排1亿元工业转型发展引导资金；基金与引导资金按年度预算安排。","where":"市财政（工业产业基金、工业转型发展引导资金）","tip":"50亿元是工业产业基金总规模，1亿元是每年的引导资金额度，两笔资金口径不同，不可混用。"},{"sectionNo":"二","headline":"战略性新兴产业企业新增流贷贴息0.5%—1%，单户最高40万","who":"娄底市战略性新兴产业工业企业，当年内新增流动资金银行贷款；由受益财政按新增流动资金贷款额的0.5%—1%贴息，单户贴息总额不超过40万元。","materials":[],"window":"按当年内新增流动资金贷款额计算，单户贴息总额不超过40万元。","where":"受益财政","tip":"贴息按新增流动资金贷款额的0.5%—1%计算，单户封顶40万元，超过部分不再贴息。"},{"sectionNo":"三","headline":"龙头企业每新增1户市内配套企业奖10万元，累计最高50万","who":"年销售收入超5亿元的娄底市龙头企业；每增加1户与其发生开票销售收入500万元以上的市内配套企业，由受益财政奖励10万元，奖励总额最高不超过50万元。","materials":[],"window":"按新增市内配套企业户数计算，单户龙头企业奖励总额最高50万元。","where":"受益财政","tip":"配套企业须与龙头企业发生500万元以上开票销售收入才算1户，奖励总额封顶50万元。"},{"sectionNo":"二(续)","headline":"工业企业股改上市，在省奖励基础上受益财政等额再奖","who":"在娄底市进行股份制改造、上市融资或股权融资的工业企业；在省人民政府给予奖励的基础上，由受益财政给予等额奖励。","materials":[],"window":"以省人民政府奖励为基数等额配套，无单独申报期。","where":"受益财政","tip":"等额奖励以省人民政府奖励为基数，省里未奖励则无等额配套；仅限工业企业的股改、上市融资、股权融资。"}],"sourceUrl":"https://www.hnloudi.gov.cn/loudi/0402/201612/b48e883c10df4f878c9d3abe2b867ce5.shtml","sourceNote":"2026-11-21 取自娄底市政府门户原文页；文号娄政发〔2016〕19号、登记号 LDCR—2016—00021、成文日期2016年11月29日与条款逐字核对。按5年有效期推算已过期，判失效。 2026-11-21 收录：与官方页面逐句比对，命中 5/5 句（100%），关卡判定「verbatim」。 有效期依据：按行政规范性文件一般不超5年推算（2016-11-29发布，推算至2021-11-28）","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"ld-material-2024-3","title":"娄底市人民政府关于印发《〈娄底市促进先进材料产业发展若干规定〉实施方案》的通知","level":"city","region":"娄底市","issuer":"娄底市人民政府","documentNo":"娄政发〔2024〕3号","publishedAt":"2024-02-07","effectiveAt":"2024-02-06","expiresAt":null,"status":"active","tags":["场地支持","财政奖补","人才政策"],"audience":["娄底市先进材料产业企业","钢铁新材与工程机械产业链企业","产业园区"],"summary":"《娄底市促进先进材料产业发展若干规定》的实施方案，从加强教育宣传、完善配套措施（规划政策、产业布局、园区建设、招商引资、用地、人才、资金、融资、公共服务、科技创新、质量监管、开放合作十二项）、落实监管措施三方面细化任务；资金支持上明确“根据实际情况安排先进材料产业发展资金，建立健全以财政贴息、事后奖补为主的激励型财政支持机制”，对重大专项、产业基金、重大科研和产业项目落户给予配套支持，用地提容不增收土地价款；未列具体奖补金额或比例，科技创新奖励补助办法另行制定；自发布之日起施行，原文未设有效期条款。","sections":[{"no":"一","title":"一、加强教育宣传，营造《规定》实施良好氛围","text":"（一）将《规定》作为干部理论学习、党委（党组）理论学习中心组学习、干部培训的重要内容，切实增强各级领导干部运用法治思维和法治方式开展工作的本领。充分利用省、市、县各类主流媒体进行深入宣传，引导社会各界各层次学习《规定》、熟悉《规定》、用好《规定》。（责任单位：市发改委、市委宣传部、娄底日报社、市广播电视台；市政府各工作部门；各县市区人民政府、娄底经开区管委会；以下责任单位均包括各县市区人民政府，娄底经开区管委会，不再列出）（二）加强宣传引导。全市各级各单位要落实“谁执法谁普法”的普法责任制，结合实际制订宣传方案，采取多种形式开展宣传教育，组织开展集中宣传活动，推动《规定》宣传进园区、进企业、进机关、进协会，强化法治意识。"},{"no":"二","title":"二、完善配套措施，推动《规定》深入贯彻落实（一）健全规划政策体系","text":"把先进材料产业发展纳入市国民经济和社会发展规划；组织编制硅钢、电子陶瓷等先进材料产业发展专项规划；建立健全先进材料产业促进工作机制，协调解决先进材料产业发展中的重大问题。制定我市先进材料产业目录并向社会公布。（责任单位：市发改委、市工信局、市商务局等市直相关单位）"},{"no":"三","title":"（二）统筹先进材料产业布局","text":"建立先进材料产业集群梯次培育体系，争取国家、省先进材料重大项目在本市落户，推动先进材料中的短板产业补链、优势产业延链、传统产业升链、新兴产业建链。（责任单位：市发改委、市工信局、市商务局、市国资委）"},{"no":"四","title":"（三）加强先进材料产业园区建设","text":"优化资源配置，完善支持政策，建立产业服务平台，推动产业园区专业化、集约化、差异化、数字化、绿色化发展。（责任单位：市发改委，各产业园区）"},{"no":"五","title":"（四）加大招商引资力度","text":"制定并适时优化先进材料产业招商引资政策，建立健全守信践诺和招商项目跟踪服务机制，加大先进材料产业链定向招商引资力度，促进先进材料产业集聚发展。（责任单位：市商务局、市财政局）"},{"no":"六","title":"（五）强化用地保障","text":"为先进材料产业项目优先提供用地保障，对符合规划、不改变用途的现有工业用地提高土地利用率和增加容积率的，不增收土地价款。（责任单位：市自然资源和规划局）"},{"no":"七","title":"（六）强化人才支持","text":"加强先进材料产业人才需求摸底，支持先进材料企业引进专业人才，支持高等学校、职业教育院校和各类职业技能培训机构根据先进材料产业发展需要培养专业人才。（责任单位：市委人才办、市人社局、市教育局）对先进材料产业人才居留落户、职称评定、住房保障、社会保险、医疗保健、配偶就业、子女入学等方面明确具体支持措施。（责任单位：市委人才办牵头，市教育局、市公安局、市人社局、市住建局、市卫健委、市医保局等单位配合）建立先进材料产业专家库，发挥专业智囊作用。（责任单位：市委人才办、市人社局、市科技局、市工信局）"},{"no":"八","title":"（七）加强资金支持","text":"根据实际情况安排先进材料产业发展资金，建立健全以财政贴息、事后奖补为主的激励型财政支持机制。对国家和省重大专项、扶持政策、产业基金、重大科研、重大产业项目落户本市，按照规定提供配套政策支持。（责任单位：市财政局牵头，市直有关部门配合）"},{"no":"九","title":"（八）加强融资保障","text":"建立融资风险补偿机制；制定金融机构促进先进材料产业发展的贡献度评估激励办法，引导金融机构积极发展先进材料产业链供应链金融、科创金融和绿色金融，开发和创新适合先进材料产业发展的金融产品和服务。鼓励和引导相关产业投资基金支持先进材料产业发展。（责任单位：市政府金融办牵头，市财政局、人民银行娄底市分行、国家金融监管总局娄底分局配合）"},{"no":"十","title":"（九）提升公共服务","text":"加强供水、供电、供气等公共服务的供给和监管。供水、供电、供气等公用企事业单位应当为企业提供优质服务，不得随意停水停电停气，不得强迫企业接受不合理的服务条件，不得以任何名义收取不合理费用。（责任单位：市发改委、市住建局、国网娄底供电分公司、市水业有限责任公司、娄底华润燃气有限公司）"},{"no":"十一","title":"（十）加强科技创新","text":"加强以先进材料企业为主体、市场为导向、产学研相结合的技术创新体系建设，健全稳定的投入机制，引导各类市场主体技术创新，对取得重大攻关突破并实现成果转化应用的给予奖励或者补助。制定具体奖励和补助办法。（责任单位：市科技局牵头，市财政局配合）争取国家和省先进材料重点实验室、工程研究中心、企业技术中心、新型研发机构等重大科技创新平台在本市落户或者设立分支机构；支持本市先进材料科研院所、技术研发中心等创新平台创建和优化升级。（责任单位：市发改委、市教育局、市科技局、市工信局）"},{"no":"十二","title":"（十一）加强质量监管","text":"健全完善先进材料产业质量监管体系，建立先进材料品牌激励机制，引导先进材料企业加强品牌培育和宣传推介，增强先进材料产业综合竞争力。（责任单位：市市场监管局）"},{"no":"十三","title":"（十二）加强开放合作","text":"通过展览会、技术交流会等平台，促进先进材料企业加强国内国际交流合作。鼓励和支持先进材料产业行业协会搭建产业发展交流平台，开展经贸洽谈、投资合作、专业论坛等交流合作活动。（责任单位：市商务局牵头，市工商联、市侨联、市贸促会等单位配合）鼓励和支持本市先进材料产业集群与其他地区的优势产业集群建立产业联盟，加强产业链供应链合作。（责任单位：各产业园区）"},{"no":"十四","title":"三、落实监管措施，有力促进先进材料产业发展","text":"（一）依法保护先进材料企业和企业家合法权益。（责任单位：市发改委、市市场监管局等市直相关单位）（二）任何单位和个人不得违法干预企业的正常生产经营活动。（责任单位：市发改委牵头，市应急管理局、市市场监管局、市税务局等相关单位配合）（三）国家公职人员在促进先进材料产业发展工作中滥用职权、玩忽职守的，依纪依法依规予以处理；涉嫌犯罪的，移送司法机关依法追究刑事责任。（责任单位：市直相关部门单位）（四）对涉及促进先进材料产业发展的规章、规范性文件进行清理，与《规定》不一致的及时修改或者废止。（责任单位：市司法局、市发改委等市直相关单位）（五）《规定》施行满一年之日起六十日内，向市人大常委会报告施行情况。（责任单位：市发改委）（六）强化监督实施。建立健全执法联动机制，加强《规定》施行情况的监督检查，及时发现并依法查处违法违规行为。全市各级各部门要把认真贯彻落实《规定》作为一项重要任务，切实履职、压实责任，根据职责分工，细化工作任务，制定配套措施和具体落实方案；加强横向纵向沟通协调，密切配合，形成合力，做好先进材料产业促进工作。"},{"no":"十五","title":"","text":"本方案自发布之日起施行。"}],"interpretations":[{"sectionNo":"六","headline":"先进材料项目优先供地，工业用地提容积率不增收土地价款","who":"先进材料产业项目；符合规划、不改变用途、提高土地利用率和增加容积率的现有工业用地企业。","materials":[],"window":"原文未设申报期限，按用地报批程序办理。","where":"市自然资源和规划局。","tip":"不增收土地价款需同时满足符合规划、不改变用途、提高利用率或容积率三项条件。"},{"sectionNo":"七","headline":"先进材料企业引进人才可享落户职称住房子女入学等支持","who":"先进材料产业企业及其引进的专业人才；高等学校、职业教育院校、职业技能培训机构可参与人才培养。","materials":[],"window":"原文未设申报期限；具体支持措施由市委人才办牵头另行明确。","where":"市委人才办牵头，市教育局、市公安局、市人社局、市住建局、市卫健委、市医保局等配合。","tip":"原文只写“明确具体支持措施”，尚未列出各项待遇标准和申报材料。"},{"sectionNo":"八","headline":"先进材料产业资金以财政贴息、事后奖补为主，重大项目可获配套","who":"先进材料产业企业；国家和省重大专项、扶持政策、产业基金、重大科研、重大产业项目落户本市的实施主体。","materials":[],"window":"原文未明确资金申报期；按年度财政预算和项目落户进度安排。","where":"市财政局牵头，市直有关部门配合。","tip":"支持方式为贴息和事后奖补，需先发生投入或贷款；具体额度原文未列。"},{"sectionNo":"九","headline":"先进材料企业可对接产业链供应链金融、科创金融和绿色金融","who":"先进材料产业链企业；纳入产业投资基金支持范围的先进材料项目。","materials":[],"window":"原文未设申报期限；融资产品由金融机构按市场化方式提供。","where":"市政府金融办牵头，市财政局、人民银行娄底市分行、国家金融监管总局娄底分局配合。","tip":"原文只写建立融资风险补偿机制和贡献度评估激励办法，未列补偿比例与申请条件。"},{"sectionNo":"十","headline":"水电气不得随意停供，不得强迫企业接受不合理服务条件","who":"先进材料产业企业等使用供水、供电、供气服务的企业。","materials":[],"window":"长期执行，原文未设申报期限。","where":"市发改委、市住建局、国网娄底供电分公司、市水业有限责任公司、娄底华润燃气有限公司。","tip":"遇到随意停水停电停气或乱收费，可向市发改委、市住建局及公用企事业单位反映。"},{"sectionNo":"十一","headline":"重大攻关突破并成果转化的先进材料项目可获奖励或补助","who":"先进材料企业及产学研合作主体；落户或设立分支机构的重点实验室、工程研究中心、企业技术中心、新型研发机构。","materials":[],"window":"奖励和补助办法另行制定，原文未定期限。","where":"市科技局牵头，市财政局配合；市发改委、市教育局、市工信局。","tip":"须同时满足取得重大攻关突破并实现成果转化应用；具体标准待办法出台。"},{"sectionNo":"十四","headline":"先进材料企业合法权益受保护，任何单位不得违法干预生产经营","who":"先进材料企业和企业家。","materials":[],"window":"《规定》施行满一年之日起六十日内向市人大常委会报告施行情况。","where":"市发改委、市市场监管局等市直相关单位；市应急管理局、市市场监管局、市税务局等配合。","tip":"公职人员滥用职权、玩忽职守依纪依法处理，涉嫌犯罪移送司法机关。"}],"sourceUrl":"https://www.hnloudi.gov.cn/loudi/0402/202402/777de4b20bee4daa81abcd0cc00bc236.shtml","derivedFrom":"official","sourceNote":"2026-11-24 修订：原 sourceUrl 指向市发改委政策解读页（b64c4a…，仅4段解读、无条款），本轮改为市政府正式文件页（娄政发〔2024〕3号原文），并按正文三方面15款逐条补录；原条目仅3款。原文未设有效期条款，仅有「本方案自发布之日起施行」。 2026-11-24 收录：与官方页面逐句比对，命中 50/50 句（100%），关卡判定「verbatim」。 有效期依据：原文未明示","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"ld-swj-fund-2026","title":"娄底市商务局 娄底市财政局关于印发《娄底市商贸服务业发展专项资金管理办法》的通知","level":"city","region":"娄底市","issuer":"娄底市商务局、娄底市财政局","documentNo":"娄商发〔2026〕20号","publishedAt":"2026-10-26","effectiveAt":"2026-10-26","expiresAt":"2031-10-26","status":"active","tags":["专项资金","财政奖补"],"audience":["商贸流通企业","餐饮住宿企业","生活性服务企业","商贸服务业行业协会"],"summary":"市级商贸服务业发展专项资金管理办法，专款专用、无偿资助，采取“事后奖励”“事后补贴”方式，支持餐饮住宿批发零售连锁品牌与标准化建设、家政美容美发洗涤沐浴等生活性服务业、政府购买行业协会服务、展会展览展销、人才培训、大型商贸综合体与冷链体系、一线品牌店与特色街、中小商贸企业服务平台等九个方向；办法未列具体奖补比例或金额，按项目法分配、由年度申报通知明确标准；自发布之日起施行，有效期5年。","sections":[{"no":"一","title":"","text":"为进一步加强商贸服务业发展专项资金管理，提高资金使用效益，促进商贸服务业加快发展，结合我市实际，制定本办法。"},{"no":"二","title":"","text":"本办法所称商贸服务业发展专项资金是指市级财政预算安排和整合其它资金来源用于促进娄底市商贸服务业发展的资金。"},{"no":"三","title":"","text":"市商贸服务业发展专项资金属于市级财政专项资金，专款专用，无偿资助。主要采取“事后奖励”和“事后补贴”方式，对符合资金引导方向的商贸服务业相关项目进行适当补助。"},{"no":"四","title":"","text":"市商贸服务业发展专项资金管理遵循公开、择优、规范、实效原则，资金分配和使用情况向社会公开，接受有关部门和社会监督。"},{"no":"五","title":"第二章 职责分工","text":"资金由市财政局、市商务局共同管理。市财政局主要负责专项资金的预算管理和资金拨付，对资金使用情况进行监督检查和绩效评价。市商务局主要负责业务指导和项目管理，对项目建设实施情况进行监督。市财政局、市商务局联合组织项目申报、审核项目申报材料、组织专家评审、提出资金分配方案、确定补助项目、开展项目资金绩效评价。"},{"no":"六","title":"第三章 使用范围","text":"市商贸服务业发展专项资金主要支持范围：（一）餐饮、住宿、批发、零售业的连锁品牌建设、标准化建设及先进技术、先进模式的运用等。（二）家政、美容美发、洗涤、沐浴等生活性服务业。（三）政府购买商贸服务业行业协会服务。（四）企业参加或举办各种经市政府及以上依法批准的经济类展会的展览展销和服务促消费活动。（五）商贸服务业人才培训及体系建设。（六）大型商贸综合体、农产品流通体系及冷链体系建设。（七）国际国内一线品牌店、特色街建设。（八）中小商贸服务业和商贸流通企业服务平台建设。（九）市委、市政府确定的其他需要重点支持的商贸服务业。"},{"no":"七","title":"第四章 使用管理","text":"市商贸服务业发展专项资金原则上采用项目法分配。"},{"no":"八","title":"","text":"市商务局根据商贸服务业发展规划和政府工作目标任务，会同市财政局研究确定年度市商贸服务业发展专项资金支持重点领域和方向，并在市商务局或市财政局的网站公布。"},{"no":"九","title":"","text":"申请市商贸服务业发展专项资金的企业、单位应当符合以下基本条件：（一）在娄底市开展实际经营，具有稳定经营条件，并具有健全的财务管理机构和完善的财务管理制度。（二）按照有关规定已取得开展相关业务的资格或已进行核准或备案。（三）按照本办法第六条规定的使用方向，已开展相关业务。（四）主营业务属于本办法支持范围内，业务模式明确，人才资源具备，经营能力突出。（五）项目单位具有良好的信用记录，没有列入失信联合惩戒对象；无拖欠民工工资、欠缴社会保险费等违法违规信用记录。（六）按有关规定报送统计资料。（七）其他按规定应满足的条件。"},{"no":"十","title":"","text":"符合规定条件的各类企业、单位，均可在规定的时间内，按属地原则向所在地商务部门和财政部门报送资金申请报告。其中，市有关单位项目资金申请报告直接报送市商务局和市财政局。资金申请报告应包括以下内容：（一）企业营业执照复印件；（二）娄底市商贸服务业发展专项资金项目申请表；（三）娄底市商贸服务业发展专项资金项目申请承诺书；（四）专项资金年度申报通知要求提供的其他资料；（五）其他需要提交的资料或情况说明。"},{"no":"十一","title":"","text":"市商务局会同市财政局负责申请项目的考察，对拟扶持的项目在一定范围内进行公示，共同研究提出资金分配方案，报市人民政府批准后，由市财政局和市商务局联合下达资金文件，市财政局根据财政国库管理制度将资金拨付到项目单位。"},{"no":"十二","title":"第五章 绩效管理和监督检查","text":"建立市商贸服务业发展专项资金绩效评价制度，产业类项目可将新增营收、新增就业等作为绩效评价重要参考因素。市财政局和市商务局按照工作职责和相关要求，对资金进行监管和绩效管理。专项资金支持的单位对相关项目资金进行绩效自评，形成自评报告报市商务局。市财政局根据情况适时开展绩效评价，强化绩效导向，将评价结果及年度绩效目标完成情况作为预算下达、执行和调整的重要参考因素。"},{"no":"十三","title":"","text":"专项资金必须专款专用，专项核算。市财政局和市商务局按照有关规定加强对专项资金使用情况的监督检查。"},{"no":"十四","title":"","text":"获得专项资金支持的单位收到资金后，应当按照国家有关财务会计制度规定进行账务处理，自觉接受市商务局、市财政局等相关部门的监督检查；并按照国家档案管理有关规定，妥善保管相关材料。"},{"no":"十五","title":"","text":"对于虚报、截留、挤占、挪用、骗取专项资金或不按规定用途使用、挥霍浪费财政资金等违法行为，一经查实，市财政局将收回已安排的专项资金，同时取消其以后两年的申报资格，并按照《财政违法行为处罚处分条例》等国家有关规定追究法律责任。"},{"no":"十六","title":"第六章 附则","text":"本办法由市商务局、市财政局负责解释。如上级出台新规定，从其规定。"},{"no":"十七","title":"","text":"本办法自发布之日起施行，有效期5年。"}],"interpretations":[{"sectionNo":"三","headline":"专项资金只做事后奖励、事后补贴，先投入后补助","who":"在娄底市开展实际经营、项目符合资金引导方向的商贸服务业企业、单位。","materials":[],"window":"项目完成后申报（事后奖励、事后补贴）","where":"原文未单列受理部门（市商务局、市财政局共同管理）","tip":"先投入后补助，项目未实施完成不能申报；资金为无偿资助，须专款专用"},{"sectionNo":"六","headline":"连锁品牌、家政、展会、冷链等九类商贸项目可获支持","who":"在娄底市开展实际经营的商贸服务业企业、单位；项目须属于餐饮住宿批发零售连锁化标准化、生活性服务业、政府购买行业协会服务、展会促消费、人才培训、大型商贸综合体与农产品流通冷链、品牌店特色街、中小商贸服务平台等支持方向。","materials":[],"window":"按年度支持重点领域和方向确定后申报","where":"市商务局、市财政局","tip":"九类方向内还须符合当年公布的支持重点；展会类限经市政府及以上依法批准的经济类展会"},{"sectionNo":"九","headline":"须在娄底实际经营、财务健全、无失信记录方可申报","who":"在娄底市开展实际经营、具有稳定经营条件和健全财务管理机构、已取得相关业务资格或完成核准备案、主营业务属支持范围、按规定报送统计资料的企业、单位；信用良好，未列入失信联合惩戒对象，无拖欠民工工资、欠缴社会保险费等记录。","materials":[],"window":"在规定时间内按属地原则报送，具体时限以年度申报通知为准","where":"所在地商务部门、财政部门；市有关单位直接报市商务局、市财政局","tip":"信用记录是硬门槛：被列入失信联合惩戒对象、拖欠民工工资、欠缴社保费的不能申报"},{"sectionNo":"十","headline":"报资金申请报告，须附营业执照、申请表、承诺书","who":"在娄底市开展实际经营、符合支持方向的企业、单位；按属地原则向所在地商务、财政部门报送，市有关单位项目直接报市商务局、市财政局。","materials":["企业营业执照复印件","娄底市商贸服务业发展专项资金项目申请表","娄底市商贸服务业发展专项资金项目申请承诺书","专项资金年度申报通知要求提供的其他资料","其他需要提交的资料或情况说明"],"window":"在规定时间内报送，具体时限见年度申报通知","where":"所在地商务部门和财政部门；市有关单位报市商务局、市财政局","tip":"市属单位项目不经过区县，直接报市商务局和市财政局；申请表、承诺书须用专项资金专用表格"},{"sectionNo":"十四","headline":"获资金单位须按财务制度做账，接受监督检查并留存材料","who":"获得娄底市商贸服务业发展专项资金支持的单位。","materials":[],"window":"收到资金后至资金使用完毕，相关材料按国家档案管理规定保管","where":"市商务局、市财政局等部门（监督检查）","tip":"账务处理须符合国家财务会计制度；相关材料按档案管理规定保管，检查时须能提供"},{"sectionNo":"十五","headline":"虚报、骗取专项资金，收回资金并取消两年申报资格","who":"申报和使用娄底市商贸服务业发展专项资金的单位。","materials":[],"window":"一经查实即收回已安排资金，并取消以后两年申报资格","where":"市财政局（收回资金）；按《财政违法行为处罚处分条例》追责","tip":"除收回资金外，取消以后两年申报资格，并按国家有关规定追究法律责任"}],"sourceUrl":"http://www.hnloudi.gov.cn/loudi/040418/202610/4942bb2619eb42d680dfc479599c1647.shtml","derivedFrom":"official","sourceNote":"2026-11-22 取自娄底市人民政府门户「文件库—市直部门规范性文件」原文页，版头载文号娄商发〔2026〕20号、统一登记号 LDCR-2026-20001，页面栏目载生效日期2026-10-26、失效日期2031-10-26。 2026-11-22 收录：与官方页面逐句比对，命中 19/19 句（100%），关卡判定「verbatim」。 有效期依据：第十七条明示“有效期5年”；页面栏目载失效日期2031-10-26 2026-11-24 收录：与官方页面逐句比对，命中 48/48 句（100%），关卡判定「verbatim」。 有效期依据：原文未明示","verified":false,"isSample":false,"numberStyle":"clause","bodyVerified":"verbatim","hunan":true},{"id":"national-unemployment-stable-jobs-2026","title":"人力资源社会保障部 教育部 财政部 国家税务总局关于失业保险支持企业稳岗扩岗的通知","documentNo":"人社部发〔2026〕39号","level":"national","region":"全国","issuer":"人力资源社会保障部、教育部、财政部、国家税务总局","publishedAt":"2026-07-10","effectiveAt":"2026-01-01","expiresAt":"2026-12-31","status":"expiring","tags":["就业补贴"],"audience":["企业","中小微企业"],"summary":"国家四部门延续实施失业保险稳岗扩岗政策：稳岗返还中小微企业按不超过上年度实缴失业保险费60%返还，一次性扩岗补助每招用1人不超过1500元，并优化技能提升补贴（初级/中级/高级分别不超过1000/1500/2000元）。政策执行期2026年1月1日至12月31日。","sections":[{"no":"一","title":"延续实施稳岗返还政策","text":"延续实施稳岗返还政策。参保企业足额缴纳失业保险费12个月以上,上年度未裁员或裁员率不高于上年度全国城镇调查失业率控制目标,30人(含)以下的参保企业裁员率不高于参保职工总数20%的,可以按规定享受失业保险稳岗返还。大型企业按不超过企业及其职工上年度实际缴纳失业保险费的30%返还,中小微企业按不超过60%返还。稳岗返还资金可用于职工生活补助、缴纳社会保险费、转岗培训、技能提升培训等稳定就业岗位以及降低生产经营成本支出。社会组织、律师事务所、会计师事务所以及以单位形式参保的个体工商户参照实施。"},{"no":"二","title":"延续实施一次性扩岗补助政策","text":"延续实施一次性扩岗补助政策。对招用毕业年度及离校两年内未就业高校毕业生、16—24岁登记失业青年,签订劳动合同并为其足额缴纳3个月以上失业、工伤、职工养老保险费的企业和社会组织,可按每招用1人不超过1500元的标准发放一次性扩岗补助。"},{"no":"三","title":"优化技能提升补贴政策","text":"优化技能提升补贴政策。参加失业保险12个月以上的企业在职职工或领取失业保险金人员,取得列入当地急需紧缺职业(工种)目录、职业种类与所在企业行业类别一致、数字和绿色职业等级证书之一的,可按初级、中级、高级分别领取不超过1000元、1500元、2000元的技能提升补贴,每人每年可享受1次补贴。对取得多项急需紧缺职业(工种)证书的,省级人力资源社会保障部门可结合本地实际,增加每人每年申请补贴次数,共计不超过3次。各地可在确保基金安全的前提下,探索更多证岗相适的情形,提升政策的针对性有效性,更好服务企业岗位需求、市场就业需要和地区产业发展。省级人力资源社会保障部门应就证岗相适情形向人力资源社会保障部备案。"},{"no":"四","title":"加强高品质服务供给","text":"加强高品质服务供给。各地要加强主动服务,畅通稳岗扩岗资金发放渠道,通过后台数据比对精准发放,充分释放政策红利。进一步优化稳岗返还“免申即享”经办模式,主动向符合条件的企业推送政策信息和资金用途,经确认领取后及时发放返还资金;对没有对公账户的小微企业,经企业确认及授权后,可将资金返还至当地税务部门协助提供的其缴纳社会保险费的账户。"},{"no":"五","title":"强化基金风险防控","text":"强化基金风险防控。各地要加强基金运行的监测和评估,优先确保失业保险待遇支出,合理确定各项政策支出标准。扎实开展高风险业务的预警处置,重点核查本省份有相关评价机构但批量持外省份同一评价机构所发证书申领技能提升补贴等情形。完善内控制度,在经办流程中设置区别于待遇审核发放的事后业务核查环节,明确专人负责。对存在风险隐患的业务,暂时无法通过信息共享核实的,可要求补充相关材料进行复核,切实防范冒领骗取和多发错发。\n各地要强化失业人员基本生活保障,持续做好失业保险金、代缴职工基本医疗保险(含生育保险)费等保生活待遇发放工作。实施稳岗返还、技能提升补贴的省(自治区、直辖市),上年末失业保险基金滚存结余备付期限应在1年以上。实施一次性扩岗补助政策所需资金从失业保险基金支出,上年末失业保险基金滚存结余备付期限不足1年的从就业补助资金支出。相关政策执行期限为2026年1月1日至12月31日。各地要高度重视,加强部门协作,优化经办流程,迅速行动,采取有效措施抓好政策落地见效。\n\n人力资源社会保障部教育部\n\n财政部国家税务总局\n\n2026年6月18日\n\n(此件主动公开)\n\n相关附件\n\n相关阅读\n\n国家部委网站\n\n省直政府网站\n\n省直单位网站\n\n市州县区网站\n\n站点地图\n\n其他"}],"interpretations":[{"sectionNo":"一","headline":"足额缴失业保险12个月以上，中小微企业可按60%返还","who":"参保企业：足额缴纳失业保险费12个月以上，上年度未裁员或裁员率不高于上年度全国城镇调查失业率控制目标；30人（含）以下企业裁员率不高于参保职工总数20%的也可享受。社会组织、律师事务所、会计师事务所以及以单位形式参保的个体工商户参照实施。","materials":[],"window":"按上年度缴费与裁员情况核定，具体申报期以当地人社部门通知为准。","where":"参保地人力资源社会保障部门；稳岗返还通过后台数据比对「免申即享」。","tip":"大型企业按不超过30%返还，中小微企业按不超过60%返还；资金可用于职工生活补助、社保缴费、转岗培训和技能提升培训。"},{"sectionNo":"二","headline":"招一名高校毕业生或失业青年，最高补1500元","who":"招用毕业年度及离校两年内未就业高校毕业生、16—24岁登记失业青年，签订劳动合同并足额缴纳3个月以上失业、工伤、职工养老保险费的企业和社会组织。","materials":[],"window":"缴纳失业、工伤、职工养老保险费满3个月以上即可申报。","where":"参保地人力资源社会保障部门。","tip":"标准是「每招用1人不超过1500元」，是补给人头不是补工资；须签劳动合同并实际缴三项保险。"},{"sectionNo":"三","headline":"技能提升补贴：初级1000、中级1500、高级2000元","who":"参加失业保险12个月以上的企业在职职工，或领取失业保险金人员；取得列入当地急需紧缺职业（工种）目录、职业种类与所在企业行业类别一致、数字和绿色职业等级证书之一的。","materials":[],"window":"每人每年可享受1次；取得多项急需紧缺职业证书的，省级人社部门可增加申请次数，共计不超过3次。","where":"参保地人力资源社会保障部门。","tip":"证书必须与所在企业行业类别一致、且在急需紧缺目录内，否则不符合条件。"},{"sectionNo":"四","headline":"稳岗返还免申即享，无对公账户小微企业可返至社保缴费账户","who":"符合条件的企业由各地主动推送政策信息和资金用途，经确认领取后发放稳岗返还资金；没有对公账户的小微企业，经企业确认及授权后，资金可返还至其缴纳社会保险费的账户。","materials":[],"window":"免申即享，无需企业申报；经确认领取后及时发放返还资金","where":"各地人社部门通过后台数据比对精准发放；无对公账户的，资金返还至当地税务部门协助提供的其缴纳社会保险费的账户","tip":"免申即享仍须经企业确认领取后才发放；没有对公账户的小微企业要先确认并授权，资金才能打到其缴纳社会保险费的账户，而不是另开对公账户。"},{"sectionNo":"五","headline":"稳岗返还等政策执行至2026年12月31日，基金备付须1年以上","who":"实施稳岗返还、技能提升补贴的省（自治区、直辖市），上年末失业保险基金滚存结余备付期限应在1年以上；实施一次性扩岗补助政策的省份，资金从失业保险基金支出，备付期限不足1年的从就业补助资金支出。","materials":[],"window":"2026年1月1日至12月31日（政策执行期限）","where":"各地（原文仅表述为“各地”，未点名具体部门或窗口），由各地经办环节设置事后业务核查","tip":"上年末失业保险基金滚存结余备付期限不足1年的省份不能实施稳岗返还、技能提升补贴；一次性扩岗补助在备付期限不足1年时改从就业补助资金支出；执行期到2026年12月31日结束。"}],"sourceUrl":"https://www.hunan.gov.cn/zqt/ztsy/zcrd/202607/t20260710_34024368.html","sourceNote":"湖南省人民政府门户网站转载人社部等四部门原文，2026-07-10发布；政策执行期2026-01-01至2026-12-31。；2026-11-08 核对：页面发布日期 2026-07-10；2026-11-09 条文按官方原文重切（5 条，自查召回 100%）","verified":true,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":false},{"id":"nx-seed-plan-2025","title":"宁乡市支持大学生创业“金种子沃土计划”二十条措施","level":"district","region":"长沙市·宁乡市","issuer":"宁乡市人民政府","documentNo":"","publishedAt":"2025-04-27","effectiveAt":"2025-04-18","expiresAt":"2029-11-30","status":"active","tags":["创业补贴","贷款贴息","社保补贴","场地支持","财政奖补"],"audience":["在宁乡市注册的大学生创业企业","大学生创业项目团队","创业孵化基地"],"summary":"每年安排200万元就业专项资金支持大学生创业培训；初创企业按不超过实际有效投入50%给予最高10万元项目扶持、最高3万元一次性创业补贴，入选长沙市“小荷”项目再给最高20万元；创业担保贷款个人最高30万元、合伙及小微企业最高400万元，按贷款实际利率50%贴息；经营场所租金第一年每月800元、第二年每月600元，入驻“雁巢计划”孵化基地500平方米以内最长3年免租；获评国家级、省级制造业单项冠军分别奖50万元、10万元。措施自2025年4月18日施行，有效期至2029年11月30日。","sections":[{"no":"一","title":"","text":"一、集成式政策扶持\n（一）创业启动补贴。根据省市相关政策，对符合条件的大学生初创企业，按不超过申报企业实际有效投入的50％，给予最高10万元的项目扶持；根据企业实际投入和带动就业人数，给予最高3万元的一次性创业补贴。被确定为长沙市“小荷”青年创新或创业项目的，给予最高20万元经费支持，重点培育优质项目。\n（二）创业贷款贴息。高校毕业生创业符合《中国人民银行长沙中心支行湖南省财政厅湖南省人力资源和社会保障厅关于印发〈湖南省创业担保贷款实施办法〉的通知》（长银发〔2017〕108号）相关条件的，最高可申请30万元创业担保贷款；合伙创业、创办小微企业的，根据合伙创业人数、小微企业新增吸纳就业人数，最高可申请400万元创业担保贷款，创业担保贷款由财政部门按贷款实际利率的50％给予贴息。个人自主创业、合伙创业及创办小微企业符合《中共长沙市委长沙市人民政府关于印发〈长沙市争创国家吸引集聚人才平台若干政策（试行）〉的通知》（长发〔2022〕12号）相关条件的，分别提供最高50万元、100万元、500万元的贷款支持，并按该文件规定给予贴息。\n（三）场地租金减免。对符合条件的大学生创业项目，按规定给予最长2年的经营场所租金补贴，补贴标准为第一年每月800元，第二年每月600元，实际租金低于补贴标准的，按实补贴。入驻宁乡“雁巢计划”孵化基地的项目，租赁场地500平方米以内租金全免，免租期最长不超过3年，同时提供配套办公设施、网络接入等服务。\n（四）社会保险补贴。对大学生新创办的小微企业、个体工商户、农民合作社、民办非企业单位等创业组织，吸纳劳动者就业满6个月后，可按吸纳符合条件的本省劳动者人数申请社会保险补贴。补贴额度按单位为劳动者实际缴纳的基本养老保险费、基本医疗保险费、失业保险费单位缴费部分进行补贴，不包括个人应缴部分。\n（五）免费入住。来宁创业考察的大学生1年内可享受8天7晚指定酒店免费入住。来宁创业的大学生符合《宁乡市实施人才强市战略推进高质量发展三十条措施（试行）》相关条件，可申请免费入住人才公寓，免费期限最长不超过3个月。\n（六）人才购房补贴。来宁创业的境外高校博士及国内普通高校博士、硕士、全日制本科毕业生，符合《中共长沙市委长沙市人民政府关于印发〈长沙市争创国家吸引集聚人才平台若干政策（试行）〉的通知》（长发〔2022〕12号）相关条件的，分别可享受10万元、3万元、2万元、1.2万元租房和生活补贴，博士、硕士毕业生在长沙市范围首次购房分别给予10万元、3万元购房补贴。\n（七）实习实训补贴。对有组织地来宁实习实训的国内外高校本科及以上在校大学生，给予每人每月1000元、最长三个月的生活补贴。\n（八）孵化基地补贴。支持大学生创业孵化基地建设，构建“1＋3＋10”创业载体体系，以园区为依托建设1个核心创业基地，在3所驻宁高等院校建设3个校园创业工作站，建设现代农业孵化园、文创数字工场、医药健康智创空间等10个特色创业孵化基地。获评省级或长沙市级创业孵化基地的，按照省市相关政策给予最高40万元补贴；对宁乡市级孵化基地择优给予适当补贴。"},{"no":"二","title":"","text":"二、多方位科技赋能\n（九）扶持科技成果转化。鼓励高校院所科研人员、在校大学生（含博士、硕士）、毕业3年内创新创业团队进行科技成果产业化，近两年内完成注册及正常办公、具备一定科技含量且对产业发展有较大促进作用的大学生创业企业，支持10万元－20万元，每年支持不超过10家，企业注册两年内，形成的产品或服务性收入达到500万元以上的，再奖励10万元，单家企业累计奖励不超过30万元；支持企业主动吸纳承接高校、科研院所科技成果，按比例给予奖励，单家企业每年累计奖励不超过20万元。\n（十）鼓励科技平台共享。结合支持建设与开放中试基地相关实施办法，整合全市科研成果转化中间试验场所和平台，对实验室研发出的新技术、新工艺、新产品进行放大试验和验证，对进入宁乡市中试基地培育名单且被新认定为国家、省、长沙市级中试基地的，分别奖励30万元、20万元、5万元；支持中试基地运营与设备开放，每年根据上年度实际服务性收入的10％给予奖励，单家企业每年累计奖励不超过30万元，鼓励中试基地向创业大学生开放，解决大学生创业项目在实际生产中可能遇到的问题，为产业化生产提供技术支持和保障。\n（十一）奖励创新创业。支持大学生创业企业创新平台建设，对大学生创业项目获评国家级、省级制造业单项冠军的企业，分别奖励50万元、10万元；对获评国家重点“小巨人”、国家专精特新“小巨人”、省专精特新中小企业的企业，分别奖励50万元、10万元、5万元；对通过国家、省认定的“智能制造”企业，分别奖励20万元、5万元；对获评国家级、省级制造业质量品牌标杆（示范）企业的企业，分别奖励10万元、5万元；对获评国家级、省级绿色工厂的企业，分别奖励10万元、3万元；对获评湖南省数字化转型标杆的企业，奖励5万元；对当年新入规工业企业一次性奖励10万元；对当年完成技术鉴定并经国家、省权威部门登记的，按照国际领先与先进、国内领先与先进科学技术成果，分别给予1万元、5000元每项奖励，单家企业累计奖励不超过10万元。"},{"no":"三","title":"","text":"三、一体化能力培育\n（十二）实施“金种子”培育工程。每年安排200万元就业专项资金，重点支持大学生开展创业培训。定期开展创业训练营，举办“千名大学生宁乡园区创业体验行”活动，组织参与“非公经济大讲堂”，提升大学生创业能力和创业愿望。\n（十三）组建“百人导师资源库”。成立指导大学生创业的导师团，加强对大学生创业项目的遴选把关，为大学生提供创业指导、信息咨询、资源对接等服务。其中在市内优秀企业遴选高管50人，组建大学生创业导师团；聘请“科创桥”人才库、宁乡籍优秀人才库、高等院校、科研院所中的专家学者30人，组建大学生创新导师团；聘请投资机构和金融机构相关人员20人，组建大学生创业投资导师团。\n（十四）建立“创业问诊”制度。在宁乡市职工服务中心设立“大学生创业门诊”，建立专家问诊制度，发挥宁乡市企业公共法律服务中心、宁乡市商事调解中心的作用，由创业导师团、法律咨询团、服务“帮办团”进行问诊答疑，解答大学生创业过程中遇到的问题，助力大学生成功创业。"},{"no":"附则","title":"","text":"六、附则\n（一）本措施中的大学生是指普通高校、科研院所、职业学校、技工院校的全日制在校生及毕业5年内的全日制大学生；大学生创业项目是指企业在宁乡市范围内登记注册、企业法定代表人为大学生，且法定代表人持股比例不低于公司总股份30％的项目。\n（二）本措施所涉及的资金奖补，同一奖补项目在多个政策文件中列出的，按就高不就低原则，不重复奖补，具体奖补办法以各项实施细则为准。\n（三）对有特殊贡献的大学生初创企业，采取“一事一议”方式确定支持政策。\n（四）本措施中奖补项目有上级文件规定的，以上级文件为准。本措施由宁乡市人力资源和社会保障局负责解释。\n（五）本措施自2025年4月18日起施行，有效期至2029年11月30日。"}],"interpretations":[{"sectionNo":"一","headline":"大学生初创企业最高10万元扶持，创业贷款最高400万元","who":"在宁乡市范围内登记注册、法定代表人为大学生且持股不低于30%的大学生创业项目；大学生指普通高校、科研院所、职业学校、技工院校全日制在校生及毕业5年内全日制大学生；子项还须符合吸纳就业、入驻雁巢计划、符合省市政策等条件。","materials":[],"window":"租金补贴最长2年（第一年800元/月、第二年600元/月）；雁巢计划免租最长3年；创业考察免费入住8天7晚；人才公寓最长3个月","where":"宁乡市；「雁巢计划」孵化基地；指定酒店（原文未列申报系统）","tip":"实际租金低于补贴标准的按实补贴；同一奖补项目就高不就低、不重复奖补"},{"sectionNo":"二","headline":"科技成果转化最高30万元，中试基地认定最高奖30万元","who":"在宁乡注册、近两年内完成注册及正常办公、具一定科技含量且对产业发展有促进作用的大学生创业企业（含高校院所科研人员、在校大学生、毕业3年内创新创业团队）；新认定国家、省、长沙市级中试基地；获评单项冠军、小巨人、智能制造、绿色工厂等企业。","materials":[],"window":"企业注册两年内；每年支持不超过10家；按年度奖励","where":"宁乡市（原文未列申报窗口）","tip":"单家企业成果转化累计奖励不超过30万元；中试基地按服务性收入10%奖励、年累计不超30万元"},{"sectionNo":"三","headline":"每年200万元创业培训资金，建百人导师库和创业门诊","who":"在宁乡创业的大学生；参加创业训练营、创业体验行、非公经济大讲堂的大学生；接受导师指导的大学生创业项目","materials":[],"window":"每年安排200万元；定期开展训练营和创业问诊","where":"宁乡市职工服务中心「大学生创业门诊」；市内园区和高校（原文未列线上系统）","tip":"导师团由50名企业高管、30名专家学者、20名投资和金融机构人员组成"}],"sourceUrl":"http://www.nxcity.gov.cn/zw229/fdzdgknr/flgw1695/bmgz10101/202507/t20250723_11927854.html","sourceNote":"2026-11-22 取自宁乡市人民政府门户「法定主动公开内容—法规公文—部门规章」；页面公布日期2025-04-27、生效日期2025-04-18，文号栏为空，按发文主体记为宁乡市人民政府。 2026-11-22 收录：与官方页面逐句比对，命中 43/43 句（100%），关卡判定「verbatim」。 有效期依据：六、附则第（五）项","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"p-2020-3ff489","title":"湖南省社会保险补贴实施办法","level":"provincial","region":"湖南省","issuer":"湖南省人力资源和社会保障厅、湖南省财政厅","documentNo":"湘人社规〔2020〕22号","publishedAt":"2020-11-03","status":"expired","tags":["社保补贴","就业补贴"],"audience":["小微企业","高校毕业生"],"summary":"小微企业招用离校2年内未就业高校毕业生并签订1年以上劳动合同的，按实际缴纳的基本养老保险、基本医疗保险、失业保险单位缴费部分给予最长1年社保补贴。","sections":[{"no":"一","title":"第一条","text":"根据《国务院关于进一步做好稳就业工作的通知》(国发〔2019〕28号)、《湖南省人民政府办公厅关于印发<应对新冠肺炎疫情影响进一步做好稳就业工作十六条措施>的通知》(湘政办发〔2020〕20号)和《湖南省财政厅 湖南省人力资源和社会保障厅关于印发〈湖南省就业专项资金管理办法〉的通知》(湘财社〔2018〕25号)等文件精神,结合实际制定本办法。"},{"no":"二","title":"第二条","text":"本省行政区域内各类企业(单位)和公益性岗位招用就业困难人员,或小微企业招用离校2年内未就业高校毕业生申请享受社会保险补贴,以及就业困难人员和离校2年内未就业高校毕业生灵活就业后申报享受社会保险补贴的,适用本办法。"},{"no":"三","title":"第三条","text":"社会保险补贴按照属地管理原则,由参保所在地人力资源和社会保障、财政部门按照本办法规定受理并核拨社会保险补贴资金。在省本级参保且符合享受补贴条件的,就业困难人员在就业困难人员认定地申领,高校毕业生在就业登记地申领。\n第二章 社会保险补贴对象"},{"no":"四","title":"第四条","text":"具备下列条件之一的对象可以按规定享受社会保险补贴:\n(一)企业(单位)招用就业困难人员或安排就业困难人员在公益性岗位工作,且依法参加社会保险,企业(单位)和职工个人按规定履行了社会保险费(基本养老保险费、基本医疗保险费和失业保险费)缴纳义务,并与之签订1年以上劳动合同的;\n(二)小微企业招用离校2年内未就业高校毕业生,且依法履行了社会保险费(基本养老保险费、基本医疗保险费和失业保险费)缴纳义务,并与之签订1年以上劳动合同的;\n(三)就业困难人员灵活就业后,以灵活就业人员身份参加社会保险、且履行了社会保险费缴纳义务的;\n(四)离校2年内未就业高校毕业生灵活就业后,以灵活就业人员身份参加社会保险、且履行了社会保险费缴纳义务的。\n第三章 社会保险补贴范围、期限和标准"},{"no":"五","title":"社会保险补贴范围","text":"社会保险补贴范围\n企业(单位)招用就业困难人员、公益性岗位安排就业困难人员和小微企业招用离校2年内未就业高校毕业生的,可申请基本养老保险、基本医疗保险和失业保险补贴,不包括个人应缴纳的部分。就业困难人员和离校2年内未就业高校毕业生进行灵活就业登记后,可申请基本养老保险、基本医疗保险补贴。代发放工资或代缴社会保险费的第三方单位,以及毕业时间(毕业证发放时间)超过2年的高校毕业生,不在补贴范围之内。"},{"no":"六","title":"社会保险补贴期限","text":"社会保险补贴期限\n(一)企业(单位)招用就业困难人员、公益性岗位安排就业困难人员和就业困难人员灵活就业后享受社会保险补贴最长不超过3年;初次核定其享受社会保险补贴时间不早于初次申报时间一年,领取养老保险待遇后不再申报本补贴。自初次核定其享受社会保险补贴之日起计算,距法定退休时间不足5年的,可延长享受至法定退休时间;提前退休的,以实际退休时间作为享受补贴截止时间,补贴起始时间不能追溯至初次核定享受政策之前;延迟退休的,以法定退休时间作为享受补贴截止时间,延迟退休期间不再继续享受补贴。\n(二)企业(单位)招用就业困难人员、公益性岗位安排就业困难人员和就业困难人员灵活就业的,同一时间、同一对象只能享受企业吸纳社会保险补贴或灵活就业社会保险补贴之中的一种,不能同时享受;对同一人,在不同时间、不同单位,享受企业吸纳社会保险补贴和灵活就业社会保险补贴的累计时间不超过本办法规定的期限。\n(三)小微企业招用离校2年内未就业高校毕业生,给予最长不超过1年的社会保险补贴;对离校2年内未就业高校毕业生进行灵活就业登记的,给予最长不超过2年的社会保险补贴。补贴时限从初次核定其享受社会保险补贴之日起,至毕业时间满2年为止。不同小微企业招用同一符合条件高校毕业生的,均可按规定享受社会保险补贴,累计享受补贴时间不超过1年。同一符合条件高校毕业生,可在不同时间按规定享受小微企业吸纳社会保险补贴和灵活就业社会保险补贴。"},{"no":"七","title":"社会保险补贴标准","text":"社会保险补贴标准\n(一)对企业(单位)和公益性岗位招用就业困难人员、小微企业招用离校2年内未就业高校毕业生的,按其为就业困难人员和高校毕业生实际缴纳的基本养老保险费、基本医疗保险费、失业保险费单位缴费部分进行补贴,不包括个人应缴部分。未缴齐上述三种社会保险费的不予补贴。\n(二)符合条件的就业困难人员灵活就业社会保险补贴计算方式为:社会保险费缴费基数按上年度我省全口径社会平均工资的60%执行,费率按实际缴纳社会保险的费率执行。“4050”人员(女性年龄在40周岁以上、男性年龄在50周岁以上,下同)按上述方式计算金额的60%予以补贴,非“4050”人员按上述方式计算金额的40%予以补贴。\n(三)符合条件的离校2年内未就业高校毕业生灵活就业后社会保险补贴按前款非“4050”人员标准执行。\n第四章 社会保险补贴的申领"},{"no":"八","title":"社会保险补贴实行“先缴后补”方式","text":"社会保险补贴实行“先缴后补”方式。申请社会保险补贴企业(单位)按规定先行缴纳基本养老保险费、基本医疗保险费和失业保险费,且须通过湖南省公共就业服务信息管理平台(以下简称“省平台”)向社会保险费缴纳地人力资源和社会保障部门申报社会保险费补贴。"},{"no":"九","title":"第九条","text":"申报社会保险补贴企业(单位)应按照省平台要求填报录入相关信息并上传以下资料:\n1.营业执照副本(组织机构代码证);\n2.与招用的就业困难人员或高校毕业生签订的劳动合同;\n3.享受补贴对象的身份证;属高校毕业生的,还需上传毕业证书。"},{"no":"十","title":"第十条","text":"就业困难人员和离校2年内未就业高校毕业生申报灵活就业社会保险补贴的,在完成缴费后,前往社会保险费缴纳地各社区(村)或通过官方平台自主申报,按要求填报相关信息并录入上传以下资料:\n1.社会保障卡或银行卡;\n2.属高校毕业生的,还需上传毕业证书。\n申报社会保险补贴企业(单位)和个人,对填报录入的所有信息的真实性、准确性负责,对提交虚假错误信息导致的后果由填报单位和个人全部承担。\n第五章 社会保险补贴资金审核拨付"},{"no":"十一","title":"第十一条","text":"人力资源和社会保障部门应及时对企业(单位)提交的社会保险补贴申请通过省平台进行审核。审核通过的,将符合条件的企业(单位)相关补贴信息在同级人力资源和社会保障门户网站公示7天,无异议后,按规定将补贴资金拨付至企业(单位)银行账户。\n公益性岗位安排就业困难人员、小微企业招用离校2年内未就业高校毕业生的社会保险补贴申请和资金拨付,按照上述规定执行。"},{"no":"十二","title":"第十二条","text":"灵活就业人员提交的社会保险补贴申请由社区(村)完成资料录入和调查,提交给街道(乡镇)进行确认,街道(乡镇)完成确认后,提交当地人力资源和社会保障部门进行审核。\n审核通过的,将符合条件的人员相关补贴信息在同级人力资源和社会保障门户网站公示7天,无异议后,按规定将补贴资金拨付至申请者本人社会保障卡账户或银行卡。\n第六章 服务与监督"},{"no":"十三","title":"第十三条","text":"各级人力资源和社会保障部门以及街道(乡镇)、社区(村)应当指导企业(单位)、就业困难人员、高校毕业生申报办理社会保险补贴,并提供咨询服务。"},{"no":"十四","title":"第十四条","text":"人力资源和社会保障、财政部门之间要加强沟通合作,精简工作流程,加强信息化建设,实行网上申报和经办,为申报企业(单位)和个人提供便利。各地人社部门应及时将享受补贴人员姓名、补助标准等情况及时纳入省平台管理,并实现与财政部门的信息共享。"},{"no":"十五","title":"第十五条","text":"人力资源和社会保障部门要做好本行政区域社会保险补贴政策的宣传、落实和统计工作,定期收集上报实施社会保险补贴政策的相关情况和问题。"},{"no":"十六","title":"第十六条","text":"人力资源和社会保障部门要设立举报投诉电话,接受社会监督;对不符合补贴条件或非法恶意骗取社会保险补贴的企业(单位)和个人,应责令其改正并依法追回被骗取的社会保险补贴资金,同时按规定纳入相关信用体系;构成犯罪的,依法追究其刑事责任。"},{"no":"十七","title":"第十七条","text":"人力资源和社会保障部门、财政部门的工作人员违规办理社会保险补贴的,分别由人力资源和社会保障部门、财政部门责令其改正;情节严重的,依法追究相关人员责任。"},{"no":"十八","title":"第十八条","text":"对疏于管理、违规发放社会保险补贴的地区,省人力资源和社会保障厅、省财政厅将适当扣减其下年度就业补助资金。\n第七章 附则"},{"no":"十九","title":"本办法自2021年1月1日起施行,有效期5年","text":"本办法自2021年1月1日起施行,有效期5年。我省之前有关社会保险补贴政策与本办法不一致的,以本办法为准。国家、省有明确新规的,从其规定。"},{"no":"二十","title":"第二十条","text":"各级人力资源和社会保障、财政部门可结合本地实际出台具体实施细则。"}],"interpretations":[{"sectionNo":"七","headline":"灵活就业社保补贴：4050 人员补 60%、其他人补 40%","who":"符合条件的就业困难人员灵活就业；离校2年内未就业高校毕业生灵活就业的，按非「4050」人员标准执行。","materials":[],"window":"本办法自2021年1月1日起施行，有效期5年（已到期，现行政策请查最新文件）。","where":"参保所在地人力资源社会保障部门。","tip":"补贴基数是上年度全省全口径社会平均工资的60%，不是按你实际缴费额全额补；「4050」指女性40周岁以上、男性50周岁以上。"},{"sectionNo":"八","headline":"先缴后补，通过省平台向缴费地人社部门申报","who":"申请社会保险补贴的企业（单位）；须先按规定缴纳养老、医疗、失业三项保险费。","materials":[],"window":"本办法第十九条定的有效期已届满，续办请以现行文件为准。","where":"湖南省公共就业服务信息管理平台（省平台），向社会保险费缴纳地人社部门申报。","tip":"没缴齐三项保险费的不予补贴；这是「先缴后补」，不是先给钱。"},{"sectionNo":"二","headline":"企业吸纳困难人员、小微企业招毕业生可申社保补贴","who":"本省行政区域内各类企业（单位）和公益性岗位招用就业困难人员；小微企业招用离校2年内未就业高校毕业生；就业困难人员和离校2年内未就业高校毕业生灵活就业后申报。","materials":[],"window":"按本办法规定的补贴期限执行：企业吸纳就业困难人员最长3年，小微企业招用高校毕业生最长1年。","where":"本省行政区域内（按属地管理原则受理）。","tip":"代发放工资或代缴社会保险费的第三方单位不在补贴范围；毕业时间超过2年的高校毕业生不再纳入。"},{"sectionNo":"三","headline":"社保补贴按属地管理，在参保所在地人社、财政部门申领","who":"在参保所在地参保并符合补贴条件的企业（单位）、就业困难人员和高校毕业生；在省本级参保且符合条件的，就业困难人员在认定地申领、高校毕业生在就业登记地申领。","materials":[],"window":"按参保所在地受理时间申报；省本级参保人员分别在认定地、就业登记地申领。","where":"参保所在地人力资源和社会保障、财政部门；省本级参保的，就业困难人员在认定地申领、高校毕业生在就业登记地申领。","tip":"按属地管理原则受理核拨，不在参保地申报可能无法受理；省本级参保人员申领地另有规定。"},{"sectionNo":"四","headline":"四类对象可享社保补贴，含企业吸纳、公益性岗位和两类灵活就业","who":"（一）企业（单位）招用就业困难人员或安排在公益性岗位工作，依法参保并缴纳基本养老、基本医疗、失业保险费，签订1年以上劳动合同；（二）小微企业招用离校2年内未就业高校毕业生，依法缴纳三项社会保险费，签订1年以上劳动合同；（三）就业困难人员灵活就业后以灵活就业人员身份参保并缴费；（四）离校2年内未就业高校毕业生灵活就业后以灵活就业人员身份参保并缴费。","materials":[],"window":"须签订1年以上劳动合同并履行缴费义务后方可申请。","where":"参保所在地人力资源和社会保障、财政部门。","tip":"四类情形具备其一即可；企业和个人须按规定履行缴费义务，未缴费不享受。"},{"sectionNo":"五","headline":"企业吸纳可补养老、医疗、失业三险，灵活就业只补养老、医疗","who":"企业（单位）招用就业困难人员、公益性岗位安排就业困难人员、小微企业招用离校2年内未就业高校毕业生；以及办理灵活就业登记的就业困难人员和离校2年内未就业高校毕业生。","materials":[],"window":"按补贴期限执行；代缴社保的第三方单位、毕业时间超过2年的高校毕业生不纳入。","where":"社会保险参保地（按本办法属地原则受理）。","tip":"不包括个人应缴纳的部分；代发放工资或代缴社会保险费的第三方单位、毕业时间超过2年的高校毕业生不在补贴范围。"},{"sectionNo":"六","headline":"企业吸纳就业困难人员补贴最长3年，距退休不足5年可延至退休","who":"企业（单位）招用就业困难人员、公益性岗位安排就业困难人员、就业困难人员灵活就业；小微企业招用离校2年内未就业高校毕业生；离校2年内未就业高校毕业生灵活就业。","materials":[],"window":"企业吸纳和就业困难人员灵活就业最长不超过3年；距法定退休时间不足5年的可延至退休；小微企业招用高校毕业生最长1年，高校毕业生灵活就业最长2年，补贴至毕业时间满2年为止。","where":"参保所在地人力资源社会保障部门（期限自初次核定之日起计算）。","tip":"同一时间、同一对象只能享受企业吸纳或灵活就业社保补贴之一；不同小微企业吸纳同一毕业生均可享受，累计不超过1年；领取养老保险待遇后不再申报。"},{"sectionNo":"九","headline":"企业申报社保补贴须上传营业执照、劳动合同、身份证等资料","who":"申报社会保险补贴的企业（单位），按省平台要求填报录入相关信息并上传资料。","materials":["营业执照副本（组织机构代码证）","与招用的就业困难人员或高校毕业生签订的劳动合同","享受补贴对象的身份证；属高校毕业生的还需毕业证书"],"window":"按省平台申报时间提交，审核通过后公示7天。","where":"省平台（按省平台要求填报录入并上传资料）。","tip":"高校毕业生须额外上传毕业证书；资料须真实，填报信息虚假错误后果由填报单位承担。"},{"sectionNo":"十","headline":"灵活就业人员缴费后可到社区（村）或官方平台申报社保补贴","who":"申报灵活就业社会保险补贴的就业困难人员和离校2年内未就业高校毕业生；须先完成社会保险费缴纳。","materials":["社会保障卡或银行卡","高校毕业生还需毕业证书"],"window":"完成缴费后申报。","where":"社会保险费缴纳地各社区（村），或通过官方平台自主申报。","tip":"填报信息须真实准确，提交虚假错误信息导致的后果由填报单位和个人全部承担。"},{"sectionNo":"十二","headline":"灵活就业社保补贴经社区录入、街道确认、人社审核，公示7天","who":"提交灵活就业社会保险补贴申请的灵活就业人员（就业困难人员、离校2年内未就业高校毕业生）。","materials":[],"window":"审核通过后公示7天，无异议后拨付。","where":"社区（村）、街道（乡镇）、当地人力资源和社会保障部门；补贴拨付至本人社会保障卡账户或银行卡。","tip":"须经社区（村）资料录入和调查、街道（乡镇）确认，直接找人社部门可能无法受理；资金拨至本人社保卡或银行卡。"},{"sectionNo":"十六","headline":"骗取社保补贴将被责令改正、追回资金并纳入信用体系","who":"申请社会保险补贴的企业（单位）和个人；人社部门设立举报投诉电话接受社会监督。","materials":[],"window":"长期执行；发现不符合条件或骗取即责令改正、追回资金。","where":"当地人力资源和社会保障部门（举报投诉电话）。","tip":"构成犯罪的依法追究刑事责任；违规资金依法追回，并按规定纳入相关信用体系。"}],"sourceUrl":"https://rst.hunan.gov.cn/rst/xxgk/zcfg/zxzc/202011/13965787/files/595b67c2f8a940aa8afde9b0a6c964bc.pdf","sourceNote":"条文已于 2026-11-09 与官方页面/PDF 逐句比对，逐字一致（明细见 采集包/条文核对表.md）；2026-11-09 按原文「自2021年1月1日起施行，有效期5年」推算 2021-01-01 至 2025-12-31","verified":false,"isSample":false,"numberStyle":"clause","bodyVerified":"verbatim","effectiveAt":"2021-01-01","expiresAt":"2025-12-31","hunan":true},{"id":"p-2023-093de0","title":"湖南省人力资源和社会保障厅 湖南省财政厅关于深入推进创业孵化基地建设工作的通知","level":"provincial","region":"湖南省","issuer":"湖南省人力资源和社会保障厅、湖南省财政厅","documentNo":"湘人社规〔2023〕5号","publishedAt":"2023-05-08","status":"active","tags":["场地支持","创业补贴","就业补贴"],"audience":["小微企业","个体工商户"],"summary":"对经各级人力资源社会保障部门认定的创业孵化基地给予创业服务补助，每吸纳1家创业实体入孵按每家每月100元给予基地补助、创业实体在孵期间成功注册市场主体的按2000元每家给予一次性补助，每个基地每年享受创业服务补助总额最高不超过40万元，本通知自2023年5月10日起执行，有效期五年。","sections":[{"no":"一","title":"建设原则","text":"创业孵化基地建设按照“政府引导、园区主建、突出特色、注重实效”的原则，以培育市场主体和带动创业就业为导向，以推动创业孵化基地提质增量为目标，以强化优化创业孵化服务能力为重点，建设和认定一批管理规范、服务优良、孵化成功率高、创业带动就业效果好、辐射示范作用强的各级创业孵化基地，为创业者提供良好的创业场所和生态环境。"},{"no":"二","title":"目标任务","text":"各县市区至少有1家创业孵化基地，各市州至少要有2家省级创业孵化基地。全省创业孵化基地（含创业园区）总量保持在400家左右，在孵创业实体（含创业企业、创业团队、创业项目）1万家以上，力争实现创业带动就业5万人。"},{"no":"三","title":"工作措施","text":"（一）整合资源，加大建设力度。各级人力资源社会保障部门要将硬件好、资源优、服务能力强的各类创业园区、工业园区、院校创新创业学院等单位纳入建设范围，推动符合条件的单位积极申报认定创业孵化基地，推动有条件的县市区依托本地园区建设创业孵化基地。鼓励社会组织和民营企业积极参与创业孵化基地建设和运营，凝聚各方资源力量。各地要指导创业孵化基地面向不同产业行业、不同创业群体配齐配优服务，打造特色基地。\n\n（二）强化指导，提高服务水平。各地要推动创业孵化基地强化服务能力建设，指导孵化基地不断健全和完善孵化服务体系。各市州人力资源社会保障部门每年至少要开展1次创业孵化基地管理和服务人员业务培训班，重点提升基地创业项目指导、投融资对接、补贴政策申请、事务代办等服务能力，不断提高孵化服务水平。各地要为各创业孵化基地至少对接2名湖南省创业创新导师团成员（专家、讲师至少各1名），为在孵实体提供创业辅导、技术辅导、政策辅导、赛事辅导等服务，并将服务情况录入湖南省人社业务一体化经办平台（以下简称省平台）。\n\n（三）依托平台，优化服务经办。依托省平台建立全省创业孵化基地信息库和在孵创业实体信息库，各创业孵化基地和在孵创业实体要及时更新单位基本信息、运营管理信息等，确保各项信息真实、准确、完整，为基地建设运营和管理信息化智能化提供数据支撑。各创业孵化基地要通过省平台对创业项目、创业团队和初创企业从评估入园、孵化培育到转化出园的全生命周期进行跟踪管理，要指导协助在孵创业实体按省平台要求完整录入相关信息，准确记录运营情况，及时受理其服务请求并反馈服务结果。\n\n（四）规范发展，实行动态管理。各地每年开展1次创业孵化基地认定工作，将具备条件、积极性高的优秀单位认定为当地创业孵化基地。各地每年要对已认定的创业孵化基地进行复评，对照省平台内各孵化基地创业服务成效情况，对孵化效果欠佳、服务能力不足、工作配合度和群众满意度不高，以及不再符合创业孵化基地认定标准的单位，要取消认定并及时予以退出。"},{"no":"四","title":"政策支持","text":"（一）给予创业孵化基地创业服务补助。对经各级人力资源社会保障部门认定的创业孵化基地给予创业服务补助。创业孵化基地每吸纳1家创业实体入孵，按每家每月100元的标准给予基地补助；创业实体在孵期间成功注册市场主体的（在孵创业实体入孵前未注册市场主体），按2000元每家给予基地一次性补助；创业孵化基地内的各在孵创业实体与劳动者签订1年以上劳动合同，签订的劳动合同总人数超过50人的按3万元每年的标准给予基地补助，超过100人的按6万元每年的标准给予基地补助，超过150人的按9万元每年的标准给予补助。被认定为市级创业孵化基地的补助金额总数上浮20%，被认定为省级的补助金额总数上浮40%，被认定为国家级的补助金额总数上浮60%，就高不就低。同一创业孵化基地中的同一在孵创业实体注册多个市场主体的，只能计算1家，不重复补贴。每个基地每年享受创业服务补助总额最高不超过40万元，按照就业专项资金使用的有关规定，主要用于开展创业孵化基地服务项目清单中的有关服务，以及孵化基地服务能力建设和提升，所需资金从所在地就业专项资金中列支。\n\n（二）给予一次性创业补贴。对在孵实体中正常运营一年以上并吸纳一定规模就业的初创企业和初次注册的个体工商户，按规定给予一次性创业补贴，主要用于创业经营性场所租金补贴、一次性开办费补贴和商标补贴等。其中创业经营性场所租金补贴部分，由创业孵化基地代为申请代为支付。所需资金从所在地就业专项资金中列支。\n\n（三）鼓励开展创业服务和活动。支持湖南省创业创新导师团成员为在孵创业实体提供创业指导服务。对于每年积极提供创业服务次数多、满意度高的创业创新导师，优先吸纳为省级创业创新导师团成员；鼓励优秀创业创新导师成立创业指导工作室，为创业实践持续提供后续服务；各级人力资源社会保障部门可通过政府购买创业服务成果的方式，支持创业孵化基地开展创业沙龙、创业讲堂、创业训练营、项目展示交流等创业活动，为创业者搭建资源对接的平台。所需资金从所在地就业专项资金中列支。\n\n（四）落实创业担保贷款相关政策。符合条件的创业孵化基地在孵创业实体申请20万元以下个人创业担保贷款的，免除反担保要求，按规定给予贴息。超过20万元且确需提供反担保的，市级以上创业孵化基地可为其在孵创业实体提供信用担保。\n\n（五）示范引领。各地要按照突出成效、重在特色、典型引领的原则，每年认定一批本级创业孵化基地，发文公布，授予牌匾，引领带动创业孵化基地做大做强，做精做专。\n\n各地安排的其他非就业专项资金用于支持创业孵化基地建设的，可按照自行制定的文件执行。"},{"no":"五","title":"工作要求","text":"（一）加强组织领导。各地要把创业孵化基地建设工作作为落实“创响三湘”行动和“五创联动”的重要举措，加强规划引导，做好基地认定、指导、服务、管理等工作，结合本地实际制定细则，认真落实各项补贴政策，切实提升创业孵化基地管理服务水平和孵化实效。\n\n（二）强化工作推动。各地要依托省平台实时掌握创业孵化基地政策落实、创业服务开展、带动就业和满意度情况，上述情况将作为全省创业带动就业相关工作评先评优和考核的重要评价指标，以及享受资金补贴的重要依据。\n\n（三）加强资金监管。各地要按照“谁使用、谁审核、谁负责”的原则，全面加强对创业孵化基地相关补贴资金的监管。要严格按照有关规定做好资金申报、审核和拨付工作，做到公开透明、公平公正，坚决杜绝优亲厚友、虚报冒领等行为。对存在徇私舞弊、套取骗取、贪污挪用等违法违纪行为的，依照法律法规和有关规定严肃追究责任。\n\n本通知自2023年5月10日起执行，有效期五年。此前有关规定与本通知不一致的，以本通知为准。\n\n联系人：胡川 0731-84900136\n\n附件：1.创业孵化基地认定的基本条件\n\n2.创业孵化基地认定及复核程序\n\n3.创业孵化基地服务项目清单\n\n4.创业孵化基地申请表\n\n5.在孵创业实体名册\n\n6.孵化基地补贴申请表"}],"interpretations":[{"sectionNo":"四","headline":"每吸纳1家实体每月补100元，基地每年最高补40万元","who":"经各级人力资源社会保障部门认定的创业孵化基地（补助给基地，不是给入孵企业）。被认定为市级、省级、国家级的，补助总额分别上浮20%、40%、60%，就高不就低。","materials":[],"window":"按年度核算，每个基地每年享受的创业服务补助总额最高不超过40万元。","where":"所在地人力资源社会保障部门；资金从所在地就业专项资金中列支。","tip":"同一在孵实体注册多个市场主体的，只计算1家，不重复补贴；在孵实体注册成功另按2000元/家给基地一次性补助。"},{"sectionNo":"四","headline":"在孵实体可申一次性创业补贴，租金补贴由基地代申请代付","who":"在孵实体中正常运营一年以上、并吸纳一定规模就业的初创企业和初次注册的个体工商户。","materials":[],"window":"正常运营一年以上方可申报。","where":"经营场所租金补贴部分，由创业孵化基地代为申请、代为支付。","tip":"补贴资金用于租金、一次性开办费和商标补贴，其中租金部分不直接发给创业者，而是由基地代收代付。"},{"sectionNo":"四","headline":"在孵实体借20万元以下创业担保贷款，免反担保","who":"符合条件的创业孵化基地在孵实体（个人创业担保贷款）。","materials":[],"window":"按创业担保贷款经办流程办理。","where":"经办银行与当地人力资源社会保障部门。","tip":"超过20万元且确需反担保的，市级以上创业孵化基地可为其在孵实体提供信用担保。"},{"sectionNo":"三","headline":"园区等单位可申报认定创业孵化基地，每年认定1次","who":"各级人力资源社会保障部门纳入建设范围的各类创业园区、工业园区、院校创新创业学院等单位；有条件的县市区可依托本地园区建设；社会组织和民营企业可参与建设运营。各基地须至少对接2名湖南省创业创新导师团成员（专家、讲师至少各1名），并配齐面向不同产业行业、不同创业群体的服务。","materials":[],"window":"各市州人社部门每年至少开展1次基地管理和服务人员业务培训班；各地每年开展1次创业孵化基地认定，每年对已认定基地复评1次。","where":"湖南省人社业务一体化经办平台（省平台）。","tip":"孵化效果欠佳、服务能力不足、工作配合度和群众满意度不高，或不再符合认定标准的，取消认定并退出；基地和在孵实体须及时更新信息，确保真实、准确、完整。"}],"sourceUrl":"https://img.zhuzhou.gov.cn/zzcms/DFS//file/2023/07/14/20230714172148612rpbxgf.pdf","sourceNote":"条文已于 2026-11-09 与官方页面/PDF 逐句比对，逐字一致（明细见 采集包/条文核对表.md）；2026-11-08 核对：湘人社规〔2023〕5号，HNPR-2023-11003","verified":true,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"p-2023-c9b55d","title":"关于印发《湖南省中小企业发展专项资金管理办法》的通知","level":"provincial","region":"湖南省","issuer":"湖南省财政厅、湖南省工业和信息化厅","documentNo":"湘财企〔2023〕6号","publishedAt":"2023-12-28","status":"active","tags":["专项资金"],"audience":["小微企业"],"summary":"专项资金由省级财政一般公共预算安排、采取财政补助和以奖代补等支持方式，支持中小企业提升创新能力及专业化水平、完善中小企业公共服务体系等，本办法自2024年1月1日起施行，有效期至2026年12月31日。","sections":[{"no":"一","title":"第一条","text":"为规范湖南省中小企业发展专项资金的使用管理，提高资金的使用效益，根据《中华人民共和国预算法》《中华人民共和国中小企业促进法》和《湖南省实施〈中华人民共和国中小企业促进法〉办法》等有关规定，结合我省实际，制定本办法。"},{"no":"二","title":"第二条","text":"本办法所称湖南省中小企业发展专项资金（以下简称专项资金），是指依据《中华人民共和国中小企业促进法》设立，由省级财政一般公共预算安排用于支持中小企业发展的资金。"},{"no":"三","title":"第三条","text":"专项资金管理使用遵循公开公正、择优高效的原则，围绕党中央、国务院和省委、省政府有关决策部署，重点引导完善中小企业公共服务体系、改善中小企业发展环境，突破制约中小企业发展的短板和瓶颈，支持中小企业高质量发展。"},{"no":"四","title":"第四条","text":"专项资金由省财政厅和省工业和信息化厅（以下简称省工信厅）按职责分工共同管理。省财政厅负责明确年度专项资金额度，会同省工信厅确定专项资金支持方向和重点、支持方式和标准；根据省工信厅报送的年度专项资金分配方案、绩效目标建议及有关材料，按程序下达预算、绩效目标并拨付资金；指导督促省工信厅开展监督管理工作。\n\n省工信厅负责提出专项资金年度支持方向和重点、资金需求测算方案、绩效目标；组织项目申报、汇总、审查、评审；根据年度预算编制要求，及时向省财政厅提供年度专项资金分配方案；加强业务指导、绩效管理、监督管理等工作；督促有关方做好专项资金支持政策实施工作。\n\n各市州、财政省直管县（市）财政、工信部门参照省级部门职责分工做好专项资金下达后的资金使用、项目报备、业务指导等工作，并进行监督和全过程绩效管理。\n\n资金申报、使用单位承担资金及项目绩效目标的真实客观申报，合规使用和有效管理的主体责任，负责直接受理资金申报材料的主管部门承担资金申报审核、资金使用监督的直接责任。"},{"no":"五","title":"第五条","text":"专项资金实行管理办法、申报通知、评审结果、分配结果、绩效评价全过程公开。"},{"no":"六","title":"专项资金的支持范围包括：","text":"专项资金的支持范围包括：\n\n（一）支持中小企业提升创新能力及专业化水平，优化创新创业环境。\n\n（二）支持完善中小企业公共服务体系，促进中小企业开展合作交流。\n\n（三）其他促进中小企业发展的工作。\n\n在符合上述支持方向内，每年根据党中央、国务院和省委、省政府有关决策部署，结合我省中小企业发展实际情况、亟待突破的短板和瓶颈等，由省财政厅、省工信厅按照零基安排、绩效导向的原则确定专项资金支持重点。对符合规定条件的新增重大项目和政策，省工信厅要组织开展事前绩效评估。"},{"no":"七","title":"第七条","text":"专项资金支持对象包括符合条件的项目或企业、中小企业公共服务平台等机构或载体，市县、园区等试点示范区域。"},{"no":"八","title":"第八条","text":"专项资金采取财政补助、以奖代补等支持方式，主要用于引导各级政府、社会资本等支持中小企业高质量发展。"},{"no":"九","title":"第九条","text":"专项资金不得用于平衡本级财政预算及偿还债务，不得用于行政事业单位人员经费、机构运转经费等。"},{"no":"十","title":"第十条","text":"专项资金分配可以采取因素法、项目法、因素法和项目法相结合等方式。"},{"no":"十一","title":"专项资金下达时间进度按照预算管理有关规定执行","text":"专项资金下达时间进度按照预算管理有关规定执行。省工信厅报送专项资金分配方案的时间不得晚于专项资金下达时限的前15日。各级财政部门应在收到专项资金指标发文30日内，将专项资金按要求拨付使用单位。"},{"no":"十二","title":"第十二条","text":"专项资金支付按照财政国库管理制度有关规定执行，涉及政府采购的，应当按照政府采购法律法规和有关制度执行。"},{"no":"十三","title":"第十三条","text":"省财政厅、省工信厅根据预算绩效管理和本办法的规定，以及专项资金有关支持政策文件，按照职责分工组织实施专项资金的绩效运行监控、绩效评价，加强绩效评价结果反馈应用。有关绩效评价结果，作为专项资金分配的重要参考。各市州、财政省直管县（市）财政、工信部门应按规定要求实施绩效评价。"},{"no":"十四","title":"省工信厅应当会同省财政厅加强对专项资金的监督管理","text":"省工信厅应当会同省财政厅加强对专项资金的监督管理。各市州、财政省直管县（市）工信、财政部门要建立健全专项资金使用管理、监督检查和跟踪问效制度，如发现资金申报、资金使用存在问题的，应当及时报告省工信厅和省财政厅。"},{"no":"十五","title":"第十五条","text":"资金使用单位收到专项资金后应当按照国家统一的财务会计制度规定管理。专项资金应当专款专用，主动接受财政、审计等部门的监督检查，不得用于支付各种罚款、捐款、赞助等。有关项目实施情况应当接受工信、财政等部门的调度和检查。"},{"no":"十六","title":"第十六条","text":"资金使用单位因市场环境、政策变化等导致不再符合专项资金支持标准的，应及时向直接受理其资金申报材料的工信、财政部门报告，有关工信、财政部门应及时向省工信厅、省财政厅报告。省工信厅会同省财政厅提出处理意见，市县有关部门督促落实，并按要求暂缓、停止拨付资金或收回已拨付资金。"},{"no":"十七","title":"第十七条","text":"专项资金应当严格执行有关财务、会计制度，实行专款专用，不得列支与项目无关的费用。"},{"no":"十八","title":"第十八条","text":"专项资金申报、评审、分配、拨付使用等过程中存在虚报、冒领、截留、挪用、滥用职权、玩忽职守、徇私舞弊等违法违纪行为的，严格按照《中华人民共和国预算法》《中华人民共和国公务员法》《中华人民共和国监察法》《财政违法行为处罚处分条例》等国家有关规定追究责任，涉嫌犯罪的，移送司法机关处理。资金使用单位应当严格遵守财政财务制度和财经纪律，建立健全专项资金管理制度和内部控制制度，加强财务稽核和内部审计，自觉接受审计、财政及主管部门的监督检查。"},{"no":"十九","title":"第十九条","text":"本办法自2024年1月1日起施行，有效期至2026年12月31日。到期后，省财政厅组织开展该专项的实施期绩效评估，评估结果作为该专项存续的依据。"}],"interpretations":[{"sectionNo":"六","headline":"专项资金支持三类事：提能力、建服务体系、促交流","who":"符合支持方向的中小企业、公共服务平台等机构或载体，以及市县、园区等试点示范区域。","materials":[],"window":"每年由省财政厅、省工信厅结合当年重点确定支持重点。","where":"省财政厅、省工业和信息化厅。","tip":"具体支持重点每年会调整，不是固定清单；新增重大项目还要做事前绩效评估。"},{"sectionNo":"七","headline":"能拿钱的不只是企业，平台和园区也算支持对象","who":"符合条件的项目或企业、中小企业公共服务平台等机构或载体、市县和园区等试点示范区域。","materials":[],"window":"按年度专项资金申报通知。","where":"省工信厅、省财政厅。","tip":"申报前先确认自己属于哪一类支持对象，平台和园区走的是不同口径。"},{"sectionNo":"十五","headline":"专项资金须专款专用，不得用于罚款、捐款、赞助","who":"收到专项资金的资金使用单位；应按国家统一的财务会计制度规定管理资金，专款专用，主动接受财政、审计等部门监督检查；不得用于支付各种罚款、捐款、赞助等。","materials":[],"window":"资金到账后至项目实施期间持续适用，原文未列具体期限。","where":"财政、审计部门；工信、财政部门（项目实施情况调度和检查）。","tip":"不得用于支付各种罚款、捐款、赞助等；项目实施情况须接受工信、财政等部门的调度和检查。"},{"sectionNo":"十六","headline":"不再符合支持标准的须及时报告，资金将被暂缓或收回","who":"已获得专项资金的资金使用单位；因市场环境、政策变化等导致不再符合专项资金支持标准的，应及时向直接受理其资金申报材料的工信、财政部门报告。","materials":[],"window":"自不再符合支持标准时及时报告，原文未列具体天数。","where":"直接受理其资金申报材料的工信、财政部门；省工信厅、省财政厅。","tip":"报告后由省工信厅会同省财政厅提出处理意见，市县有关部门督促落实，可暂缓、停止拨付或收回已拨付资金。"},{"sectionNo":"十七","headline":"专项资金专款专用，不得列支与项目无关费用","who":"使用专项资金的资金使用单位；须严格执行有关财务、会计制度，实行专款专用，不得列支与项目无关的费用。","materials":[],"window":"资金使用全过程适用，原文未列具体期限。","where":"原文未列具体监管受理部门，按财务会计制度执行。","tip":"本条是资金列支的硬性限制：与项目无关的费用一律不得从专项资金列支。"},{"sectionNo":"十八","headline":"虚报冒领、截留挪用将被追责，涉嫌犯罪移送司法","who":"专项资金申报、评审、分配、拨付使用各环节的相关单位与人员；资金使用单位应严格遵守财政财务制度和财经纪律，建立健全专项资金管理制度和内部控制制度，加强财务稽核和内部审计，自觉接受审计、财政及主管部门监督检查。","materials":[],"window":"贯穿申报、评审、分配、拨付使用全过程，原文未列具体期限。","where":"审计、财政及主管部门；涉嫌犯罪的移送司法机关。","tip":"虚报、冒领、截留、挪用、滥用职权、玩忽职守、徇私舞弊等行为，按预算法、公务员法、监察法、财政违法行为处罚处分条例等国家规定追责；涉嫌犯罪的移送司法机关。"}],"sourceUrl":"https://gxt.hunan.gov.cn/gxt/ztzl/zxzj/zdbf/202403/t20240328_33265389.html","sourceNote":"条文已于 2026-11-09 与官方页面/PDF 逐句比对，逐字一致（明细见 采集包/条文核对表.md）；2026-11-08 核对：页面发布日期 2023-12-30","verified":true,"isSample":false,"numberStyle":"clause","bodyVerified":"verbatim","hunan":true},{"id":"p-2024-7ab56f","title":"关于进一步支持大学生创业就业的若干措施","level":"provincial","region":"湖南省","issuer":"湖南省人力资源和社会保障厅、湖南省财政厅、湖南省教育厅","documentNo":"湘人社规〔2024〕2号","publishedAt":"2024-05-17","status":"active","tags":["创业补贴","贷款贴息","融资支持"],"audience":["小微企业","个体工商户","高校毕业生"],"summary":"大学生初次创办企业或个体工商户正常经营1年以上的，一次性创业补贴最低标准提高至1万元；创业担保贷款额度最高提高至400万元，20万元以下免除反担保。","sections":[{"no":"一","title":"支持和鼓励高校科研人员和学生共同创业","text":"1、高校科研人员离岗与学生共同创办企业的,其本人职称、年龄、资历、科技成果形式、获奖层次、获得专利与否均不作为限制条件,经个人书面申请,单位批准同意,可以申请1次离岗创业,最长期限不超过3年,可在3年内保留人事关系。离岗创业期间,停发工资福利待遇,养老保险、医疗保险(含生育保险)和职业年金依法继续由人事关系所在单位缴纳,单位部分由单位承担,个人部分由个人负责。工伤保险在所创办的企业缴纳,发生工伤时依法享受工伤保险待遇。离岗创业期间,允许通过所创办企业申报职称,所获得的职称可以作为其返回事业单位后参加岗位竞聘的参考。创业业绩突出,年度考核被确定为优秀等次的,不占原单位年度考核优秀比例。提前返岗的,应提前书面报告其人事关系所在单位,单位应在三个月内为其安排相应岗位。本人提出解除聘用合同的,其人事关系所在单位应及时依法解除合同,个人人事档案由用人单位转移到同级人社部门所属人力资源档案管理机构免费保管。\n2、高校科研人员在职与学生共同创办企业的,可在不影响完成本职工作的基础上,经个人书面申请,单位批准同意,进行在职创办企业。期间允许继续享有参加职称评审、项目申报、岗位竞聘、培训、考核、奖励等各方面权利,工资、社会保险等各项福利待遇不受影响。允许与企业职工同等享有获取报酬、奖金、股权激励的权利,国家另有规定的从其规定。工伤保险由在职创办企业缴纳,其在人事关系所在单位外工作期间发生工伤的,依法享受工伤保险待遇,由相关企业承担工伤保险责任。经与人事关系所在单位协商一致,可以实行相对灵活、弹性的工作时间。"},{"no":"二","title":"加大对大学生创业的金融支持力度","text":"3、设立湖南省大学生创业投资基金,扶持大学生创业就业。基金主要投资于具有良好市场发展前景的初创型项目,采用股权投资模式,重点支持大学生主导的创业项目。\n4、降低创业担保贷款及贴息门槛,对于高校毕业生、创业孵化基地在孵实体、获得“中国创翼”创业创新大赛市级以上(含市级)奖项的项目和中国国际大学生创新大赛金奖的项目,申请20万元以下个人创业担保贷款的,免除反担保手续,并按规定给予贴息。健全追偿代偿和呆坏账核销机制,制定担保基金尽职免责和激励约束办法,合理提升担保基金代偿比例和效率。加大省级财政支持力度,探索建立各级风险共担机制。\n5、提高一次性创业补贴标准,对大学生初次创办的企业或初次注册的个体工商户,且正常经营1年以上的,按规定给予一次性创业补贴,最低补贴标准提高至1万元(各市州已制定一次性创业补贴标准的,就高不就低)。\n6、提高贷款额度,对大学生创办的符合贷款条件的小微企业,创业担保贷款额度最高提高至400万元。"},{"no":"三","title":"加大对大学生创业的培训和指导力度","text":"7、深入实施“马兰花”创业培训行动,将有创业意愿的在校大学生纳入创业培训补贴范围,强化创业基础培训和后续“陪跑”服务,全面落实“创办你的企业”“乡村领雁”培训课程后续服务补贴。完善创业培训后续服务内容和清单,加快制定“改善你的企业”“网络创业培训”等课程后续服务补贴标准。加强创业培训课程开发,组织专家团队开发适合大学生创业群体创业特性的培训课程体系。\n8、支持高校和社会力量建立“创业指导工作室”,支持工作室导师采用“揭榜挂帅”的方式,对大学生创业项目提供一对一指导、创业培训后续服务和创业“陪跑”服务等。鼓励成立创业服务协会、大学生创业者联盟等社会组织,组织开展创业讲堂、创业训练营、创业实训等创业服务活动。\n9、探索在职称(职务)评聘工作中单独设立大学生创业和就业指导专业,进一步畅通创业就业指导教师职称评审渠道。建立完善省级高校创业创新导师数据库,从高校、企业及社会创业就业服务机构遴选创业创新专家。支持高校从校外选聘创业创新专家担任兼职教师,充实高校创业创新师资力量,加快培养一支数量充足、素质优良、服务优质的创业就业导师人才队伍,为我省大学生创业就业指导和研究提供人才储备与智力支持。"},{"no":"四","title":"加大对大学生创业的示范引领力度","text":"10、开展优秀大学生创业项目认定,每年扶持一定数量的已纳入创业孵化基地入孵管理大学生创业项目或创业团队开展创业。对获评省级大学生创业孵化基地的给予重点支持,对各高校开展校园招聘工作,按规定给予校园招聘活动补助。\n11、鼓励各院校建设大学生创业孵化基地,并及时纳入我省创业孵化基地认定范围,开展大学生创业创新孵化示范基地评建,将大学生创业项目孵化时间延长至5年,按规定落实创业孵化基地创业服务补助。降低大学生创业团队入驻条件,优化服务经办流程,为大学生创业团队提供创业指导、开业指导等“一站式”孵化服务。鼓励其他院校以外的社会各创业孵化基地安排场地优先提供给大学生创业项目入驻,并给予场租和管理费用减免。"},{"no":"五","title":"加大对大学生创业的保障力度","text":"12、探索设置大学生创业保险,通过政保合作的方式,为大学生创业“兜底”,解除大学生创业的后顾之忧。完善大学生创业预警机制,对于创业失败大学生及时开展职业培训、就业援助、就业服务,帮助“再就业”“再创业”。\n13、坚持以赛促教、以赛促学、以赛促创,鼓励各级举办“中国创翼”创业创新大赛、中国国际大学生创新大赛、 “耀动三湘”网络创业直播大赛等各类创业大赛,引导不同学段学生积极参赛,激发大学生创业创新热情。鼓励与行业企业深化赛事合作,拓宽办赛资金筹措渠道。加强对各类大赛中涌现的优秀项目进行后续跟踪,推动一批大赛优秀项目落地。\n14、建设湖南省大学生创业就业大平台,融合信息服务、技术培训、机动实习、成果转化、企业孵化等内容,加强创业资源的整合与利用。在全省大学生创业创新孵化一体化服务平台、“湘就业”平台上设置创业服务专区,推动创业政策发布、信息查询、项目申报、资源对接等功能“一网集聚”,方便高校学生享受创业一站式服务。\n15、进一步优化政策资金申领流程,充分利用大数据比对等方式,减少申报资料提交,推动实现网上申报、网上审核、联网核查。对能依托管理信息系统或与相关单位信息共享、业务协同获得的个人及单位信息、资料的,不再要求单位及个人报送纸质材料,符合条件的要及时拨付资金。要加强全过程监督,对工作人员在项目申报、评选及资金拨付使用等工作中,存在滥用职权、玩忽职守、徇私舞弊等违纪违法行为的,依照国家有关法律法规追究相应责任。涉嫌犯罪的,依法移送司法机关处理。\n16、加强大学生创业宣传引导,利用短视频等各类新媒体资源,建立宣传矩阵,及时发布相关政策文件与政策解读。利用“创业微电影”等方式广泛宣传大学生创业优秀案例,树立大学生创业典型,培育高校创客文化。组织开展“企业家进校园讲好创业就业故事”等系列活动,遴选更多优质企业家深入高校开展创业创新公益活动,每年省级层面举办讲座不少于20场次,营造“鼓励创业、宽容失败”的良好氛围。\n本文件自2024年5月21日起执行,有效期五年。此前有关规定与本文件不一致的,以本文件为准。"}],"interpretations":[{"sectionNo":"二","headline":"大学生首次创业满1年，一次性补贴最低1万元","who":"大学生初次创办的企业或初次注册的个体工商户，且正常经营1年以上。各市州已制定一次性创业补贴标准的，就高不就低。","materials":[],"window":"正常经营1年以上方可申领。","where":"创业主体注册地的人力资源社会保障部门。","tip":"这是省级最低标准，各市州自己的标准更高时按高的执行。"},{"sectionNo":"二","headline":"大学生申请20万元以下创业担保贷款，免反担保","who":"高校毕业生、创业孵化基地在孵实体、获得「中国创翼」市级以上奖项的项目、中国国际大学生创新大赛金奖项目。","materials":[],"window":"按创业担保贷款经办流程办理。","where":"经办银行与当地人力资源社会保障部门。","tip":"大学生创办且符合条件的小微企业，创业担保贷款额度最高可提到400万元。"},{"sectionNo":"一","headline":"高校科研人员可离岗创业3年，保留人事关系","who":"高校科研人员离岗与学生共同创办企业的，经个人书面申请、单位批准同意。","materials":[],"window":"可申请1次离岗创业，最长期限不超过3年，期间保留人事关系。","where":"向本人人事关系所在单位申请。","tip":"离岗期间停发工资福利待遇，社保和职业年金单位部分仍由原单位承担、个人部分自己负责。"},{"sectionNo":"三","headline":"在校大学生可参加“马兰花”创业培训，按规定享培训补贴","who":"有创业意愿的在校大学生；高校及社会力量建立的“创业指导工作室”及导师；高校创业就业指导教师。","materials":[],"window":"自2024年5月21日起执行，有效期五年","where":"省级高校创业创新导师数据库；高校“创业指导工作室”","tip":"后续服务补贴覆盖“创办你的企业”“乡村领雁”培训课程；“改善你的企业”“网络创业培训”等课程后续服务补贴标准另行制定。"},{"sectionNo":"四","headline":"大学生创业项目孵化期延长至5年，优秀项目每年获扶持","who":"已纳入创业孵化基地入孵管理的大学生创业项目或创业团队；获评省级大学生创业孵化基地的院校、基地；入驻孵化基地的大学生创业团队。","materials":[],"window":"大学生创业项目孵化时间延长至5年；每年扶持一定数量优秀项目（原文表述“每年扶持一定数量”）","where":"省级大学生创业孵化基地；各院校大学生创业孵化基地","tip":"获评省级大学生创业孵化基地的给予重点支持；降低大学生创业团队入驻条件；社会孵化基地应安排场地优先供大学生项目并减免场租、管理费。"},{"sectionNo":"五","headline":"大学生创业可享创业保险“兜底”，创业失败有再就业帮扶","who":"在湘创业的大学生；创业失败的大学生；参加“中国创翼”等创业大赛的大学生和高校学生。","materials":[],"window":"自2024年5月21日起执行，有效期五年","where":"湖南省大学生创业就业大平台；“湘就业”平台；全省大学生创业创新孵化一体化服务平台","tip":"网上申报、网上审核、联网核查，能通过信息共享获得的资料不再要求报送纸质材料；项目申报、资金拨付中违纪违法将被追责。"}],"sourceUrl":"https://img.zhuzhou.gov.cn/zzcms/DFS/file/2024/06/11/20240611090410597w5kpib.pdf","sourceNote":"条文已于 2026-11-09 与官方页面/PDF 逐句比对，逐字一致（明细见 采集包/条文核对表.md）","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"p-2024-8a0745","title":"湖南省财政厅 湖南省人力资源和社会保障厅关于印发《湖南省就业补助资金管理办法》的通知","level":"provincial","region":"湖南省","issuer":"湖南省财政厅、湖南省人力资源和社会保障厅","documentNo":"湘财社〔2024〕33号","publishedAt":"2024-12-27","status":"active","tags":["社保补贴","就业补贴","创业补贴"],"audience":["小微企业","个体工商户","高校毕业生"],"summary":"就业困难人员灵活就业社保补贴不超过其实际缴费的2/3、期限最长3年，小微企业招用高校毕业生给予最长1年社保补贴。","sections":[{"no":"一","title":"第一条","text":"根据《中华人民共和国预算法》《中华人民共和国就业促进法》《中共中央国务院关于全面实施预算绩效管理的意见》《中共中央国务院关于实施就业优先战略促进高质量充分就业的意见》《财政部人力资源社会保障部关于印发〈就业补助资金管理办法〉的通知》（财社〔2023〕181号）等相关法律法规和规定，为推动实施就业优先战略，促进高质量充分就业，落实各项就业创业扶持政策，规范就业补助资金管理，提高资金使用效益，结合我省实际，制定本办法。"},{"no":"二","title":"第二条","text":"本办法所称就业补助资金是由县级以上人民政府设立，由本级财政部门和人力资源社会保障部门共同管理，通过一般公共预算安排用于促进就业创业的专项资金。"},{"no":"三","title":"本办法所规范的就业补助资金包括：","text":"本办法所规范的就业补助资金包括：\n（一）中央财政安排我省的就业补助资金；\n（二）省市县各级财政年度预算安排的促进就业创业工作的专项资金；\n（三）社会各界为公益性就业服务提供的捐赠、资助等其他收入。\n失业保险基金中用于促进就业创业的支出，按国家和省有关规定执行。"},{"no":"四","title":"第四条","text":"县级以上人民政府应当根据当地就业状况和就业工作目标，在本级财政预算中安排就业补助资金用于促进就业创业工作，确保就业政策落实到位。"},{"no":"五","title":"就业补助资金管理应遵循以下原则：","text":"就业补助资金管理应遵循以下原则：\n（一）注重普惠，重点倾斜。落实国家和省普惠性的就业创业扶持政策，重点支持就业困难群体就业创业，适度向财政困难、就业工作任务重的地区倾斜，促进各类劳动者公平就业，推动地区间就业协同发展。\n（二）奖补结合，激励相容。优化机制设计，奖补结合，充分调动各级政策执行部门、政策对象等积极性。\n（三）科学合理，提升质效。提高政策可操作性和精准性，优化资金支持结构，加强监督与控制，以绩效导向、结果导向强化就业补助资金管理，并结合就业形势和工作任务变化对政策进行动态调整。"},{"no":"六","title":"第六条","text":"就业补助资金分为对个人和单位的补贴、公共就业服务能力建设补助两类。\n对个人和单位的补贴资金用于职业培训补贴、职业技能评价补贴、就业见习补贴、一次性求职补贴、一次性创业补贴、社会保险补贴、公益性岗位补贴及其他支出；公共就业服务能力建设补助资金用于就业创业服务补助和高技能人才培养补助及其他支出。\n同一项目就业补助资金补贴与失业保险基金补贴有重复的，个人和单位不可重复享受。"},{"no":"七","title":"职业培训补贴","text":"职业培训补贴。享受职业培训补贴的人员范围包括：防止返贫监测对象、毕业年度高校毕业生（含技工院校高级工班、预备技师班、技师班和特殊教育院校职业教育类毕业生，下同）、城乡未继续升学的应届初高中毕业生、农村转移就业劳动者、城镇登记失业人员、就业困难人员等（以下统称六类人员），以及符合条件的企业职工。\n职业培训补贴用于以下方面：\n（一）就业技能培训。对参加就业技能培训的六类人员，培训后取得符合规定证书的（包括职业资格证书、职业技能等级证书、专项职业能力证书、职业培训合格证书，下同），按规定标准给予职业培训补贴。\n（二）创业培训。对参加创业培训的六类人员和大中专院校在校学生（含中职、技校）、离校2年内未就业高校毕业生、登记自主创业人员、有创业意愿的企业单位职工，培训后取得创业培训合格证书的，按培训类别给予一定标准的职业培训补贴。\n（三）企业职工岗位技能培训。对企业新录用的六类人员，与企业签订1年以上期限劳动合同，并于签订劳动合同之日起1年内参加由企业依托所属培训机构或政府认定的培训机构开展企业职工岗位技能培训的，培训后取得高级及以下规定证书的，按规定标准给予职工个人或企业培训补贴。\n对按国家有关规定参加企业新型学徒制培训企业在职职工（含与企业签订半年以上实习协议或就业协议的技工院校毕业年度在企业实习学生），培训后取得证书（含职业资格证书、职业技能等级证书、培养合格证书）的，按规定标准给予职工个人或企业培训补贴。\n对符合晋升等级条件的企业在职职工参加职业技能培训后，取得技师及以上职业资格证书或职业技能等级证书的，按规定标准给予职工个人或企业培训补贴。\n（四）项目制培训。各地人力资源社会保障、财政部门可按规定通过项目制方式，向符合条件的培训机构整建制购买就业技能培训或创业培训服务，开展定点、定向、定岗等项目定制培训，对承担项目制培训任务的培训机构，给予一定标准职业培训补贴。\n上述符合条件享受职业培训补贴政策的人员，每人累计最多享受3次（含职业技能培训补贴、创业培训补贴），自2024年1月1日起计算。同一职业（工种）不得重复同级或降级享受职业技能培训补贴。同一职业（工种）同一等级的职业技能培训补贴和失业保险参保职工技能提升补贴不能重复享受。\n职业培训补贴实行“先垫后补”和“信用支付”等办法，经职业培训补贴对象同意，可由培训机构先行垫付培训费用，代为申领培训补贴。支持有条件的地方探索为培训对象建立职业培训个人信用账户，鼓励培训对象自主选择培训机构和课程，并通过信用账户支付培训费用。"},{"no":"八","title":"职业技能评价补贴","text":"职业技能评价补贴。\n对通过初次职业技能评价并取得符合规定证书（包括职业资格证书、职业技能等级证书、专项职业能力证书，不含培训合格证）的六类人员，给予职业技能评价补贴。对纳入重点产业国家职业资格评价和职业技能等级认定目录的职业工种，可适当提高补贴标准。每人累计最多享受3次，自2024年1月1日起计算，同一职业（工种）不得重复同级或降级享受。"},{"no":"九","title":"就业见习补贴","text":"就业见习补贴。\n对符合条件的见习单位吸纳离校2年内未就业高校毕业生和16-24岁登记失业青年，给予一定标准的就业见习补贴。补贴标准按当地最低工资标准执行，对见习人员见习期满留用率达到50%以上的见习单位，见习补贴标准可提高至当地最低工资标准的120%，补贴期限最长不超过12个月。补贴用于见习单位支付见习人员见习期间基本生活费、为见习人员办理人身意外伤害保险，以及对见习人员的指导管理费用。"},{"no":"十","title":"一次性求职补贴","text":"一次性求职补贴。\n对在毕业学年积极求职创业的低保家庭、零就业家庭、防止返贫监测对象家庭和特困人员中的高校毕业生，残疾及获得国家助学贷款的高校毕业生，给予一定标准的一次性求职补贴。"},{"no":"十一","title":"一次性创业补贴","text":"一次性创业补贴。\n对在省内首次创办小微企业或从事个体经济，且所创办企业或个体工商户自工商登记注册之日起正常运营1年以上的离校2年内高校毕业生、就业困难人员、返乡入乡农民工给予企业或个体经营者一定标准的一次性创业补贴。"},{"no":"十二","title":"社会保险补贴","text":"社会保险补贴。\n享受社会保险补贴的人员范围包括：我省认定的符合条件的就业困难人员和高校毕业生。\n社会保险补贴用于以下方面：\n（一）就业困难人员社会保险补贴。对招用就业困难人员并缴纳社会保险费的单位，以及通过公益性岗位安置就业困难人员并缴纳社会保险费的单位，按其为就业困难人员实际缴纳的基本养老保险费、基本医疗保险费和失业保险费给予补贴，不包括就业困难人员个人应缴纳的部分。对就业困难人员灵活就业后缴纳的社会保险费，给予一定数额的社会保险补贴，补贴标准原则上不超过其实际缴费的2/3。就业困难人员社会保险补贴期限，除对距法定退休年龄不足5年的就业困难人员可延长至退休外，其余人员最长不超过3年（以初次核定其享受社会保险补贴时年龄为准）。\n就业困难人员灵活就业后享受社会保险补贴与单位招用（安置）就业困难人员享受的社会保险补贴的补贴期限合并计算。\n（二）高校毕业生社会保险补贴。对招用毕业年度和离校2年内未就业高校毕业生，与之签订1年及以上劳动合同并为其缴纳社会保险费的小微企业，给予最长1年的社会保险补贴，不包括高校毕业生个人应缴纳的部分。对离校2年内未就业的高校毕业生灵活就业后缴纳的社会保险费，给予一定数额的社会保险补贴，补贴标准原则上不超过其实际缴费的2/3，补贴期限最长不超过2年。\n高校毕业生灵活就业后享受社会保险补贴与小微企业招用高校毕业生享受的社会保险补贴的补贴期限合并计算。\n高校毕业生社会保险补贴与就业困难人员社会保险补贴的补贴期限合并计算。"},{"no":"十三","title":"公益性岗位补贴","text":"公益性岗位补贴\n公益性岗位安置对象为我省认定的符合条件的就业困难人员和通过市场渠道确实难以就业的困难高校毕业生（含脱贫家庭、低保家庭、零就业家庭及残疾高校毕业生等），优先安排符合岗位条件的距离法定退休年龄不足5年失业人员和零就业家庭成员。\n对公益性岗位安置的就业困难人员给予岗位补贴，补贴标准参照当地最低工资标准执行。\n公益性岗位补贴期限，除对距法定退休年龄不足5年的就业困难人员可延长至退休外，其余人员最长不超过3年（以初次核定其享受公益性岗位补贴时年龄为准）。对公益性岗位补贴期满后仍难以通过其他渠道实现就业的大龄就业困难人员、零就业家庭中的就业困难人员、重度残疾人等，可在到期退岗后重新认定，再次按程序通过公益性岗位予以安置，岗位补贴和社会保险补贴期限重新计算，并报送省人力资源社会保障厅、省财政厅备案，累计安置次数不超过2次。\n乡村公益性岗位补贴按照现行有关规定执行。"},{"no":"十四","title":"就业创业服务补助","text":"就业创业服务补助\n就业创业服务补助主要用于以下方面：\n（一）用于加强公共就业创业服务平台服务能力建设。重点支持公共就业创业服务机构加强就业信息网络系统建设及维护，开展城乡劳动力信息采集及更新，开展线上线下招聘活动及就业创业服务，开展就业创业宣传活动等。对于基层公共就业服务机构（含政府设立的家门口就业服务站、零工市场、人社驿站等）承担的免费公共就业服务和创业孵化基地开展的创业孵化服务，可根据工作量、专业性和成效等，给予一定的补助。对公共就业创业服务机构、高校开展的招聘活动和创业服务，可根据服务人数、成效和成本等，给予一定的补助。\n（二）用于向社会购买基本就业创业服务。县级以上人力资源社会保障、财政部门可按政府购买服务相关规定，向社会购买基本就业创业服务。基本就业创业服务包括向社会购买就业（职业）指导、就业（职业）规划、职业介绍、就业（创业）政策研究咨询、创业指导服务；人力资源市场调查、就业信息收集与统计分析（统计监测）、委托开展第三方检查核查、就业（创业）信息发布、有组织劳务输出和劳务协作；其他适合通过市场化方式提供的基本就业创业服务。"},{"no":"十五","title":"高技能人才培养补助","text":"高技能人才培养补助\n高技能人才培养补助重点用于高技能人才培训基地建设、技能大师工作室建设等项目支出。\n（一）高技能人才培训基地建设。各地应当结合区域经济发展、产业振兴发展规划和新兴战略性产业发展的需要，依托企业、院校、职业培训机构等具备高技能人才培训能力的单位，建设高技能人才培训基地，重点开展高技能人才研修提升培训、高技能人才评价、高技能人才课程研发、高技能人才成果交流等活动。\n（二）技能大师工作室建设。各地应当发挥高技能领军人才在带徒传技、技能攻关、技艺传承、技能推广等方面的重要作用，选拔行业企业生产和服务一线的优秀高技能人才，依托其所在单位建设技能大师工作室，开展培训、研修、攻关、交流等技能传承提升活动。\n（三）鼓励我省职业学校为省内先进制造业等重点产业的企业输送高技能人才，各地对本地职业学校为省内企业输送高技能人才的，可根据输送的高技能人才数量、质量和服务年限等条件，给予职业学校一定补助。补助流程和补助标准由各市州自行确定，报省人力资源社会保障厅备案后实施。"},{"no":"十六","title":"其他支出","text":"其他支出\n其他支出是指各地根据就业形势变化在确保国家确定的各项就业补贴政策落实到位的基础上，经省级人民政府批准，符合国家、省就业政策导向，与促进重点群体就业创业直接相关，现有补贴政策无法覆盖的就业创业扶持政策支出。\n对企业自行招用毕业年度和离校2年内未就业的高校毕业生及16—24岁登记失业青年，签订劳动合同，并按规定为其足额缴纳3个月以上的失业、工伤、职工养老保险费的，给予企业1500元每人的一次性吸纳就业稳岗补贴，与一次性扩岗补助不重复享受。"},{"no":"十七","title":"第十七条","text":"就业补助资金中对个人和单位的补贴资金的具体标准，已有明确规定的，按规定执行。未明确规定的，在符合既有原则的基础上，由省人力资源社会保障厅、省财政厅结合全省实际确定。各地应合理确定并科学控制公益性岗位补贴占比，严格控制就业创业服务补助和其他支出比例。"},{"no":"十八","title":"就业补助资金不得用于以下支出：","text":"就业补助资金不得用于以下支出：\n（一）办公用房、职工宿舍建设及维修，交通工具购置及运维支出。\n（二）发放工作人员工资、津贴补贴等支出。\n（三）“三公”经费支出。\n（四）普惠金融项下创业担保贷款（原小额担保贷款）贴息及补充创业担保贷款基金相关支出。\n（五）办公设备及耗材、报刊书籍订阅、走访慰问等支出。\n（六）赛事组织实施经费、奖金等支出。\n（七）按规定应由其他财政资金渠道安排的支出。\n（八）法律法规禁止的其他支出。\n不得对机关事业单位在编人员发放本办法中的补贴。\n个人、单位按照本办法申领获得的补贴资金，具体用途可由申请人或申请单位确定，不受本条规定限制。\n第三章资金分配与下达"},{"no":"十九","title":"第十九条","text":"中央和省财政安排的就业补助资金，采取因素法与项目法相结合的方式。除用于国家级、省级项目之外，其他资金坚持“不定基数、因素分配、注重绩效”的原则，因素法分配下达到市州本级和省直管县。\n项目法分配的资金采取评审、评议、竞争性分配、集体研究等方式确定支持对象。\n对落实就业优先政策、推动高质量充分就业、促进重点群体就业创业等任务完成较好的市州、县市区进行评选评价，在分配就业补助资金时予以适当支持。\n对重点群体就业任务较重、承担国家和省重大活动、创业带动就业成效明显的地区，在分配就业补助资金时予以适当支持。"},{"no":"二十","title":"第二十条","text":"因素法分配的因素包括基础因素、投入因素、工作成果因素、重点工作因素等四类，并通过绩效调节系数和财力调节系数进行调节。其中：\n（一）基础因素权重为35%，包括常住人口数、登记失业人数等，重点考虑就业工作任务量。\n（二）投入因素权重为15%，包括地方财政投入、资金结余消化等，重点考虑地方投入力度和预算执行情况，引导地方加大投入，加快预算执行。\n（三）工作成果因素权重为15%，包括就业工作综合绩效评价、城镇新增就业人数、资金使用管理绩效等，重点考虑就业工作成果完成情况。\n（四）重点工作因素权重为35%，包括高校毕业生就业创业、乡村振兴、职业培训等工作，每年根据人力资源社会保障部、财政部和省委、省政府工作重点适时调整。\n每年分配资金选择的因素、权重、方式及增减幅上下限，可根据年度全省就业整体形势和工作任务重点适当调整。\n绩效调节系数和财力调节系数分别通过绩效评价结果和财政困难程度系数确定。"},{"no":"二十一","title":"第二十一条","text":"在因素法分配中央和省级财政就业补助资金时，省级人力资源社会保障部门负责会同有关部门提供资金测算需要的与就业相关的基础数据、绩效评价结果和资金分配建议。省级财政部门负责收集汇总资金结转结余、预算执行、财政困难程度系数等业务相关数据。各单位按照“谁提供、谁负责”的原则，对所提供数据的准确性、完整性、及时性负责。"},{"no":"二十二","title":"第二十二条","text":"高技能人才培养补助资金实行项目管理，各地人力资源社会保障部门应当编制高技能人才培养中长期规划，确定本地区支持的高技能人才重点领域。对经人力资源社会保障部、财政部备案同意的国家级高技能人才培养项目，根据备案结果给予分类分档补助。省级高技能人才培养项目由省人力资源社会保障厅会同省财政厅组织实施，按规定给予补助。"},{"no":"二十三","title":"第二十三条","text":"省、市州级财政、人力资源社会保障部门应当在收到上级资金分配通知后30日内，正式下达就业补助资金预算；省、市州级财政、人力资源社会保障部门应当将本级政府预算安排给下级政府的就业补助资金在本级人民代表大会批准预算后60日内正式下达到下级财政、人力资源社会保障部门。省级资金分配方案抄送财政部湖南监管局。\n地方各级财政、人力资源社会保障部门在收到上级财政转移支付预算时，应核对无误后再下达。如发现问题，应立即向上级财政、人力资源社会保障部门报告。地方不得擅自分配处置存疑的转移支付资金。\n地方各级财政、人力资源社会保障部门部门应对其使用的就业补助资金提出明确的资金管理要求，及时组织实施各项就业创业政策。"},{"no":"二十四","title":"第二十四条","text":"各级人力资源社会保障、财政部门应对就业补助资金全面实施预算绩效管理，建立健全全过程预算绩效管理链条，做好事前绩效评估，加大绩效目标审核力度。建立部门全面监控和财政重点监控机制，年度预算结束后，应当开展绩效自评，每年选择部分重点资金和项目开展部门评价和财政评价。将绩效评价作为项目调整、预算调整以及下一年预算安排的重要依据。全面强化绩效目标管理，做好绩效运行监控和绩效评价，并加强绩效评价结果应用，加大绩效信息公开力度，提高资金配置效率和使用效益。鼓励各地探索建立科学规范的绩效考核目标体系，积极推进就业补助资金的绩效管理。"},{"no":"二十五","title":"第二十五条","text":"各级人力资源社会保障部门要在坚持转变政府职能、提高行政效能的基础上，梳理并公开本地区就业补贴政策清单，明确申请材料、申领流程、经办渠道、办理时限等。应当建立和完善就业资金发放台账，做好就业资金管理的基础工作，有效甄别享受补贴政策人员和单位的真实性，特别是对补贴金额大、人数多、期限长的补贴对象要加强核查抽查，防止出现造假行为。落实好政府采购等法律法规的有关规定，规范采购行为。\n各级人力资源社会保障、财政部门应按规定加强信息化建设，依托湖南省人力资源社会保障一体化业务管理系统，将补贴申请、受理、审核、拨付纳入系统管理，并实现就业数据与财政、社保、工商、税务、民政等数据信息共享。对能依托系统或与相关单位信息共享、业务协同获得的信息和资料，不再要求提供纸质材料。对面向个人的补贴，具备条件的可通过社会保障卡发放。"},{"no":"二十六","title":"第二十六条","text":"就业补助资金严格按照国库集中支付管理制度相关规定支付。资金使用过程中，涉及政府采购的，应按照政府采购有关法律法规及制度执行。\n各级财政、人力资源社会保障部门应加快预算执行进度，及时拨付到位，盘活存量资金，提高资金使用效益，结转结余资金按照中央和省有关盘活财政存量资金的规定进行管理。"},{"no":"二十七","title":"第二十七条","text":"各级财政、人力资源社会保障部门应建立健全财务管理规章制度，强化内部财务管理，严格落实财务管理规定，落实岗位设置权限分设和权限不相容要求，优化业务流程，加强内部风险防控。"},{"no":"二十八","title":"第二十八条","text":"各级财政、人力资源社会保障部门应加强对就业补助资金管理使用情况的监督检查，主动开展自查互查、交叉检查或委托第三方检查等，自觉接受巡视巡察、审计等部门的检查和社会监督。"},{"no":"二十九","title":"第二十九条","text":"各级财政、人力资源社会保障部门应按照财政预决算管理的总体要求，做好年度预决算工作，并按要求向社会公开。"},{"no":"三十","title":"第三十条","text":"各级人力资源社会保障、财政部门应做好信息公开工作，通过当地媒体、部门网站等向社会公开年度就业工作总体目标、工作任务完成、各项补贴资金的使用等情况。\n各项补贴资金的使用情况公开内容包括：享受各项补贴的单位名称或人员名单（含隐藏部分位数的身份证号码）、补贴标准及具体金额等。其中，公益性岗位补贴还应公开公益性岗位名称、设立单位、安置人员名单、享受补贴时间等；一次性求职补贴应在发放前在校内公示。\n各级人力资源社会保障、财政部门要严格遵守国家有关个人信息保护的法规制度，既保证资金使用公开透明，又避免个人敏感信息泄露。"},{"no":"三十一","title":"第三十一条","text":"各级人力资源社会保障、财政部门应当建立用人单位、个人责任追究机制，对虚报、冒领、套取就业补助资金补贴补助的，责令退回，依法纳入社会信用体系，实施多部门联合惩戒，涉及犯罪的，依法移送司法机关。"},{"no":"三十二","title":"第三十二条","text":"各级财政、人力资源社会保障部门应建立就业补助资金“谁使用、谁负责”的责任追究机制。\n各级财政、人力资源社会保障部门及其工作人员在就业补助资金的分配审核、使用管理等工作中，存在违反本办法规定的行为，以及其他滥用职权、玩忽职守、徇私舞弊等违法违规行为的，依法追究相应责任。涉嫌犯罪的，依法移送有关机关处理。\n对疏于管理、违规使用资金的地方，将相应扣减其下一年度就业补助资金；情节严重的，取消其下一年度获得就业补助资金的资格，并在全省范围内予以通报。\n第五章附 则"},{"no":"三十三","title":"第三十三条","text":"本办法由省财政厅、省人力资源社会保障厅根据各自职能负责解释。各市县财政、人力资源社会保障部门严格按本办法执行。"},{"no":"三十四","title":"本办法自发布之日起施行，有效期5年","text":"本办法自发布之日起施行，有效期5年。有效期内国家出台新规定与本办法不一致的，以国家新规定为准。此前有关政策文件关于就业补助资金的规定与本办法不一致的，以本办法为准。"}],"interpretations":[{"sectionNo":"十二","headline":"灵活就业社保补贴最高补实际缴费的2/3，最长3年","who":"我省认定的就业困难人员（灵活就业或以单位招用、公益性岗位安置），以及毕业年度和离校2年内未就业的高校毕业生（小微企业招用或灵活就业）。","materials":[],"window":"就业困难人员最长不超过3年，距法定退休年龄不足5年的可延长至退休；高校毕业生被小微企业招用的最长1年，灵活就业的最长2年。","where":"当地人力资源社会保障部门，通过湖南省人社一体化业务管理系统办理。","tip":"单位招用与灵活就业的社保补贴期限合并计算；高校毕业生社保补贴与就业困难人员社保补贴期限也合并计算。"},{"sectionNo":"十一","headline":"省内首次创业、正常运营满1年，可领一次性创业补贴","who":"离校2年内高校毕业生、就业困难人员、返乡入乡农民工；须在省内首次创办小微企业或从事个体经营，且自工商登记注册之日起正常运营1年以上。","materials":[],"window":"自工商登记注册之日起正常运营1年以上方可申领。","where":"当地人力资源社会保障部门；补贴政策清单、申请材料、经办渠道由各地人社部门公开。","tip":"具体补贴标准本办法未定死，由省人力资源社会保障厅、省财政厅结合全省实际确定，各市县按本地口径执行。"},{"sectionNo":"六","headline":"就业补助资金分两类，同一项目与失业保险基金补贴不可重复享受","who":"申领职业培训补贴、职业技能评价补贴、就业见习补贴、一次性求职补贴、一次性创业补贴、社会保险补贴、公益性岗位补贴等对个人和单位补贴的对象；同一项目已享受失业保险基金补贴的不可重复享受。","materials":[],"window":"按各补贴项目规定的申报期和期限执行。","where":"各级人力资源社会保障、财政部门；具体经办渠道按各补贴项目规定。","tip":"同一项目就业补助资金补贴与失业保险基金补贴有重复的，个人和单位不可重复享受。"},{"sectionNo":"七","headline":"六类人员及企业职工可享职业培训补贴，每人累计最多3次","who":"防止返贫监测对象、毕业年度高校毕业生（含技工院校高级工班、预备技师班、技师班和特殊教育院校职业教育类毕业生）、城乡未继续升学的应届初高中毕业生、农村转移就业劳动者、城镇登记失业人员、就业困难人员等六类人员，以及符合条件的企业职工；企业职工岗位技能培训须与企业签订1年以上劳动合同，并于签订之日起1年内参训；创业培训还覆盖大中专院校在校学生（含中职、技校）、离校2年内未就业高校毕业生、登记自主创业人员、有创业意愿的企业单位职工。","materials":[],"window":"每人累计最多享受3次（含职业技能培训补贴、创业培训补贴），自2024年1月1日起计算。","where":"企业依托所属培训机构或政府认定的培训机构开展；项目制培训由人力资源社会保障、财政部门向符合条件的培训机构购买服务。","tip":"同一职业（工种）不得重复同级或降级享受；同一职业（工种）同一等级的职业技能培训补贴和失业保险参保职工技能提升补贴不能重复享受；实行“先垫后补”和“信用支付”，经本人同意可由培训机构先行垫付并代为申领。"},{"sectionNo":"八","headline":"六类人员初次取得职业技能评价证书，可享评价补贴，最多3次","who":"通过初次职业技能评价并取得职业资格证书、职业技能等级证书或专项职业能力证书（不含培训合格证）的六类人员；纳入重点产业国家职业资格评价和职业技能等级认定目录的职业工种可适当提高标准。","materials":[],"window":"每人累计最多享受3次，自2024年1月1日起计算。","where":"开展初次职业技能评价的机构；职业工种须在重点产业国家职业资格评价和职业技能等级认定目录内。","tip":"不含培训合格证；同一职业（工种）不得重复同级或降级享受。"},{"sectionNo":"九","headline":"见习单位吸纳离校2年内未就业高校毕业生，补贴最长12个月","who":"符合条件的见习单位，吸纳离校2年内未就业高校毕业生和16-24岁登记失业青年；补贴标准按当地最低工资标准执行。","materials":[],"window":"补贴期限最长不超过12个月；见习期满留用率达到50%以上的，补贴标准可提高至当地最低工资标准的120%。","where":"见习单位所在地；补贴标准按当地最低工资标准执行。","tip":"补贴用于见习单位支付见习人员基本生活费、办理人身意外伤害保险及指导管理费用；留用率50%以上的才可上浮至120%。"},{"sectionNo":"十","headline":"困难高校毕业生毕业学年求职创业，可领一次性求职补贴","who":"在毕业学年积极求职创业的低保家庭、零就业家庭、防止返贫监测对象家庭和特困人员中的高校毕业生，以及残疾高校毕业生和获得国家助学贷款的高校毕业生。","materials":[],"window":"毕业学年内申请，一次性发放。","where":"毕业学年所在高校；补贴按当地经办渠道申领。","tip":"须属低保家庭、零就业家庭、防止返贫监测对象家庭、特困人员、残疾或获得国家助学贷款的高校毕业生之一，且在毕业学年积极求职创业。"},{"sectionNo":"十三","headline":"公益性岗位安置困难人员，补贴最长3年，距退休不足5年延至退休","who":"我省认定的符合条件的就业困难人员和通过市场渠道确实难以就业的困难高校毕业生（含脱贫家庭、低保家庭、零就业家庭及残疾高校毕业生等）；优先安排距法定退休年龄不足5年的失业人员和零就业家庭成员。","materials":[],"window":"补贴期限最长不超过3年（以初次核定享受补贴时年龄为准）；距法定退休年龄不足5年的可延长至退休；期满后仍难就业的可重新认定安置，累计安置次数不超过2次。","where":"当地人力资源社会保障部门；乡村公益性岗位按现行有关规定执行。","tip":"补贴标准参照当地最低工资标准执行；再次安置须按程序重新认定并报省人力资源社会保障厅、省财政厅备案，累计安置次数不超过2次。"},{"sectionNo":"十四","headline":"基层公共就业服务机构、创业孵化基地等可获就业创业服务补助","who":"基层公共就业服务机构（含政府设立的家门口就业服务站、零工市场、人社驿站等）、创业孵化基地、公共就业创业服务机构、高校，以及承接政府购买基本就业创业服务的社会力量。","materials":[],"window":"按工作量、专业性、成效、服务人数和成本等核定，按年度组织实施。","where":"县级以上人力资源社会保障、财政部门；通过政府购买服务方式实施。","tip":"补助按工作量和成效核定；向社会购买的基本就业创业服务包括就业（职业）指导、职业介绍、创业指导、人力资源市场调查等。"},{"sectionNo":"十五","headline":"高技能人才培训基地、技能大师工作室建设可获补助","who":"依托企业、院校、职业培训机构等具备高技能人才培训能力的单位建设的高技能人才培训基地；依托行业企业生产和服务一线优秀高技能人才所在单位建设的技能大师工作室；为省内先进制造业等重点产业企业输送高技能人才的省内职业学校。","materials":[],"window":"按项目制管理；职业学校补助的流程和标准由各市州自行确定，报省人力资源社会保障厅备案后实施。","where":"各地人力资源社会保障部门；省级项目由省人力资源社会保障厅会同省财政厅组织实施。","tip":"职业学校补助按输送高技能人才的数量、质量和服务年限等条件确定，补助流程和标准由各市州自行确定。"},{"sectionNo":"十六","headline":"招用毕业生或16—24岁失业青年，缴社保3个月补1500元/人","who":"企业自行招用毕业年度和离校2年内未就业的高校毕业生及16—24岁登记失业青年，签订劳动合同，并按规定为其足额缴纳3个月以上的失业、工伤、职工养老保险费。","materials":[],"window":"按规定足额缴纳3个月以上社会保险费后方可申报。","where":"当地人力资源社会保障、财政部门（须经省级人民政府批准）。","tip":"与一次性扩岗补助不重复享受；其他支出还须符合国家、省就业政策导向且现有补贴政策无法覆盖。"},{"sectionNo":"十八","headline":"就业补助资金不得用于办公用房、三公经费，在编人员不享受补贴","who":"申领本办法补贴的个人和单位；机关事业单位在编人员不得发放本办法中的补贴。","materials":[],"window":"本办法执行期内长期适用。","where":"各级财政、人力资源社会保障部门（负责资金监管）。","tip":"补贴资金具体用途可由申请人或申请单位自行确定，不受本条禁止性规定限制；办公用房、三公经费、赛事奖金等八类支出不得列支。"},{"sectionNo":"二十五","headline":"申领就业补贴可全程网办，系统能查到的资料不再要求纸质材料","who":"在湖南省申领各项就业补贴的个人和用人单位；能通过湖南省人力资源社会保障一体化业务管理系统或部门信息共享取得的资料，不再要求提供纸质材料。","materials":[],"window":"长期执行；补贴申请、受理、审核、拨付纳入系统管理。","where":"湖南省人力资源社会保障一体化业务管理系统；各级人力资源社会保障、财政部门。","tip":"对补贴金额大、人数多、期限长的对象加强核查抽查；面向个人的补贴具备条件的可通过社会保障卡发放。"},{"sectionNo":"三十一","headline":"虚报冒领套取就业补助资金，责令退回并纳入信用体系联合惩戒","who":"申领就业补助资金的用人单位和个人。","materials":[],"window":"长期执行；发现即责令退回。","where":"各级人力资源社会保障、财政部门；涉嫌犯罪的移送司法机关。","tip":"实施多部门联合惩戒；涉及犯罪的依法移送司法机关。"}],"sourceUrl":"https://czt.hunan.gov.cn/czt/xxgk/zcfg/gfxwj/202502/t20250220_33591654.html","sourceNote":"2026-11-09 核对：原文页只挂 doc 附件，正文取自该附件且逐句比对一致（143/145 句命中，2 句为切条残句）；网页文号 湘财社〔2024〕33号、发文日期 2024-12-27、信息有效时间 2030-01-07","verified":true,"isSample":false,"numberStyle":"clause","bodyVerified":"verbatim","hunan":true},{"id":"p-2025-178898","title":"湖南省人力资源和社会保障厅 湖南省科学技术厅 湖南省财政厅 湖南省市场监督管理局关于印发《关于支持大学生创业孵化基地建设的若干措施》的通知","level":"provincial","region":"湖南省","issuer":"湖南省人力资源和社会保障厅、湖南省科学技术厅、湖南省财政厅、湖南省市场监督管理局","documentNo":"湘人社规〔2025〕31号","publishedAt":"2025-09-28","status":"active","tags":["场地支持","创业补贴","认定资质"],"audience":["小微企业","高校毕业生"],"summary":"2025至2026年每年认定30家省级大学生创业孵化基地，按功能分别给予40万元、50万元、60万元一次性培育奖补，垂直领域试点每家叠加最高20万元。","sections":[{"no":"一","title":"明确总体建设目标","text":"着眼大学生创业生态良好需求,打造一批布局合理、功能完善、运营规范的大学生创业孵化基地。到2027年底,全省创业孵化载体总量稳定在700家左右,其中,能够为大学生提供创业服务的孵化基地300家左右(每年评定一批省级大学生创业孵化基地)。全省年均孵化大学生创业项目5000个左右,孵化成功率不低于60%。"},{"no":"二","title":"坚持分类梯次建设","text":"按照不同服务功能定位,分类建设大学生创业孵化基地。全面建设一批能够为大学生创业提供一定办公场地、生活配套、创业活动、创业培训、事务代理、管理咨询等基础服务的“空间”类孵化基地;布局建设一批能够提供试验平台、检测条件等专业化服务的“平台”类孵化基地;重点建设一批能够提供专利、金融、产业等投融资服务,助力创业实体快速成长的“投资”类孵化基地。"},{"no":"三","title":"建设一批专业化孵化基地","text":"发挥特色产业集群优势,引导科研院所、工程(技术、测试)中心、园区、企业等参与建设大学生创业孵化基地。依托区域特色产业和优势资源,打造具有引领作用的专业性大学生创业孵化基地。围绕重点产业链重点建设10家左右垂直领域大学生创业孵化基地。创业孵化基地内在孵项目登记注册为市场主体且以孵化基地所在地址为注册地址的,市场监管部门根据相关规定准予登记。"},{"no":"四","title":"分级落实奖励补助","text":"2025至2026年每年认定30家省级大学生创业孵化基地。对认定为省级大学生创业孵化基地的,给予一次性培育奖补,根据基地不同功能分别给予40万元、50万元、60万元奖补;对试点开展垂直领域建设的省级大学生创业孵化基地,叠加每家最高不超过20万元的一次性试点奖补。同时,符合我省省级大学生创业孵化基地有关规定的,给予补贴和补助。对符合条件的入孵项目和创业者,优先给予创业培训、创业担保贷款、一次性创业补贴等支持。各市州、县市区可结合实际制定本地支持大学生创业孵化基地和垂直领域孵化基地建设标准及奖励补助标准。"},{"no":"五","title":"推动试验测试设备共享","text":"已列入湖南省科研设施和科研仪器开放共享服务平台的科研设施和仪器,所依托的管理单位应支持大学生创新创业团队或个人用于科学研究和技术开发活动。科研设施和仪器提供开放共享服务,可按照成本补偿和非营利性原则收取费用,开放服务收费标准应采取适当方式向社会公布。针对大学生创业孵化基地的共享办法,另行制定。"},{"no":"六","title":"做好创业资源对接","text":"对由省级大学生创业孵化基地书面推荐的项目,直接进入湖南省大学生创业投资基金尽职调查阶段。相关部门为在孵项目和创业者匹配湖南省大学生创业导师、湖南省创业创新导师团成员,及时为有培训需求的孵化基地推荐创业培训机构、公共实训基地。各地可通过政府购买创业服务成果的方式,支持孵化基地开展创业沙龙、创业讲堂、创业训练营、项目展示交流等创业活动。"},{"no":"七","title":"搭建交流协作平台","text":"加强孵化基地间的沟通协作,建立沟通协作机制,强化信息互通,促进资源共享,常态调研交流,解决困难问题,提供决策咨询,推动成立“湖南省大学生创业孵化基地协会”。"},{"no":"八","title":"完善线上服务功能","text":"依托省政务服务网和湘易办,建好用好“创业在湘”暨湖南省创业公共服务平台(含PC端和移动端),完善大学生专区“七个找”和“三地图”服务内容,展示孵化基地简介、工位、位置等基本信息,定期更新孵化载体地图。优化高效办成个人(大学生)创业一件事流程,将申请入驻创业孵化基地等多个事项集成办、极简办、掌上办。开设政务服务专窗,提供政策和业务咨询,加强与孵化基地、创业服务驿站的沟通联系,提高服务精准度和服务质效。"},{"no":"九","title":"健全评估评价机制","text":"依托“湖南人社一体化业务管理系统”动态管理大学生创业孵化基地,更新基地工作信息和在孵实体信息,定期调度相关情况,跟踪掌握相关数据,展开统计分析。每年开展大学生创业孵化基地认定复评工作,按标准进行分级分类调整;经相关程序,对服务能力不足、孵化效果欠佳、群众满意度不高、存在违法经营等情况的,撤销孵化基地资格。"},{"no":"十","title":"加强工作统筹协调","text":"人力资源社会保障部门牵头大学生创业孵化基地建设,科技、财政、市场监管等相关部门按职责参与共建共管。鼓励有条件有资源的创业孵化基地,吸纳更多大学生创业项目,建设成为大学生创业孵化基地。\n本措施自2025年8月1日起施行,有效期3年。"}],"interpretations":[{"sectionNo":"四","headline":"认定省级孵化基地，按功能分别补40万、50万、60万元","who":"被认定为省级大学生创业孵化基地的运营主体；试点开展垂直领域建设的基地可再叠加最高20万元一次性试点奖补。","materials":[],"window":"2025至2026年每年认定30家省级大学生创业孵化基地。","where":"省人力资源社会保障厅牵头，科技、财政、市场监管等部门按职责参与共建共管。","tip":"符合条件的入孵项目和创业者，还可优先获得创业培训、创业担保贷款、一次性创业补贴等支持；市州、县市区可另定本地奖补标准。"},{"sectionNo":"三","headline":"在孵项目可用基地地址注册，全省重点建10家垂直领域基地","who":"围绕重点产业链建设的垂直领域大学生创业孵化基地；在孵项目登记注册时以孵化基地所在地址为注册地址的，市场监管部门准予登记。","materials":[],"window":"本措施自2025年8月1日起施行，有效期3年。","where":"市场监管部门办理登记；省人社厅牵头基地建设。","tip":"注册地址必须是孵化基地所在地址，否则不适用这条登记便利。"},{"sectionNo":"五","headline":"大学生创业团队可共享省科研设施仪器，按成本补偿付费","who":"大学生创新创业团队或个人；所用科研设施和仪器须已列入湖南省科研设施和科研仪器开放共享服务平台，其依托的管理单位应支持用于科学研究和技术开发活动。","materials":[],"window":"开放服务收费标准向社会公布；针对大学生创业孵化基地的共享办法另行制定。","where":"湖南省科研设施和科研仪器开放共享服务平台及其依托的管理单位。","tip":"收费按成本补偿和非营利性原则，标准须向社会公布；孵化基地共享办法另行制定。"},{"sectionNo":"六","headline":"省级孵化基地书面推荐的项目，直进省大学生创业投资基金尽调","who":"由省级大学生创业孵化基地书面推荐的项目；在孵项目和创业者可获匹配湖南省大学生创业导师、湖南省创业创新导师团成员；有培训需求的孵化基地。","materials":[],"window":"经书面推荐后直接进入尽职调查阶段；按培训需求及时推荐创业培训机构、公共实训基地。","where":"湖南省大学生创业投资基金；湖南省大学生创业导师、湖南省创业创新导师团；创业培训机构、公共实训基地。","tip":"须由省级大学生创业孵化基地书面推荐才可直接进入尽调；各地可通过政府购买创业服务成果支持基地开展创业活动。"},{"sectionNo":"八","headline":"大学生创业可上“创业在湘”平台，“七个找”事项集成办","who":"大学生创业者；需申请入驻创业孵化基地、查询孵化基地简介与工位位置等信息的创业主体。","materials":[],"window":"孵化载体地图定期更新；入驻基地等多个事项集成办、极简办、掌上办。","where":"省政务服务网、湘易办、“创业在湘”暨湖南省创业公共服务平台（含PC端和移动端）、政务服务专窗。","tip":"平台含PC端和移动端，设大学生专区“七个找”和“三地图”；孵化载体地图定期更新。"}],"sourceUrl":"https://rst.hunan.gov.cn/rst/xxgk/zcfg/zxzc/202510/t20251014_33824986.html","sourceNote":"2026-11-09 核对：正文与省人社厅原文页逐句比对一致（30/30 句命中），页面落款 2025-09-28、网页发布 2025-10-14，措施自 2025-08-01 施行、有效期3年；2026-11-09 按原文「自2025年8月1日起施行，有效期3年」推算 2025-08-01 至 2028-07-31","verified":true,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","effectiveAt":"2025-08-01","expiresAt":"2028-07-31","hunan":true},{"id":"p-2025-206f90","title":"邵阳市人力资源和社会保障局 邵阳市财政局关于在全市开展一次性创业补贴申报工作的通知","level":"city","region":"邵阳市","issuer":"邵阳市人力资源和社会保障局、邵阳市财政局","documentNo":"邵人社函〔2025〕56号","publishedAt":"2025-09-17","effectiveAt":null,"expiresAt":null,"status":"active","tags":["创业补贴","就业补贴"],"audience":["小微企业","高校毕业生"],"summary":"邵阳个体门店经营者补5000元，离校2年内高校毕业生注册的个体门店补10000元；小微企业吸纳3名以上劳动者就业补10000元。","sections":[{"no":"一","title":"补贴对象","text":"在邵阳市范围内首次创办小微企业或从事个体门店的离校2年内高校毕业生（含留学回国学生，高等院校和大中专院校，高职院校大专及以上，技工院校高级工班、预备技师及技师班）、就业困难人员、返乡入乡农民工创业者。"},{"no":"二","title":"申报条件","text":"（一）创业项目或经营项目符合国家产业政策发展方向。\n（二）创业者年龄在法定劳动年龄内。\n(三)小微企业或个体门店自工商登记注册之日起正常运营1年以上。\n（四）个体门店经营者，依法参加基本养老保险（包括企业职工基本养老保险、灵活就业人员养老保险或城乡居民养老保险）。初创小微企业须吸纳3名以上（含3名）劳动年龄内的劳动者就业，并依法为其缴纳企业职工养老保险（孵化基地在孵实体项目不作此要求）且申请补贴时员工未离职。\n（五）出现以下情况的不符合申报条件：\n1. 小微企业或个体门店处于停业状态或有明确证据证实将注销、吊销营业执照的；\n2. 企业法人（或个体门店经营者）发生变更的或不是首次创业小微企业或从事个体门店的；\n3. 已享受过一次性创业补贴的企业或个体门店，不再重复享受补贴；\n4. 已享受过创业孵化基地经营场所租金补贴的；\n5. 同一个经营场所登记多家企业或个体门店的，不能重复享受一次创业补贴（孵化基地的在孵实体除外）；\n6. 门店招牌、创业项目经营地址与营业执照的注册名称和注册地址不一致的；\n7. 经核实，有其他不符合补贴政策情形的。"},{"no":"三","title":"补贴标准","text":"（一）对符合条件的个体门店经营者给予5000元的一次性创业补贴，对符合条件的离校2年内高校毕业生注册的个体门店，给予10000元的一次性创业补贴。\n（二）对符合条件的小微企业，吸纳3名以上（含3名）劳动者就业的按10000元的标准给予一次性创业补贴。\n（三）创业孵化基地中的在孵实体优先给予经营场所租金补贴，符合条件的个体门店按照5000元/家（离校2年内高校毕业生的个体门店给予10000元），符合条件的小微企业按照10000元/家给予补贴，由创业孵化基地代为申请代为支付。"},{"no":"四","title":"申报资料","text":"(一)《邵阳市一次性创业补贴申请审批表》（附件1）。\n（二）个体门店经营者或企业法人身份证及营业执照复印件。\n（三）个体门店经营者社保卡号或企业在银行开设的对公账号。\n（四）连续正常经营1年以上的有效证明资料：\n1. 税务部门开具的纳税凭证（按季度提供即可）或经营流水（流水多的企业，可视情况每个季度抽取1天提供即可）等凭证；\n2. 门面租赁合同及租金支付凭证。开办网店的，提供网店网址和平台实名认证信息、支付平台收支明细等。\n（五）创业孵化基地需提供为入孵实体减免租金的凭证。\n（六）人员类别证明资料：\n1. 离校 2 年内高校毕业生: 毕业证书复印件及学历证明(学信网下载打印), 留学回国学生提供教育部留学服务中心颁发的学历认证书复印件。\n2.返乡入乡农民工:本人户口本复印件。\n3. 就业困难人员：由人社部门从省一体化平台进行数据识别，不需要创业者提供相关身份证明材料。"},{"no":"五","title":"办理程序","text":"（一）自主申报。企业、创业孵化基地和个体门店按工商注册所在地属地原则申报受理，符合条件的可在每年10月31日前向注册所在地的县市区人力资源和社会保障部门提交申报材料，逾期不予受理。\n（二）审核审查。每年11月20日前，各县市区人力资源和社会保障部门分批次审核申报资料，确定补贴金额。\n（三）网上公示。县市区人力资源和社会保障部门将分批次审核情况，通过当地媒体或部门网站等向社会公示不少于5个工作日。\n（四）拨付资金。公示期满无异议后，县市区财政部门根据同级人力资源和社会保障部门拨款手续将补贴资金直接拨付到补贴对象提供的社保卡或对公银行账户。"},{"no":"六","title":"工作要求","text":"(一)高度重视。开展一次性创业补贴申报工作，是积极落实就业创业政策、稳就业的具体举措，各地要高度重视，认真抓好宣传发动，将一次性创业补贴工作抓实抓好。\n（二）严格把关。各地要严格把关，按照谁审核、谁把关、谁负责的原则，严格按照规定受理和审核申报资料，严防骗取补贴资金现象发生，确保补贴资金发挥实效。\n（三）严肃纪律。坚持依规申报，依规审核，对违规申报、弄虚作假骗取套取资金的单位和个人，一经查实，除追回补贴资金外，严格按有关规定追究相关人员的责任。\n其他未尽事宜，由市人力资源和社会保障局负责解释，本通知执行时间从发文之日起至2027年12月31日止，此前有关规定与本通知不一致的，以本通知为准，有效期内上级出台新规定与本通知不一致的，以上级新规定为准。"}],"interpretations":[{"sectionNo":"一","headline":"离校2年内高校毕业生等首次创业者可申一次性补贴","who":"在邵阳市范围内首次创办小微企业或从事个体门店的离校2年内高校毕业生（含留学回国学生，高等院校和大中专院校，高职院校大专及以上，技工院校高级工班、预备技师及技师班）、就业困难人员、返乡入乡农民工创业者。","materials":[],"window":"须为首次创业；高校毕业生离校时间限2年内","where":"邵阳市范围内；注册地县市区人社部门（见第五条）","tip":"首次创办是硬条件；已享受过一次性创业补贴的不能再领"},{"sectionNo":"二","headline":"正常运营1年以上，小微企业须吸纳3人并缴养老保险","who":"法定劳动年龄内；项目符合国家产业政策；工商注册后正常运营1年以上；个体门店经营者依法参加基本养老保险，小微企业吸纳3名以上劳动年龄内劳动者并缴企业职工养老保险（孵化基地在孵实体除外）且申请时员工未离职。","materials":[],"window":"自工商登记注册之日起正常运营1年以上","where":"注册地县市区人社部门（见第五条）","tip":"法人变更、非首次创业、已享租金补贴、同一经营场所多店等情形不符合条件"},{"sectionNo":"三","headline":"个体门店补5000元，高校毕业生个体门店补1万元","who":"符合条件的个体门店经营者；离校2年内高校毕业生注册的个体门店；吸纳3名以上劳动者就业的小微企业；创业孵化基地在孵实体。","materials":[],"window":"一次性补贴；按年度申报（见第五条）","where":"注册地县市区人社部门","tip":"高校毕业生个体门店标准1万元；在孵实体由基地代为申请、代为支付；同一主体不重复享受"},{"sectionNo":"四","headline":"申报补贴需审批表、营业执照及经营流水等材料","who":"申报一次性创业补贴的个体门店经营者、小微企业、创业孵化基地","materials":["《邵阳市一次性创业补贴申请审批表》（附件1）","个体门店经营者或企业法人身份证及营业执照复印件","个体门店经营者社保卡号或企业在银行开设的对公账号","连续正常经营1年以上的有效证明资料（纳税凭证或经营流水、门面租赁合同及租金支付凭证；网店提供网址、平台实名认证信息、支付平台收支明细）","创业孵化基地为入孵实体减免租金的凭证","人员类别证明资料（毕业证书复印件及学历证明或学历认证书、户口本复印件；就业困难人员由人社部门数据识别）"],"window":"经营证明须覆盖连续正常经营1年以上；纳税凭证按季度提供","where":"注册地县市区人社部门","tip":"就业困难人员无需提供身份证明，由人社部门从省一体化平台识别"},{"sectionNo":"五","headline":"每年10月31日前申报，逾期不予受理","who":"符合条件的个体门店、小微企业和创业孵化基地（按工商注册所在地属地申报）","materials":[],"window":"每年10月31日前提交；11月20日前审核；公示不少于5个工作日","where":"注册所在地县市区人力资源和社会保障部门","tip":"逾期不予受理；公示期满无异议后拨付到社保卡或对公银行账户"}],"sourceUrl":"https://www.dxzc.gov.cn/jc_dxq/uploadfiles/202604/2026042216495444921.pdf","derivedFrom":"official","sourceNote":"2026-11-09 核对：原文页为 9 页扫描件（无文本层），已用 Windows OCR 逐页识别并与本条正文比对，36/36 句命中；因 OCR 有识别误差，未直接采用 OCR 文本，保留原录入正文 2026-11-24 收录：官方页面未能打开或不是正文（pages/txt），条文未与原文比对。 有效期依据：原文未明示","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"unverifiable","hunan":true},{"id":"p-2025-40c1cf","title":"关于印发《郴州市市级大学生创业孵化基地认定管理办法（试行）》的通知","level":"city","region":"郴州市","issuer":"郴州市人力资源和社会保障局、郴州市教育局、郴州市科学技术局、郴州市财政局","documentNo":"郴人社发〔2025〕13号","publishedAt":"2025-05-21","status":"active","tags":["场地支持","认定资质","创业补贴"],"audience":["小微企业","高校毕业生"],"summary":"市级大学生创业孵化基地要求入孵实体不少于20家、孵化面积1500平方米（含）以上，每吸纳1家实体入孵按每月140元补助基地，每个基地每年补助最高不超过40万元。","sections":[{"no":"一","title":"第一条","text":"为全面贯彻落实党的二十届三中全会精神，按照省委、省政府关于支持大学生创业“七个一”的工作要求，建设一批有特色、功能强的省级大学生创业孵化载体，进一步推进大学生创新创业。根据《湖南省人民政府办公厅关于印发〈湖南省大力支持大学生创业若干政策措施〉的通知》（湘政办发〔2024〕42号）、《湖南省人力资源和社会保障厅 湖南省财政厅关于深入推进创业孵化基地建设工作的通知》（湘人社规〔2023〕5号）、《湖南省人力资源和社会保障厅 湖南省教育厅 湖南省科学技术厅 湖南省财政厅关于印发〈湖南省省级大学生创业孵化基地认定管理办法（试行）〉的通知》（湘人社规〔2024〕28号）精神，制定本办法。"},{"no":"二","title":"第二条","text":"郴州市市级大学生创业孵化基地建设坚持政府引导、社会参与、市场运营、择优认定的原则，以在校大学生、高校应届毕业生等群体为主要孵化对象，以培育创业实体、促进创业带动就业为目标，具有滚动孵化功能，发挥示范引领和辐射带动作用。"},{"no":"三","title":"申报市级大学生创业孵化基地须达到以下标准：","text":"申报市级大学生创业孵化基地须达到以下标准：\n（一）以创业孵化为主营业务的各类创业孵化载体，无违法违规记录。\n（二）在孵实体数量。在孵实体数量不少于20家，其中入孵的在校大学生和毕业5年内（含）高校毕业生创业实体数量不少于1/3。或者扶持创业及带动就业的人员不少于40人，其中在校大学生和毕业5年内（含）高校毕业生人数不少于总人数的1/4。入孵创业实体孵化周期不超过5年。\n（三）孵化场地规模。孵化面积1500平方米（含）以上，拥有必要创业孵化场所和基础设施。应设立苗圃工位或独立办公房两种办公场所。其中，免费提供给大学生和毕业5年内（含）高校毕业生创业项目的场地不低于孵化面积的30%。\n（四）创业孵化服务。配备不少于3名工作人员负责基地运营管理，为入孵实体申请各项创业扶持政策，提供创业指导、创业培训、商务代办、投融资等服务。配备不少于4名创业导师，为创业者提供各类创业指导。\n（五）服务和管理。各项管理制度健全，已制定孵化服务目录清单，有明确的入驻和退出机制。"},{"no":"四","title":"第四条","text":"市级大学生创业孵化基地坚持公平公正、自愿申报、择优推荐的原则，参照市级创业孵化基地管理要求，每年认定或复评一次。"},{"no":"五","title":"申报认定程序：","text":"申报认定程序：\n（一）自主申报。各县市区人社部门牵头对照基本条件，联合相关部门对创业孵化基地进行考评，择优向市人社部门推荐，并提交以下材料：\n1.郴州市市级大学生创业孵化基地申报表；（附件1）\n2.在孵创业实体名册；（附件2）\n3.推荐函。\n（二）填报信息。按照全省创业孵化基地信息化管理的要求，指导创业孵化基地在“湖南人社一体化业务管理系统”中录入相关信息，保证数据真实准确完整。\n（三）组织核查。市人社部门组织专家对申报的孵化基地资料进行审核，并组织相关部门实地走访。\n（四）公示认定。对拟认定的市级大学生创业孵化基地，在市人社部门官方网站进行公示。对公示无异议的，由市级人社、教育、科技三部门联合发文认定为郴州市市级大学生创业孵化基地，并颁发牌匾，择优推荐省级大学生创业孵化基地认定。"},{"no":"六","title":"政策支持：","text":"政策支持：\n（一）补贴标准\n1.对于认定的郴州市市级大学生创业孵化基地，给予一定培育奖补，补助标准另行制定。所需资金从中省下达的市级就业专项资金中列支。\n2.对已认定的郴州市市级大学生创业孵化基地，参照湘人社规〔2023〕5号文件，根据每年创业孵化成效给予创业服务补助。所需资金从所在地就业专项资金中列支。具体标准如下：\n（1）市级大学生创业孵化基地每吸纳1家创业实体入孵，按每家每月140元的标准给予基地补助；\n（2）创业实体在孵期间成功注册市场主体的（在孵创业实体入孵前未注册市场主体），按2800元每家给予基地一次性补助；同一创业孵化基地中的同一在孵创业实体注册多个市场主体的，只能计算1家，不重复补贴。\n（3）创业孵化基地内扶持大学生或毕业5年内（含）高校毕业生创业或就业的，超过40人的按4.2万元每年的标准给予基地补助，超过80人的按8.4万元每年的标准给予基地补助，超过120人的按12.6万元每年的标准给予补助。\n每个基地每年享受创业服务补助总额最高不超过40万元，按照就业专项资金使用的有关规定，主要用于开展创业孵化基地服务项目清单中的有关服务，以及孵化基地服务能力建设和提升。按照湘人社规〔2023〕5号文件已认定的创业孵化基地，享受的创业服务补助就高不就低，不重复享受。\n（二）各级人社部门可通过政府购买创业服务成果的方式，支持市级大学生创业孵化基地开展创业沙龙、创业讲堂、创业训练营、项目展示交流等创业活动，为创业者搭建资源对接的平台。指导设立“创业指导师工作室”，推动在孵项目和大学生创业导师建立“一对一”帮扶关系。为在孵实体提供创业筹备、创业运营、创业发展等方面的指引。每年在同一创业孵化基地内指导帮扶孵化成功实体注册5个以上的给予“创业指导师工作室”1万元创业带动就业补助。所需资金从所在地就业专项资金中列支。\n（三）推动政府扶持政策向孵化基地集中。各级人社、教育、科技、财政部门要加强政策的宣传和解读，主动为大学生创业孵化基地内的在孵项目落实相关政策和服务，在补贴、项目、课题、资金申报上加大支持力度。允许孵化基地按照各部门要求，组织在孵企业统一收集、统一申报，缩短审批时间。"},{"no":"七","title":"第七条","text":"依托“湖南人社一体化业务管理系统”对市级大学生创业孵化基地实行动态管理。市人社部门负责市级基地的工作指导、组织协调、认定核查等；县市区人社部门负责本地市级基地的推荐申报、服务指导、日常管理等。推荐认定环节做到公开透明、公平公正，坚决杜绝优亲厚友、虚报冒领等行为。对存在徇私舞弊、套取骗取、贪污挪用等违法违纪行为的，依照法律法规和有关规定严肃追究责任。"},{"no":"八","title":"第八条","text":"市级大学生创业孵化基地出现下列情形之一的，撤销资格并收回牌匾：\n（一）建设单位和运营单位已注销、吊销营业执照的。\n（二）未按要求申请复评或复评未通过的。\n（三）对孵化效果欠佳、服务能力不足、工作配合度和群众满意度不高，或相关部门提出处理意见后未能及时整改的。\n（四）违法经营和造成重大安全、重大质量事故的。\n（五）其他应当撤销市级基地资格的。"},{"no":"九","title":"第九条","text":"各相关部门要加强项目绩效管理，完善绩效指标体系，确保项目资金使用效益。加强绩效管理结果运用，作为政策优化调整的重要依据。"},{"no":"十","title":"第十条","text":"各县市区人社部门可根据本地实际，参照本办法自行制定县级大学生创业孵化基地认定管理办法。"},{"no":"十一","title":"本办法自2025年5月21日起执行，有效期两年","text":"本办法自2025年5月21日起执行，有效期两年。\n附件：1.郴州市市级大学生创业孵化基地申报表\n2.在孵创业实体名册"}],"interpretations":[{"sectionNo":"三","headline":"在孵实体20家以上、孵化面积1500平方米以上才能申报","who":"以创业孵化为主营业务的各类创业孵化载体，无违法违规记录；在孵实体不少于20家，其中在校大学生和毕业5年内高校毕业生创业实体不少于1/3；孵化面积1500平方米（含）以上；配3名以上运营人员和4名以上创业导师。","materials":["郴州市市级大学生创业孵化基地申报表","在孵创业实体名册","推荐函"],"window":"每年认定或复评一次，由县市区人社部门牵头推荐。","where":"县市区人社部门牵头考评推荐，市人社部门组织专家审核、实地走访并公示认定。","tip":"免费提供给大学生和毕业5年内高校毕业生的场地不低于孵化面积的30%；入孵实体孵化周期不超过5年。"},{"sectionNo":"六","headline":"每吸纳1家实体每月补140元，基地每年最高补40万元","who":"已认定的郴州市市级大学生创业孵化基地的运营方（不是入孵企业本身）；同一在孵实体注册多个市场主体的只算1家。","materials":["在孵创业实体名册","湖南人社一体化业务管理系统录入信息"],"window":"按年度核算，每个基地每年享受创业服务补助总额最高不超过40万元。","where":"市、县市区人社部门；资金从所在地就业专项资金中列支。","tip":"已按湘人社规〔2023〕5号认定的基地，创业服务补助就高不就低、不重复享受；另设「创业指导师工作室」年度帮扶孵化成功5家以上可补1万元。"},{"sectionNo":"五","headline":"市级基地认定：县市区推荐，交申报表、在孵名册、推荐函","who":"各县市区人社部门牵头对照基本条件、联合相关部门考评后择优向市人社部门推荐的创业孵化基地；基地须在湖南人社一体化业务管理系统录入信息，数据真实准确完整。","materials":["郴州市市级大学生创业孵化基地申报表（附件1）","在孵创业实体名册（附件2）","推荐函"],"window":"按年度组织申报认定；市人社部门组织专家审核并实地走访，公示无异议后联合发文认定、颁发牌匾。","where":"各县市区人社部门；市人社部门；湖南人社一体化业务管理系统；市人社部门官方网站。","tip":"公示无异议才认定；由市级人社、教育、科技三部门联合发文并颁牌，择优推荐省级基地认定。"},{"sectionNo":"八","headline":"注销、复评未通过、重大事故等情形，撤销市级基地资格","who":"已认定的市级大学生创业孵化基地及其建设、运营单位；出现注销或吊销营业执照、未按要求复评或复评未通过、孵化效果欠佳整改不到位、违法经营或重大安全质量事故等情形。","materials":[],"window":"复评及日常监管中发现所列情形即撤销资格并收回牌匾。","where":"原文未列具体部门，由认定管理部门撤销资格、收回牌匾。","tip":"未按要求申请复评或复评未通过的，同样撤销资格；相关部门提出处理意见后未及时整改的也在撤销范围。"}],"sourceUrl":"https://czrsj.czs.gov.cn/18281/18295/content_3905671.html","sourceNote":"2026-11-09 核对：正文与郴州市人社局原文页逐句比对一致（60/60 句命中），页面落款 2025-05-21、文号 郴人社发〔2025〕13号，有效期两年","verified":true,"isSample":false,"numberStyle":"clause","bodyVerified":"verbatim","hunan":true},{"id":"p-2025-42786b","title":"关于印发《张家界市进一步降本减负优化营商环境九条措施》的通知","level":"city","region":"张家界市","issuer":"张家界市人民政府办公室","documentNo":"张政办发〔2025〕13号","publishedAt":"2025-07-17","status":"active","tags":["融资支持","场地支持","社保补贴"],"audience":["小微企业","高校毕业生"],"summary":"张家界降低融资、用能、用工、物流、中介、审批、用地、税费、制度性交易九方面成本，优化营商环境。","sections":[{"no":"一","title":"降低融资成本","text":"降低融资成本。严格落实支持小微企业融资协调工作机制，抓实“千企万户大走访”，保持小微企业信贷有效供给。加大首贷、信用贷、中长期贷款投放力度，推动法人银行普惠型小微企业贷款和民营企业贷款增速均高于各项贷款增速。持续优化小微企业续贷机制，覆盖2027年9月30日前到期的中型企业流动资金贷款。建立续贷沟通机制，贷款到期前1个月主动对接，实现“应续尽续”。根据LPR定价机制，及时主动调整涉企贷款利率。全面落实企业融资收费“两禁两限”规定，除银团贷款外不得对小微企业贷款收取承诺费、资金管理费，严格限制对小微企业及其增信机构收取财务顾问费、咨询费。积极推进农村“三信”创建，发挥信用信息支持产业融资的作用。充分发挥张家界“金融超市”平台、企业收支流水征信平台作用，加大信贷投放力度，力争小微企业信用贷款占比达20%以上。用好我市农业产业贷款风险补偿基金、产业发展基金，不断健全“政银保担投”全链条金融服务体系。（市政府办公室、中国人民银行张家界市分行、国家金融监管总局张家界监管分局、市发展改革委、市工业和信息化局、市农业农村局、市融资担保集团公司等按职责分工负责，各区县人民政府负责落实本区县工作；以下均需各区县人民政府负责落实本区县工作，不再列出）"},{"no":"二","title":"降低用能成本","text":"降低用能成本。积极对接和落实天然气管网“一张网、一个价”改革。加大对土木溪水厂和花岩水厂设施建设和改良力度。实行用电重点项目“项目长”负责制，对重点企业和电价水平长期较高的用户，开展“一企一策”指导，支持企业用活分时电价政策，常态开展工业园区客户走访行动。鼓励企业配置新型储能设施，提倡“低充高用”，鼓励园区企业加强余热利用。（市住房城乡建设局、国网张家界供电公司、市发展改革委、市自来水公司等按职责分工负责）"},{"no":"三","title":"加大用工保障和补贴降费力度","text":"加大用工保障和补贴降费力度。用好“用工超市”和“张家界就业”平台，加强就业岗位信息归集共享，2025年发布岗位30万个以上。利用5G技术将招聘信息动态推送至村组干部，加强线上直播带岗。精准发放一次性扩岗补助、吸纳就业困难人员、离校2年内未就业高校毕业生社会保险补贴、就业见习补贴。开展补贴性职业培训6500人次，落实补贴资金900万元。推广“订单式”培训，在湖南旅游技师学院开设企业定向技能培养班。继续落实社保降费政策，延续实施阶段性降低失业保险费率至1%政策。实现失业保险稳岗返还政策“免申即享”。进一步做好企业用工服务保障工作。（市人力资源社会保障局、市财政局等按职责分工负责）"},{"no":"四","title":"降低物流成本","text":"降低物流成本。调整优化运输结构，持续推进“公转铁”。推进铁路物流园建设，2025年完成项目招商引资和立项审批，2026年开工建设。引进1—2家多式联运现代物流企业入驻我市。加快货运设备更新升级，推广使用新能源货运车辆。严格执行鲜活农产品运输“绿色通道”政策，落实道路运输和水路运输燃油补贴申报与发放。推行农村客货邮融合发展模式，持续完善县乡村三级物流体系，加强分拨中心、配送中心和末端网点建设。（市交通运输局、市发展改革委、市商务局、张家界高新区管委会、市自然资源和规划局、市邮政管理局等按职责分工负责）"},{"no":"五","title":"降低中介服务成本","text":"降低中介服务成本。按照“政府引导、行业自律、市场调节”原则，深入推动中介服务改革，大力开展行政审批中介服务事项清理，梳理公布各类评估评价、检验检测等涉审中介服务事项清单，审批部门不得要求经营主体提供清单之外的中介服务报告。用好“中介超市”，实现机构选择、费用支付、报告上传、服务评价等全流程网上办理。引导成立中介服务行业协会或社会组织并加强行业自律，规范中介服务收费，严厉查处中介服务机构出具虚假证明或报告、谋取不正当利益、“官荐中介”等违规行为。（市委深改办、市发展改革委、市数据局、市政务服务中心、市市场监管局等按职责分工负责）"},{"no":"六","title":"降低行政审批成本","text":"降低行政审批成本。市、区县政务服务部门建立网办帮办领办机制，大力推行“全程网办”，根据企业和群众需求免费提供帮办领办服务，构建“除了网上办就是帮办领办”的政务服务新格局。强化行政效能分析以及在线监察，对“红黄牌”和“差评”加强处置，推动审批人员按期办、提速办、优质办。进一步推动工改系统改革，规划和自然资源、住房城乡建设部门审批时间再压缩20%以上。（市数据局、市政务服务中心等按职责分工负责）"},{"no":"七","title":"降低工业用地成本","text":"降低工业用地成本。用好“土地超市”，实现“一站式”选地购地，缩减企业拿地时间。探索建立城乡统一基准地价体系，支持产业用地“标准地”出让，采用工业用地长期租赁、先租后让、租赁与出让结合、弹性年期出让等供应方式，产业园区全面推进“用地清单制+告知承诺制”和“五即”（洽谈即服务、签约即供地、开工即配套、竣工即办证、达产即复核）供地模式。继续推进“验登合一”“多测合一”，针对小微企业免收不动产登记费。（市自然资源和规划局、市工业和信息化局、张家界高新区管委会等按职责分工负责）"},{"no":"八","title":"降低税费成本","text":"降低税费成本。精准推送结构性减税降费政策，实现“政策找人”“一企一策”个性化服务，推进惠企税务政策“直达快享”。提供数字化发票开具、交付、使用服务，降低企业票据管理成本和交易成本。优化纳税信用评价，提升“银税互动”质效，将企业纳税信用转化为融资信用，提升企业融资便利度。定期召开税企“面对面”座谈交流会，高效解决企业涉税问题。加强涉企收费长效监管，动态更新涉企收费目录，加大违规收费治理力度。（市税务局、市财政局、市发展改革委、市市场监管局等按职责分工负责）"},{"no":"九","title":"降低制度性交易成本","text":"降低制度性交易成本。积极主动融入全国统一大市场建设，修订《张家界市政府性投资工程招投标实施操作办法》，完善政府采购配套措施，推广“机器管招投标”，建立排除人工干预的公共资源交易模式，提高评标效率，约束专家自由裁量权。（市发展改革委、市财政局、市公共资源交易中心等按职责分工负责）"}],"interpretations":[{"sectionNo":"一","headline":"小微企业续贷「应续尽续」，不收承诺费和资金管理费","who":"在张家界经营的小微企业；普惠型小微企业贷款和民营企业贷款增速要求高于各项贷款增速。","materials":[],"window":"续贷机制覆盖 2027 年 9 月 30 日前到期的中型企业流动资金贷款，贷款到期前 1 个月银行主动对接。","where":"各经办银行、张家界「金融超市」平台；人民银行张家界市分行等按职责分工负责。","tip":"除银团贷款外，银行不得对小微企业贷款收取承诺费、资金管理费；财务顾问费、咨询费也严格限制。"},{"sectionNo":"三","headline":"社保补贴、扩岗补助、见习补贴照发，失业保险费率仍按1%","who":"招用就业困难人员、离校2年内未就业高校毕业生等的企业；以及符合条件的失业参保单位。","materials":[],"window":"2025 年计划发布岗位 30 万个以上、补贴性职业培训 6500 人次；阶段性降低失业保险费率至 1% 政策延续实施。","where":"市人力资源社会保障局、市财政局；稳岗返还「免申即享」。","tip":"稳岗返还是「免申即享」，不用企业自己跑申请；补贴资金规模为 900 万元。"},{"sectionNo":"二","headline":"重点用电企业可享“一企一策”分时电价指导","who":"工业园区内企业；用电重点项目、重点企业和电价水平长期较高的用户；配置新型储能设施、开展余热利用的企业。","materials":[],"window":"常态化开展，原文未设申报截止时间","where":"国网张家界供电公司、市发展改革委、市住房城乡建设局（按职责分工）","tip":"天然气推进“一张网、一个价”；分时电价、储能配置需企业主动对接“项目长”和供电公司，原文未列申报材料和办理时限。"},{"sectionNo":"四","headline":"鲜活农产品走“绿色通道”，道路水路燃油补贴可申报","who":"从事道路运输、水路运输的经营者；鲜活农产品运输主体；多式联运、货运物流企业；农村客货邮融合相关经营主体。","materials":[],"window":"铁路物流园2025年完成招商引资和立项审批、2026年开工建设；燃油补贴按申报发放执行。","where":"市交通运输局、市发展改革委、市商务局、市邮政管理局（按职责分工）","tip":"“绿色通道”政策为严格执行，燃油补贴需按规定申报；原文未列申报材料和截止时间。"},{"sectionNo":"五","headline":"审批不得要清单外中介报告，“中介超市”全流程网上办","who":"办理行政审批、需要评估评价或检验检测等涉审中介服务的经营主体；入驻“中介超市”的中介服务机构。","materials":[],"window":"常态化推行，原文未设申报截止时间","where":"“中介超市”（线上）；市委深改办、市发展改革委、市数据局、市政务服务中心、市市场监管局按职责分工","tip":"清单之外的中介服务报告审批部门不得要求提供；中介机构出具虚假证明、“官荐中介”等将被查处。"},{"sectionNo":"六","headline":"办事可“全程网办”，免费帮办领办，审批时间再压20%以上","who":"在张家界市、区县办理政务事项的企业和群众；工程建设项目报建单位（工改系统审批）。","materials":[],"window":"常态化推行，原文未设申报截止时间","where":"市、区县政务服务部门；市数据局、市政务服务中心（按职责分工）；工改系统","tip":"审批时间再压缩20%以上针对规划和自然资源、住房城乡建设部门审批；遇“红黄牌”“差评”将被处置。"},{"sectionNo":"七","headline":"小微企业免收不动产登记费，工业用地可先租后让、弹性年期","who":"小微企业（免收不动产登记费）；需工业用地的产业项目、产业园区入驻企业。","materials":[],"window":"常态化推行，原文未设申报截止时间","where":"“土地超市”（线上）；市自然资源和规划局、市工业和信息化局、张家界高新区管委会按职责分工","tip":"产业园区推行“用地清单制+告知承诺制”和“五即”供地；免收不动产登记费仅限小微企业。"},{"sectionNo":"八","headline":"纳税信用可转融资信用，享减税降费“政策找人”","who":"在张家界市纳税的企业；有融资需求的纳税信用企业。","materials":[],"window":"常态化推进，原文未设申报截止时间","where":"市税务局、市财政局、市发展改革委、市市场监管局（按职责分工）","tip":"涉企收费目录动态更新，违规收费将被治理；纳税信用评价影响“银税互动”融资。"}],"sourceUrl":"http://www.zjj.gov.cn/c693/20250731/i1095938.html","sourceNote":"条文已于 2026-11-09 与官方页面/PDF 逐句比对，逐字一致（明细见 采集包/条文核对表.md）","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"p-2025-5136c2","title":"湖南省财政厅等四部门关于实施大学生创业贷款财政补助政策的通知","level":"provincial","region":"湖南省","issuer":"湖南省财政厅、中共湖南省委金融委员会办公室、湖南金融监管局、中国人民银行湖南省分行","documentNo":"湘财金〔2025〕43号","publishedAt":"2025-10-21","status":"active","tags":["贷款贴息","融资支持"],"audience":["小微企业","个体工商户","高校毕业生"],"summary":"对在湘个人创业或合伙创业的大学生，个人创业贷款额度不超过50万元、小微企业及其他市场主体创业贷款额度不超过500万元，省财政按贷款实际利率的50%给予贴息、按担保金额的1.5%给予担保机构担保费补贴，本通知自印发之日起实施，有效期至2027年12月31日。","sections":[{"no":"一","title":"政策内容","text":"（一）支持对象与适用条件\n\n1.支持对象：在湘个人创业或合伙创业的大学生。\n\n2.适用条件：同时符合以下条件的创业贷款，可享受省财政补助。\n\n贷款发放时间：本通知印发之日起至2027年12月31日期间新发放。政策到期后如需延期，另行通知。\n\n贷款方式：通过信用贷款方式或由省内纳入再担保体系的政府性融资担保机构（以下简称担保机构）提供免费担保。\n\n贷款额度与利率：个人创业贷款额度不超过50万元，小微企业及其他市场主体创业贷款额度不超过500万元；贷款利率不超过同期贷款市场报价利率（LPR）加100个基点（Bps）。\n\n资金用途：专项用于大学生在湘创办市场主体（企业、个体工商户等）的日常经营、技术研发、设备采购等生产经营活动。\n\n主体资格：“大学生”指国内外在校学生或毕业5年（含）内的大专、本科、硕士、博士毕业生，以及技师学院在校或毕业5年（含）以内的毕业生。残疾人大学生可放宽至毕业8年（含）内的毕业生。\n\n（二）财政补助标准\n\n1.贴息：对经办银行发放的符合条件贷款，省财政按贷款实际利率的50%给予贴息，贴息期限最长不超过3年。逾期或展期的贷款，自逾期或展期之日起不再享受贴息。\n\n2.担保费补贴：省财政按担保金额的1.5%给予担保机构担保费补贴。担保费补贴按实际承保期限计算，按年度补贴。\n\n3.风险补偿：对担保机构与经办银行合作开展的大学生创业担保贷款业务，代偿率在5%（含）以内的部分，由省财政、担保机构、经办银行按40%、40%、20%的比例分担风险。"},{"no":"二","title":"经办银行与贷款流程","text":"（一）经办银行范围\n\n省财政补助政策适用于以下开发并运营大学生创业专属贷款产品的银行：中国工商银行等18家全国性银行在湘分支机构、湖南银行、长沙银行及省内各农村商业银行。\n\n（二）经办担保机构范围\n\n省财政补助政策适用于省内纳入再担保体系的政府性融资担保机构。\n\n（三）贷款申请\n\n符合条件的大学生，可向所在地经办银行提出贷款申请，并提供以下材料：\n\n身份证明：在校生提供学校盖章的在校证明；毕业生提供学信网信息查询截图及学历证书（或国外学历学位认证书）复印件。经办银行须核实其真实性。\n\n主体证明：借款人是个体工商户的，提供营业执照；借款人是小微企业或小微企业主的，需提供大学生合计持股比例不低于10%的股东身份证明、担任关键核心岗位（董事长、执行董事、总经理、副总经理、技术总监、营销总监、财务总监、生产总监等）证明及营业执照。\n\n（四）贷款审核与发放\n\n经办银行遵循市场化原则，独立审核、审批贷款申请，自主决定贷款发放与否及具体条件，对符合条件的申请应及时放款。需担保的贷款，经办银行可与担保机构合作，鼓励采用“见贷即保”或联合尽调模式，简化流程。鼓励经办银行、担保机构与大学生创业投资基金建立“投贷担”联动机制，对大学生创业投资基金投资的项目，降低贷款门槛和利率，建立绿色审批通道，优先发放贷款。"},{"no":"三","title":"财政补助资金流程","text":"（一）资金预拨\n\n省财政厅按年度向经办银行省级机构（全国性银行省级分行、城市商业银行总行、省农村信用社联合社）预拨贴息资金，向担保机构预拨担保费补贴和风险补偿资金。\n\n（二）资金结算\n\n1.贴息资金。经办银行收到预拨贴息资金后，在收取利息时直接扣减贴息部分。经办银行省级机构按季度向省委金融办数据平台报送贷款发放及贴息情况。每年1月20日前，经办银行省级机构向省委金融办提交上年度贴息资金结算申请及证明材料（贷款合同、借款人身份及主体证明、资金用途证明等）。省委金融办于3月10日前完成审核，将审核结果报省财政厅。省财政厅依据审核结果与经办银行完成年度结算。\n\n2.担保费补贴与风险补偿资金。担保机构发生的担保贷款业务须在省再担保系统备案。每年2月10日前，省再担保公司完成各担保机构上年度担保费补贴、风险补偿资金的结算审核，并将结果报省委金融办。省委金融办复核，并于3月10日前将复核结果报省财政厅。省财政厅依据复核结果与担保机构完成年度结算。"},{"no":"四","title":"监督管理","text":"（一）专款专用\n\n贷款主体须确保贷款资金专项用于生产经营活动，严禁虚报、冒领、套取、截留、挤占、挪用；严禁用于偿还其他债务、投资理财等套利活动及个人消费等非生产经营领域。\n\n（二）强化监管\n\n湖南金融监管局落实小微企业贷款差异化监管政策，督促经办银行严格审核资金用途，跟踪贷款使用，确保合规有效。人民银行湖南省分行引导银行机构用好用足各项结构性货币政策工具，充分发挥央行低成本资金的牵引撬动作用，加大首贷、信用贷款投放，创新特色金融产品，支持大学生创新创业。省再担保公司、省委金融办严格审核财政补贴资金申请，确保财政资金安全。\n\n（三）严格责任追究\n\n相关部门应加强全过程跟踪管理。发现违规使用贷款或财政补助资金的，须及时追回并依法依规追究贷款主体、经办银行及相关人员责任。贷款主体及经办银行须自觉接受财会监督、审计监督和行业监管。工作人员存在违规违纪行为的，依法追究责任，涉嫌犯罪的，移送司法机关处理。"},{"no":"五","title":"其他事项","text":"1、同一笔贷款如已获得省级财政补助资金的，不得重复享受本政策补助。\n\n2、执行中如遇问题，请及时向省财政厅、省委金融办报告。\n\n3、请各有关单位高度重视，认真贯彻执行。\n\n本通知自印发之日起实施，有效期至2027年12月31日。"}],"interpretations":[{"sectionNo":"一","headline":"大学生创业贷款：个人最高50万元、企业最高500万元，省财政贴息50%","who":"在湘个人创业或合伙创业的大学生（含国内外在校学生、毕业5年内的大专/本科/硕士/博士，技师学院在校或毕业5年内；残疾人大学生放宽至毕业8年内）。贷款须为本通知印发之日至 2027年12月31日 期间新发放，通过信用贷款或政府性融资担保机构免费担保方式。","materials":[],"window":"贷款发放时间在 2027年12月31日 前；贴息期限最长不超过3年。","where":"18家全国性银行在湘分支机构、湖南银行、长沙银行及省内农村商业银行等经办银行。","tip":"贷款利率不得高于同期 LPR+100个基点；逾期或展期的贷款，自逾期或展期之日起不再享受贴息。"},{"sectionNo":"二","headline":"申请要带在校证明或学信网材料，个体户带营业执照","who":"符合条件的大学生借款人；借款人为小微企业或小微企业主的，大学生合计持股比例不低于10%，且担任董事长、总经理、技术总监等关键核心岗位。","materials":["在校生：学校盖章的在校证明","毕业生：学信网信息查询截图及学历证书（或国外学历学位认证书）复印件","个体工商户：营业执照","小微企业/小微企业主：大学生持股证明、关键岗位证明、营业执照"],"window":"向经办银行提出申请，银行按规定独立审核、及时放款。","where":"所在地经办银行；需担保的可与政府性融资担保机构合作，鼓励「见贷即保」。","tip":"银行会核实学历与身份材料真实性；被大学生创业投资基金投过的项目，可走绿色审批通道、降低门槛和利率。"},{"sectionNo":"一","headline":"担保费补1.5%，代偿率5%以内财政、担保、银行按4:4:2分担","who":"纳入再担保体系的政府性融资担保机构，及其与经办银行合作开展的大学生创业担保贷款业务。","materials":[],"window":"担保费补贴按实际承保期限计算，按年度补贴。","where":"省财政厅等部门按年度结算。","tip":"风险分担只覆盖代偿率 5%（含）以内的部分，超出部分按协议另行处理。"},{"sectionNo":"三","headline":"贴息资金由省财政厅预拨，经办银行收息时直接扣减","who":"经办银行省级机构（全国性银行省级分行、城市商业银行总行、省农村信用社联合社）；担保机构；省再担保公司。","materials":["贷款合同","借款人身份及主体证明","资金用途证明"],"window":"每年1月20日前提交上年度贴息资金结算申请，3月10日前完成审核；担保费补贴与风险补偿每年2月10日前完成结算审核。","where":"省财政厅；省委金融办；省委金融办数据平台；省再担保系统","tip":"经办银行须按季度向省委金融办数据平台报送贷款发放及贴息情况；担保贷款业务须在省再担保系统备案。"},{"sectionNo":"四","headline":"贷款资金须专项用于生产经营，违规将被追回并追责","who":"大学生创业贷款主体（借款企业或个人）；经办银行；担保机构。","materials":[],"window":"贷款存续及资金使用全过程监管","where":"湖南金融监管局、人民银行湖南省分行、省委金融办、省再担保公司","tip":"严禁用于偿还其他债务、投资理财等套利活动及个人消费；违规使用贷款或财政补助资金须及时追回并依法依规追究责任。"},{"sectionNo":"五","headline":"同一笔贷款已获省级财政补助的不得重复享受，至2027年12月31日","who":"申请大学生创业贷款财政补助的贷款主体。","materials":[],"window":"自印发之日起实施，有效期至2027年12月31日","where":"省财政厅、省委金融办","tip":"同一笔贷款已获得省级财政补助资金的不得重复享受本政策补助；执行中遇问题向省财政厅、省委金融办报告。"}],"sourceUrl":"https://jyt.hunan.gov.cn/jyt/sjyt/bys/byszcjd/202603/t20260306_33928168.html","sourceNote":"条文已于 2026-11-09 与官方页面/PDF 逐句比对，逐字一致（明细见 采集包/条文核对表.md）；2026-11-08 核对：页面发布时间 2025-11-05","verified":true,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"p-2025-71aa02","title":"湘西自治州人民政府办公室关于印发《湘西州支持培育发展“四上”企业的若干措施》的通知","level":"city","region":"湘西土家族苗族自治州","issuer":"湘西土家族苗族自治州人民政府办公室","documentNo":"州政办发〔2025〕7号","publishedAt":"2025-05-12","status":"active","tags":["专项资金","认定资质"],"audience":["小微企业"],"summary":"湘西州新入规工业企业每户奖励10万元；新入库建筑业、房地产企业各奖励10万元；新入规限上批零住餐企业奖励6万元；新入规服务业企业奖励4万元。","sections":[{"no":"一","title":"完善转企升规奖励机制","text":"完善转企升规奖励机制。支持各类企业入规纳统：对新入规工业企业每户奖励10万元；对新入库有资质的建筑业企业每户奖励10万元；对新入库房地产开发经营业企业且本年度主营业务收入1000万元以上的，每户奖励10万元；对新入规的限额以上批发零售和住宿餐饮业企业每户奖励6万元；对新入规的服务业企业每户奖励4万元（其中申报省级奖励2万元，州级配套奖励2万元）。奖励分两次发放，入规（转企）后次年3月前奖励50%；若企业持续在库正常报数，第三年3月前再奖励剩余50%。已入规（转企）企业退规（注销）后再进或变更名称、地点、经营范围等进规达限转企的经营主体不再享受奖励。"},{"no":"二","title":"完善企业扩规提质奖励机制","text":"完善企业扩规提质奖励机制。对已在库的规上工业、建筑业、房地产开发经营、批发零售和住宿餐饮业、服务业企业，每年实现正增长且当年增速同比增长20%、40%、60%、80%、100%的，分别奖励1万元、2万元、3万元、4万元、5万元；对新入规的“四上”企业，在入规后第二年（含入规当年）达到条件即可享受该项政策，奖励资金于次年3月前一次性发放。该项政策考核指标中，工业、建筑业为产值，房地产业为商品房销售面积，其余行业为营业收入。"},{"no":"三","title":"完善规范管理奖励机制","text":"完善规范管理奖励机制。鼓励商业综合体、专业市场（包括二手车、建材、家居家装、农贸市场等）、特色商业街区、产业集聚区、民宿及旅拍等行业市场主体实施联营模式，联合组建统一收银、统一核算、统一报税、统一管理的法人企业，不断规范市场主体经营、管理和发展。对新纳入统计的规上服务业和限上批零住餐业企业，其年度营业收入分别达到入规标准10倍、20倍，且自入统年度次年起主营业务收入同比增长15%的，给予管理公司奖励20万元、50万元。奖励分两次发放，对达到条件的企业于次年3月发放50%；若企业持续在库，自首次发放之日起满12个月后（即第三年3月）兑付剩余50%。集中管理结算的企业中不得包含之前已退规退库的企业。"},{"no":"四","title":"完善助企服务机制","text":"完善助企服务机制。建立健全领导联系企业和“一对一”专班服务企业机制，持续开展“送解优”专项行动，帮助企业纾困解难。鼓励各县市、湘西高新区等园区通过购买服务等方式，选择管理规范、实力较强的专业中介机构，对拟升规入统和新升规入统的企业提供全过程咨询服务，包括建立健全原始凭证和电子统计台账、办理纳税申报、提供政策咨询等。优化入库预审工作，提高审核通过率。定期举办统计报表业务培训班，及时帮助企业统计人员解决业务中遇到的疑难问题。合理降低企业用工成本，对在库“四上”企业统计人员发放统计工作补贴。各县市、湘西高新区等园区可结合本地实际，给予本地区“四上”企业及在库“大个体”统计人员（报表人员）工作经费补贴，具体补贴金额和发放形式由县市、园区研究决定。（上述补贴不含行政事业单位和国有企业）"},{"no":"五","title":"完善企业发展资金支持机制","text":"完善企业发展资金支持机制。强化服务意识，靠前服务，指导帮助企业准确掌握并合规申报各项优惠政策。支持符合条件的“四上”企业，积极申报和争取国家级、省级各类专项资金、专项试点等。对符合条件的“四上企业”，州产业发展引导基金予以优先支持。鼓励各县市、湘西高新区对连续在库3年以上且符合一定条件和要求的企业给予流动资金贷款贴息支持，州内政府性融资担保机构对符合条件的企业提供融资担保支持。鼓励银行机构精准开发支持规上企业的融资产品，按照市场化原则在贷款规模、贷款利率、授信流程等方面制定优惠政策予以支持。实施创新型企业家培育工程，探索“政府出策出钱、企业育才留才”的人才培育机制。"},{"no":"六","title":"完善涉企检查监管机制","text":"完善涉企检查监管机制。对通过大数据比对、经济普查、统计调查等途径，梳理出来符合入统条件但未入统的企业，实行告知提示，告知提示后仍未申请入统的，应在企业信用档案中予以标记。指导行业协会开展行业信用评价，将是否入统作为信用评价指标纳入企业信用评价体系。将包括“四上”企业在内的市场主体纳入赋码保护范围，减少对企业正常生产经营的干扰，力争做到“无事不扰，有事必应”。依规进行柔性执法，推行“首违不罚”、轻微违法行为不予处罚或依法减轻处罚等措施，更多运用提醒告诫、行政指导等柔性措施，将服务贯穿于监管执法全过程、各环节。"},{"no":"七","title":"完善工作推进落实机制","text":"完善工作推进落实机制。建立由州发改委牵头，州财政局、州工信局、州科技局、州文旅广电局、州农业农村局、州住建局、州市场监管局、州交通运输局、州人社局、州商务局、州统计局、州税务局等部门共同参与的州支持培育发展“四上企业”工作联席会议制度，定期调度工作落实情况，研究解决存在的困难和问题。州直相关部门要按照行业门类分工，全面掌握本行业规上企业发展情况，及时督促、指导、服务市场主体升规（上限）入统。各县市、湘西高新区要高度重视培育发展“四上”企业工作，建立工作推进机制，加强对重点领域、重点园区、重点企业的监测分析和预警预测，细化工作措施，确保“四上”企业培育发展工作有序推进，“四上”企业数量规模和质量效益稳步提升。\n本通知自2025年5月12日起施行，有效期5年。"}],"interpretations":[{"sectionNo":"一","headline":"湘西新入规企业奖10万元，商贸服务业4万至6万元","who":"在湘西州入规纳统的各类企业：新入规工业企业、新入库有资质建筑业企业、主营业务收入1000万元以上的新入库房地产开发经营企业各奖10万元；新入规限额以上批发零售和住宿餐饮企业奖6万元；新入规服务业企业奖4万元。","materials":[],"window":"分两次发放：入规（转企）后次年3月前发 50%，持续在库正常报数的，第三年3月前再发剩余 50%。","where":"湘西州及各县市区统计、工信、商务等主管部门（按行业归口）。","tip":"已入规企业退规（注销）后再进，或靠变更名称、地点、经营范围进规达限的，不再享受奖励。"},{"sectionNo":"二","headline":"在库企业增速越高奖越多，最高5万元","who":"已在库的规上工业、建筑业、房地产开发经营、批发零售和住宿餐饮业、服务业企业；新入规的「四上」企业在入规后第二年（含入规当年）达到条件也可享受。","materials":[],"window":"奖励资金于次年3月前一次性发放。","where":"湘西州统计、工信、商务等行业主管部门。","tip":"增速同比达到20%、40%、60%、80%、100%分别奖1万、2万、3万、4万、5万元；考核指标工业建筑业看产值、房地产业看销售面积、其余看营业收入。"},{"sectionNo":"三","headline":"入规标准10倍奖20万元、20倍奖50万元，分两次发放","who":"商业综合体、专业市场（含二手车、建材、家居家装、农贸市场等）、特色商业街区、产业集聚区、民宿及旅拍等行业市场主体，以联营模式联合组建统一收银、统一核算、统一报税、统一管理的法人企业（管理公司）；其管理服务的企业须为新纳入统计的规上服务业或限上批零住餐业企业，年度营业收入分别达到入规标准10倍、20倍，且自入统年度次年起主营业务收入同比增长15%；集中管理结算的企业中不得包含之前已退规退库的企业。","materials":[],"window":"对达到条件的企业于次年3月发放50%；企业持续在库的，自首次发放之日起满12个月后（即第三年3月）兑付剩余50%。","where":"新纳入统计的规上服务业、限上批零住餐业入统环节（原文未列具体受理部门或系统）。","tip":"奖励分两次发放：次年3月先发50%，满12个月仍在库才兑付剩余50%；集中管理结算的企业中不得包含之前已退规退库的企业。"},{"sectionNo":"四","headline":"在库“四上”企业统计人员可领统计工作补贴","who":"在库“四上”企业及在库“大个体”的统计人员（报表人员），上述补贴不含行政事业单位和国有企业；具体补贴金额和发放形式由县市、园区研究决定。拟升规入统和新升规入统的企业还可获得政府购买服务选定的专业中介机构全过程咨询，含建立健全原始凭证和电子统计台账、办理纳税申报、提供政策咨询。","materials":[],"window":"补贴按统计工作安排发放，统计报表业务培训班定期举办，原文未列具体申报期。","where":"各县市、湘西高新区等园区（补贴标准由县市、园区研究决定）；统计报表业务培训班（原文未列具体受理窗口）。","tip":"补贴对象仅限企业统计人员（报表人员），不含行政事业单位和国有企业；具体补贴金额和发放形式由县市、园区研究决定。"},{"sectionNo":"五","headline":"连续在库3年以上的“四上”企业可获流动资金贷款贴息","who":"符合条件的“四上”企业：可申报和争取国家级、省级各类专项资金、专项试点，州产业发展引导基金予以优先支持；连续在库3年以上且符合一定条件和要求的企业，可获县市、湘西高新区流动资金贷款贴息支持；州内政府性融资担保机构对符合条件的企业提供融资担保支持。","materials":[],"window":"贴息支持面向连续在库3年以上的企业；具体申报期原文未列。","where":"州产业发展引导基金；州内政府性融资担保机构；各县市、湘西高新区；银行机构。","tip":"贴息须同时满足连续在库3年以上且符合一定条件和要求；融资担保、银行贷款按市场化原则办理，原文未列贴息比例。"},{"sectionNo":"六","headline":"纳入赋码保护、首违不罚；拒不入统将被信用标记","who":"包括“四上”企业在内的市场主体（纳入赋码保护范围、适用柔性执法）；经大数据比对、经济普查、统计调查等途径梳理出符合入统条件但未入统的企业，告知提示后仍未申请入统的，在企业信用档案中予以标记。","materials":[],"window":"告知提示后仍未申请入统即予信用标记；柔性执法贯穿监管执法全过程、各环节。","where":"企业信用档案、行业协会行业信用评价、赋码保护范围（原文未列具体受理部门或系统）。","tip":"只有告知提示后仍未申请入统的才在信用档案标记；是否入统已作为信用评价指标纳入企业信用评价体系；轻微违法可不予处罚或依法减轻处罚。"}],"sourceUrl":"http://xxgxq.xxz.gov.cn/zwgk/fdzdgknr/zcwjjjd/bmwj/202505/t20250529_2259185.html","sourceNote":"条文已于 2026-11-09 与官方页面/PDF 逐句比对，逐字一致（明细见 采集包/条文核对表.md）；2026-11-09 按原文「自2025年5月12日起施行，有效期5年」推算 2025-05-12 至 2030-05-11","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","effectiveAt":"2025-05-12","expiresAt":"2030-05-11","hunan":true},{"id":"p-2025-777f85","title":"关于印发《怀化市科技型企业知识价值贷款风险补偿实施办法》的通知","level":"city","region":"怀化市","issuer":"怀化市科学技术局、怀化市财政局、怀化市市场监督管理局、中国人民银行怀化市分行、国家金融监督管理总局怀化监管分局","documentNo":"怀科发〔2025〕20号","publishedAt":"2025-11-20","status":"active","tags":["融资支持","贷款贴息"],"audience":["小微企业"],"summary":"怀化设立2500万元知识价值贷款风险补偿资金，省、市按1:1比例分担；国家高新技术企业信用贷款风险补偿额度最高1000万元，信用担保贷款最高3000万元。原怀政办发〔2025〕5号已废止，本条为补位政策。","sections":[{"no":"一","title":"第一条","text":"为加快实现“三高四新”美好蓝图，深入实施“五新四城”战略，推动建立轻资产债权融资模式，破解科技型企业融资难题，推动“5+10”现代化产业体系高质量发展，根据《中共湖南省委关于深入学习贯彻党的二十届三中全会精神进一步全面深化改革奋力谱写中国式现代化湖南篇章的决定》《湖南省促进金融支持科技型中小企业创新发展若干规定》《湖南省科技型企业知识价值贷款风险补偿实施办法》精神，特制定本办法。"},{"no":"二","title":"第二条","text":"知识价值贷款风险补偿工作按照“政府引导、上下联动、风险分担、企业受益”的原则，由省科技厅和市人民政府对合作银行发放的信用贷款所产生的不良贷款本金，以及合作担保机构提供担保的贷款所产生的逾期未清偿本金进行有限补偿。"},{"no":"三","title":"第三条","text":"本办法所指的科技型企业知识价值贷款（以下简称“知识价值贷款”），是合作银行以科技型企业知识价值评分结果为参考，向科技型企业发放支持其开展科技创新活动的为期三年（含）以内的贷款。包括信用贷款和合作担保机构提供担保的信用担保贷款。"},{"no":"四","title":"第四条","text":"本办法所称的科技型企业知识价值贷款评价指标体系（以下简称“指标体系”，见附件1），是指依托创新积分制所设计的，根据科技型企业科创属性，涵盖知识产权、研发投入、科技人才、经营能力等创新要素并给予不同权重赋值的评价体系。省科技厅对知识价值贷款企业库内企业按照指标体系进行评价，原则上每年不少于一次，评价结果向合作银行、合作担保机构推送。省科技厅可视实际情况对指标体系进行适当调整。"},{"no":"五","title":"第五条","text":"本办法所称的知识价值贷款企业库（以下简称“企业库”），由国家高新技术企业、国家科技型中小企业以及其他科技型企业组成，其中其他科技型企业根据本办法确定。企业库内企业有效期为：国家高新技术企业从认定之日起三年、国家科技型中小企业从评定入库（国家科技型中小企业库）之日起一年、其他科技型企业从纳入企业库之日起一年。\n企业库内企业所属产业不属于“限制”或“禁止”类产业范畴，“限制”与“禁止”类产业根据国家最新版本产业结构调整指导目录划定的范围确定。企业库内企业不含房地产业、金融业和投资与资产管理类、地方政府投融资平台类、地方国有企业资本运营平台类企业。"},{"no":"六","title":"第六条","text":"本办法所称的不良贷款，参照《商业银行金融资产风险分类办法》（中国银行保险监督管理委员会中国人民银行令2023年第1号）执行。"},{"no":"七","title":"第七条","text":"怀化市设立2500万元知识价值贷款风险补偿资金，以财政预算预留方式保障，其中市本级1000万元，各县市区、怀化高新区、怀化国际陆港经开区按约定共同组成1500万元。根据各县市区、怀化高新区、怀化国际陆港经开区企业贷款需求，经县级申请，市科技局、市财政局、市市场监管局、市政府办（金融工作科）、人民银行怀化市分行、国家金融监管总局怀化监管分局共同审核，在1500万元风补资金总额保持不变的情况下，可按年度对县级组成进行调整。\n省科技厅和怀化市按1:1比例设立知识价值贷款风险补偿资金。省、市两级风险补偿资金对合作银行、合作担保机构的风险补偿实行总额控制，若累计补偿金额超出风险补偿资金总额，不再承担风险补偿责任。\n怀化市及各县市区、怀化高新区、怀化国际陆港经开区信用贷款和信用担保贷款的总和，均不能超出允许的最大贷款额度，超出部分不纳入风险补偿的范畴。贷款总额按录入贷款信息时间顺序累加计算。"},{"no":"八","title":"第八条","text":"市科技局、市财政局、市市场监管局、市政府办（金融工作科）、人民银行怀化市分行、国家金融监管总局怀化监管分局共同设立怀化市科技型企业知识价值贷款风险补偿工作机制，由市科技局牵头开展知识价值贷款风险补偿工作，其主要职责为：\n（一）共同制定相关制度性文件，指导各县市区、怀化高新区、怀化国际陆港经开区开展相关工作，并根据各自职责研究制定督促落实的相应措施；\n（二）审定科技型企业知识价值贷款风险补偿措施；\n（三）审议拟风险补偿企业名单；\n（四）考核评估科技型企业知识价值贷款风险补偿工作；\n（五）商定其他相关事项。"},{"no":"九","title":"市科技局具体职责如下：","text":"市科技局具体职责如下：\n（一）牵头制订相关制度性文件，会同市财政局编制市本级风险补偿资金安排总体计划，提出预算建议；\n（二）确定风险补偿工作市级运营管理机构，向省科技厅和市人民政府提出合作银行、合作担保机构建议；\n（三）支持和协调合作银行、合作担保机构开展知识价值贷款工作；\n（四）向合作银行、合作担保机构遴选推荐优质科技型企业；\n（五）职责范围内的其他工作事项。"},{"no":"十","title":"市财政局具体职责如下：","text":"市财政局具体职责如下：\n（一）负责市本级风险补偿资金预算管理，对资金安排进行程序性审核，会同市科技局对风险补偿事项拨付资金；\n（二）按省财政厅要求组织实施财政监督检查、绩效评价等工作；\n（三）按省财政厅要求对合作担保机构进行管理考核；\n（四）职责范围内的其他工作事项。"},{"no":"十一","title":"市市场监管局具体职责如下：","text":"市市场监管局具体职责如下：\n（一）整合企业注册登记、行政处罚、经营异常名录、严重违法失信等信用数据，构建企业信用档案；\n（二）职责范围内的其他工作事项。"},{"no":"十二","title":"市政府办（金融工作科）具体职责如下：","text":"市政府办（金融工作科）具体职责如下：\n（一）推动合作担保机构加快构建服务科技创新的专业化组织架构、管理体系以及风险评审和产品创新等机制；\n（二）对合作担保机构开展的科技担保业务合规与风险状况进行日常监督管理和风险防范处置；\n（三）推动合作担保机构建立容错机制、细化尽职免责清单；\n（四）职责范围内的其他工作事项。"},{"no":"十三","title":"人民银行怀化市分行具体职责如下：","text":"人民银行怀化市分行具体职责如下：\n（一）联合市科技局开展银行机构金融政策效果评估工作，作为动态调整怀化市合作银行的依据；\n（二）推动怀化市内合作银行加快建设科技金融专业团队，在信贷资源和绩效考评方面给予政策倾斜，适当下放授信审批等业务权限；\n（三）职责范围内的其他工作事项。"},{"no":"十四","title":"国家金融监管总局怀化监管分局具体职责如下：","text":"国家金融监管总局怀化监管分局具体职责如下：\n（一）推动怀化市内合作银行加快构建服务科技创新的专业化组织架构、管理体系以及风险评审和产品创新等机制；\n（二）做好科技创新领域金融风险防控，督导怀化市内合作银行对新产品、新业务、新模式的合规性进行审查，对知识价值贷款业务合规与风险状况进行日常监督管理；优化科技金融业务尽职免责机制；\n（三）职责范围内的其他工作事项。"},{"no":"十五","title":"第十五条","text":"怀化市科学技术事务中心为受托的市级运营管理机构，具体职责如下：\n（一）负责全市知识价值贷款工作，受理风险补偿申请，提出风险补偿建议，并按相关程序审定后上报；\n（二）为相关部门、合作银行、合作担保机构和科技型企业提供知识价值贷款风险补偿相关服务；\n（三）负责数据统计分析、业务风险预警，建立调度、监控、预警机制，协助在贷项目监控管理，督促合作银行和合作担保机构对补偿后项目依法追偿；\n（四）根据实际情况，按程序对县级风险补偿资金组成进行调整。\n（五）完成市科技局交办的其他工作。"},{"no":"十六","title":"第十六条","text":"本办法所称的合作银行，是指自愿遵守相关规定，且与省科技厅、市人民政府签订合作协议的各商业银行。具体业务由签订合作协议的各商业银行在怀化市内设立的分支机构办理。"},{"no":"十七","title":"合作银行相关职责：","text":"合作银行相关职责：\n（一）制定和完善与风险补偿资金使用管理相关的内控制度，防范管理风险。定期对贷款的执行情况和资金的使用情况自查、自评，配合主管部门各项审计、监督、绩效评价工作。建立健全内部激励机制，加大对科技型企业的支持力度，简化贷款流程，提高贷款效率；\n（二）严格执行本办法和其他相关规定，保证贷款风险分类准确、信息完整；确保贷款企业全面准确了解知识价值贷款政策，做好相关服务工作；\n（三）将符合本办法规定的科技型企业贷款项目按程序录入知识价值贷款风险补偿管理平台，对录入信息贷款项目的真实性、完整性、合规性负责并提供承诺书，确保申请风险补偿的不良贷款项目符合本办法规定条件；\n（四）负责贷款项目的管理，及时向市、省级运营管理机构书面报送不良贷款项目情况。按规定申请补偿资金，上报已补偿不良贷款项目清收情况，妥善保管申请资料以及原始票据单证以备查验；\n（五）积极、尽责开展已补偿不良贷款项目的处置工作，收回的资金在扣除追偿费用后应按照本办法规定的补偿比例返还风险补偿资金。"},{"no":"十八","title":"第十八条","text":"本办法所称的合作担保机构，是指合法开展科技担保业务、自愿遵守相关规定的政府性融资担保机构。符合条件的担保机构，由市科技局向省科技厅推荐备案，省科技厅公示确定合作担保机构名单。合作担保机构应与省科技厅和市人民政府签订合作协议。"},{"no":"十九","title":"合作担保机构相关职责：","text":"合作担保机构相关职责：\n（一）将符合本办法规定的贷款项目按程序录入知识价值贷款风险补偿管理平台，对录入信息的真实性、完整性、合规性负责，确保申请风险补偿的贷款项目符合本办法规定条件；\n（二）负责信用担保贷款项目的管理，对已代偿项目按规定申请补偿资金，上报已补偿贷款项目清收情况，妥善保管申请资料以及原始票据单证以备查验；\n（三）积极、尽责开展已补偿贷款项目的处置工作，收回的资金在扣除追偿费用后应按照本办法规定的补偿比例返还风险补偿资金。"},{"no":"二十一","title":"第二十一条","text":"本企业库内的其他科技型企业，是指至少具备下列条件之一的企业（具体入库指标界定及所需佐证材料见附件2）：\n1.拥有一项以上Ⅰ类知识产权（包含进入实质审查阶段的发明专利）或二项（含）以上Ⅱ类知识产权；\n2.全职员工中有1名以上博士学历（或者2名（含）以上硕士学历），或1名以上副高级及以上职称的科技人员；\n3.研发费用较上年维持正增长且会计核算健全、实行查账征收并且能够准确归集；\n4.主导或参与制（修）订过国际标准、国家标准、行业标准或地方标准。\n其他科技型企业在不低于本条规定入库条件前提下，由市科技局推荐入库，并提供相关佐证材料。"},{"no":"二十二","title":"第二十二条","text":"企业库内企业可自主选择采用信用贷款、信用担保贷款或两者组合，贷款期限不超过3年。\n国家高新技术企业和国家科技型中小企业，纳入风险补偿范围的信用贷款额度不超过1000万元，信用担保贷款额度不超过3000万元，贷款总额不超过3000万元；其他科技型企业，纳入风险补偿范围的信用贷款额度不超过300万元，信用担保贷款额度不超过1000万元，贷款总额不超过1000万元。\n超过风险补偿限额的贷款不予风险补偿，多家银行放款的按录入贷款信息时间顺序累加计算。"},{"no":"二十三","title":"第二十三条","text":"贷款企业获得的贷款必须用于本企业生产经营，不得用于转贷、委托贷款、并购贷款、国家产业政策禁止和限制的项目以及参与民间借贷、投资资本市场和个人消费等。合作银行应做好贷后管理，规范贷款企业资金用途，一经发现企业有上述不当行为的，由合作银行依照有关法律法规规定收回贷款，不享受风险补偿。一年期（含）以内贷款到期后，符合银行风控条件的企业可以向合作银行申请无还本续贷，同步纳入知识价值贷款风险补偿范畴，无还本续贷最长不超过两年。"},{"no":"二十四","title":"第二十四条","text":"获得贷款的企业应当按合同还本付息，配合合作银行开展贷后检查，及时报告重大事项变更情况，严格遵守信用，主动披露风险，其贷款合同履约情况纳入企业科研诚信记录及其主要高管人员个人征信记录。\n第六章信用贷款"},{"no":"二十五","title":"第二十五条","text":"本办法所称的信用贷款，是指合作银行以科技型企业知识价值评分结果为重要参考，向企业库内企业发放的为期三年（含）以内的无需不动产、准货币等资产抵押或第三方担保的贷款（借款人的法定代表人、股东或实控人及其配偶连带担保责任不视为第三方担保）。合作银行应主动落实减费让利政策要求，贷款利率在放款日最近一期公布的相应期限贷款市场报价利率（LPR）（以下简称“LPR”）基础上，加点幅度不超过140个基点。"},{"no":"二十六","title":"第二十六条","text":"省、市两级原则上按照不超过贷款本金损失的70%给予合作银行风险补偿，省、市两级风险补偿资金按照同比例进行补偿。"},{"no":"二十七","title":"第二十七条","text":"根据各合作银行、怀化市知识价值信用贷款业务不良率（按知识价值贷款的不良贷款余额除以在贷余额计算，风险补偿资金不冲抵不良贷款余额，以下简称“业务不良率”）情况，分类建立机构熔断、区域熔断机制。发生知识价值贷款业务熔断后，对于已经受理的业务，风险补偿资金继续履行风险补偿责任。当业务不良率压降至熔断线以下时，可以申请恢复新增业务。\n（一）机构熔断。若合作银行市级机构（含全市所有分支机构，下同）全市知识价值贷款业务不良率达到3%，市级运营管理机构向其发送风险预警提示，由合作银行市级机构在10个工作日内出具风险情况说明报告；若合作银行全市业务不良率达到5%以上（含），暂停该合作银行所有分支机构的新增业务（续贷业务除外）。合作银行业务不良率下降至5%以下的，可以向市、省级运营管理机构申请恢复新增业务。\n（二）区域熔断。若县市区、怀化高新区、怀化国际陆港经开区业务不良率达到10%（含），市级运营管理机构则向其发送风险预警提示（特殊情况该区域可申请下调业务不良率），该区域需出具风险说明报告，并于6个月内采取措施压降业务不良率，若6个月后业务不良率仍超过10%（含）的，市级运营管理机构将实施区域熔断，该区域将不得新增贷款（续贷业务除外）。\n对于追加风险补偿资金或业务不良率下降至10%以下的，可以向市级运营管理机构申请恢复新增业务。"},{"no":"二十八","title":"信用贷款程序如下：","text":"信用贷款程序如下：\n（一）入库企业向合作银行分支机构提交贷款申请，合作银行按照内部风控程序自主开展贷前审核，参考入库企业的知识价值评价结果，与符合条件的企业签订贷款合同。政府部门、运营管理机构除确定入库企业名单外，不以任何形式参与贷款授信事项的审核；\n（二）合作银行向库内企业发放贷款，并于发放贷款后30个工作日内在知识价值贷款风险补偿管理平台录入贷款信息（见\n附件3第一条）。未按规定录入信息的贷款项目原则上不纳入风险补偿范围。"},{"no":"二十九","title":"信用贷款风险补偿程序：","text":"信用贷款风险补偿程序：\n（一）银行申报。贷款逾期后，合作银行应积极与企业协商贷款还款方案，采取多种形式为企业生存和发展提供便利条件。逾期超过90天仍未全额收回的，由合作银行分支机构发起补偿申请，并将申请资料（见附件3第二条）报市级运营管理机构审核。逾期之日起12个月内合作银行未提出风险补偿申请的贷款项目，不再纳入风险补偿范围。\n（二）风险补偿实施。市级运营管理机构对合作银行分支机构申报材料完整性、是否符合本办法规定进行审核，经怀化市科技型企业知识价值贷款风险补偿工作机制商议，资料齐备的应在45个工作日内出具申请函（见附件4）及合作银行申报材料函告省级运营管理机构，材料不符的需书面反馈合作银行。市级运营管理机构在收到同意实施省级风险补偿的意见后，应督促有关县市区（怀化高新区、怀化国际陆港经开区）及时将应承担的风险补偿资金划拨至合作银行指定账号或办理相关经费拨付手续，并将资金划拨凭证或经费拨付手续相关材料寄送市级运营管理机构，超出县级风险补偿资金限额的，从市本级风险补偿资金中划拨至合作银行指定账号。足额补偿后，市级运营管理机构应将相关凭证寄送至省级运营管理机构。\n（三）银行追偿。合作银行收到风险补偿资金后，应积极开展已补偿贷款项目的追偿工作，每半年书面报告追偿工作情况，原则上于6个月内向市、省两级运营管理机构提交诉讼判决书、仲裁裁决书或其他有权机关出具的相关文书。如合作银行收到追偿所得，应在收到之日起45个工作日内，将扣除追偿费用后的剩余部分按原约定的风险分担比例返还，政府所得部分继续用于补充风险补偿资金。"},{"no":"三十","title":"第三十条","text":"本办法所称的信用担保贷款，是指合作担保机构为企业库内企业提供无抵（质）押反担保要求的信用担保服务，通过银行发放的贷款。"},{"no":"三十一","title":"第三十一条","text":"信用担保贷款利率在LPR基础上加点幅度不超过90个基点，担保费率原则上不超过0.5%/年，单笔期限不超过3年。"},{"no":"三十二","title":"银行按不低于贷款金额的30%、合作担保机构","text":"银行按不低于贷款金额的30%、合作担保机构按不高于贷款金额的70%分担风险责任。合作担保机构应分担部分，除纳入再担保备案按既定比例分险外，根据《关于实施支持科技创新专项担保计划的通知》（财金〔2024〕60号）、《关于实施科技创新担保计划的通知》（国融担函〔2024〕184号）对不同类型企业设置差异化风险分担比例的精神，省级和怀化市分别按照不超过逾期未清偿本金余额的5%给予合作担保机构风险补偿，风险补偿比例可根据国家、省相关政策相应调整。\n对科技型企业中的专精特新“小巨人”、专精特新中小企业、承担国家科技项目的中小企业，省级和怀化市不予风险补偿；对高新技术企业、国家依托“创新积分制”筛选出的科技型中小企业，省级和怀化市分别按照逾期未清偿本金余额的2%给予合作担保机构风险补偿；对科技型中小企业和本办法规定的其他科技型企业，省级和怀化市分别按照逾期未清偿本金余额的5%给予合作担保机构风险补偿。企业有多重资质的，按照《关于实施支持科技创新专项担保计划的通知》（财金〔2024〕60号）、《关于实施科技创新担保计划的通知》（国融担函〔2024〕184号）\n规定最高风险分担比例对应的企业类型，确定省级和怀化市承担的风险补偿比例。\n若信用担保贷款代偿余额（风险补偿资金不冲抵信用担保贷款代偿金额）超过信用担保贷款担保余额的10%（含）后，将暂停合作担保机构的信用担保贷款风险补偿业务。待前述比例降至10%以内，恢复办理风险补偿业务。"},{"no":"三十三","title":"信用担保贷款程序如下：","text":"信用担保贷款程序如下：\n（一）符合条件的科技型企业向银行及合作担保机构提出申请，银行参考入库企业的知识价值评价结果按规定发放贷款；\n（二）合作担保机构于发放贷款后45个工作日内在知识价值贷款风险补偿管理平台录入贷款信息（见附件3第三条）。未按规定录入信息的贷款项目原则上不纳入风险补偿范围。"},{"no":"三十四","title":"信用担保贷款风险补偿程序：","text":"信用担保贷款风险补偿程序：\n（一）担保机构申报。信用担保贷款发生风险，合作担保机构完成代偿后，由合作担保机构发起补偿申请，并将申请资料报市、省两级运营管理机构审核（见附件3第四条），原则上每年可申请两次；\n（二）风险补偿实施。市、省两级运营管理机构分别对合作担保机构申报材料完整性、以及是否符合本办法规定进行审核，资料齐备的应在45个工作日内经相关程序审定并出具独立的审核意见，反馈给合作担保机构，同意实施风险补偿的，应在出具审核意见后10个工作日内将各自应承担的风险补偿资金划拨至合作担保机构指定账号或办理相关经费拨付手续。\n（三）担保机构追偿。合作担保机构收到风险补偿资金后，应积极开展已补偿贷款项目的追偿工作，每半年书面报告追偿工作情况。如合作担保机构收到追偿所得，应在收到之日起45个工作日内，将扣除追偿费用后的剩余部分按原约定的风险分担比例返还，政府所得部分继续用于补充风险补偿资金。\n第八章监督管理"},{"no":"三十五","title":"第三十五条","text":"对同一企业的同一笔贷款，合作银行如已获得其他类别的风险补偿，不得再次申请本办法规定的风险补偿；合作担保机构申请本办法规定的风险补偿，除叠加省财政风险补偿外不得重复申请其他类别省级风险补偿，严禁政策套利。一经查实，收回风险补偿资金，取消合作资格。"},{"no":"三十六","title":"第三十六条","text":"合作银行、合作担保机构以及实施知识价值贷款工作的相关部门应建立尽职合规免责制度，并按规定向相关监管机构报告。对于已履职尽责的，合作银行、合作担保机构及相关部门可按照尽职合规免责有关规定免除相关工作人员全部或部分责任。"},{"no":"三十七","title":"第三十七条","text":"市科技局对合作银行、合作担保机构总体运作情况进行评价，将评价结果上报省科技厅、市人民政府，并提出评价结果使用建议。"},{"no":"三十八","title":"第三十八条","text":"对于因工作失职、失误导致风险补偿资金遭受损失的合作银行、合作担保机构，市科技局将向省科技厅、市人民政府建议，取消其下一年度参与知识价值贷款风险补偿相关合作。对于骗取、套取风险补偿资金的行为，一经查实，将收回已安排的风险补偿资金，并按照《财政违法行为处罚处分条例》（国务院令第588号）的相关规定进行处理，情节严重的，移交司法机关处理。\n第九章附则"},{"no":"三十九","title":"第三十九条","text":"风险补偿不改变合作银行、合作担保机构与借款人的债权债务关系，借款人仍按贷款合同和担保法律文件约定承担全部责任。"},{"no":"四十","title":"本办法自发布之日起实施，有效期5年","text":"本办法自发布之日起实施，有效期5年。在本办法到期后尚未到期的存量贷款，风险补偿资金继续履行风险补偿责任。2025年4月12日至本办法实施之日期间受理的知识价值信用贷款，其风险补偿按《怀化市科技型企业知识价值信用贷款风险补偿实施办法》（怀科发〔2023〕15号）规定执行。"},{"no":"四十一","title":"本办法由市科技局负责解释","text":"本办法由市科技局负责解释。\n\n附件1湖南省科技型企业知识价值贷款评价指标体系一级指标二级指标指标解释技术创新指标（7项)\n1.1研发费用金额（万元）\n研发费用支出主要包括研发活动的人工费用、直接投入费用、用于研发活动的仪器、设备的折旧费、用于研发活动的软件、专利权、非专利技术的摊销费用、新产品设计费、新工艺规程制定费以及其他研发活动相关费用\n1.2研发费用增速（%）\n填报期内企业研发投入增加额占上年研发投入总额的比例\n1.3研发费用占营业收入的比例（%）\n填报期内企业研发投入总额占营业收入总额的比例\n1.4科技人员占职工总数的比重（%）\n填报期内企业参加科技项目活动的人员总数，占企业从业人员期末人数的比例\n1.5与主营业务相关的发明专利申请量（件）\n填报期内企业作为第一申请人向境内外知识产权行政部门提出的与主责主业相关的发明专利申请并被受理后，按规定缴足申请费，符合进入初步审查阶段条件的件数\n1.6与主营业务相关的PCT专利申请量（件）\n填报期内企业作为第一申请人提出的与主责主业相关的PCT国际专利申请数量\n1.7企业技术合同成交额（万元）\n填报期内企业吸纳和输出的技术合同成交总额（开发合作、转让合同）\n成长经营指标（6项）\n2.1高新技术产品收入（万元）\n填报期内企业生产的符合国家和省高新技术重点范围、技术领域和产品参考目录的全新型产品；或省内首次生产的换代型产品；或国内首次生产的改进型产品；或属创新产品等；具有较高的技术含量和较高的附加值的产品所形成的销售收入\n2.2营业收入（万元）\n填报期内企业从事主营业务或其他业务所取得的收入总额\n2.3营业收入增长率（%）\n填报期内企业营业收入增加额对上年营业收入总额的比率\n\n一级指标二级指标指标解释\n2.4研究生以上人员占比（%）\n填报期内企业最高一级教育为研究生教育并取得毕业证书或获得硕士、博士学位证书的人员总数（不包括肄业、结业、在读或辍学人员），占企业从业人员期末人数的比例\n2.5研发费用加计扣除金额（万元）\n研发费用加计扣除金额是指企业在开展研发活动中实际发生的费用，在按规定据实扣除的基础上，可额外按一定比例在税前加计扣除的金额\n2.6净资产利润率（%）\n填报期内企业净利润÷（期初所有者权益+期末所有者权益）÷2×100%辅助指标（5项）\n3.1吸纳应届毕业生人数（人）\n填报期内企业在境内各类高校毕业生中招收的应届毕业生数（包含国家承认的大专学历学生）\n3.2承担建设省级及以上研发或创新平台数量（项）\n企业近两年获批的省级及以上重点实验室等\n3.3获得省级及以上科技奖励数量（项）\n企业近两年作为第一单位获得的省级及以上科技奖励数量\n3.4承担省级及以上科技计划项目数量（项）\n企业近两年作为牵头单位承担的省级及以上科技计划项目数量（国家级科技计划项目可为项目或课题）\n3.5获得风险投资金额（万元）\n填报期内企业获得创投机构、风险投资机构的投资额区域特色指标根据区域科技创新特色设置若干指标按相关文件设置\n\n附件2纳入知识价值贷款企业库指标界定及佐证材料清单\n一、入库指标界定\n1.自主知识产权包括：（1）Ⅰ类知识产权：发明专利（包含进入实质审查阶段的发明专利）、植物新品种、国家级农作物品种、国家新药、国家一级中药保护品种、集成电路布图设计专有权；（2）Ⅱ类知识产权：仅指实用新型专利和软件著作权；\n2.研发费用是指企业研发活动中发生的相关费用，且按照《财政部国家税务总局科技部关于完善研究开发费用税前加计扣除政策的通知》（财税〔2015〕119号）等相关文件规定进行归集。\n二、所需提供的相关佐证材料\n1.企业营业执照扫描件（必须提供）；\n2.申请日前三天内的企业信用信息报告（通过省“一网通办”\n系统、湘易办APP、“信用中国（湖南）”查询下载）（必须提供）；\n3.自主知识产权证书扫描件；进入实质审查阶段的发明专利须提供通知书扫描件（根据选择的入库条件提供）；\n4.学历、学位证书或职称证书扫描件及社保缴纳凭证（根据选择的入库条件提供）；\n5.《研发费用加计扣除优惠明细表》（A107012表）或由第三方机构出具并能体现研发费用情况的财务报告（根据选择的入库条件提供）；\n6.国际标准、国家标准、行业标准或地方标准扫描件（根据选择的入库条件提供）。\n\n附件3贷款录入及风险补偿需提供佐证材料清单\n一、信用贷款录入已发放贷款企业的贷款金额、贷款利率、期限及借据号等信息，上传贷款合同、借据（线上贷款可提供相关系统截图）等相关资料。\n二、信用贷款风险补偿①补偿申请表（附件3-1）②贷款凭证（含贷款合同、放贷凭证，线上贷款可提供相关系统截图）③银行催收依据（含贷款逾期记录和催收通知书、人民法院受理通知或公安机关立案决定或仲裁机构受理回执等法律文书）④承诺函（附件3-2）。\n三、信用担保贷款录入已发放贷款企业的贷款金额、贷款利率、担保费率、主债权期限等信息，上传贷款合同、银行保证合同、委托担保协议或委托担保函等相关资料。\n四、信用担保贷款风险补偿①补偿申请表（附件3-3）②贷款合同③银行保证合同④委托担保协议或委托担保函⑤代偿通知书⑥代偿证明⑦代偿流水。\n\n附件3-1湖南省科技型企业知识价值贷款风险补偿资金申请表（合作银行）编号：\n一、申请合作银行：（盖章）\n收款行名称联系人及方式收款账户、账号申报日期年月日符合条件的信用贷款本金损失共计万元申请补偿金额万元（其中省级、实施区域各万元）\n相关情况说明及佐证材料\n一、贷款基本情况（说明企业和贷款基本情况、录入情况）\n二、风险贷款情况（说明风险贷款形成原因、认定情况、已采取的追偿措施、损失认定等）\n三、贷款追偿情况（介绍目前追偿工作进展，并承诺在获得省、市两级风险补偿后，将继续对贷款损失部分进行追偿并按规定返还）\n（可另附附件）\n二、知识价值贷款信息企业名称联系方式统一社会信用代码所在地录入流水号借款合同编号贷款起止日期利率贷款本金（万元）用途注：一式４份；省科技厅、市科技局，省（市）运营管理机构各1份。\n\n附件3-2承诺函我行已了解湖南省科技型企业知识价值贷款风险补偿相关政策、规定及有关要求，对申请***企业的知识价值贷款（贷款录入编号**）风险补偿作出如下承诺：\n1.在贷后管理过程中，已如实向实施区域与运营管理机构进行了风险告知；\n2.该笔贷款符合监管要求，并未申报其他省级风险补偿资金；\n3.该笔贷款用于贷款合同所述用途，未发生转贷、委托贷款、并购贷款、国家产业政策禁止和限制的项目以及参与民间借贷、投资资本市场和个人消费等；\n4.所提交的材料填写内容和数据真实、准确。\n若违反上述承诺，愿意承担由此带来的一切后果及相关法律责任。\n承诺人: \t**银行盖章年月日\n\n附件3-3湖南省科技型企业知识价值贷款风险补偿资金申请表（合作担保机构）\n编号：\n一、申请合作担保机构：\n收款行名称联系人及方式收款账户、账号申报日期年月日符合条件的信用担保贷款逾期未清偿本金余额共计万元申请补偿金额万元（其中省级、实施区域各万元）\n二、贷款企业信息企业名称联系方式统一社会信用代码所在地企业类型风险补偿比例\n三、知识价值信用担保贷款信息贷款银行名称银担风险分担比例录入流水号贷款合同编号委托担保协议编号保证合同编号贷款本金（万元）贷款起止日期贷款利率担保费率我司承诺该笔担保业务符合监管要求，提供的所有资料和信息真实、完整、准确。如申请项目存在违背《湖南省科技型企业知识价值贷款风险补偿实施办法》（湘科发〔2025〕72号）及相关协议的情形，我司将返还风险补偿资金，并承担由此带来的一切后果及相关法律责任。\n申请合作担保机构公章：\n年月日\n\n附件4关于申请湖南省科技型企业知识价值贷款风险补偿的函（参考样稿）\n省级运营管理机构：\n年月日，我单位收到银行提交的关于（企业名称）知识价值贷款的风险补偿资金申请材料，涉及贷款本金损失（万元）。依据《湖南省科技型企业知识价值贷款风险补偿实施办法》（湘科发〔2025〕72号）等文件规定，经调查核实等相关程序，我单位同意对该笔贷款进行风险补偿，补偿金额万元。现申请对该笔贷款进行省级风险补偿，补偿金额万元，并复函予以明确。\n（需以附件说明调查核实情况并加盖公章）\n**市级运营管理机构盖章年月日怀化市科学技术局办公室2025年11月26日印发"}],"interpretations":[{"sectionNo":"八","headline":"六部门共设风险补偿机制，市科技局牵头","who":"怀化市科技型企业（经知识价值评价后有贷款需求的企业）；合作银行与合作担保机构。","materials":[],"window":"按市科技局年度工作安排。","where":"市科技局牵头；市财政局、市市场监管局、市政府办（金融工作科）、人民银行怀化市分行、金融监管总局怀化监管分局共同参与。","tip":"风险补偿不是自动发生的，要经「审定补偿措施—审议拟补偿企业名单」两道程序；对个别事项由六部门商定。","stale":true,"staleReason":"chg-20261128-0007 改了这一条正文"},{"sectionNo":"十五","headline":"具体受理找市科学技术事务中心（市级运营管理机构）","who":"需要申请知识价值贷款风险补偿的企业、合作银行、合作担保机构。","materials":[],"window":"按受托机构受理流程，审定后上报。","where":"怀化市科学技术事务中心（受托的市级运营管理机构）。","tip":"它还负责数据统计、风险预警和督促追偿；县级风险补偿资金的构成调整也由它按程序办理。","stale":true,"staleReason":"chg-20261128-0004 改了这一条正文"},{"sectionNo":"三","headline":"知识价值贷款为期三年以内，分信用贷款和信用担保贷款","who":"科技型企业；由合作银行以知识价值评分结果为参考，发放用于支持其开展科技创新活动的贷款。","materials":[],"window":"贷款期限为三年（含）以内。","where":"合作银行（以科技型企业知识价值评分结果为参考发放）。","tip":"贷款包括信用贷款和合作担保机构提供担保的信用担保贷款两类。"},{"sectionNo":"五","headline":"企业库含高新技术企业等，有效期最长三年","who":"国家高新技术企业（认定之日起三年内）、国家科技型中小企业（评定入库之日起一年内）、其他科技型企业（纳入企业库之日起一年内）；所属产业不得属“限制”或“禁止”类，且不含房地产业、金融业和投资与资产管理类、地方政府投融资平台类、地方国有企业资本运营平台类企业。","materials":[],"window":"国家高新技术企业从认定之日起三年、国家科技型中小企业从评定入库之日起一年、其他科技型企业从纳入企业库之日起一年。","where":"国家科技型中小企业库、知识价值贷款企业库。","tip":"企业库内企业所属产业不属于“限制”或“禁止”类产业范畴；房地产业、金融业和投资与资产管理类等企业不纳入。"},{"sectionNo":"七","headline":"风险补偿资金共2500万元，省市按1:1设立，总额控制","who":"合作银行、合作担保机构（省科技厅与怀化市按1:1比例设立风险补偿资金）；贷款企业范围为怀化市及各县市区、怀化高新区、怀化国际陆港经开区内企业。","materials":[],"window":"可按年度对县级组成进行调整；贷款总额按录入贷款信息时间顺序累加计算。","where":"市科技局、市财政局、市市场监管局、市政府办（金融工作科）、人民银行怀化市分行、国家金融监管总局怀化监管分局共同审核。","tip":"累计补偿金额超出风险补偿资金总额的，不再承担风险补偿责任；超出允许最大贷款额度的部分不纳入风险补偿范畴。","stale":true,"staleReason":"chg-20261128-0002 改了这一条正文"},{"sectionNo":"二十一","headline":"其他科技型企业满足四类条件之一即可入库","who":"其他科技型企业，至少具备下列条件之一：拥有1项以上Ⅰ类知识产权（含进入实质审查阶段的发明专利）或2项（含）以上Ⅱ类知识产权；全职员工中有1名以上博士学历（或2名（含）以上硕士学历）或1名以上副高级及以上职称的科技人员；研发费用较上年维持正增长且会计核算健全、实行查账征收并能准确归集；主导或参与制（修）订过国际标准、国家标准、行业标准或地方标准。","materials":[],"window":"其他科技型企业在不低于本条规定入库条件前提下，由市科技局推荐入库。","where":"市科技局（推荐入库并收取佐证材料）。","tip":"企业有多重条件的按不低于本条入库条件执行；具体入库指标界定及所需佐证材料见附件2。"},{"sectionNo":"二十二","headline":"高企信用贷款最高1000万元，其他科技型企业最高300万元","who":"国家高新技术企业和国家科技型中小企业：信用贷款额度不超过1000万元、信用担保贷款额度不超过3000万元、贷款总额不超过3000万元；其他科技型企业：信用贷款不超过300万元、信用担保贷款不超过1000万元、贷款总额不超过1000万元；贷款期限不超过3年。","materials":[],"window":"贷款期限不超过3年。","where":"合作银行（企业库内企业自主选择贷款方式）。","tip":"超过风险补偿限额的贷款不予风险补偿；多家银行放款的按录入贷款信息时间顺序累加计算。","stale":true,"staleReason":"chg-20261128-0010 改了这一条正文"},{"sectionNo":"二十三","headline":"贷款须用于生产经营，一年期贷款可申请无还本续贷","who":"获得知识价值贷款的贷款企业；贷款必须用于本企业生产经营，不得用于转贷、委托贷款、并购贷款、国家产业政策禁止和限制的项目以及参与民间借贷、投资资本市场和个人消费等；申请续贷须为一年期（含）以内贷款到期后且符合银行风控条件。","materials":[],"window":"无还本续贷最长不超过两年。","where":"合作银行（负责贷后管理、规范资金用途并收回违规贷款）。","tip":"一经发现企业有上述不当行为，由合作银行收回贷款，不享受风险补偿。"},{"sectionNo":"二十四","headline":"企业须按合同还本付息，履约情况纳入科研诚信和征信","who":"获得知识价值贷款的贷款企业；须按合同还本付息、配合贷后检查、及时报告重大事项变更、严格遵守信用并主动披露风险。","materials":[],"window":"贷款合同存续期间。","where":"合作银行（开展贷后检查）。","tip":"贷款合同履约情况纳入企业科研诚信记录及其主要高管人员个人征信记录。"},{"sectionNo":"二十五","headline":"信用贷款无需抵押担保，利率加点不超过140个基点","who":"企业库内企业；信用贷款为三年（含）以内、无需不动产、准货币等资产抵押或第三方担保的贷款；借款人的法定代表人、股东或实控人及其配偶连带担保责任不视为第三方担保。","materials":[],"window":"贷款期限为三年（含）以内。","where":"合作银行（应主动落实减费让利政策要求）。","tip":"贷款利率在放款日最近一期公布的相应期限LPR基础上，加点幅度不超过140个基点。","stale":true,"staleReason":"chg-20261128-0011 改了这一条正文"},{"sectionNo":"二十六","headline":"按贷款本金损失不超过70%给予银行风险补偿","who":"合作银行；省、市两级按同比例给予风险补偿，适用于知识价值贷款形成的贷款本金损失。","materials":[],"window":"按贷款本金损失计算，省、市两级同比例补偿。","where":"省、市两级风险补偿资金（省科技厅与怀化市按1:1设立）。","tip":"补偿比例原则上不超过贷款本金损失的70%，且省、市两级风险补偿资金按同比例进行补偿。"},{"sectionNo":"二十七","headline":"银行不良率达5%暂停新增业务，区域达10%实施熔断","who":"合作银行市级机构（含全市所有分支机构）及各县市区、怀化高新区、怀化国际陆港经开区；业务不良率按知识价值贷款的不良贷款余额除以在贷余额计算。","materials":[],"window":"不良率达3%时10个工作日内出具风险情况说明报告；区域需6个月内压降，逾期仍超10%（含）实施熔断。","where":"市级运营管理机构、省级运营管理机构。","tip":"熔断后已受理业务的风险补偿资金继续履行责任；不良率压降至熔断线以下可申请恢复新增业务，续贷业务除外。","stale":true,"staleReason":"chg-20261128-0012 改了这一条正文"},{"sectionNo":"二十八","headline":"入库企业向合作银行提交申请，放款后30个工作日内录入平台","who":"企业库内入库企业；向合作银行分支机构提交贷款申请，由银行按内部风控程序自主开展贷前审核并参考知识价值评价结果。","materials":[],"window":"发放贷款后30个工作日内在知识价值贷款风险补偿管理平台录入贷款信息。","where":"合作银行分支机构、知识价值贷款风险补偿管理平台。","tip":"未按规定录入信息的贷款项目原则上不纳入风险补偿范围；政府部门、运营管理机构不参与贷款授信事项审核。"},{"sectionNo":"三十","headline":"信用担保贷款无需抵质押反担保，由担保机构担保","who":"企业库内企业；由合作担保机构提供无抵（质）押反担保要求的信用担保服务，通过银行发放贷款。","materials":[],"window":"按贷款合同约定期限执行。","where":"合作担保机构、合作银行。","tip":"担保服务不要求抵（质）押反担保。"},{"sectionNo":"三十一","headline":"担保贷款利率加点不超过90个基点，费率不超0.5%/年","who":"获得信用担保贷款的企业库内企业；单笔期限不超过3年。","materials":[],"window":"单笔期限不超过3年。","where":"合作银行、合作担保机构。","tip":"担保费率原则上不超过0.5%/年；贷款利率在LPR基础上加点幅度不超过90个基点。"},{"sectionNo":"三十二","headline":"银行分担不低于30%、担保机构不高于70%，补偿分档","who":"合作银行与合作担保机构；专精特新“小巨人”、专精特新中小企业、承担国家科技项目的中小企业省级和怀化市不予风险补偿；高新技术企业、国家依托“创新积分制”筛选出的科技型中小企业按逾期未清偿本金余额2%补偿；科技型中小企业和其他科技型企业按5%补偿；企业有多重资质的按最高风险分担比例对应类型确定。","materials":[],"window":"信用担保贷款代偿余额超过担保余额10%（含）后暂停风险补偿业务，降至10%以内恢复。","where":"省级和怀化市（分别给予合作担保机构风险补偿）。","tip":"企业有多重资质的，按最高风险分担比例对应的企业类型确定省级和怀化市承担的风险补偿比例。","stale":true,"staleReason":"chg-20261128-0015 改了这一条正文"},{"sectionNo":"三十三","headline":"企业向银行及担保机构申请，放款后45个工作日内录入平台","who":"符合条件的科技型企业（企业库内企业）；向银行及合作担保机构提出申请，由银行参考知识价值评价结果发放贷款。","materials":[],"window":"发放贷款后45个工作日内在知识价值贷款风险补偿管理平台录入贷款信息。","where":"合作银行、合作担保机构、知识价值贷款风险补偿管理平台。","tip":"未按规定录入信息的贷款项目原则上不纳入风险补偿范围。","stale":true,"staleReason":"chg-20261128-0016 改了这一条正文"},{"sectionNo":"三十五","headline":"同一笔贷款不得重复申请风险补偿，严禁政策套利","who":"合作银行、合作担保机构；同一企业的同一笔贷款已获得其他类别风险补偿的，不得再次申请本办法规定的风险补偿。","materials":[],"window":"风险补偿申请及后续核查期间。","where":"风险补偿审核环节（原文未列具体部门）。","tip":"一经查实收回风险补偿资金并取消合作资格；担保机构除叠加省财政风险补偿外，不得重复申请其他类别省级风险补偿。","stale":true,"staleReason":"chg-20261128-0017 改了这一条正文"},{"sectionNo":"三十九","headline":"风险补偿不免除借款人的还本付息责任","who":"获得知识价值贷款的借款人；仍按贷款合同和担保法律文件约定承担全部责任。","materials":[],"window":"贷款合同及担保法律文件约定的全期间。","where":"合作银行、合作担保机构（与借款人的债权债务关系不变）。","tip":"风险补偿不改变合作银行、合作担保机构与借款人的债权债务关系，借款人的责任不免除。"}],"sourceUrl":"https://www.huaihua.gov.cn/kjj/c132709/202511/c9a956f1301b49b68853a5f57a87483c/files/f28651ab2a52486eafb62085f25586ed.pdf","sourceNote":"条文已于 2026-11-09 与官方页面/PDF 逐句比对，逐字一致（明细见 采集包/条文核对表.md）；2026-11-09 条文按官方原文重切（40 条，自查召回 100%）","verified":false,"isSample":false,"numberStyle":"clause","bodyVerified":"verbatim","hunan":true},{"id":"p-2025-85cf55","title":"永州市人民政府关于印发《永州市推动先进制造业高质量发展若干措施》的通知","level":"city","region":"永州市","issuer":"永州市人民政府","documentNo":"永政发〔2025〕2号","publishedAt":"2025-03-10","status":"active","tags":["认定资质","专项资金","研发创新"],"audience":["小微企业"],"summary":"永州对新认定国家级专精特新\"小巨人\"、国家级制造业单项冠军奖励50万元；省级专精特新中小企业、省级制造业单项冠军奖励20万元；新入统规模以上工业企业奖励不低于5万元。","sections":[{"no":"一","title":"明确工作目标","text":"到2027年，打造区域先进制造业高地取得重大进展。加快打造食品加工、智能家居、现代农业、文化旅游、新能源、数字产业等6个千亿级产业；推动约500家企业扩能升级。力争制造业增加值占地区生产总值比重提高到25%以上，数字经济核心产业增加值占地区生产总值比重提高到10%以上。高新技术制造业增加值占制造业增加值比重达20%以上，规模以上工业企业高端化智能化绿色化改造率达50%以上。"},{"no":"二","title":"优化区域布局","text":"（一）改造提升传统产业。大力推动食品加工、智能家居（家电）等传统产业提质增效、转型升级，着力培育消费品工业“三品”标杆企业。绿色食品产业，用活用足用好省农业农村厅、省发展改革委等四部门联合印发的《支持永州蔬菜出口高质量发展的若干政策措施》（湘农联〔2024〕38号），支持永州陆港熙可全球食品保鲜加工中心、永州首衡国际农产品交易中心建设，推进农产品精深加工和综合利用；支持道县、新田、江永、江华等县区依托本地资源优势，重点打造粤港澳大湾区“菜篮子”功能区，加快推进传统优势食品产区和地方特色食品产业发展。智能家居（家电）产业，支持新田、蓝山、双牌、东安等县区优化资源培育，大力推进“以竹代塑”“以竹代木”行动，着力打造农林产品加工产业集聚区。支持冷水滩、新田、江华等县区以智能家居（家电）、绿色板材及配套产业为重点，开展产品展览、供需对接等产业生态活动。〔市工信局、市商务局、市农业农村局、市林业局，各县市区人民政府（含管理区、永州经开区，下同）按职责分工负责，以下各项措施均需各县市区人民政府落实，不再列出〕\n（二）培育壮大新兴产业。抢抓国家“两重”“两新”重大机遇，加快培育壮大新能源新材料、数字产业等新兴产业。新能源新材料产业，深入推进新能源产业链上下游融合，以资源换产业，引进一批风光绿色装备制造项目，加快双牌天子山、江华湾水源抽水蓄能等绿能重点项目建设。推进道县锂多金属矿采选冶一体化深度开发应用，加快紫金锂业锂矿采选项目、6万吨碳酸锂冶炼项目建设，将道县建成中国重要的锂电新能源产业基地；加快湖南稀土新材料产业园、江华离子型稀土基地、零陵绿色锰系新材料产业园建设，将永州打造成全国重要的独居石综合利用基地、全国领先的锰系新材料产业基地和产品供应中心。数字产业，加快推进5G基础设施建设，布局和建设一批高性能算力中心，大力发展大数据、人工智能、移动互联网、云计算等绿色计算产业。加快新一代信息技术集成创新和融合应用，推动产品高端化、轻量化和全产业链发展，纵深推进“智赋万企”行动，打造更多应用场景。〔市工信局、市数据局（行政审批服务局）、市商务局按职责分工负责〕"},{"no":"三","title":"加快技术改造","text":"（三）支持企业设备更新。抢抓政策机遇，引导企业开展工业领域大规模设备更新。每年支持120家左右工业企业开展技术改造和设备更新，到2027年，推动约500家工业企业就地扩能提质增效。对当年在建且通过湖南省制造强省项目库系统入库的设备更新和技术改造项目，总投资达到500万元以上的，择优向工业和信息化部、省工业和信息化厅推荐争取技术改造再贷款和贴息等政策支持；更新设备投资达到100万元及以上的，对项目一年期（含）以上设备购置贷款，由受益财政按贷款本金的1%给予贴息，贴息期限1年。单个项目贴息1次，最高不超过50万元，单个企业每年最多贴息2个项目。（市工信局、市发改委、市财政局按职责分工负责）\n（四）支持企业数智改造。重点打造一批省级及以上标杆示范企业，推动更多企业实现“智改数转”互联。到2027年，力争推动“上云”企业15000家以上、“上平台”企业1200家以上，新增40家以上企业通过国家两化融合管理体系贯标评定。培育一批数字化转型服务商，对开展两化融合、网络安全分类分级等各类数字化转型服务的服务商，当年完成服务企业20家、40家、60家以上的，由受益财政分别给予5万元、10万元、15万元一次性奖励。对当年新增的两化融合管理体系贯标企业、数字化转型贯标企业、“5G+工业互联网”标杆工厂、工业互联网平台、省100个标志性新基建项目、省级数字化转型标杆项目、省级人工智能赋能新型工业化典型应用场景，由受益财政奖励20万元/个。对被工业和信息化部当年新认定的卓越级智能工厂的企业，由受益财政奖励50万元/个；对当年新认定的省级智能制造标杆企业、车间，由受益财政分别奖励20万元/个、10万元/个。对成功入选“湖南省智能制造系统解决方案供应商推荐目录”的企业，由受益财政奖励10万元/个。〔市工信局、市财政局、市数据局（行政审批服务局）按职责分工负责〕\n（五）支持企业技术创新。持续推进规模以上工业企业创新研发活动全覆盖工作，支持企业开展新技术、新产品、新工艺研发应用。对当年新认定的国家级、省级工业设计中心，由受益财政分别奖励20万元、10万元。鼓励企业争取“五首”产品认定（首台套技术装备、首批次新材料、首版次高端软件、首轮次工程流片芯片、首套件基础电子元器件），对当年新认定国家级、省级“五首”产品的企业，由受益财政分别奖励50万元、20万元。对被工业和信息化部当年新认定为国家技术创新示范企业的工业企业，由受益财政给予20万元一次性奖励。对当年新认定为国家级、省级中试基地（平台）的工业企业，由受益财政分别给予50万元、10万元一次性奖励。（市工信局、市科技局、市财政局按职责分工负责）\n（六）支持企业低碳转型。聚焦冶金、建材、纺织等重点领域，加快传统产业转型升级，积极稳妥推进工业领域碳减排。鼓励企业开展协同降碳行动，探索减污降碳协同增效有效模式，推动低碳协同示范和数字化绿色化协同转型。围绕重点行业和领域，培育绿色工厂、绿色园区，严控污染排放，加速循环化改造，积极争取创建零碳工业园区、国家级绿色工业园区，力争每年打造1—2家省级绿色园区、创建5家省级以上绿色工厂，对评为国家级、省级绿色工厂的企业，由受益财政分别给予100万元、50万元一次性奖励。加快园区内企业实施系统性清洁生产改造，鼓励工业企业开展自愿性清洁生产审核，对通过省工业和信息化厅自愿性清洁生产审核验收的工业企业，由受益财政给予3万元一次性奖励。（市工信局、市财政局按职责分工负责）\n（七）支持企业品牌提升。推动企业建立新型质量管理体系和品牌培育管理体系，鼓励企业参与标准制定，持续培育制造业质量标杆企业，遴选推荐一批典型案例，提高企业产品质量和品牌价值。对当年新认定的国家级、省级制造业质量标杆企业，由受益财政分别给予50万元、10万元一次性奖励；对当年新认定的湖南省原材料、消费品工业“三品”标杆企业，由受益财政给予5万元奖励。（市市场监管局、市工信局、市财政局按职责分工负责）\n（八）支持企业融通发展。落实大中小企业融通创新“携手行动”，全力培育单项冠军等优质企业，支持中小微企业走专精特新发展之路。到2027年，培育国家级专精特新“小巨人”企业18家以上、省级专精特新中小企业400家以上，国家级制造业单项冠军企业5家以上、省级制造业单项冠军企业20家以上。对当年新认定的国家级专精特新“小巨人”企业、国家级制造业单项冠军企业，由市本级财政奖励50万元；对当年新认定的省级专精特新中小企业、省级制造业单项冠军企业一次性奖励20万元，其中中心城区（冷水滩区、零陵区、永州经开区）企业的奖励资金由市、区两级财政各承担50%，其他县（市）企业的奖励资金由受益县（市）财政承担，奖励标准不低于20万元。对当年通过复核的国家级专精特新“小巨人”企业，由市本级财政奖励5万元；对当年通过复核的省级专精特新中小企业，由受益县市区财政奖励1万元。持续开展新增规模以上工业企业行动，每年新增规模以上工业企业100家以上，由受益财政安排规模以上工业企业培育专项资金，对当年新入统规模以上工业企业，给予不低于5万元的一次性奖励。（市工信局、市财政局按职责分工负责）"},{"no":"四","title":"强化要素保障","text":"（九）加大政策要素保障。市本级财政每年预算安排3000万元先进制造业专项资金支持新型工业化发展。引导银行机构聚焦小微企业融资需求，合理确定信贷投放节奏，力争中小企业综合融资成本稳中有降。对重点项目、重点企业，在用工、用地、用林、用能、用气上给予重点支持，进一步优化营商环境，依法平等保护企业合法权益。〔市财政局、市工信局、市人社局、市自然资源和规划局、市林业局、市城管局、市数据局（行政审批服务局）、中国人民银行永州市分行按职责分工负责〕\n（十）支持开展表扬激励。对扩能升级效果明显的重点存量工业企业，优先推荐申报“湖南省民营企业100强”“新湖南贡献奖”“全国优秀企业家”“湖南省优秀企业家”“大国工匠”“劳动模范”等国家级、省级先进集体和个人。加大宣传力度，营造尊重和弘扬企业家精神的良好社会氛围。（市委统战部、市发改委、市工信局、市工商联、市总工会按职责分工负责）\n本文件自公布之日起施行，有效期至2027年12月31日。奖励事项涉及同类奖补政策的，按就高标准执行，对已获得上级奖补资金的同一事项，市县财政不重复奖励。我市已有的政策与本政策规定不一致的，以本政策为准。政策执行过程中，若法律法规和上级政策另有规定的，从其规定。年度内发生较大及以上生产安全事故、环境污染事故及其他重大违法违规行为的企业不予享受政策支持。本文件的具体解释工作由市工信局承担。"}],"interpretations":[{"sectionNo":"三","headline":"设备更新贷款贴息1%，单个项目最高50万元","who":"永州市当年在建、且已通过湖南省制造强省项目库入库的设备更新和技术改造项目：总投资达到500万元以上；更新设备投资达到100万元及以上。","materials":[],"window":"对一年期（含）以上设备购置贷款贴息，贴息期限1年；本文件有效期至 2027年12月31日。","where":"市工信局、市发改委、市财政局按职责分工；由受益财政贴息。","tip":"单个项目贴息1次、最高不超过50万元，单个企业每年最多贴息2个项目；总投资500万元以上的项目还会择优推荐争取中央、省级技改再贷款和贴息。"},{"sectionNo":"三","headline":"新认定卓越级智能工厂奖50万元，省级标杆奖20万元","who":"永州市当年新增的两化融合管理体系贯标企业、数字化转型贯标企业、「5G+工业互联网」标杆工厂、工业互联网平台、省100个标志性新基建项目、省级数字化转型标杆项目、省级人工智能赋能新型工业化典型应用场景；以及工信部当年新认定的卓越级智能工厂。","materials":[],"window":"按当年认定结果兑现。","where":"受益财政（市/县市区）兑现，市工信局牵头。","tip":"卓越级智能工厂 50万元/个，省级智能制造标杆企业 20万元/个、车间 10万元/个；同类奖补按就高原则，同一事项已获上级奖补的市县不重复奖励。"},{"sectionNo":"四","headline":"市本级每年安排3000万元先进制造业专项资金","who":"永州市先进制造业企业及重点项目、重点企业（在用工、用地、用林、用能、用气上给予重点支持）；扩能升级效果明显的重点存量工业企业（优先推荐申报省级、国家级先进集体和个人）；年度内发生较大及以上生产安全事故、环境污染事故及其他重大违法违规行为的企业不予享受。","materials":[],"window":"自公布之日起施行，有效期至2027年12月31日","where":"市财政局、市工信局、市人社局、市自然资源和规划局、市林业局、市城管局、市数据局（行政审批服务局）、中国人民银行永州市分行按职责分工","tip":"同类奖补按就高标准执行，已获上级奖补资金的同一事项市县财政不重复奖励；已有政策与本政策不一致的以本政策为准；年度内发生较大及以上生产安全事故、环境污染事故及其他重大违法违规行为的企业不予享受。"}],"sourceUrl":"https://zt.yzcity.gov.cn/cnyz/szfwj/202503/1846bc5bdb19429e908c66220dee6359.shtml","sourceNote":"条文已于 2026-11-09 与官方页面/PDF 逐句比对，逐字一致（明细见 采集包/条文核对表.md）","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"p-2025-a301d3","title":"湘潭市一次性创业补贴和创业经营场所租金补贴办法","level":"city","region":"湘潭市","issuer":"湘潭市人力资源和社会保障局、湘潭市财政局","documentNo":"","publishedAt":"2025-06-04","status":"active","tags":["创业补贴","场地支持"],"audience":["小微企业","个体工商户","高校毕业生"],"summary":"湘潭市首次创办小微企业或个体经营正常运营1年以上并吸纳就业的，一次性创业补贴3000-15000元；大学生创业还可享经营场所租金补贴第一年每月800元、第二年每月600元。","sections":[{"no":"一","title":"一次性创业补贴申报条件及标准","text":"(一)申报条件\n申报一次性创业补贴(含大学生一次性创业补贴),需同时具备以下条件:\n1.在我市范围内首次登记注册的初创企业,登记注册时间在5年以内(以首次营业执照登记的成立日期为准,2025年申报企业的注册时间为2020年1月1日至2024年12月31日期间,以此类推)。\n2.申报一次性创业补贴需正常运营1年以上,吸纳2名以上(含2名)城乡劳动者就业(不含法定代表人),缴纳城镇职工社会保险费6个月以上且处于正常缴纳状态。其中,申报大学生一次性创业补贴需正常运营1年以上,吸纳1名以上城乡劳动者就业(不含法定代表人),缴纳城镇职工社会保险费3个月以上且处于正常缴纳状态。\n3.符合湘潭市产业发展方向。\n4.近两年在信用中国(湖南湘潭)无行政处罚等违法记录,无知识产权或其他经济、法律纠纷。\n5.申报一次性创业补贴的企业法定代表人需属于就业困难人员或返乡入乡农民工。其中,申报大学生一次性创业补贴的企业法定代表人需属于毕业2年内的普通高校、职业学校、技工院校学生和留学归国人员。法定代表人持股比例不低于公司总股份的30%。法定代表人近两年由不符合以上条件的群体变更为符合以上条件的群体的,不纳入补贴范围。\n(二)补贴标准\n根据吸纳城乡劳动者就业人数情况,一次性创业补贴标准为3000元至15000元不等。吸纳城乡劳动者就业人数取近6个月缴纳城镇职工社会保险人数,吸纳2人(含2人)就业的补贴3000元,吸纳2人以上就业的每增加1人给予1000元补贴,最高不超过15000元。\n其中,大学生一次性创业补贴标准为10000元、12000元或15000元不等。吸纳城乡劳动者就业人数取近3个月缴纳城镇职工社会保险人数,吸纳1-5人(含5人)就业的,补贴12000元;吸纳5人以上就业的,补贴15000元。对于我市认定的高校类大学生创业孵化基地内的大学生创业主体,正常运营1年以上的,经专家评审认定,可放宽缴纳城镇职工社会保险费条件,补贴10000元。\n已经享受过市财政同一项目补贴的,不能重复享受。\n(三)所需资料\n1.《湘潭市一次性创业补贴(含大学生一次性创业补贴)申请表》(附件1)。\n2.营业执照或其他登记注册证明,法定代表人身份证,公司股权分配证明资料。\n3.法定代表人相关证明材料。返乡入乡农民工需提供湘潭市行政区域范围内户籍地乡镇(街道)人力资源社会保障服务站出具的返乡入乡创业佐证资料;毕业生需提供毕业证;留学归国人员需提供经教育部门认证的佐证资料。\n就业困难人员无需提供佐证资料,由市县人社部门在信息系统中核实。\n4.申报一次性创业补贴需提供近6个月的城镇职工社会保险费缴纳证明。其中,申报大学生一次性创业补贴需提供近3个月的城镇职工社会保险费缴纳证明(对于我市认定的高校类大学生创业孵化基地内的大学生创业主体,可不提供城镇职工社会保险费缴纳证明,但需提供正常经营相关交易证明材料)。\n5.其他佐证资料。"},{"no":"二","title":"第二条","text":"创业经营场所租金补贴申报条件及标准(仅限大学生群体创业)\n(一)申报条件\n申报创业经营场所租金补贴,需同时具备以下条件:\n1.在我市范围内首次登记注册的初创企业,登记注册时间在5年以内(以首次营业执照登记的成立日期为准,2025年申报企业的注册时间为2020年1月1日至2024年12月31日期间,以此类推)。\n2.正常运营1年以上,吸纳1名以上城乡劳动者就业(不含法定代表人),缴纳城镇职工社会保险费3个月以上且处于正常缴纳状态。\n3.符合湘潭市产业发展方向。\n4.近两年在信用中国(湖南湘潭)无行政处罚等违法记录,无知识产权或其他经济、法律纠纷。\n5.法定代表人属于毕业2年内的普通高校、职业学校、技工院校学生和留学归国人员,法定代表人持股比例不低于公司总股份的30%。法定代表人近两年由不符合以上条件的群体变更为符合以上条件的群体的,不纳入补贴范围。\n使用自有房产创业及各创业孵化基地内享受免费入驻的企业,不纳入创业经营场所租金补贴范围。\n(二)补贴标准\n第一年每月800元、第二年每月600元。补贴期限自营业执照成立日期的次月至补贴有效期内,连续计算两年。实际租金低于补贴标准的,按实际租赁合同约定的租金额度给予补贴。同一初创企业最多申请两次、累计不超过2年的经营场所租金补贴。申报企业有多处经营场所的,只能就一处经营场所提出申请。已经享受过市财政同一项目补贴的,不能重复享受。\n(三)所需资料\n1.《湘潭市创业经营场所租金补贴申请表》(附件2).\n2.营业执照或其他登记注册证明,法定代表人身份证,公司股权分配证明资料。\n3.法定代表人属于大学生群体的相关证明材料。毕业生需提供毕业证;留学归国人员需提供经教育部门认证的佐证资料。\n4.近3个月的城镇职工社会保险费缴纳证明。\n5.房产证明(如无房产证则提供商品房销售合同)、租赁合同、缴纳租金的发票和转账记录(注明租赁起止时间段)等。\n6.其他佐证资料。"},{"no":"三","title":"申报流程","text":"(一)自主申报。符合条件的创业主体按工商注册(或登记机关)属地管理原则,向所在的市、县市区人力资源和社会保障局申报。\n(二)考察审核。人社部门受理申请后,在每季度末月进行审核,核定申报企业吸纳就业人数及补贴金额,并做好实地考察工作。\n(三)网上公示。考察审核完成后确定的补贴企业名单,应在同级人力资源和社会保障局官网上进行公示,公示期为5个工作日。公示期间无异议,或者有异议但经调查不成立的,由同级人力资源和社会保障局行文公布。\n(四)资金拨付。受补贴名单公布后,由人社部门汇总补贴对象信息报送至同级财政部门,按照相关规定将补贴资金拨付至申报企业账户,并在\"湖南人社一体化业务管理系统\"内录入补贴信息。"},{"no":"四","title":"补贴终止","text":"出现以下情形之一的,终止享受补贴:\n1.申报审核期间,初创企业实体处于停业状态,或已注销、吊销营业执照的。\n2.经核实有其他不符合补贴发放政策相关条件的。"},{"no":"五","title":"工作要求","text":"(一)加强宣传推荐。市县人社部门要通过网络、报纸、电视、微信等媒体广泛开展政策宣传。各相关单位要积极推荐符合当地产业发展方向,代表先进生产力、生产方式的创新创业带动就业的先进典型。\n(二)严格审核把关。市县人社部门要严格按照文件要求,严格审核、认真把关,确保真实性。财政部门要加强资金监管,充分提高资金使用效率。\n(三)严肃工作纪律。市县人社部门要优化服务,提供便捷申报受理渠道。申报企业或个人应对申报资料的真实性负责。对有违规申报、弄虚作假、骗取套取等行为的申报企业和个人,一经核实,取消申报资格,情节严重的纳入诚信黑名单,不再享受湘潭市政府各类财政支持,并依法依规作出处理和追究相关单位和个人责任。"},{"no":"六","title":"相关说明","text":"(一)\"初创企业\"类型包括小微企业和个体工商户。\n(二)普通高校是指国家教育行政部门批准或备案的实施高等学历教育为主的高等学校,包括全日制大学、独立学院、职业技术学院、高等专科学校。按照湘教通〔2020〕66号文件精神,非全日制研究生享受与全日制研究生同等的创业扶持政策。\n(三)一次性创业补贴(含大学生一次性创业补贴)资金从各级就业补助资金中列支;创业经营场所租金补贴从各级财政配套的就业补助资金中列支。\n(四)其他未尽事宜,由市人力资源和社会保障局、市财政局负责解释。\n(五)本办法自发布之日起施行,有效期不超过3年。"}],"interpretations":[{"sectionNo":"一","headline":"首次创业满1年可申补贴，个体补3000元起、最高15000元","who":"在湘潭市范围内首次登记注册、注册时间5年以内的初创企业；正常运营1年以上并吸纳2名以上城乡劳动者就业、缴纳城镇职工社保6个月以上；法定代表人须为就业困难人员或返乡入乡农民工，持股不低于30%。申报大学生补贴的，法定代表人须为毕业2年内的高校/职业/技工院校学生或留学归国人员。","materials":[],"window":"正常运营1年以上、社保连续缴纳6个月以上（大学生为3个月）方可申报。","where":"工商注册（登记）所在地的市、县市区人力资源和社会保障局。","tip":"吸纳人数按近6个月缴纳城镇职工社会保险的人数计算；法定代表人近两年才变更为符合条件群体的，不纳入补贴范围。"},{"sectionNo":"二","headline":"大学生创业租金补贴：第一年每月800元、第二年每月600元","who":"仅限大学生群体创业：首次登记注册5年内的初创企业，正常运营1年以上、吸纳1名以上劳动者就业并缴社保3个月以上，法定代表人须为毕业2年内的高校/职业/技工院校学生或留学归国人员。","materials":["《湘潭市创业经营场所租金补贴申请表》（附件2）","营业执照或其他登记注册证明、法定代表人身份证","公司股权分配证明资料","法定代表人属于大学生群体的证明材料（毕业证等）"],"window":"自营业执照成立日期的次月起连续计算，最长2年；同一企业最多申请两次。","where":"市、县市区人力资源和社会保障局。","tip":"用自有房产创业的、以及孵化基地内免费入驻的企业，不纳入租金补贴范围；多处经营场所只能选一处申报。"},{"sectionNo":"三","headline":"创业补贴向属地人社局申报，每季度末月审核、公示5个工作日","who":"符合条件的创业主体，按工商注册(或登记机关)属地管理原则确定受理地；初创企业含小微企业和个体工商户。","materials":[],"window":"按季度受理审核，每季度末月审核；公示期5个工作日。","where":"所在的市、县市区人力资源和社会保障局；同级人力资源和社会保障局官网","tip":"公示期间有异议需经调查不成立才由同级人社局行文公布；资金拨付至申报企业账户并在“湖南人社一体化业务管理系统”录入。"},{"sectionNo":"四","headline":"初创企业停业、注销或吊销执照的，终止享受补贴","who":"已申报或已享受补贴的初创企业（小微企业和个体工商户）。","materials":[],"window":"申报审核期间及补贴享受期内核查","where":"市、县市区人力资源和社会保障局（按工商注册属地受理审核）","tip":"经核实有其他不符合补贴发放政策条件的同样终止；终止后不再享受补贴。"},{"sectionNo":"五","headline":"申报资料须真实，造假取消资格并纳入诚信黑名单","who":"申报一次性创业补贴、创业经营场所租金补贴的企业或个人。","materials":[],"window":"申报、审核、资金拨付全过程；原文未设申报截止时间","where":"市县人社部门、财政部门","tip":"违规申报、弄虚作假、骗取套取一经核实即取消申报资格，情节严重的纳入诚信黑名单，不再享受湘潭市政府各类财政支持。"},{"sectionNo":"六","headline":"初创企业含小微企业和个体工商户，非全日制研究生同等享受","who":"小微企业、个体工商户；普通高校（全日制大学、独立学院、职业技术学院、高等专科学校）；非全日制研究生（与全日制研究生同等享受创业扶持政策）。","materials":[],"window":"自发布之日起施行，有效期不超过3年","where":"市人力资源和社会保障局、市财政局","tip":"一次性创业补贴从各级就业补助资金列支，租金补贴从各级财政配套的就业补助资金列支；其他未尽事宜由市人社局、市财政局解释。"}],"sourceUrl":"http://www.xiangtan.gov.cn/jc2021/xtsjczwgk/uploadfiles/202509/2025090516413958809.pdf","sourceNote":"条文已于 2026-11-09 与官方页面/PDF 逐句比对，逐字一致（明细见 采集包/条文核对表.md）","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"p-2025-a3f757","title":"娄底市人民政府办公室关于印发《娄底市支持“三电”产业高质量发展若干措施》的通知","level":"city","region":"娄底市","issuer":"娄底市人民政府办公室","documentNo":"娄政办发〔2025〕9号","publishedAt":"2025-09-02","status":"active","tags":["场地支持","融资支持"],"audience":["小微企业"],"summary":"娄底支持“三电”（电机、变压器、家电）产业发展，建立梯度培育库，优化用地政策，加强金融服务和人才引育配套。","sections":[{"no":"一","title":"发展产业集群","text":"发展产业集群。坚持需求牵引,发挥龙头企业引领带动作用,以硅钢和“三电”产业链吸引新能源汽车、智能装备制造、工业机器人等终端应用企业。支持境内外“三电”产业链上下游企业和投融资企业通过绿地投资、股权债权投资、实物投资、无形资产投资、收购并购等方式来娄开展合作。(责任单位:市工信局、市商务局,娄星区人民政府、娄底经开区管委会、娄星产业发展中心)"},{"no":"二","title":"梯度培育优质企业","text":"梯度培育优质企业。建立“三电”企业梯度培育库,深化服务,分阶段、分目标、分类别实行梯度式培育,推动形成“三电”及其配套中小企业协同发展新格局。发展壮大龙头企业,推动龙头企业参与行业标准制定,鼓励多元化与国际化布局,提升龙头企业品牌影响力。培育创新骨干企业,加快培育一批产品层次高、市场影响力大、具备先发优势的标志性创新型骨干企业。培育高成长性中小微企业,持续开展新增规模工业企业行动,深入实施“科技小巨人”培育计划,培育一批主营业务突出、竞争力强、成长性好的高水平中小微企业。(责任单位:市工信局、市科技局,娄星区人民政府、娄底经开区管委会、娄星产业发展中心)"},{"no":"三","title":"优化用地政策","text":"优化用地政策。针对“三电”产业特点实施差异化供地策略,对快速成长且固定资产投入较少的产业项目,通过灵活设置用地年限降低企业初始投资成本,项目土地出让允许分期缴纳土地价款,自签订合同之日起1年内缴纳完毕,配套建立弹性续期机制。对上下游配套企业,采用“先租后让、租让结合”用地模式,优先保障标准化厂房供应。(责任单位:市资规局、市住建局,娄星区人民政府、娄底经开区管委会、娄星产业发展中心)"},{"no":"四","title":"加快项目筹建投产","text":"加快项目筹建投产。强化市、区两级联动,简化建设报批流程,推行并联审批模式,协助企业“零跑动”高效办理各类涉企行政审批手续。落实帮办服务制度,跟踪项目开工建设和投产达产全流程,对重大项目实行“一事一议”协调,跨部门解决企业诉求,鼓励企业“拿地即动工”“竣工即投产”。(责任单位:市发改委、市资规局,娄星区人民政府、娄底经开区管委会、娄星产业发展中心)"},{"no":"五","title":"降低企业要素成本","text":"降低企业要素成本。加强电力保障,探索“光伏+储能+微电网”集成模式,协调新能源发电企业与年用电量超500万千瓦时的“三电”企业,建立能源应急保障机制,优先保障重点项目稳定用电。加强气源保障,积极对接上游企业,多渠道筹措气源,推进LNG(液化天然气)储备站建设,加快市政燃气基础设施建设,提高应急调峰和燃气输配能力。加强环保要素保障,建设集中式污水处理、危废处理中心及公共检测实验室,对重大“三电”项目优先统筹使用市域内污染物排放总量指标,精准调剂主要污染物总量指标。优化物流网络,加快涟水复航、洛湛铁路益娄段电气化改造工程等重大项目建设,打造“制造业物流枢纽”。(责任单位:市发改委、市生态环境局、市住建局、市交通运输局、国网娄底供电公司、相关燃气公司,娄星区人民政府、娄底经开区管委会、娄星产业发展中心)"},{"no":"六","title":"支持科技创新","text":"支持科技创新。鼓励企业加大研发投入,支持企业用数智技术、绿色技术改造提升传统产业,推动企业设备更新、工艺升级及管理创新,支持租赁关键设备和生产线,实施“技术攻关+产业化应用”重大科技示范工程,加强知识产权创造、运用、保护、管理和服务。引导“三电”企业接入工业互联网平台,推荐数字化转型、智能化改造项目申报国家级、省级智能制造试点。支持各高校和科研所与企业共建高水平科技成果转化平台,促进科技成果就近就地转化应用。鼓励市级科研补贴(补助)资金向“三电”企业倾斜,鼓励市级创业基金推动“三电”科技成果转化落地,助力“三电”企业高端化、智能化、绿色化。(责任单位:市科技局、市发改委、市财政局、市工信局、市市场监管局、市创发集团,娄星区人民政府、娄底经开区管委会、娄星产业发展中心)"},{"no":"七","title":"建立供应链协同机制","text":"建立供应链协同机制。针对“三电”产业对特种钢材、铜铝等原材料的高度依赖,协调建立跨区域原材料储备联盟。通过大宗物资集采、战略储备等方式平抑价格波动,稳定供应链成本,建立原材料供需预警机制,提前做好产能调配和应急储备。建立“三电”供需对接平台,定期组织上下游企业开展采购洽谈会,推动供应链上下游企业实现协同采购、协同制造、协同物流,促进大中小企业专业化分工协作,快速响应客户需求,缩短生产周期和新品上市时间,降低生产经营和交易成本。(责任单位:市工信局、市发改委、市市场监管局,娄星区人民政府、娄底经开区管委会、娄星产业发展中心)"},{"no":"八","title":"创新金融服务","text":"创新金融服务。加强政银企对接,定期开展“行长走市县·金融送解忧”行动,适时组织“三电”产业融资对接会;完善“金融超市”平台功能,创新优化金融服务产品,积极为“三电”产业链上下游企业提供差异化融资支持。引导金融机构持续开发“三电贷”“三电担”等专属产品,探索应收账款融资、预付款融资、库存融资、订单融资等供应链融资模式,完善信贷审批流程,缩短贷款审批时限。加快推进设立创投子基金,引导娄底“材料谷”产业基金等投资“三电”企业。充分发挥商业保理、融资租赁等金融牌照作用,为“三电”企业提供银票、商票质押融资和订单保理融资等供应链金融服务。(责任单位:市政府办、市财政局、市国资委、中国人民银行娄底市分行、国家金融监督管理总局娄底监管分局、市城发集团,娄星区人民政府、娄底经开区管委会、娄星产业发展中心)"},{"no":"九","title":"强化人才引育配套","text":"强化人才引育配套。聚焦人才队伍梯次化、能力全面化、使用实战化,完善构建“引育用”全链条机制。支持企业柔性引进各类人才,鼓励有条件的企业与高校等共建高技能、跨学科复合型人才培训基地。实施“技能人才定向培养计划”,鼓励“三电”企业与高职院校合作开设“钢铁冶金”“电力电子”等专业订单班,由企业参与课程设计,毕业生直接输送至重点企业。建设园区人才公寓,按照需求提供阶梯式住房保障,对重点引进的高层次人才,提供购房补贴配套服务。建立“人才服务一卡通”制度,整合医疗、教育、交通等优质资源,提升人才归属感。(责任单位:市委组织部、市科技局、市人社局、市教育局、市财政局、市工信局,娄星区人民政府、娄底经开区管委会、娄星产业发展中心)"},{"no":"十","title":"强化政企沟通与执法监督","text":"强化政企沟通与执法监督。为“三电”产业相关企业配备营商环境联企服务专员,纳入营商环境监测。各级营商环境部门、司法行政部门发现破坏营商环境的问题线索,经交办、督办,内部纠偏效果不好的,依法依规依纪移送纪检监察机关核查处理。(责任单位:市纪委监委、市营商环境办、市司法局、各行政执法部门)\n十"},{"no":"十一","title":"建立推动落实工作机制","text":"建立推动落实工作机制。市“三电”产业工作专班定期调度工作进展情况,对相关责任单位政策落实情况进行调研,跟踪评估政策实施效果。相关部门严格按照职责分工,推进政策落实落地。(责任单位:市工信局,娄星区人民政府、娄底经开区管委会)\n本政策适用对象为入驻娄星区、娄底经开区(含娄星产业园)的“三电”终端成品或主要零配件生产企业。其他县(市)可以参照执行。本政策自公布之日起施行,有效期5年。"}],"interpretations":[{"sectionNo":"八","headline":"「三电」企业有专属贷款产品，还能做订单、库存融资","who":"娄底「三电」产业链上下游企业。","materials":[],"window":"按各银行产品与融资对接会安排。","where":"市政府办、市财政局、市国资委、人民银行娄底市分行、金融监管总局娄底监管分局及「金融超市」平台。","tip":"可用工具包括「三电贷」「三电担」专属产品、应收账款/预付款/库存/订单融资、商业保理与融资租赁；还有创投子基金和「材料谷」产业基金可投。"},{"sectionNo":"二","headline":"「三电」企业进梯度培育库，分三类扶持","who":"娄底「三电」及配套中小企业：龙头企业、创新骨干企业、高成长性中小微企业三类。","materials":[],"window":"按年度培育计划。","where":"市工信局、市科技局及娄星区、娄底经开区。","tip":"培育路径是「新增规模工业企业行动」和「科技小巨人」培育计划，先进库再谈扶持。"},{"sectionNo":"一","headline":"境内外“三电”产业链企业可通过投资、并购等方式来娄合作","who":"境内外“三电”产业链上下游企业和投融资企业；新能源汽车、智能装备制造、工业机器人等终端应用企业。","materials":[],"window":"常态化开展，原文未设申报截止时间","where":"市工信局、市商务局；娄星区人民政府、娄底经开区管委会、娄星产业发展中心","tip":"支持方式含绿地投资、股权债权投资、实物投资、无形资产投资、收购并购；以龙头企业和硅钢、“三电”产业链吸引终端应用企业。"},{"sectionNo":"三","headline":"工业用地可分期缴款，签约起1年内缴完，可先租后让","who":"“三电”产业项目，尤其是快速成长且固定资产投入较少的产业项目；上下游配套企业。","materials":[],"window":"土地出让价款自签订合同之日起1年内缴纳完毕；配套建立弹性续期机制。","where":"市资规局、市住建局；娄星区人民政府、娄底经开区管委会、娄星产业发展中心","tip":"上下游配套企业可采用“先租后让、租让结合”用地模式并优先保障标准化厂房；通过灵活设置用地年限降低企业初始投资成本。"},{"sectionNo":"四","headline":"项目审批并联办理，帮办服务全程跟踪，可“拿地即动工”","who":"在娄星区、娄底经开区（含娄星产业园）投资建设的“三电”产业项目企业。","materials":[],"window":"项目筹建、开工、投产全流程跟踪；原文未设申报截止时间","where":"市发改委、市资规局；娄星区人民政府、娄底经开区管委会、娄星产业发展中心","tip":"重大项目实行“一事一议”协调、跨部门解决企业诉求；鼓励企业“拿地即动工”“竣工即投产”。"},{"sectionNo":"五","headline":"年用电量超500万千瓦时的“三电”企业优先保障用电","who":"年用电量超500万千瓦时的“三电”企业；重大“三电”项目；需集中式污水处理、危废处理等要素保障的园区企业。","materials":[],"window":"常态化保障，原文未设申报截止时间","where":"市发改委、市生态环境局、市住建局、市交通运输局、国网娄底供电公司、相关燃气公司","tip":"重大“三电”项目优先统筹使用市域内污染物排放总量指标；探索“光伏+储能+微电网”集成模式并建立能源应急保障机制。"},{"sectionNo":"六","headline":"支持设备更新、技术攻关，推荐申报国家级省级智能制造试点","who":"“三电”企业；与高校、科研院所共建科技成果转化平台的主体；接入工业互联网平台的企业。","materials":[],"window":"常态化支持，原文未设申报截止时间","where":"市科技局、市发改委、市财政局、市工信局、市市场监管局、市创发集团","tip":"市级科研补贴（补助）资金向“三电”企业倾斜；市级创业基金推动“三电”科技成果转化落地。"},{"sectionNo":"七","headline":"建原材料储备联盟和供需对接平台，平抑价格波动","who":"“三电”产业链上下游企业，尤其是依赖特种钢材、铜铝等原材料的企业。","materials":[],"window":"定期组织上下游企业采购洽谈会；原文未设申报截止时间","where":"市工信局、市发改委、市市场监管局","tip":"通过大宗物资集采、战略储备平抑价格波动，并建立原材料供需预警机制、提前做好产能调配和应急储备。"},{"sectionNo":"九","headline":"支持柔性引才、办订单班，建人才公寓和购房补贴配套","who":"“三电”企业及其引进的各类人才；与高职院校合作开设订单班的“三电”企业及毕业生；重点引进的高层次人才。","materials":[],"window":"常态化实施，原文未设申报截止时间","where":"市委组织部、市科技局、市人社局、市教育局、市财政局、市工信局","tip":"高层次人才可享购房补贴配套服务；建立“人才服务一卡通”，整合医疗、教育、交通等资源。"},{"sectionNo":"十","headline":"“三电”企业配备营商环境联企服务专员并纳入监测","who":"“三电”产业相关企业。","materials":[],"window":"常态化，原文未设申报截止时间","where":"市纪委监委、市营商环境办、市司法局、各行政执法部门","tip":"破坏营商环境的问题线索经交办、督办后内部纠偏不力的，依法依规依纪移送纪检监察机关核查处理。"},{"sectionNo":"十一","headline":"政策适用于娄星区、娄底经开区“三电”生产企业，有效期5年","who":"入驻娄星区、娄底经开区（含娄星产业园）的“三电”终端成品或主要零配件生产企业；其他县（市）可参照执行。","materials":[],"window":"自公布之日起施行，有效期5年","where":"市“三电”产业工作专班；市工信局","tip":"其他县（市）参照执行；工作专班定期调度并跟踪评估政策实施效果。"}],"sourceUrl":"https://www.hunan.gov.cn/zqt/zcsd/202509/t20250924_33813505.html","sourceNote":"条文已于 2026-11-09 与官方页面/PDF 逐句比对，逐字一致（明细见 采集包/条文核对表.md）","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"p-2025-ab4238","title":"益阳市人民政府办公室关于印发《益阳市支持大学生创业十二条措施》的通知","level":"city","region":"益阳市","issuer":"益阳市人民政府办公室","documentNo":"益政办发〔2025〕10号","publishedAt":"2025-07-30","status":"active","tags":["创业补贴","贷款贴息","场地支持"],"audience":["小微企业","个体工商户","高校毕业生"],"summary":"为大学生创业提供个人最高30万元、合伙创业或小微企业最高400万元的创业担保贷款并按实际利率给予50%贴息，对首次创办小微企业或从事个体经济且正常运营1年以上的在校大学生或离校2年内高校毕业生最高给予1万元一次性创业补贴，自2025年8月1日起施行，有效期至2029年7月31日。","sections":[{"no":"一","title":"帮扶创业主体，完善政策支持","text":"帮扶创业主体，完善政策支持\n（一）提供创业担保贷款贴息及专属信贷支持。为大学生创业提供贷款支持，个人创业最高可贷30万元，合伙创业或小微企业最高可贷400万元，财政部门按实际利率给予50%贴息。同时推出支持青年创业者、青年领办企业及新市民的专属信贷产品，建立“白名单”推送机制。（责任单位：市人力资源社会保障局、市财政局、团市委、人民银行益阳市分行、益阳金融监管分局按职责分工负责）\n\n（二）给予一次性创业补贴支持。对首次创办小微企业或从事个体经济，且所创办企业或个体工商户自工商登记注册之日起正常运营1年以上的在校大学生或离校2年内高校毕业生，根据实际投入、带动就业人数，最高给予1万元的一次性创业补贴。（责任单位：市人力资源社会保障局、市财政局按职责分工负责）\n\n（三）支持创建大学生创业孵化载体。开展大学生创业孵化基地认定工作，对首次认定的益阳市市级大学生创业孵化基地，给予5万元/家的一次性培育奖补，对已认定的益阳市市级大学生创业孵化基地，参照《关于深入推进创业孵化基地建设工作的通知》（湘人社规〔2023〕5号），根据创业孵化成效给予每年最高不超过40万元的创业服务补助。（责任单位：市人力资源社会保障局、市财政局、市科技局、市教育局按职责分工负责）\n\n（四）给予减税降费支持。高校毕业生在毕业年度内从事个体经营，符合规定条件的，在3年内按一定限额依次扣减其当年实际应缴纳的增值税、城市维护建设税、教育费附加、地方教育附加和个人所得税；对销售额在免税标准以下的小规模纳税人免征阶段性增值税，对小微企业和个体工商户按规定减免所得税。对国家级、省级科技企业孵化器和大学科技园以及国家备案众创空间按规定免征增值税、房产税、城镇土地使用税。（责任单位：市税务局）\n\n（五）加大人才政策倾斜。将市大学生创业典型纳入市级人才计划。在益阳市银城青年人才项目创业类中，针对大学生创业者开设单独赛道，按程序将市大学生创业典型纳入市级人才计划名单，享受相应人才政策。（责任单位：市委组织部、团市委按职责分工负责）"},{"no":"二","title":"深化创业培训，增强创业能力","text":"深化创业培训，增强创业能力\n（六）加强创业导师队伍建设与指导服务。重点打造一支由10名核心实战型导师和120名专业导师组成的市级创业导师团队，构建覆盖高等教育、企业管理、法律咨询、金融财务等多领域的综合性导师体系，实现创新创业导师资源的共建共享。结合“益起来创业”系列创业服务活动，组织开展导师进基地、进校园活动，为大学生创业项目提供专业化、多元化、精细化的创业指导；并对有需要、有潜力的创业项目，安排创业导师开展结对帮扶。（责任单位：市科技局、市教育局、市人力资源社会保障局、团市委按职责分工负责）\n\n（七）开展创业课程定制培训。完善创业培训课程体系，针对不同创业阶段、创业类型、创业需求的大学生，提供定制化GYB、SYB、IYB、网络创业、创业模拟实训等课程培训，按规定给予创业培训补贴，提升大学生创业能力。（责任单位：市人力资源社会保障局、市教育局按职责分工负责）\n\n（八）支持大学生在涉农领域创业就业。市农村产权交易中心设立专项服务窗口，为大学生创业提供土地流转、技术指导等政策咨询服务。组织有返乡下乡创业意向大学生参与高素质农民培训，将返乡创业大学生纳入产业发展带头人重点培育对象，开展农村创业项目专题培训。（责任单位：市农业农村局）"},{"no":"三","title":"拓展孵化空间，助力创业成长","text":"拓展孵化空间，助力创业成长\n（九）给予大学生创业场地支持服务。大学生创业孵化基地免费提供不低于孵化面积30%的场地给大学生和毕业5年内（含）高校毕业生创业项目，并给予入驻项目场地租金首年全额补贴，次年补贴50%。支持优秀大学生落户中南科创园、龙山港、华盛创业园以及监管企业管理的商铺创业，为其提供必要的管理服务，并予以一定的租金优惠。（责任单位：市人力资源社会保障局、市财政局、市科技局、市教育局、市国资委、益阳高新区管委会按职责分工负责）\n\n（十）给予大学生创业者保障性租赁住房优惠。面向符合条件的大学生创业者供应保障性租赁住房，面积扩大到120平方米以内，租金不高于同地段同品质市场租赁住房租金的80%，实行动态管理。（责任单位：市住房城乡建设局）\n\n（十一）设立市、县两级“大学生创业一站式服务中心”，推行“零打扰”监管和“零跑腿”审批服务模式。推行“不上一次门”制度，对新设立且无投诉举报、无安全隐患的大学生创业企业，实行“首年免检”政策，并实施“轻微免罚”“首违不罚”等柔性执法措施。推进“高效办成一件事”改革，确保“个人创业一件事”落地实施，实现全流程办理。为大学生创业企业提供最大程度的“无事不扰”和“有需必应”的服务环境。（责任单位：市发展改革委、市科技局、市人力资源社会保障局、市市场监管局、团市委、市税务局，各县市区人民政府按职责分工负责）"},{"no":"四","title":"弘扬创业精神，营造社会氛围","text":"弘扬创业精神，营造社会氛围\n（十二）打造“‘益’起创青春”宣传品牌，构建全方位创新创业生态。举办“青年夜校·创新创业专场”“益阳市青年创新创业大讲堂”“‘益’起创青春 携手向未来”益阳政企青年解难题促发展主题沙龙等活动，搭建政企对话平台，弘扬新时代创新创业精神，持续激发高校学子创新潜能。同步构建媒体宣传矩阵，开设《正青春 好创业》政策解读专栏和《青春“益”起创》典型宣传栏目，形成“活动赋能+媒体发声”的全方位宣介创业工作，立体化展示青年创业典型，多维度推广基层创新经验，在全社会营造尊重创业、支持创新的良好氛围。（责任单位：市委宣传部、团市委、益阳日报社、市广播电视台按职责分工负责）\n\n大学生创业主体须依法经营并履行社会责任，在享受同类政策时，遵循“奖补不重复”原则。本文件自2025年8月1日起施行，有效期至2029年7月31日。在文件有效期内，如遇法律法规或有关政策调整变化的，从其规定。"}],"interpretations":[{"sectionNo":"一","headline":"大学生创业最高贷30万元、合伙或小微企业最高400万元，贴息50%","who":"在益阳创业的大学生（含在校大学生、离校2年内高校毕业生）；合伙创业或小微企业可提高额度。","materials":[],"window":"按创业担保贷款经办流程办理。","where":"市人力资源和社会保障局、市财政局、人民银行益阳市分行等按职责分工办理。","tip":"财政按实际利率给予50%贴息；另有面向青年创业者、青年领办企业及新市民的专属信贷产品和「白名单」推送机制。"},{"sectionNo":"一","headline":"大学生首次创业满1年，一次性补贴最高1万元","who":"首次创办小微企业或从事个体经济，且自工商登记注册之日起正常运营1年以上的在校大学生或离校2年内高校毕业生。","materials":[],"window":"自工商登记注册之日起正常运营1年以上。","where":"市人力资源和社会保障局、市财政局按职责分工办理。","tip":"补贴金额按实际投入和带动就业人数核定，最高1万元，不是人人1万元。"},{"sectionNo":"二","headline":"大学生创业可参加定制培训，按规定领创业培训补贴","who":"有创业意愿、处于不同创业阶段的大学生；在益阳创业的大学生（含涉农领域）；有返乡下乡创业意向的大学生；高校及社会力量建立的“创业指导工作室”、创业服务协会等社会组织。","materials":[],"window":"按“益起来创业”系列活动和培训开班组织，原文未设申报截止时间","where":"市人力资源社会保障局、市教育局、市科技局、团市委（按职责分工）；市农村产权交易中心专项服务窗口","tip":"创业培训补贴按GYB、SYB、IYB、网络创业、创业模拟实训等课程规定给予；涉农创业可到市农村产权交易中心专项窗口咨询土地流转、技术指导。"},{"sectionNo":"三","headline":"孵化基地30%场地免费，入驻首年租金全补、次年补50%","who":"大学生和毕业5年内（含）高校毕业生创业项目；入驻大学生创业孵化基地的项目；落户中南科创园、龙山港、华盛创业园及监管企业商铺的优秀大学生；符合条件的大学生创业者（保障性租赁住房）。","materials":[],"window":"场地租金首年全额补贴、次年补贴50%，保障性租赁住房实行动态管理","where":"大学生创业孵化基地；中南科创园、龙山港、华盛创业园；市人力资源社会保障局、市住房城乡建设局等按职责分工","tip":"孵化基地免费提供不低于孵化面积30%的场地；保障性租赁住房面积120平方米以内、租金不高于市场价80%；新设大学生创业企业首年免检。"},{"sectionNo":"四","headline":"同类政策奖补不重复，有效期至2029年7月31日","who":"在益阳创业的大学生创业主体（享受同类政策者）；参与“益”起创青春系列活动的高校学子、青年创业者。","materials":[],"window":"自2025年8月1日起施行，有效期至2029年7月31日；有效期内法律法规或政策调整的从其规定","where":"市委宣传部、团市委、益阳日报社、市广播电视台（按职责分工）","tip":"享受同类政策遵循“奖补不重复”原则；创业主体须依法经营并履行社会责任。"}],"sourceUrl":"https://www.hunan.gov.cn/zqt/zcsd/202509/t20250924_33813484.html","sourceNote":"条文已于 2026-11-09 与官方页面/PDF 逐句比对，逐字一致（明细见 采集包/条文核对表.md）；2026-11-08 核对：页面发布日期 2025-09-24","verified":true,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"p-2025-c1c73c","title":"湖南省人力资源和社会保障厅 湖南省财政厅关于印发《湖南省创业培训管理办法》的通知","level":"provincial","region":"湖南省","issuer":"湖南省人力资源和社会保障厅、湖南省财政厅","documentNo":"湘人社规〔2025〕15号","publishedAt":"2025-07-25","status":"active","tags":["创业补贴","就业补贴"],"audience":["小微企业","高校毕业生"],"summary":"GYB培训补900元/人次、SYB培训补1400元/人次，由培训机构先垫后补，证书发放3个月内代为申领。","sections":[{"no":"一","title":"第一条","text":"为贯彻落实省委、省政府关于推动大学生创新创业决策部署，优化创业培训管理，提升创业培训质量。根据《人力资源社会保障部等7部门关于健全创业支持体系提升创业质量的意见》(人社部发〔2025〕5号)、《人力资源社会保障部关于实施职业技能提升行动创业培训“马兰花计划”的通知》（人社部函〔2020〕109号）、《中国就业培训技术指导中心关于印发<马兰花创业培训项目组织实施规程>等技术文件的通知》（中就培函〔2025〕62号）、《湖南省人民政府办公厅关于印发〈湖南省大力支持大学生创业若干政策措施〉的通知》（湘政办发〔2024〕42号）和《湖南省财政厅 湖南省人力资源和社会保障厅关于印发〈湖南省就业补助资金管理办法〉的通知》（湘财社〔2024〕33号）等有关文件制定本办法。"},{"no":"二","title":"第二条","text":"本办法所指创业培训包括GYB（产生你的企业想法）、SYB（创办你的企业）、IYB（改善你的企业）、EYB（扩大你的企业）、网络创业培训（电商、直播）、创业模拟实训和乡村领雁创业培训，以及经省级创业培训主管部门开展试点或认定的培训课程。"},{"no":"三","title":"第三条","text":"对以下人员可以给予创业培训补贴：防止返贫监测对象、毕业年度高校毕业生（含技工院校高级工班、预备技师班、技师班和特殊教育院校职业教育类毕业生）、城乡未继续升学的应届初高中毕业生、农村转移就业劳动者、城镇登记失业人员、就业困难人员，以及大中专院校在校学生（含中职、技校）、离校2年内未就业高校毕业生、登记自主创业人员、有创业意愿的企业单位职工。\n第二章机构和师资管理"},{"no":"四","title":"开展创业培训的机构应符合以下条件：","text":"开展创业培训的机构应符合以下条件：\n（一）具有独立法人资格的职业培训机构、就业创业培训（实训）中心、创业孵化基地、创业指导师工作室和各类院校、众创空间等实体，可申请开展创业培训；\n（二）申请开展培训的课程，至少与3名以上对应课程的创业培训授课讲师签订不低于2年的授课协议；\n（三）有2名以上专职管理人员负责创业培训及后续服务的组织工作；\n（四）与2名以上创业创新导师团成员签订不低于1年的服务协议；\n（五）开展创业培训的机构，应配置2间创业培训理论教学专用教室（单间面积≥60㎡）及1间创业培训实操教学专用教室（面积≥120㎡），并配备不少于40台电脑，配有不低于100M高速宽带接入，且须具备教师休息室、档案室、工作人员办公室等基本办公场地；\n（六）已安装远程移动视频监控系统，能实现培训过程的实时监控并记录；\n（七）教学管理、学员管理、财务及安全管理等制度健全，近年来未发生社会不良影响事件；\n（八）能按时按质完成创业培训主管部门下达的培训任务，并使用省厅确定的教学辅助平台。"},{"no":"五","title":"第五条","text":"各市州人力资源社会保障部门按照公开规范、保障质量、提升效益的原则，从符合条件的单位中择优确定承接创业培训课程的培训机构，或者通过政府采购招标方式确定培训定点机构。"},{"no":"六","title":"第六条","text":"培训机构原则上每3年认定一次，报省创业培训主管部门备案后，录入省人社一体化业务管理系统（以下简称“省平台”），并实时更新培训机构信息，进行动态管理。"},{"no":"七","title":"第七条","text":"对新开展的创业培训课程，各市州人力资源社会保障部门根据培训需求，可组织专家评审，从已认定的创业培训机构中，择优选择机构实施，并报省创业培训主管部门备案。"},{"no":"八","title":"第八条","text":"各级创业培训主管部门要定期对创业培训机构开展考核评价，对存在以下情形之一的，创业培训主管部门可视情节给予限期整改、暂停培训、取消培训资格等处分，并将处分情况记录至省平台。\n（一）对创业培训机构丧失培训资质和办学许可、自动放弃创业培训定点机构服务资格及其他原因导致无法正常开展创业培训的；\n（二）未认真履行培训机构职责，逃避检查，拒不接受主管部门监管核查的；\n（三）未按规定执行培训技术标准或不接受省平台师资派遣、培训质量低、绩效评价差的；\n（四）出借、出租办学资质，违规颁发培训合格证书，将培训项目转包或委托给其他单位或个人的；\n（五）发布虚假招生简章或者广告，弄虚作假，套取骗取补贴资金的；\n（六）未按照开班备案信息开展培训或连续两年未正常开展创业培训工作的；\n（七）各级审计、巡视巡察、纪检监察、信访举报、资金绩效评价发现有重大问题的；\n（八）管理混乱、违规收费、有举报投诉，造成重大社会不良影响的；\n（九）法律法规禁止的其他情形。\n自取消创业培训定点机构服务资格之日起，该单位3年内不得参与创业培训业务。涉嫌违法犯罪的，依法移送有关机关处理。"},{"no":"九","title":"创业培训师资管理按照我省有关规定执行","text":"创业培训师资管理按照我省有关规定执行。\n第三章 组织实施"},{"no":"十","title":"第十条","text":"创业培训课程应按照人社部中国就业培训技术指导中心或省创业培训主管部门确定的技术标准开展培训。"},{"no":"十一","title":"第十一条","text":"培训机构在筹备开班前，应通过省平台发布拟开班信息，接受网上报名和现场报名。GYB培训在招募学员时，应重点面向院校学生和青年群体，可整建制开展培训。其他培训课程招募学员时，应筛选有创业愿望和培训需求的对象开展培训。"},{"no":"十二","title":"第十二条","text":"培训机构在正式开班前，应提前3个工作日通过省平台向当地创业培训主管部门提交《创业培训开班申请表》（附件1）、学员登记表和课程安排表。创业培训主管部门应在3个工作日内在省平台完成备案。"},{"no":"十三","title":"GYB课程每班不超过40人","text":"GYB课程每班不超过40人；SYB、IYB、网络创业培训课程每班不超过30人；EYB课程每班不超过25人；创业模拟实训和乡村领雁创业培训课程每班不超过35人。培训机构应每班安排1名工作人员担任班主任。"},{"no":"十四","title":"GYB课程原则上安排24课时","text":"GYB课程原则上安排24课时；SYB、IYB、网络创业培训、创业模拟实训和乡村领雁创业培训课程原则上安排56课时；EYB培训原则上安排48课时；每课时45分钟，每日最多可上8个课时。"},{"no":"十五","title":"第十五条","text":"课程实施中需使用的教学辅助平台由省创业培训主管部门按照对应课程技术标准和培训需求组织专家评审择优确定。"},{"no":"十六","title":"第十六条","text":"学员完成培训并经考核合格后，由创业培训主管部门颁发《创业培训合格证书》，具体按照省人力资源社会保障厅印发的《关于启用创业培训电子证书的通知》（湘人社函〔2022〕137号）执行。"},{"no":"十七","title":"第十七条","text":"有后续服务需求的学员可在创业培训结课时按照《创业培训后续服务需求清单》（附件2），通过省平台提交后续服务申请。培训机构可组织签约导师或创业指导师工作室为学员提供后续服务。"},{"no":"十八","title":"第十八条","text":"培训机构应如实记录学员考勤信息，培训过程影像资料和后续服务情况等档案材料，留存备查，保存期限不少于3年。\n第四章 补贴资金的申领和拨付"},{"no":"十九","title":"第十九条","text":"细化创业培训补贴计算方式，按照“钱随事走”的原则，将创业培训补贴分为课程培训补贴和后续服务补贴两个阶段，避免培训机构“一培了之”，所需资金从就业补助资金中列支。具体补贴标准如下：\n（一）课程培训补贴。GYB课程900元/人次（其中600元支付机构，300元用于教学辅助平台系统的使用、维护）；SYB课程1400元/人次；IYB课程1600元/人次；网络创业培训、创业模拟实训和乡村领雁创业培训1700元/人次（其中1400元支付机构，300元用于教学辅助平台系统的使用、维护）；EYB培训费用由个人和财政共同承担，补贴标准由各地自行确定。\n（二）后续服务补贴。培训机构按创业学员需求组织开展后续服务的，经服务后学员3个月内成为新增或现有市场主体的法定代表人或股东等人员的，按800元/人的标准给予培训机构补贴。培训机构可根据后续服务成效支付签约导师或创业指导师工作室相应比例的服务费。GYB不纳入后续服务补贴范围。"},{"no":"二十","title":"第二十条","text":"创业培训补贴实行“先垫后补”，由培训机构先行垫付培训费用，证书发放3个月内向当地创业培训主管部门代为申领创业培训补贴。申请时应当提交以下资料：\n1.创业培训补贴申请表（附件3）；\n2.创业培训补贴人员名册（附件4）；\n3.培训补贴代为申请协议（附件5）；\n4.缴纳培训费用凭证：培训定点机构开具的收费凭证、票据或税务发票原件；\n5.培训学员的身份类别证明材料，按照《人员类别证明材料》（附件6）的要求提供；\n6.工商营业执照，以及学员为该市场主体法定代表人或股东等人员的佐证资料，通过省平台数据协同的可不提供。\n同一班期创业培训补贴可将课程培训补贴和后续服务补贴分开提交申请，也可合并提交申请。"},{"no":"二十一","title":"培训机构应及时申请创业培训补贴","text":"培训机构应及时申请创业培训补贴。各级人力资源社会保障部门接到补贴申请后，应在15个工作日内完成审核工作。审核通过后，在当地人力资源社会保障网或政府公共服务网上公示，公示期为5天。公示期满无异议的，各地按照现行部门职责分工，人力资源社会保障部门或财政部门在接到申报补贴资料2个月内将补贴资金拨付到培训机构在银行开立的基本账户，同时由人力资源社会保障部门将资金拨付情况按规定录入省平台。"},{"no":"二十二","title":"第二十二条","text":"符合条件的补贴对象，同类别创业培训课程每人只可享受一次补贴。自2024年1月1日起，每人累计最多享受3次（与职业技能培训补贴合并计算）。\n第五章 监督管理"},{"no":"二十三","title":"第二十三条","text":"省就业服务中心负责组织制定全省创业培训工作规划、拟定年度指导性计划，持续完善创业培训信息系统，不断优化教学管理、师资管理、培训监管等制度，指导市州组织开展创业培训。各级创业培训主管部门负责具体组织实施及培训机构监管、师资监管、培训监管等工作。各级财政部门负责补贴资金的筹措，及时拨付补贴资金。"},{"no":"二十四","title":"第二十四条","text":"各级人力资源社会保障部门要依托省平台开展创业培训各项业务，落实“凡补必进，不进不补”工作要求。要定期组织创业培训业务培训，防范经办风险。要指导培训机构对学员定期回访，及时了解其创业就业情况，提升创业培训补贴资金绩效。"},{"no":"二十五","title":"第二十五条","text":"各级人力资源社会保障部门、财政部门应加强创业培训补贴资金使用监管，加大补贴资金核查力度。各级人力资源社会保障部门要加大日常巡查、定期检查和临时抽查力度，对于弄虚作假、骗取、套取补贴资金的单位和个人，依法追究其法律责任。\n第六章 附则"},{"no":"二十六","title":"本办法自2025年7月25日起施行，有效期5年","text":"本办法自2025年7月25日起施行，有效期5年。有效期内国家出台的新规定与本办法不一致的，以国家新规定为准。此前有关政策文件关于创业培训管理的规定与本办法不一致的，以本办法为准。\n附件：1.创业培训开班申请表\n2.创业培训后续服务需求清单\n3.创业培训补贴申请表\n4.创业培训补贴人员名册\n5.创业培训补贴代为申请协议（模板）\n6.人员类别证明材料"}],"interpretations":[{"sectionNo":"十九","headline":"GYB补900元、SYB补1400元，后续服务再补800元/人","who":"参加创业培训并取得合格证书的十类人员：防止返贫监测对象、毕业年度高校毕业生、城乡未继续升学的应届初高中毕业生、农村转移就业劳动者、城镇登记失业人员、就业困难人员，以及大中专院校在校学生、离校2年内未就业高校毕业生、登记自主创业人员、有创业意愿的企业单位职工。","materials":[],"window":"证书发放3个月内由培训机构代为申领。","where":"当地创业培训主管部门（人社部门），通过省人社一体化业务管理系统办理。","tip":"同类别课程每人只可享受一次，自2024年1月1日起累计最多3次（与职业技能培训补贴合并计算）；GYB不纳入后续服务补贴。"},{"sectionNo":"二十","headline":"学员先免费学，机构垫钱、发证后3个月内代为申领补贴","who":"承接创业培训的定点培训机构代学员申领；学员本人不用自己跑补贴流程。","materials":["创业培训补贴申请表（附件3）","创业培训补贴人员名册（附件4）","培训补贴代为申请协议（附件5）","缴纳培训费用凭证（收费凭证、票据或税务发票原件）","学员身份类别证明材料（附件6）","工商营业执照及学员为法定代表人或股东的佐证资料"],"window":"证书发放3个月内申领；人社部门15个工作日内完成审核，公示5天，2个月内拨付资金。","where":"当地创业培训主管部门","tip":"通过省平台数据协同能查到的营业执照等材料，可以不再提供。"},{"sectionNo":"二","headline":"创业培训含GYB、SYB、IYB、EYB及网络创业培训等课程","who":"有创业培训需求、参加上述课程的劳动者；开展GYB、SYB、IYB、EYB、网络创业培训（电商、直播）、创业模拟实训和乡村领雁创业培训的机构。","materials":[],"window":"按各课程技术标准组织实施，原文未设申报截止时间","where":"省级创业培训主管部门（负责试点或认定培训课程）","tip":"网络创业培训含电商、直播两个方向；经省级创业培训主管部门开展试点或认定的培训课程同样计入创业培训范围。"},{"sectionNo":"三","headline":"防止返贫监测对象、高校毕业生等人员可享创业培训补贴","who":"防止返贫监测对象、毕业年度高校毕业生（含技工院校高级工班、预备技师班、技师班和特殊教育院校职业教育类毕业生）、城乡未继续升学的应届初高中毕业生、农村转移就业劳动者、城镇登记失业人员、就业困难人员，以及大中专院校在校学生（含中职、技校）、离校2年内未就业高校毕业生、登记自主创业人员、有创业意愿的企业单位职工。","materials":[],"window":"按培训开班组织，原文未设申报截止时间","where":"原文未列具体受理部门或系统","tip":"毕业年度高校毕业生含技工院校高级工班、预备技师班、技师班和特殊教育院校职业教育类毕业生；离校2年内未就业高校毕业生同样在补贴范围内。"},{"sectionNo":"四","headline":"办创业培训需2间≥60㎡理论教室、1间≥120㎡实操教室","who":"具有独立法人资格的职业培训机构、就业创业培训（实训）中心、创业孵化基地、创业指导师工作室和各类院校、众创空间等实体；须至少与3名以上对应课程讲师签订不低于2年授课协议、有2名以上专职管理人员、与2名以上创业创新导师团成员签订不低于1年服务协议，并具备规定教室、电脑、宽带与办公场地。","materials":[],"window":"按机构认定批次申请，原文未设申报截止时间","where":"省厅确定的教学辅助平台（申报受理窗口原文未列）","tip":"教室须为专用：理论教室2间且单间面积≥60㎡、实操教室1间且面积≥120㎡，电脑不少于40台、宽带不低于100M；还须已安装远程移动视频监控系统并能实时记录培训过程。"},{"sectionNo":"五","headline":"市州人社部门择优或政府采购确定创业培训定点机构","who":"符合条件的职业培训机构、就业创业培训（实训）中心、创业孵化基地、创业指导师工作室、各类院校、众创空间等实体。","materials":[],"window":"按市州组织认定或招标批次开展，原文未设申报截止时间","where":"各市州人力资源社会保障部门","tip":"有两条路径：从符合条件的单位中择优确定，或通过政府采购招标方式确定培训定点机构；均须遵循公开规范、保障质量、提升效益原则。"},{"sectionNo":"六","headline":"培训机构原则上每3年认定一次，实行省平台动态管理","who":"已认定的创业培训机构；申请承接创业培训课程的培训机构。","materials":[],"window":"原则上每3年认定一次；认定后报省创业培训主管部门备案并实时更新机构信息。","where":"省人社一体化业务管理系统（省平台）；省创业培训主管部门","tip":"认定结果须报省创业培训主管部门备案后才录入省平台；机构信息需实时更新，实行动态管理。"},{"sectionNo":"七","headline":"新课程可由市州组织专家评审，从已认定机构中择优","who":"已认定的创业培训机构（承接新开展的创业培训课程）。","materials":[],"window":"按新课程开设需求组织，原文未设申报截止时间","where":"各市州人力资源社会保障部门；省创业培训主管部门（备案）","tip":"新开展课程须经专家评审择优选择实施机构，并报省创业培训主管部门备案。"},{"sectionNo":"八","headline":"九类情形可被限期整改、暂停或取消培训资格，3年内禁入","who":"各级创业培训机构（含创业培训定点机构）。","materials":[],"window":"各级创业培训主管部门定期考核评价；自取消定点机构服务资格之日起3年内不得参与创业培训业务。","where":"各级创业培训主管部门；省平台","tip":"出借出租办学资质、违规颁发合格证书、转包培训项目、发布虚假招生简章、套取骗取补贴、连续两年未正常开展培训等均在处分情形内；涉嫌犯罪移送有关机关。"},{"sectionNo":"十","headline":"创业培训课程按部中心或省主管部门确定的技术标准开展","who":"开展创业培训课程的培训机构。","materials":[],"window":"按课程技术标准执行，原文未设申报截止时间","where":"人社部中国就业培训技术指导中心；省创业培训主管部门","tip":"技术标准以人社部中国就业培训技术指导中心或省创业培训主管部门确定的版本为准，培训机构不得自行降低标准。"},{"sectionNo":"十一","headline":"开班前须在省平台发布拟开班信息，接受网上和现场报名","who":"创业培训机构；GYB课程重点面向院校学生和青年群体；其他培训课程面向有创业愿望和培训需求的对象。","materials":[],"window":"筹备开班前发布拟开班信息；原文未设申报截止时间","where":"省平台","tip":"GYB培训可整建制开展；其他课程招募学员时应筛选有创业愿望和培训需求的对象。"},{"sectionNo":"十二","headline":"开班前3个工作日提交开班申请表等，3个工作日内完成备案","who":"创业培训机构。","materials":["《创业培训开班申请表》（附件1）","学员登记表","课程安排表"],"window":"正式开班前提前3个工作日提交；创业培训主管部门3个工作日内在省平台完成备案。","where":"省平台；当地创业培训主管部门","tip":"材料须通过省平台提交，备案时限为3个工作日，未完成备案将影响开班。"},{"sectionNo":"十三","headline":"GYB每班不超40人，SYB、IYB、网络创业培训不超30人","who":"各类创业培训课程的培训机构及参训学员。","materials":[],"window":"按班次组织，原文未设申报截止时间","where":"原文未列具体受理部门或系统","tip":"EYB每班不超过25人，创业模拟实训和乡村领雁创业培训每班不超过35人；培训机构应每班安排1名工作人员担任班主任。"},{"sectionNo":"十四","headline":"GYB原则24课时，SYB等56课时，EYB48课时，每课时45分钟","who":"参加各类创业培训课程的学员及培训机构。","materials":[],"window":"按课程课时安排执行；每日最多可上8个课时","where":"原文未列具体受理部门或系统","tip":"每课时45分钟；创业模拟实训、乡村领雁创业培训与SYB、IYB、网络创业培训同为56课时。"},{"sectionNo":"十六","headline":"考核合格后颁发《创业培训合格证书》，使用电子证书","who":"完成创业培训并经考核合格的学员。","materials":[],"window":"完成培训并考核合格后颁发；按湘人社函〔2022〕137号执行","where":"创业培训主管部门；省人力资源社会保障厅","tip":"证书按《关于启用创业培训电子证书的通知》（湘人社函〔2022〕137号）执行，为电子证书。"},{"sectionNo":"十七","headline":"结课时可提交后续服务需求清单，申请创业后续服务","who":"有后续服务需求的学员；组织后续服务的培训机构、签约导师、创业指导师工作室。","materials":["《创业培训后续服务需求清单》（附件2）"],"window":"创业培训结课时通过省平台提交申请","where":"省平台；签约导师、创业指导师工作室","tip":"后续服务由培训机构组织签约导师或创业指导师工作室提供，学员须在结课时提交需求清单。"},{"sectionNo":"十八","headline":"考勤、影像和后续服务档案须留存备查，保存不少于3年","who":"创业培训机构。","materials":[],"window":"档案保存期限不少于3年","where":"原文未列具体受理部门或系统","tip":"留存范围含学员考勤信息、培训过程影像资料和后续服务情况，均须如实记录并留存备查。"},{"sectionNo":"二十一","headline":"补贴申请15个工作日内审核，公示5天，2个月内拨付","who":"申请创业培训补贴的培训机构。","materials":[],"window":"审核15个工作日；公示期5天；公示期满无异议后2个月内拨付。","where":"各级人力资源社会保障部门；当地人力资源社会保障网或政府公共服务网；省平台","tip":"公示期满无异议才拨付；资金拨付到培训机构在银行开立的基本账户，拨付情况由人社部门录入省平台。"},{"sectionNo":"二十二","headline":"同类别课程每人只享1次补贴，累计最多3次","who":"符合条件的创业培训补贴对象（参训学员）。","materials":[],"window":"自2024年1月1日起，每人累计最多享受3次","where":"原文未列具体受理部门或系统","tip":"累计次数与职业技能培训补贴合并计算；同类别创业培训课程每人只能享受一次。"},{"sectionNo":"二十五","headline":"骗取套取培训补贴将被追责，资金使用接受巡查抽查","who":"享受创业培训补贴资金的培训机构和个人。","materials":[],"window":"日常巡查、定期检查和临时抽查全过程","where":"各级人力资源社会保障部门、财政部门","tip":"对弄虚作假、骗取、套取补贴资金的单位和个人依法追究法律责任。"}],"sourceUrl":"https://rst.hunan.gov.cn/rst/xxgk/zcfg/zxzc/202509/t20250913_33803293.html","sourceNote":"2026-11-09 核对：原文页只挂 docx 附件，正文取自该附件且逐句比对一致（91/91 句命中）；网页发文日期 2025-07-25、信息时效期 2030-09-24；2026-11-09 按原文「自2025年7月25日起施行，有效期5年」推算 2025-07-25 至 2030-07-24","verified":true,"isSample":false,"numberStyle":"clause","bodyVerified":"verbatim","effectiveAt":"2025-07-25","expiresAt":"2030-07-24","hunan":true},{"id":"p-2025-c63084","title":"关于促进专精特新中小企业高质量发展的若干措施","level":"city","region":"长沙市","issuer":"长沙市人民政府办公室","documentNo":"长政办发〔2025〕3号","publishedAt":"2025-02-28","status":"active","tags":["认定资质","专项资金","研发创新"],"audience":["小微企业"],"summary":"长沙首次认定的专精特新\"小巨人\"企业每家一次性奖励50万元；重点项目每家每年最高补助30万元；数字化改造最高补助30万元。","sections":[{"no":"一","title":"建立梯度培育体系","text":"建立梯度培育体系。构建“专精特新中小企业—专精特新'小巨人'后备企业—专精特新'小巨人'企业”的梯度培育体系。围绕重点产业集群和产业链，梳理出一批创新能力强、赛道前景好、市场竞争优势显著的优质中小企业，分层动态建立企业培育体系，实施精准培育。推动科技型中小企业培育为高新技术企业，加快实现升规纳统。对首次认定的专精特新“小巨人”企业，每家给予一次性50万元奖励。（责任单位：市工业和信息化局、各区县市人民政府、园区管委会）"},{"no":"二","title":"精准支持科技创新","text":"精准支持科技创新。支持专精特新中小企业自筹建设或者与高校院所、医疗机构等联合共建技术创新中心。支持认定为高新技术企业的专精特新中小企业与国家级创新平台及高校院所组建新型研发机构。支持专精特新中小企业开展行业关键技术攻关和关键产品研发，鼓励企业牵头组建创新联合体，承担市级科技重大专项以及“揭榜挂帅”项目。鼓励专精特新中小企业依托长沙市科技创新综合信息平台发布技术需求清单；组织高校院所与专精特新中小企业开展产学研合作对接，支持专精特新中小企业主动吸纳承接高校院所科技成果，鼓励开展技术转让、技术开发、技术许可。指导支持专精特新中小企业开展标准创新型企业培育评价，对参与制定国际、国家和市级地方标准的企业，按规定给予一次性奖励。为企业开展质量诊断服务，指导专精特新中小企业导入先进质量管理模式，支持企业积极争创政府质量奖。（责任单位：市科技局、市工业和信息化局、市市场监管局）"},{"no":"三","title":"强化知识产权保护","text":"强化知识产权保护。将更多专精特新中小企业列入知识产权优势企业培育对象。依托国家专利导航综合服务平台，推进专精特新中小企业深度参与高校院所存量专利盘活工作。对符合条件的专精特新中小企业提供快速预审、快速确权和快速维权的知识产权综合服务。引导专业机构加强专精特新中小企业知识产权培训。（责任单位：市知识产权局）"},{"no":"四","title":"支持重点项目建设","text":"支持重点项目建设。支持专精特新“小巨人”后备企业深耕专业细分赛道，提升创新能力和竞争力；重点围绕打造新动能、攻坚新技术、开发新产品和强化产业链配套能力，依规定每年遴选一批重点项目，结合企业主营业务、研发创新、知识产权、数字化水平等综合指标，按照每家企业每年最高不超过30万元的标准给予补助。建立专精特新中小企业项目建设储备机制，实施动态管理，加强综合服务，积极支持符合要求的企业申报中央、省级资金项目。（责任单位：市工业和信息化局、市财政局）"},{"no":"五","title":"强化融资支持","text":"强化融资支持。发挥长沙市小微企业信贷风险补偿基金、长沙市中小企业转贷引导基金作用，推动银行业金融机构面向专精特新中小企业开发特色产品，提供应急转贷资金支持。强化供应链金融服务，探索搭建综合服务平台。建设政府引导基金与专精特新中小企业投资对接机制。依规定遴选符合条件的专精特新重点企业列入上市培育对象；做实北京证券交易所、全国股转系统长沙服务基地，健全战略合作机制，提升服务质效。聚焦重点产业链专精特新中小企业融资需求，开展投融资路演活动。（责任单位：市工业和信息化局、市委金融办、市财政局）"},{"no":"六","title":"强化人才服务","text":"强化人才服务。实施专精特新中小企业就业创业扬帆计划，将专精特新中小企业纳入重点企业用工保障范围。建设市域产教联合体，加强校企对接，开展专场招聘活动。探索推动具备条件的专精特新中小企业开展高级职称自主评定，赋予专精特新“小巨人”企业高层次人才举荐权。在企业员工职称评定中，不将论文作为硬性要求，支持将新产品研发等工作绩效作为评价的重要参考，对高端人才探索以业绩陈述代替论文答辩。大力支持专精特新中小企业吸引集聚高端人才，推荐符合条件的企业和人才申报市级“两大重点人才工程”、省级“芙蓉计划”、国家重点人才计划等人才项目，办理高层次人才分类认定，在人才落户、住房、子女教育和“长沙市卓越工程师”等享受政府津贴专家选拔中予以支持。加大人才平台建设力度。支持符合条件的专精特新“小巨人”企业建设院士工作站、专家工作站，分别给予每家企业100万元、60万元经费支持。支持符合条件的专精特新“小巨人”企业建设博士后科研工作站、博士后创新创业实践基地，分别给予每家企业100万元、60万元经费支持。专项支持专精特新中小企业举办符合长沙产业发展方向和人才需求的学术会议、专业论坛。（责任单位：市委人才办、市教育局、市科技局、市人力资源社会保障局、市科协）"},{"no":"七","title":"支持市场开拓","text":"支持市场开拓。促进大中小企业融通创新，分行业梳理专精特新中小企业产业链分布和协作清单，以集群和产业链为单位，精准推动专精特新中小企业与大企业开展市场、技术、人才对接。推动省、市国有企业开放创新资源和应用场景，与专精特新中小企业加强供需对接。对接国家中小企业国际合作协会、市级“走出去”联盟、公共信息服务平台等服务资源，组织开展专项培训，推动重点行业专精特新中小企业抱团“出海”、链式“出海”。支持专精特新中小企业参加境外展会，利用海外知名搜索引擎、社交媒体、电商平台开展线上推广营销，开展管理体系认证、境外产品认证、境外专利申请和境外商标注册，按规定给予资金支持。（责任单位：市工业和信息化局、市商务局）"},{"no":"八","title":"推进数字化发展","text":"推进数字化发展。深入推进智赋万企行动，支持中小企业上云、上平台。推进中小企业数字化转型城市试点工作。分行业推进中小企业数字化改造，对纳入试点的中小企业开展数字化改造给予补贴，按照每家企业不高于数字化改造采购总额30%的比例给予补助，其中每家企业补助金额最高不超过30万元。在使用中央财政资金按上述标准给予补助的基础上，市级财政根据实际情况给予配套支持，每家企业补助金额最高不超过30万元。打造一批数字化转型标杆，建设中小企业数字化转型公共服务平台，引导服务商研发推广“小快轻准”数字化产品和解决方案。支持专精特新中小企业建设智能制造工厂、打造应用场景。（责任单位：市工业和信息化局）"},{"no":"九","title":"促进绿色化发展","text":"促进绿色化发展。支持专精特新中小企业开展节能诊断、节能技术改造和建设工业绿色微电网。优先支持专精特新中小企业建设绿色工厂，创建绿色供应链管理企业。鼓励专精特新中小企业节约集约用地，在符合国土空间规划、不改变用途和保障安全的前提下，对专精特新中小企业通过厂房加层、厂区改造、内部用地整理等方式提高工业用地（不含工业地产）利用率和容积率的，不再增收土地价款。（责任单位：市发展改革委、市工业和信息化局、市自然资源规划局）"},{"no":"十","title":"优化企业服务","text":"优化企业服务。落实专精特新中小企业分层培育政策和服务措施，集成服务资源，提供精准服务。建立专精特新中小企业政府服务专员制度。链接全国中小企业服务一张网，建立线上线下一体化中小企业服务平台，开设专精特新中小企业服务专区，建立政策推送直达系统，完善困难问题帮扶分办系统。依托平台功能征集企业需求，开展融资服务、优才招聘、知识产权、企业管理、市场开拓等服务活动，对服务成效突出的企业服务机构按照每家机构最高不超过20万元的标准给予补助。（责任单位：市工业和信息化局、各区县市人民政府、园区管委会）\n本文件自2025年3月1日起施行，有效期3年，由市工业和信息化局负责具体解释工作。"}],"interpretations":[{"sectionNo":"一","headline":"长沙首次认定专精特新「小巨人」，一次性奖50万元","who":"在长沙的优质中小企业，按「专精特新中小企业—小巨人后备企业—小巨人企业」梯度培育；首次被认定的专精特新「小巨人」企业。","materials":[],"window":"按认定批次执行。","where":"市工业和信息化局、各区县市人民政府、园区管委会。","tip":"50万元只给「首次认定」的，已经是小巨人的不重复奖；同一政策还有推动科技型中小企业升为高新技术企业、升规纳统的培育安排。"},{"sectionNo":"八","headline":"数字化改造按采购额30%补，单家最高30万元","who":"纳入中小企业数字化转型城市试点、开展数字化改造的中小企业。","materials":[],"window":"按试点批次组织实施。","where":"市工业和信息化局。","tip":"中央财政按30%补、单家最高30万元；市级财政可再配套，但配套后每家企业合计补助金额同样不超过30万元。"},{"sectionNo":"五","headline":"应急转贷、风险补偿基金、上市培育都向专精特新倾斜","who":"长沙市专精特新中小企业，重点是重点产业链上的企业。","materials":[],"window":"按各基金、平台的具体申报安排。","where":"市工业和信息化局、市委金融办、市财政局；北京证券交易所、全国股转系统长沙服务基地。","tip":"可用的工具包括小微企业信贷风险补偿基金、中小企业转贷引导基金（应急转贷）、供应链金融和上市培育；符合条件可列入上市培育对象。"},{"sectionNo":"二","headline":"参与制定国际、国家、市级地方标准可获一次性奖励","who":"专精特新中小企业（含认定为高新技术企业的专精特新中小企业）；可自筹建设或与高校院所、医疗机构联合共建技术创新中心，与国家级创新平台及高校院所组建新型研发机构，牵头组建创新联合体承担市级科技重大专项及“揭榜挂帅”项目；参与制定国际、国家和市级地方标准的企业按规定给予一次性奖励。","materials":[],"window":"按年度科技项目、标准奖励申报批次执行，原文未列具体截止时间。","where":"长沙市科技创新综合信息平台；市科技局、市工业和信息化局、市市场监管局。","tip":"标准奖励仅写“按规定给予一次性奖励”，原文未列具体金额；技术创新中心可自筹建设，也可与高校院所、医疗机构联合共建。"},{"sectionNo":"三","headline":"符合条件的企业可享知识产权快速预审、确权、维权","who":"专精特新中小企业；将被列入知识产权优势企业培育对象，可深度参与高校院所存量专利盘活；符合条件的可获快速预审、快速确权和快速维权的知识产权综合服务。","materials":[],"window":"按知识产权服务受理安排，原文未列截止时间。","where":"国家专利导航综合服务平台；市知识产权局。","tip":"快速预审、快速确权、快速维权只对“符合条件的”专精特新中小企业提供，原文未列具体条件。"},{"sectionNo":"四","headline":"每年遴选重点项目，每家企业每年最高补助30万元","who":"专精特新“小巨人”后备企业及专精特新中小企业；重点项目须围绕打造新动能、攻坚新技术、开发新产品和强化产业链配套能力，结合企业主营业务、研发创新、知识产权、数字化水平等综合指标每年遴选一批。","materials":[],"window":"每年遴选一批重点项目；每家企业每年最高不超过30万元。","where":"市工业和信息化局、市财政局。","tip":"30万元是每家企业每年的最高限额，不是固定补助额；项目实行动态管理，符合要求的企业还可申报中央、省级资金项目。"},{"sectionNo":"六","headline":"建院士工作站补100万元、专家工作站补60万元","who":"专精特新中小企业及专精特新“小巨人”企业；员工职称评定不将论文作为硬性要求；符合条件的“小巨人”企业可建设院士工作站、专家工作站（分别100万元、60万元）及博士后科研工作站、博士后创新创业实践基地（分别100万元、60万元）；企业和人才可申报市级“两大重点人才工程”、省级“芙蓉计划”、国家重点人才计划并办理高层次人才分类认定。","materials":[],"window":"按人才项目、工作站建设申报批次执行，原文未列截止时间。","where":"市委人才办、市教育局、市科技局、市人力资源社会保障局、市科协。","tip":"院士工作站与专家工作站分别为每家企业100万元、60万元；博士后科研工作站与博士后创新创业实践基地同样分别为100万元、60万元；职称评定不将论文作为硬性要求。"},{"sectionNo":"七","headline":"境外展会、认证、专利申请、商标注册可获资金支持","who":"专精特新中小企业；参加境外展会，利用海外知名搜索引擎、社交媒体、电商平台开展线上推广营销，开展管理体系认证、境外产品认证、境外专利申请和境外商标注册的，按规定给予资金支持。","materials":[],"window":"按年度市场开拓项目申报批次，原文未列截止时间。","where":"市工业和信息化局、市商务局；国家中小企业国际合作协会、市级“走出去”联盟、公共信息服务平台。","tip":"资金支持限于参加境外展会、线上推广营销、管理体系认证、境外产品认证、境外专利申请和境外商标注册等事项，具体标准按“按规定给予资金支持”执行。"},{"sectionNo":"九","headline":"厂房加层、厂区改造提高容积率，不再增收土地价款","who":"专精特新中小企业；在符合国土空间规划、不改变用途和保障安全的前提下，通过厂房加层、厂区改造、内部用地整理等方式提高工业用地（不含工业地产）利用率和容积率的，不再增收土地价款；可开展节能诊断、节能技术改造、建设工业绿色微电网，优先支持建设绿色工厂、创建绿色供应链管理企业。","materials":[],"window":"按绿色工厂、绿色供应链管理企业认定批次，原文未列截止时间。","where":"市发展改革委、市工业和信息化局、市自然资源规划局。","tip":"免收土地价款仅限工业用地，不含工业地产；且须同时满足符合国土空间规划、不改变用途、保障安全三个前提。"},{"sectionNo":"十","headline":"服务成效突出的企业服务机构，每家最高补助20万元","who":"为专精特新中小企业提供服务且服务成效突出的企业服务机构（每家机构最高不超过20万元）；专精特新中小企业可通过线上线下一体化中小企业服务平台的服务专区获取融资服务、优才招聘、知识产权、企业管理、市场开拓等服务，并享政府服务专员制度。","materials":[],"window":"本文件自2025年3月1日起施行，有效期3年。","where":"市工业和信息化局、各区县市人民政府、园区管委会；线上线下一体化中小企业服务平台（专精特新中小企业服务专区）。","tip":"20万元是每家机构最高限额，按服务成效评定；本文件有效期3年，由市工业和信息化局负责具体解释工作。"}],"sourceUrl":"http://www.changsha.gov.cn/zfxxgk/zfwjk/szfbgt/202502/t20250228_11761924.html","sourceNote":"条文已于 2026-11-09 与官方页面/PDF 逐句比对，逐字一致（明细见 采集包/条文核对表.md）；2026-11-09 按原文「自2025年3月1日起施行，有效期3年」推算 2025-03-01 至 2028-02-29","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","effectiveAt":"2025-03-01","expiresAt":"2028-02-29","hunan":true},{"id":"p-2025-ed049d","title":"关于开展一次性创业补贴申报工作的通知","level":"city","region":"株洲市","issuer":"株洲市人力资源和社会保障局","documentNo":"株人社发〔2025〕8号","publishedAt":"2025-07-23","status":"active","tags":["创业补贴","就业补贴"],"audience":["小微企业","个体工商户","高校毕业生"],"summary":"株洲首次创办企业或个体工商户正常经营1年以上的重点群体，个体工商户补1万元、企业补2万元；大学生创业个体补2万元、企业补3万元。","sections":[{"no":"一","title":"申报条件","text":"（一）申报株洲市一次性创业补贴，需同时满足以下条件：\n1.在株洲市行政区域内首次登记注册的创业企业或个体工商户，登记注册时间在5年以内（以首次营业执照登记的成立日期为准，例如申报2025年度一次性创业补贴的，工商注册时间应在2020年1月1日至2024年12月31日之间），且有固定经营场所。\n2.创业项目符合国家产业发展方向，信用状况良好，无拖欠职工工资、欠缴社会保险费等违法违规信用记录。\n3.个体工商户经营者、企业法定代表人属于下列重点就业群体：返乡入乡农民工；大学生（在校及毕业两年内，含普通高校、职业学校、技工院校和留学归国人员）；就业困难人员。\n4.正常经营1年以上，且个体工商户经营者需带动2名以上劳动者就业，企业需带动5名以上劳动者就业，企业要求缴纳半年以上企业职工养老保险且处于正常缴纳状态。属于大学生创业企业的，带动劳动者就业可以放宽至3名以上，在校生可暂缓缴纳养老保险，当年毕业的大学生按在校生类别申报。\n（二）已申请过人社部门创业补贴的，不得重复申报。"},{"no":"二","title":"补贴标准","text":"（一）个体工商户按10000元/户的标准给予补贴，企业按20000元/户的标准给予补贴。\n（二）属于大学生创业的，个体工商户按20000元/户标准给予补贴、企业按30000元/户标准给予补贴。"},{"no":"三","title":"申报资料","text":"（一）补贴申请表\n《 年度株洲市一次性创业补贴申报表》（附件1）。\n《 年度株洲市在校生一次性创业补贴申报表》（附件2）。\n（二）申报对象基本信息资料\n包含个体工商户经营者或企业法人身份证复印件、营业执照、企业银行开户账号（个体工商户提供银行卡复印件）或其他登记注册证明复印件。\n（三）正常经营一年以上佐证资料\n包含经营场所房产证或租赁合同复印件、职工花名册、劳动合同复印件、经营流水、工资发放证明、企业公司简介、财务报表、员工参加企业职工基本养老保险证明。\n（四）信用佐证资料\n提供信用中国（湖南株洲）或国家企业信用信息公示系统无违法记录证明材料。\n（五）首次创业佐证资料\n提供国家市场监管系统市场主体投资任职情况查询材料。\n（六）申报对象就业重点群体佐证材料\n1.返乡入乡农民工提供户口本或农村土地承包经营权证复印件，以及以下任意一项转移就业经历证明：与原单位签订的劳动合同、返乡前缴纳的社会保险证明、户籍地乡镇（街道）公共服务办公室出具的返乡创业佐证资料等。\n2.普通高校、职业学校、技工院校和留学归国人员提供毕业证复印件或经教育部留学服务中心认证的国外学历学位认证书。在校生提供经学校创业就业指导部门审核的创业计划书、学生证复印件或学校出具的在校生身份证明。\n3.就业困难人员指按照《湖南省就业援助实施办法》进行身份认定，并在人社一体化平台中进行实名登记、动态管理的人员，包括：男满50周岁、女满40周岁人员；城镇零就业家庭人员；享受城市居民最低生活保障人员；残疾人员；失地农民；军队退役人员；市州级以上劳动模范；烈士家属；抚养未成年子女的单亲家庭成员；连续失业1年以上的其他登记失业人员。就业困难人员无需提交身份佐证材料，由人社部门在人社一体化平台信息系统中核实。"},{"no":"四","title":"申报流程","text":"（一）公开申报\n市人社局在官网（http://rsj.zhuzhou.gov.cn）公布政策文件。申报对象向工商注册地所在县市区人社局申报（在校生向所在学校申报），申报资料一式两份，统一用A4纸打印，按资料清单顺序装订成册。\n（二）组织初审\n县市区人社局负责受理辖区内申报对象的申报资料并组织初审（学校受理在校生的申报资料审批后报县市区人社局初审）。初审工作人员通过资料审核、实地走访等方式，核实各类证明、证件原件和资料复印件的真实性，核定申报对象经营情况、带动就业情况、补贴标准。初审完成后，由初审单位在申报表、汇总表签署意见并加盖公章。\n（三）汇总复核\n县市区人社局初审完成后，填报《株洲市一次性创业补贴汇总表》（附件3），自留一份，交市人社局一份。市人社局对申报资料的真实性、准确性进行复核，确定拟补贴对象及补贴金额。\n（四）官网公示\n复核通过后，市人社局将拟发放补贴名单在官网公示5个工作日。\n（五）资金拨付\n公示无异议后，由人社部门汇总补贴对象信息报送至同级财政部门，依据相关规定拨付补贴资金，并在“湖南人社一体化业务管理系统”内录入补贴信息。"},{"no":"五","title":"工作要求","text":"（一）加强政策宣传。各相关单位要充分利用网络、报纸、电视等媒体，多渠道、多形式宣传补贴政策，提高政策知晓度，扩大政策覆盖面，鼓励和支持更多有意愿、有能力的群体通过创业带动就业。\n（二）严格审核把关。各县市区人力资源和社会保障局、相关单位要严格按照文件要求，严谨审核，认真把关，确保申报资料的真实性。\n（三）严肃工作纪律。工作人员不得假公济私、以权谋私、索拿卡要、刁难企业和个人，收受企业和个人财物。申报企业和个人应对资料的真实性负责。对在申报过程中弄虚作假的申报企业和个人，一经核实，追回补贴资金、取消申报资格，依法纳入社会信用体系，不得再享受我市人社部门各类创业扶持政策。"},{"no":"六","title":"其他事项","text":"（一）当年度一次性创业补贴申报期截止至当年10月31日。\n（二）本通知自下发之日起实施，有效期5年。有效期内上级出台新规定与本通知不一致的，以上级新规定为准。\n（三）其他未尽事宜，由市人力资源和社会保障局负责解释。\n株洲市人力资源和社会保障局\n2025年7月23日"}],"interpretations":[{"sectionNo":"二","headline":"个体户补1万元、企业补2万元，大学生创业翻倍","who":"在株洲市行政区域内首次登记注册、登记时间在5年以内并有固定经营场所的创业企业或个体工商户；经营者或法定代表人须属返乡入乡农民工、大学生（在校及毕业两年内）、就业困难人员。","materials":[],"window":"按年度组织申报，工商注册时间需落在规定区间内（申报2025年度的为2020-01-01至2024-12-31）。","where":"工商注册地所在县市区人社局；在校生向所在学校申报。","tip":"已申请过人社部门创业补贴的，不得重复申报；大学生创业企业带动就业可放宽至3人以上。"},{"sectionNo":"一","headline":"正常经营满1年、企业带动5人就业才够条件","who":"个体户经营者需带动2名以上劳动者就业，企业需带动5名以上并缴纳半年以上企业职工养老保险且处于正常缴纳状态；大学生创业企业可放宽到3名以上。","materials":[],"window":"正常经营1年以上。","where":"县市区人社局初审，市人社局复核。","tip":"在校生可暂缓缴纳养老保险，当年毕业的大学生按在校生类别申报。"},{"sectionNo":"四","headline":"向注册地县市区人社局申报，公示5个工作日后拨付","who":"符合条件的申报对象；在校生由学校受理后报县市区人社局初审。","materials":["申报资料一式两份，A4纸打印并按清单顺序装订成册"],"window":"市人社局复核后官网公示5个工作日，无异议再拨付。","where":"工商注册地县市区人社局；公示在市人社局官网（rsj.zhuzhou.gov.cn）。","tip":"初审会实地走访核实经营情况与带动就业人数，材料要能对上实际用工。"},{"sectionNo":"三","headline":"一次性创业补贴申报要备齐申请表、执照、经营流水等资料","who":"在株洲市申报一次性创业补贴的个体工商户经营者、企业法人（含在校生）；须属于返乡入乡农民工、普通高校（职业学校、技工院校、留学归国人员）毕业生、在校生、就业困难人员等申报对象之一，并提交对应身份佐证；就业困难人员无需提交身份佐证材料，由人社部门在人社一体化平台核实。","materials":["《年度株洲市一次性创业补贴申报表》（附件1）","《年度株洲市在校生一次性创业补贴申报表》（附件2）","个体工商户经营者或企业法人身份证复印件、营业执照、企业银行开户账号（个体工商户提供银行卡复印件）或其他登记注册证明复印件","经营场所房产证或租赁合同复印件、职工花名册、劳动合同复印件、经营流水、工资发放证明、企业公司简介、财务报表、员工参加企业职工基本养老保险证明","信用中国（湖南株洲）或国家企业信用信息公示系统无违法记录证明材料","国家市场监管系统市场主体投资任职情况查询材料","返乡入乡农民工：户口本或农村土地承包经营权证复印件，以及劳动合同、返乡前社会保险证明、户籍地乡镇（街道）公共服务办公室出具的返乡创业佐证资料等任一转移就业经历证明","高校毕业生：毕业证复印件或经教育部留学服务中心认证的国外学历学位认证书；在校生：经学校创业就业指导部门审核的创业计划书、学生证复印件或学校出具的在校生身份证明"],"window":"正常经营一年以上；随当年度一次性创业补贴申报提交，申报期截止当年10月31日。","where":"株洲市人力资源和社会保障局；就业困难人员身份在人社一体化平台核实，信用情况查信用中国（湖南株洲）或国家企业信用信息公示系统。","tip":"就业困难人员无需提交身份佐证材料，由人社部门在人社一体化平台核实；申报企业和个人对资料真实性负责。"},{"sectionNo":"五","headline":"申报资料弄虚作假，追回补贴并取消申报资格","who":"株洲市一次性创业补贴的申报企业和个人；各县市区人力资源和社会保障局及相关单位负责审核把关。","materials":[],"window":"适用于当年度申报、审核全过程。","where":"各县市区人力资源和社会保障局及相关单位。","tip":"申报企业和个人应对资料真实性负责；一经核实弄虚作假，追回补贴资金、取消申报资格，依法纳入社会信用体系，且不得再享受我市人社部门各类创业扶持政策。"},{"sectionNo":"六","headline":"当年度一次性创业补贴申报截止10月31日，办法有效期5年","who":"当年度申报株洲市一次性创业补贴的申报对象（含在校生、个体工商户、企业等）。","materials":[],"window":"当年度申报期截止当年10月31日；本通知有效期5年。","where":"株洲市人力资源和社会保障局（负责解释）。","tip":"有效期内上级出台新规定与本通知不一致的，以上级新规定为准；其他未尽事宜由市人力资源和社会保障局负责解释。"}],"sourceUrl":"https://rsj.zhuzhou.gov.cn/c923/20250723/i2399858.html","sourceNote":"条文已于 2026-11-09 与官方页面/PDF 逐句比对，逐字一致（明细见 采集包/条文核对表.md）","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"p-2025-fda7b9","title":"关于印发《郴州市一次性创业补贴实施办法》的通知","level":"city","region":"郴州市","issuer":"郴州市人力资源和社会保障局、郴州市财政局","documentNo":"郴人社发〔2025〕28号","publishedAt":"2025-10-27","status":"active","tags":["创业补贴","场地支持","就业补贴"],"audience":["小微企业","个体工商户","高校毕业生"],"summary":"在校大学生、离校2年内高校毕业生、就业困难人员、返乡入乡农民工首次在郴州创办市场主体且正常运营1年以上，个体工商户补5000元、初创企业补5000元至15000元。","sections":[{"no":"一","title":"补贴对象","text":"对在校大学生和离校2年内高校毕业生（含留学回国学生，高等院校和大中专院校，高职院校大专及以上，技工院校高级工班、预备技师及技师班）、就业困难人员、返乡入乡农民工首次在我市创办小微企业或从事个体经营，以及在各级人社部门认定的创业孵化基地场所内首次开办符合产业政策范畴的初创企业和个体工商户，可按规定申报一次性创业补贴。"},{"no":"二","title":"申报条件","text":"申报一次性创业补贴需同时具备以下条件：\n（一）在我市范围内登记注册的初创企业和个体工商户，登记注册时间在5年以内（以首次营业执照登记的成立日期为准，2025年申报企业的注册时间为2020年1月1日至2024年12月31日期间，以此类推）。\n（二）正常运营1年以上，吸纳2名以上（含2名）城乡劳动者就业（不含法定代表人）。其中，在校大学生和离校2年内高校毕业生申报一次性创业补贴需吸纳1名以上城乡劳动者就业（不含法定代表人）。\n（三）创业主体经营范围符合国家产业发展方向，不含建筑业（包含建筑、安装、修缮、装饰及其他工程作业）、娱乐业（包含歌厅、舞厅、KTV、棋牌室、酒吧、台球、桑拿、美体按摩、足浴、网吧、氧吧等）、广告业、销售不动产、转让土地使用权、房产中介等其他国家政策不予鼓励扶持的产业实体。\n（四）企业法定代表人属于在校大学生、离校2年内高校毕业生、就业困难人员或返乡入乡农民工。法定代表人持股比例不低于公司总股份的30%。法定代表人近两年由不符合以上条件的群体变更为符合以上条件的群体的，不纳入补贴范围。\n（五）创业主体近两年在信用中国（湖南郴州）无行政处罚等违法记录，无知识产权或其他经济、法律纠纷。\n（六）在符合上述条件的情况下，各地根据资金预算对带动就业人数较多的申报企业进行优先扶持。"},{"no":"三","title":"补贴标准","text":"一次性创业补贴包括一次性开办费补贴、经营场所租金补贴和商标补贴。其中经营场所租金补贴和商标补贴仅限大学生创业主体和创业孵化基地入孵企业可享受。\n（一）一次性开办费补贴标准\n对符合条件的个体工商户，给予5000元的一次性开办费。对符合条件的初创企业，根据吸纳城乡劳动者就业人数情况，一次性开办费补贴标准为5000元至15000元。吸纳2人（含2人）就业的补贴5000元，吸纳2人以上就业的每增加1人给予1000元补贴，最高不超过15000元。其中，大学生初创企业吸纳1-5人（含5人）就业的补贴10000元；吸纳5人以上就业的补贴15000元。已经享受过同一项目补贴的，不能重复享受。\n（二）经营场所租金补贴标准（仅限大学生创业主体和创业孵化基地入孵企业可享受）\n1.经营场所属于工业行业企业的，按每月最高不超过8元/平方米的标准予以补贴。\n2.工业行业外的其他行业企业（含个体工商户），按每月最高16元/平方米的标准予以补贴，每年最高不超过10万元。实际租金低于补贴标准的，按实际交纳租金给予补贴。\n3.有多处经营场所的申报单位，在营业执照登记注册地申报，同一创业项目不得重复申报。经营场所租金补贴期限最长不超过2年，自工商登记注册之日起计算。使用自有房产创业的不纳入经营场所租金补贴范围。\n（三）商标注册补贴（仅限大学生创业群体和创业孵化基地入孵企业可享受）\n对符合条件的创业主体新获注册商标的，以商标注册证和付费票据据实补贴注册费用。在商标注册过程中产生的差旅费和委托代理费等费用不列入补贴范围。每个创业主体商标补贴个数最多不超过5个。"},{"no":"四","title":"申报资料","text":"1.《郴州市一次性创业补贴申请表》（附件1）。\n2.营业执照或其他登记注册证明，法定代表人身份证。\n3.身份证明材料：\n在校大学生：学生证复印件或学校证明、学信网学籍验证报告（学信网下载打印）；\n离校2年内高校毕业生：毕业证书复印件及学历证明（学信网下载打印），留学回国学生提供教育部留学服务中心颁发的学历认证书复印件；\n返乡入乡农民工提供户籍地址为村的户口本；乡镇或村出具的外出务工经历证明，或其他可印证有外出务工经历的资料、图片、车票、单据等。\n在各级人社部门认定的创业孵化基地场所内创业的，提供孵化基地入孵协议；\n就业困难人员无需提供佐证资料，由人社部门在湖南省人社一体化业务管理系统中核实。\n4.提供劳动合同复印件、员工花名册和带动就业人员近3个月的工资转账记录或参保凭证。\n5.房产证明（如无房产证则提供商品房销售合同）、租赁合同、缴纳租金的发票或收据、转账记录等，享受创业孵化基地租金减免的创业主体，租金减免金额按入孵协议的约定计算。\n6.信用中国（湖南郴州）查询记录。\n7.《商标注册证》原件及复印件，注册费发票复印件\n8.公司股权分配证明资料。\n9.其他佐证资料。"},{"no":"五","title":"申报流程","text":"（一）自主申报。按创业主体工商注册（或登记机关）属地管理原则，符合条件的申请人向所在地人力资源和社会保障部门申报，高新区、经开区创业主体向所在地综合服务中心申报。享受创业孵化基地租金减免的创业主体，经营场所租金补贴可由创业孵化基地代为申请。\n（二）考察审核。人社部门受理申请后，在每季度末月进行集中审核，结合实地考察情况，核定申报企业吸纳就业人数及补贴金额。\n（三）网上公示。考察审核完成后确定的补贴创业主体名单，应在同级人力资源和社会保障部门官网上或当地政府网站进行公示，公示期为5个工作日。\n（四）资金拨付。受补贴名单确定后，由人社部门汇总补贴对象信息报送至同级财政部门，按照相关规定将补贴资金拨付至申报企业账户，并在“湖南人社一体化业务管理系统”内录入补贴信息。"},{"no":"六","title":"补贴终止","text":"出现以下情形之一的，终止享受补贴：\n1.申报审核期间，创业主体处于停业状态，或已注销、吊销营业执照的。\n2.经核实有其他不符合补贴发放政策相关条件的。"},{"no":"七","title":"其他","text":"离校2年以上，3年以内高校毕业生首次在我市创办小微企业或从事个体经营，可参照本办法规定申报一次性创业补贴。补贴资金从郴州市支持大学生创业专项资金支出，支出流程按《郴州市支持大学生创业专项资金管理办法》（郴教发〔2025〕4号）相关规定执行。"},{"no":"八","title":"工作要求","text":"（一）加强宣传推荐。我市各级人社部门要通过网络、报纸、电视、微信等媒体广泛开展政策宣传。各相关单位要积极推荐符合当地产业发展方向，代表先进生产力、生产方式的创新创业带动就业的先进典型。\n（二）严格审核把关。我市各级人社部门要严格按照文件要求，严格审核、认真把关，确保真实性。财政部门要加强资金监管，充分提高资金使用效率。\n（三）严肃工作纪律。我市各级人社部门要优化服务，提供便捷申报受理渠道。申报企业或个人应对申报资料的真实性负责。对有违规申报、弄虚作假、骗取套取等行为的申报企业和个人，一经核实，取消申报资格，情节严重的纳入诚信黑名单，并依法依规作出处理和追究相关单位和个人责任。"},{"no":"九","title":"本办法由市人力资源和社会保障局、市财政局负责解释","text":"本办法由市人力资源和社会保障局、市财政局负责解释。"},{"no":"十","title":"本办法自公布之日起施行,有效期5年","text":"本办法自公布之日起施行,有效期5年。此前有关政策文件规定与本办法不一致的，以本办法为准。有效期内上级出台新规定与本办法不一致的，以上级新规定为准。\n附件：郴州市一次创业补贴申请表.doc"}],"interpretations":[{"sectionNo":"一","headline":"首次在郴州创业的这四类人，可领一次性创业补贴","who":"在校大学生、离校2年内高校毕业生（含留学回国学生，含技工院校高级工班及以上）、就业困难人员、返乡入乡农民工。须是首次在郴州创办小微企业或从事个体经营；或在认定的创业孵化基地内首次开办符合产业政策方向的初创企业、个体工商户。","materials":["学生证复印件或学校证明（在校大学生）","毕业证书复印件及学信网学历证明（离校2年内高校毕业生）","户籍地址为村的户口本、外出务工经历证明（返乡入乡农民工）","孵化基地入孵协议（基地内创业的）"],"window":"本办法自公布之日起施行，有效期5年。","where":"创业主体工商注册地的人力资源和社会保障部门；高新区、经开区创业主体向所在地综合服务中心申报。","tip":"就业困难人员不用自己找证明，由人社部门在湖南省人社一体化业务管理系统中核实。"},{"sectionNo":"二","headline":"注册5年内、正常运营满1年、吸纳2人以上才够条件","who":"在郴州登记注册5年以内的初创企业或个体工商户；正常运营1年以上并吸纳2名以上城乡劳动者就业（大学生创业只需吸纳1名）；法定代表人须属于四类群体之一且持股不低于30%；近两年无行政处罚记录。","materials":["营业执照","信用中国（湖南郴州）查询记录","公司股权分配证明资料","劳动合同复印件、员工花名册"],"window":"人社部门在每季度末月集中审核，名单公示5个工作日。","where":"所在地人力资源和社会保障部门","tip":"建筑业、娱乐业、广告业、销售不动产、房产中介等不在扶持范围；法定代表人近两年才变更为符合条件群体的，不纳入补贴范围。"},{"sectionNo":"三","headline":"个体户补5000元，企业按吸纳就业人数补5000至15000元","who":"符合条件的个体工商户与初创企业。经营场所租金补贴和商标注册补贴只给大学生创业主体和创业孵化基地入孵企业。","materials":["房产证明（无房产证可用商品房销售合同）","租赁合同","缴纳租金的发票或收据、转账记录","商标注册证原件及复印件、注册费发票"],"window":"经营场所租金补贴期限最长不超过2年，自工商登记注册之日起计算。","where":"所在地人社部门；享受孵化基地租金减免的，经营场所租金补贴可由孵化基地代为申请。","tip":"已享受过同一项目补贴的不能重复享受；用自有房产创业的不纳入租金补贴；商标补贴每个主体最多5个。"},{"sectionNo":"四","headline":"申报一次性创业补贴要交执照、身份证明、劳动合同与租金凭证","who":"在校大学生、离校2年内高校毕业生（含留学回国学生）、返乡入乡农民工、就业困难人员，以及在各级人社部门认定的创业孵化基地场所内创业的创业主体；就业困难人员身份由人社部门在系统核实。","materials":["《郴州市一次性创业补贴申请表》（附件1）","营业执照或其他登记注册证明，法定代表人身份证","在校大学生：学生证复印件或学校证明、学信网学籍验证报告","离校2年内高校毕业生：毕业证书复印件及学历证明；留学回国学生提供教育部留学服务中心学历认证书复印件","返乡入乡农民工：户籍地址为村的户口本、乡镇或村出具的外出务工经历证明","创业孵化基地入孵协议（在基地场所内创业的）","劳动合同复印件、员工花名册、带动就业人员近3个月工资转账记录或参保凭证","房产证明（或商品房销售合同）、租赁合同、缴纳租金的发票或收据、转账记录","信用中国（湖南郴州）查询记录","《商标注册证》原件及复印件、注册费发票复印件","公司股权分配证明资料","其他佐证资料"],"window":"带动就业人员须提供近3个月工资转账记录或参保凭证；原文未另定申报期限。","where":"人社部门在湖南省人社一体化业务管理系统核实就业困难人员；信用记录查“信用中国（湖南郴州）”。","tip":"就业困难人员无需提供佐证资料；享受创业孵化基地租金减免的，租金减免金额按入孵协议约定计算。"},{"sectionNo":"五","headline":"向注册地人社部门申报，每季度末月审核，公示5个工作日","who":"按创业主体工商注册（或登记机关）属地管理原则、符合条件的申请人；高新区、经开区创业主体向所在地综合服务中心申报；享受创业孵化基地租金减免的创业主体，经营场所租金补贴可由基地代为申请。","materials":[],"window":"人社部门受理后在每季度末月集中审核；补贴名单公示5个工作日，名单确定后拨付资金。","where":"所在地人力资源和社会保障部门；高新区、经开区综合服务中心；同级人社部门官网或当地政府网站；湖南人社一体化业务管理系统。","tip":"须先公示5个工作日；资金拨付至申报企业账户，并在“湖南人社一体化业务管理系统”录入补贴信息。"},{"sectionNo":"六","headline":"停业、注销或吊销营业执照的，终止享受补贴","who":"已申报或已享受一次性创业补贴的创业主体；申报审核期间处于停业状态，或已注销、吊销营业执照的，以及经核实有其他不符合补贴发放政策条件的。","materials":[],"window":"申报审核期间即核查，出现所列情形即终止享受补贴。","where":"原文未列具体部门，在申报审核与补贴发放环节核查。","tip":"经核实有其他不符合补贴发放政策相关条件的，同样终止享受补贴。"},{"sectionNo":"七","headline":"离校2年以上3年以内高校毕业生首次创业，可参照申报补贴","who":"离校2年以上、3年以内的高校毕业生，首次在郴州市创办小微企业或从事个体经营的，可参照本办法申报一次性创业补贴。","materials":[],"window":"离校2年以上、3年以内期间首次创业；补贴资金从郴州市支持大学生创业专项资金支出。","where":"按《郴州市支持大学生创业专项资金管理办法》（郴教发〔2025〕4号）规定的支出流程执行。","tip":"须为首次在郴州市创办小微企业或从事个体经营；资金支出流程按郴教发〔2025〕4号办法执行。"}],"sourceUrl":"https://czrsj.czs.gov.cn/18281/18298/content_3994248.html","sourceNote":"2026-11-09 核对：正文与郴州市人社局原文页逐句比对一致（69/69 句命中），页面落款 2025-10-27、文号 郴人社发〔2025〕28号，现行有效","verified":true,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"p-2026-2747c9","title":"岳阳市人民政府办公室关于印发《关于支持省域区域科技创新中心建设的若干措施》的通知","level":"city","region":"岳阳市","issuer":"岳阳市人民政府办公室","documentNo":"岳政办发〔2026〕3号","publishedAt":"2026-04-14","status":"active","tags":["研发创新","专项资金","融资支持"],"audience":["小微企业"],"summary":"岳阳实施石化产业科技重大专项单个项目最高支持100万元；前沿技术研究项目最高200万元；国家级创新平台最高支持200万元；创新创业大赛获奖项目1万-30万元不等。该市未检索到一次性创业补贴专项，本条为替代。","sections":[{"no":"一","title":"支持重点领域技术攻关","text":"（一）实施石化产业科技重大专项。聚焦绿色化工、高端新材料、现代石化装备等支柱产业，支持关键技术研发与“五首”（首台套、首批次、首版次、首轮次、首套件）产品示范，单个项目给予最高100万元资金支持。\n（二）实施“十大技术攻关”项目。围绕“1+3+X”现代化产业体系技术创新需求，每年遴选实施10项市级重大技术攻关项目，重点支持优势产业关键技术攻关与产业化应用，每个给予最高60万元资金支持。\n（三）开展前沿技术研究。推动人工智能、智能计算、合成生物、先进复合材料、医药健康、先进装备制造、循环经济等新兴产业和未来产业技术研究，每年实施1—2个原创性突破项目，每个给予最高200万元资金支持，并优先推荐纳入省市联动科技攻关项目。\n（四）优化重点研发项目布局。聚焦重点产业体系技术节点问题开展技术攻关，支持龙头企业牵头开展产业链协同创新，每个项目给予最高50万元资金支持。鼓励各县市区围绕主特产业创新发展，设立县域科技创新专项资金，重点支持2—3个科技创新项目。"},{"no":"二","title":"加大全社会研发投入","text":"（五）落实研发投入优惠政策。全面落实研发费用加计扣除和高新技术企业减征企业所得税等优惠政策，支持企业积极申报省企业研发财政奖补资金，做到优惠政策应享尽享。\n（六）鼓励高校、科研院所和医疗机构加大研发投入。对年度研发投入首次达100万元以上的科研院所，每家给予5万元资金支持；对年度研发投入首次达2000万元以上的高校和医疗机构，每家给予10万元资金支持；对年度研发投入高于往年最高年度研发投入的高校、科研院所和医疗机构，按年度研发投入增量部分的1%给予资金支持，每家最高20万元。\n（七）提升基础研究和应用基础研究能力。完善湖南省自然科学基金区域（岳阳市）联合基金机制，鼓励企事业单位出资参与，每个立项的联合基金项目给予5万元资金支持。设立应用基础研究专项资金，支持高校、科研院所和医疗机构等开展应用基础研究，每个立项项目给予最高5万元资金支持。"},{"no":"三","title":"支持科技创新平台建设","text":"（八）强化高能级创新和孵化平台建设。鼓励争创全国重点实验室、国家技术创新中心、国家制造业创新中心、国家新兴产业创新中心、国家产业技术工程化中心等高水平创新平台，对获批组建的，每个给予最高200万元资金支持。对新认定的标准级、卓越级国家级科技企业孵化器，每个分别给予20万元、30万元资金支持。\n（九）构建多层次创新平台体系。争创省级创新平台，健全完善市级创新平台。对新认定的省级创新平台按现有政策予以支持。鼓励创建市级重点实验室、技术创新中心、工程技术研究中心、新型研发机构等研究类平台，成果转化中试基地、创新联合体、科创飞地等成果转化类平台，科普基地、临床医疗技术示范基地、科技企业孵化器等服务类平台，专家工作站、博士创新站等人才引育类平台，对申报的项目符合产业发展需求的，结合绩效评价情况，每个给予最高20万元资金支持。"},{"no":"四","title":"加强创新主体培育","text":"（十）加快科技型企业培育。鼓励各县市区出台支持政策，建立“科技型中小企业—高新技术企业”梯次培育机制，对通过国家高新技术企业首次认定、复审的，给予资金支持。\n（十一）激发创新创业活力。积极举办岳阳市创新创业大赛，对获奖的项目，每个给予1万元至5万元不等的资金支持。支持承办中国创新创业大赛现代石化专业赛，由主办方对获奖的项目每个给予1万元至30万元不等的资金支持。"},{"no":"五","title":"促进科技成果转移转化","text":"（十二）开展科技成果转移转化后补助计划。对高校、科研院所和医疗机构在岳实施科技成果转移转化的，按照不超过全年技术开发和转让合同交易实际到账额1%的比例给予输出方资金支持，最高20万元；对企业承接高校、科研院所和医疗机构科技成果转移转化的，按照不超过全年技术开发和转让合同交易实际到账额1%的比例给予承接方资金支持，最高10万元。\n（十三）实施示范性科技成果转化项目。鼓励高质量科技成果在岳转化，每年评选一批具有示范效应的重大科技成果转化项目。对企业与高校或科研院所共同研发（含技术开发、技术转让、技术许可），取得关键技术突破和突出产业化效果，且持续进行技术迭代和成果产业化的科技成果转化项目，每个给予最高20万元资金支持。\n（十四）强化科技金融赋能。完善科技型企业知识价值贷款风险补偿机制，鼓励合作银行向符合条件的科技型企业发放不超过3000万元的知识价值贷款。落实科技金融“湘伴前行”计划，支持企业发行科技创新债券，发展壮大岳阳市政府产业投资基金，合作设立子基金，引导更多长期资本、耐心资本和优质资本支持科技创新。"},{"no":"六","title":"推进科技交流合作","text":"（十五）搭建区域合作桥梁。加强与长三角、京津冀等地的科技合作，深度对接武汉、长沙两大创新策源地，探索“研发在武汉长沙、转化在岳阳”创新模式，联动建设“武汉—岳阳—长沙经济科创走廊”。鼓励市外知名高校、科研院所和科技服务机构来岳建设技术转移中心，开展科技合作。对在岳阳市开展技术转移活动并取得显著成效的单位，按其技术转移实际绩效每家给予最高100万元资金支持。"},{"no":"七","title":"优化创新生态环境","text":"（十六）加大财政科技投入力度。贯彻落实《湖南省科学技术进步条例》，加强财政保障，将财政科技支出列为市、县两级财政预算保障重点,建立健全财政科技投入的稳定增长机制。\n（十七）加大科技创新战略研究。鼓励企事业单位专家、学者、企业家参与建设省域区域科技创新中心战略研究，实施一批科技创新、产业创新、体制机制创新等方面的科技创新战略研究项目，每个研究项目给予最高20万元资金支持。\n（十八）促进科技服务业发展。鼓励围绕全社会研发投入、创新主体培育、技术转移转化、技术推广等领域开展科技服务，优化科技服务业发展生态，对促进科技创新发展成效明显的科技服务单位，每家给予最高20万元资金支持。\n（十九）支持科学技术进步活动。鼓励申报科学技术奖，对获得国家、省科学技术奖的第一完成单位按照国家、省奖励标准1:1比例给予资金支持，每个最高100万元。\n（二十）选树科技创新典型。按程序开展科技研发、成果转化和产业化等方面作出突出贡献的科技工作者评选工作，在全社会营造浓厚创新氛围。\n（二十一）完善包容创新制度。支持科技人员敢于创新、先行先试。对原始记录等能够证明承担探索性强、风险高的科学技术研究开发项目的科技人员已经履行了勤勉尽责义务，且符合法律法规规定及决策程序，仍不能完成该项目的，不作负面评价，依法依规减轻或免除相关责任。\n以上措施自2026年4月14日起施行，有效期3年。政策支持总额以当年度财政科技创新专项预算为限。我市现行规定与本规定不一致的，以本规定为准。在施行过程中，如遇上级政策调整，以上级政策为准。"}],"interpretations":[{"sectionNo":"一","headline":"石化重大专项最高100万元，前沿技术项目最高200万元","who":"在岳阳开展技术攻关的企业与项目：石化产业科技重大专项（绿色化工、高端新材料、现代石化装备）；「十大技术攻关」项目；前沿技术研究（人工智能、智能计算、合成生物等）；重点研发项目。","materials":[],"window":"「十大技术攻关」每年遴选10项；前沿技术研究每年实施1—2个原创性突破项目。","where":"岳阳市科技主管部门（按各专项申报通知）。","tip":"不同专项额度不同：石化重大专项最高100万元、十大技术攻关最高60万元、前沿技术最高200万元、重点研发最高50万元，别把额度串用。"},{"sectionNo":"四","headline":"高企首次认定和复审有资金支持，创新创业大赛奖1万至5万元","who":"通过国家高新技术企业首次认定、复审的企业；岳阳市创新创业大赛获奖项目；承办中国创新创业大赛现代石化专业赛的获奖项目。","materials":[],"window":"按年度认定与赛事安排。","where":"岳阳市科技局及各县市区科技主管部门。","tip":"市级大赛奖金 1 万至 5 万元；专业赛奖金 1 万至 30 万元，两者不是一回事。"},{"sectionNo":"二","headline":"科研院所研发首达100万元补5万元，高校医院达2000万元补10万元","who":"年度研发投入首次达100万元以上的科研院所；年度研发投入首次达2000万元以上的高校和医疗机构；研发投入高于往年最高年度投入的高校、科研院所和医疗机构；出资参与湖南省自然科学基金区域（岳阳市）联合基金的企事业单位。","materials":[],"window":"按年度研发投入核算；联合基金与应用基础研究项目按立项批次，原文未设申报截止时间","where":"原文未列具体受理部门或系统","tip":"研发投入增量部分按1%支持、每家最高20万元；每个立项的联合基金项目5万元，应用基础研究项目最高5万元。"},{"sectionNo":"三","headline":"国家级创新平台最高200万元，国家级孵化器20万至30万元","who":"获批组建全国重点实验室、国家技术创新中心、国家制造业创新中心、国家新兴产业创新中心、国家产业技术工程化中心等平台的单位；新认定的标准级、卓越级国家级科技企业孵化器；申报市级研究类、成果转化类、服务类、人才引育类平台的单位。","materials":[],"window":"按平台认定（获批）批次，原文未设申报截止时间","where":"原文未列具体受理部门或系统","tip":"市级平台每个最高20万元，须符合产业发展需求并结合绩效评价；省级创新平台按现有政策予以支持。"},{"sectionNo":"五","headline":"成果转化按到账额1%补助，输出方最高20万元、承接方最高10万元","who":"在岳实施科技成果转移转化的高校、科研院所和医疗机构（输出方）；承接上述单位科技成果转移转化的企业（承接方）；共同研发并产业化的企业。","materials":[],"window":"按全年技术开发和转让合同交易实际到账额核算；示范性成果转化项目每年评选一批","where":"原文未列具体受理部门或系统","tip":"示范性科技成果转化项目每个最高20万元；合作银行发放知识价值贷款不超过3000万元。"},{"sectionNo":"六","headline":"市外高校院所来岳建技术转移中心，绩效最高支持100万元","who":"市外知名高校、科研院所和科技服务机构；在岳阳市开展技术转移活动并取得显著成效的单位。","materials":[],"window":"按技术转移实际绩效核定，原文未设申报截止时间","where":"原文未列具体受理部门或系统","tip":"探索“研发在武汉长沙、转化在岳阳”模式，联动建设“武汉—岳阳—长沙经济科创走廊”；支持按技术转移实际绩效给予支持。"},{"sectionNo":"七","headline":"战略研究、科技服务每家最高20万元，科技奖1:1配套最高100万元","who":"参与科技创新战略研究的企事业单位专家、学者、企业家；促进科技创新发展成效明显的科技服务单位；获得国家、省科学技术奖的第一完成单位；承担探索性强、风险高研究开发项目的科技人员。","materials":[],"window":"自2026年4月14日起施行，有效期3年；政策支持总额以当年度财政科技创新专项预算为限。","where":"原文未列具体受理部门或系统","tip":"科技奖按国家、省奖励标准1:1比例支持，每个最高100万元；尽职免责仅适用于已履行勤勉尽责义务且符合法律法规规定及决策程序的情形。"}],"sourceUrl":"https://www.yueyang.gov.cn/gfxwj/szfwj/content_2372867.html","sourceNote":"条文已于 2026-11-09 与官方页面/PDF 逐句比对，逐字一致（明细见 采集包/条文核对表.md）；2026-11-09 按原文「自2026年4月14日起施行，有效期3年」推算 2026-04-14 至 2029-04-13","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","effectiveAt":"2026-04-14","expiresAt":"2029-04-13","hunan":true},{"id":"p-2026-41937b","title":"常德市人力资源和社会保障局关于延续实施扩大社会保险补贴范围政策的公告","level":"city","region":"常德市","issuer":"常德市人力资源和社会保障局","documentNo":"","publishedAt":"2026-09-02","status":"active","tags":["社保补贴"],"audience":["小微企业","高校毕业生"],"summary":"制造业、生活服务业、现代服务业领域的中小微企业吸纳重点群体就业并在2026年按规定缴纳三项社会保险费的，按照个人实际缴费额的25%给予社会保险补贴，每人累计享受补贴期限不超过12个月，申请期限截至2026年12月31日。","sections":[{"no":"一","title":"为进一步激励企业扩岗吸纳就业，助力重点群","text":"为进一步激励企业扩岗吸纳就业，助力重点群体稳定就业，根据有关文件规定，我市2026年延续实施扩大社会保险补贴范围政策。\n\n1.补贴对象\n\n重点行业领域的中小微企业吸纳重点群体就业，并在2026年按规定为其新缴纳或继续缴纳企业职工基本养老保险费、基本医疗保险费、失业保险费的，按照个人实际缴费额的25%给予社会保险补贴。重点行业领域包括：制造业、生活服务业、现代服务业，具体行业按照国家统计局的行业划分确定。重点群体包括：2026届高校毕业生、2024届和2025届离校未就业高校毕业生，登记失业半年以上人员和防止返贫致贫对象。对于符合《湖南省人力资源和社会保障厅湖南省财政厅关于落实扩大社会保险补贴范围政策有关工作的通知》（湘人社函〔2025〕84号）等文件规定条件，但在2025年未及时申领补贴的人员，可于2026年继续提出申请。\n\n2.申领期限\n\n补贴采用“先缴后补”的方式，可由企业或劳动者向社保参保地或企业所在地的公共就业服务机构提出申请。每人累计享受补贴期限不超过12个月，申请期限截至2026年12月31日。\n\n3.申报流程\n\n个人申报流程\n\n1.智慧人社或电子社保卡扫码登录湖南人社公共服务网上服务大厅（网址：https://ggfw.rst.hunan.gov.cn）。\n\n2.点击公共就业菜单。\n\n3.点击扩围社会保险补贴申请——申请。\n\n4.系统会自动生成身份证、社保卡信息，无社保卡的可以自录银行（填写好申报人的银行信息），申请人填写姓名、联系电话、人员类别（选择符合条件的人员类别）等信息后上传毕业证、身份证正反面、劳动合同后提交申请。\n\n企业申报流程\n\n1.登录界面（https://ggfw.rst.hunan.gov.cn/neaf-ui/#/login）\n\n企业专员使用电子社保卡登录。\n\n2.点击“公共就业”“企业吸纳人员管理”模块进行人员资料完善。\n\n3.填写信息，上传相关资料（仅高校毕业生需要毕业证）后点击保存。\n\n4.点击人员列表后的图标\n\n提交完成。\n\n4.政策咨询电话\n\n市本级7817805\n\n武陵区7230570\n\n鼎城区7375220\n\n西湖管理区2821992\n\n西洞庭管理区7509109\n\n汉寿县2337008\n\n桃源县6612138\n\n临澧县5891049\n\n澧县3127631\n\n石门县5165977\n\n津市市4237358\n\n安乡县4338528"}],"interpretations":[{"sectionNo":"一","headline":"常德中小微企业招重点群体，按个人缴费额25%补社保","who":"重点行业领域（制造业、生活服务业、现代服务业）的中小微企业，2026年吸纳重点群体就业并按规定新缴或续缴企业职工养老、医疗、失业保险费的。重点群体包括 2026 届高校毕业生、2024 届和 2025 届离校未就业高校毕业生、登记失业半年以上人员、防止返贫致贫对象。","materials":[],"window":"每人累计享受不超过12个月；申请期限截至 2026年12月31日。","where":"社保参保地或企业所在地的公共就业服务机构；线上走湖南人社公共服务网上服务大厅（ggfw.rst.hunan.gov.cn）。","tip":"采用「先缴后补」，不是先发钱；2025 年符合条件但没及时申领的，2026 年还可以补申请。"},{"sectionNo":"一","headline":"个人网上申请四步走，企业用电子社保卡登录","who":"个人申请：符合条件的劳动者本人；企业申请：企业专员。","materials":["毕业证","身份证正反面","劳动合同","社保卡或银行账户信息"],"window":"2026年12月31日前提交申请。","where":"湖南人社公共服务网上服务大厅（个人：ggfw.rst.hunan.gov.cn；企业：企业登录入口），用电子社保卡扫码登录。","tip":"系统会自动带入身份证、社保卡信息；没有社保卡的可以自己录入银行信息。企业申报时只有高校毕业生需要上传毕业证。"}],"sourceUrl":"https://mohrss.changde.gov.cn/zhdt/gggs/content_78217097","sourceNote":"条文已于 2026-11-09 与官方页面/PDF 逐句比对，逐字一致（明细见 采集包/条文核对表.md）；2026-11-08 核对：页面发布日期 2026-09-02","verified":true,"isSample":false,"numberStyle":"clause","bodyVerified":"verbatim","hunan":true},{"id":"p-2026-63153b","title":"优质中小企业梯度培育管理办法","level":"national","region":"全国","issuer":"工业和信息化部","documentNo":"","publishedAt":"2026-06-15","status":"active","tags":["认定资质","研发创新"],"audience":["小微企业"],"summary":"优质中小企业分科技和创新型中小企业、专精特新中小企业、专精特新\"小巨人\"企业三个梯度培育，认定后有效期3年，到期复核通过可延长。","sections":[{"no":"一","title":"第一条","text":"为加强和规范优质中小企业培育管理，促进中小企业专精特新发展，支撑推进新型工业化、发展新质生产力、建设现代化产业体系，根据党中央、国务院有关决策部署，制定本办法。"},{"no":"二","title":"第二条","text":"优质中小企业是指在产品、技术、工艺、管理、模式等方面创新能力强、专注细分市场、成长性好的中小企业，包括科技和创新型中小企业、专精特新中小企业、专精特新“小巨人”企业。科技和创新型中小企业具有较高专业化水平、较强研发创新能力和发展潜力，是优质中小企业的基础力量；专精特新中小企业实现专业化、精细化、特色化发展，创新能力强、质量效益好，是优质中小企业的骨干力量；专精特新“小巨人”企业位于产业基础核心领域、产业链关键环节，创新能力突出、掌握核心技术、细分市场占有率高、质量效益优，是优质中小企业的中坚力量。"},{"no":"三","title":"第三条","text":"优质中小企业梯度培育工作，坚持落实“两个毫不动摇”，坚持有效市场和有为政府相结合，坚持专精特新发展方向，坚持分层分类分级指导，坚持动态管理和精准服务。"},{"no":"四","title":"第四条","text":"工业和信息化部负责优质中小企业梯度培育工作的宏观指导、统筹协调和监督检查，推动出台相关支持政策，发布相关认定标准，负责专精特新“小巨人”企业认定工作。各省、自治区、直辖市及计划单列市、新疆生产建设兵团中小企业主管部门（以下统称省级中小企业主管部门）负责本地区优质中小企业培育和专精特新中小企业认定工作。\n其他机构未经授权不得开展与科技和创新型中小企业、专精特新中小企业、专精特新“小巨人”企业有关的认定、授牌等活动。"},{"no":"五","title":"第五条","text":"工业和信息化部建设优质中小企业梯度培育平台（https://zjtx.miit.gov.cn/，以下简称培育平台），搭建优质中小企业数据库。各级中小企业主管部门应通过培育平台组织开展认定工作，加强服务对接和监测分析，跟踪企业运行、发展态势、意见诉求，以及扶持政策与培育成效，有针对性地制定政策和开展精准服务。落实数字政府建设要求，推动数据互通共享，减轻企业数据填报负担。\n第二章 认定程序和认定标准"},{"no":"六","title":"第六条","text":"省级以上中小企业主管部门按照谁推荐、谁把关，谁审核、谁管理方式组织开展优质中小企业认定工作。"},{"no":"七","title":"第七条","text":"专精特新中小企业认定，由科技和创新型中小企业按属地原则自愿申报，省级中小企业主管部门根据专精特新中小企业认定标准（见附件1），组织对企业申请材料和相关佐证材料进行审核、实地核查和公示。公示通过的，由省级中小企业主管部门认定为专精特新中小企业。"},{"no":"八","title":"第八条","text":"专精特新“小巨人”企业认定，由专精特新中小企业按属地原则自愿申报，省级中小企业主管部门根据专精特新“小巨人”企业认定标准（见附件2），组织对企业申请材料和相关佐证材料进行初审、实地核查和公示。公示通过的，向工业和信息化部推荐。工业和信息化部组织对被推荐企业进行审核、抽查和认定。原则上每年第二季度组织开展专精特新“小巨人”企业认定工作。"},{"no":"九","title":"第九条","text":"各级中小企业主管部门应建立健全优质中小企业主动发现机制，充分挖掘产业链供应链、股权投资、知识产权、科技奖项、人才引育等数据，常态化发现潜在优质中小企业，定向邀请其参加认定。认定标准不降低。"},{"no":"十","title":"第十条","text":"在专精特新中小企业认定和专精特新“小巨人”企业推荐工作中，省级中小企业主管部门应健全审核机制、规范全过程管理，组织专家严格对照认定标准，重点对企业申请材料和数据的真实性、准确性、完整性，以及是否符合认定标准等情况进行审核。应采取“双随机”（随机抽取专家组成多个评审专家组、即时随机派发审核任务）形式开展审核，评审专家组应包含一定数量的产业专家和财务专家。"},{"no":"十一","title":"第十一条","text":"申报企业应在中华人民共和国境内依法设立，符合《中小企业划型标准规定》，遵守国家法律法规和行业规范。申报期间未被列入经营异常名录或严重失信主体名单，提供的产品（服务）不属于国家禁止、限制或淘汰类，同时近三年未发生较大生产安全事故、重大网络和数据安全事件、重大环境违法行为、严重质量问题、严重违反相关行业管理规定。应自主、如实申报，按要求填写申请表格并提供必要佐证材料。"},{"no":"十二","title":"第十二条","text":"各级中小企业主管部门及其相关支撑单位应加强宣传培训，指导企业做好申报工作，不得以任何名义直接或变相向申报企业收取费用。"},{"no":"十三","title":"第十三条","text":"各级中小企业主管部门不得将审核认定相关工作委托第三方中介机构承担，应联合相关部门严格防范不良中介机构影响。\n第三章 动态管理"},{"no":"十四","title":"第十四条","text":"省级及以上中小企业主管部门应会同相关部门强化对优质中小企业的运行监测，挖掘利用好金融、信用、司法等各类数据信息，建立健全有进有出的动态管理机制，持续提高优质中小企业发展质量。"},{"no":"十五","title":"第十五条","text":"工业和信息化部按年度对中小企业专精特新发展质量进行评价，并将评价结果纳入中小企业发展环境第三方评估。对于评价得分较低的地区，采取限制推荐名额、控制数量增长等措施。对评价得分较低的企业，加强重点监测。"},{"no":"十六","title":"第十六条","text":"经认定的专精特新中小企业和专精特新“小巨人”企业有效期3年，每次到期前由认定部门组织复核（含实地抽查）。复核通过的，有效期延长3年。"},{"no":"十七","title":"第十七条","text":"有效期内的专精特新中小企业和专精特新“小巨人”企业，可登录培育平台查询认定状态和有效期，并在每年5月31日前通过培育平台更新企业信息。在同一个有效期内，对首次未进行更新的企业，重点监测；对累计达两次未更新的企业，取消认定。"},{"no":"十八","title":"第十八条","text":"有效期内的专精特新中小企业和专精特新“小巨人”企业，如发生合并、重组等与认定条件有关的重大变化，应在发生变化后的3个月内登录培育平台，填写重大变化情况报告表。不再符合认定标准的专精特新中小企业，由省级中小企业主管部门核实后取消认定；不再符合认定标准的专精特新“小巨人”企业，由省级中小企业主管部门核实后报工业和信息化部，由工业和信息化部取消认定。对于未报告重大变化情况的，取消复核资格，或取消认定。"},{"no":"十九","title":"第十九条","text":"有效期内的专精特新中小企业和专精特新“小巨人”企业，如发生简单更名，应在3个月内在培育平台上同步完成名称变更申请。如发生跨区域迁移，应在3个月内在培育平台上提交跨区域迁移申请，并与迁入地中小企业主管部门联系。后续由迁入地中小企业主管部门负责相关培育和服务监测等工作，迁出地中小企业主管部门应做好配合。"},{"no":"二十","title":"第二十条","text":"有效期内的专精特新中小企业和专精特新“小巨人”企业，如发生较大生产安全事故、重大网络和数据安全事件、重大环境违法行为、严重质量问题、严重违反相关行业管理规定、被列入严重失信主体名单，或被发现存在数据造假情形，取消认定且三年内不得再次申报。对取消认定后完成信用修复并移出严重失信主体名单的企业，以及按照行业管理规定要求完成整改并获得相关行业管理部门认可的企业，可以三年内再次申报。"},{"no":"二十一","title":"第二十一条","text":"各级中小企业主管部门应完善机制，加强对优质中小企业的风险监测与处置，涉及专精特新“小巨人”企业的重大风险，应及时上报工业和信息化部。"},{"no":"二十二","title":"第二十二条","text":"任何组织和个人可针对优质中小企业相关信息真实性、准确性等方面存在的问题，向负责该企业认定的中小企业主管部门实名举报，并提供佐证材料和联系方式。对受理的举报内容，中小企业主管部门应及时向被举报企业核实。被举报企业未按要求回复或经核查举报内容属实的，视情节轻重要求企业整改，或取消认定。\n第四章 培育服务"},{"no":"二十三","title":"第二十三条","text":"各级中小企业主管部门应着力把功夫下到培育和服务上，坚持质量为先，不层层设定培育数量指标。针对本地区不同发展阶段、不同类型中小企业的特点和需求，强化政策支持、健全服务体系、完善企业治理和加强权益保护，不断优化中小企业发展环境，促进中小企业专精特新发展。"},{"no":"二十四","title":"第二十四条","text":"各级中小企业主管部门应认真贯彻落实建设全国统一大市场和规范招商引资行为有关政策要求，加强部门协同、上下联动。统筹运用财税、金融、科技、产业、人才等政策工具，加强用地、用能、用数等要素保障，着力推动惠企政策“免申即享、直达快享”，提高政策精准性和有效性。"},{"no":"二十五","title":"第二十五条","text":"各级中小企业主管部门应着力构建公共服务与市场化服务相互促进的服务体系。推动各级中小企业公共服务机构扩面提质，共同打造线上线下深度融合的全国中小企业服务网，提升服务覆盖面和企业获得感。发挥国家中小企业公共服务示范平台（基地）、中小企业特色产业集群、科技型企业孵化器、校企协同育人基地等平台载体作用，坚持中小企业需求导向，聚焦技术创新、大中小企业融通、数智化转型、权益保护、市场开拓、融资促进、管理提升、国际化发展等领域，提供精准高效公共服务。建立健全服务专员队伍，加强优质中小企业对口联系帮扶。广泛汇聚市场化服务资源，鼓励引导市场化服务机构提高服务标准化、规范化、精准化水平，不断丰富服务产品、提升服务质量。"},{"no":"二十六","title":"第二十六条","text":"各级中小企业主管部门应加强指导，强化人才教育培训，通过政府购买专业机构服务等方式加强面向中小企业的经营管理诊断、精益生产等咨询服务，促进中小企业提升公司治理和经营管理水平。充分发挥企业党组织作用，大力弘扬企业家精神、工匠精神和工程师文化，提升企业凝聚力和竞争力。"},{"no":"二十七","title":"第二十七条","text":"各级中小企业主管部门应积极会同有关部门强化落实支持中小企业发展的有关法律制度，依法保护中小企业产权和知识产权等合法权益。"},{"no":"二十八","title":"第二十八条","text":"在企业认定和培育服务过程中，各级中小企业主管部门及其相关工作人员应当保护企业商业秘密。\n第五章 附则"},{"no":"二十九","title":"第二十九条","text":"与优质中小企业产生投融资、并购重组、交易合作等相关市场行为，由相关主体自主决策、自行负责。"},{"no":"三十","title":"第三十条","text":"科技和创新型中小企业有关要求和标准，以工业和信息化部联合有关部门制定发布的文件为准。在相关文件发布前，科技和创新型中小企业涵盖有效期内的科技型中小企业和创新型中小企业，相关工作继续按照原有标准、工作程序和职责分工开展。"},{"no":"三十一","title":"本办法自2026年4月1日起实施","text":"本办法自2026年4月1日起实施。原《优质中小企业梯度培育管理暂行办法》中涉及专精特新中小企业和专精特新“小巨人”企业相关条款和认定标准同时废止。在本办法实施前认定的专精特新中小企业和专精特新“小巨人”企业继续有效，有效期到期后自动失效，失效后按本办法重新认定或复核。"},{"no":"三十二","title":"本办法由工业和信息化部负责解释","text":"本办法由工业和信息化部负责解释。\n附件1\n专精特新中小企业认定标准\n需同时满足以下六项指标：\n（一）已获得科技和创新型中小企业称号，截至上年末从事特定细分市场时间达3年以上。\n（二）上年度营业收入总额达1500万元以上或近两年新增股权投资（合格机构投资者的实缴额）总额2000万元以上，主营业务收入总额占营业收入总额比重不低于80%，上年末资产负债率不超过80%。\n（三）近两年研发费用均不低于100万元，且每年占营业收入比重均不低于3%。\n（四）拥有1项以上与主导产品相关的Ι类知识产权，且实际应用并已产生经济效益。对近三年获得省部级以上科学技术奖励（排名前三）或拥有经认定的省部级以上研发机构的企业，不考察本项指标。\n（五）主导产品在国内或国际细分市场占有率较为靠前，且享有一定知名度、影响力。\n（六）本年度中小企业专精特新发展评价得分达50分以上（复核企业近两年任意一年达50分以上即可）。指标体系见《中小企业专精特新发展评价指标体系（试行）》。\n附件2\n专精特新“小巨人”企业认定标准\n需同时满足以下七项指标：\n（一）已获得专精特新中小企业称号，截至上年末从事特定细分市场时间达3年以上。\n（二）上年度营业收入总额达5000万元以上，主营业务收入总额占营业收入总额比重不低于90%。近两年营业收入复合增长率不低于5%（复核企业不考查该项指标），上年末资产负债率不超过75%。\n（三）近两年研发费用合计不低于1200万元，且每年占营业收入比重均不低于3%。\n（四）拥有4项以上与主导产品相关的Ι类知识产权，且实际应用并已产生经济效益。对近三年获得国家级科技奖励（排名前三）的企业，不考察本项指标。\n（五）主导产品在国内或国际细分市场占有率达到10%以上或国内前三名，且享有较高知名度、影响力。\n（六）主导产品属于制造业核心基础零部件、核心基础元器件、关键软件、先进基础工艺、关键基础材料、产业技术基础，或属于改造提升传统产业、培育壮大新兴产业、布局建设未来产业，位于产业链关键环节，对提升产业链供应链韧性和安全水平发挥重要作用。\n（七）本年度中小企业专精特新发展评价得分达60分以上（复核企业近两年任意一年达60分以上即可）。指标体系见《中小企业专精特新发展评价指标体系（试行）》。"}],"interpretations":[{"sectionNo":"九","headline":"主管部门会主动发现企业、定向邀请认定，但标准不降","who":"各级中小企业主管部门；被挖掘发现的潜在优质中小企业。","materials":[],"window":"常态化开展。","where":"各级中小企业主管部门。","tip":"主动发现不等于降低门槛——文件明确「认定标准不降低」，被邀请也要按标准评。"},{"sectionNo":"十","headline":"评审「双随机」派任务，材料真实性是重点","who":"申报专精特新中小企业认定、专精特新「小巨人」推荐的企业。","materials":["申请材料与相关数据（须真实、准确、完整）"],"window":"按年度认定与推荐工作安排。","where":"省级中小企业主管部门组织专家评审。","tip":"评审采用「双随机」——随机抽专家、随机派任务，专家组里会有产业专家和财务专家，财务数据对不上很容易被挑出来。"},{"sectionNo":"二","headline":"优质中小企业分科技和创新型、专精特新、小巨人三类","who":"在产品、技术、工艺、管理、模式等方面创新能力强、专注细分市场、成长性好的中小企业；三类分别为科技和创新型中小企业（基础力量）、专精特新中小企业（骨干力量）、专精特新“小巨人”企业（中坚力量）。","materials":[],"window":"长期适用的分类定义，原文未设申报期限","where":"原文未列具体受理部门或系统","tip":"三类企业构成梯度：科技和创新型中小企业是基础力量，专精特新中小企业是骨干力量，专精特新“小巨人”企业是中坚力量。"},{"sectionNo":"五","headline":"认定统一在培育平台办理，企业数据一次填报共享","who":"各级中小企业主管部门组织认定所涉的中小企业；企业通过培育平台办理认定相关事项。","materials":[],"window":"认定按批次通过培育平台组织，原文未设具体期限","where":"优质中小企业梯度培育平台（https://zjtx.miit.gov.cn/）","tip":"平台搭建优质中小企业数据库并推动数据互通共享，减轻企业数据填报负担。"},{"sectionNo":"七","headline":"科技和创新型中小企业按属地自愿申报专精特新，省级审核公示","who":"已获得科技和创新型中小企业称号、按属地原则自愿申报的中小企业；由省级中小企业主管部门按专精特新中小企业认定标准（附件1）审核、实地核查并公示。","materials":["企业申请材料","相关佐证材料"],"window":"按批次申报，公示通过后由省级中小企业主管部门认定；原文未设具体申报期限","where":"省级中小企业主管部门（按属地原则申报）","tip":"公示通过的才由省级中小企业主管部门认定为专精特新中小企业；认定标准见附件1。"},{"sectionNo":"八","headline":"专精特新企业申报小巨人，每年第二季度组织认定","who":"已获得专精特新中小企业称号、按属地原则自愿申报的企业；经省级中小企业主管部门初审、实地核查和公示后向工业和信息化部推荐，由工业和信息化部审核、抽查和认定。","materials":["企业申请材料","相关佐证材料"],"window":"原则上每年第二季度组织开展认定；公示通过后推荐，具体申报期原文未列","where":"省级中小企业主管部门；工业和信息化部","tip":"须先取得专精特新中小企业称号才能申报小巨人；认定标准见附件2。"},{"sectionNo":"十一","headline":"申报须境内依法设立、未入异常名录，近三年无重大事故","who":"在中华人民共和国境内依法设立、符合《中小企业划型标准规定》、遵守国家法律法规和行业规范的中小企业；申报期间未被列入经营异常名录或严重失信主体名单，提供的产品（服务）不属于国家禁止、限制或淘汰类，近三年未发生较大生产安全事故、重大网络和数据安全事件、重大环境违法行为、严重质量问题、严重违反相关行业管理规定。","materials":["申请表格","必要佐证材料"],"window":"申报期间核查上述状态，近三年为追溯期","where":"原文未列具体受理部门或系统","tip":"须自主、如实申报；经营异常、严重失信、产品属禁止限制淘汰类或近三年有重大事故的，均不符合申报条件。"},{"sectionNo":"十二","headline":"申报认定不收费，部门不得变相向申报企业收费","who":"申报优质中小企业的企业；各级中小企业主管部门及其相关支撑单位不得以任何名义直接或变相向申报企业收取费用。","materials":[],"window":"申报全过程适用，原文未设期限","where":"各级中小企业主管部门及其相关支撑单位","tip":"遇到以申报为名收取费用的，可拒绝支付；原文明确不得直接或变相收取费用。"},{"sectionNo":"十六","headline":"专精特新及小巨人有效期3年，复核通过延长3年","who":"经认定的专精特新中小企业和专精特新“小巨人”企业；须在有效期到期前接受认定部门复核（含实地抽查）。","materials":[],"window":"有效期3年；每次到期前复核，复核通过的延长3年。","where":"认定部门（省级中小企业主管部门、工业和信息化部）","tip":"复核含实地抽查；复核通过才延长有效期。"},{"sectionNo":"十七","headline":"每年5月31日前更新企业信息，两次未更新取消认定","who":"有效期内的专精特新中小企业和专精特新“小巨人”企业。","materials":[],"window":"每年5月31日前通过培育平台更新企业信息；同一有效期内累计两次未更新即取消认定。","where":"优质中小企业梯度培育平台（培育平台）","tip":"首次未更新只作重点监测；累计达两次未更新的取消认定。"},{"sectionNo":"十八","headline":"合并重组等重大变化须3个月内报告，否则取消复核资格","who":"有效期内的专精特新中小企业和专精特新“小巨人”企业；发生合并、重组等与认定条件有关的重大变化的。","materials":["重大变化情况报告表"],"window":"变化发生后3个月内登录培育平台填报；未报告的取消复核资格或取消认定。","where":"培育平台；省级中小企业主管部门；工业和信息化部","tip":"不再符合认定标准的，专精特新由省级部门核实后取消，小巨人由省级部门报工业和信息化部取消。"},{"sectionNo":"十九","headline":"更名或跨区域迁移须3个月内在培育平台办理","who":"有效期内发生简单更名或跨区域迁移的专精特新中小企业和专精特新“小巨人”企业。","materials":[],"window":"更名、跨区域迁移均须在3个月内通过培育平台办理。","where":"培育平台；迁入地、迁出地中小企业主管部门","tip":"迁移须同时与迁入地中小企业主管部门联系，后续培育和服务监测由迁入地负责。"},{"sectionNo":"二十","headline":"发生重大事故、失信或数据造假的取消认定，三年内不得再报","who":"有效期内的专精特新中小企业和专精特新“小巨人”企业；发生较大生产安全事故、重大网络和数据安全事件、重大环境违法行为、严重质量问题、严重违反相关行业管理规定、被列入严重失信主体名单，或存在数据造假情形的。","materials":[],"window":"取消认定后三年内不得再次申报；完成信用修复并移出严重失信主体名单、或整改获行业管理部门认可的，可三年内再次申报。","where":"认定部门（省级中小企业主管部门、工业和信息化部）","tip":"完成信用修复并移出严重失信主体名单，或按行业管理规定完成整改并获得认可的企业，可以三年内再次申报。"},{"sectionNo":"二十二","headline":"被举报须按要求回复，核查属实可被取消认定","who":"优质中小企业（被举报对象）；任何组织和个人可实名举报并提供佐证材料和联系方式。","materials":["佐证材料","联系方式（举报时提供）"],"window":"受理后主管部门及时向被举报企业核实；被举报企业须按要求回复。","where":"负责该企业认定的中小企业主管部门","tip":"未按要求回复或经核查举报属实的，视情节轻重要求企业整改或取消认定。"},{"sectionNo":"三十","headline":"科技和创新型中小企业暂按科技型、创新型中小企业执行","who":"有效期内的科技型中小企业和创新型中小企业；在工业和信息化部联合有关部门发布科技和创新型中小企业有关要求和标准前，按原有标准、工作程序和职责分工开展。","materials":[],"window":"相关文件发布前适用；原文未设截止日期","where":"工业和信息化部（会同有关部门制定发布文件）","tip":"新文件发布后以新文件为准；发布前已认定的科技型、创新型中小企业仍属科技和创新型中小企业。"},{"sectionNo":"三十二","headline":"专精特新须六项指标：营收1500万元或股权融资2000万元","who":"专精特新中小企业须同时满足六项：已获科技和创新型中小企业称号且截至上年末从事特定细分市场3年以上；上年度营业收入1500万元以上或近两年新增股权投资2000万元以上，主营业务收入占比不低于80%，上年末资产负债率不超过80%；近两年研发费用均不低于100万元且每年占营业收入比重不低于3%；拥有1项以上与主导产品相关的Ι类知识产权并已应用产生效益；主导产品细分市场占有率较为靠前；本年度专精特新发展评价得分50分以上。专精特新“小巨人”须同时满足七项：已获专精特新中小企业称号且从事特定细分市场3年以上；上年度营业收入5000万元以上，主营业务收入占比不低于90%，近两年营业收入复合增长率不低于5%，上年末资产负债率不超过75%；近两年研发费用合计不低于1200万元且每年占比不低于3%；拥有4项以上Ι类知识产权；细分市场占有率达到10%以上或国内前三名；主导产品属制造业核心基础零部件、核心基础元器件、关键软件、先进基础工艺、关键基础材料、产业技术基础等领域；本年度评价得分60分以上。","materials":[],"window":"按年度评价认定；专精特新本年度得分须达50分以上（复核企业近两年任意一年达50分即可），小巨人须达60分以上。","where":"省级中小企业主管部门（专精特新认定）；工业和信息化部（小巨人认定）","tip":"近三年获省部级以上科学技术奖励（排名前三）或拥有经认定的省部级以上研发机构的，不考察知识产权指标；小巨人近三年获国家级科技奖励（排名前三）同样不考察该项。"}],"sourceUrl":"https://gxt.hunan.gov.cn/gxt/xxgk_71033/zcfg/gjjfg/202606/t20260615_34002090.html","sourceNote":"条文已于 2026-11-09 与官方页面/PDF 逐句比对，逐字一致（明细见 采集包/条文核对表.md）","verified":false,"isSample":false,"numberStyle":"clause","bodyVerified":"verbatim","hunan":false},{"id":"p-2026-76cd70","title":"衡阳市人民政府关于印发《关于全面落实“三高四新”美好蓝图进一步推动制造业高质量发展的若干支持政策》的通知","level":"city","region":"衡阳市","issuer":"衡阳市人民政府","documentNo":"衡政发〔2026〕1号","publishedAt":"2026-03-03","status":"active","tags":["认定资质","专项资金","研发创新"],"audience":["小微企业","高校毕业生"],"summary":"衡阳对新获评国家级、省级专精特新中小企业分别给予15万元、5万元奖励；国家专精特新“小巨人”项目最高补助30万元；数字化转型项目最高贴息60万元。","sections":[{"no":"一","title":"聚焦产业培塑，推动制造业提档升级","text":"聚焦产业培塑，推动制造业提档升级\n1.支持设备更新和技术改造。持续用力打造先进制造业高地，力促规模工业企业\"原地倍增\"，引导企业实施智能化、绿色化、融合化及本质安全改造等设施更新和技术改造项目。支持企业争取中央设备更新贷款贴息、省级工业企业设备更新和技术改造融资补贴，用足用好超长期特别国债资金，促进工业、电子信息、能源电力等重点领域企业加快更新改造步伐。\"原地倍增\"企业实施设备更新和技术改造项目，当年项目总投资达到200万元以上的，市级财政对项目一年期(含)以上贷款按贷款本金的2%给予贴息，单个企业最高不超过200万元；申请贷款贴息项目，设备投资占贷款金额比例应不低于30%。同一项目只能享受中央、省级、市级融资补贴中的一项。(责任部门:市工信局)\n2.推进企业加快数字化转型。深化\"智赋万企\"行动，提升中小企业数字化水平及核心竞争力，对数字化转型升级项目，年投资在200万元以上，单个企业自贷款合同签订后首次付息日起连续12个月按照年基准利率的60%予以贴息补助，最高不超过60万元(\"原地倍增\"贴息、数字化转型贴息原则上不重复享受)。支持开展数字化转型咨询诊断，鼓励企业争取省级诊断服务费补贴资金。(责任部门:市工信局)\n对新获评国家工信部相关试点示范项目、省级工业互联网平台、省级\"5G+工业互联网标杆工厂\"，给予每家最高不超过10万元奖励。对新获评\"两化\"融合管理体系贯标企业、数字化转型成熟度贯标企业、省级人工智能赋能新型工业化典型应用场景企业、省级数字新基建项目，给予每家不超过5万元奖励。带动产业链上下游更多配套中小企业\"上云上平台\"，培育\"上云上平台\"示范企业，给予每家不超过5万元补助。对通过工业互联网网络安全分类分级管理考核或工业和信息化领域数据安全管理考核的企业，给予每家不超过2万元补助。(责任部门:市工信局)\n3.培育壮大市场主体。对首次认定的规模以上工业企业，每家给予10万元的达规入统奖励。首次认定的资质等级建筑业企业、资质等级房地产开发企业、限额以上批零住餐企业、规模以上服务业企业每家分别给予2万元的达规入统奖励。培育专精特新企业，对新获评的国家级、省级专精特新中小企业分别给予15万元、5万元奖励。支持中小企业专精特新发展，推动中小企业转型升级，对国家专精特新\"小巨人\"企业、湖南省专精特新中小企业专精特新发展类项目按项目建设支出比例分别给予最高不超过30万元、20万元补助。支持举办\"创客中国\"衡阳市中小微企业创新创业大赛。加强中小企业服务体系建设，支持省级核心服务机构提升服务能力或开展相关服务业务，根据服务能力建设支出或服务业务支出规模进行补助，最高可补助10万元。降低企业上市股改税费成本，支持企业改制重组依规享受契税、土地增值税、所得税等相关减免与税务处理政策。积极推动企业依规申报多层次资本市场建设奖补资金。(责任部门:市政府办、市工信局、市发改委、市住建局、市商务局、市统计局、市税务局)\n4.打造制造业标杆企业。推动智能制造关键核心技术攻关，助力企业提升发展优势及市场份额，对新获评国家智能制造系统解决方案\"揭榜挂帅\"企业给予20万元奖励。对新认定的国家级、省级制造业单项冠军分别给予20万元、10万元奖励。对新认定的卓越级智能工厂、先进级智能工厂分别给予每家10万元、5万元奖励。鼓励企业开展产品全生命周期绿色管理，构建绿色制造体系，对新认定的省级绿色工厂、绿色供应链管理企业给予10万元奖励。对新认定的省级、市级消费品\"三品\"标杆企业，分别给予10万元、5万元奖励。对当年认定为湖南省首台套重大技术装备、首批次重点新材料、首版次软件、首套件基础电子元器件、首轮次工程流片芯片(简称\"五首\")产品的企业，给予每家不超过10万元奖励。对新增的\"军工资质\"企业给予10万元奖励；对国、省级军民融合示范项目企业，分别给予20万元、10万元奖励。(责任部门:市工信局、市委军民融合办)"},{"no":"二","title":"激发企业活力，增强科技创新发展动能","text":"激发企业活力，增强科技创新发展动能\n5.提升技术创新水平。对首次、再次获得认定的高新技术企业分别一次性奖励10万元、3万元。培育国省科技奖励企业，对入选企业给予10万元奖励；支持科技创新重大项目，每个给予30万元奖励；支持重点研发项目，每个给予10万元奖励；支持基础应用研究，每项给予3万元奖励。设立400万元企业研发费用辅导专项资金，支持县市区辅导企业建立规范的研发费用归集机制并做好会计辅助账。设立科技成果转化专项经费100万元，支持科技成果转化及转化服务能力提升项目。支持企业引进科技人才，支持举办\"双创大赛\"，营造创新创业氛围，提升企业创新创业水平。(责任部门:市科技局)\n6.促进产学研用深度融合。鼓励各产业链领军企业与相关高校、科研院所开展产学研合作，组建创新联合体。对重点产学研合作项目、一般产学研合作项目分别给予30万元、10万元补助，创新联合体给予20万元补助。对新认定的重点实验室、技术创新中心，按照国家级50万元、省级20万元标准，分别给予一次性奖励；对新列入的国家、省级科技孵化器，分别给予30万元、10万元项目资助；对新认定的工程研究中心、企业技术中心(发改部门评定)，按照国家级50万元、省级20万元标准，分别给予一次性奖励；对新认定的省级企业技术中心、省级工业设计中心(工信部门评定)，给予10万元奖励。统筹设立专项资金1亿元，支持衡阳智能衡器计量产业园加快建设国家计量人才实训中心、国家产业计量测试中心等公共技术平台，围绕产业发展开展技术攻关和应用示范；鼓励衡阳智能衡器计量产业园与知名院校、科研院所在人才培养、技术创新等方面开展合作，提高产业集聚程度。(责任部门:市科技局、市发改委、市工信局、衡阳智能衡器计量产业园)\n7.强化标准引领作用。鼓励企业积极参与标准制定，对主持、参与标准制定的企业进行奖励。对主持制定国际标准、国家标准的企业给予奖励，最高不超过40万元；参与制定国际标准、国家标准的企业，最高不超过15万元；主持、参与制定行业标准的企业，最高不超过15万元、10万元；主持、参与制定湖南省地方标准的企业，最高不超过10万元、5万元奖励(同一企业同一标准不重复奖励，累计奖励不超过100万元)。支持企业争创质量奖，对首次获得中国质量奖、省长质量奖、市长质量奖、湖南名品的企业，分别给予50万元、30万元、10万元、10万元奖励。利用物联网、云计算、大数据等技术手段，积极打造数字化、信息化、智能化的\"阳光计量\"交易及监管模式。(责任部门:市市场监管局、衡阳智能衡器计量产业园)\n8.推动知识产权量质齐升。提升知识产权创造运用水平及服务管理能力，对知识产权强链增效项目按10万元/个进行补助，对知识产权重点企业保护项目按6万元/个进行补助，对地理标志运用保护培育工程项目按6万元/个进行补助，对高价值发明专利培育及专利转化运用项目按10万元/个进行补助，对公共服务平台建设项目按10万元/个进行补助，对知识产权优质服务机构建设项目按5万元/个进行补助。对海外知识产权保护项目按6万元/个进行补助。对经国家知识产权局质押登记的专利、商标、数据知识产权质押融资予以补助，根据单笔融资额的0.2%予以补助，最高不超过3万元。(责任部门:市市场监管局)"},{"no":"三","title":"改善融资环境，提升金融服务质效","text":"改善融资环境，提升金融服务质效\n9.发挥产业基金带动效应。树立全市产业基金\"一盘棋\"思想，深化财政资金\"拨改投\"改革，精准布局战略性新兴产业，培育壮大耐心资本，以市场化基金运作方式支持企业发展。强化联动协同，对接省级金芙蓉等基金资源，协同已参股子基金形成合力，并推动有条件的县市区(园区)出资入股，支持市属国企围绕主业设立相关基金，共同扩大惠企资本供给。畅通产融对接，建立由市发改、工信、商务等部门及各园区负责的重点产业链优质项目定期推送机制，引导基金提前介入、予以支持。优化激励与风险管控，在坚守政策目标与资金安全底线的前提下，对实现综合超额收益的基金，可在收益分配上对管理机构及社会出资人给予适当让利，吸引更多社会资本参与企业培育。(责任部门:市发改委、市工信局、市财政局、市商务局、市国资委)\n10.落实创(就)业补贴政策。通过财政贴息引导金融机构加大创业担保贷款投放。对符合创业担保贷款条件的小微企业，按照贷款合同签订日贷款利率(且贷款利率在LPR+150PB以内)的50%给予贴息，贷款额度最高为400万元；贷款期限最长不超过2年；已享受过创业担保贷款政策的小微企业，贷款无逾期还清后可再次享受创业担保贷款，累计次数不得超过3次，再次享受时吸纳就业人员不得与之前申请时吸纳人员重复。落实财政补助支持实施各项就业扶持政策，对符合条件人员参加职业技能培训、高技能人才培训基地和技能大师工作室建设、公共就业服务机构服务能力建设等给予就业创业服务补助。鼓励用人单位吸纳就业，对就业见习、自主创业、就业参保给予补贴。按规定对就业困难人员、困难高校毕业生给予求职帮扶补贴。(责任部门:市财政局、市人社局)\n11.完善政府性融资担保体系。为企业提供融资担保和\"临时性超短期贷款\"(转贷)服务，备案担保项目单户融资担保金额原则上不超过1500万元，对于符合\"民间投资专项担保计划\"的担保额度最高可达2000万元(期限1年以上)，对于科技创新型中小企业单户融资担保金额最高可达3000万元。大力推广\"人才创业贷款担保\"等金融产品，为毕业5年内在我市中心城区自主创业、合伙经营的大学生提供30-110万元融资担保政策；为招用高校毕业生达到一定数量的小微企业提供最高500万元融资担保贷款，对担保费予以优惠。推动普惠金融高质量发展，依托普惠金融发展专项资金，加大对市融资担保公司资本注入力度，鼓励市融资担保公司及市小额贷款公司为中小微企业提供低费用非融资保函等服务，促进政府融资担保扩围加力。(责任部门:市财政局、市融资担保公司)"},{"no":"四","title":"强化服务保障，助力企业降本增效","text":"强化服务保障，助力企业降本增效\n12.优化政府采购环境。符合法定条件的供应商凭《湖南省政府采购供应商资格承诺函》参与政府采购活动，免收投标保证金及采购文件工本费。中小企业凭《中小企业申明函》享受相关评审价格扣除优惠政策。采取保函、电子增信等非现金形式缴纳合同履约保证金，对资信良好的中标企业，鼓励支持采购单位免收履约保证金。预算200万元以下的货物、服务项目和400万元以下的工程项目适宜由中小企业提供的，应面向中小企业采购；上述标准以上的项目适宜由中小企业提供的，应预留40%以上的份额专门面向中小企业，其中小微企业不低于60%。全面推行政府采购贷，中标企业凭政府采购中标通知书和政府采购合同，在湖南政府采购网衡阳分网线上融资平台上自主选择金融机构进行政府采购合同融资。搭建政府采购全流程查询与线上投诉平台，供应商可即时查询相关信息，提升政府采购的公开透明程度。(责任部门:市财政局)\n以上措施自公布之日起实施，有效期至2028年12月31日。执行过程中，如上级及我市另行出台文件对政策期限进行规定的，从其规定。本文件按现行财政体制按比例分级负担，市财政统一结算。各责任部门要结合自身职责职能制定实施细则，实行全程跟踪服务，加强政策宣传和对接，确保政策直达快享，力争各项政策的施行取得更大实效，进一步助推全市制造业高质量发展。"}],"interpretations":[{"sectionNo":"一","headline":"「原地倍增」企业技改贷款，市财政按本金2%贴息、最高200万元","who":"衡阳市「原地倍增」企业实施设备更新和技术改造项目，当年项目总投资达到200万元以上，且取得一年期（含）以上贷款。","materials":[],"window":"按年度项目申报安排。","where":"市工信局。","tip":"设备投资占贷款金额比例不低于30%；同一项目只能享受中央、省级、市级融资补贴中的一项，不能叠加。"},{"sectionNo":"一","headline":"数字化转型项目按年基准利率60%贴息，最高60万元","who":"衡阳市实施数字化转型升级项目、年投资200万元以上的企业。","materials":[],"window":"自贷款合同签订后首次付息日起连续12个月。","where":"市工信局。","tip":"「原地倍增」贴息与数字化转型贴息原则上不重复享受；获评省级工业互联网平台、5G+工业互联网标杆工厂等另有最高10万元奖励。"},{"sectionNo":"三","headline":"小微企业创业担保贷款，按合同利率50%贴息、最高400万元","who":"符合创业担保贷款条件的衡阳市小微企业；贷款利率在 LPR+150BP 以内。","materials":[],"window":"贷款期限最长不超过2年；已享受过且无逾期还清的，可再次享受，累计不超过3次。","where":"市财政局、市人社局及经办银行。","tip":"再次享受时吸纳的就业人员不得与之前申报时的人员重复。"},{"sectionNo":"二","headline":"高企首次认定奖10万元，再次认定奖3万元","who":"衡阳市域内企业及项目主体：首次、再次获得认定的高新技术企业；入选国省科技奖励企业、科技创新重大项目、重点研发项目、基础应用研究项目；重点产学研合作项目、一般产学研合作项目及创新联合体；新认定的重点实验室、技术创新中心、国家或省级科技孵化器、工程研究中心、企业技术中心、省级企业技术中心、省级工业设计中心；主持或参与标准制定的企业；首次获得中国质量奖、省长质量奖、市长质量奖、湖南名品的企业；知识产权强链增效、重点企业保护、地理标志运用保护培育、高价值发明专利培育及专利转化运用、公共服务平台、优质服务机构、海外知识产权保护等项目承担单位，以及经国家知识产权局质押登记的专利、商标、数据知识产权质押融资企业。","materials":[],"window":"认定或入选后一次性奖励/补助，原文未规定申报起止时间","where":"市科技局、市发改委、市工信局、市市场监管局、衡阳智能衡器计量产业园（按事项分别负责）","tip":"同一企业同一标准不重复奖励，标准制定累计奖励不超过100万元；标准制定奖励为最高限额（主持国际标准、国家标准最高40万元，参与最高15万元）；知识产权质押融资按单笔融资额0.2%补助，最高不超过3万元。"},{"sectionNo":"四","headline":"200万元以下货物服务项目应面向中小企业采购","who":"符合法定条件的政府采购供应商（凭《湖南省政府采购供应商资格承诺函》参与，免收投标保证金及采购文件工本费）；中小企业（凭《中小企业申明函》享受评审价格扣除）；小微企业（预留份额中不低于60%）；中标企业（凭中标通知书和政府采购合同办理政府采购合同融资，资信良好的可免收履约保证金）。","materials":["《湖南省政府采购供应商资格承诺函》","《中小企业申明函》","政府采购中标通知书","政府采购合同"],"window":"自公布之日起实施，有效期至2028年12月31日","where":"湖南政府采购网衡阳分网线上融资平台；采购单位（免收履约保证金）；市财政局（责任部门）","tip":"200万元以下货物、服务项目和400万元以下工程项目适宜由中小企业提供的应面向中小企业采购；标准以上的项目应预留40%以上份额专门面向中小企业，其中小微企业不低于60%；有效期至2028年12月31日。"}],"sourceUrl":"https://www.hunan.gov.cn/zqt/zcsd/202610/t20261023_34087305.html","sourceNote":"条文已于 2026-11-09 与官方页面/PDF 逐句比对，逐字一致（明细见 采集包/条文核对表.md）","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"p-2026-d6dec6","title":"关于组织开展2026年湖南省专精特新中小企业申报和复核工作的通知","level":"provincial","region":"湖南省","issuer":"湖南省工业和信息化厅","documentNo":"","publishedAt":"2026-01-27","status":"active","tags":["认定资质"],"audience":["小微企业"],"summary":"申报企业应在湖南省内工商登记注册、符合《专精特新中小企业认定标准》且须是省工业和信息化厅已公告的湖南省创新型中小企业，申报（复核）时间为2026年1月28日—2026年3月4日，须在优质中小企业梯度培育平台完成数字化水平评测后线上申报。","sections":[{"no":"一","title":"条件标准","text":"1、申报企业应在湖南省内工商登记注册，具有独立法人资格，符合《中小企业划型标准规定》。\n\n2、企业未被列入经营异常名录或严重失信主体名单，提供的产品（服务）不属于国家禁止、限制或淘汰类，同时近三年未发生重大安全（含网络安全、数据安全）、质量、环境污染等事故以及偷漏税等违法违规行为。\n\n3、坚持企业自愿原则，符合《专精特新中小企业认定标准》（工信部企业〔2022〕63号，附件1）。\n\n4、重点聚焦制造强国重点产业（新一代信息技术产业、高档数控机床和机器人、航空航天装备、海洋工程装备及高技术船舶、先进轨道交通装备、节能与新能源汽车、电力装备、农机装备、新材料、生物医药及高性能医疗器械）、工业“六基”（核心基础零部件、核心基础元器件、关键软件、先进基础工艺、关键基础材料、产业技术基础）、“4×4”现代化产业体系（现代石化、绿色矿业、食品加工、轻工纺织4大传统产业，工程机械、轨道交通装备、现代农业、文化旅游4大优势产业，数字、新能源、大健康、空天海洋4大新兴产业，以及人工智能、生命工程、量子科技、前沿材料4大未来产业）等领域。"},{"no":"二","title":"申报（复核）时间","text":"2026年1月28日-2026年3月4日"},{"no":"三","title":"申报（复核）方式","text":"1、申报企业须是省工业和信息化厅已公告的湖南省创新型中小企业。有效期内的专精特新中小企业（湖南省专精特新“小巨人”企业）、专精特新“小巨人”企业不再申报。\n\n2、本次复核的企业为2022年、2023年认定和复核的湖南省专精特新“小巨人”企业，复核公告文件发布之前，企业仍属于有效期内的专精特新中小企业。有效期内的国家级专精特新“小巨人”企业无需参与复核。\n\n3、按属地原则，申报（复核）企业须首先在优质中小企业梯度培育平台（https://zjtx.miit.gov.cn/，以下称“培育平台”）完成数字化水平评测，然后在培育平台进行线上申报和复核，完整填写《专精特新中小企业申请书》，并打包上传佐证材料（附件2）。"},{"no":"四","title":"有关要求","text":"1、各市州工信部门要高度重视专精特新中小企业培育工作，认真履行职责，坚持条件标准，严格审核把关，确保申报（复核）质量。\n\n2、请各市州工信部门于3月4日前在培育平台提交审核意见，并将专精特新中小企业推荐函和汇总表（附件3，纸质件2份）报省工业和信息化厅，逾期不候。\n\n3、严禁弄虚作假。申报（复核）企业对申报材料的完整性、真实性、合法性负责，相关后果由申报（复核）企业自行承担。凡在申报（复核）过程中存在弄虚作假行为的，一经发现，取消本年度申报（复核）资格，并且三年内不得再次申报。\n\n4、严禁代理申报。省工业和信息化厅从未委托任何单位或个人为企业代理申报事宜，请相关企业按程序自主申报。凡委托代理申报的，一经发现，取消参评资格，且三年内不得再次申报。各级工信部门受理申报申请，不收取任何费用。如有任何中介机构或个人假借单位或工作人员名义向企业进行推销或收取费用的，请谨防欺诈，避免上当受骗，并请向当地相关部门举报。任何单位不得以参加收费培训班或解读班作为企业申报前提条件。\n\n联系电话：0731-88955419\n\n邮寄地址：长沙市天心区新韶东路467号\n\n培育平台相关问题咨询电话：85559832"}],"interpretations":[{"sectionNo":"一","headline":"2026 年省级专精特新申报：先看是不是已公告的创新型中小企业","who":"在湖南省内工商登记注册、具有独立法人资格、符合中小企业划型标准的企业；未列入经营异常名录或严重失信名单，近三年无重大安全、质量、环境污染事故及偷漏税违法。","materials":[],"window":"2026年1月28日至3月4日。","where":"优质中小企业梯度培育平台（zjtx.miit.gov.cn）线上申报。","tip":"申报企业须是省工信厅已公告的湖南省创新型中小企业；已是有效期内专精特新中小企业或「小巨人」的，不再申报。"},{"sectionNo":"三","headline":"复核对象是 2022、2023 年认定的省级「小巨人」","who":"本次复核针对 2022 年、2023 年认定和复核的湖南省专精特新「小巨人」企业；有效期内的国家级专精特新「小巨人」企业无需复核。","materials":["《专精特新中小企业申请书》","佐证材料（按附件2准备，打包上传）"],"window":"2026年1月28日至3月4日；复核公告发布前，企业仍属有效期内专精特新中小企业。","where":"优质中小企业梯度培育平台，按属地原则申报。","tip":"申报和复核都要先完成数字化水平评测，否则平台里走不下去。"},{"sectionNo":"二","headline":"2026年1月28日至3月4日申报湖南省专精特新中小企业","who":"2026年申报（复核）湖南省专精特新中小企业的企业；须在申报期内完成申报（复核）。","materials":[],"window":"2026年1月28日-2026年3月4日","where":"培育平台线上提交；本条款未列具体窗口","tip":"申报和复核使用同一时间窗口，起止日期为2026年1月28日-2026年3月4日。"},{"sectionNo":"四","headline":"申报造假取消本年度资格，三年内不得再次申报","who":"2026年申报（复核）湖南省专精特新中小企业的企业；须对申报材料完整性、真实性、合法性负责，并按程序自主申报，不得委托代理。","materials":["专精特新中小企业推荐函","汇总表（附件3，纸质件2份）"],"window":"市州工信部门于3月4日前在培育平台提交审核意见，逾期不候。","where":"培育平台；省工业和信息化厅（邮寄地址：长沙市天心区新韶东路467号）","tip":"委托代理申报一经发现取消参评资格且三年内不得再次申报；各级工信部门受理申报不收取任何费用，收费培训班或解读班不得作为申报前提。"}],"sourceUrl":"https://gxt.hunan.gov.cn/gxt/xxgk_71033/tzgg/202601/t20260128_33904604.html","sourceNote":"条文已于 2026-11-09 与官方页面/PDF 逐句比对，逐字一致（明细见 采集包/条文核对表.md）；2026-11-08 核对：页面发布日期 2026-01-28","verified":true,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"shaoshan-cultural-park-2026","title":"韶山市人民政府办公室关于印发《韶山市支持文创产业园发展的若干措施》的通知","level":"district","region":"湘潭市·韶山市","issuer":"韶山市人民政府办公室","documentNo":"韶政办发〔2026〕2号","publishedAt":"2026-07-01","effectiveAt":"2026-03-31","expiresAt":"2029-03-30","status":"active","tags":["财政奖补","创业补贴","场地支持","融资支持","人才政策"],"audience":["入驻韶山高新区文创产业园的文创企业","大学生创业团队","配套服务机构","微短剧企业与剧组"],"summary":"对经评估符合条件的文创初创企业给予10万元至50万元股权投资；入驻企业及大学生创业团队享3年孵化期、100平方米以内办公场地免费；两年内科技投入累计500万元以上按实际投入3%补助、最高30万元；吸纳1—5人就业一次性创业补贴1.2万元、5人以上1.5万元；小微企业创业担保贷款最高400万元并按实际利率50%贴息、最高7万元/家/年；设立首期及年度规模均300万元的文创产业扶持专项资金，政策自2026年3月31日起施行、有效期3年。","sections":[{"no":"一","title":"","text":"一、初创企业股权投资\n以股权投资方式支持文创初创企业发展，经评估审核符合扶持条件的企业，给予10万元至50万元股权投资支持。"},{"no":"二","title":"","text":"二、实施场地与租金支持\n给予入驻文创产业园的企业、大学生创业团队3年孵化期，孵化期内免费提供100平方米以内办公场地；100平米以外的物业租金，可采用租金入股形式。"},{"no":"三","title":"","text":"三、支持文旅与科技融合创新\n鼓励文化、文物、旅游、广电、体育等领域主体及“政产学研”联合主体，运用大数据、人工智能、AR/VR、元宇宙等数字技术，推动文旅装备创新、艺术形式数字化传承、公共文化场馆智能化升级、智慧旅游场景建设及行业监管数智化提质，打造沉浸式、互动式、体验式文旅新场景。对两年内科技投入累计达500万元以上（不含争取的项目资金）的主体，一次性按实际投入的3%给予补助，最高不超过30万元，优先推荐申报国家级、省级专项项目；对新获评国家级、省级荣誉的文旅数字化项目，分别一次性给予10万元、5万元资金扶持。"},{"no":"四","title":"","text":"四、支持产品创新开发\n在韶企业开发的文创产品，年度内获国家级文化和旅游行政主管部门金奖、银奖、铜奖的，分别给予6万元、4万元、2万元资金扶持；获省级文化和旅游行政主管部门金奖、银奖、铜奖的，分别给予3万元、2万元、1万元资金扶持。同一产品按最高标准奖励，不重复补助。"},{"no":"六","title":"","text":"六、实施创业就业激励\n对在文创园创办企业且正常经营满1年的，按吸纳就业人数给予一次性创业补贴：吸纳1-5人就业的补贴1.2万元，吸纳5人以上就业的补贴1.5万元。企业发展初具规模后，可申请认定为就业见习基地，吸纳的见习人员按规定享受最长12个月/人的见习补贴。"},{"no":"七","title":"","text":"七、强化金融服务支撑\n1．在文创园设立大学生文创基地，大学生创业可申请最高30万元个人创业担保贷款，贷款期限不超过3年。\n2．创办小微企业的，可申请最高400万元创业担保贷款，贷款期限不超过2年，按贷款实际利率的50%给予贴息，最高限额为7万/家/年。\n3．入驻企业可享受园区“助力小微贷”专属服务，单户企业贷款最高额度达1500万元。"},{"no":"九","title":"","text":"九、支持红色微短剧产业发展\n1．鼓励红色微短剧创作转化：上线播出的韶山红色题材短剧，给予5万元/部奖励；获国家级重点扶持的额外奖10万元，获省级重点扶持的额外奖5万元。\n2．鼓励红色微短剧剧组来韶取景拍摄：对在韶山完成整剧集拍摄的微短剧剧组给予支持，成立韶山片场联盟委员会，提供一站式服务；给予剧组3000元/部拍摄补贴。\n3．鼓励微短剧产业集聚发展：微短剧相关企业、产业基地获国家级、省级、市级授牌的，分别给予20万元、10万元、5万元奖励；微短剧企业首次入规的奖励5万元。"},{"no":"十","title":"","text":"同时，设立文创产业扶持专项资金，首期及年度规模均为300万元，每年足额保障资金池稳定在300万，严格遵循“专款专用、择优分配”原则，支持文创产业园发展及主体培育。"},{"no":"施行与期限","title":"","text":"凡入驻韶山高新区文创产业园的企业，均适用本政策。对符合产业定位、具有重大带动作用的企业，经审查、研究、论证后，可制定合规、非歧视性专项扶持方案。本政策由韶山高新区管委会实施与解读，自2026年3月31日起施行，有效期3年。实施期间可根据园区运营实际及发展需要，按程序动态调整，优化政策内容。"}],"interpretations":[{"sectionNo":"一","headline":"文创初创企业经评估可获10万至50万元股权投资","who":"入驻韶山高新区文创产业园的文创初创企业，经评估审核符合扶持条件。","materials":[],"window":"经评估审核后给予股权投资支持。","where":"韶山高新区文创产业园（入驻企业适用）。","tip":"以股权投资方式支持，不是无偿补助；金额区间为10万元至50万元。"},{"sectionNo":"二","headline":"入驻文创园免租3年，100平方米以内办公场地免费","who":"入驻文创产业园的企业、大学生创业团队；孵化期3年，孵化期内免费提供100平方米以内办公场地；100平米以外的物业租金可采用租金入股形式。","materials":[],"window":"3年孵化期。","where":"文创产业园（园区内）。","tip":"100平米以外物业租金不是免除，可采用租金入股形式。"},{"sectionNo":"三","headline":"两年科技投入满500万元，按3%补助最高30万元","who":"文化、文物、旅游、广电、体育等领域主体及“政产学研”联合主体，运用大数据、人工智能、AR/VR、元宇宙等数字技术；两年内科技投入累计达500万元以上（不含争取的项目资金）；新获评国家级、省级荣誉的文旅数字化项目。","materials":[],"window":"两年内科技投入累计计算；获评荣誉一次性扶持。","where":"韶山高新区文创产业园（园区主体）。","tip":"科技投入不含争取的项目资金；按实际投入3%补助且最高30万元；国家级、省级荣誉分别一次性10万元、5万元。"},{"sectionNo":"四","headline":"文创产品获国家级金奖补6万元，省级金奖补3万元","who":"在韶企业开发的文创产品，年度内获国家级文化和旅游行政主管部门金奖、银奖、铜奖的，分别补6万元、4万元、2万元；获省级同奖项的，分别补3万元、2万元、1万元。","materials":[],"window":"年度内获奖，一次性资金扶持。","where":"韶山市（在韶企业）。","tip":"同一产品按最高标准奖励，不重复补助。"},{"sectionNo":"六","headline":"文创园创业满1年，吸纳1—5人补1.2万元","who":"在文创园创办企业且正常经营满1年的；按吸纳就业人数给予一次性创业补贴：吸纳1-5人就业补贴1.2万元，吸纳5人以上就业补贴1.5万元；企业发展初具规模后可申请认定为就业见习基地，见习人员按规定享受最长12个月/人的见习补贴。","materials":[],"window":"正常经营满1年；见习补贴最长12个月/人。","where":"文创园（园区内企业）。","tip":"吸纳5人以上按1.5万元；见习补贴最长12个月/人。"},{"sectionNo":"七","headline":"大学生创业担保贷款最高30万元，小微企业最高400万元","who":"在文创园设立大学生文创基地的大学生创业者：个人创业担保贷款最高30万元、期限不超过3年；创办小微企业最高400万元、期限不超过2年，按贷款实际利率的50%贴息、最高7万/家/年；入驻企业可享园区“助力小微贷”，单户最高1500万元。","materials":[],"window":"个人创业担保贷款期限不超过3年；小微企业创业担保贷款期限不超过2年。","where":"文创园（园区“助力小微贷”专属服务）。","tip":"贴息按贷款实际利率的50%、最高7万元/家/年；个人与小微企业贷款期限分别不超过3年、2年。"},{"sectionNo":"九","headline":"韶山红色短剧上线播出奖5万元/部，国家级扶持加奖10万元","who":"上线播出的韶山红色题材短剧创作方（5万元/部，获国家级重点扶持额外10万元、省级额外5万元）；在韶山完成整剧集拍摄的微短剧剧组（3000元/部）；微短剧相关企业、产业基地获国家级、省级、市级授牌（20万元、10万元、5万元）；首次入规的微短剧企业（5万元）。","materials":[],"window":"上线播出、完成拍摄、获授牌或首次入规后按次奖励。","where":"韶山（片场联盟委员会提供一站式服务）。","tip":"国家级、省级重点扶持为额外奖励；授牌按20万/10万/5万元分级；首次入规另奖5万元。"},{"sectionNo":"十","headline":"设文创产业扶持专项资金，首期及年度规模均300万元","who":"文创产业园发展及主体培育的支持对象；专项资金专款专用、择优分配，原文未列具体申报门槛。","materials":[],"window":"首期及年度规模均为300万元，每年足额保障资金池稳定在300万。","where":"韶山高新区文创产业园（专项资金支持）。","tip":"遵循“专款专用、择优分配”，不是普惠性补贴。"}],"sourceUrl":"http://www.shaoshan.gov.cn/11698/11702/27802/29916/30095/30096/content_1440269.html","sourceNote":"2026-11-22 取自韶山市政府门户「韶山政报」2026年第2期「市政府办文件」原文页，来源标注市政府办；版头文号韶政办发〔2026〕2号，成文日期2026年4月15日，页面发布时间2026年7月1日。条文按页面正文逐字转录。 2026-11-22 收录：与官方页面逐句比对，命中 27/27 句（100%），关卡判定「verbatim」。 有效期依据：正文末段（施行与期限）","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"shaoshan-univ-startup-2025","title":"韶山市人民政府办公室关于印发《韶山市支持大学生创业十条措施（试行）》的通知","level":"district","region":"湘潭市·韶山市","issuer":"韶山市人民政府办公室","documentNo":"韶政办发〔2025〕6号","publishedAt":"2025-07-10","effectiveAt":"2025-06-09","expiresAt":"2027-12-31","status":"active","tags":["创业补贴","贷款贴息","场地支持","认定资质","财政奖补"],"audience":["在校大学生和毕业五年内高校毕业生创办的市场主体","大学生创业孵化基地运营主体"],"summary":"对初次创办企业或个体工商户且正常经营满1年的大学生，按吸纳就业人数给予1.2万元或1.5万元一次性创业补贴，并给予最长2年经营场所租金补贴（第一年800元/月、第二年600元/月）；个人创业担保贷款最高30万元、小微企业最高400万元并按实际利率50%贴息；新认定国省级科研平台奖励10万元、5万元，获评高新技术企业补助5万元、入规奖励5万元；创业孵化基地每年最高100万元创业服务补助，措施有效期至2027年底。","sections":[{"no":"2","title":"","text":"2．实施创业补贴。对初次创办企业或注册个体工商户的大学生，正常经营满1年的，根据吸纳就业人数给予一次性创业补贴，1—5人补贴1.2万元，5人以上补贴1.5万元。对于大学生新创办的小微企业、个体工商户、农民合作社、民办非企业等创业组织，给予最长2年的经营场所租金补贴，标准为第一年800元/月、第二年600元/月。大学生创业初具规模后，可申请成立就业见习基地，吸纳就业的见习人员，按规定享受见习补贴，补贴期限不超过12个月/人。对在韶创办企业的大学毕业生，在市内购买首套商品住房的，按全日制博士、硕士学历层次分别给予400元/㎡、300元/㎡的一次性购房补贴，最高不超过5万元。（责任单位：市人社局、市委人才办、市财政局、市住房建设和交通运输局）"},{"no":"3","title":"","text":"3．给予贷款贴息。开设大学生创业贴息贷款快捷通道。对大学生创业需要创业资金的，可申请个人担保贷款最高额度30万元，期限不超过3年；对创办小微企业创业贷款最高额度为400万元，期限不超过2年，给予贷款实际利率50%贴息。（责任单位：市人社局、市财政局）"},{"no":"4","title":"","text":"4．创建孵化平台。提质升级高新区创新创业基地，推动政务、法务、财税服务进基地，完善培育、孵化、配套等服务链条，安排不少于30%的办公场地免费提供给大学生创业。综合考虑基地服务成效、入驻项目和孵化成功率情况，连续三年，每年给予最高不超过100万元的创业服务补助。支持各类市场主体创建大学生孵化基地，经认定合格给予5万元开办奖励。支持创建湘潭市级、省级大学生创业孵化基地，创建成功分别给予10万、20万元奖励。（责任单位：高新区、市人社局）"},{"no":"5","title":"","text":"5．支持成果转化。支持大学生创新创业主体加大与高校科研院所合作力度，提高科研成果产业化水平，共建创新平台，对新获批为国、省级的科研平台（工程技术研究中心、工程研究中心、企业技术中心、工业设计中心、新型研发机构、重点实验室、院士创新平台等）一次性分别给予10万元、5万元奖励。（责任单位：市市场监管和科技工信局、高新区、财政局）"},{"no":"6","title":"","text":"6．聚焦科技攻关。发布“揭榜挂帅”任务清单，支持大学生创新创业人才精准揭榜，对科研攻关突出、成果转化快的项目，按不高于签订的揭榜协议总金额10%的比例给予大学生揭榜补助，单个项目资金补助最高不超过10万元。对于大学生创业主体，获评高新技术企业补助5万元，主动申报并验收合格成为规模企业的给予 5 万元奖励。（责任单位：市市场监管和科技工信局、高新区、市财政局）"},{"no":"10","title":"","text":"10．铸就经典品牌。推出“青春当燃·逐梦韶华”大学生创业主题，全方位打造韶山“青创之城”品牌。依托红色文化旅游、“我的韶山行”红色研学、肉制品精深加工等特色产业，培育特色劳务品牌。被认定为韶山市级、湘潭市级和省级的特色劳务品牌，对项目单位给予10万、20万、30万元资金奖补。鼓励红色教育培训机构组织大学生来韶开展红色教育和能力提升、技能培训等活动，持续提升“韶山红课堂”红色培训品牌影响力。定期组织有创业意向的大学生来韶观摩，开展典型导引、经验交流和路演活动，推介韶山产业特色、发展态势和创业环境。（责任单位：市人社局、市委宣传部、团市委）"},{"no":"施行与期限","title":"","text":"本通知中的“大学生”，是指在校大学生和毕业五年内高校毕业生。本措施（试行）自发布之日起施行，有效期至2027年底，相关政策若遇上级政策调整从其规定。本政策由市人力资源和社会保障局商相关市直部门负责解释，各部门相关政策相同条款不重复享受，此前有关规定与本政策不一致的，以本政策为准。"}],"interpretations":[{"sectionNo":"2","headline":"创业满1年补1.2万至1.5万元，另享2年租金补贴","who":"初次创办企业或注册个体工商户的大学生；正常经营满1年；大学生新创办的小微企业、个体工商户、农民合作社、民办非企业等创业组织；创业初具规模后可申请就业见习基地。","materials":[],"window":"正常经营满1年；租金补贴最长2年（第一年800元/月、第二年600元/月）；见习补贴不超过12个月/人","where":"韶山市；责任单位市人社局、市委人才办、市财政局、市住房建设和交通运输局","tip":"吸纳1—5人补1.2万元、5人以上补1.5万元；购房补贴博士400元/㎡、硕士300元/㎡，最高5万元"},{"sectionNo":"3","headline":"大学生创业担保贷款个人最高30万元，小微企业最高400万元","who":"需要创业资金的大学生；创办小微企业的大学生","materials":[],"window":"个人担保贷款期限不超过3年；小微企业贷款不超过2年","where":"市人社局、市财政局（原文未列具体窗口）","tip":"给予贷款实际利率50%贴息；个人最高30万元、小微企业最高400万元"},{"sectionNo":"4","headline":"大学生孵化基地每年最高100万元补助，认定奖5万元","who":"高新区创新创业基地；各类市场主体创建的大学生孵化基地；湘潭市级、省级大学生创业孵化基地","materials":[],"window":"连续三年，每年给予最高不超过100万元创业服务补助","where":"高新区、市人社局","tip":"不少于30%办公场地免费给大学生；经认定合格给5万元开办奖励；湘潭市级、省级分别奖10万、20万元"},{"sectionNo":"5","headline":"新获批国、省级科研平台，分别奖10万元、5万元","who":"大学生创新创业主体与高校科研院所共建的创新平台；新获批为国、省级的科研平台（工程技术研究中心、工程研究中心、企业技术中心、工业设计中心、新型研发机构、重点实验室、院士创新平台等）。","materials":[],"window":"新获批后一次性奖励","where":"市市场监管和科技工信局、高新区、财政局","tip":"国家级10万元、省级5万元；须为新获批平台"},{"sectionNo":"6","headline":"揭榜挂帅项目补协议金额10%，最高10万元","who":"大学生创新创业人才；大学生创业主体；获评高新技术企业或成为规模企业的大学生创业主体","materials":[],"window":"按揭榜协议执行；获评当年申报","where":"市市场监管和科技工信局、高新区、市财政局","tip":"补助按不高于揭榜协议总金额10%，单个项目最高10万元；高企补5万元、入规奖5万元"},{"sectionNo":"10","headline":"特色劳务品牌分三级，分别奖10万、20万、30万元","who":"被认定为韶山市级、湘潭市级和省级特色劳务品牌的项目单位；红色教育培训机构；有创业意向的大学生","materials":[],"window":"定期组织观摩、路演；按认定级别奖补","where":"市人社局、市委宣传部、团市委","tip":"三级品牌分别奖10万元、20万元、30万元"}],"sourceUrl":"http://www.shaoshan.gov.cn/11698/11702/27802/29037/29245/29247/content_1381686.html","sourceNote":"2026-11-22 取自韶山市政府门户「韶山政报」2025年第2期「市政府办文件」原文页，来源标注市政府办；版头文号韶政办发〔2025〕6号，成文日期2025年6月9日，页面发布时间2025年7月10日；原文为「自发布之日起施行」，生效日取文件落款（发布）日2025年6月9日，网站上网日为2025年7月10日。 2026-11-22 收录：与官方页面逐句比对，命中 27/27 句（100%），关卡判定「verbatim」。 有效期依据：正文末段（施行与期限）","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"sy-biz-2025-2","title":"中共邵阳市委办公室 邵阳市人民政府办公室关于印发《邵阳市进一步优化营商环境的十四条措施》的通知","level":"city","region":"邵阳市","issuer":"中共邵阳市委办公室、邵阳市人民政府办公室","documentNo":"邵市办发〔2025〕2号","publishedAt":"2025-02-01","effectiveAt":null,"expiresAt":null,"status":"active","tags":["营商环境","就业补贴"],"audience":["邵阳市各类企业","规上规下、限上限下企业"],"summary":"建立“企业家接待日”与“12345”营商环境领导接听日机制，企业诉求3个工作日内响应、7个工作日内办理答复。","sections":[{"no":"一","title":"企业家接待日","text":"线上线下同步公开征集参会企业及企业诉求，实行市委书记、市长“每半月轮流接待”机制，推动解决企业急难愁盼问题，跟踪督办诉求办理落实情况。县市区对标市里联动。"},{"no":"二","title":"“12345”营商环境领导接听日","text":"市县两级政府领导和市直相关部门主要负责人每半个月轮流接听一次“12345”营商环境热线，对情况清楚、政策明确的诉求即时解答；对难以当场答复的诉求，由接听领导协调督办，限期解决。"},{"no":"三","title":"送解优“服务码”全覆盖","text":"常态开展送解优、“链长到一线”等行动，全力推广应用送解优“服务码”，推动涉企政策“一码直达”，企业诉求“一码直办”，实现规上规下、限上限下企业全覆盖，做到企业诉求在3个工作日内响应、7个工作日内办理答复。"},{"no":"四","title":"“高效办成一件事”","text":"加快推动数据共享和互联互通，设置“专区、专窗、专人、专评、专督”模式，持续推进每项“高效办成一件事”落地见效。深化“三集中三到位”改革，积极对接推进全省“综窗”改革，实现“人进事进，一站办结”。政务服务“一网通办”率力争达到90%以上。"}],"interpretations":[{"sectionNo":"一","headline":"市委书记、市长每半月轮流接待企业，诉求跟踪督办","who":"邵阳市企业；通过线上线下公开征集报名参会并提出诉求，县市区企业按当地联动机制参加。","materials":[],"window":"每半月轮流接待一次；诉求办理落实情况跟踪督办。","where":"原文未列明具体接待场所；县市区对标市里联动。","tip":"接待主体为市委书记、市长轮流；企业诉求办理落实情况会被跟踪督办。"},{"sectionNo":"二","headline":"每半月一次，市县领导接听“12345”营商环境热线","who":"邵阳市有诉求的企业；可拨打“12345”营商环境热线反映，市县两级政府领导和市直相关部门主要负责人轮流接听。","materials":[],"window":"每半个月轮流接听一次；难以当场答复的诉求限期解决。","where":"“12345”营商环境热线。","tip":"情况清楚、政策明确的诉求即时解答；复杂诉求由接听领导协调督办、限期解决。"},{"sectionNo":"三","headline":"扫“服务码”提诉求，3个工作日响应、7个工作日答复","who":"邵阳市规上规下、限上限下企业全覆盖；通过送解优“服务码”反映诉求、查询涉企政策。","materials":[],"window":"诉求3个工作日内响应、7个工作日内办理答复。","where":"送解优“服务码”。","tip":"覆盖规上规下、限上限下全部企业；涉企政策“一码直达”、企业诉求“一码直办”。"},{"sectionNo":"四","headline":"“高效办成一件事”设专区专窗，一网通办率力争90%以上","who":"在邵阳市办理政务事项的企业；可通过“专区、专窗、专人、专评、专督”模式及全省“综窗”办理“高效办成一件事”事项。","materials":[],"window":"持续推进；政务服务“一网通办”率力争达到90%以上。","where":"“专区、专窗、专人、专评、专督”模式；全省“综窗”改革。","tip":"目标是“人进事进，一站办结”；一网通办率力争90%以上。"}],"sourceUrl":"https://www.shaoyang.gov.cn/shaoyang/xxgkzdjcyg/202502/8dcc0efe31bf4d3aa632b53e6953d5a9.shtml","sourceNote":"2026-11-21 取自邵阳市政府门户「政府信息公开—政策解读/文件」原文页；文号与成文日期已核对。 2026-11-21 收录：与官方页面逐句比对，命中 7/7 句（100%），关卡判定「verbatim」。 有效期依据：原文未设期限；按行政规范性文件一般不超5年推算至2030-02","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"sy-crossborder-2026","title":"邵阳市人民政府办公室印发《关于促进邵阳市跨境电商发展的若干措施（试行）》的通知","level":"city","region":"邵阳市","issuer":"邵阳市人民政府办公室","documentNo":"邵市政办发〔2026〕8号","publishedAt":"2026-08-21","effectiveAt":"2026-08-21","expiresAt":"2028-08-20","status":"active","tags":["外贸外资","财政奖补"],"audience":["跨境电商企业","外贸企业","跨境电商产业园运营主体","物流与多式联运企业"],"summary":"九条措施支持跨境电商监管场所与线上平台运营（每年各不超过100万元）、产业园区（单个不超过300万元）、服务企业、培训与孵化、传统外贸企业上线、公共海外仓、多式联运、出口前置仓，试行期两年。","sections":[{"no":"一","title":"支持口岸平台建设和运营","text":"鼓励企业运营跨境电商监管作业场所和线上综合服务平台，对企业用于跨境电商监管作业场所和线上综合服务平台的运营费用给予支持，每年各不超过100万元。"},{"no":"二","title":"支持跨境电商产业园区建设","text":"鼓励各县市区和邵阳经开区打造一批具有一定规模、产业配套齐全、多功能、多业态的跨境电商产业园。支持园区申报省级跨境电商园区，对成功获批的，由市财政按省级支持标准的50%给予支持，单个园区不超过300万元。"},{"no":"五","title":"支持传统外贸企业利用线上渠道转型跨境电商","text":"对依法诚信经营、首次通过第三方跨境电商平台或自建独立站开展跨境出口业务，且近一年内经该渠道产生纳入海关统计的进出口实绩或外汇收汇记录，并依法纳税的各类市场主体，按其开拓线上渠道的实际投入给予一次性成本补助。"},{"no":"五（续）","title":"补助标准","text":"入驻第三方跨境电商平台开展出口业务的，按实际支出的平台入驻年费、站内推广费给予不超过50%的补贴，单个企业上限10万元；自建跨境电商独立站开展出口业务的，按实际支出的建站软硬件购置、域名注册及年度运营维护费用给予不超过30%的补贴，单个企业上限15万元，同一企业同一年度可同时申请上述两类补贴，合计上限20万元。"},{"no":"七","title":"支持多式联运体系建设","text":"积极推动邵阳至珠三角图定班列开行（100列），每开行一趟奖励3万元，每年最高奖励不超过300万元；支持邵阳班列常态化开行，在班列开行装卸费、吊装费、短驳费、报关费方面给予补助，每年最高不超过50万元。"}],"interpretations":[{"sectionNo":"一","headline":"运营跨境电商监管场所或线上平台，每年各最高100万元","who":"运营跨境电商监管作业场所、跨境电商线上综合服务平台的企业；支持范围为用于上述场所和平台的运营费用。","materials":[],"window":"每年支持，监管作业场所与线上综合服务平台各不超过100万元。","where":"邵阳市（市级财政资金支持）。","tip":"监管作业场所与线上综合服务平台两类运营费用分别计算，每年各不超过100万元。"},{"sectionNo":"二","headline":"省级跨境电商园区获批，市财政按50%配套，最高300万元","who":"各县市区、邵阳经开区打造的跨境电商产业园；须申报省级跨境电商园区并成功获批，由市财政按省级支持标准的50%给予支持。","materials":[],"window":"按省级跨境电商园区申报批次；单个园区不超过300万元。","where":"市财政（按省级支持标准给予支持）；园区申报省级跨境电商园区。","tip":"补助以省级获批为前提，按省级支持标准的50%配套，单个园区封顶300万元。"},{"sectionNo":"五","headline":"首次上线开展跨境出口，按线上渠道实际投入一次性补助","who":"依法诚信经营、首次通过第三方跨境电商平台或自建独立站开展跨境出口业务的各类市场主体；须近一年内经该渠道产生纳入海关统计的进出口实绩或外汇收汇记录，并依法纳税。","materials":[],"window":"首次开展业务后一次性补助；实绩或收汇记录须在近一年内。","where":"邵阳市（市级财政资金支持）。","tip":"须同时满足首次、近一年内有海关统计实绩或外汇收汇记录、依法纳税三项条件；补助为一次性。"},{"sectionNo":"五（续）","headline":"平台补50%上限10万元，独立站补30%上限15万元，合计20万元","who":"入驻第三方跨境电商平台开展出口业务、或自建跨境电商独立站开展出口业务的企业；同一企业同一年度可同时申请两类补贴。","materials":[],"window":"同一年度内可同时申请两类补贴，合计上限20万元。","where":"邵阳市（市级财政资金支持）。","tip":"平台类补实际支出的50%、单家上限10万元；独立站类补30%、上限15万元；两类合计封顶20万元。"},{"sectionNo":"七","headline":"邵阳至珠三角班列每趟奖3万元，每年最高300万元","who":"开行邵阳至珠三角图定班列（100列）的运营主体；以及邵阳班列常态化开行中发生装卸费、吊装费、短驳费、报关费的相关企业。","materials":[],"window":"年度计算：班列开行奖励每年最高300万元，装卸等费用补助每年最高50万元。","where":"邵阳市（市级财政资金支持）。","tip":"班列奖励按实际开行趟数每趟3万元、年度封顶300万元；费用补助年度封顶50万元。"}],"sourceUrl":"https://www.shaoyang.gov.cn/shaoyang/szfbwj/202609/0202a195576a489ca62fceebf0b50657.shtml","sourceNote":"2026-11-22 取自邵阳市人民政府门户「文件库—市政府办规范性文件」原文页，版头载文号邵市政办发〔2026〕8号、统一登记号 SYCR-2026-01006，页面信息有效期栏载2028-08-20。 2026-11-22 收录：与官方页面逐句比对，命中 8/8 句（100%），关卡判定「verbatim」。 有效期依据：第九条明示“试行期为两年”；页面信息有效期栏载2028-08-20","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"sy-elderly-industry-2026","title":"邵阳市人民政府办公室关于印发《邵阳市落实〈关于壮大养老产业促进银发经济发展的实施意见〉工作方案》的通知","level":"city","region":"邵阳市","issuer":"邵阳市人民政府办公室","documentNo":"邵市政办发〔2026〕5号","publishedAt":"2026-05-06","effectiveAt":"2026-05-06","expiresAt":"2031-05-05","status":"active","tags":["认定资质","上市培育","税收优惠"],"audience":["老年用品生产企业","康复辅助器具企业","生物医药企业","养老服务机构","中医药企业"],"summary":"落实湖南省壮大养老产业促进银发经济实施意见的工作方案，明确到2029年养老服务体系更加健全、银发经济形态初步形成，2035年建成现代化养老产业体系；重点任务分丰富养老服务供给、升级银发传统产业、培育银发潜力产业、提升产业发展质量、加强产业综合支撑5方面19项，含65周岁及以上老人等级景区免票、落实养老从业人员政策性补贴、支持县市区发放银发消费券体验券、养老设施用地五年过渡期等；未列财政奖补金额或比例，财金支持以信贷、基金、专项债渠道为主；自印发之日起施行，有效期五年。","sections":[{"no":"一","title":"一、目标要求","text":"充分发挥市场机制作用和政府引导功能，以科技创新和金融支持为双轮驱动，加快构建体系完善、供给高效、布局合理的养老产业发展格局。力争到2029年，全市养老服务体系更加健全，银发经济形态初步形成;到2035年，全面建成与我市经济社会发展水平相适应、与老年群体需求相匹配的现代化养老产业体系，实现银发经济高质量发展。"},{"no":"二","title":"二、重点任务(一)丰富养老服务供给","text":"1.完善照护服务体系。建设一批乡镇(街道)综合养老服务中心，组织家庭成员照护服务技能培训。规划建设养老服务站点，提供“六助一护”等服务，在市城区推进“物业+养老”服务试点工作，推动基层医疗卫生机构开展医疗照护服务。逐步推进长期护理保险制度。将符合条件的养老机构内设医疗机构按规定纳入基本医疗保险定点范围。(责任单位：市民政局、市财政局、市人力资源社会保障局、市卫生健康委、市医保局、市数据局按职责分工负责，下同)2.加快健康服务优化。鼓励基层医疗卫生机构与养老机构共享资源，开展签约合作，扩大康复治疗和护理服务供给。落实分级诊疗制度，常态化开展巡回医疗服务，引导市区优质医疗资源下沉社区。支持参与医养结合、安宁疗护示范单位创建。(责任单位：市民政局、市卫生健康委、市医保局)3.拓展生活服务领域。积极开展老年助餐服务，优化服务网络布局，引导社会餐饮单位进行适老化改造，按规定落实老年助餐点税费优惠政策。探索建立“养老+医、护、康、养、居”等服务模式，将家政服务人员纳入养老从业人员培训体系，完善社区老年教育四级网络体系和适老化健身设施建设。深化电视层层收费和操作复杂问题治理。(责任单位：市教育局、市民政局、市财政局、市人力资源社会保障局、市文旅广体局)4.建设银发友好单元。将无障碍环境建设、适老住宅建设等融入城市更新行动和城镇老旧小区改造内容，并纳入城市体检指标体系，有序推进电梯加装、更新和公交站台适老化改造，组织参与全国示范性老年友好型社区创建工作。引导设立适老化产品体验与销售专区，配备专属服务人员，提升老年人消费便利性。(责任单位：市发展改革委、市民政局、市住房城乡建设局、市城管局、市交通运输局、市商务局)"},{"no":"三","title":"(二)升级银发传统产业","text":"5.扩大老年用品研发生产。将老年健康创新技术和产品研发纳入市级科技计划支持范围，推荐优质项目申报中央、省级科技计划项目。引导养老企业开展增品种、提品质、创品牌活动，组织优质企业申报“三品”标杆企业、“老年用品产品推广目录”、中国消费名品等。建立老年用品“专精特新”企业梯度培育库，对具备创新潜力的中小企业制定针对性培育计划。(责任单位：市科技局、市工业和信息化局)6.加快康辅器具推广应用。搭建产学研合作平台，促进高校科研资源与企业需求对接。鼓励开展康辅器具关键技术攻关和智能产品(如健康监测、走失监测等)研发，支持符合条件的产品参与省级层面“五首”产品评定。(责任单位：市科技局、市工业和信息化局、市民政局、市市场监管局)7.加强文体休闲业态建设。组织开展老年人文化体育赛事、银发用品设计大赛、“养老服务消费节”和中老年文化旅游节等活动。鼓励等级旅游景区对65周岁及以上老人实行免票优惠，完善适老化便利设施，推动开通融合本地自然与文化的慢节奏特色银发旅游线路。支持保险机构推出老年人专属保险产品。(责任单位：市民政局、市交通运输局、市商务局、市文旅广体局、邵阳金融监管分局)"},{"no":"四","title":"(三)培育银发潜力产业","text":"8.创新生物医药产品。鼓励本市医疗机构配合部省属高水平医疗机构开展医学研究。支持本市生物医药企业与医疗机构、科研院所合作，开展老年病、慢性病等相关药物的研发和创新，共同开发适老化养生系列产品。组织申报“省生物医药产业链重点品种”，培育骨干企业。加大生物医药企业招商引资力度，争取新产品引进、注册及生产许可方面的政策支持。(责任单位：市科技局、市工业和信息化局、市商务局、市卫生健康委、市市场监管局)9.发挥中医保健作用。加快中医药传承创新发展示范项目建设。打造药膳馆、文化夜市等消费场景，推出地方特色鲜明的中药膳食产品。推动药膳纳入“减盐减油”推荐食谱，与日常饮食深度融合。依托本地资源优势，构建道地药材特色产品链。鼓励建设康养示范基地，利用湖南(廉桥)中医药产业博览会、邵阳旅发大会等平台宣传推广中医药康养项目。(责任单位：市农业农村局、市商务局、市文旅广体局、市卫生健康委、市市场监管局)10.强化智慧养老赋能。支持建设“人工智能+养老”应用场景。鼓励智能养老产品技术研发，引导企业对照工信部《智慧健康养老产品及服务推广目录》申报国省重点品种和健康产品名录。利用闲置资产建设养老产品宣传展销中心。(责任单位：市科技局、市工业和信息化局、市民政局、市商务局、市数据局)11.发展养老金融服务。贯彻落实中国人民银行等9部门《关于金融支持中国式养老事业服务银发经济高质量发展的指导意见》(银发〔2024〕225号)精神，鼓励保险机构通过商业养老年金等产品完善养老金融服务体系，探索运用商业保险年金新型产品。适当调整投保条件，加快发展商业健康保险，完善基本医保、大病保险、湖南医惠保和医疗救助“一站式”结算。依托省公共数据资源平台推进全市医疗与商业健康保险数据共享。(责任单位：市政府办公室、市发展改革委、市民政局、市财政局、市卫生健康委、市医保局、市数据局、邵阳金融监管分局、人民银行邵阳市分行)"},{"no":"五","title":"(四)提升产业发展质量","text":"12.培植多元经营主体。全面放开养老服务市场，消除准入壁垒，营造公平竞争的市场环境。深化“个转企”高效办成一件事，建立“个转企”种子培育库，挖掘培育银发经济企业入库入统。加大对企业上市培育和辅导，引导符合条件的企业挂牌上市。鼓励各类市场主体积极布局“大健康”医养服务产业。(责任单位：市政府办公室、市发展改革委、市民政局、市商务局、市卫生健康委、市国资委、市市场监管局)13.打造养老产业集群。聚焦银发经济重点领域，力争培育一批制造业单项冠军企业。持续开展产业链园区提升行动，在中医药、医疗器械等优势细分领域培育养老产品产业集群，研究制定加快推进产业链群高质量发展的若干支持政策，依托医药产业园和中医药产业特色产业链谋划实施一批项目。(责任单位：市发展改革委、市工业和信息化局、市商务局、市卫生健康委)14.完善行业标准评价。邀请省级认证机构开展养老机构质量体系认证。推进老年用品质量安全追溯，引导企业使用“数字身份码”。对符合条件的养老领域社会组织优化登记服务，推动成立市养老协会，提升医养结合机构诊疗标准化、规范化水平。定期开展养老机构等级评定工作，建立常态化评定和第三方参与机制，制定科学指标体系。系统梳理建设工程领域适老化改造相关技术规范，提供科学指导。(责任单位：市卫生健康委、市民政局、市住房城乡建设局、市文旅广体局、市市场监管局)15.塑造优质银发品牌。积极发挥地理标志产品“品质+文化+地域”的优势，推动传统产业升级与老年消费市场创新。推广地理标志使用，指导农产品地理标志转化为地理标志产品。鼓励各类市场主体在养老服务品牌创建、服务标准执行等方面先行先试。依托我市中药材特色产业优势，打造地域特色银发产品品牌。(责任单位：市民政局、市农业农村局、市商务局、市市场监管局)"},{"no":"六","title":"(五)加强产业综合支撑","text":"16.落实用地保障。科学编制供地计划，分级分类保障养老项目合理用地需求。推进新建住宅小区按标准配建养老服务设施，确保同步规划、同步建设、同步验收、同步交付。通过盘活闲置资源等方式配建养老服务设施，符合条件的适用土地利用五年过渡期政策。(责任单位：市民政局、市自然资源和规划局、市住房城乡建设局)17.强化人才支撑。探索建立养老行业产教培融合共同体，鼓励高职院校开设养老相关专业，扩大招生规模，完善教学标准和课程体系，支持养老服务机构依托职业院校共建产教融合实训基地，鼓励开展养老护理员职业技能提升培训。推动落实养老从业人员按规定享受有关政策性补贴，提高养老服务队伍稳定性。(责任单位：市教育局、市民政局、市财政局、市人力资源社会保障局)18.优化市场环境。推动智慧养老平台建设，持续开展养老机构“双随机、一公开”监管，完善“互联网+监管”机制。深化部门数据协同，推动医保、社保等公共数据资源共享。建立“日常监管+属地监管+企业自查”责任机制，深化养老领域非法集资专项整治，持续做好防范非法金融活动宣传教育、非法集资风险排查、监测预警和案件处置等工作，严格落实养老服务市场失信联合惩戒制度。制定《涉老企业信用评价指标体系》，建立“一企一档”信用档案。(责任单位：市政府办公室、市发展改革委、市公安局、市民政局、市人力资源社会保障局、市卫生健康委、市市场监管局、市医保局、市数据局)19.加大财金支持。鼓励银行机构加大对各类银发经济项目的信贷支持力度，引导金芙蓉基金加大对银发经济产业支持力度，吸引社会资本投入。支持有条件的县市区发放银发消费券、体验券。统筹中央预算内投资、地方政府专项债券等资金申请渠道，谋划储备申报养老项目，支持养老服务设施建设。(责任单位：市政府办公室、市发展改革委、市民政局、市财政局、市商务局、邵阳金融监管分局)"},{"no":"七","title":"三、保障措施","text":"建立健全动态跟踪与效果研判机制，定期对改革举措实施效果进行分析研判，及时协调解决推进中的困难问题，动态优化完善相关政策，确保改革任务取得成效。各相关单位要对照工作方案明确的任务分工，主动履职尽责。各县市区可参照本工作方案开展本地壮大养老产业促进银发经济发展工作，原则上不再对照出台文件。"},{"no":"八","title":"","text":"本工作方案自印发之日起施行，有效期五年。"}],"interpretations":[{"sectionNo":"二","headline":"养老机构内设医疗机构可纳入医保定点，助餐点享税费优惠","who":"符合条件的养老机构内设医疗机构（可纳入基本医疗保险定点范围）；开展老年助餐服务的机构及经适老化改造的社会餐饮单位（按规定落实税费优惠）；提供“六助一护”服务的养老服务站点运营方。","materials":[],"window":"政策执行期内持续推进，原文未设申报批次与截止时间。","where":"市医保局、市卫生健康委、市民政局按职责分工办理。","tip":"只有“符合条件的”内设医疗机构才能纳入医保定点，原文未列具体条件；长期护理保险制度为“逐步推进”，尚非即时可享。"},{"sectionNo":"三","headline":"65周岁及以上老人游等级景区免票，可推老年专属保险","who":"65周岁及以上老年人（等级旅游景区免票优惠）；保险机构（可推出老年人专属保险产品）；符合条件的产品可参与省级“五首”产品评定。","materials":[],"window":"长期执行；景区免票为鼓励性措施，原文未设截止时间。","where":"市文旅广体局、市市场监管局、邵阳金融监管分局等按职责分工负责。","tip":"景区免票写的是“鼓励”而非强制，去前需确认景区是否执行；保险产品与“五首”评定均以“符合条件”为前提。"},{"sectionNo":"四","headline":"智能养老产品可报国省推广目录，生物医药可报省重点品种","who":"研发智能养老产品的企业（对照工信部《智慧健康养老产品及服务推广目录》申报）；生物医药企业（与医疗机构、科研院所合作开展老年病、慢性病药物研发）；中医药康养项目运营主体。","materials":[],"window":"按工信部目录及省重点品种的申报批次执行，原文未列具体时间。","where":"市科技局、市工业和信息化局、市卫生健康委、市市场监管局按职责分工。","tip":"须“对照”工信部推广目录申报，不在目录范围的产品无从申报；中医药康养可借湖南(廉桥)中医药产业博览会、邵阳旅发大会推广。"},{"sectionNo":"五","headline":"个转企入库培育，符合条件企业可获上市辅导与挂牌支持","who":"个体工商户（可进入“个转企”种子培育库）；银发经济领域企业（入库入统）；符合条件的企业（上市培育辅导、挂牌上市）；制造业企业（争创单项冠军）。","materials":[],"window":"长期推进；上市辅导与挂牌按企业条件分批实施，原文未设申报期。","where":"市政府办公室、市发展改革委、市民政局、市市场监管局等按职责分工。","tip":"“个转企”要先入库培育；上市培育面向“符合条件”的企业，原文未定具体财务门槛。"},{"sectionNo":"六","headline":"闲置资源改建养老设施享五年过渡期，可申报专项债","who":"利用闲置资源配建养老服务设施的项目主体（符合条件可适用土地利用五年过渡期政策）；养老服务机构（人才培训、政策性补贴）；银发经济项目（银行信贷、基金支持）；有条件的县市区（可发银发消费券）。","materials":[],"window":"土地利用五年过渡期为阶段性政策；养老项目按年度谋划储备申报。","where":"市自然资源和规划局、市住房城乡建设局、市民政局、市财政局按职责分工统筹资金申请渠道。","tip":"过渡期政策只适用“符合条件的”项目；消费券由“有条件的县市区”发放，非全市统一。"}],"sourceUrl":"https://www.shaoyang.gov.cn/shaoyang/szfbwj/202605/af254a5b661a4b14aaa05739d8f33ae5.shtml","derivedFrom":"official","sourceNote":"2026-11-22 取自邵阳市人民政府门户「文件库—市政府办规范性文件」原文页，版头载文号邵市政办发〔2026〕5号，页面信息有效期栏载2031-05-05，发文日期2026年5月6日。 2026-11-22 收录：与官方页面逐句比对，命中 14/14 句（100%），关卡判定「verbatim」。 有效期依据：正文末条明示“有效期五年”；页面信息有效期栏载2031-05-05（自2026-05-06起算） 2026-11-24 收录：与官方页面逐句比对，命中 87/87 句（100%），关卡判定「verbatim」。 有效期依据：原文未明示","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"sy-mfg-support","title":"邵阳市人民政府办公室关于印发《邵阳市促进先进制造业平稳增长的若干财政支持政策》的通知","level":"city","region":"邵阳市","issuer":"邵阳市人民政府办公室","documentNo":"邵市政办发〔2022〕12号","publishedAt":"2022-06-15","effectiveAt":null,"expiresAt":null,"status":"active","tags":["财政奖补","融资支持","认定资质"],"audience":["邵阳市先进制造业企业","专精特新“小巨人”企业","高新技术企业","规模工业企业"],"summary":"专精特新“小巨人”、高新技术企业1000万元（含）以下担保费率由1%下调至0.5%；规模企业500万元（含）以下由1%下调至0.8%。","sections":[{"no":"16","title":"融资担保降费","text":"依托邵阳市中小企业融资担保公司等政府出资的融资担保机构，积极为中小微企业融资提供再担保，切实缓解中小微企业融资难、融资贵的问题，其中，专精特新“小巨人”企业、高新技术企业担保金额1000万元（含）以下担保费率从1%下调至0.5%。规模企业及规模培育企业，担保金额500万元（含）以下担保费率从1%下调至0.8%，500万元-1000万元（含）担保费率从1.2%下调至1.0%。"},{"no":"17","title":"支持企业“走出去”","text":"利用邵商优势，与东盟、非洲国家深化产能合作交流，建设中非产业园、东盟产业园等外向型经济专业园区。支持以并购、重组等形式与产业链上下游重要节点企业开展合作，对重大并购事项采取“一事一议”方式给予支持。"},{"no":"20","title":"骨干税源企业培育奖励","text":"对首次上规入库且三年内不退规的工业企业，由受益地财政给予每家企业5万元奖励。对取得军工资质证书的企业，给予10万元奖励。对首次获国家级、省级制造业单项冠军企业（产品），给予不超过50万元、10万元奖励。"},{"no":"19","title":"百强企业奖励","text":"对纳入“湖南制造业100强企业”榜单且营业收入、经济贡献增幅均超过10%的邵阳企业，从榜单发布第二年起，指导支持企业申报省级不超过500万元奖励。"}],"interpretations":[{"sectionNo":"16","headline":"小巨人、高企1000万以内担保费率降至0.5%","who":"专精特新小巨人企业、高新技术企业（担保金额1000万元含以下，费率从1%降至0.5%）；规模企业及规模培育企业（500万元含以下从1%降至0.8%，500万元至1000万元含从1.2%降至1.0%）。","materials":[],"window":"原文未设申报期限，按担保业务办理","where":"邵阳市中小企业融资担保公司等政府出资的融资担保机构","tip":"须通过政府出资的融资担保机构办理再担保；费率按担保金额分档下调。"},{"sectionNo":"17","headline":"支持企业赴东盟、非洲建产业园，重大并购一事一议","who":"与东盟、非洲国家开展产能合作、建设外向型经济专业园区的企业；以并购、重组等形式与产业链上下游重要节点企业合作的企业。","materials":[],"window":"重大并购事项采取一事一议方式（原文未列申报期）","where":"原文未列受理部门；重大并购事项按一事一议办理","tip":"支持建设的是中非产业园、东盟产业园等外向型经济专业园区；重大并购须一事一议。"},{"sectionNo":"20","headline":"首次上规入库奖励5万元，军工资质奖励10万元","who":"首次上规入库且三年内不退规的工业企业（5万元）；取得军工资质证书的企业（10万元）；首次获国家级、省级制造业单项冠军的企业（产品）（不超过50万元、10万元）。","materials":[],"window":"首次上规入库且三年内不退规；单项冠军为首次获评","where":"受益地财政（上规入库奖励）；原文未列其他受理部门","tip":"上规入库奖励由受益地财政给予；三年内退规即不符合条件；单项冠军奖励按国家级、省级分档。"},{"sectionNo":"19","headline":"入围湖南制造业100强且增幅超10%，可申报省级最高500万","who":"纳入湖南制造业100强企业榜单、且营业收入和经济贡献增幅均超过10%的邵阳企业。","materials":[],"window":"从榜单发布第二年起申报（原文未列具体申报期）","where":"省级奖励申报（原文未列受理部门）；由市级指导支持企业申报","tip":"须营业收入、经济贡献增幅均超过10%；奖励为省级不超过500万元，非市级直接发放。"}],"sourceUrl":"https://www.shaoyang.gov.cn/shaoyang/zfgbszfbgswj/202208/1e3c65a7431c4a959dc087eb7fff570c.shtml","sourceNote":"2026-11-21 取自邵阳市政府门户「政府公报—市政府办公室文件」原文页；页面未标注文号，已在字段中如实记录。担保费率与奖励标准逐字核对。 2026-11-21 收录：与官方页面逐句比对，命中 8/8 句（100%），关卡判定「verbatim」。 有效期依据：原文未设期限；按行政规范性文件一般不超5年推算至2027年（以2022年起算） 2026-11-21 补录：documentNo、publishedAt 据官方页面版头/落款核对后填入。","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"sy-quality-award-2026","title":"邵阳市人民政府办公室关于印发《邵阳市市长质量奖管理办法》的通知","level":"city","region":"邵阳市","issuer":"邵阳市人民政府办公室","documentNo":"邵市政办发〔2026〕7号","publishedAt":"2026-07-25","effectiveAt":"2026-07-25","expiresAt":"2031-07-24","status":"active","tags":["认定资质","财政奖补"],"audience":["国有企业","民营企业","外商投资企业","现代农业与战略性新兴产业企业"],"summary":"市长质量奖每2年评选一届，每届市长质量奖不超过5个组织、2名个人，提名奖不超过10个组织和个人，未达条件可空缺；评审依据GB/T19580、GB/T19579；第六章“奖励”只规定由市人民政府颁发证书和奖牌，评审工作经费由市财政统筹保障，全文未设奖金金额，获奖后两届内不得再次申报；获奖后5年内发生重大质量安全事故等情形撤销奖项；自发布之日起施行，有效期5年。","sections":[{"no":"一","title":"第一章 总则","text":"为贯彻落实《质量强国建设纲要》和《湖南省质量强省建设纲要》，大力推进质量强市战略，不断提高全社会质量意识，引导和激励全市各行各业加强质量管理，推广科学质量管理制度、模式和方法，促进质量管理创新，传播先进质量理念，提高产品、工程、服务和环境等领域质量水平，推动全市经济社会健康发展，根据《中华人民共和国产品质量法》《湖南省评比表彰和创建示范活动管理实施细则(试行)》等有关规定，制定本办法。"},{"no":"二","title":"","text":"邵阳市市长质量奖(以下简称市长质量奖)是市人民政府在质量领域授予各类组织和个人的最高荣誉。"},{"no":"三","title":"","text":"每届市长质量奖评选经市委、市政府同意并报省委、省政府批准后开展。市长质量奖分为市长质量奖和市长质量奖提名奖，评选周期为2年。市长质量奖每届不超过5个组织和2名个人，提名奖每届不超过10个组织和个人。如未达到奖励条件可以空缺。"},{"no":"四","title":"","text":"市长质量奖的评审坚持科学、公开、公平、公正的原则，在组织和个人自愿申报的基础上，经相关部门推荐，严格按照程序和标准开展评审工作。"},{"no":"五","title":"第二章 组织领导","text":"经市长授权，邵阳市市长质量奖评审委员会(以下简称评委会)全面负责市长质量奖评审工作。评委会由市质量强市联席会议成员单位负责人组成，市人民政府分管市场监管工作的副市长担任评委会主任委员。评委会主要职责是组织、推动、指导市长质量奖评审活动，审定并发布市长质量奖评审方案、评审准则、评审程序等，研究决定市长质量奖评审过程中的重大事项。"},{"no":"六","title":"","text":"评委会办公室设在市市场监管局，由单位主要负责人兼任办公室主任。主要职责是负责市长质量奖日常管理工作，包括：(一)起草市长质量奖的评审方案、评审准则、评审程序等;(二)受理申报组织或个人材料，组织市长质量奖的评审工作;(三)建立获奖单位和获奖个人的监督管理和异议处理机制;(四)开展质量奖评审依据和评审工作的跟踪研究，及时总结、宣传、推广典型经验和成果。"},{"no":"七","title":"","text":"评委会办公室可依规依程序委托第三方机构开展市长质量奖的申请资料整理、材料初审、现场评审、顾客满意度测评等工作。受委托的第三方机构承担评审过程中产生的技术和法律责任，不得向申报组织和个人收取任何费用。"},{"no":"八","title":"第三章 申报条件","text":"申报市长质量奖的组织(以下简称申报组织)，应当具备以下条件：(一)拥护党中央的路线、方针、政策;(二)在邵阳市行政区域内依法成立的国有企业、民营企业和外商投资企业;(三)具备健全的质量管理体系，取得相关体系认证证书并运行有效，建立并已实施卓越绩效管理模式，具有显著的质量效益和突出的社会贡献;(四)符合国家、省、市的产业、环保、质量等政策，列入国家强制监督管理范围的应取得相关证照;(五)质量管理成效显著，产品、工程和服务质量、自主创新能力、市场竞争力等在行业内处于领先地位;(六)具有良好的诚信记录和社会声誉，顾客满意程度高;(七)近3年内无较大质量、安全、环保、公共卫生等事故，无违法、违规、违纪行为，无不良社会反映。鼓励具有自主知识产权、创新能力强、主导制定国家标准或国际标准、质量管理水平先进、符合产业发展方向、成长性较强的企业和具备示范引领作用、能够带动区域经济发展、具备良好的经济社会效益的现代农业、战略性新兴产业、新型服务业等行业的单位积极申报。"},{"no":"九","title":"","text":"申报市长质量奖的个人(以下简称申报个人)，应当具备以下条件：(一)政治坚定，拥护党中央的路线、方针、政策，恪守职业道德和社会公德，无违法、违规和违纪行为;(二)有较强的质量意识和创新能力，对质量事业有高度的责任感和使命感;(三)具有卓有成效的质量管理理论研究或丰富的实践经验，在履职的工作岗位或从事的工作领域为质量事业作出了突出贡献;(四)具有良好的诚信记录。"},{"no":"十","title":"","text":"已获得中国质量奖、省长质量奖的组织和个人不予申报市长质量奖。获得市长质量奖(不含提名奖)的组织和个人在获奖后两届内，不得再次申报市长质量奖。"},{"no":"十一","title":"第四章 评审依据","text":"市长质量奖的评定依据为GB/T19580《卓越绩效评价准则》、GB/T19579《卓越绩效评价准则实施指南》，评审标准内容包括领导、战略、顾客与市场、资源、过程管理、测量、分析与改进、经营结果等。"},{"no":"十二","title":"","text":"为保证市长质量奖评审依据的有效实施和不同行业评审工作的一致性，评委会办公室根据行业、企业类别，分别制订评审实施细则。"},{"no":"十三","title":"第五章 申报与评审","text":"每届市长质量奖评审前，由评委会办公室在市级主要媒体和网站上发布市长质量奖评审公告。"},{"no":"十四","title":"","text":"符合申报条件的组织或个人，在自愿的基础上，根据市长质量奖的申报条件，在规定时间内向所在县市区市场监管部门提出申请，县市区市场监管部门对申报材料进行初审，并报请所在县市区人民政府批准后，向评委会办公室推荐。"},{"no":"十五","title":"","text":"评委会办公室对申报材料的主体资格、推荐渠道、申报程序和材料规范性等进行审查。"},{"no":"十六","title":"","text":"评委会办公室对通过初步审查的申报组织和申报个人征求纪检监察、公安、生态环境、人力资源社会保障、税务、市场监管、应急管理、住房和城乡建设等有关主管部门意见。涉及国防、国家安全的涉密事项，在适当范围内征求相关部门意见。"},{"no":"十七","title":"","text":"评委会办公室根据初步审查结果和相关部门对初步审查结果的意见，形成市长质量奖受理名单，并向社会公示;对未予受理的申报组织和申报个人，评委会办公室向申报组织或个人说明理由。"},{"no":"十八","title":"","text":"对通过审查和公示的申报组织和个人，评委会办公室组织开展评审，评审程序包括材料评审、现场评审、市场(顾客)满意度测评、综合评价、审定和公示公告。"},{"no":"十九","title":"","text":"评委会办公室成立材料评审组，对组织或个人提交的申报材料按照评审准则进行评分，形成材料评审报告，并按得分高低提出现场评审名单。对未进入现场评审的组织，及时反馈材料评审结果。"},{"no":"二十","title":"","text":"对通过材料评审的组织和个人，评委会办公室成立现场评审组，依据现场评审准则对组织和个人进行现场评审，形成现场评审报告。"},{"no":"二十一","title":"","text":"评委会办公室对通过材料评审的组织进行市场(顾客)满意度指数测算，形成市场(顾客)满意度测评报告。"},{"no":"二十二","title":"","text":"评委会办公室对各专项评审组的材料评审、现场评审和满意度测评情况进行综合评价，提出市长质量奖候选名单。"},{"no":"二十三","title":"","text":"评委会召开会议，对市长质量奖候选名单进行审议，产生市长质量奖获奖建议名单。"},{"no":"二十四","title":"","text":"评委会办公室将市长质量奖获奖建议名单向社会公示五个工作日。对公示存在异议的组织或个人，评委会办公室应当书面告知其异议内容及拟作出的处理决定，充分听取其陈述和申辩，对其提出的事实、理由和证据进行核查，经核实异议成立的，取消拟获奖资格。对公示无异议的组织或个人，按程序报市长审定后，由市人民政府公告。"},{"no":"二十五","title":"第六章 奖励","text":"市人民政府对获得市长质量奖和市长质量奖提名奖的组织和个人颁发证书和奖牌。"},{"no":"二十六","title":"","text":"市长质量奖评审工作经费由市财政统筹保障。"},{"no":"二十七","title":"","text":"鼓励各级各有关部门结合本地区、本行业质量发展需要，制定完善产业、财政、金融、科技、贸易、环境、人才培养等配套政策措施，并在融资服务等方面对市长质量奖获奖组织和个人予以支持。"},{"no":"二十八","title":"第七章 监督管理","text":"建立对获奖组织的巡访及动态管理制度。评委会办公室及有关部门有权及时了解获奖组织和个人的生产经营和质量管理等情况，督促其珍惜荣誉、不断进步。"},{"no":"二十九","title":"","text":"获奖组织和个人可在组织和个人形象宣传中使用获奖称号，并注明获奖年度，不得出售、出租证书、奖牌或将其用于从事其他营利性活动。"},{"no":"三十","title":"","text":"对弄虚作假，采取不正当手段骗取市长质量奖荣誉的组织或个人，由评委会办公室调查核实后，提交评委会研究并提请市人民政府撤销其市长质量奖奖项，收回奖牌、证书，并向社会公告。该组织或个人不得参加下两届市长质量奖的申报。"},{"no":"三十一","title":"","text":"获奖组织或个人在获奖后5年内如发生下列情形之一的，由评委会办公室调查核实并提交评委会研究，报请市人民政府撤销其市长质量奖奖项，并向社会公告：(一)组织或个人所属组织发生了重大质量、安全、环保、卫生等责任事故的;(二)产品、工程、服务或环境质量不稳定，经国家级或省级质量监督抽查判定为严重不合格的;(三)产品、工程、服务或环境质量发生重大问题，被有关方面和群众投诉并查证属实的;(四)出口产品因质量问题被国外通报或索赔，造成国家形象和产品信誉受到较大损害的;(五)因经营管理不善，出现严重经营性亏损的;(六)不能履行向社会推广、分享其质量工作经验和成果的义务，典型示范作用不能充分体现的;(七)滥用市长质量奖标志、获奖称号，出售、出租证书和奖牌或将其用于从事其他营利性活动的;(八)被有关部门列入严重失信主体名单的;(九)发生其他严重违反法律、法规行为的。"},{"no":"三十二","title":"","text":"承担市长质量奖评审任务的工作机构、工作人员、评审人员要依法保守申报组织和个人的商业或技术秘密，严于律己，公正廉洁，严格按照有关规定、程序进行评审。"},{"no":"三十三","title":"","text":"对在评审过程中滥用职权、玩忽职守、徇私舞弊、造成不良后果的工作机构、工作人员、评审人员，取消其评审工作资格，并提请其主管部门或所在工作单位给予纪律处分;构成犯罪的，依法追究刑事责任。"},{"no":"三十四","title":"","text":"任何组织和个人发现市长质量奖评审存在问题的，可以向评委会办公室投诉举报，评委会办公室按照规定进行调查核实。"},{"no":"三十五","title":"","text":"参与市长质量奖评审的人员与申报组织或申报个人有利害关系的，应当主动提出回避。评委会办公室对回避情况进行监督，对未能主动提出回避的人员可以提出回避建议。"},{"no":"三十六","title":"","text":"接受市长质量奖现场评审的候选组织和个人，对现场评审人员和参与现场评审的其他工作人员的工作质量、纪律作风进行评价，并反馈评委会办公室。"},{"no":"三十七","title":"","text":"申报组织和申报个人应当主动申明申报材料中涉及的商业秘密或者技术秘密。参与市长质量奖评审的有关机构和人员，应当保守知悉的商业秘密和技术秘密。"},{"no":"三十八","title":"第八章 异议处理","text":"任何单位或者个人对市长质量奖评选表彰有异议的，可以向评委会办公室提出，并提供有效的证明材料。"},{"no":"三十九","title":"","text":"评委会办公室应当在法律规章规定的时限内，按法定程序对异议进行调查处理，将异议处理结果告知异议方，并向评委会通报。"},{"no":"四十","title":"第九章 推广与分享","text":"获奖组织应不断推进技术创新、管理创新，创造更具特色的质量经营管理新方案、新经验，带动全市质量整体水平提升。"},{"no":"四十一","title":"","text":"各县市区人民政府、各有关部门及相关行业协会按照职能职责，组织本地区、本领域获奖组织和个人开展质量管理交流推广活动。不得借推广名义从事任何营利性活动。"},{"no":"四十二","title":"","text":"获奖组织和个人应当发挥模范引领作用，主动分享质量管理模式和方法的实践，积极开展质量管理模式和方法推广活动。"},{"no":"四十三","title":"","text":"获奖组织应当为其他组织了解学习其质量管理模式和方法提供便利条件。国家另有规定的除外。"},{"no":"四十四","title":"第十章 附则","text":"本办法自发布之日起施行，有效期5年。"}],"interpretations":[{"sectionNo":"三","headline":"市长质量奖每2年评一届，每届不超过5个组织、2名个人","who":"邵阳市行政区域内的组织和个人；评选经市委、市政府同意并报省委、省政府批准后开展。","materials":[],"window":"评选周期为2年，每届评审前发布公告","where":"市人民政府、市长质量奖评审委员会","tip":"提名奖每届不超过10个组织和个人；未达到奖励条件可以空缺。"},{"sectionNo":"八","headline":"在邵阳依法成立的企业可申报，近3年无较大事故","who":"在邵阳市行政区域内依法成立的国有企业、民营企业、外商投资企业；具备健全质量管理体系并取得体系认证证书、已实施卓越绩效管理模式；符合产业环保质量政策，列入国家强制监督管理范围的须取得相关证照；近3年内无较大质量、安全、环保、公共卫生等事故，无违法违规违纪行为。","materials":["质量管理体系认证证书","国家强制监督管理范围内的相关证照"],"window":"近3年内无较大质量、安全、环保、公共卫生等事故","where":"邵阳市（市长质量奖评审）","tip":"产品、工程和服务质量及自主创新能力须在行业内处于领先地位，顾客满意程度高。"},{"sectionNo":"九","headline":"质量工作作出突出贡献的个人可申报市长质量奖","who":"政治坚定、恪守职业道德和社会公德、无违法违规违纪行为；有较强质量意识和创新能力；具有卓有成效的质量管理理论研究或丰富实践经验并在工作领域作出突出贡献；具有良好诚信记录的个人。","materials":[],"window":"按每届评审公告要求申报","where":"邵阳市（市长质量奖评审）","tip":"个人奖每届不超过2名。"},{"sectionNo":"十","headline":"已获中国质量奖、省长质量奖的不得申报市长质量奖","who":"拟申报市长质量奖的组织和个人","materials":[],"window":"获奖后两届内不得再次申报","where":"评委会办公室","tip":"获得市长质量奖（不含提名奖）后两届内不得再次申报。"},{"sectionNo":"十一","headline":"评审依据GB/T19580、GB/T19579卓越绩效评价准则","who":"申报市长质量奖的组织和个人","materials":[],"window":"每届评审时","where":"评委会办公室","tip":"评审标准覆盖领导、战略、顾客与市场、资源、过程管理、测量分析与改进、经营结果。"},{"sectionNo":"十四","headline":"向所在县市区市场监管部门申请，经初审后推荐","who":"符合申报条件的组织或个人","materials":["申报材料"],"window":"每届评审公告规定的申报时间内","where":"所在县市区市场监管部门、评委会办公室","tip":"须报请所在县市区人民政府批准后，由县市区市场监管部门向评委会办公室推荐。"},{"sectionNo":"二十五","headline":"获奖组织和个人获颁证书和奖牌","who":"获得市长质量奖和市长质量奖提名奖的组织和个人","materials":[],"window":"每届评审审定后","where":"市人民政府","tip":"市长质量奖与提名奖均颁发证书和奖牌。"},{"sectionNo":"二十九","headline":"获奖者可宣传使用称号，须注明获奖年度","who":"获奖组织和个人","materials":[],"window":"获奖后","where":"组织和个人形象宣传","tip":"不得出售、出租证书、奖牌或将其用于其他营利性活动。"},{"sectionNo":"三十","headline":"弄虚作假骗奖的撤销奖项，两届内不得再申报","who":"申报市长质量奖的组织和个人","materials":[],"window":"查实后撤销；下两届不得申报","where":"评委会办公室、市人民政府","tip":"收回奖牌、证书并向社会公告。"},{"sectionNo":"三十一","headline":"获奖后5年内发生重大事故等情形将被撤销奖项","who":"获奖组织和个人","materials":[],"window":"获奖后5年内","where":"评委会办公室、市人民政府","tip":"包括重大质量、安全、环保、卫生责任事故，严重经营性亏损，被列入严重失信主体名单等情形。"},{"sectionNo":"三十四","headline":"发现评审问题可向评委会办公室投诉举报","who":"任何组织和个人","materials":[],"window":"评审期间及评审结束后","where":"评委会办公室","tip":"评委会办公室按规定进行调查核实。"},{"sectionNo":"三十七","headline":"申报时应主动申明商业秘密或技术秘密","who":"申报组织和申报个人","materials":[],"window":"申报时","where":"评委会办公室","tip":"评审机构和人员应保守知悉的商业秘密和技术秘密。"},{"sectionNo":"三十八","headline":"对评选表彰有异议可向评委会办公室提出","who":"任何单位或者个人","materials":["有效的证明材料"],"window":"评选表彰期间","where":"评委会办公室","tip":"提出异议须提供有效的证明材料。"}],"sourceUrl":"https://www.shaoyang.gov.cn/shaoyang/szfbwj/202607/e01b8db73faa46d6bd7516ad98eca8bb.shtml","derivedFrom":"official","sourceNote":"2026-11-22 取自邵阳市人民政府门户「文件库—市政府办规范性文件」原文页，版头载文号邵市政办发〔2026〕7号、统一登记号 SYCR-2026-01005，页面信息有效期栏载2031-07-24。 2026-11-22 收录：与官方页面逐句比对，命中 13/13 句（100%），关卡判定「verbatim」。 有效期依据：第四十四条明示“有效期5年”；页面信息有效期栏载2031-07-24（自2026-07-25起算） 2026-11-24 收录：与官方页面逐句比对，命中 62/62 句（100%），关卡判定「verbatim」。 有效期依据：原文未明示","verified":false,"isSample":false,"numberStyle":"clause","bodyVerified":"verbatim","hunan":true},{"id":"sy-sme-fund-2026","title":"邵阳市财政局 邵阳市工业和信息化局关于印发《邵阳市中小企业发展专项资金管理办法》的通知","level":"city","region":"邵阳市","issuer":"邵阳市财政局、邵阳市工业和信息化局","documentNo":"邵财企〔2026〕2号","publishedAt":"2026-05-20","effectiveAt":"2026-05-20","expiresAt":"2029-05-19","status":"active","tags":["专项资金","融资支持"],"audience":["专精特新中小企业","中小企业公共服务平台","创新创业基地","中小微企业核心服务机构"],"summary":"市级中小企业发展专项资金管理办法，支持“专精特新”发展、中小企业公共服务体系与融资服务体系建设、企业培训展会展销供需对接等方向，采取财政补助、以奖代补等方式，按因素法、项目法或两者结合分配；办法本身不列具体补助金额，第四条明确由市财政局会同市工信局确定支持方式和标准，具体额度以年度申报通知为准；专项资金下达前15日以上报送分配方案，收到指标发文30日内拨付；自公布之日起施行，有效期3年。","sections":[{"no":"一","title":"","text":"为规范邵阳市中小企业发展专项资金的使用管理，提高资金的使用效益，根据《中华人民共和国预算法》《中华人民共和国中小企业促进法》和《湖南省实施〈中华人民共和国中小企业促进法〉办法》《湖南省中小企业发展专项资金管理办法》等有关规定，结合我市实际，制定本办法。"},{"no":"二","title":"","text":"本办法所称邵阳市中小企业发展专项资金(以下简称专项资金)，是指依据《中华人民共和国中小企业促进法》设立，由市级财政一般公共预算安排用于支持中小企业发展的资金。"},{"no":"三","title":"","text":"专项资金管理使用遵循公开公正、择优高效的原则，围绕党中央、国务院、省委、省政府和市委、市政府有关决策部署，重点引导完善中小企业公共服务体系、改善中小企业发展环境，突破制约中小企业发展的短板和瓶颈，支持中小企业高质量发展。"},{"no":"四","title":"","text":"专项资金由市财政局和市工业和信息化局按职责分工共同管理。市财政局负责明确年度专项资金额度，会同市工业和信息化局确定专项资金支持方向和重点、支持方式和标准;根据市工业和信息化局报送的年度专项资金分配方案、绩效目标建议及有关材料，按程序下达预算、绩效目标并拨付资金;督促市工业和信息化局开展监督管理工作。市工业和信息化局负责提出专项资金年度支持方向和重点、资金需求测算方案、绩效目标;组织项目申报、汇总、审查、评审;根据年度预算编制要求，及时向市财政局提供年度专项资金分配方案;加强业务指导、绩效管理、监督管理等工作;督促有关方做好专项资金支持政策实施工作。各县市区财政、工信部门参照市级部门职责分工做好专项资金下达后的资金使用、项目报备、业务指导等工作，并进行监督和全过程绩效管理。资金申报、使用单位承担资金及项目绩效目标的真实客观申报，合规使用和有效管理的主体责任，负责直接受理资金申报材料的主管部门承担资金申报审核、资金使用监督的直接责任。"},{"no":"五","title":"","text":"专项资金实行管理办法、申报通知、评审结果、分配结果、绩效评价全过程公开。"},{"no":"六","title":"","text":"专项资金的支持范围包括：(一)促进中小企业发展。主要支持全市中小企业“专精特新”发展，推动中小企业实现专业化、精细化、特色化、创新化发展和数字化转型。(二)完善中小企业服务体系项目，融资服务体系建设。主要支持加强中小企业公共服务体系建设，市县两级中小企业公共服务平台建设、能力提升、服务活动开展;支持省级中小微企业创新创业基地建设、省级以上园区中小企业服务站和省级中小微企业核心服务机构开展公益性专业化企业服务。(三)其他促进中小企业发展的工作。主要支持承办国家、省级企业培训、展会展销、供需对接、招商引资等服务中小企业发展的活动项目，以及开展中小企业项目评审经费。在符合上述支持方向内，每年根据党中央、国务院、省委、省政府和市委、市政府有关决策部署，结合我市中小企业发展实际情况、亟待突破的短板和瓶颈等，由市财政局、市工业和信息化局按照零基安排、绩效导向的原则确定专项资金支持重点。对符合规定条件的新增重大项目和政策，市工业和信息化局要组织开展事前绩效评估。"},{"no":"七","title":"","text":"专项资金支持对象包括符合条件的项目或企业、中小企业公共服务平台等机构或载体。"},{"no":"八","title":"","text":"专项资金采取财政补助、以奖代补等支持方式，主要用于引导各级政府、社会资本等支持中小企业高质量发展。"},{"no":"九","title":"","text":"专项资金不得用于平衡本级财政预算及偿还债务，不得用于行政事业单位人员经费、机构运转经费等。"},{"no":"十","title":"","text":"专项资金分配可以采取因素法、项目法、因素法和项目法相结合等方式。"},{"no":"十一","title":"","text":"专项资金下达时间进度按照预算管理有关规定执行。市工业和信息化局在专项资金下达前15日以上报送专项资金分配方案。各级财政部门应在收到专项资金指标发文30日内，将专项资金按要求拨付使用单位。"},{"no":"十二","title":"","text":"专项资金支付按照财政国库管理制度有关规定执行，涉及政府采购的，应当按照政府采购法律法规和有关制度执行。"},{"no":"十三","title":"","text":"市财政局、市工业和信息化局根据预算绩效管理和本办法的规定，以及专项资金有关支持政策文件，按照职责分工组织实施专项资金的绩效运行监控、绩效评价，加强绩效评价结果反馈应用。有关绩效评价结果，作为专项资金分配的重要参考。各县市区财政、工信部门应按规定要求实施绩效评价。"},{"no":"十四","title":"","text":"市工业和信息化局应当会同市财政局加强对专项资金的监督管理。各县市区工信、财政部门要建立健全专项资金使用管理、监督检查和跟踪问效制度，如发现资金申报、资金使用存在问题的，应当及时报告市工业和信息化局和市财政局。"},{"no":"十五","title":"","text":"资金使用单位收到专项资金后应当按照国家统一的财务会计制度规定管理。专项资金应当专款专用，主动接受财政、审计等部门的监督检查，不得用于支付各种罚款、捐款、赞助等。有关项目实施情况应当接受工信、财政等部门的调度和检查。"},{"no":"十六","title":"","text":"资金使用单位因市场环境、政策变化等导致不再符合专项资金支持标准的，应及时向直接受理其资金申报材料的工信、财政部门报告，有关工信、财政部门应及时向市工业和信息化局、市财政局报告。市工业和信息化局会同市财政局提出处理意见，县市区有关部门督促落实，并按要求暂缓、停止拨付资金或收回已拨付资金。"},{"no":"十七","title":"","text":"专项资金应当严格执行有关财务、会计制度，实行专款专用，不得列支与项目无关的费用。"},{"no":"十八","title":"","text":"专项资金申报、评审、分配、拨付使用等过程中存在虚报、冒领、截留、挪用、滥用职权、玩忽职守、徇私舞弊等违法违纪行为的，严格按照《中华人民共和国预算法》《中华人民共和国公务员法》《中华人民共和国监察法》《财政违法行为处罚处分条例》等国家有关规定追究责任，涉嫌犯罪的，移送司法机关处理。资金使用单位应当严格遵守财政财务制度和财经纪律，建立健全专项资金管理制度和内部控制制度，加强财务稽核和内部审计，自觉接受审计、财政及主管部门的监督检查。"},{"no":"十九","title":"","text":"本办法自公布之日起施行,有效期3年。原《邵阳市专精特新“小巨人”企业培育专项资金管理办法》(邵财企〔2022〕4号)同时废止。"}],"interpretations":[{"sectionNo":"六","headline":"专项资金支持专精特新、公共服务体系及培训会展三类方向","who":"全市中小企业（重点支持“专精特新”发展、数字化转型）；市县两级中小企业公共服务平台、省级中小微企业创新创业基地、省级以上园区中小企业服务站、省级中小微企业核心服务机构；承办国家、省级培训会展展销、供需对接、招商引资等活动的单位。","materials":[],"window":"按年度确定支持重点；新增重大项目和政策须开展事前绩效评估","where":"市财政局、市工业和信息化局（确定支持重点）","tip":"每年支持重点会调整，按零基安排、绩效导向确定；新增重大项目须事前绩效评估"},{"sectionNo":"八","headline":"专项资金以财政补助、以奖代补方式支持中小企业","who":"符合专项资金支持范围的中小企业及公共服务平台等机构。","materials":[],"window":"按年度资金安排，原文未设固定申报期","where":"市财政局、市工业和信息化局（按年度申报通知组织）","tip":"以财政补助、以奖代补为主，主要用于引导各级政府和社会资本共同支持中小企业"},{"sectionNo":"十一","headline":"资金指标发文后30日内拨付到使用单位","who":"获得专项资金支持的企业、项目单位。","materials":[],"window":"收到专项资金指标发文30日内拨付；市工信局提前15日以上报送分配方案","where":"各级财政部门（拨付）；市工业和信息化局（报送分配方案）","tip":"30日是财政部门拨付时限，不是企业申报时限；超期可向本级财政、工信部门反映"},{"sectionNo":"十六","headline":"不再符合支持标准的须及时报告，否则停拨或收回资金","who":"已获专项资金支持、因市场环境或政策变化不再符合支持标准的资金使用单位。","materials":[],"window":"情况发生后及时报告，原文只写“及时”，未设具体天数","where":"直接受理其资金申报材料的工信、财政部门","tip":"报告后由市工信局会同市财政局提出处理意见，可暂缓、停止拨付或收回已拨付资金"}],"sourceUrl":"https://www.shaoyang.gov.cn/shaoyang/szbmgfxwj/202606/6eb4c7f38d4245c285017e3385de4453.shtml","derivedFrom":"official","sourceNote":"2026-11-22 取自邵阳市人民政府门户「信息公开—文件库—市本级文件库—市直部门规范性文件」原文页，版头载文号邵财企〔2026〕2号、统一登记号 SYCR-2026-10001，页面信息有效期栏载2029-05-19。 2026-11-22 收录：与官方页面逐句比对，命中 8/8 句（100%），关卡判定「verbatim」。 有效期依据：第十九条明示“有效期3年”；页面信息有效期栏载2029-05-19（自2026-05-20起算） 2026-11-24 收录：与官方页面逐句比对，命中 40/40 句（100%），关卡判定「verbatim」。 有效期依据：原文未明示","verified":false,"isSample":false,"numberStyle":"clause","bodyVerified":"verbatim","hunan":true},{"id":"vat-law-transition-preferential-2026","title":"财政部 税务总局关于增值税法施行后增值税优惠政策衔接事项的公告","level":"national","region":"全国","issuer":"财政部、税务总局","documentNo":"财政部 税务总局公告2026年第10号","publishedAt":"2026-02-28","effectiveAt":"2026-01-01","expiresAt":"2027-12-31","status":"active","tags":["税收优惠"],"audience":["小规模纳税人","小微企业","个体工商户"],"summary":"2026年至2027年，小规模纳税人月销售额10万元以下免征增值税，3%征收率应税收入减按1%征收。","sections":[{"no":"一","title":"增值税起征点标准","text":"自2026年1月1日至2027年12月31日,小规模纳税人发生应税交易,起征点标准如下:\n\n(一)以一个月为一个计税期间的,起征点为月销售额10万元。以一个季度为一个计税期间的,起征点为季度销售额30万元。\n\n(二)按次纳税的,起征点为每次(日)销售额1000元。一日内发生多次应税交易的,按日适用起征点标准。\n\n小规模纳税人发生应税交易,按照规定以扣除相关价款后的余额计算销售额或者允许从含税销售额中扣除相关价款后计算应纳税额的,以扣除相关价款后的不含税余额,适用本条起征点标准。"},{"no":"二","title":"免征增值税的项目","text":"(一)自2026年1月1日起,下列项目免征增值税。\n\n1.农业生产者销售的自产农产品。\n\n《中华人民共和国增值税法实施条例》(以下简称增值税法实施条例)第二十六条所称从事农业生产,是指直接从事植物的种植、收割和动物的饲养、捕捞;初级农产品,是指《财政部 税务总局关于增值税征税具体范围有关事项的公告》(财政部 税务总局公告2026年第9号)附件1《适用9%增值税税率货物范围注释》中的农产品。\n\n纳税人销售外购的初级农产品,以及用外购农产品生产、加工的初级农产品,不属于本项目免征增值税的范围,应当按照规定缴纳增值税。\n\n2.农业机耕、排灌、病虫害防治、植物保护、农牧保险以及相关技术培训业务,家禽、牲畜、水生动物的配种和疾病防治。\n\n增值税法第二十四条第一款第一项所称农业机耕,是指在农业、林业、畜牧业中使用农业机械进行耕作(包括耕耘、种植、收割、脱粒、植物保护等)的业务;排灌,是指对农田进行灌溉或者排涝的业务;病虫害防治,是指从事农业、林业、畜牧业、渔业的病虫害测报和防治的业务;农牧保险,是指为种植业、养殖业、畜牧业种植和饲养的动植物提供保险的业务;相关技术培训,是指与农业机耕、排灌、病虫害防治、植物保护业务相关以及为使农民获得农牧保险知识的技术培训业务;家禽、牲畜、水生动物的配种和疾病防治,包括与该项服务有关的提供药品和医疗用具的业务。\n\n3.医疗机构提供的医疗服务。\n\n增值税法实施条例第二十七条所称医疗机构,具体包括:各级各类医院、门诊部(所)、社区卫生服务中心(站)、急救中心(站)、城乡卫生院、护理院(所)、疗养院、临床检验中心,各级政府及有关部门举办的卫生防疫站(疾病控制中心)、各种专科疾病防治站(所),各级政府举办的妇幼保健所(站)、母婴保健机构、儿童保健机构,各级政府举办的血站(血液中心)等医疗机构,不包括营利性美容医疗机构。\n\n增值税法第二十四条第一款第二项所称医疗服务,是指医疗机构按照不高于地市级以上医疗保障部门牵头制定的医疗服务价格(包括政府指导价和按照规定由供需双方协商确定的价格等),为就医者提供《全国医疗服务价格项目规范》所列的各项服务,以及医疗机构向社会提供卫生防疫、卫生检疫的服务。\n\n4.残疾人个人提供的服务。\n\n增值税法第二十四条第一款第六项所称残疾人个人提供的服务,是指残疾人本人为社会提供的服务。\n\n5.托儿所、幼儿园提供的育养服务。\n\n增值税法实施条例第二十九条所称有关收费标准,是指公办托儿所、幼儿园经当地有关部门批准的收费标准,以及民办托儿所、幼儿园实行政府指导价管理或政府设置参考区间的实际收费标准。\n\n保育费、保育教育费超过规定收费标准的,以及以开办实验班、特色班和兴趣班等名义收取的费用,与入托、入园挂钩的赞助费、支教费等超过规定范围的各种费用,不属于免征增值税的范围。\n\n6.殡葬服务。\n\n增值税法第二十四条第一款第七项所称的殡葬服务,是指收费标准由各地价格主管部门会同有关部门核定,或者实行政府指导价管理的遗体接运(含抬尸、消毒)、遗体整容、遗体防腐、遗体存放(含冷藏)、遗体火化、骨灰寄存、吊唁设施设备租赁、墓穴租赁及管理等服务。\n\n7.学校提供的学历教育服务。\n\n(1)增值税法第二十四条第一款第八项所称的学历教育,具体包括:\n\n初等教育:普通小学、成人小学。\n\n初级中等教育:普通初中、职业初中、成人初中。\n\n高级中等教育:普通高中、成人高中、中等职业学校(包括普通中专、成人中专、职业高中、技工学校)。\n\n高等教育:普通本专科、成人本专科、网络本专科、研究生(博士、硕士)、高等教育自学考试、高等教育学历文凭考试。\n\n(2)增值税法实施条例第三十条所称学校,具体包括:\n\n普通学校;经地市级以上人民政府或者同级政府的教育行政部门批准成立、国家承认其学员学历的各类学校;经省级及以上人力资源社会保障行政部门批准成立的技工学校、高级技工学校;经省级人民政府批准成立的技师学院。上述学校均包括符合规定的从事学历教育的民办学校,但不包括职业培训机构等国家不承认学历的教育机构。\n\n(3)提供学历教育服务免征增值税的收入,是指学校为列入规定招生计划的在籍学生提供学历教育服务取得的收入,具体包括:经有关部门审核批准并按规定标准收取的学费、住宿费、课本费、作业本费、考试报名费收入,以及学校食堂提供餐饮服务取得的伙食费收入。除此之外的收入,包括学校以各种名义收取的赞助费、择校费等,不属于免征增值税的范围。\n\n8.农业生产用地,具体包括:\n\n(1)将国有农用地出租给农业生产者用于农业生产。\n\n(2)将土地使用权转让给农业生产者用于农业生产。\n\n(3)采取转包、出租、互换、转让、入股等方式将承包地流转给农业生产者用于农业生产。\n\n9.个人从事金融商品转让业务取得的收入。\n\n10.美国船级社(ABS)在非营利宗旨不变、中国船级社在美国享受同等免税待遇的前提下,在中国境内提供的船检服务。\n\n11.台湾航运公司、航空公司从事海峡两岸海上直航、空中直航业务在大陆取得的运输收入。\n\n台湾航运公司,是指取得交通运输部颁发的“台湾海峡两岸间水路运输许可证”且该许可证上注明的公司登记地址在台湾的航运公司。\n\n台湾航空公司,是指取得中国民用航空局颁发的“经营许可”或者依据《海峡两岸空运协议》和《海峡两岸空运补充协议》规定,批准经营两岸旅客、货物和邮件不定期(包机)运输业务,且公司登记地址在台湾的航空公司。\n\n12.土地所有者出让土地使用权和土地使用者将土地使用权归还给土地所有者。\n\n13.县级以上地方人民政府或自然资源行政主管部门出让、转让或收回自然资源使用权(不含土地使用权)。\n\n14.香港市场投资者(包括单位和个人)买卖股票、基金,具体包括:\n\n(1)通过深港通买卖深圳证券交易所上市A股取得的收入。\n\n(2)通过沪港通买卖上海证券交易所上市A股取得的收入。\n\n(3)通过基金互认买卖内地基金份额取得的收入。\n\n15.被撤销金融机构以货物、不动产、无形资产、有价证券、票据等财产清偿债务。\n\n被撤销金融机构,是指经中国人民银行、金融监管总局依法决定撤销的金融机构及其分设于各地的分支机构,包括被依法撤销的商业银行、信托公司、财务公司、金融租赁公司、信用社。除另有规定外,被撤销金融机构所属、附属企业,不享受被撤销金融机构增值税免税政策。\n\n16.人民银行对金融机构的贷款的利息收入。\n\n17.外汇管理部门在从事国家外汇储备经营过程中,委托金融机构发放的外汇贷款取得的利息收入。\n\n18.个人(不含个体工商户中的一般纳税人)销售自建自用住房。\n\n19.涉及家庭财产分割的个人无偿转让不动产、土地使用权。\n\n家庭财产分割,包括下列情形:离婚财产分割;无偿赠予配偶、父母、子女、祖父母、外祖父母、孙子女、外孙子女、兄弟姐妹;无偿赠予对其承担直接抚养或者赡养义务的抚养人或者赡养人;房屋产权所有人死亡,法定继承人、遗嘱继承人或者受遗赠人依法取得房屋产权。\n\n20.执法部门和单位处置罚没财产收入,且作为罚没收入如数上缴财政的。\n\n21.下列文件中现行有效的增值税优惠政策。\n\n(1)《财政部 国家税务总局 外经贸部关于外国政府和国际组织无偿援助项目在华采购物资免征增值税问题的通知》(财税〔2002〕2号)和《财政部 国家税务总局关于外国政府和国际组织无偿援助项目在华采购物资免征增值税的补充通知》(财税〔2005〕13号)。\n\n(2)《财政部 税务总局关于全国社会保障基金有关投资业务税收政策的通知》(财税〔2018〕94号)。\n\n(3)《财政部 税务总局关于基本养老保险基金有关投资业务税收政策的通知》(财税〔2018〕95号)。\n\n(4)《财政部 税务总局 证监会关于交易型开放式基金纳入内地与香港股票市场交易互联互通机制后适用税收政策问题的公告》(财政部 税务总局 证监会公告2022年第24号)。\n\n(5)《财政部 税务总局关于法律援助补贴有关税收政策的公告》(财政部 税务总局公告2022年第25号)。\n\n(6)《财政部 税务总局关于国债等债券利息收入增值税政策的公告》(财政部 税务总局公告2025年第4号)。\n\n(7)《财政部 税务总局关于划转充实社保基金国有股权及现金收益运作管理税收政策的通知》(财税〔2025〕26号)。\n\n(二)自2026年1月1日至2027年12月31日,下列项目免征增值税。\n\n1.农业生产资料。\n\n(1)农膜、滴灌带、滴灌管和有机肥产品。\n\n(2)饲料产品。具体包括:\n\n单一大宗饲料。指以一种动物、植物、微生物或矿物质为来源的产品或其副产品。其范围仅限于糠麸、酒糟、鱼粉、饲用鱼油、草饲料及除豆粕以外的菜籽粕、棉籽粕、向日葵粕、花生粕等粕类产品。\n\n混合饲料。指由两种以上单一大宗饲料、粮食、粮食副产品及饲料添加剂按照一定比例配置,其中单一大宗饲料、粮食及粮食副产品的掺兑比例不低于95%的饲料。\n\n配合饲料。指根据不同的饲养对象的不同生长发育阶段的营养需要,将多种饲料原料按饲料配方经工业生产后,形成能满足饲养动物全部营养需要(除水分外)的饲料。\n\n复合预混料。指能够按照国家有关饲料产品的标准要求量,全面提供动物饲养相应阶段所需微量元素(4种或以上)、维生素(8种或以上),由微量元素、维生素、氨基酸和非营养性添加剂中任何两类或两类以上的组分与载体为原料、经高压浓缩制成的块状预混物,可供牛、羊等牲畜直接食用的饲料,属于浓缩饲料。\n\n浓缩饲料。指由蛋白质、复合预混料及矿物质等按一定比例配制的均匀混合物。\n\n矿物质微量元素舔砖。指以四种以上微量元素、非营养性添加剂和载体为原料,经高压浓缩制成的块状预混物,可供牛、羊等牲畜直接食用的饲料,属于浓缩饲料。\n\n宠物饲料不属于免征增值税的饲料。\n\n(3)批发和零售的种子、种苗、农药、农机。农机包括不带动力的手扶拖拉机和三轮农用运输车。\n\n(4)农民专业合作社销售本社成员生产的初级农产品,属于农业生产者销售的自产农产品。\n\n农民专业合作社向本社成员销售的农膜、种子、种苗、农药、农机。\n\n农民专业合作社,是指依法设立和登记的农民专业合作社。\n\n2.纳税人提供技术转让、技术开发和与之相关的技术咨询、技术服务。\n\n技术转让、技术开发,是指《财政部 税务总局关于增值税征税具体范围有关事项的公告》(财政部 税务总局公告2026年第9号)附件2《销售服务、无形资产、不动产注释》中的转让“技术”、提供“研发服务”范围内的业务活动。技术咨询,是指就特定技术项目提供可行性论证、技术预测、专题技术调查、分析评价报告等业务活动。与技术转让、技术开发相关的技术咨询、技术服务,是指转让方(或者受托方)根据技术转让或者委托开发合同的规定,为帮助受让方(或者委托方)掌握所转让(或者委托开发)的技术,而提供的技术咨询、技术服务业务,且这部分技术咨询、技术服务的价款与技术转让或者技术开发的价款应当在同一张发票上开具。\n\n纳税人申请免征增值税时,须持技术转让、开发的书面合同,到纳税人所在地省级科技、工信主管部门进行认定,并持有关的书面合同和科技、工信主管部门审核意见证明文件报主管税务机关备查。\n\n3.个人转让著作权。\n\n4.按照国家规定的收费标准向学生收取的高校学生公寓住宿费收入和高校学生食堂为高校师生提供餐饮服务取得的收入。\n\n5.家政服务企业由员工制家政服务员提供家政服务取得的收入。\n\n家政服务企业,是指在企业营业执照的规定经营范围中包括家政服务内容的企业。员工制家政服务员,是指同时符合下列3个条件的家政服务员:\n\n(1)依法与家政服务企业签订半年及半年以上的劳动合同或者服务协议,且在该企业实际上岗工作。\n\n(2)家政服务企业为其按月足额缴纳了企业所在地人民政府根据国家政策规定的基本养老保险、基本医疗保险、工伤保险、失业保险等社会保险。对已享受新型农村养老保险和新型农村合作医疗等社会保险或者下岗职工原单位继续为其缴纳社会保险的家政服务员,如果本人书面提出不再缴纳企业所在地人民政府根据国家政策规定的相应的社会保险,并出具其所在乡镇或者原单位开具的已缴纳相关保险的证明,可视同家政服务企业已为其按月足额缴纳了相应的社会保险。\n\n(3)家政服务企业通过金融机构向其实际支付不低于企业所在地适用的经省级人民政府批准的最低工资标准的工资。\n\n6.国家助学贷款取得的利息收入。\n\n7.福利彩票、体育彩票的发行收入。\n\n8.社会团体收取的会费。\n\n社会团体,是指依照国家有关法律法规设立或登记并取得《社会团体法人登记证书》的非营利法人。会费,是指社会团体在国家法律法规、政策许可的范围内,依照社团章程的规定,收取的个人会员、单位会员和团体会员的会费。\n\n9.中国邮政集团有限公司及其所属邮政企业提供的邮政普遍服务和邮政特殊服务。\n\n10.军队转业干部和随军家属就业。\n\n(1)从事个体经营的军队转业干部,自办理税务登记事项之日起,其提供的应税服务3年内免征增值税。\n\n为安置自主择业的军队转业干部就业而新开办的企业,凡安置自主择业的军队转业干部占企业总人数60%(含)以上的,自办理税务登记事项之日起,其提供的应税服务3年内免征增值税。\n\n享受上述优惠政策的自主择业的军队转业干部必须持有师以上部队颁发的转业证件。\n\n(2)从事个体经营的随军家属,自办理税务登记事项之日起,其提供的应税服务3年内免征增值税。\n\n为安置随军家属就业而新开办的企业,自办理税务登记事项之日起,其提供的应税服务3年内免征增值税。\n\n享受税收优惠政策的企业,随军家属必须占企业总人数的60%(含)以上,并有军(含)以上政治和后勤机关出具的证明。\n\n随军家属必须有师以上政治机关出具的可以表明其身份的证明。\n\n按照上述规定,每一名随军家属可以享受一次免税政策。\n\n11.供残疾人专用的假肢、轮椅、矫型器(包括上肢矫型器、下肢矫型器、脊椎侧弯矫型器)。\n\n12.粮食和商品储备收入,具体包括:\n\n(1)销售政府储备食用植物油。\n\n(2)粮食经营企业经营军队用粮、救灾救济粮、水库移民口粮。\n\n军队用粮:指凭相关凭证按军供价供应中国人民解放军和中国人民武装警察部队的粮食。\n\n救灾救济粮:指经县(含)以上人民政府批准,凭相关凭证按规定的销售价格向需救助的灾民供应的粮食。\n\n水库移民口粮:指经县(含)以上人民政府批准,凭相关凭证按规定的销售价格供应给水库移民的粮食。\n\n(3)国家商品储备管理单位及其直属企业承担商品储备任务,从中央或者地方财政取得的利息补贴收入和价差补贴收入。国家商品储备管理单位及其直属企业,是指接受中央、省、市、县四级政府有关部门(或者政府指定管理单位)委托,承担粮(含大豆)、食用油、棉、糖、肉、盐(限于中央储备)等6种商品储备任务,并按有关政策收储、销售上述6种储备商品,取得财政储备经费或者补贴的商品储备企业。利息补贴收入,是指国家商品储备管理单位及其直属企业因承担商品储备任务从金融机构贷款,并从中央或者地方财政取得的用于偿还贷款利息的贴息收入。价差补贴收入包括销售价差补贴收入和轮换价差补贴收入。销售价差补贴收入,是指按照中央或者地方政府指令销售上述储备商品时,由于销售收入小于库存成本而从中央或者地方财政获得的全额价差补贴收入。轮换价差补贴收入,是指根据要求定期组织政策性储备商品轮换而从中央或地方财政取得的商品新陈品质价差补贴收入。\n\n13.纳税人提供的直接或者间接国际货物运输代理服务。\n\n(1)纳税人提供直接或者间接国际货物运输代理服务,向委托方收取的全部国际货物运输代理服务收入,以及向国际运输承运人支付的国际运输费用,必须通过金融机构进行结算。\n\n(2)纳税人为大陆与香港、澳门、台湾地区之间的货物运输提供的货物运输代理服务参照国际货物运输代理服务有关规定执行。\n\n(3)委托方索取发票的,纳税人应当就国际货物运输代理服务收入向委托方全额开具增值税普通发票。\n\n14.合格境外投资者(QFII)委托境内公司在我国从事证券买卖业务、人民币合格境外机构投资者(RQFII)委托境内公司在我国从事证券买卖业务,以及经中国人民银行认可的境外机构投资银行间本币市场取得的收入。银行间本币市场包括货币市场、债券市场以及衍生品市场。\n\n15.统借统还业务利息收入。\n\n统借统还业务利息收入,是指统借统还业务中,企业集团或企业集团中的核心企业以及集团所属财务公司按不高于支付给金融机构的借款利率水平或者支付的债券票面利率水平,向企业集团或者集团内下属单位收取的利息。\n\n统借方向资金使用单位收取的利息,高于支付给金融机构借款利率水平或者支付的债券票面利率水平的,应全额缴纳增值税。\n\n统借统还业务,是指:\n\n(1)企业集团或者企业集团中的核心企业向金融机构借款或对外发行债券取得资金后,将所借资金分拨给下属单位(包括独立核算单位和非独立核算单位,下同),并向下属单位收取用于归还金融机构或债券购买方本息的业务。\n\n(2)企业集团向金融机构借款或对外发行债券取得资金后,由集团所属财务公司与企业集团或者集团内下属单位签订统借统还贷款合同并分拨资金,并向下属单位收取用于归还金融机构或债券购买方本息的业务。\n\n16.公募证券投资基金(封闭式证券投资基金、开放式证券投资基金)管理人运用基金买卖股票、债券取得的收入。\n\n17.期货保税交割业务,具体包括:\n\n(1)经国务院批准对外开放的货物期货品种保税交割业务。\n\n(2)上海国际能源交易中心股份有限公司的会员和客户通过上海国际能源交易中心股份有限公司交易的原油期货保税交割业务,大连商品交易所的会员和客户通过大连商品交易所交易的铁矿石期货保税交割业务。\n\n(3)上海期货交易所的会员和客户通过上海期货交易所交易的期货保税交割业务。\n\n18.金融同业往来利息收入,具体包括:\n\n(1)金融机构与人民银行所发生的资金往来业务。包括人民银行对一般金融机构贷款,商业银行购买央行票据、与央行开展货币掉期和货币互存,以及人民银行对商业银行的再贴现等。\n\n(2)银行联行往来业务。包括同一银行系统内部不同行、处之间所发生的资金往来业务,境内银行与其境外的总机构、母公司之间的资金往来业务,以及境内银行与其境外的分支机构、全资子公司之间的资金往来业务。\n\n(3)金融机构间的资金往来业务。是指经人民银行批准,进入全国银行间同业拆借市场的金融机构之间通过全国统一的同业拆借网络进行的短期(一年以下,含一年)无担保资金融通行为。\n\n(4)金融机构开展同业存款、同业借款、同业代付、买断式买入返售金融商品、质押式买入返售金融商品、同业存单,取得的利息收入。\n\n同业存款,是指金融机构之间开展的同业资金存入与存出业务,其中资金存入方仅为具有吸收存款资格的金融机构。\n\n同业借款,是指法律法规赋予此项业务范围的金融机构开展的同业资金借出和借入业务。其中,法律法规赋予此项业务范围的金融机构主要是指农村信用社之间以及在农村信用社营业执照业务范围中有反映为向金融机构借款业务的农村信用社。\n\n同业代付,是指商业银行(受托方)接受金融机构(委托方)的委托向企业客户付款,委托方在约定还款日偿还代付款项本息的资金融通行为。\n\n买断式买入返售金融商品,是指金融商品持有人(正回购方)将债券等金融商品卖给债券购买方(逆回购方)的同时,交易双方约定在未来某一日期,正回购方再以约定价格从逆回购方买回相等数量同种债券等金融商品的交易行为。\n\n质押式买入返售金融商品,是指交易双方进行的以债券等金融商品为权利质押的一种短期资金融通业务。\n\n同业存单,是指银行业存款类金融机构法人在全国银行间市场上发行的记账式定期存款凭证。\n\n金融机构,是指银行,包括人民银行、商业银行、政策性银行;信用社;证券公司、金融租赁公司、证券基金管理公司、财务公司、信托公司;保险公司;其他经中国人民银行、金融监管总局、中国证监会批准成立且经营金融保险业务的金融机构等。\n\n19.保险公司开办的一年期以上人身保险产品取得的保费收入。\n\n一年期以上人身保险,是指保险期间为一年期及以上返还本利的人寿保险、养老年金保险和其他年金保险,以及保险期间为一年期及以上的健康保险。\n\n人寿保险,是指以人的寿命为保险标的的人身保险。\n\n养老年金保险,是指以养老保障为目的,以被保险人生存为给付保险金条件,并按约定的时间间隔分期给付生存保险金的人身保险。\n\n养老年金保险应当同时符合下列条件:\n\n(1)保险合同约定给付被保险人生存保险金的年龄不得小于国家规定的退休年龄。\n\n(2)相邻两次给付的时间间隔不得超过一年。\n\n其他年金保险,是指养老年金以外的年金保险。\n\n健康保险,是指以因健康原因导致损失为给付保险金条件的人身保险。\n\n保险公司开办一年期以上人身保险,在保险监管部门出具备案回执或批复文件前依法取得的保费收入,属于上述规定的保费收入。\n\n20.纳税人提供再保险服务(境内保险公司向境外保险公司提供的再保险服务除外),实行与原保险服务一致的增值税政策。再保险合同对应多个原保险合同的,所有原保险合同均适用免征增值税政策时,该再保险合同适用免征增值税政策。否则,该再保险合同应按规定缴纳增值税。原保险服务,是指保险分出方与投保人之间直接签订保险合同而建立保险关系的业务活动。\n\n21.医疗机构接受其他医疗机构委托,按照不高于地市级以上医疗保障部门牵头制定的医疗服务价格(包括政府指导价和按照规定由供需双方协商确定的价格等),提供《全国医疗服务价格项目规范》所列的各项服务,可适用本公告第二条第一项“医疗机构提供的医疗服务”政策。\n\n22.为了配合国家住房制度改革,企业、行政事业单位按房改成本价、标准价出售住房取得的收入。\n\n23.住房公积金管理中心用住房公积金在指定的委托银行发放的个人住房贷款取得的利息收入。\n\n24.黄金生产和经营单位销售黄金(不包括以下品种:牌号为AU9999、AU9995、AU999、AU995,规格为50克、100克、1公斤、3公斤、12.5公斤的黄金,统称标准黄金)和黄金矿砂(含伴生金)。\n\n25.中国信达资产管理股份有限公司、中国中信金融资产管理股份有限公司、中国长城资产管理股份有限公司和中国东方资产管理股份有限公司及各自经批准分设于各地的分支机构(以下称资产公司),在收购、承接和处置剩余政策性剥离不良资产和改制银行剥离不良资产过程中开展的以下业务:\n\n(1)接受相关国有银行的不良债权,借款方以货物、不动产、无形资产、有价证券和票据等抵充贷款本息的,资产公司销售、转让该货物、不动产、无形资产、有价证券、票据以及利用该货物、不动产从事的融资租赁业务。\n\n(2)接受相关国有银行的不良债权取得的利息。\n\n(3)资产公司所属的投资咨询类公司,为本公司收购、承接、处置不良资产而提供的资产、项目评估和审计服务。\n\n政策性剥离不良资产,是指资产公司按照国务院规定的范围和额度,以账面价值进行收购的相关国有银行的不良资产。\n\n处置不良资产,是指资产公司按照有关法律、行政法规,为使不良资产的价值得到实现而采取的债权转移的措施,具体包括运用出售、置换、资产重组、债转股、证券化等方法对贷款及其抵押品进行处置。\n\n资产公司除收购、承接、处置规定的政策性剥离不良资产和改制银行剥离不良资产业务外,从事其他经营业务应一律依法纳税。\n\n除另有规定者外,资产公司所属、附属企业,不得享受资产公司免征增值税的政策。\n\n26.下列文件中现行有效的增值税优惠政策。\n\n(1)《财政部 国家税务总局关于血站有关税收问题的通知》(财税字〔1999〕264号)。\n\n(2)《财政部 国家税务总局关于医疗卫生机构有关税收政策的通知》(财税〔2000〕42号)第三条。\n\n(3)《财政部 国家税务总局关于中国信达等4家金融资产管理公司税收政策问题的通知》(财税〔2001〕10号)。\n\n(4)《财政部 国家税务总局关于中国东方资产管理公司处置港澳国际(集团)有限公司有关资产税收政策问题的通知》(财税〔2003〕212号)。\n\n(5)《财政部 国家税务总局关于免征蔬菜流通环节增值税有关问题的通知》(财税〔2011〕137号)和《财政部 国家税务总局关于免征部分鲜活肉蛋产品流通环节增值税政策的通知》(财税〔2012〕75号)。\n\n(6)《财政部 国家税务总局关于熊猫普制金币免征增值税政策的通知》(财税〔2012〕97号)。\n\n(7)《财政部 税务总局 海关总署关于第18届世界中学生运动会等三项国际综合运动会税收政策的公告》(财政部 税务总局 海关总署公告2020年第19号)。\n\n(8)《财政部 税务总局关于支持小微企业融资有关税收政策的公告》(财政部 税务总局公告2023年第13号)。\n\n(9)《财政部 税务总局关于金融机构小微企业贷款利息收入免征增值税政策的公告》(财政部 税务总局公告2023年第16号)。\n\n(10)《财政部 税务总局关于延续执行农户、小微企业和个体工商户融资担保增值税政策的公告》(财政部 税务总局公告2023年第18号)。\n\n(11)《财政部 税务总局 科技部 教育部关于继续实施科技企业孵化器、大学科技园和众创空间有关税收政策的公告》(财政部 税务总局 科技部 教育部公告2023年第42号)。\n\n(12)《财政部 税务总局关于延续实施小额贷款公司有关税收优惠政策的公告》(财政部 税务总局公告2023年第54号)。\n\n(13)《财政部 税务总局关于延续实施供热企业有关税收政策的公告》(财政部 税务总局公告2023年第56号)(至2027年供暖期结束)。\n\n(14)《财政部 税务总局关于继续实施农村饮水安全工程税收优惠政策的公告》(财政部 税务总局公告2023年第58号)。\n\n(15)《财政部 税务总局关于延续实施边销茶增值税政策的公告》(财政部 税务总局公告2023年第59号)。\n\n(16)《财政部 税务总局关于延续免征国产抗艾滋病病毒药品增值税政策的公告》(财政部 税务总局公告2023年第62号)。\n\n(17)《财政部 税务总局关于延续实施金融机构农户贷款利息收入免征增值税政策的公告》(财政部 税务总局公告2023年第67号)。\n\n(18)《财政部 税务总局 中央宣传部关于延续实施文化体制改革中经营性文化事业单位转制为企业有关税收政策的公告》(财政部 税务总局 中央宣传部公告2023年第71号)。\n\n(19)《财政部 海关总署 税务总局关于哈尔滨2025年第九届亚洲冬季运动会税收政策的通知》(财税〔2024〕24号)。\n\n(20)《财政部 海关总署 税务总局关于2025年第12届世界运动会税收政策的通知》(财税〔2025〕15号)。"},{"no":"三","title":"适用简易计税方法的项目","text":"(一)自2026年1月1日至2027年12月31日,一般纳税人发生以下应税交易,可以选择适用简易计税方法,按照3%的征收率计算缴纳增值税。\n\n1.销售自行采掘的建筑用和生产建筑材料所用的砂、土、石料,和以自行采掘的砂、土、石料或其他矿物连续自行生产的砖、瓦、石灰(不含粘土实心砖、瓦)。\n\n2.小型水力发电单位销售自产的电力。小型水力发电单位,是指装机容量为5万千瓦以下(含5万千瓦)的小型水力发电单位。\n\n3.销售自来水。水利工程供应天然水比照销售自来水政策执行。\n\n4.寄售商店代销寄售物品(包括居民个人寄售的物品在内)。\n\n5.典当业销售死当物品。\n\n6.提供公共交通运输服务。公共交通运输服务,包括轮客渡、公交客运、地铁、城市轻轨、出租车、长途客运、班车。班车,是指按固定路线、固定时间运营并在固定站点停靠的运送旅客的陆路运输服务。\n\n7.以清包工方式提供的建筑服务。以清包工方式提供建筑服务,是指施工方不采购建筑工程所需的材料或只采购辅助材料,并收取人工费、管理费或者其他费用的建筑服务。\n\n8.为建筑工程老项目提供的建筑服务。建筑工程老项目,是指《建筑工程施工许可证》注明的合同开工日期在2016年4月30日前的建筑工程项目;《建筑工程施工许可证》未注明合同开工日期或者未取得《建筑工程施工许可证》但建筑工程承包合同注明的开工日期在2016年4月30日前的建筑工程项目。\n\n9.依据有关法律、法规批准设立的农村信用社、村镇银行、农村资金互助社、法人机构在县(市、区、旗)及县以下地区的农村合作银行和农村商业银行提供金融服务。县(市、区、旗)不包括直辖市和地级市所辖区。\n\n10.非企业单位提供的研发和技术服务、信息技术服务、鉴证咨询服务,以及销售技术、著作权等无形资产。\n\n11.公路经营企业收取开工日期在2016年4月30日前的高速公路的车辆通行费。高速公路的开工日期,以相关施工许可证明上注明的合同开工日期为准。\n\n12.提供电影放映服务、仓储服务、装卸搬运服务、收派服务和文化体育服务。\n\n13.提供非学历教育服务、教育辅助服务。\n\n14.资管产品管理人运营契约制资管产品过程中发生的增值税应税行为。\n\n资管产品管理人,包括银行、信托公司、公募基金管理公司及其子公司、证券公司及其子公司、期货公司及其子公司、私募基金管理人、保险资产管理公司、专业保险资产管理机构、养老保险公司。\n\n资管产品,包括银行理财产品、资金信托(包括集合资金信托计划、单一资金信托)、财产权信托、公开募集证券投资基金、特定客户资产管理计划、集合资产管理计划、定向资产管理计划、私募投资基金、债权投资计划、股权投资计划、股债结合型投资计划、资产支持计划、组合类保险资产管理产品、养老保障管理产品。\n\n15.下列文件中现行有效的增值税优惠政策。\n\n(1)《财政部 海关总署 税务总局 国家药品监督管理局关于抗癌药品增值税政策的通知》(财税〔2018〕47号)。\n\n(2)《财政部 海关总署 税务总局 药监局关于罕见病药品增值税政策的通知》(财税〔2019〕24号)。\n\n(3)《财政部 海关总署 税务总局 药监局关于发布第二批适用增值税政策的抗癌药品和罕见病药品清单的公告》(财政部 海关总署 药监局公告2020年第39号)。\n\n(4)《财政部 海关总署 税务总局 药监局关于发布第三批适用增值税政策的抗癌药品和罕见病药品清单的公告》(财政部 海关总署 药监局公告2022年第35号)。\n\n(5)《财政部 税务总局关于延续实施中国邮政储蓄银行三农金融事业部涉农贷款增值税政策的公告》(财政部 税务总局公告2023年第66号)。\n\n(二)自2026年1月1日至2027年12月31日,一般纳税人发生以下应税交易,可以选择适用简易计税方法,按照5%的征收率计算缴纳增值税。\n\n1.2016年4月30日前签订的不动产融资租赁合同,或者以2016年4月30日前取得的不动产提供的融资租赁服务。\n\n2.收取开工日期在2016年4月30日前的一级公路、二级公路、桥、闸通行费。公路、桥、闸的开工日期,以相关施工许可证明上注明的合同开工日期为准。\n\n3.出租其2016年4月30日前取得的不动产。\n\n4.销售其2016年4月30日前取得(含自建)的不动产。\n\n5.转让其2016年4月30日前取得的土地使用权。\n\n6.房地产开发企业销售、出租自行开发的房地产老项目。\n\n房地产老项目,是指《建筑工程施工许可证》注明的合同开工日期在2016年4月30日前的房地产项目;《建筑工程施工许可证》未注明合同开工日期或者未取得《建筑工程施工许可证》但建筑工程承包合同注明的开工日期在2016年4月30日前的房地产项目。\n\n房地产开发企业以围填海方式取得土地并开发的房地产项目,以围填海工程《建筑工程施工许可证》或建筑工程承包合同注明的围填海开工日期确定合同开工日期。\n\n房地产开发企业购入未完工的房地产老项目继续开发后,以自己名义立项销售的不动产,属于房地产老项目。\n\n(三)纳税人发生以下应税交易,可以选择适用简易计税方法,按照规定征收率计算缴纳增值税。\n\n1.自2026年1月1日起,一般纳税人销售自己使用过的属于增值税法第二十二条规定不得抵扣且未抵扣进项税额的固定资产,按照简易计税方法依照3%征收率减按2%计算缴纳增值税。\n\n固定资产,是指使用期限超过12个月的机器、机械、运输工具以及其他与生产经营相关的设备、工具、器具等。\n\n2.自2026年1月1日起,小规模纳税人(不含自然人)销售自己使用过的固定资产,按照简易计税方法依照3%征收率减按2%计算缴纳增值税。\n\n3.自2026年1月1日起,销售旧货,按照简易计税方法依照3%征收率减按2%计算缴纳增值税。\n\n旧货,是指进入二次流通的具有部分使用价值的货物(含旧汽车、旧摩托车和旧游艇),但不包括自己使用过的物品。\n\n4.自2026年1月1日起,个人(不含个体工商户中的一般纳税人)出租住房,按照简易计税方法依照3%征收率减按1.5%计算缴纳增值税。\n\n5.自2026年1月1日起,《财政部 税务总局 住房城乡建设部关于完善住房租赁有关税收政策的公告》(财政部 税务总局 住房城乡建设部公告2021年第24号)中现行有效的增值税优惠政策。\n\n6.自2026年1月1日至2027年12月31日,小规模纳税人发生除销售、出租不动产或者转让土地使用权之外的增值税应税交易,依照3%征收率减按1%征收率征收增值税;按规定预缴增值税的项目,当期在预缴地实现的全部价款、预收款(均不含增值税)合计达到增值税起征点的,减按1%预征率预缴增值税。\n\n7.自2026年1月1日至2027年12月31日,《财政部 税务总局关于延续实施二手车经销有关增值税政策的公告》(财政部 税务总局公告2023年第63号)中现行有效的增值税优惠政策。\n\n(四)有关规定。\n\n1.一般纳税人销售自行开发的房地产项目、提供建筑服务,可以按照房地产开发项目、工程建设项目选择适用简易计税方法。除上述情形外,一般纳税人应当就同一简易计税方法项目的全部应税交易一并选择适用简易计税方法。\n\n2.一般纳税人自选择适用简易计税方法当月起,36个月内不得变更;期限届满后,自选择适用一般计税方法当月起,36个月内不得再选择适用简易计税方法。\n\n3.纳税人按照简易计税方法依照规定征收率计算缴纳增值税的,按照下列公式计算销售额:\n\n销售额=含税销售额÷(1+规定征收率)"},{"no":"四","title":"允许从含税销售额中扣除相关价款的应税交易","text":"自2026年1月1日至2027年12月31日,纳税人发生下列应税交易,允许从含税销售额中扣除相关价款后计算销项税额或者应纳税额\n\n(一)金融机构开展贴现、转贴现业务,以其实际持有票据期间取得的利息收入作为销售额。\n\n金融机构开展贴现、转贴现业务需要就贴现利息开具发票的,由贴现机构按照票据贴现利息全额向贴现人开具增值税普通发票,转贴现机构按照转贴现利息全额向贴现机构开具增值税普通发票。\n\n(二)中国证券登记结算有限责任公司按规定提取的证券结算风险基金、收取的证券公司资金交收违约垫付资金利息、结算过程中收取的资金交收违约罚息,允许从含税销售额中扣除。\n\n(三)融资租赁和融资性售后回租业务。\n\n1.经国务院行业主管部门批准(含备案)从事融资租赁业务的纳税人,提供融资租赁服务,支付的借款利息(包括外汇借款和人民币借款利息)、发行债券利息和车辆购置税,允许从含税销售额中扣除。\n\n2.经国务院行业主管部门批准(含备案)从事融资租赁业务的纳税人,提供融资性售后回租服务,对外支付的借款利息(包括外汇借款和人民币借款利息)、发行债券利息,允许从含税销售额(不含本金)中扣除。\n\n3.纳税人根据2016年4月30日前签订的有形动产融资性售后回租合同,在合同到期前提供的有形动产融资性售后回租服务,可以继续按照有形动产融资租赁服务缴纳增值税。\n\n继续按照有形动产融资租赁服务缴纳增值税的纳税人,经国务院行业主管部门批准(含备案)从事融资租赁业务的,根据2016年4月30日前签订的有形动产融资性售后回租合同,可以选择以下方法之一计算销项税额或者应纳税额:\n\n(1)向承租方收取的价款本金,以及对外支付的借款利息(包括外汇借款和人民币借款利息)、发行债券利息,允许从含税销售额中扣除。\n\n纳税人提供有形动产融资性售后回租服务,计算当期销项税额或者应纳税额时可以扣除的价款本金,为书面合同约定的当期应当收取的本金。无书面合同或者书面合同没有约定的,为当期实际收取的本金。\n\n(2)支付的借款利息(包括外汇借款和人民币借款利息)、发行债券利息,允许从含税销售额中扣除。\n\n4.经商务部授权的省级商务主管部门和国家经济技术开发区批准(含备案)的从事融资租赁业务的纳税人,实收资本达到1.7亿元的,从达到标准的当月起按照上述规定执行。\n\n(四)纳税人提供建筑服务适用简易计税方法计税的,支付的分包款允许从含税销售额中扣除。\n\n(五)一般纳税人提供劳务派遣服务,代用工单位支付给劳务派遣员工的工资、福利和为其办理的社会保险及住房公积金,允许从含税销售额中扣除。\n\n劳务派遣服务,是指取得《劳务派遣经营许可证》的劳务派遣公司,为了满足用工单位对于各类灵活用工的需求,将员工派遣至用工单位,接受用工单位管理并为其工作的服务。\n\n取得《保安服务许可证》的保安服务公司,提供安全保护服务(含武装守护押运服务)比照上述政策执行。\n\n(六)纳税人提供旅游服务,向旅游服务购买方收取并支付给其他单位或者个人的住宿费、餐饮费、交通费、签证费、门票费和支付给其他接团旅游企业的旅游费用,允许从含税销售额中扣除。\n\n(七)纳税人转让其2016年4月30日前取得的土地使用权,选择适用简易计税方法计税的,取得该土地使用权的原价允许从含税销售额中扣除。\n\n(八)一般纳税人销售其2016年4月30日前取得(不含自建)的不动产,选择适用简易计税方法计税的,以及小规模纳税人销售其取得(不含自建)的不动产(不含个人销售购买的住房),该项不动产购置原价或者取得不动产时的作价允许从含税销售额中扣除。\n\n(九)房地产开发企业销售房地产项目。\n\n房地产开发企业销售其开发的适用一般计税方法计税的房地产项目,受让土地时向政府部门支付的土地出让金、征地和拆迁补偿费用、土地前期开发费用和土地出让收益(以下统称土地价款),以及在取得土地时向其他单位或个人支付的货币形式拆迁补偿费用,允许从含税销售额中扣除。\n\n当期允许扣除的土地价款=(当期销售房地产项目建筑面积÷房地产项目可供销售建筑面积)×支付的土地价款\n\n当期销售房地产项目建筑面积,是指当期进行纳税申报的增值税销售额对应的建筑面积。\n\n房地产项目可供销售建筑面积,是指房地产项目可以出售的总建筑面积,不包括销售房地产项目时未单独作价结算的配套公共设施的建筑面积。\n\n房地产开发企业(包括多个房地产开发企业组成的联合体)受让土地向政府部门支付土地价款后,设立项目公司对该受让土地进行开发,同时符合下列条件的,可由项目公司按规定扣除房地产开发企业向政府部门支付的土地价款。\n\n1.房地产开发企业、项目公司、政府部门三方签订变更协议或补充合同,将土地受让人变更为项目公司;\n\n2.政府部门出让土地的用途、规划等条件不变的情况下,签署变更协议或补充合同时,土地价款总额不变;\n\n3.项目公司存续期间的全部股权由受让土地的房地产开发企业持有。\n\n(十)纳税人开展金银首饰以旧换新业务,旧金银首饰的作价允许从含税销售额中扣除。\n\n(十一)纳税人按照本公告第四条第三项至第九项规定从含税销售额中扣除的价款,应当取得符合法律、行政法规或者税务总局规定的合法有效凭证留存备查。否则,不得扣除。\n\n1.适用第四条第五项规定,以工资、福利支付记录,社会保险缴费记录以及住房公积金缴存记录为合法有效凭证。\n\n2.适用第四条第七、九项规定,向政府支付土地价款的,以省级以上(含省级)财政部门监(印)制的财政票据为合法有效凭证。\n\n3.适用第四条第七、八项规定,向其他单位或者个人支付的款项,以发票或者法院判决书、裁定书、调解书,以及仲裁裁决书、公证债权文书为合法有效凭证。如因丢失等原因无法提供取得不动产时的发票,以其他能证明契税计税金额的完税凭证等资料为合法有效凭证。\n\n4.适用第四条第九项规定,向其他单位或个人支付的货币形式拆迁补偿费用,以拆迁协议、拆迁双方支付和取得拆迁补偿费用凭证等能够证明拆迁补偿费用真实性的材料为合法有效凭证。\n\n5.除本项上述规定外,按以下规定执行。\n\n(1)支付给境内单位或者个人的款项,以发票或者省级以上(含省级)财政部门监(印)制的财政票据为合法有效凭证。\n\n(2)支付给境外单位或者个人的款项,以该单位或者个人的签收单据为合法有效凭证,税务机关对签收单据有疑义的,可以要求其提供境外公证机构的确认证明。\n\n(3)缴纳的税款,以完税凭证为合法有效凭证。\n\n纳税人取得的上述凭证属于增值税扣税凭证的,其进项税额不得从销项税额中抵扣。\n\n(十二)纳税人按照第四条第二项至第八项规定从含税销售额中扣除相关价款的,应按以下规定开具发票,否则,不得扣除。\n\n1.适用第四条第二、三、四、六项规定,从含税销售额中扣除的相关价款,不得开具增值税专用发票,可以开具普通发票。\n\n2.适用第四条第五、七、八项规定,全部含税销售额和扣除的价款应在同一张发票上分别列明,发票的税额按含税销售额扣除相关价款后计算。"},{"no":"五","title":"其他增值税优惠项目","text":"(一)自2026年1月1日至2027年12月31日,一般纳税人提供管道运输服务,对其增值税实际税负超过3%的部分实行增值税即征即退政策。\n\n增值税实际税负,是指纳税人当期提供管道运输服务实际缴纳的增值税额占纳税人当期提供管道运输服务取得的销售额的比例。\n\n(二)自2026年1月1日起,一般纳税人购进农产品,取得一般纳税人开具的增值税专用发票或海关进口增值税专用缴款书的,以增值税专用发票或海关进口增值税专用缴款书上注明的增值税额为进项税额;从按照简易计税方法依照3%征收率计算缴纳增值税的小规模纳税人取得增值税专用发票的,以增值税专用发票上注明的金额和9%的扣除率计算进项税额;取得(开具)农产品销售发票或收购发票的,以农产品销售发票或收购发票上注明的农产品买价和9%的扣除率计算进项税额。一般纳税人从农民专业合作社购进的免税农产品,可按9%的扣除率计算进项税额。\n\n(三)自2026年1月1日至2027年12月31日,药品生产企业销售自产创新药的销售额,为向购买方收取的全部价款,其提供给患者后续免费使用的相同创新药,不属于增值税视同应税交易范围。\n\n(四)自2026年1月1日起,下列文件中现行有效的增值税优惠政策继续实施。\n\n1.《财政部 国家税务总局关于软件产品增值税政策的通知》(财税〔2011〕100号)。\n\n2.《财政部 国家税务总局关于外国驻华使(领)馆及其馆员在华购买货物和服务增值税退税政策的通知》(财税〔2016〕51号)和《财政部 税务总局关于外国驻华使(领)馆及其馆员在华购买货物和服务增值税退税政策有关问题的补充通知》(财税〔2017〕74号)。\n\n3.《财政部 税务总局关于完善资源综合利用增值税政策的公告》(财政部 税务总局公告2021年第40号)。\n\n4.《财政部 海关总署 税务总局关于调整风力发电等增值税政策的公告》(财政部 海关总署 税务总局公告2025年第10号)第二条。\n\n(五)自2026年1月1日至2027年12月31日,下列文件中现行有效的增值税优惠政策继续实施。\n\n1.《财政部 国家税务总局关于粮食企业增值税征免问题的通知》(财税字〔1999〕198号)和《财政部 国家税务总局关于免征储备大豆增值税政策的通知》(财税〔2014〕38号)。\n\n2.《财政部 国家税务总局关于退还集成电路企业采购设备增值税期末留抵税额的通知》(财税〔2011〕107号)。\n\n3.《财政部 国家税务总局关于在部分行业试行农产品增值税进项税额核定扣除办法的通知》(财税〔2012〕38号)和《财政部 国家税务总局关于扩大农产品增值税进项税额核定扣除试点行业范围的通知》(财税〔2013〕57号)。\n\n4.《财政部 国家税务总局关于促进残疾人就业增值税优惠政策的通知》(财税〔2016〕52号)。\n\n5.《财政部 税务总局关于明确无偿转让股票等增值税政策的公告》(财政部 税务总局公告2020年第40号)。\n\n6.《财政部 税务总局关于集成电路企业增值税加计抵减政策的通知》(财税〔2023〕17号)。\n\n7.《财政部 税务总局关于工业母机企业增值税加计抵减政策的通知》(财税〔2023〕25号)。\n\n8.《财政部 税务总局 退役军人事务部关于进一步扶持自主就业退役士兵创业就业有关税收政策的公告》(财政部 税务总局 退役军人事务部公告2023年第14号)。\n\n9.《财政部 税务总局 人力资源社会保障部 农业农村部关于进一步支持重点群体创业就业有关税收政策的公告》(财政部 税务总局 人力资源社会保障部 农业农村部公告2023年第15号)。\n\n10.《财政部 税务总局关于民用航空发动机和民用飞机税收政策的公告》(财政部 税务总局公告2023年第27号)。\n\n11.《财政部 税务总局关于继续实施银行业金融机构、金融资产管理公司不良债权以物抵债有关税收政策的公告》(财政部 税务总局公告2023年第35号)。\n\n12.《财政部 商务部 税务总局关于研发机构采购设备增值税政策的公告》(财政部 税务总局公告2023年第41号)和《财政部 科技部 民政部 商务部 税务总局关于继续执行上海市浦东新区有关研发机构适用采购设备增值税政策资格认定事项的通知》(财税〔2023〕32号)。\n\n13.《财政部 税务总局关于先进制造业企业增值税加计抵减政策的公告》(财政部 税务总局公告2023年第43号)。\n\n14.《财政部 税务总局关于延续实施宣传文化增值税优惠政策的公告》(财政部 税务总局公告2023年第60号)和《财政部 税务总局关于更新宣传文化增值税优惠政策适用名单的公告》(财政部 税务总局公告2024年第11号)。\n\n15.《财政部 税务总局关于延续实施支持文化企业发展增值税政策的公告》(财政部 税务总局公告2023年第61号)。\n\n16.《财政部 海关总署 税务总局关于调整风力发电等增值税政策的公告》(财政部 海关总署 税务总局公告2025年第10号)第一条。\n\n17.《财政部 税务总局关于黄金有关税收政策的公告》(财政部 税务总局公告2025年第11号)。\n\n(六)《财政部 国家税务总局关于全面推开营业税改征增值税试点的通知》(财税〔2016〕36号)中附件2《营业税改征增值税试点有关事项的规定》“一般纳税人为甲供工程提供的建筑服务,可以选择适用简易计税方法计税”和《财政部 税务总局关于建筑服务等营改增试点政策的通知》(财税〔2017〕58号)“建筑工程总承包单位为房屋建筑的地基与基础、主体结构提供工程服务,建设单位自行采购全部或部分钢材、混凝土、砌体材料、预制构件的,适用简易计税方法计税”的规定自2026年1月1日起停止执行,纳税人在2026年1月1日前已适用简易计税方法的项目,继续按照原政策规定执行。"},{"no":"六","title":"施行日期","text":"本公告自2026年1月1日起实施。除本公告和增值税法、增值税法实施条例、《财政部 税务总局关于个人销售住房增值税政策的公告》(财政部 税务总局公告2025年第17号)外,在2025年12月31日前制发文件规定的国内环节增值税优惠政策同时停止执行。\n\n特此公告。"}],"interpretations":[{"sectionNo":"一","headline":"起征点：月销售额10万元、季30万元，按次1000元","who":"小规模纳税人发生应税交易。","materials":[],"window":"2026年1月1日至2027年12月31日。","where":"按增值税申报渠道适用，无需另行申请。","tip":"以扣除相关价款后的余额计算销售额的，要用扣除后的不含税余额来判断是否达到起征点；按次纳税的一日内多次交易按日合并计算。"},{"sectionNo":"二","headline":"自产农产品免征增值税，外购再卖的按规定缴税","who":"农业生产者销售的自产农产品；以及农业机耕、排灌、病虫害防治、植物保护、农牧保险和相关技术培训业务等。","materials":[],"window":"自2026年1月1日起。","where":"按增值税申报渠道适用。","tip":"销售外购的初级农产品，或用外购农产品生产、加工的初级农产品，不在免征范围内，要照章缴税。"},{"sectionNo":"三","headline":"一般纳税人多类应税交易可选3%或5%简易计税，至2027年底","who":"2026年1月1日至2027年12月31日发生列举交易的一般纳税人：销售自行采掘的砂、土、石料及自产砖、瓦、石灰（不含粘土实心砖、瓦）、装机容量5万千瓦以下小型水电销售自产电力、销售自来水、寄售商店代销寄售物品、典当业销售死当物品、公共交通运输服务、以清包工方式提供的建筑服务、为2016年4月30日前开工老项目提供的建筑服务、县及县以下农村金融机构金融服务、非企业单位研发和技术服务及信息技术、鉴证咨询服务、2016年4月30日前开工高速公路通行费、电影放映和仓储装卸搬运收派及文化体育服务、非学历教育和教育辅助服务、契约制资管产品运营；5%档为2016年4月30日前签订的不动产融资租赁合同或取得不动产的融资租赁、一级二级公路及桥闸通行费、出租或销售2016年4月30日前取得的不动产、转让2016年4月30日前取得的土地使用权、房地产老项目销售出租。","materials":[],"window":"2026年1月1日至2027年12月31日；选择简易计税当月起36个月内不得变更，期满改选一般计税后36个月内不得再选简易计税。","where":"办理增值税纳税申报时适用（原文未列具体部门或系统）","tip":"除房地产项目、建筑工程项目可按项目选择外，同一简易计税项目的全部应税交易须一并选择适用简易计税方法。"},{"sectionNo":"四","headline":"多类交易可差额扣除价款后计税，执行至2027年底","who":"2026年1月1日至2027年12月31日发生列举交易的纳税人：金融机构贴现、转贴现业务、中国证券登记结算有限责任公司相关收入、经批准从事融资租赁和融资性售后回租的纳税人（省级商务主管部门或国家经济技术开发区批准的，实收资本须达1.7亿元）、建筑服务简易计税项目、劳务派遣公司和取得《保安服务许可证》的保安服务公司、旅游服务、转让2016年4月30日前取得的土地使用权、销售2016年4月30日前取得的不动产、房地产开发企业销售房地产项目（含符合条件的项目公司扣除土地价款）、金银首饰以旧换新业务。","materials":["合法有效凭证留存备查（如财政票据、发票、法院判决书、裁定书、调解书、仲裁裁决书、公证债权文书）","拆迁协议及支付、取得拆迁补偿费用凭证","完税凭证"],"window":"2026年1月1日至2027年12月31日；扣除价款须取得合法有效凭证留存备查，否则不得扣除。","where":"办理增值税纳税申报时适用（原文未列具体部门或系统）","tip":"扣除的凭证属于增值税扣税凭证的，其进项税额不得从销项税额中抵扣；部分扣除项目不得开具增值税专用发票，可开普通发票。"},{"sectionNo":"五","headline":"管道运输税负超3%即征即退，农产品按9%扣除率抵进项","who":"一般纳税人：提供管道运输服务且增值税实际税负超过3%的；购进农产品并取得增值税专用发票、海关进口增值税专用缴款书、农产品销售发票或收购发票的；药品生产企业销售自产创新药并提供患者后续免费使用的。","materials":[],"window":"管道运输即征即退、创新药政策执行期为2026年1月1日至2027年12月31日；农产品进项扣除自2026年1月1日起执行。","where":"办理增值税纳税申报时适用（原文未列具体部门或系统）","tip":"创新药提供给患者后续免费使用不视同应税交易；从农民专业合作社购进免税农产品也可按9%的扣除率计算进项税额。"}],"sourceUrl":"https://www.hunan.gov.cn/zqt/zcsd/202602/t20260228_33923105.html","sourceNote":"2026-10-31 取自湖南省人民政府门户网站政策速递栏目转载页（信息来源：税务总局网站），原文落款2026年1月30日，本网发布2026-02-28；核心小规模纳税人优惠执行期2026-01-01至2027-12-31，故expiresAt记为2027-12-31。；2026-11-08 核对：页面发布日期 2026-02-28","verified":true,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":false},{"id":"xt-ai-action-2026","title":"湘潭市人民政府关于印发《湘潭市实施“人工智能+”行动方案》的通知","level":"city","region":"湘潭市","issuer":"湘潭市人民政府","documentNo":"潭政发〔2026〕5号","publishedAt":"2026-10-23","effectiveAt":"2026-10-23","expiresAt":"2031-10-23","status":"active","tags":["研发创新","专项资金"],"audience":["人工智能相关企业","制造业企业","专精特新中小企业","科研平台"],"summary":"到2027年底全市人工智能产业规模达100亿元、打造20个左右典型应用场景，到2030年底达150亿元；引导市级科技、科普专项资金向人工智能领域倾斜，支持重点企业、示范场景争资争项，有效期5年。","sections":[{"no":"一","title":"工作目标","text":"到2027年底，全市人工智能产业规模达到100亿元，推动人工智能与8条先进制造业产业链逐步融合，打造20个左右典型应用场景；到2030年底，全市人工智能产业规模达到150亿元，实现人工智能与8条先进制造业产业链深度融合，在智能制造等领域打造一批国省知名应用品牌。"},{"no":"二（二）2","title":"“人工智能+”先进制造","text":"大力推动中小企业数字化转型，依托龙头企业工业互联网、供应链、销售渠道等平台的开放接口与数据中台能力，带动产业链上下游协同转型。支持发展自主工业软件，推广应用韶峰天工CAX智能工作流协作平台等科研成果，促进人工智能与制造业研发设计等关键环节深度融合。"},{"no":"三","title":"保障措施","text":"积极争取国省政策支持，对标省级措施出台市级相应配套政策，重点支持人工智能领域重点企业、示范场景争资争项、试点创建，引导市级科技、科普专项资金向人工智能领域倾斜。依托市级人才工程，培育本土人工智能专业人才、引进域外高端人才。"},{"no":"三（续）","title":"算力与数据要素保障","text":"整合市域算力基础设施，推动互联互通并接入全省算力调度体系，优化升级城域网络，建设重点领域优质数据资源，推广钢铁行业“盘古大模型”应用，鼓励企业研发垂直行业大模型。"}],"interpretations":[{"sectionNo":"一","headline":"2027年人工智能产业规模达100亿元，建20个应用场景","who":"湘潭市人工智能企业及8条先进制造业产业链上的企业；这是全市产业规模目标口径，原文未设企业准入门槛。","materials":[],"window":"到2027年底为第一阶段目标，到2030年底为第二阶段目标。","where":"湘潭市人工智能产业推进（原文未点名具体部门）","tip":"100亿元、150亿元为全市产业规模目标，非企业可申领金额；20个左右场景和8条产业链融合是配套方向。"},{"sectionNo":"二（二）2","headline":"中小企业可借龙头企业平台接口与数据中台协同转型","who":"湘潭市中小企业，尤其是龙头企业产业链上下游企业；以及自主工业软件企业和应用韶峰天工CAX平台等科研成果的制造业企业。","materials":[],"window":"按行动方案持续推进；原文未设申报截止时间。","where":"龙头企业工业互联网、供应链、销售渠道等平台（原文未点名具体受理部门）","tip":"依托的是龙头企业平台开放接口与数据中台能力，原文未写补助金额；自主工业软件和CAX平台成果是重点推广方向。"}],"sourceUrl":"https://www.xiangtan.gov.cn/109/202/26291/26433/content_1460460.html","sourceNote":"2026-11-22 取自湘潭市人民政府门户「政务公开—法规文件—文件库—市政府规范性文件」原文页，版头载文号潭政发〔2026〕5号、统一登记号 XTCR-2026-00003，时效性栏载2031-10-23。 2026-11-22 收录：与官方页面逐句比对，命中 7/7 句（100%），关卡判定「verbatim」。 有效期依据：正文末条明示“有效期5年”；页面时效性栏载2031-10-23（自2026-10-23起算）","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"xt-business-28-2025","title":"湘潭市人民政府办公室关于印发《湘潭市推动营商环境优化提升28条措施》的通知","level":"city","region":"湘潭市","issuer":"湘潭市人民政府办公室","documentNo":"潭政办发〔2025〕12号","publishedAt":"2025-10-10","effectiveAt":"2025-11-01","expiresAt":"2030-11-01","status":"active","tags":["营商环境","融资支持","财政奖补"],"audience":["各类市场主体","大学生创业主体","科技型企业","中小微企业"],"summary":"从惠企政策免申即享、直达快享、申报流程优化、招投标监管、交通物流与用能降本、知识产权保护、大学生创业扶持等方面提出28条措施；对大学生创业孵化基地给予最高100万元创业服务补助，创业担保贷款最高30万元并贴息50%。","sections":[{"no":"二","title":"实行惠企政策“免申即享”评估机制","text":"制定惠企政策时，须进行“免申即享”可行性评估，并优先采用“免申即享”方式执行。梳理形成全市“免申即享”惠企政策清单，原则上当年政策当年兑现。建立“免申即享”政策落实效果评估机制，根据评估情况及时调整、新增“免申即享”惠企政策事项，并纳入“湘易办”“免申即享”专区模块。"},{"no":"三","title":"强化惠企政策“直达快享”和资金监管","text":"推进惠企政策申领审核系统与“湘易办”政策兑现系统、财政预算管理一体化系统深度对接，探索惠企项目申报在政策兑现系统统一取码、一码贯通。对涉企奖补资金进行实时跟踪，实现从预算下达、审核拨付到企业接收的全过程监管，确保资金流向清晰、可追溯。严肃查处财政留存、拖延、挪用应拨付企业资金等行为。"},{"no":"十二","title":"提升大学生创业服务质效","text":"支持在潭高校依托优势专业建设特色创业孵化基地，低成本开放高校和企业实验实训设备设施，给予每个孵化基地最高不超过100万元的创业服务补助。挂牌认定一批市级大学生创业实训基地，作为大学生创业实训重要载体，构建“企业主导、项目嵌入、双向赋能”的产教融合新模式。"},{"no":"十二（续）","title":"大学生创业金融支持","text":"设立支持大学生创业投资基金。毕业5年内的大学生个人在潭自主创业最高可申请30万元创业担保贷款，合伙创业最高可申请400万元创业担保贷款，并给予实际利率50%的贴息，其中县级财政承担22.5%。"}],"interpretations":[{"sectionNo":"二","headline":"惠企政策优先免申即享，原则上当年政策当年兑现","who":"湘潭市符合惠企政策条件的企业；纳入“免申即享”清单的事项由政策执行部门主动兑现，企业无需申报，清单外事项按原渠道办理。","materials":[],"window":"原则上当年政策当年兑现；“免申即享”政策清单根据落实效果评估动态调整、新增。","where":"“湘易办”“免申即享”专区模块。","tip":"制定惠企政策时须先做“免申即享”可行性评估；清单会随评估情况调整、新增，企业应关注专区是否新增本企业适用事项。"},{"sectionNo":"三","headline":"涉企奖补资金全程跟踪，截留拖延挪用将被查处","who":"湘潭市申报惠企奖补资金的企业；资金从预算下达、审核拨付到企业接收全过程纳入监管。","materials":[],"window":"申报在政策兑现系统统一取码、一码贯通；资金拨付全过程实时跟踪。","where":"“湘易办”政策兑现系统、财政预算管理一体化系统。","tip":"财政留存、拖延、挪用应拨付企业资金等行为将被严肃查处；资金流向清晰、可追溯。"},{"sectionNo":"十二","headline":"在潭高校建特色创业孵化基地，每个最高补100万元","who":"在潭高校依托优势专业建设的特色创业孵化基地；须低成本开放高校和企业实验实训设备设施；市级大学生创业实训基地另行挂牌认定。","materials":[],"window":"原文未明确申报期与执行期；市级大学生创业实训基地分批挂牌认定。","where":"原文未列明受理部门或申报系统。","tip":"补助按每个孵化基地最高100万元封顶；实训基地须经市级挂牌认定后才成为大学生创业实训载体。"},{"sectionNo":"十二（续）","headline":"毕业5年内大学生在潭创业，最高30万元担保贷款","who":"毕业5年内、在潭自主创业的大学生个人；合伙创业的按合伙主体申请，最高400万元。","materials":[],"window":"毕业5年内可申请；贴息按实际利率50%执行，其中县级财政承担22.5%。","where":"原文未列明经办银行或申报系统。","tip":"个人最高30万元、合伙最高400万元；贴息为实际利率的50%，其中县级财政承担22.5%。"}],"sourceUrl":"https://www.xiangtan.gov.cn/109/202/26291/26434/content_1397257.html","sourceNote":"2026-11-22 取自湘潭市人民政府门户「文件库—市政府办公室规范性文件」原文页，版头载文号潭政办发〔2025〕12号、统一登记号 XTCR-2025-01004，时效性栏载2030-11-01。publishedAt 取页面“发文日期”2025-10-10，effectiveAt 取末条“自2025年11月1日起施行”。 2026-11-22 收录：与官方页面逐句比对，命中 10/10 句（100%），关卡判定「verbatim」。 有效期依据：正文末条明示“自2025年11月1日起施行，有效期5年”；页面时效性栏载2030-11-01","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"xt-digital-pilot","title":"湘潭市支持中小企业数字化转型城市试点若干政策","level":"city","region":"湘潭市","issuer":"湘潭市人民政府","documentNo":"","publishedAt":"","effectiveAt":null,"expiresAt":null,"status":"active","tags":["数字化转型","财政奖补","贷款贴息"],"audience":["湘潭市试点行业中小企业（先进钢铁材料、新能源汽车及配套、智能制造装备、电机电控电传动）"],"summary":"首批试点企业按不高于改造投资总额35%补助、单家最高30万元；数字化贷款贴息2个百分点，单家贴息总额最高10万元。","sections":[{"no":"一","title":"支持中小企业数字化改造（普惠性）","text":"对试点企业采购用于与数字化改造相关的软件、云服务支出，网关、路由等必要的数据采集传输设备支出，以及咨询诊断等服务支出给予补助。首批试点企业按照不高于经审计核定后改造投资总额的35%给予补助，单家企业补助金额最高不超过30万元；第二批试点企业按照不高于经审计核定后改造投资总额的25%给予补助，单家企业补助金额最高不超过20万元；第三批试点企业按照不高于经审计核定后改造投资总额的10%给予补助，单家企业补助金额最高不超过2万元。"},{"no":"一续","title":"标杆性政策","text":"对于获评市级中小企业数字化转型“标杆企业”的试点企业，在基本奖补政策基础上按照不高于经审计核定后改造投资总额的30%增加补助，单家企业补助金额最高不超过30万元；对于获评市级“标杆车间”的，按20%增加补助，最高20万元；对于获评市级“典型场景”的，按10%增加补助，最高10万元。"},{"no":"二","title":"数字化转型金融政策","text":"市财政对试点企业金额50万元及以上用于数字化软硬件投资，且年化利率不超过3.5%的银行贷款本金贴息2个百分点，按照相关贷款资金划付试点企业账户之日起予以贴息，贴息期限不超过2年，单家企业贴息总额最高不超过10万元。"},{"no":"三","title":"优秀“小快轻准”解决方案","text":"对遴选的优秀“小快轻准”解决方案及产品，给予每个不超过2万元奖励。"},{"no":"四","title":"“链式”转型典型案例","text":"对“链式”数字化转型典型案例的牵头企业给予每家不超过20万元奖励；该产业链的牵头服务商给予每家不超过10万元奖励。"}],"interpretations":[{"sectionNo":"一","headline":"首批试点企业数字化改造补35%，单家最高30万元","who":"湘潭市中小企业数字化转型城市试点企业；首批按改造投资总额不高于35%补助（最高30万元），第二批25%（最高20万元），第三批10%（最高2万元）；补助范围含数字化改造相关软件、云服务、数据采集传输设备及咨询诊断服务支出。","materials":[],"window":"按试点批次分批执行（首批、第二批、第三批标准递减），原文未设具体申报日期。","where":"按试点批次由市级部门组织申报，补助以经审计核定后的改造投资总额为基数。","tip":"补助基数是经审计核定的投资额，不是合同金额；三批标准依次递减，越晚申报补得越少。"},{"sectionNo":"一续","headline":"评上标杆企业加补30%、最高30万元，标杆车间加20%","who":"获评市级中小企业数字化转型“标杆企业”的试点企业（加补30%，最高30万元）；获评“标杆车间”（加补20%，最高20万元）；获评“典型场景”（加补10%，最高10万元）。","materials":[],"window":"在基本奖补政策基础上叠加，按市级评定结果执行，原文未设单独申报期。","where":"由市级部门组织“标杆企业”“标杆车间”“典型场景”评定，按评定结果增加补助。","tip":"属“增加补助”，可与普惠性改造补助叠加；加补以获评为前提，三类荣誉分别对应30%、20%、10%三档。"},{"sectionNo":"二","headline":"数字化贷款50万元以上，贴息2个百分点，单家最高10万元","who":"试点企业用于数字化软硬件投资、金额50万元及以上、年化利率不超过3.5%的银行贷款；单家贴息总额最高不超过10万元。","materials":[],"window":"自贷款资金划付试点企业账户之日起贴息，贴息期限不超过2年。","where":"由市财政按贷款划付账户贴息，经主管部门审核，原文未列具体申报系统。","tip":"三个门槛同时满足才贴息：50万元及以上、年化利率不超过3.5%、用于数字化软硬件投资；贴息2个百分点而非全额贴息。"},{"sectionNo":"三","headline":"优秀“小快轻准”解决方案每个奖励不超过2万元","who":"入选优秀“小快轻准”解决方案及产品的开发或服务提供单位（经遴选）。","materials":[],"window":"按遴选批次执行，原文未设申报时间。","where":"由市级部门组织遴选，按遴选结果给予奖励。","tip":"奖励对象是“遴选的”优秀方案及产品，每个不超过2万元，未入选不补。"},{"sectionNo":"四","headline":"链式转型典型案例牵头企业奖20万元，牵头服务商奖10万元","who":"“链式”数字化转型典型案例的牵头企业（每家不超过20万元）；该产业链的牵头服务商（每家不超过10万元）。","materials":[],"window":"按案例评选批次执行，原文未设申报时间。","where":"由市级部门组织案例评选，按评选结果奖励。","tip":"牵头企业与牵头服务商分别计奖，同一案例两类主体各按对应标准奖励。"}],"sourceUrl":"https://www.xiangtan.gov.cn/427/435/28961/29190/content_1405439.html","sourceNote":"2026-11-21 取自湘潭市政府门户原文页；页面未标注文号。金额、比例与批次分档已逐字核对，与市工信局推进会通稿口径一致。 2026-11-21 收录：与官方页面逐句比对，命中 9/11 句（82%），关卡判定「partial」。 有效期依据：原文未设期限；以试点期为执行边界，需以市工信局年度通知复核","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"partial","hunan":true},{"id":"xt-transport-green-2024","title":"湘潭市人民政府办公室关于印发《湘潭市促进交通运输绿色低碳发展的若干措施》的通知","level":"city","region":"湘潭市","issuer":"湘潭市人民政府办公室","documentNo":"潭政办发〔2024〕6号","publishedAt":"2024-04-26","effectiveAt":"2024-05-01","expiresAt":"2029-05-01","status":"active","tags":["财政奖补","专项资金"],"audience":["道路货运企业","水路运输企业","物流园区","新能源货车购置企业"],"summary":"对“公转铁”铁路运单托运人按发运量与增量分档奖励2万至12万元，财政每年安排100万元专项奖励资金；对新购新能源货车的规上企业给予奖励；对新能源客货船舶、老旧货船拆解、水路集装箱运输按规定给予奖补，有效期至2029年5月1日。","sections":[{"no":"13","title":"促进水路运力结构优化调整","text":"鼓励船舶应用新能源，对新建或改建液化天然气、液化天然气柴油双动力、电动、氢能等新能源客货船舶给予奖补。鼓励老旧货船、现有客船（含非标准渡船）提前拆解退出市场，对按规定持有效的船舶检验证书、所有权登记证书、船舶营业运输证等证书的现有客船（含非标准渡船）和船龄在15年以上30年（含）以下的老旧货船提前拆解给予奖补。"},{"no":"15","title":"推广使用新能源车辆","text":"强化部门协同配合，建立“交通运输部门负责运力调控，商贸流通部门负责配送需求引导，公安机关交通管理部门负责通行管理”的城市配送车辆协同管控机制，出台新能源城市货运配送车辆运营补贴方案（责任单位：市交通运输局、市商务局、市财政局、市公安局交警支队、市邮政管理局）。新增或更新公交、出租车、轻型环卫车原则上使用新能源车（责任单位：市交通运输局、市城管执法局）。制定出台鼓励物流园区和建筑、建材、矿山、火电、钢铁、焦化等重点用车企业与运输企业使用新能源货车相关政策，推进重点用车单位加快智能门禁系统建设，严格管控国Ⅲ及以下排放标准柴油货车进出（责任单位：市生态环境局）。合理设定燃油货车禁限行范围，采取分时段禁限行措施，同时扩大新能源货车城区通行权限，限行区域和时长明显优于燃油货车（责任单位：市公安局交警支队）。对新购新能源货车（不含挂车、天燃气车）的规上企业按吨位及类型分别给予一定的奖励，具体奖励办法另行出台（责任单位：市交通运输局、市财政局）。"},{"no":"22","title":"积极推动“公转铁”","text":"鼓励全市大宗货物和中长距离货物运输（不含军事运输）托运人采用铁路运输方式出市，推动交通运输绿色低碳发展。自2024年起，对铁路运单托运人按以下标准给予奖励：对首次（自2022年以来湘潭市内无铁路发运量）通过湘潭市内铁路发送货物且年度累计发运量达1.2万吨（含）以上的，奖励2万元；对上年铁路发运量超1.2万吨（含），且本年度增量达20%（含）以上、40%（含）以上、60%（含）以上的，分别奖励4万元、8万元和12万元。"},{"no":"22（续）","title":"专项奖励资金规模","text":"本项奖励按自然年度结算，财政每年安排100万元专项奖励资金，如测算年度奖励资金总额小于或等于100万元，则按以上补助标准进行补助；如测算额度超过100万元，则各项补助标准同比例压减至年度奖励总额100万元后，计算实际补助额度。"}],"interpretations":[{"sectionNo":"13","headline":"新能源客货船新建改建、老旧船提前拆解均可获奖补","who":"船舶所有人或经营人：新建或改建液化天然气、液化天然气柴油双动力、电动、氢能等新能源客货船舶；或提前拆解现有客船（含非标准渡船）、船龄在15年以上30年（含）以下的老旧货船，并按规定持有效的船舶检验证书、所有权登记证书、船舶营业运输证等证书。","materials":["船舶检验证书","所有权登记证书","船舶营业运输证"],"window":"原文未设申报截止时间；老旧货船须船龄在15年以上30年（含）以下，证书须在有效期内。","where":"原文未列明具体受理部门或申报系统","tip":"证书须有效，缺船舶检验证书、所有权登记证书、船舶营业运输证之一即不符合；现有客船含非标准渡船，老旧货船船龄超过30年不在本条范围。"},{"sectionNo":"15","headline":"规上企业新购新能源货车可获奖，具体标准另行出台","who":"在湘潭市新购新能源货车（不含挂车、天燃气车）的规上企业，按吨位及类型给予奖励；新能源城市货运配送车辆运营主体适用另行出台的运营补贴方案。","materials":[],"window":"原文未设申报期；新购新能源货车奖励办法另行出台，新增或更新公交、出租车、轻型环卫车原则上使用新能源车。","where":"市交通运输局、市财政局（新购新能源货车奖励责任单位）","tip":"奖励不含挂车、天燃气车；新能源货车城区限行区域和时长明显优于燃油货车，国Ⅲ及以下排放标准柴油货车进出受严格管控。"},{"sectionNo":"22","headline":"铁路发货首达1.2万吨奖2万，增量最高奖12万","who":"通过湘潭市内铁路发送货物、且为铁路运单托运人的企业：首次（2022年以来湘潭市内无铁路发运量）发运且年度累计发运量达1.2万吨（含）以上；或上年铁路发运量超1.2万吨（含）、本年度增量达20%（含）以上、40%（含）以上、60%（含）以上。","materials":[],"window":"自2024年起，按自然年度结算；首次档要求2022年以来湘潭市内无铁路发运量。","where":"湘潭市内铁路发运，原文未列明受理部门","tip":"增量档按20%、40%、60%三档分别奖励4万元、8万元、12万元，不叠加；首次档要求2022年以来湘潭市内无铁路发运量。"},{"sectionNo":"22（续）","headline":"奖励每年100万元封顶，超额按比例压减","who":"通过湘潭市内铁路发运货物、符合前述奖励条件的铁路运单托运人；年度测算奖励总额超过100万元时，各档补助标准同比例压减。","materials":[],"window":"按自然年度结算，财政每年安排100万元专项奖励资金。","where":"原文未列明受理部门（奖励资金由财政按年度安排）","tip":"年度奖励总额小于或等于100万元时按标准足额补助；超过100万元则各档标准同比例压减至100万元，实际到手低于公布标准。"}],"sourceUrl":"https://www.xiangtan.gov.cn/109/202/26291/26434/content_1297961.html","sourceNote":"2026-11-22 取自湘潭市人民政府门户「文件库—市政府办公室规范性文件」原文页，版头载文号潭政办发〔2024〕6号、统一登记号 XTCR-2024-01001，时效性栏载2029-05-01。注意：末条另有一句“其中涉及财政补贴政策的，有效期至2025年12月31日”，即奖补类条款的兑付期限早于整件有效期。publishedAt 取页面“发文日期”2024-04-26，effectiveAt 取末条“自2024年5月1日起施行”。 2026-11-22 收录：与官方页面逐句比对，命中 12/12 句（100%），关卡判定「verbatim」。 有效期依据：正文末条明示“自2024年5月1日起施行，有效期5年”，并单列“涉及财政补贴政策的，有效期至2025年12月31日”；页面时效性栏载2029-05-01","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"xt-zfqq-2023","title":"湘潭市人民政府办公室关于印发《湘潭市“智赋千企”行动方案（2023—2025年）》的通知","level":"city","region":"湘潭市","issuer":"湘潭市人民政府办公室","documentNo":"","publishedAt":"2023-08-02","effectiveAt":null,"expiresAt":"2025-12-31","status":"expired","tags":["数字化转型","财政奖补","融资支持"],"audience":["湘潭市工业企业","数字化转型意向企业","两化融合贯标企业"],"summary":"对省智能制造标杆企业、标杆车间、国省优秀应用场景按5万—50万元/家给予一次性奖励；智改数转项目按地区经济贡献增量20%奖励，最高100万元。","sections":[{"no":"(九)","title":"智改数转奖励","text":"对项目实施完成后每年地区经济贡献增长15%以上且年实缴税额100万元以上的企业，连续三年按照当年所形成的地区经济贡献增量部分20%的标准给予奖励，每年奖励金额不超过投资总额的50%，且最高不超过100万元。"},{"no":"(十)","title":"两化融合贯标奖励","text":"对新获批省“两化”融合贯标管理体系试点并获得“两化”融合贯标认证证书的企业，按照5万元/家的标准给予一次性奖励；并在省级专项奖补资金基础上，按照5万元/家的标准给予一次性配套奖励；对新认定为省级工业互联网平台建设的项目，在省级专项奖补资金基础上，按照10万元/家的标准给予企业一次性配套奖励。"},{"no":"(十一)","title":"降低担保费率","text":"对进入市级入库数字化转型意向企业，单户担保金额500万元及以下的担保费率原则上不超过1%，单户担保金额500万元以上的担保费率原则上不超过1.5%。"},{"no":"(十二)","title":"智慧园区与资金安排","text":"市工信局、市财政局每年在“千百十”工程中安排资金，并根据省真抓实干督查激励奖励资金使用方向，经市人民政府同意后统筹安排支持“智赋千企”专项行动项目和企业，鼓励有条件的县市区、园区给予财政配套支持。"},{"no":"附则","title":"适用与叠加规则","text":"本方案所涉及的政策适用于注册地、纳税地和统计地均在湘潭的企业和机构；所涉及的奖补资金，与湘潭市其他奖补政策重复的（包含“一事一议”“一企一策”等奖励），按照就高不就低的原则执行，不重复享受。"}],"interpretations":[{"sectionNo":"(九)","headline":"年实缴税100万且贡献增长15%，连续三年奖增量20%","who":"项目实施完成后每年地区经济贡献增长15%以上、且年实缴税额100万元以上的企业。","materials":[],"window":"连续三年奖励，按当年形成的地区经济贡献增量计算。","where":"原文未写明受理部门。","tip":"每年奖励金额不超过投资总额的50%，且最高不超过100万元。"},{"sectionNo":"(十)","headline":"两化融合贯标认证奖5万，工业互联网平台配套10万","who":"新获批省“两化”融合贯标管理体系试点并获得“两化”融合贯标认证证书的企业；新认定为省级工业互联网平台建设的项目企业。","materials":[],"window":"一次性奖励、一次性配套奖励。","where":"原文未写明受理部门，配套奖励在省级专项奖补资金基础上安排。","tip":"贯标认证5万元/家，另有省级资金基础上的5万元/家配套；省级工业互联网平台配套10万元/家。"},{"sectionNo":"(十一)","headline":"入库数字化转型企业担保费率最高1%，500万以上1.5%","who":"进入市级入库的数字化转型意向企业；按单户担保金额500万元及以下、500万元以上分档。","materials":[],"window":"原文未写明执行期。","where":"原文未写明受理部门。","tip":"单户担保金额500万元及以下费率原则上不超过1%，500万元以上原则上不超过1.5%。"},{"sectionNo":"附则","headline":"注册纳税统计均在湘潭才适用，奖补就高不就低不重复","who":"注册地、纳税地和统计地均在湘潭的企业和机构。","materials":[],"window":"本方案执行期内适用。","where":"原文未写明受理部门。","tip":"与湘潭市其他奖补政策重复的（包含“一事一议”“一企一策”等奖励），按照就高不就低的原则执行，不重复享受。"}],"sourceUrl":"https://www.xiangtan.gov.cn/uploadfiles/202308/2023080217105654675.doc","sourceNote":"2026-11-21 取自湘潭市政府门户原文（.doc 直链）；标题、行动期与奖励标准已核对。行动期止于2025年，判失效。 2026-11-21 收录：与官方页面逐句比对，命中 8/8 句（100%），关卡判定「verbatim」。 有效期依据：文件名载明实施期限止于2025年；基准日已过，判失效","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"xtx-rice-purchase-award-2026","title":"湘潭县2026年食品安全指标符合标准但质量指标不符合国家标准稻谷市场化收购奖补方案","level":"district","region":"湘潭市·湘潭县","issuer":"湘潭县发展和改革局","documentNo":"","publishedAt":"2026-10-15","effectiveAt":null,"expiresAt":"2027-03-28","status":"active","tags":["财政奖补"],"audience":["湘潭县内粮食经营主体","稻谷收购与转化企业"],"summary":"对2026年产食品安全指标合格但质量指标不达标的稻谷，销售出市最高奖50元/吨、本地转化成产品最高奖100元/吨、销售出省最高奖200元/吨；粮食经营主体须收购前向县发改局报备，外销或转化完成后提交凭证申报，申报截止2027年3月28日；有违法违纪、失信行为或项目未验收的企业不得申报。","sections":[{"no":"2","title":"","text":"2.奖补范围：在政策性粮食收购中，发现的2026年产食品安全指标符合标准但质量指标不符合国家标准的稻谷，销售出市、出省和在本地转化成产品的均给予奖补。"},{"no":"3","title":"","text":"3.奖补标准：销售出市最高奖50元/吨，本地转化成产品最高奖100元/吨，销售出省最高奖200元/吨。"},{"no":"4","title":"","text":"4.申报时间：奖补项目申报截止时间为2027年3月28日，逾期不予受理。"},{"no":"5","title":"","text":"5.申报程序：粮食经营主体应当在收购此类稻谷前，先向湘潭县发展和改革局（以下简称县发改局）报备，然后收购经县发改局认可的稻谷，再在外销或转化完成后，向县发改局提交相关佐证资料。申请奖补的粮食经营主体对其佐证资料的真实性、合法性、完整性负责。县发改局对提交的材料进行汇总、审核后拨付奖补资金。"},{"no":"7","title":"","text":"7.申报说明：前期违反国家粮油购销政策，发生违法违纪、失信行为、严重质量及安全事故的企业和前期项目应验收而未及时完成验收的不得申报；申报材料弄虚作假的，取消奖补资格。"}],"interpretations":[{"sectionNo":"2","headline":"2026年产食安达标质量不达标的稻谷，外销或本地转化均奖补","who":"在政策性粮食收购中收购此类稻谷的粮食经营主体；稻谷须为2026年产、食品安全指标符合标准但质量指标不符合国家标准；销售出市、出省和在本地转化成产品的，均给予奖补。","materials":[],"window":"销售出市、出省或本地转化成产品后申报奖补，无固定批次。","where":"湘潭县政策性粮食收购环节（销售出市、出省或本地转化成产品）。","tip":"奖补只针对2026年产、食品安全指标符合标准但质量指标不符合国家标准的稻谷；出市、出省、本地转化三类去向都算。"},{"sectionNo":"3","headline":"出省200元/吨、本地转化100元/吨、出市50元/吨","who":"销售2026年产此类稻谷的粮食经营主体，按稻谷最终销售去向对应不同奖补档次。","materials":[],"window":"销售出市、出省或本地转化完成后按对应档次计发。","where":"按稻谷销售去向区分：销售出市、销售出省或本地转化成产品。","tip":"三个档次均为最高奖补额；出省最高、出市最低，同一批稻谷按实际去向取一档。"},{"sectionNo":"4","headline":"奖补申报截止2027年3月28日，逾期不予受理","who":"拟申请稻谷市场化收购奖补的粮食经营主体，须已收购2026年产此类稻谷并完成外销或转化。","materials":[],"window":"申报截止时间为2027年3月28日，逾期不予受理。","where":"湘潭县发展和改革局（县发改局）。","tip":"截止日之后提交的一律不予受理，须在外销或转化完成后、截止日前报送佐证资料。"},{"sectionNo":"5","headline":"先报备再收购，外销或转化后向县发改局交材料领奖补","who":"收购此类稻谷的粮食经营主体；须在收购前向县发改局报备，只收购经县发改局认可的稻谷；对佐证资料的真实性、合法性、完整性负责。","materials":["相关佐证资料"],"window":"收购前先报备，再收购经认可的稻谷，外销或转化完成后提交佐证资料。","where":"湘潭县发展和改革局（县发改局）。","tip":"未先报备或收购未经县发改局认可的稻谷不能申报；材料真实性、合法性、完整性由申报主体自行负责。"},{"sectionNo":"7","headline":"有违法违纪、失信、质量安全事故或项目未验收的不得申报","who":"申报奖补的粮食经营主体；前期违反国家粮油购销政策、发生违法违纪或失信行为、发生严重质量及安全事故的，以及前期项目应验收而未及时完成验收的，均不得申报。","materials":[],"window":"在申报期内（截止2027年3月28日）按前期违规情况和项目验收情况审查资格。","where":"湘潭县发展和改革局（县发改局）。","tip":"申报材料弄虚作假一经查实即取消奖补资格；前期项目应验收未验收的同样不得申报。"}],"sourceUrl":"http://www.xtx.gov.cn/9532/9540/content_1458261.html","sourceNote":"2026-11-22 取自湘潭县政府门户县发展和改革局「财政信息」原文页，页面标注来源、责任编辑均为湘潭县发展和改革局；该件为奖补方案，未标注发文字号。 2026-11-22 收录：与官方页面逐句比对，命中 8/8 句（100%），关卡判定「verbatim」。 有效期依据：第4项“申报时间”","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"xx-bizenv-2026-4","title":"湘西自治州人民政府办公室关于印发《湘西自治州贯彻落实〈湖南省以问题为靶心优化营商环境若干举措〉任务清单》的通知","level":"city","region":"湘西土家族苗族自治州","issuer":"湘西自治州人民政府办公室","documentNo":"州政办发〔2026〕4号","publishedAt":"","effectiveAt":null,"expiresAt":null,"status":"active","tags":["营商环境","就业补贴","场地支持"],"audience":["湘西州民营企业","中小微企业","个体工商户"],"summary":"围绕惠企政策获得感、拖欠民企账款、资源要素成本、中介服务规范、涉企执法检查等八个方面建立台账、限时办结、销号管理。","sections":[{"no":"一","title":"提高政治站位","text":"《湘西自治州贯彻落实〈湖南省以问题为靶心优化营商环境若干举措〉任务清单》是我州靶向破解营商环境突出堵点、激发民营经济发展活力的重要工作抓手。全州各级各部门要深入贯彻落实党中央、国务院决策部署和省委、省政府工作要求，把《任务清单》落地落实作为“一把手工程”来抓，与“企业服务年”行动一体推进。"},{"no":"二","title":"压实工作责任","text":"按照常务副州长统筹抓总、分管州领导分工负责、牵头单位统筹推进、责任单位协同配合的工作体系抓好任务落实。各牵头单位要切实履行主体责任，主动靠前服务，深入研判本领域核心问题，在清单举措基础上再推出一批突破性实招。"},{"no":"三","title":"加强工作调度","text":"企业服务年州级推进机制办公室实行“月调度、季分析、年评估”的常态化闭环管理，对《任务清单》实行“建立台账、限时办结、销号管理”全过程跟踪督办。各牵头单位要聚焦惠企政策获得感、拖欠民企账款、资源要素成本、中介服务规范、涉企执法检查、公平竞争、诉求办理、政商关系等八个方面靶向问题，定期会商研判。"},{"no":"四","title":"注重宣传引导","text":"各县市、各有关单位要及时总结推广工作中的好经验、好做法，广泛宣传优化营商环境政策措施和改革成效。要畅通企业诉求反映渠道，主动接受社会监督，不断提升企业获得感和满意度。"}],"interpretations":[],"sourceUrl":"https://xxz.gov.cn/zzf/xxzzfgb/zfgb2026/202608/zwbzzfbwj/202609/t20260914_2375006.html","sourceNote":"2026-11-21 取自《湘西政报》2026年第8期「州政府办文件」栏目；文号、登记号 XXCR—2026—01001 与条款逐字核对。 2026-11-21 收录：官方页面未能打开或不是正文（fetch/html），条文未与原文比对。 有效期依据：原文未设期限；规范性文件登记号 XXCR—2026—01001，按一般不超5年推算至2031","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"unverifiable","hunan":true},{"id":"xxz-award-fund-2025","title":"湘西自治州人民政府关于印发《湘西州本级财政支持高质量发展综合奖补政策管理办法》的通知","level":"city","region":"湘西土家族苗族自治州","issuer":"湘西自治州人民政府","documentNo":"州政发〔2025〕6号","publishedAt":"2025-10-13","effectiveAt":"2025-10-13","expiresAt":"2030-10-13","status":"active","tags":["财政奖补","专项资金","认定资质"],"audience":["市场主体","民营中小微企业","个体工商户","奖补项目申报单位"],"summary":"州本级财政奖补政策管理制度，实行清单管理，设贡献兑补、资格定补、择优奖补三类，通过以奖代补、贷款贴息、风险补偿等方式兑现，以“后补助”和间接支持为主；办法只定规则不定标准，未列具体奖补金额或比例（单项政策标准由主管部门另行制定并公开）；政策执行期限原则上不超过3年，申报公告每年第一季度发布、申报期为公告后20个工作日、公示5个工作日；自2025年10月13日起施行，有效期5年。","sections":[{"no":"一","title":"第一章 总则","text":"为加快推动我州经济社会高质量发展，建立健全州本级支持高质量发展综合奖补政策管理制度，树立鲜明奖补导向，提高财政奖补资金使用绩效，根据《中华人民共和国预算法》及其实施条例、《公平竞争审查条例》及其实施办法、《湖南省人民政府关于进一步深化预算管理制度改革的实施意见》（湘政发〔2021〕14号）等法律法规和上级政策要求，结合我州实际，制定本办法。"},{"no":"二","title":"","text":"本办法所称州本级财政支持高质量发展综合奖补政策（以下简称“奖补政策”），是指由州委或州人民政府设立，州本级财政统筹有关资金安排用于支持我州经济社会高质量发展的各类奖励或补助政策。"},{"no":"三","title":"","text":"奖补政策实行清单管理，应当遵循“依法设立、公平公开、财力协调、注重绩效、动态调整、无效退出”的原则。"},{"no":"四","title":"","text":"建立由州财政局牵头，有关职能部门为成员单位的州本级财政支持高质量发展综合奖补政策管理部门联审工作机制（以下简称“工作机制”），负责研究制定奖补政策管理制度，审核奖补政策设立、动态调整和实施兑现等工作，协调解决工作中存在的困难问题。"},{"no":"五","title":"第二章 政策设立","text":"奖补政策的设立应当符合国家法律法规和上级政策规定；符合国家、省、州国民经济和社会发展中长期规划以及产业政策要求；符合州委、州人民政府工作要求；符合州人大决定或决议要求；符合我州当前经济社会发展水平，对经济社会高质量发展有明显促进作用。"},{"no":"六","title":"","text":"设立的奖补政策应当遵守以下规定：（一）不得与上级政策法规规定相冲突；（二）不得超出州本级财政可承受能力；（三）不得以设立奖补政策为名变相安排工作经费和发放津补贴；（四）不得新增一个行业领域的奖补政策就申请新设一项专项资金，现已设立用于奖补政策的专项资金，应当根据绩效评价结果进行有序调整；（五）不得设立干预市场和与税费收入相挂钩的补贴或返还政策；（六）不得以外地经营者将注册地迁移至本地、在本地纳税、纳入本地统计等为条件，实施财政奖励或者补贴；（七）不得在没有法律、行政法规或者国务院规定的情况下，给予特定经营者财政奖励、补贴；（八）不得擅自设立评比达标表彰、创建示范活动的奖补政策；（九）不得设立前置条件无下限和奖补标准无上限的奖补政策；（十）不得增加县级支出责任或向县级转嫁支出责任，中央、省、州已明确的共同事权除外；（十一）原则上不得在国省奖补政策上设立相同的州本级奖补政策，确需重复设立的，不能在国省基础上提标扩面，上级另有规定或对湘西州经济社会高质量发展有突出贡献的除外；（十二）原则上不得设立与现行奖补政策奖补方向或用途交叉、重复、雷同的奖补政策，确需设立的，应当废止原奖补政策。"},{"no":"七","title":"","text":"奖补政策必须坚持维护市场统一和公平竞争，通过以奖代补、贷款贴息、风险补偿等方式进行奖补，以“后补助”和间接支持为主，主要奖补类别如下：（一）贡献兑补类。是指对投资额、营业额、吸纳就业人数、贷款等指标有突出贡献的市场主体进行奖补。此类政策重点考虑增量指标和“1+5+X”现代化产业体系建设。（二）资格定补类。是指对首次获得省（高）级及以上资格（职称）认定、获奖、荣誉的对象进行一次性奖补。此类政策主要考虑对我州经济社会高质量发展具有明显的品牌效应和技术支撑的资格荣誉。（三）择优奖补类。是指根据奖补项目遴选办法，由主管部门牵头组织专家进行现场评审或集中评审，对相对优秀的对象进行奖补。此类政策应事先公布评审条件，规范评审程序，进行集体决策，公开评审过程和结果。"},{"no":"八","title":"","text":"奖补政策由主管部门提出，先征求有关部门意见，再提交工作机制审核，严格落实公平竞争审查后，报请州人民政府或州委审定。奖补政策执行期限原则上不超过3年，期满需要延长执行期限的，应当按照新设立程序重新报批。"},{"no":"九","title":"","text":"主管部门提出设立奖补政策时，应当充分说明奖补政策出台的必要性、可行性，提供政策依据、绩效目标、可行性研究报告或事前绩效评估报告、执行期间的资金需求测算情况等。"},{"no":"十","title":"第三章 调整和退出","text":"奖补政策实行动态管理，根据实际执行情况和绩效评价结果，适时进行调整或决定退出。"},{"no":"十一","title":"","text":"奖补政策在执行期内有下列情形之一的，由业务主管部门商工作机制，或者由工作机制直接报请州委或州人民政府按政策设立程序予以调整。（一）上级政策调整，需按上级规定重新修订；（二）州委、州人民政府重要（大）工作调整，需按州委、州人民政府工作要求重新修订；（三）奖补事项和奖补对象相同或相近，需要归并整合、统筹安排；（四）根据政策实施绩效评价结果，需要调整修订；（五）其他需要调整的情形。"},{"no":"十二","title":"","text":"奖补政策执行期满自行失效。在执行期内有下列情形之一的，由工作机制商业务主管部门，或者由工作机制直接报请州委或州人民政府按程序退出或废止。（一）与上级新的政策相违背或上级新的政策要求废止；（二）州委、州人民政府决策不再执行；（三）政策效能差，长期未进行兑现；（四）绩效达不到主要预期目标，绩效评价结果无效；（五）其他需要退出或废止的情形。"},{"no":"十三","title":"第四章 政策实施","text":"州财政局根据年度奖补政策兑现需求，统筹安排奖补政策兑现资金。"},{"no":"十四","title":"","text":"奖补对象为个人的，必须无违法违纪行为、征信良好。奖补对象为市场主体或单位的，必须在湘西州内开展业务或开展与湘西州相关的业务，并满足以下条件：依法经营、信用良好、履行统计义务，且未发生较大以上安全生产责任事故，未对生态环境造成不良影响。"},{"no":"十五","title":"","text":"奖补政策办理原则上按照以下流程：（一）发布申报公告。各主管部门原则上应当在每年第一季度发布上一年度奖补政策的申报公告，明确申报程序。（二）申报。贡献兑补类政策和资格定补类政策对民营中小微企业和个体工商户实行“免申即享”机制；其他奖补类政策则遵循自愿原则，申报主体需在公告发布后20个工作日内向主管部门提交材料。（三）部门初审。主管部门负责汇总申报对象的申报材料，并对申报材料的真实性、合规性、完整性进行初审，提出初审意见，加盖主管部门公章，形成奖补政策兑现资金方案。（四）工作机制联审。主管部门将奖补政策资金兑现方案报工作机制联审。工作机制重点审查奖补对象条件资质、相关数据核校、奖补标准执行、是否重复奖励、奖补程序落实情况等，提出联审意见，反馈给主管部门。（五）集体研究。主管部门根据工作机制联审意见，将奖补政策兑现资金方案按州本级重大专项资金审批程序报批，涉及大额资金安排的应当报州政府常务会议研究，必要时再报州委常委会会议研究。（六）公示。除涉密项目外，由主管部门根据集体研究结果，对拟奖补对象、项目及金额等有关信息进行公示5个工作日，公示期间无异议的，由主管部门向州财政局申请兑现。公示期间如有异议的，由主管部门负责处理，并将处理结果报州委、州人民政府。（七）兑现。州财政局根据申请兑现方案，将兑现资金拨付至主管部门或县市、湘西高新区，再由主管部门或县市、湘西高新区支付至奖补对象。"},{"no":"十六","title":"第五章 绩效管理","text":"实行奖补政策事前绩效评估，对新增设立的奖补政策，应当对政策设立的必要性、合法性、合理性、财政可承受能力以及政策效益等方面进行事前绩效评估，评估结果不理想的，不予设立。"},{"no":"十七","title":"","text":"奖补政策每自然年度执行完毕后，应当通过部门绩效自评、财会审计监督、财政绩效评价等方式，对奖补政策执行情况开展综合绩效评价。评价结果应当与政策延期、调整、预算资金安排挂钩。"},{"no":"十八","title":"","text":"对奖补政策绩效运行实行动态监控。当政策执行与绩效目标出现严重偏差时，应当暂缓或停止奖补政策执行，并督促及时整改存在问题；对于整改不到位的奖补政策，应当进行调整或退出。"},{"no":"十九","title":"第六章 信息公开和监督管理","text":"主管部门应当加强政策宣传解读，提高政策知晓度和利用率，建立健全奖补政策的信息公开制度，除涉密事项不予公开外，奖补政策的文件依据、申报指南、审核流程、分配结果、绩效评价等信息，以及政策的调整变更、废止退出，都应当通过州人民政府门户网站及主管部门官网向社会公开，主动接受社会监督。"},{"no":"二十","title":"","text":"奖补政策实行“谁主管、谁解释、谁负责”的责任追究制度。主管部门要完善内部控制和内部监督制度，落实奖补政策管理的主体责任。财政部门对奖补政策资金实行跟踪管理；审计部门负责审计监督，根据年度审计项目安排，将奖补政策资金执行情况纳入审计监督范围。"},{"no":"二十一","title":"","text":"奖补对象提供虚假资料，骗取、套取奖补资金的，一经查实，立即停止发放，并由主管部门追回相应款项，5年内不得以任何形式申领财政性奖补资金；涉嫌犯罪的，依法移交司法机关处理。"},{"no":"二十二","title":"","text":"国家工作人员在奖补政策管理工作中存在违反规定、滥用职权、玩忽职守、徇私舞弊等违法违规行为的，依法追究责任；构成犯罪的，依法移交司法机关处理。"},{"no":"二十三","title":"第七章 附则","text":"本办法由州财政局负责解释。"},{"no":"二十四","title":"","text":"本办法自2025年10月13日起施行，有效期5年。现有奖补政策与本办法不符的，应停止执行。"}],"interpretations":[{"sectionNo":"七","headline":"奖补分贡献兑补、资格定补、择优奖补三类，以后补助为主","who":"在湘西州贡献突出的市场主体（投资额、营业额、吸纳就业人数、贷款等增量指标）；首次获省（高）级及以上资格认定、获奖、荣誉的对象；经评审择优的对象。","materials":[],"window":"按年度奖补政策兑现，原文未设固定申报期。","where":"由主管部门牵头组织评审、公示与兑现，无统一申报入口。","tip":"三类奖补以“后补助”和间接支持为主，不搞事前拨款；择优类须事先公布评审条件并公开结果。"},{"sectionNo":"十四","headline":"奖补对象须在湘西州开展业务，信用良好无较大以上事故","who":"个人：无违法违纪行为、征信良好。市场主体或单位：在湘西州内开展业务或开展与湘西州相关的业务，依法经营、信用良好、履行统计义务，未发生较大以上安全生产责任事故，未对生态环境造成不良影响。","materials":[],"window":"申报审核时点核查，全年适用，原文未设单独申报期。","where":"由各奖补政策主管部门在申报审核中把关，无统一申报入口。","tip":"任一条件不符即不具备资格；个人只核违法违纪与征信，单位还须核统计义务、安全生产与生态环境。"},{"sectionNo":"十五","headline":"每年一季度发申报公告，20个工作日内报材料，公示5个工作日","who":"申报奖补的市场主体和单位；贡献兑补、资格定补类对民营中小微企业和个体工商户实行“免申即享”，其他奖补类遵循自愿原则申报。","materials":[],"window":"主管部门原则上每年第一季度发布上一年度申报公告；申报主体在公告发布后20个工作日内提交材料；拟奖补名单公示5个工作日。","where":"向主管部门提交；州财政局将兑现资金拨付至主管部门或县市、湘西高新区，再支付至奖补对象。","tip":"申报窗口只有公告发布后20个工作日；公示期内有异议由主管部门处理并报州委、州人民政府。"},{"sectionNo":"二十一","headline":"提供虚假资料骗奖补，追回款项且5年内不得再申领","who":"申报或已获奖补的奖补对象（市场主体、单位、个人）。","materials":[],"window":"一经查实立即停止发放；追责后5年内不得申领财政性奖补资金。","where":"由主管部门追回相应款项；涉嫌犯罪的移交司法机关。","tip":"5年禁申领覆盖“以任何形式”申领财政性奖补资金；除追回外还可能移送司法机关。"}],"sourceUrl":"https://xxz.gov.cn/fdxxgknr/lzyj/gfxwj/202510/t20251028_2309275.html","derivedFrom":"official","sourceNote":"2026-11-24 修订：xxz.gov.cn 对脚本抓取返回 412（站点 JS 反爬），本节正文取自该页可读文本，按第一至第二十四条全文补录（原条目仅 7 款）。 2026-11-24 收录：与官方页面逐句比对，命中 76/76 句（100%），关卡判定「verbatim」。 有效期依据：原文未明示","verified":false,"isSample":false,"numberStyle":"clause","bodyVerified":"verbatim","hunan":true},{"id":"xxz-industry-fund-2025","title":"湘西自治州人民政府办公室关于印发《湘西州产业发展引导基金管理办法（试行）》的通知","level":"city","region":"湘西土家族苗族自治州","issuer":"湘西自治州人民政府办公室","documentNo":"州政办发〔2025〕4号","publishedAt":"2025-04-24","effectiveAt":"2025-04-24","expiresAt":"2027-04-24","status":"active","tags":["融资支持","专项资金"],"audience":["重点产业链企业","产业园区企业","子基金管理机构","社会资本出资人"],"summary":"设立总规模10亿元的州产业发展引导基金，由州财政局履行出资人职责，按“1+X+N”架构投资，不低于70%投资于子基金、不高于30%直投项目；直投对单一企业投资原则上不超过1000万元且不得成为第一大股东，重点投向11条重点产业链，有效期2年。","sections":[{"no":"三","title":"投资方向","text":"产业基金按照“政府引导、市场运作、科学决策、防范风险”的原则进行投资运作，主要投向我州生态文化旅游业、酒、烟、中医药和生物医药、锰锌产业及铝基复合材料、非金属矿产业及新材料、钒锂电池新能源及电子信息、优质茶叶（茶油）、特色果业、旅游类工艺及轻工产品、预制菜及特色食品等11条重点产业链。"},{"no":"四","title":"基金规模与出资","text":"产业基金总规模10亿元，根据实际需求分步到位。产业基金的政府出资部分，由州人民政府通过整合各类扶持产业发展的专项资金、滚动投资收益、新增预算安排及其他政府性资金等进行归集并出资。"},{"no":"十一","title":"投资架构","text":"产业基金按照“1+X+N”的整体投资架构进行投资运作。设立一个母基金，将其中不高于可投资金的30%投资于X个直投项目，不低于可投资金的70%投资于N个子基金。"},{"no":"十八","title":"直投项目投资限额","text":"直投项目可采用单独股权投资方式，也可引导、整合金融资本和社会资本共同投资。产业基金对单一企业的投资不得超过该企业股权比例的20%，且不得成为第一大股东。直投项目对单一企业的投资原则上不得超过1000万元。投资分红以及退出后收回的本金和收益可纳入基金管理，实行循环使用。"}],"interpretations":[{"sectionNo":"三","headline":"产业基金投向11条重点产业链，含文旅、中医药、新能源","who":"属于湘西州生态文化旅游业、酒、烟、中医药和生物医药、锰锌产业及铝基复合材料、非金属矿产业及新材料、钒锂电池新能源及电子信息、优质茶叶（茶油）、特色果业、旅游类工艺及轻工产品、预制菜及特色食品等11条重点产业链的企业和项目。","materials":[],"window":"原文未明确申报期与投资期限。","where":"原文未明确受理机构，基金按“政府引导、市场运作”原则运作","tip":"非11条重点产业链项目不在主要投向范围；基金按“政府引导、市场运作、科学决策、防范风险”原则运作。"},{"sectionNo":"十一","headline":"产业基金1+X+N：不高于30%直投、不低于70%投子基金","who":"纳入X个直投项目的企业，以及承接产业基金出资的N个子基金及其管理机构；母基金不高于可投资金30%用于直投、不低于70%用于子基金。","materials":[],"window":"按基金投资运作周期执行，原文未设申报截止期。","where":"原文未明确受理机构","tip":"直投与子基金比例按可投资金计算：直投不高于30%、子基金不低于70%。"},{"sectionNo":"十八","headline":"产业基金直投单一企业不超1000万元、持股不超20%","who":"接受产业基金直投的单一企业；基金持股不超过该企业股权比例的20%，且不成为第一大股东，直投金额原则上不超过1000万元。","materials":[],"window":"投资分红及退出收回的本金和收益可循环使用，原文未设申报期。","where":"原文未明确受理机构","tip":"不得成为第一大股东；1000万元为原则性上限，分红与退出收益可循环使用。"}],"sourceUrl":"https://xxz.gov.cn/fdxxgknr/lzyj/gfxwj/202504/t20250425_2249949.html","sourceNote":"2026-11-22 取自湘西自治州人民政府门户「法定主动公开内容—履职依据—规范性文件」原文页，版头载文号州政办发〔2025〕4号、统一登记号 XXCR—2025—01002，页面信息有效期栏载2027-04-24、列表标注“有效”。本机直连 xxz.gov.cn 被站点防护拦截（HTTP 412），改用工具端读取原文页全文，条文未与本地抓取文件比对。 2026-11-22 收录：官方页面未能打开或不是正文（fetch/html），条文未与原文比对。 有效期依据：第三十条明示“有效期2年”；页面信息有效期栏载2027-04-24","verified":false,"isSample":false,"numberStyle":"clause","bodyVerified":"unverifiable","hunan":true},{"id":"xxz-ip-fund-2024","title":"湘西自治州人民政府办公室关于印发《湘西自治州知识产权资助管理办法》的通知","level":"city","region":"湘西土家族苗族自治州","issuer":"湘西自治州人民政府办公室","documentNo":"州政办发〔2024〕11号","publishedAt":"2024-06-13","effectiveAt":"2024-06-13","expiresAt":"2027-06-13","status":"active","tags":["财政奖补","研发创新","融资支持","认定资质"],"audience":["知识产权优势企业","高新技术企业","专精特新“小巨人”企业","地理标志持有人"],"summary":"设知识产权强链护链、重点保护、地理标志运用保护培育、密集型产业培育、高校知识产权中心、学校知识产权教育六类立项项目，单项资助5万至20万元；知识产权质押融资按融资额分档补助评估费及贴息1万至5万元，专利实施转化按件数补助2万至10万元，有效期3年。","sections":[{"no":"二","title":"知识产权资助界定","text":"知识产权资助是指州人民政府对为湘西州开展知识产权项目服务有突出贡献的单位（企业）或个人给予一定的资金补助。"},{"no":"五（四）","title":"知识产权强链护链项目资助标准","text":"每个资助10万元，每年立项项目不超过3个。"},{"no":"六（四）","title":"知识产权重点保护项目资助标准","text":"每个资助6万元，每年立项项目不超过3个。"},{"no":"十一","title":"知识产权质押融资补助标准","text":"知识产权质押融资单笔融资额在50—200万元（不含200万元）的，补助评估费及贴息共计1万元；单笔融资额在200万元—500万元（不含500万元）的，补助评估费及贴息共计2.5万元；单笔融资额在500万元—1000万元（不含1000万元）的，补助评估费及贴息共计4万元；单笔融资额在1000万元（含1000万元）以上的，补助评估费及贴息共计5万元。"},{"no":"十二","title":"专利实施转化项目补助标准","text":"专利实施转化项目主要是鼓励专利实施转化，对湘西州辖区内获授权专利成功转化并在国家知识产权局备案的承接单位。当年同一单位专利转化运用5件—10件的，补助2万元；专利转化运用10件（不含10件）—20件的，补助4万元；专利转化运用20件（不含20件）—30件的，补助6万元；专利转化运用30件（不含30件）—40件的，补助8万元；专利转化运用40件（不含40件）以上的补助10万元。"}],"interpretations":[{"sectionNo":"二","headline":"为湘西州知识产权项目服务有突出贡献的单位或个人可获资助","who":"为湘西州开展知识产权项目服务有突出贡献的单位（企业）或个人；资助对象既包括企业，也包括个人。","materials":[],"window":"原文未规定申报期与执行期限，按具体资助项目安排执行。","where":"州人民政府","tip":"资助以“有突出贡献”为前置条件，具体金额按对应项目的资助标准执行。"},{"sectionNo":"五（四）","headline":"知识产权强链护链项目每个资助10万元，每年不超3个","who":"列入知识产权强链护链项目立项的单位（企业），每个项目资助10万元；全州每年立项项目不超过3个。","materials":[],"window":"按年度组织立项，每年立项项目不超过3个。","where":"原文未明确受理部门","tip":"每年立项不超过3个，资助以项目立项为前提。"},{"sectionNo":"六（四）","headline":"知识产权重点保护项目每个资助6万元，每年不超3个","who":"列入知识产权重点保护项目立项的单位（企业），每个项目资助6万元；全州每年立项项目不超过3个。","materials":[],"window":"按年度组织立项，每年立项项目不超过3个。","where":"原文未明确受理部门","tip":"每年立项不超过3个，资助以项目立项为前提。"},{"sectionNo":"十一","headline":"知识产权质押融资按单笔50万元起分档补1万至5万元","who":"以知识产权质押融资的企业，按单笔融资额分档补助评估费及贴息：50万元至200万元（不含200万元）补1万元，200万元至500万元（不含500万元）补2.5万元，500万元至1000万元（不含1000万元）补4万元，1000万元（含）以上补5万元。","materials":[],"window":"按单笔融资额分档核定，原文未规定申报截止时间。","where":"原文未明确受理部门","tip":"各档上限不含本数（200万元、500万元、1000万元），1000万元及以上按最高档5万元补助。"},{"sectionNo":"十二","headline":"专利转化按件数补2万至10万元，5件起补","who":"湘西州辖区内获授权专利成功转化并在国家知识产权局备案的承接单位；当年同一单位专利转化运用5件至10件补2万元，10件以上至20件补4万元，20件以上至30件补6万元，30件以上至40件补8万元，40件以上补10万元。","materials":[],"window":"按当年同一单位专利转化运用件数核定补助档次。","where":"国家知识产权局（备案），原文未明确州级受理窗口","tip":"档位分界10件、20件、30件、40件均不含本数，件数越多补助越高。"}],"sourceUrl":"https://xxz.gov.cn/fdxxgknr/lzyj/gfxwj/202406/t20240618_2156796.html","sourceNote":"2026-11-22 取自湘西自治州人民政府门户「法定主动公开内容—履职依据—规范性文件」原文页，版头载文号州政办发〔2024〕11号、统一登记号 XXCR—2024—01007，列表标注“有效”。本机直连 xxz.gov.cn 被站点防护拦截（HTTP 412），改用工具端读取原文页全文，条文未与本地抓取文件比对。 2026-11-22 收录：官方页面未能打开或不是正文（fetch/html），条文未与原文比对。 有效期依据：第二十三条明示“有效期3年”，自2024年6月13日起算至2027年6月13日","verified":false,"isSample":false,"numberStyle":"clause","bodyVerified":"unverifiable","hunan":true},{"id":"yiy-agri-2026","title":"益阳市人民政府办公室关于强化工业化理念产业化思维推动现代农业产业高质量发展的实施意见","level":"city","region":"益阳市","issuer":"益阳市人民政府办公室","documentNo":"益政办发〔2026〕7号","publishedAt":"2026-06-18","effectiveAt":"2026-06-18","expiresAt":"2031-06-18","status":"active","tags":["财政奖补","认定资质"],"audience":["农业产业化龙头企业","农产品精深加工企业","种养合作社","农产品流通企业"],"summary":"实施现代农业产业高质量发展“八项行动”，做大做强茶叶、笋竹、粮食、蔬菜、畜牧、水产6个百亿级主导产业；明确培育农业产业化龙头企业、农产品精深加工企业、农产品流通企业和绿色食品、有机农产品、地理标志农产品认证，“十五五”期末绿色优质农产品达448个以上。","sections":[{"no":"一","title":"工作目标","text":"做大做强茶叶、笋竹、粮食、蔬菜、畜牧、水产等6个百亿级主导产业，巩固提升中药材1个50亿级特色产业，储备打造安化腊肉等若干超10亿元的新兴产业。“十五五”期间，全市农林牧渔总产值年均增速达3.5%以上，确保不低于全省平均水平。"},{"no":"二（一）5","title":"实施农业产业化龙头企业强链育梯专项行动","text":"积极引导龙头企业打造农业全产业链，培育一批“链主”企业，推动农业产业链补链、延链、强链，形成国家级、省级、市级三级龙头企业梯队。“十五五”期间，全市年销售收入达到500万元、2000万元、5000万元、8000万元、1亿元及以上的农业产业化龙头企业分别新增120家、90家、60家、30家和20家。"},{"no":"二（一）7","title":"实施农产品精深加工企业引培延链专项行动","text":"开展“湘商回归 校友回乡 返乡创业”活动，突出招大引强，紧盯农业产业头部企业，着力引进一批国内农业产业化500强企业、农业产业化国家重点龙头企业，着力发展农产品精深加工，做大做强农产品全产业链。"},{"no":"二（二）","title":"实施农产品质量“四品一标”行动","text":"全面推行农产品承诺达标合格证制度，积极培育绿色食品，稳步发展有机农产品，着力打造全链条、全周期名特优新农产品，因地制宜培育地理标志农产品。到“十五五”期末，确保全市绿色食品、有机农产品、名特优新农产品、地理标志农产品数量达到448个以上。"}],"interpretations":[],"sourceUrl":"https://www.yiyang.gov.cn/yiyang/2/78/3284/content_2184827.html","sourceNote":"2026-11-22 取自益阳市人民政府门户「法定主动公开内容—法规文件—市政府办文件」原文页，版头载文号益政办发〔2026〕7号、统一登记号 YYCR－2026－01006，页面信息时效期栏载2031-06-18。publishedAt/effectiveAt 取页面“发文日期”2026-06-18（原文为“自公布之日起施行”）。 2026-11-22 收录：与官方页面逐句比对，命中 7/7 句（100%），关卡判定「verbatim」。 有效期依据：正文倒数第二段明示“本实施意见自公布之日起施行，有效期5年”；页面信息时效期栏载2031-06-18","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"yiy-logistics-2024","title":"益阳市人民政府办公室关于印发《益阳市加快推进现代物流业高质量发展若干措施》的通知","level":"city","region":"益阳市","issuer":"益阳市人民政府办公室","documentNo":"益政办发〔2024〕6号","publishedAt":"2024-05-22","effectiveAt":"2024-05-22","expiresAt":"2029-05-22","status":"active","tags":["财政奖补","融资支持","场地支持"],"audience":["物流企业","多式联运企业","冷链物流企业","货运代理与供应链企业"],"summary":"从完善物流设施、优化空间布局、培育壮大物流企业、提升金融服务四方面提出措施；对入库当年主营业务收入达标准2倍及以上的规上物流企业再给予5万元一次性奖励，单户担保金额1000万元以下的物流企业平均担保费率控制在1%以下，有效期至2029年5月22日。","sections":[{"no":"一（一）","title":"加强现代物流基础设施建设","text":"完善县乡村三级物流基础设施建设，县市区加快农产品集散中心、交易中心、批发市场、快递分拣中心、冷链物流设施建设，建成大通湖物流园建设工程。加快推进符合条件的乡镇建设乡镇运输服务站和村级首末站。"},{"no":"一（二）","title":"加快发展多式联运配套设施","text":"推动各种交通运输方式高效衔接，做大做强多式联运企业，整合铁路、港口、海关、货代公司、船公司等多方资源，加大多式联运“一单制”业务配套设施建设，以国家高等级航道和主要港口为重点，重点建设白沙至甘溪港1000吨级航道、益阳至芦林潭2000吨级航道、常德至鲇鱼口2000吨级航道、赤峰1000吨级和漉湖港2000吨级码头等项目。"},{"no":"三（七）","title":"招大引强物流企业","text":"积极引进国内外知名大型物流、货运代理和供应链龙头企业，在益阳设立总部或区域总部、分拨中心、运营中心、研发创新中心，支持企业将注册地和纳税地迁入益阳并在区域内交易结算。对新引进物流企业当年经济实际贡献较大的，注册地人民政府可以给予适当奖励，奖励就高不就低，不重复奖励。"},{"no":"三（八）","title":"扶植培育骨干企业","text":"3年内，培育8-10家规模以上多式联运企业，为农副产品、制造业大宗工业品提供一体化全流程物流服务。鼓励本土骨干物流企业整合资源，发展为“链主型”龙头企业。对当年度入库的规上企业，按照《益阳市加快推进服务业高质量发展若干措施》（益政办发〔2022〕21号）执行，入库当年年主营业务收入达到入库标准2倍及以上的物流企业再给予5万元一次性奖励。"},{"no":"四（十一）","title":"提升现代物流金融服务","text":"支持物流企业通过银行贷款、发行债券、增资扩股、仓单质押、股权质押贷款等途径筹集资金，鼓励金融机构创新符合物流行业发展特点的金融产品，合理确定抵质押物范围及抵质押率，加大对优质项目和诚实守信、发展前景良好的中小物流企业金融支持力度。政府性融资担保机构进一步降低担保费率，单户担保金额1000万元以下的物流企业平均担保费率控制在1%以下。"}],"interpretations":[{"sectionNo":"三（七）","headline":"新引进物流企业贡献较大，注册地政府可给奖励，就高不就低","who":"在益阳设立总部或区域总部、分拨中心、运营中心、研发创新中心，并将注册地和纳税地迁入益阳、在区域内交易结算的新引进物流、货运代理和供应链龙头企业；当年经济实际贡献较大。","materials":[],"window":"按新引进企业当年经济实际贡献核定，具体申报时间原文未列。","where":"注册地人民政府","tip":"奖励就高不就低、不重复奖励；原文未定具体奖励金额标准。"},{"sectionNo":"三（八）","headline":"入库当年营收达标准2倍，物流企业再奖5万元","who":"当年度入库的规上物流企业；入库当年年主营业务收入达到入库标准2倍及以上。","materials":[],"window":"3年内培育8-10家规模以上多式联运企业；奖励按入库当年营收核算。","where":"按《益阳市加快推进服务业高质量发展若干措施》（益政办发〔2022〕21号）执行","tip":"5万元是一次性叠加奖励，须先按益政办发〔2022〕21号入库并达到营收2倍标准。"},{"sectionNo":"四（十一）","headline":"单户1000万元以下物流企业，平均担保费率控制在1%以下","who":"物流企业；政府性融资担保机构对单户担保金额1000万元以下的物流企业，平均担保费率控制在1%以下。","materials":[],"window":"常态化执行，原文未设申报期限。","where":"政府性融资担保机构及银行等金融机构","tip":"1%是平均担保费率控制线，不是每笔业务费率；银行贷款、发行债券、增资扩股、仓单质押、股权质押贷款等渠道均可使用。"}],"sourceUrl":"https://www.yiyang.gov.cn/yiyang/2/78/3284/content_1944048.html","sourceNote":"2026-11-22 取自益阳市人民政府门户「法定主动公开内容—法规文件—市政府办文件」原文页，版头载文号益政办发〔2024〕6号、统一登记号 YYCR－2024－01005，页面信息时效期栏载2029-05-22。 2026-11-22 收录：与官方页面逐句比对，命中 10/10 句（100%），关卡判定「verbatim」。 有效期依据：页面信息时效期栏明示2029-05-22，与发文日期2024-05-22相隔5年","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"yiy-zhongyi-2026","title":"益阳市人民政府办公室印发《关于促进益阳市中医药事业和产业高质量发展若干措施》的通知","level":"city","region":"益阳市","issuer":"益阳市人民政府办公室","documentNo":"益政办发〔2026〕5号","publishedAt":"2026-04-25","effectiveAt":"2026-04-25","expiresAt":"2031-04-25","status":"active","tags":["专项资金","财政奖补","人才政策"],"audience":["中药生产企业","中药材种植主体","中医药产业园区企业","中医医疗机构"],"summary":"从中医特色医院、专科能力、人才队伍、科研创新、防康养、文化传承、产业集群品牌化、保障机制八方面提出措施；市财政每年安排300万元预算设立专项资金，由市县两级对本措施实施奖补，有效期5年。","sections":[{"no":"三","title":"支持中医药高层次和特色人才队伍建设","text":"实施“银城岐黄”人才计划，5年内培育2名省级名中医、10名市级名中医、3名非遗传承人、30名青年中医药骨干人才。加大引进力度。对全职引进的省级以上名中医、学科带头人，畅通绿色通道，落实安家费补贴等相关待遇；通过柔性引才等方式，引进10名中医药学科带头人。推进传承工作室建设。5年内分别建成国家级、省级、市级名老中医药专家传承工作室2个、3个、10个。鼓励公立中医医院建立人才基金，支持中医药高层次和特色人才队伍建设。"},{"no":"七","title":"支持中医药产业集群化品牌化发展","text":"新建1个中药材种质资源保存圃（库），累计建成3个以上省级道地药材良种繁育基地、10个以上中药材种植（含养殖）示范基地，3个以上中药材生产质量管理规范（GAP）基地，3个以上产地趁鲜切制加工示范基地，全市扩大中药材种植（含养殖）面积10万亩。"},{"no":"七（续）","title":"集群与品牌支持","text":"支持建设1个区域性中药材交易集散地；鼓励社会资本参与中医药产业发展，培育1个中医药产业优势集群；支持有条件的园区积极引进中医药产业链企业8家以上，推动产业集聚与产值规模提升；培育国家级、省级中医药相关的农业（林业）产业化龙头企业各1家、5家。"},{"no":"八","title":"加强中医药事业产业发展保障","text":"健全市县两级财政投入机制，设立专项资金，按照财政事权与支出责任，由市、县（市区）对本措施实施奖补，市财政每年安排300万元预算，统筹用于支持中医药事业和产业高质量发展。强化政策保障。支持中医传统技术与新技术申报纳入医保目录，遴选中医优势病种按疗效价值付费，积极推进院内自制制剂在医联体内使用并纳入医保支付范畴，积极探索中医药创新支付。强化体制机制保障。健全中医药工作联席会议制度，由成员单位会商制定奖补细则，强化统筹协调与督导考核，确保各项保障措施落地见效。"}],"interpretations":[{"sectionNo":"三","headline":"5年培育2名省级名中医、10名市级名中医，引进人才给安家费","who":"中医药高层次和特色人才；全职引进的省级以上名中医、学科带头人可落实安家费补贴等相关待遇；通过柔性引才方式引进的中医药学科带头人；5年内培育2名省级名中医、10名市级名中医、3名非遗传承人、30名青年中医药骨干人才。","materials":[],"window":"5年内完成培育目标；传承工作室5年内分别建成国家级2个、省级3个、市级10个。","where":"益阳市公立中医医院、名老中医药专家传承工作室。","tip":"安家费补贴等待遇只对全职引进的省级以上名中医、学科带头人落实，柔性引才另有10名学科带头人引进计划。"},{"sectionNo":"七","headline":"中药材：建1个种质资源圃、3个以上省级良种繁育基地","who":"中药材种质资源保存圃（库）、良种繁育基地、种植（含养殖）示范基地、中药材生产质量管理规范（GAP）基地、产地趁鲜切制加工示范基地等项目建设主体；全市扩大中药材种植（含养殖）面积10万亩。","materials":[],"window":"累计建成3个以上省级道地药材良种繁育基地、10个以上中药材种植（含养殖）示范基地。","where":"益阳市中药材种质资源保存圃（库）、道地药材良种繁育基地、中药材种植（含养殖）示范基地、产地趁鲜切制加工示范基地。","tip":"新建种质资源保存圃（库）1个；全市中药材种植（含养殖）面积扩大到10万亩。"},{"sectionNo":"七（续）","headline":"建1个区域性中药材交易集散地，培育1个中医药产业优势集群","who":"建设区域性中药材交易集散地的主体、参与中医药产业发展的社会资本、引进中医药产业链企业的园区；培育国家级、省级中医药相关的农业（林业）产业化龙头企业各1家、5家。","materials":[],"window":"有条件的园区引进中医药产业链企业8家以上。","where":"益阳市有条件的园区、区域性中药材交易集散地。","tip":"交易集散地全市建1个；龙头企业培育目标为国家级1家、省级5家。"}],"sourceUrl":"https://www.yiyang.gov.cn/yiyang/2/78/3284/content_2171470.html","sourceNote":"2026-11-22 取自益阳市人民政府门户「信息公开—政府信息公开发布平台—法定主动公开内容—法规文件—市政府办文件」原文页，版头载文号益政办发〔2026〕5号、统一登记号 YYCR－2026－01004，页面信息时效期栏载2031-04-25。 2026-11-22 收录：与官方页面逐句比对，命中 13/13 句（100%），关卡判定「verbatim」。 有效期依据：正文末条明示“有效期5年”；页面信息时效期栏载2031-04-25","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"yl-land-use-tax-2026","title":"炎陵县人民政府关于明确炎陵县城镇土地使用税地段等级适用税额标准和征收范围的通知","level":"district","region":"株洲市·炎陵县","issuer":"炎陵县人民政府","documentNo":"炎政发〔2026〕3号","publishedAt":"2026-02-10","effectiveAt":"2026-02-10","expiresAt":"2031-02-09","status":"active","tags":["税收优惠","营商环境"],"audience":["炎陵县城镇土地使用税纳税人（县城、建制镇、工矿区范围内使用土地的单位和个人）","九龙经济技术开发区、中小企业创业园入驻企业"],"summary":"调整炎陵县城镇土地使用税征收范围与地段等级税额标准：全县分二级、三级、四级、五级、八级五个等级，税额分别为10元、8元、6元、5元、2元/年/平方米；建制镇统一为八级（2元），九龙经济技术开发区和中小企业创业园为五级（5元），其余县城区域按对应等级征收；调整因2015年乡镇撤并（原三河镇并入霞阳镇）及部分区域已具备征收条件；自文件发布之日起施行，有效期5年。","sections":[{"no":"一","title":"调整的标准和原因","text":"此次调整以炎陵县自然资源局提供的炎陵县开发边界布局图为标准，结合炎陵县未来的发展规划和土地用途对城镇土地使用税征收范围进行调整，其中也涉及部分区域的等级税额标准变化。本次范围调整的原因，一是炎陵县2015年进行了乡镇撤并，其中涉及城镇土地使用税的主要是原三河镇撤销后并入了霞阳镇，从建制镇升级为县城辖区，需要重新确定城镇土地使用税征收范围。二是随着县域经济的发展，部分原来没有列入城镇土地使用税征收范围的区域已经具备征收条件，此次将其列入征收范围。"},{"no":"二","title":"调整后的征收范围","text":"此次征收范围调整以炎陵县城镇开发边界布局图为标准，以下是大略描述县城及各建制镇征收范围，具体以炎陵县城镇开发边界布局图为准。（一）县城：分为两段，一段位于东至康乐大道以东，西至九龙工业园区，北至霞阳互通口、南至草坪，其中包括九龙经济技术开发区和中小企业创业园；另一段位于原三河镇范围。（二）建制镇1.鹿原镇：东至炎帝陵风景区，西至天星村，北至塘旺村、南邻新坪村。征收区域被斜獭水分为南北两段。2.水口镇：位于水口村（水口镇人民政府所在地）范围。3.十都镇：分为两段，一段位于晓东村（十都镇人民政府所在地）范围，另一段位于南流村和神农谷国家森林公园之间。4.沔渡镇：分为两段，一段位于晓阳村（沔渡镇人民政府所在地）范围，另一段位于苍背村范围。"},{"no":"三","title":"调整后的征收标准","text":"我县目前分为二级、三级、四级、五级、八级共五个等级，每个等级税额分别为10元、8元、6元、5元、2元/年/㎡。建制镇土地等级为八级，九龙经济技术开发区和中小企业创业园土地等级为五级，其余县城区域土地划分为若干等级，城镇土地使用税分别按照对应等级的单位年税额征收（详见附件2）。"},{"no":"四","title":"执行时间","text":"上述调整后的城镇土地使用税征收范围，从文件发布之日起施行。此文件有效期为5年，此前相关规定与本通知不一致的，以本通知为准。"}],"interpretations":[{"sectionNo":"二","headline":"县城及鹿原水口十都沔渡等建制镇划入城镇土地使用税征收范围","who":"在炎陵县上述县城范围（含九龙经济技术开发区、中小企业创业园及原三河镇范围）和鹿原镇、水口镇、十都镇、沔渡镇征收范围内使用土地的纳税人。","materials":[],"window":"征收范围自文件发布之日起执行，范围边界以炎陵县城镇开发边界布局图为准。","where":"炎陵县城镇开发边界布局图划定的县城及鹿原镇、水口镇、十都镇、沔渡镇范围。","tip":"条文对范围只是大略描述，边界处土地是否应税须按炎陵县城镇开发边界布局图核对，图内即为征收范围。"},{"sectionNo":"三","headline":"城镇土地使用税分五级，每平方米年税额10元至2元","who":"炎陵县城镇土地使用税征收范围内使用土地的纳税人：建制镇土地按八级2元/年/㎡，九龙经济技术开发区和中小企业创业园按五级5元/年/㎡，其余县城区域按所处等级10元、8元、6元、5元、2元/年/㎡。","materials":[],"window":"按土地等级对应的单位年税额按年征收；具体地块等级详见附件2。","where":"炎陵县县城区域、九龙经济技术开发区、中小企业创业园及建制镇（按土地等级对应税额，详见附件2）。","tip":"建制镇统一为八级2元/年/㎡，开发区和创业园为五级5元/年/㎡，同一县域内等级不同、税额差距明显。"}],"sourceUrl":"http://www.hnyanling.gov.cn/c24355/20260211/i2477216.html","derivedFrom":"official","sourceNote":"2026-11-24 取自炎陵县人民政府门户（正确域名 hnyanling.gov.cn）「政务公开>政府信息公开目录>政府文件>规范性文件」栏目原文页；正文为页面内嵌 HTML 全文，按原文“一、调整的标准和原因”“二、调整后的征收范围”“三、调整后的征收标准”“四、执行时间”四部分逐段转录，第二部分内的（一）（二）及1—4建制镇分项一并保留；附件1《调查测算表》、附件2《地段等级税额标准及征收范围表》为附表，未并入条文。索引号412500/2026-00423，统一登记号YLDR-2026-00002，公开责任部门县财政局。 2026-11-24 收录：与官方页面逐句比对，命中 14/14 句（100%），关卡判定「verbatim」。 有效期依据：第四部分（执行时间）","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"yx-social-insurance-subsidy-2025","title":"关于开展2025年攸县灵活就业人员社会保险补贴工作的通知","level":"district","region":"株洲市·攸县","issuer":"攸县人力资源和社会保障局","documentNo":"","publishedAt":"2025-04-16","effectiveAt":"2025-04-16","expiresAt":null,"status":"active","tags":["社保补贴","就业补贴"],"audience":["攸县就业困难人员（灵活就业并以个人身份参保缴费）","离校2年内未就业高校毕业生","脱贫人口"],"summary":"对攸县灵活就业人员给予社会保险补贴：对象为持有《就业失业登记证》或《就业创业证》并被认定为就业困难对象者、离校2年内未就业高校毕业生、脱贫人口三类；就业困难人员补贴期限一般不超过3年，距法定退休不足5年的可延长至法定退休，高校毕业生最长不超过2年；采取“先缴后补”、按自然年度缴费，集中受理时间为5月至10月。补贴按上年度全省全口径社会平均工资的60%为基数、按实际缴费费率计算，“4050”人员补贴计算金额的60%、非“4050”人员补贴40%，高校毕业生和脱贫人口按非“4050”标准执行；审核通过后公示7天再拨付至本人社保卡。","sections":[{"no":"一","title":"补贴对象及条件","text":"1.持有《就业失业登记证》或《就业创业证》且被认定为就业困难对象，并以灵活就业人员身份参加社会保险、履行了社会保险费缴纳义务的；2.离校2年内未就业高校毕业生灵活就业后,以灵活就业人员身份参加社会保险且履行了社会保险费缴纳义务的高校毕业生；3.脱贫人口通过临时性、非全日制、季节性、弹性工作等多种形式灵活就业的，并以灵活就业人员身份参加社会保险、履行了社会保险费缴纳义务。"},{"no":"二","title":"补贴期限、补贴方式及办理时间","text":"就业困难人员社会保险补贴期限一般不超过3年；自初次核定其享受社会保险补贴之日起计算，距法定退休时间不足5年的，可延长享受至法定退休时间（此类申请人在3年补贴期满后，需凭退休证明向县本级申请延长享受至法定退休时间；对不能提供退休证明的，暂不纳入延长补贴范围）；对离校2年内的高校毕业生补贴期限最长不超过2年，补贴时限从初次核定其享受社会保险补贴之日起，至毕业时间满2年为止；脱贫人口比照就业困难人员按规定给予社会保险补贴（此前已享受过社会保险补贴的人员补贴期限合并计算）。社会保险补贴采取“先缴后补”的方式，按自然年度缴费。社会保险补贴业务集中受理时间为5月至10月。"},{"no":"三","title":"补贴标准","text":"符合条件的就业困难人员灵活就业社会保险补贴计算方式：社会保险费缴费基数按上年度我省全口径社会平均工资的60%执行，费率按实际缴纳社会保险的费率执行。“4050”人员（女性年龄在40周岁以上、男性年龄在50周岁以上，下同）按上述方式计算金额的60%予以补贴，非“4050”人员按上述方式计算金额的40%予以补贴。符合条件的离校2年内未就业高校毕业生、脱贫人口灵活就业后社会保险补贴按前款非“4050”人员标准执行。"},{"no":"四","title":"补贴的申请及审核","text":"（一）申请。已实现灵活就业的就业困难人员应按规定及时缴纳社会保险费，并在文件规定的时间内办理社保补贴申报手续。补贴申请人需提供以下资料备查：（1）本人身份证；（2）本人社保卡；（3）《就业失业登记证》(或《就业创业证》)；（4）社会保险缴费凭证；(5)退休证明（享受距退休前5年内补贴期限的人员，在享受满36个月后，需提供退休证明申报剩余月数补贴）。（6）离校2年内的高校毕业生提供毕业证书或学信网学籍证明。（7）脱贫人口提供农业农村局开具的脱贫人口证明。社会保险补贴申报人需对填报录入的所有信息的真实性、准确性负责，对提交虚假错误信息导致的后果由填报人全部承担。（二）审核及补贴拨付。灵活就业人员提交的社会保险补贴申请由社区（村）完成资料录入和调查，提交给街道（乡镇）进行确认，街道（乡镇）确认后，提交攸县人力资源和社会保障局就业服务中心审核。审核通过的，将相关补贴信息在县级门户网站公示7天，无异议后，按规定将补贴资金拨付至申请者本人社会保障卡账户。"}],"interpretations":[{"sectionNo":"一","headline":"就业困难人员、离校2年内毕业生、脱贫人口可申社保补贴","who":"持有《就业失业登记证》或《就业创业证》且被认定为就业困难对象、以灵活就业人员身份参加社会保险并履行缴费义务的人员；离校2年内未就业高校毕业生，灵活就业后以灵活就业人员身份参保并履行缴费义务；脱贫人口通过临时性、非全日制、季节性、弹性工作等多种形式灵活就业，并以灵活就业人员身份参保缴费。","materials":[],"window":"以灵活就业人员身份参保并履行缴费义务后申报；集中受理时间为5月至10月（见第二条）。","where":"攸县人力资源和社会保障局就业服务中心（经社区（村）、街道（乡镇）逐级审核）。","tip":"三类对象都要求以灵活就业人员身份参加社会保险并已实际缴费；就业困难对象须先被认定并持证。"},{"sectionNo":"二","headline":"就业困难人员补贴最长3年，距退休不足5年可延至退休","who":"就业困难人员：补贴期限一般不超过3年，自初次核定之日起算，距法定退休时间不足5年可延长至法定退休时间，3年期满后需凭退休证明向县本级申请；离校2年内高校毕业生：补贴期限最长不超过2年，至毕业时间满2年为止；脱贫人口：比照就业困难人员；此前已享受过社会保险补贴的人员，补贴期限合并计算。","materials":["退休证明"],"window":"自初次核定其享受社会保险补贴之日起计算；按自然年度缴费，集中受理时间为5月至10月。","where":"攸县本级（申请延长享受至法定退休时间）。","tip":"3年补贴期满后须凭退休证明向县本级申请延长，不能提供退休证明的暂不纳入延长补贴范围；此前已享受过的补贴期限合并计算。"},{"sectionNo":"三","headline":"“4050”人员按缴费额60%补贴，其他人员40%","who":"灵活就业的就业困难人员：“4050”人员（女性年龄40周岁以上、男性年龄50周岁以上）按计算金额的60%补贴，非“4050”人员按40%补贴；符合条件的离校2年内未就业高校毕业生、脱贫人口灵活就业后按非“4050”人员标准即40%执行。缴费基数按上年度全省全口径社会平均工资的60%执行，费率按实际缴纳社会保险的费率执行。","materials":[],"window":"按自然年度缴费；补贴按上述计算金额的比例核定。","where":"攸县人力资源和社会保障局就业服务中心（属地审核拨付）。","tip":"“4050”与“非4050”按不同比例补贴，高校毕业生和脱贫人口按40%执行；缴费基数固定为全省全口径社会平均工资的60%。"},{"sectionNo":"四","headline":"灵活就业社保补贴公示7天，无异议后拨至本人社保卡","who":"已实现灵活就业并按规定及时缴纳社会保险费的就业困难人员；享受距退休前5年内补贴期限的人员，满36个月后需提供退休证明申报剩余月数；离校2年内高校毕业生需提供毕业证书或学信网学籍证明；脱贫人口需提供农业农村局开具的脱贫人口证明。","materials":["本人身份证","本人社保卡","《就业失业登记证》(或《就业创业证》)","社会保险缴费凭证","退休证明","毕业证书或学信网学籍证明","农业农村局开具的脱贫人口证明"],"window":"在文件规定的时间内办理申报手续；审核通过后公示7天，无异议再拨付。","where":"社区（村）录入调查、街道（乡镇）确认，攸县人力资源和社会保障局就业服务中心审核；补贴信息在县级门户网站公示。","tip":"申报人对填报录入信息的真实性、准确性负责，提交虚假错误信息导致的后果由填报人全部承担；须先缴费后申报，资金拨付至本人社会保障卡账户。"}],"sourceUrl":"https://www.hnyx.gov.cn/c20487/20250530/i2373950.html","derivedFrom":"official","sourceNote":"2026-11-24 取自攸县人民政府门户「基层政务公开标准化规范化专栏>公开领域>社会保险」栏目原文页（栏目路径 c20487），正文为页面内嵌 HTML 全文（非附件）。页面未标注发文字号，来源标注“就业中心”，发布时间2025年4月16日。 2026-11-24 收录：与官方页面逐句比对，命中 22/22 句（100%），关卡判定「verbatim」。 有效期依据：第二部分（补贴期限、补贴方式及办理时间）","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"yx-youhuidai-risk-fund-2025","title":"攸县人民政府办公室关于印发《攸县“攸惠贷”风险补偿资金管理办法》的通知","level":"district","region":"株洲市·攸县","issuer":"攸县人民政府办公室","documentNo":"攸政办发〔2025〕4号","publishedAt":"2025-12-31","effectiveAt":"2026-01-01","expiresAt":"2030-12-31","status":"active","tags":["融资支持","专项资金","营商环境"],"audience":["攸县依法登记注册的法人组织或社会经济实体（有限责任公司、股份有限公司、个人独资企业等）","参与风补资金业务的合作银行"],"summary":"设立“攸惠贷”信贷风险补偿资金，由县人民政府出资，合作银行按专用账户定期存单金额1:10放大向企业发放抵押或质押贷款；单户企业贷款额度不超过1000万元、单笔期限不超过3年、年化利率不超过当期LPR+100BP；贷款形成不良后，风补资金按贷款本金损失的30%代偿，合作银行追回资金扣除必要费用后按30%回补专户；代偿贷款笔数占比超5%或代偿总额超定期存单总额须暂停新业务；自2026年1月1日起施行，有效期五年，原攸政办发〔2023〕1号同时废止。","sections":[{"no":"一","title":"第一章 总 则","text":"为进一步增强金融服务实体经济能力，有效缓解企业融资难、融资贵问题，根据《中华人民共和国中小企业促进法》、《国务院办公厅关于有效发挥政府性融资担保基金作用切实支持小微企业和\"三农\"发展的指导意见》（国办发〔2019〕6号）文件精神，县人民政府决定设立\"攸惠贷\"信贷风险补偿资金，为企业融资提供风险补偿。为规范信贷风险补偿基金管理，提高资金使用效率，结合我县实际，制定本办法。"},{"no":"二","title":"","text":"本办法所称\"攸县'攸惠贷'风险补偿资金\"（以下简称风补资金）是指由县人民政府出资设立，用于引导合作银行为企业提供贷款支持的专项资金，专项资金按县人民政府拨款情况分批存入专项资金账户。账户实行专户管理、专款专用，所产生的利息，作为下一年度风补资金滚存使用。"},{"no":"三","title":"","text":"本办法所称\"企业\"是指依法登记注册的法人组织或社会经济实体。包括有限责任公司、股份有限公司、个人独资企业和其他企业等。"},{"no":"四","title":"","text":"本办法所称\"合作银行\"是指向县政府办提出申请并参与风补资金业务的银行业金融机构。"},{"no":"五","title":"","text":"本办法所称\"贷款\"是指合作银行根据专项资金账户存入的定期存单金额，按1:10比例放大额度向符合本办法规定条件的企业发放的抵押或质押贷款。"},{"no":"六","title":"","text":"本办法所称\"代偿\"是指合作银行发放的贷款在形成不良贷款时，风补资金给予合作银行贷款本金损失的30%作为风险补偿。"},{"no":"七","title":"第二章 业务流程","text":"银行向县政府办提交参与风补资金业务申请后纳入合作名单。"},{"no":"八","title":"","text":"合作银行按以下流程发放贷款及办理贷款纳入代偿范围备案：（一）企业向县政府办提出申请；（二）县政府办根据企业自主意愿向相应的合作银行进行书面推荐；（三）合作银行根据自身业务准则独立自主对企业进行贷款审批和发放；（四）合作银行发放贷款后3个工作日内将贷款合同复印件报县政府办备案；（五）县政府办审核贷款金额、利率、期限等要素符合本办法规定的条件后贷款纳入代偿范围，并按贷款比例将专项资金以定期存单的方式存入贷款银行。"},{"no":"九","title":"","text":"合作银行按以下流程申请代偿：企业贷款本金逾期超过30个自然日或贷款本金未逾期，但利息连续逾期3期及以上的，合作银行可以向县政府办申请代偿，并提交以下资料：1.代偿申请书；2.不良贷款证明资料复印件；3.贷后管理及催收情况说明及相关资料复印件；4.向法院提起诉讼或向仲裁机构申请仲裁等积极追偿的相关资料。（二）县政府办自收到申请之日起10个工作日内完成审查后报县人民政府审批。审查内容包括但不限于：合作银行对重大风险事项有无应知未知的情况，合作银行贷前尽职调查情况及贷后管理情况等。（三）县人民政府完成审核后10个工作日内，风补资金将代偿资金拨付合作银行。"},{"no":"十","title":"第三章 贷后管理","text":"合作银行在贷款发放后应持续进行动态管理，做好贷后检查、抵（质）押物日常保管等工作，实时了解贷款企业经营情况。"},{"no":"十一","title":"","text":"企业出现贷款本金逾期或利息逾期时，合作银行应立即向县政府办报备，并制定催收方案开展催收，尽全力避免造成贷款本金损失。"},{"no":"十二","title":"","text":"合作银行在获得代偿资金后，必须继续负责不良贷款的全面追偿工作（包括但不限于司法诉讼等一切必要措施），并建立月度汇报机制，定期向县政府办提交追偿进度报告。"},{"no":"十三","title":"","text":"合作银行追回部分或全部不良贷款后，在扣除诉讼费、律师费等必要支出费用后，将剩余追回资金的30%转至风补资金专户。"},{"no":"十四","title":"第四章 代偿范围","text":"合作银行申请纳入代偿范围的贷款必须同时符合以下条件：（一）单户企业贷款额度不超过1000万元；（二）单笔贷款期限不超过3年；（三）贷款年化利率不超过当期LPR+100BP。其中，LPR为1年期贷款市场报价利率；（四）贷款不得用于转贷、参与民间借贷和投资资本市场，不得用于归还贷款企业在同一机构或者同一机构关联方原有贷款。"},{"no":"十五","title":"","text":"企业具有以下任意一种或多种情形时，合作银行向其发放的贷款不纳入代偿范围：（一）企业经营生产未超过一年的；（二）企业资产负债率超过65%的；（三）近两年企业经营连续亏损的；（四）近两年企业和实际控制人、法定代表人参与民间借贷导致正常经营受到重大不利影响的；存在恶意逃废债务等重大不良信用记录的；（五）有虚假交易和骗取银行贷款、出口退税、政府补贴等不诚信行为的，或者近两年因重大违法违规情形受到行政处罚的；（六）实际控制人或法定代表人有重大涉经济类犯罪（故意），并造成重大影响的；（七）已享受县内其他信贷风险补偿政策的。"},{"no":"十六","title":"第五章 贷款核销","text":"如贷款企业破产清算或对贷款企业诉讼且依法裁定执行终结的情况下，合作银行对贷款进行核销后7个工作日之内，需向县政府办递交资料进行备案，资料包括：（一）贷款核销报告。内容包括：贷款企业基本情况、贷款发放和管理情况、补偿和追偿情况及最终核算的损失情况等；（二）法院的民事判决书及其他可以确认形成损失的法律文书或证明材料；（三）其他补充资料。"},{"no":"十七","title":"","text":"代偿、贷款核销不改变合作银行与贷款企业的借贷关系，贷款企业及其相关当事人仍需按贷款合同约定承担全部责任。合作银行不得擅自放弃追偿权利。"},{"no":"十八","title":"第六章 日常管理","text":"县政府办应按年度向县人民政府报告合作银行贷款发放、备案、追偿等情况及其他重大事项。"},{"no":"十九","title":"","text":"若合作银行出现以下任一情况：代偿贷款笔数占存量笔数比例超过5%，或代偿总金额超过定期存单总额，须立即暂停发放新贷款。同时，必须着力推进债务追偿并进行彻底自查整改，待追偿见效、整改完成，并报请县政府办批准后，才能恢复相关业务。"},{"no":"二十","title":"","text":"县政府办按年度对合作银行贷款发放、风险控制等情况进行综合考核，并根据考核结果采取调整风补资金专户金额、取消下年度合作关系等措施确保风补资金平稳运营，风险可控。"},{"no":"二十一","title":"第七章 附 则","text":"本办法从 2026年1月1日起施行，有效期五年。同时原《攸县\"攸惠贷\"风险补偿资金管理办法》（攸政办发〔2023〕1号）废止。"}],"interpretations":[{"sectionNo":"三","headline":"攸县依法登记的企业法人和经济实体均可申请","who":"依法登记注册的法人组织或社会经济实体；包括有限责任公司、股份有限公司、个人独资企业和其他企业。","materials":[],"window":"原文未设申报期限","where":"县政府办","tip":"主体范围含有限责任公司、股份有限公司、个人独资企业和其他企业；非法人组织不在列举范围。"},{"sectionNo":"五","headline":"合作银行按存单金额1:10放大放贷，须抵押或质押","who":"符合本办法规定条件的企业；贷款由合作银行按专项资金账户定期存单金额1:10放大额度发放，须提供抵押或质押。","materials":[],"window":"原文未设申报期限","where":"合作银行","tip":"贷款须为抵押或质押贷款；额度按存单金额1:10放大，不是财政直补。"},{"sectionNo":"六","headline":"贷款形成不良，风补资金代偿本金损失的30%","who":"合作银行；其发放的贷款形成不良贷款时，风补资金按贷款本金损失的30%给予风险补偿，对应贷款须已纳入代偿范围。","materials":[],"window":"原文未设申报期限","where":"县政府办","tip":"代偿基数为贷款本金损失，比例为30%，不是全额代偿，也不含利息损失。"},{"sectionNo":"八","headline":"企业向县政府办申请，经推荐后由合作银行审批放贷","who":"符合本办法规定条件、有融资需求的企业；由县政府办按企业自主意愿书面推荐给合作银行，银行独立审批。","materials":["贷款合同复印件"],"window":"合作银行发放贷款后3个工作日内将贷款合同复印件报县政府办备案","where":"县政府办","tip":"银行按自身业务准则独立审批，推荐不等于获批；未审核纳入代偿范围的贷款不享受风险补偿。"},{"sectionNo":"九","headline":"本金逾期30天或欠息3期，合作银行可申请代偿","who":"合作银行；其发放的企业贷款本金逾期超过30个自然日，或本金未逾期但利息连续逾期3期及以上。","materials":["代偿申请书","不良贷款证明资料复印件","贷后管理及催收情况说明及相关资料复印件","向法院提起诉讼或向仲裁机构申请仲裁等积极追偿的相关资料"],"window":"县政府办自收到申请之日起10个工作日内完成审查后报县人民政府审批；县人民政府完成审核后10个工作日内拨付代偿资金","where":"县政府办、县人民政府","tip":"审查包括银行对重大风险事项有无应知未知、贷前尽职调查及贷后管理情况；须先积极追偿。"},{"sectionNo":"十四","headline":"单户贷款上限1000万元、期限3年、利率LPR+100BP","who":"申请纳入代偿范围的合作银行贷款企业：单户额度不超过1000万元、单笔期限不超过3年、年化利率不超过当期LPR+100BP。","materials":[],"window":"单笔贷款期限不超过3年","where":"县政府办","tip":"贷款不得用于转贷、民间借贷、投资资本市场，也不得归还同一机构或关联方原有贷款；四项条件须同时符合。"},{"sectionNo":"十五","headline":"经营未满1年、资产负债率超65%等情形不纳入代偿","who":"拟申请攸惠贷贷款的企业；存在经营未满一年、资产负债率超65%、近两年连续亏损、涉民间借贷重大不利影响、恶意逃废债、虚假交易骗贷、重大涉经济犯罪、已享受县内其他信贷风险补偿政策等情形之一的不纳入代偿。","materials":[],"window":"原文未设申报期限","where":"县政府办","tip":"所列情形任一存在即不纳入代偿；已享受县内其他信贷风险补偿政策的同样排除。"},{"sectionNo":"十七","headline":"代偿不免债，企业仍须按合同承担全部还款责任","who":"获得代偿或贷款被核销的贷款企业及其相关当事人。","materials":[],"window":"原文未设期限；代偿、核销后借贷关系不变","where":"合作银行","tip":"代偿、核销只处理银行与风补资金的关系，不改变银行与企业的借贷关系；银行不得擅自放弃追偿。"},{"sectionNo":"十九","headline":"代偿笔数占比超5%或代偿额超存单总额，银行须停发新贷款","who":"合作银行；其代偿贷款笔数占存量笔数比例超过5%，或代偿总金额超过定期存单总额时，立即暂停发放新贷款。","materials":[],"window":"暂停至追偿见效、整改完成并报县政府办批准后恢复","where":"县政府办","tip":"暂停期间须推进债务追偿并彻底自查整改；未经县政府办批准不得恢复业务。"}],"sourceUrl":"http://www.hnyx.gov.cn/c24643/20260128/i2473246.html","derivedFrom":"official","sourceNote":"2026-11-24 取自攸县人民政府门户（正确域名 hnyx.gov.cn）「政务公开>政府信息公开目录>政策文件>规范性文件」栏目原文页；正文为页面内嵌 HTML 全文（非附件），按原文“第一条”至“第二十一条”逐条转录，条号一至二十一与原文一一对应，未删并；原文“第一章 总则”至“第七章 附则”的章标题置于该章首条的 title 字段。版头统一登记号 ZZYXDR-2025-01002，发文字号攸政办发〔2025〕4号，成文日期2025年12月31日。 2026-11-24 收录：与官方页面逐句比对，命中 50/50 句（100%），关卡判定「verbatim」。 有效期依据：第二十一条","verified":false,"isSample":false,"numberStyle":"clause","bodyVerified":"verbatim","hunan":true},{"id":"yy-agri-leader-2026","title":"岳阳市农业农村局关于印发《岳阳市农业产业化市级龙头企业认定和运行监测管理办法》的通知","level":"city","region":"岳阳市","issuer":"岳阳市农业农村局","documentNo":"岳农发〔2026〕7号","publishedAt":"2026-11-02","effectiveAt":"2026-11-03","expiresAt":"2031-11-03","status":"active","tags":["认定资质","财政奖补"],"audience":["农产品生产加工流通企业","农业社会化服务企业","休闲农业企业","农产品电商企业"],"summary":"每两年开展一次市级龙头企业认定与监测，明确企业规模、质量管理、效益、负债信用、带动能力等申报条件；经发文认定的市级龙头企业按规定享受涉农优惠政策，办法有效期5年。","sections":[{"no":"五","title":"认定组织与周期","text":"市级龙头企业评审认定和运行监测工作由市农业农村局负责组织，每两年开展一次认定及监测工作。"},{"no":"六（三）1","title":"农产品生产、加工、流通企业规模","text":"农产品生产、加工、流通企业规模。总资产规模2000万元以上、固定资产规模1000万元以上、年销售收入2000万元以上。"},{"no":"六（七）","title":"企业带动能力","text":"企业通过合同、合作和股份合作等方式，与合作社、家庭农场等新型经营主体建立紧密、可靠、稳定的利益联结机制。原则上，粮油等大宗农产品生产加工流通企业，带动农户数量1000户以上；畜牧、水产及其他农产品生产加工流通企业，带动农户数量200户以上；电商企业带动农户数量500户以上。"},{"no":"十六","title":"享受政策","text":"经发文认定的市级龙头企业，按有关规定享受涉农优惠政策。"},{"no":"二十一","title":"监测结果运用","text":"监测合格的企业，继续保留市级龙头企业资格，享受有关优惠政策；监测不合格的企业，取消其市级龙头企业资格，不再享受有关优惠政策。市农业农村局以适当形式向社会公布监测结果。"}],"interpretations":[{"sectionNo":"五","headline":"市级龙头企业认定和监测每两年开展一次","who":"申报岳阳市农业产业化市级龙头企业的经营主体；评审认定和运行监测工作均由市农业农村局负责组织。","materials":[],"window":"每两年开展一次认定及监测工作。","where":"市农业农村局","tip":"认定与运行监测同一周期组织，非随时申报，错过当期需等下一个两年周期。"},{"sectionNo":"六（三）1","headline":"市级龙头门槛：总资产2000万、销售收入2000万以上","who":"农产品生产、加工、流通企业：总资产规模2000万元以上、固定资产规模1000万元以上、年销售收入2000万元以上。","materials":[],"window":"按每两年一次的认定周期申报，认定时核查总资产、固定资产与年销售收入规模。","where":"市农业农村局（市级龙头企业认定）","tip":"三项规模指标须同时达到：总资产2000万元以上、固定资产1000万元以上、年销售收入2000万元以上。"},{"sectionNo":"六（七）","headline":"粮油类带动农户1000户以上，畜牧水产200户、电商500户","who":"与合作社、家庭农场等新型经营主体建立紧密、可靠、稳定利益联结机制的企业：粮油等大宗农产品生产加工流通企业带动农户1000户以上，畜牧、水产及其他农产品企业200户以上，电商企业500户以上。","materials":[],"window":"认定及监测时核查带动农户数量，按每两年一次的认定周期执行。","where":"市农业农村局（认定与运行监测）","tip":"带动农户数为原则上要求，按企业类型分别适用1000户、200户、500户三档。"},{"sectionNo":"十六","headline":"经发文认定的市级龙头企业可享受涉农优惠政策","who":"经市农业农村局发文认定的岳阳市农业产业化市级龙头企业。","materials":[],"window":"自认定发文之日起享受，监测不合格时停止享受。","where":"市农业农村局（发文认定）","tip":"须经发文认定才享受；未认定或监测不合格的企业不享受涉农优惠政策。"},{"sectionNo":"二十一","headline":"监测不合格取消市级龙头资格，不再享受优惠政策","who":"已认定的市级龙头企业；监测合格保留资格并继续享受有关优惠政策，不合格取消资格。","materials":[],"window":"按每两年一次的监测安排接受监测，结果由市农业农村局向社会公布。","where":"市农业农村局","tip":"监测不合格即取消资格、停止享受优惠，不是到期自然失效。"}],"sourceUrl":"https://yueyang.gov.cn/gfxwj/20052/content_2420151.html","sourceNote":"2026-11-22 取自岳阳市人民政府门户「文件库—市直部门规范性文件」原文页，版头载文号岳农发〔2026〕7号、统一登记号 YYCR-2026-16001，页面载生效日期2026-11-03、信息时效期2031-11-03。 2026-11-22 收录：与官方页面逐句比对，命中 11/11 句（100%），关卡判定「verbatim」。 有效期依据：第二十七条明示“有效期5年”；页面信息时效期栏载2031-11-03","verified":false,"isSample":false,"numberStyle":"clause","bodyVerified":"verbatim","hunan":true},{"id":"yy-commerce-fund-2026","title":"岳阳市商务局 岳阳市财政局关于印发《岳阳市现代商贸流通体系试点城市建设专项资金管理办法》和《岳阳市现代商贸流通体系试点城市建设项目管理办法》的通知","level":"city","region":"岳阳市","issuer":"岳阳市商务局、岳阳市财政局","documentNo":"岳商流通〔2026〕2号","publishedAt":"2026-09-20","effectiveAt":"2026-09-21","expiresAt":"2028-12-31","status":"active","tags":["专项资金","财政奖补"],"audience":["商贸流通企业","农产品批发市场","冷链物流企业","再生资源回收企业"],"summary":"中央财政专项资金支持城乡商贸流通融合、生活必需品保供、农村商贸流通、现代流通骨干企业、再生资源回收五大方向；按投资额分档补助30%至50%，单个项目最高1500万元，阶段性拨付门槛为有效投资额200万元以上，有效期至2028年12月31日。","sections":[{"no":"九（一）","title":"阶段性拨付","text":"对有效投资额达到200万元以上且有效投资比例超过30%的项目，可以申请阶段性验收，1个项目原则上只能申请不超过2次阶段性验收。阶段性验收程序按照项目验收程序执行。"},{"no":"十一（二）","title":"公益类民生保障项目支持标准","text":"对公益类的民生保障项目，如农产品批发市场、农贸市场（集贸市场、便民市场、农贸市场）、社区便利店、社区粮油店等新建改造项目，专项资金支持金额不超过有效投资额的50%，单个项目支持金额不超过1500万元。"},{"no":"十一（三）","title":"再生资源与农村商贸支持标准","text":"对符合完善城乡再生资源回收体系方向、完善农村商贸流通体系、建设生活必需品流通保供体系方向的项目（除本条第（一）项支持项目外），专项资金支持金额不超过有效投资额的40%，单个项目支持金额不超过1500万元。"},{"no":"十一（四）","title":"骨干企业培育支持标准","text":"对符合推动城乡商贸流通融合发展（除本条第（二）项支持项目外）、加快培育现代流通骨干企业等方向的项目，专项资金支持金额不超过有效投资额的30%，单个项目支持金额不超过1500万元。"},{"no":"项目办法五（三）","title":"《项目管理办法》第五条（三）申报主体条件","text":"管理规范、真实经营且财务会计制度健全，自申报之日起向前追溯，近5年来无严重违规违法行为，未拖欠应缴还的财政性资金，能够及时报送相关资料。"}],"interpretations":[{"sectionNo":"九（一）","headline":"投资额200万元以上且投资比例超30%，可申请阶段性验收","who":"岳阳市现代商贸流通体系试点城市建设项目单位，项目有效投资额达到200万元以上且有效投资比例超过30%。","materials":[],"window":"项目建设期内可申请阶段性验收，1个项目原则上不超过2次。","where":"按项目验收程序执行（原文未点名具体受理部门）","tip":"两项门槛须同时满足（投资额200万元以上、有效投资比例超过30%）；阶段性验收原则上最多2次。"},{"sectionNo":"十一（二）","headline":"公益类民生保障项目，最高补有效投资额50%、1500万元","who":"公益类民生保障项目单位，项目为农产品批发市场、农贸市场（集贸市场、便民市场、农贸市场）、社区便利店、社区粮油店等新建改造项目。","materials":[],"window":"按专项资金申报安排执行；原文未明确申报截止时间。","where":"岳阳市现代商贸流通体系试点城市建设专项资金（原文未点名具体受理部门）","tip":"支持比例不超过有效投资额50%，单项目封顶1500万元，两个上限同时适用。"},{"sectionNo":"十一（三）","headline":"再生资源回收、农村商贸等项目，最高补40%、1500万元","who":"符合完善城乡再生资源回收体系、完善农村商贸流通体系、建设生活必需品流通保供体系方向的项目单位；不含本条第（一）项支持项目。","materials":[],"window":"按专项资金申报安排执行；原文未明确申报截止时间。","where":"岳阳市现代商贸流通体系试点城市建设专项资金（原文未点名具体受理部门）","tip":"支持比例40%，单项目封顶1500万元；已列入本条第（一）项支持范围的项目不再按本条支持。"},{"sectionNo":"十一（四）","headline":"城乡商贸融合、骨干企业项目，最高补30%、1500万元","who":"符合推动城乡商贸流通融合发展（不含本条第（二）项支持项目）、加快培育现代流通骨干企业等方向的项目单位。","materials":[],"window":"按专项资金申报安排执行；原文未明确申报截止时间。","where":"岳阳市现代商贸流通体系试点城市建设专项资金（原文未点名具体受理部门）","tip":"支持比例30%，单项目封顶1500万元；已列入本条第（二）项支持范围的项目不重复适用本条。"},{"sectionNo":"项目办法五（三）","headline":"申报主体近5年无严重违规违法、未拖欠财政资金","who":"申报岳阳市现代商贸流通体系试点城市项目的主体，须管理规范、真实经营、财务会计制度健全，自申报之日起向前追溯近5年无严重违规违法行为、未拖欠应缴还的财政性资金，并能及时报送相关资料。","materials":[],"window":"自申报之日起向前追溯近5年。","where":"岳阳市现代商贸流通体系试点城市项目申报（原文未点名具体受理部门）","tip":"近5年从申报之日向前追溯计算；拖欠应缴还财政性资金的一律不符合条件。"}],"sourceUrl":"https://yueyang.gov.cn/gfxwj/20052/content_2412604.html","sourceNote":"2026-11-22 取自岳阳市人民政府门户「文件库—市直部门规范性文件」原文页，版头载文号岳商流通〔2026〕2号、统一登记号 YYCR-2026-17001，页面载生效日期2026-09-21、信息时效期2028-12-31。publishedAt 取页面“来源”标注的2026-09-20（文件落款2026年9月20日），effectiveAt 取页面“生效日期”2026-09-21。注意：本页同刊两个办法——《岳阳市现代商贸流通体系试点城市建设专项资金管理办法》与《岳阳市现代商贸流通体系试点城市建设项目管理办法》。本记录中带“项目办法”前缀的条款出自后者，其余条款出自前者，两者条号各自起算、互不连续。 2026-11-22 收录：与官方页面逐句比对，命中 6/6 句（100%），关卡判定「verbatim」。 有效期依据：第二十条明示“有效期至2028年12月31日”；页面信息时效期栏一致","verified":false,"isSample":false,"numberStyle":"clause","bodyVerified":"verbatim","hunan":true},{"id":"yy-hr-2026","title":"岳阳市人民政府办公室关于印发《岳阳市人力资源服务业与制造业融合发展实施方案（2026—2027年）》的通知","level":"city","region":"岳阳市","issuer":"岳阳市人民政府办公室","documentNo":"岳政办发〔2026〕6号","publishedAt":"2026-06-16","effectiveAt":null,"expiresAt":null,"status":"active","tags":["就业补贴","人才政策","财政奖补"],"audience":["岳阳市制造业企业","人力资源服务机构","“两业”融合园运营方"],"summary":"到2027年底建成2个以上“两业”融合园、入驻机构总数达50家，每年精准服务重点制造业企业不少于300家次。","sections":[{"no":"一","title":"目标任务","text":"到2027年底，力争建成2个以上人力资源服务业与制造业融合园（以下简称“两业”融合园），园区入驻人力资源服务机构总数达50家；引进2—3家全国性头部人力资源服务机构，培育3—5家具有区域影响力的本土品牌，全市人力资源服务业机构总数和营收年均增长5%以上；每年精准服务重点制造业企业不少于300家次，解决重要技术岗位需求不少于1000个。"},{"no":"二(一)1","title":"建设重点产业园区","text":"实施湖南省（岳阳）人力资源服务产业园扩容提质专项行动，优化空间布局，完善服务功能，集聚高端要素，积极争创人社部重点联系产业园。在园内设立制造业招聘服务专区，提供招聘信息发布、直播带岗、专场招聘等服务。"},{"no":"二(一)1续","title":"“两业”融合园布局","text":"围绕“1+3+X”现代化产业体系，依托现有产业园区布局建设2个以上定位清晰、特色鲜明的“两业”融合园，在临港高新区建设1个综合服务平台。聚焦制造业企业一线需求，将用工保障、技能提升、人才引进等专业化服务送到产业一线。"},{"no":"依据","title":"制定依据","text":"根据人力资源社会保障部等5部委《关于加强人力资源服务助力制造业高质量发展的意见》（人社部发〔2024〕86号）、人力资源社会保障部办公厅《关于做好人力资源服务业与制造业融合发展试点有关工作的通知》（人社厅函〔2025〕170号）精神，结合我市实际，制定本方案。"}],"interpretations":[],"sourceUrl":"https://yueyang.gov.cn/gfxwj/szfwj/content_2384878.html","sourceNote":"2026-11-21 取自岳阳市政府门户「规范性文件—市政府文件」原文页；标题与成文日期已核对，页面未标注文号。 2026-11-21 收录：与官方页面逐句比对，命中 8/8 句（100%），关卡判定「verbatim」。 有效期依据：原文未设期限；方案期止于2027年底 2026-11-21 补录：documentNo 据官方页面版头/落款核对后填入。","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"yy-ip-fund-2026","title":"岳阳市市场监督管理局 岳阳市财政局关于印发《岳阳市知识产权强市战略专项资金管理办法》的通知","level":"city","region":"岳阳市","issuer":"岳阳市市场监督管理局、岳阳市财政局","documentNo":"岳市监发〔2026〕4号","publishedAt":"2026-10-28","effectiveAt":"2026-10-28","expiresAt":"2029-10-28","status":"active","tags":["财政奖补","研发创新","融资支持"],"audience":["企事业单位","知识产权服务机构","法律服务机构","社会组织"],"summary":"市财政预算安排知识产权专项资金，按因素法与项目法分配，覆盖高价值发明专利培育、重点商标品牌培育、质押融资激励、维权援助、公共服务平台建设等12类激励项目，质押融资按贷款额度分档激励0.5万至4万元，有效期3年。","sections":[{"no":"四","title":"支持对象","text":"岳阳市范围内的企事业单位、知识产权服务机构、法律服务机构、社会组织及个人等，可作为专项资金的申报主体。"},{"no":"五","title":"支持范围（一）知识产权创造、（二）知识产权保护","text":"（一）知识产权创造。高价值发明专利培育、海外专利布局、专利质量提升、重点商标品牌培育等。（二）知识产权保护。专利侵权纠纷行政裁决、知识产权纠纷调解、知识产权维权资金援助、海外知识产权风险防控和纠纷应对等。"},{"no":"五（续）","title":"支持范围（三）—（六）","text":"（三）知识产权运用。专利权商标权质押融资、专利许可转让、专利盘点盘活、专利导航、专利密集型产品认定、地理标志推广运用、知识产权强链护链培育等。（四）知识产权管理。知识产权政策法规宣传培训、监督检查等。（五）知识产权服务。公共服务平台建设、优质服务机构、信息平台建设等。（六）市委市政府、省市场监管局交办的需要支持的知识产权重要事项。"},{"no":"七","title":"避免重复激励","text":"对知识产权事项已获得国家知识产权局、省知识产权局激励的，市本级本年度内原则上不再给予激励。"},{"no":"附件","title":"知识产权质押融资激励标准","text":"对以专利权、商标权、地理标志为质押物，成功获得银行金融机构知识产权质押贷款的企业，按照以下标准给予激励：贷款额度在100万元-500万元的（含500万元），激励0.5万元；贷款额度在500万元（不含500万元）-1000万元的（含1000万元），激励1万元；贷款额度在1000万元（不含1000万元）-2000万元的（含2000万元），激励2万元。"}],"interpretations":[{"sectionNo":"四","headline":"岳阳企事业单位、服务机构、社会组织及个人均可申报专项资金","who":"岳阳市范围内的企事业单位、知识产权服务机构、法律服务机构、社会组织及个人等。","materials":[],"window":"原文未写明申报期。","where":"原文未写明受理部门。","tip":"申报主体须属岳阳市范围，个人也可作为申报主体。"},{"sectionNo":"五","headline":"高价值发明专利培育、海外专利布局等可获支持","who":"岳阳市范围内符合支持范围的申报主体；本条覆盖知识产权创造（高价值发明专利培育、海外专利布局、专利质量提升、重点商标品牌培育）与知识产权保护（专利侵权纠纷行政裁决、纠纷调解、维权资金援助、海外风险防控和纠纷应对）。","materials":[],"window":"原文未写明申报期。","where":"原文未写明受理部门。","tip":"支持事项须落在本条列举的创造、保护两类范围内；海外风险防控与纠纷应对单列。"},{"sectionNo":"五（续）","headline":"专利质押融资、许可转让、专利导航等运用事项可获支持","who":"岳阳市范围内符合支持范围的申报主体；涵盖知识产权运用（专利权商标权质押融资、专利许可转让、专利盘点盘活、专利导航、专利密集型产品认定、地理标志推广运用、知识产权强链护链培育）、管理（政策法规宣传培训、监督检查）、服务（公共服务平台建设、优质服务机构、信息平台建设）及市委市政府、省市场监管局交办的重要事项。","materials":[],"window":"原文未写明申报期。","where":"原文未写明受理部门。","tip":"第（六）项为市委市政府、省市场监管局交办的需要支持的知识产权重要事项，非常设申报口径。"},{"sectionNo":"七","headline":"已获国家或省知识产权激励的，市本级本年度不再激励","who":"知识产权事项已获得国家知识产权局、省知识产权局激励的申报主体。","materials":[],"window":"市本级本年度内原则上不再给予激励。","where":"岳阳市本级。","tip":"同一事项已获上级激励的，本年度原则上不再报市级激励，避免重复。"},{"sectionNo":"附件","headline":"知识产权质押贷款按额度分档激励，最高2万元","who":"以专利权、商标权、地理标志为质押物，成功获得银行金融机构知识产权质押贷款的企业；贷款额度100万元至2000万元分三档。","materials":[],"window":"贷款额度在100万元-500万元的（含500万元），激励0.5万元。","where":"原文未写明受理部门，由银行金融机构放款后按贷款额度认定。","tip":"500万元（不含）-1000万元（含）激励1万元；1000万元（不含）-2000万元（含）激励2万元；100万元-500万元（含）激励0.5万元。"}],"sourceUrl":"https://yueyang.gov.cn/gfxwj/20052/content_2419355.html","sourceNote":"2026-11-22 取自岳阳市人民政府门户「政务公开—文件库—规范性文件—市直部门规范性文件」原文页，版头载文号岳市监发〔2026〕4号、统一登记号 YYCR-2026-24002，页面载生效日期2026-10-28、信息时效期2029-10-28。 2026-11-22 收录：与官方页面逐句比对，命中 11/11 句（100%），关卡判定「verbatim」。 有效期依据：第十五条明示“有效期3年”；页面信息时效期栏载2029-10-28","verified":false,"isSample":false,"numberStyle":"clause","bodyVerified":"verbatim","hunan":true},{"id":"yy-mfg-2024-10","title":"益阳市人民政府关于印发《益阳市推进先进制造业高质量发展若干政策（试行）》的通知","level":"city","region":"益阳市","issuer":"益阳市人民政府","documentNo":"益政发〔2024〕10号","publishedAt":"2024-11-19","effectiveAt":null,"expiresAt":null,"status":"active","tags":["财政奖补","认定资质","研发创新"],"audience":["益阳市工业企业","专精特新“小巨人”企业","制造业单项冠军企业","高新技术企业"],"summary":"新入规工业企业奖8万元；国家级专精特新“小巨人”奖30万元、省级专精特新中小企业奖10万元；国家级单项冠军奖100万元。","sections":[{"no":"一1","title":"新入规奖励","text":"对新入规的工业企业，给予8万元一次性奖励。"},{"no":"一2","title":"专精特新奖励","text":"对被工业和信息化部新认定为国家级专精特新“小巨人”企业、省工业和信息化厅新认定为专精特新中小企业的工业企业，分别给予30万元、10万元一次性奖励。对通过国家级、省级复审的工业企业，分别给予5万元、1万元一次性奖励。"},{"no":"一3","title":"单项冠军奖励","text":"对被工业和信息化部新认定为国家级制造业单项冠军企业、省工业和信息化厅新认定为制造业单项冠军企业（产品）的工业企业，分别给予100万元、10万元一次性奖励。"},{"no":"一4","title":"固定资产投资与设备补助","text":"对全市十大产业链中完成工业固定资产投资50亿元以上、10亿元以上、5亿元以上、1亿元以上的工业企业，分别给予500万元、100万元、50万元、5万元一次性奖励。对纳入工业和信息化部技术改造和设备更新项目清单，当年新增设备投资500万元以上的工业企业，按新增设备购置投资的1%给予一次性补助，最高补助不超过100万元。"},{"no":"一4续","title":"兼并重组奖励","text":"对通过转让、收购等方式兼并重组益阳市域内工业企业，且实际出资额超过3000万元的企业，按实际出资额的1%给予一次性奖励，最高不超过100万元。"},{"no":"二5","title":"新材料与“三品”标杆","text":"对被省工业和信息化厅新认定为省级新材料企业、原材料工业“三品”标杆企业、消费品工业“三品”标杆企业的工业企业，分别给予5万元一次性奖励。"},{"no":"二6","title":"高新技术企业奖励","text":"对被科技部新认定为国家级高新技术企业的，给予10万元一次性奖励。对通过国家高新技术企业复审的企业，给予3万元一次性奖励。"}],"interpretations":[{"sectionNo":"一1","headline":"新入规工业企业给8万元一次性奖励","who":"益阳市新入规的工业企业；原文以“新入规”为唯一门槛，未再限定细分行业、规模或申报人身份。","materials":[],"window":"一次性奖励；原文未设申报期限、执行年度或频次。","where":"益阳市（原文未列具体受理部门或申报系统）","tip":"奖励为一次性，8万元对应“新入规”这一事项，企业入规后可对照申报。"},{"sectionNo":"一2","headline":"国家级专精特新“小巨人”奖30万，省级专精特新奖10万","who":"被工业和信息化部新认定为国家级专精特新“小巨人”企业，或被省工业和信息化厅新认定为专精特新中小企业的工业企业；通过复审的工业企业另按国家级5万元、省级1万元奖励。","materials":[],"window":"一次性奖励；新认定与复审分别计奖，原文未设申报期限。","where":"益阳市（认定由工业和信息化部、省工业和信息化厅作出，原文未列申报窗口）","tip":"只有“新认定”才按30万元、10万元奖励；复审通过按5万元、1万元另计，不按新认定标准执行。"},{"sectionNo":"一3","headline":"国家级单项冠军奖100万，省级奖10万","who":"被工业和信息化部新认定为国家级制造业单项冠军企业，或被省工业和信息化厅新认定为制造业单项冠军企业（产品）的工业企业。","materials":[],"window":"一次性奖励；原文未设申报期限或年度名额。","where":"益阳市（认定由工业和信息化部、省工业和信息化厅作出，原文未列申报窗口）","tip":"省级奖励覆盖“企业（产品）”两类认定，国家级仅指企业；两级按认定层级分别对应100万元、10万元。"},{"sectionNo":"一4","headline":"十大产业链固投达标最高奖500万，设备投资再补1%","who":"全市十大产业链中完成工业固定资产投资50亿元以上、10亿元以上、5亿元以上、1亿元以上的工业企业；或纳入工业和信息化部技术改造和设备更新项目清单、当年新增设备投资500万元以上的工业企业。","materials":[],"window":"一次性奖励或补助；固定资产投资与新增设备投资均按“当年”口径，原文未设申报截止日。","where":"益阳市（原文未列具体受理部门或申报系统）","tip":"固投奖励按50亿元、10亿元、5亿元、1亿元四档对应500万元、100万元、50万元、5万元；设备补助按新增设备购置投资的1%计算，最高不超过100万元。"},{"sectionNo":"一4续","headline":"兼并重组市域内工业企业，按出资额1%奖，最高100万","who":"通过转让、收购等方式兼并重组益阳市域内工业企业，且实际出资额超过3000万元的企业（兼并方）。","materials":[],"window":"一次性奖励；原文未设申报期限。","where":"益阳市（原文未列具体受理部门或申报系统）","tip":"奖励基数是实际出资额而非交易总额，按1%计算且封顶100万元；门槛为实际出资额超过3000万元。"},{"sectionNo":"二5","headline":"省级新材料、“三品”标杆企业各奖5万元","who":"被省工业和信息化厅新认定为省级新材料企业、原材料工业“三品”标杆企业或消费品工业“三品”标杆企业的工业企业。","materials":[],"window":"一次性奖励；原文未设申报期限。","where":"益阳市（认定由省工业和信息化厅作出，原文未列申报窗口）","tip":"三类认定各按5万元一次性奖励，均要求“新认定”，由省级认定后对应兑现。"},{"sectionNo":"二6","headline":"国家高新技术企业奖10万，复审通过再奖3万","who":"被科技部新认定为国家级高新技术企业的企业；通过国家高新技术企业复审的企业另按3万元奖励。","materials":[],"window":"一次性奖励；新认定与复审分别计奖，原文未设申报期限。","where":"益阳市（认定由科技部作出，原文未列申报窗口）","tip":"新认定10万元、复审3万元，两次奖励标准不同，复审不按新认定标准执行。"}],"sourceUrl":"http://yiyang.gov.cn/yiyang/2/98/41460/41484/41514/content_2037474.html","sourceNote":"2026-11-21 取自益阳市政府门户原文页；文号、成文日期与规范性文件登记号 YYCR-2024-00006 均已核对。奖励标准与市政府公报第5期所载口径一致。 2026-11-21 收录：与官方页面逐句比对，命中 10/10 句（100%），关卡判定「verbatim」。 有效期依据：原文未设期限；按行政规范性文件一般不超5年推算至2029-11","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"yy-performance-2026","title":"岳阳市人民政府办公室关于印发《岳阳市支持演艺市场高质量发展的若干措施》的通知","level":"city","region":"岳阳市","issuer":"岳阳市人民政府办公室","documentNo":"岳政办发〔2026〕4号","publishedAt":"2026-05-06","effectiveAt":"2026-05-06","expiresAt":"2028-12-31","status":"active","tags":["财政奖补","专项资金","场地支持"],"audience":["演艺经营主体","演艺场馆投资主体","剧目出品方","演艺新空间运营方"],"summary":"对大型营业性演出每场最高给予经营主体100万元资金支持，引进精品剧目每个最高30万元，演艺场馆新建改建每个最高20万元，市级演艺新空间一次性5万元，接收应届高校毕业生最高3万元；有效期至2028年12月31日。","sections":[{"no":"二","title":"支持举办大型营业性演出活动","text":"鼓励在岳举办演唱会等大型营业性演出活动，通过推出惠民票价等增加演艺消费人数，根据演出规模、带动旅游和促进消费等效果，每场给予经营主体最高100万元资金支持。同一经营主体同一年度内，在岳举办2场（含）以上大型营业性演出活动且效果良好的，适当增加支持金额。"},{"no":"三","title":"支持引进精品剧目在岳演出","text":"鼓励引进国内外高品质剧目多演常演，以及利用现有场馆或品牌活动举办营业性演出活动，根据演出规模、场次、效果等，每个给予组织方最高30万元资金支持。"},{"no":"四","title":"支持演艺新空间创新融合发展","text":"鼓励新建演艺场馆以及利用闲置工业厂房、空闲楼宇、商业综合体和体育馆等资源，在符合演艺场所建筑相关技术标准的前提下改建演艺场馆，根据投资规模和运营成效，每个给予投资主体最高20万元资金支持。对艺术水平较高、在全国全省具有较大影响并运营良好的在岳精品演艺项目，每个给予经营主体最高30万元资金支持。在演艺新空间驻场演出多场的原创剧目，根据演出规模、场次、效果等，每个一次性给予出品方最高20万元支持。按程序认定为市级演艺新空间的，一次性给予运营方5万元资金支持。"},{"no":"六","title":"支持演艺人才引进培育","text":"在岳演艺新空间接收应届高校毕业生的，根据接收人数和在岗稳定工作时长，一次性给予经营主体最高3万元资金支持。"},{"no":"八","title":"加强专项资金管理","text":"市财政局、市文旅广电局统筹整合国家、省、市相关资金，市文旅广电局根据年度工作重点，合理确定年度项目支持方案。具体申报、审核、资金拨付和绩效评价等，由市文旅广电局会同市财政局另行明确。"}],"interpretations":[{"sectionNo":"二","headline":"在岳办大型营业性演出，每场最高支持100万元","who":"在岳阳举办演唱会等大型营业性演出活动的经营主体；须通过推出惠民票价等方式增加演艺消费人数。","materials":[],"window":"按场次给予支持；同一经营主体同一年度内在岳举办2场（含）以上且效果良好的，适当增加支持金额","where":"市文旅广电局、市财政局（具体申报、审核、拨付另行明确）","tip":"支持金额按演出规模、带动旅游和促进消费等效果确定；2场以上才适当增加。"},{"sectionNo":"三","headline":"引进精品剧目在岳演出，每个最高支持30万元","who":"引进国内外高品质剧目多演常演的组织方，以及利用现有场馆或品牌活动举办营业性演出活动的组织方。","materials":[],"window":"按项目申报（原文未列具体申报期）","where":"市文旅广电局、市财政局（具体申报、审核、拨付另行明确）","tip":"支持金额按演出规模、场次、效果等确定，每个最高30万元。"},{"sectionNo":"四","headline":"新建改建演艺场馆最高20万元，市级新空间一次性5万元","who":"新建演艺场馆或利用闲置工业厂房、空闲楼宇、商业综合体、体育馆改建演艺场馆的投资主体；艺术水平较高、全国全省有较大影响并运营良好的精品演艺项目经营主体；驻场演出多场原创剧目的出品方；认定为市级演艺新空间的运营方。","materials":[],"window":"按项目申报；市级演艺新空间认定后一次性给予","where":"市文旅广电局、市财政局（具体申报、审核、拨付另行明确）","tip":"改建须符合演艺场所建筑相关技术标准；四类支持分别为20万元、30万元、20万元、5万元。"},{"sectionNo":"六","headline":"演艺新空间接收应届高校毕业生，一次性最高3万元","who":"在岳演艺新空间；接收应届高校毕业生，按接收人数和在岗稳定工作时长给予经营主体支持。","materials":[],"window":"一次性给予（原文未列具体申报期）","where":"市文旅广电局、市财政局（具体申报、审核、拨付另行明确）","tip":"支持金额按接收人数和在岗稳定工作时长确定，最高3万元。"}],"sourceUrl":"https://yueyang.gov.cn/gfxwj/szfwj/content_2376580.html","sourceNote":"2026-11-22 取自岳阳市人民政府门户「政务公开—文件库—规范性文件—市政府规范性文件」原文页，版头载文号岳政办发〔2026〕4号、统一登记号 YYCR—2026—01003，页面载生效日期2026-05-06、信息时效期2028-12-31。 2026-11-22 收录：与官方页面逐句比对，命中 10/10 句（100%），关卡判定「verbatim」。 有效期依据：正文末条明示“有效期至2028年12月31日”；页面信息时效期栏一致","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"yy-scale-2022-4","title":"关于印发《岳阳市深入开展新增规模以上工业企业行动方案》的通知","level":"city","region":"岳阳市","issuer":"岳阳市人民政府办公室","documentNo":"岳政办发〔2022〕4号","publishedAt":"","effectiveAt":"2022-02-22","expiresAt":"2027-02-21","status":"expiring","tags":["认定资质","财政奖补"],"audience":["岳阳市规模以下工业企业","“个转企”“小升规”主体"],"summary":"力争“十四五”期间全市每年净增规模以上工业企业110家以上，到2025年规上工业企业总数超过2200家。","sections":[{"no":"一","title":"总体目标","text":"坚持政府引导、市场主导，分级负责、协同推进，力争“十四五”期间，全市每年净增规模以上工业企业110家以上，到2025年，全市规模以上工业企业总数超过2200家。"},{"no":"二(一)","title":"“梯度”培育","text":"扎实推动“个转企”“小升规”，对符合小型企业划型标准下限和税务部门核定为一般纳税人的个体工商户实施转企。加快领军企业扩能倍增步伐，充分发挥领航企业引领作用，带动大中小企业融通发展，促进小微企业成长升规、做专做精。"},{"no":"二(三)","title":"专精特新培育","text":"以实施产业发展“万千百”工程为契机，引导“入规”企业走专精特新发展道路，实行专精特新“小巨人”企业梯队培育，稳定存量企业。“十四五”期间，挑选培育一批国家、省级专精特新“小巨人”后备企业，每年新增省级专精特新“小巨人”企业25家以上，其中国家级专精特新“小巨人”企业5家。"},{"no":"二(二)","title":"链上项目服务","text":"把引进规模以上工业企业作为招商引资工作重点，通过重大经贸活动、品牌会展活动等，引进一批“三类500强”企业。围绕“12+1”产业集群补链延链强链要求，加大产业链项目建设推进力度，支持企业加快技术改造升级。"}],"interpretations":[],"sourceUrl":"https://jxw.yueyang.gov.cn/7249/20302/content_2014273.html","sourceNote":"2026-11-21 取自岳阳市工信局原文页；规范性文件登记号 YYCR—2022—01004 与有效期起止日已核对，是本市少见明确写出有效期的一类样本。 2026-11-21 收录：与官方页面逐句比对，命中 7/7 句（100%），关卡判定「verbatim」。 有效期依据：原文明示（规范性文件登记号后标注有效期起止日）","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"yz-bamboo-2024","title":"永州市人民政府办公室关于印发《永州市加快竹产业高质量发展的若干措施》的通知","level":"city","region":"永州市","issuer":"永州市人民政府办公室","documentNo":"永政办发〔2024〕11号","publishedAt":"2024-08-05","effectiveAt":"2024-08-05","expiresAt":"2029-08-05","status":"active","tags":["财政奖补","贷款贴息","认定资质"],"audience":["竹产业龙头企业","竹林经营主体","竹产品加工企业","林业专业合作社"],"summary":"围绕竹林基地、产业升级、龙头企业等提出措施：竹林道按3万至5万元/公里补助，每年支持建设50公里以上；对龙头企业竹产业延链补链强链项目贷款予以贴息；对省级以上林下经济示范基地和龙头企业在项目立项、产业扶持资金上重点支持，有效期5年。","sections":[{"no":"一（二）","title":"提升竹林基地质效","text":"全面实施各类竹林分类经营，将符合条件的竹林培育纳入造林补助和森林抚育补助范围，将退化竹林和低产低效竹林修复纳入森林质量精准提升工程，对纳入提升工程的竹林基地，按照同等的造林补助或森林抚育补助标准给予补助。"},{"no":"一（三）","title":"完善竹林配套设施","text":"统筹旅游路、产业路、资源路、防火林道规划，提升竹林道建设规模，全市每年支持建设竹林道50公里以上，按照3万元—5万元/公里的标准给予补助。支持双牌县、蓝山县、新田县等竹产业重点发展区进一步完善竹山基础设施，改善生产条件，降低生产成本。"},{"no":"二（五）","title":"大力培育市场主体","text":"聚焦竹笋、竹材及竹材产品、竹日用品等优势领域，培育规模以上竹产业龙头企业15家。引导省级以上竹产业龙头企业提升规模化、标准化、产业化发展水平，引进升级机械化、智能化生产线，推进新技术、新工艺、新产品研发应用。对龙头企业围绕构建全竹产业链实施的竹林流转、精深加工、剩余物产品研发、创新或融资平台建设、营销渠道拓展等竹产业延链、补链、强链项目贷款予以贴息。"}],"interpretations":[{"sectionNo":"一（二）","headline":"竹林培育纳入造林、森林抚育补助，按同等标准补助","who":"实施竹林分类经营、符合条件的竹林培育主体；退化竹林和低产低效竹林修复纳入森林质量精准提升工程的竹林基地经营主体。","materials":[],"window":"按造林补助或森林抚育补助的年度安排执行，原文未设单独申报期。","where":"原文未明确受理部门","tip":"补助标准与造林补助或森林抚育补助同等，不另设标准；须先纳入提升工程。"},{"sectionNo":"一（三）","headline":"竹林道建设每年50公里以上，每公里补3万至5万元","who":"竹林道建设主体；全市每年支持建设竹林道50公里以上，按3万元—5万元/公里补助；双牌县、蓝山县、新田县等竹产业重点发展区优先完善竹山基础设施。","materials":[],"window":"每年支持建设竹林道50公里以上。","where":"原文未明确受理部门","tip":"补助按公里计算，3万元—5万元/公里；全市年度建设规模50公里以上。"},{"sectionNo":"二（五）","headline":"培育15家规模以上竹产业龙头，龙头企业延链项目贷款贴息","who":"省级以上竹产业龙头企业，围绕构建全竹产业链实施竹林流转、精深加工、剩余物产品研发、创新或融资平台建设、营销渠道拓展等延链、补链、强链项目的企业；全州培育规模以上竹产业龙头企业15家。","materials":[],"window":"原文未设申报截止期，按项目贷款贴息安排执行。","where":"原文未明确受理部门","tip":"贴息仅限龙头企业围绕全竹产业链的延链、补链、强链项目贷款；规模以上龙头企业培育目标为15家。"}],"sourceUrl":"https://www.yzcity.gov.cn/cnyz/zfbgswj/202409/b9f6d6a2940a44a0a4d49be668112f83.shtml","sourceNote":"2026-11-22 取自永州市人民政府门户「市政府—基本信息公开—履职依据—市政府办公室规范性文件」原文页，版头载文号永政办发〔2024〕11号、统一登记号 YZCR-2024-01008，页面信息时效性栏载“有效”。日期口径：publishedAt 取页面“发文日期”2024-08-05（文件落款为2024年8月4日）；effectiveAt 按原文“自本文件印发之日起施行”取同一日期。 2026-11-22 收录：与官方页面逐句比对，命中 6/6 句（100%），关卡判定「verbatim」。 有效期依据：正文末条明示“有效期五年”，自2024年8月4日印发起算至2029年8月4日","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"yz-cost-2024","title":"永州市人民政府办公室关于印发《永州市支持企业降本增效若干措施》的通知","level":"city","region":"永州市","issuer":"永州市人民政府办公室","documentNo":"永政办发〔2024〕9号","publishedAt":"2024-06-18","effectiveAt":"2024-06-18","expiresAt":"2029-06-18","status":"active","tags":["融资支持","营商环境","场地支持"],"audience":["小微企业","制造业企业","物流仓储企业","电商企业"],"summary":"15条措施降低用电、用水用气、天然气、融资、物流、创新创业和用地成本；对单户融资担保500万元及以下、年化担保费率不高于0.5%的新增业务按0.5%给予担保费补贴；对首次落户的物流仓储总部企业、首次获5A/4A/3A资质物流企业给予奖励，有效期5年。","sections":[{"no":"二","title":"推广水电气网联动报装","text":"推行160千瓦及以下小微企业用电报装“零费用”政策。实现供水、供电、供气、有线电视、网络通讯报装“一窗受理、一网通办、一同踏勘、一并接入”。普通高压用电客户用电报装，供电企业办理时限压减至15个工作日。用水用气报装无外线工程的，不超过2个工作日办结；有外线工程的，不超过10个工作日办结。"},{"no":"四","title":"降低企业融资成本","text":"对符合条件的法人银行按普惠小微贷款余额增量的1%提供激励资金。加强对单户授信1000万元以内（含）小微企业贷款利率和有贷户数的监管考核，保障更多小微企业的贷款需求。对单户融资担保金额500万元及以下，且年化担保费率不高于0.5%的新增业务，按年化担保金额的0.5%给予担保费补贴。"},{"no":"六","title":"支持物流仓储企业发展","text":"鼓励物流行业领军企业来永发展，对首次落户永州的物流仓储企业总部、区域总部、采购中心、区域分拨中心，实缴注册资本超过1亿元且营收超过1亿元的，由受益财政对其在永企业给予支持。对首次获得国家5A、4A、3A资质的物流企业，由受益财政给予一定奖励。"},{"no":"七","title":"支持企业扩能升级","text":"加大对企业“智改数转”的支持力度，对成功创建国家级、省级标杆智能车间和标杆智能企业，由受益财政给予奖励。鼓励招引和培育互联网平台企业，加快发展数字经济，对新获得省级两化融合管理体系贯标标杆企业、省级“上云上平台”标杆企业、省“数字新基建”100个标志性新基建项目，根据相关政策文件规定，由受益财政给予一定奖励。"},{"no":"八","title":"降低创新创业成本","text":"打造电子商务集聚区，由受益财政对入驻集聚区的电商企业减免前3年租金，提供集中仓储、抱团接单、统一发货、组团参加大型展销会等综合性服务，降低电商企业运营成本10%以上。"}],"interpretations":[{"sectionNo":"二","headline":"160千瓦及以下小微企业用电报装零费用，15个工作日办结","who":"160千瓦及以下的小微企业，用电报装实行“零费用”；普通高压用电客户用电报装按要求压减办理时限；办理用水、用气报装的企业，无外线工程与有外线工程分别适用不同办结时限。","materials":[],"window":"用电报装：供电企业办理时限压减至15个工作日；用水用气报装：无外线工程的不超过2个工作日办结，有外线工程的不超过10个工作日办结。","where":"供水、供电、供气、有线电视、网络通讯报装“一窗受理、一网通办、一同踏勘、一并接入”窗口。","tip":"用电“零费用”只适用于160千瓦及以下小微企业；用水用气报装要区分有无外线工程，有外线工程的为10个工作日、无外线工程的为2个工作日。"},{"sectionNo":"四","headline":"单户授信1000万元以内小微企业贷款，担保费补贴0.5%","who":"单户授信1000万元以内（含）的小微企业；符合条件的法人银行，按普惠小微贷款余额增量的1%获激励资金；单户融资担保金额500万元及以下、且年化担保费率不高于0.5%的新增担保业务。","materials":[],"window":"按普惠小微贷款余额增量和单户融资担保新增业务据实计算，原文未列固定申报期。","where":"符合条件的法人银行、办理单户融资担保业务的担保机构。","tip":"担保费补贴要求单户融资担保金额500万元及以下且年化担保费率不高于0.5%，超过500万元或费率高于0.5%的新增业务不在补贴范围。"},{"sectionNo":"六","headline":"物流企业总部落户永州，实缴资本、营收超1亿元可获支持","who":"首次落户永州的物流仓储企业总部、区域总部、采购中心、区域分拨中心，且实缴注册资本超过1亿元、营收超过1亿元；首次获得国家5A、4A、3A资质的物流企业。","materials":[],"window":"首次落户、首次获得资质时适用，原文未列申报期。","where":"受益财政。","tip":"总部类支持要求实缴注册资本和营收同时超过1亿元；资质奖励只针对首次获得国家5A、4A、3A资质的物流企业。"},{"sectionNo":"七","headline":"创建国家级、省级标杆智能车间或智能企业，可获财政奖励","who":"成功创建国家级、省级标杆智能车间和标杆智能企业的企业；新获得省级两化融合管理体系贯标标杆企业、省级“上云上平台”标杆企业、入选省“数字新基建”100个标志性新基建项目的企业。","materials":[],"window":"创建成功或新获得相应资质后，根据相关政策文件规定兑现，原文未列申报期。","where":"受益财政（按相关政策文件规定兑现）。","tip":"奖励对象限于成功创建或新获得相应标杆资质的企业；具体奖励标准根据相关政策文件规定执行。"},{"sectionNo":"八","headline":"入驻电商集聚区，前3年租金减免，运营成本降10%以上","who":"入驻电子商务集聚区的电商企业，由受益财政减免前3年租金；集聚区提供的集中仓储、抱团接单、统一发货、组团参加大型展销会等综合性服务面向入驻电商企业。","materials":[],"window":"入驻后前3年享受租金减免，原文未列申报期。","where":"电子商务集聚区（由受益财政落实租金减免）。","tip":"租金减免以入驻集聚区为前提、期限为前3年；运营成本降低10%以上，靠集中仓储、统一发货、组团参加大型展销会等综合性服务实现。"}],"sourceUrl":"https://www.yzcity.gov.cn/cnyz/zfbgswj/202406/0da693fa66a24b6da50e6445b95e9e0e.shtml","sourceNote":"2026-11-22 取自永州市人民政府门户「市政府—基本信息公开—履职依据—市政府办公室规范性文件」原文页，版头载文号永政办发〔2024〕9号、统一登记号 YZCR-2024-01006，页面信息时效性栏载“有效”。日期口径：publishedAt 取页面“发文日期”2024-06-18；effectiveAt 按原文“自本文件印发之日起施行”取同一日期。 2026-11-22 收录：与官方页面逐句比对，命中 13/13 句（100%），关卡判定「verbatim」。 有效期依据：正文末条明示“有效期五年”，自2024年6月18日印发起算至2029年6月18日","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"yz-health-2025","title":"永州市人民政府办公室关于印发《永州市培育大健康产业若干措施》的通知","level":"city","region":"永州市","issuer":"永州市人民政府办公室","documentNo":"永政办发〔2025〕8号","publishedAt":"2025-09-24","effectiveAt":"2025-09-24","expiresAt":"2030-09-24","status":"active","tags":["财政奖补","认定资质","专项资金"],"audience":["生物医药与医疗器械企业","中药材种植与加工企业","健康食品企业","医药流通企业"],"summary":"永州市培育大健康产业六方面措施：发展生物医药及医疗器械、壮大健康食品、提升医疗卫生服务、强化健康管理服务、促进健康产业跨界融合、加强发展保障。可核的量化指标包括：乡镇卫生院和社区卫生服务机构为养老机构提供医养结合服务全覆盖、二级及以上综合医院设老年医学科比例达100%、新建居住区按每千人6个托位配建、公立机构托位比例达30%；文件未列财政奖补金额，仅明确对大健康产业技术创新、产业化项目给予重点支持并落实税收优惠；自印发之日起施行，有效期5年。","sections":[{"no":"一","title":"","text":"发展生物医药及医疗器械产业（一）推广中药材种植。重点打造厚朴、黄柏、青蒿、山苍籽、迷迭香、重楼、玉竹、黄姜等特色优势中药材种植基地。通过“产供销共建”方式，参与省级中药材产地初加工、精深加工示范基地建设，鼓励中药生产企业自建、共建符合《中药材生产质量管理规范》的生产基地。支持重点乡镇建设一批集中连片、生态化种植、机械化作业、信息化管理的规范化生产基地，支持道县厚朴打造国家地理标志产品，抓好冷水滩区、零陵区“湘九味”中药材优势特色产业集群建设。（二）推动药品制造赋能。加快推进“湘九味”蕲蛇粉项目、仟亿紫薇山（湖南）药业有限公司血液透析液（粉）生产项目建设，强力推动万众制药中成药生产基地及基本药物配送中心项目尽快投产。壮大永州特色药材、道地药材产业及深加工规模，打造产业集群。（三）支持瑶医药创新发展。推进瑶药标准研究与制定，构建瑶医药产业体系，打造瑶医药产品生产基地。持续深化与湖南中医药大学的协同合作，加强瑶医药产品研发与转化应用。（四）加强技术研发。支持优势企业深化与中药种植及加工企业的合作，推进“原辅料+生产”一体化发展。推动体外诊断产品、高性能诊疗设备及核心零部件（元器件）、医用材料和植（介）入类医疗器械、可穿戴智能设备、基因检测、新型防护用品等领域产品开发与产业化，基本实现主流医疗装备有效供给，提升高端医疗装备产品性能和质量水平。（五）加强医药物流和零售服务。健全药品集中采购制度，加快完善医药冷链物流基础设施，培育一批具有竞争力的现代医药流通骨干企业。规范发展专业化第三方医药配送服务。支持医药零售连锁企业健康发展，加快形成覆盖全市的连锁网络。推动医药传统零售模式转型升级，构建“医药零售+中医服务”“互联网+医药营销”等新模式新业态。提质搭建进出口服务平台，调整完善“一站式”进出口服务措施。"},{"no":"二","title":"","text":"壮大健康食品行业（一）深化农产品加工。深挖特色资源，提升加工能力，注重打造行业标杆。围绕健康食品、休闲食品、食品添加剂、产品购销流通等重点环节，建立健全“四库一清单”（产品信息库、企业信息库、供应商信息库、客户信息库和产品购销流通清单），大力引进培育龙头企业，形成“引进一个、带动一批、集聚一片”的“葡萄串效应”，打造一批专精特新、单项冠军、“三品”标杆企业。（二）推动药食同源产品开发。利用永州玉竹、罗汉果等药食同源药材资源，开发代用茶、即食膏方、养生汤料包等便捷化产品。深入挖掘瑶族医药养生文化，探索建设瑶医药膳体验馆。打造永州药食同源创新中心，重点攻关低温萃取、膜分离等绿色提取技术。支持企业开发中药多糖、黄酮类等功能性成分提取物，应用于抗疲劳、增强免疫力等保健食品的研发。推动地理标志产品升级为健康养生食品。（三）深化功能食品加工。发展方便营养型食品，推动传统食品工业化、健康化发展，推广永州米粉、东安鸡等地方特色食品工业化生产加工，开发低盐低脂即食米粉、真空包装风味卤制品。利用葛根、茯苓等原料，研发降糖降脂代餐粉、护肝解酒咀嚼片等功能性产品。开发适应健身、母婴、银发群体的定制化食品。创建省级药食同源重点实验室。建设永州国际农产品加工研发中心。深化与粤港澳大湾区合作，共建“种植基地+加工园区+冷链物流”跨省合作样板区，争取“湘品出湘”专项通道。"},{"no":"三","title":"","text":"提升医疗卫生服务能力（一）优化医疗资源配置。整合完善医疗卫生服务体系，健全市、县、乡、村四级医疗卫生服务网络。发挥市级公立医院在城市医疗集团中的牵头作用、县级医院在县域医共体中的龙头作用，打造“15分钟就医圈”，补齐基层医疗服务短板。建立职业院校和其附属医疗机构设备共享机制。（二）推进区域医疗中心和副中心建设。支持市中心医院建设市级综合性区域医疗中心、市中医医院建设市级中医急救联盟和市级区域中医医疗中心。依托县人民医院建设市域医疗卫生副中心；依托县中医医院建设市域中医医疗副中心，在南部县推动建设1—2所三级甲等综合医院；依托乡镇卫生院建设县域医疗副中心；支持符合条件的社区卫生服务中心建设社区医院。（三）加强专科性医疗中心建设。依托市中心医院建设市公共卫生救治中心、区域病理检测中心，依托市中医医院建设市康复中心，依托市第一人民医院建设市口腔医院，依托市妇幼保健院建设市妇幼保健中心和市妇女儿童医院，依托市疾控中心建设市职业病防治医院，依托永州皮肤病医院建设市级皮肤病专科医院，依托市第四人民医院建设老年病医院。（四）加强重点专科建设。针对重大疾病加强核心专科建设，在中心城区建立高层次医学人才培养基地，构建覆盖常见病、多发病、传染病的专科服务体系。加强县市区基础专科建设，根据区域规划和疾病谱，发展具有地方特色的优势专科。加大柔性引才力度，提升医院专科核心竞争力。（五）推进医保支付方式改革。持续推行脑卒中、骨伤病等康复病种住院按床日付费，强化政策协同，探索按病种分值付费改革与中医医保支付改革、紧密型县域医共体医保支付方式改革的有效衔接。"},{"no":"四","title":"","text":"强化健康管理服务（一）提升健康体检能力。结合精准医疗和健康医疗大数据，重构健康体检产业，满足多样化和差异化服务需求。鼓励和引导专业健康体检机构连锁化、集团化经营，培育形成具有区域影响力的专业健康体检机构和品牌。开展疾控机构社会化服务试点。（二）提升中医保健能力。建设市级中医治未病中心、县级中医治未病科室，强化基层医疗卫生机构中医馆中医治未病服务。建设市级中医养生保健服务实训基地，推进中医康复中心建设，推广一批中医康复方案，提高中医药健康管理率，制定推广适宜的中医药签约服务包。（三）提升康复服务能力。建成以康复医院、综合医院康复医学科为主体，基层医疗卫生机构为基础的康复医疗服务体系。推动二级及以上综合医院实现康复医学科全覆盖。鼓励有条件的基层医疗卫生机构增设康复医疗服务床位。支持和引导社会力量举办规模化、连锁化的康复医院。推进市脑科医院建设市级精神医学中心和心理健康服务中心。（四）提升医疗照护能力。将医疗照护纳入全市老龄事业发展规划，持续推进社会养老服务体系建设，统筹医疗照护需求和供给。推动组建专业团队，鼓励引进优质医疗照护服务机构，满足老年人健康恢复需求。成立市婴幼儿照护服务指导中心和质控中心，建立专家库和行业协会。落实新建居住区按每千人6个托位的标准建设任务，公立机构托位比例达到30%。（五）推进健康保险。促进商业健康保险与基本医保互补衔接。支持保险公司发展与基本医疗保险衔接的各类医疗保险、疾病保险和失能收入损失保险等健康保险产品。开展长期护理保险试点，鼓励商业保险积极参与长期护理保险建设。支持保险公司发展食品安全责任保险。（六）加强健康人才培养。推动健康产业实用技术技能人才产教融合实训基地建设。引导企业与高校、科研院所、医疗机构等深度合作，培育一批健康领域产教融合型企业。实施中医药“神农人才”工程，依托职业院校、老年大学等建设一批健康产业实训基地。"},{"no":"五","title":"","text":"促进健康产业跨界融合（一）促进康旅融合。以承办第七届湖南旅游发展大会为契机，着力提升“健康+旅游”产业融合水平。推动优质医疗机构、旅游服务机构和旅游休闲基地深度合作，参与建设国家中医药健康旅游示范区（基地）。实施“森林康养+”行动。整合市级公立医院和市福利中心资源，统筹建设生态医疗康养城。加快江华瑶族自治县千年瑶寨桐冲口中医药康养旅游省级体验基地建设。联合湘桂粤赣“四省九市”协同推广“养胃之旅”“瑶寨康养之旅”等康养旅游精品线路。（二）促进医体融合。加快构建覆盖县、乡、村三级的全民健身设施网络和城市社区15分钟健身圈，重点推进宋家洲体育公园、湘江西路体育公园、潇湘步道（永州段）、市青少年运动训练基地（市水上运动服务中心）、宁远县莲花山体育公园等项目建设。着力培育山地、水上、汽摩、航空、极限、马拉松等时尚休闲运动项目，支持创建具有区域影响力的体育俱乐部品牌。高质量举办中国龙舟公开赛、半程马拉松等体育赛事。（三）促进医养融合。推动二级及以上综合性医院、中医医院设立老年医学科的比例达到100%。支持公立中医医院至少建成1家紧密型医养结合机构。乡镇卫生院和社区卫生服务机构为当地社区养老服务机构提供医养结合服务实现全覆盖，将市中医医院打造为医养结合标杆医院。大力推进安宁疗护标准病房建设。培育壮大一批智慧健康养老企业。（四）促进康美融合。鼓励发展外科美容、皮肤美容、注射美容和口腔美容，积极培育中医美容，做大做强一批公立医院医疗美容，做强做精一批社会医疗美容机构，在生物提取物领域着力打造一批高端化、可信赖的医疗美容品牌。（五）促进医教协同。强化卫健部门与职业院校合作，共建医疗卫生人员继续教育培训基地，深化科研合作。聚焦“小胖墩”“小眼镜”“小星星”“小骨干”“小蛀牙”儿童健康“五小”问题，构建系统高效、防治结合的儿童健康服务体系。广泛开展“健康知识进校园”活动。"},{"no":"六","title":"","text":"加强大健康产业发展保障。强化政策支持。对大健康产业领域技术创新、产业化项目等给予重点支持，加强用地、用能、原材料等要素保障，全面落实税收优惠政策。规范健康产业市场。严格落实国家行业准入制度要求，深化“放管服”改革，优化政务服务环境。打造永州市大健康产业联盟。服务集群企业技术攻关，持续搭建公共服务平台、检测检验平台、创新研发平台、产业链供应链协同平台，打造独具特质的健康产业生态。强化健康教育和宣传。引导释放健康消费需求，深化健康产业供给侧改革，加快形成健康消费与健康供给良性互动发展格局。"},{"no":"七","title":"","text":"以上措施自本文件印发之日起施行，有效期5年。"}],"interpretations":[{"sectionNo":"一","headline":"中药材种植、药品制造、医疗器械等生物医药项目获支持","who":"在永州市从事中药材种植（厚朴、黄柏、青蒿、山苍籽、迷迭香、重楼、玉竹、黄姜等）、中药生产、药品制造、瑶医药研发、医疗器械及医药物流零售的企业和基地；须符合《中药材生产质量管理规范》等要求。","materials":[],"window":"按项目推进，本条未列申报期。","where":"省级中药材产地初加工、精深加工示范基地申报渠道；道县、冷水滩区、零陵区等重点乡镇基地","tip":"鼓励中药生产企业自建、共建符合《中药材生产质量管理规范》的生产基地；道县厚朴按国家地理标志产品打造。"},{"sectionNo":"二","headline":"健康食品与药食同源加工获支持，建省级重点实验室","who":"在永州市从事健康食品、休闲食品、食品添加剂、药食同源产品、功能食品加工及购销流通的企业；围绕玉竹、罗汉果、葛根、茯苓等本地药材资源开发产品。","materials":[],"window":"本条未列申报期，按年度项目推进。","where":"永州药食同源创新中心、省级药食同源重点实验室；粤港澳大湾区跨省合作样板区","tip":"支持争取“湘品出湘”专项通道，地理标志产品可升级为健康养生食品。"},{"sectionNo":"四","headline":"社会力量可办连锁康复医院，新建居住区每千人6个托位","who":"在永州市举办健康体检、中医保健、康复、医疗照护、健康保险等健康管理服务的社会力量和企业；二级及以上综合医院须康复医学科全覆盖，新建居住区按每千人6个托位配建，公立机构托位比例达30%。","materials":[],"window":"本条未列申报期；托位配建按新建居住区建设任务执行。","where":"市婴幼儿照护服务指导中心、市脑科医院；商业保险公司","tip":"公立机构托位比例须达30%，二级及以上综合医院康复医学科全覆盖是硬指标。"},{"sectionNo":"五","headline":"康旅、医体、医养融合项目可参与省级康养基地","who":"在永州市开展康养旅游、体育健身、医养结合、医疗美容等健康产业跨界融合项目的企业和机构；支持公立中医医院建成紧密型医养结合机构，社会医疗美容机构做强做精。","materials":[],"window":"以承办第七届湖南旅游发展大会为契机推进。","where":"江华瑶族自治县千年瑶寨桐冲口中医药康养旅游省级体验基地；宋家洲体育公园等项目","tip":"二级及以上综合医院、中医医院设老年医学科比例须达100%，乡镇卫生院医养结合服务全覆盖。"}],"sourceUrl":"https://www.yzcity.gov.cn/cnyz/zfbgswj/202510/3d49f1c3ab294444acd1159b70adda28.shtml","derivedFrom":"official","sourceNote":"2026-11-22 取自永州市人民政府门户「市政府—履职依据—市政府办公室规范性文件」原文页，版头载文号永政办发〔2025〕8号、统一登记号 YZCR—2025—01003，页面信息时效性栏载“有效”。日期口径：publishedAt 取页面“发文日期”2025-09-24；effectiveAt 按原文“自本文件印发之日起施行”取同一日期。 2026-11-22 收录：与官方页面逐句比对，命中 14/14 句（100%），关卡判定「verbatim」。 有效期依据：正文末条明示“有效期5年”，自2025年9月24日印发起算至2030年9月24日 2026-11-24 收录：与官方页面逐句比对，命中 92/92 句（100%），关卡判定「verbatim」。 有效期依据：原文未明示","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"yz-tech-2025-2","title":"永州市人民政府办公室关于印发《永州市打造具有核心竞争力的区域科技创新高地若干措施》的通知","level":"city","region":"永州市","issuer":"永州市人民政府办公室","documentNo":"永政办发〔2025〕2号","publishedAt":"2025-01-14","effectiveAt":null,"expiresAt":null,"status":"active","tags":["研发创新","财政奖补","认定资质"],"audience":["永州市企业","市级科研院所","科技创新平台建设单位"],"summary":"年度研发投入200万元以上企业奖2万元、1000万元以上奖5万元；新认定国家级、省级重点实验室分别给予100万元、50万元经费支持。","sections":[{"no":"一(一)","title":"落实研发投入优惠政策","text":"全面落实研发费用税前加计扣除和高新技术企业所得税减免等优惠政策，支持企业积极申报省财政研发奖补。"},{"no":"一(二)","title":"实施研发投入奖补政策","text":"对研发投入年度增幅10%以上且排名前2位的市级科研院所，给予5万元奖励。对年度研发投入200万元以上（含200万元）的企业，给予2万元奖励；对年度研发投入1000万元以上（含1000万元）的企业，给予5万元奖励。"},{"no":"二(三)","title":"省市自然科学联合基金","text":"由省自然科学基金委员会和我市共同出资设立省市自然科学联合基金，省自然科学基金委员会每年按我市出资金额的20%配套，市财政给予每个立项的省市自然科学联合基金项目2万元支持，剩余部分由项目承担单位负责。"},{"no":"三(四)","title":"基础与应用基础研究平台","text":"对新认定的重点实验室，国家级、省级分别给予100万元、50万元经费支持。"}],"interpretations":[{"sectionNo":"一(一)","headline":"研发费用加计扣除、高企所得税减免，可申报省研发奖补","who":"永州市企业：可享受研发费用税前加计扣除、高新技术企业所得税减免；同时可申报省财政研发奖补。原文未列规模、行业等附加门槛。","materials":[],"window":"原文未写申报起止时间，为落实既有优惠政策的表述。","where":"原文未指定受理部门或线上申报系统。","tip":"本条只写政策落实方向，未给金额、门槛和申报方式；省财政研发奖补须由企业主动申报。"},{"sectionNo":"一(二)","headline":"企业研发投入超200万元奖2万元，超1000万元奖5万元","who":"年度研发投入200万元以上（含200万元）的企业奖励2万元；1000万元以上（含1000万元）的企业奖励5万元；市级科研院所须研发投入年度增幅10%以上且排名前2位，奖励5万元。","materials":[],"window":"按年度研发投入核算；原文未写申报起止时间。","where":"原文未指定受理部门或线上申报系统。","tip":"企业奖励按研发投入金额对应档次；科研院所另设增幅10%以上且排名前2位的条件，与增幅排名挂钩。"},{"sectionNo":"二(三)","headline":"联合基金立项项目市财政支持2万元，省按市出资额20%配套","who":"申报省市自然科学联合基金项目并获立项的项目承担单位；基金由省自然科学基金委员会与永州市共同出资设立。","materials":[],"window":"省自然科学基金委员会每年按我市出资金额的20%配套；原文未写项目申报时间。","where":"省自然科学基金委员会与永州市共同出资；原文未写具体受理窗口或线上系统。","tip":"市财政只给每个立项项目2万元支持，剩余部分由项目承担单位负责；省配套按我市出资金额的20%每年计算。"},{"sectionNo":"三(四)","headline":"新认定重点实验室：国家级100万元、省级50万元","who":"新认定的重点实验室依托单位：国家级重点实验室100万元、省级重点实验室50万元经费支持。","materials":[],"window":"以“新认定”为条件，认定后给予支持；原文未写申报时间。","where":"原文未指定受理部门或线上申报系统。","tip":"只奖励新认定的重点实验室，国家级与省级按认定层级分别对应100万元、50万元。"}],"sourceUrl":"https://yzcity.gov.cn/cnyz/zfbgswj/202501/d1ae078a50f142c091333fdfe2491069.shtml","sourceNote":"2026-11-21 取自永州市政府门户「政府规范性文件」原文页；登记号 YZCR-2025-01001、文号与成文日期已核对。 2026-11-21 收录：与官方页面逐句比对，命中 6/6 句（100%），关卡判定「verbatim」。 有效期依据：原文未设期限；规范性文件登记号 YZCR-2025-01001，按一般不超5年推算至2030-01","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"yz-trade-2024","title":"永州市人民政府办公室关于印发《永州市推进外贸高质量发展十条措施》的通知","level":"city","region":"永州市","issuer":"永州市人民政府办公室","documentNo":"永政办发〔2024〕8号","publishedAt":"2024-06-14","effectiveAt":"2024-06-14","expiresAt":"2027-06-14","status":"active","tags":["外贸外资","财政奖补","融资支持"],"audience":["外贸企业","蔬菜出口企业","跨境电商企业","外贸综合服务企业"],"summary":"十条措施支持外贸主体、产业集群、蔬菜出口、外贸平台、跨境电商、进口贴息、国际市场开拓、综合服务与通关效率；对综合评价前三的县市区外贸集群给予不超过50万元奖励，跨境电商孵化中心最高奖25万元，单个企业市级外贸支持累计不超过100万元，有效期3年。","sections":[{"no":"二","title":"做大产业集群","text":"市级层面将组织对全市的国家外贸转型升级基地、省级外贸产业集群开展综合评价，对于成效显著、带动作用强、综合评价排名前三位的，对所在县市区给予不超过50万元的奖励。"},{"no":"三","title":"打造特色亮点","text":"对规模以上、带动能力强的蔬菜出口企业，根据其出口创汇、社会经济贡献等情况开展综合评价，对综合评价排名靠前的2-5家企业，给予不超过50万元的奖励；扩大我市供港直通车运营规模，对购买并投入使用的供港直通车按照购车价10%、最高不超过20万元/台的标准给予支持，县市区可参照给予配套支持。"},{"no":"五","title":"发展外贸新业态","text":"支持跨境电商孵化中心建设，对成功孵化跨境电商企业10家以上的孵化运营中心主体，最高给予一次性奖励25万元；不断壮大跨境电商各类经营主体，鼓励申报省级跨境电商产业带和产业园，对成功申报省级跨境电商产业带和产业园的，最高给予一次性奖励50万元。"},{"no":"六","title":"扩大外贸进口","text":"对企业开展《湖南省鼓励类进口商品目录》内商品进口业务项下所产生的融资利息，给予不超过50%贴息，单个企业年度贴息金额支持总额不超过100万元。"},{"no":"十","title":"强化保障激励","text":"市财政统筹外贸和蔬菜发展有关资金用于支持外贸高质量发展。对于符合条件的项目，优先支持申报省级以上项目资金，中央、省、市项目资金未予保障的，县市区受益财政可给予支持。各类项目资金不得多头重复奖励，单个企业在市级层面所有外贸项目支持资金累计不超过100万元。"}],"interpretations":[{"sectionNo":"二","headline":"外贸基地集群综合评价前三，所在县市区最高奖50万","who":"全市的国家外贸转型升级基地、省级外贸产业集群所在县市区；须成效显著、带动作用强、综合评价排名前三位。","materials":[],"window":"按市级组织的综合评价结果确定。","where":"市级层面组织综合评价。","tip":"奖励给所在县市区而非单个企业；只有排名前三位才有，最高不超过50万元。"},{"sectionNo":"三","headline":"蔬菜出口企业排名前2-5名奖最高50万，供港直通车补10%","who":"规模以上、带动能力强的蔬菜出口企业，按出口创汇、社会经济贡献等综合评价，排名前2-5家；以及购买并投入使用供港直通车的运营主体。","materials":[],"window":"按综合评价结果确定；供港直通车以购买并投入使用为条件。","where":"原文未写明受理部门，按综合评价办理；县市区可参照配套。","tip":"蔬菜出口企业奖励不超过50万元；供港直通车按购车价10%、最高不超过20万元/台，县市区可参照给予配套支持。"},{"sectionNo":"五","headline":"孵化跨境电商10家以上奖25万，省级产业带或产业园奖50万","who":"成功孵化跨境电商企业10家以上的孵化运营中心主体；成功申报省级跨境电商产业带和产业园的主体。","materials":[],"window":"一次性奖励，以孵化或申报成功为条件。","where":"原文未写明受理部门。","tip":"孵化运营中心主体最高一次性奖励25万元；省级跨境电商产业带、产业园最高一次性奖励50万元。"},{"sectionNo":"六","headline":"鼓励类进口商品融资利息贴息50%，单企年最高100万","who":"开展《湖南省鼓励类进口商品目录》内商品进口业务的企业，就其进口业务项下产生的融资利息给予贴息。","materials":[],"window":"按年度计算，单个企业年度贴息金额支持总额不超过100万元。","where":"原文未写明受理部门。","tip":"贴息比例不超过50%，单个企业年度贴息总额不超过100万元。"},{"sectionNo":"十","headline":"市级外贸资金单企累计上限100万，不得多头重复奖励","who":"符合条件的项目及外贸企业；市级层面所有外贸项目支持资金合并计算。","materials":[],"window":"随年度外贸和蔬菜发展资金安排执行。","where":"市财政统筹；中央、省、市项目资金未予保障的，县市区受益财政可给予支持。","tip":"各类项目资金不得多头重复奖励，单个企业在市级层面所有外贸项目支持资金累计不超过100万元。"}],"sourceUrl":"https://www.yzcity.gov.cn/cnyz/zfbgswj/202407/13fc8a9d2c8746ed8b9d764a26ffda82.shtml","sourceNote":"2026-11-22 取自永州市人民政府门户「市政府—履职依据—市政府办公室规范性文件」原文页，版头载文号永政办发〔2024〕8号、统一登记号 YZCR-2024-01005，页面信息时效性栏载“有效”。日期口径：publishedAt 取页面“发文日期”2024-06-14（文件落款为2024年6月13日）；effectiveAt 按原文“自本文件发布之日起施行”取同一日期。 2026-11-22 收录：与官方页面逐句比对，命中 9/9 句（100%），关卡判定「verbatim」。 有效期依据：正文末条明示“有效期3年”，自2024年6月13日发布起算至2027年6月13日","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"zjj-covid-2021-20","title":"张家界市人民政府办公室印发《关于应对新冠肺炎疫情影响促进文旅行业提振信心加快复苏的政策措施》的通知","level":"city","region":"张家界市","issuer":"张家界市人民政府办公室","documentNo":"张政办发〔2021〕20号","publishedAt":"2021-08-28","effectiveAt":null,"expiresAt":"2021-12-31","status":"expired","tags":["就业补贴","财政奖补","融资支持"],"audience":["张家界市旅行社","宾馆酒店","民宿客栈","其他文旅企业"],"summary":"对30家旅行社、10家隔离宾馆酒店、10家民宿客栈及15家其他文旅企业分别安排不超过5万元、5万元、3万元、5万元扶持资金；航线航班每航段往返补贴0.5万—1万元。","sections":[{"no":"三","title":"航线航班补贴","text":"对2021年8月30日至9月30日期间恢复的国内航班给予补贴。执飞机型在100座（含）以上的，每航段往返给予1万元补贴；执飞机型在80座（含）以上100座以下的，每航段往返给予0.8万元补贴；执飞机型在80座以下的，每航段往返给予0.5万元补贴。"},{"no":"四","title":"为文旅企业纾困解难","text":"对因疫情影响导致经营困难的旅行社、宾馆酒店、民宿客栈和其它文旅企业予以扶持（为30家旅行社、10家疫情期间用于游客集中隔离的宾馆酒店、10家民宿客栈以及15家其它类型文旅企业分别安排不超过5万元、5万元、3万元、5万元的扶持资金）。对因疫情影响导致经营困难而无法按时缴纳电费的文旅企业，从即日起至2021年底实行“欠费不停供”措施。"},{"no":"五","title":"暂退旅游服务质量保证金","text":"对符合条件的旅行社，于2021年9月初完成暂退部分旅游服务质量保证金，暂退标准为现有缴纳数额的80%。被法院冻结的保证金不在此次暂退范围之内。"},{"no":"六","title":"加大信贷支持","text":"对受疫情影响较大的住宿餐饮、文化旅游等企业，金融机构不得盲目抽贷、断贷、压贷，要通过适当降低利率、信贷展期、续贷、减免逾期利息等措施给予支持，切实做到应续尽续、能续快续。"}],"interpretations":[{"sectionNo":"三","headline":"恢复的国内航班每航段往返补贴1万、0.8万、0.5万元","who":"在2021年8月30日至9月30日期间恢复国内航班并实际执飞的航空公司；执飞机型100座（含）以上按每航段往返1万元、80座（含）以上100座以下按0.8万元、80座以下按0.5万元分档补贴。","materials":[],"window":"2021年8月30日至9月30日期间恢复的航班；按每航段往返计发。","where":"原文未写明受理窗口与经办部门，条款直接面向执飞恢复航班的航空公司。","tip":"按执飞机型座位数分三档，100座（含）以上、80座（含）以上100座以下、80座以下各对应一档，不重复计发；航班须在2021年8月30日至9月30日期间恢复。"},{"sectionNo":"四","headline":"文旅企业分档扶持：旅行社等最高5万元，民宿客栈3万元","who":"因疫情影响导致经营困难的旅行社、宾馆酒店、民宿客栈和其它类型文旅企业；名额为旅行社30家、疫情期间用于游客集中隔离的宾馆酒店10家、民宿客栈10家、其它类型文旅企业15家；无法按时缴纳电费的文旅企业另可享受欠费不停供。","materials":[],"window":"扶持资金按上述名额安排；电费「欠费不停供」自即日起至2021年底。","where":"原文未写明申报窗口与经办部门，扶持对象按企业类型和名额确定。","tip":"四类扶持资金分别不超过5万元、5万元、3万元、5万元，名额分别为30家、10家、10家、15家，超出名额的不纳入；欠费不停供仅限文旅企业电费。"},{"sectionNo":"五","headline":"旅行社保证金按现有缴纳数额的80%暂退","who":"符合条件的旅行社；暂退标准为现有缴纳数额的80%；被法院冻结的保证金不在暂退范围。","materials":[],"window":"于2021年9月初完成暂退。","where":"原文未写明受理窗口与经办部门，仅明确暂退对象与标准。","tip":"被法院冻结的保证金不能暂退；暂退比例是现有缴纳数额的80%，不是全额退还。"},{"sectionNo":"六","headline":"住宿餐饮、文旅企业不得被盲目抽贷断贷，可降息续贷","who":"受疫情影响较大的住宿餐饮、文化旅游等企业。","materials":[],"window":"原文未限定申报期限，为疫情期间的信贷支持措施。","where":"金融机构（原文未列具体银行或受理窗口）。","tip":"要求做到应续尽续、能续快续，不得盲目抽贷、断贷、压贷；降息、展期、续贷、减免逾期利息由金融机构落实，不是自动发放。"}],"sourceUrl":"https://www.zjj.gov.cn/c2284/20210828/i621124.html","sourceNote":"2026-11-21 取自张家界市政府门户原文页；文号、登记号 ZJJCR—2021—01014、成文日期2021年8月28日与条款逐字核对。措施执行期已结束，判失效。 2026-11-21 收录：与官方页面逐句比对，命中 9/9 句（100%），关卡判定「verbatim」。 有效期依据：原文明示（“从即日起至2021年底”），措施执行期已结束","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"zjj-tourism-2022-27","title":"张家界市人民政府办公室关于印发《张家界市支持旅游市场主体复苏九条措施》的通知","level":"city","region":"张家界市","issuer":"张家界市人民政府办公室","documentNo":"张政办发〔2022〕27号","publishedAt":"2022-09-08","effectiveAt":null,"expiresAt":"2023-03-31","status":"expired","tags":["就业补贴","融资支持"],"audience":["张家界市旅行社","景区、酒店、民宿等旅游企业","旅游从业人员"],"summary":"暂退旅行社旅游服务质量保证金比例提高至100%、期限延至2023年3月31日；对文旅行业分会困难会员单位免收当年会费并先期拨付各10万元。","sections":[{"no":"二","title":"暂退旅游服务质量保证金","text":"落实暂退旅行社旅游服务质量保证金政策，将暂退期限延长至2023年3月31日，对符合条件的旅行社，暂退比例提高到100%，做到应退尽退。"},{"no":"三","title":"开展职业技能培训","text":"将景区、旅行社、酒店等旅游从业人员列入职业技能培训计划，开展免费的创业技能和岗位技能培训。"},{"no":"四","title":"免收困难会员单位会费","text":"文旅行业各分会对会员单位免收当前年度会费，免收部分从市政府专项资金中予以适当安排，先期拨付旅行社分会、饭店分会、民宿客栈分会、导游分会、旅游运输分会、景区及演艺分会各10万元，用于维持协会日常运转开支。"},{"no":"六","title":"加大“送客入张”奖励","text":"按照《张家界市人民政府办公室关于印发〈2022年张家界市旅游市场营销奖励实施方案〉的通知》（张政办函〔2022〕48号），实施2022年度旅游市场营销奖励。"}],"interpretations":[{"sectionNo":"二","headline":"旅行社保证金暂退比例提至100%，延至2023年3月31日","who":"符合条件的旅行社；暂退比例提高到100%，须在延长后的期限内办理。","materials":[],"window":"暂退期限延长至2023年3月31日。","where":"原文未写明受理窗口与经办部门，按暂退保证金政策执行。","tip":"比例提高到100%即全额暂退，须在2023年3月31日前办理，做到应退尽退。"},{"sectionNo":"三","headline":"景区、旅行社、酒店从业人员可免费参加技能培训","who":"景区、旅行社、酒店等旅游从业人员；列入职业技能培训计划，培训免费。","materials":[],"window":"原文未限定报名期限；按职业技能培训计划分批开展。","where":"原文未写明报名窗口与经办部门；培训由职业技能培训计划组织。","tip":"培训免费，含创业技能和岗位技能两类；对象为列入培训计划的旅游从业人员。"},{"sectionNo":"四","headline":"文旅会员单位免当年会费，六个分会各先期拨付10万元","who":"加入文旅行业各分会的会员单位（旅行社分会、饭店分会、民宿客栈分会、导游分会、旅游运输分会、景区及演艺分会）；免收当前年度会费。","materials":[],"window":"免收当前年度会费；先期拨付资金用于协会日常运转。","where":"文旅行业各分会（旅行社分会、饭店分会、民宿客栈分会、导游分会、旅游运输分会、景区及演艺分会）。","tip":"免收的是当前年度会费，不含以往年度；10万元是先期拨付给分会的工作经费，不是发给会员单位。"},{"sectionNo":"六","headline":"2022年度旅游市场营销奖励按张政办函〔2022〕48号实施","who":"参与2022年度张家界市旅游市场营销并符合奖励方案的单位；具体门槛按张政办函〔2022〕48号执行。","materials":[],"window":"2022年度；申报时间按张政办函〔2022〕48号方案执行。","where":"按《2022年张家界市旅游市场营销奖励实施方案》（张政办函〔2022〕48号）办理，原文未列具体窗口。","tip":"奖励标准与申报材料均以张政办函〔2022〕48号为准，本条只明确实施2022年度奖励。"}],"sourceUrl":"https://www.zjj.gov.cn/c2284/20220909/i698086.html","sourceNote":"2026-11-21 取自张家界市政府门户原文页；文号张政办发〔2022〕27号、登记号 ZJJCR—2022—01019、成文日期2022年9月8日与条款逐字核对。措施执行期已过，判失效。 2026-11-21 收录：与官方页面逐句比对，命中 4/4 句（100%），关卡判定「verbatim」。 有效期依据：原文明示（暂退期限延长至2023年3月31日）","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"zjj-tourism-2025-47","title":"张家界市人民政府办公室关于印发《2025年张家界市旅游发展奖励实施方案》的通知","level":"city","region":"张家界市","issuer":"张家界市人民政府办公室","documentNo":"张政办函〔2025〕47号","publishedAt":"2025-07-30","effectiveAt":"2025-01-01","expiresAt":"2025-12-31","status":"expired","tags":["财政奖补"],"audience":["张家界市旅行社","旅游饭店（民宿）","文旅内容创作者","境外宣传主体"],"summary":"2025年度旅游发展奖励，境外形象宣传网站浏览量达5000万给予每个10万元；抖音小红书作品评选10个，奖励3万—10万元。","sections":[{"no":"一","title":"实施时间","text":"2025年1月1日至12月31日。"},{"no":"二","title":"奖励原则","text":"同类奖励就高不就低、不重复奖励。申请奖励的旅行社（分社）须通过张家界智慧旅游团队管理系统（以下统称“一码行”）申报。"},{"no":"四(一)1","title":"客源市场线上推广奖","text":"对在境外建立张家界形象宣传外文网站，且浏览量、点击量达5000万的，给予每个网站10万元奖励。对在境外社交媒体上对张家界文旅资源进行宣传的法人、个人，单条播放量达500万以上的，给予每条视频3000元奖励。对在抖音、小红书平台上发布展现张家界自然美景、特色美食、历史底蕴与民俗风情等文旅元素的正能量视频、帖文创作者，综合传播影响力及内容质量等，各评选出10个作品，给予3万—10万元奖励。"},{"no":"四(一)2","title":"新闻宣传奖","text":"本年度从市旅游发展奖励资金中安排140万元，对在宣传推广工作中作出突出贡献的单位或个人给予奖励。"}],"interpretations":[{"sectionNo":"二","headline":"旅行社奖励不重复，须经“一码行”系统申报","who":"申请张家界市旅游发展奖励的旅行社（分社）。","materials":[],"window":"按本年度旅游发展奖励安排执行，原文未列明申报起止时间。","where":"张家界智慧旅游团队管理系统（“一码行”）。","tip":"同类奖励就高不就低、不重复奖励；申报须通过“一码行”系统。"},{"sectionNo":"四(一)1","headline":"境外网站点击达5000万奖10万，单条视频奖3000元","who":"在境外建立张家界形象宣传外文网站且浏览量、点击量达5000万的单位；在境外社交媒体宣传张家界文旅资源的法人、个人，单条播放量达500万以上；在抖音、小红书发布张家界文旅元素正能量视频、帖文的创作者。","materials":[],"window":"按2025年度奖励方案执行，原文未列明申报截止日期。","where":"原文未列明受理部门或申报系统。","tip":"网站奖10万元/个；境外社交媒体单条视频3000元；抖音、小红书各评选10个作品，奖3万—10万元。"},{"sectionNo":"四(一)2","headline":"新闻宣传奖安排140万元，奖突出贡献单位或个人","who":"在宣传推广工作中作出突出贡献的单位或个人。","materials":[],"window":"本年度内从市旅游发展奖励资金中安排，原文未列申报截止日期。","where":"原文未列明受理部门。","tip":"奖励资金总额140万元，由市旅游发展奖励资金列支。"}],"sourceUrl":"https://www.zjj.gov.cn/c693/20250731/i1095944.html","sourceNote":"2026-11-21 取自张家界市政府门户原文页；文号、成文日期（2025年7月30日）与条款逐字核对。2025年度方案，基准日已过执行期，判失效。 2026-11-21 收录：与官方页面逐句比对，命中 7/7 句（100%），关卡判定「verbatim」。 有效期依据：原文明示（实施时间2025年1月1日至12月31日）","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"zjj-tourism-2026-26","title":"张家界市人民政府办公室关于印发《张家界市2026—2027年旅游发展奖励实施方案》的通知","level":"city","region":"张家界市","issuer":"张家界市人民政府办公室","documentNo":"张政办函〔2026〕26号","publishedAt":"2026-04-24","effectiveAt":"2026-01-01","expiresAt":"2027-12-31","status":"active","tags":["财政奖补","认定资质"],"audience":["张家界市旅行社","旅游饭店（民宿）","文旅企业","旅游宣传推广主体"],"summary":"设旅游形象宣传奖、企业规范发展奖、服务提升奖、市场开拓奖、航线航班奖五类；营销创新奖10万元起、传播量每增2亿加2万元、100万元封顶。","sections":[{"no":"一","title":"实施时间","text":"2026年1月1日至2027年12月31日。旅游航线航班奖按年度调整，其他奖项按自然年度实施。"},{"no":"二","title":"奖励对象","text":"对张家界旅游发展有贡献的企业、媒体和个人。"},{"no":"三","title":"奖励原则与排除情形","text":"申请奖励的旅行社（分社）须纳入政府监管平台系统“一码行”监管。申报单位（个人）依法纳税，无欠税行为。申报单位当年有效投诉率超过万分之二（含）、发生涉旅重大投诉重大舆情重大安全事故、受到警告通报批评以上行政处罚、被认定为失信主体的，不予奖励。"},{"no":"五(一)2","title":"营销创新奖","text":"当年度市场主体投资举办的创新性营销活动、以张家界为主要背景的影视作品，且在境内外合计传播量10亿以上的，给予10万元奖励。传播量每增加2亿，奖励金额增加2万元，奖励资金100万元封顶。"},{"no":"五(二)1","title":"企业入规奖","text":"对本市旅行社、旅游饭店（民宿）当年度内入规，依法纳税，统计数据填报及时、准确的，按照《张家界市培育发展“四上”企业若干措施》（张政办发〔2025〕11号）实施奖励。"}],"interpretations":[{"sectionNo":"三","headline":"投诉率超万分之二、被列失信等情形，不予奖励","who":"申请奖励的旅行社（分社）须纳入政府监管平台系统“一码行”监管；申报单位（个人）依法纳税、无欠税行为；且当年有效投诉率未超过万分之二（含）、未发生涉旅重大投诉重大舆情重大安全事故、未受警告通报批评以上行政处罚、未被认定为失信主体。","materials":[],"window":"按当年情况审核，原文未列申报起止时间。","where":"张家界市（属地申报，原文未列具体受理窗口）","tip":"旅行社（分社）未纳入“一码行”监管、有欠税，或当年有效投诉率超过万分之二（含）、发生涉旅重大投诉重大舆情重大安全事故、受警告通报批评以上行政处罚、被认定为失信主体的，均不予奖励。"},{"sectionNo":"五(一)2","headline":"传播量10亿以上奖10万元，每增2亿加2万，100万封顶","who":"当年度市场主体投资举办的创新性营销活动，或以张家界为主要背景的影视作品，境内外合计传播量10亿以上的市场主体。","materials":[],"window":"按当年度实施，原文未列申报起止时间。","where":"张家界市（属地申报，原文未列具体受理窗口）","tip":"基础档为传播量10亿以上奖10万元，每增加2亿加2万元，累计奖励100万元封顶；传播量按境内外合计计算。"},{"sectionNo":"五(二)1","headline":"旅行社、旅游饭店当年度入规，按“四上”企业措施奖励","who":"本市旅行社、旅游饭店（民宿）；当年度内入规、依法纳税、统计数据填报及时准确。","materials":[],"window":"当年度内入规后申报，原文未列具体申报期。","where":"按《张家界市培育发展“四上”企业若干措施》（张政办发〔2025〕11号）执行","tip":"奖励标准按张政办发〔2025〕11号执行，须同时满足当年度入规、依法纳税、统计数据填报及时准确三项条件。"}],"sourceUrl":"https://www.zjj.gov.cn/c693/20260427/i1153971.html","sourceNote":"2026-11-21 取自张家界市政府门户原文页；文号、成文日期（2026年4月24日）与条款逐字核对。 2026-11-21 收录：与官方页面逐句比对，命中 9/9 句（100%），关卡判定「verbatim」。 有效期依据：原文明示（实施时间2026年1月1日至2027年12月31日）","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"zz-digital-sme-pilot-2026-2","title":"株洲市工信局 株洲市财政局关于印发《关于支持国家中小企业数字化转型城市试点建设的十条措施》《株洲市中小企业数字化转型城市试点专项资金管理办法（暂行）》的通知","level":"city","region":"株洲市","issuer":"株洲市工业和信息化局、株洲市财政局","documentNo":"株工信联〔2026〕2号","publishedAt":"2026-06-04","effectiveAt":"2026-06-04","expiresAt":"2026-12-06","status":"expiring","tags":["数字化转型","财政奖补","专项资金"],"audience":["四个细分行业试点中小企业","专精特新“小巨人”企业","数字化服务商","工业互联网平台企业"],"summary":"四个细分行业试点企业改造按采购总额30%补助、单家不超过30万元，其他试点企业按25%、最高25万元，市级财政再按不超过1:1配套；智能制造数字化车间最高15万元、标杆企业最高20万元。","sections":[{"no":"一","title":"支持四个细分行业中小企业数字化改造","text":"支持中小企业数字化改造，对先进轨道交通装备、中小航空发动机、先进硬质材料和陶瓷等四个细分行业试点企业采购工业软件、上云用云服务、工业网关、路由等必要的数据采集传输设备等方面给予补助，补助方式原则上为验收通过后补助，也可视情采取验收前预拨付、验收后再补助的方式。"},{"no":"二","title":"支持智能制造标杆企业和车间建设","text":"经评审验收的市级智能制造数字化车间，按照核定后的可补助投资额给予不超过15%、最高15万元补助。对经评审验收的市级智能制造标杆企业，按照核定后的可补助投资额给予不超过15%、最高20万元补助。"},{"no":"三","title":"支持企业提升数据管理能力","text":"对细分行业完成数字化转型成熟度贯标（含两化融合管理体系贯标）的试点企业，给予最高不超过5万元的奖励。"},{"no":"五","title":"支持打造“链式”转型模式","text":"对新认定的中小企业“链式”数字化转型典型案例或模式，一次性给予链主企业或数字化服务商不超过50万元的奖励，并支持申报国家级中小企业“链式”数字化转型典型案例。"},{"no":"六","title":"支持打造“小快轻准”产品及解决方案","text":"支持打造一批小型化、快速化、轻量化、精准化的“小快轻准”产品及解决方案。对列入市级优秀“小快轻准”产品及解决方案的，给予最高5万元奖励。每个服务商累计奖励不超过20万元。"}],"interpretations":[{"sectionNo":"一","headline":"四个细分行业试点企业采购工业软件等，验收后给补助","who":"先进轨道交通装备、中小航空发动机、先进硬质材料和陶瓷四个细分行业的试点企业，采购工业软件、上云用云服务、工业网关、路由等必要的数据采集传输设备。","materials":[],"window":"原则上验收通过后补助；也可视情验收前预拨付、验收后再补助。","where":"株洲市中小企业数字化转型城市试点专项资金（原文未点名具体受理部门）","tip":"补助与采购内容挂钩（工业软件、上云用云、数据采集传输设备）；以验收结果为拨付前提，验收前预拨属视情安排。"},{"sectionNo":"二","headline":"市级智能车间补15%最高15万元，标杆企业最高20万元","who":"经评审验收的市级智能制造数字化车间、市级智能制造标杆企业。","materials":[],"window":"经评审验收后按核定可补助投资额计算；原文未明确申报截止时间。","where":"株洲市中小企业数字化转型城市试点专项资金（原文未点名具体受理部门）","tip":"车间与标杆企业均按可补助投资额不超过15%计算，封顶分别为15万元、20万元；未通过评审验收不补助。"},{"sectionNo":"三","headline":"完成数字化转型成熟度贯标的试点企业，最高奖5万元","who":"细分行业试点企业，须完成数字化转型成熟度贯标（含两化融合管理体系贯标）。","materials":[],"window":"完成贯标后奖励；原文未明确申报截止时间。","where":"株洲市中小企业数字化转型城市试点专项资金（原文未点名具体受理部门）","tip":"两化融合管理体系贯标也计入；奖励封顶5万元，未完成贯标不享受。"},{"sectionNo":"五","headline":"新认定“链式”转型典型案例，链主或服务商最高奖50万元","who":"链主企业或数字化服务商，其“链式”数字化转型典型案例或模式经新认定。","materials":[],"window":"新认定后一次性奖励；原文未明确申报截止时间。","where":"株洲市中小企业数字化转型城市试点（原文未点名具体受理部门）","tip":"奖励对象为链主企业或数字化服务商，一次性发放；认定后还可申报国家级同类案例。"},{"sectionNo":"六","headline":"列入市级优秀“小快轻准”产品，最高奖5万元","who":"提供“小快轻准”（小型化、快速化、轻量化、精准化）产品及解决方案的服务商，产品须列入市级优秀名单。","materials":[],"window":"列入市级优秀名单后奖励；每个服务商累计不超过20万元。","where":"株洲市中小企业数字化转型城市试点（原文未点名具体受理部门）","tip":"单个产品最高5万元，同一服务商累计封顶20万元；未列入市级优秀名单不奖励。"}],"sourceUrl":"http://gxj.zhuzhou.gov.cn/zzcms/DFS//file/2026/06/04/202606040944463825y9slz.doc","sourceNote":"2026-11-21 取自株洲市工业和信息化局「通知公告」栏目原文页（http://gxj.zhuzhou.gov.cn/c16478/20260604/i2502812.html）所附正文附件；附件首页载明株工信联〔2026〕2号、2026年6月4日印发，与页面标注一致。正文取自 .doc 附件，已按原文核对条款顺序。 2026-11-21 收录：与官方页面逐句比对，命中 8/8 句（100%），关卡判定「verbatim」。 有效期依据：附件2《株洲市中小企业数字化转型城市试点专项资金管理办法（暂行）》第二十一条明示有效期至2026年12月6日。","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"zz-first-invest-2025","title":"株洲市人民政府办公室关于印发《株洲市“先投后股”项目资金管理办法》的通知","level":"city","region":"株洲市","issuer":"株洲市人民政府办公室","documentNo":"株政办发〔2024〕15号","publishedAt":"2024-12-31","effectiveAt":null,"expiresAt":null,"status":"active","tags":["融资支持","研发创新"],"audience":["科技型企业","科技成果转化项目"],"summary":"以“先投后股”方式支持早期科技成果转化项目和科技型企业：先以投资方式投入，达到约定条件后转为股权，明确支持对象、管理机制与退出安排。","sections":[{"no":"一","title":"","text":"为贯彻落实创新驱动发展战略，推动高水平科技自立自强，加大对早期科技成果转化项目和科技型企业的培育支持，加快发展新质生产力，根据《湖南省人民政府关于进一步深化预算管理制度改革的实施意见》（湘政发〔2021〕14号）以及省、市有关文件精神，结合我市实际，制定本办法。"},{"no":"二","title":"","text":"本办法坚持“投早、投小、投硬科技”，围绕株洲市“332”现代产业体系的创新创业项目，重点支持工业软件、人工智能、北斗应用、低空经济等产业项目，创新创业大赛获奖项目以及大学生创新创业项目等。"},{"no":"三","title":"","text":"本办法所称“先投后股”是支持科技成果转化的创新模式。在“先投”阶段，财政资金以科技项目形式向科技企业投入，支持研发和成果转化，并约定后期转化为股权的条件；在“后股”阶段，当被投企业达到转股条件时，按照约定将投入的财政科技资金转换为企业股权，并按照“适当收益”原则退出。"},{"no":"四","title":"","text":"“先投后股”模式作为引导科技创新和成果转化的加速器，遵循“政府主推、创新引导、权责清晰、公正透明”的原则，严格进行组织和管理。"},{"no":"五","title":"","text":"市科技局、市财政局、市工业和信息化局、株洲市产业投资控股集团有限公司共同组建市“先投后股”项目资金决策联席会（简称“决策联席会”） 。决策联席会主要职责包括：制定并发布“先投后股”工作实施细则；编制“先投后股”专项资金预算，审批专项资金拨付计划；管理审批“先投后股”各项工作；确定受托管理机构的职责、对受托管理机构进行考核、核定管理费用。决策联席会办公室设在市科技局，具体负责“先投后股”决策联席会的日常工作。"},{"no":"六","title":"","text":"市财政局、市国资委牵头统筹设立1000万元“先投后股”专项资金，将“先投后股”项目预算资金拨付至受托管理机构，实行专款专用。"},{"no":"七","title":"","text":"株洲市生产力促进中心为“先投后股”项目专项库建设与管理单位，负责组建“先投后股”专家库和专家评审委员会日常工作。“先投后股”评审每次抽选5名专家组成专家评审委员会，开展专业评审论证，形成评审意见供决策联席会参考。"},{"no":"八","title":"","text":"株洲市产业投资控股集团有限公司（或其指定主体）担任受托管理机构管理“先投后股”项目资金。受托管理机构负责在“先投”阶段作为项目资金池运营主体，以代收代支的形式向企业拨付项目支持资金；在“后股”阶段，作为持股主体，开展股权转化、持股管理、风险防控、股权退出、收益管理等工作。"},{"no":"九","title":"","text":"项目承担企业对项目申报材料的真实性和合法性负责，配合签订《项目合同书》《股权投资协议书》等协议，建立健全内部项目管理制度，规范合理使用资金。"},{"no":"十","title":"","text":"“先投后股”项目资金支持范围：（一）属于工业软件、人工智能、以北斗为引领的新一代信息技术、低空经济等产业且具有持续创新能力的创新创业项目。（二）国家、省、市举办的各类创新创业大赛获奖项目。（三）大学生单独创办或联合创办企业的项目。"},{"no":"十一","title":"","text":"“先投后股”项目资金支持的对象应当同时具备以下基本条件：（一）具备独立法人资格的科技企业，成立时间不超过3年。（二）申报企业创始股东实缴资金不低于申报项目预期总投入的10%。（三）项目符合株洲市产业发展方向，具有良好的开发价值及产业化前景，商业计划及技术路线清晰，实施方案合理。（四）相关知识产权权属清晰，不存在争议和纠纷。（五）项目负责人无违法失信和不良科研诚信记录，未纳入“失信联合惩戒对象名单”，无影响项目实施的未决诉讼。项目申报企业或技术核心团队拥有经认定登记的技术合同，给予优先支持。"},{"no":"十二","title":"","text":"单个科技项目支持资金原则上不超过该成果转化项目预期总投入的50%，支持金额不超过50万元。重大项目可采取“一事一议”方式给予支持，金额不超过200万元。"},{"no":"十三","title":"","text":"科技项目支持资金转化为股权的数量和持股比例在先投阶段签订的《项目合同书》中进行约定。财政科技资金参股比例不超过被投企业总股本20%，且不成为第一大股东，以出资额为限承担有限责任。"},{"no":"十四","title":"","text":"项目立项程序：（一）项目申报。决策联席会办公室定期发布项目申报指南，组织开展项目申报、形式审查，建立项目储备库。（二）项目评审。决策联席会办公室组织专家委员会对入库的申报项目的技术创新性和产业化前景等进行评审。（三）实地考察。受托管理机构配合决策联席会办公室对通过评审的项目开展实地考察，形成尽职调查报告。（四）项目立项和签约。决策联席会研究确定拟资助项目清单、金额，组织开展公示。对通过立项的项目，签订《项目合同书》。"},{"no":"十五","title":"","text":"项目实施程序：（一）资金拨付。支持资金通过受托管理机构按约定分期拨付给项目承担企业。签订《项目合同书》后拨付支持资金的70%，中期评估通过后拨付支持资金的30%。项目承担企业提前转股的，一次性拨付剩余资金。（二）项目实施。项目承担企业按照约定计划组织实施项目，开展技术攻关、产品研发及市场推广等工作，根据株洲市科技发展专项资金管理有关规定使用科技项目支持资金。（三）中期评估。项目实施满12个月后，决策联席会办公室组织开展项目中期评估，评估结果报决策联席会审核。对实施进度滞后或难以达到预期绩效目标的，督促项目承担企业及时调整或者按约定取消后续支持。（四）项目验收。转股期结束1个月内，决策联席会办公室组织开展项目验收，并委托第三方专业机构对项目资金使用情况进行审计，验收结果报决策联席会审核。对提前完成约定的验收指标且已实现转股的企业不再进行验收。（五）项目转股。原则上应当在支持资金投入项目承担企业后2年内（转股期）实现转股，未达到转股条件的，经决策联席会审批同意后可延期，延长期限视具体情况确定。"},{"no":"十六","title":"","text":"股权管理程序：（一）股权转化。当项目达到约定的转股条件后，受托管理机构提出转股建议，报决策联席会审批后，按照约定与项目承担企业签订《股权投资协议书》，并完成股权登记手续。（二）投后管理。转股后，由受托管理机构行使股东权利，开展持股管理、风险防控等工作，定期向决策联席会报告“先投后股”项目运行情况。（三）股权退出。原则上转股后的持股期不超过7年，其中后2年为股权退出期。根据被投企业发展情况，受托管理机构在持股期内择机开展股权退出，退出方式包括但不限于股权转让、股东回购、并购重组、挂牌上市、清算等。"},{"no":"十七","title":"","text":"符合以下条件之一，即认定为达到转股条件：（一）项目承担企业引入了外部风险投资机构投资且投资金额不低于50万元（含） 。（二）项目承担企业的产品或服务实现销售，且累计销售收入超过200万元（含） 。（三）达到《项目合同书》约定的验收通过条件。（四）其他经决策联席会审批认定的情况。符合前款第（一）项或第（二）项转股条件的视为项目验收通过，决策联席会不再对该项目组织验收。"},{"no":"十八","title":"","text":"为提高项目承担企业成果转化积极性，尽快推进产品进入市场创造经济效益，设置转股奖励机制和股权退出奖励机制。达到转股条件且符合下列情形之一的，财政资金最高可以让渡约定的转股持股数量的50%给对应被投企业成果转化核心团队，具体让渡比例由决策联席会审定：（一）项目承担企业在转股期限内获得风险投资机构投资且估值在亿元（含）以上。（二）科技成果转化产出的产品或服务累计实现销售收入500万元（含）以上。（三）支持资金投入1年（含）以内达到转股条件并转股的。单个持股项目股权退出后形成收益的，最高可奖励股权退出收益的50%给对应被投企业成果转化核心团队。"},{"no":"十九","title":"","text":"项目核销程序：（一）先投阶段内，经决策联席会审核确认项目终止、未通过中期评估或验收的，启动项目核销程序。如项目有结余资金应返还“先投后股”资金专户。如项目承担企业在项目实施过程中存在虚报、截留、挪用、冒领、侵占或骗取资金以及擅自改变专项资金用途等违反项目合同或法律法规行为的，应当退还“先投后股”项目资金，并依法承担相关法律责任。（二）后股阶段内，受托管理机构应当定期对被投企业发生事实损失的可能性进行评估。当被投企业出现损失时，受托管理机构启动损失核销工作流程，聘请第三方专业机构对“先投后股”资金使用情况进行专项审计，出具专项审计报告后形成核销方案上报决策联席会审核核销。"},{"no":"二十","title":"","text":"股权退出后形成的收益，扣除管理费、必要退出费用及奖励资金后，本金和剩余收益部分滚动返回至“先投后股”专用账户，继续用于开展“先投后股”项目。"},{"no":"二十一","title":"","text":"坚持“崇尚创新、宽容失败”的原则，经决策联席会研究确定的项目，不以项目损益和国有资产保值增值作为主要考核目标或责任认定依据。"},{"no":"二十二","title":"","text":"建立尽职免责机制，对于其他涉及责任问题的情形，如果符合以下规定的，可对相关主体予以免责，且在相关考核中不作负面评价。（一）未违反法律法规、党纪党规和国资监管制度的禁止性规定。（二）没有明确规定但符合中央、省级和市级决策部署精神。（三）未违反国家产业政策和株洲市产业发展规划。（四）符合“先投后股”项目资金投资方向和要求。（五）相关程序符合本办法规定。（六）没有为本人、他人或其他组织谋取不当利益，或者与其他组织、个人恶意串通，损害国家利益、公共利益和他人正当利益的行为。（七）对于探索创新、先行先试中出现的失误，主动采取措施挽回损失、消除不良影响或者有效阻止危害结果发生。（八）其他经认定符合尽职免责的情况。"},{"no":"二十三","title":"","text":"受托管理机构应当建立项目投资运作管理机制，确保参与实施尽职调查、投后管理和股权退出等方面的人员具备足够的职业操守、专业素养与审慎精神，独立、客观、公正地报告所发现情况。"},{"no":"二十四","title":"","text":"根据有关法律法规的规定，审计部门定期对“先投后股”项目中使用的财政资金进行审计监督，及时发现和揭露资金使用中的违纪违规问题。"},{"no":"二十五","title":"","text":"决策联席会对“先投后股”项目资金实施及受托管理机构履职情况开展绩效评价，充分发挥财政科技资金的引导作用。"},{"no":"二十六","title":"","text":"受托管理机构管理费根据上年度考核结果从“先投后股”项目资金中按年度提取，管理费为上年度“先投后股”项目实施、股权管理总金额的2%。“先投后股”项目实施过程中的尽职调查、价值评估、专项审计、投资退出等相关费用，可从“先投后股”项目资金中据实列支。"},{"no":"二十七","title":"","text":"决策联席会按年度编制资金预算，市财政局、市国资委统筹保障项目资金池1000万元规模，支持株洲市科技成果转化和产业发展。"},{"no":"二十八","title":"","text":"在“先投后股”项目实施过程中遇到未涉及的问题，由决策联席会研究解决。"},{"no":"二十九","title":"","text":"本办法自公布之日起施行，有效期3年。株洲市人民政府办公室2025年1月22日印发"}],"interpretations":[{"sectionNo":"二","headline":"先投后股重点支持工业软件、人工智能、北斗、低空经济","who":"株洲市“332”现代产业体系内的创新创业项目；工业软件、人工智能、北斗应用、低空经济等产业项目；创新创业大赛获奖项目；大学生创新创业项目。","materials":[],"window":"原文未明确申报期与支持期限。","where":"原文未明确受理部门","tip":"支持对象限于“332”产业体系项目、大赛获奖项目和大学生创业项目；坚持“投早、投小、投硬科技”。"},{"sectionNo":"三","headline":"先投后股：财政资金先投项目，达条件转股、按适当收益退出","who":"接受“先投后股”支持的科技企业：先投阶段以科技项目形式获得财政资金，用于研发和成果转化，并约定后期转股条件；达到转股条件后财政科技资金转换为企业股权。","materials":[],"window":"转股条件在“先投”阶段约定，达到条件后进入“后股”阶段。","where":"原文未明确受理机构","tip":"“后股”阶段按“适当收益”原则退出；转股条件须在先投阶段约定。"},{"sectionNo":"九","headline":"项目承担企业须对申报材料真实性负责并签订项目合同书","who":"获得“先投后股”支持的项目承担企业；须对申报材料真实性和合法性负责，配合签订《项目合同书》《股权投资协议书》，建立内部项目管理制度。","materials":["《项目合同书》","《股权投资协议书》"],"window":"原文未设期限，按协议约定执行。","where":"原文未明确受理机构","tip":"材料真实性、合法性由企业负责；须配合签订《项目合同书》《股权投资协议书》。"},{"sectionNo":"十","headline":"先投后股支持三类项目：重点产业、双创大赛获奖、大学生创业","who":"属于工业软件、人工智能、以北斗为引领的新一代信息技术、低空经济等产业且具有持续创新能力的创新创业项目；国家、省、市举办的各类创新创业大赛获奖项目；大学生单独创办或联合创办企业的项目。","materials":[],"window":"原文未设申报截止期。","where":"原文未明确受理部门","tip":"三类支持范围可对应不同项目；重点产业项目须具有持续创新能力。"},{"sectionNo":"十一","headline":"申报企业须成立不超3年、创始股东实缴不低于总投入10%","who":"同时具备：具备独立法人资格的科技企业，成立时间不超过3年；申报企业创始股东实缴资金不低于申报项目预期总投入的10%；项目符合株洲市产业发展方向、商业计划及技术路线清晰；相关知识产权权属清晰无争议；项目负责人无违法失信和不良科研诚信记录、未纳入“失信联合惩戒对象名单”、无影响项目实施的未决诉讼。","materials":[],"window":"成立时间不超过3年；拥有经认定登记的技术合同给予优先支持。","where":"原文未明确受理部门","tip":"五项条件须同时具备；拥有经认定登记的技术合同可优先支持。"},{"sectionNo":"十二","headline":"单个项目最高50万元，重大项目一事一议最高200万元","who":"申报“先投后股”的科技项目；单个项目支持资金原则上不超过该成果转化项目预期总投入的50%，支持金额不超过50万元；重大项目可“一事一议”，金额不超过200万元。","materials":[],"window":"原文未明确拨付期，按项目合同约定执行。","where":"原文未明确受理机构","tip":"50万元为常规上限，200万元仅限“一事一议”重大项目；支持额同时受总投入50%约束。"},{"sectionNo":"十三","headline":"财政资金参股不超总股本20%，不成为第一大股东","who":"被投企业；财政科技资金参股比例不超过被投企业总股本20%，且不成为第一大股东，以出资额为限承担有限责任。","materials":["《项目合同书》"],"window":"转股数量与持股比例在先投阶段签订的《项目合同书》中约定。","where":"原文未明确受理机构","tip":"参股比例上限20%且不得为第一大股东；以出资额为限承担有限责任。"},{"sectionNo":"十四","headline":"立项四步：申报、评审、实地考察、立项签约并公示","who":"申报“先投后股”项目的企业；须经项目申报与形式审查入库、专家评审、实地考察形成尽职调查报告、决策联席会研究确定并公示后签约。","materials":["《项目合同书》"],"window":"决策联席会办公室定期发布项目申报指南并组织申报。","where":"决策联席会办公室（设在市科技局）","tip":"入库后仍需评审与实地考察；公示通过后才签订《项目合同书》。"},{"sectionNo":"十五","headline":"签约拨70%、中期评估后拨30%，实施满12个月评估","who":"项目承担企业；签订《项目合同书》后拨付支持资金70%，中期评估通过后拨付30%；项目实施满12个月后开展中期评估；转股期原则上为资金投入后2年内。","materials":["《项目合同书》"],"window":"实施满12个月中期评估；转股期原则上为支持资金投入后2年内，未达条件经审批可延期。","where":"决策联席会办公室","tip":"提前转股的一次性拨付剩余资金；进度滞后可按约定取消后续支持；提前完成验收指标且已转股的不再验收。"},{"sectionNo":"十六","headline":"转股后持股期不超7年，其中后2年为股权退出期","who":"已转股的被投企业；转股后由受托管理机构行使股东权利、开展持股管理与风险防控；持股期内择机退出，方式含股权转让、股东回购、并购重组、挂牌上市、清算等。","materials":["《股权投资协议书》"],"window":"持股期原则上不超过7年，其中后2年为股权退出期。","where":"受托管理机构","tip":"退出方式不限于股权转让、股东回购、并购重组、挂牌上市、清算；持股期上限7年。"},{"sectionNo":"十七","headline":"转股条件：外部投资≥50万元或销售超200万元等","who":"项目承担企业；满足以下之一即达转股条件：引入外部风险投资机构投资且金额不低于50万元（含）；产品或服务实现销售且累计销售收入超过200万元（含）；达到《项目合同书》约定的验收通过条件；其他经决策联席会审批认定的情况。","materials":["《项目合同书》"],"window":"达到条件即认定转股；符合前两项的视为验收通过、不再另行验收。","where":"决策联席会","tip":"四项条件满足其一即可；第（一）（二）项达标视为验收通过，不再组织验收。"},{"sectionNo":"十八","headline":"转股达标最高让渡50%持股，退出收益最高奖50%","who":"达到转股条件且符合情形之一的项目承担企业成果转化核心团队：转股期限内获风险投资且估值在亿元（含）以上；成果转化产品或服务累计销售收入500万元（含）以上；支持资金投入1年（含）以内达到转股条件并转股。","materials":[],"window":"支持资金投入1年（含）以内达到转股条件并转股的，可获让渡。","where":"决策联席会","tip":"让渡比例最高为约定转股持股数量的50%，具体比例由决策联席会审定；单个项目退出收益最高奖励50%。"},{"sectionNo":"十九","headline":"项目终止或违规须退还资金，结余返还专户","who":"项目承担企业；先投阶段项目终止、未通过中期评估或验收的启动核销，结余资金返还“先投后股”资金专户；存在虚报、截留、挪用、冒领、侵占或骗取资金等行为的须退还资金并承担法律责任。","materials":[],"window":"先投阶段项目终止即启动核销；后股阶段出现损失时启动损失核销流程。","where":"决策联席会、受托管理机构","tip":"违规使用资金须退还并依法担责；后股阶段损失核销须第三方专项审计后报批。"}],"sourceUrl":"https://img.zhuzhou.gov.cn/zzcms/DFS//file/2025/03/04/20250304150620169xnl8z3.pdf","sourceNote":"正文来源：官方 PDF 的文字层（非 OCR），已去除页眉页脚与断行，条号按原文保留。","verified":false,"isSample":false,"numberStyle":"clause","bodyVerified":"verbatim","hunan":true},{"id":"zz-hi-skill-training-base-2025","title":"关于申报2025年株洲市示范性高技能人才培训基地建设项目的通知","level":"city","region":"株洲市","issuer":"株洲市人力资源和社会保障局","documentNo":"","publishedAt":"2025-05-26","effectiveAt":"2025-05-26","expiresAt":null,"status":"active","tags":["人才政策","财政奖补"],"audience":["株洲市辖区内职业院校、技工院校、企业职工培训中心和其他职业培训机构"],"summary":"2025年评选不超过5家市级示范性高技能人才培训基地，对立项基地给予100万元经费支持，项目自确定之日起实施、为期两年。申报须成立专门项目管理组、具备技能等级自主评价资质、实习指导教师中高级工或中级职称以上占比不低于40%（“双师型”教师占比不低于50%）、培训场所满足年培训1000人次以上、至少与2家大中型企业建立稳定合作。建设产出要求技能人才年培训量不少于2000人次（其中补贴性技能培训不少于500人次）、高技能人才年培训不少于200人次、年技能等级认定不少于300人次。申报截止2025年6月30日。","sections":[{"no":"一","title":"项目建设目标","text":"围绕我市“3+3+2”现代产业体系，聚焦轨道交通、航空动力、先进硬质材料、新能源装备、陶瓷烟花等重点产业，实施示范性高技能人才培训基地建设，从培养模式、课程设置、师资配备、实训设备、能力评价等方面，加强高技能人才培训基础，提升培养能力水平，推动我市高技能人才队伍高质量发展，促进劳动者技能水平提升与高质量就业。"},{"no":"二","title":"申报范围和评选数量","text":"株洲市示范性高技能人才培训基地建设项目主要面向株洲市辖区内具备高技能人才培训能力的职业院校、技工院校、企业职工培训中心和其他职业培训机构。2025年评选不超过5家示范性高技能人才培训基地。"},{"no":"三","title":"项目实施期限","text":"示范性高技能人才培训基地建设项目从项目确定之日起开始实施，为期两年。"},{"no":"四","title":"申报条件","text":"申报示范性高技能人才培训基地建设项目的单位应具备以下条件：（一）机构健全坚持党的领导，坚持人才培养正确政治方向，遵守国家法律法规，未发生违规违纪事件；成立专门的基地项目管理组，设立配套职能部门，明确部门职能和岗位职责；建立规范的培训管理、财务管理、资产管理、风险管理等制度；每年安排专项经费用于高技能人才培养。（二）师资队伍制定科学合理的师资培养规划和实施方案，重视骨干教师队伍建设，具有稳定的专兼职教师队伍。高级工或中级职称以上实习指导教师占实训教师总数的比例不低于40%或高级工或中级职称以上“双师型“教师占专任教师总数的比例不低于50%。（三）培训能力培训场所和设施设备符合国家建设和安全标准，满足技能人才年培训1000人次以上的需要。培训目标明确，设有1-2个与我市产业发展对接度高的职业（工种），配备与培训项目（职业、工种）、培训形式、培训规模相适应的实训设备。（四）技能竞赛重视职业技能竞赛选手培养，积极组织单位技能人才参与世界、国家、省、市各级职业技能竞赛，并取得良好成绩。根据世赛、国赛、省赛的技术标准和竞赛项目设置，具备满足集训工作任务要求的训练场地、设施设备和工具耗材，愿意承办各类职业技能竞赛。（五）技能评价申报单位须具备技能等级自主评价资质，对自身培养人员进行技能等级评价，合格者取得相应级别的职业技能等级证书。（六）校企合作强化校企对接、产教融合，至少与2家以上大、中型企业建立稳定的合作关系。"},{"no":"五","title":"申报资料","text":"1.申报书：株洲市示范性高技能人才培训基地建设项目申报书（见附件）。2.佐证材料：符合申报条件要求的，需提交有效证明材料的复印件，并装订成册。"},{"no":"六","title":"申报流程","text":"1.单位申报。申报单位携带申报材料，向市人社局职业能力建设科进行申报。2.资料审核。市人社局职业能力建设科对申报资料进行资格初审，初审通过的单位进入现场考察。3.专家评审。召开综合评审会议，专家结合考察情况进行投票表决，按得票多少排序确定支持项目名单。4.公示确定。将确定支持项目名单在部门网站进行公示，公示期为5个工作日。5.资金拨付。对立项的示范性高技能人才培训基地给予100万元经费支持。"},{"no":"七","title":"项目产出要求","text":"示范性高技能人才培训基地建设项目应形成以下项目产出：（一）构建职业技能培训体系项目实施一年后，围绕备案的职业（工种），从培训模式、课程设置、师资建设、培训设备等方面，构建成较为完备、系统的高技能人才培训体系。（二）提升高技能人才培养能力通过实施建设项目，增强规模化、系统化、个性化高技能人才培训能力，大规模开展就业技能培训、企业职工岗位技能培训（含技师培训、企业新型学徒制培训）、项目制培训。1.技能人才年培训量不少于2000人次，其中补贴性技能培训不少于500人次。2.高技能人才年培训量不少于200人次。3.积极参与省级重点培训项目（“四单”培训）试点工作。4.技能竞赛参与人数逐年增加，市级及以上竞赛项目获奖数量、等级逐年提升。5.积极面向社会开展第三方等级认定评价工作，年组织技能等级认定人数不少于300人次。（三）总结技能人才培养经验通过实施建设项目，总结高技能人才培训的科学方法，提炼高技能人才培训基地建设的经验和做法，为基地建设和规范化、规模化培养高技能人才提供科学依据。"},{"no":"八","title":"工作要求","text":"1.思想重视。各县区人社局要高度重视示范性高技能人才培训基地建设工作，积极宣传发动，鼓励本地区符合条件的单位积极申报。各申报单位要严格按照本通知规定的条件进行申报，要将建设项目作为高技能人才培养的重要内容，纳入单位发展规划。2.严格把关。各县区人社局在推荐时要认真审查把关，评审专家要严格评审，确保公平公开公正。对申报中存在弄虚作假等违法违规行为的单位，一经核实，取消资格，依法追缴支持经费，并纳入信用管理范畴；造假单位不再享受株洲市政府各类财政支持；涉嫌犯罪的，依法移送司法机关追究刑事责任。3.绩效评价。示范性高技能人才培训基地建设项目应按照备案的建设方案实施建设，原则上不作调整。申报单位须按建设方案提交年度工作报告。项目实施满两年后，由申报单位委托会计事务所等第三方机构，按照市人社局发布的申报通知中项目产出要求以及申报单位申报时呈报的申报书中规划的项目建设方案进行验收，并将项目验收报告报市人社局。若项目验收不合格，市人社局将依法追缴支持建设资金。4.资金使用。各项目单位要按照《湖南省就业补助资金管理办法》有关规定，严格加强对项目资金管理，实行专款专用，单独建账，确保资金用于示范性高技能人才基地，重点开展高技能人才研修提升培训、高技能人才评价、职业技能竞赛、高技能人才课程研发、高技能人才成果交流等活动。按“谁使用，谁负责”的原则，各项目单位对资金使用管理过程中相关资料的真实性、合法性负责。资金不得用于以下支出：1.办公用房建设支出；2.职工宿舍建设支出；3.购置交通工具支出；4.发放工作人员津贴补贴等方式；5.“三公”经费支出；6.普惠金融项下创业担保贷款贴息及补充创业担保贷款基金相关支出；7.部门预算已安排支出；8.法律法规禁止的其他支出。5.其他要求。各申报单位需同步报送与纸质资料相同的电子版文件。项目申报截至日期为2025年6月30日，逾期将不予受理。"}],"interpretations":[{"sectionNo":"二","headline":"株洲市评选示范性高技能人才培训基地，2025年不超过5家","who":"株洲市辖区内具备高技能人才培训能力的职业院校、技工院校、企业职工培训中心和其他职业培训机构。","materials":[],"window":"2025年度评选，评选不超过5家。","where":"株洲市人力资源和社会保障局","tip":"2025年名额上限5家，是上限而非保底数量。"},{"sectionNo":"三","headline":"基地建设项目从确定之日起实施，为期两年","who":"经认定的株洲市示范性高技能人才培训基地建设项目单位。","materials":[],"window":"从项目确定之日起实施，为期两年。","where":"株洲市人力资源和社会保障局（项目管理）","tip":"实施期两年，期满须按项目产出要求验收。"},{"sectionNo":"四","headline":"申报基地须满足师资占比、年培训1000人次等六项条件","who":"株洲市辖区内申报单位须同时具备：机构健全、未发生违规违纪事件、每年安排专项经费；高级工或中级职称以上实习指导教师占实训教师总数不低于40%，或双师型教师占专任教师总数不低于50%；培训场所满足年培训1000人次以上；具备技能等级自主评价资质；至少与2家以上大、中型企业建立稳定合作关系。","materials":[],"window":"申报时具备；原文未设条件有效期。","where":"株洲市人力资源和社会保障局职业能力建设科","tip":"六项条件须同时满足；技能等级自主评价资质和2家企业合作是硬门槛。"},{"sectionNo":"五","headline":"申报需提交申报书与装订成册的佐证材料复印件","who":"申报株洲市示范性高技能人才培训基地建设项目的单位。","materials":["株洲市示范性高技能人才培训基地建设项目申报书（见附件）","符合申报条件要求的有效证明材料复印件（装订成册）"],"window":"按申报通知提交，截止时间为2025年6月30日。","where":"株洲市人力资源和社会保障局职业能力建设科","tip":"佐证材料须为有效证明材料复印件并装订成册。"},{"sectionNo":"六","headline":"基地立项后给予100万元经费支持，公示5个工作日","who":"向市人社局职业能力建设科申报，经资格初审、现场考察、专家评审投票排序并公示的申报单位。","materials":["申报材料（含申报书与佐证材料）"],"window":"公示期5个工作日。","where":"市人社局职业能力建设科（申报与初审）；部门网站（公示）。","tip":"按专家投票得票多少排序确定支持名单，不是达条件即立项。"},{"sectionNo":"七","headline":"基地年培训不少于2000人次，高技能人才不少于200人次","who":"经立项的示范性高技能人才培训基地；须达到年培训2000人次（其中补贴性技能培训500人次）、高技能人才年培训200人次、年技能等级认定300人次等产出。","materials":[],"window":"实施一年后构建培训体系；项目实施满两年后验收。","where":"株洲市人力资源和社会保障局（验收）","tip":"除培训量外，还须年组织技能等级认定不少于300人次，并参与省级四单培训试点。"},{"sectionNo":"八","headline":"申报截止2025年6月30日，逾期不予受理；资金须专款专用","who":"申报单位及推荐单位；须按备案建设方案实施，按建设方案提交年度工作报告，并接受第三方验收。","materials":["与纸质资料相同的电子版文件","年度工作报告","项目验收报告（委托会计师事务所等第三方机构出具）"],"window":"项目申报截止日期为2025年6月30日，逾期不予受理；实施满两年后验收。","where":"株洲市人力资源和社会保障局；验收由申报单位委托会计师事务所等第三方机构。","tip":"资金不得用于办公用房建设、职工宿舍建设、购置交通工具、发放工作人员津贴补贴、三公经费等八类支出。"}],"sourceUrl":"http://rsj.zhuzhou.gov.cn/c923/20250526/i2369483.html","derivedFrom":"official","sourceNote":"2026-11-24 取自株洲市人社局门户「政务公开>信息公开目录>法定主动公开内容>通知公告」栏目原文页；正文为页面内嵌 HTML 全文（非附件），申报书以 .doc 附件另行发布。页面未标注发文字号（属年度申报通知），落款株洲市人力资源和社会保障局2025年5月26日。 2026-11-24 收录：与官方页面逐句比对，命中 49/49 句（100%），关卡判定「verbatim」。 有效期依据：第八部分第5项（其他要求）","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"zz-incubator-2026","title":"株洲市人力资源和社会保障局、株洲市科学技术局、株洲市财政局关于印发《株洲市市级大学生创业孵化基地认定管理办法（试行）》的通知","level":"city","region":"株洲市","issuer":"株洲市人力资源和社会保障局、株洲市科学技术局、株洲市财政局","documentNo":"株人社发〔2026〕7号","publishedAt":"2026-08-04","effectiveAt":null,"expiresAt":null,"status":"active","tags":["认定资质","创业补贴","场地支持"],"audience":["大学生创业孵化基地","创业孵化载体运营机构","大学生创业者"],"summary":"对市级大学生创业孵化基地实行认定管理：在孵实体不少于 15 家、孵化面积 1500 平方米以上方可申报；经认定的基地按每家每月 150 元、每吸纳 1 家实体 2800 元的标准给予补助，并按在孵人数分档给予每年 4.2 万至 12.6 万元的创业服务补贴，单个基地每年合计不超过 40 万元。","sections":[{"no":"一","title":"","text":"为全面贯彻落实省委、省政府关于支持大学生创业“七个一”的工作要求，持续深入推进我市创业孵化基地工作，建设一批有特色、功能强的市级大学生创业孵化载体，进一步推进大学生创新创业。根据《湖南省人民政府办公厅关于印发〈湖南省大力支持大学生创业若干政策措施〉的通知》（湘政办发〔2024〕42号）、《湖南省人力资源和社会保障厅湖南省教育厅湖南省科学技术厅湖南省财政厅关于印发〈湖南省省级大学生创业孵化基地认定管理办法（试行）〉的通知》（湘人社规〔2024〕28号）、《株洲市人民政府办公室关于印发〈株洲市进一步支持大学生创新创业若干措施〉的通知》（株政办发〔2025〕11号）精神，制定本办法。"},{"no":"二","title":"","text":"株洲市市级大学生创业孵化基地建设坚持政府引导、社会参与、市场运营、择优认定的原则，以在校大学生、高校应届毕业生等群体为主要孵化对象，以培育创业实体、促进创业带动就业为目标，具有滚动孵化功能，发挥示范引领和辐射带动作用。"},{"no":"三","title":"","text":"申报市级大学生创业孵化基地须达到以下标准：（一）以创业孵化为主营业务的各类创业孵化载体，无违法违规记录。（二）在孵实体数量。在孵实体数量不少于15家，其中入孵的在校大学生和毕业5年内（含）高校毕业生创业实体数量不少于1/2。或者扶持创业及带动就业的人员不少于40人，其中在校大学生和毕业5年内（含）高校毕业生人数不少于总人数的1/3。入孵创业实体孵化周期不超过5年。（三）孵化场地规模。孵化面积1500平方米（含）以上，拥有必要创业孵化场所和基础设施。应设立苗圃工位或独立办公房两种办公场所。其中，免费提供给大学生和毕业5年内（含）高校毕业生创业项目的场地不低于孵化面积的30%。（四）创业孵化服务。配备不少于2名工作人员负责基地运营管理，为入孵实体申请各项创业扶持政策，提供创业指导、创业培训、商务代办、投融资等服务。配备不少于3名创业导师，为创业者提供各类创业指导。（五）服务和管理。各项管理制度健全，制定孵化服务目录清单，有明确的入驻和退出机制。"},{"no":"四","title":"","text":"市级大学生创业孵化基地坚持公平公正、自愿申报、择优推荐的原则，参照市级创业孵化基地管理要求，每年认定或复评一次。"},{"no":"五","title":"","text":"申报认定程序（一）自主申报。符合条件的市级大学生创业孵化基地向注册地的人力资源社会保障部门申报，各县市区人力资源社会保障部门牵头对照基本条件，联合相关部门对创业孵化基地进行考评，择优向市人力资源社会保障部门推荐，并提交以下材料：1.株洲市市级大学生创业孵化基地申报表（附件1）；2.在孵创业实体名册（附件2）；3.其他相关佐证资料。（二）填报信息。按照全省创业孵化基地信息化管理的要求，申报单位在“湖南人社一体化业务管理系统”中录入相关信息，保证数据真实准确完整。（三）组织核查。市人力资源社会保障部门组织人员对申报的孵化基地资料进行审核，并组织相关部门实地走访。（四）公示认定。对拟认定的市级大学生创业孵化基地，在市人力资源社会保障部门官方网站进行公示。对公示无异议的，由市人社、市科技两部门联合发文认定为株洲市市级大学生创业孵化基地。"},{"no":"六","title":"","text":"政策支持（一）补贴标准1.对新挂牌认定的市级大学生创业孵化基地给予10万元一次性培育奖补，所需资金从就业专项资金中列支。2.市级大学生创业孵化基地每吸纳1家创业实体入孵，按每家每月150元的标准给予基地补助；3.创业实体在孵期间成功注册市场主体的（在孵创业实体入孵前未注册市场主体），按2800元每家给予基地一次性补助；同一创业孵化基地中的同一在孵创业实体注册多个市场主体的，只能计算1家，不重复补贴。4.创业孵化基地内扶持大学生或毕业5年内（含）高校毕业生创业或就业的，超过40人的按4.2万元每年的标准给予基地补助，超过80人的按8.4万元每年的标准给予基地补助，超过120人的按12.6万元每年的标准给予补助。每个基地每年享受创业服务补助总额最高不超过40万元，按照就业专项资金使用的有关规定，主要用于开展创业孵化基地服务项目清单中的有关服务，以及孵化基地服务能力建设和提升。对同时认定为省、市级创业孵化基地，省、市级大学生创业孵化基地其中两种及以上的，每年享受的创业服务补贴就高不就低，不重复享受。（二）各级人力资源社会保障部门可通过政府购买创业服务成果的方式，支持市级大学生创业孵化基地开展创业沙龙、创业讲堂、创业训练营、项目展示交流等创业活动，为创业者搭建资源对接的平台。所需资金从所在地就业专项资金中列支。（三）推动政府扶持政策向孵化基地集中。各级人力资源社会保障、科技、财政部门要加强政策的宣传和解读，主动为大学生创业孵化基地内的在孵项目落实相关政策和服务，在补贴、项目、课题、资金申报上加大支持力度。允许孵化基地按照各部门要求，组织在孵企业统一收集、统一申报，缩短审批时间。"},{"no":"七","title":"","text":"孵化服务。市级大学生创业孵化基地应主动为大学生创业项目提供以下服务：（一）核心服务1.提供项目开发服务。统一组织创业项目路演，对项目可行性、筹备运作情况、融资能力与资金情况、创业团队情况、产业导向情况进行综合评估。协助入驻实体在市场调研、制定创业计划、组建创业团队等方面提供服务和帮助。2.提供项目对接服务。推荐在孵项目纳入全省大学生创业项目库管理，指导大学生创业项目及时、动态更新数据。为在孵实体搭建对接平台，助其引资、引智、引才。3.提供项目展示服务。为在孵实体提供宣传推广、品牌打造等服务，组织其参加各类创业创新赛事活动。（二）成长服务4.提供创业培训服务。和创业培训机构合作，组织在孵实体经营管理人员开展创业培训，为在孵项目提供多元化的创业培训课程，不断提升大学生创业能力。5.提供融资担保服务。积极协助在孵实体申请创业担保贷款，为优质在孵实体提供担保。6.提供创业指导。与优秀大学生创业导师合作，推动在孵项目和大学生创业导师建立“一对一”帮扶关系。为在孵实体提供创业筹备、创业运营、创业发展等方面的指引。7.提供人才招聘。积极对接本地人力资源市场，为在孵企业提供岗位发布、人才招聘等就业服务。（三）营商环境服务8.协助提供工商、法务等相关服务。协助在孵实体办理工商登记、变更、注销、年审等相关业务。提供法律咨询、合同审查等基础法律、法务服务，协助在孵实体维护自身合法权益。9.协助提供税务、财务管理等相关服务。协助在孵实体办理税务登记、变更、注销、年审等相关服务。提供财务管理支持，协助在孵实体降低企业经营成本。10.协助宣传、办理政府性补贴。广泛收集本地各部门出台的涉及支持在孵化实体的发展运营奖励性、补贴性政策，以及税费减免政策，建立政策清单，加强政策宣讲，为在孵化实体申领和享受相关政策提供指导和帮助。（四）保障性服务11.租金和管理费用减免或优惠。制定入驻相关优惠政策，为符合条件的入驻实体减少或免除租金、管理费等相关费用。12.提供管理咨询。为在孵实体提供生产、运营、销售、人力资源、品牌和网络建设等方面的咨询服务。13.提供事务代理。为在孵实体提供专利申请、商标注册、人事代理等相关代理服务。14.提供后勤保障。为在孵实体提供公共配套的硬件设施（茶水间、洽谈区、会议室、路演厅等），保障在孵实体的水、电、网的正常安全使用，提供保洁、保安、停车等后勤服务。15.其他专项服务。创业孵化基地还可根据园区特色、定位提供其他专项服务。（五）组织活动开展。制定创业服务活动年度计划，定期组织项目路演、创业沙龙、训练营等创业服务活动，积极组织在孵项目参加各类创业大赛，积极为创业项目搭建资源对接平台。（六）加强合作交流。加大与其他各类创业孵化平台、产业园区的合作交流，建立与其他孵化基地的项目推介、输送机制，为大学生创业项目提供持续孵化服务。"},{"no":"八","title":"","text":"市人力资源社会保障部门负责市级基地的工作指导、组织协调、认定核查等；各县市区人力资源社会保障部门负责本地市级基地的推荐申报、服务指导、日常管理等。推荐认定环节做到公开透明、公平公正，坚决杜绝优亲厚友、虚报冒领等行为。对存在徇私舞弊、套取骗取、贪污挪用等违法违纪行为的，依照法律法规和有关规定严肃追究责任。"},{"no":"九","title":"","text":"依托“湖南人社一体化业务管理系统”对市级大学生创业孵化基地实行动态管理。市人力资源社会保障部门会同相关部门不定期对市级大学生创业孵化基地进行走访指导。"},{"no":"十","title":"","text":"市级大学生创业孵化基地出现下列情形之一的，撤销资格：（一）建设单位和运营单位已注销、吊销营业执照的。（二）未按要求申请复评或复评未通过的。（三）对孵化效果欠佳、服务能力不足、工作配合度和群众满意度不高，或相关部门提出处理意见后未能及时整改的。（四）违法经营和造成重大安全、重大质量事故的。（五）其他应当撤销市级基地资格的。"},{"no":"十一","title":"","text":"加强项目绩效评价工作，完善评价指标体系，确保项目资金使用效益。加强评价结果运用，作为政策优化调整的重要依据。"},{"no":"十二","title":"","text":"本办法自公布之日起执行，有效期两年。各县市区可根据本地实际，参照本办法自行制定县（市、区）级大学生创业孵化基地认定管理办法。附件：1.株洲市市级大学生创业孵化基地申报表2.在孵创业实体名册"}],"interpretations":[{"sectionNo":"三","headline":"市级孵化基地：在孵不少于15家、面积1500平方米以上","who":"以创业孵化为主营业务、无违法违规记录的各类创业孵化载体；在孵实体不少于15家且大学生及毕业5年内高校毕业生实体不少于1/2，或扶持创业及带动就业不少于40人且上述大学生不少于1/3；孵化周期不超5年；面积1500平方米以上，免费给大学生场地不低于30%；配2名运营人员、3名创业导师，制度健全。","materials":[],"window":"入孵创业实体孵化周期不超过5年；基地每年认定或复评一次","where":"注册地人力资源社会保障部门（申报程序见第五条）","tip":"在孵实体数量不达标时，可用带动就业不少于40人且大学生占1/3替代；免费场地不低于30%"},{"sectionNo":"四","headline":"市级大学生创业孵化基地每年认定或复评一次","who":"符合条件的市级大学生创业孵化基地申报单位","materials":[],"window":"每年认定或复评一次","where":"注册地人力资源社会保障部门（申报程序见第五条）","tip":"坚持自愿申报、择优推荐；认定和复评均参照市级创业孵化基地管理要求"},{"sectionNo":"五","headline":"市级孵化基地申报：3类材料，报注册地人社部门","who":"符合条件的市级大学生创业孵化基地（以创业孵化为主营业务、无违法违规记录）","materials":["株洲市市级大学生创业孵化基地申报表（附件1）","在孵创业实体名册（附件2）","其他相关佐证资料"],"window":"按年度申报（每年认定或复评一次），具体截止时间原文未列","where":"湖南人社一体化业务管理系统；注册地人力资源社会保障部门","tip":"申报单位须在系统录入信息并保证真实准确完整；公示无异议后由市人社、市科技联合发文认定"},{"sectionNo":"六","headline":"市级孵化基地：10万元奖补，年补最高40万元","who":"新挂牌认定的市级大学生创业孵化基地；吸纳创业实体入孵的基地；在孵实体成功注册市场主体的基地；扶持大学生或毕业5年内高校毕业生创业就业超40人、80人、120人的基地。","materials":[],"window":"一次性培育奖补；入孵补助按月计；创业服务补助每年核定，每基地每年最高40万元","where":"就业专项资金列支；各级人力资源社会保障部门（原文未列申报窗口）","tip":"同一在孵实体注册多个市场主体只计1家；省、市级两种及以上认定就高不就低、不重复享受"},{"sectionNo":"七","headline":"市级孵化基地须提供15项服务，含租金减免和融资对接","who":"经认定的市级大学生创业孵化基地及其在孵大学生创业项目","materials":[],"window":"持续提供；每年制定创业服务活动年度计划","where":"基地内（原文未列具体窗口）","tip":"服务含项目开发、创业培训、融资担保、工商税务代办、租金减免等；在孵项目可向基地申请"},{"sectionNo":"十","headline":"市级孵化基地出现注销执照等情形将被撤销资格","who":"已认定的市级大学生创业孵化基地","materials":[],"window":"动态管理；出现所列情形即撤销资格","where":"市人力资源社会保障部门（动态管理）","tip":"未按要求申请复评或复评未通过、整改不到位、违法经营或重大事故均可撤销资格"}],"sourceUrl":"https://img.zhuzhou.gov.cn/zzcms/DFS//file/2026/08/06/202608061011075181jtkhr.pdf","sourceNote":"2026-11-22 取自株洲市人民政府门户原文页（https://www.zhuzhou.gov.cn/c19478/20260807/i2519402.html）所挂 PDF 附件；正文为扫描件，已按《zz-incubator-2026.checked.txt》校对单逐页对照原件修正。 正文来源：扫描版 PDF（11 页，无文字层），经 Windows OCR 逐页识别后整理；已去除字符间空格与页眉页脚，条号按原文保留。个别字词、标点在页边界处可能被截断或识别有误，引用前请核对官方原件。","verified":false,"isSample":false,"numberStyle":"clause","bodyVerified":"ocr","hunan":true},{"id":"zz-industry-fund-2024","title":"株洲市财政局关于印发《株洲市产业引导基金管理办法》的通知","level":"city","region":"株洲市","issuer":"株洲市财政局","documentNo":"株财发〔2024〕1号","publishedAt":"2024-07-08","effectiveAt":null,"expiresAt":null,"status":"active","tags":["专项资金","融资支持"],"audience":["产业引导基金管理机构","子基金管理人","市内企业"],"summary":"设立株洲市产业引导基金，以参股子基金、直接股权投资等方式引导社会资本投向本地重点产业；办法对基金设立审批、出资比例、投资方向、让利与退出、风险控制、绩效评价及监督管理作出规定。","sections":[{"no":"一","title":"","text":"为深入推进培育制造名城发展战略，创新财政资金投入方式，提高资金使用效益，规范基金运作，根据《湖南省财政厅关于印发〈湖南省省级政府引导基金体系改革实施方案〉的通知》（湘财办〔2023〕20号）等有关政策规定，结合我市实际，制定本办法。"},{"no":"二","title":"","text":"株洲市产业引导基金是指经市人民政府同意，由市财政和引导基金出资人代表出资设立的母基金及与社会资本共同出资设立的子基金，以股权投资方式，采用市场化手段，发挥财政资金杠杆作用，引导社会资本共同投资于产业发展的政策性引导基金。产业引导基金立足于服务株洲、服务产业，按照“政府引导、市场主导、专业管理、防范风险”的原则，通过与专业投资机构、金融机构和社会资本共同设立子基金，扶持产业发展。"},{"no":"三","title":"","text":"严格控制产业引导基金数量，原则上只设立一支产业引导类母基金，母基金下设各类子基金。"},{"no":"四","title":"","text":"产业引导基金由市人民政府整合各类扶持产业发展的专项资金、滚动投资收益及其他政府性资金归集出资，纳入年度财政预算管理，并视基金投放情况分期出资。"},{"no":"五","title":"","text":"拓宽基金出资渠道。通过推进竞争性领域财政资金“拨改投”改革、加大预算新增和统筹力度、盘活国有“三资”收入、整合市级相关专项资金、财政出资滚动投入等方式，专项用于壮大产业引导基金。"},{"no":"六","title":"","text":"产业引导母基金存续期限为15年，期满后可根据需要按程序协商延期。子基金存续期限一般不超过8年，即投资期不超过5年、退出期不超过3年，具体应当在基金章程或合伙协议中予以明确。"},{"no":"七","title":"","text":"产业引导基金及子基金要主动参与推动培育制造名城发展战略，投资株洲市的优势支柱产业和战略性新兴产业。"},{"no":"八","title":"","text":"市产业引导基金投资决策委员会（以下简称投决会）由市人民政府常务副市长任主任，分管工业工作的副市长任副主任，市政府办、市发展改革委、市科技局、市工信局、市财政局、市人社局、市农业农村局、市商务局、市国资委等为组成单位。"},{"no":"九","title":"","text":"投决会下设市产业基金管理办公室（以下简称基金办），办公室主任由市财政局局长担任，办公室副主任由市财政局分管副局长担任，办公室具体职责由市财政局承担。"},{"no":"十","title":"","text":"投决会的主要职责：（一）审定引导基金相关制度；（二）审定母基金设立方案；（三）听取引导基金年度运行情况；（四）审议引导基金其他重大事项。（五）投决会对议案的审议采取票决制，少数服从多数。"},{"no":"十一","title":"","text":"基金办的主要职责：（一）牵头拟订引导基金相关制度；（二）牵头组织投决会成员单位规范性审查母基金设立方案并提请投决会审定；（三）审定子基金设立年度计划；（四）牵头组织投决会成员单位规范性审查子基金设立方案；（五）组织开展引导基金考核评价工作；（六）落实投决会的决议及其他交办事项。"},{"no":"十二","title":"","text":"产业引导基金实行委托管理。产业引导基金受托管理机构由基金办依法从具有一定规模、较丰富基金管理经验和良好基金管理业绩和符合本办法规定的企业中择优选择，按程序招募，报投决会审定，并依法签订委托管理协议，明确双方权利、义务与责任。"},{"no":"十三","title":"","text":"受托管理机构的职责：（一）根据本办法拟制子基金管理细则及有关操作规程，报投决会审定；（二）根据投决会要求，建立、完善子基金评审专家库和株洲市可投资项目备选库；（三）对子基金社会出资人和子基金管理机构开展尽职调查，进行入股谈判；（四）子基金设立方案报投决会审定后，代表产业引导基金与其他社会出资人签订子基金章程或合伙协议；（五）以出资额为限，代表产业引导基金对子基金行使出资人职责，可以向子基金委派董事、监事、理事或投资决策委员会委员等，监督子基金运作；（六）管理产业引导基金参股子基金形成的股权，及时将所管理的股权退出情况报基金办，及时将产业引导基金参股子基金的分红和退出资金（含本金和收益）上缴国库；（七）子基金新投资项目在投资决议后一周内，及时报基金办备案；（八）定期报送产业引导基金运行报告，及时报送子基金重大情况，并于每个会计年度结束后3个月内提交经会计师事务所审计的年度财务报告；（九）接受相关部门、基金办或其委托的第三方机构对产业引导基金的审计检查；（十）办理基金办交办的其他事项。受托管理机构未尽职履责造成损失的，应当承担赔偿责任。"},{"no":"十四","title":"","text":"产业引导基金资金实行银行第三方托管，托管银行由受托管理机构按照公平竞争原则，从具有基金托管资格的银行中择优选择，并依法签订托管协议。"},{"no":"十五","title":"","text":"每年1月31日前，产业引导基金托管银行应向受托管理机构报送上一年度资金收支托管报告，经受托管理机构审核、汇总后及时报基金办备案。产业引导基金出现资金挪用、与托管协议不符等异常情况时，产业引导基金托管银行应及时向基金办报告。"},{"no":"十六","title":"","text":"产业引导类母基金对单个子基金的出资比例不超过母基金资产总值的20%、不超过子基金认缴规模的30%，市、区两级出资总额（含财政和国有企业出资）原则上不超过子基金认缴规模的50%，且不能成为子基金第一大出资人。"},{"no":"十七","title":"","text":"受托管理机构按规定应收取的产业引导基金管理费用，原则上按照不超过产业引导基金实际出资子基金额度扣除已退出项目投资本金后实际投资额的0.5%核定。特别优秀的头部基金管理机构申请设立子基金的，子基金管理费可按照“一事一议”的原则报基金办审批。对于运营管理效益好、带动社会出资比例高、导入产业项目多的出资部分，可适当提高管理费用核定比例。产业引导基金管理费用按年从产业引导基金中支付，当年支付上年，主要用于引进外部创投机构、子基金组建方案评审以及日常开支等。"},{"no":"十八","title":"","text":"受托管理机构应加强对产业引导基金参股子基金的管理，每年度依据管理细则及有关操作规程，对子基金的投资进度、经营业绩、投资于市内资金比例、信用评价等情况进行考核，并将考核结果报基金办。考核结果较差的，受托管理机构应责成子基金限期进行整改。"},{"no":"十九","title":"","text":"支持基金管理人依法依约履行基金管理职责，按市场化专业化方式推进基金日常管理、项目投资、投后管理等，政府部门不干预基金的具体运营。"},{"no":"二十","title":"","text":"申请设立子基金应当满足以下要求：（一）具备《中华人民共和国公司法》《中华人民共和国合伙企业法》等法律法规规定的条件；（二）主要发起人、子基金管理机构、托管金融机构已基本确定，并草签发起人协议、子基金章程或合伙协议，其他出资人基本落实，保证资金按进度及时到位，所有出资人均以货币形式出资；（三）子基金对单个项目投资时，原则上不得控股和成为第一大股东；（四）为体现产业引导基金引导作用，子基金对株洲市的资金投放比例不得低于产业引导基金出资比例的1.5倍。（五）拟设立子基金总规模中除产业引导基金和国家、省级政府性出资部分以外的全部资金（以下统称非政府性资金）达成募集意向后，由出资人提供出资承诺函、募资兜底承诺函等材料；同时，在子基金运作期间，产业引导基金须在上述非政府性资金完成出资后，方可履行出资义务。"},{"no":"二十一","title":"","text":"子基金设立程序：（一）各区县市人民政府（管委会）、市直行业主管部门、基金管理机构等向产业引导基金受托管理机构提出申请，申请内容包括子基金设立方案、管理团队简介、项目储备情况等资料；（二）受托管理机构收到申请资料后进行初审，草拟《子基金设立方案（初稿）》报基金办审核，并由基金办出具书面审核意见，基金办认为必要时，可组织相关单位召开专题会议，对子基金初步设立方案进行专题审查、研究；（三）受托管理机构根据基金办审核意见，对相关方、相关情况开展尽职调查，并与基金管理机构、子基金出资各方就合作协议等进行协谈，形成《子基金设立方案（建议稿）》报基金办；（四）基金办复核后形成《子基金设立方案（送审稿）》，提请投决会对子基金组建方案进行评审，并从专家库中选聘有关专家（不得选聘子基金投资各方关联人员）参加评审，专家不参与评审表决，但其发表意见可作为评审、审批子基金的参考依据；（五）《子基金设立方案》评审通过后，由受托管理机构对子基金社会出资人的基本信息、出资比例等情况在有关媒体公示，公示无异议的，由基金办将《子基金设立方案》呈报投决会审批；（六）受托管理机构根据投决会审批意见与各出资人签订子基金合伙协议，按市场化方式参与子基金具体组建和运作。"},{"no":"二十二","title":"","text":"子基金存续期内，最终认定返投的企业必须在株洲市依法登记注册并纳税，具体包括：（一）子基金投资机构直接投资的株洲市内企业（即在株洲市依法登记注册并纳税的企业，以下简称存量企业）；（二）子基金投资机构投资的株洲市外企业（即不在株洲市依法登记注册并纳税的企业），该企业将注册地迁至株洲市或在株洲市注册成立子公司（以下简称增量企业），注册成立子公司的，应将生产基地等落地至株洲市。"},{"no":"二十三","title":"","text":"基金存续期内，返投金额认定标准如下：（一）存量企业按直接投资株洲市内企业（即在株洲市依法登记注册并纳税的企业）的投资额认定返投金额。（二）增量企业按以下3项中金额最高值认定返投金额：1.增量企业的实缴注册资本；2.增量企业在株洲市的累计投资额（撤回投资的不纳入计算）；3.增量企业在株洲市产生的市级税收总额。"},{"no":"二十四","title":"","text":"引导撬动社会资本。积极与优秀基金管理公司、产业链龙头企业、重点园区及高校等合作设立子基金，广泛募集社会资本，建立健全多元化出资结构，着力提高财政资金杆杠放大倍数。引导市场化基金投资我市优质标的。鼓励基金管理人、被投企业与银行、保险、担保等金融机构开展投贷联动、投保联动、投担联动、投债联动等创新业务。"},{"no":"二十五","title":"","text":"子基金管理机构应当具备以下条件：（一）在中国大陆境内注册且在中国证券投资基金业协会登记备案，实缴注册资本不低于1000万元人民币，有较强的资金募集能力。（二）管理和运作规范，具有严格合理的项目遴选机制、投资决策程序和风险控制机制；（三）其核心管理团队至少有3名具备3年以上股权投资或基金管理工作经验的专职高级管理人员，且高管人员已取得良好的管理业绩，有3个以上基金投资成功案例；（四）应对子基金认缴出资，出资比例不低于1%，具体出资比例及亏损弥补办法在子基金章程或合伙协议中约定；（五）管理机构及其工作人员在最近三年无重大违法行为。"},{"no":"二十六","title":"","text":"同等条件下以下2类基金管理机构优先合作：（一）募资能力强、投资管理能力强、产业招引能力强的头部基金管理机构；（二）行业龙头企业设立的基金管理机构。"},{"no":"二十七","title":"","text":"子基金管理机构的管理年费标准应在子基金章程或合伙协议中明确。"},{"no":"二十八","title":"","text":"子基金投资于株洲市区域内项目的，经基金管理办公室审批同意后，产业引导基金可按出资额享受的子基金净收益的50%让渡给子基金其他合伙人；经基金投资决策委员会审批同意后，可按不高于出资额享受的子基金净收益的70%的比例让渡。子基金投资于株洲市区域外项目的，产业引导基金不进行收益让渡。"},{"no":"二十九","title":"","text":"子基金管理机构及其核心管理团队在子基金成功募集、设立并投出总额的70%以上时，方可受托管理其他与该子基金有竞争关系的基金。"},{"no":"三十","title":"","text":"经审批设立的子基金，其社会出资人应及时按投资方案或协议履行出资及其他义务。首期出资原则上不得低于承诺出资额的20%，全部出资应在基金投资期内到位。"},{"no":"三十一","title":"","text":"子基金闲置资金只能存放托管银行或购买保本型理财产品。"},{"no":"三十二","title":"","text":"子基金未按规定使用资金或从事禁止业务的，受托管理机构应要求子基金限期整改。"},{"no":"三十三","title":"","text":"子基金应当在章程或合伙协议中明确下列事项：（一）子基金的其他股东不先于产业引导基金退出；（二）其他情况。如子基金到期、在规定期限社会出资未到位或未开展投资业务等情况下产业引导基金可以退出。"},{"no":"三十四","title":"","text":"财政部门应与其他出资人在投资基金章程中约定，有下述情况之一的，政府出资可无需其他出资人同意，选择提前退出：（一）投资基金方案确认后超过一年，未按规定程序和时间要求完成设立手续的；（二）政府出资拨付投资基金账户一年以上，基金未开展投资业务的；（三）基金投资领域和方向不符合政策目标的；（四）基金未按章程约定投资的；（五）其他不符合章程约定情形的。"},{"no":"三十五","title":"","text":"产业引导基金可以通过转让、清算、并购、上市、重组等方式退出，退出后的本金和收益缴入国库，可继续作为产业引导基金滚动使用。受托管理机构不得截留、挪用产业引导基金退出后的本金和收益或将其拨入其他账户。"},{"no":"三十六","title":"","text":"基金办根据受托管理机构投后管理的报告，对子基金未按协议约定开展投资业务的和未及时完成相关监管部门注册登记的，协调子基金管理机构进行整改；协调无效的或子基金的运作出现违法违规、偏离政策导向等情况时，产业引导基金应按协议终止与子基金管理机构的合作，并由子基金管理机构承担相应违约责任。"},{"no":"三十七","title":"","text":"市财政局根据上级财政部门相关规定对产业引导基金进行绩效管理。评价结果与管理费支付等挂钩。"},{"no":"三十八","title":"","text":"市审计局对产业引导基金使用运行情况依法进行审计检查。"},{"no":"三十九","title":"","text":"对弄虚作假骗取产业引导基金投资，或不按规定用途使用、截留挪用、挥霍浪费投资基金等违法违规行为，由有权机关按有关法律法规进行处理，构成犯罪的，依法追究刑事责任。"},{"no":"四十","title":"","text":"建立尽职免责机制。在产业引导基金运营管理过程中，未能实现预期目标或出现偏差，但有关单位和个人认真履行职责，未牟取私利且无重大过失的，可免予追究相关单位和个人投资决策失误责任。在巡察、审计、财会监督以及主管部门考核时，基于基金生命周期进行整体评价，不对单个基金或单个投资子项目造成的投资亏损进行评定。"},{"no":"四十一","title":"","text":"防范基金风险。基金管理人应建立规范高效的基金治理结构和内控体系，执行报告和信息披露等制度，主动防范基金运营风险。建立部门观察员制度，向基金委派观察员，对基金投资、运营和成效进行监督。产业引导基金接受相关部门监督。基金运作中要严格遵守地方政府债务管理的各项规定，不得以任何形式新增政府隐性债务。"},{"no":"四十二","title":"","text":"产业引导基金禁止从事下列业务：（一）从事担保、抵押、委托贷款、房地产（包括购买自用房地产）等业务；（二）投资于二级市场股票（并购、重组上市公司除外）、期货、企业债券、信托产品、非保本型理财产品、保险计划及其他金融衍生品；（三）投资于其他创业投资基金或投资性企业；（四）吸收或变相吸收存款；（五）向任何第三方提供资金拆借、赞助、捐赠；（六）进行承担无限连带责任的对外投资；（七）存续期内，投资回收资金再用于对外投资；（八）法律、法规及其他政策文件规定禁止的其他业务。"},{"no":"四十三","title":"","text":"本办法自公布之日起施行。之前有关规定与本办法不一致的，以本办法为准。株洲市财政局办公室2024年7月8日印发"}],"interpretations":[{"sectionNo":"六","headline":"子基金存续期一般不超8年：投资期5年、退出期3年","who":"在株洲市设立的产业引导母基金及子基金，其出资人与管理机构。","materials":[],"window":"母基金存续15年，期满可按程序协商延期；子基金一般不超过8年","where":"基金章程或合伙协议","tip":"存续期限须写入基金章程或合伙协议；子基金8年期满不能自动延期，须按约定处理"},{"sectionNo":"十六","headline":"母基金对单个子基金出资不超其资产总值20%、认缴规模30%","who":"申请产业引导类母基金出资的子基金及其社会出资人；市、区两级财政和国有企业出资合计同样受上限约束。","materials":[],"window":"子基金设立及增资时适用","where":"株洲市产业引导基金（母基金出资）","tip":"市、区两级出资总额不超过子基金认缴规模50%，且引导基金不能成为子基金第一大出资人"},{"sectionNo":"十七","headline":"引导基金管理费按实际投资额0.5%以内核定，一年一付","who":"产业引导基金受托管理机构；特别优秀的头部基金管理机构申请设立子基金的，管理费可“一事一议”报基金办审批。","materials":[],"window":"按年从产业引导基金中支付，当年支付上年","where":"株洲市产业基金管理办公室（基金办）","tip":"核定基数为实际出资额度扣除已退出项目投资本金后的实际投资额；运营效益好、带动社会出资多的可适当提高比例"},{"sectionNo":"二十","headline":"设子基金须满足五项要求，投株洲资金不低于引导基金出资1.5倍","who":"申请设立子基金的发起人、子基金管理机构、托管金融机构；主要发起人须基本确定、其他出资人基本落实，所有出资人均以货币形式出资。","materials":["出资承诺函","募资兜底承诺函","发起人协议","子基金章程或合伙协议"],"window":"申请设立子基金阶段；非政府性资金完成出资后，引导基金才履行出资义务","where":"向株洲市产业引导基金申请设立子基金","tip":"子基金对单个项目原则上不得控股、不得成为第一大股东；非政府性资金不到位引导基金不出资"},{"sectionNo":"二十一","headline":"子基金设立须经申请、初审、尽调、评审、公示、审批六步","who":"各区县市人民政府（管委会）、市直行业主管部门、基金管理机构等申请主体；基金办、受托管理机构、投决会按流程办理。","materials":["子基金设立方案","管理团队简介","项目储备情况等资料"],"window":"公示无异议后报投决会审批，审批通过后签订合伙协议","where":"株洲市产业引导基金受托管理机构、基金办、投决会","tip":"专家只提参考意见、不参与表决；不得选聘子基金投资各方关联人员参评"},{"sectionNo":"二十二","headline":"返投须是株洲注册纳税企业：本地存量企业或迁入、新设子公司","who":"子基金投资的株洲市内依法登记注册并纳税的存量企业；或注册地迁至株洲、在株洲注册成立子公司并将生产基地等落地株洲的增量企业。","materials":[],"window":"子基金存续期内认定","where":"株洲市（依法登记注册并纳税）","tip":"只在株洲注册子公司、生产基地不落地的，不符合返投认定要求"},{"sectionNo":"二十三","headline":"返投金额：存量企业按投资额，增量企业按注册资本等三项最高值","who":"子基金投资的株洲市内存量企业；将注册地迁至株洲或在株洲新设子公司的增量企业。","materials":[],"window":"基金存续期内认定","where":"株洲市（按企业在株洲注册纳税及投资情况认定）","tip":"增量企业取实缴注册资本、累计投资额、市级税收总额三项最高值；撤回投资不计入"},{"sectionNo":"二十五","headline":"子基金管理机构须实缴1000万元以上、认缴出资1%以上","who":"在中国大陆境内注册并在中国证券投资基金业协会登记备案；实缴注册资本不低于1000万元；核心团队至少3名具备3年以上股权投资或基金管理经验的专职高管、有3个以上成功案例；认缴子基金出资不低于1%；近三年无重大违法。","materials":[],"window":"登记备案须持续有效；近三年无重大违法行为","where":"中国证券投资基金业协会（登记备案）","tip":"管理机构必须对子基金认缴出资，出资比例及亏损弥补办法须在章程或合伙协议中约定"},{"sectionNo":"二十八","headline":"子基金投株洲项目，引导基金最高让渡70%净收益","who":"投资于株洲市区域内项目的子基金及其其他合伙人；投资株洲市区域外项目的不享受让渡。","materials":[],"window":"经基金管理办公室或基金投资决策委员会审批同意后","where":"株洲市产业基金管理办公室（基金办）、基金投资决策委员会","tip":"区内项目按50%或70%两档让渡，须先审批；区外项目不让渡"},{"sectionNo":"三十","headline":"子基金社会出资人首期出资不低于承诺出资额20%，全期到位","who":"经审批设立的子基金的社会出资人。","materials":[],"window":"首期出资不低于承诺出资额20%；全部出资在基金投资期内到位","where":"按投资方案或协议出资","tip":"未按期出资属违约；全部出资须在基金投资期内到位"},{"sectionNo":"三十三","headline":"子基金其他股东不得先于产业引导基金退出","who":"子基金的其他股东（社会出资人）。","materials":[],"window":"子基金到期、社会出资未到位或未开展投资业务时，引导基金可退出","where":"子基金章程或合伙协议","tip":"引导基金可先行退出的情形须写进章程或协议，否则无法约束其他股东"},{"sectionNo":"三十四","headline":"五种情形下政府出资可提前退出，无需其他出资人同意","who":"获得政府出资的投资基金及其其他出资人。","materials":[],"window":"基金方案确认后超过一年未完成设立、出资拨付基金账户一年以上未开展投资等情形","where":"财政部门（在投资基金章程中约定）","tip":"政府出资提前退出不以其他出资人同意为前提，须事先在基金章程中约定"},{"sectionNo":"四十","headline":"尽职免责：未牟取私利且无重大过失可免予追责","who":"产业引导基金运营管理过程中的有关单位和个人。","materials":[],"window":"在巡察、审计、财会监督以及主管部门考核时适用","where":"巡察、审计、财会监督及主管部门考核","tip":"按基金生命周期整体评价，不对单个基金或单个投资子项目造成的投资亏损评定追责"},{"sectionNo":"四十二","headline":"产业引导基金禁止八类业务：担保、炒股、拆借等","who":"产业引导基金及其子基金（含基金管理人）。","materials":[],"window":"基金存续期内持续适用","where":"株洲市产业引导基金及其子基金","tip":"存续期内投资回收资金不得再用于对外投资；不得吸收存款、对外拆借或提供担保"}],"sourceUrl":"https://img.zhuzhou.gov.cn/zzcms/DFS//file/2024/07/16/20240716105925104zdedtn.pdf","sourceNote":"2026-11-22 取自株洲市人民政府门户原文页（https://www.zhuzhou.gov.cn/c19478/20240719/i2223985.html）所挂 PDF 附件；正文为扫描件，已按《zz-industry-fund-2024.checked.txt》校对单逐页对照原件修正。 正文来源：扫描版 PDF（14 页，无文字层），经 Windows OCR 逐页识别后整理；已去除字符间空格与页眉页脚，条号按原文保留。个别字词、标点在页边界处可能被截断或识别有误，引用前请核对官方原件。","verified":false,"isSample":false,"numberStyle":"clause","bodyVerified":"ocr","hunan":true},{"id":"zz-internship-subsidy-2024-1","title":"株洲市人力资源和社会保障局关于印发《株洲市就业见习补贴实施细则（试行）》的通知","level":"city","region":"株洲市","issuer":"株洲市人力资源和社会保障局","documentNo":"株人社发〔2024〕1号","publishedAt":"2024-03-12","effectiveAt":"2024-02-22","expiresAt":null,"status":"active","tags":["就业补贴"],"audience":["就业见习单位（企事业单位和社会组织）","离校2年内未就业高校毕业生","16—24岁登记失业人员","离校2年内未就业中职毕业生"],"summary":"明确就业见习补贴的申领规则：见习期限一般3至12个月；补贴标准为当地最低工资标准，含见习人员基本生活费、人身意外伤害保险费和指导管理费；见习期满留用率达到50%以上（含50%）的见习单位，补贴标准提高至当地最低工资标准的120%；补贴自见习期满3个月开始发放，首次发放前3个月补贴总额，之后按月发放，见习不足3个月不予发放，见习期内提前退岗当月补贴少于15日（含）不计入、超过15日按整月计算；提高部分在见习期满后一次性申报发放。","sections":[{"no":"一","title":"","text":"为进一步提升我市就业见习质量，切实维护就业补助资金安全，发挥就业见习“就业缓冲区”作用，结合我市实际，制定本实施细则。"},{"no":"二","title":"","text":"本细则所称就业见习（以下简称见习）指见习人员按照有关政策规定，在就业见习单位提供的见习岗位进行一定期限的实践锻炼，积累工作经验、提升就业能力的就业促进活动。"},{"no":"三","title":"","text":"本细则所称就业见习单位（以下简称见习单位）为株洲市行政区域范围内，自愿开展见习工作，主动提供见习岗位和见习条件，合法合规的企事业单位和社会组织。"},{"no":"四","title":"","text":"以下三类人员可纳入见习对象:（一）离校2年内未就业高校毕业生（含技师学院高级工班、预备技师班和特殊院校职业教育类毕业生）；（二）16-24岁的登记失业人员；（三）离校2年内未就业中职毕业生。"},{"no":"五","title":"","text":"见习期限一般为3至12个月。见习单位与见习人员应签订见习协议书。离校未就业高校毕业生见习期间不视为就业，见习期满后可按规定参照应届毕业生享受有关政策。"},{"no":"六","title":"","text":"见习期间，见习单位要及时向见习人员发放基本生活费，办理人身意外伤害保险，并承担对见习人员的指导管理费用，按规定向单位所在地人力资源社会保障部门提出就业见习补贴申请。就业见习补贴标准为当地最低工资标准，包括见习人员在见习期间的基本生活费、人身意外伤害保险费以及指导管理费用。已享受就业见习补贴政策的见习对象不可重复申请。"},{"no":"七","title":"","text":"对见习人员见习期满留用率达到50%以上（含50%）的见习单位，就业见习补贴标准提高至当地最低工资标准的120%。"},{"no":"八","title":"","text":"留用率指上一年度见习单位与见习期满人员签订1年以上劳动合同并依法缴纳社会保险人数占上一年度内见习期满人数的比例。"},{"no":"九","title":"","text":"见习单位申请就业见习补贴需提交以下资料：（一）见习对象身份证明；（二）见习对象属离校2年内未就业毕业生的，提供毕业证书。属16-24岁失业青年的，提供进行了失业登记的就业创业证；（三）见习协议书；（四）为见习对象办理人身意外伤害保险发票复印件；（五）见习单位发放基本生活补助明细账（单）和银行转账凭证；（六）《见习人员首次申请就业见习补贴承诺书》；（七）留用见习人员还需提交劳动合同和社保缴纳凭证。"},{"no":"十","title":"","text":"就业见习补贴自见习期满3个月开始发放，第一次发放金额为前3个月补贴总额，之后按月发放到位。见习不足3个月的，不予发放补贴；见习超过3个月，但在见习期内提前退岗的，退岗当月补贴少于15日（含15日）的不计入补贴范围，超过15日的按整月计算。"},{"no":"十一","title":"","text":"留用率达到50%以上的就业见习补贴标准提高部分，在见习期满后，集中一次性申报和发放。"},{"no":"十二","title":"","text":"市人力资源社会保障部门指导各县市区人力资源社会保障部门加强对见习单位的监督管理，定期或不定期开展电话抽查和实地检查。对见习工作组织、管理不规范的见习单位要求限期整改，对审查不严、违规操作、虚报、套取、私分、挪用见习补贴资金等行为的单位和个人，按有关规定追究相应责任；涉嫌犯罪的，依法移交有关部门处理。第十三条本细则自公布之日执行。"}],"interpretations":[{"sectionNo":"三","headline":"株洲市域内合法合规的企事业单位和社会组织可自愿成为见习单位","who":"株洲市行政区域范围内、自愿开展见习工作、主动提供见习岗位和见习条件、合法合规的企事业单位和社会组织。","materials":[],"window":"长期有效，原文未设申报截止时间。","where":"单位所在地人力资源社会保障部门（株洲市各级人社部门）。","tip":"须合法合规且主动提供见习岗位和见习条件；成为见习单位后按第六条、第七条申请补贴。"},{"sectionNo":"四","headline":"离校2年内未就业毕业生、16-24岁登记失业人员可参加见习","who":"（一）离校2年内未就业高校毕业生（含技师学院高级工班、预备技师班和特殊院校职业教育类毕业生）；（二）16-24岁的登记失业人员；（三）离校2年内未就业中职毕业生。","materials":[],"window":"离校2年内未就业是硬时限；报名按见习单位岗位发布组织，原文未设统一申报期。","where":"株洲市行政区域内的就业见习单位。","tip":"16-24岁人员须为登记失业人员；高校毕业生、中职毕业生须为离校2年内未就业。"},{"sectionNo":"五","headline":"见习期3至12个月须签协议，期满可参照应届毕业生享政策","who":"见习单位与见习人员（离校2年内未就业高校毕业生、16-24岁登记失业人员、离校2年内未就业中职毕业生）。","materials":["见习协议书"],"window":"见习期限一般为3至12个月；期满后可按规定参照应届毕业生享受有关政策。","where":"见习单位（签订见习协议书）；由单位所在地人力资源社会保障部门管理。","tip":"离校未就业高校毕业生见习期间不视为就业，见习期满后可参照应届毕业生享受政策。"},{"sectionNo":"六","headline":"见习补贴按当地最低工资标准发放，含生活费、意外险和指导费","who":"株洲市就业见习单位（为见习人员发放基本生活费、办理人身意外伤害保险、承担指导管理费用）；已享受过见习补贴的见习对象不可重复申请。","materials":[],"window":"见习期间按月计发；见习期满3个月后开始发放（见第十条）。","where":"单位所在地人力资源社会保障部门。","tip":"补贴含基本生活费、人身意外伤害保险费、指导管理费用三部分，已享受过的不能重复申请。"},{"sectionNo":"七","headline":"留用率达50%以上，见习补贴提高到当地最低工资的120%","who":"见习期满留用率达到50%以上（含50%）的就业见习单位。","materials":[],"window":"见习期满后核定留用率；提高部分集中一次性申报发放（见第十一条）。","where":"单位所在地人力资源社会保障部门。","tip":"留用率须达50%及以上才适用120%标准；留用率口径按第八条计算。"},{"sectionNo":"八","headline":"留用率=上年签1年以上合同并缴社保人数÷上年见习期满人数","who":"申请提高见习补贴标准的见习单位（按上一年度留用情况计算）。","materials":[],"window":"以上一年度为计算周期。","where":"单位所在地人力资源社会保障部门（核定留用率）。","tip":"分子须同时满足签订1年以上劳动合同并依法缴纳社会保险；仅签合同未缴社保不计入。"},{"sectionNo":"九","headline":"申请见习补贴需交身份证明、毕业证、见习协议、保险发票等材料","who":"申请就业见习补贴的见习单位；留用见习人员的还需提交劳动合同和社保缴纳凭证。","materials":["见习对象身份证明","毕业证书（离校2年内未就业毕业生提供）","就业创业证（16-24岁失业青年提供）","见习协议书","人身意外伤害保险发票复印件","发放基本生活补助明细账（单）和银行转账凭证","《见习人员首次申请就业见习补贴承诺书》","劳动合同和社保缴纳凭证（留用见习人员提供）"],"window":"见习期满3个月后首次申请（见第十条）；材料随申请一并提交。","where":"单位所在地人力资源社会保障部门。","tip":"16-24岁失业青年须提供已进行失业登记的就业创业证，毕业生须提供毕业证书。"},{"sectionNo":"十","headline":"见习满3个月起发补贴，首次发前3个月，之后按月发放","who":"见习满3个月及以上的见习单位；见习不足3个月的不予发放。","materials":[],"window":"见习期满3个月开始发放；提前退岗当月不足15日（含）不计，超过15日按整月计。","where":"单位所在地人力资源社会保障部门。","tip":"见习不足3个月不发补贴；退岗当月补贴少于15日（含15日）的不计入。"},{"sectionNo":"十一","headline":"留用率50%以上的补贴提高部分，见习期满后一次性申报发放","who":"留用率达到50%以上的见习单位（申请提高部分）。","materials":[],"window":"见习期满后集中一次性申报和发放。","where":"单位所在地人力资源社会保障部门。","tip":"提高部分不按月随补贴发放，须见习期满后单独申报。"}],"sourceUrl":"http://rsj.zhuzhou.gov.cn/c933/20240312/i2172629.html","derivedFrom":"official","sourceNote":"2026-11-24 取自株洲市人社局门户「政务公开>信息公开目录>法定主动公开内容>业务事项>促进就业信息」栏目原文页；正文为页面内嵌 HTML 全文（非附件），原文13条已全部转录、未删一字；原文第十三条“本细则自公布之日执行”仅11字，按收录规范并入第十二条同段列示，条号“第十三条”保留在句前以维持与原文逐字连续。版头发文字号株人社发〔2024〕1号，成文日期2024年2月22日，页面发布日期2024年3月12日。 2026-11-24 收录：与官方页面逐句比对，命中 29/29 句（100%），关卡判定「verbatim」。 有效期依据：第十三条","verified":false,"isSample":false,"numberStyle":"clause","bodyVerified":"verbatim","hunan":true},{"id":"zz-liling-ecommerce-2025","title":"醴陵市人民政府办公室关于印发《醴陵市推动电子商务发展三年行动方案（2025—2027年）》的通知","level":"district","region":"株洲市·醴陵市","issuer":"醴陵市人民政府办公室","documentNo":"醴政办发〔2025〕3号","publishedAt":"2025-07-18","effectiveAt":null,"expiresAt":"2027-12-31","status":"active","tags":["数字化转型","外贸外资","创业补贴"],"audience":["电商企业","直播电商从业主体","电商产业园区","农产品上行经营主体"],"summary":"醴陵市推动电子商务发展三年行动方案（2025—2027 年）：围绕「五个 1」目标，培育 1 个电商产业功能区、1 条跨境电商陶瓷产业带、1 家销售额 5 亿元以上龙头（标杆）企业；2026 年力争 1 家企业电商交易额突破 1 亿元、3 家企业突破 5000 万元；在电商产业园区打造 4 个场景直播间，开设陶瓷与特色农产品官方旗舰店，建设高标准云仓并打通「最后一公里」配送；政策保障上由政府统筹每年安排资金支持电商活动与产业发展。","sections":[{"no":"一","title":"发展方向","text":"紧紧围绕“五个1”发展战略目标，即培育1个电商产业功能区（集聚区）、1条跨境电商陶瓷产业带、1家销售额达5亿元以上龙头（标杆）企业、一系列有影响力的电商直播活动、1批电商专业人才，推动全市电商主体、专业服务、创新要素、营商环境等方面取得重要突破，将我市初步打造成产业链完整、人才集聚、品牌突出、服务高效、生态繁荣的电商强市。2025年：强基础，搭平台。出台醴陵市促进电子商务发展相关政策，全市电商发展公共服务平台基本搭建完成，生态圈初步建立。2026年：育企业，上台阶。力争1家企业电商交易额突破亿元，3家企业电商交易额突破5000万元。2027年：树品牌，促提升。培育醴陵陶瓷、醴陵特色农产品官方旗舰店，树立醴陵品牌，“五个1”战略目标完成。"},{"no":"二","title":"打造公共服务平台，形成电子商务聚集区","text":"1.成立市级电子商务协会。团结全市电商产业优势力量，成立醴陵市电子商务协会，加强全市电子商务行业自律、交流与合作，在供应链打造、产销对接、品牌创建、人才培训等领域建立广泛合作关系，探索多元化合作共赢发展模式，通过电商协会举办电商技能比赛、行业交流、学习考察、专题会议等活动，促进我市电子商务产业健康发展。（责任单位：市商务局、市民政局）2.搭建电子商务公共服务平台。通过整合各方资源，引进优质第三方运营管理企业，搭建集办公场地、拍摄展示、直播带货、培训交流等于一体的公共电商服务平台，构建“孵化+培育+赋能”全链条服务体系。加快电商产业园的基础建设改造，用好用活直播间共享等相关入园政策，支持现有入驻企业做大做强，吸引更多的优质企业入驻。加强运营服务体系建设，鼓励和支持整合物流仓储、直播培训、金融服务等第三方资源，搭建产销对接平台促进企业协作，形成“基础设施完善+政策精准扶持+产业生态优化”的驱动格局，提升产业园区的综合竞争力，推动电商集群式发展。（责任单位：市商务局、经开区产业发展部、市渌江集团等）3.打造示范共享直播基地。在电商产业园区打造4个场景直播间，为入驻企业和人才培养提供一站式、全过程、多层次服务，帮助更多电商创业者掌握直播技能。在主城区打造城市共享直播间，开展消费活动推广和达人带货，助力商家实现“拎包直播”，将“瞬时流量”有效转化为“持久留量”，形成区域“线上平台引流+线下商圈人流”双重效应。在醴陵陶瓷博物馆开启直播“云”观展，传播陶瓷文化历史，多渠道满足公众需求。充分利用“淘淘醴品”平台，发挥融媒体传播优势，带动醴陵特色农产品共享供销服务。（责任单位：市商务局、市文旅广体局、市融媒体中心、经开区产业发展部、市渌江集团、陶瓷博物馆等）"},{"no":"三","title":"培育醴陵官方旗舰店，形成品牌统一集中输出","text":"1.开设醴陵陶瓷官方旗舰店。实施大陶瓷战略，以高起点、高标准推进醴陵陶瓷品牌化建设，鼓励和支持企业在抖音、天猫、小红书等线上平台设立陶瓷官方旗舰店，严格把控产品质量，形成展销一体、上下联动的品牌形象店，形成统一的醴陵陶瓷产品质量、市场定位输出，杜绝市场乱象。（责任单位：市商务局、湖南省陶瓷行业协会、市陶瓷发展研究中心、市市场监管局等）2.开设大师产品集中展示区。在陶瓷研究所、1915街区大师工作室等地设立釉下五彩瓷大师作品展区和直播场地，打造集作品展示、技艺传承、文化体验于一体的沉浸式空间。开通大师联名款、故宫文创联名款私人订制通道，开通大师直播间，提供在线咨询、交易等服务。（责任单位：市陶瓷发展研究中心、市商务局、市渌江集团、市文旅广体局、市会展中心等）3.开设醴陵特色农产品官方旗舰店。主要聚焦醴陵酱板鸭、玻璃椒等具有地理标志的特色农产品、农副产品，在京东、天猫等主流电商平台开设线上旗舰店，同时在主产乡镇设立实体展销门店，通过“线上商城+线下体验”的双轨模式，构建一站式消费场景。鼓励商家引入溯源技术，为每件产品配置专属“数字身份证”。通过专业团队策划同步开展直播带货、社区团购等新零售业务，搭建农产品上行的高速通道，助力乡村振兴、消费扶贫。（责任单位：市农业农村局、市市场监管局、市商务局、湖南省陶瓷行业协会、各镇等）"},{"no":"四","title":"加快建设物流仓储，形成配套服务强大支撑","text":"1.优化仓储布局与网络。划出特定区域用于物流仓储，引进第三方建设高标准云仓，依托仓储管理系统，提升商品仓配服务能力和水平，大幅降低存储、分拣、包装、发运、退换货等电商仓储服务成本，为全市中小电商卖家提供最具性价比的快递，快运和仓储服务。鼓励有自建仓储的企业引入自动化分拣系统、智能货架和机器人，提升仓储作业效率。（责任单位：市发改局、市科工信局、市邮政管理局、市商务局、市交通运输局等）2.强化物流配送协同。鼓励行业协会通过市场化协商机制优化服务流程。通过规模化协商，有效避免市场价格乱象，提升物流服务质量。加快推进电商物流寄递基础设施建设，合理规划布局物流寄递配送体系，支持物流寄递企业建立区域分拨中心、配送中心。支持物流公司加大智能快递柜、菜鸟驿站以及无人配送机、无人配送车等相关设施的投入，与社区便利店、快递驿站打通“最后一公里”配送。（责任单位：市商务局、市邮政管理局、市交通运输局等）3.利用铁海联运跨境出海。支持企业发展跨境电商零售商品与铁路运输的深度融合。海关、税务等涉外部门积极强化政策导向，精准指导企业规范申报流程，有效促进陶瓷、服饰等商品的快速集结，为中小企业拓展国际市场提供坚实的运力保障。鼓励传统外贸企业勇于探索“跨境电商+海外仓”新模式，并积极实施国际自主品牌战略，为外贸行业的转型升级注入强劲的新动力。（责任单位：市商务局、市税务局、株洲海关驻醴陵办事处等）"},{"no":"五","title":"加强人才培育引进，形成电商创业创新生态","text":"1.打好聚才“本土牌”。开设企业实操班，鼓励现有陶瓷生产企业在企业内部发掘培养电商人才。开设三天两夜创造营，聘请讲师为电商企业学员全方位培训。开设游学研究营，帮助本土企业家拓宽视野、对接资源，帮助学员企业实现电商道路上的新突破。开展送教下乡活动，针对防止返贫监测对象、农村劳动力、登记失业人员、毕业年度高校毕业生、离校2年内未就业高校毕业生、登记自主创业人员、有创业意愿的企业单位职工等开展电商、直播的网络创业培训。（责任单位：市人社局、市商务局、市融媒体中心等）2.打好育才“孵化牌”。开设校企合作班，湖南工业大学醴陵陶瓷学院、醴陵市陶瓷烟花职业技术学校、湖南省陶瓷技师学院三所职校设立电商班，产教融合，打造“教学—实训—创业—就业”一体化，协同培养实战型电商人才。开展职业技能培训，培育熟练掌握电商从业技能、能够胜任各类电商岗位工作的专业从业者。（责任单位：市教育局、市人社局、市商务局等）3.打好留才“服务牌”。用好用活人才政策，服务电商人才，开展电子商务专题讲座培训，精准引导和推动本地电子商务蓬勃发展。定期开展短视频实操训练营和抖音直播带货特训班，组织“十佳电商主播”等活动，优化电商生态环境，全面激发电商人才的创新活力与潜能。（责任单位：市商务局、市委组织部、市教育局、市融媒体中心等）"},{"no":"六","title":"加快本地生活推广，形成电商文旅互促互进","text":"1.“电商+文旅”融合。“捡陶瓷、玩烟花、吃小炒”文旅火热出圈，带来爆发式流量。依托产业优势与地域特色精心规划运营活动，充分展现其作为“旅游集散地”与“消费目的地”的双重魅力。启用文旅直播间，宣传本地旅游路线，整合特色好品、美食、非遗等各类元素，打造“可逛、可购、可体验”的沉浸式消费生态。联动更多文旅资源与企业，推出特色活动，助力流量与文化的双重赋能。（责任单位：市委宣传部、市文旅广体局、市商务局、市融媒体中心等）2.“电商+探店”体验。通过网红达人、探店主播拓展本地生活服务，采取生动的现场感和体验感，吸引消费者关注，从而使商家获得更高的曝光率，助力商家获客，进一步挖掘流量变现的潜力。（责任单位：市文旅广体局、市商务局、市融媒体中心等）3.“电商+社区”创新。支持各街道社区引入电商服务平台，为社区居民打造一个集商品销售、物流生活服务的平台。加速推进智慧社区项目的广泛落地，借助科技力量强化社区服务效能，从而持续提升居民的幸福感和满足感。（责任单位：市商务局、各街道等）"},{"no":"七","title":"组织构建","text":"（一）强化组织领导。为加强对全市推动电子商务高质量发展工作统筹协调，各部门要结合部门职能细化措施，加大对重点工作任务的指导协调力度。切实执行行动方案，持续推进监管体系的优化、政策的健全及业务的创新升级。（二）强化政策保障。充分发挥政策资金的杠杆作用，政府统筹每年安排资金，用于支持各类电商活动和电商产业发展。同时积极向上对接，争取中央、省级、市级资金支持，促进电商高质量发展。（三）强化氛围构建。充分发挥市融媒体中心各媒体平台作用，全方位宣传我市电商发展的政策举措，广泛推广电商活动、培训及各项措施，拓展各项涉企惠企政策的覆盖范围，营造有利于电商发展的浓厚氛围。"}],"interpretations":[{"sectionNo":"二","headline":"入园电商企业可用4个场景直播间和城市共享直播间开播","who":"入驻醴陵电商产业园的电商企业，以及有直播需求的电商创业者；园区提供办公场地、拍摄展示、直播带货、培训交流等一体化服务。","materials":[],"window":"原文未设申报期限；直播间共享按园区入园政策执行。","where":"醴陵市电商产业园区（场景直播间）、主城区城市共享直播间；由市商务局、经开区产业发展部、市渌江集团等推进。","tip":"城市共享直播间面向商家开展消费活动推广和达人带货，原文未列具体申请条件。"},{"sectionNo":"三","headline":"陶瓷企业可在抖音天猫小红书开官方旗舰店","who":"醴陵陶瓷企业（在抖音、天猫、小红书等平台设陶瓷官方旗舰店）；釉下五彩瓷大师工作室可入驻陶瓷研究所、1915街区大师工作室展区并开通联名款订制通道。","materials":[],"window":"原文未设申报期限与频次。","where":"抖音、天猫、小红书等线上平台；陶瓷研究所、1915街区大师工作室等线下展区。","tip":"官方旗舰店须严格把控产品质量，形成统一的醴陵陶瓷产品质量、市场定位输出。"},{"sectionNo":"四","headline":"中小电商卖家可用高标准云仓，外贸企业可试水海外仓","who":"全市中小电商卖家（享仓储、分拣、包装、发运、退换货服务）；陶瓷、服饰等传统外贸企业（跨境电商零售+铁路运输、跨境电商+海外仓）。","materials":[],"window":"原文未设申报期限；云仓与物流设施按市场化方式提供服务。","where":"市商务局、市邮政管理局、市交通运输局；跨境业务对接株洲海关驻醴陵办事处、市税务局。","tip":"铁海联运需按海关、税务要求规范申报流程；原文未明确海外仓模式的扶持标准。"},{"sectionNo":"五","headline":"七类人员可参加电商直播网络创业培训，三所职校开电商班","who":"防止返贫监测对象、农村劳动力、登记失业人员、毕业年度高校毕业生、离校2年内未就业高校毕业生、登记自主创业人员、有创业意愿的企业单位职工；陶瓷企业可派员参加企业实操班。","materials":[],"window":"原文未设报名截止时间；按企业实操班、三天两夜创造营、游学研究营、送教下乡等班次组织。","where":"市人社局、市商务局、市融媒体中心；湖南工业大学醴陵陶瓷学院、醴陵市陶瓷烟花职业技术学校、湖南省陶瓷技师学院。","tip":"送教下乡面向上述七类人员，原文未列报名材料与名额上限。"},{"sectionNo":"六","headline":"商家可借文旅直播间和探店主播获客，社区引入电商服务平台","who":"醴陵本地餐饮、文旅、零售等商家（参与探店、文旅直播间推广）；各街道社区及其引入的电商服务平台。","materials":[],"window":"原文未设申报期限，活动按文旅推广节点组织。","where":"市委宣传部、市文旅广体局、市商务局、市融媒体中心；各街道社区。","tip":"探店与直播属流量推广合作，原文未明确费用分担和补贴标准。"}],"sourceUrl":"http://www.liling.gov.cn/c1046/20250721/i2398713.html","derivedFrom":"official","sourceNote":"取自醴陵市人民政府门户「政府文件」原文页；页面「发文字号」栏为醴政办发〔2025〕3 号，发布时间 2025-07-18，有效期栏标注 2027-12-31。2026-11-24 按原文三部分（发展方向、主要内容五项、组织构建）重切全文 7 条；文末《2025 年电子商务十大行动责任分解表》为任务分工附件，内容与正文重复，未另立条款。该方案为行动方案，除目标值外不含对企业的奖补金额标准，具体奖补见市商务局配套出台的促进电子商务发展政策。 2026-11-24 收录：与官方页面逐句比对，命中 63/63 句（100%），关卡判定「verbatim」。 有效期依据：原文未设有效期条款；页面「有效期」栏登记为2027-12-31","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"zz-liling-land-use-tax-2026","title":"醴陵市财政局 国家税务总局醴陵市税务局关于《公布醴陵市城镇土地使用税地段等级适用税额标准和征收范围》的通告","level":"district","region":"株洲市·醴陵市","issuer":"醴陵市财政局、国家税务总局醴陵市税务局","documentNo":"","publishedAt":"2026-03-19","effectiveAt":"2026-01-01","expiresAt":null,"status":"active","tags":["税收优惠"],"audience":["醴陵市城镇土地使用税纳税人","在醴陵市城区拥有土地使用权的企业"],"summary":"醴陵市城镇土地使用税地段等级适用税额标准：一级 12 元/平方米、二级 10 元/平方米、三级 8 元/平方米、四级 6 元/平方米、七级 3 元/平方米，五级、六级、八级至十级不适用；一级范围为浙赣铁路以西、李畋路以南合围区域及状元洲区域，七级为城区规划范围内除一至六级以外区域。通告自 2026 年 1 月 1 日起执行。","sections":[{"no":"一","title":"制定依据","text":"为进一步加强我市城镇土地使用税征管，依据《湖南省财政厅 国家税务总局湖南省税务局关于批准城镇土地使用税地段等级适用税额标准和征收范围的通知》（湘财税〔2025〕20号）、《株洲市财政局 国家税务总局株洲市税务局转发<湖南省财政厅 国家税务总局湖南省税务局关于批准城镇土地使用税地段等级适用税额标准和征收范围的通知>的通知》（株财发〔2026〕2号）文件精神，现将我市城镇土地使用税地段等级适用税额标准和征收范围通告如下："},{"no":"二","title":"地段等级适用税额标准","text":"醴陵市适用一级、二级、三级、四级、七级等级适用税额标准分别为12元、10元、8元、6元、3元。具体征收范围及具体地段所适用的等级税额标准按照《醴陵市城镇土地使用税地段等级适用税额标准表》《醴陵市城镇土地使用税地段等级适用税额范围表》执行。附件1《醴陵市城镇土地使用税地段等级适用税额标准表》载明：醴陵市地段等级税额标准（元/平方米）一级12、二级10、三级8、四级6、七级3，五级、六级、八级、九级、十级不适用。"},{"no":"三","title":"执行时间","text":"本通告自2026年1月1日起执行。"},{"no":"四","title":"征收范围（附件2）","text":"附件2《醴陵市城镇土地使用税地段等级适用税额范围表》载明：醴陵市一级（12元/平方米）征收范围为：1.浙赣铁路以西、沿三刀石路自铁路涵洞至金石小区路口后沿渌江河至与李畋路交汇处，李畋西路、李畋中路、李畋东路以南的合围区域。2.状元洲区域。二级（10元/平方米）征收范围为：1.醴茶铁路以西，渌江大道以北，沿左权南路、左权路、江源路延伸至江源大桥止，渌江河河畔以南的合围区域。2.浙赣铁路以西，沿李畋东路、李畋中路、李畋西路，至渌江河河畔，醴泉路以南的合围区域。3.320国道以西，李畋东路以北，浙赣铁路以东，醴陵大道以南的合围区域。4.浙赣铁路以西，渌江河河畔以北、至沿三刀石路自铁路涵洞至金石小区路口以南的合围区域。三级（8元/平方米）征收范围为：1.醴泉路以西、国瓷路以北、城北路以东、浙赣铁路以南的合围区域。2.醴泉路以西，玉瓷路以北，玉瓷北路、016县道以东、国瓷路以南的合围区域。四级（6元/平方米）征收范围为：1.320国道以西，渌江河河畔以北，浙赣铁路以东，长庆大道以南的合围区域。2.320国道以西，渌江大道以北，醴茶铁路以东，渌江河河畔以南的合围区域。3.醴茶铁路以西，沿墩凤路、西山路至仙岳山公园界、仙源桥止以东，沿渌江河河畔、江源路、左权路、左权南路、渌江大道以南的合围区域。4.城北路以西、沿国瓷路到016县道、玉瓷北路以西，B05县道以北，武深高速以东，浙赣铁路以南的合围区域。5.沿320国道以西、醴陵大道以东、浙赣铁路以北、凤凰大道至茶园路以南的合围区域。6.佛子岭路以西，渌江河河畔以北、山人桥起沿梧桐山边界以北，320国道以东，澄潭江路、B23县道、玉屏山路以南的合围区域。七级（3元/平方米）征收范围为：醴陵市城区规划范围内除上述一至六级以外区域。"}],"interpretations":[{"sectionNo":"二","headline":"醴陵土地使用税分五档：一级12元/平方米，七级3元","who":"醴陵市范围内使用应税土地的纳税人；按土地所在地段等级适用税额，一级12元、二级10元、三级8元、四级6元、七级3元每平方米，五级、六级、八级、九级、十级不适用。","materials":[],"window":"适用一级、二级、三级、四级、七级五个等级标准；五级、六级、八级、九级、十级不适用。","where":"以附件1《醴陵市城镇土地使用税地段等级适用税额标准表》和附件2范围表确定土地所在地段等级。","tip":"五级、六级、八级、九级、十级不适用，别按相邻等级套用；地段等级以范围表划定的合围区域为准。"},{"sectionNo":"四","headline":"醴陵一级地段12元/平方米：浙赣铁路以西、李畋路以南","who":"醴陵市城区规划范围内使用应税土地的单位和个人；一级（12元/平方米）为浙赣铁路以西、李畋路以南合围区域及状元洲区域，二级10元、三级8元、四级6元，城区规划范围内一至六级以外区域为七级3元。","materials":[],"window":"按土地所在合围区域确定地段等级，再适用对应等级税额标准。","where":"按附件2《醴陵市城镇土地使用税地段等级适用税额范围表》划定的合围区域确定地段等级。","tip":"一级最高12元/平方米；城区规划范围内一至六级以外区域统一按七级3元执行。"}],"sourceUrl":"http://www.liling.gov.cn/c3812/20260319/i2484772.html","derivedFrom":"official","sourceNote":"取自醴陵市人民政府门户「信息公开目录—政策文件—部门文件」原文页（索引号 103/2026-00809，发布时间 2026-03-19，页面「发文字号」栏为空）。2026-11-24 按原文正文及附件 1 税额标准表、附件 2 征收范围表重切为 4 条，税额数值 12/10/8/6/3 元/平方米与两张附件表逐格核对一致。 2026-11-24 收录：与官方页面逐句比对，命中 19/19 句（100%），关卡判定「verbatim」。 有效期依据：本通告自2026年1月1日起执行；原文未设终止日期","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"zz-liling-teaoli-insurance-2026","title":"醴陵市林业局关于开展2026年油茶保险有关事项的通知","level":"district","region":"株洲市·醴陵市","issuer":"醴陵市林业局","documentNo":"","publishedAt":"2026-09-28","effectiveAt":null,"expiresAt":null,"status":"active","tags":["财政奖补"],"audience":["油茶种植经营主体","承保保险机构"],"summary":"2026年在醴陵市开展油茶保险，补贴标准为每亩保费的20%，油茶保险补贴资金150万元；市内保险机构均可在试点期间承保，险种由保险公司自行设计，林业部门负责组织协调与监管，要求理赔服务做到查勘定损、赔款支付、理赔信息公开“三到户”。","sections":[{"no":"引言","title":"","text":"根据湖南省财政厅、湖南省林业局《关于开展2025年产油大县奖励资金申报工作的通知》（湘财建〔2025〕12号）文件精神及湖南省林业局与中国平安财产保险股份有限公司签署的《推动油茶高质量发展合作协议》、醴陵市2025年茶油大县实施方案有关规定，现将开展2026年油茶保险工作有关事项通知如下："},{"no":"一","title":"规模确认","text":"在醴陵市开展2026年油茶保险，补贴标准为每亩保费的20%，油茶保险补贴资金为150万元。"},{"no":"三（一）","title":"明确部门职责分工","text":"林业部门主要负责油茶种植保险的组织协调、管理监督。经办保险机构要做好种植户档案资料的收集、审核、保存和管理工作。建立种植户参保资料数字化信息登记管理制度，确保档案资料的真实、完整性，加强承保、防灾防损、查勘定损、理赔等专业化服务以及有关统计、报送、核算工作，把维护油茶种植户合法权益放在首位，做到理赔服务“三到户”，即查勘定损到户、赔款支付到户、理赔信息公开到户。"},{"no":"三（二）","title":"加强宣传与推广","text":"林业部门及经办保险机构要加大宣传力度，充分利用电视、电台、报刊、网络等新闻媒体，通过召开专题会议、编印、张贴、发放宣传资料等多种形式，广泛宣传油茶种植保险的重要意义和政策内容，增强广大油茶种植户的保险意识、风险防范意识，引导更多的油茶种植户积极主动投保。"}],"interpretations":[{"sectionNo":"引言","headline":"2026年油茶保险按省产油大县奖励及平安产险合作协议实施","who":"醴陵市油茶种植户（2026年油茶保险投保主体）；政策依据为湘财建〔2025〕12号、省林业局与中国平安财产保险股份有限公司签署的《推动油茶高质量发展合作协议》及醴陵市2025年茶油大县实施方案。","materials":[],"window":"2026年度。","where":"醴陵市林业局；经办保险机构为中国平安财产保险股份有限公司。","tip":"承保机构依省林业局与平安产险的合作协议确定；政策依据含湘财建〔2025〕12号及醴陵市2025年茶油大县实施方案。"},{"sectionNo":"一","headline":"醴陵油茶保险补每亩保费20%，补贴资金共150万元","who":"在醴陵市投保2026年油茶保险的油茶种植户（种植经营主体）。","materials":[],"window":"2026年度；油茶保险补贴资金150万元。","where":"醴陵市林业局（经办保险机构承保）。","tip":"补贴按每亩保费的20%计算，全市补贴资金总额150万元；具体投保亩数需经规模确认。"},{"sectionNo":"三（一）","headline":"油茶保险理赔做到查勘定损、赔款支付、信息公开三到户","who":"投保醴陵市油茶种植保险的油茶种植户；由经办保险机构负责档案资料收集审核和承保、查勘定损、理赔等服务。","materials":[],"window":"承保、查勘定损、理赔全流程；本条未规定具体时限。","where":"醴陵市林业局（组织协调、管理监督）；经办保险机构（承保理赔服务）。","tip":"理赔服务须做到“三到户”：查勘定损到户、赔款支付到户、理赔信息公开到户；档案资料须数字化登记管理。"}],"sourceUrl":"http://www.liling.gov.cn/c3812/20260929/i2531199.html","sourceNote":"2026-11-22 取自醴陵市政府门户「信息公开目录—政策文件—部门文件」原文页；该件页面发文字号为空。 2026-11-22 收录：与官方页面逐句比对，命中 6/6 句（100%），关卡判定「verbatim」。 有效期依据：原文未明示有效期","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"zz-skill-master-studio-2025","title":"关于申报2025年株洲市技能大师工作室建设项目的通知","level":"city","region":"株洲市","issuer":"株洲市人力资源和社会保障局","documentNo":"","publishedAt":"2025-05-26","effectiveAt":"2025-05-26","expiresAt":null,"status":"active","tags":["人才政策","财政奖补"],"audience":["株洲市范围内注册登记的企业、学校、行业协会组织等申报单位","技能大师工作室领衔人及团队成员"],"summary":"2025年评选不超过10家市级技能大师工作室，对每个工作室给予一次性补助资金5万元，用于培训、研修、攻关、交流等技能传承活动；项目自确定之日起实施，为期一年。申报单位须在株洲市注册登记、自建工作室1年以上、配备不少于5人的高技能与专业技术人才团队并签订劳动合同缴纳社保、为工作室提供不少于5万元资金支持及场所设备；领衔人须在株工作2年及以上并具备技师及以上职业资格等条件之一。申报截止2025年6月30日。","sections":[{"no":"一","title":"申报范围和评选数量","text":"株洲市技能大师工作室建设项目主要以具备较高技能水平的人才为领衔人，依托株洲市范围内的企业、学校、行业协会组织等建设，旨在攻关技能难题、传帮带青年技能骨干。2025年评选不超过10家技能大师工作室。"},{"no":"二","title":"项目实施期限","text":"技能大师工作室建设项目从项目确定之日起开始实施，为期一年。"},{"no":"三","title":"申报条件","text":"申报技能大师工作室建设项目应同时满足以下条件：（一）工作室领衔人应具备以下条件：1.遵纪守法、爱岗敬业，具有良好的职业道德，身体健康，能够承担工作室日常工作，已在株洲市工作2年及以上；2.掌握所在岗位关键技术，近3年在生产、服务、技能教学等一线岗位从事技能工作，带徒传技经验丰富；3.除满足以上基本条件外，还须具备下列条件之一：①获得过中华技能大奖、全国（或省）技术能手、省（或市）技能大师、“享受国务院（或省）政府特殊津贴”的高技能人才；②具有技师及以上职业资格（职业技能等级）证书，积极开展技术技能革新，取得有一定影响的创新成果或解决了关键性技术难题，经济效益显著或对技术发展有引领作用；③具有技师及以上职业资格（职业技能等级）证书2年及以上，在行业内有一定的知名度，积极传承技能技艺，在培养高技能人才、传承技艺方面作出较大贡献。（二）申报单位应具备以下条件：1.有符合条件（一）的工作室领衔人，申报单位为我市范围内注册登记的的企业、学校、行业协会组织等；2.自建工作室1年以上，经常性组织开展技术交流活动，在攻关技能难题、教学改革、培养技能人才和成果推广等方面取得一定成效；3.为工作室配备不少于5人的高技能人才和专业技术人才团队，成员职责明确，并与申报单位签订劳动合同，缴纳社会保险；4.高度重视技能人才队伍建设工作。依托企业、行业协会组织等建立工作室的，应建立了较为完善的技能人才培养、使用、激励等制度，行业协会还需具备本行业技能培训资质；依托学校建立工作室的，应制定了一系列加快高技能人才队伍建设的措施和制度，与企业联系紧密，校企合作卓有成效；5.为技能大师工作室提供不少于5万元的资金支持以及包括场所、设备等在内的必要工作条件；有相应的技能大师工作室配套管理制度和具体可行的工作规划（含技术攻关、带徒计划等）。（三）申报职业（工种）：技能大师工作室所申报的职业（工种）应属于《中华人民共和国职业分类大典》中第四、五、六大类，并与领衔人技能领域相关。已获得国家级、省级、市级技能大师工作室和高级工程师工作室建设项目扶持的领衔人不得重复申报。"},{"no":"四","title":"申报资料","text":"1.《株洲市技能大师工作室建设项目申报表》《2025年度株洲市技能大师工作室建设项目情况一览表》（见附件）；2.申报报告。申报技能大师工作室职业（工种）、技能大师工作室成立的必要性和现有优势、领衔人简介、技能大师工作室配套管理制度和技能大师工作室计划目标（含技术攻关、带徒计划）等；3.技能大师工作室所依托的申报单位有关情况说明。包括技能人才队伍建设的情况及相关措施制度，能够为技能大师工作室提供资金、场所、设备等在内的必要工作条件的情况说明；4.企业法人营业执照或主管部门批准成立文件的复印件；5.工作室领衔人及团队成员身份证复印件、社会保险缴费证明及相关资格证书、获奖证书复印件等佐证材料。"},{"no":"五","title":"申报流程","text":"1.单位申报。申报单位携带申报材料，向市人社局职业能力建设科进行申报。2.资料审核。市人社局职业能力建设科对申报资料进行资格初审，初审通过的单位进入现场考察。3.专家评审。召开综合评审会议，专家结合考察情况进行投票表决，按得票多少排序确定支持项目名单。4.公示确定。将确定支持项目名单在部门网站进行公示，公示期为5个工作日。5.资金拨付。对每个市级技能大师工作室给予一次性补助资金5万元，主要用于开展培训、研修、攻关、交流等技能传承提升活动。"},{"no":"六","title":"项目产出要求","text":"项目实施一年后，市人社局组织专家对技能大师工作室建设项目运行情况进行考核评估；技能大师工作室需达到以下产出，并向市人社局提供验收报告：1.有固定办公场地，配备必要的设施设备，定期开展相关活动；2.建立一套完善的技能大师工作室管理和运行机制；3.充分发挥工作室领衔人带徒传技作用，为所在企业（行业）或社会培养不少于3名高级工（三级）以上职业技能等级的高技能人才；4.发挥团队优势，积极开展技术攻关或技术技能研发，推动企业技术改造或形成一批有价值的技术、创新成果；5.每年组织开展2次以上技术技能交流活动，为技术研修、创新、教学改革等提供交流平台。"},{"no":"七","title":"工作要求","text":"1.加强宣传引导，规范申报审核。各县区人社局要高度重视技能大师工作室建设项目申报工作，积极宣传发动，鼓励本地区符合条件的单位积极申报。同时，要对申报单位提供的资料进行严格审核，确保推荐的单位符合条件。严禁各申报单位弄虚作假，一经发现，取消参评资格。2.加强经费保障，规范资金管理。技能大师工作室依托的单位要根据技能大师工作室年度工作计划建立投入经费制度，设立带徒津贴、研究（攻关）项目补贴及日常工作经费等，全力支持技能大师工作室开展各项业务活动，确保完成项目产出任务。技能大师工作室依托的单位还要做好项目资金管理工作，完善项目经费管理制度，规范政府补助资金使用，确保专款专用，做到资金到项目、管理到项目、核算到项目，保证资金安全和效益。3.加强考核评估，规范违规查处。市人社局将严格按照项目产出要求、工作室工作目标进行考核评估。对技能大师工作室带头人已离开一线工作岗位或调离工作室所在单位、技能大师工作室缺少正常开展工作的场地和设施设备、技能大师工作室未按工作计划正常开展工作等情况的，将予以摘牌撤销；如发现相关责任人员擅自挪用市财政补助资金，违反财政相关规定的，将依照《财政违法行为处罚处分条例》予以处理，涉嫌犯罪的依法移交司法机关。4.其他要求。各申报单位需同步报送与纸质资料相同的电子版文件。项目申报截至日期为2025年6月30日，逾期将不予受理。"}],"interpretations":[{"sectionNo":"一","headline":"株洲市评选技能大师工作室，2025年不超过10家","who":"以具备较高技能水平的人才为领衔人，依托株洲市范围内的企业、学校、行业协会组织等建设单位。","materials":[],"window":"2025年度评选，评选不超过10家。","where":"株洲市人力资源和社会保障局","tip":"2025年名额上限10家；领衔人须为具备较高技能水平的人才。"},{"sectionNo":"二","headline":"技能大师工作室从确定之日起实施，为期一年","who":"经认定的株洲市技能大师工作室建设项目单位。","materials":[],"window":"从项目确定之日起实施，为期一年。","where":"株洲市人力资源和社会保障局（项目管理）","tip":"实施满一年后由市人社局组织专家考核评估。"},{"sectionNo":"三","headline":"领衔人须在株洲工作2年以上、带徒传技，单位自建工作室1年以上","who":"领衔人须已在株洲市工作2年及以上、近3年在生产服务技能教学一线岗位从事技能工作，并具备中华技能大奖、技术能手、技能大师等荣誉之一，或具有技师及以上职业资格（职业技能等级）证书等条件之一；申报单位为我市范围内注册登记的企业、学校、行业协会组织等，自建工作室1年以上，配备不少于5人的团队并签劳动合同、缴社保，提供不少于5万元资金支持。","materials":[],"window":"领衔人在株洲工作2年及以上、近3年一线岗位；单位自建工作室1年以上。","where":"株洲市人力资源和社会保障局","tip":"已获国家级、省级、市级技能大师工作室和高级工程师工作室建设项目扶持的领衔人不得重复申报。"},{"sectionNo":"四","headline":"申报需交申报表、情况一览表、申报报告及佐证材料","who":"申报株洲市技能大师工作室建设项目的单位。","materials":["《株洲市技能大师工作室建设项目申报表》","《2025年度株洲市技能大师工作室建设项目情况一览表》","申报报告（含职业工种、必要性、领衔人简介、管理制度和计划目标）","申报单位有关情况说明","企业法人营业执照或主管部门批准成立文件的复印件","领衔人及团队成员身份证复印件、社会保险缴费证明及相关资格证书、获奖证书复印件"],"window":"按申报通知提交，截止时间为2025年6月30日。","where":"株洲市人力资源和社会保障局职业能力建设科","tip":"申报报告须含技术攻关、带徒计划；营业执照或批准成立文件、社保缴费证明缺一不可。"},{"sectionNo":"五","headline":"每个市级技能大师工作室一次性补助5万元","who":"经申报、资格初审、现场考察、专家评审投票排序并公示的申报单位。","materials":["申报材料"],"window":"公示期5个工作日。","where":"市人社局职业能力建设科；部门网站（公示）。","tip":"补助资金用于培训、研修、攻关、交流等技能传承提升活动，不是给个人的奖金。"},{"sectionNo":"六","headline":"工作室须培养不少于3名高级工，每年2次以上技术交流","who":"经立项的市级技能大师工作室；须有固定办公场地和必要设施设备，建立管理运行机制，每年组织2次以上技术技能交流活动。","materials":["验收报告（向市人社局提供）"],"window":"项目实施一年后考核评估；每年组织2次以上交流活动。","where":"株洲市人力资源和社会保障局（考核评估）","tip":"培养对象须为高级工（三级）以上职业技能等级，数量不少于3名。"},{"sectionNo":"七","headline":"申报截止2025年6月30日，领衔人离岗将被摘牌撤销","who":"申报单位与技能大师工作室依托单位；须建立投入经费制度、设带徒津贴，规范使用政府补助资金。","materials":["与纸质资料相同的电子版文件"],"window":"项目申报截止日期为2025年6月30日，逾期不予受理。","where":"株洲市人力资源和社会保障局","tip":"领衔人离开一线岗位或调离、缺场地设施、未按计划开展工作的予以摘牌撤销。"}],"sourceUrl":"http://rsj.zhuzhou.gov.cn/c923/20250526/i2369478.html","derivedFrom":"official","sourceNote":"2026-11-24 取自株洲市人社局门户「政务公开>信息公开目录>法定主动公开内容>通知公告」栏目原文页；正文为页面内嵌 HTML 全文（非附件），申报表以 .doc 附件另行发布。页面未标注发文字号（属年度申报通知），落款株洲市人力资源和社会保障局2025年5月26日。 2026-11-24 收录：与官方页面逐句比对，命中 48/48 句（100%），关卡判定「verbatim」。 有效期依据：第七部分第4项（其他要求）","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"zz-sme-2022-7","title":"关于印发《株洲市专精特新中小企业培育行动方案（2022-2025）》的通知","level":"city","region":"株洲市","issuer":"株洲市人民政府办公室","documentNo":"株政办发〔2022〕7号","publishedAt":"","effectiveAt":null,"expiresAt":"2025-12-31","status":"expired","tags":["认定资质","财政奖补","研发创新"],"audience":["在株洲注册登记、连续经营1年以上、上年度主营业务收入2000万元以上的中小企业"],"summary":"对获评国家级“单项冠军”和国、省专精特新“小巨人”企业给予一定财政奖励、政策扶持和服务保障。","sections":[{"no":"适用对象","title":"企业门槛","text":"在我市注册登记具有独立法人资格、连续经营1年以上的中小企业，上年度主营业务收入2000万元以上，近两年主营业务收入、实现税金年均增长15%以上，企业资产负债率不高于70%，主营业务收入占营业收入60%以上。"},{"no":"支持措施","title":"奖励与扶持","text":"对获评国家级“单项冠军”和国、省专精特新“小巨人”企业，给予一定财政奖励、政策扶持和服务保障。对上云用云、智能制造和绿色发展标杆企业，技术创新“破零倍增”标杆企业以及品牌培育标杆企业，给予一定奖励。"},{"no":"申报","title":"申请途径","text":"向主管部门申报，申请材料见相关政策文件，主管部门为株洲市人民政府办公室。"}],"interpretations":[{"sectionNo":"适用对象","headline":"株洲中小企业营收2000万元以上、负债率不超70%","who":"在株洲市注册登记、具有独立法人资格、连续经营1年以上的中小企业；上年度主营业务收入2000万元以上；近两年主营业务收入、实现税金年均增长15%以上；资产负债率不高于70%；主营业务收入占营业收入60%以上。","materials":[],"window":"以连续经营1年以上、上年度及近两年数据为考核口径；原文未写申报起止时间。","where":"原文未指定受理部门或线上申报系统。","tip":"各项门槛须同时满足：独立法人、连续经营1年、上年度营收2000万元以上、近两年增长15%以上、负债率不高于70%、主营占比60%以上。"},{"sectionNo":"支持措施","headline":"获评单项冠军、专精特新小巨人及各类标杆企业给奖励","who":"获评国家级“单项冠军”和国家级、省级专精特新“小巨人”的企业；上云用云、智能制造和绿色发展标杆企业；技术创新“破零倍增”标杆企业；品牌培育标杆企业。","materials":[],"window":"以获评、获认定为条件，原文未写申报时间和奖励标准。","where":"原文未指定受理部门或线上申报系统。","tip":"原文只写“一定财政奖励、政策扶持和服务保障”，未定金额和档次；奖励以获评称号为前提。"}],"sourceUrl":"https://www.hunan.gov.cn/zqt/hqzc/202405/t20240524_33311017.html","sourceNote":"2026-11-21 取自省门户「惠企政策」库条目（对株洲市政策的汇总条目）；文号与适用对象已核对。行动期已止于2025年，判失效，保留作对照。 2026-11-21 收录：与官方页面逐句比对，命中 4/4 句（100%），关卡判定「verbatim」。 有效期依据：文件名载明实施期限止于2025年；基准日已过，判失效","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"zz-tech-fund-2024","title":"株洲市科学技术局、株洲市财政局关于印发《株洲市科技发展专项资金管理办法》的通知","level":"city","region":"株洲市","issuer":"株洲市科学技术局、株洲市财政局","documentNo":"株科办〔2024〕18号","publishedAt":"2024-08-07","effectiveAt":null,"expiresAt":null,"status":"active","tags":["专项资金","研发创新"],"audience":["科技型企业","项目承担单位","事业单位"],"summary":"市级财政预算安排科技发展专项资金，支持企事业单位开展技术攻关、科学研究与试验发展、科技成果转化和科普推广；资金分前资助、后补助等支持方式，按项目申报、评审、立项流程管理，并实行绩效评价与验收。","sections":[{"no":"一","title":"","text":"为规范和加强株洲市科技发展专项资金管理，提高资金使用绩效，根据《湖南省财政厅湖南省科学技术厅关于印发《湖南省创新型省份建设专项资金管理办法》的通知》（湘财教〔2023〕3号）以及《株洲市人民政府办公室关于印发《株洲市市本级财政专项资金分配审批管理办法》的通知》（株政办发〔2020〕11号）等有关规定，结合我市工作实际，制定本办法。"},{"no":"二","title":"","text":"本办法所称市科技发展专项资金是指由市级财政预算安排，用于我市打造科技创新高地，推进科技发展的专项资金，主要支持企事业单位开展技术攻关、科学研究与试验发展、科技成果转化和科普推广等科技活动。"},{"no":"三","title":"","text":"市科技发展专项资金的管理和使用应严格按照财政预算管理的有关规定，遵循统筹兼顾、突出重点、分类支持、讲求绩效、科学规范、公开透明的原则。"},{"no":"四","title":"","text":"市级财政预算根据全市经济社会发展状况和上一年度科技专项使用情况，编制下一年度科技专项资金预算。"},{"no":"五","title":"","text":"市财政局和市科技局按照职责分工管理市科技发展专项资金。（一）市财政局会同市科技局做好市科技发展专项资金年度预算编制，审核资金分配建议，按程序下达专项资金，并对资金使用情况进行监督和绩效评价。（二）市科技局会同市财政局提出年度专项资金具体实施方案，牵头组织项目申报、评审、立项等，提出资金需求测算方案和分配建议，审核批复项目绩效目标，负责项目验收等工作。"},{"no":"六","title":"","text":"县市区科技、财政主管部门和相关指定单位为项目推荐单位，协助市科技局、市财政局开展项目真实性核查和执行期监督管理。"},{"no":"七","title":"","text":"依法注册、具有独立法人资格的单位或企业为项目承担单位，是项目资金使用的责任主体，应按照有关规定规范使用项目资金，并自觉接受监督检查。"},{"no":"八","title":"","text":"市科技局在推动我市“三个高地”重大标志性工程、实施市委、市政府重大科技项目等方面，根据实际工作需求，报市政府审批同意后，可申请科技计划管理费，原则上不超过当年科技专项资金总额的3%，专项用于在科技计划实施和管理过程中所发生的费用，包括科技政策宣传、科研管理培训、科技项目调研、资料整理归档等工作。"},{"no":"九","title":"","text":"市科技发展专项资金支持方式主要为以下几种：（一）前资助。在项目立项以后，根据相关批文对项目进行事前资助，将资金拨付项目承担单位。（二）后补助。项目承担单位先行投入资金，根据任务完成情况、验收结果、绩效情况或政策规定，给予资金补助。后补助包括事前立项事后补助、事后立项事后补助及政策兑现。事前立项事后补助是指项目按照规定的程序立项后，承担单位根据任务书先行投入组织项目执行并达到预期目标，按规定程序通过验收后，给予补助的支持方式。事后立项事后补助是指项目承担单位在研发、科技服务等方面达到目标要求，给予相应补助的支持方式。政策兑现是指项目承担单位符合相关奖补政策补助的条件，给予资金补助。（三）前资助和后补助结合。在项目立项以后，根据相关批文和立项金额，将资金按一定比例拨付项目承担单位，待项目按规定程序进行中期检查或验收后，将剩余资金拨付项目承担单位。"},{"no":"十","title":"","text":"市科技发展专项资金支持范围主要为以下几个方面。（一）重大科技攻关计划。主要支持面向产业链建设和产业集群建设等需要解决的重大技术攻关项目、区域性重大问题系统解决方案，以及打破垄断、填补空白或替代进口的关键核心产品研发等，着力推动重大科技成果应用及产业化。原则上采用前资助、后补助、前资助和后补助结合的支持方式。（二）重点研发计划。围绕技术需求，突出问题导向和应用导向，主要支持制约我市产业发展、公益民生等重点领域的前沿性、引领性和关键共性技术攻关、工程化研究及应用示范，以及重大应用基础研究和科技合作创新等。原则上采用前资助、后补助、前资助和后补助结合的支持方式。（三）科技创新平台与人才。主要支持各类科技创新创业（服务）平台基地和重大科研基础设施的建设与运行，支持科技创新创业人才（团队）的引进、培养和使用。原则上采用前资助、后补助、前资助和后补助结合的支持方式。（四）省市联合基金。针对全市经济社会社会发展战略性、基础性、前瞻性重大科学问题，支持科研人员开展基础研究和前沿技术研究，创新理论和方法，鼓励自由探索，培养优秀科技人才，提升原始创新能力。原则上采用前资助的支持方式。（五）科技创新政策兑现。主要支持研发管理补助、新认定国家高新技术企业补助、省以上科技创新平台、科技金融、科研基础设施与科研仪器开放共享等科技创新政策的兑现。原则上采用后补助（政策兑现）的支持方式。（六）重点科技工作及活动。主要支持长株潭国家自主创新示范区、国家创新型城市、创新型县（市）区建设工作，支持研发投入提升、科学技术普及、创新创业大赛、技术合同登记、科技帮扶、乡村振兴和科技决策咨询等科技项目及活动。原则上采用后补助（事前立项事后补助或事后立项事后补助）的支持方式。（七）指令性项目。主要支持根据省市相关文件、会议纪要、重要批示等自上而下指令安排的项目和活动。原则上采用前资助、后补助、前资助和后补助结合的支持方式。（八）其他科技项目和服务。主要支持其他经市科技局、市财政局共同核定，并报市政府批准的科技项目和服务，原则上采用前资助、后补助、前资助和后补助结合的支持方式。"},{"no":"十一","title":"","text":"重大科技攻关计划、重点研发计划、科技创新平台与人才计划、省市联合基金类别的计划项目，由项目申报单位按当年市科技专项资金申报通知及申报指南的要求提交申报材料进行申报。申报单位必须保证报送资料真实、合法、完整、有效，并承担相应法律责任。科技创新政策兑现根据相关科技创新政策，由市科技局、市财政局审定，并报市政府批准后按程序予以补助。重点科技工作及活动、指令性项目、其他科技项目和服务按照“一事一议”的原则，由市科技局、市财政局审定，并报市政府批准后执行。"},{"no":"十二","title":"","text":"项目推荐单位对项目真实性进行审核，并根据审核结果联合行文推荐报送市科技局、市财政局。"},{"no":"十三","title":"","text":"市科技局牵头组织对推荐的项目进行形式审查与实质审查，主要审查项目内容及材料是否符合要求、项目申报单位和申报负责人是否符合申报条件、同一项目是否存在多头或重复申报等。"},{"no":"十四","title":"","text":"对审查合格的项目，由市科技局会同市财政局牵头组织专家进行评审或咨询论证。对需要现场考察的项目，由市科技局牵头组织现场考察。"},{"no":"十五","title":"","text":"市科技局会同市财政局根据年度专项资金，结合专家评审意见、考察情况等，确定拟立项项目，制定资金分配方案，并进行公示等，公示期不少于5个工作日，涉密项目除外。"},{"no":"十六","title":"","text":"经公示无异议的项目，由市财政局会同市科技局下达专项资金，并由市科技局负责与项目承担单位及时签订项目任务书。对于前资助项目，市科技局下达立项文件并签订任务书，市财政局根据市科技局的立项文件，下达专项资金；对于事前立项事后补助项目，由市科技局下达立项文件并签订任务书，待验收合格后，市财政局根据市科技局立项文件及验收情况，下达专项资金；对于事后立项事后补助项目，市财政局根据市科技局的立项文件，下达专项资金；对于政策兑现项目，市科技局出具核定依据和文件，市财政局根据市科技局的核定依据和文件，下达专项资金。"},{"no":"十七","title":"","text":"各县市区财政部门和相关单位在收到专项资金文件后，应该在30个工作日内将资金拨付到项目承担单位。项目牵头单位要根据项目任务书要求和项目负责人意见，30个工作日内将经费拨付至项目参与单位，不得截留、挪用。"},{"no":"十八","title":"","text":"项目承担单位应建立相应资金管理制度，对专项资金按规定进行财务管理和会计核算，做到专款专用。"},{"no":"十九","title":"","text":"前资助项目实施期内的年度结余资金结转下一年度继续使用。前资助项目实施期满后，通过验收且无不良信用记录的项目承担单位，结余资金可统筹安排用于本单位科研活动支出。"},{"no":"二十","title":"","text":"经核定的后补助资金拨付至项目承担单位后，由项目承担单位统筹安排，不再组织资金过程管理和验收。"},{"no":"二十一","title":"","text":"市科技局严格按照项目任务书确定的任务目标和资金使用情况进行绩效评价，不开展单独的财务验收和技术验收。"},{"no":"二十二","title":"","text":"市科技局牵头对项目承担单位、项目负责人、项目推荐单位和科技服务机构、评审或咨询专家等参与主体实行科研诚信审核、评价和记录，做好科研诚信管理。"},{"no":"二十三","title":"","text":"市科技局建立健全专项资金绩效评价制度，组织专项资金使用情况绩效评价，并将绩效评价结果报送市财政局。市财政局根据绩效评价结果和工作需要，适时委托第三方中介机构对项目资金使用情况进行重点绩效评价。绩效评价结果作为财政安排项目资金的重要依据。"},{"no":"二十四","title":"","text":"资金使用单位应积极配合科技、财政、审计等部门的监督与审计。对于虚报、截留、挪用、冒领、侵占或骗取资金以及擅自改变专项资金用途等违法违规行为的，按照《中华人民共和国预算法》《财政违法行为处罚处分条例》等有关法律法规查处。涉嫌犯罪的，依法追究刑事责任。"},{"no":"二十五","title":"","text":"市科技发展专项资金管理接受同级审计、监察等有关部门的监督。"},{"no":"二十六","title":"","text":"根据国家科技体制改革和财政科技专项资金管理改革精神，以及市委市政府重点工作安排部署，市科技发展专项的支持重点及支持方式可动态调整，具体由市财政局会同市科技局按程序报市政府批准后执行。"},{"no":"二十七","title":"","text":"本办法自公布之日起实施。"}],"interpretations":[{"sectionNo":"二","headline":"市科技发展专项资金支持企事业单位技术攻关、研发","who":"株洲市企事业单位（开展技术攻关、科学研究与试验发展、科技成果转化和科普推广等科技活动）。","materials":[],"window":"由市级财政预算安排，按年度专项资金申报通知组织。","where":"株洲市科学技术局、株洲市财政局","tip":"资金用途限于科技活动，不支持非科技类支出。"},{"sectionNo":"九","headline":"支持方式含前资助、后补助、两者结合","who":"市科技发展专项资金项目承担单位。","materials":[],"window":"前资助于立项后按批文拨付；后补助按任务完成、验收结果或政策规定补助。","where":"株洲市科学技术局、株洲市财政局","tip":"后补助含事前立项事后补助、事后立项事后补助及政策兑现三类。"},{"sectionNo":"十","headline":"支持重大科技攻关、重点研发、平台人才等八类计划","who":"符合八类计划方向的申报单位：重大科技攻关、重点研发、科技创新平台与人才、省市联合基金、科技创新政策兑现、重点科技工作及活动、指令性项目、其他科技项目和服务。","materials":[],"window":"按当年市科技专项资金申报通知及申报指南组织。","where":"株洲市科学技术局、株洲市财政局","tip":"政策兑现按相关科技创新政策审定；重点科技工作及指令性项目按「一事一议」执行。"},{"sectionNo":"十一","headline":"按年度申报通知提交材料，申报资料须真实完整","who":"重大科技攻关计划、重点研发计划、科技创新平台与人才计划、省市联合基金类别的项目申报单位。","materials":["按当年市科技专项资金申报通知及申报指南要求提交的申报材料"],"window":"按当年申报通知及申报指南要求申报。","where":"株洲市科学技术局、株洲市财政局","tip":"申报单位须保证资料真实、合法、完整、有效并承担相应法律责任。"},{"sectionNo":"十三","headline":"审查材料与申报条件，查同一项目多头或重复申报","who":"经推荐单位审核推荐申报市科技项目的单位。","materials":[],"window":"推荐后由市科技局组织形式审查与实质审查。","where":"株洲市科学技术局","tip":"同一项目多头或重复申报会被查出，影响立项。"},{"sectionNo":"十五","headline":"拟立项项目公示不少于5个工作日","who":"通过专家评审、拟立项的申报项目单位。","materials":[],"window":"公示期不少于5个工作日，涉密项目除外。","where":"株洲市科学技术局、株洲市财政局","tip":"公示无异议后才下达专项资金；涉密项目不公示。"},{"sectionNo":"十六","headline":"立项后签任务书，不同支持方式按节点拨款","who":"经公示无异议后立项的项目承担单位。","materials":["项目任务书"],"window":"前资助立项即下达；事前立项事后补助验收合格后下达；事后立项事后补助与政策兑现按核定文件下达。","where":"株洲市科学技术局、株洲市财政局","tip":"任务书由市科技局与承担单位及时签订，资金按支持方式分别下达。"},{"sectionNo":"十七","headline":"资金到文后30个工作日内拨付，不得截留挪用","who":"各县市区财政部门、项目牵头单位及项目参与单位。","materials":[],"window":"收到专项资金文件后30个工作日内拨付项目承担单位；牵头单位30个工作日内拨付参与单位。","where":"各县市区财政部门、项目牵头单位","tip":"不得截留、挪用，牵头单位须按任务书要求和项目负责人意见转拨。"},{"sectionNo":"十九","headline":"结余资金结转，验收通过且信用良好可留归单位","who":"前资助项目承担单位（通过验收且无不良信用记录）。","materials":[],"window":"实施期内年度结余结转下一年度；实施期满通过验收后结余可统筹用于本单位科研活动支出。","where":"项目承担单位","tip":"有不良信用记录的不适用；结余须用于本单位科研活动支出。"},{"sectionNo":"二十","headline":"后补助资金由承担单位统筹，不再组织验收","who":"后补助项目承担单位。","materials":[],"window":"经核定拨付后由承担单位统筹安排，不再组织资金过程管理和验收。","where":"项目承担单位（市科技局核定）","tip":"后补助资金不再单独开展财务验收。"},{"sectionNo":"二十四","headline":"虚报截留挪用资金依法查处并追责","who":"资金使用单位及相关责任人。","materials":[],"window":"发现违法违规即按预算法、财政违法行为处罚处分条例查处；涉嫌犯罪追究刑责。","where":"科技、财政、审计等部门","tip":"擅自改变专项资金用途同样属违法违规行为。"}],"sourceUrl":"https://img.zhuzhou.gov.cn/zzcms/DFS//file/2024/08/07/20240807100214179avxhez.pdf","sourceNote":"2026-11-22 取自株洲市人民政府门户原文页（https://www.zhuzhou.gov.cn/c19478/20240807/i2229972.html）所挂 PDF 附件；正文为扫描件，已按《zz-tech-fund-2024.checked.txt》校对单逐页对照原件修正 8 处。 正文来源：扫描版 PDF（10 页，无文字层），经 Windows OCR 逐页识别后整理；已去除字符间空格与页眉页脚，条号按原文保留。个别字词、标点在页边界处可能被截断或识别有误，引用前请核对官方原件。","verified":false,"isSample":false,"numberStyle":"clause","bodyVerified":"ocr","hunan":true},{"id":"zz-tianyuan-aigc-talent-2025","title":"印发《关于引进培养AIGC产业人才十条措施（试行）》的通知","level":"district","region":"株洲市·天元区","issuer":"株洲高新区管委会、中共株洲市委人才工作领导小组办公室","documentNo":"株高政发〔2025〕1号","publishedAt":"2025-02-24","effectiveAt":"2025-02-24","expiresAt":"2028-02-23","status":"active","tags":["人才政策","创业补贴","场地支持"],"audience":["AIGC产业人才及团队","入驻株洲AIGC内容生产中心的创业企业"],"summary":"设立1000万元株洲市AIGC产业人才培养专项资金，由市级人才专项资金与株洲高新区按1:1共同出资、分2年完成；入驻内容生产中心并经评审认定的重点人才可获最高5万元创业启动资金，首年产出12个以上作品的个人或团队按每件4000元给予最高100万元奖励，并提供两年免费、三年减半的孵化空间租金优惠。","sections":[{"no":"二","title":"","text":"设立 1000 万元的株洲市 AIGC 产业人才培养专项资金，由市级人才专项资金和株洲高新区按 1:1 比例共同出资，分 2 年完成。专项资金主要用于支持引进培养 AIGC 产业人才及团队，扶持株洲 AIGC 内容生产中心建设，株洲高新区作为专项资金执行主体，履行资金管理主体责任，制定专项资金管理办法，负责资金的审批、拨付、使用及监督管理。（责任单位：株洲高新区管委会、市委人才办）"},{"no":"三","title":"","text":"天元智能科学研究院负责对入驻 AIGC 内容生产中心的产业人才进行评审认定，经评审认定为重点人才的，可给予最高 5 万元的创业启动资金，每年创业启动资金拨付总额不超过 100 万元。（责任单位：株洲高新区管委会、天元智能科学研究院、市委人才办）"},{"no":"四","title":"","text":"支持 AIGC 产业人才及团队加强创新创作。株洲 AIGC 内容生产中心启动运营后首年，对当年产出作品达 12 个以上（含 12 个）的入驻人才及团队，按照每个作品 4000 元标准给予单个人才或团队最高 100 万元资金奖励；第二年，对当年产出作品达 24 个以上（含 24 个）的入驻人才及团队，按照每个作品 2000 元标准给予单个人才或团队最高 100 万元资金奖励。（责任单位：株洲高新区管委会）"},{"no":"六","title":"","text":"为 AIGC 产业人才及团队提供创业孵化空间，由空间运营主体按市场化原则给予入驻人才及团队两年免费、三年减半的租金优惠，为创业者提供一站式服务，入驻资格由天元智能科学研究院认定，报株洲高新区管委会审定或备案。（责任单位：天元智能科学研究院、株洲高新区管委会）"}],"interpretations":[{"sectionNo":"三","headline":"入驻AIGC中心经评审认定为重点人才，最高5万元启动资金","who":"入驻株洲AIGC内容生产中心的AIGC产业人才；须经天元智能科学研究院评审认定为重点人才。","materials":[],"window":"每年创业启动资金拨付总额不超过100万元，按评审认定批次拨付。","where":"天元智能科学研究院、株洲高新区管委会","tip":"须先入驻并经评审认定为重点人才，不是入驻即得；每年拨付总额不超过100万元，存在额度用尽风险。"},{"sectionNo":"四","headline":"首年产作品12个以上，每个奖4000元，最高100万元","who":"株洲AIGC内容生产中心启动运营后首年，当年产出作品达12个以上（含12个）的入驻人才及团队；第二年当年产出作品达24个以上（含24个）的入驻人才及团队。","materials":[],"window":"中心启动运营后首年按12个、第二年按24个作品核算，单个人才或团队最高100万元。","where":"株洲高新区管委会","tip":"首年每个作品4000元、第二年每个作品2000元；单个人才或团队均以100万元封顶。"},{"sectionNo":"六","headline":"入驻AIGC中心，场地两年免费、三年租金减半","who":"AIGC产业人才及团队；入驻资格由天元智能科学研究院认定，报株洲高新区管委会审定或备案。","materials":[],"window":"两年免费、三年减半，自入驻认定后按运营主体约定执行。","where":"空间运营主体、天元智能科学研究院、株洲高新区管委会","tip":"租金优惠由空间运营主体按市场化原则给予；入驻资格须经认定并报管委会审定或备案。"}],"sourceUrl":"https://img.zhuzhou.gov.cn/zzcms/DFS//file/2025/03/04/20250304103038963p4k31i.pdf","sourceNote":"正文取自附件：天元区政府门户「政策文件」原文页 /c16354/20250304/i2325054.html 所挂 PDF（扫描版，无文字层）。2026-11-22 按原件转录，文号（株高政发〔2025〕1号）、成文日期（2025年2月24日）与金额对照原件核对；扫描件无法自动逐句比对。 2026-11-22 收录：官方页面未能打开或不是正文（pages/pdf），条文未与原文比对。 有效期依据：PDF 第 4 页正文末段明示有效期三年，按成文日期 2025-02-24 推算","verified":false,"isSample":false,"numberStyle":"clause","bodyVerified":"unverifiable","hunan":true},{"id":"zz-tianyuan-tech-renovation-fund-2026","title":"关于印发《天元区制造业新型技术改造试点重点项目和专项资金管理办法》的通知","level":"district","region":"株洲市·天元区","issuer":"株洲市天元区科技和工业信息化局、株洲市天元区财政局","documentNo":"株天科工信发〔2026〕2号","publishedAt":"2026-11-13","effectiveAt":"2026-11-13","expiresAt":"2029-11-12","status":"active","tags":["专项资金","研发创新"],"audience":["天元区通用设备制造业企业","天元区汽车制造业企业","制造业技术改造项目实施单位"],"summary":"天元区制造业新型技术改造试点重点项目和专项资金管理办法共 9 章 24 条：省级财政拨付 1000 万元试点奖励资金，统筹用于技术改造投入补助和标杆示范奖励；单个项目补助额度最低不低于 30 万元、最高不超过 200 万元；标杆示范项目一次性奖励原则上单个项目不超过 100 万元，且不超过项目补助金额；拨付分首发补助（拨付省级首批专项资金的 60% 以上）、中期补助、验收补助三步。办法自印发之日起施行，有效期三年。","sections":[{"no":"一","title":"总则","text":"为扎实推进我区制造业新型技术改造试点工作，规范省级试点专项资金管理、提升资金使用效益，推动制造业智能化、绿色化、融合化转型升级，根据《关于印发〈规范地方财政补贴工作问答（一）〉的通知》（财综〔2026〕42号）《湖南省持续用力打造国家重要先进制造业高地若干财政支持政策》（湘财产业〔2026〕9号）《湖南省制造业新型技术改造县（市、区）试点工作规程》（湘工信投资〔2026〕222号）《湖南省工业和信息化厅关于〈2026年制造业新型技术改造县（市、区）试点实施方案〉的批复》（湘工信投资〔2026〕356号）等文件要求，结合天元区产业发展实际，制定本办法。"},{"no":"二","title":"总则","text":"本办法适用于本行政区域内制造业新型技术改造试点重点项目（以下简称重点项目）的实施调度、绩效自评、竣工验收、省级试点专项资金申报、拨付、监管及区本级配套资金统筹管理工作。"},{"no":"三","title":"总则","text":"本办法所称重点项目，是指由株洲市天元区科技和工业信息化局根据本区产业发展规划，从通用设备制造业、汽车制造业两个行业中遴选，报省工业和信息化厅备案的项目。"},{"no":"四","title":"总则","text":"本办法所称专项资金，是指省级财政下达和区本级配套用于支持我区开展制造业新型技术改造试点工作的资金。"},{"no":"五","title":"总则","text":"资金的使用和项目管理遵循“科学规范、专款专用、全面统筹、公开透明、注重绩效\"的原则。"},{"no":"六","title":"职责分工","text":"区科技和工业信息化局、区财政局按照职责分工，协同做好试点重点项目及专项资金全流程管理工作。（一）区科技和工业信息化局牵头统筹试点整体工作，组织项目征集、初审、综合评审、日常调度、年度绩效评价组织、竣工验收等全流程工作，拟定资金分配及拨付方案。（二）区财政局负责及时拨付省级财政奖补资金；负责对专项资金的预算执行、资金使用情况进行监督检查；会同区科技和工业信息化局开展专项资金绩效管理工作及综合整体验收。（三）项目实施单位为项目实施、资金使用责任主体，须严格按照任务书明确的建设内容、时间节点推进项目实施，按期报送进度、财务、绩效评价材料，主动配合调度、核查与验收工作，确保项目按期保质完成。"},{"no":"七","title":"重点项目管理","text":"重点项目实行台账式管理，按照“一项一书一台账\"原则，各项目实施单位应当签订项目实施任务书、建立专项台账，按期推进建设进度。项目实施过程中，须按规定时限向区科技和工业信息化局报送项目进展资料。"},{"no":"八","title":"重点项目管理","text":"项目实施单位须在规定时限内与区科技和工业信息化局签订项目任务书，任务书一经签订原则上不予变更；逾期未签订任务书的，视同自动放弃项目试点及资金补助资格。"},{"no":"九","title":"重点项目管理","text":"任务书载明的实施主体（含联合共建单位）、总投资额、智能化、绿色化建设指标等核心内容，须与项目申报内容保持一致；各项经济、技改绩效指标做到清晰、量化、可考核，项目建设分工、资金投入计划、智能改造、绿色升级、产业融合建设成效等关键内容全部在任务书中予以明确。"},{"no":"十","title":"重点项目管理","text":"区科技和工业信息化局会同区财政局统筹开展项目指导、日常监管，根据项目推进情况不定期组织专家开展现场抽查核验。现场核查指出问题的，项目实施单位须在一个月内完成整改，并将整改落实情况书面反馈区科技和工业信息化局、区财政局。"},{"no":"十一","title":"重点项目管理","text":"区科技和工业信息化局收到变更申请后，会同区财政局联合出具审核意见，按程序上报市工业和信息化局、市财政局，由市级主管部门审核后统一报送省工业和信息化厅、省财政厅，待上级批复同意后方可实施调整。（一）项目实施主体发生变更；（二）项目主要建设内容、建设性质发生重大调整；（三）项目督导过程中查实建设内容虚假、实施进度严重滞后、绩效指标无法完成、绩效评价不合格、预期效益明显下滑等问题；（四）法律法规、省市试点政策规定的其他重大变更事项；（五）自然灾害、政策变动等不可抗力因素导致项目难以正常实施。"},{"no":"十二","title":"重点项目绩效自评","text":"项目实施单位实行年度绩效自评制度，每年11月前向区科技和工业信息化局报送年度绩效自评报告，报告包含以下内容：（一）全部申报、佐证资料真实性承诺函；（二）项目年度建设推进完成情况及总体进度完成情况；（三）各项定量、定性绩效目标完成程度分析；（四）项目实施带来经济效益、社会效益综合评估；（五）技改实施采取的举措、破解的痛点、形成的典型改造模式、实际改造成果以及可复制推广经验；（六）项目现存短板、问题及下一步整改提升方案；（七）项目相关的合同、发票、会计凭证等全套财务佐证材料。"},{"no":"十三","title":"重点项目绩效自评","text":"年度绩效自评材料由区科技和工业信息化局统一收集初审，区科技和工业信息化局、区财政局视工作安排组织实地现场核查。对自评材料缺漏、绩效指标未达标的项目，项目实施单位须在收到整改通知10个工作日内完成整改并提交正式整改报告；年度绩效出现重大变动、无法按期完成既定任务的，同步按项目变更流程提交调整申请。"},{"no":"十四","title":"重点项目验收管理与评价","text":"项目全部建设内容完工后，实施单位须及时向区科技和工业信息化局提交验收申请。区科技和工业信息化局先行开展初审，初审合格后联合区财政局统筹组织项目综合验收。"},{"no":"十五","title":"重点项目验收管理与评价","text":"区科技和工业信息化局、区财政局对照《湖南省制造业新型技术改造县（市、区）试点工作规程》等相关文件要求开展项目整体验收。验收未通过的，项目实施单位自收到整改通知起一个月内完成整改，并重新报送验收材料；逾期未申请复验，或整改后验收仍不合格的，不予通过项目验收，并将收回全部已拨付奖励资金。"},{"no":"十六","title":"重点项目验收管理与评价","text":"全部项目完成综合验收后，区科技和工业信息化局结合年度绩效自评、项目实际改造成果开展标杆项目遴选并予以一次性奖励，表彰技改示范成效突出的实施主体。若省级专项资金全部用于入库试点项目补助，则不再安排标杆项目专项奖励。标杆项目遴选参考标准如下：（一）项目落地后生产效率、产品合格率、能耗成本等经营指标提升幅度；（二）项目投入国产工业母机、工业机器人、自主工业软件、工业操作系统的规模与应用成效；（三）项目实施形成的新能源装备、新能源汽车行业标准化数字化、绿色改造解决方案数量与落地价值；（四）其他在产业带动、模式创新、降本增效、示范推广等方面成效突出，经区科技和工业信息化局综合认定的加分情形。"},{"no":"十七","title":"资金拨付","text":"省级专项资金支持标准。省级财政拨付的1000万元试点奖励资金，统筹用于技术改造投入补助和标杆示范奖励两类支出。（一）技术改造投入补助。结合“点\"“线”“面”项目类型、技术先进性水平和行业示范带动效应等进行统筹分配。单个项目补助额度最低不低于30万元、最高不超过200万元，专项资金不针对特定经营者进行补贴支持。（二）标杆示范奖励。从省级试点专项资金结余中统筹安排，重点项目通过竣工验收并经综合评定，对成功遴选为标杆示范项目的给予一次性奖励，原则上单个项目奖励金额不超过100万元，标杆奖励金额不超过项目补助金额。"},{"no":"十八","title":"资金拨付","text":"省级专项资金拨付方式。（一）首发补助。对已开工入统，建设进度达预期且签订任务书的“点\"“线”“面”重点项目，经天元区人民政府官方网站公示5个工作日公示无异议后，以技术改造投入补助形式拨付奖补资金，拨付省级首批专项资金的60％以上。（二）中期补助。项目实施中期现场核查、绩效评价达标后拨付，以技术改造投入补助形式拨付剩余省级首批专项资金。（三）验收补助。省级后续专项资金下达后，对全部完成建设内容的项目且通过区级联合综合验收合格和综合绩效评价后，拨付剩余补助资金；符合条件的标杆示范项目，从专项资金结余中拨付标杆奖励资金，无结余则不予兑现。"},{"no":"十九","title":"资金拨付","text":"项目变更后资金管理。（一）对于首发补贴未拨付，重点项目出现无法建设或重大变化的，资金不予拨付。（二）对于首发补贴已拨付，实施过程中出现无法建设或重大变化的重点项目，将及时暂停其重点项目资格，由区科技和工业信息化局会同区财政局按规定流程追回已拨付资金，并将有关情况专题上报市工业和信息化局、市财政局，再由市级主管部门按程序汇总上报省工业和信息化厅、省财政厅。（三）对未通过审核验收的重点项目，按照规定程序追回已拨付资金。（四）上述未拨付资金和按规定程序追回的资金，用于奖励标杆示范项目。"},{"no":"二十","title":"区级配套资金支持范围及管理","text":"区级配套资金支持全区制造业企业技术改造，涵盖企业智能化产线升级、绿色低碳工艺改造、产业链协同平台建设、园区数字与零碳基础设施搭建、本土数字化服务商培育等领域，按合规方式予以支持区级配套资金申报、拨付、不予支持、资金追回流程，参照本办法省级专项资金相关规定执行。"},{"no":"二十一","title":"监督管理与法律责任","text":"项目实施单位应当恪守诚信原则，严格执行财务会计管理制度，落实专项资金专款专用规定，仅列支与本试点项目直接相关的支出，严禁截留、挤占专项资金或列支无关费用，如实完整提交项目申报、财务、绩效等全部佐证材料。对伪造申报资料、虚报设备及工程投资、套取骗取补助、截留挤占、挪用专项资金等违规行为的，立即取消项目补助资格，全额追回已拨付资金，项目单位三年内不得申报全区各类产业扶持专项资金；涉嫌违法犯罪的，依法移送司法机关处理。"},{"no":"二十二","title":"监督管理与法律责任","text":"区科技和工业信息化局联合区财政局常态化开展专项资金监督检查，可按规定委托第三方专业机构开展专项审计、绩效核查。项目单位及经办工作人员存在截留挤占资金、审核把关不严、违规审批等违法违规行为的，责令限期整改；涉嫌违纪、犯罪的，依规依纪、依法移送相关机关追究责任。"},{"no":"二十三","title":"附则","text":"本办法自印发之日起施行，有效期三年。本办法由区科技和工业信息化局、区财政局共同解释。"},{"no":"二十四","title":"附则","text":"本办法执行期间，若国家、省、市出台资金使用新政策，按新政策执行。"}],"interpretations":[{"sectionNo":"二","headline":"重点项目全流程管理：调度、自评、验收、资金申报拨付","who":"天元区行政区域内制造业新型技术改造试点重点项目实施单位，覆盖项目实施调度、绩效自评、竣工验收、省级试点专项资金申报拨付监管及区本级配套资金统筹。","materials":[],"window":"覆盖项目实施调度、年度绩效自评、竣工验收、省级试点专项资金申报拨付及监管全过程。","where":"区科技和工业信息化局、区财政局","tip":"本办法只管试点重点项目及省级、区本级两级资金，非试点项目不适用。"},{"sectionNo":"三","headline":"重点项目只从通用设备制造、汽车制造两个行业遴选","who":"天元区通用设备制造业、汽车制造业企业；须由区科技和工业信息化局按本区产业发展规划遴选，并报省工业和信息化厅备案。","materials":[],"window":"按区产业发展规划遴选，报省工业和信息化厅备案。","where":"株洲市天元区科技和工业信息化局","tip":"未纳入遴选、未报省工业和信息化厅备案的项目不属于重点项目。"},{"sectionNo":"四","headline":"专项资金由省级财政下达和区本级配套","who":"经遴选备案的天元区制造业新型技术改造试点重点项目实施单位。","materials":[],"window":"按省级财政下达和区本级配套安排，随项目进度拨付。","where":"省级财政、区本级财政（经区科技和工业信息化局、区财政局管理）","tip":"资金仅用于支持我区开展制造业新型技术改造试点工作。"},{"sectionNo":"七","headline":"重点项目须签任务书、建专项台账并按期报进展","who":"经遴选备案的重点项目实施单位。","materials":["项目实施任务书","专项台账","项目进展资料"],"window":"项目实施过程中按规定时限向区科技和工业信息化局报送项目进展资料。","where":"区科技和工业信息化局","tip":"实行台账式管理，未建台账或未按期报送进展会影响调度与验收。"},{"sectionNo":"八","headline":"逾期未签项目任务书视同放弃试点及补助资格","who":"已入选重点项目、须签订任务书的项目实施单位。","materials":["项目任务书"],"window":"须在规定时限内签订；任务书一经签订原则上不予变更。","where":"区科技和工业信息化局","tip":"逾期未签订视同自动放弃项目试点及资金补助资格；任务书签订后原则上不予变更。"},{"sectionNo":"九","headline":"任务书核心内容须与申报一致，绩效指标要可考核","who":"签订任务书的重点项目实施单位（含联合共建单位）。","materials":["项目任务书"],"window":"签订任务书时明确，实施期内按任务书载明内容考核。","where":"区科技和工业信息化局","tip":"实施主体、总投资额、智能化绿色化指标须与申报一致，经济与技改绩效指标须清晰、量化、可考核。"},{"sectionNo":"十","headline":"现场核查发现问题须一个月内整改并书面反馈","who":"被现场抽查核验的重点项目实施单位。","materials":["整改落实情况书面反馈"],"window":"现场核查指出问题后一个月内完成整改。","where":"区科技和工业信息化局、区财政局","tip":"整改落实情况须书面反馈两部门，整改不到位会影响后续核查与验收。"},{"sectionNo":"十一","headline":"实施主体、建设内容等重大变更须逐级报批后实施","who":"出现实施主体变更、建设内容或建设性质重大调整、进度严重滞后、绩效评价不合格、不可抗力等情形的重点项目实施单位。","materials":["项目变更申请"],"window":"区科技和工业信息化局会同区财政局出具审核意见后逐级上报，批复同意后方可调整。","where":"区科技和工业信息化局、区财政局（上报市工业和信息化局、市财政局、省工业和信息化厅、省财政厅）","tip":"五类情形含查实建设内容虚假、预期效益明显下滑，以及自然灾害、政策变动等不可抗力。"},{"sectionNo":"十二","headline":"每年11月前报年度绩效自评报告并附财务佐证","who":"重点项目实施单位。","materials":["年度绩效自评报告（含真实性承诺函）","项目相关的合同、发票、会计凭证等全套财务佐证材料"],"window":"每年11月前报送年度绩效自评报告。","where":"区科技和工业信息化局","tip":"报告须含全部申报、佐证资料真实性承诺函、绩效目标完成分析、短板问题及整改提升方案。"},{"sectionNo":"十三","headline":"自评缺漏或指标未达标须10个工作日内整改","who":"年度绩效自评材料缺漏或绩效指标未达标的重点项目实施单位。","materials":["正式整改报告","项目调整申请（年度绩效重大变动时）"],"window":"收到整改通知10个工作日内完成整改；绩效重大变动同步按变更流程提交调整申请。","where":"区科技和工业信息化局、区财政局","tip":"无法按期完成既定任务的，须同步按项目变更流程提交调整申请。"},{"sectionNo":"十四","headline":"项目完工后申请验收，初审合格再组织综合验收","who":"全部建设内容完工的重点项目实施单位。","materials":["验收申请"],"window":"全部建设内容完工后及时提交验收申请，初审合格后组织综合验收。","where":"区科技和工业信息化局（初审）、区财政局（联合验收）","tip":"初审不合格不进入联合综合验收，后续补助无法拨付。"},{"sectionNo":"十五","headline":"验收未通过须一个月内整改，仍不合格收回全部奖补","who":"验收未通过的重点项目实施单位。","materials":["验收材料（重新报送）"],"window":"收到整改通知起一个月内完成整改并重新报送验收材料。","where":"区科技和工业信息化局、区财政局","tip":"逾期未申请复验或整改后验收仍不合格的，不予通过验收并收回全部已拨付奖励资金。"},{"sectionNo":"十六","headline":"通过综合验收可参评标杆项目并获一次性奖励","who":"全部完成综合验收、技改示范成效突出的重点项目实施单位。","materials":[],"window":"全部项目完成综合验收后组织遴选；省级专项资金全部用于入库项目补助时不再安排标杆奖励。","where":"区科技和工业信息化局","tip":"遴选看生产效率、产品合格率、能耗成本提升，以及国产工业母机、工业机器人、自主工业软件应用成效。"},{"sectionNo":"十七","headline":"省级试点奖励1000万元，单项目补助30万至200万元","who":"纳入试点并签订任务书的「点线面」重点项目实施单位；专项资金不针对特定经营者进行补贴支持。","materials":[],"window":"省级财政拨付1000万元试点奖励资金，统筹用于技术改造投入补助和标杆示范奖励。","where":"省级财政（经区科技和工业信息化局、区财政局拨付）","tip":"单个项目补助最低30万元、最高200万元；标杆奖励不超过100万元且不超过项目补助金额。"},{"sectionNo":"十八","headline":"首拨省级首批专项资金60%以上，中期与验收后拨剩余","who":"已开工入统、建设进度达预期且签订任务书的「点线面」重点项目实施单位。","materials":[],"window":"公示5个工作日后首发；中期核查、绩效评价达标后拨剩余首批；完工通过验收和绩效评价后拨剩余及标杆奖励。","where":"天元区人民政府官方网站公示；区科技和工业信息化局、区财政局拨付","tip":"中期补助须现场核查和绩效评价达标；标杆奖励从结余中列支，无结余不予兑现。"},{"sectionNo":"十九","headline":"项目无法建设即停拨，已拨资金按规定追回","who":"出现无法建设或重大变化、未通过审核验收的重点项目实施单位。","materials":[],"window":"首发补贴未拨付的不予拨付；已拨付的暂停重点项目资格并追回。","where":"区科技和工业信息化局、区财政局（逐级上报市、省主管部门）","tip":"追回资金用于奖励标杆示范项目；未通过验收的同样追回已拨付资金。"},{"sectionNo":"二十","headline":"区级配套支持智能化产线、绿色低碳工艺等技改","who":"全区制造业企业，涵盖智能化产线升级、绿色低碳工艺改造、产业链协同平台建设、园区数字与零碳基础设施搭建、本土数字化服务商培育。","materials":[],"window":"申报、拨付、不予支持、资金追回流程参照省级专项资金规定执行。","where":"区科技和工业信息化局、区财政局","tip":"区级配套按合规方式支持，具体流程参照本办法省级专项资金相关规定。"},{"sectionNo":"二十一","headline":"伪造资料套取补助，取消资格追回资金并三年禁申","who":"所有项目实施单位。","materials":["项目申报、财务、绩效等全部佐证材料"],"window":"违规即取消补助资格、全额追回；项目单位三年内不得申报全区各类产业扶持专项资金。","where":"区科技和工业信息化局（涉嫌犯罪移送司法机关）","tip":"专款专用，仅列支与本试点项目直接相关支出；截留、挤占、挪用同属违规。"}],"sourceUrl":"https://img.zhuzhou.gov.cn/zzcms/DFS//file/2026/11/19/20261119171653471en794d.pdf","derivedFrom":"ocr","sourceNote":"正文取自株洲市政府门户图片服务器所挂 PDF（株天科工信发〔2026〕2 号，扫描版，无文字层）。2026-11-24 用 Windows.Media.Ocr 逐页识别原件后按条重切全文 24 条，金额与比例（1000 万元、30 万元、200 万元、100 万元、60%）已对照原件页面图像逐字复核。 2026-11-24 收录：原件为扫描件（无文字层），条文系 OCR 转录后按条重切，机器无法独立比对；金额与比例已对原件页面图像逐字复核。 有效期依据：第二十三条：本办法自印发之日起施行，有效期三年","verified":false,"isSample":false,"numberStyle":"clause","bodyVerified":"unverifiable","hunan":true},{"id":"zz-univ-2025-11","title":"株洲市人民政府办公室关于印发《株洲市进一步支持大学生创新创业若干措施》的通知","level":"city","region":"株洲市","issuer":"株洲市人民政府办公室","documentNo":"株政办发〔2025〕11号","publishedAt":"2025-10-21","effectiveAt":null,"expiresAt":null,"status":"active","tags":["创业补贴","人才政策","场地支持"],"audience":["高校在校生","毕业5年内大学生","高校科研人员","大学生创业载体运营单位"],"summary":"政府投资开发的孵化器等载体应免费提供不少于30%的场地支持大学生创新创业；科研人员离岗创业可保留人事关系3年。","sections":[{"no":"一","title":"强化重点领域人才引育","text":"支持高校在校生、毕业5年内大学生及高校科研人员围绕株洲“3+3+2”现代化产业体系，以“揭榜挂帅”“先用后付”等方式提供技术解决方案或产品，开展创新创业。"},{"no":"一续","title":"离岗创业人事关系","text":"鼓励高校科研人员离岗（或在职）与学生共同创办企业，离岗与学生共同创办企业的，按程序经单位批准可以保留人事关系3年，期间停发工资福利待遇，养老保险、医疗保险、职业年金依法继续由人事关系所在单位缴纳，个人部分由个人负责。"},{"no":"一续二","title":"职务科技成果转化收益","text":"职务科技成果转化收益可按不低于70%奖励团队，实施成果转化后可连续3-5年提取营业利润10%以上作为奖励。"},{"no":"二","title":"完善创业载体建设","text":"政府投资开发的孵化器等载体，应免费提供不少于30%的场地支持大学生创新创业。探索建立“大学生创业载体联盟”，重点扶持湖南工业大学、在株职业院校、株洲高新区双创中心、湖南九郎山职教科创城发展集团有限公司、中车株洲电力机车研究所有限公司等单位建设在全省、全市有较强影响力的大学生创业载体。"}],"interpretations":[{"sectionNo":"一","headline":"在校生、毕业5年内大学生及科研人员可揭榜挂帅创业","who":"高校在校生、毕业5年内大学生及高校科研人员；须围绕株洲“3+3+2”现代化产业体系，以“揭榜挂帅”“先用后付”等方式提供技术解决方案或产品。","materials":[],"window":"原文未限定申报期限，为常态化支持措施。","where":"原文未写明受理窗口；实施范围为株洲“3+3+2”现代化产业体系相关领域。","tip":"毕业时间以5年内为限；须围绕“3+3+2”产业体系、以“揭榜挂帅”“先用后付”方式提供技术方案或产品，不是直接发补贴。"},{"sectionNo":"一续","headline":"科研人员离岗与学生办企业，可保留人事关系3年","who":"高校科研人员（离岗或在职）与学生共同创办企业；离岗创办须按程序经单位批准；保留人事关系期间停发工资福利待遇。","materials":[],"window":"可保留人事关系3年，自离岗与学生共同创办企业起算。","where":"人事关系所在单位（须按程序报批）。","tip":"保留关系期间停发工资福利待遇；养老保险、医疗保险、职业年金由单位继续缴纳，个人部分由个人负责。"},{"sectionNo":"一续二","headline":"成果转化收益不低于70%奖团队，可连续3-5年提利润10%","who":"高校科研人员团队；针对职务科技成果转化，收益可按不低于70%奖励团队，实施转化后可连续3-5年提取营业利润10%以上。","materials":[],"window":"实施成果转化后可连续3-5年提取营业利润10%以上作为奖励。","where":"原文未写明受理窗口；由科技成果所在高校及团队按转化收益分配执行。","tip":"70%是不低于的下限；3-5年为可连续提取区间，10%为营业利润提取下限；仅限职务科技成果转化收益。"},{"sectionNo":"二","headline":"政府投资的孵化器须免费提供不少于30%场地给大学生","who":"大学生创新创业者；可入驻政府投资开发的孵化器等载体，免费场地比例不少于30%；重点载体包括湖南工业大学、在株职业院校、株洲高新区双创中心等。","materials":[],"window":"原文未限定申请期限；免费场地比例按不少于30%执行。","where":"政府投资开发的孵化器等载体；重点扶持湖南工业大学、株洲高新区双创中心、湖南九郎山职教科创城发展集团有限公司、中车株洲电力机车研究所有限公司等。","tip":"30%是免费场地的最低比例，不是全部免费；强制对象为政府投资开发的载体，社会投资载体不在其列。"}],"sourceUrl":"http://img.zhuzhou.gov.cn/zzcms/DFS//file/2025/11/12/202511121050263422ywzvb.pdf","sourceNote":"2026-11-21 原登记链接指向商业资讯站附件（img9.qianzhan.com），不在信源白名单，已置空；文号株政办发〔2025〕11号与条款已核对，待取得政府门户原文页后回填。 原文链接由核对脚本定位：标题已在页面命中。 2026-11-21 收录：与官方页面逐句比对，命中 5/5 句（100%），关卡判定「verbatim」。 有效期依据：原文未设期限；按行政规范性文件一般不超5年推算至2030-10","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"zz-univ-startup-2025","title":"株洲高新区关于支持大学生创新创业的实施意见（试行）","level":"district","region":"株洲市·天元区","issuer":"株洲高新区管委会","documentNo":"","publishedAt":"2025-01-16","effectiveAt":"2025-01-16","expiresAt":"2026-01-15","status":"expired","tags":["创业补贴","场地支持"],"audience":["株洲本地高校在校大学生","株洲籍毕业5年内创业团队","大学生创业企业"],"summary":"株洲高新区管委会设立500万元专项资金池，对经评审通过的大学生创业项目按5万元、10万元、20万元标准给予无偿资助，并优先推荐入驻孵化载体、申报“先投后股”资金支持。","sections":[{"no":"第二条","title":"","text":"株洲高新区管委会设立500万元专项资金池，用于支持大学生创新创业，授权株洲高新区动力谷创新创业服务中心（以下简称双创中心）负责组织实施。"},{"no":"第四条","title":"","text":"本意见所支持的对象是指在株洲本地高校、与株洲战略合作高校、其他高校株洲籍的在校大学生，在株洲本地高校、与株洲战略合作高校、其他高校株洲籍的毕业不超过5年的创业团队及个人。"},{"no":"第五条","title":"创业项目支持","text":"采取事前支持方式，根据大学生创业项目的经济和社会效益、科技含量、市场前景进行评判，经评审通过后单个项目可按照5万元、10万元、20万元的标准给予创业支持。"},{"no":"第七条","title":"","text":"对获得支持的创业项目，将优先推荐给各级政府投资建设的大学科技园、科技企业孵化器等载体，各园区根据自身实际可给予一定的场地免租支持。"}],"interpretations":[{"sectionNo":"第四条","headline":"株洲高校在校生及株洲籍毕业5年内创业者均可申报","who":"株洲本地高校、与株洲战略合作高校的在校大学生；株洲本地高校、与株洲战略合作高校及其他高校株洲籍的毕业不超过5年的创业团队及个人。","materials":[],"window":"在校期间，或毕业不超过5年内","where":"株洲市（株洲本地高校、与株洲战略合作高校；其他高校须株洲籍）","tip":"其他高校非株洲籍的在校生、毕业生不在支持范围；毕业超过5年即不符合条件"},{"sectionNo":"第五条","headline":"评审通过的大学生创业项目可获5万、10万、20万元支持","who":"株洲本地高校、与株洲战略合作高校就读或毕业不超过5年的创业团队及个人，项目经评审通过，并按经济和社会效益、科技含量、市场前景评判。","materials":[],"window":"采取事前支持方式，经评审通过后给予","where":"株洲高新区动力谷创新创业服务中心（双创中心）","tip":"三个档次金额由评审结果确定，未通过评审不予支持；资金在项目评审通过后事前拨付"},{"sectionNo":"第七条","headline":"获支持项目优先推荐进大学科技园、孵化器，可获场地免租","who":"获得本意见支持的创业项目；入驻后由各园区根据自身实际给予场地免租支持。","materials":[],"window":"入驻后按各园区自身实际确定，原文未设统一免租期限","where":"各级政府投资建设的大学科技园、科技企业孵化器等载体","tip":"免租由各园区自行决定，不是所有获支持项目都享受同一免租标准"}],"sourceUrl":"http://www.tianyuan.gov.cn/c16354/20250116/i2305647.html","sourceNote":"2026-11-21 取自株洲市天元区人民政府门户「政策文件」原文页；页面标题与发布时间（2025-01-16）已核对，原文未标注文号。条文为页面正文逐字摘录。原意见第十三条载明试行一年，页面仍列于政策文件栏目且未见废止或延续公告，有效期以最新文件为准。 2026-11-21 收录：与官方页面逐句比对，命中 4/4 句（100%），关卡判定「verbatim」。 有效期依据：原文明示“试行一年，自正式印发之日起施行”，按发布时间2025-01-16推算至2026-01-15；页面仍在政策文件栏目公开，未见废止公告。","verified":false,"isSample":false,"numberStyle":"clause","bodyVerified":"verbatim","hunan":true},{"id":"zzgxq-fund-mgmt-2024","title":"株洲高新区（天元区）基金管理办法（试行）","level":"district","region":"株洲市·天元区","issuer":"株洲高新区管委会、株洲市天元区人民政府","documentNo":"株高天政发〔2024〕4号","publishedAt":"2024-12-30","effectiveAt":"2024-12-30","expiresAt":"2026-12-29","status":"expiring","tags":["融资支持","财政奖补","研发创新"],"audience":["株洲高新区（天元区）政策性基金与市场化基金","区属国有公司","基金管理人"],"summary":"基金分政策性基金与市场化基金两类，政策性基金又分产业引导基金、投资促进基金、战略发展基金、天使基金（含科技成果转化类基金）、种子基金等类型，重点投向“2+2”产业集群；基金须委托具备资质的商业银行托管，托管银行原则上应在天元区境内或设有分支机构；政策性基金退出净收益扣除上缴财政和留存出资人代表部分后可用于滚动投资；本办法有效期2年。","sections":[{"no":"一","title":"","text":"为充分发挥株洲高新区（天元区）基金引导金融和社会资本支持我区产业高质量发展的作用，加快形成新质生产力，根据党中央、国务院关于完善国有金融资本管理的有关意见精神，按照《财政部关于印发〈政府投资基金暂行管理办法〉的通知》（财预〔2015〕210号）、《财政部关于财政资金注资政府投资基金支持产业发展的指导意见》（财建〔2015〕1062号）、《财政部关于加强政府投资基金管理提高财政出资效益的通知》（财预〔2020〕7号）、《国家发展改革委关于印发〈政府出资产业投资基金管理暂行办法〉的通知》（发改财金规〔2016〕2800号）、《湖南省财政厅关于印发〈湖南省省级政府性投资基金暂行管理办法〉的通知》（湘财预〔2016〕30号）等文件规定，以及国家、省、市、区国有资产监督管理部门的政策要求，结合我区实际，制定本办法。"},{"no":"二","title":"","text":"本办法所称基金是指由株洲高新区（天元区）财政和区属国有公司出资设立的各类股权投资基金的统称。"},{"no":"三","title":"","text":"基金的组织形式可以采用公司制或有限合伙制，投资形式包括母基金、直投基金和专项基金等。"},{"no":"四","title":"","text":"基金的资金主要来源于区财政资金、区属国有公司资本金投入以及其他出资主体。"},{"no":"五","title":"","text":"基金划分为政策性基金和市场化基金两大类型。政策性基金主要由区财政或区属国有公司出资，由区属国有公司具体运作，重在发挥财政资金的杠杆放大效应和投资引导作用，重点支持株洲高新区（天元区）“2+2”产业集群（即新能源汽车产业、新能源装备产业、新材料产业和电子信息产业）以及其他战略性新兴产业，构建新型产业生态。市场化基金可由财政少量出资作为撬动，主要由区属国有公司以自有资金出资或联合外部资本方共同出资设立，以取得投资收益为主要目标，兼顾支持高新区产业发展。"},{"no":"六","title":"","text":"政策性基金根据设立目的和投向划分为产业引导基金、投资促进基金、战略发展基金、天使基金（含科技成果转化类基金）、种子基金等类型，并采取“一分类一办法”的模式进行管理。"},{"no":"七","title":"","text":"遵循基金投资运行规律，构建金融服务工作联席会议、联席会议办公室、出资人代表和受托管理机构（基金管理人）“四位一体”的株洲高新区（天元区）政策性基金管理体系。联席会议不参与基金日常运营管理，其主要职责是：（一）审议基金相关的管理办法和实施细则等管理文件；（二）审定政策性基金及政策性子基金的设立、重大调整和退出方案；（三）确定基金的投资方向；（四）审定基金年度投资计划等重大事项。"},{"no":"八","title":"","text":"联席会议办公室设在投资金融局，其主要职责是：（一）负责牵头拟订基金相关的管理办法和实施细则等管理文件；（二）初审政策性基金及政策性子基金的设立、重大调整和退出方案；（三）牵头组织认定政策性基金的返投结果；（四）负责组织政策性基金的绩效评估；（五）负责基金管理人提请高新区管委会或联席会议研究决定相关事项的协调工作；（六）负责联席会议的承办工作；（七）负责向财政申报基金年度资金预算；（八）承担联席会议交办的其他工作。"},{"no":"九","title":"","text":"各相关部门根据职能划分履行职责：产业发展局负责制定重点产业发展投资方向指引；发改局负责制定重点行业发展投资方向指引；项目服务局、经济合作局、双创中心、发改局、科工信局、高科集团负责建立重大战略类项目库，支持重点行业类、科创培育类项目库建设；企业服务局负责基金投资项目的落地服务；财政局负责政策性基金出资的年度预算安排，并对出资基金履行监管职责，统筹监管国企出资。各部门可根据基金类型和投资需要，经联席会议同意后向基金参投的子基金派驻观察员，加强对投资基金及项目的培育赋能。"},{"no":"十","title":"","text":"财政局（国资）授权委托株洲高科集团有限公司所属子公司株洲动力谷产业投资发展集团有限公司（以下简称“产投公司”）履行出资人代表职责，在授权范围内，按照联席会议的工作要求负责政策性基金运行的日常监管工作，并对委托人负责。其主要职责是：（一）承担区财政出资人代表职责；（二）承担对受托管理机构的监督管理职责；（三）负责拟订政策性基金的具体设立、调整、退出方案，按程序报批后组织实施；（四）定期向联席会议办公室报告基金运作情况，申报基金返投的初核情况，及时报告重大事项等；（五）承担联席会议办公室交办的其他事项。"},{"no":"十一","title":"","text":"基金应遵循专业化管理原则，由具有专业资质的基金管理机构受托履行日常管理职责，主要包括：（一）建立完善内部决策和风险控制制度；（二）对子基金、投资项目开展尽职调查，形成项目投资建议，制定投资、退出方案；（三）实施经批准的投资方案，签署投资协议和合伙协议（章程），管理基金投资所形成的股权，实施基金投资所形成股权退出工作；（四）监督、指导被投资项目运行情况；（五）定期报告基金运行情况；（六）完成交办的其他工作。"},{"no":"十二","title":"","text":"政策性基金遵循市场在资源配置中起决定性作用和更好发挥政府作用的要求，按照“政府引导、市场运作、科学决策、防范风险”的原则进行投资运作。"},{"no":"十三","title":"","text":"各类政策性基金的设立和管理，另行制定管理实施细则。"},{"no":"十四","title":"","text":"政策性基金应投向符合新区发展导向的产业领域，重点投向主导产业、优势特色产业、战略性新兴产业以及传统支柱产业的改造提升，优先投向具有完善补充产业链关键环节作用的项目。"},{"no":"十五","title":"","text":"政策性基金向受托管理机构原则上按不高于出资额2%/年的比例支付管理费，也可采取投资收益分成等方式给予补贴，具体事宜在政策性基金设立方案中明确。"},{"no":"十六","title":"","text":"政策性基金可以对受托管理机构及其管理团队设置合理的激励约束机制，具体在政策性基金设立方案中明确。政策性基金可以对子基金管理机构和其他出资人设置让利机制，包括回购和让渡超额收益等，具体方式在实施细则中明确。"},{"no":"十七","title":"","text":"市场化基金由区属国有公司归口管理，按照市场化原则进行投资运作，以取得投资收益为主要目标，兼顾支持新区产业发展。"},{"no":"十八","title":"","text":"市场化基金的“募投管退”均按照法律及各级国有资产监督管理的有关规定执行，如无特殊情况，不再另行约定。"},{"no":"十九","title":"","text":"市场化基金应尽量注册在天元区境内，并按国家监管规定要求登记备案及规范运营。"},{"no":"二十","title":"","text":"市场化基金设立后，区属国有公司应定期向联席会议办公室报送半年度和年度基金数据及运营情况。"},{"no":"二十一","title":"","text":"基金一般通过到期清算、基金份额转让、股权转让等方式实施退出，也可通过社会股东回购等其他合法方式退出。"},{"no":"二十二","title":"","text":"基金中途退出时，属于按协议约定退出或有市场参考价（如其他投资人的转让或增资价格、第三方评估价格等）的，可免于产权交易市场公开挂牌转让。不属于协议约定退出或退出时没有市场参考价的，应当聘请有资质的机构进行资产评估，并在依法设立的产权交易机构公开进行。"},{"no":"二十三","title":"","text":"基金按照利益共享、风险共担的原则，协商约定收益分配或亏损负担方式。出资人代表不得向其他出资人承诺投资本金不受损失，不得承诺最低收益（国家另有规定的除外）。"},{"no":"二十四","title":"","text":"基金的退出资金应及时收回并归集至相关基金专户。政策性基金退出形成的投资净收益（含利息收入等），扣除按国资管理相关规定上缴财政和留存出资人代表的部分，剩余收益和本金可用于政策性基金的滚动投资；市场化基金的退出资金按相关规定管理。"},{"no":"二十五","title":"","text":"基金管理人应当依据法律法规和行业监管要求审慎经营，建立健全并严格遵守资金募集管理、投资者适当性、信息披露、风险管理、内部控制等业务规则和管理制度。"},{"no":"二十六","title":"","text":"基金（含其子基金）的资金必须委托具有相关资质的商业银行进行托管，托管银行原则上应在天元区境内或在天元区设有分支机构，开户行原则上应在天元区。"},{"no":"二十七","title":"","text":"除国家政策另有规定外，基金不得从事以下业务：（一）从事担保、抵押、委托贷款等业务；（二）投资二级市场股票（以并购重组为目的的除外）、证券投资基金、评价AAA级以下的企业债、信托产品、理财产品、证券公司或基金公司或保险公司及其子公司的资产管理计划产品、期货及其他金融衍生品、房地产业以及国家政策限制类行业；（三）向任何第三方提供赞助、捐赠（经批准的公益性捐赠除外）；（四）吸收或变相吸收存款，或向第三方提供贷款和资金拆借；（五）进行承担无限连带责任的对外投资；（六）发行信托或集合理财产品募集资金；（七）从事明股实债等变相增加政府债务的行为；（八）国家法律法规禁止从事的其他业务。"},{"no":"二十八","title":"","text":"基金应当遵照国家有关法律法规以及行业自律规则等规定，建立健全内部控制和外部监管制度，建立投资决策和风险约束机制，切实防范基金运作过程中可能出现的风险。"},{"no":"二十九","title":"","text":"联席会议办公室负责组织对政策性基金开展绩效评价工作，必要时可以委托审计部门或聘请第三方审计机构对基金运行情况进行专项审计。对政策性基金的绩效评价，应遵循风险投资行业发展规律，重在产业扶持效果及流程规范等过程考核，基金绩效评价原则上应按照整个基金生命周期予以评定，而非对单个子基金或单个投资项目造成的投资盈亏进行评定。"},{"no":"三十","title":"","text":"政策性基金坚持产业扶持、鼓励探索、宽容失误的原则，建立容亏免责和尽职免责机制，支持基金落地见效。"},{"no":"三十一","title":"","text":"对于履行规定程序作出决策的投资，因不可抗力、政策变动或者发生市场（经营）风险等非人为因素造成投资损失，但不涉及违法违规、重大过失和其他道德风险的，对决策机构、主管部门、基金管理机构及相关人员不予追究责任。"},{"no":"三十二","title":"","text":"对弄虚作假骗取基金投资，或不按规定用途使用、截留挪用、挥霍浪费产业发展基金等违法违规行为，按国家有关法律、法规处理。涉嫌犯罪的，移送司法机关追究刑事责任。"},{"no":"三十三","title":"","text":"本办法自发布之日起施行，有效期2年。在本办法实施前已批准或者已签订协议（章程）的，存续期内按原协议（章程）的条款内容执行。"}],"interpretations":[{"sectionNo":"十五","headline":"基金管理费不高于出资额2%/年，也可按收益分成","who":"政策性基金的受托管理机构（基金管理人）；具体比例在政策性基金设立方案中确定。","materials":[],"window":"按年计提，自基金设立方案约定之日起执行，原文未设申报期限。","where":"按政策性基金设立方案约定执行，无对外申报窗口。","tip":"2%/年是上限而非固定标准；管理费与投资收益分成是两种可选方式，具体在设立方案中明确。"},{"sectionNo":"十六","headline":"子基金管理机构可获让利，含回购与让渡超额收益","who":"受托管理机构及其管理团队（激励约束机制）；子基金管理机构和其他出资人（让利机制，含回购和让渡超额收益）。","materials":[],"window":"在政策性基金设立方案和实施细则中约定，原文未设申报期。","where":"在政策性基金设立方案和实施细则中约定，无对外申报窗口。","tip":"让利方式须在实施细则中明确，未约定的不当然享受；激励约束同样以设立方案约定为准。"},{"sectionNo":"二十三","headline":"基金出资不保本、不承诺最低收益，收益分配协商约定","who":"参与基金出资的各类出资人（含社会资本）；出资人代表不得向其作出保本或最低收益承诺。","materials":[],"window":"基金存续期内持续适用，原文未设期限。","where":"按基金协议（章程）约定执行，无申报窗口。","tip":"“国家另有规定的除外”是唯一例外；亏损负担方式同样按风险共担协商，不因出资比例自动兜底。"},{"sectionNo":"三十二","headline":"弄虚作假骗取基金投资，依法处理并可能追刑责","who":"申请或使用基金投资的基金、子基金及其管理人员、被投企业。","materials":[],"window":"基金投资运作全过程适用，原文未设追责时效。","where":"按国家有关法律、法规处理；涉嫌犯罪的移送司法机关。","tip":"除骗取投资外，截留挪用、挥霍浪费产业发展基金同样追责；涉嫌犯罪的移送司法机关追究刑事责任。"}],"sourceUrl":"http://img.zhuzhou.gov.cn/zzcms/DFS//file/2026/01/08/202601081622459074767ws.pdf","derivedFrom":"official","sourceNote":"原页面 https://www.zhuzhou.gov.cn/c24812/20250605/i2376394.html 及天元区同路径页均已下架（313 字节错误页），原栏目 c24812 失效。本条取自天元区政府门户「政府公报」2024 年卷第 8—11 页 PDF（http://www.tianyuan.gov.cn/c24217/20250807/i2407399.html 挂载的附件），该卷 PDF 有文字层；版头文号株高天政发〔2024〕4号、统一登记号 ZZTYDR—2024—00003，成文日期 2024 年 12 月 30 日。本文与《株洲高新区（天元区）产业引导基金管理细则》（id: zzgxq-fund-rules-2024）同文印发，两条 documentNo 相同。转录时已剔除公报跨页页眉页脚（「管委会、区政府文件 … 公报」「— N —」），并剥离条末夹带的「第X章」「第X节」标题；首条至第三十三条连续，无缺号。 2026-11-24 收录：与官方页面逐句比对，命中 73/73 句（100%），关卡判定「verbatim」。 有效期依据：第三十三条","verified":false,"isSample":false,"numberStyle":"clause","bodyVerified":"verbatim","hunan":true},{"id":"zzgxq-fund-rules-2024","title":"株洲高新区（天元区）产业引导基金管理细则（试行）","level":"district","region":"株洲市·天元区","issuer":"株洲高新区管委会、株洲市天元区人民政府","documentNo":"株高天政发〔2024〕4号","publishedAt":"2024-12-30","effectiveAt":"2024-12-30","expiresAt":"2026-12-29","status":"expiring","tags":["融资支持","财政奖补","研发创新"],"audience":["株洲高新区（天元区）产业引导基金及子基金","基金管理机构","区属国有公司"],"summary":"产业引导基金由区财政资金或区属国有公司出资设立并纳入国资监管；引导基金可出资设立政策性子基金、市场化子基金或直接投资项目，参股子基金出资比例原则上不超过子基金规模的30%，返投比例一般不低于引导基金出资额的1.2倍；引导基金参股子基金存续期满一般应退出；本细则有效期2年。","sections":[{"no":"一","title":"","text":"为了规范和加强政府产业引导基金管理，充分发挥财政资金引导放大作用，按照《财政部关于印发〈政府投资基金暂行管理办法〉的通知》（财预〔2015〕210号）、《国家发展改革委关于印发〈政府出资产业投资基金管理暂行办法〉的通知》（发改财金规〔2016〕2800号），参照《湖南省省级政府性投资基金暂行管理办法》（湘财预〔2016〕30号）、《株洲高新区（天元区）基金管理办法（试行）》等有关文件要求，结合我区实际，制定本细则。"},{"no":"二","title":"","text":"株洲高新区（天元区）产业引导基金（以下简称“引导基金”），是指由高新区（天元区）财政资金或区属国有公司出资设立，按照市、区相关文件要求纳入国资监管，并完成备案的基金。"},{"no":"三","title":"","text":"引导基金按照“政府引导、市场运作、科学决策、防范风险”原则进行投资管理，围绕株洲高新区产业规划布局，积极支持产业转型升级和科技成果转化，重点投向株洲高新园区新能源汽车、新能源装备、新材料、电子信息（“2+2”产业集群）以及符合国家重点布局的战略新兴产业和未来产业。"},{"no":"四","title":"","text":"引导基金可出资设立政策性子基金、市场化子基金，也可直接参与项目投资。其中政策性子基金是指为加速株洲高新区产业招引和产业培育，促进科技成果转化而设立的系列产业孵化和促进产业发展类基金；市场化子基金是指按照本办法及投资管理制度自主决策、市场化运作的基金；项目投资是指引导基金及子基金根据政策文件相关要求的规定直接投资于企业。"},{"no":"五","title":"","text":"引导基金的管理主要由金融服务工作联席会议办公室（以下简称“联席会议办公室”）、财政局、基金管理机构负责。"},{"no":"六","title":"","text":"联席会议办公室设在投资金融局，根据《株洲高新区（天元区）基金管理办法（试行）》及金融服务联席会议要求，开展相关工作。"},{"no":"七","title":"","text":"财政局根据政策性基金的出资需求，将高新区管委会出资额纳入年度政府预算，根据基金需求拨付资金。"},{"no":"八","title":"","text":"财政局按照国资监管有关规定，对于纳入《株洲高新区（天元区）区属国有企业出资人审批事项清单管理办法（试行）》的重大事项履行监管与审批职责。"},{"no":"九","title":"","text":"基金管理机构即基金管理人由株洲高科集团有限公司旗下国有私募股权投资机构担任，按照《株洲高新区（天元区）基金管理办法（试行）》要求，履行基金管理人职责，负责引导基金日常事务管理。"},{"no":"十","title":"","text":"投资方式。在充分考虑财政承受能力的基础上，发挥市场在资源配置中的决定性作用，引导社会资本投资株洲高新区经济社会发展的重点领域和薄弱环节，其中以参股子基金为主，直投、跟投为辅，主要包括以下方式：（一）通过参股方式与其他资本合作设立子基金或增资参股基金；（二）采取直接投资、跟进投资等方式进行投资运作。"},{"no":"十一","title":"","text":"基金管理机构按照专业化、市场化方式履行相关程序，提出书面投资建议，按照《株洲高新区（天元区）基金管理办法（试行）》相关授权履行决策程序。"},{"no":"十二","title":"","text":"引导基金出资设立子基金，应当遵循本细则及相关投资政策规定，与其他出资人签订有限合伙协议（章程），约定基金设立政策目标、基金规模、存续期限、出资方案、投资领域、决策机制、基金管理机构、风险防范、投资退出、管理费用和收益分配等事项。"},{"no":"十三","title":"","text":"引导基金参与出资设立子基金，出资比例原则上不超过子基金规模的30%；由高科集团旗下私募基金管理公司主管的基金以及天使基金、科技成果转化基金等政策性基金的出资比例不受此比例限制。"},{"no":"十四","title":"","text":"引导基金参与设立的子基金，应当在有限合伙协议（章程）中明确约定返投比例，返投比例一般不低于引导基金出资额的1.2倍。对社会资本出资比例较高或者具有战略合作意义的子基金，返投要求可按照“一事一议”方式适当放宽。"},{"no":"十五","title":"","text":"子基金一般应投资于株洲高新区园区企业，对于产业关联度强，有利于高新区园区企业上下游配套的企业、项目，可适当扩展到株洲市域内。投资于株洲市域范围内企业的投资金额计算包括：（一）直接投资株洲市域内企业，按照基金或其投资的子基金投资的金额计算投资返投金额；（二）投资株洲市域外企业被株洲市域内企业并购，按照母基金或其投资的子基金投资株洲市域外项目的金额计算投资返投金额；（三）投资株洲市域外企业并购株洲市域内企业，按照母基金或其投资的子基金所投企业并购株洲市域内项目金额计算投资返投金额；（四）投资株洲市域外企业在株洲市域内投资，按照该企业在株洲市域内的总投资额计算返投金额；（五）投资株洲市域外企业迁址株洲市域内，按该企业在株洲市域的总投资额计算返投金额；（六）基金管理人及关联方的自有资金、管理的其他基金、参股的基金投资的项目以及基金管理人协助引进的项目，按照上述标准认定；（七）如投资时项目公司在市域外，投资完成后2年内将项目公司总部或分、子公司等主体落户于株洲市域内的，该主体股本金投入部分认定为返投金额；（八）其他经联席会议办公室认定的可确认为投资株洲市域内项目。"},{"no":"十六","title":"","text":"引导基金参与设立的子基金存续期一般不超过10年，存续期内遇有重大事项变更或者存续期满确需延期的，由子基金的决策机构审议通过后办理变更或者延期手续。参与设立的子基金以及直接投资主要通过清算、上市、股权转让、其他出资人回购、二手份额交易等方式退出。"},{"no":"十七","title":"","text":"引导基金及子基金管理人应当依据法律法规和行业监管要求审慎经营，建立健全并严格遵守资金募集管理、投资者适当性、信息披露、风险管理、内部控制等业务规则和管理制度。"},{"no":"十八","title":"","text":"引导基金不得以任何方式承诺回购社会出资人的投资本金，不得以任何方式承担社会出资人的投资本金损失，不得以任何方式向社会出资人承诺最低收益，不得变相举债。"},{"no":"十九","title":"","text":"基金管理机构应于每半年度结束后两个月内汇总基金及子基金的总体运行情况，分别报送联席会议办公室、财政局，并及时报告基金运行中的重大事项。基金管理人应当配合上级监管部门完成基金的相关审计与评估工作。"},{"no":"二十","title":"","text":"基金、子基金不得从事超出国家法律法规禁止从事的业务及《株洲高新区（天元区）基金管理办法（试行）》规定以外的业务。"},{"no":"二十一","title":"","text":"引导基金参与设立的子基金以及管理人应当根据相关法律法规和行业管理规定进行登记备案，在全国政府出资产业投资基金信用信息登记系统进行登记和信息更新。"},{"no":"二十二","title":"","text":"基金管理机构应密切跟踪子基金经营和财务状况，防范财务风险。"},{"no":"二十三","title":"","text":"按照基金投资规律和市场化原则，建立分类评估机制。对于政策性子基金，重点考核政策目标、撬动放大、规范管理等内容，兼顾经济效益;对于市场性子基金及市场化直投，重点评估经济效益、规范管理等内容，兼顾社会效益。"},{"no":"二十四","title":"","text":"引导基金管理人应加强对参与设立的子基金及其管理机构运营监管，及时掌握子基金以及被投项目经营情况。"},{"no":"二十五","title":"","text":"建立按基金生命周期予以评定的基金绩效评价制度，在基金运作过程中，原则上不对单个所投项目造成的投资亏损进行评定。"},{"no":"二十六","title":"","text":"引导基金及其参与设立的子基金管理机构应当自觉接受基金监管部门业务监管，对弄虚作假骗取引导基金投资，或者不按照规定用途使用、截留挪用、挥霍浪费资金等违法违规行为，按照国家有关法律法规处理。"},{"no":"二十七","title":"","text":"直投项目的项目创始人及实控人原则上不得先于引导基金退出其在该企业的股权；子基金发起人不得先于引导基金退出其在合作子基金中的份额。"},{"no":"二十八","title":"","text":"引导基金一般通过到期清算、基金份额转让、股权转让等方式实施退出，也可以通过社会股东回购等其他合法方式退出。"},{"no":"二十九","title":"","text":"基金中途退出时，属于按协议约定退出或有市场参考价（如其他投资人的转让或增资价格、第三方评估价格等）的，可免于产权交易市场公开挂牌转让。不属于协议约定退出或退出时没有市场参考价的，应当聘请有资质的机构进行资产评估，并在依法设立的产权交易机构公开进行。"},{"no":"三十","title":"","text":"直投项目发生下列情况之一的，可终止合作并选择退出，并依法依约追究直投项目企业的违约责任：（一）未按本办法要求、投资协议约定开展相关业务的；（二）合作协议签订后，其它投资方未按约定程序和时间要求完成出资的；（三）投资完成一年以后，直投项目企业未按投资协议使用投资资金的；（四）直投项目企业出现重大风险的。"},{"no":"三十一","title":"","text":"引导基金设立子基金的，子基金发生下列情况之一的，应当采取终止合作并选择退出等措施避免损失：（一）投资基金方案确认后超过一年，未按规定程序和时间要求完成设立手续的；（二）子基金设立一年以上，未开展投资业务的；（三）子基金投资领域和方向不符合政策目标的；（四）其他不符合合伙协议约定情形的。"},{"no":"三十二","title":"","text":"建立风险容忍机制，引导基金参与的天使基金、科技成果转化基金等政策性基金可以允许最高不超过50%的本金亏损；其他市场化基金由各出资人自担风险。"},{"no":"三十三","title":"","text":"原则上在基金进入清算阶段后一般应由联席会议办公室负责对基金进行绩效评价，评价机制应将设立基金的政策制度、政府要求、投资目的、运作规范等方面的情况作为评价的主要内容。联席会议办公室也可根据基金实际运作情况不定期组织绩效评价或审计。"},{"no":"三十四","title":"","text":"基金运行周期结束，即基金清算完成后，若基金出现亏损时，由联席会议办公室牵头组织责任认定工作。"},{"no":"三十五","title":"","text":"本细则自公布之日起施行，有效期为2年。在本办法实施前已批准或者已签订协议（章程）的，存续期内按原协议（章程）约定的条款内容执行。"}],"interpretations":[{"sectionNo":"十三","headline":"引导基金参股子基金，出资比例原则上不超30%","who":"拟与引导基金合作设立子基金的基金管理机构及其他出资人；高科集团旗下私募基金管理公司主管的基金、天使基金、科技成果转化基金等政策性基金不受30%比例限制。","materials":[],"window":"子基金出资设立时约定，原文未设申报截止时间。","where":"在子基金合伙协议（章程）中约定，无对外申报窗口。","tip":"30%是“原则上”上限；天使基金、科技成果转化基金及高科集团旗下私募基金管理公司主管的基金不受此限。"},{"sectionNo":"十四","headline":"子基金返投一般不低于引导基金出资额的1.2倍","who":"引导基金参与设立的子基金及其管理机构；社会资本出资比例较高或具战略合作意义的子基金可“一事一议”放宽。","materials":[],"window":"在有限合伙协议（章程）中约定，按基金存续期考核，原文未设申报期。","where":"在有限合伙协议（章程）中约定，无对外申报窗口。","tip":"1.2倍是“一般”下限；放宽须走“一事一议”，不是自动适用。"},{"sectionNo":"十五","headline":"返投认定含并购、迁址等八类情形，外地项目2年内落户可计","who":"引导基金参与设立的子基金及其管理机构（计算返投金额）；投资株洲市域外企业后2年内将总部或分、子公司落户株洲市域内的，该主体股本金投入可认定为返投。","materials":[],"window":"投资完成后2年内完成落户方可认定；返投按基金存续期累计计算。","where":"由联席会议办公室认定（含“其他经联席会议办公室认定”的情形），无申报窗口。","tip":"子基金一般应投园区企业，产业关联度强的可扩至株洲市域内；八类情形之外须经联席会议办公室认定。"},{"sectionNo":"十六","headline":"子基金存续期一般不超过10年，延期须决策机构审议","who":"引导基金参与设立的子基金及其管理人；存续期内发生重大事项变更或期满需延期的子基金。","materials":[],"window":"存续期一般不超过10年；延期须子基金决策机构审议通过后办理变更或延期手续。","where":"由子基金决策机构审议，按合伙协议办理变更或延期，无申报窗口。","tip":"10年是“一般”上限；退出主要通过清算、上市、股权转让、其他出资人回购、二手份额交易。"},{"sectionNo":"十八","headline":"引导基金不回购社会出资人本金，不承诺最低收益","who":"与社会资本共同出资设立子基金的引导基金及子基金；社会出资人不得期待保本保收益安排。","materials":[],"window":"基金存续期内持续适用，原文未设期限。","where":"按合伙协议（章程）约定执行，无申报窗口。","tip":"四类禁止均无例外：承诺回购本金、承担本金损失、承诺最低收益、变相举债。"},{"sectionNo":"二十六","headline":"弄虚作假骗取引导基金投资，依法处理并追责","who":"引导基金及其参与设立的子基金管理机构、被投企业。","materials":[],"window":"基金运作全过程适用，原文未设追责时效。","where":"按国家有关法律法规处理，并接受基金监管部门业务监管。","tip":"截留挪用、挥霍浪费资金同样追责；管理机构须自觉接受基金监管部门业务监管。"},{"sectionNo":"二十七","headline":"直投企业创始人不得先于引导基金退出股权","who":"获引导基金直投项目的项目创始人及实际控制人；子基金发起人（不得先于引导基金退出其在合作子基金中的份额）。","materials":[],"window":"自投资日起至引导基金退出前持续适用，原文未设具体年限。","where":"在投资协议、合伙协议中约定，无申报窗口。","tip":"约束对象包括直投项目创始人、实控人及子基金发起人；“原则上”表述留有个案协商空间。"},{"sectionNo":"三十","headline":"直投项目未按约定用款等情形，可终止合作并追责","who":"获引导基金直投的企业；出现未按协议开展业务、其他投资方未按约出资、投资完成一年后未按协议使用资金、重大风险四类情形之一。","materials":[],"window":"投资完成一年以后未按投资协议使用投资资金的，列入可终止情形。","where":"由基金管理机构按投资协议处理，无申报窗口。","tip":"四类情形任一即触发，可终止合作并依法依约追究直投项目企业违约责任。"},{"sectionNo":"三十一","headline":"子基金设立一年未开展投资等情形，应终止合作退出","who":"引导基金参与设立的子基金及其管理机构；出现方案确认后超一年未完成设立、设立一年以上未开展投资、投向不符政策目标等情形。","materials":[],"window":"投资基金方案确认后超过一年未完成设立手续即触发；子基金设立一年以上未开展投资业务亦触发。","where":"由引导基金按合伙协议采取终止合作、退出等措施，无申报窗口。","tip":"四类情形“应当”采取终止合作并退出，不是可选；不符合合伙协议约定的同样适用。"},{"sectionNo":"三十二","headline":"天使基金、科技成果转化基金容亏最高50%本金","who":"引导基金参与的天使基金、科技成果转化基金等政策性基金；其他市场化基金由各出资人自担风险。","materials":[],"window":"基金存续期内适用，按基金生命周期评价，原文未设申报期。","where":"由联席会议办公室在绩效评价与责任认定中执行，无申报窗口。","tip":"50%是本金亏损容忍上限，不是财政补贴；市场化基金不适用，风险由出资人自担。"}],"sourceUrl":"http://img.zhuzhou.gov.cn/zzcms/DFS//file/2026/01/08/202601081622459074767ws.pdf","derivedFrom":"official","sourceNote":"原页面 https://www.zhuzhou.gov.cn/c24812/20250605/i2376394.html 及天元区同路径页均已下架（313 字节错误页），原栏目 c24812 失效。本条取自天元区政府门户「政府公报」2024 年卷第 12—19 页 PDF（http://www.tianyuan.gov.cn/c24217/20250807/i2407399.html 挂载的附件），该卷 PDF 有文字层；与《株洲高新区（天元区）基金管理办法》（id: zzgxq-fund-mgmt-2024）同属株高天政发〔2024〕4号、统一登记号 ZZTYDR—2024—00003，成文日期 2024 年 12 月 30 日。转录时已剔除公报跨页页眉页脚并剥离条末「第X章」标题；首条至第三十五条连续，无缺号。 2026-11-24 收录：与官方页面逐句比对，命中 63/63 句（100%），关卡判定「verbatim」。 有效期依据：第三十五条","verified":false,"isSample":false,"numberStyle":"clause","bodyVerified":"verbatim","hunan":true},{"id":"zzgxq-invest-supplement-2023","title":"株洲高新区管委会 株洲市天元区人民政府印发《关于落实〈株洲市进一步加强招商引资工作助推“三个高地”建设的若干措施〉的补充措施》的通知","level":"district","region":"株洲市·天元区","issuer":"株洲高新区管委会、株洲市天元区人民政府","documentNo":"株高天政发〔2023〕6号","publishedAt":"2023-07-05","effectiveAt":"2023-07-05","expiresAt":null,"status":"active","tags":["财政奖补","场地支持","营商环境"],"audience":["株洲高新区（天元区）主导产业制造类项目投资主体","租赁或购买标准厂房的入园企业"],"summary":"对固定资产投资强度350万元/亩、年产值600万元/亩、年纳税30万元/亩以上且固投总额1亿元以上的产业项目优先保障供地或定制代建；项目摘牌18个月后按纳税区级贡献前三年100%、后两年50%给予产业扶持奖励，上限为实付购地款；设备投资强度1500元/㎡以上的标准厂房项目给予24个月租金减免，期满回购按年纳税300-500元/㎡奖补10%、500元/㎡以上奖补15%；年纳税400元/㎡以上的租赁或购买厂房项目自合同签订6个月起按前三年100%、后两年50%奖励；固定资产投资2亿元以上等项目可“一事一议”。","sections":[{"no":"一","title":"","text":"对电子信息、新材料、新能源装备、新能源汽车等主导产业发展方向的优质制造类项目，在坚持土地集约高效利用原则的前提下，可以申请购地或定制代建。"},{"no":"二","title":"","text":"对固定资产投资强度350万元/亩以上、年产值600万元/亩以上、年纳税30万元/亩以上且固定资产投资总额达1亿元以上的产业项目，原则上优先保障供地或定制代建。"},{"no":"三","title":"","text":"项目自土地摘牌之日起18个月后，按企业纳税的地方财政贡献区级部分（限增值税和企业所得税，下同）前三年100%、后两年50%的比例给予产业扶持奖励，奖励上限总额为实际支付的购地款。"},{"no":"四","title":"","text":"对新引进符合我区主导产业发展方向的先进制造类项目使用标准厂房且生产设备投资强度1500元/㎡以上的，自厂房交付之日起给予24个月租金减免支持。支持期后项目方需回购该标准厂房的，按以下优惠支持：年均纳税300-500元/㎡（含300元/㎡）的，按厂房价款（不含税）的10%予以奖补；年均纳税在500元/㎡（含）以上的，按厂房价款（不含税）的15%予以奖补；支持期后项目方需继续租赁该标准厂房的，租金按市场价执行。"},{"no":"五","title":"","text":"对成长性好、有助于我区产业强链扩链、年纳税400元/㎡以上的租赁或购买标准厂房项目，自合同签订后6个月起，可视情况按企业地方财政（增值税、企业所得税）贡献区级部分前三年100%、后两年50%的比例给予产业扶持奖励。奖励上限总额不超过实际支付的厂房购置款或厂房租赁款。"},{"no":"六","title":"","text":"对符合下列条件之一的项目，可申请“一事一议”支持：（一）符合我区主导产业发展方向，国家级制造业单项冠军企业、国家级专精特新“小巨人”企业、细分领域龙头企业的项目；（二）对我区产业发展有显著促进作用，且实际到位固定资产投资额2亿元及以上的产业项目；（三）对能优化我区产业结构、属于“2+2”产业“强链补链”、能实现进口替代的产业项目；（四）国家大力鼓励、取得重大科技突破、具备解决“卡脖子”核心关键技术和颠覆性技术等对园区产业带动性大的产业项目。"},{"no":"七","title":"","text":"本办法由株洲高新区管委会负责解释。"},{"no":"八","title":"","text":"本办法自公布之日起执行。《株洲高新区（天元区）关于促进产业链招商和产业配套的十二条政策措施》（株高天政发〔2020〕1号）、《株洲高新区、株洲市天元区入园工业项目土地使用及标准厂房租售相关优惠政策（试行）》（株高天政发〔2017〕2号）、《株洲高新区、株洲市天元区工业项目招商引资奖励办法》（株高天政办发〔2017〕2号）同时废止。在本办法执行期间，如遇国家、省、市政策调整，按调整后的政策执行。"}],"interpretations":[{"sectionNo":"一","headline":"电子信息、新材料等主导产业优质制造项目可申请购地或定制代建","who":"电子信息、新材料、新能源装备、新能源汽车等主导产业发展方向的优质制造类项目；须坚持土地集约高效利用原则。","materials":[],"window":"原文未设申报期限，按招商项目洽谈流程办理。","where":"株洲高新区管委会（按项目落地流程办理）。","tip":"须属于主导产业发展方向且为优质制造类项目，并坚持土地集约高效利用。"},{"sectionNo":"二","headline":"固投350万元/亩、年纳税30万元/亩以上项目优先供地或代建","who":"固定资产投资强度350万元/亩以上、年产值600万元/亩以上、年纳税30万元/亩以上，且固定资产投资总额达1亿元以上的产业项目。","materials":[],"window":"原文未设申报期限；达标的产业项目原则上优先保障。","where":"株洲高新区管委会（供地或定制代建按项目审批流程办理）。","tip":"四项指标须同时满足：投资强度、年产值、年纳税、固投总额1亿元以上。"},{"sectionNo":"三","headline":"摘牌18个月后，按区级纳税贡献前三年100%、后两年50%奖励","who":"自土地摘牌之日起的购地项目企业；奖励按企业纳税的地方财政贡献区级部分（限增值税和企业所得税）计算。","materials":[],"window":"自土地摘牌之日起18个月后开始计算，前三年100%、后两年50%。","where":"株洲高新区管委会（按财政体制兑现）。","tip":"奖励上限总额为实际支付的购地款；仅限增值税和企业所得税的区级部分。"},{"sectionNo":"四","headline":"设备投资1500元/㎡以上，标准厂房免租24个月","who":"新引进、符合我区主导产业发展方向、使用标准厂房且生产设备投资强度1500元/㎡以上的先进制造类项目。","materials":[],"window":"自厂房交付之日起24个月租金减免；支持期后可按年均纳税额申请回购奖补。","where":"株洲高新区管委会（标准厂房租售按园区管理流程办理）。","tip":"回购奖补按年均纳税300-500元/㎡（含300）奖10%、500元/㎡（含）以上奖15%；继续租赁按市场价。"},{"sectionNo":"五","headline":"年纳税400元/㎡以上厂房项目，前三年100%、后两年50%奖励","who":"成长性好、有助于我区产业强链扩链、年纳税400元/㎡以上的租赁或购买标准厂房项目。","materials":[],"window":"自合同签订后6个月起计算，前三年100%、后两年50%。","where":"株洲高新区管委会（按财政体制兑现）。","tip":"奖励上限不超过实际支付的厂房购置款或厂房租赁款；按增值税、企业所得税区级部分计算。"},{"sectionNo":"六","headline":"单项冠军、专精特新小巨人、固投2亿元以上项目可“一事一议”","who":"国家级制造业单项冠军企业、国家级专精特新“小巨人”企业、细分领域龙头企业的项目；实际到位固定资产投资额2亿元及以上的产业项目；属于“2+2”产业强链补链、能实现进口替代的项目；解决“卡脖子”核心关键技术和颠覆性技术的项目。","materials":[],"window":"原文未设申报期限，按项目洽谈和评审进度安排。","where":"株洲高新区管委会（“一事一议”按项目评审程序办理）。","tip":"四类条件满足其一即可申请；固定资产投资额口径为实际到位额。"}],"sourceUrl":"http://img.zhuzhou.gov.cn/zzcms/DFS//file/2024/04/24/20240424153658621ic7cnd.pdf","derivedFrom":"official","sourceNote":"该件无独立网页，全文仅见于天元区政府门户「政府公报」2023 年卷第 31—33 页 PDF（http://www.tianyuan.gov.cn/c24217/20240328/i2179872.html 挂载的附件），该卷 PDF 有文字层。版头文号株高天政发〔2023〕6号、统一登记号 ZZTYDR—2023—00007；2023 年 7 月《株洲市县市区人民政府规范性文件备案登记薄》著录制定日期 2023.7.5、备案日期 2023.7.17。转录时已剔除公报跨页页眉页脚；首条至第八条连续，无缺号。 2026-11-24 收录：与官方页面逐句比对，命中 16/16 句（100%），关卡判定「verbatim」。 有效期依据：第八条","verified":false,"isSample":false,"numberStyle":"clause","bodyVerified":"verbatim","hunan":true},{"id":"zzgxq-knowledge-value-loan-2023","title":"株洲高新区（天元区）科技型企业知识价值信用贷款风险补偿管理办法","level":"district","region":"株洲市·天元区","issuer":"株洲高新区管委会、株洲市天元区人民政府","documentNo":"株高天政发〔2023〕5号","publishedAt":"2023-06-16","effectiveAt":"2023-06-16","expiresAt":null,"status":"active","tags":["融资支持","研发创新","财政奖补"],"audience":["注册地在天元区的高新技术企业","纳入国家科技型中小企业评价库的科技型中小企业","合作银行"],"summary":"对合作银行向天元区科技型企业发放的知识价值信用贷款本金损失给予补偿，单户贷款额度不超过500万元、超出部分不纳入补偿；区级风险补偿资金承担本金损失35%，省级按同比例补偿，放款银行承担30%；风险补偿金按1：20放大贷款倍数，单家银行年度累计不良率达3%触发风险警示、达5%暂停新增业务。","sections":[{"no":"一","title":"","text":"为积极发挥财政资金的引导和放大效应，引导有关金融机构支持株洲高新区（天元区）科技型企业快速健康发展，缓解企业“融资难、融资贵、融资慢”问题，根据湖南省科学技术厅等6部门《关于印发<湖南省科技型企业知识价值信用贷款风险补偿改革实施办法>的通知》（湘科发〔2022〕49号）等有关规定，由湖南省科技厅、株洲高新区管委会共同为合作银行向株洲高新区（天元区）科技型企业发放的知识价值信用贷款的风险损失提供补偿。"},{"no":"二","title":"","text":"本办法所指科技型企业是指注册地在株洲市天元区，自身竞争能力较强、诚信经营且经营情况良好、信用资质佳、已经认定的高新技术企业或纳入国家科技型中小企业评价库的科技型中小企业。"},{"no":"三","title":"","text":"本办法所指合作银行是指与湖南省科技厅、株洲高新区管委会签订了风险补偿金合作协议，同时合作银行所在株洲的分行与株洲高新区风险补偿委托管理机构（湖南高科园创园区管理服务有限公司，以下简称“高科园创”）签订了两方合作协议，为企业提供融资业务的银行。"},{"no":"四","title":"","text":"株洲高新区科技型企业知识价值信用贷款业务，由高新区投资金融局牵头，产业发展局、区财政局、区金融办、高科园创在各自职责范围内开展工作。具体分工如下：（一）投资金融局：牵头统筹指导开展知识价值信用贷款风险补偿相关工作；制定知识价值信用贷款风险补偿实施办法；确定合作银行；审定贷款风险补偿申请以及代偿追偿方案；牵头联合有关部门向上级提交风险补偿金申请；会同区财政局编制风险补偿资金年度安排计划并提出预算建议；落实对业务单位的相关奖补。（二）产业发展局：负责建立科技型企业库并定期审核更新名录；对知识价值信用贷款风险补偿工作进行业务指导；联合有关部门向上级提交风险补偿资金申请。（三）区财政局：负责风险补偿资金预算管理，对资金安排进行程序性审核；会同投资金融局按规定拨付资金；组织实施监督检查工作。（四）区金融办：对知识价值信用贷款风险补偿工作进行业务指导；建立健全支持推进知识价值信用贷款风险补偿工作的相关政策体系。（五）高科园创为业务运行支撑单位，负责日常业务开展工作。其主要职责为：1.根据上年度全区知识价值信用贷款业务开展情况，提出年度风险补偿资金预算申请，并报投资金融局审核；2.加强与合作银行联系，对科技型企业发放知识价值信用贷款提供业务支持，明确流程规范；3.受理、初步审核风险补偿金代偿申请，并报投资金融局审议；4.协助合作银行依法对发生风险的贷款进行追偿，定期向投资金融局报告业务开展情况；5.落实株洲高新区管委会及上级部门交办的与此项业务相关的其他工作。"},{"no":"五","title":"","text":"合作银行应具备以下基本条件：（一）在湖南省注册，且在株洲高新区（天元区）设有分支机构；（二）自身实力较强，服务网点较多，构建了针对科技型企业的专属信贷审批和信用评价机制，一般应在株洲高新区（天元区）拥有科技贷款专营机构和科技信贷专属产品；（三）资产状况良好，管理机制完善，具有较强的风险控制能力和较好的经营业绩，无重大违规违法行为。"},{"no":"六","title":"","text":"合作银行相关职责：（一）合作银行应对科技型企业有较高的不良贷款风险容忍度且建立相关容错纠错机制，细化和明确相关尽职免责条款；（二）合作银行一般应建立科技支行、专营机构等，根据科技型企业特点，建立专门针对知识价值信用贷款的授信体系、审贷流程和绿色审批通道；出台相关激励措施，加大对科技型企业首贷、信用贷和无还本续贷支持力度，简化贷款审批流程，提高放款效率；（三）合作银行负责对企业的贷款申请进行尽职调查，独立做出审贷决策；（四）向符合条件的科技型企业发放贷款，贷款利率参考放款日最近一期相应期限贷款市场报价利率（LPR）；贷款期限一般为1年（含1年）以内；对知识价值信用评级等级高的企业，银行应给予更大利率优惠；（五）合作银行应与高新区（天元区）业务归口部门和高科园创建立信息联动机制，贷款发放后及时将相关信息传递有关单位，并监督贷款企业依法依规使用贷款资金，严控贷款风险；（六）合作银行发现贷款回收面临风险时，应首先采取必要措施，尽量规避风险，减少贷款损失，确因客观或特殊因素影响导致贷款到期经催收后无法全部收回时，按程序提交贷款风险补偿申请；（七）风险补偿资金先行代偿后，合作银行应依法进行追偿，并及时向省级运营管理机构、株洲高新区管委会、高科园创报送其依法尽责追偿的工作进展情况。"},{"no":"七","title":"","text":"贷款企业选择。贷款企业为注册地在株洲高新区（天元区）的科技型企业，其中，优先支持符合国家战略性新兴产业的科技型企业。具体名录由产业发展局定期筛选，并向合作银行推送。"},{"no":"八","title":"","text":"知识价值信用贷款企业的单户贷款额度不超过500万元，超出额度的部分不纳入风险补偿范围。"},{"no":"九","title":"","text":"贷款企业须符合合作银行的准入要求及相关业务的办理条件，且贷款必须用于本企业生产经营，不得用于转贷、委托贷款、国家产业政策中明令禁止和限制的行业或领域。"},{"no":"十","title":"","text":"获得知识价值信用贷款的企业应当按合同还本付息，配合合作银行及高科园创开展贷后检查，及时向高科园创及贷款银行报备重大事项变更情况。贷款企业应严格遵守信用，主动披露风险，知识价值信用贷款合同履约情况将纳入企业科研诚信记录及其主要高管人员个人征信记录。"},{"no":"十一","title":"","text":"贷款企业及法定代表人、主要经营者本人及其配偶，有以下情形的，禁止发放知识价值信用贷款；（一）企业生产经营活动违反现行产业政策和环保政策规定，且未整改到位的；（二）在国家信用信息系统、征信系统等信用信息平台有失信被执行人、限制高消费等严重不良征信记录的；（三）存在未按时履行法律义务而被法院强制执行、曾有案件被终本等情形的；（四）在申请贷款时已存在多次逾期、欠缴利息、欠缴担保费用等情形的；（五）存在逃废债务可能的；（六）存在未清偿的担保代偿记录的；（七）正常持续经营年限少于2年（含2年）的；（八）申请年度的上一年度纳税信用等级为D级，或纳税额5万元以下的；（九）存在违反《商业银行法》第四十条情形的。"},{"no":"十二","title":"","text":"风险补偿金出资方式。湖南省科技厅和株洲高新区（天元区）依据约定按照同比例分别安排预算资金作为知识价值信用贷款风险补偿资金。湖南省科技厅资金采取省级财政预留预算据实支付方式，株洲高新区（天元区）资金采取区级财政预留预算据实支付方式。"},{"no":"十三","title":"","text":"风险补偿金补偿范围。企业贷款逾期形成的贷款本金损失（只包括借款人逾期贷款的本金，不含违约金、利息、罚息等）。"},{"no":"十四","title":"","text":"株洲高新区（天元区）风险补偿资金承担贷款本金损失的35%，省级风险补偿资金与株洲高新区（天元区）风险补偿资金按照同比例进行补偿。放款银行承担贷款本金损失的30%。"},{"no":"十五","title":"","text":"省级风险补偿资金按三方协议应承担部分，先期由株洲高新区（天元区）进行垫付。"},{"no":"十六","title":"","text":"风险补偿金以1：20的比例放大贷款倍数，如超过倍数，则根据《湖南省科技型企业知识价值信用贷款风险补偿改革实施办法》操作。在一个合作年度内，单家银行在株洲高新区（天元区）内累计不良率达到3%时，株洲高新区管委会可立即向该银行提出风险警示；不良率达到5%的，株洲高新区管委会暂停受理该银行知识价值信用贷款新增业务，并对前期运行效果予以全面评估，视评估结果决定是否重启业务受理工作。对于已经受理的业务，风险补偿资金继续履行风险补偿责任。"},{"no":"十七","title":"","text":"对于同一企业同笔贷款，只补偿1次风险补偿资金；如已享受政府给予的其他风险补偿，不再享受知识价值信用贷款风险补偿。"},{"no":"十八","title":"","text":"贷款程序（一）入库申请。贷款企业通过知识价值信用贷款统一服务平台，在线填写并提交入库申请表；（二）信用评分。按照湖南省科技型企业知识价值信用评价指标体系评分标准，对入库的科技型企业进行知识价值信用评分；（三）先期授信。省级运营管理机构将库内科技型企业的信用评分数据推送至合作银行，合作银行可参考知识价值评价结果，结合内部风控审核机制，对企业进行先期授信；（四）按需贷款。合作银行根据先期授信情况，结合尽职调查情况，向提出贷款申请的科技型企业完成授信发放贷款；（五）对于未先期授信的企业，银行依据尽调和风控情况对贷款申请进行独立审核，做出授信决定，并督促企业进行知识价值评价，作为纳入风险补偿备案的依据；（六）合作银行在贷款发放前需提前向高科园创提交加盖企业和银行公章的齐全项目资料。高科园创对银行提交的资料进行审核筛查（原则上对贷款企业不进行尽职调查等实质性审查，审核时间原则不超过2个工作日），对符合条件的企业再由高科园创发起内部审批流程。"},{"no":"十九","title":"","text":"风险补偿程序（一）银行催收。贷款本金逾期后的5个工作日内，合作银行应启动催收工作并书面函告株洲高新区管委会、高科园创。（二）代偿程序。合作银行在尽职催收后，对知识价值信用贷款本金逾期超过1个月仍未全额收回的，可按《湖南省科技型企业知识价值信用贷款风险补偿改革实施办法》规定向高科园创提交代偿申请，启动代偿程序。1．代偿申请。合作银行向高科园创提出代偿申请。代偿申请资料包括：代偿申请书（含贷款合同、加盖公章的放贷凭证等贷款资料）、贷款逾期记录和催收通知书、人民法院受理通知或公安机关立案决定、仲裁机构受理回执等银行催收依据；2．代偿审批。高科园创对合作银行提交的代偿资料进行初步审查，报株洲高新区管委会审定后再报送省级运营管理机构确认。省级运营管理机构审批同意后，由投资金融局向区财政局提交资金申请，区财政局从本级预算中先期安排垫付资金，将省、区应承担代偿部分拨付至投资金融局，由投资金融局一并代偿；3．代偿补偿。区财政局先行垫付的应由省级财政承担的代偿资金，在垫付代偿后，应按程序及时将代偿情况报告省级运营管理机构，申请拨付省级代偿资金。（三）追偿。风险补偿资金代偿后，合作银行应依法积极开展追偿工作，追偿所得扣除追偿费用后，按约定分担比例予以分配，政府所得部分继续用于补充风险补偿资金。（四）在经诉讼或仲裁后且依法执行终结的情况下，贷款确实无法追回时，合作银行向株洲高新区管委会提交终止追偿建议方案，报省级运营管理机构确认后，对该笔贷款终止追偿。"},{"no":"二十","title":"","text":"株洲高新区管委会每年对合作银行开展的知识价值信用贷款增长率、企业首贷率、服务能力及风险补偿资金使用等情况进行绩效评估。"},{"no":"二十一","title":"","text":"各方应按财务规定妥善保存原始票据及凭证，积极配合相关部门的审计和监督。"},{"no":"二十二","title":"","text":"合作银行应依法依规开展知识价值信用贷款业务工作，确保政策实施效果。凡存在弄虚作假骗取补偿资金的，一经查实，除收回有关资金、取消合作资格外，将提交金融监管部门进行处理，并向社会通报。"},{"no":"二十三","title":"","text":"风险补偿受托管理机构（高科园创）应按协议要求，积极履行合同义务，加强与合作银行的联系、协调，规范知识价值信用贷款业务的日常监督，及时向委托机关报告情况，做好风险防范工作。"},{"no":"二十四","title":"","text":"对骗取风险补偿资金或恶意逃避债务导致风险补偿资金损失的企业，根据实际情况将企业及责任人列入诚信黑名单。"},{"no":"二十五","title":"","text":"在实施贷款程序、申请风险补偿资金过程中，相关机构及其工作人员弄虚作假、隐瞒事实真相或串通作弊造成风险补偿资金损失的，依照有关规定，对相关人员进行处理。构成犯罪的，依法移交司法机关处理。"},{"no":"二十六","title":"","text":"本办法实施过程中如遇上级相关政策或法律法规调整的，适用上级相关政策或法律法规。"},{"no":"二十七","title":"","text":"本办法自发布之日起施行。原《株洲高新区（天元区）科技型企业知识价值信用贷款风险补偿管理办法》（株高天政发〔2022〕2号）文件同时废止。本办法实施前在株洲高新区（天元区）发放的知识价值信用贷款，按照原办法规定执行。"}],"interpretations":[{"sectionNo":"二","headline":"天元区注册的高企或科技型中小企业可申知识价值信用贷款","who":"注册地在株洲市天元区，自身竞争能力较强、诚信经营、经营情况良好、信用资质佳，且已认定为高新技术企业或已纳入国家科技型中小企业评价库的科技型中小企业。","materials":[],"window":"按高新技术企业认定或科技型中小企业入库状态持续有效，贷款按合作银行授信周期办理。","where":"株洲高新区（天元区）合作银行","tip":"未取得高企认定或未入库的不能申请，注册地须在天元区。"},{"sectionNo":"七","headline":"知识价值信用贷款面向园区科技型企业，优先战新产业","who":"注册地在株洲高新区（天元区）的科技型企业；优先支持符合国家战略性新兴产业的科技型企业，名录由产业发展局定期筛选推送。","materials":[],"window":"名录定期筛选更新，贷款按合作银行授信流程办理。","where":"产业发展局（筛选并推送名录）、合作银行","tip":"未进入产业发展局推送名录的企业，银行难以按知识价值信用贷款受理。"},{"sectionNo":"八","headline":"知识价值信用贷单户不超500万元，超出不补偿","who":"注册地在株洲高新区（天元区）的科技型企业；单户贷款额度不超过500万元。","materials":[],"window":"按单户额度控制，超出500万元的部分不纳入风险补偿范围。","where":"合作银行（受理并放款）","tip":"超过500万元的部分银行可放但政府不补偿，风险由银行自担。"},{"sectionNo":"九","headline":"知识价值信用贷款只能用于本企业生产经营","who":"获得知识价值信用贷款的株洲高新区（天元区）科技型企业；须符合合作银行准入要求及相关业务办理条件。","materials":[],"window":"贷款存续期内按合同约定用途使用。","where":"合作银行（贷后监督贷款用途）","tip":"不得转贷、委托贷款，也不得投向国家产业政策明令禁止和限制的行业或领域。"},{"sectionNo":"十","headline":"贷款履约纳入企业科研诚信及高管个人征信","who":"获得知识价值信用贷款的株洲高新区（天元区）科技型企业及其主要高管人员。","materials":[],"window":"贷款存续期内按合同还本付息、配合贷后检查，重大事项变更须及时报备。","where":"高科园创（贷后检查）、贷款银行（报备）","tip":"逾期或违约同时影响企业科研诚信记录和高管个人征信，不只是企业信用。"},{"sectionNo":"十一","headline":"经营不足2年、纳税5万元以下等情形禁止放贷","who":"注册地在株洲高新区（天元区）的科技型企业及其法定代表人、主要经营者及配偶；存在产业环保未整改、失信被执行、欠税、逃废债、未清偿担保代偿、正常经营少于2年、上年度纳税信用D级或纳税额5万元以下、违反《商业银行法》第四十条等情形之一即禁止放贷。","materials":[],"window":"按申请时点审核上一年度纳税信用等级与纳税额；经营年限以正常持续经营时间计。","where":"合作银行（审贷时核查，本条未列具体窗口）","tip":"正常持续经营年限少于2年（含2年）即被排除；纳税信用D级或年纳税5万元以下同样不能放贷。"},{"sectionNo":"十六","headline":"知识价值信用贷款按1：20放大，不良率5%暂停新增","who":"株洲高新区（天元区）合作银行发放知识价值信用贷款的科技型企业；全区贷款按风险补偿金1：20放大，单家银行不良率达3%警示、达5%暂停新增。","materials":[],"window":"按合作年度统计不良率；超过1：20放大倍数时按省级实施办法操作。","where":"株洲高新区管委会（风险警示、暂停受理）、省级运营管理机构","tip":"已受理业务风险补偿继续履行；不良率达5%后由评估结果决定是否重启受理。"},{"sectionNo":"十七","headline":"同一企业同笔贷款只补偿1次，不得重复享受","who":"已获知识价值信用贷款并申请风险补偿的株洲高新区（天元区）科技型企业；同一企业同一笔贷款仅补偿1次。","materials":[],"window":"按单笔贷款申请，1次为限。","where":"高科园创（受理代偿申请）、株洲高新区管委会（审定）","tip":"已享受政府其他风险补偿的，不再享受知识价值信用贷款风险补偿。"},{"sectionNo":"十八","headline":"知识价值信用贷走统一服务平台，入库、评分、授信","who":"注册地在株洲高新区（天元区）的科技型企业；须通过统一服务平台入库申请、知识价值信用评分，再由合作银行先期授信或独立审贷。","materials":["入库申请表"],"window":"高科园创资料审核原则上不超过2个工作日；合作银行放款前须提交齐全项目资料。","where":"知识价值信用贷款统一服务平台（线上入库申请）、高科园创（资料审核）","tip":"未先期授信的企业由银行独立审核，但仍须完成知识价值评价才能纳入风险补偿备案。"},{"sectionNo":"二十四","headline":"骗取风险补偿资金或恶意逃债，企业及责任人列黑名单","who":"骗取知识价值信用贷款风险补偿资金或恶意逃避债务导致资金损失的企业及责任人。","materials":[],"window":"查实后按实际情况列入，无固定期限。","where":"诚信黑名单（本条未列具体经办窗口）","tip":"列入黑名单后企业及责任人后续融资受影响。"}],"sourceUrl":"http://img.zhuzhou.gov.cn/zzcms/DFS//file/2024/04/24/20240424153658621ic7cnd.pdf","derivedFrom":"official","sourceNote":"原页面 https://www.zhuzhou.gov.cn/c16354/20241119/i2280111.html 已下架（313 字节错误页）；天元区同路径页 http://www.tianyuan.gov.cn/c24812/20241114/i2266490.html 仍可打开，但正文只挂 16 页扫描 PDF、无文字层，不能逐字摘录。本条改取自天元区政府门户「政府公报」2023 年卷第 18—24 页 PDF（http://www.tianyuan.gov.cn/c24217/20240328/i2179872.html 挂载的附件），该卷 PDF 有文字层；版头文号株高天政发〔2023〕5号、统一登记号 ZZTYDR—2023—00005。转录时已剔除公报跨页页眉页脚并剥离条末「第X章」标题；首条至第二十七条连续，无缺号。公报排版把该办法的引言段（“为推动建立科技型企业知识价值信用贷款模式……制定本办法”）排在了“第一章 总则”标题之前，该段不属任何条文，故未计入 sections。 2026-11-24 收录：与官方页面逐句比对，命中 90/90 句（100%），关卡判定「verbatim」。 有效期依据：第二十七条","verified":false,"isSample":false,"numberStyle":"clause","bodyVerified":"verbatim","hunan":true},{"id":"zzgxq-tech-loan-guarantee-2025","title":"株洲高新区（天元区）科技创新专项担保贷款业务管理办法（试行）","level":"district","region":"株洲市·天元区","issuer":"株洲高新区管委会、株洲市天元区人民政府","documentNo":"株高天政发〔2025〕1号","publishedAt":"2025-01-20","effectiveAt":"2025-01-20","expiresAt":"2027-01-19","status":"expiring","tags":["融资支持","财政奖补","研发创新"],"audience":["株洲高新区（天元区）内初创期科技型小微企业","合作银行","政府性融资担保机构"],"summary":"区财政预留“科技担”风险补偿金1000万元并纳入年度预算，纳入补偿的担保贷款总额原则上不超过风补金规模的50倍；单户（个）项目在保余额原则上不超过1000万元；单笔贷款期限原则上不超过1年、最长2年；担保费率0.5%/年；代偿率5%以内的部分，除国家、省担保基金承担40%外，区级风补金承担10%本金损失，5%（含）以上或未纳入省再担保分担的部分由区级承担30%、银行承担20%。","sections":[{"no":"一","title":"","text":"为积极发挥财政资金的引导和放大效应，构建与原有科技型企业知识价值信用贷款相互补充、全面覆盖的园区科技金融服务体系，鼓励担保机构创新金融产品，支持初创期、科技型小微企业发展，按照上级有关政策，结合株洲高新区实际，特就科技创新专项担保贷款业务相关事项，制定本办法。"},{"no":"二","title":"","text":"本办法所称株洲高新区（天元区）科技创新专项担保贷款（以下简称“科技担”）是指由株洲高新区（天元区）联合株洲市金财融资担保集团有限公司下属的株洲市融资担保有限公司、株洲高科火炬融资担保有限公司共同设立，专门用于帮助株洲高新区（天元区）内符合“科技担”支持条件和范围的企业在合作银行获得担保贷款的金融产品。"},{"no":"三","title":"","text":"“科技担”的管理遵循“公开透明、权责明确、规范管理”的原则。"},{"no":"四","title":"","text":"株洲高新区（天元区）“科技担”业务，由高新区投资金融局牵头，天元区科工信局、天元区财政局、株洲市融资担保有限公司（以下简称“市融担”）、株洲高科火炬融资担保有限公司（以下简称“火炬担保”）、株洲动力谷产业投资发展集团有限公司（以下简称“高科产投”）、湖南高科园创园区管理服务有限公司（以下简称“高科园创”）在各自约定职责范围内开展工作。具体分工如下：（一）高新区投资金融局：牵头统筹指导开展“科技担”风险补偿相关工作；制定“科技担”风险补偿管理办法；审定贷款风险补偿申请及代偿追偿方案；牵头联合有关部门向上级提交风险补偿金申请；会同区财政局编制风险补偿资金年度安排计划并提出预算建议。（二）天元区科工信局：负责建立科技型企业库并定期审核更新名录；对“科技担”风险补偿工作进行业务指导。（三）天元区财政局：负责风险补偿资金预算管理，对资金安排进行程序性审核；会同高新区投资金融局按规定拨付风险补偿资金；对资金使用情况实施监督检查。（四）高科产投：发挥金融体系的整合作用，利用银行资源并结合基金等其他金融工具，为科技创新提供更全面的支持，促进金融机构与投资机构的合作，形成“投贷联动”的资金支持体系。（五）高科园创：负责推荐符合准入标准且有融资需求的企业；提供园区企业的运营数据，包括但不限于年租金、水电气费用、税收缴纳情况等；配合高新区投资金融局开展项目路演、银企对接等活动。（六）市融担、火炬担保为业务运行支撑单位，负责日常业务开展工作。其主要职责为：1．根据上年度我区“科技担”业务开展情况，提出年度风险补偿资金预算申请，并报高新区投资金融局审核；2．筛选合作银行，明确其准入条件及相关职责；3．加强与合作银行对接，对科技型企业发放“科技担”提供业务支持，明确流程规范；4．受理、初步审核风险补偿金代偿申请，并报高新区投资金融局审议；5．协助合作银行依法对发生风险的贷款进行追偿，定期向高新区投资金融局报告业务开展情况；6．落实株洲高新区管委会、天元区政府及上级部门交办的与此项业务相关的其他工作。"},{"no":"五","title":"","text":"区财政局将区级“科技担”风险补偿金纳入区级年度预算预备，预留风补资金规模为1000万元，并根据全区“科技担”规模需求实行动态调整。"},{"no":"六","title":"","text":"纳入风险补偿金担保的贷款总额原则上不超过风险补偿金规模的50倍。"},{"no":"七","title":"","text":"建立风险补偿金补充机制。当全区“科技担”需求超过风险补偿金规模的50倍或代偿后风险补偿金余额不足时，由高新区投资金融局向高新区管委会、天元区政府报告，申请在下一年度预算中足额补充。"},{"no":"八","title":"","text":"资金用途。风险补偿金专项用于担保项目贷款逾期形成风险的依约代偿，不得挪用。"},{"no":"九","title":"","text":"风险补偿金补偿范围。企业贷款逾期形成的贷款本金损失（逾期利息、罚息等其他费用由银行承担）。"},{"no":"十","title":"","text":"合作银行的选择。与市融担、火炬担保签订了合作协议的金融机构均纳入我区合作银行范畴。"},{"no":"十一","title":"","text":"风险预警。在一个合作年度内，单家银行在株洲高新区（天元区）内“科技担”累计不良率达到3%时，株洲高新区管委会可立即向该银行提出风险警示；不良率达到5%的，株洲高新区管委会暂停受理该银行“科技担”新增业务，并对前期运行效果予以全面评估，视评估结果决定是否重启业务受理工作。对于已经受理的业务，风险补偿资金继续履行风险补偿责任。本办法所称不良率是指市融担、火炬担保备案至湖南省融资再担保有限公司（以下简称“省再担保”）的合作业务所对应的担保业务在一个统计期内单家银行累计发生代偿的本金金额/市融担、火炬担保备案至省再担保合作业务所对应的担保业务在同一统计期内单家银行累计解除担保责任本金金额。上述公式所称统计期，是指每月初滚动统计前365日内的期间，如2022年2月1日测算的统计期为2021年2月1日（含当日）至2022年1月31日（含当日）；2022年3月1日测算的统计期为2021年3月1日（含当日）至2022年2月28日（含当日）。"},{"no":"十二","title":"","text":"对于同一企业同笔贷款，只给予1次风险补偿资金；如已享受政府给予的其他风险补偿，不再享受“科技担”风险补偿。"},{"no":"十三","title":"","text":"代偿比例。（一）已纳入省再担保风险分担机制，且市融担、火炬担保再担保业务代偿率在5%（不含）以内的部分，除国家、省担保基金承担40%分险责任外，区级风险补偿金承担10%的贷款本金损失，银行承担20%的本金以及贷款利息损失，其余本金损失由市融担、火炬担保承担。（二）已纳入省再担保风险分担机制，且市融担、火炬担保再担保业务代偿率在5%（含）以上的部分，或因省再担保集团政策调整未进行风险分担的项目，由区级风险补偿金承担30%的贷款本金损失，银行承担20%的本金以及贷款利息损失，其余本金损失由市融担、火炬担保承担。"},{"no":"十四","title":"","text":"贷款对象。在株洲高新区范围内（含田心片区、董家塅片区）登记注册，有固定住所和经营场所，具备完全民事行为能力，其生产经营符合国家法律法规、产业政策和环境保护要求，经营稳定，发展潜力较大，无重大不良信用记录，申请贷款时无不良贷款余额或承担担保责任的不良贷款余额的科技型制造业企业。具体准入标准如下：（一）准入标准1．上一年度营业收入规模不低于100万元；2．上一年度各项税收实缴金额不低于1万元；3．资产负债率不高于70%；4．创新的科技型制造业企业。（二）增信标准对于具备下列条件两项以上（含两项）的企业，可在提交贷款申请时同步提交相关资料，作为获取银行贷款增信的手段：1．核心技术团队科技人员占从业人员总数的比例>5%；2．全职员工中有超过1名（含）博士学历或超过2名（含）硕士学历或拥有副高级及以上职称的科技人员1名（含）以上（须提供连续3个月社保缴纳证明）；3．研发经费占销售收入的比重>2%；4．通过自主研发、受让、受赠、并购等方式，拥有I类知识产权1项（含）以上或Ⅱ类知识产权2项（含）以上；5．上一年度申报享受加计扣除政策，并完成研发费用备案;6．拥有经认定的市级以上研发平台；7．主导或参与制（修）定过国际标准、国家标准、行业标准或地方标准。（三）禁止性事项贷款企业及法定代表人、主要经营者本人、控股股东及前述人员配偶，有以下情形之一的，合作银行不得发放贷款：1．不符合产业政策、环保政策，且未整改到位的企业；2．在国家信用信息系统、征信系统等信用信息平台有失信被执行、限制高消费等严重不良征信记录的；3．存在未按时履行法律义务而被法院强制执行、终本案件等情形的；4．存在逃废债务可能的；5．存在未清偿的担保代偿记录或已由市融担、火炬担保代偿或部分代偿的；6．存在欠缴税费情况。"},{"no":"十五","title":"","text":"贷款额度。单户（个）项目在保余额原则上不超过1000万元。"},{"no":"十六","title":"","text":"贷款期限。单笔贷款期限原则上不超过1年，借款人生产经营周期超过1年或与正常经营周期不同的，单笔贷款期限最高不超过2年，不允许随借随还。"},{"no":"十七","title":"","text":"贷款用途。贷款企业须符合合作银行的准入要求及相关业务的办理条件，且贷款必须用于本企业生产经营，不得用于转贷、委托贷款、国家产业政策中明令禁止和限制的行业或领域。"},{"no":"十八","title":"","text":"担保费率。“科技担”旨在为科技型企业提供高效、优质、低成本的融资担保服务，担保费率定为0.5%/年，根据实际运营情况动态调整。"},{"no":"十九","title":"","text":"贷款程序（一）企业申请。企业自主自愿向市融担、火炬担保提出贷款担保申请，并提交以下资料：1．《科技创新专项担保贷款业务申请表》等项目推荐资料；2．贷款项目的基础资料：法人营业执照复印件；公司章程；缴纳社保人数证明或近三个月工资表；一年一期的财务报表、增值税纳税申报表；法定代表人或企业主提供个人连带责任保证，保证人及其配偶需提供身份证、结婚证复印件，个人财产清单；抵/质押类产品需提供抵/质押物权证复印件；贷款主体、法定代表人、实际控制人45天有效期内征信报告；其他需要提交资料。（二）项目尽调。市融担、火炬担保对借款人提交的担保贷款项目资料进行初步筛查，并对项目进行现场尽调。（三）出具担保意向函。项目审核通过后，市融担、火炬担保向合作银行签发《担保意向函》。（四）合同签订。市融担、火炬担保与借款人、反担保人签订《委托担保合同》《保证反担保合同》，与承办银行签订《保证合同》等。（五）保费收取。业务审核通过后，市融担、火炬担保将审批结果告知银行，并通知客户足额缴纳担保费。市融担、火炬担保收到担保费后，向合作银行发出《担保放款通知函》。（六）贷款发放。在满足放款条件后，合作银行对客户方可放款。"},{"no":"二十","title":"","text":"银行催收。贷款本金逾期后的5个工作日内或符合银行提前收回贷款的情况，合作银行启动催收工作并书面通知高新区投资金融局、市融担或火炬担保。"},{"no":"二十一","title":"","text":"合作银行尽职催收后，对担保贷款本金逾期超过1个月仍未全额收回的或符合银行提前收回贷款的情况的，向市融担、火炬担保提交代偿申请，启动代偿程序：（一）代偿申请。合作银行向市融担、火炬担保提出代偿申请。代偿申请资料包括：代偿申请书（含贷款合同、加盖公章的放贷凭证等贷款资料）、贷款逾期记录和催收通知书等银行催收依据。（二）代偿审批。市融担、火炬担保对合作银行提交的代偿资料进行初步审查，报株洲高新区投资金融局审核，对于符合条件的，按程序经管委会审批同意代偿后书面通知市融担、火炬担保代偿；对于不符合条件的，反馈书面意见给市融担、火炬担保和合作银行。（三）代偿支付。市融担、火炬担保代风险补偿基金向银行支付代偿资金，代偿范围为借款本金，不含利息、复利、罚息等其他实现债权费用，市融担、火炬担保替风险补偿基金代偿后向株洲高新区管委会申请代偿补偿。"},{"no":"二十二","title":"","text":"追偿。逾期贷款的追偿工作由市融担、火炬担保与合作银行共同完成，依法追偿所得扣除追偿费用后，及时将追偿收回的剩余部分，按照“政银担”分险比例缴回各自指定账户。"},{"no":"二十三","title":"","text":"经诉讼或仲裁后，已依法执行终结，贷款确实无法追回的，合作银行与市融担、火炬担保向株洲高新区管委会提交终止追偿建议方案，经书面确认后，对该笔贷款终止追偿。"},{"no":"二十四","title":"","text":"株洲高新区管委会每年对合作银行开展的“科技担”增长率、企业首贷率、服务能力及风险补偿资金使用等情况进行绩效评估。"},{"no":"二十五","title":"","text":"各方应按财务规定妥善保存原始票据及凭证，积极配合相关部门的审计和监督检查。"},{"no":"二十六","title":"","text":"合作银行应依法依规开展“科技担”业务工作，确保政策实施效果。凡存在弄虚作假骗取补偿资金的，一经查实，除收回有关资金、取消合作资格外，将提交金融监管部门进行处理，并向社会通报。"},{"no":"二十七","title":"","text":"市融担、火炬担保应按担保协议要求，积极履行合同义务，加强与合作银行的联系、协调，规范“科技担”业务的日常监督，及时向高新区投资金融局报告情况，做好风险防范工作。"},{"no":"二十八","title":"","text":"对骗取风险补偿资金或恶意逃避债务导致风险补偿资金损失的企业，根据实际情况将企业及责任人列入诚信黑名单。涉嫌犯罪的，依法移送司法机关处理。"},{"no":"二十九","title":"","text":"在实施贷款程序、申请风险补偿资金过程中，相关机构及其工作人员弄虚作假、隐瞒真相或串通作弊造成风险补偿资金损失的，依照有关规定，对相关人员进行处理。涉嫌犯罪的，依法移交司法机关处理。"},{"no":"三十","title":"","text":"本办法实施过程中如遇法律法规或上级相关政策调整的，适用法律法规、上级相关政策。"},{"no":"三十一","title":"","text":"本办法自发布之日起实施，有效期2年。"}],"interpretations":[{"sectionNo":"六","headline":"科技担担保贷款总额不超风险补偿金规模的50倍","who":"纳入“科技担”风险补偿金担保的株洲高新区（天元区）科技型制造业企业贷款；全区贷款总额受风险补偿金规模50倍上限约束。","materials":[],"window":"按风险补偿金规模计算，总额原则上不超过其50倍，无单独申报期。","where":"本条未列受理窗口，按“科技担”合作银行与市融担、火炬担保渠道办理。","tip":"50倍是全区共享的总额度，达到上限后新增业务受限，需待风险补偿金补充。"},{"sectionNo":"十","headline":"与市融担、火炬担保签约的银行均为科技担合作银行","who":"株洲高新区（天元区）内拟申请“科技担”的科技型制造业企业；可向与市融担、火炬担保签订合作协议的金融机构申请。","materials":[],"window":"合作协议签订后即纳入合作银行范畴，无申报期限制。","where":"与市融担、火炬担保签订合作协议的金融机构网点","tip":"未与市融担、火炬担保签约的银行不办“科技担”，申请前先确认该行是否在合作名单内。"},{"sectionNo":"十一","headline":"单家银行科技担不良率达5%，暂停受理新增业务","who":"在株洲高新区（天元区）合作银行办理“科技担”的科技型制造业企业；单家银行不良率达3%先风险警示，达5%暂停受理该行新增业务。","materials":[],"window":"每月初滚动统计前365日为一个统计期，按累计代偿本金与累计解除担保责任本金计算不良率。","where":"株洲高新区管委会（提出风险警示、暂停受理）","tip":"暂停受理只针对新增业务，已受理业务风险补偿资金继续履行补偿责任，评估后可能重启。"},{"sectionNo":"十二","headline":"同一企业同笔贷款只给1次科技担风险补偿","who":"已获“科技担”贷款并发生风险、申请风险补偿资金的株洲高新区（天元区）科技型制造业企业；同一企业同一笔贷款仅补偿1次。","materials":[],"window":"按单笔贷款申请，1次为限；已获其他政府风险补偿的不再受理。","where":"市融担、火炬担保受理后报高新区投资金融局审议","tip":"已享受政府其他风险补偿的，不再享受“科技担”风险补偿，不能重复叠加。"},{"sectionNo":"十四","headline":"园区科技型制造业企业可申科技担，营收不低于100万元","who":"在株洲高新区范围内（含田心片区、董家塅片区）登记注册、有固定住所和经营场所、具备完全民事行为能力、经营稳定、无重大不良信用记录的科技型制造业企业；准入须上一年度营业收入不低于100万元、各项税收实缴不低于1万元、资产负债率不高于70%；法定代表人、主要经营者、控股股东及其配偶有失信被执行、欠缴税费、未清偿担保代偿等禁止性情形的不得放贷。","materials":["连续3个月社保缴纳证明"],"window":"营业收入、税收、资产负债率按上一年度数据审核；增信条件满足两项以上（含两项）可同步提交资料。","where":"株洲高新区（天元区）合作银行、市融担、火炬担保","tip":"禁止性事项含失信被执行、限制高消费、欠缴税费、未清偿担保代偿等，任一项即不得放贷；增信7项中满足2项以上才作为增信手段。"},{"sectionNo":"十五","headline":"科技担单户在保余额原则上不超过1000万元","who":"株洲高新区（天元区）内符合“科技担”准入条件的科技型制造业企业；单户（个）项目在保余额原则上不超过1000万元。","materials":[],"window":"按单户在保余额控制，原则上不超过1000万元，无单独申报期。","where":"市融担、火炬担保及合作银行","tip":"额度以在保余额为口径，已还款部分释放额度后方可新增。"},{"sectionNo":"十六","headline":"科技担单笔期限原则不超1年，最长不超2年","who":"株洲高新区（天元区）内“科技担”借款企业；单笔贷款期限原则上不超过1年，生产经营周期超过1年的最长不超过2年。","materials":[],"window":"单笔原则上不超过1年；生产经营周期超过1年或与正常经营周期不同的，最高不超过2年。","where":"市融担、火炬担保与合作银行按贷款程序办理","tip":"不允许随借随还；期限超过1年须以生产经营周期为依据。"},{"sectionNo":"十七","headline":"科技担贷款只能用于本企业生产经营，不得转贷","who":"取得“科技担”贷款的株洲高新区（天元区）科技型制造业企业；须符合合作银行准入要求及相关业务办理条件。","materials":[],"window":"贷款发放后按合同约定用途使用，贷款存续期内全程受限。","where":"合作银行（贷后监督贷款用途）","tip":"不得用于转贷、委托贷款及国家产业政策明令禁止和限制的行业或领域。"},{"sectionNo":"十八","headline":"科技担担保费率0.5%/年，按运营情况动态调整","who":"株洲高新区（天元区）内申请“科技担”的科技型制造业企业；担保费率0.5%/年。","materials":[],"window":"按年计收，费率0.5%/年，根据实际运营情况动态调整。","where":"本条未列受理窗口，担保费由承保机构收取","tip":"费率会随运营情况调整，签约前按当期费率测算成本。"},{"sectionNo":"十九","headline":"科技担申请须交申请表、营业执照、财报、征信报告等","who":"向市融担、火炬担保提出贷款担保申请的株洲高新区（天元区）科技型制造业企业；须通过尽调、出具担保意向函、合同签订、保费收取后放款。","materials":["《科技创新专项担保贷款业务申请表》等项目推荐资料","法人营业执照复印件","公司章程","缴纳社保人数证明或近三个月工资表","一年一期的财务报表、增值税纳税申报表","身份证、结婚证复印件","个人财产清单","抵/质押物权证复印件","贷款主体、法定代表人、实际控制人45天有效期内征信报告"],"window":"流程为申请、尽调、出具担保意向函、合同签订、保费收取、放款；征信报告须为45天有效期内。","where":"市融担、火炬担保（受理申请、尽调）；合作银行（放款）","tip":"征信报告超过45天有效期需重新打印；资料不齐或尽调不通过不出具担保意向函。"},{"sectionNo":"二十八","headline":"骗取风险补偿资金或恶意逃债，企业及责任人列黑名单","who":"骗取“科技担”风险补偿资金或恶意逃避债务导致风险补偿资金损失的企业及其责任人。","materials":[],"window":"查实后按实际情况列入，涉嫌犯罪的移送司法机关，无固定期限。","where":"诚信黑名单；涉嫌犯罪的移送司法机关","tip":"列入黑名单与移送司法可并行，企业及责任人（含法定代表人）均在被列范围。"}],"sourceUrl":"http://img.zhuzhou.gov.cn/zzcms/DFS//file/2026/01/27/202601271519268542t67rm.pdf","derivedFrom":"official","sourceNote":"原页面 https://www.zhuzhou.gov.cn/c24812/20250603/i2375324.html 及天元区同路径页均已下架（313 字节错误页），原栏目 c24812 失效。本条取自天元区政府门户「政府公报」2025 年卷第 1—6 页 PDF（http://www.tianyuan.gov.cn/c24217/20260127/i2472893.html 挂载的附件），该卷 PDF 有文字层；版头文号株高天政发〔2025〕1号、统一登记号 ZZTYDR—2025—00001，成文日期 2025 年 1 月 20 日。转录时已剔除公报跨页页眉页脚并剥离条末「第X章」标题；首条至第三十一条连续，无缺号（公报原文第二十九条误排为“笫二十九条”，已按第二十九条收录）。 2026-11-24 收录：与官方页面逐句比对，命中 92/92 句（100%），关卡判定「verbatim」。 有效期依据：第三十一条","verified":false,"isSample":false,"numberStyle":"clause","bodyVerified":"verbatim","hunan":true}];
